#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 硬件寄存器定义 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t mock_ADC_DR   = 0;
static volatile uint32_t mock_ADC_CR2  = 0;
static volatile uint32_t mock_ADC_SR   = 0;
static volatile uint32_t mock_TIM1_CR1 = 0;
static volatile uint32_t mock_TIM1_CCR1= 0;
static volatile uint32_t mock_TIM1_ARR = 0;
static volatile uint32_t mock_TIM1_CCMR1 = 0;
static volatile uint32_t mock_TIM1_CCER  = 0;
static volatile uint32_t mock_TIM1_BDTR  = 0;
static volatile uint32_t mock_GPIOA_MODER= 0;
static volatile uint32_t mock_GPIOA_ODR  = 0;

#define ADC_DR              (mock_ADC_DR)
#define ADC_CR2             (mock_ADC_CR2)
#define ADC_SR              (mock_ADC_SR)

#define TIM1_CR1            (mock_TIM1_CR1)
#define TIM1_CCR1           (mock_TIM1_CCR1)
#define TIM1_ARR            (mock_TIM1_ARR)
#define TIM1_CCMR1          (mock_TIM1_CCMR1)
#define TIM1_CCER           (mock_TIM1_CCER)
#define TIM1_BDTR           (mock_TIM1_BDTR)

#define GPIOA_MODER         (mock_GPIOA_MODER)
#define GPIOA_ODR           (mock_GPIOA_ODR)

/* ================= 系统参数 ================= */
#define VREF                3.3f
#define ADC_RES             4095.0f
#define PWM_PERIOD          1000.0f
#define TS                  1.0e-4f     /* 采样周期 100us */
#define VIN_NOM             12.0f
#define VOUT_REF            24.0f
#define L                   100.0e-6f
#define C1                  100.0e-6f
#define C2                  470.0e-6f
#define R_LOAD_NOM          10.0f

/* ================= 滑模控制器参数 ================= */
#define LAMBDA              800.0f      /* 滑模面系数 */
#define K_EXP               5000.0f     /* 指数趋近律增益 */
#define EPSILON             200.0f      /* 等速趋近律增益 */
#define K_LOAD              0.5f        /* 负载扰动观测增益 */
#define VOUT_MAX            40.0f
#define VOUT_MIN            5.0f

/* ================= 全局状态变量 ================= */
typedef struct {
    float vout;             /* 输出电压 */
    float vout_prev;        /* 上一拍输出电压 */
    float vout_ref;         /* 输出电压参考 */
    float dvout;            /* 输出电压变化率 */
    float error;            /* 电压误差 */
    float derror;           /* 误差变化率 */
    float s;                /* 滑模面 */
    float s_prev;           /* 上一拍滑模面 */
    float u;                /* 控制量 */
    float duty;             /* 占空比 */
    float load_est;         /* 负载扰动估计 */
    float il_est;           /* 电感电流估计 */
    float vc1_est;          /* 中间电容电压估计 */
} SEPIC_SMC_t;

static SEPIC_SMC_t ctrl;

/* ================= 硬件初始化 (Mock) ================= */
static void Hardware_Init(void)
{
    ADC_CR2 = 0x00000001U;
    ADC_CR2 |= 0x00000002U;
    ADC_CR2 |= 0x40000000U;

    TIM1_ARR = (uint32_t)PWM_PERIOD;
    TIM1_CCMR1 = 0x00000060U;
    TIM1_CCER = 0x00000001U;
    TIM1_BDTR = 0x00008000U;
    TIM1_CR1 = 0x00000001U;
    TIM1_CCR1 = 0;

    GPIOA_MODER = 0x00000400U;
    GPIOA_ODR = 0;
}

/* ================= ADC 读取 (Mock) ================= */
static float ADC_ReadVoltage(void)
{
    uint32_t raw = ADC_DR & 0x00000FFFU;
    return ((float)raw / ADC_RES) * VREF * 10.0f;
}

/* ================= PWM 设置 (Mock) ================= */
static void PWM_SetDuty(float duty)
{
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 0.95f) duty = 0.95f;
    TIM1_CCR1 = (uint32_t)(duty * PWM_PERIOD);
}

/* ================= 负载扰动观测器 ================= */
static float Load_Disturbance_Observer(float vout, float duty, float il_est)
{
    float dvout_dt = (vout - ctrl.vout_prev) / TS;
    float i_load_est = (1.0f - duty) * il_est - C2 * dvout_dt;
    if (i_load_est < 0.0f) i_load_est = 0.0f;

    ctrl.load_est = ctrl.load_est + K_LOAD * (i_load_est - ctrl.load_est);
    return ctrl.load_est;
}

/* ================= SEPIC 滑模控制器 ================= */
static float SEPIC_SMC_Control(float vout, float vout_ref)
{
    float s, u_eq, u_sw, u;
    float d_eq, load_comp, sat_s, boundary;

    /* 1. 计算误差及其变化率 */
    ctrl.error = vout_ref - vout;
    ctrl.derror = (ctrl.error - (vout_ref - ctrl.vout_prev)) / TS;

    /* 2. 滑模面 s = e + lambda * de/dt */
    ctrl.s_prev = ctrl.s;
    s = ctrl.error + LAMBDA * ctrl.derror;
    ctrl.s = s;

    /* 3. 等效控制律 */
    d_eq = vout_ref / (VIN_NOM + vout_ref);
    if (d_eq > 0.95f) d_eq = 0.95f;
    if (d_eq < 0.05f) d_eq = 0.05f;

    load_comp = ctrl.load_est * R_LOAD_NOM / (VIN_NOM + vout_ref);
    u_eq = d_eq + load_comp;

    /* 4. 指数趋近律 */
    boundary = 0.5f;
    if (s > boundary)       sat_s = 1.0f;
    else if (s < -boundary) sat_s = -1.0f;
    else                    sat_s = s / boundary;

    u_sw = -K_EXP * s - EPSILON * sat_s;

    /* 5. 总控制量 */
    u = u_eq + u_sw;

    /* 6. 限幅 */
    if (u > 0.95f) u = 0.95f;
    if (u < 0.05f) u = 0.05f;

    ctrl.u = u;
    ctrl.duty = u;

    /* 7. 更新状态估计 */
    ctrl.vout_prev = vout;
    ctrl.il_est = (u * VIN_NOM) / (VIN_NOM + vout_ref) / R_LOAD_NOM * 2.0f;
    ctrl.vc1_est = VIN_NOM * u / (1.0f - u + 1e-6f);

    return u;
}

/* ================= 主控制循环 ================= */
static void Control_Loop(void)
{
    float vout, duty;

    vout = ADC_ReadVoltage();

    if (vout > VOUT_MAX) vout = VOUT_MAX;
    if (vout < VOUT_MIN) vout = VOUT_MIN;

    ctrl.vout = vout;

    Load_Disturbance_Observer(vout, ctrl.duty, ctrl.il_est);

    duty = SEPIC_SMC_Control(vout, VOUT_REF);

    PWM_SetDuty(duty);
}

/* ================= 测试打印 ================= */
static void Print_Status(int step)
{
    printf("Step=%3d | Vout=%7.3f V | Vref=%7.3f V | Error=%8.4f | "
           "S=%10.4f | Duty=%6.4f | LoadEst=%7.4f A\n",
           step,
           ctrl.vout,
           ctrl.vout_ref,
           ctrl.error,
           ctrl.s,
           ctrl.duty,
           ctrl.load_est);
}

/* ================= 主函数 ================= */
int main(void)
{
    int i;
    float sim_vout = 0.0f;
    float sim_il = 0.0f;
    float sim_vc1 = 0.0f;
    float sim_load = R_LOAD_NOM;
    float d, vin, vout_target, il_target;

    printf("========================================\n");
    printf("  SEPIC Converter Sliding Mode Control\n");
    printf("  Exponential Reaching Law + Load Disturbance Rejection\n");
    printf("========================================\n\n");

    Hardware_Init();

    ctrl.vout = 0.0f;
    ctrl.vout_prev = 0.0f;
    ctrl.vout_ref = VOUT_REF;
    ctrl.dvout = 0.0f;
    ctrl.error = VOUT_REF;
    ctrl.derror = 0.0f;
    ctrl.s = 0.0f;
    ctrl.s_prev = 0.0f;
    ctrl.u = 0.0f;
    ctrl.duty = 0.0f;
    ctrl.load_est = 0.0f;
    ctrl.il_est = 0.0f;
    ctrl.vc1_est = 0.0f;

    for (i = 0; i < 200; i++) {
        d = ctrl.duty;
        vin = VIN_NOM;

        if (i == 100) {
            sim_load = 5.0f;
            printf("\n>>> Load disturbance: R_LOAD 10ohm -> 5ohm <<<\n\n");
        }

        vout_target = vin * d / (1.0f - d + 1e-6f);
        il_target = vout_target / sim_load;

        sim_vout += (vout_target - sim_vout) * TS / (C2 * sim_load * 0.01f + 1e-6f);
        sim_il += (il_target - sim_il) * TS / (L * 1000.0f + 1e-6f);
        sim_vc1 += (vin - sim_vc1) * TS / (C1 * 1000.0f + 1e-6f);

        if (sim_vout < 0.0f) sim_vout = 0.0f;
        if (sim_vout > VOUT_MAX) sim_vout = VOUT_MAX;

        ADC_DR = (uint32_t)((sim_vout / 10.0f / VREF) * ADC_RES) & 0x00000FFFU;

        Control_Loop();

        if (i % 10 == 0 || i == 100 || i == 101 || i == 102 || i == 105) {
            Print_Status(i);
        }
    }

    printf("\n========================================\n");
    printf("  Simulation Complete\n");
    printf("  Final Vout = %.3f V (Ref = %.3f V)\n", ctrl.vout, VOUT_REF);
    printf("  Final Duty = %.4f\n", ctrl.duty);
    printf("  Final Load Estimate = %.4f A\n", ctrl.load_est);
    printf("========================================\n");

    return 0;
}
