#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 使用普通变量模拟寄存器，避免非法地址访问 */
static volatile uint32_t mock_adc_dr = 0U;
static volatile uint32_t mock_adc_sr = 0U;
static volatile uint32_t mock_adc_cr2 = 0U;
static volatile uint32_t mock_tim_cr1 = 0U;
static volatile uint32_t mock_tim_ccr1 = 0U;
static volatile uint32_t mock_tim_arr = 0U;
static volatile uint32_t mock_tim_cnt = 0U;
static volatile uint32_t mock_gpioa_odr = 0U;

#define ADC1_DR             (mock_adc_dr)
#define ADC1_SR             (mock_adc_sr)
#define ADC1_CR2            (mock_adc_cr2)
#define TIM1_CR1            (mock_tim_cr1)
#define TIM1_CCR1           (mock_tim_ccr1)
#define TIM1_ARR            (mock_tim_arr)
#define TIM1_CNT            (mock_tim_cnt)
#define GPIOA_ODR           (mock_gpioa_odr)

#define ADC_SR_EOC          (1U << 1)
#define TIM_CR1_CEN         (1U << 0)
#define GPIO_PIN_5          (1U << 5)

/* ==================== 系统参数定义 ==================== */
#define PWM_FREQ_HZ         100000U
#define PWM_PERIOD_TICKS    720U
#define ADC_MAX_VALUE       4095.0f
#define ADC_VREF            3.3f
#define CS_GAIN             10.0f
#define RSENSE              0.1f
#define CS_OFFSET_CAL       2048.0f
#define CS_OFFSET_TOL       50.0f

#define IREF_MAX_AMP        5.0f
#define IREF_MIN_AMP        0.0f
#define COMP_GAIN           0.5f
#define COMP_INTEGRAL       0.01f
#define DUTY_MAX            0.85f
#define DUTY_MIN            0.05f

/* ==================== 数据结构 ==================== */
typedef struct {
    float i_ref;
    float i_avg_measured;
    float i_peak_measured;
    float duty;
    float comp_integral;
    float cs_offset;
    float cs_gain_cal;
    uint8_t cal_done;
} FlybackCtrl_t;

/* ==================== 全局变量 ==================== */
static FlybackCtrl_t g_ctrl;

/* ==================== 硬件模拟函数 ==================== */
static void HW_Init(void)
{
    ADC1_CR2 = 0x00000001U;
    TIM1_ARR = PWM_PERIOD_TICKS - 1U;
    TIM1_CR1 |= TIM_CR1_CEN;
    GPIOA_ODR = 0x00000000U;
}

static uint32_t HW_ADC_ReadRaw(void)
{
    static uint32_t mock_val = 2048U;
    mock_val = (mock_val + 137U) % 4096U;
    return mock_val;
}

static void HW_PWM_SetDuty(float duty)
{
    uint32_t ccr;
    if (duty > DUTY_MAX) duty = DUTY_MAX;
    if (duty < DUTY_MIN) duty = DUTY_MIN;
    ccr = (uint32_t)(duty * (float)PWM_PERIOD_TICKS);
    TIM1_CCR1 = ccr;
}

static void HW_DelayMs(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 1000U; i++) {
        __asm__ volatile ("nop");
    }
}

/* ==================== 电流采样校准 ==================== */
static float CS_CalibrateOffset(void)
{
    uint32_t i;
    uint32_t sum = 0U;
    uint32_t raw;
    float offset;

    HW_PWM_SetDuty(0.0f);
    HW_DelayMs(10U);

    for (i = 0U; i < 64U; i++) {
        raw = HW_ADC_ReadRaw();
        sum += raw;
        HW_DelayMs(1U);
    }

    offset = (float)sum / 64.0f;
    return offset;
}

static float CS_RawToCurrent(uint32_t raw)
{
    float voltage;
    float current;

    voltage = ((float)raw - g_ctrl.cs_offset) * ADC_VREF / ADC_MAX_VALUE;
    current = voltage / (RSENSE * CS_GAIN);
    return current;
}

static float CS_CalibrateGain(float actual_current)
{
    uint32_t i;
    uint32_t sum = 0U;
    uint32_t raw;
    float measured;
    float gain_cal;

    for (i = 0U; i < 32U; i++) {
        raw = HW_ADC_ReadRaw();
        sum += raw;
        HW_DelayMs(1U);
    }

    measured = CS_RawToCurrent(sum / 32U);

    if (fabsf(measured) > 0.001f) {
        gain_cal = actual_current / measured;
    } else {
        gain_cal = 1.0f;
    }

    if (gain_cal > 1.5f) gain_cal = 1.5f;
    if (gain_cal < 0.5f) gain_cal = 0.5f;

    return gain_cal;
}

/* ==================== 平均电流模式控制 ==================== */
static float AverageCurrentModeControl(float i_ref, float i_avg)
{
    float error;
    float comp_out;

    error = i_ref - i_avg;

    g_ctrl.comp_integral += error * COMP_INTEGRAL;
    comp_out = error * COMP_GAIN + g_ctrl.comp_integral;

    if (comp_out > DUTY_MAX) {
        comp_out = DUTY_MAX;
        g_ctrl.comp_integral -= error * COMP_INTEGRAL;
    }
    if (comp_out < DUTY_MIN) {
        comp_out = DUTY_MIN;
        g_ctrl.comp_integral -= error * COMP_INTEGRAL;
    }

    return comp_out;
}

static float CS_GetAverageCurrent(void)
{
    uint32_t i;
    uint32_t sum = 0U;
    uint32_t raw;
    float current;
    float avg;

    for (i = 0U; i < 8U; i++) {
        raw = HW_ADC_ReadRaw();
        sum += raw;
        HW_DelayMs(1U);
    }

    current = CS_RawToCurrent(sum / 8U);
    avg = current * g_ctrl.cs_gain_cal;

    return avg;
}

/* ==================== 主控制循环 ==================== */
static void Flyback_ControlLoop(void)
{
    float i_avg;
    float duty;

    i_avg = CS_GetAverageCurrent();
    g_ctrl.i_avg_measured = i_avg;

    duty = AverageCurrentModeControl(g_ctrl.i_ref, i_avg);
    g_ctrl.duty = duty;

    HW_PWM_SetDuty(duty);
}

/* ==================== 初始化 ==================== */
static void Flyback_Init(void)
{
    g_ctrl.i_ref = 1.0f;
    g_ctrl.i_avg_measured = 0.0f;
    g_ctrl.i_peak_measured = 0.0f;
    g_ctrl.duty = 0.0f;
    g_ctrl.comp_integral = 0.0f;
    g_ctrl.cs_offset = CS_OFFSET_CAL;
    g_ctrl.cs_gain_cal = 1.0f;
    g_ctrl.cal_done = 0U;

    HW_Init();
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t loop_count;
    float offset;
    float gain_cal;

    printf("========================================\n");
    printf("  反激变换器平均电流模式控制 - 电流采样校准\n");
    printf("========================================\n\n");

    Flyback_Init();
    printf("[初始化] 系统参数:\n");
    printf("  PWM 频率: %u Hz\n", PWM_FREQ_HZ);
    printf("  采样电阻: %.2f 欧姆\n", RSENSE);
    printf("  采样增益: %.1f 倍\n", CS_GAIN);
    printf("  ADC 参考: %.1f V\n", ADC_VREF);
    printf("  最大占空比: %.2f\n\n", DUTY_MAX);

    printf("[步骤 1] 电流采样偏置校准...\n");
    offset = CS_CalibrateOffset();
    g_ctrl.cs_offset = offset;
    printf("  校准偏置值: %.2f (ADC 码值)\n", offset);
    printf("  理论偏置值: %.2f\n", CS_OFFSET_CAL);
    printf("  偏置误差: %.2f\n", fabsf(offset - CS_OFFSET_CAL));
    if (fabsf(offset - CS_OFFSET_CAL) < CS_OFFSET_TOL) {
        printf("  偏置校准通过!\n\n");
    } else {
        printf("  偏置校准警告: 误差超出容差!\n\n");
    }

    printf("[步骤 2] 电流采样增益校准...\n");
    gain_cal = CS_CalibrateGain(1.0f);
    g_ctrl.cs_gain_cal = gain_cal;
    printf("  增益校准系数: %.4f\n", gain_cal);
    printf("  增益校准完成!\n\n");

    printf("[步骤 3] 平均电流模式控制循环...\n");
    printf("  参考电流: %.2f A\n\n", g_ctrl.i_ref);

    for (loop_count = 0U; loop_count < 10U; loop_count++) {
        Flyback_ControlLoop();

        printf("  [周期 %2u] 平均电流: %.4f A | 占空比: %.4f | 积分项: %.4f\n",
               loop_count + 1U,
               g_ctrl.i_avg_measured,
               g_ctrl.duty,
               g_ctrl.comp_integral);
    }

    printf("\n[步骤 4] 改变参考电流至 2.5A...\n");
    g_ctrl.i_ref = 2.5f;

    for (loop_count = 0U; loop_count < 10U; loop_count++) {
        Flyback_ControlLoop();

        printf("  [周期 %2u] 平均电流: %.4f A | 占空比: %.4f | 积分项: %.4f\n",
               loop_count + 1U,
               g_ctrl.i_avg_measured,
               g_ctrl.duty,
               g_ctrl.comp_integral);
    }

    printf("\n========================================\n");
    printf("  控制算法执行完成\n");
    printf("========================================\n");

    return 0;
}
