#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
#define PWM_FREQ_HZ             100000.0f
#define PWM_PERIOD_TICKS        1000U
#define DEADTIME_TICKS          20U
#define MAX_DUTY_TICKS          (PWM_PERIOD_TICKS - 2U * DEADTIME_TICKS)

/* 模拟定时器寄存器 */
typedef struct {
    uint32_t CR1;
    uint32_t ARR;
    uint32_t CCR1;
    uint32_t CCR2;
    uint32_t CCR3;
    uint32_t CCR4;
    uint32_t BDTR;
} TIM_TypeDef;

static TIM_TypeDef TIM1_mock;
#define TIM1                    (&TIM1_mock)

/* 模拟 ADC 寄存器 */
typedef struct {
    uint32_t DR;
    uint32_t SR;
} ADC_TypeDef;

static ADC_TypeDef ADC1_mock;
#define ADC1                    (&ADC1_mock)

/* 模拟 GPIO */
typedef struct {
    uint32_t ODR;
} GPIO_TypeDef;

static GPIO_TypeDef GPIOA_mock;
#define GPIOA                   (&GPIOA_mock)

/* 位定义 */
#define TIM_CR1_CEN             (1U << 0)
#define TIM_BDTR_MOE            (1U << 15)
#define ADC_SR_EOC              (1U << 1)

/* ==================== 控制参数 ==================== */
#define VIN_NOMINAL             400.0f
#define VOUT_REF                48.0f
#define VOUT_MIN                40.0f
#define VOUT_MAX                56.0f
#define IOUT_MAX                20.0f

#define KP_VOLTAGE              0.05f
#define KI_VOLTAGE              0.002f
#define KP_CURRENT              0.10f
#define KI_CURRENT              0.005f

#define PHASE_SHIFT_MIN_TICKS   50U
#define PHASE_SHIFT_MAX_TICKS   450U

#define ZVZCS_LAG_EDGE_BOOST    30U
#define ZVZCS_AUX_PULSE_TICKS   15U

/* ==================== 系统状态结构体 ==================== */
typedef struct {
    float vout_ref;
    float vout_fb;
    float iout_fb;
    float vin_fb;
    float verr;
    float ierr;
    float v_integral;
    float i_integral;
    float duty_phase_shift;
    uint32_t phase_ticks;
    uint32_t lead_ticks;
    uint32_t lag_ticks;
    uint32_t aux_pulse_ticks;
    uint8_t  zvs_achieved;
    uint8_t  zcs_achieved;
    uint8_t  soft_switch_enable;
} ZVZCS_State_t;

static ZVZCS_State_t g_zvzcs;

/* ==================== 硬件初始化（Mock） ==================== */
static void Hardware_Init(void)
{
    TIM1->CR1  = 0;
    TIM1->ARR  = PWM_PERIOD_TICKS - 1U;
    TIM1->CCR1 = 0;
    TIM1->CCR2 = 0;
    TIM1->CCR3 = 0;
    TIM1->CCR4 = 0;
    TIM1->BDTR = TIM_BDTR_MOE;
    TIM1->CR1 |= TIM_CR1_CEN;

    ADC1->SR = 0;
    GPIOA->ODR = 0;

    printf("[HW] TIM1 ARR=%u, DEADTIME=%u ticks\n",
           (unsigned)TIM1->ARR, (unsigned)DEADTIME_TICKS);
}

/* ==================== 采样函数（Mock） ==================== */
static float ADC_ReadVoltage(void)
{
    /* 模拟：返回 48V 附近带微小纹波 */
    static float t = 0.0f;
    t += 0.01f;
    return VOUT_REF + 0.5f * sinf(t);
}

static float ADC_ReadCurrent(void)
{
    static float t = 0.0f;
    t += 0.013f;
    return 5.0f + 0.3f * sinf(t * 1.7f);
}

static float ADC_ReadInputVoltage(void)
{
    return VIN_NOMINAL;
}

/* ==================== 移相全桥 ZVZCS 控制核心 ==================== */
static void ZVZCS_Init(ZVZCS_State_t *s)
{
    s->vout_ref          = VOUT_REF;
    s->vout_fb           = 0.0f;
    s->iout_fb           = 0.0f;
    s->vin_fb            = 0.0f;
    s->verr              = 0.0f;
    s->ierr              = 0.0f;
    s->v_integral        = 0.0f;
    s->i_integral        = 0.0f;
    s->duty_phase_shift  = 0.5f;
    s->phase_ticks       = 250U;
    s->lead_ticks        = 0U;
    s->lag_ticks         = 0U;
    s->aux_pulse_ticks   = 0U;
    s->zvs_achieved      = 0U;
    s->zcs_achieved      = 0U;
    s->soft_switch_enable = 1U;
}

static void ZVZCS_UpdateFeedback(ZVZCS_State_t *s)
{
    s->vout_fb = ADC_ReadVoltage();
    s->iout_fb = ADC_ReadCurrent();
    s->vin_fb  = ADC_ReadInputVoltage();
}

static void ZVZCS_VoltageLoop(ZVZCS_State_t *s)
{
    float verr;

    verr = s->vout_ref - s->vout_fb;
    s->verr = verr;

    s->v_integral += KI_VOLTAGE * verr;

    /* 积分限幅 */
    if (s->v_integral > 1.0f)  s->v_integral = 1.0f;
    if (s->v_integral < 0.0f)  s->v_integral = 0.0f;

    s->duty_phase_shift = KP_VOLTAGE * verr + s->v_integral;

    /* 占空比限幅 */
    if (s->duty_phase_shift > 0.95f) s->duty_phase_shift = 0.95f;
    if (s->duty_phase_shift < 0.05f) s->duty_phase_shift = 0.05f;
}

static void ZVZCS_CurrentLoop(ZVZCS_State_t *s)
{
    float ierr;

    ierr = s->duty_phase_shift * IOUT_MAX - s->iout_fb;
    s->ierr = ierr;

    s->i_integral += KI_CURRENT * ierr;

    if (s->i_integral > 0.5f)  s->i_integral = 0.5f;
    if (s->i_integral < -0.5f) s->i_integral = -0.5f;

    s->duty_phase_shift += KP_CURRENT * ierr + s->i_integral;

    if (s->duty_phase_shift > 0.95f) s->duty_phase_shift = 0.95f;
    if (s->duty_phase_shift < 0.05f) s->duty_phase_shift = 0.05f;
}

static void ZVZCS_PhaseShiftCalc(ZVZCS_State_t *s)
{
    uint32_t half_period;
    uint32_t shift;

    half_period = PWM_PERIOD_TICKS / 2U;

    shift = (uint32_t)(s->duty_phase_shift * (float)half_period);

    if (shift < PHASE_SHIFT_MIN_TICKS) shift = PHASE_SHIFT_MIN_TICKS;
    if (shift > PHASE_SHIFT_MAX_TICKS) shift = PHASE_SHIFT_MAX_TICKS;

    s->phase_ticks = shift;

    /* 超前桥臂固定 50% 占空比 */
    s->lead_ticks = half_period;

    /* 滞后桥臂根据移相角调整 */
    s->lag_ticks = half_period - shift;

    if (s->lag_ticks < DEADTIME_TICKS) {
        s->lag_ticks = DEADTIME_TICKS;
    }
}

static void ZVZCS_SoftSwitchAssess(ZVZCS_State_t *s)
{
    float load_ratio;

    load_ratio = s->iout_fb / IOUT_MAX;

    /* ZVS 条件：超前桥臂在轻载以上可实现 */
    if (load_ratio > 0.15f) {
        s->zvs_achieved = 1U;
    } else {
        s->zvs_achieved = 0U;
    }

    /* ZCS 条件：滞后桥臂需要辅助网络提供电流复位 */
    if (s->soft_switch_enable && load_ratio > 0.10f) {
        s->zcs_achieved = 1U;
        s->aux_pulse_ticks = ZVZCS_AUX_PULSE_TICKS;
    } else {
        s->zcs_achieved = 0U;
        s->aux_pulse_ticks = 0U;
    }

    /* 根据软开关状态微调移相角 */
    if (s->zvs_achieved && s->zcs_achieved) {
        if (s->phase_ticks > PHASE_SHIFT_MIN_TICKS + ZVZCS_LAG_EDGE_BOOST) {
            s->phase_ticks -= ZVZCS_LAG_EDGE_BOOST;
        }
    }
}

static void ZVZCS_PWMOutput(ZVZCS_State_t *s)
{
    uint32_t ccr1, ccr2, ccr3, ccr4;

    /* 超前桥臂：固定 50% 互补 */
    ccr1 = s->lead_ticks;
    ccr2 = s->lead_ticks;

    /* 滞后桥臂：移相控制 */
    ccr3 = s->lag_ticks;
    ccr4 = s->lag_ticks;

    /* 辅助网络脉冲：在滞后桥臂关断前触发 */
    if (s->aux_pulse_ticks > 0U) {
        ccr4 += s->aux_pulse_ticks;
        if (ccr4 > PWM_PERIOD_TICKS) {
            ccr4 = PWM_PERIOD_TICKS;
        }
    }

    TIM1->CCR1 = ccr1;
    TIM1->CCR2 = ccr2;
    TIM1->CCR3 = ccr3;
    TIM1->CCR4 = ccr4;
}

static void ZVZCS_ControlStep(ZVZCS_State_t *s)
{
    ZVZCS_UpdateFeedback(s);
    ZVZCS_VoltageLoop(s);
    ZVZCS_CurrentLoop(s);
    ZVZCS_PhaseShiftCalc(s);
    ZVZCS_SoftSwitchAssess(s);
    ZVZCS_PWMOutput(s);
}

/* ==================== 测试打印 ==================== */
static void Print_State(const ZVZCS_State_t *s, uint32_t step)
{
    printf("Step %3u | Vout=%6.2fV Iout=%5.2fA | "
           "Phase=%3u ticks | ZVS=%u ZCS=%u | "
           "CCR1=%3u CCR2=%3u CCR3=%3u CCR4=%3u\n",
           (unsigned)step,
           s->vout_fb,
           s->iout_fb,
           (unsigned)s->phase_ticks,
           (unsigned)s->zvs_achieved,
           (unsigned)s->zcs_achieved,
           (unsigned)TIM1->CCR1,
           (unsigned)TIM1->CCR2,
           (unsigned)TIM1->CCR3,
           (unsigned)TIM1->CCR4);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t step;

    printf("========================================\n");
    printf("  Phase-Shifted Full-Bridge ZVZCS Control\n");
    printf("  Auxiliary Network Soft-Switching\n");
    printf("========================================\n\n");

    Hardware_Init();
    ZVZCS_Init(&g_zvzcs);

    printf("Initial: Vref=%.1fV, Fsw=%.0fkHz, Period=%u ticks\n\n",
           g_zvzcs.vout_ref,
           PWM_FREQ_HZ / 1000.0f,
           (unsigned)PWM_PERIOD_TICKS);

    for (step = 0; step < 20U; step++) {
        ZVZCS_ControlStep(&g_zvzcs);
        Print_State(&g_zvzcs, step);
    }

    printf("\n--- Soft-Switching Summary ---\n");
    printf("ZVS achieved: %s\n", g_zvzcs.zvs_achieved ? "YES" : "NO");
    printf("ZCS achieved: %s\n", g_zvzcs.zcs_achieved ? "YES" : "NO");
    printf("Aux pulse width: %u ticks\n", (unsigned)g_zvzcs.aux_pulse_ticks);
    printf("Final phase shift: %u ticks (%.1f%%)\n",
           (unsigned)g_zvzcs.phase_ticks,
           (float)g_zvzcs.phase_ticks / (float)(PWM_PERIOD_TICKS / 2U) * 100.0f);

    return 0;
}
