#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ============================================================
 * 移相全桥ZVZCS控制（辅助网络软开关）控制算法骨架
 * 目标平台：通用C环境（GCC可编译）
 * 说明：所有硬件寄存器均使用本地变量模拟，不依赖任何单片机头文件
 * ============================================================ */

/* ---------- 硬件寄存器模拟（mock，使用普通变量避免非法地址访问） ---------- */
static uint32_t mock_pwm_cr = 0;
static uint32_t mock_pwm_arr = 0;
static uint32_t mock_pwm_ccr1 = 0;
static uint32_t mock_pwm_ccr2 = 0;
static uint32_t mock_pwm_ccr3 = 0;
static uint32_t mock_pwm_ccr4 = 0;
static uint32_t mock_pwm_bdtr = 0;
static uint32_t mock_adc_dr = 0;
static uint32_t mock_adc_cr = 0;
static uint32_t mock_gpio_odr = 0;

#define PWM_CR      (mock_pwm_cr)
#define PWM_ARR     (mock_pwm_arr)
#define PWM_CCR1    (mock_pwm_ccr1)
#define PWM_CCR2    (mock_pwm_ccr2)
#define PWM_CCR3    (mock_pwm_ccr3)
#define PWM_CCR4    (mock_pwm_ccr4)
#define PWM_BDTR    (mock_pwm_bdtr)
#define ADC_DR      (mock_adc_dr)
#define ADC_CR      (mock_adc_cr)
#define GPIO_ODR    (mock_gpio_odr)

/* ---------- 系统参数 ---------- */
#define PWM_FREQ_HZ         100000U
#define PWM_PERIOD_TICKS    1000U
#define DEADTIME_NS         200U
#define DEADTIME_TICKS      ((DEADTIME_NS * PWM_PERIOD_TICKS) / (1000000000U / PWM_FREQ_HZ))

#define VIN_NOMINAL         400.0f
#define VOUT_TARGET         48.0f
#define VOUT_MAX            60.0f
#define IOUT_MAX            20.0f

#define PI_KP               0.5f
#define PI_KI               0.02f
#define PI_LIMIT            0.95f

#define ZVZCS_LAG_MIN       0.05f
#define ZVZCS_LAG_MAX       0.90f

/* ---------- 数据结构 ---------- */
typedef struct {
    float vout_ref;
    float vout_fb;
    float iout_fb;
    float vin_fb;
    float phase_shift;
    float phase_shift_prev;
    float integral;
    float error;
    float error_prev;
    float duty_lead;
    float duty_lag;
    float aux_duty;
    uint32_t pwm_ccr1;
    uint32_t pwm_ccr2;
    uint32_t pwm_ccr3;
    uint32_t pwm_ccr4;
    uint32_t aux_ccr;
} ZVZCS_Ctrl_t;

/* ---------- 全局变量 ---------- */
static ZVZCS_Ctrl_t g_ctrl;
static uint32_t g_tick_count = 0;

/* ---------- 函数声明 ---------- */
static void ZVZCS_Init(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_ReadFeedback(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_VoltageLoop(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_PhaseShiftCalc(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_AuxNetworkCtrl(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_PWMUpdate(ZVZCS_Ctrl_t *ctrl);
static void ZVZCS_SoftStart(ZVZCS_Ctrl_t *ctrl);
static float ZVZCS_Clamp(float val, float min, float max);
static void ZVZCS_PrintStatus(ZVZCS_Ctrl_t *ctrl);

/* ============================================================
 * 初始化
 * ============================================================ */
static void ZVZCS_Init(ZVZCS_Ctrl_t *ctrl)
{
    ctrl->vout_ref = VOUT_TARGET;
    ctrl->vout_fb = 0.0f;
    ctrl->iout_fb = 0.0f;
    ctrl->vin_fb = VIN_NOMINAL;
    ctrl->phase_shift = 0.0f;
    ctrl->phase_shift_prev = 0.0f;
    ctrl->integral = 0.0f;
    ctrl->error = 0.0f;
    ctrl->error_prev = 0.0f;
    ctrl->duty_lead = 0.5f;
    ctrl->duty_lag = 0.5f;
    ctrl->aux_duty = 0.1f;
    ctrl->pwm_ccr1 = 0;
    ctrl->pwm_ccr2 = 0;
    ctrl->pwm_ccr3 = 0;
    ctrl->pwm_ccr4 = 0;
    ctrl->aux_ccr = 0;

    PWM_CR = 0x00000001U;
    PWM_ARR = PWM_PERIOD_TICKS - 1U;
    PWM_BDTR = DEADTIME_TICKS;

    ADC_CR = 0x00000001U;

    printf("[ZVZCS] 初始化完成: PWM频率=%uHz, 死区=%uticks\n",
           PWM_FREQ_HZ, DEADTIME_TICKS);
}

/* ============================================================
 * 读取反馈量（模拟ADC采样）
 * ============================================================ */
static void ZVZCS_ReadFeedback(ZVZCS_Ctrl_t *ctrl)
{
    uint32_t adc_raw = ADC_DR;
    float t = (float)g_tick_count * 0.001f;

    ctrl->vout_fb = VOUT_TARGET * (0.8f + 0.2f * sinf(t * 0.5f));
    ctrl->iout_fb = IOUT_MAX * (0.3f + 0.2f * sinf(t * 0.3f));
    ctrl->vin_fb = VIN_NOMINAL * (0.95f + 0.05f * sinf(t * 0.1f));

    if (ctrl->vin_fb < 1.0f) {
        ctrl->vin_fb = 1.0f;
    }

    (void)adc_raw;
}

/* ============================================================
 * 电压环PI控制
 * ============================================================ */
static void ZVZCS_VoltageLoop(ZVZCS_Ctrl_t *ctrl)
{
    float error;
    float p_term;
    float i_term;
    float output;

    error = ctrl->vout_ref - ctrl->vout_fb;
    ctrl->error = error;

    p_term = PI_KP * error;

    ctrl->integral += PI_KI * error;

    if (ctrl->integral > PI_LIMIT) {
        ctrl->integral = PI_LIMIT;
    } else if (ctrl->integral < -PI_LIMIT) {
        ctrl->integral = -PI_LIMIT;
    }

    i_term = ctrl->integral;

    output = p_term + i_term;

    output = ZVZCS_Clamp(output, 0.0f, PI_LIMIT);

    ctrl->phase_shift_prev = ctrl->phase_shift;
    ctrl->phase_shift = output;

    ctrl->error_prev = error;
}

/* ============================================================
 * 移相占空比计算（ZVZCS核心）
 * ============================================================ */
static void ZVZCS_PhaseShiftCalc(ZVZCS_Ctrl_t *ctrl)
{
    float ps;
    float lag_duty;
    float lead_duty;

    ps = ctrl->phase_shift;

    if (ctrl->vin_fb > 1.0f) {
        ps = ps * (VIN_NOMINAL / ctrl->vin_fb);
    }

    ps = ZVZCS_Clamp(ps, ZVZCS_LAG_MIN, ZVZCS_LAG_MAX);

    lead_duty = 0.5f;
    lag_duty = ps;

    ctrl->aux_duty = ZVZCS_Clamp(ps * 0.3f, 0.02f, 0.3f);

    ctrl->duty_lead = lead_duty;
    ctrl->duty_lag = lag_duty;

    ctrl->pwm_ccr1 = (uint32_t)((float)PWM_PERIOD_TICKS * (1.0f - lead_duty));
    ctrl->pwm_ccr2 = (uint32_t)((float)PWM_PERIOD_TICKS * lead_duty);
    ctrl->pwm_ccr3 = (uint32_t)((float)PWM_PERIOD_TICKS * (1.0f - lag_duty));
    ctrl->pwm_ccr4 = (uint32_t)((float)PWM_PERIOD_TICKS * lag_duty);
    ctrl->aux_ccr = (uint32_t)((float)PWM_PERIOD_TICKS * ctrl->aux_duty);
}

/* ============================================================
 * 辅助网络控制
 * ============================================================ */
static void ZVZCS_AuxNetworkCtrl(ZVZCS_Ctrl_t *ctrl)
{
    float aux_duty;
    float load_factor;

    load_factor = ctrl->iout_fb / IOUT_MAX;
    load_factor = ZVZCS_Clamp(load_factor, 0.0f, 1.0f);

    if (load_factor < 0.3f) {
        aux_duty = ctrl->aux_duty * (1.0f + (0.3f - load_factor) * 2.0f);
    } else {
        aux_duty = ctrl->aux_duty;
    }

    aux_duty = ZVZCS_Clamp(aux_duty, 0.02f, 0.35f);
    ctrl->aux_duty = aux_duty;
    ctrl->aux_ccr = (uint32_t)((float)PWM_PERIOD_TICKS * aux_duty);

    if (ctrl->phase_shift > 0.1f) {
        GPIO_ODR |= (1U << 5);
    } else {
        GPIO_ODR &= ~(1U << 5);
    }
}

/* ============================================================
 * PWM寄存器更新
 * ============================================================ */
static void ZVZCS_PWMUpdate(ZVZCS_Ctrl_t *ctrl)
{
    PWM_CCR1 = ctrl->pwm_ccr1;
    PWM_CCR2 = ctrl->pwm_ccr2;
    PWM_CCR3 = ctrl->pwm_ccr3;
    PWM_CCR4 = ctrl->pwm_ccr4;

    PWM_BDTR = (PWM_BDTR & 0xFFFF0000U) | (ctrl->aux_ccr & 0x0000FFFFU);
    PWM_BDTR = (PWM_BDTR & 0x0000FFFFU) | (DEADTIME_TICKS << 16);
}

/* ============================================================
 * 软启动
 * ============================================================ */
static void ZVZCS_SoftStart(ZVZCS_Ctrl_t *ctrl)
{
    static uint32_t soft_start_cnt = 0;
    float ramp;

    if (soft_start_cnt < 1000U) {
        soft_start_cnt++;
        ramp = (float)soft_start_cnt / 1000.0f;
        ctrl->vout_ref = VOUT_TARGET * ramp;
    } else {
        ctrl->vout_ref = VOUT_TARGET;
    }
}

/* ============================================================
 * 限幅函数
 * ============================================================ */
static float ZVZCS_Clamp(float val, float min, float max)
{
    if (val < min) {
        return min;
    }
    if (val > max) {
        return max;
    }
    return val;
}

/* ============================================================
 * 状态打印
 * ============================================================ */
static void ZVZCS_PrintStatus(ZVZCS_Ctrl_t *ctrl)
{
    printf("[ZVZCS] tick=%u | Vin=%.1fV Vout=%.2fV(Ref=%.2fV) Iout=%.2fA | "
           "PS=%.3f | Lead=%.3f Lag=%.3f Aux=%.3f | "
           "CCR1=%u CCR2=%u CCR3=%u CCR4=%u AuxCCR=%u\n",
           g_tick_count,
           ctrl->vin_fb,
           ctrl->vout_fb,
           ctrl->vout_ref,
           ctrl->iout_fb,
           ctrl->phase_shift,
           ctrl->duty_lead,
           ctrl->duty_lag,
           ctrl->aux_duty,
           ctrl->pwm_ccr1,
           ctrl->pwm_ccr2,
           ctrl->pwm_ccr3,
           ctrl->pwm_ccr4,
           ctrl->aux_ccr);
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    uint32_t loop_count;

    printf("========================================\n");
    printf("  移相全桥ZVZCS控制算法（辅助网络软开关）\n");
    printf("========================================\n");

    ZVZCS_Init(&g_ctrl);

    for (loop_count = 0; loop_count < 20U; loop_count++) {
        g_tick_count++;

        ZVZCS_SoftStart(&g_ctrl);
        ZVZCS_ReadFeedback(&g_ctrl);
        ZVZCS_VoltageLoop(&g_ctrl);
        ZVZCS_PhaseShiftCalc(&g_ctrl);
        ZVZCS_AuxNetworkCtrl(&g_ctrl);
        ZVZCS_PWMUpdate(&g_ctrl);
        ZVZCS_PrintStatus(&g_ctrl);
    }

    printf("========================================\n");
    printf("  控制循环结束\n");
    printf("========================================\n");

    return 0;
}
