#define TIMER_COUNT_REG     (g_timer_count_reg)

/* 过零比较器 状态位定义 */
#define ZCD_FLAG_CURRENT_ZERO   (1U << 0)

/* PWM 使能位定义 */
#define PWM_ENABLE_BIT          (1U << 0)

/* ==================== 系统参数定义 ==================== */

#define PWM_PERIOD          1000U       /* PWM 周期计数值 */
#define ADC_MAX_VALUE       4095U       /* 12 位 ADC 最大值 */
#define VREF_MV             3300U       /* 参考电压 mV */
#define VOUT_TARGET_MV      12000U      /* 目标输出电压 mV */
#define VIN_NOMINAL_MV      5000U       /* 标称输入电压 mV */

/* 控制参数 */
#define KP                  0.5f
#define KI                  0.05f
#define DUTY_MIN            0.05f
#define DUTY_MAX            0.90f

/* DCM 检测参数 */
#define ZCD_DEBOUNCE_CNT    3U
#define DCM_MIN_OFF_TIME    5U

/* ==================== 数据结构定义 ==================== */

typedef struct {
    float   duty_cycle;
    float   duty_cycle_prev;
    float   integral;
    float   vout_target;
    float   vout_actual;
    float   error;
    float   error_prev;

    bool    dcm_mode;
    bool    inductor_current_zero;
    uint8_t zcd_debounce;
    uint32_t off_time;

    uint8_t state;
    uint32_t timer;
} BoostDCM_Controller;

/* 状态机状态定义 */
#define STATE_IDLE              0U
#define STATE_SWITCH_ON         1U
#define STATE_SWITCH_OFF        2U
#define STATE_DCM_WAIT          3U

/* ==================== 函数声明 ==================== */

static void BoostDCM_Init(BoostDCM_Controller *ctrl);
static void BoostDCM_Update(BoostDCM_Controller *ctrl, uint16_t adc_vout);
static void BoostDCM_StateMachine(BoostDCM_Controller *ctrl);
static bool BoostDCM_CheckZCD(BoostDCM_Controller *ctrl);
static void BoostDCM_SetPWM(float duty);
static void BoostDCM_EnablePWM(bool enable);
static float BoostDCM_ReadVout(uint16_t adc_value);
static void BoostDCM_PrintStatus(const BoostDCM_Controller *ctrl);

/* ==================== 主函数 ==================== */

int main(void)
{
    BoostDCM_Controller ctrl;
    uint16_t adc_value;
    uint32_t loop_count;

    printf("========================================\n");
    printf("  Boost Converter DCM Control Demo\n");
    printf("========================================\n\n");

    BoostDCM_Init(&ctrl);

    for (loop_count = 0; loop_count < 20; loop_count++) {
        float simulated_vout = 5000.0f + (float)loop_count * 400.0f;
        if (simulated_vout > 13000.0f) {
            simulated_vout = 13000.0f;
        }
        adc_value = (uint16_t)((simulated_vout / (float)VREF_MV) * (float)ADC_MAX_VALUE);
        if (adc_value > ADC_MAX_VALUE) {
            adc_value = ADC_MAX_VALUE;
        }

        /* 模拟过零比较器 */
        if (ctrl.state == STATE_SWITCH_OFF && ctrl.timer > 10U) {
            ZCD_STATUS_REG |= ZCD_FLAG_CURRENT_ZERO;
