            ZCD_STATUS_REG &= (uint8_t)(~ZCD_FLAG_CURRENT_ZERO);
        }

        BoostDCM_Update(&ctrl, adc_value);
        BoostDCM_PrintStatus(&ctrl);

        TIMER_COUNT_REG++;
    }

    printf("\n========================================\n");
    printf("  Simulation Complete\n");
    printf("========================================\n");

    return 0;
}

/* ==================== 函数实现 ==================== */

static void BoostDCM_Init(BoostDCM_Controller *ctrl)
{
    if (ctrl == NULL) {
        return;
    }

    ctrl->duty_cycle = 0.5f;
    ctrl->duty_cycle_prev = 0.5f;
    ctrl->integral = 0.0f;
    ctrl->vout_target = (float)VOUT_TARGET_MV;
    ctrl->vout_actual = 0.0f;
    ctrl->error = 0.0f;
    ctrl->error_prev = 0.0f;

    ctrl->dcm_mode = false;
    ctrl->inductor_current_zero = false;
    ctrl->zcd_debounce = 0U;
    ctrl->off_time = 0U;

    ctrl->state = STATE_IDLE;
    ctrl->timer = 0U;

    PWM_DUTY_REG = 0U;
    PWM_ENABLE_REG = 0U;
    ZCD_STATUS_REG = 0U;
    TIMER_COUNT_REG = 0U;

    printf("[INIT] Boost DCM Controller initialized.\n");
    printf("[INIT] Target Vout = %d mV, Vin = %d mV\n",
           VOUT_TARGET_MV, VIN_NOMINAL_MV);
    printf("[INIT] KP = %.2f, KI = %.2f\n", KP, KI);
    printf("[INIT] Duty range: %.2f ~ %.2f\n\n", DUTY_MIN, DUTY_MAX);
}

static float BoostDCM_ReadVout(uint16_t adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * (float)VREF_MV;
}

static void BoostDCM_SetPWM(float duty)
{
    uint16_t duty_reg;

    if (duty < DUTY_MIN) {
        duty = DUTY_MIN;
    }
    if (duty > DUTY_MAX) {
        duty = DUTY_MAX;
    }

    duty_reg = (uint16_t)(duty * (float)PWM_PERIOD);
    PWM_DUTY_REG = duty_reg;
}

static void BoostDCM_EnablePWM(bool enable)
{
    if (enable) {
        PWM_ENABLE_REG |= PWM_ENABLE_BIT;
    } else {
        PWM_ENABLE_REG &= (uint8_t)(~PWM_ENABLE_BIT);
    }
}

static bool BoostDCM_CheckZCD(BoostDCM_Controller *ctrl)
{
    bool zcd_detected = false;

    if (ctrl == NULL) {
        return false;
    }

    if (ZCD_STATUS_REG & ZCD_FLAG_CURRENT_ZERO) {
        if (ctrl->zcd_debounce < ZCD_DEBOUNCE_CNT) {
            ctrl->zcd_debounce++;
        }
        if (ctrl->zcd_debounce >= ZCD_DEBOUNCE_CNT) {
            zcd_detected = true;
        }
    } else {
        ctrl->zcd_debounce = 0U;
    }

    return zcd_detected;
}

static void BoostDCM_StateMachine(BoostDCM_Controller *ctrl)
{
    if (ctrl == NULL) {
        return;
    }

    switch (ctrl->state) {
    case STATE_IDLE:
        ctrl->timer = 0U;
        ctrl->state = STATE_SWITCH_ON;
        break;

    case STATE_SWITCH_ON:
        BoostDCM_EnablePWM(true);
        BoostDCM_SetPWM(ctrl->duty_cycle);
        ctrl->timer++;

        if (ctrl->timer >= (uint32_t)(ctrl->duty_cycle * (float)PWM_PERIOD)) {
            ctrl->state = STATE_SWITCH_OFF;
            ctrl->timer = 0U;
        }
        break;

    case STATE_SWITCH_OFF:
        BoostDCM_EnablePWM(false);
        ctrl->timer++;

        if (BoostDCM_CheckZCD(ctrl)) {
            ctrl->inductor_current_zero = true;
            ctrl->dcm_mode = true;
            ctrl->state = STATE_DCM_WAIT;
            ctrl->timer = 0U;
            ctrl->off_time = 0U;
        } else if (ctrl->timer >= (uint32_t)((1.0f - ctrl->duty_cycle) * (float)PWM_PERIOD)) {
            ctrl->dcm_mode = false;
            ctrl->inductor_current_zero = false;
            ctrl->state = STATE_SWITCH_ON;
            ctrl->timer = 0U;
        }
        break;

    case STATE_DCM_WAIT:
        BoostDCM_EnablePWM(false);
        ctrl->timer++;
        ctrl->off_time++;

        if (ctrl->off_time >= DCM_MIN_OFF_TIME) {
            ctrl->state = STATE_SWITCH_ON;
            ctrl->timer = 0U;
            ctrl->inductor_current_zero = false;
            ctrl->zcd_debounce = 0U;
        }
        break;

    default:
        ctrl->state = STATE_IDLE;
        break;
    }
}

static void BoostDCM_Update(BoostDCM_Controller *ctrl, uint16_t adc_vout)
{
    if (ctrl == NULL) {
        return;
    }

    ctrl->vout_actual = BoostDCM_ReadVout(adc_vout);
    ctrl->error = ctrl->vout_target - ctrl->vout_actual;

    ctrl->integral += ctrl->error * KI;

    if (ctrl->integral > DUTY_MAX) {
        ctrl->integral = DUTY_MAX;
    }
    if (ctrl->integral < DUTY_MIN) {
        ctrl->integral = DUTY_MIN;
    }

    ctrl->duty_cycle = (KP * ctrl->error) + ctrl->integral;

    if (ctrl->duty_cycle < DUTY_MIN) {
        ctrl->duty_cycle = DUTY_MIN;
    }
    if (ctrl->duty_cycle > DUTY_MAX) {
        ctrl->duty_cycle = DUTY_MAX;
    }

    BoostDCM_StateMachine(ctrl);

    ctrl->error_prev = ctrl->error;
    ctrl->duty_cycle_prev = ctrl->duty_cycle;
}

static void BoostDCM_PrintStatus(const BoostDCM_Controller *ctrl)
{
    const char *state_str;

    if (ctrl == NULL) {
        return;
    }

    switch (ctrl->state) {
    case STATE_IDLE:       state_str = "IDLE";       break;
    case STATE_SWITCH_ON:  state_str = "SWITCH_ON";  break;
    case STATE_SWITCH_OFF: state_str = "SWITCH_OFF"; break;
    case STATE_DCM_WAIT:   state_str = "DCM_WAIT";   break;
    default:               state_str = "UNKNOWN";    break;
    }

    printf("[CTRL] Vout=%7.1f mV | Target=%7.1f mV | Err=%7.1f mV | "
           "Duty=%.3f | State=%-10s | DCM=%s | ZCD=%s\n",
           ctrl->vout_actual,
           ctrl->vout_target,
           ctrl->error,
           ctrl->duty_cycle,
           state_str,
           ctrl->dcm_mode ? "YES" : "NO ",
           ctrl->inductor_current_zero ? "YES" : "NO ");
}
