#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误
 * ============================================================ */
static volatile uint16_t g_adc_data = 0;
static volatile uint32_t g_adc_ctrl = 0;
static volatile uint16_t g_pwm_duty = 0;
static volatile uint32_t g_pwm_ctrl = 0;
static volatile uint32_t g_gpio_zcd = 0;
static volatile uint32_t g_timer_cnt = 0;

#define REG_ADC_DATA        (g_adc_data)
#define REG_ADC_CTRL        (g_adc_ctrl)
#define REG_PWM_DUTY        (g_pwm_duty)
#define REG_PWM_CTRL        (g_pwm_ctrl)
#define REG_GPIO_ZCD        (g_gpio_zcd)
#define REG_TIMER_CNT       (g_timer_cnt)

#define ADC_START           (1U << 0)
#define ADC_EOC             (1U << 1)
#define PWM_ENABLE          (1U << 0)
#define PWM_DISABLE         (0U)
#define ZCD_PIN_MASK        (1U << 0)

/* ============================================================
 * 系统参数
 * ============================================================ */
#define VREF_MV             3300U
#define ADC_FULL_SCALE      4095U
#define PWM_PERIOD          1000U
#define VOUT_TARGET_MV      12000U
#define VIN_MIN_MV          3000U
#define DUTY_MIN            50U
#define DUTY_MAX            900U
#define DCM_ZCD_THRESHOLD   5U

/* ============================================================
 * 状态机定义
 * ============================================================ */
typedef enum {
    BOOST_STATE_IDLE = 0,
    BOOST_STATE_ON,
    BOOST_STATE_OFF,
    BOOST_STATE_DCM_WAIT_ZCD,
    BOOST_STATE_FAULT
} BoostState_t;

typedef struct {
    BoostState_t state;
    uint16_t duty;
    uint16_t vout_mv;
    uint16_t vin_mv;
    uint16_t zcd_counter;
    uint32_t switch_count;
    bool     zcd_detected;
    bool     dcm_mode;
} BoostCtrl_t;

static BoostCtrl_t boost;

/* ============================================================
 * 硬件抽象函数
 * ============================================================ */
static uint16_t ADC_ReadChannel(uint8_t ch)
{
    (void)ch;
    REG_ADC_CTRL |= ADC_START;
    /* 模拟转换完成，避免死循环 */
    REG_ADC_CTRL |= ADC_EOC;
    return REG_ADC_DATA;
}

static uint16_t ADC_ToMilliVolt(uint16_t raw)
{
    return (uint16_t)(((uint32_t)raw * VREF_MV) / ADC_FULL_SCALE);
}

static void PWM_SetDuty(uint16_t duty)
{
    if (duty > PWM_PERIOD) {
        duty = PWM_PERIOD;
    }
    REG_PWM_DUTY = duty;
}

static void PWM_Enable(void)
{
    REG_PWM_CTRL |= PWM_ENABLE;
}

static void PWM_Disable(void)
{
    REG_PWM_CTRL = PWM_DISABLE;
}

static bool ZCD_IsCurrentZero(void)
{
    return (REG_GPIO_ZCD & ZCD_PIN_MASK) != 0U;
}

/* ============================================================
 * 初始化
 * ============================================================ */
static void Boost_Init(void)
{
    boost.state = BOOST_STATE_IDLE;
    boost.duty = DUTY_MIN;
    boost.vout_mv = 0U;
    boost.vin_mv = 0U;
    boost.zcd_counter = 0U;
    boost.switch_count = 0U;
    boost.zcd_detected = false;
    boost.dcm_mode = true;

    PWM_Disable();
    PWM_SetDuty(0U);
}

/* ============================================================
 * 电压采样
 * ============================================================ */
static void Boost_SampleVoltages(void)
{
    uint16_t raw_vin = ADC_ReadChannel(0U);
    uint16_t raw_vout = ADC_ReadChannel(1U);

    boost.vin_mv = ADC_ToMilliVolt(raw_vin);
    boost.vout_mv = ADC_ToMilliVolt(raw_vout);
}

/* ============================================================
 * 占空比计算（简单电压模式）
 * ============================================================ */
static uint16_t Boost_CalcDuty(void)
{
    uint32_t duty;

    if (boost.vin_mv < VIN_MIN_MV) {
        return DUTY_MIN;
    }

    if (boost.vout_mv >= VOUT_TARGET_MV) {
        return DUTY_MIN;
    }

    duty = ((uint32_t)DUTY_MAX * (VOUT_TARGET_MV - boost.vout_mv)) /
           VOUT_TARGET_MV;

    if (duty < DUTY_MIN) {
        duty = DUTY_MIN;
    }
    if (duty > DUTY_MAX) {
        duty = DUTY_MAX;
    }

    return (uint16_t)duty;
}

/* ============================================================
 * DCM 过零检测处理
 * ============================================================ */
static void Boost_HandleZCD(void)
{
    if (ZCD_IsCurrentZero()) {
        boost.zcd_counter++;
        if (boost.zcd_counter >= DCM_ZCD_THRESHOLD) {
            boost.zcd_detected = true;
        }
    } else {
        boost.zcd_counter = 0U;
        boost.zcd_detected = false;
    }
}

/* ============================================================
 * 状态机主循环
 * ============================================================ */
static void Boost_ControlStep(void)
{
    Boost_SampleVoltages();

    switch (boost.state) {
    case BOOST_STATE_IDLE:
        boost.duty = DUTY_MIN;
        PWM_SetDuty(boost.duty);
        PWM_Enable();
        boost.state = BOOST_STATE_ON;
        break;

    case BOOST_STATE_ON:
        boost.duty = Boost_CalcDuty();
        PWM_SetDuty(boost.duty);
        boost.switch_count++;
        boost.state = BOOST_STATE_OFF;
        break;

    case BOOST_STATE_OFF:
        PWM_SetDuty(0U);
        boost.state = BOOST_STATE_DCM_WAIT_ZCD;
        break;

    case BOOST_STATE_DCM_WAIT_ZCD:
        Boost_HandleZCD();
        if (boost.zcd_detected) {
            boost.dcm_mode = true;
        } else {
            boost.dcm_mode = false;
        }
        boost.state = BOOST_STATE_ON;
        break;

    case BOOST_STATE_FAULT:
    default:
        PWM_Disable();
        PWM_SetDuty(0U);
        break;
    }
}

/* ============================================================
 * 测试打印
 * ============================================================ */
static void Boost_PrintStatus(void)
{
    const char *state_str;

    switch (boost.state) {
    case BOOST_STATE_IDLE:         state_str = "IDLE";         break;
    case BOOST_STATE_ON:           state_str = "ON";           break;
    case BOOST_STATE_OFF:          state_str = "OFF";          break;
    case BOOST_STATE_DCM_WAIT_ZCD: state_str = "DCM_WAIT_ZCD"; break;
    case BOOST_STATE_FAULT:        state_str = "FAULT";        break;
    default:                       state_str = "UNKNOWN";      break;
    }

    printf("State=%-12s Duty=%4u Vin=%5umV Vout=%5umV ZCD=%s DCM=%s SwCnt=%lu\n",
           state_str,
           (unsigned)boost.duty,
           (unsigned)boost.vin_mv,
           (unsigned)boost.vout_mv,
           boost.zcd_detected ? "YES" : "NO",
           boost.dcm_mode ? "YES" : "NO",
           (unsigned long)boost.switch_count);
}

/* ============================================================
 * main
 * ============================================================ */
int main(void)
{
    int i;

    printf("=== Boost Converter DCM Control Simulation ===\n");

    Boost_Init();

    for (i = 0; i < 20; i++) {
        /* 模拟 ADC 输入变化 */
        REG_ADC_DATA = (uint16_t)(1000U + (uint16_t)(i * 100U));

        /* 模拟过零检测信号周期性变化 */
        if ((i % 3) == 0) {
            REG_GPIO_ZCD |= ZCD_PIN_MASK;
        } else {
            REG_GPIO_ZCD &= ~ZCD_PIN_MASK;
        }

        Boost_ControlStep();
        Boost_PrintStatus();
    }

    printf("=== Simulation End ===\n");

    return 0;
}
