```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 模拟定时器寄存器 */
typedef struct {
    volatile uint32_t CR1;      /* 控制寄存器1 */
    volatile uint32_t ARR;      /* 自动重装载寄存器 */
    volatile uint32_t CCR1;     /* 捕获/比较寄存器1 (高侧) */
    volatile uint32_t CCR2;     /* 捕获/比较寄存器2 (低侧) */
    volatile uint32_t CNT;      /* 计数器 */
    volatile uint32_t SR;       /* 状态寄存器 */
} TIM_TypeDef;

/* 模拟 GPIO 寄存器 */
typedef struct {
    volatile uint32_t MODER;
    volatile uint32_t ODR;
    volatile uint32_t IDR;
} GPIO_TypeDef;

/* 模拟 ADC 寄存器 */
typedef struct {
    volatile uint32_t CR2;
    volatile uint32_t SR;
    volatile uint32_t DR;
} ADC_TypeDef;

/* 实例化 mock 外设 */
static TIM_TypeDef TIM1_mock;
static GPIO_TypeDef GPIOA_mock;
static ADC_TypeDef ADC1_mock;

#define TIM1        (&TIM1_mock)
#define GPIOA       (&GPIOA_mock)
#define ADC1        (&ADC1_mock)

/* 寄存器位定义 */
#define TIM_CR1_CEN         (1U << 0)
#define TIM_SR_UIF          (1U << 0)
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_SWSTART     (1U << 30)
#define ADC_SR_EOC          (1U << 1)

/* 驱动引脚定义 */
#define GPIO_PIN_HIGH_SIDE  0U
#define GPIO_PIN_LOW_SIDE   1U

/* ================= 系统参数 ================= */
#define PWM_PERIOD          1000U   /* PWM 周期计数值 */
#define DEAD_TIME_NS        200U    /* 死区时间 200ns */
#define DEAD_TIME_TICKS     20U     /* 死区时间对应计数值 (假设 100MHz 时钟) */
#define ADC_REF_VOLTAGE     3.3f    /* ADC 参考电压 */
#define ADC_RESOLUTION      4096.0f /* 12位 ADC */
#define BODY_DIODE_THRESH   0.05f   /* 体二极管导通检测阈值 (伏特) */
#define MIN_DUTY            0.05f   /* 最小占空比 */
#define MAX_DUTY            0.95f   /* 最大占空比 */

/* ================= 全局变量 ================= */
typedef struct {
    float duty_cycle;           /* 目标占空比 */
    float output_voltage;       /* 输出电压 */
    float input_voltage;        /* 输入电压 */
    float inductor_current;     /* 电感电流 */
    bool  body_diode_active;    /* 体二极管导通标志 */
    uint32_t high_side_ccr;     /* 高侧比较值 */
    uint32_t low_side_ccr;      /* 低侧比较值 */
} BuckController_t;

static BuckController_t buck;

/* ================= 硬件初始化 ================= */
static void Hardware_Init(void)
{
    /* 使能定时器时钟 (mock) */
    TIM1->CR1 = 0;
    TIM1->ARR = PWM_PERIOD;
    TIM1->CCR1 = 0;
    TIM1->CCR2 = 0;
    TIM1->CNT = 0;
    TIM1->SR = 0;

    /* 配置 GPIO 为复用推挽输出 (mock) */
    GPIOA->MODER |= (1U << (GPIO_PIN_HIGH_SIDE * 2));
    GPIOA->MODER |= (1U << (GPIO_PIN_LOW_SIDE * 2));
    GPIOA->ODR = 0;

    /* 使能 ADC (mock) */
    ADC1->CR2 |= ADC_CR2_ADON;
}

/* ================= 启动 PWM ================= */
static void PWM_Start(void)
{
    TIM1->CR1 |= TIM_CR1_CEN;
}

/* ================= 停止 PWM ================= */
static void PWM_Stop(void)
{
    TIM1->CR1 &= ~TIM_CR1_CEN;
    GPIOA->ODR &= ~((1U << GPIO_PIN_HIGH_SIDE) | (1U << GPIO_PIN_LOW_SIDE));
}

/* ================= 设置 PWM 占空比 (带死区) ================= */
static void PWM_SetDutyCycle(float duty)
{
    uint32_t ccr_val;

    /* 占空比限幅 */
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    buck.duty_cycle = duty;

    /* 计算比较值 */
    ccr_val = (uint32_t)(duty * (float)PWM_PERIOD);

    /* 高侧和低侧互补输出，插入死区 */
    if (ccr_val > DEAD_TIME_TICKS) {
        buck.high_side_ccr = ccr_val - DEAD_TIME_TICKS;
    } else {
        buck.high_side_ccr = 0;
    }

    if (ccr_val < (PWM_PERIOD - DEAD_TIME_TICKS)) {
        buck.low_side_ccr = ccr_val + DEAD_TIME_TICKS;
    } else {
        buck.low_side_ccr = PWM_PERIOD;
    }

    /* 写入寄存器 */
    TIM1->CCR1 = buck.high_side_ccr;
    TIM1->CCR2 = buck.low_side_ccr;
}

/* ================= 读取 ADC 值 ================= */
static uint32_t ADC_ReadChannel(uint32_t channel)
{
    (void)channel;
    /* 启动转换 */
    ADC1->CR2 |= ADC_CR2_SWSTART;

    /* 等待转换完成 (mock 直接返回) */
    ADC1->SR |= ADC_SR_EOC;

    return ADC1->DR;
}

/* ================= 读取输出电压 ================= */
static float Read_OutputVoltage(void)
{
    uint32_t adc_val = ADC_ReadChannel(0);
    return ((float)adc_val / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
}

/* ================= 读取电感电流 ================= */
static float Read_InductorCurrent(void)
{
    uint32_t adc_val = ADC_ReadChannel(1);
    /* 假设 1V 对应 1A */
    return ((float)adc_val / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
}

/* ================= 体二极管导通检测 ================= */
static bool Detect_BodyDiodeConduction(void)
{
    float vds_low_side;

    /* 读取低侧 MOSFET 的漏源电压 (通过 ADC 采样) */
    vds_low_side = Read_OutputVoltage();

    /* 如果低侧 MOSFET 体二极管导通，VDS 会出现负压或异常 */
    if (vds_low_side < -BODY_DIODE_THRESH) {
        return true;
    }

    return false;
}

/* ================= 体二极管导通抑制策略 ================= */
static void Suppress_BodyDiodeConduction(void)
{
    bool body_diode = Detect_BodyDiodeConduction();

    buck.body_diode_active = body_diode;

    if (body_diode) {
        /*
         * 体二极管导通抑制策略：
         * 1. 增加低侧 MOSFET 的导通时间 (减小死区)
         * 2. 或者提前关断高侧 MOSFET
         * 3. 或者调整占空比
         *
         * 这里采用动态调整死区时间的策略：
         * 当检测到体二极管导通时，减小死区时间
         */

        /* 动态减小死区时间 (最小为 0) */
        if (buck.high_side_ccr > 0) {
            buck.high_side_ccr -= 1;
        }
        if (buck.low_side_ccr < PWM_PERIOD) {
            buck.low_side_ccr += 1;
        }

        /* 更新寄存器 */
        TIM1->CCR1 = buck.high_side_ccr;
        TIM1->CCR2 = buck.low_side_ccr;

        printf("[抑制] 检测到体二极管导通! 调整死区: H=%u, L=%u\n",
               buck.high_side_ccr, buck.low_side_ccr);
    }
}

/* ================= 电压闭环控制 (简单 PI) ================= */
static void Voltage_Control_Loop(float v_ref)
{
    static float integral = 0.0f;
    float error;
    float kp = 0.1f;
    float ki = 0.01f;
    float duty;

    /* 读取输出电压 */
    buck.output_voltage = Read_OutputVoltage();

    /* 计算误差 */
    error = v_ref - buck.output_voltage;

    /* PI 控制 */
    integral += error * ki;
    duty = kp * error + integral;

    /* 限幅 */
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    /* 设置占空比 */
    PWM_SetDutyCycle(duty);
}

/* ================= 主控制循环 ================= */
static void Buck_Control_Loop(void)
{
    float v_ref = 5.0f;  /* 目标输出电压 5V */

    /* 电压闭环控制 */
    Voltage_Control_Loop(v_ref);

    /* 体二极管导通抑制 */
    Suppress_BodyDiodeConduction();

    /* 读取电感电流 (用于监控) */
    buck.inductor_current = Read_InductorCurrent();
}

/* ================= 打印系统状态 ================= */
static void Print_System_Status(void)
{
    printf("========== Buck 变换器状态 ==========\n");
    printf("输入电压:     %.2f V\n", buck.input_voltage);
    printf("输出电压:     %.2f V\n", buck.output_voltage);
    printf("电感电流:     %.2f A\n", buck.inductor_current);
    printf("占空比:       %.2f %%\n", buck.duty_cycle * 100.0f);
    printf("高侧 CCR:     %u\n", buck.high_side_ccr);
