```c
#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define REG_ADC_BASE        0x40012000U
#define REG_PWM_BASE        0x40013000U
#define REG_GPIO_BASE       0x40020000U

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t SR;
    volatile uint32_t DR;
} ADC_TypeDef;

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t ARR;
    volatile uint32_t CCR1;
    volatile uint32_t CCR2;
    volatile uint32_t CCR3;
    volatile uint32_t CCR4;
} PWM_TypeDef;

typedef struct {
    volatile uint32_t MODER;
    volatile uint32_t ODR;
} GPIO_TypeDef;

/* 使用静态内存模拟寄存器，避免访问非法地址 */
static ADC_TypeDef  g_adc1;
static PWM_TypeDef  g_pwm1;
static GPIO_TypeDef g_gpioa;

#define ADC1                (&g_adc1)
#define PWM1                (&g_pwm1)
#define GPIOA               (&g_gpioa)

#define ADC_CR_START        (1U << 0)
#define ADC_SR_EOC          (1U << 0)
#define PWM_CR_EN           (1U << 0)
#define PWM_CR_ALIGN        (1U << 1)

/* ================= 系统参数 ================= */
#define NUM_MODULES         4U
#define VREF_MV             3300U
#define ADC_FULL_SCALE      4095U
#define V_TARGET_MV         400000U
#define V_BALANCE_TOL_MV    2000U
#define KP_DEFAULT          0.35f
#define KI_DEFAULT          0.08f
#define DUTY_MIN            0.05f
#define DUTY_MAX            0.95f
#define PWM_PERIOD          1000U

/* ================= 数据结构 ================= */
typedef struct {
    uint32_t adc_raw;
    uint32_t voltage_mv;
    float    duty;
    float    duty_cmd;
    float    integral;
    float    error;
    float    kp;
    float    ki;
} ModuleCtrl_t;

typedef struct {
    ModuleCtrl_t mod[NUM_MODULES];
    uint32_t     v_avg_mv;
    uint32_t     v_max_mv;
    uint32_t     v_min_mv;
    uint32_t     v_spread_mv;
    uint32_t     cycle_cnt;
    uint8_t      balance_enable;
} Balancer_t;

/* ================= 硬件读取（Mock） ================= */
static uint32_t ADC_ReadChannel(uint8_t ch)
{
    /* 模拟各模块电压采样：400V 附近，带轻微偏差 */
    static const uint32_t mock_mv[NUM_MODULES] = {
        402500U, 398200U, 401100U, 399600U
    };
    uint32_t mv;
    uint32_t raw;

    if (ch >= NUM_MODULES) {
        ch = 0;
    }
    mv = mock_mv[ch];
    raw = (mv * ADC_FULL_SCALE) / VREF_MV;
    if (raw > ADC_FULL_SCALE) raw = ADC_FULL_SCALE;
    return raw;
}

static void PWM_SetDuty(uint8_t ch, float duty)
{
    uint32_t ccr;
    if (duty < DUTY_MIN) duty = DUTY_MIN;
    if (duty > DUTY_MAX) duty = DUTY_MAX;
    ccr = (uint32_t)(duty * (float)PWM_PERIOD);
    switch (ch) {
        case 0: PWM1->CCR1 = ccr; break;
        case 1: PWM1->CCR2 = ccr; break;
        case 2: PWM1->CCR3 = ccr; break;
        case 3: PWM1->CCR4 = ccr; break;
        default: break;
    }
}

static void PWM_Init(void)
{
    PWM1->CR  = PWM_CR_EN | PWM_CR_ALIGN;
    PWM1->ARR = PWM_PERIOD;
    PWM1->CCR1 = PWM_PERIOD / 2;
    PWM1->CCR2 = PWM_PERIOD / 2;
    PWM1->CCR3 = PWM_PERIOD / 2;
    PWM1->CCR4 = PWM_PERIOD / 2;
}

/* ================= 主动均压算法 ================= */
static void Balancer_Init(Balancer_t *b)
{
    uint8_t i;
    for (i = 0; i < NUM_MODULES; i++) {
        b->mod[i].adc_raw    = 0;
        b->mod[i].voltage_mv = 0;
        b->mod[i].duty       = 0.5f;
        b->mod[i].duty_cmd   = 0.5f;
        b->mod[i].integral   = 0.0f;
        b->mod[i].error      = 0.0f;
        b->mod[i].kp         = KP_DEFAULT;
        b->mod[i].ki         = KI_DEFAULT;
    }
    b->v_avg_mv       = 0;
    b->v_max_mv       = 0;
    b->v_min_mv       = 0;
    b->v_spread_mv    = 0;
    b->cycle_cnt      = 0;
    b->balance_enable = 1;
}

static void Balancer_SampleVoltages(Balancer_t *b)
{
    uint8_t i;
    for (i = 0; i < NUM_MODULES; i++) {
        b->mod[i].adc_raw = ADC_ReadChannel(i);
        b->mod[i].voltage_mv =
            (b->mod[i].adc_raw * VREF_MV) / ADC_FULL_SCALE;
    }
}

static void Balancer_ComputeStats(Balancer_t *b)
{
    uint8_t i;
    uint32_t sum = 0;
    uint32_t vmax = 0;
    uint32_t vmin = 0xFFFFFFFFU;

    for (i = 0; i < NUM_MODULES; i++) {
        uint32_t v = b->mod[i].voltage_mv;
        sum += v;
        if (v > vmax) vmax = v;
        if (v < vmin) vmin = v;
    }
    b->v_avg_mv    = sum / NUM_MODULES;
    b->v_max_mv    = vmax;
    b->v_min_mv    = vmin;
    b->v_spread_mv = vmax - vmin;
}

static void Balancer_UpdateDuty(Balancer_t *b)
{
    uint8_t i;
    float v_avg;

    if (b->v_avg_mv == 0) {
        return;
    }
    v_avg = (float)b->v_avg_mv;

    for (i = 0; i < NUM_MODULES; i++) {
        float v_meas = (float)b->mod[i].voltage_mv;
        float err;
        float p_term;
        float i_term;
        float duty_new;

        /* 误差：本模块电压高于平均值 -> 正误差 -> 应减小占空比 */
        err = (v_meas - v_avg) / v_avg;

        b->mod[i].error = err;

        p_term = b->mod[i].kp * err;

        b->mod[i].integral += b->mod[i].ki * err;
        /* 积分限幅 */
        if (b->mod[i].integral >  0.30f) b->mod[i].integral =  0.30f;
        if (b->mod[i].integral < -0.30f) b->mod[i].integral = -0.30f;
        i_term = b->mod[i].integral;

        /* 基准占空比 0.5，叠加均压修正量 */
        duty_new = 0.5f - (p_term + i_term);

        if (duty_new < DUTY_MIN) duty_new = DUTY_MIN;
        if (duty_new > DUTY_MAX) duty_new = DUTY_MAX;

        b->mod[i].duty_cmd = duty_new;
    }
}

static void Balancer_ApplyDuty(Balancer_t *b)
{
    uint8_t i;
    for (i = 0; i < NUM_MODULES; i++) {
        b->mod[i].duty = b->mod[i].duty_cmd;
        PWM_SetDuty(i, b->mod[i].duty);
    }
}

static void Balancer_RunCycle(Balancer_t *b)
{
    Balancer_SampleVoltages(b);
    Balancer_ComputeStats(b);

    if (b->balance_enable) {
        if (b->v_spread_mv > V_BALANCE_TOL_MV) {
            Balancer_UpdateDuty(b);
        } else {
            /* 已均衡，缓慢回归基准 */
            uint8_t i;
            for (i = 0; i < NUM_MODULES; i++) {
                b->mod[i].duty_cmd += (0.5f - b->mod[i].duty_cmd) * 0.05f;
            }
        }
    }
    Balancer_ApplyDuty(b);
    b->cycle_cnt++;
}

/* ================= 打印 ================= */
static void Balancer_PrintStatus(const Balancer_t *b)
{
    uint8_t i;
    printf("========== Cycle %u ==========\n", b->cycle_cnt);
    printf("Vavg=%u mV  Vmax=%u mV  Vmin=%u mV  Spread=%u mV\n",
           b->v_avg_mv, b->v_max_mv, b->v_min_mv, b->v_spread_mv);
    for (i = 0; i < NUM_MODULES; i++) {
        printf("  Module[%u]: V=%u mV  Err=%+.4f  Duty=%.4f  Int=%+.4f\n",
               i,
               b->mod[i].voltage_mv,
               b->mod[i].error,
               b->mod[i].duty,
               b->mod[i].integral);
    }
    printf("\n");
}

/* ================= 主函数 ================= */
int main(void)
{
    Balancer_t balancer;
    uint32_t   cycle;

    printf("High-Voltage DC/DC Series-Connected Active Voltage Balancing\n");
    printf("Target: %u mV, Tolerance: %u mV, Modules: %u\n\n",
           V_TARGET_MV, V_BALANCE_TOL_MV, NUM_MODULES);

    PWM_Init();
    Balancer_Init(&balancer);

    for (cycle = 0; cycle < 10; cycle++) {
        Balancer_RunCycle(&balancer);
        Balancer_PrintStatus(&balancer);
    }

    printf("Balancing algorithm finished.\n");
    return 0;
}
