#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
static volatile uint32_t g_adc_regs[4];
static volatile uint32_t g_pwm_regs[5];
static volatile uint32_t g_tim_regs[3];

#define ADC_DR              (g_adc_regs[0])
#define ADC_CR1             (g_adc_regs[1])
#define ADC_CR2             (g_adc_regs[2])
#define ADC_SR              (g_adc_regs[3])

#define PWM_CR              (g_pwm_regs[0])
#define PWM_ARR             (g_pwm_regs[1])
#define PWM_CCR1            (g_pwm_regs[2])
#define PWM_CCR2            (g_pwm_regs[3])
#define PWM_SR              (g_pwm_regs[4])

#define TIM_CR1             (g_tim_regs[0])
#define TIM_SR              (g_tim_regs[1])
#define TIM_CNT             (g_tim_regs[2])

/* ==================== 系统参数定义 ==================== */
#define PWM_FREQ_HZ         200000.0f
#define PWM_PERIOD_TICKS    1000U
#define ADC_VREF_MV         3300.0f
#define ADC_RESOLUTION      4096.0f
#define VOUT_TARGET_MV      28000.0f
#define VIN_NOMINAL_MV      27000.0f
#define IOUT_MAX_MA         5000.0f

/* 多级滤波参数 */
#define FILTER_STAGE1_ALPHA 0.35f
#define FILTER_STAGE2_ALPHA 0.20f
#define FILTER_STAGE3_ALPHA 0.10f
#define FILTER_STAGE4_ALPHA 0.05f

/* 控制环参数 */
#define KP_VOLTAGE          0.85f
#define KI_VOLTAGE          0.012f
#define KD_VOLTAGE          0.003f
#define KP_CURRENT          0.45f
#define KI_CURRENT          0.008f

/* 纹波抑制参数 */
#define RIPPLE_COMP_GAIN    0.65f

/* ==================== 数据结构定义 ==================== */
typedef struct {
    float alpha;
    float prev_output;
    float prev_input;
} IIRFilter_t;

typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
} PIDController_t;

typedef struct {
    float vout_mv;
    float vin_mv;
    float iout_ma;
    float duty_cycle;
    float ripple_est;
    float ripple_comp;
} PowerState_t;

typedef struct {
    IIRFilter_t stage1;
    IIRFilter_t stage2;
    IIRFilter_t stage3;
    IIRFilter_t stage4;
    float filtered_value;
} MultiStageFilter_t;

/* ==================== 函数声明 ==================== */
static void IIRFilter_Init(IIRFilter_t *f, float alpha);
static float IIRFilter_Update(IIRFilter_t *f, float input);
static void MultiStageFilter_Init(MultiStageFilter_t *mf);
static float MultiStageFilter_Update(MultiStageFilter_t *mf, float input);
static void PID_Init(PIDController_t *pid, float kp, float ki, float kd,
                     float out_min, float out_max);
static float PID_Update(PIDController_t *pid, float setpoint, float feedback,
                        float dt);
static float RippleEstimator(float *history, uint32_t len, float current);
static float RippleCompensator(float ripple_est, float duty);
static void ADC_ReadRaw(uint32_t *vout_raw, uint32_t *vin_raw, uint32_t *iout_raw);
static void PWM_SetDuty(float duty);
static void System_Init(void);
static void Control_Loop(void);

/* ==================== 全局变量 ==================== */
static MultiStageFilter_t g_vout_filter;
static MultiStageFilter_t g_vin_filter;
static MultiStageFilter_t g_iout_filter;
static PIDController_t g_voltage_pid;
static PIDController_t g_current_pid;
static PowerState_t g_state;
static float g_ripple_history[16];
static uint32_t g_ripple_idx = 0;
static float g_dt = 1.0f / PWM_FREQ_HZ;

/* ==================== IIR 滤波器实现 ==================== */
static void IIRFilter_Init(IIRFilter_t *f, float alpha)
{
    f->alpha = alpha;
    f->prev_output = 0.0f;
    f->prev_input = 0.0f;
}

static float IIRFilter_Update(IIRFilter_t *f, float input)
{
    float output = f->alpha * input + (1.0f - f->alpha) * f->prev_output;
    f->prev_input = input;
    f->prev_output = output;
    return output;
}

/* ==================== 多级滤波器实现 ==================== */
static void MultiStageFilter_Init(MultiStageFilter_t *mf)
{
    IIRFilter_Init(&mf->stage1, FILTER_STAGE1_ALPHA);
    IIRFilter_Init(&mf->stage2, FILTER_STAGE2_ALPHA);
    IIRFilter_Init(&mf->stage3, FILTER_STAGE3_ALPHA);
    IIRFilter_Init(&mf->stage4, FILTER_STAGE4_ALPHA);
    mf->filtered_value = 0.0f;
}

static float MultiStageFilter_Update(MultiStageFilter_t *mf, float input)
{
    float s1 = IIRFilter_Update(&mf->stage1, input);
    float s2 = IIRFilter_Update(&mf->stage2, s1);
    float s3 = IIRFilter_Update(&mf->stage3, s2);
    float s4 = IIRFilter_Update(&mf->stage4, s3);
    mf->filtered_value = s4;
    return s4;
}

/* ==================== PID 控制器实现 ==================== */
static void PID_Init(PIDController_t *pid, float kp, float ki, float kd,
                     float out_min, float out_max)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
}

static float PID_Update(PIDController_t *pid, float setpoint, float feedback,
                        float dt)
{
    float error = setpoint - feedback;
    float derivative;
    float output;

    pid->integral += error * dt;
    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;

    if (output > pid->output_max) {
        output = pid->output_max;
        pid->integral -= error * dt;
    } else if (output < pid->output_min) {
        output = pid->output_min;
        pid->integral -= error * dt;
    }

    return output;
}

/* ==================== 纹波估计与补偿 ==================== */
static float RippleEstimator(float *history, uint32_t len, float current)
{
    float mean = 0.0f;
    float variance = 0.0f;
    uint32_t i;

    if (len == 0) return 0.0f;

    history[g_ripple_idx] = current;
    g_ripple_idx = (g_ripple_idx + 1) % len;

    for (i = 0; i < len; i++) {
        mean += history[i];
    }
    mean /= (float)len;

    for (i = 0; i < len; i++) {
        float diff = history[i] - mean;
        variance += diff * diff;
    }
    variance /= (float)len;

    return sqrtf(variance);
}

static float RippleCompensator(float ripple_est, float duty)
{
    float comp = 0.0f;
    if (ripple_est > 0.0f) {
        comp = RIPPLE_COMP_GAIN * ripple_est * (1.0f - duty);
    }
    return comp;
}

/* ==================== 硬件抽象层 ==================== */
static void ADC_ReadRaw(uint32_t *vout_raw, uint32_t *vin_raw, uint32_t *iout_raw)
{
    static uint32_t counter = 0;
    float noise = sinf((float)counter * 0.1f) * 15.0f;
    counter++;

    *vout_raw = (uint32_t)((VOUT_TARGET_MV / ADC_VREF_MV) * ADC_RESOLUTION + noise);
    *vin_raw  = (uint32_t)((VIN_NOMINAL_MV / ADC_VREF_MV) * ADC_RESOLUTION);
    *iout_raw = (uint32_t)((2500.0f / ADC_VREF_MV) * ADC_RESOLUTION);
}

static void PWM_SetDuty(float duty)
{
    uint32_t ccr;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;

    ccr = (uint32_t)(duty * (float)PWM_PERIOD_TICKS);
    PWM_ARR = PWM_PERIOD_TICKS;
    PWM_CCR1 = ccr;
    PWM_CCR2 = PWM_PERIOD_TICKS - ccr;
    PWM_CR |= 0x01;
}

/* ==================== 系统初始化 ==================== */
static void System_Init(void)
{
    uint32_t i;

    MultiStageFilter_Init(&g_vout_filter);
    MultiStageFilter_Init(&g_vin_filter);
    MultiStageFilter_Init(&g_iout_filter);

    PID_Init(&g_voltage_pid, KP_VOLTAGE, KI_VOLTAGE, KD_VOLTAGE, 0.0f, 0.95f);
    PID_Init(&g_current_pid, KP_CURRENT, KI_CURRENT, 0.0f, 0.0f, 0.95f);

    g_state.vout_mv = 0.0f;
    g_state.vin_mv = 0.0f;
    g_state.iout_ma = 0.0f;
    g_state.duty_cycle = 0.5f;
    g_state.ripple_est = 0.0f;
    g_state.ripple_comp = 0.0f;

    for (i = 0; i < 16; i++) {
        g_ripple_history[i] = 0.0f;
    }

    ADC_CR1 = 0x01;
    ADC_CR2 = 0x01;
    TIM_CR1 = 0x01;
    PWM_CR = 0x00;

    printf("[INIT] Aviation DC/DC Converter - Low Ripple Control\n");
    printf("[INIT] PWM Freq: %.0f Hz, Period: %u ticks\n",
           PWM_FREQ_HZ, PWM_PERIOD_TICKS);
    printf("[INIT] Target Vout: %.0f mV\n", VOUT_TARGET_MV);
    printf("[INIT] Multi-stage filter: 4 stages\n");
    printf("[INIT] Filter alphas: %.2f, %.2f, %.2f, %.2f\n",
           FILTER_STAGE1_ALPHA, FILTER_STAGE2_ALPHA,
           FILTER_STAGE3_ALPHA, FILTER_STAGE4_ALPHA);
}

/* ==================== 控制主循环 ==================== */
static void Control_Loop(void)
{
    uint32_t vout_raw, vin_raw, iout_raw;
    float vout_mv, vin_mv, iout_ma;
    float vout_filtered, vin_filtered, iout_filtered;
    float duty_voltage;
    float duty_current;
    float duty_final;
    float ripple_est;
    float ripple_comp;

    /* 1. 读取 ADC 原始值 */
    ADC_ReadRaw(&vout_raw, &vin_raw, &iout_raw);

    /* 2. 转换为物理量 */
    vout_mv = ((float)vout_raw / ADC_RESOLUTION) * ADC_VREF_MV;
    vin_mv  = ((float)vin_raw / ADC_RESOLUTION) * ADC_VREF_MV;
    iout_ma = ((float)iout_raw / ADC_RESOLUTION) * ADC_VREF_MV;

    /* 3. 多级滤波 */
    vout_filtered = MultiStageFilter_Update(&g_vout_filter, vout_mv);
    vin_filtered  = MultiStageFilter_Update(&g_vin_filter, vin_mv);
    iout_filtered = MultiStageFilter_Update(&g_iout_filter, iout_ma);

    g_state.vout_mv = vout_filtered;
    g_state.vin_mv = vin_filtered;
    g_state.iout_ma = iout_filtered;

    /* 4. 纹波估计 */
    ripple_est = RippleEstimator(g_ripple_history, 16, vout_filtered);
    g_state.ripple_est = ripple_est;

    /* 5. 电压环 PID */
    duty_voltage = PID_Update(&g_voltage_pid, VOUT_TARGET_MV,
                              vout_filtered, g_dt);

    /* 6. 电流环 PID (内环) */
    duty_current = PID_Update(&g_current_pid, IOUT_MAX_MA * 0.8f,
                              iout_filtered, g_dt);

    /* 7. 纹波补偿 */
    ripple_comp = RippleCompensator(ripple_est, g_state.duty_cycle);
    g_state.ripple_comp = ripple_comp;

    /* 8. 综合输出 */
    duty_final = duty_voltage + duty_current * 0.3f + ripple_comp;

    if (duty_final < 0.0f) duty_final = 0.0f;
    if (duty_final > 0.95f) duty_final = 0.95f;

    g_state.duty_cycle = duty_final;

    /* 9. 设置 PWM */
    PWM_SetDuty(duty_final);

    /* 10. 打印调试信息 */
    printf("[CTRL] Vout=%.1fmV Vin=%.1fmV Iout=%.1fmA "
           "Ripple=%.2fmV Comp=%.4f Duty=%.4f\n",
           vout_filtered, vin_filtered, iout_filtered,
           ripple_est, ripple_comp, duty_final);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t loop_count;

    System_Init();

    printf("\n===== Starting Control Loop =====\n\n");

    for (loop_count = 0; loop_count < 20; loop_count++) {
        Control_Loop();
    }

    printf("\n===== Control Loop Finished =====\n");
    printf("Final State:\n");
    printf("  Vout: %.1f mV (Target: %.1f mV)\n",
           g_state.vout_mv, VOUT_TARGET_MV);
    printf("  Vin:  %.1f mV\n", g_state.vin_mv);
    printf("  Iout: %.1f mA\n", g_state.iout_ma);
    printf("  Duty: %.4f\n", g_state.duty_cycle);
    printf("  Ripple Est: %.2f mV\n", g_state.ripple_est);
    printf("  Ripple Comp: %.4f\n", g_state.ripple_comp);

    return 0;
}
