```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器（使用普通变量，避免非法地址访问） ================= */
static volatile uint16_t g_reg_adc_data      = 0;
static volatile uint32_t g_reg_adc_ctrl      = 0;
static volatile uint16_t g_reg_pwm_duty      = 0;
static volatile uint16_t g_reg_opto_feedback = 0;
static volatile uint32_t g_reg_gpio_status   = 0;

#define REG_ADC_DATA        (g_reg_adc_data)
#define REG_ADC_CTRL        (g_reg_adc_ctrl)
#define REG_PWM_DUTY        (g_reg_pwm_duty)
#define REG_OPTO_FEEDBACK   (g_reg_opto_feedback)
#define REG_GPIO_STATUS     (g_reg_gpio_status)

#define ADC_CTRL_START      (1U << 0)
#define ADC_CTRL_CH_SEL(x)  (((x) & 0x7U) << 1)
#define ADC_CTRL_ENABLE     (1U << 4)

#define OPTO_FAULT_BIT      (1U << 0)
#define OPTO_READY_BIT      (1U << 1)

/* ================= 系统参数 ================= */
#define VREF_MV             3300.0f
#define ADC_FULL_SCALE      4095.0f
#define DIVIDER_RATIO       11.0f
#define OPTO_CTR_NOMINAL    0.8f
#define OPTO_CTR_MIN        0.4f
#define OPTO_CTR_MAX        1.2f
#define VOUT_TARGET_MV      5000.0f
#define VOUT_OVP_MV         6000.0f
#define VOUT_UVP_MV         4000.0f
#define PWM_DUTY_MIN        100U
#define PWM_DUTY_MAX        900U
#define PWM_DUTY_INIT       500U
#define LOOP_GAIN_KP        0.35f
#define LOOP_GAIN_KI        0.08f
#define INTEGRAL_LIMIT      300.0f
#define FILTER_ALPHA        0.25f
#define STARTUP_DELAY_MS    50U
#define FAULT_DEBOUNCE_CNT  5U

/* ================= 状态机 ================= */
typedef enum {
    STATE_INIT = 0,
    STATE_STARTUP,
    STATE_RUN,
    STATE_FAULT_OVP,
    STATE_FAULT_UVP,
    STATE_FAULT_OPTO,
    STATE_SHUTDOWN
} sys_state_t;

/* ================= 控制器结构体 ================= */
typedef struct {
    float    vout_filtered_mv;
    float    vout_raw_mv;
    float    integral;
    float    duty;
    uint16_t duty_reg;
    uint16_t fault_counter;
    uint32_t startup_timer;
    sys_state_t state;
    bool     opto_ready;
    bool     opto_fault;
} dcdc_ctrl_t;

static dcdc_ctrl_t g_ctrl;

/* ================= 硬件抽象层 ================= */
static void hw_adc_init(void)
{
    REG_ADC_CTRL = ADC_CTRL_ENABLE | ADC_CTRL_CH_SEL(0);
}

static uint16_t hw_adc_read_raw(void)
{
    REG_ADC_CTRL |= ADC_CTRL_START;
    /* 模拟转换完成，返回固定值用于测试 */
    return (uint16_t)(VOUT_TARGET_MV / VREF_MV * ADC_FULL_SCALE / DIVIDER_RATIO);
}

static void hw_pwm_set_duty(uint16_t duty)
{
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    REG_PWM_DUTY = duty;
}

static bool hw_opto_ready(void)
{
    return (REG_GPIO_STATUS & OPTO_READY_BIT) != 0U;
}

static bool hw_opto_fault(void)
{
    return (REG_GPIO_STATUS & OPTO_FAULT_BIT) != 0U;
}

static void hw_pwm_disable(void)
{
    REG_PWM_DUTY = 0U;
}

/* ================= 信号处理 ================= */
static float adc_to_mv(uint16_t raw)
{
    return ((float)raw / ADC_FULL_SCALE) * VREF_MV * DIVIDER_RATIO;
}

static float low_pass_filter(float new_val, float old_val)
{
    return old_val + FILTER_ALPHA * (new_val - old_val);
}

/* ================= 光耦反馈监测 ================= */
static bool opto_feedback_check(void)
{
    uint16_t opto_raw = REG_OPTO_FEEDBACK;
    float opto_ratio = (float)opto_raw / ADC_FULL_SCALE;

    if (opto_ratio < OPTO_CTR_MIN || opto_ratio > OPTO_CTR_MAX) {
        return false;
    }
    return true;
}

/* ================= 控制算法 ================= */
static void control_loop(void)
{
    uint16_t adc_raw = hw_adc_read_raw();
    float vout_mv = adc_to_mv(adc_raw);

    g_ctrl.vout_raw_mv = vout_mv;
    g_ctrl.vout_filtered_mv = low_pass_filter(vout_mv, g_ctrl.vout_filtered_mv);

    float error = VOUT_TARGET_MV - g_ctrl.vout_filtered_mv;

    g_ctrl.integral += error * LOOP_GAIN_KI;
    if (g_ctrl.integral > INTEGRAL_LIMIT)  g_ctrl.integral = INTEGRAL_LIMIT;
    if (g_ctrl.integral < -INTEGRAL_LIMIT) g_ctrl.integral = -INTEGRAL_LIMIT;

    float duty_f = (float)PWM_DUTY_INIT + error * LOOP_GAIN_KP + g_ctrl.integral;

    if (duty_f < (float)PWM_DUTY_MIN) duty_f = (float)PWM_DUTY_MIN;
    if (duty_f > (float)PWM_DUTY_MAX) duty_f = (float)PWM_DUTY_MAX;

    g_ctrl.duty = duty_f;
    g_ctrl.duty_reg = (uint16_t)duty_f;
    hw_pwm_set_duty(g_ctrl.duty_reg);
}

/* ================= 保护逻辑 ================= */
static void protection_check(void)
{
    if (g_ctrl.vout_filtered_mv > VOUT_OVP_MV) {
        g_ctrl.fault_counter++;
        if (g_ctrl.fault_counter >= FAULT_DEBOUNCE_CNT) {
            g_ctrl.state = STATE_FAULT_OVP;
            hw_pwm_disable();
        }
    } else if (g_ctrl.vout_filtered_mv < VOUT_UVP_MV &&
               g_ctrl.state == STATE_RUN) {
        g_ctrl.fault_counter++;
        if (g_ctrl.fault_counter >= FAULT_DEBOUNCE_CNT) {
            g_ctrl.state = STATE_FAULT_UVP;
            hw_pwm_disable();
        }
    } else {
        g_ctrl.fault_counter = 0;
    }

    if (!opto_feedback_check() || hw_opto_fault()) {
        g_ctrl.opto_fault = true;
        g_ctrl.state = STATE_FAULT_OPTO;
        hw_pwm_disable();
    }
}

/* ================= 状态机 ================= */
static void state_machine_run(void)
{
    switch (g_ctrl.state) {
    case STATE_INIT:
        hw_adc_init();
        hw_pwm_set_duty(PWM_DUTY_INIT);
        g_ctrl.vout_filtered_mv = 0.0f;
        g_ctrl.integral = 0.0f;
        g_ctrl.fault_counter = 0;
        g_ctrl.startup_timer = 0;
        g_ctrl.opto_ready = false;
        g_ctrl.opto_fault = false;
        g_ctrl.state = STATE_STARTUP;
        printf("[STATE] INIT -> STARTUP\n");
        break;

    case STATE_STARTUP:
        g_ctrl.startup_timer++;
        if (hw_opto_ready()) {
            g_ctrl.opto_ready = true;
        }
        if (g_ctrl.startup_timer >= STARTUP_DELAY_MS && g_ctrl.opto_ready) {
            g_ctrl.state = STATE_RUN;
            printf("[STATE] STARTUP -> RUN\n");
        } else if (g_ctrl.startup_timer >= STARTUP_DELAY_MS * 4U) {
            g_ctrl.state = STATE_FAULT_OPTO;
            hw_pwm_disable();
            printf("[STATE] STARTUP -> FAULT_OPTO (timeout)\n");
        }
        break;

    case STATE_RUN:
        control_loop();
        protection_check();
        break;

    case STATE_FAULT_OVP:
        printf("[FAULT] OVP detected, Vout=%.1f mV\n", g_ctrl.vout_filtered_mv);
        g_ctrl.state = STATE_SHUTDOWN;
        break;

    case STATE_FAULT_UVP:
        printf("[FAULT] UVP detected, Vout=%.1f mV\n", g_ctrl.vout_filtered_mv);
        g_ctrl.state = STATE_SHUTDOWN;
        break;

    case STATE_FAULT_OPTO:
        printf("[FAULT] Opto feedback abnormal\n");
        g_ctrl.state = STATE_SHUTDOWN;
        break;

    case STATE_SHUTDOWN:
        hw_pwm_disable();
        break;

    default:
        g_ctrl.state = STATE_INIT;
        break;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    printf("=== Medical DC/DC Isolated Voltage Monitor (Opto Feedback) ===\n");

    g_ctrl.state = STATE_INIT;

    /* 模拟光耦就绪信号，使状态机能够进入 RUN 状态 */
    REG_GPIO_STATUS |= OPTO_READY_BIT;
    /* 模拟光耦反馈正常值 (CTR 约 0.8) */
    REG_OPTO_FEEDBACK = (uint16_t)(0.8f * ADC_FULL_SCALE);

    for (int i = 0; i < 200; i++) {
        state_machine_run();

        if (g_ctrl.state == STATE_RUN) {
            printf("Cycle %3d | Vout=%.1f mV | Duty=%u | Opto=%s\n",
                   i,
                   g_ctrl.vout_filtered_mv,
                   g_ctrl.duty_reg,
                   g_ctrl.opto_fault ? "FAULT" : "OK");
        }

        if (g_ctrl.state == STATE_SHUTDOWN) {
            printf("System shutdown at cycle %d\n", i);
            break;
        }
    }

    printf("=== Test Complete ===\n");
    return 0;
}
