```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
/* 使用普通全局变量代替指针解引用，避免非法地址访问 */
static volatile uint16_t g_mock_adc_data = 0U;
static volatile uint16_t g_mock_pwm_cmp  = 0U;
static volatile uint32_t g_mock_prot_flag = 0U;
static volatile uint32_t g_mock_sys_tick  = 0U;

#define MOCK_ADC_DATA_REG       (g_mock_adc_data)
#define MOCK_PWM_CMP_REG        (g_mock_pwm_cmp)
#define MOCK_PROT_FLAG_REG      (g_mock_prot_flag)
#define MOCK_SYS_TICK_MS        (g_mock_sys_tick)

/* ==================== 系统参数定义 ==================== */
#define ADC_REF_VOLTAGE         3.3f
#define ADC_RESOLUTION          4095.0f
#define CURRENT_SENSOR_RATIO    0.01f
#define CURRENT_OFFSET_VOLTAGE  1.65f

#define PWM_MAX_DUTY            1000U
#define PWM_MIN_DUTY            0U

/* ==================== 反时限保护参数 ==================== */
#define I_RATED                 10.0f
#define I_START                 12.0f
#define I_MAX                   50.0f
#define K_CONSTANT              500.0f
#define MIN_TRIP_TIME_MS        10U
#define MAX_TRIP_TIME_MS        10000U

/* ==================== 保护状态机 ==================== */
typedef enum {
    PROT_STATE_NORMAL = 0,
    PROT_STATE_WARNING,
    PROT_STATE_TRIPPING,
    PROT_STATE_TRIPPED,
    PROT_STATE_FAULT_LOCK
} ProtState_t;

/* ==================== 保护控制结构体 ==================== */
typedef struct {
    ProtState_t state;
    float       current_amp;
    float       trip_time_ms;
    uint32_t    trip_start_tick;
    uint32_t    trip_elapsed_ms;
    uint32_t    trip_count;
    bool        pwm_enabled;
    uint16_t    pwm_duty;
} ProtCtrl_t;

/* ==================== 全局变量 ==================== */
static ProtCtrl_t g_prot;

/* ==================== 函数声明 ==================== */
static float    ADC_ReadCurrent(void);
static float    CalcInverseTimeTrip(float current);
static void     Prot_Init(ProtCtrl_t *p);
static void     Prot_Update(ProtCtrl_t *p, float current);
static void     Prot_Action(ProtCtrl_t *p);
static void     PWM_SetDuty(uint16_t duty);
static void     PWM_Disable(void);
static void     PWM_Enable(void);
static uint32_t GetTickMs(void);
static const char* StateToString(ProtState_t s);

/* ==================== 函数实现 ==================== */

static float ADC_ReadCurrent(void)
{
    uint16_t adc_raw = MOCK_ADC_DATA_REG;
    float voltage = ((float)adc_raw / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    float current = (voltage - CURRENT_OFFSET_VOLTAGE) / CURRENT_SENSOR_RATIO;
    if (current < 0.0f) {
        current = 0.0f;
    }
    return current;
}

static float CalcInverseTimeTrip(float current)
{
    float i_sq = current * current;
    float i_rated_sq = I_RATED * I_RATED;
    float denom;
    float t;

    if (current < I_START) {
        return 0.0f;
    }

    denom = i_sq - i_rated_sq;
    if (denom <= 0.0f) {
        return (float)MAX_TRIP_TIME_MS;
    }

    t = K_CONSTANT / denom * 1000.0f;

    if (t < (float)MIN_TRIP_TIME_MS) {
        t = (float)MIN_TRIP_TIME_MS;
    }
    if (t > (float)MAX_TRIP_TIME_MS) {
        t = (float)MAX_TRIP_TIME_MS;
    }
    return t;
}

static void Prot_Init(ProtCtrl_t *p)
{
    if (p == NULL) {
        return;
    }
    p->state = PROT_STATE_NORMAL;
    p->current_amp = 0.0f;
    p->trip_time_ms = 0.0f;
    p->trip_start_tick = 0U;
    p->trip_elapsed_ms = 0U;
    p->trip_count = 0U;
    p->pwm_enabled = true;
    p->pwm_duty = PWM_MAX_DUTY / 2U;
    PWM_SetDuty(p->pwm_duty);
    PWM_Enable();
}

static void Prot_Update(ProtCtrl_t *p, float current)
{
    uint32_t now;

    if (p == NULL) {
        return;
    }

    now = GetTickMs();
    p->current_amp = current;

    switch (p->state) {
    case PROT_STATE_NORMAL:
        if (current >= I_START) {
            p->state = PROT_STATE_WARNING;
            p->trip_time_ms = CalcInverseTimeTrip(current);
            p->trip_start_tick = now;
            p->trip_elapsed_ms = 0U;
        }
        break;

    case PROT_STATE_WARNING:
        if (current < I_START) {
            p->state = PROT_STATE_NORMAL;
            p->trip_time_ms = 0.0f;
        } else {
            p->state = PROT_STATE_TRIPPING;
            p->trip_time_ms = CalcInverseTimeTrip(current);
            p->trip_start_tick = now;
            p->trip_elapsed_ms = 0U;
        }
        break;

    case PROT_STATE_TRIPPING:
        if (current < I_START) {
            p->state = PROT_STATE_NORMAL;
            p->trip_time_ms = 0.0f;
            p->trip_elapsed_ms = 0U;
        } else {
            p->trip_time_ms = CalcInverseTimeTrip(current);
            p->trip_elapsed_ms = now - p->trip_start_tick;

            if ((float)p->trip_elapsed_ms >= p->trip_time_ms) {
                p->state = PROT_STATE_TRIPPED;
                Prot_Action(p);
            }
        }
        break;

    case PROT_STATE_TRIPPED:
        p->state = PROT_STATE_FAULT_LOCK;
        break;

    case PROT_STATE_FAULT_LOCK:
        break;

    default:
        p->state = PROT_STATE_NORMAL;
        break;
    }
}

static void Prot_Action(ProtCtrl_t *p)
{
    if (p == NULL) {
        return;
    }
    PWM_Disable();
    p->pwm_enabled = false;
    p->trip_count++;
    MOCK_PROT_FLAG_REG = 0x01U;
}

static void PWM_SetDuty(uint16_t duty)
{
    if (duty > PWM_MAX_DUTY) {
        duty = PWM_MAX_DUTY;
    }
    MOCK_PWM_CMP_REG = duty;
}

static void PWM_Disable(void)
{
    MOCK_PWM_CMP_REG = PWM_MIN_DUTY;
}

static void PWM_Enable(void)
{
    MOCK_PWM_CMP_REG = g_prot.pwm_duty;
}

static uint32_t GetTickMs(void)
{
    return MOCK_SYS_TICK_MS;
}

static const char* StateToString(ProtState_t s)
{
    switch (s) {
    case PROT_STATE_NORMAL:     return "NORMAL";
    case PROT_STATE_WARNING:    return "WARNING";
    case PROT_STATE_TRIPPING:   return "TRIPPING";
    case PROT_STATE_TRIPPED:    return "TRIPPED";
    case PROT_STATE_FAULT_LOCK: return "FAULT_LOCK";
    default:                    return "UNKNOWN";
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    float test_currents[] = {5.0f, 11.0f, 15.0f, 20.0f, 30.0f, 45.0f};
    int   num_tests = (int)(sizeof(test_currents) / sizeof(test_currents[0]));
    int   i;
    uint32_t tick;

    printf("========================================\n");
    printf("  Industrial DC/DC Overcurrent Protection\n");
    printf("  Inverse-Time Characteristic Test\n");
    printf("========================================\n\n");

    Prot_Init(&g_prot);
    printf("[INIT] State=%s, PWM Duty=%u\n\n",
           StateToString(g_prot.state), (unsigned)g_prot.pwm_duty);

    printf("--- Inverse-Time Trip Time Calculation ---\n");
    printf("I_rated=%.1fA, I_start=%.1fA, K=%.1f\n\n",
           I_RATED, I_START, K_CONSTANT);
    printf("%-10s %-15s %-15s\n", "Current(A)", "TripTime(ms)", "Status");
    printf("------------------------------------------\n");

    for (i = 0; i < num_tests; i++) {
        float t = CalcInverseTimeTrip(test_currents[i]);
        printf("%-10.1f %-15.1f %-15s\n",
               test_currents[i], t,
               (test_currents[i] >= I_START) ? "TRIP" : "NORMAL");
    }
    printf("\n");

    printf("--- Simulation Run ---\n");
    printf("%-8s %-10s %-12s %-12s %-12s\n",
           "Tick(ms)", "Current(A)", "State", "TripTime(ms)", "Elapsed(ms)");
    printf("----------------------------------------------------------\n");

    for (tick = 0U; tick <= 200U; tick += 20U) {
        float sim_current;
        float v;
        uint16_t raw;
        float measured;

        MOCK_SYS_TICK_MS = tick;

        if (tick < 60U) {
            sim_current = 5.0f + (float)tick * 0.05f;
        } else {
            sim_current = 15.0f + (float)(tick - 60U) * 0.05f;
        }

        v = sim_current * CURRENT_SENSOR_RATIO + CURRENT_OFFSET_VOLTAGE;
        raw = (uint16_t)((v / ADC_REF_VOLTAGE) * ADC_RESOLUTION);
        MOCK_ADC_DATA_REG = raw;

        measured = ADC_ReadCurrent();
        Prot_Update(&g_prot, measured);

        printf("%-8u %-10.2f %-12s %-12.1f %-12u\n",
               (unsigned)tick,
               g_prot.current_amp,
               StateToString(g_prot.state),
               g_prot.trip_time_ms,
               (unsigned)g_prot.trip_elapsed_ms);

        if (g_prot.state == PROT_STATE_FAULT_LOCK) {
            printf("\n[!] Protection TRIPPED at tick=%ums, current=%.2fA\n",
                   (unsigned)tick, g_prot.current_amp);
            printf("[!] PWM disabled, trip_count=%u\n",
                   (unsigned)g_prot.trip_count);
            break;
        }
    }

    printf("\n--- Final Status ---\n");
    printf("State       : %s\n", StateToString(g_prot.state));
    printf("Current     : %.2f A\n", g_prot.current_amp);
    printf("Trip Count  : %u\n", (unsigned)g_prot.trip_count);
    printf("PWM Enabled : %s\n", g_prot.pwm_enabled ? "YES" : "NO");
    printf("Prot Flag   : 0x%08X\n", (unsigned)MOCK_PROT_FLAG_REG);

    return 0;
}
