```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t mock_pwr_cr   = 0U;
static volatile uint32_t mock_pwr_sr   = 0U;
static volatile uint32_t mock_adc_dr   = 0U;
static volatile uint32_t mock_tim_cnt  = 0U;
static volatile uint32_t mock_gpio_odr = 0U;

/* 寄存器位定义 */
#define PWR_CR_LPDS      (1U << 0)     /* 低功耗深度睡眠使能 */
#define PWR_CR_PDDS      (1U << 1)     /* 掉电深度睡眠使能 */
#define PWR_CR_CWUF      (1U << 2)     /* 清除唤醒标志 */
#define PWR_SR_WUF       (1U << 0)     /* 唤醒标志 */

#define GPIO_LED_PIN     (1U << 5)     /* 模拟 LED 指示引脚 */

/* ================= 系统参数配置 ================= */
#define VOUT_TARGET_MV       5000U     /* 目标输出电压 5.0V */
#define VOUT_HYST_MV         200U      /* 唤醒/休眠迟滞 200mV */
#define ADC_VREF_MV          3300U     /* ADC 参考电压 */
#define ADC_FULL_SCALE       4095U     /* 12 位 ADC 满量程 */
#define ADC_TO_MV(adc)       ((uint32_t)(adc) * ADC_VREF_MV / ADC_FULL_SCALE)

#define WAKE_INTERVAL_MS     100U      /* 唤醒检测周期 */
#define SLEEP_TIMEOUT_MS     5000U     /* 无负载超时进入休眠 */

/* ================= 状态机定义 ================= */
typedef enum {
    STATE_ACTIVE = 0,      /* 正常工作 */
    STATE_IDLE,            /* 轻载待机 */
    STATE_SLEEP,           /* 深度休眠 */
    STATE_WAKEUP           /* 唤醒过程 */
} dc_dc_state_t;

typedef struct {
    dc_dc_state_t state;
    uint32_t      vout_mv;         /* 当前输出电压 */
    uint32_t      sleep_timer_ms;  /* 休眠计时 */
    uint32_t      wake_timer_ms;   /* 唤醒计时 */
    uint32_t      cycle_count;     /* 运行周期计数 */
    bool          load_detected;   /* 负载检测标志 */
} dc_dc_ctrl_t;

/* ================= 硬件抽象层 (Mock) ================= */
static void hw_enter_sleep(void)
{
    mock_pwr_cr |= PWR_CR_LPDS;
    mock_pwr_cr |= PWR_CR_PDDS;
    printf("[HW] Enter deep sleep mode (LPDS=1, PDDS=1)\n");
}

static void hw_exit_sleep(void)
{
    mock_pwr_cr |= PWR_CR_CWUF;
    mock_pwr_cr &= ~(PWR_CR_LPDS | PWR_CR_PDDS);
    printf("[HW] Exit sleep mode, clear WUF\n");
}

static bool hw_is_wakeup_event(void)
{
    /* 模拟唤醒事件：定时器计数达到阈值或外部唤醒标志 */
    uint32_t tim = mock_tim_cnt;
    if ((tim % 20U) == 0U && tim != 0U) {
        return true;
    }
    if (mock_pwr_sr & PWR_SR_WUF) {
        return true;
    }
    return false;
}

static uint32_t hw_read_vout_adc(void)
{
    /* 模拟 ADC 采样，返回 0~4095 */
    static uint32_t fake_adc = 3000U;
    fake_adc = (fake_adc + 37U) % (ADC_FULL_SCALE + 1U);
    mock_adc_dr = fake_adc;
    return fake_adc;
}

static void hw_set_led(bool on)
{
    if (on) {
        mock_gpio_odr |= GPIO_LED_PIN;
    } else {
        mock_gpio_odr &= ~GPIO_LED_PIN;
    }
}

static void hw_delay_ms(uint32_t ms)
{
    (void)ms;
}

/* ================= 控制算法核心 ================= */
static void dc_dc_ctrl_init(dc_dc_ctrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }
    ctrl->state          = STATE_ACTIVE;
    ctrl->vout_mv        = 0U;
    ctrl->sleep_timer_ms = 0U;
    ctrl->wake_timer_ms  = 0U;
    ctrl->cycle_count    = 0U;
    ctrl->load_detected  = false;

    mock_pwr_cr   = 0U;
    mock_pwr_sr   = 0U;
    mock_tim_cnt  = 0U;
    mock_gpio_odr = 0U;
    hw_set_led(true);
    printf("[CTRL] Init done, state=ACTIVE\n");
}

static void dc_dc_update_voltage(dc_dc_ctrl_t *ctrl)
{
    uint32_t adc;
    if (ctrl == NULL) {
        return;
    }
    adc = hw_read_vout_adc();
    ctrl->vout_mv = ADC_TO_MV(adc);
}

static bool dc_dc_check_load(dc_dc_ctrl_t *ctrl)
{
    if (ctrl == NULL) {
        return false;
    }
    if (ctrl->vout_mv < (VOUT_TARGET_MV - VOUT_HYST_MV)) {
        ctrl->load_detected = true;
        return true;
    }
    ctrl->load_detected = false;
    return false;
}

static void dc_dc_state_machine(dc_dc_ctrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }
    ctrl->cycle_count++;

    switch (ctrl->state) {
    case STATE_ACTIVE:
        if (!dc_dc_check_load(ctrl)) {
            ctrl->sleep_timer_ms += WAKE_INTERVAL_MS;
            if (ctrl->sleep_timer_ms >= SLEEP_TIMEOUT_MS) {
                printf("[CTRL] No load for %ums, ACTIVE -> IDLE\n",
                       ctrl->sleep_timer_ms);
                ctrl->state = STATE_IDLE;
                ctrl->sleep_timer_ms = 0U;
            }
        } else {
            ctrl->sleep_timer_ms = 0U;
        }
        break;

    case STATE_IDLE:
        if (!dc_dc_check_load(ctrl)) {
            ctrl->sleep_timer_ms += WAKE_INTERVAL_MS;
            if (ctrl->sleep_timer_ms >= WAKE_INTERVAL_MS * 2U) {
                printf("[CTRL] IDLE -> SLEEP\n");
                ctrl->state = STATE_SLEEP;
                ctrl->sleep_timer_ms = 0U;
                hw_set_led(false);
                hw_enter_sleep();
            }
        } else {
            printf("[CTRL] Load detected in IDLE, back to ACTIVE\n");
            ctrl->state = STATE_ACTIVE;
            ctrl->sleep_timer_ms = 0U;
        }
        break;

    case STATE_SLEEP:
        if (hw_is_wakeup_event()) {
            printf("[CTRL] Wakeup event detected, SLEEP -> WAKEUP\n");
            ctrl->state = STATE_WAKEUP;
            ctrl->wake_timer_ms = 0U;
            hw_exit_sleep();
        }
        break;

    case STATE_WAKEUP:
        ctrl->wake_timer_ms += WAKE_INTERVAL_MS;
        if (ctrl->wake_timer_ms >= WAKE_INTERVAL_MS * 3U) {
            printf("[CTRL] Power stable, WAKEUP -> ACTIVE\n");
            ctrl->state = STATE_ACTIVE;
            ctrl->wake_timer_ms = 0U;
            ctrl->sleep_timer_ms = 0U;
            hw_set_led(true);
        }
        break;

    default:
        ctrl->state = STATE_ACTIVE;
        break;
    }
}

static const char *state_name(dc_dc_state_t s)
{
    switch (s) {
    case STATE_ACTIVE: return "ACTIVE";
    case STATE_IDLE:   return "IDLE";
    case STATE_SLEEP:  return "SLEEP";
    case STATE_WAKEUP: return "WAKEUP";
    default:           return "UNKNOWN";
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    dc_dc_ctrl_t ctrl;
    uint32_t i;

    printf("===== DC/DC Sleep/Wakeup Control Demo =====\n");
    dc_dc_ctrl_init(&ctrl);

    for (i = 0U; i < 80U; i++) {
        mock_tim_cnt = i;

        dc_dc_update_voltage(&ctrl);
        dc_dc_state_machine(&ctrl);

        printf("[%03u] Vout=%4umV State=%-6s SleepTimer=%ums WakeTimer=%ums LED=%s\n",
               i,
               ctrl.vout_mv,
               state_name(ctrl.state),
               ctrl.sleep_timer_ms,
               ctrl.wake_timer_ms,
               (mock_gpio_odr & GPIO_LED_PIN) ? "ON" : "OFF");

        hw_delay_ms(WAKE_INTERVAL_MS);
    }

    printf("===== Demo finished =====\n");
    return 0;
}
