#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock register definitions (no MCU-specific headers)
 * ============================================================ */
static volatile uint16_t g_adc_data;
static volatile uint32_t g_adc_ctrl;
static volatile uint32_t g_adc_status;
static volatile uint16_t g_pwm_duty;
static volatile uint32_t g_pwm_ctrl;
static volatile uint32_t g_gpio_fault;
static volatile uint32_t g_gpio_led;
static volatile uint32_t g_timer_ms;

#define REG_ADC_DATA           (g_adc_data)
#define REG_ADC_CTRL           (g_adc_ctrl)
#define REG_ADC_STATUS         (g_adc_status)
#define REG_PWM_DUTY           (g_pwm_duty)
#define REG_PWM_CTRL           (g_pwm_ctrl)
#define REG_GPIO_FAULT         (g_gpio_fault)
#define REG_GPIO_LED           (g_gpio_led)
#define REG_TIMER_MS           (g_timer_ms)

/* ADC control bits */
#define ADC_CTRL_START         (1U << 0)
#define ADC_CTRL_CH_SEL_SHIFT  4U
#define ADC_CTRL_CH_SEL_MASK   (0x7U << ADC_CTRL_CH_SEL_SHIFT)
#define ADC_STATUS_EOC         (1U << 0)

/* PWM control bits */
#define PWM_CTRL_ENABLE        (1U << 0)
#define PWM_CTRL_FAULT_CLR     (1U << 1)

/* GPIO bits */
#define GPIO_FAULT_OVP         (1U << 0)
#define GPIO_FAULT_UVP         (1U << 1)
#define GPIO_LED_RUN           (1U << 0)
#define GPIO_LED_ALARM         (1U << 1)

/* ============================================================
 * System parameters
 * ============================================================ */
#define VREF_MV                3300U
#define ADC_FULL_SCALE         4095U

#define OPTO_GAIN_NUM          187U
#define OPTO_GAIN_DEN          10U

#define VOUT_NOMINAL_MV        5000U
#define VOUT_OVP_MV            6000U
#define VOUT_UVP_MV            4000U

#define KP_NUM                 3U
#define KP_DEN                 10U
#define KI_NUM                 1U
#define KI_DEN                 100U

#define PWM_DUTY_MIN           50U
#define PWM_DUTY_MAX           950U
#define PWM_DUTY_INIT          500U

#define FILTER_DEPTH           8U

/* ============================================================
 * Data structures
 * ============================================================ */
typedef struct {
    uint16_t adc_raw;
    uint32_t vout_mv;
    uint32_t vout_filtered_mv;
    uint16_t pwm_duty;
    int32_t  integral;
    bool     ovp_flag;
    bool     uvp_flag;
    bool     fault_active;
    uint32_t fault_count;
} DCDC_Handle_t;

typedef struct {
    uint32_t buf[FILTER_DEPTH];
    uint32_t sum;
    uint8_t  idx;
    uint8_t  count;
} MovAvgFilter_t;

static MovAvgFilter_t g_vout_filter;

/* ============================================================
 * Mock hardware helpers
 * ============================================================ */
static void mock_hw_init(void)
{
    REG_ADC_CTRL   = 0U;
    REG_ADC_STATUS = 0U;
    REG_PWM_CTRL   = 0U;
    REG_PWM_DUTY   = PWM_DUTY_INIT;
    REG_GPIO_FAULT = 0U;
    REG_GPIO_LED   = 0U;
    REG_TIMER_MS   = 0U;
}

static uint16_t mock_adc_read(uint8_t channel)
{
    uint32_t ctrl = REG_ADC_CTRL;
    ctrl &= ~ADC_CTRL_CH_SEL_MASK;
    ctrl |= ((uint32_t)(channel & 0x7U) << ADC_CTRL_CH_SEL_SHIFT);
    ctrl |= ADC_CTRL_START;
    REG_ADC_CTRL = ctrl;

    REG_ADC_STATUS |= ADC_STATUS_EOC;

    /* Synthetic ADC value: ~2500 counts for ~2V at ADC pin */
    uint16_t raw = (uint16_t)(2500U + (REG_TIMER_MS % 100U));
    REG_ADC_DATA = raw;
    return raw;
}

static void mock_pwm_set_duty(uint16_t duty)
{
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    REG_PWM_DUTY = duty;
    REG_PWM_CTRL |= PWM_CTRL_ENABLE;
}

static void mock_pwm_disable(void)
{
    REG_PWM_CTRL &= ~PWM_CTRL_ENABLE;
}

static void mock_gpio_set_fault(bool ovp, bool uvp)
{
    uint32_t val = 0U;
    if (ovp) val |= GPIO_FAULT_OVP;
    if (uvp) val |= GPIO_FAULT_UVP;
    REG_GPIO_FAULT = val;
}

static void mock_gpio_set_led(bool run, bool alarm)
{
    uint32_t val = 0U;
    if (run)   val |= GPIO_LED_RUN;
    if (alarm) val |= GPIO_LED_ALARM;
    REG_GPIO_LED = val;
}

static uint32_t mock_get_tick_ms(void)
{
    return REG_TIMER_MS;
}

static void mock_delay_ms(uint32_t ms)
{
    REG_TIMER_MS += ms;
}

/* ============================================================
 * Moving average filter
 * ============================================================ */
static void filter_init(MovAvgFilter_t *f)
{
    uint32_t i;
    for (i = 0U; i < FILTER_DEPTH; i++) {
        f->buf[i] = 0U;
    }
    f->sum   = 0U;
    f->idx   = 0U;
    f->count = 0U;
}

static uint32_t filter_update(MovAvgFilter_t *f, uint32_t new_val)
{
    if (f->count < FILTER_DEPTH) {
        f->sum += new_val;
        f->buf[f->idx] = new_val;
        f->idx++;
        f->count++;
        if (f->idx >= FILTER_DEPTH) {
            f->idx = 0U;
        }
        return f->sum / f->count;
    } else {
        f->sum -= f->buf[f->idx];
        f->sum += new_val;
        f->buf[f->idx] = new_val;
        f->idx++;
        if (f->idx >= FILTER_DEPTH) {
            f->idx = 0U;
        }
        return f->sum / FILTER_DEPTH;
    }
}

/* ============================================================
 * ADC to millivolt conversion
 * ============================================================ */
static uint32_t adc_to_mv(uint16_t raw)
{
    uint32_t mv;
    mv = ((uint32_t)raw * VREF_MV) / ADC_FULL_SCALE;
    return mv;
}

/* ============================================================
 * Apply optocoupler feedback gain
 * ============================================================ */
static uint32_t apply_opto_gain(uint32_t adc_mv)
{
    uint32_t vout;
    vout = (adc_mv * OPTO_GAIN_NUM) / OPTO_GAIN_DEN;
    return vout;
}

/* ============================================================
 * PI controller
 * ============================================================ */
static uint16_t pi_control(DCDC_Handle_t *h, uint32_t vout_mv)
{
    int32_t error;
    int32_t p_term;
    int32_t i_term;
    int32_t output;

    error = (int32_t)VOUT_NOMINAL_MV - (int32_t)vout_mv;

    p_term = (error * (int32_t)KP_NUM) / (int32_t)KP_DEN;

    h->integral += (error * (int32_t)KI_NUM) / (int32_t)KI_DEN;

    if (h->integral > 5000)  h->integral = 5000;
    if (h->integral < -5000) h->integral = -5000;

    i_term = h->integral;

    output = (int32_t)PWM_DUTY_INIT + p_term + i_term;

    if (output < (int32_t)PWM_DUTY_MIN) output = (int32_t)PWM_DUTY_MIN;
    if (output > (int32_t)PWM_DUTY_MAX) output = (int32_t)PWM_DUTY_MAX;

    return (uint16_t)output;
}

/* ============================================================
 * Protection check
 * ============================================================ */
static void protection_check(DCDC_Handle_t *h, uint32_t vout_mv)
{
    h->ovp_flag = false;
    h->uvp_flag = false;

    if (vout_mv > VOUT_OVP_MV) {
        h->ovp_flag = true;
    }
    if (vout_mv < VOUT_UVP_MV) {
        h->uvp_flag = true;
    }

    if (h->ovp_flag || h->uvp_flag) {
        h->fault_active = true;
        h->fault_count++;
        mock_pwm_disable();
        mock_gpio_set_fault(h->ovp_flag, h->uvp_flag);
        mock_gpio_set_led(false, true);
    } else {
        h->fault_active = false;
        mock_gpio_set_fault(false, false);
        mock_gpio_set_led(true, false);
    }
}

/* ============================================================
 * Main control loop step
 * ============================================================ */
static void control_step(DCDC_Handle_t *h)
{
    uint16_t raw;
    uint32_t adc_mv;
    uint32_t vout_mv;
    uint32_t vout_filt;
    uint16_t duty;

    raw = mock_adc_read(0U);
    h->adc_raw = raw;

    adc_mv = adc_to_mv(raw);

    vout_mv = apply_opto_gain(adc_mv);
    h->vout_mv = vout_mv;

    vout_filt = filter_update(&g_vout_filter, vout_mv);
    h->vout_filtered_mv = vout_filt;

    protection_check(h, vout_filt);

    if (!h->fault_active) {
        duty = pi_control(h, vout_filt);
        h->pwm_duty = duty;
        mock_pwm_set_duty(duty);
    }
}

/* ============================================================
 * Main function
 * ============================================================ */
int main(void)
{
    DCDC_Handle_t dcdc;
    uint32_t tick;
    uint32_t loop_count;

    dcdc.adc_raw          = 0U;
    dcdc.vout_mv          = 0U;
    dcdc.vout_filtered_mv = 0U;
    dcdc.pwm_duty         = PWM_DUTY_INIT;
    dcdc.integral         = 0;
    dcdc.ovp_flag         = false;
    dcdc.uvp_flag         = false;
    dcdc.fault_active     = false;
    dcdc.fault_count      = 0U;

    mock_hw_init();
    filter_init(&g_vout_filter);

    printf("=== Medical DC/DC Isolated Voltage Monitor ===\n");
    printf("Nominal: %u mV, OVP: %u mV, UVP: %u mV\n",
           (unsigned)VOUT_NOMINAL_MV, (unsigned)VOUT_OVP_MV, (unsigned)VOUT_UVP_MV);
    printf("Opto gain: %u/%u\n", (unsigned)OPTO_GAIN_NUM, (unsigned)OPTO_GAIN_DEN);
    printf("----------------------------------------------\n");

    for (loop_count = 0U; loop_count < 20U; loop_count++) {
        tick = mock_get_tick_ms();

        control_step(&dcdc);

        printf("[%4u ms] ADC=%4u  Vout=%5u mV  Filt=%5u mV  "
               "Duty=%3u  OVP=%d UVP=%d Fault=%d\n",
               (unsigned)tick,
               (unsigned)dcdc.adc_raw,
               (unsigned)dcdc.vout_mv,
               (unsigned)dcdc.vout_filtered_mv,
               (unsigned)dcdc.pwm_duty,
               dcdc.ovp_flag ? 1 : 0,
               dcdc.uvp_flag ? 1 : 0,
               dcdc.fault_active ? 1 : 0);

        mock_delay_ms(10U);
    }

    printf("----------------------------------------------\n");
    printf("Total faults detected: %u\n", (unsigned)dcdc.fault_count);
    printf("Final PWM duty: %u\n", (unsigned)dcdc.pwm_duty);
    printf("Final filtered Vout: %u mV\n", (unsigned)dcdc.vout_filtered_mv);
    printf("=== Monitor complete ===\n");

    return 0;
}
