```c
#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint16_t mock_adc_vin  = 0;
static volatile uint16_t mock_adc_vout = 0;
static volatile uint16_t mock_adc_il   = 0;
static volatile uint16_t mock_pwm_duty = 0;
static volatile uint16_t mock_pwm_period = 0;
static volatile uint8_t  mock_ctrl_enable = 0;

#define MOCK_REG_ADC_VIN        (mock_adc_vin)
#define MOCK_REG_ADC_VOUT       (mock_adc_vout)
#define MOCK_REG_ADC_IL         (mock_adc_il)
#define MOCK_REG_PWM_DUTY       (mock_pwm_duty)
#define MOCK_REG_PWM_PERIOD     (mock_pwm_period)
#define MOCK_REG_CTRL_ENABLE    (mock_ctrl_enable)

/* ================= 系统参数 ================= */
#define ADC_VREF                3.3f
#define ADC_FULL_SCALE          4095.0f
#define PWM_PERIOD_TICKS        1000.0f

#define VIN_NOMINAL             12.0f
#define VOUT_REF                5.0f
#define L_INDUCTANCE            10e-6f
#define C_CAPACITANCE           470e-6f
#define R_LOAD                  5.0f

/* 前馈增益：D_ff = Vout_ref / Vin */
#define FF_GAIN                 1.0f

/* 反馈 PID 参数 */
#define PID_KP                  0.08f
#define PID_KI                  0.5f
#define PID_KD                  0.0005f

/* 抗积分饱和限幅 */
#define DUTY_MIN                0.02f
#define DUTY_MAX                0.95f
#define INTEGRAL_MIN            (-0.5f)
#define INTEGRAL_MAX            (0.5f)

/* 采样周期 (秒) */
#define TS                      20e-6f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float out_min;
    float out_max;
} PID_Controller;

typedef struct {
    float vin;
    float vout;
    float il;
    float vout_ref;
    float duty_ff;
    float duty_fb;
    float duty_total;
    float duty_prev;
} Buck_State;

/* ================= 工具函数 ================= */
static float adc_to_voltage(uint16_t adc_val)
{
    return ((float)adc_val / ADC_FULL_SCALE) * ADC_VREF;
}

static uint16_t voltage_to_duty(float duty)
{
    if (duty < DUTY_MIN) duty = DUTY_MIN;
    if (duty > DUTY_MAX) duty = DUTY_MAX;
    return (uint16_t)(duty * PWM_PERIOD_TICKS);
}

static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

/* ================= PID 初始化 ================= */
static void pid_init(PID_Controller *pid, float kp, float ki, float kd,
                     float out_min, float out_max)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->out_min = out_min;
    pid->out_max = out_max;
}

/* ================= PID 计算 ================= */
static float pid_compute(PID_Controller *pid, float error, float dt)
{
    float p_term, i_term, d_term, output;

    p_term = pid->kp * error;

    pid->integral += pid->ki * error * dt;
    pid->integral = clampf(pid->integral, INTEGRAL_MIN, INTEGRAL_MAX);
    i_term = pid->integral;

    d_term = pid->kd * (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = p_term + i_term + d_term;
    output = clampf(output, pid->out_min, pid->out_max);

    return output;
}

/* ================= 前馈计算 ================= */
static float feedforward_duty(float vin, float vout_ref)
{
    if (vin < 0.1f) vin = 0.1f;
    return FF_GAIN * (vout_ref / vin);
}

/* ================= Buck 控制主循环 ================= */
static void buck_control_step(Buck_State *st, PID_Controller *pid)
{
    float error;
    float duty_ff;
    float duty_fb;
    float duty_total;
    uint16_t pwm_val;

    /* 1. 读取 ADC 采样值 */
    st->vin  = adc_to_voltage(MOCK_REG_ADC_VIN);
    st->vout = adc_to_voltage(MOCK_REG_ADC_VOUT);
    st->il   = adc_to_voltage(MOCK_REG_ADC_IL);

    /* 2. 前馈控制：基于输入电压和参考输出电压直接计算占空比 */
    duty_ff = feedforward_duty(st->vin, st->vout_ref);
    st->duty_ff = duty_ff;

    /* 3. 反馈控制：PID 调节输出电压误差 */
    error = st->vout_ref - st->vout;
    duty_fb = pid_compute(pid, error, TS);
    st->duty_fb = duty_fb;

    /* 4. 前馈 + 反馈 合成总占空比 */
    duty_total = duty_ff + duty_fb;
    duty_total = clampf(duty_total, DUTY_MIN, DUTY_MAX);
    st->duty_total = duty_total;

    /* 5. 占空比限幅与 PWM 输出 */
    pwm_val = voltage_to_duty(duty_total);
    MOCK_REG_PWM_DUTY = pwm_val;

    /* 6. 保存历史值 */
    st->duty_prev = duty_total;
}

/* ================= 主函数 ================= */
int main(void)
{
    Buck_State buck;
    PID_Controller pid;
    int i;

    /* 初始化状态 */
    buck.vin = VIN_NOMINAL;
    buck.vout = 0.0f;
    buck.il = 0.0f;
    buck.vout_ref = VOUT_REF;
    buck.duty_ff = 0.0f;
    buck.duty_fb = 0.0f;
    buck.duty_total = 0.0f;
    buck.duty_prev = 0.0f;

    /* 初始化 PID */
    pid_init(&pid, PID_KP, PID_KI, PID_KD, -0.5f, 0.5f);

    /* 使能控制 */
    MOCK_REG_CTRL_ENABLE = 1;
    MOCK_REG_PWM_PERIOD = (uint16_t)PWM_PERIOD_TICKS;

    printf("===== Buck Converter Feedforward + Feedback Control =====\n");
    printf("Vref=%.2fV, Vin_nom=%.2fV, L=%.1fuH, C=%.0fuF, R=%.1fOhm\n",
           VOUT_REF, VIN_NOMINAL, L_INDUCTANCE * 1e6f,
           C_CAPACITANCE * 1e6f, R_LOAD);
    printf("PID: Kp=%.4f, Ki=%.4f, Kd=%.6f\n", PID_KP, PID_KI, PID_KD);
    printf("----------------------------------------------------------\n");
    printf("%-6s %-8s %-8s %-8s %-8s %-8s %-8s\n",
           "Step", "Vin(V)", "Vout(V)", "D_ff", "D_fb", "D_total", "PWM");

    /* 模拟 20 个控制周期，输入电压在中间发生阶跃 */
    for (i = 0; i < 20; i++) {
