#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t g_pwr_cr = 0;
static volatile uint32_t g_pwr_csr = 0;
static volatile uint32_t g_dcdc_cr = 0;
static volatile uint32_t g_dcdc_sr = 0;
static volatile uint32_t g_gpioa_moder = 0;
static volatile uint32_t g_gpioa_odr = 0;
static volatile uint32_t g_gpioa_idr = 0;
static volatile uint32_t g_exti_imr = 0;
static volatile uint32_t g_exti_pr = 0;
static volatile uint32_t g_nvic_iser = 0;

#define PWR_CR              (g_pwr_cr)
#define PWR_CSR             (g_pwr_csr)
#define DCDC_CR             (g_dcdc_cr)
#define DCDC_SR             (g_dcdc_sr)
#define GPIOA_MODER         (g_gpioa_moder)
#define GPIOA_ODR           (g_gpioa_odr)
#define GPIOA_IDR           (g_gpioa_idr)
#define EXTI_IMR            (g_exti_imr)
#define EXTI_PR             (g_exti_pr)
#define NVIC_ISER           (g_nvic_iser)

/* PWR_CR 位定义 */
#define PWR_CR_LPDS         (1U << 0)
#define PWR_CR_PDDS         (1U << 1)
#define PWR_CR_CWUF         (1U << 2)
#define PWR_CR_PVDE         (1U << 4)

/* PWR_CSR 位定义 */
#define PWR_CSR_WUF         (1U << 0)
#define PWR_CSR_SBF         (1U << 1)
#define PWR_CSR_PVDO        (1U << 2)

/* DCDC_CR 位定义 */
#define DCDC_CR_EN          (1U << 0)
#define DCDC_CR_LPEN        (1U << 1)
#define DCDC_CR_SLEEP       (1U << 2)
#define DCDC_CR_WAKEUP      (1U << 3)

/* DCDC_SR 位定义 */
#define DCDC_SR_READY       (1U << 0)
#define DCDC_SR_FAULT       (1U << 1)
#define DCDC_SR_LP_MODE     (1U << 2)

/* ================= 系统状态定义 ================= */
typedef enum {
    DCDC_STATE_ACTIVE = 0,
    DCDC_STATE_IDLE,
    DCDC_STATE_SLEEP,
    DCDC_STATE_WAKEUP,
    DCDC_STATE_FAULT
} DCDC_State_t;

typedef enum {
    WAKEUP_SRC_NONE = 0,
    WAKEUP_SRC_GPIO,
    WAKEUP_SRC_TIMER,
    WAKEUP_SRC_LOAD
} WakeupSource_t;

/* ================= 全局变量 ================= */
static DCDC_State_t g_dcdc_state = DCDC_STATE_ACTIVE;
static WakeupSource_t g_wakeup_source = WAKEUP_SRC_NONE;
static uint32_t g_idle_counter = 0;
static uint32_t g_sleep_counter = 0;

#define IDLE_THRESHOLD      3U
#define SLEEP_THRESHOLD     3U
#define WAKEUP_DELAY        2U

/* ================= 函数声明 ================= */
static void DCDC_Init(void);
static void DCDC_EnterSleep(void);
static void DCDC_ExitSleep(void);
static void DCDC_Process(void);
static bool DCDC_CheckLoadActivity(void);
static void System_EnterLowPower(void);
static void System_ExitLowPower(void);
static void Delay(uint32_t count);

/* ================= 初始化 ================= */
static void DCDC_Init(void)
{
    /* 复位寄存器 */
    PWR_CR = 0;
    PWR_CSR = 0;
    DCDC_CR = 0;
    DCDC_SR = 0;
    GPIOA_MODER = 0;
    GPIOA_ODR = 0;
    GPIOA_IDR = 0;
    EXTI_IMR = 0;
    EXTI_PR = 0;
    NVIC_ISER = 0;

    /* 使能 DC/DC 转换器 */
    DCDC_CR |= DCDC_CR_EN;
    /* 模拟硬件就绪 */
    DCDC_SR |= DCDC_SR_READY;

    /* 清除唤醒标志 */
    PWR_CR |= PWR_CR_CWUF;

    /* 配置唤醒源 GPIO */
    GPIOA_MODER &= ~(3U << 0);
    EXTI_IMR |= (1U << 0);
    NVIC_ISER |= (1U << 6);

    g_dcdc_state = DCDC_STATE_ACTIVE;
    g_wakeup_source = WAKEUP_SRC_NONE;
    g_idle_counter = 0;
    g_sleep_counter = 0;

    printf("[DCDC] Initialized, state=ACTIVE\r\n");
}

/* ================= 进入休眠 ================= */
static void DCDC_EnterSleep(void)
{
    printf("[DCDC] Entering sleep mode...\r\n");

    DCDC_CR |= DCDC_CR_LPEN;
    DCDC_CR |= DCDC_CR_SLEEP;
    /* 模拟硬件进入低功耗模式 */
    DCDC_SR |= DCDC_SR_LP_MODE;

    PWR_CR |= PWR_CR_LPDS;
    PWR_CR &= ~PWR_CR_PDDS;

    g_dcdc_state = DCDC_STATE_SLEEP;
    g_sleep_counter = 0;

    printf("[DCDC] Sleep mode entered, LP_MODE=%d\r\n",
           (DCDC_SR & DCDC_SR_LP_MODE) ? 1 : 0);

    System_EnterLowPower();
}

/* ================= 退出休眠 ================= */
static void DCDC_ExitSleep(void)
{
    printf("[DCDC] Exiting sleep mode...\r\n");

    System_ExitLowPower();

    PWR_CR |= PWR_CR_CWUF;

    DCDC_CR &= ~DCDC_CR_SLEEP;
    DCDC_CR &= ~DCDC_CR_LPEN;
    DCDC_SR &= ~DCDC_SR_LP_MODE;
    DCDC_SR |= DCDC_SR_READY;

    g_dcdc_state = DCDC_STATE_WAKEUP;
    g_idle_counter = 0;
    g_sleep_counter = 0;

    printf("[DCDC] Wakeup complete, state=WAKEUP\r\n");
}

/* ================= 检查负载活动 ================= */
static bool DCDC_CheckLoadActivity(void)
{
    return (GPIOA_IDR & (1U << 1)) != 0;
}

/* ================= 系统进入低功耗 ================= */
static void System_EnterLowPower(void)
{
    printf("[SYSTEM] Entering low power (WFI)...\r\n");

    /* 模拟唤醒事件 */
    g_wakeup_source = WAKEUP_SRC_GPIO;
    EXTI_PR |= (1U << 0);

    printf("[SYSTEM] Wakeup event detected, source=GPIO\r\n");
}

/* ================= 系统退出低功耗 ================= */
static void System_ExitLowPower(void)
{
    printf("[SYSTEM] Exiting low power\r\n");
}

/* ================= 主处理循环 ================= */
static void DCDC_Process(void)
{
    switch (g_dcdc_state) {
        case DCDC_STATE_ACTIVE:
            if (DCDC_CheckLoadActivity()) {
                g_idle_counter = 0;
                g_sleep_counter = 0;
            } else {
                g_idle_counter++;
                if (g_idle_counter >= IDLE_THRESHOLD) {
                    g_dcdc_state = DCDC_STATE_IDLE;
                    printf("[DCDC] State -> IDLE (counter=%u)\r\n", g_idle_counter);
                }
            }
            break;

        case DCDC_STATE_IDLE:
            if (DCDC_CheckLoadActivity()) {
                g_idle_counter = 0;
                g_sleep_counter = 0;
                g_dcdc_state = DCDC_STATE_ACTIVE;
                printf("[DCDC] State -> ACTIVE (load detected)\r\n");
            } else {
                g_sleep_counter++;
                if (g_sleep_counter >= SLEEP_THRESHOLD) {
                    DCDC_EnterSleep();
                }
            }
            break;

        case DCDC_STATE_SLEEP:
            if (g_wakeup_source != WAKEUP_SRC_NONE) {
                DCDC_ExitSleep();
            }
            break;

        case DCDC_STATE_WAKEUP:
            g_sleep_counter++;
            if (g_sleep_counter >= WAKEUP_DELAY) {
                g_dcdc_state = DCDC_STATE_ACTIVE;
                g_wakeup_source = WAKEUP_SRC_NONE;
                g_idle_counter = 0;
                g_sleep_counter = 0;
                printf("[DCDC] State -> ACTIVE (wakeup complete)\r\n");
            }
            break;

        case DCDC_STATE_FAULT:
            printf("[DCDC] FAULT state, attempting recovery...\r\n");
            DCDC_CR &= ~DCDC_CR_EN;
            Delay(10);
            DCDC_CR |= DCDC_CR_EN;
            DCDC_SR |= DCDC_SR_READY;
            g_dcdc_state = DCDC_STATE_ACTIVE;
            printf("[DCDC] Recovered to ACTIVE\r\n");
            break;

        default:
            g_dcdc_state = DCDC_STATE_ACTIVE;
            break;
    }
}

/* ================= 延时函数 ================= */
static void Delay(uint32_t count)
{
    volatile uint32_t i;
    for (i = 0; i < count; i++) {
        /* 空循环 */
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t loop_count = 0;

    printf("========================================\r\n");
    printf("  DC/DC Sleep-Wakeup Control Demo\r\n");
    printf("========================================\r\n");

    DCDC_Init();

    while (loop_count < 20) {
        printf("\r\n--- Loop %u ---\r\n", loop_count);
        printf("State=%d, IdleCnt=%u, SleepCnt=%u\r\n",
               (int)g_dcdc_state, g_idle_counter, g_sleep_counter);

        DCDC_Process();

        if (loop_count == 5) {
            printf("[SIM] Load activity ON\r\n");
            GPIOA_IDR |= (1U << 1);
        }
        if (loop_count == 10) {
            printf("[SIM] Load activity OFF\r\n");
            GPIOA_IDR &= ~(1U << 1);
        }
        if (loop_count == 15) {
            printf("[SIM] Wakeup event triggered\r\n");
            g_wakeup_source = WAKEUP_SRC_GPIO;
        }

        Delay(100);
        loop_count++;
    }

    printf("\r\n========================================\r\n");
    printf("  Demo Complete\r\n");
    printf("  Final State=%d\r\n", (int)g_dcdc_state);
    printf("========================================\r\n");

    return 0;
}
