#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ================= 参数定义 ================= */
#define VREF_DEFAULT            12.0f
#define VOUT_MIN                0.0f
#define VOUT_MAX                24.0f
#define DUTY_MIN                0.05f
#define DUTY_MAX                0.95f
#define SAMPLE_TIME_S           1e-4f
#define SETTLE_BAND_PERCENT     0.02f
#define MAX_SAMPLES             2000
#define KP_INIT                 0.1f
#define KI_INIT                 0.01f
#define KD_INIT                 0.0f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float prev_prev_error;
    float output;
} PID_Controller;

typedef struct {
    float rise_time;
    float peak_time;
    float settling_time;
    float overshoot;
    float steady_state_error;
    float peak_value;
    float final_value;
    bool  valid;
} StepResponseMetrics;

/* ================= 模拟 DC/DC 被控对象 ================= */
static float mock_dcdc_plant(float duty, float vout_prev, float dt)
{
    const float K = 20.0f;
    const float tau = 0.005f;
    float target = K * duty;
    float alpha = dt / (tau + dt);
    float vout = vout_prev + alpha * (target - vout_prev);

    if (vout < VOUT_MIN) vout = VOUT_MIN;
    if (vout > VOUT_MAX) vout = VOUT_MAX;

    return vout;
}

/* ================= PID 控制器 ================= */
static void pid_init(PID_Controller *pid, float kp, float ki, float kd)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_prev_error = 0.0f;
    pid->output = 0.0f;
}

static float pid_compute(PID_Controller *pid, float setpoint, float measured, float dt)
{
    float error = setpoint - measured;
    float derivative;
    float output;

    pid->integral += error * dt;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;

    derivative = (error - pid->prev_error) / dt;

    output = pid->kp * error
           + pid->ki * pid->integral
           + pid->kd * derivative;

    pid->prev_prev_error = pid->prev_error;
    pid->prev_error = error;
    pid->output = output;

    return output;
}

static void pid_reset(PID_Controller *pid)
{
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_prev_error = 0.0f;
    pid->output = 0.0f;
}

/* ================= 阶跃响应数据采集 ================= */
static void capture_step_response(float *vout_buf, float *time_buf, int *count, float vref)
{
    int i = 0;
    float t = 0.0f;
    float vout = 0.0f;
    float duty = 0.5f;

    (void)vref;

    while (i < MAX_SAMPLES) {
        vout = mock_dcdc_plant(duty, vout, SAMPLE_TIME_S);

        vout_buf[i] = vout;
        time_buf[i] = t;
        t += SAMPLE_TIME_S;
        i++;
    }

    *count = i;
}

/* ================= 阶跃响应指标计算 ================= */
static void analyze_step_response(const float *vout, const float *time, int count,
                                  float vref, StepResponseMetrics *metrics)
{
    int i;
    float final_val = 0.0f;
    float peak = 0.0f;
    float band;
    int settle_idx = -1;
    int peak_idx = -1;
    float t_rise = 0.0f;
    float t_peak = 0.0f;
    float t_settle = 0.0f;
    float overshoot = 0.0f;
    float sse = 0.0f;

    metrics->valid = false;

    if (count < 10) {
        return;
    }

    {
        int start = count - count / 10;
        if (start < 0) start = 0;
        float sum = 0.0f;
        int n = 0;
        for (i = start; i < count; i++) {
            sum += vout[i];
            n++;
        }
        final_val = (n > 0) ? sum / (float)n : 0.0f;
    }

    peak = vout[0];
    peak_idx = 0;
    for (i = 1; i < count; i++) {
        if (vout[i] > peak) {
            peak = vout[i];
            peak_idx = i;
        }
    }

    {
        float low = 0.1f * vref;
        float high = 0.9f * vref;
        int low_idx = -1;
        int high_idx = -1;

        for (i = 0; i < count; i++) {
            if (low_idx < 0 && vout[i] >= low) {
                low_idx = i;
            }
            if (high_idx < 0 && vout[i] >= high) {
                high_idx = i;
            }
        }

        if (low_idx >= 0 && high_idx >= 0 && high_idx > low_idx) {
            t_rise = time[high_idx] - time[low_idx];
        } else {
            t_rise = 0.0f;
        }
    }

    t_peak = time[peak_idx];

    if (vref > 0.0f) {
        overshoot = (peak - vref) / vref * 100.0f;
        if (overshoot < 0.0f) overshoot = 0.0f;
    }

    sse = fabsf(vref - final_val);

    band = SETTLE_BAND_PERCENT * vref;
    if (band < 1e-6f) band = 1e-6f;

    settle_idx = -1;
    for (i = 0; i < count; i++) {
        if (fabsf(vout[i] - vref) <= band) {
            int j;
            bool inside = true;
            for (j = i; j < count; j++) {
                if (fabsf(vout[j] - vref) > band) {
                    inside = false;
                    break;
                }
            }
            if (inside) {
                settle_idx = i;
                break;
            }
        }
    }

    if (settle_idx >= 0) {
        t_settle = time[settle_idx];
    } else {
        t_settle = time[count - 1];
    }

    metrics->rise_time = t_rise;
    metrics->peak_time = t_peak;
    metrics->settling_time = t_settle;
    metrics->overshoot = overshoot;
    metrics->steady_state_error = sse;
    metrics->peak_value = peak;
    metrics->final_value = final_val;
    metrics->valid = true;
}

/* ================= 自整定算法 ================= */
static void auto_tune_pid(PID_Controller *pid, const StepResponseMetrics *metrics,
                          float vref)
{
    float kp = pid->kp;
    float ki = pid->ki;
    float kd = pid->kd;

    if (!metrics->valid) {
        return;
    }

    if (metrics->overshoot > 20.0f) {
        kp *= 0.7f;
    } else if (metrics->overshoot > 10.0f) {
        kp *= 0.85f;
    } else if (metrics->overshoot < 2.0f && metrics->rise_time > 0.01f) {
        kp *= 1.15f;
    }

    if (metrics->steady_state_error > 0.05f * vref) {
        ki *= 1.5f;
    } else if (metrics->steady_state_error < 0.01f * vref) {
        ki *= 0.9f;
    }

    if (metrics->settling_time > 0.05f) {
        kd += 0.001f;
    } else if (metrics->settling_time < 0.01f) {
        kd *= 0.9f;
    }

    if (kp < 0.001f) kp = 0.001f;
    if (kp > 10.0f) kp = 10.0f;
    if (ki < 0.0001f) ki = 0.0001f;
    if (ki > 5.0f) ki = 5.0f;
    if (kd < 0.0f) kd = 0.0f;
    if (kd > 1.0f) kd = 1.0f;

    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
}

/* ================= 主函数 ================= */
int main(void)
{
    PID_Controller pid;
    StepResponseMetrics metrics;
    static float vout_buf[MAX_SAMPLES];
    static float time_buf[MAX_SAMPLES];
    float vref = VREF_DEFAULT;
    float vout = 0.0f;
    float duty = 0.5f;
    int count = 0;
    int iter;
    int i;

    printf("========================================\n");
    printf("  DC/DC Converter PID Auto-Tuning\n");
    printf("  Method: Step Response Analysis\n");
    printf("========================================\n\n");

    pid_init(&pid, KP_INIT, KI_INIT, KD_INIT);

    printf("[Init] PID parameters: Kp=%.4f, Ki=%.4f, Kd=%.4f\n",
           pid.kp, pid.ki, pid.kd);
    printf("[Init] Vref = %.2f V\n\n", vref);

    for (iter = 0; iter < 5; iter++) {
        printf("----------------------------------------\n");
        printf("[Iteration %d] Tuning...\n", iter + 1);

        pid_reset(&pid);
        vout = 0.0f;
        duty = 0.5f;

        capture_step_response(vout_buf, time_buf, &count, vref);

        printf("  Captured %d samples\n", count);

        analyze_step_response(vout_buf, time_buf, count, vref, &metrics);

        if (metrics.valid) {
            printf("  Rise Time:        %.6f s\n", metrics.rise_time);
            printf("  Peak Time:        %.6f s\n", metrics.peak_time);
            printf("  Settling Time:    %.6f s\n", metrics.settling_time);
            printf("  Overshoot:        %.2f %%\n", metrics.overshoot);
            printf("  Steady-State Err: %.6f V\n", metrics.steady_state_error);
            printf("  Peak Value:       %.4f V\n", metrics.peak_value);
            printf("  Final Value:      %.4f V\n", metrics.final_value);
        } else {
            printf("  [WARN] Invalid step response data\n");
        }

        auto_tune_pid(&pid, &metrics, vref);

        printf("  -> Updated PID: Kp=%.4f, Ki=%.4f, Kd=%.4f\n",
               pid.kp, pid.ki, pid.kd);
    }

    printf("----------------------------------------\n");
    printf("\n[Final] Auto-tuned PID parameters:\n");
    printf("  Kp = %.4f\n", pid.kp);
    printf("  Ki = %.4f\n", pid.ki);
    printf("  Kd = %.4f\n", pid.kd);

    printf("\n[Verification] Running closed-loop with tuned parameters...\n");
    pid_reset(&pid);
    vout = 0.0f;
    duty = 0.5f;

    for (i = 0; i < 500; i++) {
        float control = pid_compute(&pid, vref, vout, SAMPLE_TIME_S);
        duty = 0.5f + control;
        if (duty < DUTY_MIN) duty = DUTY_MIN;
        if (duty > DUTY_MAX) duty = DUTY_MAX;
        vout = mock_dcdc_plant(duty, vout, SAMPLE_TIME_S);
    }

    printf("  Final Vout = %.4f V (Vref = %.4f V)\n", vout, vref);
    printf("  Error = %.6f V\n", fabsf(vref - vout));

    printf("\n========================================\n");
    printf("  Auto-Tuning Complete\n");
    printf("========================================\n");

    return 0;
}
