/* 模拟 GPIO 输出寄存器 */
static volatile uint32_t g_gpioa_odr = 0U;
#define GPIOA_ODR           (g_gpioa_odr)

/* 模拟比较器状态寄存器 */
static volatile uint32_t g_comp1_csr = 0U;
#define COMP1_CSR           (g_comp1_csr)

/* 模拟 DMA 传输完成标志 */
static volatile uint32_t g_dma1_isr = 0U;
#define DMA1_ISR            (g_dma1_isr)

/* 模拟系统时钟频率（Hz） */
#define SYSTEM_CLOCK_HZ     72000000UL

/* 模拟 PWM 开关频率（Hz） */
#define PWM_FREQ_HZ         100000UL

/* 模拟 PWM 周期计数值 */
#define PWM_PERIOD_TICKS    (SYSTEM_CLOCK_HZ / PWM_FREQ_HZ)

/* 模拟 ADC 参考电压（mV） */
#define ADC_VREF_MV         3300U

/* 模拟 ADC 分辨率 */
#define ADC_RESOLUTION      4096U

/* 模拟磁芯复位检测阈值（mV） */
#define CORE_RESET_THRESHOLD_MV     150U

/* 模拟磁芯饱和检测阈值（mV） */
#define CORE_SATURATION_THRESHOLD_MV 2800U

/* 模拟去抖计数 */
#define DEBOUNCE_COUNT      3U

/* ============================================================
 * 数据结构定义
 * ============================================================ */

/* 磁芯复位状态枚举 */
typedef enum {
    CORE_STATE_UNKNOWN = 0,
    CORE_STATE_RESET_OK,        /* 磁芯已复位 */
    CORE_STATE_NOT_RESET,       /* 磁芯未复位 */
    CORE_STATE_SATURATED,       /* 磁芯饱和 */
    CORE_STATE_FAULT            /* 故障 */
} CoreResetState_t;

/* 磁芯复位检测上下文 */
typedef struct {
    uint16_t adc_raw;                 /* 当前 ADC 原始值 */
    uint16_t adc_mv;                  /* 当前 ADC 电压值（mV） */
    uint16_t adc_prev_mv;             /* 上一次 ADC 电压值（mV） */
    uint16_t reset_threshold_mv;      /* 复位检测阈值 */
    uint16_t saturation_threshold_mv; /* 饱和检测阈值 */
    uint8_t  debounce_counter;        /* 去抖计数器 */
    uint8_t  debounce_target;         /* 去抖目标计数 */
    CoreResetState_t state;           /* 当前状态 */
    CoreResetState_t prev_state;      /* 上一次状态 */
    uint32_t reset_ok_count;          /* 复位成功计数 */
    uint32_t reset_fail_count;        /* 复位失败计数 */
    uint32_t saturation_count;        /* 饱和计数 */
    uint32_t total_cycles;            /* 总检测周期数 */
} CoreResetDetector_t;

/* ============================================================
 * 函数声明
 * ============================================================ */

static void     CoreResetDetector_Init(CoreResetDetector_t *det);
static uint16_t ADC_ReadRaw(void);
static uint16_t ADC_RawToMv(uint16_t raw);
static void     CoreResetDetector_Update(CoreResetDetector_t *det);
static void     CoreResetDetector_PrintStatus(const CoreResetDetector_t *det);
static void     Mock_Hardware_SimulateAdcValue(uint16_t mv);

/* ============================================================
 * 模拟硬件行为
 * ============================================================ */

/* 模拟 ADC 采样：将给定电压值写入 ADC 数据寄存器 */
static void Mock_Hardware_SimulateAdcValue(uint16_t mv)
{
    uint32_t raw;
    if (mv >= ADC_VREF_MV) {
        raw = ADC_RESOLUTION - 1U;
    } else {
        raw = ((uint32_t)mv * ADC_RESOLUTION) / ADC_VREF_MV;
    }
    ADC1_DR = (uint16_t)raw;
}

/* 读取 ADC 原始值 */
static uint16_t ADC_ReadRaw(void)
{
    return ADC1_DR;
}

/* ADC 原始值转电压（mV） */
static uint16_t ADC_RawToMv(uint16_t raw)
{
    uint32_t mv;
    mv = ((uint32_t)raw * ADC_VREF_MV) / ADC_RESOLUTION;
    if (mv > 0xFFFFU) {
        mv = 0xFFFFU;
    }
    return (uint16_t)mv;
}

/* ============================================================
 * 磁芯复位检测器实现
 * ============================================================ */

static void CoreResetDetector_Init(CoreResetDetector_t *det)
{
    if (det == NULL) {
        return;
    }
    det->adc_raw = 0U;
    det->adc_mv = 0U;
    det->adc_prev_mv = 0U;
    det->reset_threshold_mv = CORE_RESET_THRESHOLD_MV;
    det->saturation_threshold_mv = CORE_SATURATION_THRESHOLD_MV;
    det->debounce_counter = 0U;
    det->debounce_target = DEBOUNCE_COUNT;
    det->state = CORE_STATE_UNKNOWN;
    det->prev_state = CORE_STATE_UNKNOWN;
    det->reset_ok_count = 0U;
    det->reset_fail_count = 0U;
    det->saturation_count = 0U;
    det->total_cycles = 0U;
}

/*
 * 磁芯复位检测核心算法：
 * 在隔离型 DC/DC 变换器中，每个开关周期结束后需要检测
 * 变压器/电感磁芯是否完全复位。通常通过辅助绕组或
 * 采样电阻检测复位电压。
 *
 * 检测逻辑：
 *   1. 读取 ADC 采样值（代表磁芯复位电压）
 *   2. 若电压低于复位阈值，且持续 N 个周期，判定为已复位
 *   3. 若电压高于饱和阈值，判定为磁芯饱和
 *   4. 否则判定为未复位
 */
static void CoreResetDetector_Update(CoreResetDetector_t *det)
{
    if (det == NULL) {
        return;
    }

    det->total_cycles++;

    /* 1. 读取 ADC 并转换为电压值 */
    det->adc_raw = ADC_ReadRaw();
    det->adc_mv = ADC_RawToMv(det->adc_raw);

    /* 2. 状态判定 */
    if (det->adc_mv >= det->saturation_threshold_mv) {
        /* 磁芯饱和：电压超过饱和阈值 */
        det->state = CORE_STATE_SATURATED;
        det->debounce_counter = 0U;
        det->saturation_count++;
    } else if (det->adc_mv <= det->reset_threshold_mv) {
        /* 电压低于复位阈值，进行去抖确认 */
        if (det->debounce_counter < det->debounce_target) {
            det->debounce_counter++;
        }
        if (det->debounce_counter >= det->debounce_target) {
            det->state = CORE_STATE_RESET_OK;
            det->reset_ok_count++;
        } else {
            det->state = CORE_STATE_NOT_RESET;
        }
    } else {
        /* 电压在阈值之间，判定为未复位 */
        det->state = CORE_STATE_NOT_RESET;
        det->debounce_counter = 0U;
        det->reset_fail_count++;
    }

    /* 3. 状态变化记录 */
    if (det->state != det->prev_state) {
        det->prev_state = det->state;
    }

    det->adc_prev_mv = det->adc_mv;
}

static void CoreResetDetector_PrintStatus(const CoreResetDetector_t *det)
{
    const char *state_str;

    if (det == NULL) {
        return;
    }

    switch (det->state) {
        case CORE_STATE_RESET_OK:
            state_str = "RESET_OK";
            break;
        case CORE_STATE_NOT_RESET:
            state_str = "NOT_RESET";
            break;
        case CORE_STATE_SATURATED:
            state_str = "SATURATED";
            break;
        case CORE_STATE_FAULT:
            state_str = "FAULT";
            break;
        default:
            state_str = "UNKNOWN";
            break;
    }

    printf("[Cycle %lu] ADC_RAW=%4u, ADC=%4u mV, State=%-10s | "
           "OK=%lu, FAIL=%lu, SAT=%lu\n",
           (unsigned long)det->total_cycles,
           (unsigned)det->adc_raw,
           (unsigned)det->adc_mv,
           state_str,
           (unsigned long)det->reset_ok_count,
           (unsigned long)det->reset_fail_count,
           (unsigned long)det->saturation_count);
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    CoreResetDetector_t detector;
    uint16_t test_voltages_mv[] = {
        50U,    /* 远低于复位阈值 -> 复位成功 */
        80U,    /* 低于复位阈值 -> 复位成功 */
        120U,   /* 低于复位阈值 -> 复位成功 */
        200U,   /* 高于复位阈值，低于饱和阈值 -> 未复位 */
        500U,   /* 未复位 */
        1500U,  /* 未复位 */
        2900U,  /* 超过饱和阈值 -> 饱和 */
        3000U,  /* 饱和 */
        100U,   /* 复位成功 */
        60U,    /* 复位成功 */
        2500U,  /* 未复位 */
        3200U,  /* 饱和 */
        30U,    /* 复位成功 */
        40U,    /* 复位成功 */
        45U     /* 复位成功 */
    };
    uint32_t i;
    uint32_t num_tests;

    printf("========================================\n");
    printf("  Isolated DC/DC Core Reset Detection\n");
    printf("========================================\n");
    printf("Reset Threshold   : %u mV\n", (unsigned)CORE_RESET_THRESHOLD_MV);
    printf("Saturation Thresh : %u mV\n", (unsigned)CORE_SATURATION_THRESHOLD_MV);
    printf("Debounce Count    : %u\n", (unsigned)DEBOUNCE_COUNT);
    printf("PWM Frequency     : %lu Hz\n", (unsigned long)PWM_FREQ_HZ);
    printf("----------------------------------------\n");

    CoreResetDetector_Init(&detector);

    num_tests = (uint32_t)(sizeof(test_voltages_mv) / sizeof(test_voltages_mv[0]));

    for (i = 0U; i < num_tests; i++) {
