    printf("  Reset OK Count   : %lu\n", (unsigned long)detector.reset_ok_count);
    printf("  Reset Fail Count : %lu\n", (unsigned long)detector.reset_fail_count);
    printf("  Saturation Count : %lu\n", (unsigned long)detector.saturation_count);
    printf("========================================\n");

    return 0;
}
