#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 硬件寄存器定义 ================= */
typedef struct {
    volatile uint32_t DR;
    volatile uint32_t SR;
    volatile uint32_t CR;
} MockADC_TypeDef;

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t ARR;
    volatile uint32_t CCR;
    volatile uint32_t CNT;
} MockPWM_TypeDef;

/* 使用静态变量模拟寄存器，避免非法地址访问 */
static MockADC_TypeDef g_mock_adc;
static MockPWM_TypeDef g_mock_pwm;

#define MOCK_ADC            (&g_mock_adc)
#define MOCK_PWM            (&g_mock_pwm)

/* ADC 状态位 */
#define ADC_SR_EOC          (1U << 0)
/* PWM 控制位 */
#define PWM_CR_EN           (1U << 0)

/* ================= 系统参数 ================= */
#define PWM_PERIOD          1000U
#define PWM_DUTY_MIN        50U
#define PWM_DUTY_MAX        950U
#define MPPT_STEP_INIT      10U
#define MPPT_STEP_MIN       1U
#define MPPT_STEP_MAX       50U
#define POWER_THRESHOLD     0.5f
#define VOLTAGE_THRESHOLD   0.1f
#define ADC_VREF            3.3f
#define ADC_RESOLUTION      4095.0f
#define VOLTAGE_DIVIDER     11.0f
#define CURRENT_GAIN        10.0f
#define SHUNT_RESISTOR      0.01f

/* ================= 数据结构 ================= */
typedef struct {
    float voltage;
    float current;
    float power;
} PV_Data_t;

typedef struct {
    float prev_power;
    float prev_voltage;
    uint32_t duty;
    uint32_t step;
    int8_t direction;
    uint8_t initialized;
} MPPT_State_t;

/* ================= 硬件抽象层 ================= */
static void HW_ADC_StartConversion(void)
{
    MOCK_ADC->CR |= (1U << 0);
}

static uint8_t HW_ADC_IsConversionDone(void)
{
    return (MOCK_ADC->SR & ADC_SR_EOC) ? 1U : 0U;
}

static uint16_t HW_ADC_ReadValue(void)
{
    MOCK_ADC->SR &= ~ADC_SR_EOC;
    return (uint16_t)(MOCK_ADC->DR & 0x0FFFU);
}

static void HW_PWM_SetDuty(uint32_t duty)
{
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    MOCK_PWM->CCR = duty;
}

static void HW_PWM_Enable(void)
{
    MOCK_PWM->CR |= PWM_CR_EN;
}

static void HW_PWM_Disable(void)
{
    MOCK_PWM->CR &= ~PWM_CR_EN;
}

/* ================= 数据采集 (模拟) ================= */
static uint32_t g_sim_counter = 0;

static void PV_ReadData(PV_Data_t *pv)
{
    uint16_t adc_v, adc_i;
    float v, i;

    /* 模拟 ADC 转换：产生随占空比变化的电压电流 */
    /* 使用简单的模拟模型，避免死循环 */
    g_sim_counter++;

    /* 模拟电压：随占空比增大而减小 (降压变换器特性) */
    {
        float duty_ratio = (float)MOCK_PWM->CCR / (float)PWM_PERIOD;
        float sim_voltage = 36.0f - 20.0f * duty_ratio;
        float sim_current = 2.0f + 3.0f * duty_ratio - 0.5f * duty_ratio * duty_ratio;
        if (sim_current < 0.1f) sim_current = 0.1f;

        /* 转换为 ADC 原始值 */
        adc_v = (uint16_t)((sim_voltage / VOLTAGE_DIVIDER / ADC_VREF) * ADC_RESOLUTION);
        adc_i = (uint16_t)((sim_current * SHUNT_RESISTOR * CURRENT_GAIN / ADC_VREF) * ADC_RESOLUTION);
    }

    /* 写入 mock 寄存器 */
    MOCK_ADC->DR = adc_v;
    MOCK_ADC->SR |= ADC_SR_EOC;

    /* 读取电压通道 */
    HW_ADC_StartConversion();
    if (HW_ADC_IsConversionDone()) {
        adc_v = HW_ADC_ReadValue();
    }

    /* 写入电流通道 */
    MOCK_ADC->DR = adc_i;
    MOCK_ADC->SR |= ADC_SR_EOC;

    HW_ADC_StartConversion();
    if (HW_ADC_IsConversionDone()) {
        adc_i = HW_ADC_ReadValue();
    }

    /* 转换为实际物理量 */
    v = ((float)adc_v / ADC_RESOLUTION) * ADC_VREF * VOLTAGE_DIVIDER;
    i = ((float)adc_i / ADC_RESOLUTION) * ADC_VREF / (SHUNT_RESISTOR * CURRENT_GAIN);

    pv->voltage = v;
    pv->current = i;
    pv->power   = v * i;
}

/* ================= MPPT 算法 (变步长扰动观察法) ================= */
static void MPPT_Init(MPPT_State_t *mppt)
{
    mppt->prev_power   = 0.0f;
    mppt->prev_voltage = 0.0f;
    mppt->duty         = (PWM_DUTY_MIN + PWM_DUTY_MAX) / 2U;
    mppt->step         = MPPT_STEP_INIT;
    mppt->direction    = 1;
    mppt->initialized  = 0;
}

static void MPPT_Update(MPPT_State_t *mppt, const PV_Data_t *pv)
{
    float delta_power;
    float delta_voltage;

    if (!mppt->initialized) {
        mppt->prev_power   = pv->power;
        mppt->prev_voltage = pv->voltage;
        mppt->initialized  = 1;
        return;
    }

    delta_power   = pv->power - mppt->prev_power;
    delta_voltage = pv->voltage - mppt->prev_voltage;

    /* 功率变化很小，认为达到最大功率点附近，减小步长 */
    if (fabsf(delta_power) < POWER_THRESHOLD) {
        if (mppt->step > MPPT_STEP_MIN) {
            mppt->step--;
        }
    } else {
        if (mppt->step < MPPT_STEP_MAX) {
            mppt->step++;
        }
    }

    /* 扰动观察法核心逻辑 */
    if (fabsf(delta_voltage) > VOLTAGE_THRESHOLD) {
        if (delta_power > 0.0f) {
            if (delta_voltage > 0.0f) {
                mppt->direction = 1;
            } else {
                mppt->direction = -1;
            }
        } else {
            if (delta_voltage > 0.0f) {
                mppt->direction = -1;
            } else {
                mppt->direction = 1;
            }
        }
    }

    /* 更新占空比 */
    if (mppt->direction > 0) {
        if (mppt->duty + mppt->step <= PWM_DUTY_MAX) {
            mppt->duty += mppt->step;
        } else {
            mppt->duty = PWM_DUTY_MAX;
            mppt->direction = -1;
        }
    } else {
        if (mppt->duty >= mppt->step + PWM_DUTY_MIN) {
            mppt->duty -= mppt->step;
        } else {
            mppt->duty = PWM_DUTY_MIN;
            mppt->direction = 1;
        }
    }

    mppt->prev_power   = pv->power;
    mppt->prev_voltage = pv->voltage;
}

/* ================= 主函数 ================= */
int main(void)
{
    PV_Data_t pv;
    MPPT_State_t mppt;
    uint32_t loop_count;

    printf("========================================\n");
    printf("  光伏 DC/DC 变换器 MPPT 协同控制算法\n");
    printf("  算法: 变步长扰动观察法 (P&O)\n");
    printf("========================================\n\n");

    /* 初始化 */
    MPPT_Init(&mppt);
    HW_PWM_SetDuty(mppt.duty);
    HW_PWM_Enable();

    printf("初始占空比: %u / %u (%.1f%%)\n\n",
           mppt.duty, PWM_PERIOD,
           (float)mppt.duty / PWM_PERIOD * 100.0f);

    /* 模拟控制循环 */
    for (loop_count = 0; loop_count < 20; loop_count++) {
        PV_ReadData(&pv);
        MPPT_Update(&mppt, &pv);
        HW_PWM_SetDuty(mppt.duty);

        printf("[%02u] V=%6.2fV  I=%5.2fA  P=%6.2fW  "
               "Duty=%4u(%.1f%%)  Step=%2u  Dir=%+d\n",
               loop_count,
               pv.voltage,
               pv.current,
               pv.power,
               mppt.duty,
               (float)mppt.duty / PWM_PERIOD * 100.0f,
               mppt.step,
               mppt.direction);
    }

    HW_PWM_Disable();

    printf("\n========================================\n");
    printf("  MPPT 控制循环结束\n");
    printf("  最终占空比: %u / %u (%.1f%%)\n",
           mppt.duty, PWM_PERIOD,
           (float)mppt.duty / PWM_PERIOD * 100.0f);
    printf("========================================\n");

    return 0;
}
