    ADC_VIN_REG = 24000U;
    FAULT_STATUS_REG = 0;
    FAULT_CLEAR_REG = 0;
}

static void mock_hw_pwm_enable(void)
{
    PWM_CTRL_REG |= PWM_ENABLE_BIT;
    PWM_CTRL_REG &= ~PWM_DISABLE_BIT;
    g_pwm_enabled = true;
}

static void mock_hw_pwm_disable(void)
{
    PWM_CTRL_REG |= PWM_DISABLE_BIT;
    PWM_CTRL_REG &= ~PWM_ENABLE_BIT;
    PWM_DUTY_REG = 0;
    g_pwm_enabled = false;
}

static uint32_t mock_hw_read_vout_mv(void)
{
    return ADC_VOUT_REG;
}

static uint32_t mock_hw_read_iout_ma(void)
{
    return ADC_IOUT_REG;
}

static uint32_t mock_hw_read_vin_mv(void)
{
    return ADC_VIN_REG;
}

static uint32_t mock_hw_read_fault(void)
{
    return FAULT_STATUS_REG;
}

static void mock_hw_clear_fault(void)
{
    FAULT_CLEAR_REG = 0xFFFFFFFFU;
    FAULT_STATUS_REG = 0;
}

/* ==================== 时间管理 ==================== */
static uint32_t get_tick_ms(void)
{
    return g_system_tick_ms;
}

static void delay_ms(uint32_t ms)
{
    g_system_tick_ms += ms;
}

/* ==================== 故障检测 ==================== */
static uint32_t detect_fault(void)
{
    uint32_t fault = 0;
    uint32_t vout = mock_hw_read_vout_mv();
    uint32_t iout = mock_hw_read_iout_ma();
    uint32_t vin = mock_hw_read_vin_mv();
    uint32_t hw_fault = mock_hw_read_fault();

    if (hw_fault != 0) {
        fault |= hw_fault;
    }

    if (vout > VOUT_OVP_MV) {
        fault |= FAULT_OVP;
    }

    if (iout > IOUT_OCP_MA) {
        fault |= FAULT_OCP;
    }

    if (vin < VOUT_UVLO_MV) {
        fault |= FAULT_UVLO;
    }

    return fault;
}

/* ==================== 故障处理 ==================== */
static void enter_state(DCDC_State_t new_state)
{
    g_state = new_state;
    g_state_entry_time_ms = get_tick_ms();
}

static void handle_fault(uint32_t fault_code)
{
    g_fault_record.fault_code = fault_code;
    g_fault_record.timestamp_ms = get_tick_ms();

    printf("[FAULT] Code=0x%08X at %u ms\n", fault_code, get_tick_ms());

    mock_hw_pwm_disable();
    enter_state(STATE_SHUTDOWN);
}

static bool can_restart(void)
{
    uint32_t now = get_tick_ms();

    if (g_restart_attempts >= MAX_RESTART_ATTEMPTS) {
        if ((now - g_restart_window_start_ms) > RESTART_WINDOW_MS) {
            g_restart_attempts = 0;
            g_restart_window_start_ms = now;
            printf("[RESTART] Window expired, reset attempt counter\n");
        } else {
            return false;
        }
    }

    return true;
}

static void attempt_restart(void)
{
    if (!can_restart()) {
        printf("[RESTART] Max attempts reached, permanent fault\n");
        enter_state(STATE_PERMANENT_FAULT);
        return;
    }

    g_restart_attempts++;
    g_fault_record.restart_count++;
    g_fault_record.last_restart_time_ms = get_tick_ms();

    printf("[RESTART] Attempt %u/%u at %u ms\n",
           g_restart_attempts, MAX_RESTART_ATTEMPTS, get_tick_ms());

    mock_hw_clear_fault();
    mock_hw_pwm_enable();
    enter_state(STATE_RESTART_ATTEMPT);
}

/* ==================== 状态机主循环 ==================== */
static void dcdc_state_machine(void)
{
    uint32_t fault;
    uint32_t elapsed;

    switch (g_state) {
    case STATE_INIT:
        printf("[STATE] INIT\n");
        mock_hw_init();
        g_restart_attempts = 0;
        g_restart_window_start_ms = get_tick_ms();
        g_fault_record.restart_count = 0;
        enter_state(STATE_RUNNING);
        break;

    case STATE_RUNNING:
        fault = detect_fault();
        if (fault != 0) {
            handle_fault(fault);
        } else {
            if (!g_pwm_enabled) {
                mock_hw_pwm_enable();
            }
        }
        break;

    case STATE_FAULT_DETECTED:
        enter_state(STATE_SHUTDOWN);
        break;

    case STATE_SHUTDOWN:
        mock_hw_pwm_disable();
        elapsed = get_tick_ms() - g_state_entry_time_ms;
        if (elapsed >= RESTART_DELAY_MS) {
            enter_state(STATE_WAIT_RESTART);
        }
        break;

    case STATE_WAIT_RESTART:
        attempt_restart();
        break;

    case STATE_RESTART_ATTEMPT:
        fault = detect_fault();
        if (fault != 0) {
            printf("[RESTART] Failed, fault=0x%08X\n", fault);
            handle_fault(fault);
        } else {
            elapsed = get_tick_ms() - g_state_entry_time_ms;
            if (elapsed >= 100U) {
                printf("[RESTART] Success, back to RUNNING\n");
                enter_state(STATE_RUNNING);
            }
        }
        break;

    case STATE_PERMANENT_FAULT:
        mock_hw_pwm_disable();
        printf("[STATE] PERMANENT FAULT - manual intervention required\n");
        break;

    default:
        enter_state(STATE_INIT);
        break;
    }
}

/* ==================== 测试辅助函数 ==================== */
static void simulate_ovp(void)
{
    printf("\n--- Simulating OVP (Vout > %u mV) ---\n", VOUT_OVP_MV);
    ADC_VOUT_REG = VOUT_OVP_MV + 1000U;
}

static void simulate_ocp(void)
{
    printf("\n--- Simulating OCP (Iout > %u mA) ---\n", IOUT_OCP_MA);
    ADC_IOUT_REG = IOUT_OCP_MA + 1000U;
}

static void clear_simulation(void)
{
    ADC_VOUT_REG = VOUT_NOMINAL_MV;
    ADC_IOUT_REG = IOUT_NOMINAL_MA;
    ADC_VIN_REG = 24000U;
    mock_hw_clear_fault();
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t loop_count = 0;

    printf("========================================\n");
    printf("  DC/DC Converter Fault Recovery Test\n");
    printf("========================================\n");

    /* 初始化 */
    dcdc_state_machine();

    /* 正常运行阶段 */
    printf("\n[TEST] Normal operation for 500ms\n");
    for (loop_count = 0; loop_count < 5; loop_count++) {
        delay_ms(100);
        dcdc_state_machine();
    }

    /* 测试1: 过压故障 -> 自动重启 */
    printf("\n[TEST] Test 1: OVP fault and auto-restart\n");
    simulate_ovp();
    for (loop_count = 0; loop_count < 20; loop_count++) {
        delay_ms(100);
        dcdc_state_machine();
        if (g_state == STATE_RUNNING && loop_count > 5) {
            break;
        }
    }
    clear_simulation();

    /* 测试2: 过流故障 -> 自动重启 */
    printf("\n[TEST] Test 2: OCP fault and auto-restart\n");
    simulate_ocp();
    for (loop_count = 0; loop_count < 20; loop_count++) {
        delay_ms(100);
        dcdc_state_machine();
        if (g_state == STATE_RUNNING && loop_count > 5) {
            break;
        }
    }
    clear_simulation();

    /* 测试3: 连续故障 -> 达到最大重启次数 -> 永久故障 */
    printf("\n[TEST] Test 3: Repeated faults -> permanent fault\n");
    for (loop_count = 0; loop_count < 50; loop_count++) {
        if (g_state == STATE_RUNNING) {
            simulate_ovp();
        }
        delay_ms(100);
        dcdc_state_machine();
        if (g_state == STATE_PERMANENT_FAULT) {
            break;
        }
    }

    printf("\n[TEST] Final state: %d\n", (int)g_state);
    printf("[TEST] Total restart attempts: %u\n", g_restart_attempts);
    printf("[TEST] PWM enabled: %s\n", g_pwm_enabled ? "YES" : "NO");

    printf("\n========================================\n");
    printf("  Test Complete\n");
    printf("========================================\n");

    return 0;
}
