#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define MOCK_ADC_RESOLUTION     4096.0f
#define MOCK_VREF               3.3f

#define MOCK_TEMP_MIN_C         (-40.0f)
#define MOCK_TEMP_MAX_C         (85.0f)
#define MOCK_TEMP_ADC_MIN        200.0f
#define MOCK_TEMP_ADC_MAX        3800.0f

#define MOCK_PWM_PERIOD         1000U
#define MOCK_PWM_MAX_DUTY       1000U

/* 使用普通全局变量模拟寄存器，避免非法地址访问 */
static volatile uint32_t g_adc_data_reg   = 0;
static volatile uint32_t g_pwm_duty_reg   = 0;
static volatile uint32_t g_temp_adc_reg   = 0;

#define REG_READ(reg)           (reg)
#define REG_WRITE(reg, val)     ((reg) = (uint32_t)(val))

/* ================= 系统参数定义 ================= */
#define VOUT_TARGET             12.0f
#define TEMP_COMP_ENABLE        1

#define TEMP_COEFF_VREF         (-0.0005f)
#define TEMP_COEFF_GAIN         (0.0003f)
#define TEMP_COEFF_OFFSET       (0.001f)

#define TEMP_SEG1               (-20.0f)
#define TEMP_SEG2               (25.0f)
#define TEMP_SEG3               (60.0f)

/* ================= 数据结构 ================= */
typedef struct {
    float temperature;
    float vout_measured;
    float vout_target;
    float duty_cycle;
    float comp_vref;
    float comp_gain;
    float comp_offset;
    uint32_t pwm_duty;
} DCDC_Comp_t;

/* ================= 函数声明 ================= */
static float adc_to_voltage(uint32_t adc_val);
static float adc_to_temperature(uint32_t adc_val);
static float read_temperature(void);
static float read_vout(void);
static void  write_pwm_duty(uint32_t duty);
static void  temp_compensation_init(DCDC_Comp_t *comp);
static void  temp_compensation_update(DCDC_Comp_t *comp, float temp);
static float temp_compensation_calc_duty(DCDC_Comp_t *comp, float vout_meas);
static void  dcdc_control_loop(DCDC_Comp_t *comp);

/* ================= 函数实现 ================= */
static float adc_to_voltage(uint32_t adc_val)
{
    return ((float)adc_val / MOCK_ADC_RESOLUTION) * MOCK_VREF;
}

static float adc_to_temperature(uint32_t adc_val)
{
    float ratio = ((float)adc_val - MOCK_TEMP_ADC_MIN) /
                  (MOCK_TEMP_ADC_MAX - MOCK_TEMP_ADC_MIN);
    return MOCK_TEMP_MIN_C + ratio * (MOCK_TEMP_MAX_C - MOCK_TEMP_MIN_C);
}

static float read_temperature(void)
{
    uint32_t adc_val = REG_READ(g_temp_adc_reg);
    return adc_to_temperature(adc_val);
}

static float read_vout(void)
{
    uint32_t adc_val = REG_READ(g_adc_data_reg);
    return adc_to_voltage(adc_val);
}

static void write_pwm_duty(uint32_t duty)
{
    if (duty > MOCK_PWM_MAX_DUTY) {
        duty = MOCK_PWM_MAX_DUTY;
    }
    REG_WRITE(g_pwm_duty_reg, duty);
}

static void temp_compensation_init(DCDC_Comp_t *comp)
{
    comp->temperature   = 25.0f;
    comp->vout_measured = 0.0f;
    comp->vout_target   = VOUT_TARGET;
    comp->duty_cycle    = 0.5f;
    comp->comp_vref     = 1.25f;
    comp->comp_gain     = 1.0f;
    comp->comp_offset   = 0.0f;
    comp->pwm_duty      = MOCK_PWM_PERIOD / 2;
}

static void temp_compensation_update(DCDC_Comp_t *comp, float temp)
{
    float delta_t = temp - 25.0f;
    float seg_factor = 1.0f;

    if (temp < TEMP_SEG1) {
        seg_factor = 1.5f;
    } else if (temp < TEMP_SEG2) {
        seg_factor = 1.0f;
    } else if (temp < TEMP_SEG3) {
        seg_factor = 1.2f;
    } else {
        seg_factor = 1.8f;
    }

    comp->comp_vref   = 1.25f + TEMP_COEFF_VREF   * delta_t * seg_factor;
    comp->comp_gain   = 1.0f  + TEMP_COEFF_GAIN   * delta_t * seg_factor;
    comp->comp_offset = 0.0f  + TEMP_COEFF_OFFSET * delta_t * seg_factor;

    if (comp->comp_vref < 0.8f)  comp->comp_vref = 0.8f;
    if (comp->comp_vref > 1.8f)  comp->comp_vref = 1.8f;
    if (comp->comp_gain < 0.7f)  comp->comp_gain = 0.7f;
    if (comp->comp_gain > 1.3f)  comp->comp_gain = 1.3f;
    if (comp->comp_offset < -0.1f) comp->comp_offset = -0.1f;
    if (comp->comp_offset > 0.1f)  comp->comp_offset = 0.1f;
}

static float temp_compensation_calc_duty(DCDC_Comp_t *comp, float vout_meas)
{
    float error;
    float duty;

    error = (comp->vout_target - vout_meas) * comp->comp_gain + comp->comp_offset;
    duty = comp->duty_cycle + error * 0.1f;

    if (duty < 0.05f) duty = 0.05f;
    if (duty > 0.95f) duty = 0.95f;

    return duty;
}

static void dcdc_control_loop(DCDC_Comp_t *comp)
{
    float temp;
    float vout;
    float duty;

    temp = read_temperature();
    comp->temperature = temp;

    vout = read_vout();
    comp->vout_measured = vout;

#if TEMP_COMP_ENABLE
    temp_compensation_update(comp, temp);
#endif

    duty = temp_compensation_calc_duty(comp, vout);
    comp->duty_cycle = duty;

    comp->pwm_duty = (uint32_t)(duty * (float)MOCK_PWM_PERIOD);
    write_pwm_duty(comp->pwm_duty);
}

/* ================= 主函数 ================= */
int main(void)
{
    DCDC_Comp_t comp;
    int i;

    float test_temps[7] = {-40.0f, -20.0f, 0.0f, 25.0f, 50.0f, 70.0f, 85.0f};
    int num_temps = 7;

    printf("========================================\n");
    printf("  宽温DC/DC变换器参数补偿测试\n");
    printf("  温度范围: -40C ~ 85C\n");
    printf("========================================\n\n");

    temp_compensation_init(&comp);

    for (i = 0; i < num_temps; i++) {
        float temp = test_temps[i];
        float ratio = (temp - MOCK_TEMP_MIN_C) / (MOCK_TEMP_MAX_C - MOCK_TEMP_MIN_C);
        uint32_t temp_adc = (uint32_t)(MOCK_TEMP_ADC_MIN + ratio * (MOCK_TEMP_ADC_MAX - MOCK_TEMP_ADC_MIN));
        float vout_sim;
        uint32_t vout_adc;

        REG_WRITE(g_temp_adc_reg, temp_adc);

        vout_sim = VOUT_TARGET + (temp - 25.0f) * 0.01f;
        vout_adc = (uint32_t)((vout_sim / MOCK_VREF) * MOCK_ADC_RESOLUTION);
        REG_WRITE(g_adc_data_reg, vout_adc);

        dcdc_control_loop(&comp);

        printf("温度: %6.1fC | 实测Vout: %6.3fV | 补偿Vref: %6.4fV | "
               "补偿Gain: %6.4f | 补偿Offset: %7.5f | 占空比: %5.2f%% | PWM: %4u\n",
               comp.temperature,
               comp.vout_measured,
               comp.comp_vref,
               comp.comp_gain,
               comp.comp_offset,
               comp.duty_cycle * 100.0f,
               comp.pwm_duty);
    }

    printf("\n========================================\n");
    printf("  测试完成\n");
    printf("========================================\n");

    return 0;
}
