```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 硬件寄存器定义 ================= */
static volatile uint32_t g_adc_dr = 0;
static volatile uint32_t g_adc_cr2 = 0;
static volatile uint32_t g_tim1_ccr1 = 0;
static volatile uint32_t g_tim1_arr = 0;
static volatile uint32_t g_tim1_cr1 = 0;
static volatile uint32_t g_gpioa_moder = 0;
static volatile uint32_t g_gpioa_odr = 0;

#define ADC1_DR             (g_adc_dr)
#define ADC1_CR2            (g_adc_cr2)
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_SWSTART     (1U << 30)

#define TIM1_CCR1           (g_tim1_ccr1)
#define TIM1_ARR            (g_tim1_arr)
#define TIM1_CR1            (g_tim1_cr1)
#define TIM_CR1_CEN         (1U << 0)

#define GPIOA_MODER         (g_gpioa_moder)
#define GPIOA_ODR           (g_gpioa_odr)

/* ================= 系统参数 ================= */
#define PWM_PERIOD          1000U
#define PWM_MIN_DUTY        50U
#define PWM_MAX_DUTY        950U
#define MPPT_STEP_INIT      10U
#define MPPT_STEP_MIN       1U
#define MPPT_STEP_MAX       50U
#define MPPT_POWER_TH       0.5f
#define MPPT_VOLTAGE_MIN    5.0f
#define MPPT_VOLTAGE_MAX    40.0f
#define MPPT_CURRENT_MAX    10.0f

/* ================= 数据结构 ================= */
typedef struct {
    float voltage;
    float current;
    float power;
    float prev_voltage;
    float prev_power;
    float duty;
    float step;
    int   direction;
    int   initialized;
} MPPT_State_t;

typedef struct {
    float kp;
    float ki;
    float integral;
    float out_min;
    float out_max;
} PI_Controller_t;

/* ================= 全局变量 ================= */
static MPPT_State_t g_mppt;
static PI_Controller_t g_voltage_pi;

/* ================= 硬件抽象层 ================= */
static void HAL_Init(void)
{
    ADC1_CR2 |= ADC_CR2_ADON;
    TIM1_CR1 |= TIM_CR1_CEN;
    TIM1_ARR = PWM_PERIOD;
    GPIOA_MODER &= ~(3U << 10);
    GPIOA_MODER |=  (2U << 10);
}

static float HAL_ReadVoltage(void)
{
    uint32_t raw = ADC1_DR & 0x0FFFU;
    return (float)raw * 3.3f / 4095.0f * 11.0f;
}

static float HAL_ReadCurrent(void)
{
    uint32_t raw = ADC1_DR & 0x0FFFU;
    return (float)raw * 3.3f / 4095.0f / 0.1f;
}

static void HAL_SetPWM(float duty)
{
    uint32_t ccr;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    ccr = (uint32_t)(duty * (float)PWM_PERIOD);
    if (ccr < PWM_MIN_DUTY) ccr = PWM_MIN_DUTY;
    if (ccr > PWM_MAX_DUTY) ccr = PWM_MAX_DUTY;
    TIM1_CCR1 = ccr;
}

/* ================= PI 控制器 ================= */
static void PI_Init(PI_Controller_t *pi, float kp, float ki, float min, float max)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_min = min;
    pi->out_max = max;
}

static float PI_Compute(PI_Controller_t *pi, float error, float dt)
{
    float p, out;
    p = pi->kp * error;
    pi->integral += pi->ki * error * dt;
    if (pi->integral > pi->out_max) pi->integral = pi->out_max;
    if (pi->integral < pi->out_min) pi->integral = pi->out_min;
    out = p + pi->integral;
    if (out > pi->out_max) out = pi->out_max;
    if (out < pi->out_min) out = pi->out_min;
    return out;
}

/* ================= MPPT 扰动观察法 ================= */
static void MPPT_Init(MPPT_State_t *m)
{
    m->voltage = 0.0f;
    m->current = 0.0f;
    m->power = 0.0f;
    m->prev_voltage = 0.0f;
    m->prev_power = 0.0f;
    m->duty = 0.5f;
    m->step = (float)MPPT_STEP_INIT;
    m->direction = 1;
    m->initialized = 0;
}

static float MPPT_Update(MPPT_State_t *m, float v, float i)
{
    float dP, dV;

    m->voltage = v;
    m->current = i;
    m->power = v * i;

    if (!m->initialized) {
        m->prev_voltage = v;
        m->prev_power = m->power;
        m->initialized = 1;
        return m->duty;
    }

    dP = m->power - m->prev_power;
    dV = m->voltage - m->prev_voltage;

    if (fabsf(dP) > MPPT_POWER_TH) {
        if (dP > 0.0f) {
            if (dV > 0.0f) {
                m->direction = 1;
            } else {
                m->direction = -1;
            }
        } else {
            if (dV > 0.0f) {
                m->direction = -1;
            } else {
                m->direction = 1;
            }
        }
        if (fabsf(dP) > 2.0f * MPPT_POWER_TH) {
            m->step += 1.0f;
            if (m->step > (float)MPPT_STEP_MAX) m->step = (float)MPPT_STEP_MAX;
        } else {
            m->step -= 0.5f;
            if (m->step < (float)MPPT_STEP_MIN) m->step = (float)MPPT_STEP_MIN;
        }
    }

    m->duty += (float)m->direction * m->step / (float)PWM_PERIOD;

    if (m->duty < 0.05f) m->duty = 0.05f;
    if (m->duty > 0.95f) m->duty = 0.95f;

    m->prev_voltage = m->voltage;
    m->prev_power = m->power;

    return m->duty;
}

/* ================= 协同控制主循环 ================= */
static void MPPT_CooperativeControl(float dt)
{
    float v, i, duty_mppt, v_ref, v_error, duty_pi, duty_final;

    v = HAL_ReadVoltage();
    i = HAL_ReadCurrent();

    if (v < MPPT_VOLTAGE_MIN || v > MPPT_VOLTAGE_MAX || i > MPPT_CURRENT_MAX) {
        HAL_SetPWM(0.0f);
        printf("[PROTECT] V=%.2f I=%.2f -> PWM OFF\n", v, i);
        return;
    }

    duty_mppt = MPPT_Update(&g_mppt, v, i);

    v_ref = 0.78f * MPPT_VOLTAGE_MAX;
    v_error = v_ref - v;
    duty_pi = PI_Compute(&g_voltage_pi, v_error, dt);

    duty_final = 0.7f * duty_mppt + 0.3f * duty_pi;

    if (duty_final < 0.05f) duty_final = 0.05f;
    if (duty_final > 0.95f) duty_final = 0.95f;

    HAL_SetPWM(duty_final);

    printf("[MPPT] V=%.2fV I=%.2fA P=%.2fW Duty=%.3f Step=%.1f Dir=%d\n",
           v, i, g_mppt.power, duty_final, g_mppt.step, g_mppt.direction);
}

/* ================= 主函数 ================= */
int main(void)
{
    const float dt = 0.01f;
    int cycle;

    printf("=== Photovoltaic DC/DC MPPT Cooperative Control ===\n");

    HAL_Init();
    MPPT_Init(&g_mppt);
    PI_Init(&g_voltage_pi, 0.5f, 0.1f, 0.0f, 1.0f);

    for (cycle = 0; cycle < 20; cycle++) {
        float sim_v, sim_i;
        uint32_t raw;

        sim_v = 18.0f + 2.0f * sinf((float)cycle * 0.3f);
        sim_i = 5.0f - 0.1f * (float)cycle + 0.5f * cosf((float)cycle * 0.2f);
        if (sim_i < 0.1f) sim_i = 0.1f;

        raw = (uint32_t)(sim_v / 11.0f / 3.3f * 4095.0f);
        ADC1_DR = raw & 0x0FFFU;

        printf("--- Cycle %d ---\n", cycle);
        MPPT_CooperativeControl(dt);
    }

    printf("=== Control Loop Finished ===\n");
    return 0;
}
