/* ================= Mock 寄存器与硬件抽象 ================= */
static float mock_adc_soc = 0.0f;
static float mock_adc_vbat = 0.0f;
static float mock_adc_ibat = 0.0f;
static float mock_pwm_duty = 0.0f;
static unsigned int mock_ctrl_enable = 0;

#define REG_ADC_SOC          (mock_adc_soc)
#define REG_ADC_VBAT         (mock_adc_vbat)
#define REG_ADC_IBAT         (mock_adc_ibat)
#define REG_PWM_DUTY         (mock_pwm_duty)
#define REG_CTRL_ENABLE      (mock_ctrl_enable)

/* ================= 系统参数 ================= */
#define SOC_MIN              0.10f
#define SOC_MAX              0.90f
#define SOC_REF              0.50f
#define VBAT_NOMINAL         48.0f
#define IBAT_CHARGE_MAX      10.0f
#define IBAT_DISCHARGE_MAX   10.0f
#define DUTY_MIN             0.05f
#define DUTY_MAX             0.95f
#define TS                   0.001f

/* ================= 控制器参数 ================= */
#define KP                   0.8f
#define KI                   0.05f
#define KD                   0.01f

/* ================= 数据结构 ================= */
typedef struct {
    float soc;
    float vbat;
    float ibat;
    float duty;
    float integral;
    float prev_error;
    float prev_soc;
    float soc_rate;
    float i_ref;
    unsigned int enable;
} DCDC_SOC_Ctrl_t;

/* ================= 函数声明 ================= */
static void DCDC_SOC_Init(DCDC_SOC_Ctrl_t *ctrl);
static float DCDC_SOC_Control(DCDC_SOC_Ctrl_t *ctrl, float soc_ref);
static float Clamp(float val, float min, float max);
static void DCDC_SOC_Update(DCDC_SOC_Ctrl_t *ctrl);

/* ================= 初始化 ================= */
static void DCDC_SOC_Init(DCDC_SOC_Ctrl_t *ctrl)
{
    ctrl->soc = 0.0f;
    ctrl->vbat = 0.0f;
    ctrl->ibat = 0.0f;
    ctrl->duty = 0.5f;
    ctrl->integral = 0.0f;
    ctrl->prev_error = 0.0f;
    ctrl->prev_soc = 0.0f;
    ctrl->soc_rate = 0.0f;
    ctrl->i_ref = 0.0f;
    ctrl->enable = 0;
}

/* ================= 限幅函数 ================= */
static float Clamp(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

/* ================= SOC 闭环控制核心 ================= */
static float DCDC_SOC_Control(DCDC_SOC_Ctrl_t *ctrl, float soc_ref)
{
    float error;
    float derivative;
    float output;

    /* 1. 计算 SOC 误差 */
    error = soc_ref - ctrl->soc;

    /* 2. 计算 SOC 变化率 (用于前馈) */
    ctrl->soc_rate = (ctrl->soc - ctrl->prev_soc) / TS;
    ctrl->prev_soc = ctrl->soc;

    /* 3. PID 计算 */
    ctrl->integral += error * TS;
    ctrl->integral = Clamp(ctrl->integral, -1.0f, 1.0f);

    derivative = (error - ctrl->prev_error) / TS;
    ctrl->prev_error = error;

    output = KP * error + KI * ctrl->integral + KD * derivative;

    /* 4. 根据 SOC 状态决定充放电方向 */
    if (ctrl->soc < SOC_MIN) {
        ctrl->i_ref = IBAT_CHARGE_MAX;
    } else if (ctrl->soc > SOC_MAX) {
        ctrl->i_ref = -IBAT_DISCHARGE_MAX;
    } else {
        ctrl->i_ref = output * IBAT_CHARGE_MAX;
        ctrl->i_ref = Clamp(ctrl->i_ref, -IBAT_DISCHARGE_MAX, IBAT_CHARGE_MAX);
    }

    /* 5. 电流环简化：根据电流参考计算占空比 */
    if (ctrl->i_ref >= 0.0f) {
        ctrl->duty = 0.5f + 0.4f * (ctrl->i_ref / IBAT_CHARGE_MAX);
    } else {
        ctrl->duty = 0.5f - 0.4f * (fabsf(ctrl->i_ref) / IBAT_DISCHARGE_MAX);
    }

    /* 6. 占空比限幅 */
    ctrl->duty = Clamp(ctrl->duty, DUTY_MIN, DUTY_MAX);

    return ctrl->duty;
}

/* ================= 更新硬件寄存器 ================= */
static void DCDC_SOC_Update(DCDC_SOC_Ctrl_t *ctrl)
{
    REG_PWM_DUTY = ctrl->duty;
    REG_CTRL_ENABLE = ctrl->enable;
}

/* ================= 主函数 ================= */
int main(void)
{
    DCDC_SOC_Ctrl_t ctrl;
    float soc_ref = SOC_REF;
    int i;

    printf("===== 储能 DC/DC 变换器 SOC 闭环控制 =====\n");
    printf("SOC 参考值: %.2f\n", soc_ref);
    printf("PID 参数: Kp=%.2f, Ki=%.2f, Kd=%.2f\n", KP, KI, KD);
    printf("------------------------------------------\n");

    DCDC_SOC_Init(&ctrl);
    ctrl.enable = 1;

    for (i = 0; i < 20; i++) {
        ctrl.soc = 0.30f + 0.02f * (float)i;
        ctrl.vbat = VBAT_NOMINAL;
        ctrl.ibat = ctrl.i_ref;

        DCDC_SOC_Control(&ctrl, soc_ref);
        DCDC_SOC_Update(&ctrl);

        printf("Step %2d | SOC=%.3f | Vbat=%.1fV | Iref=%+.2fA | Duty=%.3f | PWM=%.3f\n",
               i, ctrl.soc, ctrl.vbat, ctrl.i_ref, ctrl.duty, REG_PWM_DUTY);
    }

    printf("------------------------------------------\n");
    printf("控制完成，最终占空比: %.3f\n", ctrl.duty);
    printf("==========================================\n");

    return 0;
}
