#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static uint16_t mock_adc_udc = 0;
static int16_t  mock_adc_iac = 0;
static int16_t  mock_adc_uac = 0;
static uint16_t mock_pwm_duty = 0;
static uint32_t mock_sys_tick = 0;

#define MOCK_REG_ADC_Udc        (mock_adc_udc)
#define MOCK_REG_ADC_Iac        (mock_adc_iac)
#define MOCK_REG_ADC_Uac        (mock_adc_uac)
#define MOCK_REG_PWM_DUTY       (mock_pwm_duty)
#define MOCK_REG_SYS_TICK       (mock_sys_tick)

/* ================= 系统参数定义 ================= */
#define PI                      3.14159265358979f
#define TS                      1.0e-4f
#define GRID_FREQ               50.0f
#define OMEGA_GRID              (2.0f * PI * GRID_FREQ)
#define UDC_REF                 400.0f
#define UDC_NOMINAL             400.0f
#define C_DC_PHYS               2200.0e-6f
#define K_VIRTUAL_CAP           0.02f
#define K_P_UDC                 0.5f
#define K_I_UDC                 20.0f
#define K_P_CURRENT             8.0f
#define K_I_CURRENT             200.0f
#define UDC_LIMIT               450.0f
#define UDC_LOW_LIMIT           350.0f
#define IAC_LIMIT               20.0f

/* ================= 数据结构 ================= */
typedef struct {
    float Udc;
    float Uac;
    float Iac;
    float Udc_ref;
    float Iac_ref;
    float Iac_ref_peak;
    float theta;
    float sin_theta;
    float sin_theta_prev;
    float cos_theta;
    float Pdc;
    float Pac;
    float Pdc_ripple;
    float Pdc_ripple_comp;
    float Udc_comp;
    float Udc_err;
    float Udc_err_int;
    float Iac_err;
    float Iac_err_int;
    float duty;
    float virtual_cap_energy;
    float virtual_cap_power;
    float virtual_cap_voltage;
    float virtual_cap_current;
    float Pdc_avg;
    float Pdc_avg_filter;
    float Pdc_ripple_filter;
    float Udc_ripple;
    float Udc_ripple_filter;
    float Udc_ripple_comp;
    float Udc_ripple_comp_filter;
    float Udc_ripple_comp_gain;
    float Udc_ripple_comp_limit;
    float Udc_ripple_comp_out;
    float Udc_ripple_comp_out_filter;
    float Udc_ripple_comp_out_gain;
    float Udc_ripple_comp_out_limit;
    float Udc_ripple_comp_out_int;
    float Udc_ripple_comp_out_int_limit;
    float Udc_ripple_comp_out_int_gain;
    float Udc_ripple_comp_out_int_out;
    float Udc_ripple_comp_out_int_out_filter;
    float Udc_ripple_comp_out_int_out_gain;
    float Udc_ripple_comp_out_int_out_limit;
} InverterCtrl_t;

/* ================= 工具函数 ================= */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

static float low_pass_filter(float input, float prev, float alpha)
{
    return prev + alpha * (input - prev);
}

/* ================= 初始化 ================= */
static void InverterCtrl_Init(InverterCtrl_t *ctrl)
{
    ctrl->Udc = UDC_NOMINAL;
    ctrl->Uac = 0.0f;
    ctrl->Iac = 0.0f;
    ctrl->Udc_ref = UDC_REF;
    ctrl->Iac_ref = 0.0f;
    ctrl->Iac_ref_peak = 0.0f;
    ctrl->theta = 0.0f;
    ctrl->sin_theta = 0.0f;
    ctrl->sin_theta_prev = 0.0f;
    ctrl->cos_theta = 1.0f;
    ctrl->Pdc = 0.0f;
    ctrl->Pac = 0.0f;
    ctrl->Pdc_ripple = 0.0f;
    ctrl->Pdc_ripple_comp = 0.0f;
    ctrl->Udc_comp = 0.0f;
    ctrl->Udc_err = 0.0f;
    ctrl->Udc_err_int = 0.0f;
    ctrl->Iac_err = 0.0f;
    ctrl->Iac_err_int = 0.0f;
    ctrl->duty = 0.5f;
    ctrl->virtual_cap_energy = 0.0f;
    ctrl->virtual_cap_power = 0.0f;
    ctrl->virtual_cap_voltage = 0.0f;
    ctrl->virtual_cap_current = 0.0f;
    ctrl->Pdc_avg = 0.0f;
    ctrl->Pdc_avg_filter = 0.0f;
    ctrl->Pdc_ripple_filter = 0.0f;
    ctrl->Udc_ripple = 0.0f;
    ctrl->Udc_ripple_filter = 0.0f;
    ctrl->Udc_ripple_comp = 0.0f;
    ctrl->Udc_ripple_comp_filter = 0.0f;
    ctrl->Udc_ripple_comp_gain = 0.5f;
    ctrl->Udc_ripple_comp_limit = 20.0f;
    ctrl->Udc_ripple_comp_out = 0.0f;
    ctrl->Udc_ripple_comp_out_filter = 0.0f;
    ctrl->Udc_ripple_comp_out_gain = 0.5f;
    ctrl->Udc_ripple_comp_out_limit = 20.0f;
    ctrl->Udc_ripple_comp_out_int = 0.0f;
    ctrl->Udc_ripple_comp_out_int_limit = 20.0f;
    ctrl->Udc_ripple_comp_out_int_gain = 0.5f;
    ctrl->Udc_ripple_comp_out_int_out = 0.0f;
    ctrl->Udc_ripple_comp_out_int_out_filter = 0.0f;
    ctrl->Udc_ripple_comp_out_int_out_gain = 0.5f;
    ctrl->Udc_ripple_comp_out_int_out_limit = 20.0f;
}

/* ================= 采样 ================= */
static void InverterCtrl_Sample(InverterCtrl_t *ctrl)
{
    ctrl->Udc = (float)MOCK_REG_ADC_Udc * 0.1f;
    ctrl->Uac = (float)MOCK_REG_ADC_Uac * 0.1f;
    ctrl->Iac = (float)MOCK_REG_ADC_Iac * 0.01f;
}

/* ================= 锁相环 (简化) ================= */
static void InverterCtrl_PLL(InverterCtrl_t *ctrl)
{
    ctrl->theta += OMEGA_GRID * TS;
    if (ctrl->theta > 2.0f * PI) {
        ctrl->theta -= 2.0f * PI;
    }
    ctrl->sin_theta_prev = ctrl->sin_theta;
    ctrl->sin_theta = sinf(ctrl->theta);
    ctrl->cos_theta = cosf(ctrl->theta);
}

/* ================= 功率计算 ================= */
static void InverterCtrl_PowerCalc(InverterCtrl_t *ctrl)
{
    ctrl->Pdc = ctrl->Udc * ctrl->Iac;
    ctrl->Pac = ctrl->Uac * ctrl->Iac;
    ctrl->Pdc_ripple = ctrl->Pdc - ctrl->Pdc_avg_filter;
    ctrl->Udc_ripple = ctrl->Udc - ctrl->Udc_ref;

    ctrl->Pdc_avg_filter = low_pass_filter(ctrl->Pdc, ctrl->Pdc_avg_filter, 0.01f);
    ctrl->Pdc_ripple_filter = low_pass_filter(ctrl->Pdc_ripple, ctrl->Pdc_ripple_filter, 0.1f);
    ctrl->Udc_ripple_filter = low_pass_filter(ctrl->Udc_ripple, ctrl->Udc_ripple_filter, 0.1f);
}

/* ================= 虚拟电容法功率解耦 ================= */
static void InverterCtrl_VirtualCapDecoupling(InverterCtrl_t *ctrl)
{
    ctrl->virtual_cap_current = K_VIRTUAL_CAP * C_DC_PHYS * (ctrl->Udc_ripple_filter - ctrl->Udc_ripple_comp_filter) / TS;
    ctrl->virtual_cap_power = ctrl->Udc * ctrl->virtual_cap_current;
    ctrl->virtual_cap_energy += ctrl->virtual_cap_power * TS;
    ctrl->virtual_cap_voltage = ctrl->virtual_cap_energy / (0.5f * K_VIRTUAL_CAP * C_DC_PHYS + 1e-9f);

    ctrl->Pdc_ripple_comp = -ctrl->Pdc_ripple_filter * K_VIRTUAL_CAP;
    ctrl->Udc_comp = ctrl->Pdc_ripple_comp / (ctrl->Udc + 1e-6f);

    ctrl->Udc_ripple_comp = ctrl->Udc_ripple_filter * ctrl->Udc_ripple_comp_gain;
    ctrl->Udc_ripple_comp = clampf(ctrl->Udc_ripple_comp, -ctrl->Udc_ripple_comp_limit, ctrl->Udc_ripple_comp_limit);
    ctrl->Udc_ripple_comp_filter = low_pass_filter(ctrl->Udc_ripple_comp, ctrl->Udc_ripple_comp_filter, 0.1f);

    ctrl->Udc_ripple_comp_out = ctrl->Udc_ripple_comp_filter * ctrl->Udc_ripple_comp_out_gain;
    ctrl->Udc_ripple_comp_out = clampf(ctrl->Udc_ripple_comp_out, -ctrl->Udc_ripple_comp_out_limit, ctrl->Udc_ripple_comp_out_limit);
    ctrl->Udc_ripple_comp_out_filter = low_pass_filter(ctrl->Udc_ripple_comp_out, ctrl->Udc_ripple_comp_out_filter, 0.1f);

    ctrl->Udc_ripple_comp_out_int += ctrl->Udc_ripple_comp_out_filter * ctrl->Udc_ripple_comp_out_int_gain * TS;
    ctrl->Udc_ripple_comp_out_int = clampf(ctrl->Udc_ripple_comp_out_int, -ctrl->Udc_ripple_comp_out_int_limit, ctrl->Udc_ripple_comp_out_int_limit);
    ctrl->Udc_ripple_comp_out_int_out = ctrl->Udc_ripple_comp_out_int;
    ctrl->Udc_ripple_comp_out_int_out_filter = low_pass_filter(ctrl->Udc_ripple_comp_out_int_out, ctrl->Udc_ripple_comp_out_int_out_filter, 0.1f);

    ctrl->Udc_ripple_comp_out_int_out = ctrl->Udc_ripple_comp_out_int_out_filter * ctrl->Udc_ripple_comp_out_int_out_gain;
    ctrl->Udc_ripple_comp_out_int_out = clampf(ctrl->Udc_ripple_comp_out_int_out, -ctrl->Udc_ripple_comp_out_int_out_limit, ctrl->Udc_ripple_comp_out_int_out_limit);
}

/* ================= 母线电压外环 ================= */
static void InverterCtrl_VoltageLoop(InverterCtrl_t *ctrl)
{
    ctrl->Udc_err = ctrl->Udc_ref - ctrl->Udc + ctrl->Udc_comp + ctrl->Udc_ripple_comp_out_int_out;

    ctrl->Udc_err_int += ctrl->Udc_err * K_I_UDC * TS;
    ctrl->Udc_err_int = clampf(ctrl->Udc_err_int, -IAC_LIMIT, IAC_LIMIT);

    ctrl->Iac_ref_peak = K_P_UDC * ctrl->Udc_err + ctrl->Udc_err_int;
    ctrl->Iac_ref_peak = clampf(ctrl->Iac_ref_peak, -IAC_LIMIT, IAC_LIMIT);

    ctrl->Iac_ref = ctrl->Iac_ref_peak * ctrl->sin_theta;
}

/* ================= 电流内环 ================= */
static void InverterCtrl_CurrentLoop(InverterCtrl_t *ctrl)
{
    ctrl->Iac_err = ctrl->Iac_ref - ctrl->Iac;

    ctrl->Iac_err_int += ctrl->Iac_err * K_I_CURRENT * TS;
    ctrl->Iac_err_int = clampf(ctrl->Iac_err_int, -1.0f, 1.0f);

    ctrl->duty = K_P_CURRENT * ctrl->Iac_err + ctrl->Iac_err_int;
    ctrl->duty = clampf(ctrl->duty, 0.0f, 1.0f);
}

/* ================= 输出 ================= */
static void InverterCtrl_Output(InverterCtrl_t *ctrl)
{
    MOCK_REG_PWM_DUTY = (uint16_t)(ctrl->duty * 10000.0f);
}

/* ================= 主函数 ================= */
int main(void)
{
    InverterCtrl_t ctrl;
    int i;

    InverterCtrl_Init(&ctrl);

    /* 模拟 ADC 输入 */
    MOCK_REG_ADC_Udc = 4000;   /* 400.0V */
    MOCK_REG_ADC_Uac = 3110;   /* 311.0V */
    MOCK_REG_ADC_Iac = 1000;   /* 10.0A */

    printf("=== 光伏并网逆变器功率解耦控制 (虚拟电容法) ===\n");
    printf("初始参数: Udc_ref=%.1fV, C_dc=%.1f uF, K_virtual=%.3f\n",
           UDC_REF, C_DC_PHYS * 1e6f, K_VIRTUAL_CAP);
    printf("--------------------------------------------------\n");

    for (i = 0; i < 10; i++) {
        InverterCtrl_Sample(&ctrl);
        InverterCtrl_PLL(&ctrl);
        InverterCtrl_PowerCalc(&ctrl);
        InverterCtrl_VirtualCapDecoupling(&ctrl);
        InverterCtrl_VoltageLoop(&ctrl);
        InverterCtrl_CurrentLoop(&ctrl);
        InverterCtrl_Output(&ctrl);

        printf("Step %2d | Udc=%7.2fV | Uac=%7.2fV | Iac=%6.2fA | "
               "Pdc=%8.2fW | Pdc_ripple=%7.2fW | Udc_comp=%7.3fV | "
               "Iac_ref=%6.3fA | duty=%.4f\n",
               i + 1,
               ctrl.Udc, ctrl.Uac, ctrl.Iac,
               ctrl.Pdc, ctrl.Pdc_ripple_filter, ctrl.Udc_comp,
               ctrl.Iac_ref, ctrl.duty);
    }

    printf("--------------------------------------------------\n");
    printf("虚拟电容储能: %.6f J\n", ctrl.virtual_cap_energy);
    printf("虚拟电容功率: %.6f W\n", ctrl.virtual_cap_power);
    printf("虚拟电容电压: %.6f V\n", ctrl.virtual_cap_voltage);
    printf("虚拟电容电流: %.6f A\n", ctrl.virtual_cap_current);
    printf("最终 PWM 占空比寄存器值: %u\n", (unsigned)MOCK_REG_PWM_DUTY);
    printf("=== 测试完成 ===\n");

    return 0;
}
