```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问 */
static volatile uint16_t g_adc_data_reg = 0U;
static volatile uint32_t g_gpio_out_reg = 0U;
static volatile uint32_t g_systick_ms_reg = 0U;

#define MOCK_ADC_DATA_REG       (g_adc_data_reg)
#define MOCK_GPIO_OUT_REG       (g_gpio_out_reg)
#define MOCK_SYSTICK_MS_REG     (g_systick_ms_reg)

/* 输出使能位定义 */
#define PWM_ENABLE_BIT          (1U << 0)

/* ================= 系统参数配置 ================= */
#define ADC_VREF_MV             3300U
#define ADC_FULL_SCALE          4095U

/* UVLO 阈值（单位：mV） */
#define UVLO_RISING_THRESHOLD_MV    1800U
#define UVLO_FALLING_THRESHOLD_MV   1600U
#define UVLO_DEBOUNCE_MS            50U

/* 将 ADC 原始值转换为输入电压（mV） */
static uint32_t adc_to_mv(uint16_t adc_raw)
{
    return ((uint32_t)adc_raw * ADC_VREF_MV) / ADC_FULL_SCALE;
}

/* ================= UVLO 状态机 ================= */
typedef enum {
    UVLO_STATE_OFF = 0,
    UVLO_STATE_DEBOUNCE,
    UVLO_STATE_ON
} uvlo_state_t;

typedef struct {
    uvlo_state_t state;
    uint32_t     debounce_start_ms;
    uint32_t     vin_mv;
    bool         pwm_enabled;
} uvlo_ctx_t;

static void uvlo_init(uvlo_ctx_t *ctx)
{
    ctx->state = UVLO_STATE_OFF;
    ctx->debounce_start_ms = 0U;
    ctx->vin_mv = 0U;
    ctx->pwm_enabled = false;
    MOCK_GPIO_OUT_REG &= ~PWM_ENABLE_BIT;
}

static void uvlo_set_pwm(uvlo_ctx_t *ctx, bool enable)
{
    if (enable) {
        MOCK_GPIO_OUT_REG |= PWM_ENABLE_BIT;
        ctx->pwm_enabled = true;
    } else {
        MOCK_GPIO_OUT_REG &= ~PWM_ENABLE_BIT;
        ctx->pwm_enabled = false;
    }
}

static void uvlo_update(uvlo_ctx_t *ctx)
{
    uint32_t now_ms = MOCK_SYSTICK_MS_REG;
    uint16_t adc_raw = MOCK_ADC_DATA_REG;

    ctx->vin_mv = adc_to_mv(adc_raw);

    switch (ctx->state) {
    case UVLO_STATE_OFF:
        if (ctx->vin_mv >= UVLO_RISING_THRESHOLD_MV) {
            ctx->state = UVLO_STATE_DEBOUNCE;
            ctx->debounce_start_ms = now_ms;
        }
        uvlo_set_pwm(ctx, false);
        break;

    case UVLO_STATE_DEBOUNCE:
        if (ctx->vin_mv < UVLO_FALLING_THRESHOLD_MV) {
            ctx->state = UVLO_STATE_OFF;
            uvlo_set_pwm(ctx, false);
        } else if ((now_ms - ctx->debounce_start_ms) >= UVLO_DEBOUNCE_MS) {
            if (ctx->vin_mv >= UVLO_RISING_THRESHOLD_MV) {
                ctx->state = UVLO_STATE_ON;
                uvlo_set_pwm(ctx, true);
            } else {
                ctx->debounce_start_ms = now_ms;
            }
        }
        break;

    case UVLO_STATE_ON:
        if (ctx->vin_mv < UVLO_FALLING_THRESHOLD_MV) {
            ctx->state = UVLO_STATE_OFF;
            uvlo_set_pwm(ctx, false);
        }
        break;

    default:
        ctx->state = UVLO_STATE_OFF;
        uvlo_set_pwm(ctx, false);
        break;
    }
}

/* ================= 测试辅助函数 ================= */
static const char *state_to_str(uvlo_state_t s)
{
    switch (s) {
    case UVLO_STATE_OFF:      return "OFF";
    case UVLO_STATE_DEBOUNCE: return "DEBOUNCE";
