#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
static float mock_voltage_grid = 0.0f;
static float mock_voltage_inv = 0.0f;
static float mock_current_inv = 0.0f;
static float mock_freq_grid = 0.0f;
static float mock_phase_grid = 0.0f;
static float mock_phase_inv = 0.0f;
static float mock_pwm_duty = 0.0f;
static unsigned int mock_relay_grid = 0;
static unsigned int mock_relay_inv = 0;
static unsigned int mock_mode = 0;

#define MOCK_REG_VOLTAGE_GRID      (mock_voltage_grid)
#define MOCK_REG_VOLTAGE_INV       (mock_voltage_inv)
#define MOCK_REG_CURRENT_INV       (mock_current_inv)
#define MOCK_REG_FREQ_GRID         (mock_freq_grid)
#define MOCK_REG_PHASE_GRID        (mock_phase_grid)
#define MOCK_REG_PHASE_INV         (mock_phase_inv)
#define MOCK_REG_PWM_DUTY          (mock_pwm_duty)
#define MOCK_REG_RELAY_GRID        (mock_relay_grid)
#define MOCK_REG_RELAY_INV         (mock_relay_inv)
#define MOCK_REG_MODE              (mock_mode)

/* ==================== 系统参数 ==================== */
#define NOMINAL_VOLTAGE            220.0f
#define NOMINAL_FREQ               50.0f
#define VOLTAGE_TOLERANCE          10.0f
#define FREQ_TOLERANCE             0.5f
#define PHASE_TOLERANCE            0.05f
#define CONTROL_PERIOD             0.0001f
#define PI                         3.14159265358979323846f

/* ==================== 运行模式 ==================== */
typedef enum {
    MODE_OFF_GRID = 0,
    MODE_GRID_TIED,
    MODE_SYNC_PHASE,
    MODE_SYNC_VOLTAGE,
    MODE_CLOSE_RELAY,
    MODE_ON_GRID,
    MODE_OPEN_RELAY,
    MODE_OFF_GRID_RESTORE
} InverterMode;

/* ==================== 控制器状态 ==================== */
typedef struct {
    InverterMode mode;
    float phase_inv;
    float phase_grid;
    float voltage_ref;
    float voltage_inv;
    float freq_inv;
    float freq_grid;
    float phase_error;
    float voltage_error;
    float freq_error;
    float duty;
    unsigned int relay_grid;
    unsigned int relay_inv;
    unsigned int sync_ok;
    unsigned int fault;
    unsigned int step_counter;
    float voltage_integral;
    float current_integral;
} InverterState;

/* ==================== 初始化 ==================== */
static void inverter_init(InverterState *s)
{
    s->mode = MODE_OFF_GRID;
    s->phase_inv = 0.0f;
    s->phase_grid = 0.0f;
    s->voltage_ref = NOMINAL_VOLTAGE;
    s->voltage_inv = 0.0f;
    s->freq_inv = NOMINAL_FREQ;
    s->freq_grid = NOMINAL_FREQ;
    s->phase_error = 0.0f;
    s->voltage_error = 0.0f;
    s->freq_error = 0.0f;
    s->duty = 0.0f;
    s->relay_grid = 0;
    s->relay_inv = 0;
    s->sync_ok = 0;
    s->fault = 0;
    s->step_counter = 0;
    s->voltage_integral = 0.0f;
    s->current_integral = 0.0f;

    MOCK_REG_RELAY_GRID = 0;
    MOCK_REG_RELAY_INV = 0;
    MOCK_REG_MODE = MODE_OFF_GRID;
    MOCK_REG_PWM_DUTY = 0.0f;
}

/* ==================== 读取传感器 ==================== */
static void read_sensors(InverterState *s)
{
    s->voltage_inv = MOCK_REG_VOLTAGE_INV;
    s->freq_grid = MOCK_REG_FREQ_GRID;
    s->phase_grid = MOCK_REG_PHASE_GRID;
    s->phase_inv = MOCK_REG_PHASE_INV;
}

/* ==================== 相位误差归一化 ==================== */
static float normalize_phase_error(float err)
{
    while (err > PI)  err -= 2.0f * PI;
    while (err < -PI) err += 2.0f * PI;
    return err;
}

/* ==================== 离网电压闭环控制 ==================== */
static void off_grid_voltage_control(InverterState *s)
{
    float v_err = s->voltage_ref - s->voltage_inv;
    float kp = 0.02f;
    float ki = 0.001f;

    s->voltage_integral += v_err * CONTROL_PERIOD;
    if (s->voltage_integral > 1.0f)  s->voltage_integral = 1.0f;
    if (s->voltage_integral < -1.0f) s->voltage_integral = -1.0f;

    s->duty = kp * v_err + ki * s->voltage_integral;
    if (s->duty > 0.95f)  s->duty = 0.95f;
    if (s->duty < 0.05f)  s->duty = 0.05f;

    MOCK_REG_PWM_DUTY = s->duty;
}

/* ==================== 并网电流控制 ==================== */
static void grid_tied_current_control(InverterState *s)
{
    float i_ref = 5.0f;
    float i_err = i_ref - MOCK_REG_CURRENT_INV;
    float kp = 0.05f;
    float ki = 0.002f;

    s->current_integral += i_err * CONTROL_PERIOD;
    if (s->current_integral > 1.0f)  s->current_integral = 1.0f;
    if (s->current_integral < -1.0f) s->current_integral = -1.0f;

    s->duty = kp * i_err + ki * s->current_integral;
    if (s->duty > 0.95f)  s->duty = 0.95f;
    if (s->duty < 0.05f)  s->duty = 0.05f;

    MOCK_REG_PWM_DUTY = s->duty;
}

/* ==================== 相位同步 ==================== */
static void phase_sync_control(InverterState *s)
{
    float phase_err = normalize_phase_error(s->phase_grid - s->phase_inv);
    s->phase_error = phase_err;

    float freq_correction = phase_err * 0.5f;
    s->freq_inv = NOMINAL_FREQ + freq_correction;

    if (s->freq_inv > NOMINAL_FREQ + 2.0f) s->freq_inv = NOMINAL_FREQ + 2.0f;
    if (s->freq_inv < NOMINAL_FREQ - 2.0f) s->freq_inv = NOMINAL_FREQ - 2.0f;

    s->phase_inv += 2.0f * PI * s->freq_inv * CONTROL_PERIOD;
    while (s->phase_inv > 2.0f * PI) s->phase_inv -= 2.0f * PI;
    while (s->phase_inv < 0.0f)      s->phase_inv += 2.0f * PI;

    MOCK_REG_PHASE_INV = s->phase_inv;
}

/* ==================== 电压幅值同步 ==================== */
static void voltage_sync_control(InverterState *s)
{
    float v_grid = MOCK_REG_VOLTAGE_GRID;
    float v_err = v_grid - s->voltage_inv;
    s->voltage_error = v_err;

    if (v_err > 0.5f)  v_err = 0.5f;
    if (v_err < -0.5f) v_err = -0.5f;

    s->voltage_ref += v_err;
    if (s->voltage_ref > NOMINAL_VOLTAGE + VOLTAGE_TOLERANCE)
        s->voltage_ref = NOMINAL_VOLTAGE + VOLTAGE_TOLERANCE;
    if (s->voltage_ref < NOMINAL_VOLTAGE - VOLTAGE_TOLERANCE)
        s->voltage_ref = NOMINAL_VOLTAGE - VOLTAGE_TOLERANCE;

    off_grid_voltage_control(s);
}

/* ==================== 同步条件检查 ==================== */
static unsigned int check_sync_conditions(InverterState *s)
{
    float v_grid = MOCK_REG_VOLTAGE_GRID;
    float v_diff = fabsf(v_grid - s->voltage_inv);
    float f_diff = fabsf(s->freq_grid - s->freq_inv);
    float p_diff = fabsf(normalize_phase_error(s->phase_grid - s->phase_inv));

    if (v_diff < VOLTAGE_TOLERANCE &&
        f_diff < FREQ_TOLERANCE &&
        p_diff < PHASE_TOLERANCE) {
        return 1;
    }
    return 0;
}

/* ==================== 状态机主循环 ==================== */
static void inverter_state_machine(InverterState *s)
{
    read_sensors(s);

    switch (s->mode) {
    case MODE_OFF_GRID:
        s->relay_grid = 0;
        s->relay_inv = 0;
        MOCK_REG_RELAY_GRID = 0;
        MOCK_REG_RELAY_INV = 0;
        s->voltage_ref = NOMINAL_VOLTAGE;
        off_grid_voltage_control(s);
        s->step_counter++;
        if (s->step_counter > 100) {
            s->mode = MODE_SYNC_PHASE;
            s->step_counter = 0;
            printf("[STATE] OFF_GRID -> SYNC_PHASE\n");
        }
        break;

    case MODE_SYNC_PHASE:
        s->relay_grid = 0;
        s->relay_inv = 0;
        MOCK_REG_RELAY_GRID = 0;
        MOCK_REG_RELAY_INV = 0;
        phase_sync_control(s);
        off_grid_voltage_control(s);
        s->step_counter++;
        if (s->step_counter > 200) {
            s->mode = MODE_SYNC_VOLTAGE;
            s->step_counter = 0;
            printf("[STATE] SYNC_PHASE -> SYNC_VOLTAGE\n");
        }
        break;

    case MODE_SYNC_VOLTAGE:
        s->relay_grid = 0;
        s->relay_inv = 0;
        MOCK_REG_RELAY_GRID = 0;
        MOCK_REG_RELAY_INV = 0;
        phase_sync_control(s);
        voltage_sync_control(s);
        s->step_counter++;
        if (s->step_counter > 200) {
            s->mode = MODE_CLOSE_RELAY;
            s->step_counter = 0;
            printf("[STATE] SYNC_VOLTAGE -> CLOSE_RELAY\n");
        }
        break;

    case MODE_CLOSE_RELAY:
        if (check_sync_conditions(s)) {
            s->relay_grid = 1;
            s->relay_inv = 1;
            MOCK_REG_RELAY_GRID = 1;
            MOCK_REG_RELAY_INV = 1;
            s->sync_ok = 1;
            s->mode = MODE_ON_GRID;
            printf("[STATE] CLOSE_RELAY -> ON_GRID (sync OK)\n");
        } else {
            s->mode = MODE_SYNC_PHASE;
            s->step_counter = 0;
            printf("[STATE] CLOSE_RELAY -> SYNC_PHASE (sync fail)\n");
        }
        break;

    case MODE_ON_GRID:
        s->relay_grid = 1;
        s->relay_inv = 1;
        MOCK_REG_RELAY_GRID = 1;
        MOCK_REG_RELAY_INV = 1;
        grid_tied_current_control(s);
        s->step_counter++;
        if (s->step_counter > 500) {
            s->mode = MODE_OPEN_RELAY;
            s->step_counter = 0;
            printf("[STATE] ON_GRID -> OPEN_RELAY\n");
        }
        break;

    case MODE_OPEN_RELAY:
        s->relay_grid = 0;
        s->relay_inv = 0;
        MOCK_REG_RELAY_GRID = 0;
        MOCK_REG_RELAY_INV = 0;
        s->sync_ok = 0;
        s->voltage_ref = NOMINAL_VOLTAGE;
        off_grid_voltage_control(s);
        s->step_counter++;
        if (s->step_counter > 50) {
            s->mode = MODE_OFF_GRID_RESTORE;
            s->step_counter = 0;
            printf("[STATE] OPEN_RELAY -> OFF_GRID_RESTORE\n");
        }
        break;

    case MODE_OFF_GRID_RESTORE:
        s->relay_grid = 0;
        s->relay_inv = 0;
        MOCK_REG_RELAY_GRID = 0;
        MOCK_REG_RELAY_INV = 0;
        off_grid_voltage_control(s);
        s->step_counter++;
        if (s->step_counter > 100) {
            s->mode = MODE_OFF_GRID;
            s->step_counter = 0;
            printf("[STATE] OFF_GRID_RESTORE -> OFF_GRID\n");
        }
        break;

    default:
        s->mode = MODE_OFF_GRID;
        break;
    }

    MOCK_REG_MODE = (unsigned int)s->mode;
}

/* ==================== 打印状态 ==================== */
static void print_status(const InverterState *s)
{
    printf("Mode=%d Vref=%.2f Vinv=%.2f Vgrid=%.2f "
           "Fgrid=%.2f Finv=%.2f PhaseErr=%.4f "
           "Duty=%.4f RelayG=%u RelayI=%u SyncOK=%u\n",
           (int)s->mode,
           s->voltage_ref,
           s->voltage_inv,
           MOCK_REG_VOLTAGE_GRID,
           s->freq_grid,
           s->freq_inv,
           s->phase_error,
           s->duty,
           s->relay_grid,
           s->relay_inv,
           s->sync_ok);
}

/* ==================== 模拟电网与逆变器 ==================== */
static void simulate_plant(InverterState *s)
{
    static float t = 0.0f;
    t += CONTROL_PERIOD;

    MOCK_REG_VOLTAGE_GRID = NOMINAL_VOLTAGE + 2.0f * sinf(2.0f * PI * NOMINAL_FREQ * t);
    MOCK_REG_FREQ_GRID = NOMINAL_FREQ;
    MOCK_REG_PHASE_GRID = 2.0f * PI * NOMINAL_FREQ * t;
    while (MOCK_REG_PHASE_GRID > 2.0f * PI)
        MOCK_REG_PHASE_GRID -= 2.0f * PI;

    if (s->relay_inv) {
        MOCK_REG_VOLTAGE_INV = MOCK_REG_VOLTAGE_GRID;
        MOCK_REG_PHASE_INV = MOCK_REG_PHASE_GRID;
    } else {
        MOCK_REG_VOLTAGE_INV = s->voltage_ref * (0.5f + 0.5f * s->duty);
        MOCK_REG_PHASE_INV = s->phase_inv;
    }

    MOCK_REG_CURRENT_INV = 5.0f * sinf(2.0f * PI * NOMINAL_FREQ * t);
}

/* ==================== main ==================== */
int main(void)
{
    InverterState state;
    int cycle;

    printf("=== Energy Storage Inverter Seamless Transfer Control ===\n");
    printf("=== Off-Grid / Grid-Tied Switching Algorithm ===\n\n");

    inverter_init(&state);

    for (cycle = 0; cycle < 2000; cycle++) {
        simulate_plant(&state);
        inverter_state_machine(&state);

        if (cycle % 200 == 0) {
            printf("--- Cycle %d ---\n", cycle);
            print_status(&state);
        }
    }

    printf("\n=== Final State ===\n");
    print_status(&state);
    printf("=== Test Complete ===\n");

    return 0;
}
