#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ===== 模拟寄存器与硬件抽象层 ===== */
static volatile uint16_t mock_adc_vdc = 0;
static volatile int16_t  mock_adc_id = 0;
static volatile int16_t  mock_adc_iq = 0;
static volatile int16_t  mock_adc_vgrid = 0;
static volatile uint16_t mock_pwm_a = 0;
static volatile uint16_t mock_pwm_b = 0;
static volatile uint16_t mock_pwm_c = 0;

#define REG_ADC_VDC        (mock_adc_vdc)
#define REG_ADC_ID         (mock_adc_id)
#define REG_ADC_IQ         (mock_adc_iq)
#define REG_ADC_VGRID      (mock_adc_vgrid)
#define REG_PWM_DUTY_A     (mock_pwm_a)
#define REG_PWM_DUTY_B     (mock_pwm_b)
#define REG_PWM_DUTY_C     (mock_pwm_c)

/* ===== 系统参数 ===== */
#define PI                 3.14159265358979f
#define TS                 1.0e-4f
#define F_GRID             50.0f
#define W_GRID             (2.0f * PI * F_GRID)
#define VDC_REF            400.0f
#define VDC_NOM            400.0f
#define C_VIRT             2000.0e-6f
#define K_P_VDC            0.5f
#define K_I_VDC            20.0f
#define K_P_IQ             2.0f
#define K_I_IQ             100.0f
#define K_P_ID             2.0f
#define K_I_ID             100.0f
#define V_GRID_RMS         220.0f
#define V_GRID_PEAK        (V_GRID_RMS * 1.41421356f)
#define ADC_SCALE_V        0.1f
#define ADC_SCALE_I        0.01f
#define PWM_PERIOD         10000.0f

/* ===== 数学工具 ===== */
static float clampf(float v, float lo, float hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

/* ===== 控制器状态 ===== */
typedef struct {
    float vdc_err_int;
    float vdc_err_prev;
    float id_err_int;
    float id_err_prev;
    float iq_err_int;
    float iq_err_prev;
    float vdc_prev;
    float p_virt;
    float p_virt_filt;
    float p_virt_lpf_alpha;
    float pll_theta;
    float pll_sin;
    float pll_cos;
    float vd_ref;
    float vq_ref;
    float duty_a;
    float duty_b;
    float duty_c;
} ctrl_state_t;

/* ===== 初始化 ===== */
static void ctrl_init(ctrl_state_t *s)
{
    s->vdc_err_int = 0.0f;
    s->vdc_err_prev = 0.0f;
    s->id_err_int = 0.0f;
    s->id_err_prev = 0.0f;
    s->iq_err_int = 0.0f;
    s->iq_err_prev = 0.0f;
    s->vdc_prev = VDC_NOM;
    s->p_virt = 0.0f;
    s->p_virt_filt = 0.0f;
    s->p_virt_lpf_alpha = 0.05f;
    s->pll_theta = 0.0f;
    s->pll_sin = 0.0f;
    s->pll_cos = 1.0f;
    s->vd_ref = 0.0f;
    s->vq_ref = 0.0f;
    s->duty_a = 0.5f;
    s->duty_b = 0.5f;
    s->duty_c = 0.5f;
}

/* ===== 锁相环 (简化) ===== */
static void pll_update(ctrl_state_t *s)
{
    s->pll_theta += W_GRID * TS;
    if (s->pll_theta > 2.0f * PI) {
        s->pll_theta -= 2.0f * PI;
    }
    s->pll_sin = sinf(s->pll_theta);
    s->pll_cos = cosf(s->pll_theta);
}

/* ===== 虚拟电容功率解耦 ===== */
static float virtual_capacitor_power(ctrl_state_t *s, float vdc)
{
    float vdc_sq = vdc * vdc;
    float vdc_prev_sq = s->vdc_prev * s->vdc_prev;
    float p_virt_raw = 0.5f * C_VIRT * (vdc_sq - vdc_prev_sq) / TS;

    s->p_virt_filt += s->p_virt_lpf_alpha * (p_virt_raw - s->p_virt_filt);
    s->p_virt = s->p_virt_filt;

    s->vdc_prev = vdc;
    return s->p_virt;
}

/* ===== 电压外环 PI ===== */
static float vdc_voltage_loop(ctrl_state_t *s, float vdc, float p_virt)
{
    float err = VDC_REF - vdc;
    float p_comp = p_virt / VDC_NOM;

    s->vdc_err_int += err * TS;
    s->vdc_err_int = clampf(s->vdc_err_int, -50.0f, 50.0f);

    float out = K_P_VDC * err + K_I_VDC * s->vdc_err_int + p_comp;
    s->vdc_err_prev = err;

    return clampf(out, -20.0f, 20.0f);
}

/* ===== 电流内环 PI (d 轴) ===== */
static float id_current_loop(ctrl_state_t *s, float id_ref, float id_fb)
{
    float err = id_ref - id_fb;
    s->id_err_int += err * TS;
    s->id_err_int = clampf(s->id_err_int, -10.0f, 10.0f);
    float out = K_P_ID * err + K_I_ID * s->id_err_int;
    s->id_err_prev = err;
    return clampf(out, -1.0f, 1.0f);
}

/* ===== 电流内环 PI (q 轴) ===== */
static float iq_current_loop(ctrl_state_t *s, float iq_ref, float iq_fb)
{
    float err = iq_ref - iq_fb;
    s->iq_err_int += err * TS;
    s->iq_err_int = clampf(s->iq_err_int, -10.0f, 10.0f);
    float out = K_P_IQ * err + K_I_IQ * s->iq_err_int;
    s->iq_err_prev = err;
    return clampf(out, -1.0f, 1.0f);
}

/* ===== 反 Park 变换 ===== */
static void inv_park(float vd, float vq, float sin_t, float cos_t,
                     float *va, float *vb, float *vc)
{
    float valpha = vd * cos_t - vq * sin_t;
    float vbeta  = vd * sin_t + vq * cos_t;

    *va = valpha;
    *vb = -0.5f * valpha + 0.8660254f * vbeta;
    *vc = -0.5f * valpha - 0.8660254f * vbeta;
}

/* ===== 主控制步 ===== */
static void control_step(ctrl_state_t *s)
{
    float vdc    = (float)REG_ADC_VDC * ADC_SCALE_V;
    float id_fb  = (float)REG_ADC_ID  * ADC_SCALE_I;
    float iq_fb  = (float)REG_ADC_IQ  * ADC_SCALE_I;

    pll_update(s);

    float p_virt = virtual_capacitor_power(s, vdc);

    float iq_ref = vdc_voltage_loop(s, vdc, p_virt);
    float id_ref = 0.0f;

    float vd_out = id_current_loop(s, id_ref, id_fb);
    float vq_out = iq_current_loop(s, iq_ref, iq_fb);

    vd_out += V_GRID_PEAK;

    float va, vb, vc;
    inv_park(vd_out, vq_out, s->pll_sin, s->pll_cos, &va, &vb, &vc);

    float vdc_half = vdc * 0.5f;
    if (vdc_half < 1.0f) vdc_half = 1.0f;

    s->duty_a = clampf(0.5f + va / vdc_half, 0.0f, 1.0f);
    s->duty_b = clampf(0.5f + vb / vdc_half, 0.0f, 1.0f);
    s->duty_c = clampf(0.5f + vc / vdc_half, 0.0f, 1.0f);

    REG_PWM_DUTY_A = (uint16_t)(s->duty_a * PWM_PERIOD);
    REG_PWM_DUTY_B = (uint16_t)(s->duty_b * PWM_PERIOD);
    REG_PWM_DUTY_C = (uint16_t)(s->duty_c * PWM_PERIOD);

    printf("Vdc=%.2fV Id=%.3fA Iq=%.3fA Pvirt=%.2fW "
           "DutyA=%.4f DutyB=%.4f DutyC=%.4f\n",
           vdc, id_fb, iq_fb, p_virt,
           s->duty_a, s->duty_b, s->duty_c);
}

/* ===== 主函数 ===== */
int main(void)
{
    ctrl_state_t ctrl;
    ctrl_init(&ctrl);

    printf("=== PV Grid-Connected Inverter Power Decoupling Control ===\n");
    printf("=== Virtual Capacitor Method ===\n\n");

    for (int i = 0; i < 20; i++) {
        float t = (float)i * TS;
        float vdc_sim = VDC_NOM + 5.0f * sinf(2.0f * W_GRID * t);
        float id_sim  = 2.0f * sinf(W_GRID * t);
        float iq_sim  = 1.0f * cosf(W_GRID * t);

        REG_ADC_VDC   = (uint16_t)(vdc_sim / ADC_SCALE_V);
        REG_ADC_ID    = (int16_t)(id_sim / ADC_SCALE_I);
        REG_ADC_IQ    = (int16_t)(iq_sim / ADC_SCALE_I);
        REG_ADC_VGRID = 0;

        printf("[Step %2d] ", i);
        control_step(&ctrl);
    }

    printf("\n=== Control loop finished ===\n");
    return 0;
}
