#include <stdio.h>
#include <math.h>

/* ============================================================
 * 逆变器低频振荡抑制（阻尼控制）算法骨架
 * 采用虚拟电阻阻尼 + 带通滤波提取振荡分量
 * 纯软件仿真，无硬件依赖，GCC 可直接编译
 * ============================================================ */

/* ---------- 基础参数宏定义（模拟系统配置） ---------- */
#define PI                  3.14159265358979323846f
#define TS                  0.0001f          /* 控制周期 100us */
#define FS                  (1.0f / TS)      /* 采样频率 10kHz */
#define GRID_FREQ           50.0f            /* 电网频率 Hz */
#define OMEGA_GRID          (2.0f * PI * GRID_FREQ)

/* 低频振荡典型频段：5Hz ~ 50Hz，中心频率取 20Hz */
#define OSC_FREQ            20.0f
#define OSC_OMEGA           (2.0f * PI * OSC_FREQ)
#define OSC_BW              10.0f            /* 带宽 Hz */
#define OSC_OMEGA_BW        (2.0f * PI * OSC_BW)

/* 阻尼系数：虚拟电阻增益，可在线调节 */
#define KD_DEFAULT          0.35f
#define KD_MIN              0.0f
#define KD_MAX              1.0f

/* 限幅 */
#define DAMP_OUT_LIMIT      0.25f            /* 阻尼输出限幅（标幺值） */

/* ---------- 数据结构定义 ---------- */

/* 二阶广义积分器（SOGI）用于提取振荡分量 */
typedef struct {
    float k;            /* 阻尼比系数 */
    float omega;        /* 中心角频率 rad/s */
    float x1;           /* 状态变量1 */
    float x2;           /* 状态变量2 */
    float y;            /* 输出（振荡分量） */
} SOGI_Filter;

/* 阻尼控制器 */
typedef struct {
    float kd;           /* 阻尼增益 */
    float out;          /* 阻尼输出 */
    float out_prev;     /* 上一拍输出 */
    float limit;        /* 输出限幅 */
    SOGI_Filter sogi;   /* 振荡提取滤波器 */
} DampingController;

/* ---------- 函数实现 ---------- */

/* SOGI 滤波器初始化 */
static void SOGI_Init(SOGI_Filter *sogi, float center_freq, float bw)
{
    sogi->omega = 2.0f * PI * center_freq;
    sogi->k     = bw / center_freq;   /* 阻尼比 = 带宽/中心频率 */
    if (sogi->k > 1.0f) sogi->k = 1.0f;
    if (sogi->k < 0.01f) sogi->k = 0.01f;
    sogi->x1 = 0.0f;
    sogi->x2 = 0.0f;
    sogi->y  = 0.0f;
}

/* SOGI 滤波器更新（离散化：前向欧拉） */
static float SOGI_Update(SOGI_Filter *sogi, float input)
{
    float err;
    float dx1, dx2;

    /* 误差 = 输入 - 状态1 */
    err = input - sogi->x1;

    /* 状态方程：
     * dx1 = omega * (k * err - x2)
     * dx2 = omega * x1
     * y   = x1
     */
    dx1 = sogi->omega * (sogi->k * err - sogi->x2);
    dx2 = sogi->omega * sogi->x1;

    sogi->x1 += dx1 * TS;
    sogi->x2 += dx2 * TS;

    sogi->y = sogi->x1;
    return sogi->y;
}

/* 阻尼控制器初始化 */
static void Damping_Init(DampingController *dc, float kd, float center_freq, float bw)
{
    dc->kd       = kd;
    dc->out      = 0.0f;
    dc->out_prev = 0.0f;
    dc->limit    = DAMP_OUT_LIMIT;
    SOGI_Init(&dc->sogi, center_freq, bw);
}

/* 阻尼控制器更新
 * 输入：id_meas  - 实际 d 轴电流（或功率/电压反馈量）
 *       id_ref   - 参考 d 轴电流
 * 输出：阻尼补偿量，叠加到电压指令上
 */
static float Damping_Update(DampingController *dc, float id_meas, float id_ref)
{
    float err;
    float osc_component;
    float damp_raw;

    /* 1. 计算跟踪误差 */
    err = id_ref - id_meas;

    /* 2. 通过 SOGI 提取误差中的低频振荡分量 */
    osc_component = SOGI_Update(&dc->sogi, err);

    /* 3. 虚拟电阻阻尼：振荡分量 * 阻尼增益 */
    damp_raw = dc->kd * osc_component;

    /* 4. 输出限幅 */
    if (damp_raw > dc->limit)  damp_raw = dc->limit;
    if (damp_raw < -dc->limit) damp_raw = -dc->limit;

    /* 5. 一阶低通平滑（可选，抑制高频噪声） */
    dc->out = 0.85f * dc->out_prev + 0.15f * damp_raw;
    dc->out_prev = dc->out;

    return dc->out;
}

/* 在线调节阻尼增益 */
static void Damping_SetGain(DampingController *dc, float kd)
{
    if (kd < KD_MIN) kd = KD_MIN;
    if (kd > KD_MAX) kd = KD_MAX;
    dc->kd = kd;
}

/* ---------- 主函数：仿真测试 ---------- */
int main(void)
{
    DampingController dc;
    float id_ref, id_meas;
    float damp_out;
    float t;
    int   i;
    int   steps;

    printf("========================================\n");
    printf("  逆变器低频振荡抑制（阻尼控制）仿真\n");
    printf("========================================\n");
    printf("控制周期: %.1f us\n", TS * 1e6f);
    printf("振荡中心频率: %.1f Hz\n", OSC_FREQ);
    printf("阻尼带宽: %.1f Hz\n", OSC_BW);
    printf("初始阻尼增益: %.2f\n", KD_DEFAULT);
    printf("----------------------------------------\n");

    /* 初始化阻尼控制器 */
    Damping_Init(&dc, KD_DEFAULT, OSC_FREQ, OSC_BW);

    /* 仿真参数 */
    id_ref  = 1.0f;          /* 参考电流 1.0 pu */
    steps   = 2000;          /* 仿真 2000 步 = 0.2s */

    printf("时间(s)  参考电流  实际电流  阻尼输出\n");
    printf("----------------------------------------\n");

    for (i = 0; i < steps; i++) {
        t = (float)i * TS;

        /* 模拟实际电流：参考值 + 20Hz 低频振荡 + 少量噪声 */
        id_meas = id_ref
                + 0.15f * sinf(OSC_OMEGA * t)          /* 20Hz 振荡 */
                + 0.05f * sinf(2.0f * PI * 5.0f * t)   /* 5Hz 振荡 */
                + 0.01f * sinf(2.0f * PI * 1000.0f * t); /* 1kHz 噪声 */

        /* 执行阻尼控制 */
        damp_out = Damping_Update(&dc, id_meas, id_ref);

        /* 每 200 步打印一次 */
        if (i % 200 == 0) {
            printf("%.4f   %.4f    %.4f    %.4f\n",
                   t, id_ref, id_meas, damp_out);
        }
    }

    printf("----------------------------------------\n");

    /* 测试在线调节阻尼增益 */
    printf("\n在线调节阻尼增益测试:\n");
    Damping_SetGain(&dc, 0.8f);
    printf("设置增益为 0.8，当前增益 = %.2f\n", dc.kd);

    Damping_SetGain(&dc, 1.5f);
    printf("设置增益为 1.5（超限），当前增益 = %.2f\n", dc.kd);

    Damping_SetGain(&dc, -0.5f);
    printf("设置增益为 -0.5（超限），当前增益 = %.2f\n", dc.kd);

    /* 验证 SOGI 对 20Hz 信号的提取能力 */
    printf("\nSOGI 滤波器频率响应验证:\n");
    {
        SOGI_Filter test_sogi;
        float freq_list[3] = {5.0f, 20.0f, 100.0f};
        int   f;

        for (f = 0; f < 3; f++) {
            float amp_in, amp_out, max_out;
            int   k;

            SOGI_Init(&test_sogi, OSC_FREQ, OSC_BW);
            amp_in  = 1.0f;
            max_out = 0.0f;

            /* 运行足够长时间让滤波器稳定 */
            for (k = 0; k < 5000; k++) {
                float tt = (float)k * TS;
                float sig = amp_in * sinf(2.0f * PI * freq_list[f] * tt);
                float out = SOGI_Update(&test_sogi, sig);

                /* 取后半段的最大幅值 */
                if (k > 2500) {
                    if (fabsf(out) > max_out) max_out = fabsf(out);
                }
            }
            amp_out = max_out;
            printf("  输入 %.1f Hz 正弦 -> 输出幅值 %.4f (增益 %.2f)\n",
                   freq_list[f], amp_out, amp_out / amp_in);
        }
    }

    printf("\n仿真完成。\n");
    return 0;
}
