#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通静态变量模拟寄存器，避免访问非法地址导致段错误 */
static volatile uint32_t g_adc_ac_current = 2048;
static volatile uint32_t g_adc_ac_voltage = 2048;
static volatile uint32_t g_adc_dc_voltage = 2048;
static volatile uint32_t g_pwm_duty = 0;

#define ADC_AC_CURRENT_REG      (g_adc_ac_current)
#define ADC_AC_VOLTAGE_REG      (g_adc_ac_voltage)
#define ADC_DC_VOLTAGE_REG      (g_adc_dc_voltage)
#define PWM_DUTY_REG            (g_pwm_duty)

/* 模拟定时器周期 */
#define PWM_PERIOD              1000.0f

/* ================= 系统参数 ================= */
#define V_AC_RMS                220.0f
#define V_DC_REF                400.0f
#define L_BOOST                 0.002f
#define F_SW                    20000.0f
#define TS                      (1.0f / F_SW)
#define PI                      3.14159265358979323846f

/* 电压环 PI 参数 */
#define KP_V                    0.5f
#define KI_V                    20.0f

/* 电流环 PI 参数 */
#define KP_I                    5.0f
#define KI_I                    500.0f

/* 限幅 */
#define I_REF_MAX               20.0f
#define DUTY_MIN                0.02f
#define DUTY_MAX                0.98f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_min;
    float out_max;
} PI_Controller;

typedef struct {
    float v_ac;          /* 交流电压瞬时值 */
    float i_ac;          /* 交流电流瞬时值 */
    float v_dc;          /* 直流母线电压 */
    float v_dc_ref;      /* 直流母线电压参考 */
    float i_ref;         /* 电流参考幅值 */
    float i_ref_inst;    /* 电流瞬时参考 */
    float duty;          /* 占空比 */
    float theta;         /* 电网相位角 */
    float sin_theta;     /* 正弦值 */
    float v_ff;          /* 前馈电压 */
} PFC_State;

/* ================= PI 控制器 ================= */
static void PI_Init(PI_Controller *pi, float kp, float ki, float out_min, float out_max)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_min = out_min;
    pi->out_max = out_max;
}

static float PI_Update(PI_Controller *pi, float error, float ts)
{
    float p_term = pi->kp * error;
    pi->integral += pi->ki * error * ts;

    /* 积分限幅 */
    if (pi->integral > pi->out_max) pi->integral = pi->out_max;
    if (pi->integral < pi->out_min) pi->integral = pi->out_min;

    float out = p_term + pi->integral;

    /* 输出限幅 */
    if (out > pi->out_max) out = pi->out_max;
    if (out < pi->out_min) out = pi->out_min;

    return out;
}

/* ================= 锁相环（简化：软件生成相位） ================= */
static void PLL_Update(PFC_State *pfc, float ts)
{
    /* 简化实现：假设电网频率 50Hz，相位累加 */
    float omega = 2.0f * PI * 50.0f;
    pfc->theta += omega * ts;
    if (pfc->theta > 2.0f * PI) {
        pfc->theta -= 2.0f * PI;
    }
    pfc->sin_theta = sinf(pfc->theta);
}

/* ================= 采样（Mock） ================= */
static void ADC_Read(PFC_State *pfc)
{
    uint32_t raw_i = ADC_AC_CURRENT_REG;
    uint32_t raw_v = ADC_AC_VOLTAGE_REG;
    uint32_t raw_vdc = ADC_DC_VOLTAGE_REG;

    /* 简单标度：假设 12 位 ADC，参考 3.3V */
    pfc->i_ac = ((float)raw_i / 4095.0f) * 3.3f;
    pfc->v_ac = ((float)raw_v / 4095.0f) * 3.3f;
    pfc->v_dc = ((float)raw_vdc / 4095.0f) * 3.3f;
}

/* ================= PWM 输出（Mock） ================= */
static void PWM_SetDuty(float duty)
{
    if (duty < DUTY_MIN) duty = DUTY_MIN;
    if (duty > DUTY_MAX) duty = DUTY_MAX;

    uint32_t reg_val = (uint32_t)(duty * PWM_PERIOD);
    PWM_DUTY_REG = reg_val;
}

/* ================= PFC 控制核心 ================= */
static void PFC_Control(PFC_State *pfc, PI_Controller *pi_v, PI_Controller *pi_i, float ts)
{
    /* 1. 锁相环更新 */
    PLL_Update(pfc, ts);

    /* 2. 电压外环：调节直流母线电压，输出电流参考幅值 */
    float v_err = pfc->v_dc_ref - pfc->v_dc;
    pfc->i_ref = PI_Update(pi_v, v_err, ts);

    /* 电流参考限幅 */
    if (pfc->i_ref > I_REF_MAX) pfc->i_ref = I_REF_MAX;
    if (pfc->i_ref < 0.0f) pfc->i_ref = 0.0f;

    /* 3. 生成电流瞬时参考：与电网电压同相 */
    pfc->i_ref_inst = pfc->i_ref * pfc->sin_theta;

    /* 4. 电流内环：调节交流电流跟踪参考 */
    float i_err = pfc->i_ref_inst - pfc->i_ac;
    float v_ctrl = PI_Update(pi_i, i_err, ts);

    /* 5. 前馈解耦：加上电网电压前馈 */
    pfc->v_ff = pfc->v_ac;

    /* 6. 计算占空比 */
    float v_dc_half = pfc->v_dc * 0.5f;
    if (v_dc_half < 1.0f) v_dc_half = 1.0f;

    pfc->duty = 0.5f + (v_ctrl + pfc->v_ff) / (2.0f * v_dc_half);

    /* 7. 输出 PWM */
    PWM_SetDuty(pfc->duty);
}

/* ================= 主函数 ================= */
int main(void)
{
    PFC_State pfc;
    PI_Controller pi_v;
    PI_Controller pi_i;

    /* 初始化状态 */
    pfc.v_ac = 0.0f;
    pfc.i_ac = 0.0f;
    pfc.v_dc = 0.0f;
    pfc.v_dc_ref = V_DC_REF;
    pfc.i_ref = 0.0f;
    pfc.i_ref_inst = 0.0f;
    pfc.duty = 0.5f;
    pfc.theta = 0.0f;
    pfc.sin_theta = 0.0f;
    pfc.v_ff = 0.0f;

    /* 初始化 PI 控制器 */
    PI_Init(&pi_v, KP_V, KI_V, 0.0f, I_REF_MAX);
    PI_Init(&pi_i, KP_I, KI_I, -1.0f, 1.0f);

    /* 模拟 ADC 初始值 */
    ADC_AC_CURRENT_REG = 2048;   /* 中点 */
    ADC_AC_VOLTAGE_REG = 2048;   /* 中点 */
    ADC_DC_VOLTAGE_REG = 2048;   /* 中点 */

    printf("=== 单相 PWM 整流器 PFC 控制仿真 ===\n");
    printf("Vdc_ref = %.1f V, Fsw = %.0f Hz, Ts = %.6f s\n\n",
           V_DC_REF, F_SW, TS);

    /* 仿真循环 */
    int step;
    for (step = 0; step < 10; step++) {
        /* 模拟 ADC 采样 */
        ADC_Read(&pfc);

        /* 模拟直流电压逐渐上升 */
        pfc.v_dc = 300.0f + (float)step * 10.0f;

        /* 模拟交流电压 */
        pfc.v_ac = V_AC_RMS * 1.414f * sinf(2.0f * PI * 50.0f * (float)step * TS);

        /* 执行 PFC 控制 */
        PFC_Control(&pfc, &pi_v, &pi_i, TS);

        /* 打印测试信息 */
        printf("Step %2d | theta=%.3f rad | sin=%.3f | Vac=%.2f V | "
               "Vdc=%.1f V | Iref=%.3f A | Iref_inst=%.3f A | "
               "Iac=%.3f A | Duty=%.4f\n",
               step,
               pfc.theta,
               pfc.sin_theta,
               pfc.v_ac,
               pfc.v_dc,
               pfc.i_ref,
               pfc.i_ref_inst,
               pfc.i_ac,
               pfc.duty);
    }

    printf("\n=== 仿真结束 ===\n");
    return 0;
}
