    uint32_t module_id;
} InverterModule_t;

/* ==================== 全局变量 ==================== */
static InverterModule_t g_modules[MODULE_NUM];
static float g_global_Vref = NOMINAL_AC_VOLTAGE;
static float g_global_freq = NOMINAL_FREQ;
static float g_global_phase = 0.0f;
static uint32_t g_control_tick = 0;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

static float PI_Update(PI_Controller_t *pi, float error)
{
    float p_term = pi->Kp * error;
    pi->integral += pi->Ki * error * TS;
    pi->integral = clampf(pi->integral, pi->limit_min, pi->limit_max);
    float output = p_term + pi->integral;
    return clampf(output, pi->limit_min, pi->limit_max);
}

/* ==================== 硬件抽象层 ==================== */
static void HAL_ADC_Read(ModuleSample_t *s, uint32_t id)
{
    float base = (float)(id + 1);
    s->Vdc = NOMINAL_DC_VOLTAGE + (base - 2.0f) * 5.0f;
    s->Idc = 10.0f + (base - 2.0f) * 0.5f;
    s->Iac = 5.0f + (base - 2.0f) * 0.3f;
    s->Vac = NOMINAL_AC_VOLTAGE + (base - 2.0f) * 2.0f;
}

static void HAL_PWM_SetDuty(uint32_t id, float duty)
{
    duty = clampf(duty, 0.0f, 1.0f);
    if (id == 0U) {
        PWM1->CCR1 = (uint32_t)(duty * 1000.0f);
    } else if (id == 1U) {
        PWM1->CCR2 = (uint32_t)(duty * 1000.0f);
    } else {
        PWM1->CCR3 = (uint32_t)(duty * 1000.0f);
    }
}

static void HAL_CAN_SendSync(float phase, float freq)
{
    CAN1->TX = (uint32_t)(phase * 1000.0f);
    (void)freq;
}

static void HAL_CAN_RecvSync(float *phase, float *freq)
{
    *phase = (float)(CAN1->RX) / 1000.0f;
    *freq = g_global_freq;
}

/* ==================== 主从式均流均压控制 ==================== */
static void Module_Init(InverterModule_t *m, uint32_t id, ModuleRole_t role)
{
    m->module_id = id;
    m->role = role;
    m->phase_ref = 0.0f;
    m->freq_ref = NOMINAL_FREQ;
    m->Vdc_avg = NOMINAL_DC_VOLTAGE;
    m->Idc_avg = 10.0f;
    m->sync_counter = 0.0f;

    m->vpi.Kp = VOLTAGE_LOOP_KP;
    m->vpi.Ki = VOLTAGE_LOOP_KI;
    m->vpi.integral = 0.0f;
    m->vpi.limit_max = 50.0f;
    m->vpi.limit_min = -50.0f;

    m->ipi.Kp = CURRENT_LOOP_KP;
    m->ipi.Ki = CURRENT_LOOP_KI;
    m->ipi.integral = 0.0f;
    m->ipi.limit_max = 1.0f;
    m->ipi.limit_min = -1.0f;

    m->ctrl.Vref = NOMINAL_AC_VOLTAGE;
    m->ctrl.Iref = 0.0f;
    m->ctrl.Vdroop = 0.0f;
    m->ctrl.Idroop = 0.0f;
    m->ctrl.Vcmd = 0.0f;
    m->ctrl.Icmd = 0.0f;
    m->ctrl.duty = 0.5f;
}

static void Master_GenerateReference(void)
{
    g_global_phase += 2.0f * PI * g_global_freq * TS;
    if (g_global_phase > 2.0f * PI) {
        g_global_phase -= 2.0f * PI;
    }
    HAL_CAN_SendSync(g_global_phase, g_global_freq);
}

static void Master_UpdateAverage(void)
{
    float vsum = 0.0f;
    float isum = 0.0f;
    uint32_t i;
    for (i = 0; i < MODULE_NUM; i++) {
        vsum += g_modules[i].sample.Vdc;
        isum += g_modules[i].sample.Idc;
    }
    g_modules[0].Vdc_avg = vsum / (float)MODULE_NUM;
    g_modules[0].Idc_avg = isum / (float)MODULE_NUM;
}

static void Master_Control(InverterModule_t *m)
{
    float verr, ierr;
    float vref_droop, iref_droop;

    vref_droop = g_global_Vref - DROOP_COEFF_V * (m->sample.Vdc - m->Vdc_avg);
    m->ctrl.Vref = vref_droop;
    verr = m->ctrl.Vref - m->sample.Vac;
    m->ctrl.Iref = PI_Update(&m->vpi, verr);

    iref_droop = m->ctrl.Iref - DROOP_COEFF_I * (m->sample.Idc - m->Idc_avg);
    m->ctrl.Icmd = iref_droop;
    ierr = m->ctrl.Icmd - m->sample.Iac;
    m->ctrl.duty = 0.5f + PI_Update(&m->ipi, ierr);

    m->phase_ref = g_global_phase;
    m->freq_ref = g_global_freq;
}

static void Slave_Control(InverterModule_t *m)
{
    float verr, ierr;
    float vref_droop, iref_droop;
    float sync_phase, sync_freq;

    HAL_CAN_RecvSync(&sync_phase, &sync_freq);
    m->phase_ref = sync_phase;
    m->freq_ref = sync_freq;

    vref_droop = g_global_Vref - DROOP_COEFF_V * (m->sample.Vdc - m->Vdc_avg);
    m->ctrl.Vref = vref_droop;
    verr = m->ctrl.Vref - m->sample.Vac;
    m->ctrl.Iref = PI_Update(&m->vpi, verr);

    iref_droop = m->ctrl.Iref - DROOP_COEFF_I * (m->sample.Idc - m->Idc_avg);
    m->ctrl.Icmd = iref_droop;
    ierr = m->ctrl.Icmd - m->sample.Iac;
    m->ctrl.duty = 0.5f + PI_Update(&m->ipi, ierr);
}

static void Module_ControlStep(InverterModule_t *m)
{
    HAL_ADC_Read(&m->sample, m->module_id);

    if (m->role == MODULE_ROLE_MASTER) {
        Master_Control(m);
    } else {
        Slave_Control(m);
    }

    HAL_PWM_SetDuty(m->module_id, m->ctrl.duty);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t i;
    uint32_t step;

    printf("========================================\n");
    printf("  Modular Inverter Master-Slave Control\n");
    printf("  Modules: %u, Control Freq: %.0f Hz\n",
           MODULE_NUM, CONTROL_FREQ);
    printf("========================================\n\n");

    for (i = 0; i < MODULE_NUM; i++) {
        ModuleRole_t role = (i == 0) ? MODULE_ROLE_MASTER : MODULE_ROLE_SLAVE;
        Module_Init(&g_modules[i], i, role);
    }

    for (step = 0; step < 5; step++) {
        g_control_tick++;

        if (g_modules[0].role == MODULE_ROLE_MASTER) {
            Master_GenerateReference();
            Master_UpdateAverage();
            for (i = 1; i < MODULE_NUM; i++) {
                g_modules[i].Vdc_avg = g_modules[0].Vdc_avg;
                g_modules[i].Idc_avg = g_modules[0].Idc_avg;
            }
        }

        for (i = 0; i < MODULE_NUM; i++) {
            Module_ControlStep(&g_modules[i]);
        }

        printf("--- Control Step %u ---\n", step + 1);
        printf("Global Phase: %.4f rad, Freq: %.2f Hz\n",
               g_global_phase, g_global_freq);
        printf("Master Avg: Vdc=%.2f V, Idc=%.2f A\n",
               g_modules[0].Vdc_avg, g_modules[0].Idc_avg);
        for (i = 0; i < MODULE_NUM; i++) {
            printf("  Module[%u] %s: Vdc=%.2f V, Idc=%.2f A, "
                   "Vac=%.2f V, Iac=%.2f A, Duty=%.4f\n",
                   i,
                   (g_modules[i].role == MODULE_ROLE_MASTER) ? "M" : "S",
                   g_modules[i].sample.Vdc,
                   g_modules[i].sample.Idc,
                   g_modules[i].sample.Vac,
                   g_modules[i].sample.Iac,
                   g_modules[i].ctrl.duty);
        }
        printf("\n");
    }

    printf("========================================\n");
    printf("  Control Loop Finished Successfully\n");
    printf("========================================\n");

    return 0;
}
