#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器（使用普通变量，避免非法地址访问） ==================== */
static volatile uint16_t g_mock_adc_ugrid = 0;
static volatile uint16_t g_mock_adc_igrid = 0;
static volatile uint16_t g_mock_adc_udc   = 0;
static volatile uint16_t g_mock_pwm_a     = 0;
static volatile uint16_t g_mock_pwm_b     = 0;
static volatile uint16_t g_mock_pwm_c     = 0;
static volatile uint32_t g_mock_fault     = 0;

#define MOCK_ADC_UGRID_REG      (g_mock_adc_ugrid)
#define MOCK_ADC_IGRID_REG      (g_mock_adc_igrid)
#define MOCK_ADC_UDC_REG        (g_mock_adc_udc)
#define MOCK_PWM_DUTY_A_REG     (g_mock_pwm_a)
#define MOCK_PWM_DUTY_B_REG     (g_mock_pwm_b)
#define MOCK_PWM_DUTY_C_REG     (g_mock_pwm_c)
#define MOCK_FAULT_FLAG_REG     (g_mock_fault)

#define ADC_FULL_SCALE          4095.0f
#define GRID_VOLTAGE_FULL       400.0f
#define GRID_CURRENT_FULL       50.0f
#define DC_BUS_VOLTAGE_FULL     800.0f
#define PWM_FULL_SCALE          10000.0f

/* ==================== LVRT 控制参数 ==================== */
#define GRID_NOMINAL_VOLTAGE    311.0f
#define LVRT_THRESHOLD          0.9f
#define LVRT_RECOVERY_THRESHOLD 0.95f
#define LVRT_DEEP_THRESHOLD     0.2f
#define LVRT_MAX_CURRENT_PU     1.2f
#define LVRT_REACTIVE_GAIN      2.0f
#define LVRT_ACTIVE_REDUCE_GAIN 1.5f
#define CONTROL_TS              0.0001f
#define PI_KP                   0.5f
#define PI_KI                   100.0f

/* ==================== 系统状态结构体 ==================== */
typedef enum {
    STATE_NORMAL = 0,
    STATE_LVRT,
    STATE_RECOVERY,
    STATE_FAULT
} SystemState_t;

typedef struct {
    float ugrid_pu;
    float igrid_pu;
    float udc_pu;
    float ugrid_amp;
    float igrid_amp;
    float udc_amp;

    float id_ref;
    float iq_ref;
    float id_fbk;
    float iq_fbk;
    float ud_ref;
    float uq_ref;

    float id_integ;
    float iq_integ;

    SystemState_t state;
    uint32_t lvrt_timer;
    uint32_t recovery_timer;
} LVRT_Controller_t;

static LVRT_Controller_t g_lvrt;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static void inv_park_transform(float ud, float uq, float theta,
                               float *ualpha, float *ubeta)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *ualpha = ud * ct - uq * st;
    *ubeta  = ud * st + uq * ct;
}

static void svpwm_calc(float ualpha, float ubeta, float udc,
                       float *da, float *db, float *dc)
{
    float half_udc = udc * 0.5f;
    if (half_udc < 1.0f) half_udc = 1.0f;

    float ua = ualpha;
    float ub = -0.5f * ualpha + 0.8660254f * ubeta;
    float uc = -0.5f * ualpha - 0.8660254f * ubeta;

    *da = clampf(0.5f + ua / (2.0f * half_udc), 0.0f, 1.0f);
    *db = clampf(0.5f + ub / (2.0f * half_udc), 0.0f, 1.0f);
    *dc = clampf(0.5f + uc / (2.0f * half_udc), 0.0f, 1.0f);
}

/* ==================== 采样与标幺化 ==================== */
static void lvrt_sample(LVRT_Controller_t *ctrl)
{
    uint16_t raw_ugrid = MOCK_ADC_UGRID_REG;
    uint16_t raw_igrid = MOCK_ADC_IGRID_REG;
    uint16_t raw_udc   = MOCK_ADC_UDC_REG;

    ctrl->ugrid_amp = (float)raw_ugrid / ADC_FULL_SCALE * GRID_VOLTAGE_FULL;
    ctrl->igrid_amp = (float)raw_igrid / ADC_FULL_SCALE * GRID_CURRENT_FULL;
    ctrl->udc_amp   = (float)raw_udc   / ADC_FULL_SCALE * DC_BUS_VOLTAGE_FULL;

    ctrl->ugrid_pu = ctrl->ugrid_amp / GRID_NOMINAL_VOLTAGE;
    ctrl->igrid_pu = ctrl->igrid_amp / GRID_CURRENT_FULL;
    ctrl->udc_pu   = ctrl->udc_amp   / DC_BUS_VOLTAGE_FULL;
}

/* ==================== LVRT 状态机 ==================== */
static void lvrt_state_machine(LVRT_Controller_t *ctrl)
{
    float ugrid = ctrl->ugrid_pu;

    switch (ctrl->state) {
    case STATE_NORMAL:
        if (ugrid < LVRT_THRESHOLD) {
            ctrl->state = STATE_LVRT;
            ctrl->lvrt_timer = 0;
            printf("[LVRT] Enter LVRT! Ugrid=%.3f pu\n", ugrid);
        }
        break;

    case STATE_LVRT:
        ctrl->lvrt_timer++;
        if (ugrid > LVRT_RECOVERY_THRESHOLD) {
            ctrl->state = STATE_RECOVERY;
            ctrl->recovery_timer = 0;
            printf("[LVRT] Grid recovered, entering recovery. Ugrid=%.3f pu\n", ugrid);
        }
        if (ugrid < LVRT_DEEP_THRESHOLD) {
            printf("[LVRT] Deep voltage sag detected! Ugrid=%.3f pu\n", ugrid);
        }
        break;

    case STATE_RECOVERY:
        ctrl->recovery_timer++;
        if (ctrl->recovery_timer > 1000) {
            ctrl->state = STATE_NORMAL;
            printf("[LVRT] Recovery complete, back to normal.\n");
        }
        if (ugrid < LVRT_THRESHOLD) {
            ctrl->state = STATE_LVRT;
            ctrl->lvrt_timer = 0;
            printf("[LVRT] Voltage sag again! Ugrid=%.3f pu\n", ugrid);
        }
        break;

    case STATE_FAULT:
        printf("[LVRT] Fault state, output disabled.\n");
        break;

    default:
        ctrl->state = STATE_NORMAL;
        break;
    }
}

/* ==================== LVRT 电流参考生成 ==================== */
static void lvrt_current_reference(LVRT_Controller_t *ctrl)
{
    float ugrid = ctrl->ugrid_pu;
    float id_max = LVRT_MAX_CURRENT_PU;
    float iq_max = LVRT_MAX_CURRENT_PU;

    if (ctrl->state == STATE_LVRT || ctrl->state == STATE_RECOVERY) {
        float voltage_dip = 1.0f - ugrid;
        if (voltage_dip < 0.0f) voltage_dip = 0.0f;

        ctrl->iq_ref = LVRT_REACTIVE_GAIN * voltage_dip;
        ctrl->iq_ref = clampf(ctrl->iq_ref, 0.0f, iq_max);

        float id_available = sqrtf(1.0f - ctrl->iq_ref * ctrl->iq_ref);
        ctrl->id_ref = id_available * (1.0f - LVRT_ACTIVE_REDUCE_GAIN * voltage_dip);
        ctrl->id_ref = clampf(ctrl->id_ref, 0.0f, id_max);

        if (ugrid < LVRT_DEEP_THRESHOLD) {
            ctrl->id_ref = 0.0f;
            ctrl->iq_ref = iq_max;
        }
    } else {
        ctrl->id_ref = 0.8f;
        ctrl->iq_ref = 0.0f;
    }
}

/* ==================== 电流环 PI 控制 ==================== */
static void current_loop_pi(LVRT_Controller_t *ctrl)
{
    float id_err = ctrl->id_ref - ctrl->id_fbk;
    float iq_err = ctrl->iq_ref - ctrl->iq_fbk;

    ctrl->id_integ += PI_KI * id_err * CONTROL_TS;
    ctrl->id_integ = clampf(ctrl->id_integ, -1.0f, 1.0f);
    ctrl->ud_ref = PI_KP * id_err + ctrl->id_integ;

    ctrl->iq_integ += PI_KI * iq_err * CONTROL_TS;
    ctrl->iq_integ = clampf(ctrl->iq_integ, -1.0f, 1.0f);
    ctrl->uq_ref = PI_KP * iq_err + ctrl->iq_integ;

    ctrl->ud_ref += ctrl->ugrid_pu;
}

/* ==================== 主控制循环 ==================== */
static void lvrt_control_step(LVRT_Controller_t *ctrl)
{
    lvrt_sample(ctrl);
    lvrt_state_machine(ctrl);
    lvrt_current_reference(ctrl);

    ctrl->id_fbk = ctrl->igrid_pu * 0.95f;
    ctrl->iq_fbk = ctrl->igrid_pu * 0.05f;

    current_loop_pi(ctrl);

    float theta = 0.0f;
    float ualpha, ubeta;
    inv_park_transform(ctrl->ud_ref, ctrl->uq_ref, theta, &ualpha, &ubeta);

    float da, db, dc;
    svpwm_calc(ualpha, ubeta, ctrl->udc_amp, &da, &db, &dc);

    MOCK_PWM_DUTY_A_REG = (uint16_t)(da * PWM_FULL_SCALE);
    MOCK_PWM_DUTY_B_REG = (uint16_t)(db * PWM_FULL_SCALE);
    MOCK_PWM_DUTY_C_REG = (uint16_t)(dc * PWM_FULL_SCALE);

    if (ctrl->state == STATE_FAULT) {
        MOCK_FAULT_FLAG_REG = 1;
    } else {
        MOCK_FAULT_FLAG_REG = 0;
    }
}

/* ==================== 初始化 ==================== */
static void lvrt_init(LVRT_Controller_t *ctrl)
{
    ctrl->ugrid_pu = 1.0f;
    ctrl->igrid_pu = 0.0f;
    ctrl->udc_pu   = 1.0f;
    ctrl->ugrid_amp = GRID_NOMINAL_VOLTAGE;
    ctrl->igrid_amp = 0.0f;
    ctrl->udc_amp   = DC_BUS_VOLTAGE_FULL;

    ctrl->id_ref = 0.0f;
    ctrl->iq_ref = 0.0f;
    ctrl->id_fbk = 0.0f;
    ctrl->iq_fbk = 0.0f;
    ctrl->ud_ref = 0.0f;
    ctrl->uq_ref = 0.0f;

    ctrl->id_integ = 0.0f;
    ctrl->iq_integ = 0.0f;

    ctrl->state = STATE_NORMAL;
    ctrl->lvrt_timer = 0;
    ctrl->recovery_timer = 0;

    printf("LVRT Controller initialized.\n");
}

/* ==================== 测试打印 ==================== */
static void lvrt_print_status(LVRT_Controller_t *ctrl)
{
    const char *state_str[] = {"NORMAL", "LVRT", "RECOVERY", "FAULT"};
    int idx = (int)ctrl->state;
    if (idx < 0 || idx > 3) idx = 0;
    printf("State=%-8s | Ugrid=%.3f pu | Igrid=%.3f pu | Udc=%.3f pu | "
           "Id_ref=%.3f | Iq_ref=%.3f | Ud_ref=%.3f | Uq_ref=%.3f\n",
           state_str[idx],
           ctrl->ugrid_pu, ctrl->igrid_pu, ctrl->udc_pu,
           ctrl->id_ref, ctrl->iq_ref,
           ctrl->ud_ref, ctrl->uq_ref);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("========================================\n");
    printf("  Grid-Connected Inverter LVRT Control\n");
    printf("========================================\n\n");

    lvrt_init(&g_lvrt);

    float test_ugrid[] = {
        1.00f, 1.00f, 0.95f, 0.85f, 0.70f, 0.50f,
        0.30f, 0.15f, 0.25f, 0.45f, 0.65f, 0.80f,
        0.90f, 0.96f, 1.00f, 1.00f, 1.00f, 1.00f
    };
    int num_tests = (int)(sizeof(test_ugrid) / sizeof(test_ugrid[0]));

    for (int i = 0; i < num_tests; i++) {
        float ugrid_amp = test_ugrid[i] * GRID_NOMINAL_VOLTAGE;
        MOCK_ADC_UGRID_REG = (uint16_t)(ugrid_amp / GRID_VOLTAGE_FULL * ADC_FULL_SCALE);
        MOCK_ADC_IGRID_REG = (uint16_t)(0.5f * ADC_FULL_SCALE);
        MOCK_ADC_UDC_REG   = (uint16_t)(0.9f * ADC_FULL_SCALE);

        lvrt_control_step(&g_lvrt);

        printf("[Step %2d] ", i);
        lvrt_print_status(&g_lvrt);
    }

    printf("\nLVRT control test completed.\n");
    return 0;
}
