#include <stdio.h>
#include <math.h>
#include <string.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define MOCK_REG(addr) (*(volatile float *)(addr))

/* 模拟逆变器输出采样寄存器 */
#define INV_OUTPUT_SAMPLE_ADDR   ((volatile float *)0x40000000)
#define INV_REFERENCE_ADDR       ((volatile float *)0x40000004)
#define INV_PWM_DUTY_ADDR        ((volatile float *)0x40000008)

/* 采样与PWM周期 */
#define SAMPLE_FREQ             10000.0f
#define PWM_FREQ                10000.0f
#define FUNDAMENTAL_FREQ        50.0f

/* 重复控制器参数 */
#define RC_N                    200     /* 每周期采样点数 = SAMPLE_FREQ / FUNDAMENTAL_FREQ */
#define RC_KR                   0.95f   /* 重复控制增益 */
#define RC_Q                    0.98f   /* 衰减因子 */
#define RC_S                    0.5f    /* 相位超前补偿拍数 */

/* PI控制器参数 */
#define PI_KP                   0.8f
#define PI_KI                   0.05f

/* 限幅 */
#define DUTY_MAX                0.95f
#define DUTY_MIN                0.05f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_max;
    float out_min;
} PI_Controller;

typedef struct {
    float mem[RC_N];        /* 重复控制记忆数组 */
    int   index;            /* 当前写入位置 */
    float kr;               /* 重复控制增益 */
    float q;                /* 衰减因子 */
    int   s;                /* 相位超前补偿拍数 */
    float out;              /* 重复控制器输出 */
} Repetitive_Controller;

/* ================= 全局变量 ================= */
static PI_Controller pi_ctrl;
static Repetitive_Controller rc_ctrl;

/* ================= 函数声明 ================= */
void PI_Init(PI_Controller *pi, float kp, float ki, float out_max, float out_min);
float PI_Update(PI_Controller *pi, float error);
void RC_Init(Repetitive_Controller *rc, float kr, float q, int s);
float RC_Update(Repetitive_Controller *rc, float error);
float Inv_Control(float ref, float feedback);

/* ================= PI 控制器实现 ================= */
void PI_Init(PI_Controller *pi, float kp, float ki, float out_max, float out_min)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_max = out_max;
    pi->out_min = out_min;
}

float PI_Update(PI_Controller *pi, float error)
{
    float out;

    pi->integral += pi->ki * error;

    /* 积分限幅 */
    if (pi->integral > pi->out_max) {
        pi->integral = pi->out_max;
    } else if (pi->integral < pi->out_min) {
        pi->integral = pi->out_min;
    }

    out = pi->kp * error + pi->integral;

    /* 输出限幅 */
    if (out > pi->out_max) {
        out = pi->out_max;
    } else if (out < pi->out_min) {
        out = pi->out_min;
    }

    return out;
}

/* ================= 重复控制器实现 ================= */
void RC_Init(Repetitive_Controller *rc, float kr, float q, int s)
{
    int i;
    for (i = 0; i < RC_N; i++) {
        rc->mem[i] = 0.0f;
    }
    rc->index = 0;
    rc->kr = kr;
    rc->q = q;
    rc->s = s;
    rc->out = 0.0f;
}

float RC_Update(Repetitive_Controller *rc, float error)
{
    int read_idx;
    float delayed;
    float rc_inner;

    /* 读取延迟一个基波周期的误差信号 */
    read_idx = rc->index;
    delayed = rc->mem[read_idx];

    /* 重复控制内模: Q(z)*z^-N 环节 */
    rc_inner = rc->q * delayed + error;

    /* 写入当前误差到记忆数组 */
    rc->mem[rc->index] = rc_inner;

    /* 更新索引 */
    rc->index++;
    if (rc->index >= RC_N) {
        rc->index = 0;
    }

    /* 相位超前补偿 z^S 与增益 Kr */
    read_idx = rc->index + rc->s;
    if (read_idx >= RC_N) {
        read_idx -= RC_N;
    }

    rc->out = rc->kr * rc->mem[read_idx];

    return rc->out;
}

/* ================= 逆变器复合控制 ================= */
float Inv_Control(float ref, float feedback)
{
    float error;
    float pi_out;
    float rc_out;
    float total;
    float duty;

    /* 误差计算 */
    error = ref - feedback;

    /* PI 控制 */
    pi_out = PI_Update(&pi_ctrl, error);

    /* 重复控制 */
    rc_out = RC_Update(&rc_ctrl, error);

    /* 复合控制输出 */
    total = pi_out + rc_out;

    /* 归一化到占空比范围 */
    duty = 0.5f + total * 0.5f;

    /* 占空比限幅 */
    if (duty > DUTY_MAX) {
        duty = DUTY_MAX;
    } else if (duty < DUTY_MIN) {
        duty = DUTY_MIN;
    }

    return duty;
}

/* ================= 主函数 ================= */
int main(void)
{
    float ref;
    float feedback;
    float duty;
    int   i;
    float t;
    float error;
    float thd_accum;
    float fundamental_accum;

    printf("===== Inverter Output Harmonic Suppression (Repetitive Control) =====\n\n");

    /* 初始化控制器 */
    PI_Init(&pi_ctrl, PI_KP, PI_KI, 1.0f, -1.0f);
    RC_Init(&rc_ctrl, RC_KR, RC_Q, (int)RC_S);

    printf("PI Controller: Kp=%.2f, Ki=%.2f\n", PI_KP, PI_KI);
    printf("Repetitive Controller: Kr=%.2f, Q=%.2f, S=%d, N=%d\n\n",
           RC_KR, RC_Q, (int)RC_S, RC_N);

    /* 模拟运行多个基波周期 */
    thd_accum = 0.0f;
    fundamental_accum = 0.0f;

    for (i = 0; i < RC_N * 5; i++) {
        /* 时间 */
        t = (float)i / SAMPLE_FREQ;

        /* 参考信号: 50Hz 正弦 */
        ref = sinf(2.0f * 3.14159265f * FUNDAMENTAL_FREQ * t);

        /* 模拟反馈信号: 参考 + 5次谐波 + 7次谐波 + 噪声 */
        feedback = ref
                 + 0.08f * sinf(2.0f * 3.14159265f * 5.0f * FUNDAMENTAL_FREQ * t)
                 + 0.05f * sinf(2.0f * 3.14159265f * 7.0f * FUNDAMENTAL_FREQ * t)
                 + 0.01f * sinf(2.0f * 3.14159265f * 11.0f * FUNDAMENTAL_FREQ * t);

        /* 执行控制 */
        duty = Inv_Control(ref, feedback);

        /* 模拟PWM输出后反馈更新（简化：占空比映射回电压） */
        feedback = (duty - 0.5f) * 2.0f;

        /* 统计谐波含量（仅统计稳态后） */
        if (i > RC_N * 2) {
            error = ref - feedback;
            thd_accum += error * error;
            fundamental_accum += ref * ref;
        }

        /* 每200个点打印一次 */
        if (i % 200 == 0) {
            printf("Step %4d | t=%.4fs | Ref=%+.4f | Fb=%+.4f | Duty=%.4f\n",
                   i, t, ref, feedback, duty);
        }
    }

    /* 计算THD近似值 */
    if (fundamental_accum > 0.0f) {
        float thd = sqrtf(thd_accum / fundamental_accum) * 100.0f;
        printf("\n===== Steady-State Results =====\n");
        printf("Approximate THD: %.2f%%\n", thd);
    }

    printf("\n===== Test Complete =====\n");

    return 0;
}
