#include <stdio.h>
#include <math.h>

/* ========== 模拟寄存器与硬件抽象层 ========== */
typedef struct {
    volatile unsigned int ADC_IL;
    volatile unsigned int ADC_IOUT;
    volatile unsigned int PWM_DUTY;
    volatile unsigned int FAULT_FLAG;
} MockRegs_t;

static MockRegs_t g_mock_regs;

#define REG_ADC_IL      (g_mock_regs.ADC_IL)
#define REG_ADC_IOUT    (g_mock_regs.ADC_IOUT)
#define REG_PWM_DUTY    (g_mock_regs.PWM_DUTY)
#define REG_FAULT_FLAG  (g_mock_regs.FAULT_FLAG)

/* ========== 系统参数 ========== */
#define ADC_FULL_SCALE      4095.0f
#define ADC_REF_VOLTAGE     3.3f
#define CURRENT_SENSOR_V_PER_A  0.05f
#define CURRENT_OFFSET_V    1.65f

#define PWM_PERIOD          10000U
#define PWM_MAX_DUTY        PWM_PERIOD
#define PWM_MIN_DUTY        0U

#define I_RATED_A           10.0f
#define I_LIMIT_A           12.0f
#define I_TRIP_A            15.0f
#define I_RECOVER_A         9.0f

#define DERATE_STEP         0.02f
#define DERATE_RECOVER_STEP 0.005f
#define DERATE_MIN_FACTOR   0.30f
#define DERATE_MAX_FACTOR   1.00f

#define CONTROL_TS          0.0001f

/* ========== 状态枚举 ========== */
typedef enum {
    STATE_NORMAL = 0,
    STATE_LIMITING,
    STATE_DERATING,
    STATE_FAULT
} InverterState_t;

/* ========== 控制器结构体 ========== */
typedef struct {
    float i_ref;
    float i_fbk;
    float i_err;
    float duty;
    float duty_min;
    float duty_max;
    float derate_factor;
    float integral;
    float kp;
    float ki;
    InverterState_t state;
    unsigned int fault_cnt;
    unsigned int recover_cnt;
} InverterCtrl_t;

/* ========== 工具函数 ========== */
static float clampf(float v, float lo, float hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float adc_to_current(unsigned int adc)
{
    float v = ((float)adc / ADC_FULL_SCALE) * ADC_REF_VOLTAGE;
    return (v - CURRENT_OFFSET_V) / CURRENT_SENSOR_V_PER_A;
}

static unsigned int duty_to_pwm(float duty)
{
    float d = clampf(duty, 0.0f, 1.0f);
    return (unsigned int)(d * (float)PWM_PERIOD);
}

/* ========== 控制器初始化 ========== */
static void inverter_ctrl_init(InverterCtrl_t *c)
{
    c->i_ref = 0.0f;
    c->i_fbk = 0.0f;
    c->i_err = 0.0f;
    c->duty = 0.0f;
    c->duty_min = 0.0f;
    c->duty_max = 1.0f;
    c->derate_factor = DERATE_MAX_FACTOR;
    c->integral = 0.0f;
    c->kp = 0.05f;
    c->ki = 0.5f;
    c->state = STATE_NORMAL;
    c->fault_cnt = 0;
    c->recover_cnt = 0;
}

/* ========== 过流检测与状态机 ========== */
static void inverter_overcurrent_check(InverterCtrl_t *c)
{
    float i_abs = fabsf(c->i_fbk);

    switch (c->state) {
    case STATE_NORMAL:
        if (i_abs >= I_TRIP_A) {
            c->state = STATE_FAULT;
            c->fault_cnt = 0;
        } else if (i_abs >= I_LIMIT_A) {
            c->state = STATE_LIMITING;
        }
        break;

    case STATE_LIMITING:
        if (i_abs >= I_TRIP_A) {
            c->state = STATE_FAULT;
            c->fault_cnt = 0;
        } else if (i_abs >= I_LIMIT_A) {
            c->state = STATE_DERATING;
        } else if (i_abs < I_RECOVER_A) {
            c->state = STATE_NORMAL;
        }
        break;

    case STATE_DERATING:
        if (i_abs >= I_TRIP_A) {
            c->state = STATE_FAULT;
            c->fault_cnt = 0;
        } else if (i_abs < I_RECOVER_A) {
            c->recover_cnt++;
            if (c->recover_cnt > 100) {
                c->state = STATE_NORMAL;
                c->recover_cnt = 0;
            }
        } else {
            c->recover_cnt = 0;
        }
        break;

    case STATE_FAULT:
        c->fault_cnt++;
        if (c->fault_cnt > 500) {
            c->state = STATE_NORMAL;
            c->fault_cnt = 0;
            c->derate_factor = DERATE_MIN_FACTOR;
        }
        break;

    default:
        c->state = STATE_NORMAL;
        break;
    }
}

/* ========== 降载因子更新 ========== */
static void inverter_derate_update(InverterCtrl_t *c)
{
    float i_abs = fabsf(c->i_fbk);

    if (c->state == STATE_DERATING || c->state == STATE_LIMITING) {
        if (i_abs > I_LIMIT_A) {
            c->derate_factor -= DERATE_STEP;
        } else if (i_abs > I_RATED_A) {
            c->derate_factor -= DERATE_STEP * 0.5f;
        }
    } else if (c->state == STATE_NORMAL) {
        if (i_abs < I_RATED_A * 0.8f) {
            c->derate_factor += DERATE_RECOVER_STEP;
        }
    }

    c->derate_factor = clampf(c->derate_factor, DERATE_MIN_FACTOR, DERATE_MAX_FACTOR);
}

/* ========== 电流限幅 ========== */
static float inverter_current_limit(InverterCtrl_t *c, float i_cmd)
{
    float i_lim = I_LIMIT_A * c->derate_factor;
    if (i_lim > I_LIMIT_A) i_lim = I_LIMIT_A;
    if (i_lim < 0.0f) i_lim = 0.0f;

    if (i_cmd > i_lim) {
        i_cmd = i_lim;
    } else if (i_cmd < -i_lim) {
        i_cmd = -i_lim;
    }
    return i_cmd;
}

/* ========== 主控制步 ========== */
static void inverter_ctrl_step(InverterCtrl_t *c, float i_ref_cmd)
{
    unsigned int adc_il = REG_ADC_IL;
    unsigned int adc_iout = REG_ADC_IOUT;

    c->i_fbk = adc_to_current(adc_il);
    (void)adc_iout;

    inverter_overcurrent_check(c);
    inverter_derate_update(c);

    if (c->state == STATE_FAULT) {
        c->duty = 0.0f;
        c->integral = 0.0f;
        REG_PWM_DUTY = duty_to_pwm(0.0f);
        REG_FAULT_FLAG = 1U;
        return;
    }

    REG_FAULT_FLAG = 0U;

    c->i_ref = inverter_current_limit(c, i_ref_cmd);

    c->i_err = c->i_ref - c->i_fbk;

    c->integral += c->ki * c->i_err * CONTROL_TS;
    c->integral = clampf(c->integral, -1.0f, 1.0f);

    float duty_cmd = c->kp * c->i_err + c->integral;

    c->duty = clampf(duty_cmd, c->duty_min, c->duty_max);

    REG_PWM_DUTY = duty_to_pwm(c->duty);
}

/* ========== 测试打印 ========== */
static void print_state(const InverterCtrl_t *c, int step)
{
    const char *state_str[] = {"NORMAL", "LIMITING", "DERATING", "FAULT"};
    printf("Step %3d | State: %-8s | I_ref: %6.3f A | I_fbk: %6.3f A | "
           "Derate: %.3f | Duty: %.4f | PWM: %5u\n",
           step,
           state_str[c->state],
           c->i_ref,
           c->i_fbk,
           c->derate_factor,
           c->duty,
           REG_PWM_DUTY);
}

/* ========== 主函数 ========== */
int main(void)
{
    InverterCtrl_t ctrl;
    inverter_ctrl_init(&ctrl);

    printf("===== Inverter Overcurrent Limit & Derating Control Test =====\n\n");

    float test_currents[] = {
        0.0f, 2.0f, 5.0f, 8.0f, 10.0f, 11.0f, 12.5f, 13.0f,
        14.0f, 15.5f, 16.0f, 14.0f, 12.0f, 10.0f, 8.0f, 6.0f,
        4.0f, 2.0f, 1.0f, 0.5f
    };
    int n = (int)(sizeof(test_currents) / sizeof(test_currents[0]));

    for (int i = 0; i < n; i++) {
        float i_meas = test_currents[i];
        float v = i_meas * CURRENT_SENSOR_V_PER_A + CURRENT_OFFSET_V;
        unsigned int adc = (unsigned int)((v / ADC_REF_VOLTAGE) * ADC_FULL_SCALE);
        if (adc > 4095U) adc = 4095U;
        REG_ADC_IL = adc;
        REG_ADC_IOUT = adc;

        inverter_ctrl_step(&ctrl, 10.0f);

        print_state(&ctrl, i);
    }

    printf("\n===== Test Complete =====\n");
    return 0;
}
