```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t g_adc_mains_voltage = 0;
static volatile uint32_t g_adc_inv_voltage = 0;
static volatile uint32_t g_adc_load_current = 0;
static volatile uint32_t g_pwm_mains_duty = 0;
static volatile uint32_t g_pwm_inv_duty = 0;
static volatile uint32_t g_gpio_relay_ctrl = 0;
static volatile uint32_t g_timer_status = 0;

#define ADC_MAINS_VOLTAGE_REG   (g_adc_mains_voltage)
#define ADC_INV_VOLTAGE_REG     (g_adc_inv_voltage)
#define ADC_LOAD_CURRENT_REG    (g_adc_load_current)
#define PWM_MAINS_DUTY_REG      (g_pwm_mains_duty)
#define PWM_INV_DUTY_REG        (g_pwm_inv_duty)
#define GPIO_RELAY_CTRL_REG     (g_gpio_relay_ctrl)
#define TIMER_STATUS_REG        (g_timer_status)

/* 位定义 */
#define RELAY_MAINS_BIT         (1U << 0)
#define RELAY_INV_BIT           (1U << 1)
#define TIMER_ZERO_CROSS_FLAG   (1U << 0)

/* ================= 系统参数 ================= */
#define MAINS_NOMINAL_VOLTAGE   220.0f
#define MAINS_VOLTAGE_MIN       180.0f
#define MAINS_VOLTAGE_MAX       260.0f
#define INV_NOMINAL_VOLTAGE     220.0f
#define INV_VOLTAGE_TOLERANCE   5.0f
#define PHASE_LOCK_TOLERANCE    0.05f
#define ZERO_CROSS_DEBOUNCE_MS  2
#define SWITCH_OVER_DELAY_US    100

#define PI_F                    3.14159265f

/* ================= 状态机定义 ================= */
typedef enum {
    STATE_MAINS_POWERED = 0,
    STATE_INVERTER_POWERED,
    STATE_SYNC_PHASE,
    STATE_SWITCHING_TO_MAINS,
    STATE_SWITCHING_TO_INV,
    STATE_FAULT
} ups_state_t;

/* ================= 系统数据结构 ================= */
typedef struct {
    float mains_voltage;
    float inv_voltage;
    float load_current;

    ups_state_t state;
    ups_state_t next_state;
    float phase_error;
    float phase_lock_target;
    uint32_t zero_cross_count;
    uint32_t switch_over_timer;

    float mains_duty;
    float inv_duty;
    uint32_t relay_ctrl;

    bool mains_valid;
    bool inv_ready;
    bool zero_cross_detected;
    bool phase_locked;
} ups_ctrl_t;

/* ================= 全局变量 ================= */
static ups_ctrl_t g_ups;

/* ================= 函数声明 ================= */
static void ups_init(ups_ctrl_t *ups);
static void ups_read_inputs(ups_ctrl_t *ups);
static void ups_check_mains(ups_ctrl_t *ups);
static void ups_check_inverter(ups_ctrl_t *ups);
static void ups_phase_sync(ups_ctrl_t *ups);
static void ups_state_machine(ups_ctrl_t *ups);
static void ups_output_update(ups_ctrl_t *ups);
static void ups_fault_handler(ups_ctrl_t *ups);
static float ups_calc_phase_error(float mains_phase, float inv_phase);
static void ups_set_relay(ups_ctrl_t *ups, bool mains_on, bool inv_on);

/* ================= 初始化 ================= */
static void ups_init(ups_ctrl_t *ups)
{
    ups->mains_voltage = 0.0f;
    ups->inv_voltage = 0.0f;
    ups->load_current = 0.0f;

    ups->state = STATE_MAINS_POWERED;
    ups->next_state = STATE_MAINS_POWERED;
    ups->phase_error = 0.0f;
    ups->phase_lock_target = 0.0f;
    ups->zero_cross_count = 0;
    ups->switch_over_timer = 0;

    ups->mains_duty = 0.0f;
    ups->inv_duty = 0.0f;
    ups->relay_ctrl = 0;

    ups->mains_valid = false;
    ups->inv_ready = false;
    ups->zero_cross_detected = false;
    ups->phase_locked = false;

    ups_set_relay(ups, true, false);

    printf("[INIT] UPS controller initialized. State: MAINS_POWERED\n");
}

/* ================= 读取输入 ================= */
static void ups_read_inputs(ups_ctrl_t *ups)
{
    ups->mains_voltage = (float)ADC_MAINS_VOLTAGE_REG;
    ups->inv_voltage = (float)ADC_INV_VOLTAGE_REG;
    ups->load_current = (float)ADC_LOAD_CURRENT_REG;

    if (TIMER_STATUS_REG & TIMER_ZERO_CROSS_FLAG) {
        ups->zero_cross_detected = true;
        ups->zero_cross_count++;
        TIMER_STATUS_REG &= ~TIMER_ZERO_CROSS_FLAG;
    } else {
        ups->zero_cross_detected = false;
    }
}

/* ================= 市电检测 ================= */
static void ups_check_mains(ups_ctrl_t *ups)
{
    if (ups->mains_voltage >= MAINS_VOLTAGE_MIN &&
        ups->mains_voltage <= MAINS_VOLTAGE_MAX) {
        ups->mains_valid = true;
    } else {
        ups->mains_valid = false;
    }
}

/* ================= 逆变检测 ================= */
static void ups_check_inverter(ups_ctrl_t *ups)
{
    float inv_error = fabsf(ups->inv_voltage - INV_NOMINAL_VOLTAGE);

    if (inv_error <= INV_VOLTAGE_TOLERANCE) {
        ups->inv_ready = true;
    } else {
        ups->inv_ready = false;
    }
}

/* ================= 相位同步 ================= */
static void ups_phase_sync(ups_ctrl_t *ups)
{
    float mains_phase = 0.0f;
    float inv_phase = 0.0f;

    if (ups->zero_cross_count > 0) {
        inv_phase = (float)(ups->zero_cross_count % 100) / 100.0f * 2.0f * PI_F;
        mains_phase = 0.0f;
    }

    ups->phase_error = ups_calc_phase_error(mains_phase, inv_phase);

    if (fabsf(ups->phase_error) <= PHASE_LOCK_TOLERANCE) {
        ups->phase_locked = true;
    } else {
        ups->phase_locked = false;
    }

    if (!ups->phase_locked) {
        float adjust = ups->phase_error * 0.1f;
        ups->inv_duty += adjust;

        if (ups->inv_duty > 1.0f) ups->inv_duty = 1.0f;
        if (ups->inv_duty < 0.0f) ups->inv_duty = 0.0f;
    }
}

/* ================= 计算相位误差 ================= */
static float ups_calc_phase_error(float mains_phase, float inv_phase)
{
    float error = mains_phase - inv_phase;

    while (error > PI_F) error -= 2.0f * PI_F;
    while (error < -PI_F) error += 2.0f * PI_F;

    return error;
}

/* ================= 设置继电器 ================= */
static void ups_set_relay(ups_ctrl_t *ups, bool mains_on, bool inv_on)
{
    uint32_t ctrl = 0;

    if (mains_on) {
        ctrl |= RELAY_MAINS_BIT;
    }
    if (inv_on) {
        ctrl |= RELAY_INV_BIT;
    }

    ups->relay_ctrl = ctrl;
    GPIO_RELAY_CTRL_REG = ctrl;
}

/* ================= 状态机 ================= */
static void ups_state_machine(ups_ctrl_t *ups)
{
    switch (ups->state) {
        case STATE_MAINS_POWERED:
            if (!ups->mains_valid) {
                printf("[STATE] Mains fault detected. Preparing to switch to inverter.\n");
                ups->next_state = STATE_SYNC_PHASE;
            }
            break;

        case STATE_INVERTER_POWERED:
            if (ups->mains_valid) {
                printf("[STATE] Mains restored. Preparing to switch back to mains.\n");
                ups->next_state = STATE_SYNC_PHASE;
            }
            break;

        case STATE_SYNC_PHASE:
            ups_phase_sync(ups);

            if (ups->phase_locked) {
                if (ups->mains_valid) {
                    ups->next_state = STATE_SWITCHING_TO_MAINS;
                    printf("[STATE] Phase locked. Switching to mains.\n");
                } else {
                    ups->next_state = STATE_SWITCHING_TO_INV;
                    printf("[STATE] Phase locked. Switching to inverter.\n");
                }
            }
            break;

        case STATE_SWITCHING_TO_MAINS:
            ups->switch_over_timer++;

            if (ups->switch_over_timer >= SWITCH_OVER_DELAY_US) {
                ups_set_relay(ups, true, true);
                ups->next_state = STATE_MAINS_POWERED;
                ups->switch_over_timer = 0;
                printf("[STATE] Switched to mains. Zero-interruption complete.\n");
            }
            break;

        case STATE_SWITCHING_TO_INV:
            ups->switch_over_timer++;

            if (ups->switch_over_timer >= SWITCH_OVER_DELAY_US) {
                ups_set_relay(ups, true, true);
                ups->next_state = STATE_INVERTER_POWERED;
                ups->switch_over_timer = 0;
                printf("[STATE] Switched to inverter. Zero-interruption complete.\n");
            }
            break;

        case STATE_FAULT:
            ups_fault_handler(ups);
            break;

        default:
            ups->next_state = STATE_FAULT;
            break;
    }

    if (ups->next_state != ups->state) {
        ups->state = ups->next_state;
    }
}

/* ================= 输出更新 ================= */
static void ups_output_update(ups_ctrl_t *ups)
{
    switch (ups->state) {
        case STATE_MAINS_POWERED:
            ups->mains_duty = 1.0f;
            ups->inv_duty = 0.0f;
            ups_set_relay(ups, true, false);
            break;

        case STATE_INVERTER_POWERED:
            ups->mains_duty = 0.0f;
            ups->inv_duty = 1.0f;
            ups_set_relay(ups, false, true);
            break;

        case STATE_SYNC_PHASE:
            ups->mains_duty = 0.5f;
            break;

        case STATE_SWITCHING_TO_MAINS:
        case STATE_SWITCHING_TO_INV:
            break;

        case STATE_FAULT:
            ups->mains_duty = 0.0f;
            ups->inv_duty = 0.0f;
            ups_set_relay(ups, false, false);
