#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ============================================================
 * 逆变器载波移相调制（多电平输出）控制算法骨架
 * 适用于级联H桥多电平逆变器
 * 载波移相SPWM：N个H桥模块，载波依次相移 180°/N
 * ============================================================ */

/* ---------- Mock 寄存器定义（避免依赖具体硬件） ---------- */
#define MOCK_REG_TIMER_ARR      0x40000000U
#define MOCK_REG_TIMER_CCR1     0x40000004U
#define MOCK_REG_TIMER_CCR2     0x40000008U
#define MOCK_REG_TIMER_CCR3     0x4000000CU
#define MOCK_REG_TIMER_CCR4     0x40000010U
#define MOCK_REG_TIMER_CNT      0x40000014U
#define MOCK_REG_TIMER_CR1      0x40000018U

/* 使用静态变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t g_mock_regs[8];

static volatile uint32_t *MockRegPtr(uint32_t addr)
{
    /* 将 mock 地址映射到本地数组索引 */
    uint32_t idx = (addr - MOCK_REG_TIMER_ARR) / 4U;
    if (idx > 7U) {
        idx = 7U;
    }
    return &g_mock_regs[idx];
}

#define REG32(addr)             (*MockRegPtr(addr))

/* ---------- 系统参数 ---------- */
#define MODULE_NUM              4U          /* 级联H桥模块数 */
#define PWM_FREQ                10000U      /* 载波频率 10kHz */
#define SYS_CLK                 72000000U   /* 系统时钟 72MHz */
#define MOD_FREQ                50U         /* 调制波频率 50Hz */
#define PI                      3.14159265358979f

/* 定时器自动重装载值 */
#define TIMER_ARR_VAL           (SYS_CLK / PWM_FREQ - 1U)

/* 调制比 */
#define MOD_INDEX               0.85f

/* ---------- 全局变量 ---------- */
static uint32_t g_carrier_phase[MODULE_NUM];   /* 各模块载波相位偏移（计数值） */
static uint32_t g_duty[MODULE_NUM];            /* 各模块占空比比较值 */
static float    g_theta = 0.0f;                /* 调制波角度 */
static uint32_t g_step  = 0;                   /* 步进计数 */

/* ---------- 初始化载波移相 ---------- */
static void CarrierPhaseShift_Init(void)
{
    uint32_t i;
    /* 载波周期对应计数值 */
    uint32_t period = TIMER_ARR_VAL + 1U;

    /* 每个模块载波相移 180°/MODULE_NUM */
    for (i = 0; i < MODULE_NUM; i++) {
        g_carrier_phase[i] = (uint32_t)((float)period * (float)i / (float)MODULE_NUM);
    }

    /* 配置定时器（mock） */
    REG32(MOCK_REG_TIMER_ARR) = TIMER_ARR_VAL;
    REG32(MOCK_REG_TIMER_CR1) = 0x0001U;   /* 使能定时器 */
}

/* ---------- 计算单极性/双极性调制占空比 ---------- */
static void ComputeDuty(void)
{
    uint32_t i;
    float    mod_wave;      /* 调制波瞬时值 */
    float    duty_f;

    /* 生成正弦调制波 */
    mod_wave = MOD_INDEX * sinf(g_theta);

    /* 对每个模块计算占空比（双极性调制） */
    for (i = 0; i < MODULE_NUM; i++) {
        /* 载波移相后，各模块比较值 = 中心值 + 调制波偏移 */
        float carrier_center = (float)(TIMER_ARR_VAL) * 0.5f;
        float offset = mod_wave * carrier_center;

        /* 叠加载波相位偏移（等效于移相） */
        float phase_shift = (float)g_carrier_phase[i];

        duty_f = carrier_center + offset + phase_shift;

        /* 限幅 */
        if (duty_f < 0.0f) {
            duty_f = 0.0f;
        }
        if (duty_f > (float)TIMER_ARR_VAL) {
            duty_f = (float)TIMER_ARR_VAL;
        }

        g_duty[i] = (uint32_t)duty_f;
    }

    /* 更新比较寄存器（mock） */
    REG32(MOCK_REG_TIMER_CCR1) = g_duty[0];
    REG32(MOCK_REG_TIMER_CCR2) = g_duty[1];
    REG32(MOCK_REG_TIMER_CCR3) = g_duty[2];
    REG32(MOCK_REG_TIMER_CCR4) = g_duty[3];
}

/* ---------- 更新调制波角度 ---------- */
static void UpdateTheta(void)
{
    float delta;

    /* 每个PWM周期角度增量 */
    delta = 2.0f * PI * (float)MOD_FREQ / (float)PWM_FREQ;

    g_theta += delta;
    if (g_theta >= 2.0f * PI) {
        g_theta -= 2.0f * PI;
    }
}

/* ---------- 主控制循环（单步执行，便于测试） ---------- */
static void ControlStep(void)
{
    UpdateTheta();
    ComputeDuty();
    g_step++;
}

/* ---------- 打印测试 ---------- */
static void PrintStatus(void)
{
    uint32_t i;

    printf("Step=%lu  Theta=%.4f rad  ModWave=%.4f\n",
           (unsigned long)g_step,
           (double)g_theta,
           (double)(MOD_INDEX * sinf(g_theta)));

    printf("  CarrierPhase: ");
    for (i = 0; i < MODULE_NUM; i++) {
        printf("%lu ", (unsigned long)g_carrier_phase[i]);
    }
    printf("\n");

    printf("  Duty(CCR):    ");
    for (i = 0; i < MODULE_NUM; i++) {
        printf("%lu ", (unsigned long)g_duty[i]);
    }
    printf("\n");

    printf("  ARR=%lu  PWM_FREQ=%uHz  MOD_FREQ=%uHz  MODULE_NUM=%u\n\n",
           (unsigned long)TIMER_ARR_VAL, PWM_FREQ, MOD_FREQ, MODULE_NUM);
}

/* ---------- main ---------- */
int main(void)
{
    uint32_t k;

    printf("========================================\n");
    printf("  Inverter Carrier Phase-Shift PWM\n");
    printf("  Cascaded H-Bridge Multilevel Output\n");
    printf("========================================\n\n");

    CarrierPhaseShift_Init();

    /* 模拟运行若干个PWM周期，观察输出 */
    for (k = 0; k < 20U; k++) {
        ControlStep();
        PrintStatus();
    }

    printf("Simulation finished. Total steps = %lu\n", (unsigned long)g_step);

    return 0;
}
