#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 硬件寄存器与参数定义 ================= */
#define PWM_PERIOD          1000.0f
#define DC_BUS_VOLTAGE      400.0f
#define PHASE_RESISTANCE    0.5f
#define PHASE_INDUCTANCE    0.002f
#define SAMPLE_TIME         0.0001f
#define PI                  3.14159265358979323846f

/* 逆变器开关状态枚举：0=下桥臂导通，1=上桥臂导通 */
typedef enum {
    SWITCH_STATE_0 = 0,
    SWITCH_STATE_1 = 1
} SwitchState;

/* 三相开关状态组合 */
typedef struct {
    SwitchState sa;
    SwitchState sb;
    SwitchState sc;
} InverterSwitches;

/* 三相电流与电压结构体 */
typedef struct {
    float ia;
    float ib;
    float ic;
} ThreePhaseCurrent;

typedef struct {
    float va;
    float vb;
    float vc;
} ThreePhaseVoltage;

/* 预测模型状态 */
typedef struct {
    ThreePhaseCurrent i_meas;      /* 当前测量电流 */
    ThreePhaseCurrent i_ref;       /* 参考电流 */
    float vdc;                     /* 直流母线电压 */
    float ts;                      /* 采样周期 */
    float r;                       /* 相电阻 */
    float l;                       /* 相电感 */
} MPC_Model;

/* 最优开关状态与成本 */
typedef struct {
    InverterSwitches switches;
    float cost;
} MPC_Result;

/* ================= 工具函数 ================= */

/* 根据开关状态计算三相输出电压（相对于直流母线中点） */
static ThreePhaseVoltage get_output_voltage(InverterSwitches sw, float vdc)
{
    ThreePhaseVoltage v;
    float half_vdc = vdc * 0.5f;

    /* 每相电压 = (2*S - 1) * Vdc/2，其中 S 为 0 或 1 */
    v.va = (sw.sa == SWITCH_STATE_1 ? half_vdc : -half_vdc);
    v.vb = (sw.sb == SWITCH_STATE_1 ? half_vdc : -half_vdc);
    v.vc = (sw.sc == SWITCH_STATE_1 ? half_vdc : -half_vdc);

    return v;
}

/* 单步预测：根据当前电流、开关状态和模型参数预测下一时刻电流 */
static ThreePhaseCurrent predict_current(MPC_Model *model, InverterSwitches sw)
{
    ThreePhaseCurrent i_pred;
    ThreePhaseVoltage v_out = get_output_voltage(sw, model->vdc);

    float r = model->r;
    float l = model->l;
    float ts = model->ts;

    /* 离散化方程：i(k+1) = i(k) + (Ts/L) * (v - R*i(k)) */
    i_pred.ia = model->i_meas.ia + (ts / l) * (v_out.va - r * model->i_meas.ia);
    i_pred.ib = model->i_meas.ib + (ts / l) * (v_out.vb - r * model->i_meas.ib);
    i_pred.ic = model->i_meas.ic + (ts / l) * (v_out.vc - r * model->i_meas.ic);

    return i_pred;
}

/* 成本函数：电流误差平方和 */
static float cost_function(ThreePhaseCurrent i_pred, ThreePhaseCurrent i_ref)
{
    float ea = i_pred.ia - i_ref.ia;
    float eb = i_pred.ib - i_ref.ib;
    float ec = i_pred.ic - i_ref.ic;

    return (ea * ea + eb * eb + ec * ec);
}

/* ================= 模型预测控制核心 ================= */

/* 单步成本函数优化：遍历所有 8 种开关状态，选择成本最小的 */
static MPC_Result mpc_step(MPC_Model *model)
{
    MPC_Result best;
    best.cost = 1e30f;  /* 初始化为一个大数 */

    /* 遍历 8 种开关组合：000 ~ 111 */
    for (int state = 0; state < 8; state++) {
        InverterSwitches sw;
        sw.sa = (state & 0x04) ? SWITCH_STATE_1 : SWITCH_STATE_0;
        sw.sb = (state & 0x02) ? SWITCH_STATE_1 : SWITCH_STATE_0;
        sw.sc = (state & 0x01) ? SWITCH_STATE_1 : SWITCH_STATE_0;

        /* 预测下一时刻电流 */
        ThreePhaseCurrent i_pred = predict_current(model, sw);

        /* 计算成本 */
        float cost = cost_function(i_pred, model->i_ref);

        /* 更新最优解 */
        if (cost < best.cost) {
            best.cost = cost;
            best.switches = sw;
        }
    }

    return best;
}

/* ================= 主函数 ================= */
int main(void)
{
    printf("========================================\n");
    printf("  逆变器模型预测控制 (MPC) 单步优化测试\n");
    printf("========================================\n\n");

    /* 初始化 MPC 模型 */
    MPC_Model model;
    model.i_meas.ia = 1.0f;
    model.i_meas.ib = -0.5f;
    model.i_meas.ic = -0.5f;

    model.i_ref.ia = 2.0f;
    model.i_ref.ib = -1.0f;
    model.i_ref.ic = -1.0f;

    model.vdc = DC_BUS_VOLTAGE;
    model.ts = SAMPLE_TIME;
    model.r = PHASE_RESISTANCE;
    model.l = PHASE_INDUCTANCE;

    printf("[模型参数]\n");
    printf("  直流母线电压 Vdc = %.1f V\n", model.vdc);
    printf("  采样周期 Ts      = %.6f s\n", model.ts);
    printf("  相电阻 R         = %.3f Ohm\n", model.r);
    printf("  相电感 L         = %.6f H\n\n", model.l);

    printf("[当前状态]\n");
    printf("  测量电流: ia=%.3f A, ib=%.3f A, ic=%.3f A\n",
           model.i_meas.ia, model.i_meas.ib, model.i_meas.ic);
    printf("  参考电流: ia=%.3f A, ib=%.3f A, ic=%.3f A\n\n",
           model.i_ref.ia, model.i_ref.ib, model.i_ref.ic);

    /* 执行 MPC 单步优化 */
    MPC_Result result = mpc_step(&model);

    printf("[MPC 优化结果]\n");
    printf("  最优开关状态: Sa=%d, Sb=%d, Sc=%d\n",
           result.switches.sa, result.switches.sb, result.switches.sc);
    printf("  最小成本值:   %.6f\n\n", result.cost);

    /* 验证最优开关状态下的预测电流 */
    ThreePhaseCurrent i_pred_best = predict_current(&model, result.switches);
    printf("[最优状态下的预测电流]\n");
    printf("  ia_pred=%.4f A, ib_pred=%.4f A, ic_pred=%.4f A\n",
           i_pred_best.ia, i_pred_best.ib, i_pred_best.ic);

    /* 打印所有 8 种状态的成本，便于观察 */
    printf("\n[所有开关状态成本对比]\n");
    printf("  State | Sa Sb Sc | Cost\n");
    printf("  ------+---------+-----------\n");
    for (int state = 0; state < 8; state++) {
        InverterSwitches sw;
        sw.sa = (state & 0x04) ? SWITCH_STATE_1 : SWITCH_STATE_0;
        sw.sb = (state & 0x02) ? SWITCH_STATE_1 : SWITCH_STATE_0;
        sw.sc = (state & 0x01) ? SWITCH_STATE_1 : SWITCH_STATE_0;

        ThreePhaseCurrent i_pred = predict_current(&model, sw);
        float cost = cost_function(i_pred, model.i_ref);

        printf("   %d    |  %d  %d  %d | %.6f%s\n",
               state, sw.sa, sw.sb, sw.sc, cost,
               (cost == result.cost) ? "  <-- 最优" : "");
    }

    printf("\n========================================\n");
    printf("  MPC 单步优化测试完成\n");
    printf("========================================\n");

    return 0;
}
