#include <stdio.h>
#include <math.h>

/* ============================================================
 * 逆变器输出阻抗重塑（阻尼注入）控制算法骨架
 * 纯软件仿真，无硬件依赖，GCC 可直接编译
 * ============================================================ */

/* ---------- 基础参数宏定义（模拟系统配置） ---------- */
#define PI                  3.14159265358979323846f
#define TS                  1.0e-4f          /* 采样周期 100us -> 10kHz */
#define FS                  (1.0f / TS)      /* 采样频率 */
#define W0                  (2.0f * PI * 50.0f) /* 基波角频率 50Hz */

/* 逆变器 LC 滤波器参数 */
#define L_F                 1.0e-3f          /* 滤波电感 1mH */
#define C_F                 20.0e-6f         /* 滤波电容 20uF */
#define R_L                 0.1f             /* 电感等效串联电阻 */

/* 阻尼注入参数 */
#define K_DAMP              0.5f             /* 阻尼增益 */
#define W_C                  (2.0f * PI * 800.0f) /* 虚拟阻尼中心频率 800Hz */
#define Q_DAMP              0.707f           /* 阻尼品质因数 */

/* 电压/电流基准 */
#define V_REF_AMP           311.0f           /* 参考电压幅值 311V (220Vrms) */
#define V_DC                400.0f           /* 直流母线电压 */

/* 限幅 */
#define V_OUT_MAX           350.0f
#define V_OUT_MIN          (-350.0f)

/* ---------- 模拟寄存器/外设（mock） ---------- */
typedef struct {
    float v_cap;        /* 电容电压反馈 */
    float i_ind;        /* 电感电流反馈 */
    float v_ref;        /* 电压参考 */
    float duty;         /* 输出占空比 */
} InverterState_t;

/* 模拟 ADC 读取 */
static float mock_adc_read_vcap(void) { return 0.0f; }
static float mock_adc_read_iind(void) { return 0.0f; }

/* 模拟 PWM 更新 */
static void mock_pwm_update(float duty) { (void)duty; }

/* ---------- 二阶广义积分器（SOGI）用于阻尼注入 ---------- */
typedef struct {
    float x1;
    float x2;
    float k;
    float w;
    float ts;
} SOGI_t;

static void SOGI_Init(SOGI_t *s, float k, float w, float ts)
{
    s->x1 = 0.0f;
    s->x2 = 0.0f;
    s->k  = k;
    s->w  = w;
    s->ts = ts;
}

/* SOGI 离散更新：输入 u，输出 alpha（同相）和 beta（正交） */
static void SOGI_Update(SOGI_t *s, float u, float *alpha, float *beta)
{
    float err = u - s->x1;
    float dx1 = s->w * s->x2;
    float dx2 = -s->w * s->x1 - 2.0f * s->k * s->w * err;

    s->x1 += dx1 * s->ts;
    s->x2 += dx2 * s->ts;

    *alpha = s->x1;
    *beta  = s->x2;
}

/* ---------- 虚拟阻抗（阻尼注入）核心 ---------- */
typedef struct {
    SOGI_t sogi_v;      /* 电压 SOGI */
    SOGI_t sogi_i;      /* 电流 SOGI */
    float  k_damp;      /* 阻尼增益 */
    float  w_c;         /* 中心频率 */
    float  r_virt;      /* 虚拟电阻 */
    float  l_virt;      /* 虚拟电感 */
} VirtualImpedance_t;

static void VirtualImpedance_Init(VirtualImpedance_t *vi,
                                  float k_damp,
                                  float w_c,
                                  float r_virt,
                                  float l_virt)
{
    SOGI_Init(&vi->sogi_v, 0.707f, w_c, TS);
    SOGI_Init(&vi->sogi_i, 0.707f, w_c, TS);
    vi->k_damp = k_damp;
    vi->w_c    = w_c;
    vi->r_virt = r_virt;
    vi->l_virt = l_virt;
}

/*
 * 虚拟阻抗计算：
 *   v_damp = k_damp * ( R_v * i_alpha + w_c * L_v * i_beta )
 * 其中 i_alpha / i_beta 为电感电流经 SOGI 分解后的同相/正交分量。
 * 该阻尼电压叠加到电压参考上，等效于在输出阻抗中注入阻尼，
 * 抑制 LC 滤波器谐振峰。
 */
static float VirtualImpedance_Calc(VirtualImpedance_t *vi,
                                   float v_cap,
                                   float i_ind)
{
    float v_alpha, v_beta;
    float i_alpha, i_beta;
    float v_damp;

    /* 对电容电压和电感电流做 SOGI 分解 */
    SOGI_Update(&vi->sogi_v, v_cap, &v_alpha, &v_beta);
    SOGI_Update(&vi->sogi_i, i_ind, &i_alpha, &i_beta);

    /* 阻尼注入：虚拟电阻项 + 虚拟电感项 */
    v_damp = vi->k_damp * (vi->r_virt * i_alpha
                           + vi->w_c * vi->l_virt * i_beta);

    /* 限幅 */
    if (v_damp >  V_OUT_MAX) v_damp =  V_OUT_MAX;
    if (v_damp <  V_OUT_MIN) v_damp =  V_OUT_MIN;

    return v_damp;
}

/* ---------- 电压外环 PI 控制器 ---------- */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_max;
    float out_min;
} PI_t;

static void PI_Init(PI_t *pi, float kp, float ki, float out_max, float out_min)
{
    pi->kp       = kp;
    pi->ki       = ki;
    pi->integral = 0.0f;
    pi->out_max  = out_max;
    pi->out_min  = out_min;
}

static float PI_Update(PI_t *pi, float err, float ts)
{
    float out;

    pi->integral += pi->ki * err * ts;

    /* 积分抗饱和 */
    if (pi->integral > pi->out_max) pi->integral = pi->out_max;
    if (pi->integral < pi->out_min) pi->integral = pi->out_min;

    out = pi->kp * err + pi->integral;

    if (out > pi->out_max) out = pi->out_max;
    if (out < pi->out_min) out = pi->out_min;

    return out;
}

/* ---------- 主控制结构 ---------- */
typedef struct {
    PI_t               v_pi;        /* 电压环 PI */
    VirtualImpedance_t vi;          /* 虚拟阻抗 */
    float              theta;       /* 参考相位 */
    float              v_ref;       /* 当前参考电压 */
    float              v_damp;      /* 阻尼注入电压 */
    float              v_ctrl;      /* 最终控制电压 */
    float              duty;        /* 占空比 */
} InverterCtrl_t;

static void InverterCtrl_Init(InverterCtrl_t *ctrl)
{
    PI_Init(&ctrl->v_pi, 2.0f, 50.0f, V_OUT_MAX, V_OUT_MIN);

    /* 虚拟电阻 0.5Ω，虚拟电感 0.2mH */
    VirtualImpedance_Init(&ctrl->vi, K_DAMP, W_C, 0.5f, 0.2e-3f);

    ctrl->theta  = 0.0f;
    ctrl->v_ref  = 0.0f;
    ctrl->v_damp = 0.0f;
    ctrl->v_ctrl = 0.0f;
    ctrl->duty   = 0.5f;
}

static void InverterCtrl_Step(InverterCtrl_t *ctrl,
                              float v_cap,
                              float i_ind)
{
    float err;

    /* 1. 生成参考电压（50Hz 正弦） */
    ctrl->v_ref = V_REF_AMP * sinf(ctrl->theta);
    ctrl->theta += W0 * TS;
    if (ctrl->theta > 2.0f * PI) ctrl->theta -= 2.0f * PI;

    /* 2. 计算阻尼注入电压（阻抗重塑核心） */
    ctrl->v_damp = VirtualImpedance_Calc(&ctrl->vi, v_cap, i_ind);

    /* 3. 电压环 PI：参考电压减去阻尼电压后与反馈比较 */
    err = (ctrl->v_ref - ctrl->v_damp) - v_cap;
    ctrl->v_ctrl = PI_Update(&ctrl->v_pi, err, TS);

    /* 4. 占空比计算（半桥逆变器） */
    ctrl->duty = 0.5f + ctrl->v_ctrl / V_DC;

    /* 占空比限幅 */
    if (ctrl->duty > 0.95f) ctrl->duty = 0.95f;
    if (ctrl->duty < 0.05f) ctrl->duty = 0.05f;
}

/* ---------- 主函数 ---------- */
int main(void)
{
    InverterCtrl_t ctrl;
    float v_cap, i_ind;
    int   step;

    printf("========================================\n");
    printf("  Inverter Output Impedance Reshaping\n");
    printf("  (Damping Injection) Control Demo\n");
    printf("========================================\n");
    printf("Ts = %.1f us, Fs = %.1f Hz\n", TS * 1e6f, FS);
    printf("Lf = %.2f mH, Cf = %.1f uF\n", L_F * 1e3f, C_F * 1e6f);
    printf("K_damp = %.2f, W_c = %.1f Hz\n", K_DAMP, W_C / (2.0f * PI));
    printf("----------------------------------------\n");
    printf(" Step |  V_ref  |  V_damp |  V_ctrl |  Duty\n");
    printf("----------------------------------------\n");

    InverterCtrl_Init(&ctrl);

    /* 模拟 200 个控制周期（20ms，约一个工频周期） */
    for (step = 0; step < 200; step++) {
        /* 模拟反馈采样（此处用简单模型代替真实硬件） */
        v_cap = mock_adc_read_vcap();
        i_ind = mock_adc_read_iind();

        /* 用上一拍输出近似反馈，形成闭环仿真 */
        v_cap = ctrl.v_ctrl * 0.95f;
        i_ind = ctrl.v_ctrl / 10.0f;

        /* 执行控制 */
        InverterCtrl_Step(&ctrl, v_cap, i_ind);

        /* 更新 PWM */
        mock_pwm_update(ctrl.duty);

        /* 每 20 步打印一次 */
        if (step % 20 == 0) {
            printf(" %4d | %7.2f | %7.2f | %7.2f | %.4f\n",
                   step,
                   ctrl.v_ref,
                   ctrl.v_damp,
                   ctrl.v_ctrl,
                   ctrl.duty);
        }
    }

    printf("----------------------------------------\n");
    printf("Simulation finished.\n");
    printf("Final: V_ref=%.2f V, V_damp=%.2f V, Duty=%.4f\n",
           ctrl.v_ref, ctrl.v_damp, ctrl.duty);

    return 0;
}
