#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ============================================================
 * 高频逆变器 EMI 滤波设计（软件补偿）控制算法骨架
 * 目标：通过软件生成反相补偿信号，抑制开关频率及其谐波
 * 说明：所有硬件寄存器均使用宏定义模拟，不依赖任何单片机头文件
 * ============================================================ */

/* ---------- 模拟硬件寄存器定义（使用普通变量，避免非法地址访问） ---------- */
static volatile uint32_t g_reg_adc_ctrl  = 0;
static volatile uint32_t g_reg_adc_data  = 0;
static volatile uint32_t g_reg_pwm_ctrl  = 0;
static volatile uint32_t g_reg_pwm_duty  = 0;
static volatile uint32_t g_reg_comp_out  = 0;

#define REG_ADC_CTRL   (g_reg_adc_ctrl)
#define REG_ADC_DATA   (g_reg_adc_data)
#define REG_PWM_CTRL   (g_reg_pwm_ctrl)
#define REG_PWM_DUTY   (g_reg_pwm_duty)
#define REG_COMP_OUT   (g_reg_comp_out)

/* ADC 控制位 */
#define ADC_START           (1U << 0)
#define ADC_EOC             (1U << 1)

/* PWM 控制位 */
#define PWM_ENABLE          (1U << 0)

/* ---------- 系统参数 ---------- */
#define SWITCH_FREQ_HZ      100000.0f   /* 开关频率 100kHz */
#define SAMPLE_FREQ_HZ      1000000.0f  /* 采样频率 1MHz */
#define PI                  3.14159265358979323846f

/* EMI 补偿滤波器阶数 */
#define EMI_FILTER_ORDER    4

/* ---------- 自适应陷波滤波器结构体 ---------- */
typedef struct {
    float b0, b1, b2;       /* 分子系数 */
    float a1, a2;           /* 分母系数 */
    float x1, x2;           /* 输入历史 */
    float y1, y2;           /* 输出历史 */
    float freq;             /* 陷波中心频率 */
    float bw;               /* 带宽 */
    float fs;               /* 采样频率 */
} NotchFilter;

/* ---------- 滑动平均滤波器（用于谐波提取） ---------- */
typedef struct {
    float buffer[EMI_FILTER_ORDER];
    uint32_t index;
    float sum;
} MovingAvg;

/* ---------- 全局变量 ---------- */
static NotchFilter g_notch;
static MovingAvg   g_mavg;
static float       g_comp_gain = 1.0f;   /* 补偿增益 */
static float       g_phase_comp = 0.0f;  /* 相位补偿 */

/* ============================================================
 * 初始化陷波滤波器
 * 中心频率 f0，带宽 bw，采样频率 fs
 * 传递函数：H(z) = (b0 + b1*z^-1 + b2*z^-2) / (1 + a1*z^-1 + a2*z^-2)
 * ============================================================ */
static void NotchFilter_Init(NotchFilter *nf, float f0, float bw, float fs)
{
    float omega0;
    float alpha;
    float a0;
    float sin_w0;

    if (nf == NULL || fs <= 0.0f) {
        return;
    }

    omega0 = 2.0f * PI * f0 / fs;
    sin_w0 = sinf(omega0);

    /* 防止 sin(omega0) 为 0 导致除零 */
    if (fabsf(sin_w0) < 1e-9f) {
        sin_w0 = 1e-9f;
    }

    alpha = sin_w0 * sinhf(logf(2.0f) / 2.0f * bw * omega0 / sin_w0);

    nf->b0 = 1.0f;
    nf->b1 = -2.0f * cosf(omega0);
    nf->b2 = 1.0f;
    nf->a1 = -2.0f * cosf(omega0);
    nf->a2 = 1.0f - alpha;

    /* 归一化 */
    a0 = 1.0f + alpha;
    if (fabsf(a0) < 1e-9f) {
        a0 = 1e-9f;
    }
    nf->b0 /= a0;
    nf->b1 /= a0;
    nf->b2 /= a0;
    nf->a1 /= a0;
    nf->a2 /= a0;

    nf->x1 = 0.0f;
    nf->x2 = 0.0f;
    nf->y1 = 0.0f;
    nf->y2 = 0.0f;
    nf->freq = f0;
    nf->bw   = bw;
    nf->fs   = fs;
}

/* ============================================================
 * 陷波滤波器处理（直接 II 型）
 * ============================================================ */
static float NotchFilter_Process(NotchFilter *nf, float input)
{
    float output;

    if (nf == NULL) {
        return input;
    }

    output = nf->b0 * input
           + nf->b1 * nf->x1
           + nf->b2 * nf->x2
           - nf->a1 * nf->y1
           - nf->a2 * nf->y2;

    nf->x2 = nf->x1;
    nf->x1 = input;
    nf->y2 = nf->y1;
    nf->y1 = output;

    return output;
}

/* ============================================================
 * 滑动平均滤波器初始化
 * ============================================================ */
static void MovingAvg_Init(MovingAvg *ma)
{
    uint32_t i;

    if (ma == NULL) {
        return;
    }

    for (i = 0; i < EMI_FILTER_ORDER; i++) {
        ma->buffer[i] = 0.0f;
    }
    ma->index = 0;
    ma->sum   = 0.0f;
}

/* ============================================================
 * 滑动平均滤波器处理
 * ============================================================ */
static float MovingAvg_Process(MovingAvg *ma, float input)
{
    if (ma == NULL) {
        return input;
    }

    ma->sum -= ma->buffer[ma->index];
    ma->buffer[ma->index] = input;
    ma->sum += input;
    ma->index = (ma->index + 1) % EMI_FILTER_ORDER;

    return ma->sum / (float)EMI_FILTER_ORDER;
}

/* ============================================================
 * 模拟 ADC 读取（返回归一化电流采样值）
 * 实际硬件中应读取真实 ADC 寄存器
 * ============================================================ */
static float Mock_ADC_Read(void)
{
    /* 模拟：基波 + 开关频率纹波 + 谐波 + 噪声 */
    static float t = 0.0f;
    float dt = 1.0f / SAMPLE_FREQ_HZ;
    float fundamental = 0.5f * sinf(2.0f * PI * 50.0f * t);
    float ripple      = 0.1f * sinf(2.0f * PI * SWITCH_FREQ_HZ * t);
    float harmonic2   = 0.05f * sinf(2.0f * PI * 2.0f * SWITCH_FREQ_HZ * t);
    float noise       = 0.01f * sinf(2.0f * PI * 12345.0f * t);

    t += dt;
    if (t > 1.0f) {
        t -= 1.0f;
    }

    return fundamental + ripple + harmonic2 + noise;
}

/* ============================================================
 * 模拟 PWM 占空比设置
 * ============================================================ */
static void Mock_PWM_SetDuty(float duty)
{
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;
    REG_PWM_DUTY = (uint32_t)(duty * 10000.0f);
}

/* ============================================================
 * EMI 软件补偿核心算法
 * 1. 读取电流采样
 * 2. 陷波滤波提取开关频率分量
 * 3. 滑动平均提取低频分量
 * 4. 计算反相补偿量
 * 5. 更新 PWM 占空比
 * ============================================================ */
static float EMI_Compensation_Update(float sample)
{
    float ripple;
    float fundamental;
    float comp;

    /* 步骤 1：陷波滤波，提取开关频率及其谐波分量 */
    ripple = NotchFilter_Process(&g_notch, sample);

    /* 步骤 2：滑动平均，提取低频基波分量 */
    fundamental = MovingAvg_Process(&g_mavg, sample);

    /* 步骤 3：计算补偿量（反相 + 增益 + 相位补偿） */
    comp = -g_comp_gain * ripple;

    /* 相位补偿（简单一阶超前/滞后） */
    comp += g_phase_comp * (sample - fundamental);

    /* 步骤 4：限幅 */
    if (comp > 0.5f)  comp = 0.5f;
    if (comp < -0.5f) comp = -0.5f;

    /* 步骤 5：输出到补偿寄存器 */
    REG_COMP_OUT = (uint32_t)((comp + 1.0f) * 10000.0f);

    return comp;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    uint32_t i;
    float    sample;
    float    comp;
    float    duty;

    printf("========================================\n");
    printf(" 高频逆变器 EMI 滤波设计（软件补偿）\n");
    printf(" 开关频率: %.1f Hz\n", SWITCH_FREQ_HZ);
    printf(" 采样频率: %.1f Hz\n", SAMPLE_FREQ_HZ);
    printf("========================================\n\n");

    /* 初始化陷波滤波器：中心频率 = 开关频率，带宽 = 1kHz */
    NotchFilter_Init(&g_notch, SWITCH_FREQ_HZ, 1000.0f, SAMPLE_FREQ_HZ);

    /* 初始化滑动平均滤波器 */
    MovingAvg_Init(&g_mavg);

    /* 初始化模拟硬件 */
    REG_ADC_CTRL = ADC_START;
    REG_PWM_CTRL = PWM_ENABLE;

    printf("采样点\t原始值\t\t补偿量\t\tPWM占空比\n");
    printf("------\t--------\t--------\t--------\n");

    /* 主循环：模拟 20 个采样周期 */
    for (i = 0; i < 20; i++) {
        /* 读取 ADC */
        sample = Mock_ADC_Read();

        /* EMI 软件补偿 */
        comp = EMI_Compensation_Update(sample);

        /* 计算 PWM 占空比（基波 + 补偿） */
        duty = 0.5f + comp;
        Mock_PWM_SetDuty(duty);

        printf("%4u\t%+8.5f\t%+8.5f\t%8.5f\n",
               (unsigned int)i, sample, comp, duty);
    }

    printf("\n========================================\n");
    printf(" EMI 软件补偿测试完成\n");
    printf(" 补偿寄存器值: %u\n", (unsigned int)REG_COMP_OUT);
    printf(" PWM 占空比寄存器值: %u\n", (unsigned int)REG_PWM_DUTY);
    printf("========================================\n");

    return 0;
}
