```c
#include <stdio.h>
#include <math.h>

/* ============================================================
 * 逆变器输出阻抗重塑（阻尼注入）控制算法骨架
 * 纯软件仿真，无硬件依赖，GCC 可直接编译
 * ============================================================ */

/* ---------- 基础参数宏定义 ---------- */
#define PI                  3.14159265358979323846f
#define TS                  1.0e-4f          /* 采样周期 100us -> 10kHz */
#define FS                  (1.0f / TS)      /* 采样频率 */
#define W0                  (2.0f * PI * 50.0f) /* 基波角频率 50Hz */

/* 逆变器主电路参数（模拟值） */
#define L_F                 2.0e-3f          /* 滤波电感 2mH */
#define C_F                 20.0e-6f         /* 滤波电容 20uF */
#define R_L                 0.1f             /* 电感等效串联电阻 */
#define V_DC                400.0f           /* 直流母线电压 */

/* 阻尼注入参数 */
#define K_DAMP              0.5f             /* 虚拟阻尼系数 */
#define K_VIRTUAL_R         2.0f             /* 虚拟电阻（阻抗重塑核心） */
#define W_C                 2.0f * PI * 800.0f /* 阻尼注入高通截止频率 */

/* 限幅 */
#define V_REF_MAX           311.0f           /* 输出参考电压幅值 */
#define I_MAX               20.0f            /* 最大电流限幅 */

/* ---------- 模拟寄存器（mock） ---------- */
typedef struct {
    float v_dc;          /* 直流母线电压 */
    float v_out;         /* 逆变器输出电压 */
    float i_L;           /* 电感电流 */
    float v_c;           /* 电容电压（输出电压） */
    float i_load;        /* 负载电流 */
} InverterState_t;

/* ---------- 控制器状态 ---------- */
typedef struct {
    /* 电压外环 PI */
    float v_err_int;
    float kp_v;
    float ki_v;

    /* 电流内环 P */
    float kp_i;

    /* 阻尼注入状态 */
    float v_c_prev;      /* 上一拍电容电压 */
    float i_c_prev;      /* 上一拍电容电流 */
    float v_damp;        /* 阻尼注入电压 */
    float i_damp;        /* 阻尼注入电流 */

    /* 高通滤波器状态（用于虚拟电阻） */
    float hp_x_prev;
    float hp_y_prev;

    /* 输出 */
    float v_mod;         /* 调制电压 */
    float d;             /* 占空比 */
} Controller_t;

/* ---------- 工具函数 ---------- */
static float clampf(float x, float lo, float hi)
{
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

/* 一阶高通滤波器：H(s) = s / (s + wc) */
static float high_pass(Controller_t *c, float x)
{
    float alpha = W_C * TS;
    float y = (x - c->hp_x_prev + c->hp_y_prev) / (1.0f + alpha);
    /* 更精确的离散化：y[n] = (1/(1+wc*Ts)) * (y[n-1] + x[n] - x[n-1]) */
    c->hp_x_prev = x;
    c->hp_y_prev = y;
    return y;
}

/* ---------- 控制器初始化 ---------- */
static void controller_init(Controller_t *c)
{
    c->v_err_int = 0.0f;
    c->kp_v = 0.5f;
    c->ki_v = 200.0f;
    c->kp_i = 10.0f;

    c->v_c_prev = 0.0f;
    c->i_c_prev = 0.0f;
    c->v_damp = 0.0f;
    c->i_damp = 0.0f;

    c->hp_x_prev = 0.0f;
    c->hp_y_prev = 0.0f;

    c->v_mod = 0.0f;
    c->d = 0.0f;
}

/* ============================================================
 * 核心控制：输出阻抗重塑（阻尼注入）
 *
 * 原理：
 *   逆变器输出阻抗 Z_out(s) 在谐振频率附近呈现负阻尼特性，
 *   导致 LC 滤波器谐振峰放大。通过注入虚拟阻尼，重塑输出阻抗：
 *
 *   Z_out_new(s) = Z_out(s) + Z_virtual(s)
 *
 *   其中 Z_virtual(s) 由虚拟电阻 R_v 与高通滤波器构成：
 *   Z_virtual(s) = R_v * s / (s + w_c)
 *
 *   在时域中，阻尼注入电压为：
 *   v_damp = R_v * HPF(i_c)
 *
 *   其中 i_c 为电容电流（可由 i_L - i_load 估算）。
 * ============================================================ */
static void impedance_reshaping(Controller_t *c,
                                const InverterState_t *inv,
                                float v_ref,
                                float *v_mod_out)
{
    /* --- 1. 计算电容电流 --- */
    float i_c = inv->i_L - inv->i_load;

    /* --- 2. 虚拟电阻阻尼注入 --- */
    /* 对电容电流进行高通滤波，提取谐振频段分量 */
    float i_c_hp = high_pass(c, i_c);

    /* 虚拟电阻产生的阻尼电压 */
    c->v_damp = K_VIRTUAL_R * i_c_hp;

    /* 附加阻尼项（可选：基于电容电压微分） */
    float dv_c = (inv->v_c - c->v_c_prev) / TS;
    c->i_damp = K_DAMP * dv_c;

    /* --- 3. 电压外环 PI 控制 --- */
    float v_err = v_ref - inv->v_c;
    c->v_err_int += v_err * TS;
    c->v_err_int = clampf(c->v_err_int, -I_MAX, I_MAX);

    float i_ref = c->kp_v * v_err + c->ki_v * c->v_err_int;
    i_ref = clampf(i_ref, -I_MAX, I_MAX);

    /* --- 4. 电流内环 P 控制 --- */
    float i_err = i_ref - inv->i_L;
    float v_pi = c->kp_i * i_err;

    /* --- 5. 前馈解耦 + 阻尼注入 --- */
    /* 输出电压前馈 */
    float v_ff = inv->v_c;

    /* 最终调制电压 = PI输出 + 前馈 + 阻尼注入 */
    float v_cmd = v_pi + v_ff + c->v_damp + c->i_damp;

    /* 限幅 */
    v_cmd = clampf(v_cmd, -V_DC * 0.95f, V_DC * 0.95f);

    /* --- 6. 更新状态 --- */
    c->v_c_prev = inv->v_c;
    c->i_c_prev = i_c;

    /* 计算占空比 */
    c->v_mod = v_cmd;
    c->d = 0.5f + v_cmd / (2.0f * V_DC);
    c->d = clampf(c->d, 0.0f, 1.0f);

    *v_mod_out = v_cmd;
}

/* ============================================================
 * 逆变器主电路仿真（简化离散模型）
 * ============================================================ */
static void inverter_step(InverterState_t *inv, float v_mod, float i_load)
{
    /* 逆变器输出电压（平均值模型） */
    inv->v_out = v_mod;

    /* 电感电流微分：di_L/dt = (v_out - v_c - R_L*i_L) / L_F */
    float di_L = (inv->v_out - inv->v_c - R_L * inv->i_L) / L_F;

    /* 电容电压微分：dv_c/dt = (i_L - i_load) / C_F */
    float dv_c = (inv->i_L - i_load) / C_F;

    /* 欧拉离散化 */
    inv->i_L += di_L * TS;
    inv->v_c += dv_c * TS;
    inv->i_load = i_load;

    /* 限幅保护 */
    inv->i_L = clampf(inv->i_L, -I_MAX * 2.0f, I_MAX * 2.0f);
    inv->v_c = clampf(inv->v_c, -V_REF_MAX * 1.5f, V_REF_MAX * 1.5f);
}

/* ============================================================
 * 主函数：仿真测试
 * ============================================================ */
int main(void)
{
    Controller_t ctrl;
    InverterState_t inv;

    /* 初始化 */
    controller_init(&ctrl);
    inv.v_dc = V_DC;
    inv.v_out = 0.0f;
    inv.i_L = 0.0f;
    inv.v_c = 0.0f;
    inv.i_load = 0.0f;

    printf("========================================\n");
    printf("  Inverter Output Impedance Reshaping\n");
    printf("  (Damping Injection) Simulation\n");
    printf("========================================\n");
    printf("Parameters:\n");
    printf("  L_F = %.2f mH, C_F = %.2f uF\n", L_F * 1000.0f, C_F * 1e6f);
    printf("  K_DAMP = %.2f, K_VIRTUAL_R = %.2f\n", K_DAMP, K_VIRTUAL_R);
    printf("  W_C = %.1f rad/s (%.1f Hz)\n", W_C, W_C / (2.0f * PI));
    printf("  Ts = %.1f us, Fs = %.1f Hz\n", TS * 1e6f, FS);
    printf("----------------------------------------\n");
    printf(" Time(ms)  Vref(V)  Vc(V)   iL(A)   Vdamp(V)  D\n");
    printf("----------------------------------------\n");

    /* 仿真参数 */
    int steps = 2000;           /* 200ms 仿真 */
    float t = 0.0f;
    float v_ref_amp = 100.0f;   /* 参考电压幅值 100V */
    float load_current = 2.0f;  /* 负载电流 2A */

    for (int k = 0; k < steps; k++) {
        /* 生成参考电压（50Hz 正弦） */
        float v_ref = v_ref_amp * sinf(W0 * t);

        /* 执行控制算法 */
        float v_mod;
        impedance_reshaping(&ctrl, &inv, v_ref, &v_mod);

        /* 主电路仿真 */
        inverter_step(&inv, v_mod, load_current);

        /* 每 200 步打印一次（20ms） */
        if (k % 200 == 0) {
            printf(" %7.2f  %7.2f  %7.2f  %7.3f  %7.3f  %6.3f\n",
                   t * 1000.0f,
                   v_ref,
                   inv.v_c,
                   inv.i_L,
                   ctrl.v_damp,
                   ctrl.d);
        }

        t += TS;
    }

    printf("----------------------------------------\n");
    printf("Simulation complete.\n");
    printf("Final state: Vc = %.3f V, iL = %.3f A\n", inv.v_c, inv.i_L);
    printf("Damping voltage: Vdamp = %.3f V\n", ctrl.v_damp);
    printf("Modulation index: D = %.3f\n", ctrl.d);

    /* 验证阻尼注入效果 */
    printf("\n--- Impedance Reshaping Verification ---\n");
    float z_out_original = sqrtf(R_L * R_L + (W0 * L_F) * (W0 * L_F));
    float z_virtual = K_VIRTUAL_R;
    float z_out_new = z_out_original + z_virtual;
    printf("Original output impedance at 50Hz: %.4f Ohm\n", z_out_original);
    printf("Virtual damping resistance:        %.4f Ohm\n", z_virtual);
    printf("Reshaped output impedance:         %.4f Ohm\n", z_out_new);
    printf("Damping ratio improvement:         %.2fx\n", z_out_new / z_out_original);

    return 0;
}
