#include <stdio.h>
#include <math.h>
#include <string.h>

/* ==================== Mock 寄存器与宏定义 ==================== */
#define MOCK_REG_ADC_U (*(volatile float *)0x40000000)
#define MOCK_REG_ADC_V (*(volatile float *)0x40000004)
#define MOCK_REG_ADC_W (*(volatile float *)0x40000008)
#define MOCK_REG_PWM_U (*(volatile float *)0x40000010)
#define MOCK_REG_PWM_V (*(volatile float *)0x40000014)
#define MOCK_REG_PWM_W (*(volatile float *)0x40000018)

#define PI 3.14159265358979323846f
#define TWO_PI (2.0f * PI)
#define SQRT3 1.7320508075688772935f
#define SQRT2 1.4142135623730950488f

#define GRID_FREQ_HZ 50.0f
#define CONTROL_FREQ_HZ 10000.0f
#define TS (1.0f / CONTROL_FREQ_HZ)

/* 负序抑制 PI 参数 */
#define NEG_SEQ_KP 0.5f
#define NEG_SEQ_KI 20.0f

/* 限幅 */
#define VOLTAGE_LIMIT 400.0f
#define CURRENT_LIMIT 50.0f

/* ==================== 数据结构 ==================== */
typedef struct {
    float alpha;
    float beta;
} AlphaBeta;

typedef struct {
    float d;
    float q;
} DQ;

typedef struct {
    float kp;
    float ki;
    float integral;
    float out_max;
    float out_min;
} PI_Controller;

typedef struct {
    float theta;
    float sin_val;
    float cos_val;
} PLL_State;

typedef struct {
    float u_neg_d;
    float u_neg_q;
    float i_neg_d;
    float i_neg_q;
    float comp_alpha;
    float comp_beta;
} NegSeqComp;

/* ==================== 全局变量 ==================== */
static PLL_State g_pll;
static PI_Controller g_pi_neg_d;
static PI_Controller g_pi_neg_q;
static NegSeqComp g_neg_comp;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

static void pi_init(PI_Controller *pi, float kp, float ki, float out_max, float out_min)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_max = out_max;
    pi->out_min = out_min;
}

static float pi_update(PI_Controller *pi, float error, float ts)
{
    float p_term = pi->kp * error;
    pi->integral += pi->ki * error * ts;
    pi->integral = clampf(pi->integral, pi->out_min, pi->out_max);
    float out = p_term + pi->integral;
    return clampf(out, pi->out_min, pi->out_max);
}

/* Clarke 变换: abc -> alpha-beta (等幅值) */
static AlphaBeta clarke_transform(float a, float b, float c)
{
    AlphaBeta ab;
    ab.alpha = (2.0f / 3.0f) * (a - 0.5f * b - 0.5f * c);
    ab.beta = (2.0f / 3.0f) * (SQRT3 * 0.5f * (b - c));
    return ab;
}

/* 逆 Clarke 变换: alpha-beta -> abc */
static void inv_clarke_transform(AlphaBeta ab, float *a, float *b, float *c)
{
    *a = ab.alpha;
    *b = -0.5f * ab.alpha + (SQRT3 * 0.5f) * ab.beta;
    *c = -0.5f * ab.alpha - (SQRT3 * 0.5f) * ab.beta;
}

/* Park 变换: alpha-beta -> dq */
static DQ park_transform(AlphaBeta ab, float sin_t, float cos_t)
{
    DQ dq;
    dq.d = ab.alpha * cos_t + ab.beta * sin_t;
    dq.q = -ab.alpha * sin_t + ab.beta * cos_t;
    return dq;
}

/* 逆 Park 变换: dq -> alpha-beta */
static AlphaBeta inv_park_transform(DQ dq, float sin_t, float cos_t)
{
    AlphaBeta ab;
    ab.alpha = dq.d * cos_t - dq.q * sin_t;
    ab.beta = dq.d * sin_t + dq.q * cos_t;
    return ab;
}

/* 简易 PLL 更新 (用于获取电网相位) */
static void pll_update(PLL_State *pll, float u_alpha, float u_beta, float ts)
{
    float error = -u_alpha * pll->sin_val + u_beta * pll->cos_val;
    float omega = TWO_PI * GRID_FREQ_HZ;
    float kp_pll = 50.0f;
    float ki_pll = 2000.0f;
    static float integral_pll = 0.0f;
    integral_pll += ki_pll * error * ts;
    integral_pll = clampf(integral_pll, -100.0f, 100.0f);
    float freq_correction = kp_pll * error + integral_pll;
    float omega_est = omega + freq_correction;
    pll->theta += omega_est * ts;
    if (pll->theta > TWO_PI) pll->theta -= TWO_PI;
    if (pll->theta < 0.0f) pll->theta += TWO_PI;
    pll->sin_val = sinf(pll->theta);
    pll->cos_val = cosf(pll->theta);
}

/* 负序提取: 通过 dq 旋转坐标系下的 2 倍频滤波 */
static void extract_negative_sequence(AlphaBeta u_ab, AlphaBeta i_ab,
                                       PLL_State *pll, NegSeqComp *neg,
                                       float ts)
{
    /* 负序旋转坐标系: theta_neg = -theta */
    float sin_neg = -pll->sin_val;
    float cos_neg = pll->cos_val;

    /* 将电压电流变换到负序 dq 坐标系 */
    DQ u_neg = park_transform(u_ab, sin_neg, cos_neg);
    DQ i_neg = park_transform(i_ab, sin_neg, cos_neg);

    /* 低通滤波提取直流分量 (负序分量在负序 dq 下为直流) */
    static float u_neg_d_filt = 0.0f;
    static float u_neg_q_filt = 0.0f;
    static float i_neg_d_filt = 0.0f;
    static float i_neg_q_filt = 0.0f;

    float lpf_alpha = 0.05f; /* 低通滤波系数 */

    u_neg_d_filt += lpf_alpha * (u_neg.d - u_neg_d_filt);
    u_neg_q_filt += lpf_alpha * (u_neg.q - u_neg_q_filt);
    i_neg_d_filt += lpf_alpha * (i_neg.d - i_neg_d_filt);
    i_neg_q_filt += lpf_alpha * (i_neg.q - i_neg_q_filt);

    neg->u_neg_d = u_neg_d_filt;
    neg->u_neg_q = u_neg_q_filt;
    neg->i_neg_d = i_neg_d_filt;
    neg->i_neg_q = i_neg_q_filt;
}

/* 负序补偿计算 */
static AlphaBeta negative_sequence_compensation(NegSeqComp *neg,
                                                 PI_Controller *pi_d,
                                                 PI_Controller *pi_q,
                                                 PLL_State *pll,
                                                 float ts)
{
    /* 负序电流指令: 抑制负序电流为零 */
    float i_neg_d_ref = 0.0f;
    float i_neg_q_ref = 0.0f;

    float err_d = i_neg_d_ref - neg->i_neg_d;
    float err_q = i_neg_q_ref - neg->i_neg_q;

    float comp_d = pi_update(pi_d, err_d, ts);
    float comp_q = pi_update(pi_q, err_q, ts);

    /* 将补偿量从负序 dq 变换回 alpha-beta */
    float sin_neg = -pll->sin_val;
    float cos_neg = pll->cos_val;

    DQ comp_dq;
    comp_dq.d = comp_d;
    comp_dq.q = comp_q;

    AlphaBeta comp_ab = inv_park_transform(comp_dq, sin_neg, cos_neg);

    neg->comp_alpha = comp_ab.alpha;
    neg->comp_beta = comp_ab.beta;

    return comp_ab;
}

/* ==================== 主控制算法 ==================== */
static void inverter_control_step(float u_a, float u_b, float u_c,
                                   float i_a, float i_b, float i_c,
                                   float *pwm_a, float *pwm_b, float *pwm_c)
{
    /* 1. Clarke 变换 */
    AlphaBeta u_ab = clarke_transform(u_a, u_b, u_c);
    AlphaBeta i_ab = clarke_transform(i_a, i_b, i_c);

    /* 2. PLL 更新 */
    pll_update(&g_pll, u_ab.alpha, u_ab.beta, TS);

    /* 3. 负序提取 */
    extract_negative_sequence(u_ab, i_ab, &g_pll, &g_neg_comp, TS);

    /* 4. 负序补偿计算 */
    AlphaBeta comp_ab = negative_sequence_compensation(&g_neg_comp,
                                                        &g_pi_neg_d,
                                                        &g_pi_neg_q,
                                                        &g_pll,
                                                        TS);

    /* 5. 正序电流控制 (简化: 仅做电压前馈 + 负序补偿) */
    /* 正序 dq 变换 */
    DQ u_pos_dq = park_transform(u_ab, g_pll.sin_val, g_pll.cos_val);
    DQ i_pos_dq = park_transform(i_ab, g_pll.sin_val, g_pll.cos_val);

    /* 正序电流指令 (简化: 仅维持电压) */
    float i_pos_d_ref = 0.0f;
    float i_pos_q_ref = 0.0f;

    /* 正序 PI 控制 (简化) */
    static PI_Controller pi_pos_d;
    static PI_Controller pi_pos_q;
    static int pos_pi_init = 0;
    if (!pos_pi_init) {
        pi_init(&pi_pos_d, 1.0f, 50.0f, VOLTAGE_LIMIT, -VOLTAGE_LIMIT);
        pi_init(&pi_pos_q, 1.0f, 50.0f, VOLTAGE_LIMIT, -VOLTAGE_LIMIT);
        pos_pi_init = 1;
    }

    float v_pos_d = pi_update(&pi_pos_d, i_pos_d_ref - i_pos_dq.d, TS);
    float v_pos_q = pi_update(&pi_pos_q, i_pos_q_ref - i_pos_dq.q, TS);

    /* 正序电压前馈 */
    v_pos_d += u_pos_dq.d;
    v_pos_q += u_pos_dq.q;

    DQ v_pos_dq;
    v_pos_dq.d = v_pos_d;
    v_pos_dq.q = v_pos_q;

    AlphaBeta v_pos_ab = inv_park_transform(v_pos_dq, g_pll.sin_val, g_pll.cos_val);

    /* 6. 合成最终电压指令: 正序 + 负序补偿 */
    AlphaBeta v_ref_ab;
    v_ref_ab.alpha = v_pos_ab.alpha + comp_ab.alpha;
    v_ref_ab.beta = v_pos_ab.beta + comp_ab.beta;

    /* 限幅 */
    v_ref_ab.alpha = clampf(v_ref_ab.alpha, -VOLTAGE_LIMIT, VOLTAGE_LIMIT);
    v_ref_ab.beta = clampf(v_ref_ab.beta, -VOLTAGE_LIMIT, VOLTAGE_LIMIT);

    /* 7. 逆 Clarke 变换得到三相电压指令 */
    float v_a, v_b, v_c;
    inv_clarke_transform(v_ref_ab, &v_a, &v_b, &v_c);

    /* 8. 归一化到 PWM 占空比 (假设母线电压 700V) */
    float vdc = 700.0f;
    *pwm_a = clampf(v_a / (vdc * 0.5f), -1.0f, 1.0f);
    *pwm_b = clampf(v_b / (vdc * 0.5f), -1.0f, 1.0f);
    *pwm_c = clampf(v_c / (vdc * 0.5f), -1.0f, 1.0f);
}

/* ==================== 测试打印 ==================== */
static void print_neg_seq(const NegSeqComp *neg)
{
    printf("NegSeq: u_d = %8.4f, u_q = %8.4f, i_d = %8.4f, i_q = %8.4f\n",
           neg->u_neg_d, neg->u_neg_q, neg->i_neg_d, neg->i_neg_q);
    printf("NegSeq: comp_alpha = %8.4f, comp_beta = %8.4f\n",
           neg->comp_alpha, neg->comp_beta);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("========================================\n");
    printf("Three-Phase Inverter Negative Sequence\n");
    printf("Compensation Control Algorithm Test\n");
    printf("========================================\n\n");

    /* 初始化 PI 控制器 */
    pi_init(&g_pi_neg_d, NEG_SEQ_KP, NEG_SEQ_KI, VOLTAGE_LIMIT, -VOLTAGE_LIMIT);
    pi_init(&g_pi_neg_q, NEG_SEQ_KP, NEG_SEQ_KI, VOLTAGE_LIMIT, -VOLTAGE_LIMIT);

    /* 初始化 PLL */
    g_pll.theta = 0.0f;
    g_pll.sin_val = 0.0f;
    g_pll.cos_val = 1.0f;

    /* 模拟不平衡负载: A 相重载, B/C 相轻载 */
    float u_a, u_b, u_c;
    float i_a, i_b, i_c;
    float pwm_a, pwm_b, pwm_c;

    int step;
    int total_steps = 20;

    printf("Step |    Ua     Ub     Uc   |    Ia     Ib     Ic   |  PWM_A  PWM_B  PWM_C\n");
    printf("-----+------------------------+------------------------+----------------------\n");

    for (step = 0; step < total_steps; step++) {
        float t = step * TS;
        float theta = TWO_PI * GRID_FREQ_HZ * t;

        /* 模拟三相电压 (平衡) */
        u_a = 311.0f * sinf(theta);
        u_b = 311.0f * sinf(theta - TWO_PI / 3.0f);
        u_c = 311.0f * sinf(theta + TWO_PI / 3.0f);

        /* 模拟不平衡电流: A 相幅值大, B/C 相幅值小且相位偏移 */
        i_a = 30.0f * sinf(theta - 0.1f);
        i_b = 15.0f * sinf(theta - TWO_PI / 3.0f + 0.2f);
        i_c = 15.0f * sinf(theta + TWO_PI / 3.0f - 0.2f);

        /* 执行控制算法 */
        inverter_control_step(u_a, u_b, u_c, i_a, i_b, i_c,
                              &pwm_a, &pwm_b, &pwm_c);

        /* 打印结果 */
        printf("%4d | %6.1f %6.1f %6.1f | %6.1f %6.1f %6.1f | %6.3f %6.3f %6.3f\n",
               step, u_a, u_b, u_c, i_a, i_b, i_c, pwm_a, pwm_b, pwm_c);
    }

    printf("\n========================================\n");
    printf("Final Negative Sequence Compensation:\n");
    print_neg_seq(&g_neg_comp);

    /* 打印最终 PLL 状态 */
    printf("\nPLL State: theta = %.4f rad, sin = %.4f, cos = %.4f\n",
           g_pll.theta, g_pll.sin_val, g_pll.cos_val);

    printf("\nTest completed successfully.\n");
    return 0;
}
