#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define REG_PWM_CR      0x40000000U
#define REG_PWM_SR      0x40000004U
#define REG_ADC_DR      0x40000008U
#define REG_ADC_CR      0x4000000CU
#define REG_TIM_ARR     0x40000010U
#define REG_TIM_CCR1    0x40000014U
#define REG_TIM_CCR2    0x40000018U
#define REG_GPIO_ODR    0x4000001CU

#define PWM_ENABLE      (1U << 0)
#define PWM_UPDATE      (1U << 1)
#define ADC_START       (1U << 0)
#define ADC_EOC         (1U << 1)

static volatile uint32_t mock_regs[8];

static inline void reg_write(uint32_t addr, uint32_t val)
{
    mock_regs[(addr >> 2) & 0x07U] = val;
}

static inline uint32_t reg_read(uint32_t addr)
{
    return mock_regs[(addr >> 2) & 0x07U];
}

/* ================= 系统参数 ================= */
#define PWM_FREQ_HZ         100000.0f
#define DEAD_TIME_NS        200.0f
#define ZVS_MIN_CURRENT_A   0.5f
#define ZCS_MAX_CURRENT_A   5.0f
#define VIN_NOMINAL_V       400.0f
#define VOUT_TARGET_V       48.0f
#define L_RESONANT_H        2.0e-6f
#define C_RESONANT_F        10.0e-9f
#define PI_F                3.14159265358979323846f

/* ================= 状态机定义 ================= */
typedef enum {
    STATE_IDLE = 0,
    STATE_ZVS_PRECHARGE,
    STATE_ZVS_ACTIVE,
    STATE_ZCS_ACTIVE,
    STATE_FAULT
} sw_state_t;

/* ================= 控制器结构体 ================= */
typedef struct {
    sw_state_t state;
    float vin;
    float vout;
    float i_resonant;
    float phase_shift_deg;
    float duty_cycle;
    float zvs_current_threshold;
    float zcs_current_threshold;
    float dead_time_ns;
    uint32_t pwm_period_ticks;
    uint32_t pwm_duty_ticks;
    uint32_t fault_count;
} sw_ctrl_t;

/* ================= 工具函数 ================= */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static float adc_to_voltage(uint32_t raw)
{
    return ((float)raw / 4095.0f) * 500.0f;
}

static float adc_to_current(uint32_t raw)
{
    return ((float)raw / 4095.0f) * 10.0f;
}

/* ================= 软开关控制核心 ================= */
static void sw_ctrl_init(sw_ctrl_t *ctrl)
{
    ctrl->state = STATE_IDLE;
    ctrl->vin = 0.0f;
    ctrl->vout = 0.0f;
    ctrl->i_resonant = 0.0f;
    ctrl->phase_shift_deg = 0.0f;
    ctrl->duty_cycle = 0.5f;
    ctrl->zvs_current_threshold = ZVS_MIN_CURRENT_A;
    ctrl->zcs_current_threshold = ZCS_MAX_CURRENT_A;
    ctrl->dead_time_ns = DEAD_TIME_NS;
    ctrl->pwm_period_ticks = (uint32_t)(1000000000.0f / PWM_FREQ_HZ);
    ctrl->pwm_duty_ticks = (uint32_t)((float)ctrl->pwm_period_ticks * ctrl->duty_cycle);
    ctrl->fault_count = 0;

    reg_write(REG_TIM_ARR, ctrl->pwm_period_ticks);
    reg_write(REG_TIM_CCR1, ctrl->pwm_duty_ticks);
    reg_write(REG_TIM_CCR2, ctrl->pwm_duty_ticks);
    reg_write(REG_PWM_CR, PWM_ENABLE);
}

static void sw_ctrl_read_sensors(sw_ctrl_t *ctrl)
{
    uint32_t raw_v = reg_read(REG_ADC_DR);
    uint32_t raw_i = reg_read(REG_ADC_DR + 4U);

    ctrl->vin = adc_to_voltage(raw_v);
    ctrl->i_resonant = adc_to_current(raw_i);
    ctrl->vout = ctrl->vin * ctrl->duty_cycle * 0.9f;
}

static float sw_ctrl_calc_zvs_phase(sw_ctrl_t *ctrl)
{
    float zvs_margin;
    float phase;

    if (ctrl->i_resonant < ctrl->zvs_current_threshold) {
        zvs_margin = 0.0f;
    } else {
        zvs_margin = (ctrl->i_resonant - ctrl->zvs_current_threshold) /
                     (ctrl->zcs_current_threshold - ctrl->zvs_current_threshold);
    }
    zvs_margin = clampf(zvs_margin, 0.0f, 1.0f);

    phase = 180.0f * (1.0f - zvs_margin * 0.5f);

    if (ctrl->vin > 0.0f) {
        float v_ratio = ctrl->vout / ctrl->vin;
        phase *= (1.0f - v_ratio * 0.3f);
    }

    return clampf(phase, 0.0f, 180.0f);
}

static float sw_ctrl_calc_zcs_duty(sw_ctrl_t *ctrl)
{
    float duty;
    float i_norm;

    i_norm = ctrl->i_resonant / ctrl->zcs_current_threshold;
    i_norm = clampf(i_norm, 0.0f, 2.0f);

    duty = 0.5f - (i_norm - 1.0f) * 0.15f;

    return clampf(duty, 0.1f, 0.9f);
}

static void sw_ctrl_update_pwm(sw_ctrl_t *ctrl)
{
    uint32_t period = ctrl->pwm_period_ticks;
    uint32_t duty_ticks;

    duty_ticks = (uint32_t)((float)period * ctrl->duty_cycle);
    if (duty_ticks >= period) {
        duty_ticks = period - 1U;
    }

    reg_write(REG_TIM_CCR1, duty_ticks);
    reg_write(REG_TIM_CCR2, period - duty_ticks);
    reg_write(REG_PWM_SR, PWM_UPDATE);
}

static void sw_ctrl_state_machine(sw_ctrl_t *ctrl)
{
    switch (ctrl->state) {
    case STATE_IDLE:
        if (ctrl->vin > 50.0f) {
            ctrl->state = STATE_ZVS_PRECHARGE;
            printf("[STATE] IDLE -> ZVS_PRECHARGE (Vin=%.1fV)\n", ctrl->vin);
        }
        break;

    case STATE_ZVS_PRECHARGE:
        ctrl->duty_cycle = 0.5f;
        ctrl->phase_shift_deg = 180.0f;
        if (ctrl->i_resonant > ctrl->zvs_current_threshold) {
            ctrl->state = STATE_ZVS_ACTIVE;
            printf("[STATE] ZVS_PRECHARGE -> ZVS_ACTIVE (Ir=%.2fA)\n", ctrl->i_resonant);
        }
        break;

    case STATE_ZVS_ACTIVE:
        ctrl->phase_shift_deg = sw_ctrl_calc_zvs_phase(ctrl);
        ctrl->duty_cycle = 0.5f;

        if (ctrl->i_resonant > ctrl->zcs_current_threshold) {
            ctrl->state = STATE_ZCS_ACTIVE;
            printf("[STATE] ZVS_ACTIVE -> ZCS_ACTIVE (Ir=%.2fA)\n", ctrl->i_resonant);
        }
        if (ctrl->i_resonant < 0.1f && ctrl->vin > 100.0f) {
            ctrl->state = STATE_FAULT;
            ctrl->fault_count++;
            printf("[FAULT] ZVS lost! Ir=%.2fA\n", ctrl->i_resonant);
        }
        break;

    case STATE_ZCS_ACTIVE:
        ctrl->duty_cycle = sw_ctrl_calc_zcs_duty(ctrl);
        ctrl->phase_shift_deg = 180.0f;

        if (ctrl->i_resonant < ctrl->zvs_current_threshold) {
            ctrl->state = STATE_ZVS_ACTIVE;
            printf("[STATE] ZCS_ACTIVE -> ZVS_ACTIVE (Ir=%.2fA)\n", ctrl->i_resonant);
        }
        if (ctrl->i_resonant > ctrl->zcs_current_threshold * 1.5f) {
            ctrl->state = STATE_FAULT;
            ctrl->fault_count++;
            printf("[FAULT] ZCS overcurrent! Ir=%.2fA\n", ctrl->i_resonant);
        }
        break;

    case STATE_FAULT:
        ctrl->duty_cycle = 0.0f;
        ctrl->phase_shift_deg = 0.0f;
        reg_write(REG_PWM_CR, 0U);
        if (ctrl->fault_count > 3U) {
            printf("[STATE] FAULT -> IDLE (recovery)\n");
            ctrl->state = STATE_IDLE;
            ctrl->fault_count = 0;
            reg_write(REG_PWM_CR, PWM_ENABLE);
        }
        break;

    default:
        ctrl->state = STATE_IDLE;
        break;
    }
}

static void sw_ctrl_run(sw_ctrl_t *ctrl)
{
    sw_ctrl_read_sensors(ctrl);
    sw_ctrl_state_machine(ctrl);
    sw_ctrl_update_pwm(ctrl);
}

/* ================= 测试打印 ================= */
static void print_status(const sw_ctrl_t *ctrl, int step)
{
    const char *state_names[] = {
        "IDLE", "ZVS_PRECHARGE", "ZVS_ACTIVE", "ZCS_ACTIVE", "FAULT"
    };

    printf("Step %2d | State: %-14s | Vin: %6.1fV | Vout: %5.1fV | "
           "Ir: %5.2fA | Duty: %.3f | Phase: %6.1f deg\n",
           step,
           state_names[ctrl->state],
           ctrl->vin,
           ctrl->vout,
           ctrl->i_resonant,
           ctrl->duty_cycle,
           ctrl->phase_shift_deg);
}

/* ================= 主函数 ================= */
int main(void)
{
    sw_ctrl_t ctrl;
    int step;
    uint32_t test_vin_raw[] = {0, 200, 800, 1500, 2500, 3000, 3500, 3000, 2000, 1000};
    uint32_t test_ir_raw[]  = {0, 50, 200, 500, 800, 1200, 1500, 1000, 600, 300};
    int num_steps = (int)(sizeof(test_vin_raw) / sizeof(test_vin_raw[0]));

    printf("========================================\n");
    printf("  Rectifier Soft-Switching (ZVS/ZCS)   \n");
    printf("  Control Algorithm Test               \n");
    printf("========================================\n\n");

    sw_ctrl_init(&ctrl);

    for (step = 0; step < num_steps; step++) {
        reg_write(REG_ADC_DR, test_vin_raw[step]);
        reg_write(REG_ADC_DR + 4U, test_ir_raw[step]);

        sw_ctrl_run(&ctrl);
        print_status(&ctrl, step);
    }

    printf("\n========================================\n");
    printf("  Test Complete. Faults: %u\n", ctrl.fault_count);
    printf("  Final State: %d\n", (int)ctrl.state);
    printf("========================================\n");

    return 0;
}
