#include <stdio.h>
#include <stdint.h>

/* ===== Mock 寄存器与硬件抽象 ===== */
static volatile uint16_t mock_voltage_adc = 0;
static volatile uint16_t mock_current_adc = 0;
static volatile uint16_t mock_pwm_duty = 0;

#define MOCK_REG_VOLTAGE_ADC    (mock_voltage_adc)
#define MOCK_REG_CURRENT_ADC    (mock_current_adc)
#define MOCK_REG_PWM_DUTY       (mock_pwm_duty)

/* ===== 系统参数 ===== */
#define ADC_VREF                3.3f
#define ADC_RESOLUTION          4095.0f
#define VOLTAGE_DIVIDER_RATIO   11.0f
#define CURRENT_SHUNT_GAIN      0.1f
#define PWM_PERIOD              1000.0f
#define CONTROL_PERIOD_S        0.001f

/* ===== PID 结构体 ===== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
    float integral_min;
    float integral_max;
} PID_Controller;

/* ===== 全局变量 ===== */
static PID_Controller voltage_pid;
static PID_Controller current_pid;
static float target_voltage = 12.0f;
static float current_reference = 0.0f;
static float voltage_measured = 0.0f;
static float current_measured = 0.0f;
static float pwm_output = 0.0f;

/* ===== 工具函数 ===== */
static float clampf(float value, float min, float max)
{
    if (value > max) return max;
    if (value < min) return min;
    return value;
}

/* ===== PID 初始化 ===== */
static void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd,
                     float out_min, float out_max,
                     float int_min, float int_max)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->integral_min = int_min;
    pid->integral_max = int_max;
}

/* ===== PID 计算 ===== */
static float PID_Compute(PID_Controller *pid, float setpoint, float measured, float dt)
{
    float error = setpoint - measured;
    float derivative;
    float output;

    pid->integral += error * dt;
    pid->integral = clampf(pid->integral, pid->integral_min, pid->integral_max);

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    output = clampf(output, pid->output_min, pid->output_max);

    return output;
}

/* ===== 硬件读取（Mock） ===== */
static float Read_Voltage(void)
{
    uint16_t adc = MOCK_REG_VOLTAGE_ADC;
    float voltage = ((float)adc / ADC_RESOLUTION) * ADC_VREF * VOLTAGE_DIVIDER_RATIO;
    return voltage;
}

static float Read_Current(void)
{
    uint16_t adc = MOCK_REG_CURRENT_ADC;
    float current = ((float)adc / ADC_RESOLUTION) * ADC_VREF / CURRENT_SHUNT_GAIN;
    return current;
}

static void Write_PWM(float duty)
{
    uint16_t pwm_val = (uint16_t)clampf(duty, 0.0f, PWM_PERIOD);
    MOCK_REG_PWM_DUTY = pwm_val;
}

/* ===== 串级 PID 控制主循环 ===== */
static void Cascade_PID_Control(void)
{
    float dt = CONTROL_PERIOD_S;

    /* 1. 采样 */
    voltage_measured = Read_Voltage();
    current_measured = Read_Current();

    /* 2. 外环（电压环）：输出作为内环（电流环）的参考 */
    current_reference = PID_Compute(&voltage_pid, target_voltage, voltage_measured, dt);

    /* 3. 内环（电流环）：输出作为 PWM 占空比 */
    pwm_output = PID_Compute(&current_pid, current_reference, current_measured, dt);

    /* 4. 输出到执行器 */
    Write_PWM(pwm_output);
}

/* ===== 测试打印 ===== */
static void Print_Status(int step)
{
    printf("Step %3d | Vref=%.2fV Vmeas=%.2fV | Iref=%.3fA Imeas=%.3fA | PWM=%.1f\n",
           step, target_voltage, voltage_measured,
           current_reference, current_measured, pwm_output);
}

/* ===== main ===== */
int main(void)
{
    int i;

    /* 初始化外环：电压环，输出为电流参考，限幅 0~5A */
    PID_Init(&voltage_pid, 2.0f, 5.0f, 0.01f, 0.0f, 5.0f, -5.0f, 5.0f);

    /* 初始化内环：电流环，输出为 PWM 占空比，限幅 0~1000 */
    PID_Init(&current_pid, 50.0f, 200.0f, 0.5f, 0.0f, PWM_PERIOD, -PWM_PERIOD, PWM_PERIOD);

    printf("=== Cascade PID Control (Voltage Outer + Current Inner) ===\n");
    printf("Target Voltage: %.2f V\n\n", target_voltage);

    /* 模拟 50 个控制周期 */
    for (i = 0; i < 50; i++) {
        /* 模拟 ADC 反馈：将当前测量值写回 mock 寄存器 */
        float v_adc_f = (voltage_measured / VOLTAGE_DIVIDER_RATIO / ADC_VREF) * ADC_RESOLUTION;
        float i_adc_f = (current_measured * CURRENT_SHUNT_GAIN / ADC_VREF) * ADC_RESOLUTION;

        if (v_adc_f < 0.0f) v_adc_f = 0.0f;
        if (v_adc_f > ADC_RESOLUTION) v_adc_f = ADC_RESOLUTION;
        if (i_adc_f < 0.0f) i_adc_f = 0.0f;
        if (i_adc_f > ADC_RESOLUTION) i_adc_f = ADC_RESOLUTION;

        MOCK_REG_VOLTAGE_ADC = (uint16_t)v_adc_f;
        MOCK_REG_CURRENT_ADC = (uint16_t)i_adc_f;

        Cascade_PID_Control();

        if (i % 5 == 0) {
            Print_Status(i);
        }

        /* 简单一阶系统模拟：PWM 驱动电压上升 */
        voltage_measured += (pwm_output / PWM_PERIOD) * 0.5f;
        current_measured += (pwm_output / PWM_PERIOD) * 0.1f - current_measured * 0.05f;

        if (voltage_measured > 20.0f) voltage_measured = 20.0f;
        if (voltage_measured < 0.0f) voltage_measured = 0.0f;
        if (current_measured > 10.0f) current_measured = 10.0f;
        if (current_measured < 0.0f) current_measured = 0.0f;
    }

    printf("\n=== Final State ===\n");
    Print_Status(50);

    return 0;
}
