#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* ================= Mock 寄存器与宏定义 ================= */
/* 使用静态数组模拟寄存器空间，避免整数转指针导致的运行异常 */
#define MOCK_REG_SPACE_SIZE  0x2000U
static uint32_t g_mock_regs[MOCK_REG_SPACE_SIZE / 4U];

#define REG32(addr) (g_mock_regs[((uint32_t)(addr)) / 4U])

/* 模拟逆变器控制寄存器基地址 */
#define INV0_BASE       0x00000000U
#define INV1_BASE       0x00001000U

/* 寄存器偏移 */
#define INV_CTRL_OFFSET     0x00U   /* 控制寄存器 */
#define INV_STATUS_OFFSET   0x04U   /* 状态寄存器 */
#define INV_FAULT_OFFSET    0x08U   /* 故障寄存器 */
#define INV_PWM_OFFSET      0x0CU   /* PWM 输出寄存器 */

/* 控制位 */
#define INV_CTRL_ENABLE     (1U << 0)
#define INV_CTRL_MASTER     (1U << 1)
#define INV_CTRL_SYNC       (1U << 2)

/* 状态位 */
#define INV_STATUS_RUNNING  (1U << 0)
#define INV_STATUS_READY    (1U << 1)
#define INV_STATUS_FAULT    (1U << 2)

/* 故障位 */
#define INV_FAULT_OC        (1U << 0)   /* 过流 */
#define INV_FAULT_OV        (1U << 1)   /* 过压 */
#define INV_FAULT_UV        (1U << 2)   /* 欠压 */
#define INV_FAULT_OT        (1U << 3)   /* 过温 */

/* 模拟寄存器访问宏 */
#define INV_REG(base, offset)   REG32((base) + (offset))

/* ================= 系统参数 ================= */
#define INV_NUM             2U      /* 逆变器数量 */
#define SWITCH_DELAY_MS     5U      /* 主备切换延时(ms) */
#define FAULT_CONFIRM_CNT   3U      /* 故障确认次数 */

/* ================= 逆变器角色枚举 ================= */
typedef enum {
    ROLE_SLAVE = 0,
    ROLE_MASTER = 1
} inv_role_t;

/* ================= 逆变器状态结构体 ================= */
typedef struct {
    uint32_t base_addr;         /* 寄存器基地址 */
    inv_role_t role;            /* 当前角色 */
    bool     enabled;           /* 使能状态 */
    bool     fault_latched;     /* 故障锁存 */
    uint32_t fault_code;        /* 故障码 */
    uint32_t fault_cnt;         /* 故障计数 */
    uint32_t switch_cnt;        /* 切换次数 */
} inv_channel_t;

/* ================= 全局变量 ================= */
static inv_channel_t g_inv[INV_NUM];
static uint32_t g_active_master = 0U;   /* 当前主逆变器索引 */
static uint32_t g_switch_pending = 0U;  /* 待切换目标索引 */
static uint32_t g_switch_timer = 0U;    /* 切换延时计数器 */
static bool     g_switch_requested = false; /* 是否有切换请求 */

/* ================= 底层寄存器操作 ================= */
static void inv_hw_enable(uint32_t base, bool en)
{
    uint32_t ctrl = INV_REG(base, INV_CTRL_OFFSET);
    if (en) {
        ctrl |= INV_CTRL_ENABLE;
    } else {
        ctrl &= ~INV_CTRL_ENABLE;
    }
    INV_REG(base, INV_CTRL_OFFSET) = ctrl;
}

static void inv_hw_set_master(uint32_t base, bool master)
{
    uint32_t ctrl = INV_REG(base, INV_CTRL_OFFSET);
    if (master) {
        ctrl |= INV_CTRL_MASTER;
    } else {
        ctrl &= ~INV_CTRL_MASTER;
    }
    INV_REG(base, INV_CTRL_OFFSET) = ctrl;
}

static void inv_hw_set_sync(uint32_t base, bool sync)
{
    uint32_t ctrl = INV_REG(base, INV_CTRL_OFFSET);
    if (sync) {
        ctrl |= INV_CTRL_SYNC;
    } else {
        ctrl &= ~INV_CTRL_SYNC;
    }
    INV_REG(base, INV_CTRL_OFFSET) = ctrl;
}

static uint32_t inv_hw_get_status(uint32_t base)
{
    return INV_REG(base, INV_STATUS_OFFSET);
}

static uint32_t inv_hw_get_fault(uint32_t base)
{
    return INV_REG(base, INV_FAULT_OFFSET);
}

static void inv_hw_clear_fault(uint32_t base)
{
    INV_REG(base, INV_FAULT_OFFSET) = 0U;
}

static void inv_hw_set_pwm(uint32_t base, uint32_t duty)
{
    INV_REG(base, INV_PWM_OFFSET) = duty;
}

/* ================= 初始化 ================= */
static void inv_system_init(void)
{
    uint32_t i;

    memset(g_mock_regs, 0, sizeof(g_mock_regs));
    memset(g_inv, 0, sizeof(g_inv));

    g_inv[0].base_addr = INV0_BASE;
    g_inv[1].base_addr = INV1_BASE;

    for (i = 0U; i < INV_NUM; i++) {
        g_inv[i].role = ROLE_SLAVE;
        g_inv[i].enabled = false;
        g_inv[i].fault_latched = false;
        g_inv[i].fault_code = 0U;
        g_inv[i].fault_cnt = 0U;
        g_inv[i].switch_cnt = 0U;

        /* 硬件初始化：关闭输出，清除故障 */
        inv_hw_enable(g_inv[i].base_addr, false);
        inv_hw_set_master(g_inv[i].base_addr, false);
        inv_hw_set_sync(g_inv[i].base_addr, false);
        inv_hw_clear_fault(g_inv[i].base_addr);
        inv_hw_set_pwm(g_inv[i].base_addr, 0U);
    }

    /* 默认选择逆变器 0 为主机 */
    g_active_master = 0U;
    g_switch_pending = 0U;
    g_switch_timer = 0U;
    g_switch_requested = false;

    /* 启动主机 */
    g_inv[0].role = ROLE_MASTER;
    g_inv[0].enabled = true;
    inv_hw_set_master(g_inv[0].base_addr, true);
    inv_hw_set_sync(g_inv[0].base_addr, true);
    inv_hw_enable(g_inv[0].base_addr, true);

    /* 从机待机 */
    g_inv[1].role = ROLE_SLAVE;
    g_inv[1].enabled = false;
    inv_hw_set_master(g_inv[1].base_addr, false);
    inv_hw_set_sync(g_inv[1].base_addr, true);
    inv_hw_enable(g_inv[1].base_addr, false);

    printf("[INIT] System initialized. Master = INV%u\n", g_active_master);
}

/* ================= 故障检测 ================= */
static bool inv_check_fault(uint32_t idx)
{
    uint32_t fault;
    uint32_t status;

    if (idx >= INV_NUM) {
        return false;
    }

    fault = inv_hw_get_fault(g_inv[idx].base_addr);
    status = inv_hw_get_status(g_inv[idx].base_addr);

    if ((fault != 0U) || ((status & INV_STATUS_FAULT) != 0U)) {
        g_inv[idx].fault_cnt++;
        if (g_inv[idx].fault_cnt >= FAULT_CONFIRM_CNT) {
            g_inv[idx].fault_latched = true;
            g_inv[idx].fault_code = fault;
            printf("[FAULT] INV%u fault confirmed, code = 0x%08X\n", idx, fault);
            return true;
        }
    } else {
        g_inv[idx].fault_cnt = 0U;
    }

    return false;
}

/* ================= 主备切换 ================= */
static void inv_switch_master(uint32_t new_master)
{
    uint32_t old_master = g_active_master;
    uint32_t i;

    if (new_master >= INV_NUM || new_master == old_master) {
        return;
    }

    printf("[SWITCH] Master switch: INV%u -> INV%u\n", old_master, new_master);

    /* 1. 关闭旧主机输出 */
    inv_hw_enable(g_inv[old_master].base_addr, false);
    inv_hw_set_master(g_inv[old_master].base_addr, false);
    g_inv[old_master].role = ROLE_SLAVE;
    g_inv[old_master].enabled = false;

    /* 2. 同步新主机 */
    inv_hw_set_sync(g_inv[new_master].base_addr, true);

    /* 3. 使能新主机 */
    inv_hw_set_master(g_inv[new_master].base_addr, true);
    inv_hw_enable(g_inv[new_master].base_addr, true);
    g_inv[new_master].role = ROLE_MASTER;
    g_inv[new_master].enabled = true;
    g_inv[new_master].switch_cnt++;

    /* 4. 更新全局主索引 */
    g_active_master = new_master;

    /* 5. 清除切换请求 */
    g_switch_pending = 0U;
    g_switch_timer = 0U;
    g_switch_requested = false;

    printf("[SWITCH] New master INV%u active, switch count = %u\n",
           new_master, g_inv[new_master].switch_cnt);
}

/* ================= 冗余控制主循环 ================= */
static void inv_redundancy_control(void)
{
    uint32_t i;
    bool master_fault = false;

    /* 1. 检测当前主机故障 */
    if (inv_check_fault(g_active_master)) {
        master_fault = true;
    }

    /* 2. 主机故障，寻找备用机 */
    if (master_fault && !g_switch_requested) {
        for (i = 0U; i < INV_NUM; i++) {
            if (i == g_active_master) {
                continue;
            }
            if (!g_inv[i].fault_latched) {
                g_switch_pending = i;
                g_switch_timer = SWITCH_DELAY_MS;
                g_switch_requested = true;
                printf("[REDUNDANCY] Master fault, backup INV%u selected\n", i);
                break;
            }
        }

        if (!g_switch_requested) {
            printf("[REDUNDANCY] No available backup! System shutdown.\n");
            for (i = 0U; i < INV_NUM; i++) {
                inv_hw_enable(g_inv[i].base_addr, false);
                inv_hw_set_pwm(g_inv[i].base_addr, 0U);
            }
            return;
        }
    }

    /* 3. 切换延时处理 */
    if (g_switch_requested) {
        if (g_switch_timer > 0U) {
            g_switch_timer--;
        } else {
            inv_switch_master(g_switch_pending);
        }
    }

    /* 4. 从机状态维护 */
    for (i = 0U; i < INV_NUM; i++) {
        if (i == g_active_master) {
            continue;
        }
        if (!g_inv[i].fault_latched) {
            /* 从机保持同步待机 */
            inv_hw_set_sync(g_inv[i].base_addr, true);
            inv_hw_enable(g_inv[i].base_addr, false);
            inv_hw_set_pwm(g_inv[i].base_addr, 0U);
        }
    }

    /* 5. 主机 PWM 输出 */
    if (g_inv[g_active_master].enabled) {
        inv_hw_set_pwm(g_inv[g_active_master].base_addr, 5000U);
    }
}

/* ================= 测试辅助：模拟故障注入 ================= */
static void inv_inject_fault(uint32_t idx, uint32_t fault_code)
{
    if (idx >= INV_NUM) {
        return;
    }
    INV_REG(g_inv[idx].base_addr, INV_FAULT_OFFSET) = fault_code;
    printf("[TEST] Inject fault 0x%08X to INV%u\n", fault_code, idx);
}

static void inv_clear_fault(uint32_t idx)
{
    if (idx >= INV_NUM) {
        return;
    }
    inv_hw_clear_fault(g_inv[idx].base_addr);
    g_inv[idx].fault_latched = false;
    g_inv[idx].fault_code = 0U;
    g_inv[idx].fault_cnt = 0U;
    printf("[TEST] Clear fault on INV%u\n", idx);
}

/* ================= 打印系统状态 ================= */
static void inv_print_status(void)
{
    uint32_t i;
    printf("---- System Status ----\n");
    printf("Active Master: INV%u\n", g_active_master);
    for (i = 0U; i < INV_NUM; i++) {
        printf("INV%u: role=%s, enabled=%d, fault_latched=%d, fault_code=0x%08X, switch_cnt=%u\n",
               i,
               (g_inv[i].role == ROLE_MASTER) ? "MASTER" : "SLAVE",
               g_inv[i].enabled,
               g_inv[i].fault_latched,
               g_inv[i].fault_code,
               g_inv[i].switch_cnt);
    }
    printf("-----------------------\n");
}

/* ================= main ================= */
int main(void)
{
    uint32_t cycle;

    printf("===== Inverter Redundancy Control Test =====\n");

    inv_system_init();
    inv_print_status();

    /* 模拟运行 20 个周期 */
    for (cycle = 0U; cycle < 20U; cycle++) {
        printf("\n[Cycle %u]\n", cycle);

        /* 在第 5 周期注入主机过流故障 */
        if (cycle == 5U) {
            inv_inject_fault(0U, INV_FAULT_OC);
        }

        /* 在第 12 周期清除故障 */
        if (cycle == 12U) {
            inv_clear_fault(0U);
        }

        inv_redundancy_control();

        if ((cycle == 5U) || (cycle == 8U) || (cycle == 12U) || (cycle == 19U)) {
            inv_print_status();
        }
    }

