#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t g_pwm_ta = 0;
static volatile uint32_t g_pwm_tb = 0;
static volatile uint32_t g_pwm_tc = 0;
static volatile uint32_t g_adc_ua = 0;
static volatile uint32_t g_adc_ub = 0;
static volatile uint32_t g_adc_uc = 0;

#define PWM_TA_REG   (g_pwm_ta)
#define PWM_TB_REG   (g_pwm_tb)
#define PWM_TC_REG   (g_pwm_tc)
#define ADC_UA_REG   (g_adc_ua)
#define ADC_UB_REG   (g_adc_ub)
#define ADC_UC_REG   (g_adc_uc)

/* 模拟系统时钟频率与 PWM 周期 */
#define PWM_PERIOD   1000.0f
#define SAMPLE_FREQ  10000.0f

/* ==================== 控制参数 ==================== */
#define PI           3.14159265358979323846f
#define VREF         220.0f          /* 目标相电压幅值 (V) */
#define KP_VOLT      0.5f            /* 电压环比例增益 */
#define KI_VOLT      0.01f           /* 电压环积分增益 */
#define MAX_DUTY     0.95f           /* 最大占空比限幅 */
#define MIN_DUTY     0.05f           /* 最小占空比限幅 */

/* ==================== 数据结构 ==================== */
typedef struct {
    float ua;           /* A 相电压采样值 */
    float ub;           /* B 相电压采样值 */
    float uc;           /* C 相电压采样值 */
    float ua_ref;       /* A 相参考电压 */
    float ub_ref;       /* B 相参考电压 */
    float uc_ref;       /* C 相参考电压 */
    float da;           /* A 相占空比 */
    float db;           /* B 相占空比 */
    float dc;           /* C 相占空比 */
    float err_a_int;    /* A 相积分误差 */
    float err_b_int;    /* B 相积分误差 */
    float err_c_int;    /* C 相积分误差 */
    float theta;        /* 参考电压相位角 */
} InvCtrl_t;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

/* 模拟读取 ADC 采样值 (实际中由硬件触发) */
static void read_adc_samples(InvCtrl_t *ctrl)
{
    /* 模拟采样：假设实际电压存在不平衡 */
    ctrl->ua = (float)ADC_UA_REG;
    ctrl->ub = (float)ADC_UB_REG;
    ctrl->uc = (float)ADC_UC_REG;
}

/* 模拟写入 PWM 比较寄存器 */
static void write_pwm_duty(float da, float db, float dc)
{
    PWM_TA_REG = (uint32_t)(da * PWM_PERIOD);
    PWM_TB_REG = (uint32_t)(db * PWM_PERIOD);
    PWM_TC_REG = (uint32_t)(dc * PWM_PERIOD);
}

/* ==================== 核心控制算法 ==================== */
/*
 * 三相逆变器相电压平衡控制
 * 原理：通过电压外环 PI 调节器，分别对三相电压进行独立闭环控制，
 *       使各相输出电压跟踪同一参考幅值，从而消除三相不平衡。
 *       参考电压由相位角 theta 生成三相对称正弦波。
 */
static void inverter_voltage_balance_control(InvCtrl_t *ctrl, float dt)
{
    float err_a, err_b, err_c;
    float ua_comp, ub_comp, uc_comp;

    /* 1. 生成三相对称参考电压 */
    ctrl->ua_ref = VREF * sinf(ctrl->theta);
    ctrl->ub_ref = VREF * sinf(ctrl->theta - 2.0f * PI / 3.0f);
    ctrl->uc_ref = VREF * sinf(ctrl->theta + 2.0f * PI / 3.0f);

    /* 2. 读取实际相电压 */
    read_adc_samples(ctrl);

    /* 3. 计算各相电压误差 */
    err_a = ctrl->ua_ref - ctrl->ua;
    err_b = ctrl->ub_ref - ctrl->ub;
    err_c = ctrl->uc_ref - ctrl->uc;

    /* 4. 积分项累加 (带抗积分饱和) */
    ctrl->err_a_int += err_a * dt;
    ctrl->err_b_int += err_b * dt;
    ctrl->err_c_int += err_c * dt;

    /* 积分限幅 */
    ctrl->err_a_int = clampf(ctrl->err_a_int, -MAX_DUTY, MAX_DUTY);
    ctrl->err_b_int = clampf(ctrl->err_b_int, -MAX_DUTY, MAX_DUTY);
    ctrl->err_c_int = clampf(ctrl->err_c_int, -MAX_DUTY, MAX_DUTY);

    /* 5. PI 调节器输出补偿量 */
    ua_comp = KP_VOLT * err_a + KI_VOLT * ctrl->err_a_int;
    ub_comp = KP_VOLT * err_b + KI_VOLT * ctrl->err_b_int;
    uc_comp = KP_VOLT * err_c + KI_VOLT * ctrl->err_c_int;

    /* 6. 计算占空比 (前馈 + 反馈补偿) */
    ctrl->da = 0.5f + ua_comp;
    ctrl->db = 0.5f + ub_comp;
    ctrl->dc = 0.5f + uc_comp;

    /* 7. 占空比限幅 */
    ctrl->da = clampf(ctrl->da, MIN_DUTY, MAX_DUTY);
    ctrl->db = clampf(ctrl->db, MIN_DUTY, MAX_DUTY);
    ctrl->dc = clampf(ctrl->dc, MIN_DUTY, MAX_DUTY);

    /* 8. 更新 PWM 输出 */
    write_pwm_duty(ctrl->da, ctrl->db, ctrl->dc);

    /* 9. 更新相位角 */
    ctrl->theta += 2.0f * PI * 50.0f * dt;  /* 50Hz 基波 */
    if (ctrl->theta > 2.0f * PI) {
        ctrl->theta -= 2.0f * PI;
    }
}

/* ==================== 初始化 ==================== */
static void inverter_ctrl_init(InvCtrl_t *ctrl)
{
    ctrl->ua = 0.0f;
    ctrl->ub = 0.0f;
    ctrl->uc = 0.0f;
    ctrl->ua_ref = 0.0f;
    ctrl->ub_ref = 0.0f;
    ctrl->uc_ref = 0.0f;
    ctrl->da = 0.5f;
    ctrl->db = 0.5f;
    ctrl->dc = 0.5f;
    ctrl->err_a_int = 0.0f;
    ctrl->err_b_int = 0.0f;
    ctrl->err_c_int = 0.0f;
    ctrl->theta = 0.0f;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    InvCtrl_t ctrl;
    float dt = 1.0f / SAMPLE_FREQ;
    int step;

    printf("========================================\n");
    printf("  三相逆变器相电压平衡控制算法测试\n");
    printf("========================================\n\n");

    inverter_ctrl_init(&ctrl);

    /* 模拟 20 个控制周期 */
    for (step = 0; step < 20; step++) {
        /* 模拟 ADC 采样：人为制造三相不平衡 */
        ADC_UA_REG = (uint32_t)(200.0f + 10.0f * sinf(ctrl.theta));
        ADC_UB_REG = (uint32_t)(210.0f + 10.0f * sinf(ctrl.theta - 2.0f * PI / 3.0f));
        ADC_UC_REG = (uint32_t)(190.0f + 10.0f * sinf(ctrl.theta + 2.0f * PI / 3.0f));

        /* 执行控制算法 */
        inverter_voltage_balance_control(&ctrl, dt);

        /* 打印调试信息 */
        printf("Step %2d | theta=%6.3f rad\n", step, ctrl.theta);
        printf("  Ref: Ua=%7.2f  Ub=%7.2f  Uc=%7.2f\n",
               ctrl.ua_ref, ctrl.ub_ref, ctrl.uc_ref);
        printf("  Act: Ua=%7.2f  Ub=%7.2f  Uc=%7.2f\n",
               ctrl.ua, ctrl.ub, ctrl.uc);
        printf("  Duty: Da=%6.3f  Db=%6.3f  Dc=%6.3f\n",
               ctrl.da, ctrl.db, ctrl.dc);
        printf("  PWM: TA=%4u  TB=%4u  TC=%4u\n\n",
               (unsigned)PWM_TA_REG, (unsigned)PWM_TB_REG, (unsigned)PWM_TC_REG);
    }

    printf("========================================\n");
    printf("  测试完成\n");
    printf("========================================\n");

    return 0;
}
