#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 *  Mock 寄存器与硬件抽象层（HAL）
 *  使用普通全局变量模拟寄存器，避免非法地址访问导致崩溃
 * ============================================================ */

static volatile uint16_t g_adc_result_reg = 0;
static volatile uint32_t g_pwm_enable_reg = 0;
static volatile uint32_t g_precharge_relay_reg = 0;
static volatile uint32_t g_main_relay_reg = 0;
static volatile uint32_t g_sys_status_reg = 0;

#define ADC_RESULT_REG          (g_adc_result_reg)
#define PWM_ENABLE_REG          (g_pwm_enable_reg)
#define PRECHARGE_RELAY_REG     (g_precharge_relay_reg)
#define MAIN_RELAY_REG          (g_main_relay_reg)
#define SYS_STATUS_REG          (g_sys_status_reg)

#define PWM_ENABLE_BIT          (1U << 0)
#define RELAY_ON                (1U << 0)
#define RELAY_OFF               (0U << 0)

#define STATUS_PRECHARGE_DONE   (1U << 0)
#define STATUS_FAULT            (1U << 1)

/* ============================================================
 *  系统参数配置
 * ============================================================ */

#define DC_BUS_VOLTAGE_MIN      1800U
#define DC_BUS_VOLTAGE_MAX      4200U
#define DC_BUS_PRECHARGE_TARGET 3500U
#define DC_BUS_PRECHARGE_TOL    50U

#define PRECHARGE_TIMEOUT_MS    5000U
#define PRECHARGE_STABLE_MS     200U
#define CONTROL_PERIOD_MS       1U

#define VOLTAGE_DIVIDER_RATIO   100U

/* ============================================================
 *  系统状态枚举
 * ============================================================ */

typedef enum {
    STATE_IDLE = 0,
    STATE_PRECHARGE_START,
    STATE_PRECHARGE_RUN,
    STATE_PRECHARGE_STABLE,
    STATE_PRECHARGE_DONE,
    STATE_MAIN_RELAY_ON,
    STATE_RUNNING,
    STATE_FAULT
} InverterState_t;

/* ============================================================
 *  系统数据结构
 * ============================================================ */

typedef struct {
    InverterState_t state;
    uint16_t dc_bus_voltage;
    uint16_t precharge_target;
    uint32_t precharge_timer;
    uint32_t stable_timer;
    uint32_t fault_code;
    bool precharge_relay_on;
    bool main_relay_on;
    bool pwm_enabled;
} InverterCtrl_t;

/* ============================================================
 *  硬件抽象层函数（Mock）
 * ============================================================ */

static uint16_t HAL_ReadDcBusVoltage(void)
{
    uint16_t adc_raw = ADC_RESULT_REG;
    return (uint16_t)((uint32_t)adc_raw * VOLTAGE_DIVIDER_RATIO / 100U);
}

static void HAL_SetPrechargeRelay(bool on)
{
    if (on) {
        PRECHARGE_RELAY_REG |= RELAY_ON;
    } else {
        PRECHARGE_RELAY_REG &= ~RELAY_ON;
    }
}

static void HAL_SetMainRelay(bool on)
{
    if (on) {
        MAIN_RELAY_REG |= RELAY_ON;
    } else {
        MAIN_RELAY_REG &= ~RELAY_ON;
    }
}

static void HAL_SetPwmEnable(bool enable)
{
    if (enable) {
        PWM_ENABLE_REG |= PWM_ENABLE_BIT;
    } else {
        PWM_ENABLE_REG &= ~PWM_ENABLE_BIT;
    }
}

static void HAL_SetStatusFlag(uint32_t flag)
{
    SYS_STATUS_REG |= flag;
}

static void HAL_ClearStatusFlag(uint32_t flag)
{
    SYS_STATUS_REG &= ~flag;
}

static void HAL_DelayMs(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 100U; i++) {
        /* 空循环模拟延时 */
    }
}

/* ============================================================
 *  逆变器低电压启动控制（预充电）核心算法
 * ============================================================ */

static void Inverter_Init(InverterCtrl_t *ctrl)
{
    ctrl->state = STATE_IDLE;
    ctrl->dc_bus_voltage = 0;
    ctrl->precharge_target = DC_BUS_PRECHARGE_TARGET;
    ctrl->precharge_timer = 0;
    ctrl->stable_timer = 0;
    ctrl->fault_code = 0;
    ctrl->precharge_relay_on = false;
    ctrl->main_relay_on = false;
    ctrl->pwm_enabled = false;

    HAL_SetPrechargeRelay(false);
    HAL_SetMainRelay(false);
    HAL_SetPwmEnable(false);
    HAL_ClearStatusFlag(STATUS_PRECHARGE_DONE | STATUS_FAULT);
}

static void Inverter_SetFault(InverterCtrl_t *ctrl, uint32_t code)
{
    ctrl->state = STATE_FAULT;
    ctrl->fault_code = code;
    ctrl->precharge_relay_on = false;
    ctrl->main_relay_on = false;
    ctrl->pwm_enabled = false;

    HAL_SetPrechargeRelay(false);
    HAL_SetMainRelay(false);
    HAL_SetPwmEnable(false);
    HAL_SetStatusFlag(STATUS_FAULT);
}

static void Inverter_PrechargeControl(InverterCtrl_t *ctrl)
{
    ctrl->dc_bus_voltage = HAL_ReadDcBusVoltage();

    switch (ctrl->state) {
    case STATE_IDLE:
        if (ctrl->dc_bus_voltage >= DC_BUS_VOLTAGE_MIN &&
            ctrl->dc_bus_voltage <= DC_BUS_VOLTAGE_MAX) {
            ctrl->state = STATE_PRECHARGE_START;
            printf("[PRECHARGE] DC Bus Voltage = %u.%u V, entering precharge start\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        } else if (ctrl->dc_bus_voltage > DC_BUS_VOLTAGE_MAX) {
            Inverter_SetFault(ctrl, 0x0001U);
            printf("[FAULT] DC Bus Overvoltage: %u.%u V\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        }
        break;

    case STATE_PRECHARGE_START:
        HAL_SetPrechargeRelay(true);
        ctrl->precharge_relay_on = true;
        ctrl->precharge_timer = 0;
        ctrl->stable_timer = 0;
        ctrl->state = STATE_PRECHARGE_RUN;
        printf("[PRECHARGE] Precharge relay ON, target = %u.%u V\n",
               ctrl->precharge_target / 10U, ctrl->precharge_target % 10U);
        break;

    case STATE_PRECHARGE_RUN:
        ctrl->precharge_timer += CONTROL_PERIOD_MS;

        if (ctrl->precharge_timer > PRECHARGE_TIMEOUT_MS) {
            Inverter_SetFault(ctrl, 0x0002U);
            printf("[FAULT] Precharge timeout! Voltage = %u.%u V\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
            break;
        }

        if (ctrl->dc_bus_voltage >= (ctrl->precharge_target - DC_BUS_PRECHARGE_TOL) &&
            ctrl->dc_bus_voltage <= (ctrl->precharge_target + DC_BUS_PRECHARGE_TOL)) {
            ctrl->stable_timer = 0;
            ctrl->state = STATE_PRECHARGE_STABLE;
            printf("[PRECHARGE] Voltage reached target: %u.%u V, verifying stability...\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        }
        break;

    case STATE_PRECHARGE_STABLE:
        ctrl->stable_timer += CONTROL_PERIOD_MS;

        if (ctrl->dc_bus_voltage < (ctrl->precharge_target - DC_BUS_PRECHARGE_TOL) ||
            ctrl->dc_bus_voltage > (ctrl->precharge_target + DC_BUS_PRECHARGE_TOL)) {
            ctrl->state = STATE_PRECHARGE_RUN;
            printf("[PRECHARGE] Voltage unstable: %u.%u V, back to run\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
            break;
        }

        if (ctrl->stable_timer >= PRECHARGE_STABLE_MS) {
            ctrl->state = STATE_PRECHARGE_DONE;
            HAL_SetStatusFlag(STATUS_PRECHARGE_DONE);
            printf("[PRECHARGE] Precharge stable, voltage = %u.%u V\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        }
        break;

    case STATE_PRECHARGE_DONE:
        HAL_SetMainRelay(true);
        ctrl->main_relay_on = true;
        HAL_SetPrechargeRelay(false);
        ctrl->precharge_relay_on = false;
        ctrl->state = STATE_MAIN_RELAY_ON;
        printf("[PRECHARGE] Main relay ON, precharge relay OFF\n");
        break;

    case STATE_MAIN_RELAY_ON:
        HAL_SetPwmEnable(true);
        ctrl->pwm_enabled = true;
        ctrl->state = STATE_RUNNING;
        printf("[RUNNING] PWM enabled, inverter running\n");
        break;

    case STATE_RUNNING:
        if (ctrl->dc_bus_voltage < DC_BUS_VOLTAGE_MIN) {
            Inverter_SetFault(ctrl, 0x0003U);
            printf("[FAULT] DC Bus Undervoltage: %u.%u V\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        } else if (ctrl->dc_bus_voltage > DC_BUS_VOLTAGE_MAX) {
            Inverter_SetFault(ctrl, 0x0004U);
            printf("[FAULT] DC Bus Overvoltage: %u.%u V\n",
                   ctrl->dc_bus_voltage / 10U, ctrl->dc_bus_voltage % 10U);
        }
        break;

    case STATE_FAULT:
        printf("[FAULT] System in fault state, code = 0x%04X\n", ctrl->fault_code);
        break;

    default:
        ctrl->state = STATE_IDLE;
        break;
    }
}

/* ============================================================
 *  主函数 - 测试打印
 * ============================================================ */

int main(void)
{
    InverterCtrl_t inverter_ctrl;
    uint32_t loop_count = 0;
    uint16_t simulated_voltage = 0;

    printf("========================================\n");
    printf("  Inverter Low-Voltage Start Control\n");
    printf("  (Precharge) Algorithm Test\n");
    printf("========================================\n\n");

    Inverter_Init(&inverter_ctrl);
    printf("[INIT] Inverter control initialized\n");
    printf("[INIT] DC Bus Voltage Range: %u.%u V ~ %u.%u V\n",
           DC_BUS_VOLTAGE_MIN / 10U, DC_BUS_VOLTAGE_MIN % 10U,
           DC_BUS_VOLTAGE_MAX / 10U, DC_BUS_VOLTAGE_MAX % 10U);
    printf("[INIT] Precharge Target: %u.%u V\n\n",
           DC_BUS_PRECHARGE_TARGET / 10U, DC_BUS_PRECHARGE_TARGET % 10U);

    printf("--- Simulating DC Bus Voltage Ramp Up ---\n");

    for (loop_count = 0; loop_count < 6000U; loop_count++) {
        if (simulated_voltage < 3600U) {
            simulated_voltage += 2U;
        }

        ADC_RESULT_REG = simulated_voltage;

        Inverter_PrechargeControl(&inverter_ctrl);

        if ((loop_count % 500U) == 0U) {
            printf("[MONITOR] Loop=%u, State=%d, Vdc=%u.%u V, PreTimer=%u ms, StbTimer=%u ms\n",
                   loop_count,
                   (int)inverter_ctrl.state,
                   inverter_ctrl.dc_bus_voltage / 10U,
                   inverter_ctrl.dc_bus_voltage % 10U,
                   inverter_ctrl.precharge_timer,
                   inverter_ctrl.stable_timer);
        }

        if (inverter_ctrl.state == STATE_RUNNING ||
            inverter_ctrl.state == STATE_FAULT) {
            break;
        }

        HAL_DelayMs(CONTROL_PERIOD_MS);
    }

    printf("\n--- Final System State ---\n");
    printf("State: %d\n", (int)inverter_ctrl.state);
    printf("DC Bus Voltage: %u.%u V\n",
           inverter_ctrl.dc_bus_voltage / 10U, inverter_ctrl.dc_bus_voltage % 10U);

    return 0;
}
