#include <stdio.h>
#include <math.h>

/* ==================== Mock 硬件寄存器定义 ==================== */
#define MOCK_REG_PID_KP      (*(volatile float *)0x40000000)
#define MOCK_REG_PID_KI      (*(volatile float *)0x40000004)
#define MOCK_REG_PID_KD      (*(volatile float *)0x40000008)
#define MOCK_REG_PID_SETPOINT (*(volatile float *)0x4000000C)
#define MOCK_REG_PID_FEEDBACK (*(volatile float *)0x40000010)
#define MOCK_REG_PID_OUTPUT   (*(volatile float *)0x40000014)
#define MOCK_REG_PID_MODE     (*(volatile unsigned int *)0x40000018)

/* ==================== PID 结构体定义 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float setpoint;
    float feedback;
    float output;
    float integral;
    float prev_error;
    float out_min;
    float out_max;
    unsigned int mode;
} PID_TypeDef;

/* ==================== Ziegler-Nichols 自整定结构体 ==================== */
typedef struct {
    float Ku;               /* 临界增益 */
    float Tu;               /* 临界周期 */
    float Kp;
    float Ki;
    float Kd;
    unsigned int oscillating;
    unsigned int cycle_count;
    float prev_feedback;
    float max_feedback;
    float min_feedback;
    float last_peak_time;
    float current_time;
    float peak_interval_sum;
    unsigned int peak_count;
} ZN_AutoTune_TypeDef;

/* ==================== 全局变量 ==================== */
static PID_TypeDef pid;
static ZN_AutoTune_TypeDef zn;

/* ==================== PID 初始化 ==================== */
void PID_Init(PID_TypeDef *p, float kp, float ki, float kd,
              float out_min, float out_max)
{
    p->Kp = kp;
    p->Ki = ki;
    p->Kd = kd;
    p->setpoint = 0.0f;
    p->feedback = 0.0f;
    p->output = 0.0f;
    p->integral = 0.0f;
    p->prev_error = 0.0f;
    p->out_min = out_min;
    p->out_max = out_max;
    p->mode = 0;
}

/* ==================== PID 计算 ==================== */
float PID_Compute(PID_TypeDef *p, float setpoint, float feedback, float dt)
{
    float error;
    float derivative;
    float output;

    p->setpoint = setpoint;
    p->feedback = feedback;

    error = p->setpoint - p->feedback;

    p->integral += error * dt;
    derivative = (error - p->prev_error) / dt;

    output = p->Kp * error + p->Ki * p->integral + p->Kd * derivative;

    if (output > p->out_max) {
        output = p->out_max;
        p->integral -= error * dt;
    } else if (output < p->out_min) {
        output = p->out_min;
        p->integral -= error * dt;
    }

    p->prev_error = error;
    p->output = output;

    return output;
}

/* ==================== ZN 自整定初始化 ==================== */
void ZN_Init(ZN_AutoTune_TypeDef *z)
{
    z->Ku = 0.0f;
    z->Tu = 0.0f;
    z->Kp = 0.0f;
    z->Ki = 0.0f;
    z->Kd = 0.0f;
    z->oscillating = 0;
    z->cycle_count = 0;
    z->prev_feedback = 0.0f;
    z->max_feedback = -1e9f;
    z->min_feedback = 1e9f;
    z->last_peak_time = 0.0f;
    z->current_time = 0.0f;
    z->peak_interval_sum = 0.0f;
    z->peak_count = 0;
}

/* ==================== ZN 自整定步骤 ==================== */
/* 返回 0: 整定中, 1: 整定完成 */
int ZN_AutoTune(ZN_AutoTune_TypeDef *z, PID_TypeDef *p,
                float feedback, float dt)
{
    float error;
    float output;
    float peak_interval;

    z->current_time += dt;

    /* 阶段1: 仅使用比例控制，逐步增大 Kp 直到系统等幅振荡 */
    if (z->oscillating == 0) {
        /* 使用纯比例控制 */
        error = p->setpoint - feedback;
        output = p->Kp * error;

        if (output > p->out_max) output = p->out_max;
        if (output < p->out_min) output = p->out_min;

        p->output = output;

        /* 检测振荡: 反馈值穿越设定值 */
        if ((z->prev_feedback - p->setpoint) * (feedback - p->setpoint) < 0.0f) {
            z->cycle_count++;
            if (z->cycle_count >= 4) {
                /* 检测到持续振荡，记录临界增益 */
                z->Ku = p->Kp;
                z->oscillating = 1;
                z->peak_count = 0;
                z->peak_interval_sum = 0.0f;
                z->last_peak_time = z->current_time;
                z->max_feedback = feedback;
                z->min_feedback = feedback;
            }
        }

        z->prev_feedback = feedback;
        return 0;
    }

    /* 阶段2: 测量振荡周期 Tu */
    if (feedback > z->max_feedback) z->max_feedback = feedback;
    if (feedback < z->min_feedback) z->min_feedback = feedback;

    /* 检测峰值 (从上升转为下降) */
    if (z->prev_feedback < feedback && feedback > p->setpoint) {
        /* 当前可能是峰值附近，记录时间间隔 */
        peak_interval = z->current_time - z->last_peak_time;
        if (peak_interval > 0.01f) {
            z->peak_interval_sum += peak_interval;
            z->peak_count++;
            z->last_peak_time = z->current_time;
        }
    }

    z->prev_feedback = feedback;

    /* 采集足够周期后计算 Tu 和 PID 参数 */
    if (z->peak_count >= 3) {
        z->Tu = z->peak_interval_sum / (float)z->peak_count;

        /* Ziegler-Nichols 临界比例度法公式 */
        z->Kp = 0.6f * z->Ku;
        z->Ki = 2.0f * z->Kp / z->Tu;
        z->Kd = z->Kp * z->Tu / 8.0f;

        /* 更新 PID 参数 */
        p->Kp = z->Kp;
        p->Ki = z->Ki;
        p->Kd = z->Kd;
        p->integral = 0.0f;
        p->prev_error = 0.0f;

        return 1;
    }

    return 0;
}

/* ==================== 模拟被控对象 ==================== */
/* 一阶惯性 + 纯滞后近似: y[k] = a*y[k-1] + b*u[k-1] */
static float plant_sim(float input, float dt)
{
    static float y = 0.0f;
    static float u_prev = 0.0f;
    float a = 0.95f;
    float b = 0.05f;

    (void)dt;
    y = a * y + b * u_prev;
    u_prev = input;

    return y;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    float dt = 0.01f;
    float setpoint = 1.0f;
    float feedback;
    float output;
    int step;
    int tune_done = 0;

    printf("========================================\n");
    printf("  PID Ziegler-Nichols 临界比例度法自整定\n");
    printf("========================================\n\n");

    /* 初始化 PID */
    PID_Init(&pid, 0.5f, 0.0f, 0.0f, -10.0f, 10.0f);
    pid.setpoint = setpoint;

    /* 初始化 ZN 自整定 */
    ZN_Init(&zn);

    /* 阶段1: 逐步增大 Kp 寻找临界增益 */
    printf("[阶段1] 寻找临界增益 Ku...\n");
    for (step = 0; step < 2000; step++) {
        feedback = plant_sim(pid.output, dt);
        output = PID_Compute(&pid, setpoint, feedback, dt);
        (void)output;

        if (ZN_AutoTune(&zn, &pid, feedback, dt) == 1) {
            tune_done = 1;
            break;
        }

        /* 每 200 步增大一次 Kp */
        if (step % 200 == 199 && zn.oscillating == 0) {
            pid.Kp += 0.5f;
            printf("  step=%4d, Kp=%.2f, feedback=%.4f\n",
                   step, pid.Kp, feedback);
        }
    }

    if (tune_done) {
        printf("\n[阶段2] 整定完成!\n");
        printf("  临界增益 Ku = %.4f\n", zn.Ku);
        printf("  临界周期 Tu = %.4f s\n", zn.Tu);
        printf("  -------------------------\n");
        printf("  整定后 PID 参数:\n");
        printf("    Kp = %.4f\n", zn.Kp);
        printf("    Ki = %.4f\n", zn.Ki);
        printf("    Kd = %.4f\n", zn.Kd);
    } else {
        printf("\n[警告] 未检测到持续振荡，整定未完成\n");
        printf("  当前 Kp = %.4f\n", pid.Kp);
    }

    /* 使用整定后的参数运行一段时间验证 */
    printf("\n[验证] 使用整定参数运行 PID 控制...\n");
    pid.integral = 0.0f;
    pid.prev_error = 0.0f;

    for (step = 0; step < 500; step++) {
        feedback = plant_sim(pid.output, dt);
        output = PID_Compute(&pid, setpoint, feedback, dt);
        (void)output;

        if (step % 100 == 99) {
            printf("  step=%4d, setpoint=%.2f, feedback=%.4f, output=%.4f\n",
                   step, setpoint, feedback, pid.output);
        }
    }

    printf("\n========================================\n");
    printf("  自整定测试结束\n");
    printf("========================================\n");

    return 0;
}
