#include <stdio.h>
#include <math.h>

/* ============================================================
 * 逆变器死区效应补偿（电流方向判断）控制算法骨架
 * 说明：
 *   死区效应会导致输出电压偏差，偏差方向取决于相电流方向。
 *   本代码通过判断三相电流方向，计算死区补偿电压。
 * ============================================================ */

/* ---------- Mock 寄存器与宏定义（替代硬件头文件） ---------- */
#define PWM_PERIOD          1000.0f     /* PWM 周期计数值 */
#define DEAD_TIME_NS        2000.0f     /* 死区时间 2us */
#define PWM_CLK_MHZ         72.0f       /* PWM 时钟 72MHz */
#define VDC                 300.0f      /* 直流母线电压 */
#define CURRENT_THRESHOLD   0.05f       /* 电流过零判断阈值(A) */

/* 模拟的三相电流采样值 */
typedef struct {
    float ia;
    float ib;
    float ic;
} PhaseCurrent;

/* 模拟的三相占空比输出 */
typedef struct {
    float da;
    float db;
    float dc;
} PhaseDuty;

/* ---------- 电流方向枚举 ---------- */
typedef enum {
    CURRENT_POSITIVE = 1,
    CURRENT_NEGATIVE = -1,
    CURRENT_ZERO     = 0
} CurrentDir;

/* ---------- 根据电流值判断方向 ---------- */
CurrentDir get_current_direction(float current)
{
    if (current > CURRENT_THRESHOLD) {
        return CURRENT_POSITIVE;
    } else if (current < -CURRENT_THRESHOLD) {
        return CURRENT_NEGATIVE;
    } else {
        return CURRENT_ZERO;
    }
}

/* ---------- 计算死区补偿电压（伏特） ---------- */
float calc_deadtime_compensation_voltage(void)
{
    /* 死区导致的平均电压误差：
     *   ΔV = (T_dead / T_pwm) * Vdc * sign(i)
     * 其中 T_dead 为死区时间，T_pwm 为 PWM 周期
     */
    float t_pwm_ns = (PWM_PERIOD / (PWM_CLK_MHZ * 1e6f)) * 1e9f; /* PWM 周期(ns) */
    float ratio = DEAD_TIME_NS / t_pwm_ns;
    return ratio * VDC;
}

/* ---------- 死区补偿核心算法 ---------- */
void deadtime_compensation(PhaseCurrent *curr, PhaseDuty *duty)
{
    float comp_v = calc_deadtime_compensation_voltage();
    float comp_duty = comp_v / VDC;   /* 补偿占空比 */

    CurrentDir dir_a = get_current_direction(curr->ia);
    CurrentDir dir_b = get_current_direction(curr->ib);
    CurrentDir dir_c = get_current_direction(curr->ic);

    /* 根据电流方向修正占空比：
     *   电流为正：实际输出偏低，需增加占空比
     *   电流为负：实际输出偏高，需减小占空比
     *   电流为零：不补偿
     */
    if (dir_a == CURRENT_POSITIVE) {
        duty->da += comp_duty;
    } else if (dir_a == CURRENT_NEGATIVE) {
        duty->da -= comp_duty;
    }

    if (dir_b == CURRENT_POSITIVE) {
        duty->db += comp_duty;
    } else if (dir_b == CURRENT_NEGATIVE) {
        duty->db -= comp_duty;
    }

    if (dir_c == CURRENT_POSITIVE) {
        duty->dc += comp_duty;
    } else if (dir_c == CURRENT_NEGATIVE) {
        duty->dc -= comp_duty;
    }

    /* 占空比限幅 [0, 1] */
    if (duty->da > 1.0f) duty->da = 1.0f;
    if (duty->da < 0.0f) duty->da = 0.0f;
    if (duty->db > 1.0f) duty->db = 1.0f;
    if (duty->db < 0.0f) duty->db = 0.0f;
    if (duty->dc > 1.0f) duty->dc = 1.0f;
    if (duty->dc < 0.0f) duty->dc = 0.0f;
}

/* ---------- 打印辅助函数 ---------- */
const char* dir_str(CurrentDir d)
{
    switch (d) {
        case CURRENT_POSITIVE: return "POS";
        case CURRENT_NEGATIVE: return "NEG";
        default:               return "ZERO";
    }
}

/* ---------- main 测试 ---------- */
int main(void)
{
    printf("===== Inverter Dead-Time Compensation Test =====\n");
    printf("PWM Period = %.0f, Dead Time = %.0f ns, Vdc = %.0f V\n",
           PWM_PERIOD, DEAD_TIME_NS, VDC);

    float comp_v = calc_deadtime_compensation_voltage();
    printf("Dead-time compensation voltage = %.4f V\n\n", comp_v);

    /* 测试用例 1：三相电流均为正 */
    PhaseCurrent curr1 = { 1.5f, 2.0f, 0.8f };
    PhaseDuty    duty1 = { 0.50f, 0.50f, 0.50f };
    printf("Case 1: Ia=%.2f(%s), Ib=%.2f(%s), Ic=%.2f(%s)\n",
           curr1.ia, dir_str(get_current_direction(curr1.ia)),
           curr1.ib, dir_str(get_current_direction(curr1.ib)),
           curr1.ic, dir_str(get_current_direction(curr1.ic)));
    printf("  Before: Da=%.4f, Db=%.4f, Dc=%.4f\n",
           duty1.da, duty1.db, duty1.dc);
    deadtime_compensation(&curr1, &duty1);
    printf("  After : Da=%.4f, Db=%.4f, Dc=%.4f\n\n",
           duty1.da, duty1.db, duty1.dc);

    /* 测试用例 2：三相电流均为负 */
    PhaseCurrent curr2 = { -1.2f, -0.9f, -2.1f };
    PhaseDuty    duty2 = { 0.50f, 0.50f, 0.50f };
    printf("Case 2: Ia=%.2f(%s), Ib=%.2f(%s), Ic=%.2f(%s)\n",
           curr2.ia, dir_str(get_current_direction(curr2.ia)),
           curr2.ib, dir_str(get_current_direction(curr2.ib)),
           curr2.ic, dir_str(get_current_direction(curr2.ic)));
    printf("  Before: Da=%.4f, Db=%.4f, Dc=%.4f\n",
           duty2.da, duty2.db, duty2.dc);
    deadtime_compensation(&curr2, &duty2);
    printf("  After : Da=%.4f, Db=%.4f, Dc=%.4f\n\n",
           duty2.da, duty2.db, duty2.dc);

    /* 测试用例 3：混合方向，含过零 */
    PhaseCurrent curr3 = { 0.8f, -0.6f, 0.01f };
    PhaseDuty    duty3 = { 0.30f, 0.70f, 0.50f };
    printf("Case 3: Ia=%.2f(%s), Ib=%.2f(%s), Ic=%.2f(%s)\n",
           curr3.ia, dir_str(get_current_direction(curr3.ia)),
           curr3.ib, dir_str(get_current_direction(curr3.ib)),
           curr3.ic, dir_str(get_current_direction(curr3.ic)));
    printf("  Before: Da=%.4f, Db=%.4f, Dc=%.4f\n",
           duty3.da, duty3.db, duty3.dc);
    deadtime_compensation(&curr3, &duty3);
    printf("  After : Da=%.4f, Db=%.4f, Dc=%.4f\n\n",
           duty3.da, duty3.db, duty3.dc);

    printf("===== Test Finished =====\n");
    return 0;
}
