#include <stdio.h>
#include <math.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float prev_measure;
    float output_min;
    float output_max;
    float integral_sep_threshold;
} PID_Controller;

void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd,
              float out_min, float out_max, float int_sep_thresh) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_measure = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->integral_sep_threshold = int_sep_thresh;
}

float PID_Compute(PID_Controller *pid, float setpoint, float measure, float dt) {
    float error = setpoint - measure;
    float p_term = pid->Kp * error;

    float i_term = 0.0f;
    if (fabsf(error) <= pid->integral_sep_threshold) {
        pid->integral += pid->Ki * error * dt;
        i_term = pid->integral;
    }

    float d_measure = (measure - pid->prev_measure) / dt;
    float d_term = -pid->Kd * d_measure;

    float output = p_term + i_term + d_term;

    if (output > pid->output_max) {
        output = pid->output_max;
        if (error > 0.0f) {
            pid->integral -= pid->Ki * error * dt;
        }
    } else if (output < pid->output_min) {
        output = pid->output_min;
        if (error < 0.0f) {
            pid->integral -= pid->Ki * error * dt;
        }
    }

    pid->prev_error = error;
    pid->prev_measure = measure;

    return output;
}

int main(void) {
    PID_Controller pid;
    PID_Init(&pid, 2.0f, 0.5f, 0.1f, -100.0f, 100.0f, 5.0f);

    float setpoint = 50.0f;
    float measure = 0.0f;
    float dt = 0.01f;

    printf("=== Position PID with Integral Separation + Derivative on Measurement ===\n");
    printf("Setpoint: %.2f, dt: %.3f\n", setpoint, dt);
    printf("Kp=%.2f Ki=%.2f Kd=%.2f IntSepThresh=%.2f\n\n",
           pid.Kp, pid.Ki, pid.Kd, pid.integral_sep_threshold);

    for (int i = 0; i < 50; i++) {
        float output = PID_Compute(&pid, setpoint, measure, dt);

        measure += output * dt * 0.1f;

        if (i % 5 == 0) {
            printf("Step %2d | Measure: %7.3f | Output: %8.3f | Error: %7.3f | Integral: %8.3f\n",
                   i, measure, output, setpoint - measure, pid.integral);
        }
    }

    printf("\nFinal measure: %.3f (target: %.3f)\n", measure, setpoint);

    return 0;
}
