#include <stdio.h>
#include <stdint.h>

/* ================= 宏定义（模拟寄存器/参数） ================= */
#define PID_KP              2.0f
#define PID_KI              0.5f
#define PID_KD              0.1f

#define PID_OUT_MAX         100.0f
#define PID_OUT_MIN         (-100.0f)

#define PID_INTEGRAL_MAX    50.0f
#define PID_INTEGRAL_MIN    (-50.0f)

/* ================= 增量式PID结构体 ================= */
typedef struct {
    float Kp;
    float Ki;
    float Kd;

    float error;            /* 当前误差 e(k) */
    float error_last;       /* 上一次误差 e(k-1) */
    float error_prev;       /* 上上次误差 e(k-2) */

    float delta_out;        /* 增量输出 Δu(k) */
    float output;           /* 累计输出 u(k) */

    float out_max;
    float out_min;

    float integral;         /* 积分项（用于抗饱和） */
    float integral_max;
    float integral_min;
} IncPID;

/* ================= 初始化 ================= */
void IncPID_Init(IncPID *pid,
                 float Kp, float Ki, float Kd,
                 float out_max, float out_min,
                 float integral_max, float integral_min)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;

    pid->error = 0.0f;
    pid->error_last = 0.0f;
    pid->error_prev = 0.0f;

    pid->delta_out = 0.0f;
    pid->output = 0.0f;

    pid->out_max = out_max;
    pid->out_min = out_min;

    pid->integral = 0.0f;
    pid->integral_max = integral_max;
    pid->integral_min = integral_min;
}

/* ================= 增量式PID计算（抗饱和 + 输出限幅） ================= */
float IncPID_Calc(IncPID *pid, float setpoint, float feedback)
{
    float delta;
    float temp_output;

    /* 1. 计算当前误差 */
    pid->error = setpoint - feedback;

    /* 2. 计算增量 Δu(k) = Kp*(e(k)-e(k-1)) + Ki*e(k) + Kd*(e(k)-2e(k-1)+e(k-2)) */
    delta = pid->Kp * (pid->error - pid->error_last)
          + pid->Ki * pid->error
          + pid->Kd * (pid->error - 2.0f * pid->error_last + pid->error_prev);

    pid->delta_out = delta;

    /* 3. 积分项累加（用于抗饱和判断） */
    pid->integral += pid->Ki * pid->error;
    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }

    /* 4. 计算临时输出 */
    temp_output = pid->output + delta;

    /* 5. 抗饱和处理：如果输出已饱和且增量方向继续推向饱和，则抑制积分 */
    if (temp_output > pid->out_max) {
        if (delta > 0.0f) {
            /* 正向饱和且还在增大，抑制积分 */
            pid->integral -= pid->Ki * pid->error;
            if (pid->integral > pid->integral_max) {
                pid->integral = pid->integral_max;
            } else if (pid->integral < pid->integral_min) {
                pid->integral = pid->integral_min;
            }
            delta = 0.0f;
        }
        temp_output = pid->out_max;
    } else if (temp_output < pid->out_min) {
        if (delta < 0.0f) {
            /* 负向饱和且还在减小，抑制积分 */
            pid->integral -= pid->Ki * pid->error;
            if (pid->integral > pid->integral_max) {
                pid->integral = pid->integral_max;
            } else if (pid->integral < pid->integral_min) {
                pid->integral = pid->integral_min;
            }
            delta = 0.0f;
        }
        temp_output = pid->out_min;
    }

    /* 6. 更新输出 */
    pid->output = temp_output;

    /* 7. 更新误差历史 */
    pid->error_prev = pid->error_last;
    pid->error_last = pid->error;

    return pid->output;
}

/* ================= 主函数测试 ================= */
int main(void)
{
    IncPID pid;
    float setpoint = 50.0f;
    float feedback = 0.0f;
    float output;
    int i;

    IncPID_Init(&pid,
                PID_KP, PID_KI, PID_KD,
                PID_OUT_MAX, PID_OUT_MIN,
                PID_INTEGRAL_MAX, PID_INTEGRAL_MIN);

    printf("===== 增量式PID控制测试（抗饱和+输出限幅） =====\n");
    printf("设定值: %.2f, 输出范围: [%.2f, %.2f]\n\n",
           setpoint, PID_OUT_MIN, PID_OUT_MAX);

    for (i = 0; i < 30; i++) {
        /* 模拟被控对象：一阶惯性环节 */
        feedback += (output - feedback) * 0.1f;

        output = IncPID_Calc(&pid, setpoint, feedback);

        printf("Step %2d | 反馈: %7.3f | 误差: %7.3f | 增量: %7.3f | 输出: %7.3f\n",
               i + 1, feedback, pid.error, pid.delta_out, output);
    }

    printf("\n===== 测试完成 =====\n");
    return 0;
}
