#define CURRENT_AMP_GAIN  50.0f

/* ===== PID 结构体 ===== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
    float integral_min;
    float integral_max;
} PID_Controller;

/* ===== PID 初始化 ===== */
void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd,
              float out_min, float out_max,
              float int_min, float int_max)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->integral_min = int_min;
    pid->integral_max = int_max;
}

/* ===== PID 计算 ===== */
float PID_Compute(PID_Controller *pid, float setpoint, float feedback, float dt)
{
    float error = setpoint - feedback;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = 0.001f;
    }

    pid->integral += error * dt;

    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output > pid->output_max) {
        output = pid->output_max;
    } else if (output < pid->output_min) {
        output = pid->output_min;
    }

    return output;
}

/* ===== 采样电压 ===== */
float Read_Voltage(void)
{
    uint16_t adc = REG_ADC_VOLTAGE;
    float v_adc = (adc / ADC_VOLTAGE_MAX) * VREF;
    return v_adc * VOLTAGE_DIV_RATIO;
}

/* ===== 采样电流 ===== */
float Read_Current(void)
{
    uint16_t adc = REG_ADC_CURRENT;
    float v_adc = (adc / ADC_CURRENT_MAX) * VREF;
    return v_adc / (CURRENT_SHUNT * CURRENT_AMP_GAIN);
}

/* ===== 设置 PWM 占空比 ===== */
void Set_PWM_Duty(float duty)
{
    if (duty > PWM_DUTY_MAX) {
        duty = PWM_DUTY_MAX;
    } else if (duty < 0.0f) {
        duty = 0.0f;
    }
    REG_PWM_DUTY = (uint16_t)duty;
}

/* ===== 串级 PID 控制 ===== */
typedef struct {
    PID_Controller voltage_pid;
    PID_Controller current_pid;
    float voltage_setpoint;
    float current_limit;
    float voltage_feedback;
    float current_feedback;
    float current_setpoint;
    float duty_output;
} Cascade_PID;

void Cascade_PID_Init(Cascade_PID *cascade, float v_setpoint, float i_limit)
{
    PID_Init(&cascade->voltage_pid, 2.0f, 0.5f, 0.01f, 0.0f, i_limit, -i_limit, i_limit);
    PID_Init(&cascade->current_pid, 5.0f, 1.0f, 0.0f, 0.0f, PWM_DUTY_MAX, -PWM_DUTY_MAX, PWM_DUTY_MAX);
    cascade->voltage_setpoint = v_setpoint;
    cascade->current_limit = i_limit;
    cascade->voltage_feedback = 0.0f;
    cascade->current_feedback = 0.0f;
    cascade->current_setpoint = 0.0f;
    cascade->duty_output = 0.0f;
}

void Cascade_PID_Update(Cascade_PID *cascade, float dt)
{
    cascade->voltage_feedback = Read_Voltage();
    cascade->current_feedback = Read_Current();

    cascade->current_setpoint = PID_Compute(&cascade->voltage_pid,
                                            cascade->voltage_setpoint,
                                            cascade->voltage_feedback,
                                            dt);

    if (cascade->current_setpoint > cascade->current_limit) {
        cascade->current_setpoint = cascade->current_limit;
    } else if (cascade->current_setpoint < 0.0f) {
        cascade->current_setpoint = 0.0f;
    }

    cascade->duty_output = PID_Compute(&cascade->current_pid,
                                       cascade->current_setpoint,
                                       cascade->current_feedback,
                                       dt);

    Set_PWM_Duty(cascade->duty_output);
}

/* ===== 主函数 ===== */
int main(void)
{
    Cascade_PID cascade;
    float dt = 0.001f;
    int i;

    Cascade_PID_Init(&cascade, 12.0f, 5.0f);

    printf("===== Cascade PID Control (Voltage Outer + Current Inner) =====\n");
    printf("V_set=%.2fV, I_limit=%.2fA, dt=%.4fs\n\n", cascade.voltage_setpoint, cascade.current_limit, dt);

    for (i = 0; i < 10; i++) {
        mock_adc_voltage = (uint16_t)((i * 200) % 4096);
        mock_adc_current = (uint16_t)((i * 150) % 4096);

