        printf("Step %2d | V_fb=%.3fV | I_fb=%.3fA | I_set=%.3fA | Duty=%.1f\n",
               i,
               cascade.voltage_feedback,
               cascade.current_feedback,
               cascade.current_setpoint,
               cascade.duty_output);
    }

    printf("\n===== Test Complete =====\n");
    return 0;
}
