#include <stdio.h>
#include <stdint.h>

/* ================= 模拟寄存器与硬件抽象层 ================= */
/* 使用宏定义模拟寄存器，避免依赖特定单片机头文件 */
#define MOCK_REG_PID_KP      (*(volatile float *)0x40000000)
#define MOCK_REG_PID_KI      (*(volatile float *)0x40000004)
#define MOCK_REG_PID_KD      (*(volatile float *)0x40000008)
#define MOCK_REG_PID_OUT_MAX (*(volatile float *)0x4000000C)
#define MOCK_REG_PID_OUT_MIN (*(volatile float *)0x40000010)
#define MOCK_REG_PID_INT_MAX (*(volatile float *)0x40000014)
#define MOCK_REG_PID_INT_MIN (*(volatile float *)0x40000018)

/* ================= PID 结构体定义 ================= */
typedef struct {
    float Kp;               /* 比例系数 */
    float Ki;               /* 积分系数 */
    float Kd;               /* 微分系数 */
    float setpoint;         /* 目标值 */
    float integral;         /* 积分累加项 */
    float prev_error;       /* 上一次误差 */
    float out_max;          /* 输出上限 */
    float out_min;          /* 输出下限 */
    float integral_max;     /* 积分限幅上限 */
    float integral_min;     /* 积分限幅下限 */
    float output;           /* 本次输出 */
    uint8_t integral_cut;   /* 积分切除标志：1=切除积分，0=启用积分 */
} PID_TypeDef;

/* ================= PID 初始化 ================= */
void PID_Init(PID_TypeDef *pid,
              float Kp, float Ki, float Kd,
              float out_max, float out_min,
              float integral_max, float integral_min)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->setpoint = 0.0f;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->out_max = out_max;
    pid->out_min = out_min;
    pid->integral_max = integral_max;
    pid->integral_min = integral_min;
    pid->output = 0.0f;
    pid->integral_cut = 0;
}

/* ================= 积分饱和抑制 PID 计算 =================
 * 策略：
 *   1. 计算误差 error = setpoint - feedback
 *   2. 判断是否需要进行积分切除：
 *      - 当输出已经达到限幅值，且误差方向会继续增大积分项时，切除积分
 *      - 即：输出 >= out_max 且 error > 0，或 输出 <= out_min 且 error < 0
 *   3. 若未切除积分，则累加积分项，并对积分项进行限幅
 *   4. 计算 PID 输出，并对输出进行限幅
 *   5. 保存本次误差
 * ========================================================= */
float PID_Compute(PID_TypeDef *pid, float feedback)
{
    float error;
    float p_term;
    float i_term;
    float d_term;
    float output;

    /* 1. 计算当前误差 */
    error = pid->setpoint - feedback;

    /* 2. 判断积分切除条件 */
    if ((pid->output >= pid->out_max && error > 0.0f) ||
        (pid->output <= pid->out_min && error < 0.0f)) {
        pid->integral_cut = 1;   /* 切除积分 */
    } else {
        pid->integral_cut = 0;   /* 启用积分 */
    }

    /* 3. 积分项累加与限幅（仅在未切除时累加） */
    if (pid->integral_cut == 0) {
        pid->integral += error;

        /* 积分限幅 */
        if (pid->integral > pid->integral_max) {
            pid->integral = pid->integral_max;
        } else if (pid->integral < pid->integral_min) {
            pid->integral = pid->integral_min;
        }
    }

    /* 4. 计算各项 */
    p_term = pid->Kp * error;
    i_term = pid->Ki * pid->integral;
    d_term = pid->Kd * (error - pid->prev_error);

    /* 5. 计算总输出 */
    output = p_term + i_term + d_term;

    /* 6. 输出限幅 */
    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    /* 7. 保存本次误差和输出 */
    pid->prev_error = error;
    pid->output = output;

    return output;
}

/* ================= 主函数测试 ================= */
int main(void)
{
    PID_TypeDef pid;
    float feedback;
    float out;
    int i;

    /* 初始化 PID 参数：
     * Kp=2.0, Ki=0.5, Kd=0.1
     * 输出限幅 [-100, 100]
     * 积分限幅 [-50, 50]
     */
    PID_Init(&pid, 2.0f, 0.5f, 0.1f, 100.0f, -100.0f, 50.0f, -50.0f);

    /* 设定目标值 */
    pid.setpoint = 50.0f;

    printf("===== 积分饱和抑制 PID 测试 =====\n");
    printf("Setpoint = %.2f\n", pid.setpoint);
    printf("Kp=%.2f, Ki=%.2f, Kd=%.2f\n", pid.Kp, pid.Ki, pid.Kd);
    printf("OutLimit=[%.2f, %.2f], IntLimit=[%.2f, %.2f]\n\n",
           pid.out_min, pid.out_max, pid.integral_min, pid.integral_max);

    /* 模拟反馈值逐步逼近目标值 */
    feedback = 0.0f;
    for (i = 0; i < 20; i++) {
        out = PID_Compute(&pid, feedback);

        printf("Step %2d: feedback=%7.3f, error=%7.3f, integral=%7.3f, "
               "cut=%d, output=%7.3f\n",
               i + 1, feedback, pid.setpoint - feedback,
               pid.integral, pid.integral_cut, out);

        /* 简单模拟被控对象：反馈值向输出方向变化 */
        feedback += out * 0.05f;

        /* 防止反馈值超过目标值太多 */
        if (feedback > 100.0f) {
            feedback = 100.0f;
        }
    }

    printf("\n===== 测试结束 =====\n");
    return 0;
}
