#include <stdio.h>
#include <math.h>
#include <string.h>

/* ==================== 模糊PID控制器参数定义 ==================== */
#define NB 0
#define NM 1
#define NS 2
#define ZO 3
#define PS 4
#define PM 5
#define PB 6

#define RULE_SIZE 7

/* 输入输出论域 */
#define E_MIN   (-3.0f)
#define E_MAX   ( 3.0f)
#define EC_MIN  (-3.0f)
#define EC_MAX  ( 3.0f)
#define ECC_MIN (-3.0f)
#define ECC_MAX ( 3.0f)

/* PID参数初始值 */
#define KP0  (1.0f)
#define KI0  (0.1f)
#define KD0  (0.05f)

/* PID参数调整范围 */
#define KP_MIN  (0.0f)
#define KP_MAX  (5.0f)
#define KI_MIN  (0.0f)
#define KI_MAX  (1.0f)
#define KD_MIN  (0.0f)
#define KD_MAX  (0.5f)

/* 采样周期 */
#define TS  (0.01f)

/* ==================== 模糊集合定义 ==================== */
/* 三角形隶属度函数 */
static float trimf(float x, float a, float b, float c)
{
    if (x <= a || x >= c) {
        return 0.0f;
    } else if (x <= b) {
        return (x - a) / (b - a);
    } else {
        return (c - x) / (c - b);
    }
}

/* ==================== 模糊化 ==================== */
/* 将输入映射到模糊论域 [-3, 3] */
static float normalize(float x, float min, float max)
{
    float mid = (min + max) * 0.5f;
    float half = (max - min) * 0.5f;
    if (half < 1e-6f) return 0.0f;
    return (x - mid) / half * 3.0f;
}

/* 计算输入变量在7个模糊子集上的隶属度 */
static void fuzzify(float x, float *mu)
{
    const float centers[7] = {-3.0f, -2.0f, -1.0f, 0.0f, 1.0f, 2.0f, 3.0f};
    int i;
    for (i = 0; i < 7; i++) {
        float c = centers[i];
        float left  = (i > 0) ? centers[i - 1] : c - 1.0f;
        float right = (i < 6) ? centers[i + 1] : c + 1.0f;
        mu[i] = trimf(x, left, c, right);
    }
}

/* ==================== 模糊规则表 ==================== */
static const int rule_dKp[7][7] = {
    {PB, PB, PM, PM, PS, ZO, ZO},
    {PB, PB, PM, PS, PS, ZO, NS},
    {PM, PM, PM, PS, ZO, NS, NS},
    {PM, PM, PS, ZO, NS, NM, NM},
    {PS, PS, ZO, NS, NS, NM, NM},
    {PS, ZO, NS, NM, NM, NM, NB},
    {ZO, ZO, NM, NM, NM, NB, NB}
};

static const int rule_dKi[7][7] = {
    {NB, NB, NM, NM, NS, ZO, ZO},
    {NB, NB, NM, NS, NS, ZO, ZO},
    {NB, NM, NS, NS, ZO, PS, PS},
    {NM, NM, NS, ZO, PS, PM, PM},
    {NM, NS, ZO, PS, PS, PM, PB},
    {ZO, ZO, PS, PS, PM, PB, PB},
    {ZO, ZO, PS, PM, PM, PB, PB}
};

static const int rule_dKd[7][7] = {
    {PS, NS, NB, NB, NB, NM, PS},
    {PS, NS, NB, NM, NM, NS, ZO},
    {ZO, NS, NM, NM, NS, NS, ZO},
    {ZO, NS, NS, NS, NS, NS, ZO},
    {ZO, ZO, ZO, ZO, ZO, ZO, ZO},
    {PB, NS, PS, PS, PS, PS, PB},
    {PB, PM, PM, PM, PS, PS, PB}
};

/* ECC 修正系数 */
static float ecc_correction(float ecc_norm)
{
    float abs_ecc = fabsf(ecc_norm);
    if (abs_ecc < 1.0f) {
        return 0.5f;
    } else if (abs_ecc < 2.0f) {
        return 1.0f;
    } else {
        return 1.5f;
    }
}

/* ==================== 解模糊 ==================== */
static float defuzzify(const float *mu, int n)
{
    const float centers[7] = {-3.0f, -2.0f, -1.0f, 0.0f, 1.0f, 2.0f, 3.0f};
    float num = 0.0f;
    float den = 0.0f;
    int i;
    for (i = 0; i < n && i < 7; i++) {
        num += mu[i] * centers[i];
        den += mu[i];
    }
    if (den < 1e-6f) return 0.0f;
    return num / den;
}

/* ==================== 模糊PID控制器结构体 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float Kp0;
    float Ki0;
    float Kd0;
    float e_prev;
    float e_prev2;
    float integral;
    float output;
    float output_max;
    float output_min;
} FuzzyPID;

static void FuzzyPID_Init(FuzzyPID *pid, float kp, float ki, float kd,
                          float out_min, float out_max)
{
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->Kp0 = kp;
    pid->Ki0 = ki;
    pid->Kd0 = kd;
    pid->e_prev = 0.0f;
    pid->e_prev2 = 0.0f;
    pid->integral = 0.0f;
    pid->output = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
}

/* 模糊推理 */
static void fuzzy_inference(float e_norm, float ec_norm, float ecc_norm,
                            float *dKp, float *dKi, float *dKd)
{
    float mu_e[7], mu_ec[7], mu_ecc[7];
    float mu_dKp[7], mu_dKi[7], mu_dKd[7];
    int i, j, k;

    fuzzify(e_norm, mu_e);
    fuzzify(ec_norm, mu_ec);
    fuzzify(ecc_norm, mu_ecc);

    for (i = 0; i < 7; i++) {
        mu_dKp[i] = 0.0f;
        mu_dKi[i] = 0.0f;
        mu_dKd[i] = 0.0f;
    }

    for (i = 0; i < 7; i++) {
        for (j = 0; j < 7; j++) {
            for (k = 0; k < 7; k++) {
                float w = mu_e[i];
                if (mu_ec[j] < w) w = mu_ec[j];
                if (mu_ecc[k] < w) w = mu_ecc[k];

                if (w > 1e-6f) {
                    int out_kp = rule_dKp[i][j];
                    int out_ki = rule_dKi[i][j];
                    int out_kd = rule_dKd[i][j];

                    float corr = ecc_correction(ecc_norm);
                    w *= corr;
                    if (w > 1.0f) w = 1.0f;

                    if (w > mu_dKp[out_kp]) mu_dKp[out_kp] = w;
                    if (w > mu_dKi[out_ki]) mu_dKi[out_ki] = w;
                    if (w > mu_dKd[out_kd]) mu_dKd[out_kd] = w;
                }
            }
        }
    }

    *dKp = defuzzify(mu_dKp, 7);
    *dKi = defuzzify(mu_dKi, 7);
    *dKd = defuzzify(mu_dKd, 7);
}

/* 模糊PID计算 */
static float FuzzyPID_Compute(FuzzyPID *pid, float setpoint, float feedback)
{
    float e, ec, ecc;
    float e_norm, ec_norm, ecc_norm;
    float dKp, dKi, dKd;
    float Kp, Ki, Kd;
    float P, I, D;
    float output;

    e = setpoint - feedback;
    ec = (e - pid->e_prev) / TS;
    ecc = (e - 2.0f * pid->e_prev + pid->e_prev2) / (TS * TS);

    e_norm = normalize(e, E_MIN, E_MAX);
    ec_norm = normalize(ec, EC_MIN, EC_MAX);
    ecc_norm = normalize(ecc, ECC_MIN, ECC_MAX);

    if (e_norm > 3.0f) e_norm = 3.0f;
    if (e_norm < -3.0f) e_norm = -3.0f;
    if (ec_norm > 3.0f) ec_norm = 3.0f;
    if (ec_norm < -3.0f) ec_norm = -3.0f;
    if (ecc_norm > 3.0f) ecc_norm = 3.0f;
    if (ecc_norm < -3.0f) ecc_norm = -3.0f;

    fuzzy_inference(e_norm, ec_norm, ecc_norm, &dKp, &dKi, &dKd);

    Kp = pid->Kp0 + dKp * 0.1f;
    Ki = pid->Ki0 + dKi * 0.02f;
    Kd = pid->Kd0 + dKd * 0.01f;

    if (Kp < KP_MIN) Kp = KP_MIN;
    if (Kp > KP_MAX) Kp = KP_MAX;
    if (Ki < KI_MIN) Ki = KI_MIN;
    if (Ki > KI_MAX) Ki = KI_MAX;
    if (Kd < KD_MIN) Kd = KD_MIN;
    if (Kd > KD_MAX) Kd = KD_MAX;

    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;

    P = Kp * e;

    pid->integral += e * TS;
    if (pid->integral > 10.0f) pid->integral = 10.0f;
    if (pid->integral < -10.0f) pid->integral = -10.0f;
    I = Ki * pid->integral;

    D = Kd * ec;

    output = P + I + D;

    if (output > pid->output_max) output = pid->output_max;
    if (output < pid->output_min) output = pid->output_min;

    pid->output = output;

    pid->e_prev2 = pid->e_prev;
    pid->e_prev = e;

    return output;
}

/* ==================== 被控对象模拟 ==================== */
typedef struct {
    float K;
    float T;
    float tau;
    float y;
    float u_delay[50];
    int delay_idx;
    int delay_len;
} Plant;

static void Plant_Init(Plant *p, float K, float T, float tau)
{
    p->K = K;
    p->T = T;
    p->tau = tau;
    p->y = 0.0f;
    p->delay_idx = 0;
    p->delay_len = (int)(tau / TS);
    if (p->delay_len > 50) p->delay_len = 50;
    if (p->delay_len < 1) p->delay_len = 1;
    memset(p->u_delay, 0, sizeof(p->u_delay));
}

static float Plant_Update(Plant *p, float u)
{
    float u_delayed;
    float dy;

    p->u_delay[p->delay_idx] = u;
    p->delay_idx = (p->delay_idx + 1) % p->delay_len;
    u_delayed = p->u_delay[p->delay_idx];

    dy = (p->K * u_delayed - p->y) / p->T;
    p->y += dy * TS;

    return p->y;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    FuzzyPID pid;
    Plant plant;
    float setpoint = 1.0f;
    float feedback;
    float output;
    int i;

    printf("========================================\n");
    printf("  模糊PID控制 (三维模糊规则, 在线参数调整)\n");
    printf("========================================\n\n");

    FuzzyPID_Init(&pid, KP0, KI0, KD0, -10.0f, 10.0f);
    Plant_Init(&plant, 1.0f, 0.5f, 0.05f);

    printf("初始参数: Kp=%.4f, Ki=%.4f, Kd=%.4f\n", pid.Kp, pid.Ki, pid.Kd);
    printf("目标值: %.2f\n\n", setpoint);

    printf("%-6s %-10s %-10s %-10s %-10s %-10s %-10s\n",
           "Step", "Setpoint", "Feedback", "Error", "Kp", "Ki", "Kd");
    printf("--------------------------------------------------------------"
           "----------\n");

    for (i = 0; i < 200; i++) {
        feedback = plant.y;
        output = FuzzyPID_Compute(&pid, setpoint, feedback);
        Plant_Update(&plant, output);

        if (i % 10 == 0) {
            printf("%-6d %-10.4f %-10.4f %-10.4f %-10.4f %-10.4f %-10.4f\n",
                   i, setpoint, feedback, setpoint - feedback,
                   pid.Kp, pid.Ki, pid.Kd);
        }
    }

    printf("\n========================================\n");
    printf("最终状态:\n");
    printf("  反馈值: %.4f\n", plant.y);
    printf("  误差:   %.4f\n", setpoint - plant.y);
    printf("========================================\n");

    return 0;
}
