#include <stdio.h>
#include <math.h>

/* ==================== 模拟硬件寄存器宏定义 ==================== */
#define MOCK_REG_PID_KP     0x40000000U
#define MOCK_REG_PID_KI     0x40000004U
#define MOCK_REG_PID_KD     0x40000008U
#define MOCK_REG_PID_OUT    0x4000000CU
#define MOCK_REG_PID_ERR    0x40000010U

/* 使用静态变量模拟寄存器，避免直接访问非法地址导致崩溃 */
static float g_reg_kp  = 0.0f;
static float g_reg_ki  = 0.0f;
static float g_reg_kd  = 0.0f;
static float g_reg_out = 0.0f;
static float g_reg_err = 0.0f;

#define REG_WRITE(addr, val)  do { \
    if ((addr) == MOCK_REG_PID_KP)  g_reg_kp  = (val); \
    else if ((addr) == MOCK_REG_PID_KI)  g_reg_ki  = (val); \
    else if ((addr) == MOCK_REG_PID_KD)  g_reg_kd  = (val); \
    else if ((addr) == MOCK_REG_PID_OUT) g_reg_out = (val); \
    else if ((addr) == MOCK_REG_PID_ERR) g_reg_err = (val); \
} while (0)

#define REG_READ(addr) ( \
    ((addr) == MOCK_REG_PID_KP)  ? g_reg_kp  : \
    ((addr) == MOCK_REG_PID_KI)  ? g_reg_ki  : \
    ((addr) == MOCK_REG_PID_KD)  ? g_reg_kd  : \
    ((addr) == MOCK_REG_PID_OUT) ? g_reg_out : \
    ((addr) == MOCK_REG_PID_ERR) ? g_reg_err : 0.0f )

/* ==================== 分段PID参数结构体 ==================== */
typedef struct {
    float kp;           /* 比例系数 */
    float ki;           /* 积分系数 */
    float kd;           /* 微分系数 */
    float err_min;      /* 误差区间下限（含） */
    float err_max;      /* 误差区间上限（不含） */
} PID_Segment_t;

/* ==================== PID控制器结构体 ==================== */
typedef struct {
    float setpoint;         /* 目标值 */
    float feedback;         /* 反馈值 */
    float error;            /* 当前误差 */
    float error_last;       /* 上次误差 */
    float integral;         /* 积分累积 */
    float output;           /* 输出值 */
    float out_min;          /* 输出下限 */
    float out_max;          /* 输出上限 */
    float integral_limit;   /* 积分限幅 */
    PID_Segment_t *segments;/* 分段参数表 */
    int   seg_count;        /* 分段数量 */
} PID_Controller_t;

/* ==================== 根据误差选择PID参数 ==================== */
static const PID_Segment_t *pid_select_segment(PID_Controller_t *pid)
{
    float abs_err;
    int i;

    if (pid == NULL || pid->segments == NULL || pid->seg_count <= 0) {
        return NULL;
    }

    abs_err = fabsf(pid->error);

    for (i = 0; i < pid->seg_count; i++) {
        if (abs_err >= pid->segments[i].err_min &&
            abs_err <  pid->segments[i].err_max) {
            return &pid->segments[i];
        }
    }
    /* 超出所有区间时，使用最后一段作为兜底 */
    return &pid->segments[pid->seg_count - 1];
}

/* ==================== 分段PID计算 ==================== */
float pid_compute(PID_Controller_t *pid)
{
    const PID_Segment_t *seg;
    float p_term, i_term, d_term;
    float output;

    if (pid == NULL) {
        return 0.0f;
    }

    /* 1. 计算当前误差 */
    pid->error = pid->setpoint - pid->feedback;

    /* 2. 根据误差区间选择PID参数 */
    seg = pid_select_segment(pid);
    if (seg == NULL) {
        return 0.0f;
    }

    /* 3. 比例项 */
    p_term = seg->kp * pid->error;

    /* 4. 积分项（带限幅） */
    pid->integral += pid->error;
    if (pid->integral >  pid->integral_limit) pid->integral =  pid->integral_limit;
    if (pid->integral < -pid->integral_limit) pid->integral = -pid->integral_limit;
    i_term = seg->ki * pid->integral;

    /* 5. 微分项 */
    d_term = seg->kd * (pid->error - pid->error_last);

    /* 6. 求和并限幅 */
    output = p_term + i_term + d_term;
    if (output > pid->out_max) output = pid->out_max;
    if (output < pid->out_min) output = pid->out_min;

    /* 7. 更新状态 */
    pid->error_last = pid->error;
    pid->output = output;

    /* 8. 模拟写入硬件寄存器 */
    REG_WRITE(MOCK_REG_PID_KP,  seg->kp);
    REG_WRITE(MOCK_REG_PID_KI,  seg->ki);
    REG_WRITE(MOCK_REG_PID_KD,  seg->kd);
    REG_WRITE(MOCK_REG_PID_ERR, pid->error);
    REG_WRITE(MOCK_REG_PID_OUT, output);

    return output;
}

/* ==================== 主函数测试 ==================== */
int main(void)
{
    /* 定义三段式PID参数：
     *   大误差段：强比例、弱积分、弱微分（快速响应）
     *   中误差段：适中参数
     *   小误差段：弱比例、强积分、强微分（消除稳态误差）
     */
    PID_Segment_t segments[3] = {
        /* kp    ki    kd    err_min  err_max */
        { 2.0f, 0.05f, 0.01f,  50.0f,  1000.0f },  /* 大误差 */
