        { 0.5f, 0.50f, 0.10f,   0.0f,    10.0f }   /* 小误差 */
    };

    PID_Controller_t pid;
    float test_feedback[] = { 0.0f, 20.0f, 60.0f, 85.0f, 95.0f, 99.0f, 100.0f };
    int n;
    int i;

    /* 初始化PID控制器 */
