#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ==================== 宏定义（模拟寄存器/参数） ==================== */
#define PID_KP              2.0f
#define PID_KI              0.5f
#define PID_KD              0.1f
#define PID_DT              0.01f
#define PID_OUT_MAX         100.0f
#define PID_OUT_MIN         (-100.0f)
#define PID_INTEGRAL_MAX    50.0f
#define PID_INTEGRAL_MIN    (-50.0f)

/* 积分切除阈值：当误差绝对值大于此值时，切除积分作用 */
#define PID_INTEGRAL_CUTOFF 20.0f

/* ==================== PID 结构体 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float dt;

    float out_max;
    float out_min;

    float integral_max;
    float integral_min;

    float integral_cutoff;

    float prev_error;
    float integral;
    float output;
} PID_TypeDef;

/* ==================== PID 初始化 ==================== */
void PID_Init(PID_TypeDef *pid)
{
    pid->Kp = PID_KP;
    pid->Ki = PID_KI;
    pid->Kd = PID_KD;
    pid->dt = PID_DT;

    pid->out_max = PID_OUT_MAX;
    pid->out_min = PID_OUT_MIN;

    pid->integral_max = PID_INTEGRAL_MAX;
    pid->integral_min = PID_INTEGRAL_MIN;

    pid->integral_cutoff = PID_INTEGRAL_CUTOFF;

    pid->prev_error = 0.0f;
    pid->integral = 0.0f;
    pid->output = 0.0f;
}

/* ==================== 限幅辅助函数 ==================== */
static float clamp(float value, float min, float max)
{
    if (value > max) return max;
    if (value < min) return min;
    return value;
}

/* ==================== PID 计算（限幅 + 积分切除） ==================== */
float PID_Compute(PID_TypeDef *pid, float setpoint, float feedback)
{
    float error;
    float p_term;
    float i_term;
    float d_term;
    float output_raw;
    float output_limited;

    error = setpoint - feedback;

    /* 比例项 */
    p_term = pid->Kp * error;

    /* 微分项（对误差微分，也可对反馈微分） */
    d_term = pid->Kd * (error - pid->prev_error) / pid->dt;

    /* 积分项：积分切除策略
     * 当误差绝对值大于积分切除阈值时，不累加积分，防止积分饱和
     * 同时积分项本身也做限幅
     */
    if (fabsf(error) <= pid->integral_cutoff) {
        pid->integral += pid->Ki * error * pid->dt;
        pid->integral = clamp(pid->integral, pid->integral_min, pid->integral_max);
    }
    /* 否则：保持积分值不变（积分切除），不累加也不清零 */

    i_term = pid->integral;

    /* 原始输出 */
    output_raw = p_term + i_term + d_term;

    /* 输出限幅 */
    output_limited = clamp(output_raw, pid->out_min, pid->out_max);

    /* 抗积分饱和：如果输出被限幅，且积分方向与限幅方向一致，则回退积分
     * 这是限幅 + 积分切除的补充保护
     */
    if (output_raw != output_limited) {
        if ((output_raw > pid->out_max && error > 0.0f) ||
            (output_raw < pid->out_min && error < 0.0f)) {
            pid->integral -= pid->Ki * error * pid->dt;
            pid->integral = clamp(pid->integral, pid->integral_min, pid->integral_max);
            i_term = pid->integral;
            output_raw = p_term + i_term + d_term;
            output_limited = clamp(output_raw, pid->out_min, pid->out_max);
        }
    }

    pid->prev_error = error;
    pid->output = output_limited;

    return output_limited;
}

/* ==================== 主函数测试 ==================== */
int main(void)
{
    PID_TypeDef pid;
    float setpoint = 50.0f;
    float feedback = 0.0f;
    float output;
    int i;

    PID_Init(&pid);

    printf("===== PID 积分饱和抑制测试（限幅 + 积分切除） =====\n");
    printf("Kp=%.2f, Ki=%.2f, Kd=%.2f, dt=%.3f\n",
           pid.Kp, pid.Ki, pid.Kd, pid.dt);
    printf("输出限幅: [%.1f, %.1f]\n", pid.out_min, pid.out_max);
    printf("积分限幅: [%.1f, %.1f]\n", pid.integral_min, pid.integral_max);
    printf("积分切除阈值: %.1f\n\n", pid.integral_cutoff);

    printf("Step  Setpoint  Feedback  Error    Integral   Output\n");
    printf("----  --------  --------  -------  ---------  --------\n");

    for (i = 0; i < 30; i++) {
        output = PID_Compute(&pid, setpoint, feedback);

        printf("%4d  %8.2f  %8.2f  %7.2f  %9.3f  %8.3f\n",
               i + 1, setpoint, feedback,
               setpoint - feedback, pid.integral, output);

        /* 简单一阶惯性对象模拟：feedback 逐渐逼近 output */
        feedback += (output - feedback) * 0.1f;

        /* 模拟大误差场景：前 5 步反馈保持 0，测试积分切除 */
        if (i < 5) {
            feedback = 0.0f;
        }
    }

    printf("\n===== 测试完成 =====\n");
    return 0;
}
