#include <stdio.h>
#include <math.h>
#include <string.h>

/* ==================== 宏定义（模拟寄存器/硬件抽象） ==================== */
#define MOCK_REG_TEMP_INPUT     0x40000000U
#define MOCK_REG_LOAD_INPUT     0x40000004U
#define MOCK_REG_PWM_OUTPUT     0x40000008U
#define MOCK_REG_CTRL_ENABLE    0x4000000CU

#define REG32(addr)             (*(volatile unsigned int *)(addr))

/* 温度采样范围与负载采样范围（模拟量程） */
#define TEMP_MIN                0.0f
#define TEMP_MAX                100.0f
#define LOAD_MIN                0.0f
#define LOAD_MAX                100.0f

/* PID 参数限幅 */
#define KP_MIN                  0.0f
#define KP_MAX                  50.0f
#define KI_MIN                  0.0f
#define KI_MAX                  10.0f
#define KD_MIN                  0.0f
#define KD_MAX                  5.0f

/* 模糊论域划分：NB, NM, NS, ZO, PS, PM, PB 共 7 档 */
#define FUZZY_N                 7
#define FUZZY_NB                0
#define FUZZY_NM                1
#define FUZZY_NS                2
#define FUZZY_ZO                3
#define FUZZY_PS                4
#define FUZZY_PM                5
#define FUZZY_PB                6

/* 采样周期（秒） */
#define SAMPLE_TS               0.01f

/* ==================== 数据结构 ==================== */
typedef struct {
    float kp;
    float ki;
    float kd;
} PID_Params;

typedef struct {
    float setpoint;
    float feedback;
    float error;
    float last_error;
    float integral;
    float derivative;
    float output;
    float out_min;
    float out_max;
    PID_Params params;
} PID_Controller;

/* ==================== 模糊自整定模块 ==================== */

static float normalize(float value, float min, float max)
{
    float mid = (min + max) * 0.5f;
    float half = (max - min) * 0.5f;
    if (half < 1e-6f) return 0.0f;
    float n = (value - mid) / half;
    if (n > 1.0f) n = 1.0f;
    if (n < -1.0f) n = -1.0f;
    return n;
}

static float trimf(float x, float c, float w)
{
    if (w < 1e-6f) return 0.0f;
    float d = fabsf(x - c) / w;
    if (d >= 1.0f) return 0.0f;
    return 1.0f - d;
}

static void fuzzy_membership(float e_norm, float ec_norm,
                             float mu_e[FUZZY_N], float mu_ec[FUZZY_N])
{
    const float centers[FUZZY_N] = {
        -1.0f, -0.6667f, -0.3333f, 0.0f, 0.3333f, 0.6667f, 1.0f
    };
    const float width = 0.3333f;

    for (int i = 0; i < FUZZY_N; i++) {
        mu_e[i]  = trimf(e_norm,  centers[i], width);
        mu_ec[i] = trimf(ec_norm, centers[i], width);
    }
}

static const int rule_dkp[FUZZY_N][FUZZY_N] = {
    { FUZZY_PB, FUZZY_PB, FUZZY_PM, FUZZY_PM, FUZZY_PS, FUZZY_ZO, FUZZY_ZO },
    { FUZZY_PB, FUZZY_PB, FUZZY_PM, FUZZY_PS, FUZZY_PS, FUZZY_ZO, FUZZY_NS },
    { FUZZY_PM, FUZZY_PM, FUZZY_PM, FUZZY_PS, FUZZY_ZO, FUZZY_NS, FUZZY_NS },
    { FUZZY_PM, FUZZY_PM, FUZZY_PS, FUZZY_ZO, FUZZY_NS, FUZZY_NM, FUZZY_NM },
    { FUZZY_PS, FUZZY_PS, FUZZY_ZO, FUZZY_NS, FUZZY_NS, FUZZY_NM, FUZZY_NM },
    { FUZZY_PS, FUZZY_ZO, FUZZY_NS, FUZZY_NM, FUZZY_NM, FUZZY_NM, FUZZY_NB },
    { FUZZY_ZO, FUZZY_ZO, FUZZY_NM, FUZZY_NM, FUZZY_NM, FUZZY_NB, FUZZY_NB }
};

static const int rule_dki[FUZZY_N][FUZZY_N] = {
    { FUZZY_NB, FUZZY_NB, FUZZY_NM, FUZZY_NM, FUZZY_NS, FUZZY_ZO, FUZZY_ZO },
    { FUZZY_NB, FUZZY_NB, FUZZY_NM, FUZZY_NS, FUZZY_NS, FUZZY_ZO, FUZZY_ZO },
    { FUZZY_NB, FUZZY_NM, FUZZY_NS, FUZZY_NS, FUZZY_ZO, FUZZY_PS, FUZZY_PS },
    { FUZZY_NM, FUZZY_NM, FUZZY_NS, FUZZY_ZO, FUZZY_PS, FUZZY_PM, FUZZY_PM },
    { FUZZY_NM, FUZZY_NS, FUZZY_ZO, FUZZY_PS, FUZZY_PS, FUZZY_PM, FUZZY_PB },
    { FUZZY_ZO, FUZZY_ZO, FUZZY_PS, FUZZY_PS, FUZZY_PM, FUZZY_PB, FUZZY_PB },
    { FUZZY_ZO, FUZZY_ZO, FUZZY_PS, FUZZY_PM, FUZZY_PM, FUZZY_PB, FUZZY_PB }
};

static const int rule_dkd[FUZZY_N][FUZZY_N] = {
    { FUZZY_PS, FUZZY_NS, FUZZY_NB, FUZZY_NB, FUZZY_NB, FUZZY_NM, FUZZY_PS },
    { FUZZY_PS, FUZZY_NS, FUZZY_NB, FUZZY_NM, FUZZY_NM, FUZZY_NS, FUZZY_ZO },
    { FUZZY_ZO, FUZZY_NS, FUZZY_NM, FUZZY_NM, FUZZY_NS, FUZZY_NS, FUZZY_ZO },
    { FUZZY_ZO, FUZZY_NS, FUZZY_NS, FUZZY_NS, FUZZY_NS, FUZZY_NS, FUZZY_ZO },
    { FUZZY_ZO, FUZZY_ZO, FUZZY_ZO, FUZZY_ZO, FUZZY_ZO, FUZZY_ZO, FUZZY_ZO },
    { FUZZY_PB, FUZZY_PS, FUZZY_PS, FUZZY_PS, FUZZY_PS, FUZZY_PS, FUZZY_PB },
    { FUZZY_PB, FUZZY_PM, FUZZY_PM, FUZZY_PM, FUZZY_PS, FUZZY_PS, FUZZY_PB }
};

static float defuzzify(const float mu_e[FUZZY_N], const float mu_ec[FUZZY_N],
                       const int rule[FUZZY_N][FUZZY_N])
{
    const float centers[FUZZY_N] = {
        -1.0f, -0.6667f, -0.3333f, 0.0f, 0.3333f, 0.6667f, 1.0f
    };
    float num = 0.0f;
    float den = 0.0f;

    for (int i = 0; i < FUZZY_N; i++) {
        for (int j = 0; j < FUZZY_N; j++) {
            float w = mu_e[i] * mu_ec[j];
            if (w < 1e-6f) continue;
            int out_idx = rule[i][j];
            if (out_idx < 0) out_idx = 0;
            if (out_idx > FUZZY_N - 1) out_idx = FUZZY_N - 1;
            num += w * centers[out_idx];
            den += w;
        }
    }
    if (den < 1e-6f) return 0.0f;
    return num / den;
}

static void fuzzy_self_tuning(PID_Controller *pid, float load_norm)
{
    float e = pid->setpoint - pid->feedback;
    float ec = (e - pid->last_error) / SAMPLE_TS;

    float e_norm  = normalize(e, -50.0f, 50.0f);
    float ec_norm = normalize(ec, -200.0f, 200.0f);

    float mu_e[FUZZY_N], mu_ec[FUZZY_N];
    fuzzy_membership(e_norm, ec_norm, mu_e, mu_ec);

    float dkp = defuzzify(mu_e, mu_ec, rule_dkp);
    float dki = defuzzify(mu_e, mu_ec, rule_dki);
    float dkd = defuzzify(mu_e, mu_ec, rule_dkd);

    float load_factor = 1.0f + 0.5f * load_norm;
    if (load_factor < 0.5f) load_factor = 0.5f;
    if (load_factor > 1.5f) load_factor = 1.5f;

    float kp_base = 10.0f;
    float ki_base = 1.0f;
    float kd_base = 0.5f;

    float kp_new = kp_base + dkp * 5.0f;
    float ki_new = (ki_base + dki * 0.5f) * load_factor;
    float kd_new = kd_base + dkd * 0.3f;

    if (kp_new < KP_MIN) kp_new = KP_MIN;
    if (kp_new > KP_MAX) kp_new = KP_MAX;
    if (ki_new < KI_MIN) ki_new = KI_MIN;
    if (ki_new > KI_MAX) ki_new = KI_MAX;
    if (kd_new < KD_MIN) kd_new = KD_MIN;
    if (kd_new > KD_MAX) kd_new = KD_MAX;

    pid->params.kp = kp_new;
    pid->params.ki = ki_new;
    pid->params.kd = kd_new;
}

/* ==================== PID 控制模块 ==================== */
static void pid_init(PID_Controller *pid, float sp, float out_min, float out_max)
{
    memset(pid, 0, sizeof(PID_Controller));
    pid->setpoint = sp;
    pid->out_min = out_min;
    pid->out_max = out_max;
    pid->params.kp = 10.0f;
    pid->params.ki = 1.0f;
    pid->params.kd = 0.5f;
}

static float pid_compute(PID_Controller *pid, float feedback, float load_norm)
{
    pid->feedback = feedback;
    pid->error = pid->setpoint - pid->feedback;

    pid->integral += pid->error * SAMPLE_TS;
    float i_limit = pid->out_max / (pid->params.ki + 1e-6f);
    if (pid->integral > i_limit) pid->integral = i_limit;
    if (pid->integral < -i_limit) pid->integral = -i_limit;

    pid->derivative = (pid->error - pid->last_error) / SAMPLE_TS;

    fuzzy_self_tuning(pid, load_norm);

    pid->output = pid->params.kp * pid->error
                + pid->params.ki * pid->integral
                + pid->params.kd * pid->derivative;

    if (pid->output > pid->out_max) pid->output = pid->out_max;
    if (pid->output < pid->out_min) pid->output = pid->out_min;

    pid->last_error = pid->error;
    return pid->output;
}

/* ==================== 模拟被控对象 ==================== */
static float plant_update(float current_temp, float pwm, float load_norm)
{
    float heat_gain = 0.5f;
    float cooling = 0.02f * (current_temp - 25.0f);
    float load_loss = 0.1f * (load_norm + 1.0f) * 0.5f * current_temp * 0.01f;
    float dt = SAMPLE_TS;

    float dtemp = heat_gain * pwm * dt - cooling * dt - load_loss * dt;
    float next = current_temp + dtemp;
    if (next < 0.0f) next = 0.0f;
    if (next > 150.0f) next = 150.0f;
    return next;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("===== PID Fuzzy Self-Tuning (Temperature/Load Adaptive) =====\n");

    PID_Controller pid;
    pid_init(&pid, 80.0f, 0.0f, 100.0f);

    float temp = 25.0f;
    float load = 50.0f;

    printf("Step | Temp(C) | Load(%%) | Kp     | Ki     | Kd     | PWM\n");
    printf("-----+---------+---------+--------+--------+--------+------\n");

    for (int step = 0; step < 200; step++) {
        if (step == 80) {
            load = 80.0f;
            printf(">>> Load disturbance: 50%% -> 80%% at step %d\n", step);
        }
        if (step == 140) {
            load = 30.0f;
            printf(">>> Load disturbance: 80%% -> 30%% at step %d\n", step);
        }

        float load_norm = normalize(load, LOAD_MIN, LOAD_MAX);

        float pwm = pid_compute(&pid, temp, load_norm);

        temp = plant_update(temp, pwm, load_norm);

        if (step % 10 == 0) {
            printf("%4d | %7.2f | %7.1f | %6.3f | %6.3f | %6.3f | %5.1f\n",
                   step, temp, load,
                   pid.params.kp, pid.params.ki, pid.params.kd, pwm);
        }
    }

    printf("\n===== Final State =====\n");
    printf("Setpoint: %.1f C\n", pid.setpoint);
    printf("Final Temp: %.2f C\n", temp);
    printf("Final Error: %.2f C\n", pid.setpoint - temp);
    printf("Final Kp=%.3f Ki=%.3f Kd=%.3f\n",
           pid.params.kp, pid.params.ki, pid.params.kd);
    printf("Final PWM: %.1f\n", pid.output);

    return 0;
}
