#include <stdio.h>

/* ============================================================
 * 离散化 PID 控制（Tustin 变换，无静差）
 *
 * 连续域 PID:
 *   U(s)      Kp * s + Ki + Kd * s^2
 *   ---- = ---------------------------
 *   E(s)              s
 *
 * 采用 Tustin（双线性）变换:
 *   s = (2/T) * (1 - z^-1) / (1 + z^-1)
 *
 * 推导后得到增量式（速度式）差分方程:
 *   u[k] = u[k-1] + b0*e[k] + b1*e[k-1] + b2*e[k-2]
 *
 * 其中:
 *   b0 = Kp + Ki*T/2 + 2*Kd/T
 *   b1 = Ki*T - 4*Kd/T
 *   b2 = -Kp + Ki*T/2 + 2*Kd/T
 *
 * 该形式天然包含积分作用，且无静差。
 * ============================================================ */

/* ---------- 模拟寄存器 / 硬件抽象（mock） ----------
 * 注意：不使用真实地址指针，避免非法内存访问。
 * 使用普通全局变量模拟寄存器。
 */
static volatile unsigned int g_pid_ctrl_reg   = 0u;
static volatile unsigned int g_pid_status_reg = 0u;

#define PID_CTRL_REG      (g_pid_ctrl_reg)
#define PID_STATUS_REG    (g_pid_status_reg)

#define PID_ENABLE_BIT    (1u << 0)
#define PID_READY_BIT     (1u << 1)

/* ---------- PID 控制器结构体 ---------- */
typedef struct {
    /* 整定参数 */
    float Kp;          /* 比例增益 */
    float Ki;          /* 积分增益 */
    float Kd;          /* 微分增益 */
    float T;           /* 采样周期 (秒) */

    /* 差分方程系数 */
    float b0;
    float b1;
    float b2;

    /* 历史状态 */
    float e1;          /* e[k-1] */
    float e2;          /* e[k-2] */
    float u_prev;      /* u[k-1] */

    /* 输出限幅 */
    float u_min;
    float u_max;

    /* 限幅标志 */
    int   saturated;
} PID_Tustin_t;

/* ---------- 初始化 ---------- */
void PID_Tustin_Init(PID_Tustin_t *pid,
                     float Kp, float Ki, float Kd,
                     float T,
                     float u_min, float u_max)
{
    if (pid == NULL) {
        return;
    }
    if (T <= 0.0f) {
        T = 0.001f; /* 防止除以零 */
    }

    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->T  = T;

    /* Tustin 变换系数 */
    pid->b0 =  Kp + (Ki * T) / 2.0f + (2.0f * Kd) / T;
    pid->b1 =        (Ki * T)        - (4.0f * Kd) / T;
    pid->b2 = -Kp + (Ki * T) / 2.0f + (2.0f * Kd) / T;

    /* 清零历史 */
    pid->e1 = 0.0f;
    pid->e2 = 0.0f;
    pid->u_prev = 0.0f;

    pid->u_min = u_min;
    pid->u_max = u_max;
    pid->saturated = 0;
}

/* ---------- 复位 ---------- */
void PID_Tustin_Reset(PID_Tustin_t *pid)
{
    if (pid == NULL) {
        return;
    }
    pid->e1 = 0.0f;
    pid->e2 = 0.0f;
    pid->u_prev = 0.0f;
    pid->saturated = 0;
}

/* ---------- 单步计算 ----------
 * 输入: setpoint 设定值, feedback 反馈值
 * 返回: 控制量 u[k]
 */
float PID_Tustin_Update(PID_Tustin_t *pid, float setpoint, float feedback)
{
    float e0;
    float u;

    if (pid == NULL) {
        return 0.0f;
    }

    /* 误差 */
    e0 = setpoint - feedback;

    /* 增量式差分方程 */
    u = pid->u_prev
      + pid->b0 * e0
      + pid->b1 * pid->e1
      + pid->b2 * pid->e2;

    /* 输出限幅（抗积分饱和） */
    pid->saturated = 0;
    if (u > pid->u_max) {
        u = pid->u_max;
        pid->saturated = 1;
    } else if (u < pid->u_min) {
        u = pid->u_min;
        pid->saturated = 1;
    }

    /* 更新历史 */
    pid->e2 = pid->e1;
    pid->e1 = e0;
    pid->u_prev = u;

    return u;
}

/* ---------- 获取系数（调试用） ---------- */
void PID_Tustin_PrintCoeffs(const PID_Tustin_t *pid)
{
    if (pid == NULL) {
        return;
    }
    printf("PID Tustin Coefficients:\n");
    printf("  Kp = %.4f, Ki = %.4f, Kd = %.4f, T = %.4f s\n",
           pid->Kp, pid->Ki, pid->Kd, pid->T);
    printf("  b0 = %.6f\n", pid->b0);
    printf("  b1 = %.6f\n", pid->b1);
    printf("  b2 = %.6f\n", pid->b2);
    printf("  u_min = %.4f, u_max = %.4f\n", pid->u_min, pid->u_max);
    printf("\n");
}

/* ---------- 主函数：测试 ---------- */
int main(void)
{
    PID_Tustin_t pid;
    float setpoint;
    float feedback;
    float u;
    int   k;

    /* 模拟硬件寄存器操作 */
    PID_CTRL_REG = PID_ENABLE_BIT;
    PID_STATUS_REG = PID_READY_BIT;

    if (PID_STATUS_REG & PID_READY_BIT) {
        printf("[HW] PID peripheral ready.\n");
    } else {
        printf("[HW] PID peripheral mock (no real hardware).\n");
    }

    /* 初始化 PID: Kp=2.0, Ki=1.0, Kd=0.1, T=0.01s, 输出限幅 [-100, 100] */
    PID_Tustin_Init(&pid, 2.0f, 1.0f, 0.1f, 0.01f, -100.0f, 100.0f);
    PID_Tustin_PrintCoeffs(&pid);

    /* 模拟一个一阶被控对象: y[k] = 0.9*y[k-1] + 0.1*u[k-1] */
    setpoint = 10.0f;
    feedback = 0.0f;

    printf("Step  Setpoint  Feedback   Error     Output\n");
    printf("----  --------  --------  --------  --------\n");

    for (k = 0; k < 20; k++) {
        float error = setpoint - feedback;

        /* 计算控制量 */
        u = PID_Tustin_Update(&pid, setpoint, feedback);

        /* 被控对象更新（模拟） */
        feedback = 0.9f * feedback + 0.1f * u;

        printf("%4d  %8.4f  %8.4f  %8.4f  %8.4f%s\n",
               k, setpoint, feedback, error, u,
               pid.saturated ? "  [SAT]" : "");
    }

    /* 验证无静差：稳态误差应趋近于 0 */
    printf("\nFinal steady-state error = %.6f\n", setpoint - feedback);

    /* 复位测试 */
    PID_Tustin_Reset(&pid);
    printf("After reset: e1=%.4f, e2=%.4f, u_prev=%.4f\n",
           pid.e1, pid.e2, pid.u_prev);

    return 0;
}
