#include <stdio.h>
#include <math.h>

/* ==================== PID 控制器结构体 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float Ts;
    float integral;
    float prev_error;
    float prev_prev_error;
    float out_min;
    float out_max;
    float integral_min;
    float integral_max;
    float P_term;
    float I_term;
    float D_term;
} PID_Controller;

/* ==================== 解耦控制器结构体 ==================== */
typedef struct {
    PID_Controller pid1;
    PID_Controller pid2;
    float d11, d12;
    float d21, d22;
    float g11, g12;
    float g21, g22;
    int decouple_mode;
    float setpoint1;
    float setpoint2;
    float feedback1;
    float feedback2;
    float output1;
    float output2;
    float error1;
    float error2;
} DecoupleController;

/* ==================== PID 初始化 ==================== */
static void pid_init(PID_Controller *pid,
                     float Kp, float Ki, float Kd,
                     float Ts,
                     float out_min, float out_max,
                     float integral_min, float integral_max)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->Ts = Ts;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_prev_error = 0.0f;
    pid->out_min = out_min;
    pid->out_max = out_max;
    pid->integral_min = integral_min;
    pid->integral_max = integral_max;
    pid->P_term = 0.0f;
    pid->I_term = 0.0f;
    pid->D_term = 0.0f;
}

/* ==================== PID 计算 ==================== */
static float pid_compute(PID_Controller *pid, float setpoint, float feedback)
{
    float error = setpoint - feedback;
    float output;

    pid->P_term = pid->Kp * error;

    pid->integral += pid->Ki * error * pid->Ts;
    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }
    pid->I_term = pid->integral;

    pid->D_term = pid->Kd * (error - pid->prev_error) / pid->Ts;

    output = pid->P_term + pid->I_term + pid->D_term;

    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    pid->prev_prev_error = pid->prev_error;
    pid->prev_error = error;

    return output;
}

/* ==================== 解耦控制器初始化 ==================== */
static void decouple_init(DecoupleController *dc,
                          float Kp1, float Ki1, float Kd1,
                          float Kp2, float Ki2, float Kd2,
                          float Ts,
                          float out_min, float out_max,
                          float integral_min, float integral_max,
                          float d11, float d12, float d21, float d22,
                          float g11, float g12, float g21, float g22,
                          int decouple_mode)
{
    pid_init(&dc->pid1, Kp1, Ki1, Kd1, Ts, out_min, out_max, integral_min, integral_max);
    pid_init(&dc->pid2, Kp2, Ki2, Kd2, Ts, out_min, out_max, integral_min, integral_max);

    dc->d11 = d11; dc->d12 = d12;
    dc->d21 = d21; dc->d22 = d22;

    dc->g11 = g11; dc->g12 = g12;
    dc->g21 = g21; dc->g22 = g22;

    dc->decouple_mode = decouple_mode;

    dc->setpoint1 = 0.0f;
    dc->setpoint2 = 0.0f;
    dc->feedback1 = 0.0f;
    dc->feedback2 = 0.0f;
    dc->output1 = 0.0f;
    dc->output2 = 0.0f;
    dc->error1 = 0.0f;
    dc->error2 = 0.0f;
}

/* ==================== 解耦控制计算 ==================== */
static void decouple_compute(DecoupleController *dc)
{
    float v1, v2;
    float u1, u2;
    float det;

    dc->error1 = dc->setpoint1 - dc->feedback1;
    dc->error2 = dc->setpoint2 - dc->feedback2;

    v1 = pid_compute(&dc->pid1, dc->setpoint1, dc->feedback1);
    v2 = pid_compute(&dc->pid2, dc->setpoint2, dc->feedback2);

    if (dc->decouple_mode == 0) {
        u1 = dc->d11 * v1 + dc->d12 * v2;
        u2 = dc->d21 * v1 + dc->d22 * v2;
    } else {
        det = dc->g11 * dc->g22 - dc->g12 * dc->g21;
        if (fabsf(det) < 1e-6f) {
            u1 = v1;
            u2 = v2;
        } else {
            u1 = (dc->g22 * v1 - dc->g12 * v2) / det;
            u2 = (-dc->g21 * v1 + dc->g11 * v2) / det;
        }
    }

    if (u1 > dc->pid1.out_max) u1 = dc->pid1.out_max;
    if (u1 < dc->pid1.out_min) u1 = dc->pid1.out_min;
    if (u2 > dc->pid2.out_max) u2 = dc->pid2.out_max;
    if (u2 < dc->pid2.out_min) u2 = dc->pid2.out_min;

    dc->output1 = u1;
    dc->output2 = u2;
}

/* ==================== 模拟被控对象 ==================== */
typedef struct {
    float y1;
    float y2;
    float a11;
    float a22;
    float b11;
    float b12;
    float b21;
    float b22;
} PlantModel;

static void plant_init(PlantModel *p)
{
    p->y1 = 0.0f;
    p->y2 = 0.0f;
    p->a11 = 0.95f;
    p->a22 = 0.95f;
    p->b11 = 0.10f;
    p->b12 = 0.05f;
    p->b21 = 0.04f;
    p->b22 = 0.10f;
}

static void plant_step(PlantModel *p, float u1, float u2)
{
    float y1_next, y2_next;
    y1_next = p->a11 * p->y1 + p->b11 * u1 + p->b12 * u2;
    y2_next = p->a22 * p->y2 + p->b21 * u1 + p->b22 * u2;
    p->y1 = y1_next;
    p->y2 = y2_next;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    DecoupleController dc;
    PlantModel plant;
    int i;
    const int STEPS = 200;
    const float Ts = 0.01f;

    plant_init(&plant);

    decouple_init(&dc,
                  2.0f, 5.0f, 0.1f,
                  1.8f, 4.5f, 0.08f,
                  Ts,
                  -10.0f, 10.0f,
                  -5.0f, 5.0f,
                  1.0f, -0.5f, -0.4f, 1.0f,
                  0.10f, 0.05f, 0.04f, 0.10f,
                  0);

    dc.setpoint1 = 1.0f;
    dc.setpoint2 = 0.5f;

    printf("=== 多变量PID解耦控制（双输入双输出）仿真 ===\n");
    printf("设定值: y1=%.2f, y2=%.2f\n", dc.setpoint1, dc.setpoint2);
    printf("解耦模式: 静态解耦矩阵\n");
    printf("解耦矩阵 D = [%.2f, %.2f; %.2f, %.2f]\n",
           dc.d11, dc.d12, dc.d21, dc.d22);
    printf("被控对象 G = [%.2f, %.2f; %.2f, %.2f]\n",
           dc.g11, dc.g12, dc.g21, dc.g22);
    printf("\n步数\t设定值1\t反馈值1\t输出1\t设定值2\t反馈值2\t输出2\n");
    printf("----\t-------\t-------\t-----\t-------\t-------\t-----\n");

    for (i = 0; i < STEPS; i++) {
        dc.feedback1 = plant.y1;
        dc.feedback2 = plant.y2;

        decouple_compute(&dc);

        plant_step(&plant, dc.output1, dc.output2);

        if (i % 20 == 0 || i == STEPS - 1) {
            printf("%3d\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f\t%.4f\n",
                   i,
                   dc.setpoint1, dc.feedback1, dc.output1,
                   dc.setpoint2, dc.feedback2, dc.output2);
        }
    }

    printf("\n=== 仿真结束 ===\n");
    printf("最终反馈: y1=%.4f (设定 %.4f), y2=%.4f (设定 %.4f)\n",
           plant.y1, dc.setpoint1, plant.y2, dc.setpoint2);
    printf("最终误差: e1=%.4f, e2=%.4f\n",
           dc.setpoint1 - plant.y1, dc.setpoint2 - plant.y2);
    printf("最终输出: u1=%.4f, u2=%.4f\n", dc.output1, dc.output2);

    printf("\nPID1 内部状态: P=%.4f, I=%.4f, D=%.4f\n",
           dc.pid1.P_term, dc.pid1.I_term, dc.pid1.D_term);
    printf("PID2 内部状态: P=%.4f, I=%.4f, D=%.4f\n",
           dc.pid2.P_term, dc.pid2.I_term, dc.pid2.D_term);

    return 0;
}
