#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>

/* ========== 模拟寄存器与硬件抽象层 ========== */
#define MOCK_REG_BASE       0x40000000U
#define MOCK_REG_CTRL       (*(volatile unsigned int *)(MOCK_REG_BASE + 0x00))
#define MOCK_REG_STATUS     (*(volatile unsigned int *)(MOCK_REG_BASE + 0x04))
#define MOCK_REG_FAULT      (*(volatile unsigned int *)(MOCK_REG_BASE + 0x08))

#define FAULT_NONE          0x00U
#define FAULT_PARAM_CRC     0x01U
#define FAULT_PARAM_RANGE   0x02U
#define FAULT_SENSOR_LOSS   0x04U
#define FAULT_ACTUATOR      0x08U

/* ========== PID 参数结构体 ========== */
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral_limit;
    float output_min;
    float output_max;
    float setpoint;
    unsigned int crc;
} PID_Params_t;

/* ========== PID 运行时状态 ========== */
typedef struct {
    float integral;
    float prev_error;
    float output;
    bool  initialized;
} PID_State_t;

/* ========== 参数备份存储（模拟非易失存储） ========== */
#define PARAM_BACKUP_SLOTS  3

typedef struct {
    PID_Params_t params;
    unsigned int version;
    bool         valid;
} ParamBackup_t;

static ParamBackup_t g_param_backup[PARAM_BACKUP_SLOTS];
static unsigned int  g_backup_write_idx = 0;
static unsigned int  g_param_version    = 0;

/* ========== 简易 CRC32 计算 ========== */
static unsigned int crc32_calc(const unsigned char *data, unsigned int len)
{
    unsigned int crc = 0xFFFFFFFFU;
    unsigned int i, j;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 1U) {
                crc = (crc >> 1) ^ 0xEDB88320U;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc ^ 0xFFFFFFFFU;
}

static unsigned int pid_params_crc(const PID_Params_t *p)
{
    return crc32_calc((const unsigned char *)p,
                      sizeof(PID_Params_t) - sizeof(unsigned int));
}

/* ========== 参数合法性检查 ========== */
static bool pid_params_validate(const PID_Params_t *p)
{
    if (p == NULL) return false;
    if (p->kp < 0.0f || p->ki < 0.0f || p->kd < 0.0f) return false;
    if (p->integral_limit <= 0.0f) return false;
    if (p->output_min >= p->output_max) return false;
    if (p->setpoint < p->output_min || p->setpoint > p->output_max) return false;
    if (p->crc != pid_params_crc(p)) return false;
    return true;
}

/* ========== 参数备份 ========== */
static void pid_params_backup(const PID_Params_t *p)
{
    if (p == NULL) return;

    g_param_backup[g_backup_write_idx].params  = *p;
    g_param_backup[g_backup_write_idx].version = ++g_param_version;
    g_param_backup[g_backup_write_idx].valid   = true;

    g_backup_write_idx = (g_backup_write_idx + 1) % PARAM_BACKUP_SLOTS;
    printf("[BACKUP] Params backed up, version=%u, slot=%u\n",
           g_param_version,
           (g_backup_write_idx + PARAM_BACKUP_SLOTS - 1) % PARAM_BACKUP_SLOTS);
}

/* ========== 参数恢复（从最新有效备份） ========== */
static bool pid_params_restore(PID_Params_t *p)
{
    int i;
    int best_idx = -1;
    unsigned int best_ver = 0;

    if (p == NULL) return false;

    for (i = 0; i < PARAM_BACKUP_SLOTS; i++) {
        if (g_param_backup[i].valid &&
            g_param_backup[i].version > best_ver) {
            best_ver = g_param_backup[i].version;
            best_idx = i;
        }
    }

    if (best_idx < 0) {
        printf("[RESTORE] No valid backup found!\n");
        return false;
    }

    if (!pid_params_validate(&g_param_backup[best_idx].params)) {
        printf("[RESTORE] Backup slot %d CRC/range invalid!\n", best_idx);
        g_param_backup[best_idx].valid = false;
        return false;
    }

    *p = g_param_backup[best_idx].params;
    printf("[RESTORE] Restored from slot %d, version=%u\n",
           best_idx, g_param_backup[best_idx].version);
    return true;
}

/* ========== PID 初始化 ========== */
static void pid_init(PID_State_t *state)
{
    if (state == NULL) return;
    memset(state, 0, sizeof(PID_State_t));
    state->initialized = true;
}

/* ========== PID 计算 ========== */
static float pid_compute(PID_State_t *state, const PID_Params_t *params,
                         float feedback, float dt)
{
    float error, p_term, i_term, d_term, output;

    if (state == NULL || params == NULL || dt <= 0.0f) {
        return 0.0f;
    }

    error = params->setpoint - feedback;

    /* 比例项 */
    p_term = params->kp * error;

    /* 积分项（带限幅） */
    state->integral += params->ki * error * dt;
    if (state->integral > params->integral_limit) {
        state->integral = params->integral_limit;
    } else if (state->integral < -params->integral_limit) {
        state->integral = -params->integral_limit;
    }
    i_term = state->integral;

    /* 微分项 */
    d_term = params->kd * (error - state->prev_error) / dt;
    state->prev_error = error;

    /* 输出限幅 */
    output = p_term + i_term + d_term;
    if (output > params->output_max) {
        output = params->output_max;
    } else if (output < params->output_min) {
        output = params->output_min;
    }

    state->output = output;
    return output;
}

/* ========== 故障检测 ========== */
static unsigned int fault_detect(const PID_Params_t *params)
{
    unsigned int fault = FAULT_NONE;

    if (params == NULL) {
        return FAULT_PARAM_CRC;
    }

    if (params->crc != pid_params_crc(params)) {
        fault |= FAULT_PARAM_CRC;
    }

    if (params->kp < 0.0f || params->ki < 0.0f || params->kd < 0.0f ||
        params->integral_limit <= 0.0f ||
        params->output_min >= params->output_max) {
        fault |= FAULT_PARAM_RANGE;
    }

    return fault;
}

/* ========== 故障容错处理 ========== */
static bool pid_fault_tolerant(PID_Params_t *params, PID_State_t *state,
                               unsigned int fault)
{
    bool recovered = false;

    printf("[FAULT] Detected fault=0x%02X\n", fault);

    if (fault & (FAULT_PARAM_CRC | FAULT_PARAM_RANGE)) {
        printf("[FAULT] Parameter corruption detected, attempting restore...\n");
        if (pid_params_restore(params)) {
            pid_init(state);
            recovered = true;
            printf("[FAULT] Parameter recovery SUCCESS\n");
        } else {
            printf("[FAULT] Parameter recovery FAILED, using safe defaults\n");
            /* 安全默认参数 */
            params->kp = 1.0f;
            params->ki = 0.1f;
            params->kd = 0.01f;
            params->integral_limit = 100.0f;
            params->output_min = -100.0f;
            params->output_max = 100.0f;
            params->setpoint = 0.0f;
            params->crc = pid_params_crc(params);
            pid_init(state);
            recovered = true;
        }
    }

    if (fault & FAULT_SENSOR_LOSS) {
        printf("[FAULT] Sensor loss, holding last output\n");
        /* 保持上次输出，不更新积分 */
        recovered = true;
    }

    if (fault & FAULT_ACTUATOR) {
        printf("[FAULT] Actuator fault, forcing output to safe state\n");
        state->output = 0.0f;
        state->integral = 0.0f;
        recovered = true;
    }

    return recovered;
}

/* ========== 主函数 ========== */
int main(void)
{
    PID_Params_t params;
    PID_State_t  state;
    float        feedback;
    float        output;
    unsigned int fault;
    int          i;

    printf("===== PID Fault-Tolerant Control Demo =====\n\n");

    /* 1. 初始化参数 */
    memset(&params, 0, sizeof(params));
    params.kp = 2.0f;
    params.ki = 0.5f;
    params.kd = 0.1f;
    params.integral_limit = 50.0f;
    params.output_min = -100.0f;
    params.output_max = 100.0f;
    params.setpoint = 50.0f;
    params.crc = pid_params_crc(&params);

    printf("[INIT] kp=%.2f ki=%.2f kd=%.2f setpoint=%.2f\n",
           params.kp, params.ki, params.kd, params.setpoint);

    /* 2. 备份参数 */
    pid_params_backup(&params);

    /* 3. 初始化 PID 状态 */
    pid_init(&state);

    /* 4. 正常运行 */
    printf("\n--- Normal Operation ---\n");
    feedback = 0.0f;
    for (i = 0; i < 5; i++) {
        output = pid_compute(&state, &params, feedback, 0.01f);
        printf("Step %d: feedback=%.2f output=%.2f integral=%.2f\n",
               i, feedback, output, state.integral);
        feedback += output * 0.01f;
    }

    /* 5. 模拟参数损坏 */
    printf("\n--- Simulating Parameter Corruption ---\n");
    params.kp = -999.0f;  /* 非法值 */
    params.crc = 0xDEADBEEF;  /* 错误 CRC */

    fault = fault_detect(&params);
    printf("Fault code: 0x%02X\n", fault);

    /* 6. 故障容错恢复 */
    printf("\n--- Fault Tolerant Recovery ---\n");
    if (pid_fault_tolerant(&params, &state, fault)) {
        printf("Recovery successful!\n");
        printf("Restored params: kp=%.2f ki=%.2f kd=%.2f setpoint=%.2f\n",
               params.kp, params.ki, params.kd, params.setpoint);
    } else {
        printf("Recovery failed!\n");
    }

    /* 7. 恢复后继续运行 */
    printf("\n--- Post-Recovery Operation ---\n");
    feedback = 0.0f;
    for (i = 0; i < 5; i++) {
        output = pid_compute(&state, &params, feedback, 0.01f);
        printf("Step %d: feedback=%.2f output=%.2f integral=%.2f\n",
               i, feedback, output, state.integral);
        feedback += output * 0.01f;
    }

    /* 8. 测试传感器故障 */
    printf("\n--- Simulating Sensor Loss ---\n");
    fault = FAULT_SENSOR_LOSS;
    pid_fault_tolerant(&params, &state, fault);

    /* 9. 测试执行器故障 */
    printf("\n--- Simulating Actuator Fault ---\n");
    fault = FAULT_ACTUATOR;
    pid_fault_tolerant(&params, &state, fault);
    printf("Output after actuator fault: %.2f\n", state.output);

    /* 10. 参数验证测试 */
    printf("\n--- Parameter Validation Test ---\n");
    params.crc = pid_params_crc(&params);
    if (pid_params_validate(&params)) {
        printf("Params valid: YES\n");
    } else {
        printf("Params valid: NO\n");
    }

    printf("\n===== Demo Complete =====\n");
    return 0;
}
