#include <stdio.h>
#include <stdbool.h>

/* ==================== 模拟寄存器与硬件抽象 ==================== */
/* 使用静态变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile float mock_pid_kp        = 0.0f;
static volatile float mock_pid_ki        = 0.0f;
static volatile float mock_pid_kd        = 0.0f;
static volatile float mock_pid_setpoint  = 0.0f;
static volatile float mock_pid_feedback  = 0.0f;
static volatile float mock_pid_output    = 0.0f;
static volatile float mock_pid_manual    = 0.0f;
static volatile int   mock_pid_mode      = 0;

#define MOCK_REG_PID_KP        (mock_pid_kp)
#define MOCK_REG_PID_KI        (mock_pid_ki)
#define MOCK_REG_PID_KD        (mock_pid_kd)
#define MOCK_REG_PID_SETPOINT  (mock_pid_setpoint)
#define MOCK_REG_PID_FEEDBACK  (mock_pid_feedback)
#define MOCK_REG_PID_OUTPUT    (mock_pid_output)
#define MOCK_REG_PID_MANUAL    (mock_pid_manual)
#define MOCK_REG_PID_MODE      (mock_pid_mode)

/* 模式定义 */
#define PID_MODE_MANUAL   0
#define PID_MODE_AUTO     1

/* 输出限幅 */
#define PID_OUTPUT_MIN   (-100.0f)
#define PID_OUTPUT_MAX   ( 100.0f)

/* ==================== PID 控制器结构体 ==================== */
typedef struct {
    float kp;
    float ki;
    float kd;
    float setpoint;
    float feedback;
    float output;
    float manual_output;
    float integral;
    float prev_error;
    float prev_feedback;
    int   mode;
    int   prev_mode;
    float sample_time;
    bool  first_run;
} PID_Controller;

/* ==================== 工具函数 ==================== */
static float clampf(float value, float min, float max)
{
    if (value > max) return max;
    if (value < min) return min;
    return value;
}

/* ==================== PID 初始化 ==================== */
void PID_Init(PID_Controller *pid, float kp, float ki, float kd, float ts)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->setpoint = 0.0f;
    pid->feedback = 0.0f;
    pid->output = 0.0f;
    pid->manual_output = 0.0f;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_feedback = 0.0f;
    pid->mode = PID_MODE_MANUAL;
    pid->prev_mode = PID_MODE_MANUAL;
    pid->sample_time = ts;
    pid->first_run = true;
}

/* ==================== 设置模式（含无扰切换） ==================== */
void PID_SetMode(PID_Controller *pid, int new_mode)
{
    if (new_mode == pid->mode) {
        return;
    }

    if (new_mode == PID_MODE_AUTO) {
        /* 手动 -> 自动：无扰切换
         * 预置积分项，使切换瞬间自动输出等于手动输出。
         */
        float error = pid->setpoint - pid->feedback;
        float p_term = pid->kp * error;
        float d_term = 0.0f;

        if (!pid->first_run) {
            d_term = pid->kd * (pid->feedback - pid->prev_feedback) / pid->sample_time;
        }

        pid->integral = pid->manual_output - p_term - d_term;

        /* 积分限幅 */
        {
            float i_max = PID_OUTPUT_MAX;
            float i_min = PID_OUTPUT_MIN;
            if (pid->ki > 0.0f) {
                i_max = PID_OUTPUT_MAX / pid->ki;
                i_min = PID_OUTPUT_MIN / pid->ki;
            }
            pid->integral = clampf(pid->integral, i_min, i_max);
        }

        pid->prev_error = error;
        pid->prev_feedback = pid->feedback;
        pid->output = pid->manual_output;
    } else {
        /* 自动 -> 手动：无扰切换
         * 将当前自动输出值赋给手动输出。
         */
        pid->manual_output = pid->output;
    }

    pid->prev_mode = pid->mode;
    pid->mode = new_mode;
}

/* ==================== 设置手动输出值 ==================== */
void PID_SetManualOutput(PID_Controller *pid, float manual_value)
{
    pid->manual_output = clampf(manual_value, PID_OUTPUT_MIN, PID_OUTPUT_MAX);
    if (pid->mode == PID_MODE_MANUAL) {
        pid->output = pid->manual_output;
    }
}

/* ==================== PID 计算（周期调用） ==================== */
float PID_Compute(PID_Controller *pid)
{
    float error;
    float p_term;
    float i_term;
    float d_term;
    float output;

    /* 读取输入 */
    pid->setpoint = MOCK_REG_PID_SETPOINT;
    pid->feedback = MOCK_REG_PID_FEEDBACK;

    if (pid->mode == PID_MODE_MANUAL) {
        /* 手动模式：输出直接跟随手动值 */
        pid->output = pid->manual_output;
        pid->integral = pid->manual_output;
        pid->prev_error = pid->setpoint - pid->feedback;
        pid->prev_feedback = pid->feedback;
        pid->first_run = false;
        MOCK_REG_PID_OUTPUT = pid->output;
        return pid->output;
    }

    /* 自动模式：标准 PID 计算 */
    error = pid->setpoint - pid->feedback;

    /* 比例项 */
    p_term = pid->kp * error;

    /* 积分项（累加） */
    pid->integral += pid->ki * error * pid->sample_time;

    /* 积分限幅（抗积分饱和） */
    {
        float i_max = PID_OUTPUT_MAX;
        float i_min = PID_OUTPUT_MIN;
        if (pid->ki > 0.0f) {
            i_max = PID_OUTPUT_MAX / pid->ki;
            i_min = PID_OUTPUT_MIN / pid->ki;
        }
        pid->integral = clampf(pid->integral, i_min, i_max);
    }
    i_term = pid->integral;

    /* 微分项（微分先行，对反馈值微分） */
    if (pid->first_run) {
        d_term = 0.0f;
        pid->first_run = false;
    } else {
        d_term = pid->kd * (pid->feedback - pid->prev_feedback) / pid->sample_time;
    }

    /* 计算输出 */
    output = p_term + i_term - d_term;

    /* 输出限幅 */
    output = clampf(output, PID_OUTPUT_MIN, PID_OUTPUT_MAX);

    /* 更新历史值 */
    pid->prev_error = error;
    pid->prev_feedback = pid->feedback;
    pid->output = output;

    /* 写入输出寄存器 */
    MOCK_REG_PID_OUTPUT = pid->output;

    return pid->output;
}

/* ==================== 主函数测试 ==================== */
int main(void)
{
    PID_Controller pid;
    int i;

    /* 初始化 PID 参数：Kp=2.0, Ki=0.5, Kd=0.1, 采样周期 0.1s */
    PID_Init(&pid, 2.0f, 0.5f, 0.1f, 0.1f);

    /* 设置设定值 */
    MOCK_REG_PID_SETPOINT = 50.0f;

    printf("========== PID 手动/自动无扰切换测试 ==========\n\n");

    /* ---------- 阶段1：手动模式 ---------- */
    printf("--- 阶段1：手动模式 ---\n");
    PID_SetMode(&pid, PID_MODE_MANUAL);
    PID_SetManualOutput(&pid, 30.0f);

    for (i = 0; i < 5; i++) {
        MOCK_REG_PID_FEEDBACK = 20.0f + (float)i * 2.0f;
        float out = PID_Compute(&pid);
        printf("手动模式 第%d次: 反馈=%.2f, 输出=%.2f\n",
               i + 1, MOCK_REG_PID_FEEDBACK, out);
    }

    /* ---------- 阶段2：手动 -> 自动 无扰切换 ---------- */
    printf("\n--- 阶段2：手动 -> 自动 无扰切换 ---\n");
    printf("切换前手动输出 = %.2f\n", pid.output);

    PID_SetMode(&pid, PID_MODE_AUTO);

    MOCK_REG_PID_FEEDBACK = 30.0f;
    float out_after_switch = PID_Compute(&pid);
    printf("切换后第一次计算: 反馈=%.2f, 输出=%.2f (应接近切换前手动输出)\n",
           MOCK_REG_PID_FEEDBACK, out_after_switch);

    for (i = 0; i < 5; i++) {
        MOCK_REG_PID_FEEDBACK = 30.0f + (float)i * 3.0f;
        float out = PID_Compute(&pid);
        printf("自动模式 第%d次: 反馈=%.2f, 输出=%.2f\n",
               i + 1, MOCK_REG_PID_FEEDBACK, out);
    }

    /* ---------- 阶段3：自动 -> 手动 无扰切换 ---------- */
    printf("\n--- 阶段3：自动 -> 手动 无扰切换 ---\n");
    printf("切换前自动输出 = %.2f\n", pid.output);

    PID_SetMode(&pid, PID_MODE_MANUAL);

    MOCK_REG_PID_FEEDBACK = 45.0f;
    float out_after_switch2 = PID_Compute(&pid);
    printf("切换后第一次计算: 反馈=%.2f, 输出=%.2f (应接近切换前自动输出)\n",
           MOCK_REG_PID_FEEDBACK, out_after_switch2);

    PID_SetManualOutput(&pid, 60.0f);
    float out_manual = PID_Compute(&pid);
    printf("手动调整输出为60.0后: 输出=%.2f\n", out_manual);

    /* ---------- 阶段4：再次手动 -> 自动 无扰切换 ---------- */
    printf("\n--- 阶段4：再次手动 -> 自动 无扰切换 ---\n");
    printf("切换前手动输出 = %.2f\n", pid.output);

    PID_SetMode(&pid, PID_MODE_AUTO);

    MOCK_REG_PID_FEEDBACK = 50.0f;
    float out_after_switch3 = PID_Compute(&pid);
    printf("切换后第一次计算: 反馈=%.2f, 输出=%.2f (应接近切换前手动输出)\n",
           MOCK_REG_PID_FEEDBACK, out_after_switch3);

    printf("\n========== 测试完成 ==========\n");
    return 0;
}
