#include <stdio.h>
#include <stdbool.h>
#include <string.h>

/* ================= 模拟寄存器（使用普通变量代替非法地址） ================= */
static unsigned int g_reg_pid_kp   = 0U;
static unsigned int g_reg_pid_ki   = 0U;
static unsigned int g_reg_pid_kd   = 0U;
static unsigned int g_reg_pid_lock = 0U;

#define MOCK_REG_PID_KP      (&g_reg_pid_kp)
#define MOCK_REG_PID_KI      (&g_reg_pid_ki)
#define MOCK_REG_PID_KD      (&g_reg_pid_kd)
#define MOCK_REG_PID_LOCK    (&g_reg_pid_lock)

#define MOCK_REG_READ(addr)       (*(volatile unsigned int *)(addr))
#define MOCK_REG_WRITE(addr, val) (*(volatile unsigned int *)(addr) = (val))

/* ================= PID 参数结构体 ================= */
typedef struct {
    float kp;
    float ki;
    float kd;
} PID_Params;

/* ================= 全局变量 ================= */
static PID_Params g_pid_params = { 1.0f, 0.1f, 0.01f };
static bool g_pid_locked = false;

/* ================= 底层寄存器读写（模拟） ================= */
static void pid_hw_write_kp(float val)
{
    unsigned int raw;
    memcpy(&raw, &val, sizeof(raw));
    MOCK_REG_WRITE(MOCK_REG_PID_KP, raw);
}

static void pid_hw_write_ki(float val)
{
    unsigned int raw;
    memcpy(&raw, &val, sizeof(raw));
    MOCK_REG_WRITE(MOCK_REG_PID_KI, raw);
}

static void pid_hw_write_kd(float val)
{
    unsigned int raw;
    memcpy(&raw, &val, sizeof(raw));
    MOCK_REG_WRITE(MOCK_REG_PID_KD, raw);
}

static float pid_hw_read_kp(void)
{
    unsigned int raw = MOCK_REG_READ(MOCK_REG_PID_KP);
    float val;
    memcpy(&val, &raw, sizeof(val));
    return val;
}

static float pid_hw_read_ki(void)
{
    unsigned int raw = MOCK_REG_READ(MOCK_REG_PID_KI);
    float val;
    memcpy(&val, &raw, sizeof(val));
    return val;
}

static float pid_hw_read_kd(void)
{
    unsigned int raw = MOCK_REG_READ(MOCK_REG_PID_KD);
    float val;
    memcpy(&val, &raw, sizeof(val));
    return val;
}

static void pid_hw_set_lock(bool lock)
{
    MOCK_REG_WRITE(MOCK_REG_PID_LOCK, lock ? 1U : 0U);
}

/* ================= PID 参数锁定控制接口 ================= */

/* 锁定 PID 参数，防止误操作 */
void pid_lock_params(void)
{
    g_pid_locked = true;
    pid_hw_set_lock(true);
    printf("[PID] 参数已锁定 (LOCK)\n");
}

/* 解锁 PID 参数，允许修改 */
void pid_unlock_params(void)
{
    g_pid_locked = false;
    pid_hw_set_lock(false);
    printf("[PID] 参数已解锁 (UNLOCK)\n");
}

/* 查询锁定状态 */
bool pid_is_locked(void)
{
    return g_pid_locked;
}

/* 安全设置 PID 参数（带锁定保护） */
bool pid_set_params(float kp, float ki, float kd)
{
    if (pid_is_locked()) {
        printf("[PID] 设置失败：参数处于锁定状态，禁止修改！\n");
        return false;
    }

    if (kp < 0.0f || ki < 0.0f || kd < 0.0f) {
        printf("[PID] 设置失败：参数不能为负值！\n");
        return false;
    }

    g_pid_params.kp = kp;
    g_pid_params.ki = ki;
    g_pid_params.kd = kd;

    pid_hw_write_kp(kp);
    pid_hw_write_ki(ki);
    pid_hw_write_kd(kd);

    printf("[PID] 参数设置成功: Kp=%.3f, Ki=%.3f, Kd=%.3f\n", kp, ki, kd);
    return true;
}

/* 读取当前 PID 参数 */
void pid_get_params(PID_Params *out)
{
    if (out == NULL) {
        return;
    }
    out->kp = pid_hw_read_kp();
    out->ki = pid_hw_read_ki();
    out->kd = pid_hw_read_kd();
}

/* 打印当前 PID 参数 */
void pid_print_params(void)
{
    PID_Params p;
    pid_get_params(&p);
    printf("[PID] 当前参数: Kp=%.3f, Ki=%.3f, Kd=%.3f, 锁定状态=%s\n",
           p.kp, p.ki, p.kd,
           pid_is_locked() ? "LOCKED" : "UNLOCKED");
}

/* ================= 主函数测试 ================= */
int main(void)
{
    printf("========== PID 参数锁定（防误操作）测试 ==========\n\n");

    /* 1. 初始状态 */
    printf("--- 步骤1: 初始状态 ---\n");
    pid_print_params();

    /* 2. 解锁状态下修改参数 */
    printf("\n--- 步骤2: 解锁状态下修改参数 ---\n");
    pid_unlock_params();
    pid_set_params(2.5f, 0.5f, 0.05f);
    pid_print_params();

    /* 3. 锁定参数 */
    printf("\n--- 步骤3: 锁定参数 ---\n");
    pid_lock_params();
    pid_print_params();

    /* 4. 锁定状态下尝试修改参数（应被拒绝） */
    printf("\n--- 步骤4: 锁定状态下尝试修改参数 ---\n");
    pid_set_params(9.9f, 9.9f, 9.9f);
