#include <stdio.h>
#include <string.h>
#include <math.h>

#define PID_HISTORY_SIZE 64

typedef struct {
    double kp;
    double ki;
    double kd;
    double setpoint;
    double integral;
    double prev_error;
    double output_min;
    double output_max;
} PID_Controller;

typedef struct {
    double setpoint;
    double feedback;
    double error;
    double integral;
    double derivative;
    double output;
    unsigned long timestamp;
} PID_HistoryEntry;

typedef struct {
    PID_HistoryEntry entries[PID_HISTORY_SIZE];
    int head;
    int count;
} PID_History;

static void PID_Init(PID_Controller *pid, double kp, double ki, double kd,
                     double setpoint, double out_min, double out_max)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0;
    pid->prev_error = 0.0;
    pid->output_min = out_min;
    pid->output_max = out_max;
}

static void PID_History_Init(PID_History *hist)
{
    memset(hist, 0, sizeof(PID_History));
    hist->head = 0;
    hist->count = 0;
}

static void PID_History_Record(PID_History *hist, const PID_HistoryEntry *entry)
{
    hist->entries[hist->head] = *entry;
    hist->head = (hist->head + 1) % PID_HISTORY_SIZE;
    if (hist->count < PID_HISTORY_SIZE) {
        hist->count++;
    }
}

static void PID_History_Print(const PID_History *hist)
{
    int i;
    int start;
    int idx;

    printf("========== PID History (count=%d) ==========\n", hist->count);
    printf("%-6s %-10s %-10s %-10s %-10s %-10s %-10s %-10s\n",
           "Index", "Time", "Setpoint", "Feedback", "Error",
           "Integral", "Deriv", "Output");

    if (hist->count == 0) {
        printf("(empty)\n");
        return;
    }

    start = (hist->head - hist->count + PID_HISTORY_SIZE) % PID_HISTORY_SIZE;

    for (i = 0; i < hist->count; i++) {
        idx = (start + i) % PID_HISTORY_SIZE;
        printf("%-6d %-10lu %-10.3f %-10.3f %-10.3f %-10.3f %-10.3f %-10.3f\n",
               i,
               hist->entries[idx].timestamp,
               hist->entries[idx].setpoint,
               hist->entries[idx].feedback,
               hist->entries[idx].error,
               hist->entries[idx].integral,
               hist->entries[idx].derivative,
               hist->entries[idx].output);
    }
}

static double PID_Compute(PID_Controller *pid, double feedback,
                          PID_History *hist, unsigned long timestamp)
{
    double error;
    double derivative;
    double output;
    PID_HistoryEntry entry;

    error = pid->setpoint - feedback;
    pid->integral += error;
    derivative = error - pid->prev_error;

    output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;

    if (output > pid->output_max) {
        output = pid->output_max;
    } else if (output < pid->output_min) {
        output = pid->output_min;
    }

    entry.setpoint = pid->setpoint;
    entry.feedback = feedback;
    entry.error = error;
    entry.integral = pid->integral;
    entry.derivative = derivative;
    entry.output = output;
    entry.timestamp = timestamp;

    PID_History_Record(hist, &entry);

    pid->prev_error = error;
    return output;
}

static void PID_History_Trend(const PID_History *hist)
{
    int i;
    int start;
    int idx;
    double max_err = 0.0;
    double avg_err = 0.0;
    double last_err = 0.0;

    if (hist->count == 0) {
        printf("No history for trend analysis.\n");
        return;
    }

    start = (hist->head - hist->count + PID_HISTORY_SIZE) % PID_HISTORY_SIZE;

    for (i = 0; i < hist->count; i++) {
        idx = (start + i) % PID_HISTORY_SIZE;
        if (fabs(hist->entries[idx].error) > max_err) {
            max_err = fabs(hist->entries[idx].error);
        }
        avg_err += hist->entries[idx].error;
        last_err = hist->entries[idx].error;
    }

    avg_err /= (double)hist->count;

    printf("---------- Trend Analysis ----------\n");
    printf("Max |error| : %.4f\n", max_err);
    printf("Avg error   : %.4f\n", avg_err);
    printf("Last error  : %.4f\n", last_err);
    printf("Samples     : %d\n", hist->count);
    printf("------------------------------------\n");
}

int main(void)
{
    PID_Controller pid;
    PID_History history;
    double feedback = 0.0;
    double output;
    int i;

    PID_Init(&pid, 1.2, 0.5, 0.05, 100.0, -200.0, 200.0);
    PID_History_Init(&history);

    printf("PID Control with History Trend Analysis\n");
    printf("Kp=%.2f Ki=%.2f Kd=%.2f Setpoint=%.2f\n\n",
           pid.kp, pid.ki, pid.kd, pid.setpoint);

    for (i = 0; i < 20; i++) {
        output = PID_Compute(&pid, feedback, &history, (unsigned long)(i * 10));
        feedback += output * 0.1;
        if (feedback > 150.0) {
            feedback = 150.0;
        }
        if (feedback < -50.0) {
            feedback = -50.0;
        }
    }

    PID_History_Print(&history);
    printf("\n");
    PID_History_Trend(&history);

    return 0;
}
