#include <math.h>

#define PI 3.14159265358979323846f
#define SIN_TABLE_SIZE 1024
#define PWM_PERIOD 1000
#define MODULATION_INDEX 0.8f

static uint16_t sin_table[SIN_TABLE_SIZE];
static uint16_t pwm_duty_a;
static uint16_t pwm_duty_b;
static uint16_t pwm_duty_c;

static void sin_table_init(void)
{
    for (int i = 0; i < SIN_TABLE_SIZE; i++) {
        float angle = 2.0f * PI * (float)i / (float)SIN_TABLE_SIZE;
        float value = sinf(angle);
        sin_table[i] = (uint16_t)((value + 1.0f) * 0.5f * (float)PWM_PERIOD);
    }
}

static uint16_t sin_lookup(uint32_t phase)
{
    phase %= SIN_TABLE_SIZE;
    return sin_table[phase];
}

static void spwm_update(float theta)
{
    uint32_t phase_a = (uint32_t)(theta * (float)SIN_TABLE_SIZE / (2.0f * PI));
    uint32_t phase_b = (phase_a + SIN_TABLE_SIZE / 3) % SIN_TABLE_SIZE;
    uint32_t phase_c = (phase_a + 2 * SIN_TABLE_SIZE / 3) % SIN_TABLE_SIZE;

    uint16_t sin_a = sin_lookup(phase_a);
    uint16_t sin_b = sin_lookup(phase_b);
    uint16_t sin_c = sin_lookup(phase_c);

    pwm_duty_a = (uint16_t)((float)sin_a * MODULATION_INDEX);
    pwm_duty_b = (uint16_t)((float)sin_b * MODULATION_INDEX);
    pwm_duty_c = (uint16_t)((float)sin_c * MODULATION_INDEX);
}

int main(void)
{
    sin_table_init();

    printf("SPWM Modulation with 1024-point sine table\n");
    printf("PWM Period: %d, Modulation Index: %.2f\n\n", PWM_PERIOD, MODULATION_INDEX);

    printf("Index\tTheta(deg)\tDuty_A\tDuty_B\tDuty_C\n");
    printf("--------------------------------------------------\n");

    for (int step = 0; step < 12; step++) {
        float theta = 2.0f * PI * (float)step / 12.0f;
        spwm_update(theta);
        printf("%d\t%.1f\t\t%d\t%d\t%d\n",
               step,
               theta * 180.0f / PI,
               pwm_duty_a,
               pwm_duty_b,
               pwm_duty_c);
    }

    printf("\nSine table first 8 entries:\n");
    for (int i = 0; i < 8; i++) {
        printf("sin_table[%d] = %d\n", i, sin_table[i]);
    }

    return 0;
}
