#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
static volatile uint32_t g_reg_ta  = 0;
static volatile uint32_t g_reg_tb  = 0;
static volatile uint32_t g_reg_tc  = 0;
static volatile uint32_t g_reg_udc = 0;

#define MOCK_REG_TA  (g_reg_ta)
#define MOCK_REG_TB  (g_reg_tb)
#define MOCK_REG_TC  (g_reg_tc)
#define MOCK_REG_UDC (g_reg_udc)

/* ==================== 常量定义 ==================== */
#define PI          3.14159265358979323846f
#define SQRT3       1.73205080756887729353f

/* 扇区枚举 */
typedef enum {
    SECTOR_1 = 1,
    SECTOR_2 = 2,
    SECTOR_3 = 3,
    SECTOR_4 = 4,
    SECTOR_5 = 5,
    SECTOR_6 = 6
} SVPWM_Sector;

/* SVPWM 输出结构体 */
typedef struct {
    float Ta;
    float Tb;
    float Tc;
    int   sector;
} SVPWM_Output;

/* ==================== 扇区判断优化 ==================== */
static int svpwm_get_sector(float alpha, float beta)
{
    float A = beta;
    float B = (SQRT3 * alpha - beta) * 0.5f;
    float C = (-SQRT3 * alpha - beta) * 0.5f;

    int sign_A = (A > 0.0f) ? 1 : 0;
    int sign_B = (B > 0.0f) ? 1 : 0;
    int sign_C = (C > 0.0f) ? 1 : 0;

    int N = sign_A + 2 * sign_B + 4 * sign_C;

    switch (N) {
        case 3: return SECTOR_1;
        case 1: return SECTOR_2;
        case 5: return SECTOR_3;
        case 4: return SECTOR_4;
        case 6: return SECTOR_5;
        case 2: return SECTOR_6;
        default: return SECTOR_1;
    }
}

/* ==================== SVPWM 核心计算 ==================== */
static SVPWM_Output svpwm_calc(float Ualpha, float Ubeta, float Udc)
{
    SVPWM_Output out;
    float Ts = 1.0f;
    float T1, T2, T0;
    float X, Y, Z;
    float half_T0;

    (void)Udc;

    out.sector = svpwm_get_sector(Ualpha, Ubeta);

    X = SQRT3 * Ubeta;
    Y = 1.5f * Ualpha + 0.5f * SQRT3 * Ubeta;
    Z = -1.5f * Ualpha + 0.5f * SQRT3 * Ubeta;

    switch (out.sector) {
        case SECTOR_1: T1 = -Z; T2 =  X; break;
        case SECTOR_2: T1 =  Z; T2 =  Y; break;
        case SECTOR_3: T1 =  X; T2 = -Y; break;
        case SECTOR_4: T1 = -X; T2 =  Z; break;
        case SECTOR_5: T1 = -Y; T2 = -Z; break;
        case SECTOR_6: T1 =  Y; T2 = -X; break;
        default:       T1 = 0.0f; T2 = 0.0f; break;
    }

    if (T1 < 0.0f) T1 = 0.0f;
    if (T2 < 0.0f) T2 = 0.0f;
    if (T1 + T2 > Ts) {
        float scale = Ts / (T1 + T2);
        T1 *= scale;
        T2 *= scale;
    }

    T0 = Ts - T1 - T2;
    half_T0 = T0 * 0.5f;

    switch (out.sector) {
        case SECTOR_1:
            out.Ta = half_T0 + T1 + T2;
            out.Tb = half_T0 + T2;
            out.Tc = half_T0;
            break;
        case SECTOR_2:
            out.Ta = half_T0 + T1;
            out.Tb = half_T0 + T1 + T2;
            out.Tc = half_T0;
            break;
        case SECTOR_3:
            out.Ta = half_T0;
            out.Tb = half_T0 + T1 + T2;
            out.Tc = half_T0 + T2;
            break;
        case SECTOR_4:
            out.Ta = half_T0;
            out.Tb = half_T0 + T1;
            out.Tc = half_T0 + T1 + T2;
            break;
        case SECTOR_5:
            out.Ta = half_T0 + T2;
            out.Tb = half_T0;
            out.Tc = half_T0 + T1 + T2;
            break;
        case SECTOR_6:
            out.Ta = half_T0 + T1 + T2;
            out.Tb = half_T0;
            out.Tc = half_T0 + T1;
            break;
        default:
            out.Ta = 0.5f;
            out.Tb = 0.5f;
            out.Tc = 0.5f;
            break;
    }

    if (out.Ta > 1.0f) out.Ta = 1.0f;
    if (out.Tb > 1.0f) out.Tb = 1.0f;
    if (out.Tc > 1.0f) out.Tc = 1.0f;
    if (out.Ta < 0.0f) out.Ta = 0.0f;
    if (out.Tb < 0.0f) out.Tb = 0.0f;
    if (out.Tc < 0.0f) out.Tc = 0.0f;

    return out;
}

/* ==================== 主函数测试 ==================== */
int main(void)
{
