```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
/* 使用真实变量模拟寄存器，避免对宏常量取地址 */
static volatile uint16_t TIM1_ARR_REG = 0xFFFFU;
static volatile uint16_t TIM1_CCR1_REG = 0x0000U;
static volatile uint16_t TIM1_CCR2_REG = 0x0000U;
static volatile uint16_t TIM1_CCR3_REG = 0x0000U;
static volatile uint16_t TIM1_CR1_REG = 0x0000U;

#define TIM1_ARR        (TIM1_ARR_REG)
#define TIM1_CCR1       (TIM1_CCR1_REG)
#define TIM1_CCR2       (TIM1_CCR2_REG)
#define TIM1_CCR3       (TIM1_CCR3_REG)
#define TIM1_CR1        (TIM1_CR1_REG)

/* 死区补偿参数 */
#define DEADTIME_NS     1000U
#define PWM_FREQ_HZ     10000U
#define PWM_PERIOD_NS   (1000000000U / PWM_FREQ_HZ)
#define DEADTIME_TICKS  ((DEADTIME_NS * 0xFFFFU) / PWM_PERIOD_NS)

/* 电流方向定义 */
typedef enum {
    CURRENT_POSITIVE = 1,
    CURRENT_NEGATIVE = -1,
    CURRENT_ZERO     = 0
} CurrentDir_t;

/* 三相电流结构体 */
typedef struct {
    float ia;
    float ib;
    float ic;
} PhaseCurrent_t;

/* 三相占空比结构体 */
typedef struct {
    float da;
    float db;
    float dc;
} DutyCycle_t;

/* ==================== 电流方向判断 ==================== */
CurrentDir_t get_current_direction(float current, float threshold)
{
    if (current > threshold) {
        return CURRENT_POSITIVE;
    } else if (current < -threshold) {
        return CURRENT_NEGATIVE;
    } else {
        return CURRENT_ZERO;
    }
}

/* ==================== 死区补偿 ==================== */
float deadtime_compensate(float duty, CurrentDir_t dir, float comp_amount)
{
    float compensated = duty;

    switch (dir) {
        case CURRENT_POSITIVE:
            compensated = duty + comp_amount;
            break;
        case CURRENT_NEGATIVE:
            compensated = duty - comp_amount;
            break;
        case CURRENT_ZERO:
        default:
            compensated = duty;
            break;
    }

    if (compensated > 1.0f) {
        compensated = 1.0f;
    } else if (compensated < 0.0f) {
        compensated = 0.0f;
    }

    return compensated;
}

/* ==================== SVPWM 调制 ==================== */
void svpwm_modulate(float u_alpha, float u_beta, float vdc, DutyCycle_t *duty)
{
    float ua, ub, uc;
    float umax, umin, uoffset;

    if (vdc <= 0.0f) {
        duty->da = 0.5f;
        duty->db = 0.5f;
        duty->dc = 0.5f;
        return;
    }

    /* 反 Clarke 变换：alpha-beta -> abc */
    ua = u_alpha;
    ub = -0.5f * u_alpha + (sqrtf(3.0f) / 2.0f) * u_beta;
    uc = -0.5f * u_alpha - (sqrtf(3.0f) / 2.0f) * u_beta;

    /* 归一化 */
    ua = ua / vdc;
    ub = ub / vdc;
    uc = uc / vdc;

    /* 零序分量注入（SVPWM 核心） */
    umax = ua;
    if (ub > umax) umax = ub;
    if (uc > umax) umax = uc;

    umin = ua;
    if (ub < umin) umin = ub;
    if (uc < umin) umin = uc;

    uoffset = -(umax + umin) / 2.0f;

    /* 计算占空比 */
    duty->da = 0.5f + ua + uoffset;
    duty->db = 0.5f + ub + uoffset;
    duty->dc = 0.5f + uc + uoffset;

    /* 限幅 */
    if (duty->da > 1.0f) duty->da = 1.0f;
    if (duty->da < 0.0f) duty->da = 0.0f;
    if (duty->db > 1.0f) duty->db = 1.0f;
    if (duty->db < 0.0f) duty->db = 0.0f;
    if (duty->dc > 1.0f) duty->dc = 1.0f;
    if (duty->dc < 0.0f) duty->dc = 0.0f;
}

/* ==================== 更新 PWM 寄存器 ==================== */
void update_pwm_registers(DutyCycle_t *duty)
{
    uint16_t ccr1 = (uint16_t)(duty->da * (float)TIM1_ARR);
    uint16_t ccr2 = (uint16_t)(duty->db * (float)TIM1_ARR);
    uint16_t ccr3 = (uint16_t)(duty->dc * (float)TIM1_ARR);

    TIM1_CCR1 = ccr1;
    TIM1_CCR2 = ccr2;
    TIM1_CCR3 = ccr3;
}

/* ==================== 主控制步骤 ==================== */
void svpwm_control_step(float u_alpha, float u_beta, float vdc,
                        PhaseCurrent_t *current, float current_threshold)
{
    DutyCycle_t duty;
    CurrentDir_t dir_a, dir_b, dir_c;
    float comp_amount;

    /* 1. SVPWM 调制 */
    svpwm_modulate(u_alpha, u_beta, vdc, &duty);

    /* 2. 计算死区补偿量（归一化） */
    comp_amount = (float)DEADTIME_TICKS / (float)TIM1_ARR;

    /* 3. 判断各相电流方向 */
    dir_a = get_current_direction(current->ia, current_threshold);
    dir_b = get_current_direction(current->ib, current_threshold);
    dir_c = get_current_direction(current->ic, current_threshold);

    /* 4. 死区补偿 */
    duty.da = deadtime_compensate(duty.da, dir_a, comp_amount);
    duty.db = deadtime_compensate(duty.db, dir_b, comp_amount);
    duty.dc = deadtime_compensate(duty.dc, dir_c, comp_amount);

    /* 5. 更新 PWM 寄存器 */
    update_pwm_registers(&duty);

    /* 打印调试信息 */
    printf("=== SVPWM Control Step ===\n");
    printf("Input: u_alpha=%.4f, u_beta=%.4f, vdc=%.2f\n", u_alpha, u_beta, vdc);
    printf("Currents: ia=%.4f, ib=%.4f, ic=%.4f\n", current->ia, current->ib, current->ic);
    printf("Current Dir: A=%d, B=%d, C=%d\n", (int)dir_a, (int)dir_b, (int)dir_c);
    printf("Comp Amount: %.6f\n", comp_amount);
    printf("Duty (compensated): da=%.4f, db=%.4f, dc=%.4f\n", duty.da, duty.db, duty.dc);
    printf("CCR1=%u, CCR2=%u, CCR3=%u\n",
           (unsigned)TIM1_CCR1, (unsigned)TIM1_CCR2, (unsigned)TIM1_CCR3);
