/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t g_pwm_period_reg = 0;
static volatile uint32_t g_pwm_duty_reg[4] = {0, 0, 0, 0};
static volatile uint32_t g_pwm_enable_reg = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_DUTY_REG(n)     (g_pwm_duty_reg[(n)])
#define PWM_ENABLE_REG      (g_pwm_enable_reg)

#define PWM_MODULE_COUNT    4
#define PWM_TIMER_CLK_HZ    100000000UL
#define PWM_SWITCH_FREQ_HZ  10000UL
#define PWM_DEADTIME_NS     500UL

/* ================= 系统参数 ================= */
#define PI                  3.14159265358979323846f
#define MOD_INDEX           0.85f
#define FUND_FREQ_HZ        50.0f
#define SAMPLE_RATE_HZ      100000.0f

/* ================= 全局变量 ================= */
static float g_phase_accum = 0.0f;
static float g_phase_step = 0.0f;
static uint32_t g_pwm_period = 0;
static uint32_t g_deadtime_ticks = 0;

/* ================= 初始化 ================= */
static void cps_pwm_init(void)
{
    g_pwm_period = PWM_TIMER_CLK_HZ / PWM_SWITCH_FREQ_HZ;
    g_deadtime_ticks = (PWM_TIMER_CLK_HZ / 1000000000UL) * PWM_DEADTIME_NS;
    if (g_deadtime_ticks < 1) g_deadtime_ticks = 1;

    g_phase_step = 2.0f * PI * FUND_FREQ_HZ / SAMPLE_RATE_HZ;

    PWM_PERIOD_REG = g_pwm_period;
    PWM_ENABLE_REG = 0x01;
}

/* ================= 载波移相 PWM 核心算法 ================= */
static void cps_pwm_update(float mod_wave)
{
    uint32_t i;
    float carrier_phase;
    float duty;
    uint32_t duty_ticks;

    for (i = 0; i < PWM_MODULE_COUNT; i++) {
        carrier_phase = g_phase_accum + (2.0f * PI * (float)i / (float)PWM_MODULE_COUNT);
        carrier_phase = fmodf(carrier_phase, 2.0f * PI);
        if (carrier_phase < 0.0f) carrier_phase += 2.0f * PI;

        float carrier = 0.5f * (1.0f - cosf(carrier_phase));

        duty = 0.5f + 0.5f * mod_wave * MOD_INDEX;

        float pwm_val = duty - carrier;
        if (pwm_val > 0.0f) {
            duty_ticks = (uint32_t)(pwm_val * (float)g_pwm_period);
        } else {
            duty_ticks = 0;
        }

        if (duty_ticks > g_pwm_period) duty_ticks = g_pwm_period;
        if (duty_ticks < g_deadtime_ticks) duty_ticks = g_deadtime_ticks;

        PWM_DUTY_REG(i) = duty_ticks;
    }

    g_phase_accum += g_phase_step;
    if (g_phase_accum >= 2.0f * PI) {
        g_phase_accum -= 2.0f * PI;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t step;
    uint32_t total_steps;
    uint32_t print_interval;

    cps_pwm_init();

    total_steps = (uint32_t)(SAMPLE_RATE_HZ / FUND_FREQ_HZ);
    if (total_steps == 0) total_steps = 1;
    print_interval = total_steps / 10;
    if (print_interval == 0) print_interval = 1;

    printf("=== CPS-PWM Multi-Level Control Algorithm ===\n");
    printf("PWM Period: %u ticks\n", g_pwm_period);
    printf("Deadtime: %u ticks\n", g_deadtime_ticks);
    printf("Modules: %d\n", PWM_MODULE_COUNT);
    printf("Modulation Index: %.2f\n", MOD_INDEX);
    printf("Fundamental Freq: %.1f Hz\n", FUND_FREQ_HZ);
    printf("Switch Freq: %.1f Hz\n", (float)PWM_SWITCH_FREQ_HZ);
    printf("----------------------------------------------\n");

    printf("Step | ModWave | Duty0 | Duty1 | Duty2 | Duty3\n");
    printf("-----+---------+-------+-------+-------+-------\n");

    for (step = 0; step < total_steps; step++) {
        float mod_wave = sinf(g_phase_accum);
        cps_pwm_update(mod_wave);

        if (step % print_interval == 0) {
            printf("%4u | %+7.4f | %5u | %5u | %5u | %5u\n",
                   step, mod_wave,
                   PWM_DUTY_REG(0), PWM_DUTY_REG(1),
                   PWM_DUTY_REG(2), PWM_DUTY_REG(3));
        }
    }

    printf("----------------------------------------------\n");
    printf("CPS-PWM test completed successfully.\n");

    return 0;
}
