#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t g_pwm_period_reg = 0;
static volatile uint32_t g_pwm_cmpa_reg = 0;
static volatile uint32_t g_pwm_cmpb_reg = 0;
static volatile uint32_t g_pwm_deadtime_reg = 0;
static volatile uint32_t g_pwm_ctrl_reg = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_CMPA_REG        (g_pwm_cmpa_reg)
#define PWM_CMPB_REG        (g_pwm_cmpb_reg)
#define PWM_DEADTIME_REG    (g_pwm_deadtime_reg)
#define PWM_CTRL_REG        (g_pwm_ctrl_reg)

#define PWM_CTRL_ENABLE     (1U << 0)
#define PWM_CTRL_UPDATE     (1U << 1)

/* 系统时钟与PWM参数 */
#define SYS_CLK_HZ          100000000U
#define PWM_FREQ_HZ         100000U
#define PWM_PERIOD_TICKS    (SYS_CLK_HZ / PWM_FREQ_HZ)
#define DEADTIME_NS         200U
#define DEADTIME_TICKS      ((SYS_CLK_HZ / 1000000U) * DEADTIME_NS / 1000U)

/* 移相全桥控制参数 */
#define PHASE_SHIFT_MIN_DEG 5.0f
#define PHASE_SHIFT_MAX_DEG 175.0f
#define PHASE_SHIFT_INIT_DEG 90.0f

/* 软开关相关参数 */
#define ZVS_DEADTIME_MIN_NS 150U
#define ZVS_DEADTIME_MAX_NS 500U
#define ZVS_LOAD_MIN_A      0.5f
#define ZVS_LOAD_MAX_A      20.0f

/* ================= 数据结构 ================= */
typedef struct {
    float phase_shift_deg;
    float output_voltage;
    float output_current;
    float target_voltage;
    float kp;
    float ki;
    float integral;
    uint32_t period_ticks;
    uint32_t deadtime_ticks;
    uint8_t enabled;
} PSFB_Controller_t;

/* ================= 全局变量 ================= */
static PSFB_Controller_t g_psfb;

/* ================= 函数声明 ================= */
static void PSFB_Init(PSFB_Controller_t *ctrl);
static void PSFB_SetPhaseShift(PSFB_Controller_t *ctrl, float phase_deg);
static void PSFB_UpdatePWM(PSFB_Controller_t *ctrl);
static float PSFB_CalcPhaseShift(PSFB_Controller_t *ctrl, float vout, float iout);
static void PSFB_Enable(PSFB_Controller_t *ctrl, uint8_t en);
static void PSFB_SoftStart(PSFB_Controller_t *ctrl, uint32_t step);

/* ================= 初始化 ================= */
static void PSFB_Init(PSFB_Controller_t *ctrl)
{
    ctrl->phase_shift_deg = PHASE_SHIFT_INIT_DEG;
    ctrl->output_voltage = 0.0f;
    ctrl->output_current = 0.0f;
    ctrl->target_voltage = 48.0f;
    ctrl->kp = 0.05f;
    ctrl->ki = 0.001f;
    ctrl->integral = 0.0f;
    ctrl->period_ticks = PWM_PERIOD_TICKS;
    ctrl->deadtime_ticks = DEADTIME_TICKS;
    ctrl->enabled = 0;

    PWM_PERIOD_REG = ctrl->period_ticks;
    PWM_DEADTIME_REG = ctrl->deadtime_ticks;
    PWM_CTRL_REG = 0;
}

/* ================= 设置移相角 ================= */
static void PSFB_SetPhaseShift(PSFB_Controller_t *ctrl, float phase_deg)
{
    if (phase_deg < PHASE_SHIFT_MIN_DEG) {
        phase_deg = PHASE_SHIFT_MIN_DEG;
    }
    if (phase_deg > PHASE_SHIFT_MAX_DEG) {
        phase_deg = PHASE_SHIFT_MAX_DEG;
    }
    ctrl->phase_shift_deg = phase_deg;
}

/* ================= 更新PWM寄存器 ================= */
static void PSFB_UpdatePWM(PSFB_Controller_t *ctrl)
{
    uint32_t period = ctrl->period_ticks;
    uint32_t half_period;
    float phase_ratio;
    uint32_t phase_ticks;
    uint32_t cmpa;
    uint32_t cmpb;

    if (period == 0U) {
        return;
    }

    half_period = period / 2U;
    if (half_period == 0U) {
        half_period = 1U;
    }

    phase_ratio = ctrl->phase_shift_deg / 180.0f;
    phase_ticks = (uint32_t)(phase_ratio * (float)half_period);

    cmpa = half_period;
    cmpb = half_period + phase_ticks;

    if (cmpb >= period) {
        cmpb = period - 1U;
    }

    PWM_CMPA_REG = cmpa;
    PWM_CMPB_REG = cmpb;

    PWM_CTRL_REG |= PWM_CTRL_UPDATE;
}

/* ================= 计算移相角（PI控制） ================= */
static float PSFB_CalcPhaseShift(PSFB_Controller_t *ctrl, float vout, float iout)
{
    float error = ctrl->target_voltage - vout;
    float phase;

    ctrl->integral += error;
    if (ctrl->integral > 1000.0f) {
        ctrl->integral = 1000.0f;
    }
    if (ctrl->integral < -1000.0f) {
        ctrl->integral = -1000.0f;
    }

    phase = ctrl->phase_shift_deg + ctrl->kp * error + ctrl->ki * ctrl->integral;

    if (iout < ZVS_LOAD_MIN_A) {
        ctrl->deadtime_ticks = (SYS_CLK_HZ / 1000000U) * ZVS_DEADTIME_MAX_NS / 1000U;
    } else if (iout > ZVS_LOAD_MAX_A) {
        ctrl->deadtime_ticks = (SYS_CLK_HZ / 1000000U) * ZVS_DEADTIME_MIN_NS / 1000U;
    } else {
        float ratio = (iout - ZVS_LOAD_MIN_A) / (ZVS_LOAD_MAX_A - ZVS_LOAD_MIN_A);
        uint32_t dt_ns = (uint32_t)(ZVS_DEADTIME_MAX_NS -
                        ratio * (ZVS_DEADTIME_MAX_NS - ZVS_DEADTIME_MIN_NS));
        ctrl->deadtime_ticks = (SYS_CLK_HZ / 1000000U) * dt_ns / 1000U;
    }
    PWM_DEADTIME_REG = ctrl->deadtime_ticks;

    if (phase < PHASE_SHIFT_MIN_DEG) {
        phase = PHASE_SHIFT_MIN_DEG;
    }
    if (phase > PHASE_SHIFT_MAX_DEG) {
        phase = PHASE_SHIFT_MAX_DEG;
    }

    return phase;
}

/* ================= 使能控制 ================= */
static void PSFB_Enable(PSFB_Controller_t *ctrl, uint8_t en)
{
    ctrl->enabled = en;
    if (en) {
        PWM_CTRL_REG |= PWM_CTRL_ENABLE;
    } else {
        PWM_CTRL_REG &= ~PWM_CTRL_ENABLE;
    }
}

/* ================= 软启动 ================= */
static void PSFB_SoftStart(PSFB_Controller_t *ctrl, uint32_t step)
{
    float target = 48.0f;
    float start = 0.0f;
    float step_voltage;

    if (step > 100U) {
        step = 100U;
    }

    step_voltage = start + (target - start) * ((float)step / 100.0f);
    ctrl->target_voltage = step_voltage;
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t i;
    float vout_sim;
    float iout_sim;

    printf("===== Phase-Shifted Full-Bridge PWM Controller =====\n");
    printf("PWM Frequency: %u Hz\n", (unsigned)PWM_FREQ_HZ);
    printf("PWM Period: %u ticks\n", (unsigned)PWM_PERIOD_TICKS);
    printf("Deadtime: %u ticks\n", (unsigned)DEADTIME_TICKS);
    printf("Initial Phase Shift: %.1f deg\n\n", (double)PHASE_SHIFT_INIT_DEG);

    PSFB_Init(&g_psfb);
    PSFB_Enable(&g_psfb, 1);

    vout_sim = 0.0f;
    iout_sim = 2.0f;

    printf("Step | Phase(deg) | Vout(V) | Iout(A) | Deadtime(ticks)\n");
    printf("-----+------------+---------+---------+----------------\n");

    for (i = 0; i < 20U; i++) {
        float phase;

        if (i < 10U) {
            PSFB_SoftStart(&g_psfb, i * 10U);
        }

        phase = PSFB_CalcPhaseShift(&g_psfb, vout_sim, iout_sim);
        PSFB_SetPhaseShift(&g_psfb, phase);

        PSFB_UpdatePWM(&g_psfb);

        vout_sim += (g_psfb.target_voltage - vout_sim) * 0.15f;
        if (vout_sim < 0.0f) {
            vout_sim = 0.0f;
        }

        iout_sim = 2.0f + 5.0f * sinf((float)i * 0.3f);
        if (iout_sim < 0.1f) {
            iout_sim = 0.1f;
        }

        printf("%4u | %10.2f | %7.2f | %7.2f | %14u\n",
               (unsigned)i,
               (double)g_psfb.phase_shift_deg,
               (double)vout_sim,
               (double)iout_sim,
               (unsigned)g_psfb.deadtime_ticks);
    }

    PSFB_Enable(&g_psfb, 0);
    printf("\nController disabled. PWM output off.\n");

    return 0;
}
