/* ---------- 模拟硬件寄存器（mock） ---------- */
static volatile unsigned int g_pwm_period_reg = 0;
static volatile unsigned int g_pwm_duty_reg   = 0;
static volatile unsigned int g_pwm_ctrl_reg   = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_DUTY_REG        (g_pwm_duty_reg)
#define PWM_CTRL_REG        (g_pwm_ctrl_reg)
#define PWM_ENABLE_BIT      (1u << 0)

/* ---------- 系统参数 ---------- */
#define PWM_CLK_FREQ_HZ     72000000u
#define PWM_BASE_FREQ_HZ    10000u
#define PWM_FREQ_DEVIATION  2000u
#define PWM_DUTY_RATIO      0.5f

/* ---------- 随机数生成器（线性同余） ---------- */
static unsigned int g_rng_state = 123456789u;

static void rng_seed(unsigned int seed)
{
    g_rng_state = seed ? seed : 1u;
}

static unsigned int rng_next(void)
{
    g_rng_state = g_rng_state * 1664525u + 1013904223u;
    return g_rng_state;
}

static float rng_float(void)
{
    return (float)(rng_next() >> 8) / (float)(1u << 24);
}

static float rng_signed(void)
{
    return rng_float() * 2.0f - 1.0f;
}

/* ---------- PWM 初始化 ---------- */
static void pwm_init(void)
{
    PWM_CTRL_REG = 0;
    PWM_PERIOD_REG = PWM_CLK_FREQ_HZ / PWM_BASE_FREQ_HZ;
    PWM_DUTY_REG = (unsigned int)((float)PWM_PERIOD_REG * PWM_DUTY_RATIO);
    PWM_CTRL_REG |= PWM_ENABLE_BIT;
}

/* ---------- 随机 PWM 更新 ---------- */
static unsigned int pwm_random_update(void)
{
    float r;
    float freq;
    unsigned int period;

    r = rng_signed();

    freq = (float)PWM_BASE_FREQ_HZ + r * (float)PWM_FREQ_DEVIATION;

    if (freq < (float)(PWM_BASE_FREQ_HZ - PWM_FREQ_DEVIATION))
        freq = (float)(PWM_BASE_FREQ_HZ - PWM_FREQ_DEVIATION);
    if (freq > (float)(PWM_BASE_FREQ_HZ + PWM_FREQ_DEVIATION))
        freq = (float)(PWM_BASE_FREQ_HZ + PWM_FREQ_DEVIATION);

    if (freq < 1.0f) freq = 1.0f;

    period = (unsigned int)((float)PWM_CLK_FREQ_HZ / freq);
    if (period == 0) period = 1;

    PWM_PERIOD_REG = period;
    PWM_DUTY_REG = (unsigned int)((float)period * PWM_DUTY_RATIO);

    return (unsigned int)freq;
}

/* ---------- 主函数 ---------- */
int main(void)
{
    int i;
    unsigned int freq;
    unsigned int period;

    printf("========================================\n");
    printf("  Random PWM (Triangular Carrier Freq)  \n");
    printf("========================================\n");
    printf("PWM Clock     : %u Hz\n", PWM_CLK_FREQ_HZ);
    printf("Base Freq     : %u Hz\n", PWM_BASE_FREQ_HZ);
    printf("Deviation     : +/- %u Hz\n", PWM_FREQ_DEVIATION);
    printf("Duty Ratio    : %.1f%%\n", PWM_DUTY_RATIO * 100.0f);
    printf("----------------------------------------\n");

    rng_seed((unsigned int)time(NULL));

    pwm_init();
    printf("[INIT] PWM initialized. Period = %u, Duty = %u\n",
           PWM_PERIOD_REG, PWM_DUTY_REG);
    printf("----------------------------------------\n");

    printf("Step |  Freq(Hz) |  Period  |  Duty\n");
    printf("-----+-----------+----------+-------\n");

    for (i = 0; i < 20; i++) {
        freq = pwm_random_update();
        period = PWM_PERIOD_REG;
        printf("%4d | %9u | %8u | %5u\n",
               i + 1, freq, period, PWM_DUTY_REG);
    }

    printf("----------------------------------------\n");
    printf("[DONE] Random PWM test completed.\n");

    return 0;
}
