#include <stdio.h>
#include <stdint.h>
#include <math.h>

#define PDM_TABLE_SIZE 256
#define PDM_MAX_DENSITY 255

typedef struct {
    uint32_t phase_acc;
    uint32_t phase_step;
    uint32_t density;
    uint32_t pulse_count;
    uint32_t total_count;
    uint32_t error_acc;
    uint32_t target_density;
    uint32_t output;
} PDM_Handle;

static uint8_t pdm_density_table[PDM_TABLE_SIZE];

static void PDM_InitTable(void)
{
    for (uint32_t i = 0; i < PDM_TABLE_SIZE; i++) {
        pdm_density_table[i] = (uint8_t)((i * PDM_MAX_DENSITY) / (PDM_TABLE_SIZE - 1));
    }
}

static void PDM_Init(PDM_Handle *h, uint32_t sample_rate, uint32_t pdm_freq)
{
    h->phase_acc = 0;
    h->phase_step = (uint32_t)(((uint64_t)pdm_freq << 32) / sample_rate);
    h->density = 0;
    h->pulse_count = 0;
    h->total_count = 0;
    h->error_acc = 0;
    h->target_density = 0;
    h->output = 0;
}

static void PDM_SetDensity(PDM_Handle *h, uint32_t density)
{
    if (density > PDM_MAX_DENSITY) {
        density = PDM_MAX_DENSITY;
    }
    h->target_density = density;
}

static uint32_t PDM_Update(PDM_Handle *h)
{
    h->phase_acc += h->phase_step;
    if (h->phase_acc < h->phase_step) {
        h->phase_acc = 0;
    }

    uint32_t idx = (h->phase_acc >> 24) & (PDM_TABLE_SIZE - 1);
    uint32_t desired = pdm_density_table[idx];

    if (h->target_density > 0) {
        desired = (desired * h->target_density) / PDM_MAX_DENSITY;
    }

    h->error_acc += desired;
    if (h->error_acc >= PDM_MAX_DENSITY) {
        h->error_acc -= PDM_MAX_DENSITY;
        h->output = 1;
        h->pulse_count++;
    } else {
        h->output = 0;
    }
    h->total_count++;

    return h->output;
}

static double PDM_GetActualDensity(PDM_Handle *h)
{
    if (h->total_count == 0) {
        return 0.0;
    }
    return (double)h->pulse_count / (double)h->total_count;
}

int main(void)
{
    PDM_InitTable();

    PDM_Handle pdm;
    uint32_t sample_rate = 1000000;
    uint32_t pdm_freq = 100000;

    PDM_Init(&pdm, sample_rate, pdm_freq);

    printf("=== PDM (Pulse Density Modulation) Test ===\n");
    printf("Sample Rate: %u Hz\n", sample_rate);
    printf("PDM Frequency: %u Hz\n", pdm_freq);
    printf("Table Size: %d\n\n", PDM_TABLE_SIZE);

    uint32_t test_densities[] = {0, 32, 64, 128, 192, 255};
    uint32_t num_tests = sizeof(test_densities) / sizeof(test_densities[0]);

    for (uint32_t t = 0; t < num_tests; t++) {
        PDM_Init(&pdm, sample_rate, pdm_freq);
        PDM_SetDensity(&pdm, test_densities[t]);

        uint32_t iterations = 10000;
        for (uint32_t i = 0; i < iterations; i++) {
            PDM_Update(&pdm);
        }

        double actual = PDM_GetActualDensity(&pdm);
        double expected = (double)test_densities[t] / (double)PDM_MAX_DENSITY;

        printf("Target Density: %3u/255 (%.4f) | ", test_densities[t], expected);
        printf("Actual: %.4f | ", actual);
        printf("Pulses: %u/%u | ", pdm.pulse_count, pdm.total_count);
        printf("Error: %.4f\n", fabs(actual - expected));
    }

    printf("\n=== PDM Waveform Sample (density=128) ===\n");
    PDM_Init(&pdm, sample_rate, pdm_freq);
    PDM_SetDensity(&pdm, 128);

    printf("Output: ");
    for (uint32_t i = 0; i < 64; i++) {
        uint32_t out = PDM_Update(&pdm);
        printf("%u", out);
        if ((i + 1) % 16 == 0) {
            printf(" ");
        }
    }
    printf("\n");

    printf("\n=== PDM Low Harmonic Verification ===\n");
    PDM_Init(&pdm, sample_rate, pdm_freq);
    PDM_SetDensity(&pdm, 128);

    uint32_t ones = 0;
    uint32_t window = 256;
    uint32_t max_deviation = 0;

    for (uint32_t i = 0; i < 4096; i++) {
        uint32_t out = PDM_Update(&pdm);
        ones += out;

        if ((i + 1) % window == 0) {
            uint32_t expected_ones = (window * 128) / 255;
            uint32_t deviation = (ones > expected_ones) ? (ones - expected_ones) : (expected_ones - ones);
            if (deviation > max_deviation) {
                max_deviation = deviation;
            }
            ones = 0;
        }
    }

    printf("Window size: %u samples\n", window);
    printf("Max deviation from ideal: %u pulses\n", max_deviation);
    printf("Deviation ratio: %.2f%%\n", (100.0 * max_deviation) / window);

    printf("\n=== PDM Test Complete ===\n");

    return 0;
}
