#include <stdio.h>
#include <math.h>
#include <stdint.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* ===== Mock 寄存器与硬件抽象 ===== */
static volatile uint32_t mock_regs[8];

#define PWM_TIMER_ARR       (mock_regs[0])
#define PWM_TIMER_CCR1      (mock_regs[1])
#define PWM_TIMER_CCR2      (mock_regs[2])
#define PWM_TIMER_CCR3      (mock_regs[3])
#define PWM_TIMER_CCR4      (mock_regs[4])
#define PWM_TIMER_CNT       (mock_regs[5])
#define PWM_TIMER_CR1       (mock_regs[6])

#define PWM_CR1_CEN         (1U << 0)
#define PWM_CR1_ARPE        (1U << 7)

/* ===== 同步调制 SPWM 参数 ===== */
#define PWM_FREQ_HZ         9000U       /* 载波频率 9kHz */
#define FUND_FREQ_HZ        50U         /* 基波频率 50Hz */
#define CARRIER_RATIO       (PWM_FREQ_HZ / FUND_FREQ_HZ) /* 载波比 N = 180 */
#define MODULATION_INDEX    0.8f        /* 调制比 M */
#define TIMER_CLK_HZ        72000000U   /* 定时器时钟 72MHz */

/* 同步调制：载波比必须为整数，且通常为 3 的倍数以消除偶次谐波 */
#if ((CARRIER_RATIO % 3) != 0)
#error "同步调制载波比必须为 3 的整数倍"
#endif

/* 三相正弦表：一个基波周期内采样 CARRIER_RATIO 个点 */
#define TABLE_SIZE          CARRIER_RATIO
static float sin_table[TABLE_SIZE];

/* ===== 初始化正弦表 ===== */
static void spwm_init_table(void)
{
    uint32_t i;
    for (i = 0; i < TABLE_SIZE; i++) {
        float theta = 2.0f * (float)M_PI * (float)i / (float)TABLE_SIZE;
        sin_table[i] = sinf(theta);
    }
}

/* ===== 初始化 PWM 定时器 (Mock) ===== */
static void pwm_timer_init(void)
{
    /* 中心对齐模式，ARR = 定时器时钟 / (2 * 载波频率) */
    uint32_t arr = TIMER_CLK_HZ / (2U * PWM_FREQ_HZ);
    PWM_TIMER_ARR = arr;
    PWM_TIMER_CR1 = PWM_CR1_ARPE;
    PWM_TIMER_CNT = 0;
    PWM_TIMER_CR1 |= PWM_CR1_CEN;
}

/* ===== 同步调制 SPWM 更新 =====
 * 在每个载波周期更新一次比较值
 * 三相相位差 120 度，对应 TABLE_SIZE/3 个索引偏移
 */
static void spwm_update(uint32_t step)
{
    uint32_t arr = PWM_TIMER_ARR;
    uint32_t idx_a, idx_b, idx_c;
    float duty_a, duty_b, duty_c;
    uint32_t ccr_a, ccr_b, ccr_c;

    /* 同步调制：step 在 0 ~ TABLE_SIZE-1 之间循环 */
    idx_a = step % TABLE_SIZE;
    idx_b = (idx_a + TABLE_SIZE / 3U) % TABLE_SIZE;
    idx_c = (idx_a + 2U * TABLE_SIZE / 3U) % TABLE_SIZE;

    /* 计算占空比：d = 0.5 + 0.5 * M * sin(theta) */
    duty_a = 0.5f + 0.5f * MODULATION_INDEX * sin_table[idx_a];
    duty_b = 0.5f + 0.5f * MODULATION_INDEX * sin_table[idx_b];
    duty_c = 0.5f + 0.5f * MODULATION_INDEX * sin_table[idx_c];

    /* 限幅保护 */
    if (duty_a > 1.0f) duty_a = 1.0f;
    if (duty_a < 0.0f) duty_a = 0.0f;
    if (duty_b > 1.0f) duty_b = 1.0f;
    if (duty_b < 0.0f) duty_b = 0.0f;
    if (duty_c > 1.0f) duty_c = 1.0f;
    if (duty_c < 0.0f) duty_c = 0.0f;

    /* 转换为比较寄存器值 */
    ccr_a = (uint32_t)(duty_a * (float)arr);
    ccr_b = (uint32_t)(duty_b * (float)arr);
    ccr_c = (uint32_t)(duty_c * (float)arr);

    PWM_TIMER_CCR1 = ccr_a;
    PWM_TIMER_CCR2 = ccr_b;
    PWM_TIMER_CCR3 = ccr_c;
    PWM_TIMER_CCR4 = 0; /* 互补通道由硬件生成 */
}

/* ===== 主函数 ===== */
int main(void)
{
    uint32_t step;
    uint32_t total_steps = TABLE_SIZE; /* 一个基波周期 */

    printf("=== 同步调制 SPWM (整数倍载波比) ===\n");
    printf("载波频率: %u Hz\n", PWM_FREQ_HZ);
    printf("基波频率: %u Hz\n", FUND_FREQ_HZ);
    printf("载波比 N: %u\n", CARRIER_RATIO);
    printf("调制比 M: %.2f\n", MODULATION_INDEX);
    printf("定时器 ARR: %u\n\n", TIMER_CLK_HZ / (2U * PWM_FREQ_HZ));

    spwm_init_table();
    pwm_timer_init();

    printf("Step |  Theta(deg) |  Duty_A  |  Duty_B  |  Duty_C  | CCR1  CCR2  CCR3\n");
    printf("-----+-------------+----------+----------+----------+------------------\n");

    for (step = 0; step < total_steps; step++) {
        float theta_deg = 360.0f * (float)step / (float)TABLE_SIZE;
        float duty_a, duty_b, duty_c;

        spwm_update(step);

        duty_a = 0.5f + 0.5f * MODULATION_INDEX * sin_table[step % TABLE_SIZE];
        duty_b = 0.5f + 0.5f * MODULATION_INDEX * sin_table[(step + TABLE_SIZE / 3U) % TABLE_SIZE];
        duty_c = 0.5f + 0.5f * MODULATION_INDEX * sin_table[(step + 2U * TABLE_SIZE / 3U) % TABLE_SIZE];

        /* 每 10 步打印一次，避免输出过多 */
        if ((step % 10U) == 0U) {
            printf("%4u | %10.2f  | %8.4f | %8.4f | %8.4f | %5u %5u %5u\n",
                   step, theta_deg, duty_a, duty_b, duty_c,
                   PWM_TIMER_CCR1, PWM_TIMER_CCR2, PWM_TIMER_CCR3);
        }
    }

    printf("\n同步调制 SPWM 测试完成。\n");
    return 0;
}
