```c
#include <stdio.h>
#include <stdint.h>

/* ============================================================
 * Mock 硬件寄存器定义（模拟数字 PWM 死区时间配置寄存器）
 * 使用普通全局变量模拟寄存器，避免直接访问非法地址导致崩溃
 * ============================================================ */

static volatile uint32_t g_pwm_dtcr = 0U;   /* 死区时间控制寄存器 */
static volatile uint32_t g_pwm_cr   = 0U;   /* 控制寄存器 */
static volatile uint32_t g_pwm_sr   = 0U;   /* 状态寄存器 */

/* 寄存器访问宏 */
#define PWM_DTCR                (g_pwm_dtcr)
#define PWM_CR                  (g_pwm_cr)
#define PWM_SR                  (g_pwm_sr)

/* 死区时间控制寄存器位定义 */
#define DTCR_DTEN               (1U << 0)       /* 死区时间使能 */
#define DTCR_DTR_SHIFT          8U              /* 上升沿死区时间位偏移 */
#define DTCR_DTR_MASK           (0xFFU << DTCR_DTR_SHIFT)
#define DTCR_DTF_SHIFT          16U             /* 下降沿死区时间位偏移 */
#define DTCR_DTF_MASK           (0xFFU << DTCR_DTF_SHIFT)
#define DTCR_DTCLK_SHIFT        24U             /* 死区时钟分频位偏移 */
#define DTCR_DTCLK_MASK         (0x0FU << DTCR_DTCLK_SHIFT)

/* 控制寄存器位定义 */
#define CR_PWMEN                (1U << 0)       /* PWM 使能 */
#define CR_DT_UPDATE            (1U << 1)       /* 死区时间更新触发 */

/* 状态寄存器位定义 */
#define SR_DT_BUSY              (1U << 0)       /* 死区时间更新忙标志 */

/* ============================================================
 * 死区时间配置参数结构体
 * ============================================================ */
typedef struct {
    uint8_t  dead_time_rising;      /* 上升沿死区时间（0~255 个时钟周期） */
    uint8_t  dead_time_falling;     /* 下降沿死区时间（0~255 个时钟周期） */
    uint8_t  clock_divider;         /* 死区时钟分频系数（0~15） */
    uint8_t  enable;                /* 死区时间使能 */
} DeadTimeConfig_t;

/* ============================================================
 * 函数声明
 * ============================================================ */
static void     PWM_DeadTime_Init(void);
static int32_t  PWM_DeadTime_Config(const DeadTimeConfig_t *cfg);
static void     PWM_DeadTime_Enable(uint8_t enable);
static uint32_t PWM_DeadTime_GetRegister(void);
static void     PWM_DeadTime_PrintConfig(const DeadTimeConfig_t *cfg);

/* ============================================================
 * 函数实现
 * ============================================================ */

/**
 * @brief  初始化 PWM 死区时间模块（复位寄存器到默认状态）
 */
static void PWM_DeadTime_Init(void)
{
    PWM_DTCR = 0x00000000U;     /* 清除所有死区配置 */
    PWM_CR  &= ~CR_PWMEN;       /* 关闭 PWM 输出 */
    PWM_CR  &= ~CR_DT_UPDATE;   /* 清除更新触发 */
    PWM_SR  &= ~SR_DT_BUSY;     /* 清除忙标志 */
    printf("[INIT] PWM 死区时间模块已初始化，DTCR = 0x%08X\n", (unsigned int)PWM_DTCR);
}

/**
 * @brief  配置 PWM 死区时间
 * @param  cfg  死区时间配置结构体指针
 * @retval 0    配置成功
 * @retval -1   参数错误
 * @retval -2   硬件忙
 */
static int32_t PWM_DeadTime_Config(const DeadTimeConfig_t *cfg)
{
    uint32_t reg_val;

    if (cfg == NULL) {
        printf("[ERROR] 配置结构体指针为空\n");
        return -1;
    }

    /* 参数范围检查 */
    if (cfg->clock_divider > 15U) {
        printf("[ERROR] 时钟分频系数超出范围 (0~15)\n");
        return -1;
    }

    /* 等待硬件空闲 */
    if (PWM_SR & SR_DT_BUSY) {
        printf("[ERROR] 硬件忙，无法配置死区时间\n");
        return -2;
    }

    /* 读取当前寄存器值 */
    reg_val = PWM_DTCR;

    /* 清除死区时间相关位域 */
    reg_val &= ~(DTCR_DTR_MASK | DTCR_DTF_MASK | DTCR_DTCLK_MASK | DTCR_DTEN);

    /* 设置上升沿死区时间 */
    reg_val |= ((uint32_t)cfg->dead_time_rising << DTCR_DTR_SHIFT) & DTCR_DTR_MASK;

    /* 设置下降沿死区时间 */
    reg_val |= ((uint32_t)cfg->dead_time_falling << DTCR_DTF_SHIFT) & DTCR_DTF_MASK;

    /* 设置死区时钟分频 */
    reg_val |= ((uint32_t)cfg->clock_divider << DTCR_DTCLK_SHIFT) & DTCR_DTCLK_MASK;

    /* 设置死区使能位 */
    if (cfg->enable) {
        reg_val |= DTCR_DTEN;
    }

    /* 写入寄存器 */
    PWM_DTCR = reg_val;

    /* 触发更新 */
    PWM_CR |= CR_DT_UPDATE;
    PWM_CR &= ~CR_DT_UPDATE;

    printf("[CONFIG] 死区时间配置完成，DTCR = 0x%08X\n", (unsigned int)PWM_DTCR);
    return 0;
}

/**
 * @brief  使能或禁用 PWM 死区时间
 * @param  enable  1=使能，0=禁用
 */
static void PWM_DeadTime_Enable(uint8_t enable)
{
    if (enable) {
        PWM_DTCR |= DTCR_DTEN;
        printf("[ENABLE] 死区时间已使能\n");
    } else {
        PWM_DTCR &= ~DTCR_DTEN;
        printf("[DISABLE] 死区时间已禁用\n");
    }
}

/**
 * @brief  读取死区时间控制寄存器原始值
 * @retval 寄存器值
 */
static uint32_t PWM_DeadTime_GetRegister(void)
{
    return PWM_DTCR;
}

/**
 * @brief  打印死区时间配置信息
 * @param  cfg  配置结构体指针
 */
static void PWM_DeadTime_PrintConfig(const DeadTimeConfig_t *cfg)
{
    if (cfg == NULL) {
        return;
    }

    printf("========== 死区时间配置 ==========\n");
    printf("  上升沿死区时间 : %u 个时钟周期\n", (unsigned int)cfg->dead_time_rising);
    printf("  下降沿死区时间 : %u 个时钟周期\n", (unsigned int)cfg->dead_time_falling);
    printf("  时钟分频系数   : %u\n", (unsigned int)cfg->clock_divider);
    printf("  死区使能       : %s\n", cfg->enable ? "是" : "否");
    printf("==================================\n");
}

/* ============================================================
 * main 函数
 * ============================================================ */
int main(void)
{
    DeadTimeConfig_t dt_cfg;
    int32_t ret;

    printf("========================================\n");
    printf("  数字 PWM 死区时间配置测试程序\n");
    printf("========================================\n\n");

    /* 1. 初始化 */
    PWM_DeadTime_Init();
    printf("\n");

    /* 2. 配置死区时间：上升沿 50 周期，下降沿 30 周期，分频 2，使能 */
    dt_cfg.dead_time_rising  = 50U;
    dt_cfg.dead_time_falling = 30U;
    dt_cfg.clock_divider     = 2U;
    dt_cfg.enable            = 1U;

    ret = PWM_DeadTime_Config(&dt_cfg);
    if (ret != 0) {
        printf("[FAIL] 死区时间配置失败，错误码 = %d\n", (int)ret);
        return 0;
    }

    PWM_DeadTime_PrintConfig(&dt_cfg);
    printf("DTCR 寄存器值 = 0x%08X\n\n", (unsigned int)PWM_DeadTime_GetRegister());

    /* 3. 验证寄存器位域 */
    {
        uint32_t reg = PWM_DeadTime_GetRegister();
        uint8_t  dtr = (uint8_t)((reg & DTCR_DTR_MASK) >> DTCR_DTR_SHIFT);
        uint8_t  dtf = (uint8_t)((reg & DTCR_DTF_MASK) >> DTCR_DTF_SHIFT);
        uint8_t  clk = (uint8_t)((reg & DTCR_DTCLK_MASK) >> DTCR_DTCLK_SHIFT);
        uint8_t  en  = (reg & DTCR_DTEN) ? 1U : 0U;

        printf("========== 寄存器位域验证 ==========\n");
        printf("  DTR  = %u (期望 50)\n", (unsigned int)dtr);
        printf("  DTF  = %u (期望 30)\n", (unsigned int)dtf);
        printf("  CLK  = %u (期望 2)\n", (unsigned int)clk);
        printf("  EN   = %u (期望 1)\n", (unsigned int)en);

        if (dtr == 50U && dtf == 30U && clk == 2U && en == 1U) {
            printf("  [PASS] 所有位域验证通过\n");
        } else {
            printf("  [FAIL] 位域验证失败\n");
        }
        printf("====================================\n\n");
