#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * ============================================================ */

/* 模拟定时器寄存器 */
typedef struct {
    volatile uint32_t CR1;      /* 控制寄存器1 */
    volatile uint32_t ARR;      /* 自动重装载寄存器 */
    volatile uint32_t PSC;      /* 预分频寄存器 */
    volatile uint32_t CCR1;     /* 捕获/比较寄存器1 */
    volatile uint32_t CNT;      /* 计数器 */
} Mock_TIM_TypeDef;

/* 模拟 GPIO 寄存器 */
typedef struct {
    volatile uint32_t MODER;
    volatile uint32_t ODR;
} Mock_GPIO_TypeDef;

/* 实例化模拟外设 */
static Mock_TIM_TypeDef mock_tim1;
static Mock_GPIO_TypeDef mock_gpioa;

/* 寄存器位定义 */
#define TIM_CR1_CEN         (1U << 0)
#define TIM_CR1_ARPE        (1U << 7)

/* 外设基地址宏（模拟） */
#define MOCK_TIM1           (&mock_tim1)
#define MOCK_GPIOA          (&mock_gpioa)

/* 系统时钟频率（Hz） */
#define SYSTEM_CLOCK_HZ     72000000U

/* ============================================================
 * PWM 模式定义
 * ============================================================ */

typedef enum {
    PWM_MODE_LOW_FREQ = 0,      /* 低频模式：1kHz，用于电机低速/加热 */
    PWM_MODE_MID_FREQ,          /* 中频模式：10kHz，用于常规电机驱动 */
    PWM_MODE_HIGH_FREQ,         /* 高频模式：20kHz，用于静音驱动 */
    PWM_MODE_ULTRA_FREQ,        /* 超高频模式：50kHz，用于高频开关电源 */
    PWM_MODE_COUNT
} PWM_Mode_t;

/* PWM 模式配置表 */
typedef struct {
    uint32_t frequency_hz;      /* 目标频率 */
    uint16_t duty_percent;      /* 占空比（0-100） */
    const char *name;           /* 模式名称 */
} PWM_ModeConfig_t;

static const PWM_ModeConfig_t pwm_mode_table[PWM_MODE_COUNT] = {
    { 1000U,  50, "LOW_FREQ   (1kHz)"  },
    { 10000U, 50, "MID_FREQ   (10kHz)" },
    { 20000U, 50, "HIGH_FREQ  (20kHz)" },
    { 50000U, 50, "ULTRA_FREQ (50kHz)" }
};

/* ============================================================
 * PWM 驱动层
 * ============================================================ */

/* 计算预分频和自动重装载值
 * 目标：PWM频率 = SYSTEM_CLOCK / ((PSC+1) * (ARR+1))
 * 策略：固定 ARR 为 1000-1，通过调整 PSC 实现频率切换
 *       这样占空比分辨率保持 0.1%
 */
static void pwm_calc_timing(uint32_t freq_hz, uint32_t *psc, uint32_t *arr)
{
    const uint32_t resolution = 1000U;  /* ARR+1 = 1000，分辨率 0.1% */
    uint32_t timer_clk = SYSTEM_CLOCK_HZ;
    uint32_t psc_val;

    if (freq_hz == 0U) {
        freq_hz = 1U;
    }

    /* PSC+1 = timer_clk / (freq * resolution) */
    psc_val = timer_clk / (freq_hz * resolution);

    if (psc_val == 0U) {
        psc_val = 1U;
    }
    if (psc_val > 65536U) {
        psc_val = 65536U;
    }

    *psc = psc_val - 1U;
    *arr = resolution - 1U;
}

/* 初始化 PWM 输出（模拟 GPIO 和定时器配置） */
static void pwm_init(void)
{
    /* 配置 GPIO 为复用推挽输出（模拟） */
    MOCK_GPIOA->MODER &= ~(3U << 0);
    MOCK_GPIOA->MODER |=  (2U << 0);   /* 复用功能模式 */

    /* 定时器基础配置 */
    MOCK_TIM1->CR1 = 0U;
    MOCK_TIM1->CR1 |= TIM_CR1_ARPE;    /* 使能自动重装载预装载 */
    MOCK_TIM1->CNT = 0U;
}

/* 设置 PWM 频率和占空比 */
static void pwm_set_frequency(uint32_t freq_hz, uint16_t duty_percent)
{
    uint32_t psc, arr;
    uint32_t ccr;

    if (duty_percent > 100U) {
        duty_percent = 100U;
    }

    pwm_calc_timing(freq_hz, &psc, &arr);

    /* 写入预分频和重装载值 */
    MOCK_TIM1->PSC = psc;
    MOCK_TIM1->ARR = arr;

    /* 计算比较值：CCR = (ARR+1) * duty / 100 */
    ccr = ((arr + 1U) * duty_percent) / 100U;
    MOCK_TIM1->CCR1 = ccr;

    /* 产生更新事件，使影子寄存器立即生效（模拟） */
    MOCK_TIM1->CNT = 0U;

    printf("  [HW] PSC=%lu, ARR=%lu, CCR1=%lu\r\n",
           (unsigned long)psc, (unsigned long)arr, (unsigned long)ccr);
}

/* 启动 PWM 输出 */
static void pwm_start(void)
{
    MOCK_TIM1->CR1 |= TIM_CR1_CEN;
    printf("  [HW] PWM 输出已启动\r\n");
}

/* 停止 PWM 输出 */
static void pwm_stop(void)
{
    MOCK_TIM1->CR1 &= ~TIM_CR1_CEN;
    printf("  [HW] PWM 输出已停止\r\n");
}

/* 读取当前实际 PWM 频率（用于验证） */
static uint32_t pwm_get_actual_frequency(void)
{
    uint32_t psc = MOCK_TIM1->PSC + 1U;
    uint32_t arr = MOCK_TIM1->ARR + 1U;
    return SYSTEM_CLOCK_HZ / (psc * arr);
}

/* ============================================================
 * 应用层：多模式适配控制
 * ============================================================ */

/* 切换 PWM 模式 */
static void pwm_switch_mode(PWM_Mode_t mode)
{
    if (mode >= PWM_MODE_COUNT) {
        printf("  [APP] 错误：无效的 PWM 模式 %d\r\n", (int)mode);
        return;
    }

    const PWM_ModeConfig_t *cfg = &pwm_mode_table[mode];

    printf("\r\n[APP] 切换到模式：%s\r\n", cfg->name);
    printf("  [APP] 目标频率：%lu Hz，占空比：%u%%\r\n",
           (unsigned long)cfg->frequency_hz, cfg->duty_percent);

    pwm_set_frequency(cfg->frequency_hz, cfg->duty_percent);

    printf("  [APP] 实际频率：%lu Hz\r\n",
           (unsigned long)pwm_get_actual_frequency());
}

/* 根据负载状态自动选择模式（示例策略） */
static PWM_Mode_t pwm_auto_select_mode(uint32_t load_rpm, uint32_t temperature_c)
{
    /* 简单策略：
     * - 温度过高 -> 降低频率减少开关损耗
     * - 转速低   -> 低频模式
     * - 转速中   -> 中频模式
     * - 转速高   -> 高频模式
     */
    if (temperature_c > 85U) {
        return PWM_MODE_LOW_FREQ;
    }
    if (load_rpm < 1000U) {
        return PWM_MODE_LOW_FREQ;
    } else if (load_rpm < 3000U) {
        return PWM_MODE_MID_FREQ;
    } else if (load_rpm < 6000U) {
        return PWM_MODE_HIGH_FREQ;
    } else {
        return PWM_MODE_ULTRA_FREQ;
    }
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    printf("========================================\r\n");
    printf("  PWM 频率切换（多模式适配）测试程序\r\n");
    printf("========================================\r\n");

    /* 1. 初始化 PWM 硬件 */
    printf("\r\n[INIT] 初始化 PWM 硬件...\r\n");
    pwm_init();
    pwm_start();

    /* 2. 手动遍历所有模式 */
    printf("\r\n--- 手动模式切换测试 ---\r\n");
    for (PWM_Mode_t m = PWM_MODE_LOW_FREQ; m < PWM_MODE_COUNT; m++) {
        pwm_switch_mode(m);
    }

    /* 3. 自动模式选择测试 */
    printf("\r\n--- 自动模式选择测试 ---\r\n");

    struct {
        uint32_t rpm;
        uint32_t temp;
    } test_cases[] = {
        {  500U, 25U },
        { 2000U, 40U },
        { 4500U, 60U },
        { 8000U, 70U },
        { 3000U, 90U }
    };

    for (size_t i = 0; i < sizeof(test_cases) / sizeof(test_cases[0]); i++) {
        printf("\r\n[TEST] 转速=%lu RPM, 温度=%lu C\r\n",
               (unsigned long)test_cases[i].rpm,
               (unsigned long)test_cases[i].temp);

        PWM_Mode_t auto_mode = pwm_auto_select_mode(test_cases[i].rpm,
                                                     test_cases[i].temp);
        pwm_switch_mode(auto_mode);
    }

    /* 4. 停止 PWM */
    printf("\r\n[SHUTDOWN] 停止 PWM 输出...\r\n");
    pwm_stop();

    printf("\r\n========================================\r\n");
    printf("  测试完成\r\n");
    printf("========================================\r\n");

    return 0;
}
