#include <stdio.h>
#include <stdint.h>
#include <math.h>

#define PWM_PHASES          4
#define PWM_PERIOD          1000
#define PWM_DEADTIME        10
#define PWM_MAX_DUTY        (PWM_PERIOD - PWM_DEADTIME)

typedef struct {
    uint32_t period;
    uint32_t phase_count;
    uint32_t phase_offset[PWM_PHASES];
    uint32_t duty[PWM_PHASES];
    uint32_t counter[PWM_PHASES];
    uint32_t output[PWM_PHASES];
} InterleavedPWM_t;

static void InterleavedPWM_Init(InterleavedPWM_t *pwm, uint32_t period, uint32_t phases)
{
    uint32_t i;
    pwm->period = period;
    pwm->phase_count = phases;
    for (i = 0; i < phases; i++) {
        pwm->phase_offset[i] = (period * i) / phases;
        pwm->duty[i] = 0;
        pwm->counter[i] = pwm->phase_offset[i];
        pwm->output[i] = 0;
    }
}

static void InterleavedPWM_SetDuty(InterleavedPWM_t *pwm, uint32_t phase, uint32_t duty)
{
    if (phase >= pwm->phase_count) return;
    if (duty > PWM_MAX_DUTY) duty = PWM_MAX_DUTY;
    pwm->duty[phase] = duty;
}

static void InterleavedPWM_Update(InterleavedPWM_t *pwm)
{
    uint32_t i;
    for (i = 0; i < pwm->phase_count; i++) {
        pwm->counter[i]++;
        if (pwm->counter[i] >= pwm->period) {
            pwm->counter[i] = 0;
        }
        if (pwm->counter[i] < pwm->duty[i]) {
            pwm->output[i] = 1;
        } else {
            pwm->output[i] = 0;
        }
    }
}

static uint32_t InterleavedPWM_GetOutput(const InterleavedPWM_t *pwm, uint32_t phase)
{
    if (phase >= pwm->phase_count) return 0;
    return pwm->output[phase];
}

static double InterleavedPWM_CalcRipple(const InterleavedPWM_t *pwm)
{
    uint32_t i;
    uint32_t sum = 0;
    uint32_t max_sum = 0;
    uint32_t min_sum = 0xFFFFFFFF;
    uint32_t total_steps = pwm->period;
    uint32_t step;

    for (step = 0; step < total_steps; step++) {
        sum = 0;
        for (i = 0; i < pwm->phase_count; i++) {
            uint32_t cnt = (pwm->counter[i] + step) % pwm->period;
            if (cnt < pwm->duty[i]) {
                sum++;
            }
        }
        if (sum > max_sum) max_sum = sum;
        if (sum < min_sum) min_sum = sum;
    }

    if (max_sum == 0) return 0.0;
    return (double)(max_sum - min_sum) / (double)max_sum * 100.0;
}

static void InterleavedPWM_PrintStatus(const InterleavedPWM_t *pwm)
{
    uint32_t i;
    printf("=== Interleaved PWM Status ===\n");
    printf("Period: %u, Phases: %u\n", pwm->period, pwm->phase_count);
    for (i = 0; i < pwm->phase_count; i++) {
        printf("Phase %u: offset=%4u duty=%4u counter=%4u output=%u\n",
               i, pwm->phase_offset[i], pwm->duty[i],
               pwm->counter[i], pwm->output[i]);
    }
    printf("Ripple: %.2f%%\n", InterleavedPWM_CalcRipple(pwm));
    printf("==============================\n");
}

int main(void)
{
    InterleavedPWM_t pwm;
    uint32_t i;
    uint32_t step;

    printf("Interleaved PWM Modulation Demo\n");
    printf("Multi-phase interleaving for ripple cancellation\n\n");

    InterleavedPWM_Init(&pwm, PWM_PERIOD, PWM_PHASES);

    for (i = 0; i < PWM_PHASES; i++) {
        InterleavedPWM_SetDuty(&pwm, i, 300);
    }

    printf("Initial state:\n");
    InterleavedPWM_PrintStatus(&pwm);

    printf("\nSimulating 20 PWM steps...\n");
    for (step = 0; step < 20; step++) {
        InterleavedPWM_Update(&pwm);
        printf("Step %2u: ", step);
        for (i = 0; i < PWM_PHASES; i++) {
            printf("P%u=%u ", i, InterleavedPWM_GetOutput(&pwm, i));
        }
        printf("\n");
    }

    printf("\nFinal state:\n");
    InterleavedPWM_PrintStatus(&pwm);

    printf("\nChanging duty to 500 for all phases...\n");
    for (i = 0; i < PWM_PHASES; i++) {
        InterleavedPWM_SetDuty(&pwm, i, 500);
    }
    InterleavedPWM_PrintStatus(&pwm);

    printf("\nChanging duty to 700 for all phases...\n");
    for (i = 0; i < PWM_PHASES; i++) {
        InterleavedPWM_SetDuty(&pwm, i, 700);
    }
    InterleavedPWM_PrintStatus(&pwm);

    printf("\nDone.\n");
    return 0;
}
