#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t g_pwm_period_reg   = 0;
static volatile uint32_t g_pwm_cmpa_reg     = 0;
static volatile uint32_t g_pwm_cmpb_reg     = 0;
static volatile uint32_t g_pwm_deadtime_reg = 0;
static volatile uint32_t g_pwm_ctrl_reg     = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_CMPA_REG        (g_pwm_cmpa_reg)
#define PWM_CMPB_REG        (g_pwm_cmpb_reg)
#define PWM_DEADTIME_REG    (g_pwm_deadtime_reg)
#define PWM_CTRL_REG        (g_pwm_ctrl_reg)

#define PWM_CTRL_ENABLE     (1U << 0)
#define PWM_CTRL_UPDATE     (1U << 1)

/* 系统时钟与PWM参数 */
#define SYS_CLK_HZ          100000000U   /* 100 MHz */
#define PWM_FREQ_HZ         100000U      /* 100 kHz */
#define PWM_PERIOD_TICKS    (SYS_CLK_HZ / PWM_FREQ_HZ)
#define DEADTIME_NS         200U
#define DEADTIME_TICKS      ((SYS_CLK_HZ / 1000000U) * DEADTIME_NS / 1000U)

/* 移相角限制 */
#define PHASE_MIN_DEG       5.0f
#define PHASE_MAX_DEG       175.0f

/* ================= 移相PWM控制结构体 ================= */
typedef struct {
    float phase_deg;
    float phase_rad;
    uint32_t period_ticks;
    uint32_t cmp_a_ticks;
    uint32_t cmp_b_ticks;
    uint32_t deadtime_ticks;
} PhaseShiftPWM_t;

/* ================= 初始化PWM外设 ================= */
static void PWM_Init(void)
{
    PWM_PERIOD_REG   = PWM_PERIOD_TICKS - 1U;
    PWM_DEADTIME_REG = DEADTIME_TICKS;
    PWM_CMPA_REG     = 0U;
    PWM_CMPB_REG     = 0U;
    PWM_CTRL_REG     = PWM_CTRL_ENABLE;
}

/* ================= 角度转弧度 ================= */
static float DegToRad(float deg)
{
    return deg * 3.14159265358979323846f / 180.0f;
}

/* ================= 限幅函数 ================= */
static float ClampFloat(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

/* ================= 移相PWM计算与更新 ================= */
static void PhaseShiftPWM_Update(PhaseShiftPWM_t *pwm, float phase_deg)
{
    uint32_t half_period;
    uint32_t phase_ticks;

    if (pwm == NULL) {
        return;
    }

    /* 1. 限幅移相角 */
    pwm->phase_deg = ClampFloat(phase_deg, PHASE_MIN_DEG, PHASE_MAX_DEG);
    pwm->phase_rad = DegToRad(pwm->phase_deg);

    /* 2. 计算半周期计数值 */
    half_period = (PWM_PERIOD_TICKS - 1U) / 2U;

    /* 3. 计算移相对应的计数值 */
    phase_ticks = (uint32_t)((float)half_period * (pwm->phase_deg / 180.0f));

    /* 4. 超前桥臂：固定50%占空比 */
    pwm->cmp_a_ticks = half_period;

    /* 5. 滞后桥臂：比较值 = 半周期 + 移相计数值 */
    pwm->cmp_b_ticks = half_period + phase_ticks;

    /* 6. 边界保护 */
    if (pwm->cmp_b_ticks >= PWM_PERIOD_TICKS) {
        pwm->cmp_b_ticks = PWM_PERIOD_TICKS - 1U;
    }

    /* 7. 写入硬件寄存器 */
    PWM_CMPA_REG = pwm->cmp_a_ticks;
    PWM_CMPB_REG = pwm->cmp_b_ticks;
    PWM_CTRL_REG |= PWM_CTRL_UPDATE;
}

/* ================= 软开关条件检查 ================= */
static int SoftSwitching_Check(const PhaseShiftPWM_t *pwm, float load_current)
{
    if (pwm == NULL) {
        return 0;
    }
    if (pwm->phase_deg < PHASE_MIN_DEG) {
        return 0;
    }
    if (load_current < 0.1f) {
        return 0;
    }
    return 1;
}

/* ================= 主函数 ================= */
int main(void)
{
    PhaseShiftPWM_t pwm;
    float test_phase_angles[] = {0.0f, 5.0f, 45.0f, 90.0f, 135.0f, 175.0f, 180.0f};
    int i;
    int num_tests = (int)(sizeof(test_phase_angles) / sizeof(test_phase_angles[0]));

    printf("========================================\n");
    printf("  Phase-Shift PWM for Full-Bridge Converter\n");
    printf("  Soft-Switching Control Algorithm\n");
    printf("========================================\n\n");

    printf("System Clock : %u Hz\n", (unsigned)SYS_CLK_HZ);
    printf("PWM Frequency: %u Hz\n", (unsigned)PWM_FREQ_HZ);
    printf("PWM Period   : %u ticks\n", (unsigned)PWM_PERIOD_TICKS);
    printf("Deadtime     : %u ticks (%u ns)\n\n", (unsigned)DEADTIME_TICKS, (unsigned)DEADTIME_NS);

    /* 初始化PWM */
    PWM_Init();
    printf("[PWM Init] Period Reg = %u, Deadtime Reg = %u\n\n",
           (unsigned)PWM_PERIOD_REG, (unsigned)PWM_DEADTIME_REG);

    /* 初始化结构体 */
    pwm.phase_deg      = 0.0f;
    pwm.phase_rad      = 0.0f;
    pwm.period_ticks   = PWM_PERIOD_TICKS;
    pwm.cmp_a_ticks    = 0U;
    pwm.cmp_b_ticks    = 0U;
    pwm.deadtime_ticks = DEADTIME_TICKS;

    /* 遍历测试移相角 */
    for (i = 0; i < num_tests; i++) {
        float phase = test_phase_angles[i];
        int zvs_ok;

        printf("--- Test %d: Phase = %.1f deg ---\n", i + 1, (double)phase);

        PhaseShiftPWM_Update(&pwm, phase);

        printf("  Clamped Phase : %.2f deg (%.4f rad)\n",
               (double)pwm.phase_deg, (double)pwm.phase_rad);
        printf("  CMPA (Lead)   : %u ticks\n", (unsigned)pwm.cmp_a_ticks);
        printf("  CMPB (Lag)    : %u ticks\n", (unsigned)pwm.cmp_b_ticks);
        printf("  Duty Lead     : %.2f%%\n",
               100.0 * (double)pwm.cmp_a_ticks / (double)PWM_PERIOD_TICKS);
        printf("  Duty Lag      : %.2f%%\n",
               100.0 * (double)pwm.cmp_b_ticks / (double)PWM_PERIOD_TICKS);

        /* 软开关检查 */
        zvs_ok = SoftSwitching_Check(&pwm, 1.0f);
        printf("  ZVS Condition : %s\n", zvs_ok ? "SATISFIED" : "NOT MET");
        printf("\n");
    }

    printf("========================================\n");
    printf("  Phase-Shift PWM Test Complete\n");
    printf("========================================\n");

    return 0;
}
