/* 同步配置位定义 */
#define SYNC_CFG_PHASE_ALIGN    (1U << 0)
#define SYNC_CFG_COUNT_ALIGN    (1U << 1)
#define SYNC_CFG_EDGE_RISING    (1U << 2)
#define SYNC_CFG_EDGE_FALLING   (1U << 3)
#define SYNC_CFG_MASTER_OUT_EN  (1U << 4)
#define SYNC_CFG_SLAVE_IN_EN    (1U << 5)

/* 多模块同步最大数量 */
#define MAX_SYNC_MODULES        8U

/* 同步超时计数 */
#define SYNC_TIMEOUT_COUNT      100000U

/* ================= 数据结构定义 ================= */
typedef enum {
    SYNC_MODE_MASTER = 0,
    SYNC_MODE_SLAVE,
    SYNC_MODE_CASCADE
} SyncMode_t;

typedef enum {
    SYNC_TRIG_SOFTWARE = 0,
    SYNC_TRIG_HARDWARE
} SyncTrigSource_t;

typedef enum {
    SYNC_STATE_IDLE = 0,
    SYNC_STATE_WAIT_TRIG,
    SYNC_STATE_SYNCING,
    SYNC_STATE_SYNCED,
    SYNC_STATE_ERROR
} SyncState_t;

typedef struct {
    uint32_t module_id;
    SyncMode_t mode;
    SyncTrigSource_t trig_source;
    uint32_t pwm_period;
    uint32_t phase_offset;
    bool phase_align_en;
    bool count_align_en;
    bool master_out_en;
    bool slave_in_en;
} SyncModuleConfig_t;

typedef struct {
    SyncState_t state;
    uint32_t sync_counter;
    uint32_t sync_error_count;
    uint32_t last_sync_time;
    bool sync_flag;
} SyncModuleStatus_t;

typedef struct {
    SyncModuleConfig_t config;
    SyncModuleStatus_t status;
} SyncModule_t;

/* ================= 全局变量 ================= */
static SyncModule_t g_sync_modules[MAX_SYNC_MODULES];
static uint32_t g_sync_module_count = 0U;
static uint32_t g_global_sync_counter = 0U;
static bool g_sync_initialized = false;

/* ================= 函数声明 ================= */
static void pwm_sync_hw_init(void);
static void pwm_sync_hw_enable(bool enable);
static void pwm_sync_hw_set_master(void);
static void pwm_sync_hw_set_slave(void);
static void pwm_sync_hw_trigger(void);
static void pwm_sync_hw_set_period(uint32_t period);
static void pwm_sync_hw_set_phase(uint32_t phase);
static bool pwm_sync_hw_is_synced(void);
static bool pwm_sync_hw_is_busy(void);
static bool pwm_sync_hw_has_error(void);
static void pwm_sync_hw_clear_error(void);
static uint32_t pwm_sync_hw_get_counter(void);

static void pwm_sync_module_init(uint32_t module_id, SyncMode_t mode,
                                 SyncTrigSource_t trig_source,
                                 uint32_t period, uint32_t phase);
static void pwm_sync_module_start(uint32_t module_id);
static void pwm_sync_module_stop(uint32_t module_id);
static bool pwm_sync_module_wait_sync(uint32_t module_id, uint32_t timeout);
static void pwm_sync_module_update_status(uint32_t module_id);
static void pwm_sync_global_trigger(void);
static void pwm_sync_all_modules(void);
static void pwm_sync_print_status(void);

/* ================= 硬件抽象层实现 ================= */
static void pwm_sync_hw_init(void)
{
    PWM_SYNC_CTRL = 0U;
    PWM_SYNC_CFG = 0U;
    PWM_SYNC_STATUS = 0U;
    PWM_SYNC_COUNTER = 0U;
    PWM_SYNC_PERIOD = 0U;
    PWM_SYNC_PHASE = 0U;
}

static void pwm_sync_hw_enable(bool enable)
{
    if (enable) {
        PWM_SYNC_CTRL |= SYNC_CTRL_ENABLE;
    } else {
        PWM_SYNC_CTRL &= ~SYNC_CTRL_ENABLE;
    }
}

static void pwm_sync_hw_set_master(void)
{
    PWM_SYNC_CTRL |= SYNC_CTRL_MASTER;
    PWM_SYNC_CTRL &= ~SYNC_CTRL_SLAVE;
}

static void pwm_sync_hw_set_slave(void)
{
    PWM_SYNC_CTRL |= SYNC_CTRL_SLAVE;
    PWM_SYNC_CTRL &= ~SYNC_CTRL_MASTER;
}

static void pwm_sync_hw_trigger(void)
{
    PWM_SYNC_CTRL |= SYNC_CTRL_SW_TRIG;
    PWM_SYNC_CTRL &= ~SYNC_CTRL_SW_TRIG;
    PWM_SYNC_STATUS |= SYNC_STATUS_SYNCED;
    PWM_SYNC_STATUS &= ~SYNC_STATUS_BUSY;
    PWM_SYNC_COUNTER++;
}

static void pwm_sync_hw_set_period(uint32_t period)
{
    PWM_SYNC_PERIOD = period;
}

static void pwm_sync_hw_set_phase(uint32_t phase)
{
    PWM_SYNC_PHASE = phase;
}

static bool pwm_sync_hw_is_synced(void)
{
    return (PWM_SYNC_STATUS & SYNC_STATUS_SYNCED) != 0U;
}

static bool pwm_sync_hw_is_busy(void)
{
    return (PWM_SYNC_STATUS & SYNC_STATUS_BUSY) != 0U;
}

static bool pwm_sync_hw_has_error(void)
{
    return (PWM_SYNC_STATUS & SYNC_STATUS_ERR) != 0U;
}

static void pwm_sync_hw_clear_error(void)
{
    PWM_SYNC_STATUS &= ~SYNC_STATUS_ERR;
}

static uint32_t pwm_sync_hw_get_counter(void)
{
    return PWM_SYNC_COUNTER;
}

/* ================= 模块管理实现 ================= */
static void pwm_sync_module_init(uint32_t module_id, SyncMode_t mode,
                                 SyncTrigSource_t trig_source,
                                 uint32_t period, uint32_t phase)
{
    SyncModule_t *mod;

    if (module_id >= MAX_SYNC_MODULES) {
        return;
    }

    mod = &g_sync_modules[module_id];
    mod->config.module_id = module_id;
    mod->config.mode = mode;
    mod->config.trig_source = trig_source;
    mod->config.pwm_period = period;
    mod->config.phase_offset = phase;
    mod->config.phase_align_en = true;
    mod->config.count_align_en = true;
    mod->config.master_out_en = (mode == SYNC_MODE_MASTER);
    mod->config.slave_in_en = (mode == SYNC_MODE_SLAVE);

    mod->status.state = SYNC_STATE_IDLE;
    mod->status.sync_counter = 0U;
    mod->status.sync_error_count = 0U;
    mod->status.last_sync_time = 0U;
    mod->status.sync_flag = false;

    if (module_id >= g_sync_module_count) {
        g_sync_module_count = module_id + 1U;
    }
}

static void pwm_sync_module_start(uint32_t module_id)
{
    SyncModule_t *mod;

    if (module_id >= g_sync_module_count) {
        return;
    }

    mod = &g_sync_modules[module_id];

    pwm_sync_hw_enable(true);
    pwm_sync_hw_set_period(mod->config.pwm_period);
    pwm_sync_hw_set_phase(mod->config.phase_offset);

    if (mod->config.mode == SYNC_MODE_MASTER) {
        pwm_sync_hw_set_master();
        PWM_SYNC_CFG |= SYNC_CFG_MASTER_OUT_EN;
        PWM_SYNC_CFG &= ~SYNC_CFG_SLAVE_IN_EN;
    } else {
        pwm_sync_hw_set_slave();
        PWM_SYNC_CFG |= SYNC_CFG_SLAVE_IN_EN;
        PWM_SYNC_CFG &= ~SYNC_CFG_MASTER_OUT_EN;
    }

    if (mod->config.phase_align_en) {
        PWM_SYNC_CFG |= SYNC_CFG_PHASE_ALIGN;
    }
    if (mod->config.count_align_en) {
        PWM_SYNC_CFG |= SYNC_CFG_COUNT_ALIGN;
    }

    mod->status.state = SYNC_STATE_WAIT_TRIG;
}

static void pwm_sync_module_stop(uint32_t module_id)
{
    SyncModule_t *mod;

    if (module_id >= g_sync_module_count) {
        return;
    }

    mod = &g_sync_modules[module_id];
    mod->status.state = SYNC_STATE_IDLE;
    pwm_sync_hw_enable(false);
}

static bool pwm_sync_module_wait_sync(uint32_t module_id, uint32_t timeout)
{
    SyncModule_t *mod;
    uint32_t wait_count = 0U;

    if (module_id >= g_sync_module_count) {
        return false;
    }

    mod = &g_sync_modules[module_id];
    mod->status.state = SYNC_STATE_SYNCING;

    while (wait_count < timeout) {
        if (pwm_sync_hw_is_synced()) {
            mod->status.state = SYNC_STATE_SYNCED;
            mod->status.sync_flag = true;
            mod->status.sync_counter++;
            mod->status.last_sync_time = g_global_sync_counter;
            return true;
        }

        if (pwm_sync_hw_has_error()) {
            mod->status.state = SYNC_STATE_ERROR;
            mod->status.sync_error_count++;
            pwm_sync_hw_clear_error();
            return false;
        }

        wait_count++;
    }

    mod->status.state = SYNC_STATE_ERROR;
    mod->status.sync_error_count++;
    return false;
}

static void pwm_sync_module_update_status(uint32_t module_id)
{
    SyncModule_t *mod;

    if (module_id >= g_sync_module_count) {
        return;
    }

    mod = &g_sync_modules[module_id];

    if (pwm_sync_hw_is_synced()) {
        mod->status.state = SYNC_STATE_SYNCED;
        mod->status.sync_flag = true;
    } else if (pwm_sync_hw_has_error()) {
        mod->status.state = SYNC_STATE_ERROR;
        mod->status.sync_error_count++;
        pwm_sync_hw_clear_error();
    } else if (pwm_sync_hw_is_busy()) {
        mod->status.state = SYNC_STATE_SYNCING;
    } else {
        mod->status.state = SYNC_STATE_WAIT_TRIG;
    }
}

/* ================= 同步控制实现 ================= */
static void pwm_sync_global_trigger(void)
{
    g_global_sync_counter++;
    pwm_sync_hw_trigger();
}

static void pwm_sync_all_modules(void)
{
    uint32_t i;

    for (i = 0U; i < g_sync_module_count; i++) {
        if (g_sync_modules[i].config.mode == SYNC_MODE_MASTER) {
            pwm_sync_module_start(i);
        }
    }

    pwm_sync_global_trigger();

    for (i = 0U; i < g_sync_module_count; i++) {
        if (g_sync_modules[i].config.mode == SYNC_MODE_SLAVE) {
            pwm_sync_module_start(i);
            (void)pwm_sync_module_wait_sync(i, SYNC_TIMEOUT_COUNT);
        }
    }

    for (i = 0U; i < g_sync_module_count; i++) {
        pwm_sync_module_update_status(i);
    }
}

static void pwm_sync_print_status(void)
{
    uint32_t i;

    printf("========== PWM Sync Status ==========\n");
    printf("Global Sync Counter: %u\n", g_global_sync_counter);
    printf("HW Counter: %u\n", pwm_sync_hw_get_counter());
    printf("Module Count: %u\n", g_sync_module_count);
    printf("-------------------------------------\n");

    for (i = 0U; i < g_sync_module_count; i++) {
        SyncModule_t *mod = &g_sync_modules[i];
        const char *mode_str;
        const char *state_str;

        switch (mod->config.mode) {
            case SYNC_MODE_MASTER:  mode_str = "MASTER";  break;
            case SYNC_MODE_SLAVE:   mode_str = "SLAVE";   break;
            case SYNC_MODE_CASCADE: mode_str = "CASCADE"; break;
            default:                mode_str = "UNKNOWN"; break;
        }

        switch (mod->status.state) {
            case SYNC_STATE_IDLE:      state_str = "IDLE";      break;
            case SYNC_STATE_WAIT_TRIG: state_str = "WAIT_TRIG"; break;
            case SYNC_STATE_SYNCING:   state_str = "SYNCING";   break;
            case SYNC_STATE_SYNCED:    state_str = "SYNCED";    break;
            case SYNC_STATE_ERROR:     state_str = "ERROR";     break;
            default:                   state_str = "UNKNOWN";   break;
        }

        printf("Module[%u]: Mode=%-7s State=%-9s SyncCnt=%u ErrCnt=%u Period=%u Phase=%u\n",
               mod->config.module_id,
               mode_str,
               state_str,
               mod->status.sync_counter,
               mod->status.sync_error_count,
               mod->config.pwm_period,
               mod->config.phase_offset);
    }

    printf("=====================================\n\n");
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t i;

    printf("PWM Synchronization Signal Generation - Multi-Module Sync\n");
    printf("==========================================================\n\n");

    pwm_sync_hw_init();
    g_sync_initialized = true;

    pwm_sync_module_init(0U, SYNC_MODE_MASTER, SYNC_TRIG_SOFTWARE, 1000U, 0U);
    pwm_sync_module_init(1U, SYNC_MODE_SLAVE,  SYNC_TRIG_HARDWARE, 1000U, 0U);
    pwm_sync_module_init(2U, SYNC_MODE_SLAVE,  SYNC_TRIG_HARDWARE, 1000U, 250U);
    pwm_sync_module_init(3U, SYNC_MODE_SLAVE,  SYNC_TRIG_HARDWARE, 1000U, 500U);

    printf("Initialized %u sync modules\n\n", g_sync_module_count);

    pwm_sync_print_status();

    printf(">>> Executing multi-module synchronization...\n\n");
    pwm_sync_all_modules();

    pwm_sync_print_status();

    for (i = 0U; i < 3U; i++) {
        uint32_t j;
        printf(">>> Sync cycle %u\n", i + 1U);
        pwm_sync_global_trigger();

        for (j = 0U; j < g_sync_module_count; j++) {
            pwm_sync_module_update_status(j);
        }
    }

    printf("\n");
    pwm_sync_print_status();

    for (i = 0U; i < g_sync_module_count; i++) {
        pwm_sync_module_stop(i);
    }

    printf("All modules stopped.\n");
    printf("PWM Sync test completed successfully.\n");

    return 0;
}
