#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t mock_timer_cr1  = 0;
static volatile uint32_t mock_timer_sr   = 0;
static volatile uint32_t mock_timer_cnt  = 0;
static volatile uint32_t mock_timer_arr  = 0xFFFF;
static volatile uint32_t mock_timer_ccr1 = 0;
static volatile uint32_t mock_timer_ccer = 0;

#define PWM_TIMER_CR1       (mock_timer_cr1)
#define PWM_TIMER_SR        (mock_timer_sr)
#define PWM_TIMER_CNT       (mock_timer_cnt)
#define PWM_TIMER_ARR       (mock_timer_arr)
#define PWM_TIMER_CCR1      (mock_timer_ccr1)
#define PWM_TIMER_CCER      (mock_timer_ccer)

#define PWM_TIMER_CR1_CEN   (1U << 0)
#define PWM_TIMER_SR_UIF    (1U << 0)
#define PWM_TIMER_SR_CC1IF  (1U << 1)
#define PWM_TIMER_CCER_CC1E (1U << 0)

/* 模拟的 PWM 捕获/比较中断标志位 */
static volatile uint32_t g_pwm_capture_flag = 0;
static volatile uint32_t g_pwm_capture_value = 0;

/* ================= PWM 脉冲丢失检测算法 ================= */

/* 检测状态枚举 */
typedef enum {
    PWM_STATE_NORMAL = 0,
    PWM_STATE_WARNING,
    PWM_STATE_FAULT
} PwmDiagState_t;

/* 诊断配置参数 */
typedef struct {
    uint32_t expected_period;      /* 期望的 PWM 周期（定时器计数） */
    uint32_t period_tolerance;     /* 周期允许偏差 */
    uint32_t missing_threshold;    /* 连续丢失多少个脉冲判定为故障 */
    uint32_t warning_threshold;    /* 连续丢失多少个脉冲判定为警告 */
} PwmDiagConfig_t;

/* 诊断运行时数据 */
typedef struct {
    PwmDiagConfig_t cfg;
    PwmDiagState_t  state;
    uint32_t        last_capture;
    uint32_t        current_capture;
    uint32_t        period;
    uint32_t        missing_count;      /* 连续丢失脉冲计数 */
    uint32_t        total_missing;      /* 累计丢失脉冲数 */
    uint32_t        total_pulses;       /* 累计检测脉冲数 */
    bool            first_capture;      /* 首次捕获标志 */
} PwmDiagHandle_t;

/* 初始化诊断模块 */
static void pwm_diag_init(PwmDiagHandle_t *h, const PwmDiagConfig_t *cfg)
{
    h->cfg = *cfg;
    h->state = PWM_STATE_NORMAL;
    h->last_capture = 0;
    h->current_capture = 0;
    h->period = 0;
    h->missing_count = 0;
    h->total_missing = 0;
    h->total_pulses = 0;
    h->first_capture = true;
}

/* 计算两个捕获值之间的周期（考虑计数器溢出） */
static uint32_t pwm_diag_calc_period(uint32_t prev, uint32_t curr, uint32_t arr)
{
    if (curr >= prev) {
        return curr - prev;
    } else {
        return (arr - prev) + curr + 1U;
    }
}

/* 判断周期是否在允许范围内 */
static bool pwm_diag_period_valid(const PwmDiagHandle_t *h, uint32_t period)
{
    uint32_t expected = h->cfg.expected_period;
    uint32_t tol = h->cfg.period_tolerance;

    if (period >= (expected - tol) && period <= (expected + tol)) {
        return true;
    }
    return false;
}

/* 核心诊断处理：每次捕获中断调用一次 */
static void pwm_diag_process_capture(PwmDiagHandle_t *h, uint32_t capture_value)
{
    uint32_t arr = PWM_TIMER_ARR;

    h->total_pulses++;

    if (h->first_capture) {
        h->last_capture = capture_value;
        h->first_capture = false;
        h->missing_count = 0;
        return;
    }

    h->current_capture = capture_value;
    h->period = pwm_diag_calc_period(h->last_capture, h->current_capture, arr);
    h->last_capture = h->current_capture;

    if (pwm_diag_period_valid(h, h->period)) {
        h->missing_count = 0;
        if (h->state != PWM_STATE_NORMAL) {
            h->state = PWM_STATE_NORMAL;
            printf("[PWM_DIAG] State -> NORMAL (period=%lu)\n",
                   (unsigned long)h->period);
        }
    } else {
        uint32_t expected = h->cfg.expected_period;
        uint32_t lost = 0;

        if (expected > 0 && h->period > expected) {
            lost = (h->period / expected) - 1U;
        }

        if (lost == 0) {
            lost = 1;
        }

        h->missing_count += lost;
        h->total_missing += lost;

        printf("[PWM_DIAG] Pulse missing detected! period=%lu, lost=%lu, "
               "missing_count=%lu\n",
               (unsigned long)h->period,
               (unsigned long)lost,
               (unsigned long)h->missing_count);

        if (h->missing_count >= h->cfg.missing_threshold) {
            if (h->state != PWM_STATE_FAULT) {
                h->state = PWM_STATE_FAULT;
                printf("[PWM_DIAG] State -> FAULT (missing_count=%lu)\n",
                       (unsigned long)h->missing_count);
            }
        } else if (h->missing_count >= h->cfg.warning_threshold) {
            if (h->state != PWM_STATE_FAULT) {
                h->state = PWM_STATE_WARNING;
                printf("[PWM_DIAG] State -> WARNING (missing_count=%lu)\n",
                       (unsigned long)h->missing_count);
            }
        }
    }
}

/* 超时检测 */
static void pwm_diag_check_timeout(PwmDiagHandle_t *h, uint32_t current_cnt)
{
    uint32_t arr = PWM_TIMER_ARR;
    uint32_t elapsed;

    if (h->first_capture) {
        return;
    }

    if (current_cnt >= h->last_capture) {
        elapsed = current_cnt - h->last_capture;
    } else {
        elapsed = (arr - h->last_capture) + current_cnt + 1U;
    }

    if (elapsed > (h->cfg.expected_period * 2U)) {
        h->missing_count++;
        h->total_missing++;
        h->last_capture = current_cnt;

        printf("[PWM_DIAG] Timeout! elapsed=%lu, missing_count=%lu\n",
               (unsigned long)elapsed,
               (unsigned long)h->missing_count);

        if (h->missing_count >= h->cfg.missing_threshold) {
            if (h->state != PWM_STATE_FAULT) {
                h->state = PWM_STATE_FAULT;
                printf("[PWM_DIAG] State -> FAULT (timeout)\n");
            }
        } else if (h->missing_count >= h->cfg.warning_threshold) {
            if (h->state != PWM_STATE_FAULT) {
                h->state = PWM_STATE_WARNING;
                printf("[PWM_DIAG] State -> WARNING (timeout)\n");
            }
        }
    }
}

/* 打印诊断统计信息 */
static void pwm_diag_print_stats(const PwmDiagHandle_t *h)
{
    printf("===== PWM Diagnostic Statistics =====\n");
    printf("  State          : %s\n",
           h->state == PWM_STATE_NORMAL  ? "NORMAL"  :
           h->state == PWM_STATE_WARNING ? "WARNING" : "FAULT");
    printf("  Total pulses   : %lu\n", (unsigned long)h->total_pulses);
    printf("  Total missing  : %lu\n", (unsigned long)h->total_missing);
    printf("  Missing count  : %lu\n", (unsigned long)h->missing_count);
    printf("  Last period    : %lu\n", (unsigned long)h->period);
    printf("=====================================\n");
}

/* ================= 测试辅助函数 ================= */

static void simulate_capture(PwmDiagHandle_t *h, uint32_t capture_value)
{
    g_pwm_capture_value = capture_value;
    g_pwm_capture_flag = 1;
    pwm_diag_process_capture(h, capture_value);
    g_pwm_capture_flag = 0;
}

/* ================= main 函数 ================= */
int main(void)
{
    PwmDiagHandle_t diag;
    PwmDiagConfig_t cfg;

    cfg.expected_period = 1000;
    cfg.period_tolerance = 50;
    cfg.missing_threshold = 5;
    cfg.warning_threshold = 2;

    PWM_TIMER_ARR = 0xFFFF;
    PWM_TIMER_CR1 = PWM_TIMER_CR1_CEN;
    PWM_TIMER_CCER = PWM_TIMER_CCER_CC1E;

    pwm_diag_init(&diag, &cfg);

    printf("===== PWM Pulse Loss Detection Test =====\n\n");

    printf("--- Scenario 1: Normal PWM pulses ---\n");
    simulate_capture(&diag, 0);
    simulate_capture(&diag, 1000);
    simulate_capture(&diag, 2000);
    simulate_capture(&diag, 3000);
    simulate_capture(&diag, 4000);
    pwm_diag_print_stats(&diag);

    printf("\n--- Scenario 2: One pulse missing ---\n");
    simulate_capture(&diag, 6000);
    pwm_diag_print_stats(&diag);

    printf("\n--- Scenario 3: Consecutive missing -> WARNING ---\n");
    simulate_capture(&diag, 9000);
    pwm_diag_print_stats(&diag);

    printf("\n--- Scenario 4: Continue missing -> FAULT ---\n");
    simulate_capture(&diag, 13000);
    simulate_capture(&diag, 18000);
    pwm_diag_print_stats(&diag);

    printf("\n--- Scenario 5: Recovery to NORMAL ---\n");
    simulate_capture(&diag, 19000);
    simulate_capture(&diag, 20000);
    pwm_diag_print_stats(&diag);

    printf("\n--- Scenario 6: Timeout detection ---\n");
    pwm_diag_check_timeout(&diag, 25000);
    pwm_diag_print_stats(&diag);

    printf("\n===== Test Complete =====\n");
    return 0;
}
