#include <stdio.h>
#include <stdint.h>
#include <math.h>

#define PDM_TABLE_SIZE 256
#define PDM_OUTPUT_BITS 8

typedef struct {
    uint32_t accumulator;
    uint32_t step;
    uint32_t density;
    uint32_t output;
    uint32_t sample_count;
} PDM_Handle;

static uint8_t pdm_lut[PDM_TABLE_SIZE];

static void PDM_InitLUT(void)
{
    for (uint32_t i = 0; i < PDM_TABLE_SIZE; i++) {
        double phase = (double)i / (double)PDM_TABLE_SIZE;
        double val = 0.5 + 0.5 * sin(2.0 * M_PI * phase);
        pdm_lut[i] = (uint8_t)(val * 255.0);
    }
}

static void PDM_Init(PDM_Handle *h, uint32_t step)
{
    h->accumulator = 0;
    h->step = step;
    h->density = 0;
    h->output = 0;
    h->sample_count = 0;
}

static uint32_t PDM_Update(PDM_Handle *h)
{
    h->accumulator += h->step;
    if (h->accumulator >= PDM_TABLE_SIZE) {
        h->accumulator -= PDM_TABLE_SIZE;
    }

    uint32_t idx = h->accumulator;
    uint32_t target = pdm_lut[idx];

    h->density = target;

    uint32_t bit_out = 0;
    static uint32_t bit_acc = 0;
    static uint32_t bit_cnt = 0;

    bit_acc += h->density;
    if (bit_acc >= 256) {
        bit_acc -= 256;
        bit_out = 1;
    }

    h->output = bit_out;
    h->sample_count++;

    return bit_out;
}

static double PDM_GetDensity(const PDM_Handle *h)
{
    return (double)h->density / 255.0;
}

int main(void)
{
    PDM_InitLUT();

    PDM_Handle pdm;
    PDM_Init(&pdm, 3);

    printf("PDM Low-Harmonic High-Frequency Control Test\n");
    printf("=============================================\n");
    printf("Step: %u, Table Size: %d, Output Bits: %d\n\n",
           pdm.step, PDM_TABLE_SIZE, PDM_OUTPUT_BITS);

    printf("Sample | Acc | Density | Output | Density(%%)\n");
    printf("-------|-----|---------|--------|----------\n");

    for (int i = 0; i < 32; i++) {
        uint32_t out = PDM_Update(&pdm);
        printf("%6d | %3u | %7u | %6u | %8.2f\n",
               i, pdm.accumulator, pdm.density, out,
               PDM_GetDensity(&pdm) * 100.0);
    }

    printf("\n--- Harmonic Analysis (simplified) ---\n");

    double sum = 0.0;
    double sum_sq = 0.0;
    int n = 1000;

    PDM_Init(&pdm, 7);

    for (int i = 0; i < n; i++) {
        uint32_t out = PDM_Update(&pdm);
        sum += out;
        sum_sq += out * out;
    }

    double mean = sum / n;
    double variance = (sum_sq / n) - (mean * mean);
    double std_dev = sqrt(variance);

    printf("Mean: %.4f\n", mean);
    printf("Variance: %.4f\n", variance);
    printf("Std Dev: %.4f\n", std_dev);
    printf("Density range: 0.0 - 1.0\n");
    printf("PDM output is 1-bit stream, density represents analog value\n");

    printf("\n--- Multi-rate PDM test ---\n");

    uint32_t steps[] = {1, 3, 7, 15, 31, 63, 127};
    int num_steps = sizeof(steps) / sizeof(steps[0]);

    for (int s = 0; s < num_steps; s++) {
        PDM_Init(&pdm, steps[s]);
        double avg = 0.0;
        int cnt = 500;

        for (int i = 0; i < cnt; i++) {
            avg += PDM_Update(&pdm);
        }
        avg /= cnt;

        printf("Step %3u: avg output = %.4f, density = %.4f\n",
               steps[s], avg, PDM_GetDensity(&pdm));
    }

    printf("\nPDM test completed successfully.\n");

    return 0;
}
