#include <stdio.h>
#include <stdint.h>

/* ============================================================
 * Mock 硬件寄存器定义 (替代单片机特定头文件)
 * ============================================================ */

/* 使用静态数组模拟寄存器内存, 避免直接访问非法地址导致段错误 */
static uint32_t g_tim1_regs[32];

/* 寄存器索引 */
#define TIM_CR1_IDX            0
#define TIM_CCMR1_IDX          1
#define TIM_CCER_IDX           2
#define TIM_BDTR_IDX           3
#define TIM_PSC_IDX            4
#define TIM_ARR_IDX            5
#define TIM_CCR1_IDX           6
#define TIM_CCR2_IDX           7

#define TIM1_CR1               (g_tim1_regs[TIM_CR1_IDX])
#define TIM1_CCMR1             (g_tim1_regs[TIM_CCMR1_IDX])
#define TIM1_CCER              (g_tim1_regs[TIM_CCER_IDX])
#define TIM1_BDTR              (g_tim1_regs[TIM_BDTR_IDX])
#define TIM1_PSC               (g_tim1_regs[TIM_PSC_IDX])
#define TIM1_ARR               (g_tim1_regs[TIM_ARR_IDX])
#define TIM1_CCR1              (g_tim1_regs[TIM_CCR1_IDX])
#define TIM1_CCR2              (g_tim1_regs[TIM_CCR2_IDX])

/* CR1 位定义 */
#define TIM_CR1_CEN            (1U << 0)
#define TIM_CR1_ARPE           (1U << 7)

/* CCMR1 位定义 (通道1 PWM模式1, 通道2 PWM模式1) */
#define TIM_CCMR1_OC1M_PWM1    (6U << 4)
#define TIM_CCMR1_OC1PE        (1U << 3)
#define TIM_CCMR1_OC2M_PWM1    (6U << 12)
#define TIM_CCMR1_OC2PE        (1U << 11)

/* CCER 位定义 */
#define TIM_CCER_CC1E          (1U << 0)
#define TIM_CCER_CC1P          (1U << 1)
#define TIM_CCER_CC2E          (1U << 4)
#define TIM_CCER_CC2P          (1U << 5)

/* BDTR 位定义 */
#define TIM_BDTR_DTG_Pos       0U
#define TIM_BDTR_DTG_Msk       (0xFFU << TIM_BDTR_DTG_Pos)
#define TIM_BDTR_LOCK_Pos      8U
#define TIM_BDTR_LOCK_Msk      (0x3U << TIM_BDTR_LOCK_Pos)
#define TIM_BDTR_OSSI          (1U << 10)
#define TIM_BDTR_OSSR          (1U << 11)
#define TIM_BDTR_BKE           (1U << 12)
#define TIM_BDTR_BKP           (1U << 13)
#define TIM_BDTR_AOE           (1U << 14)
#define TIM_BDTR_MOE           (1U << 15)

/* ============================================================
 * 死区时间配置参数
 * ============================================================ */

/* 系统时钟频率 (Hz) */
#define SYSTEM_CLOCK_HZ        72000000UL

/* ============================================================
 * 死区时间配置函数
 * ============================================================ */

/**
 * @brief 计算并配置死区时间寄存器 (DTG[7:0])
 * @param dead_time_ns 期望的死区时间 (纳秒)
 * @param timer_clk_hz 定时器时钟频率 (Hz)
 * @return 实际配置的死区时间 (纳秒), 0 表示配置失败
 */
static uint32_t configure_dead_time(uint32_t dead_time_ns, uint32_t timer_clk_hz)
{
    uint64_t dt_ticks;
    uint32_t dtg_value = 0;
    uint32_t actual_ns = 0;

    if (timer_clk_hz == 0U) {
        return 0U;
    }

    /* 将死区时间转换为定时器时钟周期数 */
    dt_ticks = ((uint64_t)dead_time_ns * (uint64_t)timer_clk_hz) / 1000000000ULL;

    if (dt_ticks == 0U) {
        dt_ticks = 1U; /* 最小 1 个时钟周期 */
    }

    /* 根据 DTG 编码规则选择合适的分段 */
    if (dt_ticks <= 127U) {
        /* 范围 1: DT = DTG[7:0] * t_dts, 最大 127 */
        dtg_value = (uint32_t)dt_ticks;
        actual_ns = (uint32_t)((dt_ticks * 1000000000ULL) / timer_clk_hz);
    } else if (dt_ticks <= (64U + 63U) * 2U) {
        /* 范围 2: DT = (64 + DTG[5:0]) * 2 * t_dts, 最大 254 */
        uint32_t code = (uint32_t)((dt_ticks / 2U) - 64U);
        if (code > 63U) {
            code = 63U;
        }
        dtg_value = (2U << 6) | code; /* DTG[7:5] = 10x */
        actual_ns = (uint32_t)(((64U + code) * 2ULL * 1000000000ULL) / timer_clk_hz);
    } else if (dt_ticks <= (32U + 31U) * 8U) {
        /* 范围 3: DT = (32 + DTG[4:0]) * 8 * t_dts, 最大 504 */
        uint32_t code = (uint32_t)((dt_ticks / 8U) - 32U);
        if (code > 31U) {
            code = 31U;
        }
        dtg_value = (6U << 5) | code; /* DTG[7:5] = 110 */
        actual_ns = (uint32_t)(((32U + code) * 8ULL * 1000000000ULL) / timer_clk_hz);
    } else if (dt_ticks <= (32U + 31U) * 16U) {
        /* 范围 4: DT = (32 + DTG[4:0]) * 16 * t_dts, 最大 1008 */
        uint32_t code = (uint32_t)((dt_ticks / 16U) - 32U);
        if (code > 31U) {
            code = 31U;
        }
        dtg_value = (7U << 5) | code; /* DTG[7:5] = 111 */
        actual_ns = (uint32_t)(((32U + code) * 16ULL * 1000000000ULL) / timer_clk_hz);
    } else {
        /* 超出最大范围, 使用最大值 */
        dtg_value = (7U << 5) | 31U;
        actual_ns = (uint32_t)(((32U + 31U) * 16ULL * 1000000000ULL) / timer_clk_hz);
    }

    /* 写入 BDTR 寄存器, 保留其他位 */
    {
        uint32_t bdtr = TIM1_BDTR;
        bdtr &= ~TIM_BDTR_DTG_Msk;
        bdtr |= (dtg_value << TIM_BDTR_DTG_Pos) & TIM_BDTR_DTG_Msk;
        TIM1_BDTR = bdtr;
    }

    return actual_ns;
}

/* ============================================================
 * PWM 初始化函数
 * ============================================================ */

/**
 * @brief 初始化互补 PWM 输出 (带死区)
 * @param pwm_freq_hz PWM 频率 (Hz)
 * @param dead_time_ns 死区时间 (纳秒)
 * @param duty_percent 占空比 (0-100)
 */
static void pwm_init(uint32_t pwm_freq_hz, uint32_t dead_time_ns, uint32_t duty_percent)
{
    uint32_t timer_clk = SYSTEM_CLOCK_HZ;
    uint32_t arr;
    uint32_t ccr;
    uint32_t actual_dead_ns;

    /* 防止除以零 */
    if (pwm_freq_hz == 0U) {
        pwm_freq_hz = 1U;
    }

    /* 计算 ARR: 使用 PSC=0, 即定时器时钟 = 系统时钟 */
    arr = (timer_clk / pwm_freq_hz);
    if (arr == 0U) {
        arr = 1U;
    }
    arr = arr - 1U;
    if (arr > 0xFFFFU) {
        arr = 0xFFFFU;
    }

    /* 计算占空比对应的 CCR 值 */
    if (duty_percent > 100U) {
        duty_percent = 100U;
    }
    ccr = ((arr + 1U) * duty_percent) / 100U;

    /* 配置预分频和自动重装载 */
    TIM1_PSC = 0U;
    TIM1_ARR = arr;

    /* 配置通道1和通道2为 PWM 模式1 */
    TIM1_CCMR1 = TIM_CCMR1_OC1M_PWM1 | TIM_CCMR1_OC1PE |
                 TIM_CCMR1_OC2M_PWM1 | TIM_CCMR1_OC2PE;

    /* 配置比较值 */
    TIM1_CCR1 = ccr;
    TIM1_CCR2 = ccr;

    /* 使能通道1和通道2输出, 通道1高有效, 通道2高有效 */
    TIM1_CCER = TIM_CCER_CC1E | TIM_CCER_CC2E;

    /* 配置死区时间 */
    actual_dead_ns = configure_dead_time(dead_time_ns, timer_clk);

    /* 使能主输出 (MOE) 和自动输出 (AOE) */
    {
        uint32_t bdtr = TIM1_BDTR;
        bdtr |= TIM_BDTR_MOE | TIM_BDTR_AOE;
        TIM1_BDTR = bdtr;
    }

    /* 使能定时器 */
    TIM1_CR1 |= TIM_CR1_CEN | TIM_CR1_ARPE;

    /* 打印配置结果 */
    printf("========================================\n");
    printf("  PWM Dead-Time Configuration Report\n");
    printf("========================================\n");
    printf("  System Clock     : %lu Hz\n", (unsigned long)SYSTEM_CLOCK_HZ);
    printf("  PWM Frequency    : %lu Hz\n", (unsigned long)pwm_freq_hz);
    printf("  Timer Clock      : %lu Hz\n", (unsigned long)timer_clk);
    printf("  ARR Value        : %lu\n", (unsigned long)arr);
    printf("  CCR Value        : %lu\n", (unsigned long)ccr);
    printf("  Duty Cycle       : %lu %%\n", (unsigned long)duty_percent);
    printf("  Requested DT     : %lu ns\n", (unsigned long)dead_time_ns);
    printf("  Actual DT        : %lu ns\n", (unsigned long)actual_dead_ns);
    printf("  BDTR Register    : 0x%08lX\n", (unsigned long)TIM1_BDTR);
    printf("  DTG[7:0]         : 0x%02lX\n",
           (unsigned long)((TIM1_BDTR & TIM_BDTR_DTG_Msk) >> TIM_BDTR_DTG_Pos));
    printf("  MOE              : %s\n", (TIM1_BDTR & TIM_BDTR_MOE) ? "Enabled" : "Disabled");
    printf("  AOE              : %s\n", (TIM1_BDTR & TIM_BDTR_AOE) ? "Enabled" : "Disabled");
    printf("  CR1 Register     : 0x%08lX\n", (unsigned long)TIM1_CR1);
    printf("  CEN              : %s\n", (TIM1_CR1 & TIM_CR1_CEN) ? "Enabled" : "Disabled");
    printf("========================================\n");
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    printf("\n>>> Test 1: 20kHz PWM, 500ns dead-time, 50%% duty\n\n");
    pwm_init(20000U, 500U, 50U);

    printf("\n>>> Test 2: 50kHz PWM, 200ns dead-time, 75%% duty\n\n");
    pwm_init(50000U, 200U, 75U);

    printf("\n>>> Test 3: 10kHz PWM, 1000ns dead-time, 30%% duty\n\n");
    pwm_init(10000U, 1000U, 30U);

    printf("\n>>> Test 4: 100kHz PWM, 100ns dead-time, 90%% duty\n\n");
    pwm_init(100000U, 100U, 90U);

    printf("\nAll tests completed.\n");
    return 0;
}
