#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== 模拟寄存器与硬件抽象层 ==================== */
/* 使用静态变量模拟寄存器，避免非法指针访问 */
static uint32_t mock_TIM1_CR1;
static uint32_t mock_TIM1_CCMR1;
static uint32_t mock_TIM1_CCER;
static uint32_t mock_TIM1_CNT;
static uint32_t mock_TIM1_ARR;
static uint32_t mock_TIM1_CCR1;
static uint32_t mock_TIM1_BDTR;
static uint32_t mock_TIM1_SR;

static uint32_t mock_GPIOA_MODER;
static uint32_t mock_GPIOA_ODR;

static uint32_t mock_ADC1_CR2;
static uint32_t mock_ADC1_SR;
static uint32_t mock_ADC1_DR;

static uint32_t mock_COMP_CSR;

/* 使用宏定义模拟寄存器访问 */
#define TIM1_CR1        (mock_TIM1_CR1)
#define TIM1_CCMR1      (mock_TIM1_CCMR1)
#define TIM1_CCER       (mock_TIM1_CCER)
#define TIM1_CNT        (mock_TIM1_CNT)
#define TIM1_ARR        (mock_TIM1_ARR)
#define TIM1_CCR1       (mock_TIM1_CCR1)
#define TIM1_BDTR       (mock_TIM1_BDTR)
#define TIM1_SR         (mock_TIM1_SR)

#define GPIOA_MODER     (mock_GPIOA_MODER)
#define GPIOA_ODR       (mock_GPIOA_ODR)

#define ADC1_CR2        (mock_ADC1_CR2)
#define ADC1_SR         (mock_ADC1_SR)
#define ADC1_DR         (mock_ADC1_DR)

#define COMP_CSR        (mock_COMP_CSR)

/* 寄存器位定义 */
#define TIM_CR1_CEN             (1U << 0)
#define TIM_CCER_CC1E           (1U << 0)
#define TIM_BDTR_MOE            (1U << 15)
#define TIM_BDTR_AOE            (1U << 14)
#define TIM_BDTR_BKE            (1U << 12)
#define TIM_BDTR_BKP            (1U << 13)
#define TIM_SR_BIF              (1U << 7)
#define TIM_SR_CC1IF            (1U << 1)

#define GPIO_MODER_OUTPUT       (1U << 0)
#define GPIO_ODR_PIN0           (1U << 0)

#define ADC_CR2_ADON            (1U << 0)
#define ADC_CR2_SWSTART         (1U << 30)
#define ADC_SR_EOC              (1U << 1)

#define COMP_CSR_COMP1EN        (1U << 0)
#define COMP_CSR_COMP1OUT       (1U << 30)

/* ==================== 故障保护状态机 ==================== */
typedef enum {
    FAULT_STATE_NORMAL = 0,
    FAULT_STATE_TRIP,
    FAULT_STATE_LATCHED,
    FAULT_STATE_RECOVERY
} FaultState_t;

typedef struct {
    FaultState_t state;
    uint32_t     trip_count;
    uint32_t     recovery_delay_ms;
    uint32_t     recovery_timer_ms;
    uint32_t     current_threshold;
    uint32_t     blanking_time_us;
    bool         pwm_enabled;
} FaultProtection_t;

static FaultProtection_t g_fault = {
    .state = FAULT_STATE_NORMAL,
    .trip_count = 0,
    .recovery_delay_ms = 1000,
    .recovery_timer_ms = 0,
    .current_threshold = 3000,
    .blanking_time_us = 5,
    .pwm_enabled = false
};

/* ==================== 硬件抽象层函数 ==================== */
static void HAL_TIM_PWM_Start(void)
{
    TIM1_CCER |= TIM_CCER_CC1E;
    TIM1_BDTR |= TIM_BDTR_MOE;
    TIM1_CR1  |= TIM_CR1_CEN;
    g_fault.pwm_enabled = true;
    printf("[HAL] PWM output ENABLED (MOE=1, CC1E=1, CEN=1)\n");
}

static void HAL_TIM_PWM_Stop(void)
{
    TIM1_BDTR &= ~TIM_BDTR_MOE;
    TIM1_CCER &= ~TIM_CCER_CC1E;
    TIM1_CR1  &= ~TIM_CR1_CEN;
    g_fault.pwm_enabled = false;
    printf("[HAL] PWM output DISABLED (MOE=0, CC1E=0, CEN=0)\n");
}

static void HAL_TIM_Break_Enable(void)
{
    TIM1_BDTR |= TIM_BDTR_BKE | TIM_BDTR_BKP | TIM_BDTR_AOE;
    printf("[HAL] Break input enabled (BKE=1, BKP=1, AOE=1)\n");
}

static uint32_t HAL_ADC_ReadCurrent(void)
{
    /* 模拟读取电流采样值 */
    static uint32_t mock_current = 0;
    mock_current += 500;
    if (mock_current > 5000) mock_current = 0;
    return mock_current;
}

static bool HAL_COMP_IsOverCurrent(void)
{
    /* 模拟比较器输出：电流超过阈值时返回true */
    uint32_t current = HAL_ADC_ReadCurrent();
    return (current > g_fault.current_threshold);
}

static void HAL_GPIO_SetFaultLED(bool on)
{
    if (on) {
        GPIOA_ODR |= GPIO_ODR_PIN0;
    } else {
        GPIOA_ODR &= ~GPIO_ODR_PIN0;
    }
}

/* ==================== 故障保护核心算法 ==================== */
static void FaultProtection_Init(void)
{
    g_fault.state = FAULT_STATE_NORMAL;
    g_fault.trip_count = 0;
    g_fault.recovery_timer_ms = 0;
    g_fault.pwm_enabled = false;

    /* 配置GPIO为输出 */
    GPIOA_MODER |= GPIO_MODER_OUTPUT;
    HAL_GPIO_SetFaultLED(false);

    /* 使能比较器 */
    COMP_CSR |= COMP_CSR_COMP1EN;

    /* 使能刹车输入 */
    HAL_TIM_Break_Enable();

    printf("[INIT] Fault protection initialized, threshold=%u\n",
           g_fault.current_threshold);
}

static void FaultProtection_Trip(void)
{
    /* 立即关断PWM输出 */
    HAL_TIM_PWM_Stop();

    /* 点亮故障指示灯 */
    HAL_GPIO_SetFaultLED(true);

    /* 更新状态 */
    g_fault.state = FAULT_STATE_LATCHED;
    g_fault.trip_count++;
    g_fault.recovery_timer_ms = 0;

    printf("[FAULT] !!! SHORT CIRCUIT DETECTED !!! PWM tripped, count=%u\n",
           g_fault.trip_count);
}

static void FaultProtection_Process(uint32_t tick_ms)
{
    switch (g_fault.state) {
    case FAULT_STATE_NORMAL:
        /* 正常运行时检测过流 */
        if (HAL_COMP_IsOverCurrent()) {
            printf("[FAULT] Over-current detected in NORMAL state\n");
            FaultProtection_Trip();
        }
        break;

    case FAULT_STATE_TRIP:
        /* 瞬时跳闸状态，立即进入锁存 */
        FaultProtection_Trip();
        break;

    case FAULT_STATE_LATCHED:
        /* 锁存状态，等待恢复延时 */
        g_fault.recovery_timer_ms += tick_ms;
        if (g_fault.recovery_timer_ms >= g_fault.recovery_delay_ms) {
            g_fault.state = FAULT_STATE_RECOVERY;
            g_fault.recovery_timer_ms = 0;
            printf("[RECOVERY] Recovery delay elapsed, attempting restart\n");
        }
        break;

    case FAULT_STATE_RECOVERY:
        /* 恢复前再次检查是否仍然过流 */
        if (HAL_COMP_IsOverCurrent()) {
            printf("[RECOVERY] Fault still present, re-latching\n");
            g_fault.state = FAULT_STATE_LATCHED;
            g_fault.recovery_timer_ms = 0;
        } else {
            /* 清除故障标志，重新使能PWM */
            TIM1_SR |= TIM_SR_BIF;
            HAL_GPIO_SetFaultLED(false);
            HAL_TIM_PWM_Start();
            g_fault.state = FAULT_STATE_NORMAL;
            printf("[RECOVERY] Fault cleared, PWM restarted\n");
        }
        break;

    default:
        g_fault.state = FAULT_STATE_NORMAL;
        break;
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("========================================\n");
    printf("  PWM Fault Protection (Short Circuit)  \n");
    printf("========================================\n\n");

    /* 初始化故障保护模块 */
    FaultProtection_Init();

    /* 启动PWM输出 */
    HAL_TIM_PWM_Start();

    /* 模拟运行循环 */
    for (int i = 0; i < 20; i++) {
        printf("\n--- Cycle %d ---\n", i + 1);

        /* 模拟读取电流 */
        uint32_t current = HAL_ADC_ReadCurrent();
        printf("[ADC] Current = %u (threshold = %u)\n",
               current, g_fault.current_threshold);

        /* 执行故障保护处理 */
        FaultProtection_Process(100);

        /* 打印当前状态 */
        const char *state_str[] = {
            "NORMAL", "TRIP", "LATCHED", "RECOVERY"
        };
        printf("[STATE] %s, PWM=%s, trips=%u\n",
               state_str[g_fault.state],
               g_fault.pwm_enabled ? "ON" : "OFF",
               g_fault.trip_count);
    }

