#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器定义（使用普通变量，避免非法地址访问） ================= */
static uint32_t reg_pwm_cr1   = 0;
static uint32_t reg_pwm_cr2   = 0;
static uint32_t reg_pwm_sr    = 0;
static uint32_t reg_pwm_ccr1  = 0;
static uint32_t reg_pwm_ccr2  = 0;
static uint32_t reg_pwm_ccr3  = 0;
static uint32_t reg_pwm_arr   = 0;
static uint32_t reg_pwm_psc   = 0;
static uint32_t reg_pwm_bdtr  = 0;
static uint32_t reg_gpioa_moder = 0;
static uint32_t reg_gpioa_odr   = 0;
static uint32_t reg_gpioa_idr   = 0xFFFFFFFFU; /* 默认高电平，无故障 */

#define PWM_CR1         (reg_pwm_cr1)
#define PWM_CR2         (reg_pwm_cr2)
#define PWM_SR          (reg_pwm_sr)
#define PWM_CCR1        (reg_pwm_ccr1)
#define PWM_CCR2        (reg_pwm_ccr2)
#define PWM_CCR3        (reg_pwm_ccr3)
#define PWM_ARR         (reg_pwm_arr)
#define PWM_PSC         (reg_pwm_psc)
#define PWM_BDTR        (reg_pwm_bdtr)

#define GPIOA_MODER     (reg_gpioa_moder)
#define GPIOA_ODR       (reg_gpioa_odr)
#define GPIOA_IDR       (reg_gpioa_idr)

/* 位定义 */
#define PWM_CR1_CEN             (1U << 0)
#define PWM_CR1_ARPE            (1U << 7)
#define PWM_BDTR_MOE            (1U << 15)
#define PWM_BDTR_OSSR           (1U << 11)
#define PWM_BDTR_OSSI           (1U << 10)
#define PWM_BDTR_BKE            (1U << 12)
#define PWM_BDTR_BKP            (1U << 13)
#define PWM_BDTR_AOE            (1U << 14)

#define PWM_SR_BIF              (1U << 7)
#define PWM_SR_CC1IF            (1U << 1)

#define GPIO_PIN_0              (1U << 0)
#define GPIO_PIN_1              (1U << 1)
#define GPIO_PIN_2              (1U << 2)

/* 故障保护状态 */
typedef enum {
    FAULT_NONE = 0,
    FAULT_SHORT_CIRCUIT,
    FAULT_OVERCURRENT,
    FAULT_UNDERVOLTAGE
} fault_type_t;

typedef struct {
    fault_type_t fault;
    uint32_t     fault_count;
    bool         pwm_enabled;
    bool         brake_active;
} pwm_protect_t;

static pwm_protect_t g_protect = {
    .fault = FAULT_NONE,
    .fault_count = 0,
    .pwm_enabled = false,
    .brake_active = false
};

/* ================= 硬件抽象层 ================= */

static void pwm_gpio_init(void)
{
    GPIOA_MODER &= ~((3U << 0) | (3U << 2) | (3U << 4));
    GPIOA_MODER |=  ((2U << 0) | (2U << 2) | (2U << 4));
}

static void pwm_timer_init(void)
{
    PWM_CR1 = 0;
    PWM_CR2 = 0;
    PWM_ARR = 999;
    PWM_PSC = 71;
    PWM_CCR1 = 500;
    PWM_CCR2 = 500;
    PWM_CCR3 = 500;

    PWM_BDTR = PWM_BDTR_BKE | PWM_BDTR_BKP | PWM_BDTR_OSSR | PWM_BDTR_OSSI;
    PWM_CR1 |= PWM_CR1_ARPE;
}

static void pwm_enable_output(bool enable)
{
    if (enable) {
        PWM_BDTR |= PWM_BDTR_MOE;
        PWM_CR1  |= PWM_CR1_CEN;
        g_protect.pwm_enabled = true;
    } else {
        PWM_BDTR &= ~PWM_BDTR_MOE;
        PWM_CR1  &= ~PWM_CR1_CEN;
        g_protect.pwm_enabled = false;
    }
}

static void pwm_set_duty(uint32_t ch, uint32_t duty)
{
    if (duty > PWM_ARR) {
        duty = PWM_ARR;
    }
    switch (ch) {
        case 1: PWM_CCR1 = duty; break;
        case 2: PWM_CCR2 = duty; break;
        case 3: PWM_CCR3 = duty; break;
        default: break;
    }
}

/* 模拟读取短路检测引脚（低电平表示短路） */
static bool read_short_circuit_pin(void)
{
    return (GPIOA_IDR & GPIO_PIN_0) == 0;
}

/* 模拟读取过流检测引脚 */
static bool read_overcurrent_pin(void)
{
    return (GPIOA_IDR & GPIO_PIN_1) == 0;
}

/* ================= 故障保护核心逻辑 ================= */

static void pwm_emergency_shutdown(void)
{
    PWM_BDTR &= ~PWM_BDTR_MOE;
    PWM_CR1 &= ~PWM_CR1_CEN;
    PWM_CCR1 = 0;
    PWM_CCR2 = 0;
    PWM_CCR3 = 0;
    PWM_BDTR |= PWM_BDTR_AOE;
    PWM_SR |= PWM_SR_BIF;

    g_protect.pwm_enabled = false;
    g_protect.brake_active = true;
}

static void pwm_fault_handler(fault_type_t fault)
{
    if (g_protect.fault == FAULT_NONE) {
        g_protect.fault = fault;
        g_protect.fault_count++;
        printf("[FAULT] Detected fault type: %d, count: %lu\n",
               (int)fault, (unsigned long)g_protect.fault_count);
        pwm_emergency_shutdown();
    }
}

static void pwm_fault_recovery(void)
{
    if (g_protect.fault != FAULT_NONE) {
        if (!read_short_circuit_pin() && !read_overcurrent_pin()) {
            printf("[RECOVERY] Fault cleared, restoring PWM output\n");
            g_protect.fault = FAULT_NONE;
            g_protect.brake_active = false;

            pwm_set_duty(1, 500);
            pwm_set_duty(2, 500);
            pwm_set_duty(3, 500);

            pwm_enable_output(true);
        }
    }
}

/* ================= 主控制循环 ================= */

static void pwm_control_loop(void)
{
    if (read_short_circuit_pin()) {
        pwm_fault_handler(FAULT_SHORT_CIRCUIT);
        return;
    }

    if (read_overcurrent_pin()) {
        pwm_fault_handler(FAULT_OVERCURRENT);
        return;
    }

    if (PWM_SR & PWM_SR_BIF) {
        PWM_SR |= PWM_SR_BIF;
        pwm_fault_handler(FAULT_SHORT_CIRCUIT);
        return;
    }

    if (g_protect.pwm_enabled) {
        static uint32_t duty = 0;
        static int dir = 1;
        if (dir > 0) {
            duty += 10;
            if (duty >= 900) { duty = 900; dir = -1; }
        } else {
            if (duty >= 10) duty -= 10;
            if (duty <= 100) { duty = 100; dir = 1; }
        }
        pwm_set_duty(1, duty);
        pwm_set_duty(2, duty);
        pwm_set_duty(3, duty);
    }
}

/* ================= 测试入口 ================= */

int main(void)
{
    printf("=== PWM Short-Circuit Protection Demo ===\n");

    pwm_gpio_init();
    pwm_timer_init();
    pwm_enable_output(true);

    printf("PWM initialized, output enabled.\n");

    for (int i = 0; i < 3; i++) {
        pwm_control_loop();
        printf("Cycle %d: PWM running, duty=%lu, enabled=%d\n",
               i, (unsigned long)PWM_CCR1, g_protect.pwm_enabled);
    }

    printf("\n--- Simulating SHORT CIRCUIT ---\n");
    GPIOA_IDR &= ~GPIO_PIN_0;
    pwm_control_loop();
    printf("After fault: enabled=%d, brake=%d, fault=%d\n",
           g_protect.pwm_enabled, g_protect.brake_active, g_protect.fault);

    pwm_control_loop();
    printf("Fault persists: enabled=%d, fault_count=%lu\n",
           g_protect.pwm_enabled, (unsigned long)g_protect.fault_count);

    printf("\n--- Simulating FAULT CLEAR ---\n");
    GPIOA_IDR |= GPIO_PIN_0;
    pwm_fault_recovery();
    printf("After recovery: enabled=%d, fault=%d\n",
           g_protect.pwm_enabled, g_protect.fault);

    for (int i = 0; i < 2; i++) {
        pwm_control_loop();
        printf("Post-recovery cycle %d: duty=%lu, enabled=%d\n",
               i, (unsigned long)PWM_CCR1, g_protect.pwm_enabled);
    }

    printf("\n=== Demo finished ===\n");
    return 0;
}
