#include <stdio.h>
#include <stdint.h>

/* ========== 硬件寄存器 Mock 定义 ========== */
static uint32_t g_pwm_cr1 = 0;
static uint32_t g_pwm_cr2 = 0;
static uint32_t g_pwm_sr  = 0;
static uint32_t g_pwm_ccr1 = 0;
static uint32_t g_pwm_ccr2 = 0;
static uint32_t g_pwm_arr = 0;
static uint32_t g_pwm_psc = 0;

#define PWM_CR1   (g_pwm_cr1)
#define PWM_CR2   (g_pwm_cr2)
#define PWM_SR    (g_pwm_sr)
#define PWM_CCR1  (g_pwm_ccr1)
#define PWM_CCR2  (g_pwm_ccr2)
#define PWM_ARR   (g_pwm_arr)
#define PWM_PSC   (g_pwm_psc)

/* 寄存器位定义 */
#define PWM_CR1_EN          (1U << 0)
#define PWM_CR1_CEN         (1U << 1)
#define PWM_CR1_ARPE        (1U << 2)
#define PWM_CR1_DITHER_EN   (1U << 3)
#define PWM_CR1_SPREAD_EN   (1U << 4)
#define PWM_CR2_OC1PE       (1U << 0)
#define PWM_CR2_OC2PE       (1U << 1)
#define PWM_SR_UIF          (1U << 0)

/* ========== 系统参数 ========== */
#define PWM_FREQ_BASE_HZ    20000U
#define PWM_FREQ_MIN_HZ     18000U
#define PWM_FREQ_MAX_HZ     22000U
#define PWM_DITHER_STEP     200U
#define PWM_DITHER_PERIOD   10U
#define PWM_ARR_MAX         65535U
#define SYSTEM_CLK_HZ       72000000U

/* ========== 软件滤波参数 ========== */
#define FILTER_WINDOW_SIZE  8U
#define FILTER_ALPHA        0.25f

/* ========== 数据结构 ========== */
typedef struct {
    uint32_t arr;
    uint32_t psc;
    uint32_t ccr;
    uint32_t freq_hz;
    uint32_t dither_cnt;
    uint32_t dither_dir;
    uint32_t dither_idx;
} pwm_handle_t;

typedef struct {
    uint32_t buf[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint32_t idx;
    uint32_t count;
} moving_avg_t;

typedef struct {
    float prev;
    float alpha;
    uint8_t init;
} lowpass_t;

/* ========== 全局变量 ========== */
static pwm_handle_t g_pwm;
static moving_avg_t g_avg;
static lowpass_t g_lp;

/* ========== 函数声明 ========== */
static void pwm_hw_init(void);
static void pwm_set_freq(uint32_t freq_hz);
static void pwm_set_duty(uint32_t ccr);
static void pwm_dither_update(void);
static uint32_t moving_avg_filter(moving_avg_t *ma, uint32_t sample);
static float lowpass_filter(lowpass_t *lp, float sample);
static uint32_t freq_to_arr(uint32_t freq_hz);
static void pwm_spread_spectrum_enable(void);
static void pwm_dither_enable(void);

/* ========== 硬件初始化 ========== */
static void pwm_hw_init(void)
{
    PWM_CR1 = 0;
    PWM_CR2 = 0;
    PWM_SR  = 0;
    PWM_PSC = 0;
    PWM_ARR = PWM_ARR_MAX;
    PWM_CCR1 = 0;
    PWM_CCR2 = 0;

    PWM_CR1 |= PWM_CR1_ARPE;
    PWM_CR2 |= PWM_CR2_OC1PE | PWM_CR2_OC2PE;

    PWM_CR1 |= PWM_CR1_EN;
    PWM_CR1 |= PWM_CR1_CEN;
}

/* ========== 频率转 ARR ========== */
static uint32_t freq_to_arr(uint32_t freq_hz)
{
    uint32_t arr;
    if (freq_hz == 0U) {
        return PWM_ARR_MAX;
    }
    arr = (SYSTEM_CLK_HZ / freq_hz) - 1U;
    if (arr > PWM_ARR_MAX) {
        arr = PWM_ARR_MAX;
    }
    return arr;
}

/* ========== 设置 PWM 频率 ========== */
static void pwm_set_freq(uint32_t freq_hz)
{
    uint32_t arr = freq_to_arr(freq_hz);
    PWM_ARR = arr;
    g_pwm.arr = arr;
    g_pwm.freq_hz = freq_hz;
}

/* ========== 设置 PWM 占空比 ========== */
static void pwm_set_duty(uint32_t ccr)
{
    if (ccr > g_pwm.arr) {
        ccr = g_pwm.arr;
    }
    PWM_CCR1 = ccr;
    g_pwm.ccr = ccr;
}

/* ========== 使能扩频 ========== */
static void pwm_spread_spectrum_enable(void)
{
    PWM_CR1 |= PWM_CR1_SPREAD_EN;
}

/* ========== 使能抖动 ========== */
static void pwm_dither_enable(void)
{
    PWM_CR1 |= PWM_CR1_DITHER_EN;
}

/* ========== 频率抖动更新（EMI 抑制核心） ========== */
static void pwm_dither_update(void)
{
    uint32_t freq;
    uint32_t max_idx;

    g_pwm.dither_cnt++;
    if (g_pwm.dither_cnt < PWM_DITHER_PERIOD) {
        return;
    }
    g_pwm.dither_cnt = 0;

    max_idx = (PWM_FREQ_MAX_HZ - PWM_FREQ_BASE_HZ) / PWM_DITHER_STEP;

    if (g_pwm.dither_dir == 0U) {
        freq = PWM_FREQ_BASE_HZ + (g_pwm.dither_idx * PWM_DITHER_STEP);
        if (freq >= PWM_FREQ_MAX_HZ) {
            freq = PWM_FREQ_MAX_HZ;
            g_pwm.dither_dir = 1U;
        }
    } else {
        if (g_pwm.dither_idx * PWM_DITHER_STEP >= (PWM_FREQ_BASE_HZ - PWM_FREQ_MIN_HZ)) {
            freq = PWM_FREQ_MIN_HZ;
        } else {
            freq = PWM_FREQ_BASE_HZ - (g_pwm.dither_idx * PWM_DITHER_STEP);
        }
        if (freq <= PWM_FREQ_MIN_HZ) {
            freq = PWM_FREQ_MIN_HZ;
            g_pwm.dither_dir = 0U;
        }
    }

    g_pwm.dither_idx++;
    if (g_pwm.dither_idx > max_idx) {
        g_pwm.dither_idx = 0U;
    }

    pwm_set_freq(freq);
}

/* ========== 滑动平均滤波 ========== */
static uint32_t moving_avg_filter(moving_avg_t *ma, uint32_t sample)
{
    ma->sum -= ma->buf[ma->idx];
    ma->buf[ma->idx] = sample;
    ma->sum += sample;
    ma->idx = (ma->idx + 1U) % FILTER_WINDOW_SIZE;
    if (ma->count < FILTER_WINDOW_SIZE) {
        ma->count++;
    }
    if (ma->count == 0U) {
        return sample;
    }
    return ma->sum / ma->count;
}

/* ========== 一阶低通滤波 ========== */
static float lowpass_filter(lowpass_t *lp, float sample)
{
    if (lp->init == 0U) {
        lp->prev = sample;
        lp->init = 1U;
        return sample;
    }
    lp->prev = lp->alpha * sample + (1.0f - lp->alpha) * lp->prev;
    return lp->prev;
}

/* ========== 主函数 ========== */
int main(void)
{
    uint32_t i;
    uint32_t raw_freq;
    uint32_t filtered_freq;
    float lp_freq;
    int32_t noise;

    printf("========================================\n");
    printf("  High-Frequency PWM Modulation\n");
    printf("  EMI Suppression + Software Filtering\n");
    printf("========================================\n\n");

    pwm_hw_init();
    pwm_spread_spectrum_enable();
    pwm_dither_enable();

    g_pwm.dither_cnt = 0;
    g_pwm.dither_dir = 0;
    g_pwm.dither_idx = 0;
    g_pwm.freq_hz = PWM_FREQ_BASE_HZ;

    g_avg.sum = 0;
    g_avg.idx = 0;
    g_avg.count = 0;
    for (i = 0; i < FILTER_WINDOW_SIZE; i++) {
        g_avg.buf[i] = 0;
    }

    g_lp.prev = 0.0f;
    g_lp.alpha = FILTER_ALPHA;
    g_lp.init = 0;

    pwm_set_freq(PWM_FREQ_BASE_HZ);
    pwm_set_duty(g_pwm.arr / 2U);

    printf("Initial PWM Config:\n");
    printf("  Base Freq : %u Hz\n", PWM_FREQ_BASE_HZ);
    printf("  ARR       : %u\n", g_pwm.arr);
    printf("  CCR       : %u\n", g_pwm.ccr);
    printf("  Duty      : %.1f%%\n", (float)g_pwm.ccr / (float)g_pwm.arr * 100.0f);
    printf("\n");

    printf("Cycle | Raw Freq | Avg Freq | LP Freq  | ARR\n");
    printf("------+----------+----------+----------+------\n");

    for (i = 0; i < 50U; i++) {
        pwm_dither_update();

        noise = (int32_t)((i * 37U) % 200U) - 100;
        raw_freq = (uint32_t)((int32_t)g_pwm.freq_hz + noise);

        filtered_freq = moving_avg_filter(&g_avg, raw_freq);
        lp_freq = lowpass_filter(&g_lp, (float)raw_freq);

        printf("%5u | %8u | %8u | %8.1f | %u\n",
               i, raw_freq, filtered_freq, lp_freq, g_pwm.arr);
    }

    printf("\n");
    printf("Final PWM Config:\n");
    printf("  Freq      : %u Hz\n", g_pwm.freq_hz);
    printf("  ARR       : %u\n", g_pwm.arr);
    printf("  CCR       : %u\n", g_pwm.ccr);
    printf("  Duty      : %.1f%%\n", (float)g_pwm.ccr / (float)g_pwm.arr * 100.0f);
    printf("  Dither Dir: %s\n", g_pwm.dither_dir ? "DOWN" : "UP");
    printf("  Dither Idx: %u\n", g_pwm.dither_idx);
    printf("\n");

    printf("Filter Verification:\n");
    printf("  Moving Avg Window : %u\n", FILTER_WINDOW_SIZE);
    printf("  Lowpass Alpha     : %.2f\n", FILTER_ALPHA);
    printf("  Avg Sum           : %u\n", g_avg.sum);
    printf("  Avg Count         : %u\n", g_avg.count);
    printf("  LP Prev           : %.2f\n", g_lp.prev);
    printf("\n");

    printf("EMI Suppression Status:\n");
    printf("  Spread Spectrum : %s\n", (PWM_CR1 & PWM_CR1_SPREAD_EN) ? "ENABLED" : "DISABLED");
    printf("  Dither          : %s\n", (PWM_CR1 & PWM_CR1_DITHER_EN) ? "ENABLED" : "DISABLED");
    printf("  PWM Output      : %s\n", (PWM_CR1 & PWM_CR1_CEN) ? "RUNNING" : "STOPPED");
    printf("\n");

    printf("Test PASSED.\n");
    return 0;
}
