#include <stdio.h>
#include <stdint.h>

/* ============================================================
 * Mock 寄存器定义（替代单片机硬件头文件）
 * ============================================================ */
static uint32_t g_pwm_cr;
static uint32_t g_pwm_arr;
static uint32_t g_pwm_ccr;
static uint32_t g_pwm_sr;

#define PWM_CR              (g_pwm_cr)
#define PWM_ARR             (g_pwm_arr)
#define PWM_CCR             (g_pwm_ccr)
#define PWM_SR              (g_pwm_sr)

#define PWM_CR_EN           (1U << 0)
#define PWM_CR_DITHER_EN    (1U << 1)
#define PWM_SR_UIF          (1U << 0)

/* ============================================================
 * 系统参数
 * ============================================================ */
#define PWM_FREQ_HZ         100000U      /* 100 kHz 高频 PWM */
#define SYS_CLK_HZ          72000000U    /* 72 MHz 系统时钟 */
#define DITHER_CYCLE        8U           /* 抖动周期 */
#define FILTER_ORDER        4U           /* 滑动平均滤波器阶数 */

/* ============================================================
 * 全局变量
 * ============================================================ */
static uint32_t g_pwm_arr_base;              /* 自动重装载基准值 */
static uint32_t g_dither_cnt;                /* 抖动计数器 */
static int32_t  g_dither_offset;             /* 当前抖动偏移量 */
static uint32_t g_filter_buf[FILTER_ORDER];  /* 滤波器缓冲区 */
static uint32_t g_filter_idx;                /* 滤波器写索引 */
static uint32_t g_filter_sum;                /* 滤波器累加和 */

/* ============================================================
 * 初始化 PWM 外设（Mock）
 * ============================================================ */
static void pwm_init(void)
{
    g_pwm_arr_base = (SYS_CLK_HZ / PWM_FREQ_HZ) - 1U;

    PWM_ARR = g_pwm_arr_base;
    PWM_CCR = g_pwm_arr_base / 2U;
    PWM_CR  = PWM_CR_EN | PWM_CR_DITHER_EN;

    g_dither_cnt    = 0U;
    g_dither_offset = 0;

    printf("[PWM] Init: ARR=%u, PWM Freq=%u Hz, Dither=ON\n",
           (unsigned)g_pwm_arr_base, (unsigned)PWM_FREQ_HZ);
}

/* ============================================================
 * 滑动平均滤波器
 * ============================================================ */
static uint32_t moving_average_filter(uint32_t new_sample)
{
    uint32_t avg;

    g_filter_sum -= g_filter_buf[g_filter_idx];
    g_filter_buf[g_filter_idx] = new_sample;
    g_filter_sum += new_sample;

    g_filter_idx = (g_filter_idx + 1U) % FILTER_ORDER;

    avg = g_filter_sum / FILTER_ORDER;
    return avg;
}

/* ============================================================
 * 抖动调制（Dithering）
 * ============================================================ */
static void pwm_dither_update(void)
{
    static const int32_t dither_pattern[DITHER_CYCLE] = {
        0, 1, 2, 1, 0, -1, -2, -1
    };

    g_dither_offset = dither_pattern[g_dither_cnt];

    PWM_ARR = (uint32_t)((int32_t)g_pwm_arr_base + g_dither_offset);

    g_dither_cnt = (g_dither_cnt + 1U) % DITHER_CYCLE;
}

/* ============================================================
 * 模拟读取电流采样值（含 EMI 噪声）—— 使用简单整数近似正弦
 * ============================================================ */
static uint32_t adc_read_current(void)
{
    static uint32_t t = 0U;
    int32_t base, noise, value;
    uint32_t phase;

    /* 用整数三角波近似正弦，避免 math 库依赖 */
    phase = t % 100U;
    if (phase < 25U) {
        base = 2048 + (int32_t)(phase * 40);
    } else if (phase < 50U) {
        base = 2048 + (int32_t)((50U - phase) * 40);
    } else if (phase < 75U) {
        base = 2048 - (int32_t)((phase - 50U) * 40);
    } else {
        base = 2048 - (int32_t)((100U - phase) * 40);
    }

    /* 模拟 EMI 高频噪声（伪随机） */
    noise = (int32_t)((t * 37U + 13U) % 200U) - 100;

    value = base + noise;
    if (value < 0) {
        value = 0;
    }

    t++;
    return (uint32_t)value;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    uint32_t i;
    uint32_t raw, filtered;

    printf("========================================\n");
    printf("  High-Freq PWM Modulation with EMI Suppression\n");
    printf("  (Dithering + Software Moving Average Filter)\n");
    printf("========================================\n\n");

    pwm_init();

    for (i = 0U; i < FILTER_ORDER; i++) {
        g_filter_buf[i] = 0U;
    }
    g_filter_idx = 0U;
    g_filter_sum = 0U;

    printf("\n--- PWM Dithering & Filter Test ---\n");
    printf("%-6s %-12s %-12s %-12s %-12s\n",
           "Step", "ARR", "Dither", "Raw ADC", "Filtered");

    for (i = 0U; i < 20U; i++) {
        pwm_dither_update();
        raw = adc_read_current();
        filtered = moving_average_filter(raw);

        printf("%-6u %-12u %-12d %-12u %-12u\n",
               (unsigned)i,
               (unsigned)PWM_ARR,
               (int)g_dither_offset,
               (unsigned)raw,
               (unsigned)filtered);
    }

    printf("\n--- EMI Suppression Summary ---\n");
    printf("PWM Center Freq : %u Hz\n", (unsigned)PWM_FREQ_HZ);
    printf("Dither Range    : +/- 2 counts (ARR)\n");
