#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FFT_N           256
#define PWM_FREQ        10000.0
#define SAMPLE_FREQ     256000.0
#define MOD_FREQ        50.0
#define MOD_INDEX       0.8

typedef struct {
    double real;
    double imag;
} complex_t;

static complex_t fft_buf[FFT_N];

static void fft_init(void)
{
    memset(fft_buf, 0, sizeof(fft_buf));
}

static void fft_bit_reverse(complex_t *x, int n)
{
    int i, j, k;
    complex_t tmp;
    for (i = 1, j = 0; i < n; i++) {
        k = n >> 1;
        while (j & k) {
            j ^= k;
            k >>= 1;
        }
        j ^= k;
        if (i < j) {
            tmp = x[i];
            x[i] = x[j];
            x[j] = tmp;
        }
    }
}

static void fft_compute(complex_t *x, int n)
{
    int len, i, j, k;
    double ang;
    complex_t w, u, v;

    fft_bit_reverse(x, n);

    for (len = 2; len <= n; len <<= 1) {
        ang = -2.0 * M_PI / (double)len;
        for (i = 0; i < n; i += len) {
            for (k = 0; k < len / 2; k++) {
                w.real = cos(ang * k);
                w.imag = sin(ang * k);
                u = x[i + k];
                v.real = x[i + k + len / 2].real * w.real - x[i + k + len / 2].imag * w.imag;
                v.imag = x[i + k + len / 2].real * w.imag + x[i + k + len / 2].imag * w.real;
                x[i + k].real = u.real + v.real;
                x[i + k].imag = u.imag + v.imag;
                x[i + k + len / 2].real = u.real - v.real;
                x[i + k + len / 2].imag = u.imag - v.imag;
            }
        }
    }
}

static void generate_pwm_samples(complex_t *buf, int n)
{
    int i;
    double t, mod, carrier, pwm;
    double carrier_period = 1.0 / PWM_FREQ;
    double sample_period = 1.0 / SAMPLE_FREQ;

    for (i = 0; i < n; i++) {
        t = (double)i * sample_period;
        mod = MOD_INDEX * sin(2.0 * M_PI * MOD_FREQ * t);
        carrier = 2.0 * (t / carrier_period - floor(t / carrier_period)) - 1.0;
        pwm = (mod > carrier) ? 1.0 : -1.0;
        buf[i].real = pwm;
        buf[i].imag = 0.0;
    }
}

static void compute_magnitude(complex_t *x, double *mag, int n)
{
    int i;
    for (i = 0; i < n / 2; i++) {
        mag[i] = sqrt(x[i].real * x[i].real + x[i].imag * x[i].imag) / (double)(n / 2);
    }
}

static void print_harmonics(double *mag, int n, double fs)
{
    int i;
    double freq, thd = 0.0;
    double fundamental = 0.0;

    printf("========================================\n");
    printf("  PWM Harmonic Analysis (FFT, N=%d)\n", n);
    printf("  PWM Freq: %.1f Hz, Sample Freq: %.1f Hz\n", PWM_FREQ, SAMPLE_FREQ);
    printf("  Mod Freq: %.1f Hz, Mod Index: %.2f\n", MOD_FREQ, MOD_INDEX);
    printf("========================================\n");
    printf("  Bin   Freq(Hz)    Mag(pu)    Mag(dB)\n");
    printf("----------------------------------------\n");

    for (i = 1; i < n / 2; i++) {
        freq = (double)i * fs / (double)n;
        if (mag[i] > 0.001) {
            printf("  %3d   %8.1f   %8.4f   %8.2f\n",
                   i, freq, mag[i], 20.0 * log10(mag[i] + 1e-12));
        }
    }

    fundamental = mag[1];
    for (i = 2; i < n / 2; i++) {
        thd += mag[i] * mag[i];
    }
    thd = sqrt(thd) / (fundamental + 1e-12) * 100.0;

    printf("----------------------------------------\n");
    printf("  Fundamental: %.4f pu\n", fundamental);
    printf("  THD: %.2f %%\n", thd);
    printf("========================================\n");
}

int main(void)
{
    double mag[FFT_N / 2];
    int i;

    printf("PWM Modulation Harmonic Analysis using FFT\n\n");

    fft_init();
    generate_pwm_samples(fft_buf, FFT_N);

    printf("First 8 PWM samples: ");
    for (i = 0; i < 8; i++) {
        printf("%.0f ", fft_buf[i].real);
    }
    printf("...\n\n");

    fft_compute(fft_buf, FFT_N);
    compute_magnitude(fft_buf, mag, FFT_N);
    print_harmonics(mag, FFT_N, SAMPLE_FREQ);

    return 0;
}
