/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t g_pwm_period_reg = 0;
static volatile uint32_t g_pwm_duty_reg = 0;
static volatile uint32_t g_pwm_ctrl_reg = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_DUTY_REG        (g_pwm_duty_reg)
#define PWM_CTRL_REG        (g_pwm_ctrl_reg)
#define PWM_ENABLE_BIT      (1U << 0)
#define PWM_UPDATE_BIT      (1U << 1)

/* 系统时钟与PWM参数 */
#define SYS_CLK_HZ          72000000U
#define PWM_FREQ_HZ         20000U
#define PWM_PERIOD_TICKS    (SYS_CLK_HZ / PWM_FREQ_HZ)

/* 调制深度限制 */
#define MOD_DEPTH_MIN       0.0f
#define MOD_DEPTH_MAX       1.0f

/* ================= 数据结构 ================= */
typedef struct {
    float modulation_depth;   /* 调制深度 0.0 ~ 1.0 */
    float output_voltage;     /* 期望输出电压 */
    float vdc_bus;            /* 直流母线电压 */
    uint32_t period_ticks;    /* PWM周期计数值 */
    uint32_t duty_ticks;      /* 比较值 */
} PWM_Handle_t;

/* ================= 函数实现 ================= */

/**
 * @brief 初始化PWM模块
 */
static void PWM_Init(PWM_Handle_t *pwm, float vdc_bus)
{
    if (pwm == NULL) {
        return;
    }

    pwm->vdc_bus = vdc_bus;
    pwm->modulation_depth = 0.0f;
    pwm->output_voltage = 0.0f;
    pwm->period_ticks = PWM_PERIOD_TICKS;
    pwm->duty_ticks = 0;

    PWM_PERIOD_REG = pwm->period_ticks;
    PWM_DUTY_REG = 0;
    PWM_CTRL_REG |= PWM_ENABLE_BIT;
}

/**
 * @brief 设置调制深度（0.0 ~ 1.0），并自动限幅
 */
static void PWM_SetModulationDepth(PWM_Handle_t *pwm, float depth)
{
    if (pwm == NULL) {
        return;
    }

    if (depth < MOD_DEPTH_MIN) {
        depth = MOD_DEPTH_MIN;
    } else if (depth > MOD_DEPTH_MAX) {
        depth = MOD_DEPTH_MAX;
    }

    pwm->modulation_depth = depth;
    pwm->output_voltage = depth * pwm->vdc_bus;

    /* 计算占空比计数值 */
    pwm->duty_ticks = (uint32_t)(depth * (float)pwm->period_ticks + 0.5f);

    /* 防止溢出 */
    if (pwm->duty_ticks > pwm->period_ticks) {
        pwm->duty_ticks = pwm->period_ticks;
    }

    /* 写入硬件寄存器 */
    PWM_DUTY_REG = pwm->duty_ticks;
    PWM_CTRL_REG |= PWM_UPDATE_BIT;
}

/**
 * @brief 根据目标输出电压计算并设置调制深度
 */
static void PWM_SetOutputVoltage(PWM_Handle_t *pwm, float target_voltage)
{
    float depth;

    if (pwm == NULL) {
        return;
    }

    if (pwm->vdc_bus <= 0.0f) {
        return;
    }

    depth = target_voltage / pwm->vdc_bus;
    PWM_SetModulationDepth(pwm, depth);
}

/**
 * @brief 打印PWM状态
 */
static void PWM_PrintStatus(const PWM_Handle_t *pwm)
{
    if (pwm == NULL) {
        return;
    }

    printf("PWM Status:\n");
    printf("  Vdc Bus        = %.2f V\n", pwm->vdc_bus);
    printf("  Mod Depth      = %.4f (%.2f%%)\n",
           pwm->modulation_depth, pwm->modulation_depth * 100.0f);
    printf("  Output Voltage = %.2f V\n", pwm->output_voltage);
    printf("  Period Ticks   = %u\n", (unsigned int)pwm->period_ticks);
    printf("  Duty Ticks     = %u\n", (unsigned int)pwm->duty_ticks);
    if (pwm->period_ticks > 0) {
        printf("  Duty Ratio     = %.2f%%\n",
               (float)pwm->duty_ticks / (float)pwm->period_ticks * 100.0f);
    }
    printf("----------------------------------------\n");
}

/* ================= 主函数 ================= */
int main(void)
{
    PWM_Handle_t pwm;

    printf("===== PWM Modulation Depth Control Demo =====\n\n");

    /* 初始化，假设直流母线电压 24V */
    PWM_Init(&pwm, 24.0f);
    PWM_PrintStatus(&pwm);

    /* 测试1：直接设置调制深度 0.5 */
    printf("[Test 1] Set modulation depth = 0.5\n");
    PWM_SetModulationDepth(&pwm, 0.5f);
    PWM_PrintStatus(&pwm);

    /* 测试2：设置调制深度 0.85 */
    printf("[Test 2] Set modulation depth = 0.85\n");
    PWM_SetModulationDepth(&pwm, 0.85f);
    PWM_PrintStatus(&pwm);

    /* 测试3：设置调制深度 1.5（应被限幅到 1.0） */
    printf("[Test 3] Set modulation depth = 1.5 (should clamp to 1.0)\n");
    PWM_SetModulationDepth(&pwm, 1.5f);
    PWM_PrintStatus(&pwm);

    /* 测试4：设置调制深度 -0.3（应被限幅到 0.0） */
    printf("[Test 4] Set modulation depth = -0.3 (should clamp to 0.0)\n");
    PWM_SetModulationDepth(&pwm, -0.3f);
    PWM_PrintStatus(&pwm);

    /* 测试5：通过目标输出电压设置，目标 18V */
