#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FFT_N 1024
#define PWM_FREQ 1000.0
#define SAMPLE_FREQ 51200.0
#define MOD_INDEX 0.8

typedef struct {
    double real;
    double imag;
} complex_t;

static complex_t fft_buf[FFT_N];

static void fft(complex_t *x, int n)
{
    int i, j, k, m;
    complex_t t, w;
    double ang;

    j = 0;
    for (i = 0; i < n - 1; i++) {
        if (i < j) {
            t = x[i];
            x[i] = x[j];
            x[j] = t;
        }
        k = n >> 1;
        while (k <= j) {
            j -= k;
            k >>= 1;
        }
        j += k;
    }

    for (m = 2; m <= n; m <<= 1) {
        ang = -2.0 * M_PI / (double)m;
        for (i = 0; i < n; i += m) {
            for (k = 0; k < m / 2; k++) {
                double theta = ang * (double)k;
                w.real = cos(theta);
                w.imag = sin(theta);
                int idx1 = i + k;
                int idx2 = i + k + m / 2;
                t.real = w.real * x[idx2].real - w.imag * x[idx2].imag;
                t.imag = w.real * x[idx2].imag + w.imag * x[idx2].real;
                x[idx2].real = x[idx1].real - t.real;
                x[idx2].imag = x[idx1].imag - t.imag;
                x[idx1].real += t.real;
                x[idx1].imag += t.imag;
            }
        }
    }
}

static void generate_pwm_samples(complex_t *buf, int n)
{
    int i;
    double carrier_ratio = SAMPLE_FREQ / PWM_FREQ;
    for (i = 0; i < n; i++) {
        double t = (double)i / SAMPLE_FREQ;
        double mod = MOD_INDEX * sin(2.0 * M_PI * 50.0 * t);
        double carrier_phase = fmod((double)i / carrier_ratio, 1.0);
        double carrier = (carrier_phase < 0.5) ? 1.0 : -1.0;
        double pwm = (mod >= carrier) ? 1.0 : -1.0;
        buf[i].real = pwm;
        buf[i].imag = 0.0;
    }
}

static void apply_window(complex_t *buf, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        double w = 0.5 * (1.0 - cos(2.0 * M_PI * (double)i / (double)(n - 1)));
        buf[i].real *= w;
    }
}

static double magnitude(complex_t c)
{
    return sqrt(c.real * c.real + c.imag * c.imag);
}

static void print_spectrum(complex_t *buf, int n, double fs)
{
    int i;
    double max_mag = 0.0;
    int max_idx = 0;
    double freq_res = fs / (double)n;

    for (i = 1; i < n / 2; i++) {
        double m = magnitude(buf[i]);
        if (m > max_mag) {
            max_mag = m;
            max_idx = i;
        }
    }

    printf("=== PWM Harmonic Analysis (FFT) ===\n");
    printf("Sample Freq: %.1f Hz, FFT Size: %d, Freq Res: %.2f Hz\n",
           fs, n, freq_res);
    printf("PWM Freq: %.1f Hz, Mod Index: %.2f\n", PWM_FREQ, MOD_INDEX);
    printf("----------------------------------------\n");
    printf("Fundamental (max) at %.2f Hz, Mag = %.4f\n",
           (double)max_idx * freq_res, max_mag);
    printf("----------------------------------------\n");
    printf("Top harmonics:\n");

    {
        int count = 0;
        int used[FFT_N / 2];
        memset(used, 0, sizeof(used));
        while (count < 8) {
            double best = 0.0;
            int best_i = -1;
            for (i = 1; i < n / 2; i++) {
                if (!used[i]) {
                    double m = magnitude(buf[i]);
                    if (m > best) {
                        best = m;
                        best_i = i;
                    }
                }
            }
            if (best_i < 0) break;
            used[best_i] = 1;
            printf("  Harmonic %d: Freq = %8.2f Hz, Mag = %.4f\n",
                   count + 1, (double)best_i * freq_res, best);
            count++;
        }
    }
}

int main(void)
{
    int i;

    printf("PWM Modulation Harmonic Analysis using FFT\n");
    printf("Generating %d PWM samples...\n", FFT_N);

    generate_pwm_samples(fft_buf, FFT_N);
    apply_window(fft_buf, FFT_N);

    printf("Performing FFT...\n");
    fft(fft_buf, FFT_N);

    print_spectrum(fft_buf, FFT_N, SAMPLE_FREQ);

    printf("----------------------------------------\n");
    printf("First 10 time-domain samples:\n");
    for (i = 0; i < 10; i++) {
        printf("  sample[%d] = %.4f\n", i, fft_buf[i].real);
    }

    printf("FFT analysis complete.\n");
    return 0;
}
