```c
#include <stdio.h>
#include <math.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * 使用普通全局变量代替指针解引用，避免非法地址访问
 * ============================================================ */
static volatile unsigned int g_pwm_period_reg = 0;
static volatile unsigned int g_pwm_duty_a_reg = 0;
static volatile unsigned int g_pwm_duty_b_reg = 0;
static volatile unsigned int g_pwm_duty_c_reg = 0;
static volatile int g_adc_ia_reg = 0;
static volatile int g_adc_ib_reg = 0;
static volatile int g_adc_ic_reg = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_DUTY_A_REG      (g_pwm_duty_a_reg)
#define PWM_DUTY_B_REG      (g_pwm_duty_b_reg)
#define PWM_DUTY_C_REG      (g_pwm_duty_c_reg)
#define ADC_IA_REG          (g_adc_ia_reg)
#define ADC_IB_REG          (g_adc_ib_reg)
#define ADC_IC_REG          (g_adc_ic_reg)

/* ============================================================
 * 系统参数定义
 * ============================================================ */
#define PWM_FREQ_HZ         10000.0f
#define PWM_PERIOD_TICKS    1000
#define DEAD_TIME_NS        2000.0f
#define VDC_VOLT            48.0f
#define CURRENT_SENSE_GAIN  0.01f
#define ADC_OFFSET          2048

/* 死区补偿参数 */
#define DEADTIME_COMP_GAIN  1.0f
#define CURRENT_DEADZONE_A  0.05f

/* ============================================================
 * 数据结构
 * ============================================================ */
typedef struct {
    float ia;
    float ib;
    float ic;
    float theta;
    float vd_ref;
    float vq_ref;
    float vd_comp;
    float vq_comp;
    float duty_a;
    float duty_b;
    float duty_c;
} MotorCtrl_t;

static MotorCtrl_t g_motor;

/* ============================================================
 * 工具函数
 * ============================================================ */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

static float signf(float x)
{
    if (x > 0.0f) return 1.0f;
    if (x < 0.0f) return -1.0f;
    return 0.0f;
}

/* ============================================================
 * 死区效应电压误差计算
 * ============================================================ */
static float calc_deadtime_voltage_error(void)
{
    float tpwm_s = 1.0f / PWM_FREQ_HZ;
    float tdead_s = DEAD_TIME_NS * 1e-9f;
    float dv = (tdead_s / tpwm_s) * VDC_VOLT;
    return dv;
}

/* ============================================================
 * 相电流读取与标幺化
 * ============================================================ */
static void read_phase_currents(void)
{
    g_motor.ia = ((float)(ADC_IA_REG - ADC_OFFSET)) * CURRENT_SENSE_GAIN;
    g_motor.ib = ((float)(ADC_IB_REG - ADC_OFFSET)) * CURRENT_SENSE_GAIN;
    g_motor.ic = ((float)(ADC_IC_REG - ADC_OFFSET)) * CURRENT_SENSE_GAIN;
}

/* ============================================================
 * 死区补偿：在 dq 轴参考电压上叠加校正量
 * ============================================================ */
static void deadtime_compensation(void)
{
    float dv = calc_deadtime_voltage_error();
    float ia = g_motor.ia;
    float ib = g_motor.ib;
    float ic = g_motor.ic;
    float theta = g_motor.theta;
    float cos_t = cosf(theta);
    float sin_t = sinf(theta);

    /* 电流死区处理 */
    if (fabsf(ia) < CURRENT_DEADZONE_A) ia = 0.0f;
    if (fabsf(ib) < CURRENT_DEADZONE_A) ib = 0.0f;
    if (fabsf(ic) < CURRENT_DEADZONE_A) ic = 0.0f;

    /* 三相电流方向符号 */
    float sa = signf(ia);
    float sb = signf(ib);
    float sc = signf(ic);

    /* Clarke 变换 (等幅值) */
    float alpha = (2.0f / 3.0f) * (sa - 0.5f * sb - 0.5f * sc) * dv;
    float beta  = (2.0f / 3.0f) * (0.8660254f * (sb - sc)) * dv;

    /* Park 变换 */
    float d_comp =  alpha * cos_t + beta * sin_t;
    float q_comp = -alpha * sin_t + beta * cos_t;

    /* 叠加补偿量 */
    g_motor.vd_comp = g_motor.vd_ref + DEADTIME_COMP_GAIN * d_comp;
    g_motor.vq_comp = g_motor.vq_ref + DEADTIME_COMP_GAIN * q_comp;
}

/* ============================================================
 * 逆 Park + SVPWM 占空比生成
 * ============================================================ */
static void svpwm_generate(void)
{
    float theta = g_motor.theta;
    float cos_t = cosf(theta);
    float sin_t = sinf(theta);
    float vd = g_motor.vd_comp;
    float vq = g_motor.vq_comp;

    /* 逆 Park 变换到 alpha-beta */
    float valpha = vd * cos_t - vq * sin_t;
    float vbeta  = vd * sin_t + vq * cos_t;

    /* 逆 Clarke 变换到三相电压 */
    float va = valpha;
    float vb = -0.5f * valpha + 0.8660254f * vbeta;
    float vc = -0.5f * valpha - 0.8660254f * vbeta;

    /* 归一化到占空比 (0~1) */
    float da = 0.5f + va / VDC_VOLT;
    float db = 0.5f + vb / VDC_VOLT;
    float dc = 0.5f + vc / VDC_VOLT;

    g_motor.duty_a = clampf(da, 0.0f, 1.0f);
    g_motor.duty_b = clampf(db, 0.0f, 1.0f);
    g_motor.duty_c = clampf(dc, 0.0f, 1.0f);
}

/* ============================================================
 * 占空比写入 PWM 寄存器
 * ============================================================ */
static void pwm_output(void)
{
    PWM_PERIOD_REG = PWM_PERIOD_TICKS;
    PWM_DUTY_A_REG = (unsigned int)(g_motor.duty_a * PWM_PERIOD_TICKS);
    PWM_DUTY_B_REG = (unsigned int)(g_motor.duty_b * PWM_PERIOD_TICKS);
    PWM_DUTY_C_REG = (unsigned int)(g_motor.duty_c * PWM_PERIOD_TICKS);
}

/* ============================================================
