static volatile unsigned int g_pwm_period_reg   = 0;
static volatile unsigned int g_pwm_duty_a_reg   = 0;
static volatile unsigned int g_pwm_duty_b_reg   = 0;
static volatile unsigned int g_pwm_duty_c_reg   = 0;
static volatile unsigned int g_pwm_deadtime_reg = 0;
static volatile int          g_adc_ia_reg       = 0;
static volatile int          g_adc_ib_reg       = 0;
static volatile int          g_adc_ic_reg       = 0;

#define PWM_PERIOD_REG      (g_pwm_period_reg)
#define PWM_DUTY_A_REG      (g_pwm_duty_a_reg)
#define PWM_DUTY_B_REG      (g_pwm_duty_b_reg)
#define PWM_DUTY_C_REG      (g_pwm_duty_c_reg)
#define PWM_DEADTIME_REG    (g_pwm_deadtime_reg)
#define ADC_IA_REG          (g_adc_ia_reg)
#define ADC_IB_REG          (g_adc_ib_reg)
#define ADC_IC_REG          (g_adc_ic_reg)

/* 系统参数 */
#define PWM_FREQ_HZ         10000.0f
#define PWM_PERIOD_TICKS    1000
#define DEADTIME_NS         1000.0f
#define VDC_VOLT            48.0f
#define ADC_CURRENT_SCALE   0.01f
#define PI                  3.14159265358979323846f

/* 死区补偿参数 */
#define DEADTIME_COMP_GAIN  1.0f
#define CURRENT_POLARITY_TH 0.05f

/* ============================================================
 * 死区效应补偿结构体
 * ============================================================ */
typedef struct {
    float deadtime_ns;
    float vdc;
    float pwm_period_ticks;
    float comp_gain;
    float current_threshold;
    float comp_voltage_a;
    float comp_voltage_b;
    float comp_voltage_c;
    float duty_a;
    float duty_b;
    float duty_c;
} DeadtimeComp_t;

/* ============================================================
 * 初始化死区补偿模块
 * ============================================================ */
void DeadtimeComp_Init(DeadtimeComp_t *dtc)
{
    if (dtc == NULL) return;

    dtc->deadtime_ns = DEADTIME_NS;
    dtc->vdc = VDC_VOLT;
    dtc->pwm_period_ticks = (float)PWM_PERIOD_TICKS;
    dtc->comp_gain = DEADTIME_COMP_GAIN;
    dtc->current_threshold = CURRENT_POLARITY_TH;
    dtc->comp_voltage_a = 0.0f;
    dtc->comp_voltage_b = 0.0f;
    dtc->comp_voltage_c = 0.0f;
    dtc->duty_a = 0.5f;
    dtc->duty_b = 0.5f;
    dtc->duty_c = 0.5f;
}

/* ============================================================
 * 计算死区导致的电压误差
 * 死区效应：输出电压误差 = (Tdead / Tpwm) * Vdc * sign(i)
 * ============================================================ */
float DeadtimeComp_CalcVoltageError(const DeadtimeComp_t *dtc, float current)
{
    float sign_i;
    float error_v;

    if (dtc == NULL) return 0.0f;

    if (current > dtc->current_threshold) {
        sign_i = 1.0f;
    } else if (current < -dtc->current_threshold) {
        sign_i = -1.0f;
    } else {
        sign_i = 0.0f;
    }

    error_v = (dtc->deadtime_ns * 1e-9f) * PWM_FREQ_HZ * dtc->vdc * sign_i;
    return error_v;
}

/* ============================================================
 * 死区补偿核心：根据相电流修正占空比
 * ============================================================ */
void DeadtimeComp_Update(DeadtimeComp_t *dtc,
                         float ia, float ib, float ic,
                         float duty_a_in, float duty_b_in, float duty_c_in)
{
    float comp_a, comp_b, comp_c;
    float sign_a, sign_b, sign_c;

    if (dtc == NULL) return;

    /* 电流极性判断 */
    sign_a = (ia > dtc->current_threshold) ? 1.0f :
             ((ia < -dtc->current_threshold) ? -1.0f : 0.0f);
    sign_b = (ib > dtc->current_threshold) ? 1.0f :
             ((ib < -dtc->current_threshold) ? -1.0f : 0.0f);
    sign_c = (ic > dtc->current_threshold) ? 1.0f :
             ((ic < -dtc->current_threshold) ? -1.0f : 0.0f);

    /* 死区补偿占空比增量 */
    comp_a = (dtc->deadtime_ns * 1e-9f) * PWM_FREQ_HZ * sign_a * dtc->comp_gain;
    comp_b = (dtc->deadtime_ns * 1e-9f) * PWM_FREQ_HZ * sign_b * dtc->comp_gain;
    comp_c = (dtc->deadtime_ns * 1e-9f) * PWM_FREQ_HZ * sign_c * dtc->comp_gain;

    /* 补偿后的占空比 */
    dtc->duty_a = duty_a_in + comp_a;
    dtc->duty_b = duty_b_in + comp_b;
    dtc->duty_c = duty_c_in + comp_c;

    /* 限幅到 [0, 1] */
    if (dtc->duty_a > 1.0f) dtc->duty_a = 1.0f;
    if (dtc->duty_a < 0.0f) dtc->duty_a = 0.0f;
    if (dtc->duty_b > 1.0f) dtc->duty_b = 1.0f;
    if (dtc->duty_b < 0.0f) dtc->duty_b = 0.0f;
    if (dtc->duty_c > 1.0f) dtc->duty_c = 1.0f;
    if (dtc->duty_c < 0.0f) dtc->duty_c = 0.0f;

    /* 计算补偿电压误差（用于观测/打印） */
    dtc->comp_voltage_a = DeadtimeComp_CalcVoltageError(dtc, ia);
    dtc->comp_voltage_b = DeadtimeComp_CalcVoltageError(dtc, ib);
    dtc->comp_voltage_c = DeadtimeComp_CalcVoltageError(dtc, ic);
}

/* ============================================================
 * 将占空比写入 PWM 寄存器
 * ============================================================ */
void PWM_WriteDuty(float duty_a, float duty_b, float duty_c)
{
    PWM_DUTY_A_REG = (unsigned int)(duty_a * (float)PWM_PERIOD_TICKS);
    PWM_DUTY_B_REG = (unsigned int)(duty_b * (float)PWM_PERIOD_TICKS);
    PWM_DUTY_C_REG = (unsigned int)(duty_c * (float)PWM_PERIOD_TICKS);
}

/* ============================================================
