```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ============================================================
 * 模拟寄存器与硬件抽象层（Mock）
 * ============================================================ */
#define PWM_PERIOD_REG      (*(volatile uint32_t *)0x40000000)
#define PWM_DUTY_A_REG      (*(volatile uint32_t *)0x40000004)
#define PWM_DUTY_B_REG      (*(volatile uint32_t *)0x40000008)
#define PWM_DUTY_C_REG      (*(volatile uint32_t *)0x4000000C)
#define PWM_CTRL_REG        (*(volatile uint32_t *)0x40000010)

#define PWM_CTRL_ENABLE     (1U << 0)
#define PWM_CTRL_OVERMOD    (1U << 1)

/* ============================================================
 * 常量定义
 * ============================================================ */
#define PI                  3.14159265358979323846f
#define SQRT3               1.73205080756887729353f
#define TWO_PI              (2.0f * PI)

/* 过调制模式 */
typedef enum {
    MODE_LINEAR = 0,
    MODE_OVERMOD_I = 1,
    MODE_OVERMOD_II = 2,
    MODE_SIX_STEP = 3
} OverModMode_t;

/* 调制器状态 */
typedef struct {
    float Udc;
    float Ts;
    float m;
    float theta;
    float theta_step;
    OverModMode_t mode;
    float duty_a;
    float duty_b;
    float duty_c;
} PWM_OverMod_t;

/* ============================================================
 * 工具函数
 * ============================================================ */
static float clampf(float v, float lo, float hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float fmod_2pi(float angle)
{
    while (angle >= TWO_PI) angle -= TWO_PI;
    while (angle < 0.0f)    angle += TWO_PI;
    return angle;
}

/* ============================================================
 * 过调制模式判定
 * ============================================================ */
static OverModMode_t get_overmod_mode(float m)
{
    const float m_linear = PI / (2.0f * SQRT3);
    const float m_overmod1 = 0.9517f;
    const float m_overmod2 = 1.0f;

    if (m <= m_linear) {
        return MODE_LINEAR;
    } else if (m <= m_overmod1) {
        return MODE_OVERMOD_I;
    } else if (m <= m_overmod2) {
        return MODE_OVERMOD_II;
    } else {
        return MODE_SIX_STEP;
    }
}

/* ============================================================
 * 过调制 I
 * ============================================================ */
static void overmod_I(float *valpha, float *vbeta, float m)
{
    float theta = atan2f(*vbeta, *valpha);
    float r = sqrtf((*valpha) * (*valpha) + (*vbeta) * (*vbeta));
    float sector;
    float theta_s;
    float r_hex;
    float r_linear;
    float scale;

    theta = fmod_2pi(theta);

    sector = floorf(theta / (PI / 3.0f));
    theta_s = theta - sector * (PI / 3.0f);
    r_hex = (SQRT3 / 2.0f) / cosf(theta_s - PI / 6.0f);

    r_linear = (SQRT3 / 2.0f) * m;

    if (r > r_linear && r > 1e-6f) {
        scale = r_hex / r;
        *valpha *= scale;
        *vbeta  *= scale;
    }
}

/* ============================================================
 * 过调制 II
 * ============================================================ */
static void overmod_II(float *valpha, float *vbeta, float m)
{
    float r = sqrtf((*valpha) * (*valpha) + (*vbeta) * (*vbeta));
    float r_inner = 0.5f;
    float r_outer = SQRT3 / 3.0f;
    float t;
    float r_limit;
    float scale;

    t = (m - 0.9517f) / (1.0f - 0.9517f);
    t = clampf(t, 0.0f, 1.0f);
    r_limit = r_inner + t * (r_outer - r_inner);

    if (r > r_limit && r > 1e-6f) {
        scale = r_limit / r;
        *valpha *= scale;
        *vbeta  *= scale;
    }
}

/* ============================================================
 * 六步模式
 * ============================================================ */
static void six_step(float theta, float *duty_a, float *duty_b, float *duty_c)
{
    float sector;
    int sec;

    theta = fmod_2pi(theta);
    sector = floorf(theta / (PI / 3.0f));
    sec = (int)sector % 6;
    if (sec < 0) sec += 6;

    switch (sec) {
        case 0: *duty_a = 1.0f; *duty_b = 0.0f; *duty_c = 0.0f; break;
        case 1: *duty_a = 1.0f; *duty_b = 1.0f; *duty_c = 0.0f; break;
        case 2: *duty_a = 0.0f; *duty_b = 1.0f; *duty_c = 0.0f; break;
        case 3: *duty_a = 0.0f; *duty_b = 1.0f; *duty_c = 1.0f; break;
        case 4: *duty_a = 0.0f; *duty_b = 0.0f; *duty_c = 1.0f; break;
        case 5: *duty_a = 1.0f; *duty_b = 0.0f; *duty_c = 1.0f; break;
        default: *duty_a = 0.5f; *duty_b = 0.5f; *duty_c = 0.5f; break;
    }
}

/* ============================================================
 * 核心：PWM 过调制算法
 * ============================================================ */
void PWM_OverModulation(PWM_OverMod_t *pwm)
{
    float valpha, vbeta;
    float va, vb, vc;

    if (pwm == NULL) return;

    pwm->mode = get_overmod_mode(pwm->m);

    valpha = pwm->m * cosf(pwm->theta);
    vbeta  = pwm->m * sinf(pwm->theta);

    switch (pwm->mode) {
        case MODE_LINEAR:
            break;

        case MODE_OVERMOD_I:
            overmod_I(&valpha, &vbeta, pwm->m);
            break;

        case MODE_OVERMOD_II:
            overmod_II(&valpha, &vbeta, pwm->m);
            break;

        case MODE_SIX_STEP:
            six_step(pwm->theta, &pwm->duty_a, &pwm->duty_b, &pwm->duty_c);
            return;

        default:
            break;
    }

    va = valpha;
    vb = -0.5f * valpha + (SQRT3 / 2.0f) * vbeta;
    vc = -0.5f * valpha - (SQRT3 / 2.0f) * vbeta;

    if (pwm->Udc < 1e-6f) {
        pwm->duty_a = 0.5f;
        pwm->duty_b = 0.5f;
        pwm->duty_c = 0.5f;
        return;
    }

    pwm->duty_a = clampf(0.5f + va / pwm->Udc, 0.0f, 1.0f);
    pwm->duty_b = clampf(0.5f + vb / pwm->Udc, 0.0f, 1.0f);
    pwm->duty_c = clampf(0.5f + vc / pwm->Udc, 0.0f, 1.0f);
}

/* ============================================================
 * 硬件写入（Mock）—— 使用静态变量模拟寄存器，避免非法地址访问
 * ============================================================ */
static volatile uint32_t g_pwm_period = 0;
static volatile uint32_t g_pwm_duty_a = 0;
static volatile uint32_t g_pwm_duty_b = 0;
static volatile uint32_t g_pwm_duty_c = 0;
static volatile uint32_t g_pwm_ctrl   = 0;

void PWM_WriteHardware(const PWM_OverMod_t *pwm)
{
    uint32_t period = 10000;

    if (pwm == NULL) return;

    g_pwm_period = period;
    g_pwm_duty_a = (uint32_t)(pwm->duty_a * (float)period);
    g_pwm_duty_b = (uint32_t)(pwm->duty_b * (float)period);
    g_pwm_duty_c = (uint32_t)(pwm->duty_c * (float)period);

    g_pwm_ctrl = PWM_CTRL_ENABLE;
    if (pwm->mode != MODE_LINEAR) {
        g_pwm_ctrl |= PWM_CTRL_OVERMOD;
    }
}

/* ============================================================
 * 测试主函数
 * ============================================================ */
int main(void)
{
    PWM_OverMod_t pwm;
    float m_test[] = {0.8f, 0.9069f, 0.93f, 0.9517f, 0.97f, 1.0f, 1.05f};
    int m_count = (int)(sizeof(m_test) / sizeof(m_test[0]));
    int i;

    printf("========================================\n");
    printf("  PWM 过调制（输出电压提升）测试\n");
    printf("========================================\n\n");

    pwm.Udc = 300.0f;
    pwm.Ts = 1.0f / 10000.0f;
    pwm.theta = 0.0f;
    pwm.theta_step = TWO_PI / 36.0f;
    pwm.m = 0.0f;
    pwm.mode = MODE_LINEAR;
    pwm.duty_a = 0.5f;
    pwm.duty_b = 0.5f;
    pwm.duty_c = 0.5f;

    for (i = 0; i < m_count; i++) {
        int step;
        printf("----------------------------------------\n");
        printf("调制比 m = %.4f\n", m_test[i]);
        printf("----------------------------------------\n");

        pwm.m = m_test[i];
        pwm.theta = 0.0f;

        for (step = 0; step < 6; step++) {
            PWM_OverModulation(&pwm);
            PWM_WriteHardware(&pwm);

            printf("  theta=%6.1f deg | mode=%d | "
                   "Da=%.4f Db=%.4f Dc=%.4f\n",
                   pwm.theta * 180.0f / PI,
                   (int)pwm.mode,
                   pwm.duty_a, pwm.duty_b, pwm.duty_c);

