#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static uint32_t g_pwm_cr  = 0U;
static uint32_t g_pwm_arr = 0U;
static uint32_t g_pwm_ccr = 0U;
static uint32_t g_gpio_idr = 0U;

#define MOCK_REG_PWM_CR      (g_pwm_cr)
#define MOCK_REG_PWM_ARR     (g_pwm_arr)
#define MOCK_REG_PWM_CCR     (g_pwm_ccr)
#define MOCK_REG_GPIO_IDR    (g_gpio_idr)

#define PWM_CR_EN            (1U << 0)
#define PWM_CR_OC1E          (1U << 1)
#define PWM_CR_ARPE          (1U << 2)

#define PWM_ARR_DEFAULT      999U
#define PWM_CCR_MIN          0U
#define PWM_CCR_MAX          1000U

/* ================= 硬件防抖参数 ================= */
#define DEBOUNCE_SAMPLES     5U
#define DEBOUNCE_THRESHOLD   3U

/* ================= 软件滤波参数 ================= */
#define FILTER_WINDOW_SIZE   8U
#define FILTER_ALPHA         0.25f

/* ================= 数据结构 ================= */
typedef struct {
    uint8_t  history[DEBOUNCE_SAMPLES];
    uint8_t  index;
    uint8_t  stable_state;
    uint8_t  last_raw;
} Debounce_t;

typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint8_t  index;
    uint32_t sum;
    uint16_t filtered;
} MovingAvgFilter_t;

typedef struct {
    float    alpha;
    float    prev_output;
    uint8_t  initialized;
} LowPassFilter_t;

typedef struct {
    Debounce_t      debounce;
    MovingAvgFilter_t moving_avg;
    LowPassFilter_t  low_pass;
    uint16_t        duty_raw;
    uint16_t        duty_filtered;
    uint32_t        sample_count;
} PwmAntiInterference_t;

/* ================= 硬件防抖实现 ================= */
static void Debounce_Init(Debounce_t *db)
{
    memset(db, 0, sizeof(Debounce_t));
    db->stable_state = 0U;
    db->last_raw = 0U;
}

static uint8_t Debounce_Process(Debounce_t *db, uint8_t raw_input)
{
    uint8_t i;
    uint8_t high_count = 0U;

    db->history[db->index] = raw_input;
    db->index = (uint8_t)((db->index + 1U) % DEBOUNCE_SAMPLES);

    for (i = 0U; i < DEBOUNCE_SAMPLES; i++) {
        if (db->history[i] != 0U) {
            high_count++;
        }
    }

    if (high_count >= DEBOUNCE_THRESHOLD) {
        db->stable_state = 1U;
    } else if (high_count <= (DEBOUNCE_SAMPLES - DEBOUNCE_THRESHOLD)) {
        db->stable_state = 0U;
    }

    db->last_raw = raw_input;
    return db->stable_state;
}

/* ================= 滑动平均滤波实现 ================= */
static void MovingAvg_Init(MovingAvgFilter_t *f)
{
    memset(f, 0, sizeof(MovingAvgFilter_t));
}

static uint16_t MovingAvg_Process(MovingAvgFilter_t *f, uint16_t input)
{
    f->sum -= f->buffer[f->index];
    f->buffer[f->index] = input;
    f->sum += input;
    f->index = (uint8_t)((f->index + 1U) % FILTER_WINDOW_SIZE);
    f->filtered = (uint16_t)(f->sum / FILTER_WINDOW_SIZE);
    return f->filtered;
}

/* ================= 一阶低通滤波实现 ================= */
static void LowPass_Init(LowPassFilter_t *f, float alpha)
{
    f->alpha = alpha;
    f->prev_output = 0.0f;
    f->initialized = 0U;
}

static uint16_t LowPass_Process(LowPassFilter_t *f, uint16_t input)
{
    float out;

    if (f->initialized == 0U) {
        f->prev_output = (float)input;
        f->initialized = 1U;
        return input;
    }

    out = f->alpha * (float)input + (1.0f - f->alpha) * f->prev_output;
    f->prev_output = out;

    if (out < 0.0f) {
        out = 0.0f;
    }
    if (out > (float)PWM_CCR_MAX) {
        out = (float)PWM_CCR_MAX;
    }

    return (uint16_t)(out + 0.5f);
}

/* ================= PWM 抗干扰控制器 ================= */
static void PwmAntiInterference_Init(PwmAntiInterference_t *ctrl)
{
    Debounce_Init(&ctrl->debounce);
    MovingAvg_Init(&ctrl->moving_avg);
    LowPass_Init(&ctrl->low_pass, FILTER_ALPHA);
    ctrl->duty_raw = 0U;
    ctrl->duty_filtered = 0U;
    ctrl->sample_count = 0U;
}

static uint16_t PwmAntiInterference_Update(PwmAntiInterference_t *ctrl, uint16_t raw_duty)
{
    uint16_t after_debounce;
    uint16_t after_moving_avg;
    uint16_t after_low_pass;

    ctrl->sample_count++;

    /* 第一级：硬件防抖（对占空比采样值做数字防抖） */
    after_debounce = (uint16_t)Debounce_Process(&ctrl->debounce, (uint8_t)(raw_duty & 0x01U));
    if (after_debounce == 0U) {
        after_debounce = 0U;
    } else {
        after_debounce = raw_duty;
    }

    /* 第二级：滑动平均滤波 */
    after_moving_avg = MovingAvg_Process(&ctrl->moving_avg, after_debounce);

    /* 第三级：一阶低通滤波 */
    after_low_pass = LowPass_Process(&ctrl->low_pass, after_moving_avg);

    /* 限幅 */
    if (after_low_pass < PWM_CCR_MIN) {
        after_low_pass = PWM_CCR_MIN;
    }
    if (after_low_pass > PWM_CCR_MAX) {
        after_low_pass = PWM_CCR_MAX;
    }

    ctrl->duty_raw = raw_duty;
    ctrl->duty_filtered = after_low_pass;

    return after_low_pass;
}

/* ================= PWM 输出更新 ================= */
static void Pwm_ApplyDuty(uint16_t duty)
{
    if (duty > PWM_ARR_DEFAULT) {
        duty = PWM_ARR_DEFAULT;
    }
    MOCK_REG_PWM_CCR = (uint32_t)duty;
}

static void Pwm_Init(void)
{
    MOCK_REG_PWM_ARR = PWM_ARR_DEFAULT;
    MOCK_REG_PWM_CCR = 0U;
    MOCK_REG_PWM_CR = PWM_CR_EN | PWM_CR_OC1E | PWM_CR_ARPE;
}

/* ================= 模拟噪声输入 ================= */
static uint16_t Simulate_NoisyDuty(uint32_t step)
{
    uint16_t base = 500U;
    int16_t noise;

    switch (step % 8U) {
        case 0U: noise = 0;    break;
        case 1U: noise = 80;   break;
        case 2U: noise = -60;  break;
        case 3U: noise = 120;  break;
        case 4U: noise = -100; break;
        case 5U: noise = 30;   break;
        case 6U: noise = -20;  break;
        default: noise = 0;    break;
    }

    if (step > 20U && step < 30U) {
        base = 800U;
    } else if (step >= 30U) {
        base = 200U;
    }

    {
        int32_t val = (int32_t)base + (int32_t)noise;
        if (val < 0) {
            val = 0;
        }
        if (val > (int32_t)PWM_CCR_MAX) {
            val = (int32_t)PWM_CCR_MAX;
        }
        return (uint16_t)val;
    }
}

/* ================= main ================= */
int main(void)
{
    PwmAntiInterference_t ctrl;
    uint32_t i;
    uint16_t raw;
    uint16_t filtered;

    printf("===== PWM Anti-Interference Control (HW Debounce + SW Filter) =====\n\n");

    Pwm_Init();
    PwmAntiInterference_Init(&ctrl);

    printf("PWM_ARR = %u, PWM_CR = 0x%08X\n\n", (unsigned)PWM_ARR_DEFAULT, (unsigned)MOCK_REG_PWM_CR);

    printf("%-6s %-12s %-12s %-12s\n", "Step", "RawDuty", "FilteredDuty", "CCR_Reg");
    printf("--------------------------------------------------\n");

    for (i = 0U; i < 40U; i++) {
        raw = Simulate_NoisyDuty(i);
        filtered = PwmAntiInterference_Update(&ctrl, raw);
        Pwm_ApplyDuty(filtered);

        printf("%-6u %-12u %-12u %-12u\n",
               (unsigned)i,
               (unsigned)raw,
               (unsigned)filtered,
               (unsigned)MOCK_REG_PWM_CCR);
    }

    printf("\n===== Final State =====\n");
    printf("Total samples   : %u\n", (unsigned)ctrl.sample_count);
    printf("Last raw duty   : %u\n", (unsigned)ctrl.duty_raw);
    printf("Last filtered   : %u\n", (unsigned)ctrl.duty_filtered);
    printf("PWM_CCR register: %u\n", (unsigned)MOCK_REG_PWM_CCR);
    printf("PWM_CR register : 0x%08X\n", (unsigned)MOCK_REG_PWM_CR);

    return 0;
}
