#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define MOCK_PWM_FREQ_HZ        20000.0f
#define MOCK_SAMPLE_FREQ_HZ     20000.0f
#define MOCK_TS                 (1.0f / MOCK_SAMPLE_FREQ_HZ)

/* 模拟 PWM 寄存器 */
typedef struct {
    float duty;          /* 占空比 0.0 ~ 1.0 */
    float phase_comp;    /* 相位补偿量 (弧度) */
} MockPwmRegs_t;

static MockPwmRegs_t g_pwm = {0.5f, 0.0f};

/* 模拟 ADC 采样值 */
static float g_adc_sample = 0.0f;

/* ================= 滤波器延迟模型 ================= */
/*
 * 一阶低通滤波器 (LPF) 的相位延迟:
 *   phi = -atan(2 * pi * f_signal * tau)
 *
 * 其中 tau = RC 时间常数。
 * 在电流环中，采样滤波器会引入相位滞后，
 * 导致系统相位裕度降低。PWM 调制相位补偿
 * 通过提前一个角度来抵消该延迟。
 */

typedef struct {
    float fc;            /* 滤波器截止频率 (Hz) */
    float tau;           /* 时间常数 = 1/(2*pi*fc) */
    float phase_delay;   /* 当前计算的相位延迟 (rad) */
    float phase_comp;    /* 补偿相位 (rad) */
} FilterDelayComp_t;

/* 初始化滤波器延迟补偿器 */
static void FilterDelayComp_Init(FilterDelayComp_t *comp, float fc_hz)
{
    comp->fc = fc_hz;
    comp->tau = 1.0f / (2.0f * (float)M_PI * fc_hz);
    comp->phase_delay = 0.0f;
    comp->phase_comp = 0.0f;
}

/* 计算相位延迟与补偿量
 * f_signal: 当前信号频率 (Hz)
 * 返回补偿相位 (弧度)
 */
static float FilterDelayComp_Update(FilterDelayComp_t *comp, float f_signal)
{
    /* 一阶 LPF 相位延迟: phi = -atan(2*pi*f*tau) */
    float omega_tau = 2.0f * (float)M_PI * f_signal * comp->tau;
    comp->phase_delay = -atanf(omega_tau);

    /* 补偿相位 = 延迟的相反数 (提前) */
    comp->phase_comp = -comp->phase_delay;

    return comp->phase_comp;
}

/* ================= PWM 相位补偿调制 ================= */
/*
 * 在 PWM 调制中，相位补偿通过调整载波与调制波的
 * 相对相位实现。这里用角度偏移量表示。
 *
 * duty_compensated = duty * cos(phase_comp) 的近似
 * 实际实现中通常直接对调制波进行角度偏移。
 */

typedef struct {
    float duty;          /* 原始占空比 */
    float duty_comp;     /* 补偿后占空比 */
    float phase_comp;    /* 补偿相位 (rad) */
    float mod_index;     /* 调制比 */
} PwmPhaseComp_t;

static void PwmPhaseComp_Init(PwmPhaseComp_t *pwm)
{
    pwm->duty = 0.5f;
    pwm->duty_comp = 0.5f;
    pwm->phase_comp = 0.0f;
    pwm->mod_index = 0.0f;
}

/* 执行 PWM 相位补偿
 * duty: 原始占空比
 * phase_comp: 补偿相位 (rad)
 * 返回补偿后的占空比
 */
static float PwmPhaseComp_Apply(PwmPhaseComp_t *pwm, float duty, float phase_comp)
{
    pwm->duty = duty;
    pwm->phase_comp = phase_comp;

    /* 将占空比映射为调制比: m = 2*duty - 1 */
    pwm->mod_index = 2.0f * duty - 1.0f;

    /* 相位补偿: 对调制波进行角度偏移
     * 补偿后调制比 = m * cos(phase_comp) + sqrt(1-m^2) * sin(phase_comp)
     * 简化实现: 直接对占空比做小角度修正
     */
    float m_comp = pwm->mod_index * cosf(phase_comp)
                 + sqrtf(1.0f - pwm->mod_index * pwm->mod_index) * sinf(phase_comp);

    /* 限幅 */
    if (m_comp > 1.0f)  m_comp = 1.0f;
    if (m_comp < -1.0f) m_comp = -1.0f;

    /* 映射回占空比 */
    pwm->duty_comp = (m_comp + 1.0f) * 0.5f;

    return pwm->duty_comp;
}

/* ================= 主控制循环 ================= */
int main(void)
{
    FilterDelayComp_t filter_comp;
    PwmPhaseComp_t pwm_comp;

    /* 初始化: 滤波器截止频率 2kHz */
    FilterDelayComp_Init(&filter_comp, 2000.0f);
    PwmPhaseComp_Init(&pwm_comp);

    printf("===== PWM Phase Compensation (Filter Delay) =====\n");
    printf("PWM Freq: %.1f Hz, Sample Freq: %.1f Hz\n",
           MOCK_PWM_FREQ_HZ, MOCK_SAMPLE_FREQ_HZ);
    printf("Filter Cutoff: %.1f Hz, tau = %.6f s\n",
           filter_comp.fc, filter_comp.tau);
    printf("--------------------------------------------------\n");
    printf("%-10s %-12s %-12s %-12s %-12s\n",
           "f_sig(Hz)", "phi_delay", "phi_comp", "duty", "duty_comp");
    printf("--------------------------------------------------\n");

    /* 模拟不同信号频率下的相位补偿 */
    float test_freqs[] = {10.0f, 50.0f, 100.0f, 200.0f, 500.0f, 1000.0f};
    int n = sizeof(test_freqs) / sizeof(test_freqs[0]);

    for (int i = 0; i < n; i++) {
        float f_sig = test_freqs[i];

        /* 1. 计算滤波器相位延迟与补偿量 */
        float phase_comp = FilterDelayComp_Update(&filter_comp, f_sig);

        /* 2. 模拟 ADC 采样得到占空比 (这里用固定值测试) */
        g_adc_sample = 0.5f + 0.3f * sinf(2.0f * (float)M_PI * f_sig * MOCK_TS);
        float duty = g_adc_sample;
        if (duty < 0.0f) duty = 0.0f;
        if (duty > 1.0f) duty = 1.0f;

        /* 3. 应用 PWM 相位补偿 */
        float duty_comp = PwmPhaseComp_Apply(&pwm_comp, duty, phase_comp);

        /* 4. 更新模拟 PWM 寄存器 */
        g_pwm.duty = duty_comp;
        g_pwm.phase_comp = phase_comp;

        /* 5. 打印结果 */
        printf("%-10.1f %-12.6f %-12.6f %-12.6f %-12.6f\n",
               f_sig,
               filter_comp.phase_delay,
               phase_comp,
               duty,
               duty_comp);
    }

    printf("--------------------------------------------------\n");
    printf("Final PWM duty: %.6f, phase_comp: %.6f rad\n",
           g_pwm.duty, g_pwm.phase_comp);

    return 0;
}
