```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* ===== Mock 寄存器与硬件抽象 ===== */
static uint32_t mock_pwm_cr1;
static uint32_t mock_pwm_cr2;
static uint32_t mock_pwm_sr;
static uint32_t mock_pwm_ccr1;
static uint32_t mock_pwm_arr;
static uint32_t mock_pwm_psc;
static uint32_t mock_gpioa_idr;
static uint32_t mock_gpioa_odr;

#define PWM_CR1         (mock_pwm_cr1)
#define PWM_CR2         (mock_pwm_cr2)
#define PWM_SR          (mock_pwm_sr)
#define PWM_CCR1        (mock_pwm_ccr1)
#define PWM_ARR         (mock_pwm_arr)
#define PWM_PSC         (mock_pwm_psc)

#define GPIOA_IDR       (mock_gpioa_idr)
#define GPIOA_ODR       (mock_gpioa_odr)

#define PWM_CR1_CEN     (1U << 0)
#define PWM_CR1_ARPE    (1U << 7)
#define PWM_CR2_CC1E    (1U << 0)
#define PWM_CR2_CC1P    (1U << 1)
#define PWM_SR_UIF      (1U << 0)

#define PWM_MODE1       0x60U
#define PWM_MODE2       0x70U

/* ===== 硬件防抖参数 ===== */
#define DEBOUNCE_SAMPLES    5U
#define DEBOUNCE_THRESHOLD  3U

/* ===== 软件滤波参数 ===== */
#define FILTER_WINDOW       8U
#define FILTER_ALPHA_NUM    3U
#define FILTER_ALPHA_DEN    4U

/* ===== 全局状态 ===== */
typedef struct {
    uint8_t  history[DEBOUNCE_SAMPLES];
    uint8_t  index;
    uint8_t  stable_state;
    uint8_t  last_raw;
} DebounceState;

typedef struct {
    uint32_t buffer[FILTER_WINDOW];
    uint32_t sum;
    uint8_t  index;
    uint8_t  count;
    uint32_t filtered;
} FilterState;

typedef struct {
    uint32_t duty;
    uint32_t period;
    uint32_t target_duty;
    uint32_t current_duty;
    uint8_t  direction;
} PwmControl;

static DebounceState g_debounce;
static FilterState   g_filter;
static PwmControl    g_pwm;

/* ===== 硬件防抖：多数表决法 ===== */
static void debounce_init(DebounceState *db, uint8_t init_state)
{
    memset(db, 0, sizeof(DebounceState));
    db->stable_state = init_state;
    db->last_raw = init_state;
    for (uint8_t i = 0; i < DEBOUNCE_SAMPLES; i++) {
        db->history[i] = init_state;
    }
}

static uint8_t debounce_update(DebounceState *db, uint8_t raw)
{
    uint8_t ones = 0;

    db->history[db->index] = raw;
    db->index = (uint8_t)((db->index + 1U) % DEBOUNCE_SAMPLES);

    for (uint8_t i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (db->history[i]) {
            ones++;
        }
    }

    if (ones >= DEBOUNCE_THRESHOLD) {
        db->stable_state = 1U;
    } else {
        db->stable_state = 0U;
    }

    db->last_raw = raw;
    return db->stable_state;
}

/* ===== 软件滤波：滑动平均 + 一阶低通 ===== */
static void filter_init(FilterState *fs)
{
    memset(fs, 0, sizeof(FilterState));
}

static uint32_t filter_update(FilterState *fs, uint32_t sample)
{
    uint32_t avg;
    uint32_t denom;

    fs->sum -= fs->buffer[fs->index];
    fs->buffer[fs->index] = sample;
    fs->sum += sample;

    if (fs->count < FILTER_WINDOW) {
        fs->count++;
    }

    fs->index = (uint8_t)((fs->index + 1U) % FILTER_WINDOW);

    denom = (fs->count ? (uint32_t)fs->count : 1U);
    avg = fs->sum / denom;

    fs->filtered = (avg * FILTER_ALPHA_NUM +
                    fs->filtered * (FILTER_ALPHA_DEN - FILTER_ALPHA_NUM)) /
                   FILTER_ALPHA_DEN;

    return fs->filtered;
}

/* ===== PWM 初始化 ===== */
static void pwm_init(uint32_t period, uint32_t prescaler)
{
    PWM_CR1 = 0;
    PWM_CR2 = 0;
    PWM_PSC = prescaler;
    PWM_ARR = period;
    PWM_CCR1 = 0;
    PWM_CR1 |= PWM_CR1_ARPE;
    PWM_CR2 |= PWM_CR2_CC1E;
    PWM_CR2 &= ~PWM_CR2_CC1P;
    PWM_CR1 |= PWM_CR1_CEN;

    g_pwm.period = period;
    g_pwm.duty = 0;
    g_pwm.target_duty = 0;
    g_pwm.current_duty = 0;
    g_pwm.direction = 0;
}

static void pwm_set_duty(uint32_t duty)
{
    if (duty > g_pwm.period) {
        duty = g_pwm.period;
    }
    g_pwm.current_duty = duty;
    PWM_CCR1 = duty;
}

/* ===== 抗干扰 PWM 控制主循环 ===== */
static void pwm_anti_interference_loop(uint32_t raw_adc, uint8_t raw_button)
{
    uint8_t  stable_btn;
    uint32_t filtered_adc;
    uint32_t new_duty;

    stable_btn = debounce_update(&g_debounce, raw_button);

    filtered_adc = filter_update(&g_filter, raw_adc);

    if (stable_btn) {
        g_pwm.target_duty = (filtered_adc * g_pwm.period) / 4095U;
    } else {
        g_pwm.target_duty = 0;
    }

    if (g_pwm.current_duty < g_pwm.target_duty) {
        g_pwm.direction = 1;
        new_duty = g_pwm.current_duty + 1U;
        if (new_duty > g_pwm.target_duty) {
            new_duty = g_pwm.target_duty;
        }
    } else if (g_pwm.current_duty > g_pwm.target_duty) {
        g_pwm.direction = 0;
        new_duty = g_pwm.current_duty - 1U;
        if (new_duty < g_pwm.target_duty) {
            new_duty = g_pwm.target_duty;
        }
    } else {
        new_duty = g_pwm.current_duty;
    }

