/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint32_t g_pwm_freq_reg = 0U;
static volatile uint32_t g_pwm_duty_reg = 0U;
static volatile uint32_t g_pwm_ctrl_reg = 0U;
static volatile uint32_t g_pwm_status_reg = 0U;

