#define PWM_DUTY_REG        (g_pwm_duty_reg)
#define PWM_CTRL_REG        (g_pwm_ctrl_reg)
#define PWM_STATUS_REG      (g_pwm_status_reg)

#define PWM_CTRL_ENABLE     (1U << 0)
#define PWM_CTRL_UPDATE     (1U << 1)
#define PWM_STATUS_ACTIVE   (1U << 0)

#define PWM_BASE_FREQ_HZ    20000U
#define PWM_MIN_FREQ_HZ     2000U
#define PWM_FREQ_STEP_HZ    1000U

#define LOAD_LIGHT_THRESH   15U
#define LOAD_MEDIUM_THRESH  50U
#define LOAD_HEAVY_THRESH   85U

#define LOAD_FILTER_ALPHA   0.2f

/* ================= 全局状态 ================= */
typedef struct {
    uint32_t target_freq_hz;
    uint32_t current_freq_hz;
    uint32_t duty_percent;
    uint8_t  load_percent;
    uint8_t  filtered_load;
    bool     pwm_enabled;
    uint32_t switch_count;
} PwmOptimizer_t;

static PwmOptimizer_t g_pwm = {
    PWM_BASE_FREQ_HZ,
    PWM_BASE_FREQ_HZ,
    50U,
    0U,
    0U,
    false,
    0U
};

/* ================= 硬件抽象层 ================= */
static void pwm_hw_set_frequency(uint32_t freq_hz)
{
    if (freq_hz < PWM_MIN_FREQ_HZ) {
        freq_hz = PWM_MIN_FREQ_HZ;
    }
    if (freq_hz > PWM_BASE_FREQ_HZ) {
        freq_hz = PWM_BASE_FREQ_HZ;
    }
    PWM_FREQ_REG = freq_hz;
    g_pwm.current_freq_hz = freq_hz;
}

static void pwm_hw_set_duty(uint32_t duty_percent)
{
    if (duty_percent > 100U) {
        duty_percent = 100U;
    }
    PWM_DUTY_REG = duty_percent;
    g_pwm.duty_percent = duty_percent;
}

static void pwm_hw_enable(bool enable)
{
    if (enable) {
        PWM_CTRL_REG |= PWM_CTRL_ENABLE;
        PWM_STATUS_REG |= PWM_STATUS_ACTIVE;
    } else {
        PWM_CTRL_REG &= ~PWM_CTRL_ENABLE;
        PWM_STATUS_REG &= ~PWM_STATUS_ACTIVE;
    }
    g_pwm.pwm_enabled = enable;
}

static void pwm_hw_apply_update(void)
{
    PWM_CTRL_REG |= PWM_CTRL_UPDATE;
    PWM_CTRL_REG &= ~PWM_CTRL_UPDATE;
}

static bool pwm_hw_is_active(void)
{
    return (PWM_STATUS_REG & PWM_STATUS_ACTIVE) != 0U;
}

/* ================= 负载采样与滤波 ================= */
static uint8_t load_sample(void)
{
    static uint8_t sim_load = 0U;
    sim_load = (uint8_t)((sim_load + 7U) % 100U);
    return sim_load;
}

static void load_filter_update(uint8_t raw_load)
{
    float filtered = (float)g_pwm.filtered_load;
    filtered = (LOAD_FILTER_ALPHA * (float)raw_load) +
               ((1.0f - LOAD_FILTER_ALPHA) * filtered);
    if (filtered > 100.0f) {
        filtered = 100.0f;
    }
    if (filtered < 0.0f) {
        filtered = 0.0f;
    }
    g_pwm.filtered_load = (uint8_t)(filtered + 0.5f);
    g_pwm.load_percent = raw_load;
}

/* ================= 轻载降频核心算法 ================= */
static uint32_t calc_optimized_frequency(uint8_t load)
{
    uint32_t freq;

    if (load < LOAD_LIGHT_THRESH) {
        freq = PWM_MIN_FREQ_HZ;
    } else if (load < LOAD_MEDIUM_THRESH) {
        freq = PWM_MIN_FREQ_HZ + PWM_FREQ_STEP_HZ;
    } else if (load < LOAD_HEAVY_THRESH) {
        freq = PWM_MIN_FREQ_HZ + (PWM_FREQ_STEP_HZ * 2U);
    } else {
        freq = PWM_BASE_FREQ_HZ;
    }

    if (freq > PWM_BASE_FREQ_HZ) {
        freq = PWM_BASE_FREQ_HZ;
    }
    if (freq < PWM_MIN_FREQ_HZ) {
        freq = PWM_MIN_FREQ_HZ;
    }
    return freq;
}

static uint32_t calc_optimized_duty(uint8_t load)
{
    uint32_t duty;

    if (load < LOAD_LIGHT_THRESH) {
        duty = 10U + (uint32_t)load;
    } else if (load < LOAD_MEDIUM_THRESH) {
        duty = 25U + (uint32_t)(load / 2U);
    } else if (load < LOAD_HEAVY_THRESH) {
        duty = 50U + (uint32_t)((load - LOAD_MEDIUM_THRESH) / 2U);
    } else {
        duty = 70U + (uint32_t)((load - LOAD_HEAVY_THRESH) / 3U);
    }

    if (duty > 95U) {
        duty = 95U;
    }
    if (duty < 5U) {
        duty = 5U;
    }
    return duty;
}

static void pwm_optimizer_step(void)
{
    uint8_t raw_load = load_sample();
    load_filter_update(raw_load);

    uint32_t new_freq = calc_optimized_frequency(g_pwm.filtered_load);
    uint32_t new_duty = calc_optimized_duty(g_pwm.filtered_load);

    if (new_freq != g_pwm.target_freq_hz) {
        g_pwm.target_freq_hz = new_freq;
        g_pwm.switch_count++;
    }

    if (g_pwm.target_freq_hz != g_pwm.current_freq_hz) {
        pwm_hw_set_frequency(g_pwm.target_freq_hz);
    }

    if (new_duty != g_pwm.duty_percent) {
        pwm_hw_set_duty(new_duty);
    }

    if (!g_pwm.pwm_enabled) {
        pwm_hw_enable(true);
    }

    pwm_hw_apply_update();
}

/* ================= 测试打印 ================= */
static void print_status(uint32_t step)
{
    printf("Step %2u | Load(raw=%3u, filt=%3u) | Freq=%5u Hz | Duty=%3u%% | "
           "SwitchCnt=%u | Active=%s\n",
           step,
           (unsigned)g_pwm.load_percent,
           (unsigned)g_pwm.filtered_load,
           (unsigned)g_pwm.current_freq_hz,
           (unsigned)g_pwm.duty_percent,
           (unsigned)g_pwm.switch_count,
           pwm_hw_is_active() ? "YES" : "NO");
}

int main(void)
{
    uint32_t i;

    printf("===== PWM Modulation Energy Optimization (Light-Load Frequency Scaling) =====\n");
    printf("Base Freq: %u Hz, Min Freq: %u Hz, Step: %u Hz\n\n",
           (unsigned)PWM_BASE_FREQ_HZ,
           (unsigned)PWM_MIN_FREQ_HZ,
           (unsigned)PWM_FREQ_STEP_HZ);

    for (i = 0U; i < 20U; i++) {
        pwm_optimizer_step();
        print_status(i + 1U);
    }

    printf("\n===== Optimization Summary =====\n");
    printf("Total frequency switches: %u\n", (unsigned)g_pwm.switch_count);
    printf("Final frequency: %u Hz\n", (unsigned)g_pwm.current_freq_hz);
    printf("Final duty: %u%%\n", (unsigned)g_pwm.duty_percent);
    printf("PWM enabled: %s\n", g_pwm.pwm_enabled ? "YES" : "NO");

    return 0;
}
