#include <stdio.h>
#include <stdint.h>

/* ===== Mock 寄存器（使用普通变量，避免非法地址访问） ===== */
static uint32_t mock_pwm_cr  = 0U;
static uint32_t mock_pwm_arr = 0U;
static uint32_t mock_pwm_ccr = 0U;
static uint32_t mock_pwm_psc = 0U;
static uint32_t mock_pwm_sr  = 0U;

#define PWM_CR   (mock_pwm_cr)
#define PWM_ARR  (mock_pwm_arr)
#define PWM_CCR  (mock_pwm_ccr)
#define PWM_PSC  (mock_pwm_psc)
#define PWM_SR   (mock_pwm_sr)

#define PWM_CR_EN           (1U << 0)
#define PWM_CR_UDIS         (1U << 1)
#define PWM_SR_UIF          (1U << 0)

#define SYSTEM_CLK_HZ       72000000U
#define PWM_FREQ_NORMAL     20000U
#define PWM_FREQ_LIGHT      10000U
#define PWM_FREQ_DEEP       5000U
#define PWM_FREQ_MIN        2000U

#define LOAD_LIGHT_TH       30U
#define LOAD_DEEP_TH        10U

#define DUTY_MIN            5U
#define DUTY_MAX            95U

/* ===== 轻载降频控制器结构体 ===== */
typedef struct {
    uint32_t target_freq;
    uint32_t current_freq;
    uint32_t arr;
    uint32_t psc;
    uint8_t  duty;
    uint8_t  load_percent;
    uint8_t  state;
    uint32_t switch_cnt;
} PwmCtrl_t;

static PwmCtrl_t g_pwm;

/* ===== 计算 ARR 与 PSC ===== */
static void pwm_calc_timing(uint32_t freq, uint32_t *arr, uint32_t *psc)
{
    uint32_t timer_clk = SYSTEM_CLK_HZ;
    uint32_t p = 0U;
    uint32_t a = 0U;

    if (freq == 0U) {
        freq = PWM_FREQ_MIN;
    }

    while (p < 0xFFFFU) {
        a = (timer_clk / (p + 1U)) / freq;
        if (a <= 0xFFFFU && a > 0U) {
            break;
        }
        p++;
    }

    if (a == 0U) {
        a = 1U;
    }
    if (a > 0xFFFFU) {
        a = 0xFFFFU;
    }

    *arr = a - 1U;
    *psc = p;
}

/* ===== 设置 PWM 频率与占空比 ===== */
static void pwm_apply(uint32_t freq, uint8_t duty)
{
    uint32_t arr = 0U;
    uint32_t psc = 0U;
    uint32_t ccr = 0U;

    if (duty < DUTY_MIN) duty = DUTY_MIN;
    if (duty > DUTY_MAX) duty = DUTY_MAX;

    pwm_calc_timing(freq, &arr, &psc);

    PWM_CR &= ~PWM_CR_EN;
    PWM_ARR = arr;
    PWM_PSC = psc;

    ccr = ((arr + 1U) * duty) / 100U;
    if (ccr == 0U) ccr = 1U;
    if (ccr > arr) ccr = arr;
    PWM_CCR = ccr;

    PWM_SR = PWM_SR_UIF;
    PWM_CR |= PWM_CR_EN;

    g_pwm.current_freq = freq;
    g_pwm.arr = arr;
    g_pwm.psc = psc;
    g_pwm.duty = duty;
}

/* ===== 根据负载选择目标频率 ===== */
static uint32_t pwm_select_freq(uint8_t load)
{
    uint32_t freq;

    if (load <= LOAD_DEEP_TH) {
        freq = PWM_FREQ_DEEP;
    } else if (load <= LOAD_LIGHT_TH) {
        freq = PWM_FREQ_LIGHT;
    } else {
        freq = PWM_FREQ_NORMAL;
    }

    if (freq < PWM_FREQ_MIN) {
        freq = PWM_FREQ_MIN;
    }
    return freq;
}

/* ===== 轻载降频主控制逻辑 ===== */
static void pwm_light_load_optimize(uint8_t load_percent)
{
    uint32_t new_freq;
    uint8_t  new_duty;

    g_pwm.load_percent = load_percent;

    new_freq = pwm_select_freq(load_percent);

    if (load_percent < DUTY_MIN) {
        new_duty = DUTY_MIN;
    } else if (load_percent > DUTY_MAX) {
        new_duty = DUTY_MAX;
    } else {
        new_duty = load_percent;
    }

    if (new_freq != g_pwm.current_freq) {
        uint32_t diff;
        if (new_freq < g_pwm.current_freq) {
            diff = g_pwm.current_freq - new_freq;
        } else {
            diff = new_freq - g_pwm.current_freq;
        }
        if (diff > (PWM_FREQ_NORMAL / 10U)) {
            g_pwm.switch_cnt++;
        }
    }

    pwm_apply(new_freq, new_duty);
    g_pwm.target_freq = new_freq;
}

/* ===== 初始化 ===== */
static void pwm_init(void)
{
    g_pwm.target_freq = PWM_FREQ_NORMAL;
    g_pwm.current_freq = 0U;
    g_pwm.arr = 0U;
    g_pwm.psc = 0U;
    g_pwm.duty = 50U;
    g_pwm.load_percent = 50U;
    g_pwm.state = 0U;
    g_pwm.switch_cnt = 0U;

    PWM_CR = 0U;
    PWM_ARR = 0U;
    PWM_PSC = 0U;
    PWM_CCR = 0U;
    PWM_SR = 0U;

    pwm_apply(PWM_FREQ_NORMAL, 50U);
}

/* ===== 打印状态 ===== */
static void pwm_print_status(const char *tag)
{
    printf("[%s] Load=%3u%%  Freq=%6u Hz  ARR=%5u  PSC=%5u  Duty=%3u%%  SwitchCnt=%u\n",
           tag,
           (unsigned)g_pwm.load_percent,
           (unsigned)g_pwm.current_freq,
           (unsigned)g_pwm.arr,
           (unsigned)g_pwm.psc,
           (unsigned)g_pwm.duty,
           (unsigned)g_pwm.switch_cnt);
}

/* ===== 主函数 ===== */
int main(void)
{
    uint8_t test_loads[] = {80U, 50U, 25U, 15U, 8U, 5U, 20U, 40U, 70U, 90U};
    uint32_t i;
    uint32_t n = (uint32_t)(sizeof(test_loads) / sizeof(test_loads[0]));

    printf("===== PWM Light-Load Frequency Reduction Demo =====\n");

    pwm_init();
    pwm_print_status("INIT");

    for (i = 0U; i < n; i++) {
        pwm_light_load_optimize(test_loads[i]);
        pwm_print_status("RUN ");
    }

    printf("===== Done. Total frequency switches: %u =====\n",
           (unsigned)g_pwm.switch_cnt);
    return 0;
}
