#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== Mock 寄存器与宏定义 ==================== */
/* 使用普通变量模拟寄存器, 避免非法地址访问导致崩溃 */
static volatile uint32_t g_reg_pwm_period  = 0U;
static volatile uint32_t g_reg_pwm_duty    = 0U;
static volatile uint32_t g_reg_temp_sensor = 25U;
static volatile uint32_t g_reg_pwm_ctrl    = 0U;

#define PWM_PERIOD_REG      (g_reg_pwm_period)
#define PWM_DUTY_REG        (g_reg_pwm_duty)
#define TEMP_SENSOR_REG     (g_reg_temp_sensor)
#define PWM_CTRL_REG        (g_reg_pwm_ctrl)

#define PWM_ENABLE_BIT      (1U << 0)
#define PWM_UPDATE_BIT      (1U << 1)

/* 温度阈值与降频参数 */
#define TEMP_NORMAL_C       45U
#define TEMP_WARN_C         65U
#define TEMP_CRITICAL_C     85U
#define TEMP_SHUTDOWN_C     105U

#define PWM_PERIOD_MAX      1000U
#define PWM_DUTY_MAX        1000U

/* 降频步进与周期 */
#define FREQ_STEP           50U
#define CONTROL_INTERVAL_MS 100U

/* ==================== 全局状态 ==================== */
typedef struct {
    uint32_t current_temp;
    uint32_t target_duty;
    uint32_t current_duty;
    uint32_t pwm_period;
    uint32_t freq_level;      /* 0=全速, 越大越降频 */
    bool     pwm_enabled;
    bool     shutdown_flag;
} ThermalState_t;

static ThermalState_t g_thermal;

/* ==================== 硬件抽象层 ==================== */
static void hw_pwm_init(void)
{
    PWM_PERIOD_REG = PWM_PERIOD_MAX;
    PWM_DUTY_REG   = PWM_DUTY_MAX;
    PWM_CTRL_REG  |= PWM_ENABLE_BIT;
    PWM_CTRL_REG  |= PWM_UPDATE_BIT;
}

static void hw_pwm_set_duty(uint32_t duty)
{
    if (duty > PWM_DUTY_MAX) {
        duty = PWM_DUTY_MAX;
    }
    PWM_DUTY_REG = duty;
    PWM_CTRL_REG |= PWM_UPDATE_BIT;
}

static void hw_pwm_set_period(uint32_t period)
{
    if (period < 1U) {
        period = 1U;
    }
    if (period > 2000U) {
        period = 2000U;
    }
    PWM_PERIOD_REG = period;
    PWM_CTRL_REG  |= PWM_UPDATE_BIT;
}

static uint32_t hw_read_temperature(void)
{
    return TEMP_SENSOR_REG;
}

static void hw_pwm_disable(void)
{
    PWM_CTRL_REG &= ~PWM_ENABLE_BIT;
    PWM_CTRL_REG |= PWM_UPDATE_BIT;
}

/* ==================== 热管理算法 ==================== */
static void thermal_init(void)
{
    g_thermal.current_temp  = 25U;
    g_thermal.target_duty   = PWM_DUTY_MAX;
    g_thermal.current_duty  = PWM_DUTY_MAX;
    g_thermal.pwm_period    = PWM_PERIOD_MAX;
    g_thermal.freq_level    = 0U;
    g_thermal.pwm_enabled   = true;
    g_thermal.shutdown_flag = false;

    hw_pwm_init();
}

/*
 * 根据温度计算目标占空比与降频等级
 */
static void thermal_calc_target(uint32_t temp)
{
    uint32_t duty = PWM_DUTY_MAX;
    uint32_t level = 0U;

    if (temp >= TEMP_SHUTDOWN_C) {
        g_thermal.shutdown_flag = true;
        g_thermal.target_duty   = 0U;
        g_thermal.freq_level    = 4U;
        return;
    }

    g_thermal.shutdown_flag = false;

    if (temp < TEMP_NORMAL_C) {
        duty  = PWM_DUTY_MAX;
        level = 0U;
    } else if (temp < TEMP_WARN_C) {
        /* 45~65C: 1000 -> 700 */
        uint32_t delta = temp - TEMP_NORMAL_C;
        uint32_t range = TEMP_WARN_C - TEMP_NORMAL_C;
        duty  = PWM_DUTY_MAX - (delta * 300U) / range;
        level = 1U;
    } else if (temp < TEMP_CRITICAL_C) {
        /* 65~85C: 700 -> 400 */
        uint32_t delta = temp - TEMP_WARN_C;
        uint32_t range = TEMP_CRITICAL_C - TEMP_WARN_C;
        duty  = 700U - (delta * 300U) / range;
        level = 2U;
    } else {
        /* 85~105C: 400 -> 100 */
        uint32_t delta = temp - TEMP_CRITICAL_C;
        uint32_t range = TEMP_SHUTDOWN_C - TEMP_CRITICAL_C;
        duty  = 400U - (delta * 300U) / range;
        level = 3U;
    }

    if (duty < 100U) {
        duty = 100U;
    }

    g_thermal.target_duty = duty;
    g_thermal.freq_level  = level;
}

/*
 * 平滑调节占空比, 避免突变
 */
static void thermal_apply_duty(void)
{
    if (g_thermal.shutdown_flag) {
        g_thermal.current_duty = 0U;
        hw_pwm_set_duty(0U);
        hw_pwm_disable();
        g_thermal.pwm_enabled = false;
        return;
    }

    if (!g_thermal.pwm_enabled) {
        PWM_CTRL_REG |= PWM_ENABLE_BIT;
        g_thermal.pwm_enabled = true;
    }

    if (g_thermal.current_duty < g_thermal.target_duty) {
        uint32_t step = FREQ_STEP;
        if (g_thermal.current_duty + step > g_thermal.target_duty) {
            g_thermal.current_duty = g_thermal.target_duty;
        } else {
            g_thermal.current_duty += step;
        }
    } else if (g_thermal.current_duty > g_thermal.target_duty) {
        uint32_t step = FREQ_STEP;
        if (g_thermal.current_duty < step ||
            g_thermal.current_duty - step < g_thermal.target_duty) {
            g_thermal.current_duty = g_thermal.target_duty;
        } else {
            g_thermal.current_duty -= step;
        }
    }

    hw_pwm_set_duty(g_thermal.current_duty);
}

/*
 * 根据降频等级调整 PWM 周期(频率)
 */
static void thermal_apply_frequency(void)
{
    uint32_t period = PWM_PERIOD_MAX + g_thermal.freq_level * 200U;
    if (period > 2000U) {
        period = 2000U;
    }
    g_thermal.pwm_period = period;
    hw_pwm_set_period(period);
}

/*
 * 主控制循环单步执行
 */
static void thermal_control_step(void)
{
    uint32_t temp = hw_read_temperature();
    g_thermal.current_temp = temp;

    thermal_calc_target(temp);
    thermal_apply_duty();
    thermal_apply_frequency();

    printf("[Thermal] Temp=%3u C | Level=%u | Duty=%4u/%4u | Period=%4u | PWM=%s\n",
           (unsigned)temp,
           (unsigned)g_thermal.freq_level,
           (unsigned)g_thermal.current_duty,
           (unsigned)PWM_DUTY_MAX,
           (unsigned)g_thermal.pwm_period,
           g_thermal.pwm_enabled ? "ON" : "OFF");
}

