#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 模拟寄存器与硬件抽象层 ==================== */
/* 使用宏定义模拟寄存器，避免依赖具体单片机头文件 */
#define MOCK_REG_ADC_DATA       (*(volatile uint16_t *)0x40000000)
#define MOCK_REG_PWM_PERIOD     (*(volatile uint16_t *)0x40000004)
#define MOCK_REG_PLL_CTRL       (*(volatile uint32_t *)0x40000008)
#define MOCK_REG_PLL_STATUS     (*(volatile uint32_t *)0x4000000C)

/* 模拟系统时钟频率，用于计算定时器周期 */
#define MOCK_SYSTEM_CLOCK_HZ    72000000UL
#define MOCK_PWM_FREQ_HZ        20000UL
#define MOCK_ADC_SAMPLE_FREQ_HZ 20000UL

/* ==================== 常量定义 ==================== */
#define PI                      3.14159265358979323846f
#define TWO_PI                  (2.0f * PI)

/* PLL 频率自适应范围 45Hz - 55Hz */
#define PLL_FREQ_MIN_HZ         45.0f
#define PLL_FREQ_MAX_HZ         55.0f
#define PLL_FREQ_NOMINAL_HZ     50.0f

/* 环路滤波器参数（归一化） */
#define PLL_KP                  0.15f
#define PLL_KI                  0.002f

/* 限幅 */
#define PLL_FREQ_DELTA_MAX      5.0f    /* 最大频率偏差 ±5Hz */
#define PLL_PHASE_ERR_MAX       (PI / 4.0f)

/* ==================== 数据结构 ==================== */
typedef struct {
    /* 输入 */
    float   theta_grid;         /* 电网电压相位（由采样计算） */
    float   v_alpha;            /* 电网电压 alpha 分量 */
    float   v_beta;             /* 电网电压 beta 分量 */

    /* 内部状态 */
    float   theta_pll;          /* PLL 估计相位 */
    float   freq_pll;           /* PLL 估计频率 (Hz) */
    float   omega_pll;          /* PLL 估计角频率 (rad/s) */
    float   integrator;         /* 环路滤波器积分器状态 */
    float   phase_err;          /* 相位误差 */
    float   sin_theta;          /* sin(theta_pll) */
    float   cos_theta;          /* cos(theta_pll) */

    /* 输出 */
    float   freq_out;           /* 输出频率 (Hz) */
    float   theta_out;          /* 输出相位 (rad) */
    float   locked;             /* 锁定标志 0/1 */
} PLL_Handle_t;

/* ==================== 工具函数 ==================== */
static inline float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static inline float wrap_phase(float theta)
{
    while (theta > PI)  theta -= TWO_PI;
    while (theta < -PI) theta += TWO_PI;
    return theta;
}

/* ==================== PLL 初始化 ==================== */
void PLL_Init(PLL_Handle_t *pll)
{
    pll->theta_grid   = 0.0f;
    pll->v_alpha      = 0.0f;
    pll->v_beta       = 0.0f;
    pll->theta_pll    = 0.0f;
    pll->freq_pll     = PLL_FREQ_NOMINAL_HZ;
    pll->omega_pll    = TWO_PI * PLL_FREQ_NOMINAL_HZ;
    pll->integrator   = 0.0f;
    pll->phase_err    = 0.0f;
    pll->sin_theta    = 0.0f;
    pll->cos_theta    = 1.0f;
    pll->freq_out     = PLL_FREQ_NOMINAL_HZ;
    pll->theta_out    = 0.0f;
    pll->locked       = 0;
}

/* ==================== PLL 核心更新 ==================== */
/* 输入：v_alpha, v_beta（电网电压两相静止坐标系分量）
 * 输出：更新 pll 结构体中的频率、相位、锁定状态
 * 采样周期 Ts 由调用者传入（秒）
 */
void PLL_Update(PLL_Handle_t *pll, float v_alpha, float v_beta, float Ts)
{
    /* 1. 保存输入 */
    pll->v_alpha = v_alpha;
    pll->v_beta  = v_beta;

    /* 2. 计算当前估计相位的正余弦 */
    pll->sin_theta = sinf(pll->theta_pll);
    pll->cos_theta = cosf(pll->theta_pll);

    /* 3. 相位检测：使用 Park 变换提取 q 轴分量作为相位误差
     *    v_q = -v_alpha * sin(theta) + v_beta * cos(theta)
     *    当 PLL 锁定时，v_q 趋近于 0
     */
    float v_q = -v_alpha * pll->sin_theta + v_beta * pll->cos_theta;

    /* 4. 归一化相位误差（假设电网电压幅值为 1.0，实际应用需除以幅值） */
    float v_mag = sqrtf(v_alpha * v_alpha + v_beta * v_beta);
    if (v_mag < 1e-6f) {
        v_mag = 1e-6f;  /* 防止除零 */
    }
    pll->phase_err = v_q / v_mag;

    /* 5. 相位误差限幅 */
    pll->phase_err = clampf(pll->phase_err, -PLL_PHASE_ERR_MAX, PLL_PHASE_ERR_MAX);

    /* 6. 环路滤波器（PI 控制器） */
    pll->integrator += PLL_KI * pll->phase_err * Ts;
    /* 积分器限幅，防止饱和 */
    pll->integrator = clampf(pll->integrator,
                             -PLL_FREQ_DELTA_MAX * TWO_PI,
                             PLL_FREQ_DELTA_MAX * TWO_PI);

    /* 7. 计算角频率偏差 */
    float omega_delta = PLL_KP * pll->phase_err + pll->integrator;

    /* 8. 更新估计角频率 */
    pll->omega_pll = TWO_PI * PLL_FREQ_NOMINAL_HZ + omega_delta;

    /* 9. 频率自适应限幅：45Hz - 55Hz */
    pll->freq_pll = pll->omega_pll / TWO_PI;
    pll->freq_pll = clampf(pll->freq_pll, PLL_FREQ_MIN_HZ, PLL_FREQ_MAX_HZ);
    pll->omega_pll = TWO_PI * pll->freq_pll;

    /* 10. 相位积分（VCO） */
    pll->theta_pll += pll->omega_pll * Ts;
    pll->theta_pll = wrap_phase(pll->theta_pll);

    /* 11. 输出更新 */
    pll->freq_out  = pll->freq_pll;
    pll->theta_out = pll->theta_pll;

    /* 12. 锁定检测：相位误差持续较小则判定锁定 */
    if (fabsf(pll->phase_err) < 0.05f) {
        pll->locked = 1;
    } else {
        pll->locked = 0;
    }
}

/* ==================== 模拟电网电压生成 ==================== */
/* 生成频率为 freq_hz、幅值为 amp 的三相电网电压的 alpha-beta 分量 */
void MockGrid_Generate(float freq_hz, float amp, float theta,
                       float *v_alpha, float *v_beta)
{
    /* 三相电压：Va = amp*sin(theta), Vb = amp*sin(theta-2pi/3), Vc = amp*sin(theta+2pi/3) */
    float va = amp * sinf(theta);
    float vb = amp * sinf(theta - TWO_PI / 3.0f);
    float vc = amp * sinf(theta + TWO_PI / 3.0f);

    /* Clarke 变换（等幅值） */
    *v_alpha = (2.0f / 3.0f) * (va - 0.5f * vb - 0.5f * vc);
    *v_beta  = (2.0f / 3.0f) * (0.86602540378f * (vb - vc));
}

/* ==================== 主函数 ==================== */
int main(void)
{
    PLL_Handle_t pll;
    PLL_Init(&pll);

    /* 模拟参数 */
    const float Ts = 1.0f / (float)MOCK_ADC_SAMPLE_FREQ_HZ;  /* 采样周期 50us */
    const float grid_amp = 1.0f;                              /* 电网电压幅值 */
    float grid_freq = 50.0f;                                  /* 初始电网频率 50Hz */
    float grid_theta = 0.0f;                                  /* 电网相位 */

    /* 模拟运行 2000 个采样点（约 100ms） */
    const int total_steps = 2000;
    int step;

    printf("=== PLL Frequency Adaptive Control (45Hz-55Hz) ===\n");
    printf("Sample freq: %d Hz, Ts = %.6f s\n", MOCK_ADC_SAMPLE_FREQ_HZ, Ts);
    printf("Step | GridFreq | PLLFreq  | PhaseErr | Locked\n");
    printf("-----+----------+----------+----------+-------\n");

    for (step = 0; step < total_steps; step++) {
        /* 1. 模拟电网电压生成 */
        float v_alpha, v_beta;
        MockGrid_Generate(grid_freq, grid_amp, grid_theta, &v_alpha, &v_beta);

        /* 2. 更新电网相位 */
        grid_theta += TWO_PI * grid_freq * Ts;
        grid_theta = wrap_phase(grid_theta);

        /* 3. 在特定时刻改变电网频率，测试自适应能力 */
        if (step == 500) {
            grid_freq = 47.0f;   /* 频率跌落至 47Hz */
            printf(">>> Grid frequency changed to 47.0 Hz at step %d\n", step);
        }
        if (step == 1000) {
            grid_freq = 53.0f;   /* 频率上升至 53Hz */
            printf(">>> Grid frequency changed to 53.0 Hz at step %d\n", step);
        }
        if (step == 1500) {
            grid_freq = 50.0f;   /* 恢复至 50Hz */
            printf(">>> Grid frequency changed to 50.0 Hz at step %d\n", step);
        }

        /* 4. PLL 更新 */
        PLL_Update(&pll, v_alpha, v_beta, Ts);

        /* 5. 每 200 步打印一次状态 */
        if (step % 200 == 0) {
            printf("%4d | %8.2f | %8.2f | %+8.4f | %d\n",
                   step, grid_freq, pll.freq_out, pll.phase_err, pll.locked);
        }
    }

    /* 最终状态 */
    printf("\n=== Final State ===\n");
    printf("Grid frequency : %.2f Hz\n", grid_freq);
    printf("PLL frequency  : %.2f Hz\n", pll.freq_out);
    printf("PLL phase      : %.4f rad\n", pll.theta_out);
    printf("PLL locked     : %s\n", pll.locked ? "YES" : "NO");
    printf("Frequency error: %.4f Hz\n", pll.freq_out - grid_freq);

    /* 验证频率范围 */
    if (pll.freq_out >= PLL_FREQ_MIN_HZ && pll.freq_out <= PLL_FREQ_MAX_HZ) {
        printf("Frequency within [45, 55] Hz range: PASS\n");
    } else {
        printf("Frequency within [45, 55] Hz range: FAIL\n");
    }

    return 0;
}
