#include <stdio.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* ==================== 模拟寄存器与硬件抽象 ==================== */
/* 使用宏定义模拟寄存器，避免依赖特定单片机头文件 */
typedef struct {
    volatile float adc_result;      /* ADC采样结果寄存器 */
    volatile float dac_output;      /* DAC输出寄存器 */
    volatile float timer_count;     /* 定时器计数寄存器 */
    volatile float timer_period;    /* 定时器周期寄存器 */
} MockHardwareRegs;

static MockHardwareRegs g_hw = {0};

/* 模拟ADC读取 */
#define ADC_READ()              (g_hw.adc_result)
/* 模拟DAC写入 */
#define DAC_WRITE(val)          (g_hw.dac_output = (val))
/* 模拟定时器计数读取 */
#define TIMER_GET_COUNT()       (g_hw.timer_count)
/* 模拟定时器周期设置 */
#define TIMER_SET_PERIOD(p)     (g_hw.timer_period = (p))

/* ==================== SOGI-PLL 参数定义 ==================== */
#define SOGI_K          1.414f      /* SOGI阻尼系数，通常取sqrt(2) */
#define PLL_KP          50.0f       /* PLL比例增益 */
#define PLL_KI          500.0f      /* PLL积分增益 */
#define NOMINAL_FREQ    50.0f       /* 额定频率(Hz) */
#define NOMINAL_OMEGA   (2.0f * M_PI * NOMINAL_FREQ)  /* 额定角频率(rad/s) */
#define TS              0.0001f     /* 采样周期(s)，对应10kHz采样率 */
#define V_GRID_PEAK     311.0f      /* 电网电压峰值(V) */

/* ==================== SOGI-PLL 结构体 ==================== */
typedef struct {
    /* SOGI 状态变量 */
    float x1;           /* 正交信号alpha轴积分器状态 */
    float x2;           /* 正交信号beta轴积分器状态 */

    /* PLL 状态变量 */
    float theta;        /* 估计相位角(rad) */
    float omega;        /* 估计角频率(rad/s) */
    float integrator;   /* PI积分器状态 */

    /* 输出信号 */
    float alpha;        /* 同相分量 */
    float beta;         /* 正交分量 */
    float v_d;          /* d轴分量(用于锁相) */
    float v_q;          /* q轴分量(用于锁相) */
    float freq;         /* 估计频率(Hz) */
} SOGI_PLL;

/* ==================== 初始化 ==================== */
static void SOGI_PLL_Init(SOGI_PLL *pll)
{
    pll->x1 = 0.0f;
    pll->x2 = 0.0f;
    pll->theta = 0.0f;
    pll->omega = NOMINAL_OMEGA;
    pll->integrator = 0.0f;
    pll->alpha = 0.0f;
    pll->beta = 0.0f;
    pll->v_d = 0.0f;
    pll->v_q = 0.0f;
    pll->freq = NOMINAL_FREQ;
}

/* ==================== SOGI-PLL 核心算法 ==================== */
/*
 * 输入: v_in  - 电网电压采样值
 * 输出: 更新 pll 结构体中的 alpha, beta, theta, freq 等
 *
 * SOGI 离散化采用双线性变换(Tustin)或前向欧拉法
 * 此处使用前向欧拉法，简单且适用于小步长
 *
 * SOGI 连续域方程:
 *   d(alpha)/dt = omega * (k * (v_in - alpha) - beta)
 *   d(beta)/dt  = omega * alpha
 *
 * PLL 鉴相:
 *   v_q = -alpha * sin(theta) + beta * cos(theta)
 *   v_d =  alpha * cos(theta) + beta * sin(theta)
 *
 * PI 调节器:
 *   omega = omega_nominal + kp * v_q + ki * integral(v_q)
 *   theta = integral(omega)
 */
static void SOGI_PLL_Update(SOGI_PLL *pll, float v_in)
{
    float alpha_new, beta_new;
    float sin_theta, cos_theta;
    float v_q, v_d;
    float omega_err;

    /* ---- 步骤1: SOGI 正交信号生成 ---- */
    /* 前向欧拉离散化 */
    alpha_new = pll->x1 + TS * pll->omega * (SOGI_K * (v_in - pll->x1) - pll->x2);
    beta_new  = pll->x2 + TS * pll->omega * pll->x1;

    pll->x1 = alpha_new;
    pll->x2 = beta_new;
    pll->alpha = alpha_new;
    pll->beta  = beta_new;

    /* ---- 步骤2: Park 变换(鉴相) ---- */
    sin_theta = sinf(pll->theta);
    cos_theta = cosf(pll->theta);

    v_d =  pll->alpha * cos_theta + pll->beta * sin_theta;
    v_q = -pll->alpha * sin_theta + pll->beta * cos_theta;

    pll->v_d = v_d;
    pll->v_q = v_q;

    /* ---- 步骤3: PI 调节器(锁频) ---- */
    /* 积分项 */
    pll->integrator += PLL_KI * v_q * TS;

    /* 限幅积分器，防止饱和 */
    if (pll->integrator > 100.0f) pll->integrator = 100.0f;
    if (pll->integrator < -100.0f) pll->integrator = -100.0f;

    /* 角频率 = 额定角频率 + PI输出 */
    omega_err = PLL_KP * v_q + pll->integrator;
    pll->omega = NOMINAL_OMEGA + omega_err;

    /* 角频率限幅，防止失锁 */
    if (pll->omega > NOMINAL_OMEGA * 1.5f) pll->omega = NOMINAL_OMEGA * 1.5f;
    if (pll->omega < NOMINAL_OMEGA * 0.5f) pll->omega = NOMINAL_OMEGA * 0.5f;

    /* ---- 步骤4: 相位积分 ---- */
    pll->theta += pll->omega * TS;

    /* 相位归一化到 [0, 2*pi) */
    while (pll->theta >= 2.0f * M_PI) pll->theta -= 2.0f * M_PI;
    while (pll->theta < 0.0f) pll->theta += 2.0f * M_PI;

    /* ---- 步骤5: 频率计算 ---- */
    pll->freq = pll->omega / (2.0f * M_PI);
}

/* ==================== 测试用信号发生器 ==================== */
/* 生成含谐波和直流偏置的电网电压信号 */
static float GenerateGridVoltage(float t)
{
    float fundamental = V_GRID_PEAK * sinf(2.0f * M_PI * 50.0f * t);
    float harmonic3   = 0.15f * V_GRID_PEAK * sinf(2.0f * M_PI * 150.0f * t + 0.5f);
    float harmonic5   = 0.10f * V_GRID_PEAK * sinf(2.0f * M_PI * 250.0f * t + 1.0f);
    float dc_offset   = 0.05f * V_GRID_PEAK;
    return fundamental + harmonic3 + harmonic5 + dc_offset;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    SOGI_PLL pll;
    float t = 0.0f;
    float v_in;
    int i;
    int print_counter = 0;

    printf("========================================\n");
    printf("  Single-Phase SOGI-PLL Test\n");
    printf("  Ts = %.6f s, Fs = %.1f Hz\n", TS, 1.0f / TS);
    printf("  Nominal Freq = %.1f Hz\n", NOMINAL_FREQ);
    printf("  SOGI K = %.4f\n", SOGI_K);
    printf("  PLL Kp = %.1f, Ki = %.1f\n", PLL_KP, PLL_KI);
    printf("========================================\n\n");

    /* 初始化 */
    SOGI_PLL_Init(&pll);
    TIMER_SET_PERIOD(TS);

    printf("Time(s)   V_in(V)   Alpha(V)  Beta(V)   Theta(rad) Freq(Hz)  Vq(V)\n");
    printf("------------------------------------------------------------------------\n");

    /* 仿真循环: 0.5秒，10kHz采样率 */
    for (i = 0; i < 5000; i++) {
        /* 1. 生成电网电压信号(模拟ADC采样) */
        v_in = GenerateGridVoltage(t);
        g_hw.adc_result = v_in;

        /* 2. 执行SOGI-PLL算法 */
        SOGI_PLL_Update(&pll, ADC_READ());

        /* 3. 模拟DAC输出(可用于调试) */
        DAC_WRITE(pll.alpha);

        /* 4. 每500个点打印一次(每50ms) */
        if (i % 500 == 0) {
            printf("%.4f   %8.2f  %8.2f  %8.2f  %8.4f  %8.3f  %8.2f\n",
                   t, v_in, pll.alpha, pll.beta,
                   pll.theta, pll.freq, pll.v_q);
            print_counter++;
        }

        /* 5. 时间推进 */
        t += TS;
    }

    printf("\n========================================\n");
    printf("  Final Results:\n");
    printf("  Estimated Frequency: %.4f Hz\n", pll.freq);
    printf("  Estimated Omega:     %.4f rad/s\n", pll.omega);
    printf("  Estimated Theta:     %.4f rad\n", pll.theta);
    printf("  Alpha amplitude:     %.2f V\n", pll.alpha);
    printf("  Beta amplitude:      %.2f V\n", pll.beta);
    printf("  Frequency Error:     %.4f Hz\n", pll.freq - NOMINAL_FREQ);
    printf("========================================\n");

    return 0;
}
