/* ===== Mock 寄存器 (使用普通变量, 避免非法地址访问) ===== */
static volatile float g_adc_u = 0.0f;
static volatile float g_adc_v = 0.0f;
static volatile float g_adc_w = 0.0f;
static volatile float g_pwm   = 0.0f;

#define MOCK_REG_ADC_U  (g_adc_u)
#define MOCK_REG_ADC_V  (g_adc_v)
#define MOCK_REG_ADC_W  (g_adc_w)
#define MOCK_REG_PWM    (g_pwm)

/* ===== 三相 DPLL 参数 ===== */
#define DPLL_TS         0.0001f
#define DPLL_KP         120.0f
#define DPLL_KI         3000.0f
#define DPLL_WNOM       (2.0f * M_PI * 50.0f)
#define DPLL_WMIN       (2.0f * M_PI * 40.0f)
#define DPLL_WMAX       (2.0f * M_PI * 60.0f)
#define DPLL_ALPHA      0.5f

/* ===== 三相 DPLL 状态结构体 ===== */
typedef struct {
    float theta;
    float omega;
    float integ;
    float v_alpha;
    float v_beta;
    float v_alpha_f;
    float v_beta_f;
    float sin_theta;
    float cos_theta;
    float freq_hz;
} DPLL_State;

/* ===== 初始化 DPLL ===== */
static void DPLL_Init(DPLL_State *s)
{
    s->theta     = 0.0f;
    s->omega     = DPLL_WNOM;
    s->integ     = 0.0f;
    s->v_alpha   = 0.0f;
    s->v_beta    = 0.0f;
    s->v_alpha_f = 0.0f;
    s->v_beta_f  = 0.0f;
    s->sin_theta = 0.0f;
    s->cos_theta = 1.0f;
    s->freq_hz   = 50.0f;
}

/* ===== Clarke 变换: abc -> alpha-beta ===== */
static void Clarke_Transform(float ua, float ub, float uc,
                             float *alpha, float *beta)
{
    *alpha = (2.0f / 3.0f) * (ua - 0.5f * ub - 0.5f * uc);
    *beta  = (2.0f / 3.0f) * (0.86602540378f * (ub - uc));
}

/* ===== 二阶广义积分器 (SOGI) 滤波 ===== */
static void SOGI_Filter(DPLL_State *s)
{
    float k = DPLL_ALPHA;
    float omega = s->omega;
    float err_a = s->v_alpha - s->v_alpha_f;
    float d_alpha_f = omega * s->v_beta_f;
    float d_beta_f  = -omega * s->v_alpha_f + k * omega * err_a;

    s->v_alpha_f += d_alpha_f * DPLL_TS;
    s->v_beta_f  += d_beta_f  * DPLL_TS;

    if (s->v_alpha_f > 10.0f)  s->v_alpha_f = 10.0f;
    if (s->v_alpha_f < -10.0f) s->v_alpha_f = -10.0f;
    if (s->v_beta_f > 10.0f)   s->v_beta_f = 10.0f;
    if (s->v_beta_f < -10.0f)  s->v_beta_f = -10.0f;
}

/* ===== 相位检测器 (Park 变换) ===== */
static float Phase_Detector(DPLL_State *s)
{
    float vd =  s->cos_theta * s->v_alpha_f + s->sin_theta * s->v_beta_f;
    float vq = -s->sin_theta * s->v_alpha_f + s->cos_theta * s->v_beta_f;
    (void)vd;
    return vq;
}

/* ===== 环路滤波器 (PI) ===== */
static float Loop_Filter(DPLL_State *s, float phase_err)
{
    float omega_corr;

    s->integ += DPLL_KI * phase_err * DPLL_TS;

    if (s->integ >  DPLL_WMAX) s->integ =  DPLL_WMAX;
    if (s->integ < -DPLL_WMAX) s->integ = -DPLL_WMAX;

    omega_corr = DPLL_KP * phase_err + s->integ;

    s->omega = DPLL_WNOM + omega_corr;

    if (s->omega > DPLL_WMAX) s->omega = DPLL_WMAX;
    if (s->omega < DPLL_WMIN) s->omega = DPLL_WMIN;

    return s->omega;
}

/* ===== 压控振荡器 (VCO) ===== */
static void VCO_Update(DPLL_State *s)
{
    s->theta += s->omega * DPLL_TS;

    while (s->theta >= 2.0f * M_PI) s->theta -= 2.0f * M_PI;
    while (s->theta < 0.0f)         s->theta += 2.0f * M_PI;

    s->sin_theta = sinf(s->theta);
    s->cos_theta = cosf(s->theta);

    s->freq_hz = s->omega / (2.0f * M_PI);
}

/* ===== 单步 DPLL 更新 ===== */
static void DPLL_Update(DPLL_State *s, float ua, float ub, float uc)
{
    float alpha, beta;
    float phase_err;

    Clarke_Transform(ua, ub, uc, &alpha, &beta);
    s->v_alpha = alpha;
    s->v_beta  = beta;

    SOGI_Filter(s);

    phase_err = Phase_Detector(s);

    Loop_Filter(s, phase_err);

    VCO_Update(s);
}

/* ===== 生成测试用三相电压 ===== */
static void Generate_Test_Voltage(float t, float freq, float amp,
                                  float *ua, float *ub, float *uc)
{
    float w = 2.0f * M_PI * freq;
    *ua = amp * sinf(w * t);
    *ub = amp * sinf(w * t - 2.0f * M_PI / 3.0f);
    *uc = amp * sinf(w * t + 2.0f * M_PI / 3.0f);
}

/* ===== 主函数 ===== */
int main(void)
{
    DPLL_State dpll;
    float t = 0.0f;
    float ua, ub, uc;
    int i;

    printf("========================================\n");
    printf("  三相 DPLL (频率自适应) 仿真测试\n");
    printf("========================================\n");
    printf("采样周期: %.1f us\n", DPLL_TS * 1e6f);
    printf("额定频率: 50 Hz\n");
    printf("频率范围: 40 ~ 60 Hz\n");
    printf("----------------------------------------\n");
    printf(" 时间(ms)  实际频率(Hz)  估计频率(Hz)  相位误差(deg)\n");
    printf("----------------------------------------\n");

    DPLL_Init(&dpll);

    for (i = 0; i < 6000; i++) {
        float actual_freq;

        if (t < 0.2f) {
            actual_freq = 50.0f;
        } else if (t < 0.4f) {
            actual_freq = 55.0f;
        } else {
            actual_freq = 45.0f;
        }

        Generate_Test_Voltage(t, actual_freq, 1.0f, &ua, &ub, &uc);

        MOCK_REG_ADC_U = ua;
        MOCK_REG_ADC_V = ub;
        MOCK_REG_ADC_W = uc;

        DPLL_Update(&dpll, MOCK_REG_ADC_U, MOCK_REG_ADC_V, MOCK_REG_ADC_W);

        if (i % 200 == 0) {
            float phase_err_deg;
            float actual_phase = 2.0f * M_PI * actual_freq * t;
            float phase_diff = dpll.theta - actual_phase;

            while (phase_diff >  M_PI) phase_diff -= 2.0f * M_PI;
            while (phase_diff < -M_PI) phase_diff += 2.0f * M_PI;

            phase_err_deg = phase_diff * 180.0f / M_PI;

            printf("  %6.1f     %6.1f        %6.2f        %7.2f\n",
                   t * 1000.0f, actual_freq, dpll.freq_hz, phase_err_deg);
        }

        t += DPLL_TS;
    }

    printf("----------------------------------------\n");
    printf("仿真完成, 共 6000 个采样点\n");
    printf("最终估计频率: %.2f Hz\n", dpll.freq_hz);
    printf("最终估计相位: %.4f rad (%.2f deg)\n",
           dpll.theta, dpll.theta * 180.0f / M_PI);
    printf("========================================\n");

    return 0;
}
