#include <stdio.h>
#include <math.h>

/* ============================================================
 * 模拟寄存器与硬件抽象层（Mock）
 * 使用普通全局变量代替非法指针，避免段错误
 * ============================================================ */
static volatile float g_reg_adc_u_alpha = 0.0f;
static volatile float g_reg_adc_u_beta  = 0.0f;
static volatile float g_reg_pll_theta   = 0.0f;
static volatile float g_reg_pll_omega   = 0.0f;
static volatile float g_reg_pll_amp     = 0.0f;
static volatile int   g_reg_pll_lock    = 0;

#define MOCK_REG_ADC_U_ALPHA   (g_reg_adc_u_alpha)
#define MOCK_REG_ADC_U_BETA    (g_reg_adc_u_beta)
#define MOCK_REG_PLL_THETA     (g_reg_pll_theta)
#define MOCK_REG_PLL_OMEGA     (g_reg_pll_omega)
#define MOCK_REG_PLL_AMP       (g_reg_pll_amp)
#define MOCK_REG_PLL_LOCK_FLAG (g_reg_pll_lock)

/* ============================================================
 * 参数定义
 * ============================================================ */
#define PI                    3.14159265358979323846f
#define TWO_PI                (2.0f * PI)
#define TS                    0.0001f          /* 采样周期 100us */
#define PLL_KP                120.0f           /* 锁相环比例增益 */
#define PLL_KI                5000.0f          /* 锁相环积分增益 */
#define AMP_LPF_ALPHA         0.02f            /* 幅值低通滤波系数 */
#define AMP_DIP_THRESHOLD     0.85f            /* 电压跌落判定阈值(pu) */
#define AMP_RECOVER_THRESHOLD 0.92f            /* 电压恢复判定阈值(pu) */
#define AMP_NOMINAL           1.0f             /* 额定幅值(pu) */
#define FREQ_NOMINAL          50.0f            /* 额定频率(Hz) */
#define OMEGA_NOMINAL         (TWO_PI * FREQ_NOMINAL)

/* ============================================================
 * PLL 状态结构体
 * ============================================================ */
typedef struct {
    float theta;            /* 锁相角(rad) */
    float omega;            /* 估计角频率(rad/s) */
    float amp;              /* 估计幅值(pu) */
    float amp_filtered;     /* 滤波后幅值(pu) */
    float integrator;       /* PI积分器状态 */
    float sin_theta;        /* sin(theta) */
    float cos_theta;        /* cos(theta) */
    int   lock_flag;        /* 锁定标志: 0=未锁, 1=已锁 */
    int   dip_flag;         /* 跌落标志: 0=正常, 1=跌落 */
    int   recover_cnt;      /* 恢复计数器 */
} PLL_State;

/* ============================================================
 * 初始化 PLL
 * ============================================================ */
static void PLL_Init(PLL_State *pll)
{
    pll->theta        = 0.0f;
    pll->omega        = OMEGA_NOMINAL;
    pll->amp          = AMP_NOMINAL;
    pll->amp_filtered = AMP_NOMINAL;
    pll->integrator   = 0.0f;
    pll->sin_theta    = 0.0f;
    pll->cos_theta    = 1.0f;
    pll->lock_flag    = 0;
    pll->dip_flag     = 0;
    pll->recover_cnt  = 0;
}

/* ============================================================
 * 幅值锁定 PLL 核心算法
 * ============================================================ */
static void PLL_Update(PLL_State *pll, float u_alpha, float u_beta)
{
    float sin_t, cos_t;
    float u_d, u_q;
    float amp_raw;
    float error;
    float omega_est;
    float theta_next;

    /* --- 1. 计算当前角度的正余弦 --- */
    sin_t = sinf(pll->theta);
    cos_t = cosf(pll->theta);

    /* --- 2. Park 变换: alpha-beta -> d-q --- */
    u_d =  u_alpha * cos_t + u_beta * sin_t;
    u_q = -u_alpha * sin_t + u_beta * cos_t;

    /* --- 3. 幅值估计 --- */
    amp_raw = sqrtf(u_d * u_d + u_q * u_q);

    /* --- 4. 幅值低通滤波 --- */
    pll->amp_filtered += AMP_LPF_ALPHA * (amp_raw - pll->amp_filtered);
    pll->amp = pll->amp_filtered;

    /* --- 5. 电压跌落检测与幅值锁定 --- */
    if (pll->amp < AMP_DIP_THRESHOLD * AMP_NOMINAL) {
        pll->dip_flag = 1;
        pll->recover_cnt = 0;
    } else if (pll->dip_flag) {
        if (pll->amp > AMP_RECOVER_THRESHOLD * AMP_NOMINAL) {
            pll->recover_cnt++;
            if (pll->recover_cnt > 50) {   /* 持续 5ms 确认恢复 */
                pll->dip_flag = 0;
                pll->recover_cnt = 0;
            }
        } else {
            pll->recover_cnt = 0;
        }
    }

    /* --- 6. 相位误差 --- */
    error = u_q;

    /* --- 7. PI 调节器 --- */
    if (pll->dip_flag) {
        /* 跌落期间：冻结积分器，仅用比例项维持相位跟踪 */
        omega_est = pll->omega + PLL_KP * error;
    } else {
        /* 正常工况：完整 PI 调节 */
        pll->integrator += PLL_KI * error * TS;
        if (pll->integrator >  200.0f) pll->integrator =  200.0f;
        if (pll->integrator < -200.0f) pll->integrator = -200.0f;
        omega_est = pll->omega + PLL_KP * error + pll->integrator;
    }

    /* --- 8. 频率限幅 --- */
    if (omega_est > OMEGA_NOMINAL * 1.2f) omega_est = OMEGA_NOMINAL * 1.2f;
    if (omega_est < OMEGA_NOMINAL * 0.8f) omega_est = OMEGA_NOMINAL * 0.8f;

    pll->omega = omega_est;

    /* --- 9. 角度积分 --- */
    theta_next = pll->theta + pll->omega * TS;
    if (theta_next > TWO_PI) theta_next -= TWO_PI;
    if (theta_next < 0.0f)   theta_next += TWO_PI;
    pll->theta = theta_next;

    /* --- 10. 锁定判定 --- */
    if (fabsf(error) < 0.05f && fabsf(pll->omega - OMEGA_NOMINAL) < 5.0f) {
        pll->lock_flag = 1;
    } else {
        pll->lock_flag = 0;
    }

    /* --- 11. 更新缓存 --- */
    pll->sin_theta = sinf(pll->theta);
    pll->cos_theta = cosf(pll->theta);

    /* --- 12. 写入 Mock 寄存器 --- */
    MOCK_REG_PLL_THETA     = pll->theta;
    MOCK_REG_PLL_OMEGA     = pll->omega;
    MOCK_REG_PLL_AMP       = pll->amp;
    MOCK_REG_PLL_LOCK_FLAG = pll->lock_flag;
}

/* ============================================================
 * 生成测试用 alpha-beta 电压信号
 * ============================================================ */
static void Generate_Test_Voltage(float t, float *u_alpha, float *u_beta)
{
    float amp;
    float theta;

    /* 模拟电压跌落：0.02s ~ 0.06s 期间幅值降至 0.3pu */
    if (t >= 0.02f && t < 0.06f) {
        amp = 0.3f;
    } else {
        amp = 1.0f;
    }

    theta = TWO_PI * FREQ_NOMINAL * t;

    *u_alpha = amp * cosf(theta);
    *u_beta  = amp * sinf(theta);
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    PLL_State pll;
    float t;
    float u_alpha, u_beta;
    int   step;
    int   total_steps = 1000;   /* 100ms 仿真 */

    printf("========================================\n");
    printf("  PLL 抗电压跌落（幅值锁定）测试\n");
    printf("========================================\n");
    printf("时间(s)   U_alpha   U_beta    Theta(rad)  Omega(rad/s)  Amp(pu)  Lock  Dip\n");
    printf("--------------------------------------------------------------------------\n");

    PLL_Init(&pll);

    for (step = 0; step < total_steps; step++) {
        t = (float)step * TS;

        /* 生成测试电压 */
        Generate_Test_Voltage(t, &u_alpha, &u_beta);

        /* 写入 Mock ADC 寄存器 */
        MOCK_REG_ADC_U_ALPHA = u_alpha;
        MOCK_REG_ADC_U_BETA  = u_beta;

        /* 执行 PLL 更新 */
        PLL_Update(&pll, u_alpha, u_beta);

        /* 每 100 步打印一次 */
        if (step % 100 == 0) {
            printf("%.4f   %+.4f   %+.4f   %+.4f     %+.2f       %.4f   %d     %d\n",
                   t,
                   u_alpha,
                   u_beta,
                   pll.theta,
                   pll.omega,
                   pll.amp,
                   pll.lock_flag,
                   pll.dip_flag);
        }
    }

    printf("--------------------------------------------------------------------------\n");
    printf("最终状态:\n");
    printf("  Theta     = %.4f rad\n", pll.theta);
    printf("  Omega     = %.2f rad/s (%.2f Hz)\n", pll.omega, pll.omega / TWO_PI);
    printf("  Amp       = %.4f pu\n", pll.amp);
    printf("  Lock Flag = %d\n", pll.lock_flag);
    printf("  Dip Flag  = %d\n", pll.dip_flag);
    printf("========================================\n");

    return 0;
