```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 模拟电网电压采样寄存器（12位ADC，0~4095对应-1.0~1.0标幺值） */
#define MOCK_ADC_VOLTAGE_REG   (*(volatile uint16_t *)0x40000000)

/* 模拟PLL控制周期（秒），对应10kHz采样率 */
#define PLL_TS                 (0.0001f)

/* 模拟PI控制器参数 */
#define PLL_KP                 (120.0f)
#define PLL_KI                 (3000.0f)

/* 模拟频率限幅范围：45Hz ~ 55Hz */
#define FREQ_MIN_HZ            (45.0f)
#define FREQ_MAX_HZ            (55.0f)

/* 模拟额定频率 */
#define FREQ_NOMINAL_HZ        (50.0f)

/* 模拟2*pi */
#define TWO_PI                 (6.28318530718f)

/* ==================== PLL 结构体定义 ==================== */
typedef struct {
    /* 输入 */
    float v_alpha;          /* 电网电压alpha分量（标幺值） */
    float v_beta;           /* 电网电压beta分量（标幺值） */

    /* 内部状态 */
    float theta;            /* 估计相位（弧度） */
    float omega;            /* 估计角频率（rad/s） */
    float freq_hz;          /* 估计频率（Hz） */

    /* PI控制器状态 */
    float integrator;       /* 积分器累加值 */
    float kp;               /* 比例增益 */
    float ki;               /* 积分增益 */

    /* 输出 */
    float sin_theta;        /* sin(theta) */
    float cos_theta;        /* cos(theta) */
    float error;            /* 相位误差 */
} PLL_Handle;

/* ==================== 函数声明 ==================== */
static void PLL_Init(PLL_Handle *pll);
static void PLL_Update(PLL_Handle *pll, float v_alpha, float v_beta, float ts);
static float PLL_Clamp(float val, float min, float max);
static float PLL_Sin(float x);
static float PLL_Cos(float x);

/* ==================== 函数实现 ==================== */

/**
 * @brief 初始化PLL控制器
 */
static void PLL_Init(PLL_Handle *pll)
{
    pll->v_alpha    = 0.0f;
    pll->v_beta     = 0.0f;
    pll->theta      = 0.0f;
    pll->omega      = TWO_PI * FREQ_NOMINAL_HZ;
    pll->freq_hz    = FREQ_NOMINAL_HZ;
    pll->integrator = 0.0f;
    pll->kp         = PLL_KP;
    pll->ki         = PLL_KI;
    pll->sin_theta  = 0.0f;
    pll->cos_theta  = 1.0f;
    pll->error      = 0.0f;
}

/**
 * @brief 数值限幅
 */
static float PLL_Clamp(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

/**
 * @brief 泰勒级数近似sin（避免链接libm，也可直接用sinf）
 */
static float PLL_Sin(float x)
{
    /* 将x归一化到[-pi, pi] */
    while (x >  3.14159265359f) x -= TWO_PI;
    while (x < -3.14159265359f) x += TWO_PI;
    /* 7阶泰勒展开 */
    float x2 = x * x;
    float x3 = x2 * x;
    float x5 = x3 * x2;
    float x7 = x5 * x2;
    return x - x3 / 6.0f + x5 / 120.0f - x7 / 5040.0f;
}

/**
 * @brief 泰勒级数近似cos
 */
static float PLL_Cos(float x)
{
    while (x >  3.14159265359f) x -= TWO_PI;
    while (x < -3.14159265359f) x += TWO_PI;
    float x2 = x * x;
    float x4 = x2 * x2;
    float x6 = x4 * x2;
    return 1.0f - x2 / 2.0f + x4 / 24.0f - x6 / 720.0f;
}

/**
 * @brief PLL核心更新函数（SRF-PLL）
 *
 * 原理：
 *   1. 用估计相位theta对v_alpha/v_beta做Park变换，得到v_d/v_q
 *   2. v_q即为相位误差信号（当theta锁定时v_q=0）
 *   3. 通过PI控制器调节omega，使v_q趋于0
 *   4. 对omega积分得到theta
 *   5. 对omega限幅实现45Hz~55Hz频率自适应
 *
 * @param pll     PLL句柄
 * @param v_alpha 电网电压alpha分量
 * @param v_beta  电网电压beta分量
 * @param ts      控制周期（秒）
 */
static void PLL_Update(PLL_Handle *pll, float v_alpha, float v_beta, float ts)
{
    float v_d, v_q;
    float omega_cmd;
    float freq_cmd;

    /* 1. 保存输入 */
    pll->v_alpha = v_alpha;
    pll->v_beta  = v_beta;

    /* 2. 计算sin/cos */
    pll->sin_theta = PLL_Sin(pll->theta);
    pll->cos_theta = PLL_Cos(pll->theta);

    /* 3. Park变换：从alpha-beta到d-q */
    v_d =  v_alpha * pll->cos_theta + v_beta * pll->sin_theta;
    v_q = -v_alpha * pll->sin_theta + v_beta * pll->cos_theta;

    /* 4. 相位误差 = v_q（归一化后） */
    pll->error = v_q;

    /* 5. PI控制器：调节角频率 */
    pll->integrator += pll->ki * pll->error * ts;
    /* 积分限幅（防止饱和），对应频率范围45~55Hz */
    pll->integrator = PLL_Clamp(pll->integrator,
                                TWO_PI * (FREQ_MIN_HZ - FREQ_NOMINAL_HZ),
                                TWO_PI * (FREQ_MAX_HZ - FREQ_NOMINAL_HZ));

    omega_cmd = TWO_PI * FREQ_NOMINAL_HZ + pll->kp * pll->error + pll->integrator;

    /* 6. 频率限幅：45Hz ~ 55Hz（频率自适应核心） */
    freq_cmd = omega_cmd / TWO_PI;
    freq_cmd = PLL_Clamp(freq_cmd, FREQ_MIN_HZ, FREQ_MAX_HZ);
    pll->omega   = TWO_PI * freq_cmd;
    pll->freq_hz = freq_cmd;

    /* 7. 对omega积分得到theta */
    pll->theta += pll->omega * ts;

    /* 8. 相位归一化到[0, 2*pi) */
    while (pll->theta >= TWO_PI) pll->theta -= TWO_PI;
    while (pll->theta <  0.0f)   pll->theta += TWO_PI;

    (void)v_d; /* v_d可用于电压幅值估计，此处暂不使用 */
}

/* ==================== 主函数 ==================== */
int main(void)
{
    PLL_Handle pll;
    float t;
    float v_alpha, v_beta;
    float test_freq;
    int   i;
    int   print_cnt;

    printf("========================================\n");
    printf("  PLL Frequency Adaptive Control Test\n");
    printf("  Frequency Range: 45Hz ~ 55Hz\n");
    printf("========================================\n\n");

    /* 测试1：电网频率50Hz，验证锁定 */
    printf("--- Test 1: Grid frequency = 50.0 Hz ---\n");
    PLL_Init(&pll);
    test_freq = 50.0f;
    print_cnt = 0;
    for (i = 0; i < 2000; i++) {
        t = (float)i * PLL_TS;
        v_alpha = PLL_Cos(TWO_PI * test_freq * t);
        v_beta  = PLL_Sin(TWO_PI * test_freq * t);
        PLL_Update(&pll, v_alpha, v_beta, PLL_TS);

        if (i % 400 == 0) {
            printf("  t=%6.3fs  theta=%7.4f rad  freq=%8.4f Hz  err=%9.6f\n",
                   t, pll.theta, pll.freq_hz, pll.error);
            print_cnt++;
        }
    }
    printf("  Final: freq = %.4f Hz (expected 50.0000)\n\n", pll.freq_hz);

    /* 测试2：电网频率45Hz（下限），验证自适应 */
    printf("--- Test 2: Grid frequency = 45.0 Hz (lower limit) ---\n");
    PLL_Init(&pll);
    test_freq = 45.0f;
    for (i = 0; i < 3000; i++) {
        t = (float)i * PLL_TS;
        v_alpha = PLL_Cos(TWO_PI * test_freq * t);
        v_beta  = PLL_Sin(TWO_PI * test_freq * t);
        PLL_Update(&pll, v_alpha, v_beta, PLL_TS);

        if (i % 600 == 0) {
