    printf("  Final: freq = %.4f Hz (expected 45.0000)\n\n", pll.freq_hz);

    /* 测试3：电网频率55Hz（上限），验证自适应 */
    printf("--- Test 3: Grid frequency = 55.0 Hz (upper limit) ---\n");
