#include <stdio.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* ================= 模拟寄存器与宏定义 ================= */
#define PLL_KP              0.5f
#define PLL_KI              0.05f
#define PLL_TS              0.0001f
#define PLL_WC              2.0f * M_PI * 50.0f
#define PLL_WN              2.0f * M_PI * 20.0f
#define PLL_ZETA            0.707f
#define PLL_FILTER_ORDER    2

/* 模拟硬件寄存器 */
typedef struct {
    float theta;
    float omega;
    float integrator;
    float err;
    float sin_val;
    float cos_val;
    float comp_theta;
    float comp_omega;
    float delay_comp;
    float filter_delay;
    float phase_comp;
} PLL_Regs_t;

static PLL_Regs_t pll_regs;

/* ================= 滤波器延迟修正算法 ================= */
static float pll_calc_filter_delay(float omega)
{
    float wc = PLL_WC;
    float wn = PLL_WN;
    float zeta = PLL_ZETA;
    float delay;

    if (omega < 1e-6f) {
        omega = 1e-6f;
    }

    /* 二阶低通滤波器群延迟近似 */
    delay = (2.0f * zeta * omega) / (wn * wn);
    delay += (2.0f * zeta * wc) / (wn * wn);

    return delay;
}

static float pll_calc_phase_comp(float omega, float delay)
{
    float comp;

    comp = omega * delay;

    /* 限制补偿角度范围 */
    if (comp > M_PI / 4.0f) {
        comp = M_PI / 4.0f;
    } else if (comp < -M_PI / 4.0f) {
        comp = -M_PI / 4.0f;
    }

    return comp;
}

static void pll_phase_compensate(PLL_Regs_t *regs)
{
    float omega;
    float delay;
    float comp;

    omega = regs->omega;
    if (omega < 1e-6f) {
        omega = 1e-6f;
    }

    delay = pll_calc_filter_delay(omega);
    comp = pll_calc_phase_comp(omega, delay);

    regs->filter_delay = delay;
    regs->phase_comp = comp;
    regs->comp_theta = regs->theta + comp;
    regs->comp_omega = omega;

    /* 归一化补偿角度 */
    while (regs->comp_theta > M_PI) {
        regs->comp_theta -= 2.0f * M_PI;
    }
    while (regs->comp_theta < -M_PI) {
        regs->comp_theta += 2.0f * M_PI;
    }
}

/* ================= PLL 核心更新 ================= */
static void pll_update(PLL_Regs_t *regs, float input_sin, float input_cos)
{
    float err;
    float sin_val;
    float cos_val;
    float theta;

    theta = regs->theta;
    sin_val = sinf(theta);
    cos_val = cosf(theta);

    /* 鉴相器 */
    err = input_sin * cos_val - input_cos * sin_val;

    /* PI 控制器 */
    regs->integrator += PLL_KI * err * PLL_TS;
    regs->omega = PLL_KP * err + regs->integrator;

    /* 积分得到角度 */
    regs->theta += regs->omega * PLL_TS;

    /* 归一化 */
    while (regs->theta > M_PI) {
        regs->theta -= 2.0f * M_PI;
    }
    while (regs->theta < -M_PI) {
        regs->theta += 2.0f * M_PI;
    }

    regs->err = err;
    regs->sin_val = sin_val;
    regs->cos_val = cos_val;

    /* 相位补偿 */
    pll_phase_compensate(regs);
}

/* ================= 初始化 ================= */
static void pll_init(PLL_Regs_t *regs)
{
    regs->theta = 0.0f;
    regs->omega = 0.0f;
    regs->integrator = 0.0f;
    regs->err = 0.0f;
    regs->sin_val = 0.0f;
    regs->cos_val = 0.0f;
    regs->comp_theta = 0.0f;
    regs->comp_omega = 0.0f;
    regs->delay_comp = 0.0f;
    regs->filter_delay = 0.0f;
    regs->phase_comp = 0.0f;
}

/* ================= 主函数 ================= */
int main(void)
{
    float t;
    float input_sin;
    float input_cos;
    float freq;
    int i;

    pll_init(&pll_regs);

    printf("=== PLL Phase Compensation Test ===\n");
    printf("Time(s)  InputFreq(Hz)  PLL_Omega(rad/s)  FilterDelay(s)  PhaseComp(rad)  CompTheta(rad)\n");

    for (i = 0; i < 2000; i++) {
        t = (float)i * PLL_TS;

        /* 模拟输入信号：频率从 45Hz 渐变到 55Hz */
        freq = 45.0f + 10.0f * (float)i / 2000.0f;
        input_sin = sinf(2.0f * M_PI * freq * t);
        input_cos = cosf(2.0f * M_PI * freq * t);

        pll_update(&pll_regs, input_sin, input_cos);

        if (i % 200 == 0) {
            printf("%.4f   %.2f          %.4f            %.6f      %.6f      %.6f\n",
                   t,
                   freq,
                   pll_regs.omega,
                   pll_regs.filter_delay,
                   pll_regs.phase_comp,
                   pll_regs.comp_theta);
        }
    }

    printf("\n=== Final Results ===\n");
    printf("PLL Omega:        %.4f rad/s\n", pll_regs.omega);
    printf("Filter Delay:     %.6f s\n", pll_regs.filter_delay);
    printf("Phase Comp:       %.6f rad\n", pll_regs.phase_comp);
    printf("Compensated Theta:%.6f rad\n", pll_regs.comp_theta);
    printf("Phase Error:      %.6f rad\n", pll_regs.err);

    return 0;
}
