```c
#include <stdio.h>
#include <math.h>

/* ============================================================
 * 模拟寄存器与常量定义（不依赖任何单片机头文件）
 * ============================================================ */
#define PI                  3.14159265358979323846f
#define TWO_PI              (2.0f * PI)

/* 模拟电网角频率：50Hz -> 314.159 rad/s */
#define GRID_OMEGA_NOM      314.159265f

/* 模拟采样周期：10kHz -> 100us */
#define TS                  0.0001f

/* PLL 环路参数（典型值，可调） */
#define PLL_KP              120.0f
#define PLL_KI              4000.0f

/* 抗相位跳变阻尼控制参数 */
#define DAMP_GAIN           0.85f       /* 阻尼增益（0~1） */
#define DAMP_THRESHOLD      0.15f       /* 相位误差阈值(rad)，超过则启用阻尼 */
#define DAMP_RECOVER_RATE   0.02f       /* 阻尼系数恢复速率 */

/* ============================================================
 * PLL 结构体
 * ============================================================ */
typedef struct {
    /* 输入 */
    float theta_grid;       /* 电网实际相位（模拟用） */

    /* 状态变量 */
    float theta_pll;        /* PLL 估计相位 */
    float omega_pll;        /* PLL 估计角频率 */
    float integrator;       /* PI 积分器状态 */

    /* 阻尼控制状态 */
    float damp_factor;      /* 当前阻尼系数（0~1） */
    float phase_error;      /* 相位误差 */
    float phase_error_prev; /* 上一拍相位误差 */
    float freq_error;       /* 频率误差 */

    /* 输出 */
    float sin_theta;        /* sin(theta_pll) */
    float cos_theta;        /* cos(theta_pll) */
} PLL_TypeDef;

/* ============================================================
 * 初始化 PLL
 * ============================================================ */
void PLL_Init(PLL_TypeDef *pll)
{
    pll->theta_grid       = 0.0f;
    pll->theta_pll        = 0.0f;
    pll->omega_pll        = GRID_OMEGA_NOM;
    pll->integrator       = 0.0f;
    pll->damp_factor      = 1.0f;
    pll->phase_error      = 0.0f;
    pll->phase_error_prev = 0.0f;
    pll->freq_error       = 0.0f;
    pll->sin_theta        = 0.0f;
    pll->cos_theta        = 1.0f;
}

/* ============================================================
 * 角度归一化到 [-PI, PI]
 * ============================================================ */
static float wrap_pi(float angle)
{
    while (angle > PI)  angle -= TWO_PI;
    while (angle < -PI) angle += TWO_PI;
    return angle;
}

/* ============================================================
 * PLL 抗相位跳变阻尼控制核心算法
 *
 * 原理：
 *   1. 用 Park 变换得到相位误差 err = sin(theta_grid - theta_pll)
 *   2. 当 |err| 超过阈值时，判定发生相位跳变
 *   3. 通过阻尼系数 damp_factor 动态衰减 PI 输出，
 *      抑制相位跳变引起的频率/相位剧烈振荡
 *   4. 跳变结束后 damp_factor 逐渐恢复到 1
 * ============================================================ */
void PLL_Update(PLL_TypeDef *pll, float theta_grid)
{
    float sin_err, cos_err;
    float pi_out;
    float omega_cmd;
    float err;

    /* ---------- 1. 计算相位误差（Park 变换） ---------- */
    sin_err = sinf(theta_grid - pll->theta_pll);
    cos_err = cosf(theta_grid - pll->theta_pll);

    /* 小角度近似：err ≈ sin(err) */
    err = sin_err;

    /* 保存上一拍误差用于频率误差估计 */
    pll->phase_error_prev = pll->phase_error;
    pll->phase_error      = err;

    /* ---------- 2. 相位跳变检测与阻尼系数更新 ---------- */
    if (fabsf(err) > DAMP_THRESHOLD) {
        /* 检测到相位跳变：立即降低阻尼系数 */
        pll->damp_factor = DAMP_GAIN;
    } else {
        /* 无跳变：阻尼系数逐渐恢复到 1 */
        pll->damp_factor += DAMP_RECOVER_RATE;
        if (pll->damp_factor > 1.0f) {
            pll->damp_factor = 1.0f;
        }
    }

    /* ---------- 3. PI 调节器（带阻尼衰减） ---------- */
    /* 比例项 */
    float p_term = PLL_KP * err;

    /* 积分项（带阻尼衰减，抑制跳变时的积分饱和） */
    pll->integrator += PLL_KI * err * TS * pll->damp_factor;

    /* 积分限幅（防止 windup） */
    if (pll->integrator >  500.0f) pll->integrator =  500.0f;
    if (pll->integrator < -500.0f) pll->integrator = -500.0f;

    /* PI 输出 = 比例 + 积分，整体乘以阻尼系数 */
    pi_out = (p_term + pll->integrator) * pll->damp_factor;

    /* ---------- 4. 频率估计 ---------- */
    omega_cmd = GRID_OMEGA_NOM + pi_out;

    /* 频率限幅（防止频率估计发散） */
    if (omega_cmd > GRID_OMEGA_NOM * 1.5f) omega_cmd = GRID_OMEGA_NOM * 1.5f;
    if (omega_cmd < GRID_OMEGA_NOM * 0.5f) omega_cmd = GRID_OMEGA_NOM * 0.5f;

    pll->omega_pll = omega_cmd;

    /* 频率误差（用于调试） */
    pll->freq_error = omega_cmd - GRID_OMEGA_NOM;

    /* ---------- 5. 相位积分 ---------- */
    pll->theta_pll += omega_cmd * TS;
    pll->theta_pll = wrap_pi(pll->theta_pll);

    /* ---------- 6. 输出正余弦 ---------- */
    pll->sin_theta = sinf(pll->theta_pll);
    pll->cos_theta = cosf(pll->theta_pll);
}

/* ============================================================
 * 模拟电网相位发生器（用于测试）
 * ============================================================ */
static float grid_phase_gen(float t, float phase_jump_time, float phase_jump_rad)
{
    float theta = GRID_OMEGA_NOM * t;
    if (t >= phase_jump_time) {
        theta += phase_jump_rad;
    }
    return wrap_pi(theta);
}

/* ============================================================
 * main 函数：测试 PLL 抗相位跳变阻尼控制
 * ============================================================ */
int main(void)
{
    PLL_TypeDef pll;
    float t;
    int   step;
    int   total_steps = 2000;       /* 2000 * 100us = 200ms */
    float phase_jump_time = 0.05f;  /* 50ms 处发生相位跳变 */
    float phase_jump_rad  = 0.8f;   /* 跳变 0.8 rad ≈ 45.8° */

    printf("========================================\n");
    printf("  PLL Anti-Phase-Jump Damping Control\n");
    printf("========================================\n");
    printf("Ts = %.1f us, Kp = %.1f, Ki = %.1f\n",
           TS * 1e6f, PLL_KP, PLL_KI);
    printf("Phase jump: %.2f rad at t = %.1f ms\n",
           phase_jump_rad, phase_jump_time * 1000.0f);
    printf("----------------------------------------\n");
    printf("  t(ms)   theta_grid  theta_pll   err(rad)  damp   freq_err\n");
    printf("----------------------------------------\n");

    PLL_Init(&pll);

    for (step = 0; step < total_steps; step++) {
        t = step * TS;

        /* 生成电网相位（含相位跳变） */
        float theta_grid = grid_phase_gen(t, phase_jump_time, phase_jump_rad);

        /* 执行 PLL 更新 */
        PLL_Update(&pll, theta_grid);

        /* 每 100 步（10ms）打印一次 */
        if (step % 100 == 0) {
            printf("%7.2f  %9.4f  %9.4f  %8.4f  %5.2f  %8.2f\n",
                   t * 1000.0f,
                   theta_grid,
                   pll.theta_pll,
                   pll.phase_error,
                   pll.damp_factor,
                   pll.freq_error);
        }
    }

    printf("----------------------------------------\n");
    printf("Final: theta_pll = %.4f rad, omega_pll = %.2f rad/s\n",
           pll.theta_pll, pll.omega_pll);
    printf("Damping factor recovered to: %.2f\n", pll.damp_factor);
    printf("========================================\n");

    return 0;
}
