#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层 (HAL) 定义
 * 使用普通全局变量替代硬编码地址，避免非法内存访问
 * ============================================================ */
static volatile int32_t  g_mock_adc_phase_err  = 0;
static volatile int32_t  g_mock_pll_phase_comp = 0;
static volatile int32_t  g_mock_pll_freq_word  = 0;
static volatile uint32_t g_mock_pll_status     = 0;

#define MOCK_REG_ADC_PHASE_ERR      (g_mock_adc_phase_err)
#define MOCK_REG_PLL_PHASE_COMP     (g_mock_pll_phase_comp)
#define MOCK_REG_PLL_FREQ_WORD      (g_mock_pll_freq_word)
#define MOCK_REG_PLL_STATUS         (g_mock_pll_status)

#define PLL_STATUS_LOCKED           (1U << 0)
#define PLL_STATUS_ERR_VALID        (1U << 1)

/* ============================================================
 * 系统参数定义
 * ============================================================ */
#define PI                          3.14159265358979323846f
#define TWO_PI                      (2.0f * PI)

/* 相位误差补偿参数 */
#define PHASE_ERR_GAIN_KP           0.05f
#define PHASE_ERR_GAIN_KI           0.001f
#define PHASE_ERR_DEADBAND          0.001f
#define PHASE_ERR_MAX_COMP          0.5f
#define PHASE_ERR_MIN_COMP          (-0.5f)

/* 采样与滤波参数 */
#define PHASE_ERR_FILTER_ALPHA      0.1f
#define CALIB_SAMPLE_COUNT          1000

/* ============================================================
 * 数据结构定义
 * ============================================================ */
typedef struct {
    float phase_err_raw;
    float phase_err_filtered;
    float phase_comp;
    float integral;
    float kp;
    float ki;
    float deadband;
    float max_comp;
    float min_comp;
    float filter_alpha;
    uint32_t sample_cnt;
    uint8_t  initialized;
} PLL_PhaseCalib_t;

/* ============================================================
 * 函数声明
 * ============================================================ */
static void PLL_PhaseCalib_Init(PLL_PhaseCalib_t *calib);
static float PLL_PhaseCalib_Update(PLL_PhaseCalib_t *calib, float phase_err);
static float PLL_PhaseCalib_GetCompensation(const PLL_PhaseCalib_t *calib);
static void PLL_PhaseCalib_Reset(PLL_PhaseCalib_t *calib);
static float PLL_PhaseCalib_NormalizeAngle(float angle);

/* ============================================================
 * 函数实现
 * ============================================================ */

static void PLL_PhaseCalib_Init(PLL_PhaseCalib_t *calib)
{
    if (calib == NULL) {
        return;
    }

    calib->phase_err_raw      = 0.0f;
    calib->phase_err_filtered = 0.0f;
    calib->phase_comp         = 0.0f;
    calib->integral           = 0.0f;
    calib->kp                 = PHASE_ERR_GAIN_KP;
    calib->ki                 = PHASE_ERR_GAIN_KI;
    calib->deadband           = PHASE_ERR_DEADBAND;
    calib->max_comp           = PHASE_ERR_MAX_COMP;
    calib->min_comp           = PHASE_ERR_MIN_COMP;
    calib->filter_alpha       = PHASE_ERR_FILTER_ALPHA;
    calib->sample_cnt         = 0U;
    calib->initialized        = 1U;
}

static void PLL_PhaseCalib_Reset(PLL_PhaseCalib_t *calib)
{
    if (calib == NULL) {
        return;
    }

    calib->phase_err_raw      = 0.0f;
    calib->phase_err_filtered = 0.0f;
    calib->phase_comp         = 0.0f;
    calib->integral           = 0.0f;
    calib->sample_cnt         = 0U;
}

static float PLL_PhaseCalib_NormalizeAngle(float angle)
{
    /* 使用 fmodf 避免 while 死循环风险 */
    if (angle > PI || angle < -PI) {
        angle = fmodf(angle + PI, TWO_PI);
        if (angle < 0.0f) {
            angle += TWO_PI;
        }
        angle -= PI;
    }
    return angle;
}

static float PLL_PhaseCalib_Update(PLL_PhaseCalib_t *calib, float phase_err)
{
    float err;
    float p_term;
    float i_term;

    if (calib == NULL || calib->initialized == 0U) {
        return 0.0f;
    }

    /* 1. 归一化输入相位误差 */
    err = PLL_PhaseCalib_NormalizeAngle(phase_err);
    calib->phase_err_raw = err;

    /* 2. 一阶低通滤波 */
    calib->phase_err_filtered = calib->filter_alpha * err
                              + (1.0f - calib->filter_alpha) * calib->phase_err_filtered;

    /* 3. 死区处理 */
    if (fabsf(calib->phase_err_filtered) < calib->deadband) {
        calib->phase_err_filtered = 0.0f;
    }

    /* 4. PI 控制器 */
    p_term = calib->kp * calib->phase_err_filtered;

    calib->integral += calib->ki * calib->phase_err_filtered;
    i_term = calib->integral;

    /* 5. 计算补偿量并限幅 */
    calib->phase_comp = p_term + i_term;

    if (calib->phase_comp > calib->max_comp) {
        calib->phase_comp = calib->max_comp;
        calib->integral = calib->max_comp - p_term;
    } else if (calib->phase_comp < calib->min_comp) {
        calib->phase_comp = calib->min_comp;
        calib->integral = calib->min_comp - p_term;
    }

    /* 6. 采样计数 */
    calib->sample_cnt++;

    return calib->phase_comp;
}

static float PLL_PhaseCalib_GetCompensation(const PLL_PhaseCalib_t *calib)
{
    if (calib == NULL) {
        return 0.0f;
    }
    return calib->phase_comp;
}

/* ============================================================
 * 主函数 - 测试打印
 * ============================================================ */
int main(void)
{
    PLL_PhaseCalib_t calib;
    float test_errors[] = {
        0.0f,
        0.01f,
        0.05f,
        0.1f,
        -0.02f,
        -0.08f,
        0.15f,
        0.3f,
        -0.25f,
        0.0f
    };
    int i;
    int n;

    printf("========================================\n");
    printf("  PLL Phase Calibration Test\n");
    printf("========================================\n\n");

    PLL_PhaseCalib_Init(&calib);

    printf("Calib Params: Kp=%.4f, Ki=%.4f, Deadband=%.4f\n",
           calib.kp, calib.ki, calib.deadband);
    printf("Filter Alpha=%.2f, Comp Range=[%.2f, %.2f]\n\n",
           calib.filter_alpha, calib.min_comp, calib.max_comp);

    printf("%-6s %-14s %-14s %-14s %-14s\n",
           "Step", "RawErr(rad)", "FiltErr(rad)", "Comp(rad)", "Integral");
    printf("--------------------------------------------------------------\n");

    n = (int)(sizeof(test_errors) / sizeof(test_errors[0]));

    for (i = 0; i < n; i++) {
        float comp;

        MOCK_REG_ADC_PHASE_ERR = (int32_t)(test_errors[i] * 1000000.0f);

        comp = PLL_PhaseCalib_Update(&calib, test_errors[i]);

        MOCK_REG_PLL_PHASE_COMP = (int32_t)(comp * 1000000.0f);

