    }

    printf("--------------------------------------------------------------\n");
    printf("Final Compensation: %.6f rad\n", PLL_PhaseCalib_GetCompensation(&calib));
    printf("Total Samples: %u\n", calib.sample_cnt);

    printf("\n--- Reset Test ---\n");
    PLL_PhaseCalib_Reset(&calib);
