#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint16_t mock_adc_dr = 0;
static volatile uint32_t mock_adc_sr = 0;
static volatile uint32_t mock_adc_cr = 0;
static volatile uint32_t mock_tim_cnt = 0;
static volatile uint32_t mock_tim_psc = 0;
static volatile uint32_t mock_tim_arr = 0;
static volatile uint32_t mock_tim_cr = 0;
static volatile uint32_t mock_gpio_odr = 0;
static volatile uint32_t mock_gpio_idr = 0;

#define MOCK_ADC_DR         (mock_adc_dr)
#define MOCK_ADC_SR         (mock_adc_sr)
#define MOCK_ADC_CR         (mock_adc_cr)
#define MOCK_TIM_CNT        (mock_tim_cnt)
#define MOCK_TIM_PSC        (mock_tim_psc)
#define MOCK_TIM_ARR        (mock_tim_arr)
#define MOCK_TIM_CR         (mock_tim_cr)
#define MOCK_GPIO_ODR       (mock_gpio_odr)
#define MOCK_GPIO_IDR       (mock_gpio_idr)

#define ADC_CR_EN           (1U << 0)
#define ADC_CR_START        (1U << 1)
#define ADC_SR_EOC          (1U << 0)
#define TIM_CR_EN           (1U << 0)

/* ================= 系统参数 ================= */
#define ADC_FS_HZ           10000.0f
#define GRID_NOMINAL_HZ     50.0f
#define GRID_MIN_HZ         45.0f
#define GRID_MAX_HZ         55.0f
#define ADC_MID_SCALE       2048.0f
#define ADC_FULL_SCALE      4095.0f
#define ZC_HYSTERESIS       30.0f
#define LPF_ALPHA           0.15f
#define PLL_KP              0.08f
#define PLL_KI              0.002f
#define TWO_PI              6.28318530718f
#define PI                  3.14159265359f

/* ================= 数据结构 ================= */
typedef struct {
    float    adc_raw;
    float    adc_filtered;
    float    adc_prev;
    int      zc_sign;
    int      zc_sign_prev;
    uint32_t zc_timestamp;
    uint32_t zc_timestamp_prev;
    uint32_t zc_period;
    uint32_t zc_period_filtered;
    int      zc_valid;
    int      zc_count;

    float    lpf_state;

    float    pll_phase;
    float    pll_freq;
    float    pll_integ;
    float    phase_error;
    float    freq_error;

    float    grid_freq;
    float    grid_phase;
    float    grid_amplitude;
    float    sin_ref;
    float    cos_ref;
} SPLL_Handle;

/* ================= 初始化 ================= */
static void SPLL_Init(SPLL_Handle *spll)
{
    spll->adc_raw            = ADC_MID_SCALE;
    spll->adc_filtered       = ADC_MID_SCALE;
    spll->adc_prev           = ADC_MID_SCALE;
    spll->zc_sign            = 1;
    spll->zc_sign_prev       = 1;
    spll->zc_timestamp       = 0;
    spll->zc_timestamp_prev  = 0;
    spll->zc_period          = (uint32_t)(ADC_FS_HZ / GRID_NOMINAL_HZ);
    spll->zc_period_filtered = spll->zc_period;
    spll->zc_valid           = 0;
    spll->zc_count           = 0;

    spll->lpf_state          = ADC_MID_SCALE;

    spll->pll_phase          = 0.0f;
    spll->pll_freq           = GRID_NOMINAL_HZ;
    spll->pll_integ          = 0.0f;
    spll->phase_error        = 0.0f;
    spll->freq_error         = 0.0f;

    spll->grid_freq          = GRID_NOMINAL_HZ;
    spll->grid_phase         = 0.0f;
    spll->grid_amplitude     = 0.0f;
    spll->sin_ref            = 0.0f;
    spll->cos_ref            = 1.0f;
}

/* ================= 一阶低通数字滤波 ================= */
static float LPF_Update(SPLL_Handle *spll, float input)
{
    spll->lpf_state = spll->lpf_state + LPF_ALPHA * (input - spll->lpf_state);
    return spll->lpf_state;
}

/* ================= 过零检测 ================= */
static int ZC_Detect(SPLL_Handle *spll, float filtered_val, uint32_t timestamp)
{
    float centered = filtered_val - ADC_MID_SCALE;
    int   new_sign;
    int   zero_cross = 0;

    if (centered > ZC_HYSTERESIS) {
        new_sign = 1;
    } else if (centered < -ZC_HYSTERESIS) {
        new_sign = -1;
    } else {
        new_sign = spll->zc_sign;
    }

    if (spll->zc_sign == -1 && new_sign == 1) {
        zero_cross = 1;
        spll->zc_timestamp_prev = spll->zc_timestamp;
        spll->zc_timestamp = timestamp;

        if (spll->zc_timestamp_prev != 0) {
            uint32_t period = spll->zc_timestamp - spll->zc_timestamp_prev;
            if (period > 0) {
                float freq = ADC_FS_HZ / (float)period;
                if (freq >= GRID_MIN_HZ && freq <= GRID_MAX_HZ) {
                    spll->zc_period = period;
                    spll->zc_period_filtered = (uint32_t)(
                        (float)spll->zc_period_filtered * 0.7f +
                        (float)period * 0.3f
                    );
                    if (spll->zc_period_filtered == 0) {
                        spll->zc_period_filtered = period;
                    }
                    spll->zc_valid = 1;
                    spll->zc_count++;
                }
            }
        }
    }

    spll->zc_sign_prev = spll->zc_sign;
    spll->zc_sign = new_sign;
    return zero_cross;
}

/* ================= 锁相环更新 ================= */
static void PLL_Update(SPLL_Handle *spll, float dt)
{
    float freq_from_zc;
    float target_freq;

    if (spll->zc_valid && spll->zc_period_filtered > 0) {
        freq_from_zc = ADC_FS_HZ / (float)spll->zc_period_filtered;
    } else {
        freq_from_zc = GRID_NOMINAL_HZ;
    }

    if (freq_from_zc < GRID_MIN_HZ) freq_from_zc = GRID_MIN_HZ;
    if (freq_from_zc > GRID_MAX_HZ) freq_from_zc = GRID_MAX_HZ;

    target_freq = freq_from_zc;

    spll->freq_error = target_freq - spll->pll_freq;

    spll->pll_integ += PLL_KI * spll->freq_error * dt;
    if (spll->pll_integ > 5.0f)  spll->pll_integ = 5.0f;
    if (spll->pll_integ < -5.0f) spll->pll_integ = -5.0f;

    spll->pll_freq = GRID_NOMINAL_HZ + PLL_KP * spll->freq_error + spll->pll_integ;

    if (spll->pll_freq < GRID_MIN_HZ) spll->pll_freq = GRID_MIN_HZ;
    if (spll->pll_freq > GRID_MAX_HZ) spll->pll_freq = GRID_MAX_HZ;

    spll->pll_phase += TWO_PI * spll->pll_freq * dt;
    while (spll->pll_phase >= TWO_PI) spll->pll_phase -= TWO_PI;
    while (spll->pll_phase < 0.0f)    spll->pll_phase += TWO_PI;

    spll->grid_freq  = spll->pll_freq;
    spll->grid_phase = spll->pll_phase;
    spll->sin_ref    = sinf(spll->pll_phase);
    spll->cos_ref    = cosf(spll->pll_phase);
}

/* ================= 幅值估计 ================= */
static void Amplitude_Estimate(SPLL_Handle *spll, float filtered_val)
{
    float centered = filtered_val - ADC_MID_SCALE;
    float abs_val = fabsf(centered);

    if (abs_val > spll->grid_amplitude) {
        spll->grid_amplitude = abs_val;
    } else {
        spll->grid_amplitude = spll->grid_amplitude * 0.999f + abs_val * 0.001f;
    }
}

/* ================= 主处理函数 ================= */
static void SPLL_Process(SPLL_Handle *spll, float adc_val, uint32_t timestamp)
{
    float dt = 1.0f / ADC_FS_HZ;

    spll->adc_raw = adc_val;
    spll->adc_filtered = LPF_Update(spll, adc_val);

    ZC_Detect(spll, spll->adc_filtered, timestamp);

    PLL_Update(spll, dt);

    Amplitude_Estimate(spll, spll->adc_filtered);

    spll->adc_prev = spll->adc_filtered;
}

/* ================= Mock 硬件初始化 ================= */
static void Mock_Hardware_Init(void)
{
    MOCK_ADC_CR = ADC_CR_EN;
    MOCK_TIM_PSC = 0;
    MOCK_TIM_ARR = 1000;
    MOCK_TIM_CR = TIM_CR_EN;
    MOCK_GPIO_ODR = 0;
}

/* ================= 模拟 ADC 读取 ================= */
static float Mock_ADC_Read(uint32_t sample_idx)
{
    float t = (float)sample_idx / ADC_FS_HZ;
    float freq = 50.0f;
    float amplitude = 1500.0f;
    float noise = 20.0f * sinf(TWO_PI * 300.0f * t);
    float val = ADC_MID_SCALE + amplitude * sinf(TWO_PI * freq * t) + noise;

    if (val < 0.0f) val = 0.0f;
    if (val > ADC_FULL_SCALE) val = ADC_FULL_SCALE;
    return val;
}

/* ================= 主函数 ================= */
int main(void)
{
    SPLL_Handle spll;
    uint32_t i;
    uint32_t total_samples = 2000;

    printf("========================================\n");
    printf("  单相锁相环 (过零检测 + 数字滤波)\n");
    printf("========================================\n\n");

    Mock_Hardware_Init();
    SPLL_Init(&spll);

    printf("采样率: %.0f Hz\n", ADC_FS_HZ);
    printf("标称频率: %.1f Hz\n", GRID_NOMINAL_HZ);
    printf("LPF 系数: %.2f\n", LPF_ALPHA);
    printf("PLL KP: %.3f, KI: %.4f\n\n", PLL_KP, PLL_KI);

    printf("--- 开始处理 ---\n");
    printf("采样点\tADC原始\tADC滤波\t过零\t频率(Hz)\t相位(rad)\t幅值\n");

    for (i = 0; i < total_samples; i++) {
        float adc_val = Mock_ADC_Read(i);
        uint32_t timestamp = i;

        MOCK_ADC_DR = (uint16_t)adc_val;
        MOCK_ADC_SR |= ADC_SR_EOC;

        SPLL_Process(&spll, adc_val, timestamp);

        if (i % 200 == 0) {
            printf("%lu\t%.0f\t%.1f\t%s\t%.3f\t\t%.3f\t\t%.0f\n",
                   (unsigned long)i,
                   spll.adc_raw,
                   spll.adc_filtered,
                   (spll.zc_sign == 1) ? "+" : "-",
                   spll.grid_freq,
                   spll.grid_phase,
                   spll.grid_amplitude);
        }
    }

    printf("\n--- 处理完成 ---\n");
    printf("有效过零次数: %d\n", spll.zc_count);
    printf("最终频率估计: %.3f Hz\n", spll.grid_freq);
    printf("最终相位估计: %.3f rad\n", spll.grid_phase);
    printf("最终幅值估计: %.0f (ADC counts)\n", spll.grid_amplitude);
    printf("过零周期(滤波): %lu 采样点\n", (unsigned long)spll.zc_period_filtered);

    if (spll.zc_period_filtered > 0) {
        printf("对应频率: %.3f Hz\n", ADC_FS_HZ / (float)spll.zc_period_filtered);
    } else {
        printf("对应频率: N/A\n");
    }

    {
        float freq_error = fabsf(spll.grid_freq - 50.0f);
        printf("\n频率误差: %.4f Hz\n", freq_error);
        if (freq_error < 0.5f) {
            printf("结果: 锁相环锁定成功 [PASS]\n");
        } else {
            printf("结果: 锁相环未锁定 [FAIL]\n");
        }
    }

    return 0;
}
