#define PLL_LOCKED          (1u << 0)
#define PLL_FREQ_ERR_HIGH   (1u << 1)
#define PLL_PHASE_ERR_HIGH  (1u << 2)

/* ===== 参数定义 ===== */
#define FREQ_ERR_FAST_TH    50.0f
#define FREQ_ERR_STABLE_TH  5.0f
#define PHASE_ERR_FAST_TH   0.5f
#define PHASE_ERR_STABLE_TH 0.05f
#define FAST_KP             0.8f
#define FAST_KI             0.3f
#define STABLE_KP           0.2f
#define STABLE_KI           0.05f
#define TS                  0.001f

/* ===== PLL 控制器结构体 ===== */
typedef struct {
    float freq_ref;
    float freq_fb;
    float phase_ref;
    float phase_fb;
    float freq_err;
    float phase_err;
    float integral;
    float output;
    int   track_mode;
    int   locked;
} PLL_Controller;

/* ===== 函数声明 ===== */
static void PLL_Init(PLL_Controller *pll);
static void PLL_UpdateFeedback(PLL_Controller *pll, float freq, float phase);
static void PLL_SelectTrackMode(PLL_Controller *pll);
static void PLL_Compute(PLL_Controller *pll);
static void PLL_ApplyOutput(PLL_Controller *pll);
static void PLL_PrintStatus(PLL_Controller *pll, int step);

/* ===== 初始化 ===== */
static void PLL_Init(PLL_Controller *pll)
{
    pll->freq_ref   = 50.0f;
    pll->freq_fb    = 0.0f;
    pll->phase_ref  = 0.0f;
    pll->phase_fb   = 0.0f;
    pll->freq_err   = 0.0f;
    pll->phase_err  = 0.0f;
    pll->integral   = 0.0f;
    pll->output     = 0.0f;
    pll->track_mode = 0;
    pll->locked     = 0;

    PLL_CTRL_REG = PLL_ENABLE | PLL_STABLE_TRACK;
}

/* ===== 更新反馈量 ===== */
static void PLL_UpdateFeedback(PLL_Controller *pll, float freq, float phase)
{
    pll->freq_fb  = freq;
    pll->phase_fb = phase;
}

/* ===== 跟踪模式选择 ===== */
static void PLL_SelectTrackMode(PLL_Controller *pll)
{
    float abs_freq_err  = fabsf(pll->freq_err);
    float abs_phase_err = fabsf(pll->phase_err);

    if (abs_freq_err > FREQ_ERR_FAST_TH || abs_phase_err > PHASE_ERR_FAST_TH) {
        pll->track_mode = 1;
        PLL_CTRL_REG = (PLL_CTRL_REG & ~PLL_STABLE_TRACK) | PLL_FAST_TRACK;
    } else if (abs_freq_err < FREQ_ERR_STABLE_TH && abs_phase_err < PHASE_ERR_STABLE_TH) {
        pll->track_mode = 0;
        PLL_CTRL_REG = (PLL_CTRL_REG & ~PLL_FAST_TRACK) | PLL_STABLE_TRACK;
    }
}

/* ===== 核心控制计算 ===== */
static void PLL_Compute(PLL_Controller *pll)
{
    float kp, ki;

    pll->freq_err  = pll->freq_ref  - pll->freq_fb;
    pll->phase_err = pll->phase_ref - pll->phase_fb;

    PLL_SelectTrackMode(pll);

    if (pll->track_mode == 1) {
        kp = FAST_KP;
        ki = FAST_KI;
    } else {
        kp = STABLE_KP;
        ki = STABLE_KI;
    }

    pll->integral += ki * pll->phase_err * TS;
    pll->output = kp * pll->phase_err + pll->integral;

    if (pll->output > 100.0f)  pll->output = 100.0f;
    if (pll->output < -100.0f) pll->output = -100.0f;

    if (fabsf(pll->freq_err) < FREQ_ERR_STABLE_TH &&
        fabsf(pll->phase_err) < PHASE_ERR_STABLE_TH) {
        pll->locked = 1;
        PLL_STATUS_REG |= PLL_LOCKED;
    } else {
        pll->locked = 0;
        PLL_STATUS_REG &= ~PLL_LOCKED;
    }
}

/* ===== 输出到硬件 ===== */
static void PLL_ApplyOutput(PLL_Controller *pll)
{
    PLL_FREQ_REG  = (unsigned int)(pll->freq_ref * 1000.0f);
    PLL_PHASE_REG = (unsigned int)(pll->output * 100.0f);
}

/* ===== 打印状态 ===== */
static void PLL_PrintStatus(PLL_Controller *pll, int step)
{
    printf("Step %2d | Mode: %s | FreqErr: %7.3f Hz | PhaseErr: %7.4f rad | "
           "Output: %7.3f | Locked: %s\n",
           step,
           pll->track_mode ? "FAST" : "STABLE",
           pll->freq_err,
           pll->phase_err,
           pll->output,
           pll->locked ? "YES" : "NO");
}

/* ===== 主函数 ===== */
int main(void)
{
    PLL_Controller pll;
    int step;
    float sim_freq;
    float sim_phase;

    printf("===== PLL Frequency Tracking Speed Control =====\n\n");

    PLL_Init(&pll);

    for (step = 0; step < 30; step++) {
        float decay = expf(-0.15f * (float)step);
        sim_freq  = pll.freq_ref - 80.0f * decay;
        sim_phase = pll.phase_ref - 0.8f * decay;

        PLL_UpdateFeedback(&pll, sim_freq, sim_phase);
        PLL_Compute(&pll);
        PLL_ApplyOutput(&pll);
        PLL_PrintStatus(&pll, step);
    }

    printf("\n===== Final Status =====\n");
    printf("Track Mode : %s\n", pll.track_mode ? "FAST" : "STABLE");
    printf("Locked     : %s\n", pll.locked ? "YES" : "NO");
    printf("Freq Error : %.4f Hz\n", pll.freq_err);
    printf("Phase Error: %.4f rad\n", pll.phase_err);

    return 0;
}
