/* ================= Mock 寄存器与硬件抽象 ================= */
#define MOCK_TIMER_COUNT_REG    (*(volatile uint32_t*)0x40000000)
#define MOCK_TIMER_STATUS_REG   (*(volatile uint32_t*)0x40000004)
#define MOCK_TIMER_CTRL_REG     (*(volatile uint32_t*)0x40000008)

#define TIMER_START()           (MOCK_TIMER_CTRL_REG |= 0x01)
#define TIMER_STOP()            (MOCK_TIMER_CTRL_REG &= ~0x01)
#define TIMER_RESET()           (MOCK_TIMER_COUNT_REG = 0)
#define TIMER_GET_COUNT()       (MOCK_TIMER_COUNT_REG)
#define TIMER_CAPTURE_FLAG()    (MOCK_TIMER_STATUS_REG & 0x01)
#define TIMER_CLEAR_FLAG()      (MOCK_TIMER_STATUS_REG &= ~0x01)

/* 模拟定时器时钟频率 (Hz) */
#define TIMER_CLK_FREQ          1000000.0f

/* ================= PLL 与频率测量结构体 ================= */
typedef struct {
    /* PLL 参数 */
    float kp;               /* 比例增益 */
    float ki;               /* 积分增益 */
    float integrator;       /* 积分器状态 */
    float phase_error;      /* 相位误差 */
    float freq_est;         /* 频率估计值 (Hz) */
    float phase_est;        /* 相位估计值 (rad) */
    float omega_nom;        /* 额定角频率 (rad/s) */
    float ts;               /* 控制周期 (s) */

    /* 周期计数法频率测量 */
    uint32_t last_capture;  /* 上次捕获计数值 */
    uint32_t period_count;  /* 周期计数值 */
    float freq_meas;        /* 测量频率 (Hz) */
    uint8_t capture_ready;  /* 捕获就绪标志 */

    /* 输出 */
    float freq_out;         /* 融合后频率输出 */
    float phase_out;        /* 输出相位 */
} PLL_FreqMeas_t;

/* ================= 初始化 ================= */
void PLL_FreqMeas_Init(PLL_FreqMeas_t *pll, float kp, float ki,
                       float omega_nom, float ts)
{
    pll->kp = kp;
    pll->ki = ki;
    pll->integrator = 0.0f;
    pll->phase_error = 0.0f;
    pll->freq_est = omega_nom / (2.0f * 3.14159265358979323846f);
    pll->phase_est = 0.0f;
    pll->omega_nom = omega_nom;
    pll->ts = ts;

    pll->last_capture = 0;
    pll->period_count = 0;
    pll->freq_meas = 0.0f;
    pll->capture_ready = 0;

    pll->freq_out = pll->freq_est;
    pll->phase_out = 0.0f;
}

/* ================= 周期计数法频率测量 ================= */
/* 模拟输入信号过零点捕获，返回测量频率 */
float PeriodCount_MeasureFreq(PLL_FreqMeas_t *pll, uint32_t capture_val)
{
    uint32_t period;

    if (pll->last_capture == 0) {
        pll->last_capture = capture_val;
        return pll->freq_meas;
    }

    /* 计算周期计数值（处理计数器溢出） */
    if (capture_val >= pll->last_capture) {
        period = capture_val - pll->last_capture;
    } else {
        period = (0xFFFFFFFF - pll->last_capture) + capture_val + 1;
    }

    pll->last_capture = capture_val;
    pll->period_count = period;

    if (period > 0) {
        pll->freq_meas = TIMER_CLK_FREQ / (float)period;
        pll->capture_ready = 1;
    }

    return pll->freq_meas;
}

/* ================= PLL 更新 ================= */
/* 输入：相位误差（来自过零点与PLL相位的比较） */
void PLL_Update(PLL_FreqMeas_t *pll, float phase_err_input)
{
    float omega_est;

    /* 相位误差限幅 */
    if (phase_err_input > 3.14159265358979323846f)
        phase_err_input -= 2.0f * 3.14159265358979323846f;
    else if (phase_err_input < -3.14159265358979323846f)
        phase_err_input += 2.0f * 3.14159265358979323846f;

    pll->phase_error = phase_err_input;

    /* PI 控制器 */
    pll->integrator += pll->ki * pll->phase_error * pll->ts;
    omega_est = pll->omega_nom + pll->kp * pll->phase_error + pll->integrator;

    /* 频率估计 */
    pll->freq_est = omega_est / (2.0f * 3.14159265358979323846f);

    /* 相位积分 */
    pll->phase_est += omega_est * pll->ts;

    /* 相位归一化到 [-pi, pi] */
    while (pll->phase_est > 3.14159265358979323846f)
        pll->phase_est -= 2.0f * 3.14159265358979323846f;
    while (pll->phase_est < -3.14159265358979323846f)
        pll->phase_est += 2.0f * 3.14159265358979323846f;

    /* 融合：PLL 频率估计与周期计数法测量值加权 */
    if (pll->capture_ready) {
        /* 简单互补滤波：PLL 快速跟踪，周期计数提供稳态精度 */
        pll->freq_out = 0.7f * pll->freq_est + 0.3f * pll->freq_meas;
        pll->capture_ready = 0;
    } else {
        pll->freq_out = pll->freq_est;
    }

    pll->phase_out = pll->phase_est;
}

/* ================= 模拟过零点检测 ================= */
/* 模拟输入正弦信号，返回相位误差 */
float Mock_ZeroCrossDetect(float input_signal, float pll_phase)
{
    float phase_err;
    /* 模拟：输入信号过零点对应相位 0 */
    if (input_signal >= 0.0f) {
        phase_err = -pll_phase;
    } else {
        phase_err = 3.14159265358979323846f - pll_phase;
        if (phase_err > 3.14159265358979323846f)
            phase_err -= 2.0f * 3.14159265358979323846f;
    }
    return phase_err;
}

/* ================= 主函数 ================= */
int main(void)
{
    PLL_FreqMeas_t pll;
    float input_freq = 50.0f;       /* 模拟输入信号频率 50Hz */
    float input_phase = 0.0f;
    float ts = 0.0001f;             /* 100us 控制周期 */
    float omega_nom = 2.0f * 3.14159265358979323846f * 50.0f;
    int i;
    uint32_t mock_capture = 0;
    float input_signal;

    printf("=== PLL + Period Count Frequency Measurement Test ===\n");
    printf("Nominal Frequency: 50.00 Hz\n");
    printf("Input Frequency:   %.2f Hz\n\n", input_freq);

    /* 初始化 PLL */
    PLL_FreqMeas_Init(&pll, 50.0f, 500.0f, omega_nom, ts);

