#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 使用普通静态变量代替绝对地址访问，避免段错误 */
static volatile uint32_t g_timer_cnt  = 0U;
static volatile uint32_t g_timer_arr  = 65535U;
static volatile uint32_t g_timer_cr   = 0U;
static volatile uint32_t g_timer_sr   = 0U;
static volatile uint32_t g_gpio_idr   = 0U;
static volatile uint32_t g_gpio_bsrr  = 0U;

#define TIMER_CNT_REG       (g_timer_cnt)
#define TIMER_ARR_REG       (g_timer_arr)
#define TIMER_CR_REG        (g_timer_cr)
#define TIMER_SR_REG        (g_timer_sr)

#define GPIO_IDR_REG        (g_gpio_idr)
#define GPIO_BSRR_REG       (g_gpio_bsrr)

#define TIMER_CC1IF         (1U << 0)
#define TIMER_CC2IF         (1U << 1)

#define SYSTEM_CLOCK_HZ     72000000U
#define TIMER_PRESCALER     72U
#define TIMER_TICK_HZ       (SYSTEM_CLOCK_HZ / TIMER_PRESCALER)

/* ==================== 数据结构定义 ==================== */

typedef struct {
    uint32_t capture_prev;
    uint32_t capture_curr;
    uint32_t period_ticks;
    float    frequency_hz;
    float    period_sec;
    uint8_t  first_capture;
    uint8_t  valid;
} FreqMeas_t;

typedef struct {
    float    kp;
    float    ki;
    float    integrator;
    float    phase_error;
    float    freq_est;
    float    phase_est;
    float    omega_est;
    float    ts;
    float    freq_nominal;
    float    freq_min;
    float    freq_max;
} PLL_t;

/* ==================== 全局变量 ==================== */
static FreqMeas_t g_freq_meas;
static PLL_t      g_pll;

/* ==================== 函数声明 ==================== */
static void     FreqMeas_Init(FreqMeas_t *fm);
static void     FreqMeas_Update(FreqMeas_t *fm, uint32_t capture_val);
static void     PLL_Init(PLL_t *pll, float ts, float fnom, float kp, float ki);
static float    PLL_Update(PLL_t *pll, float phase_ref);
static void     PLL_SetFrequency(PLL_t *pll, float freq_hz);
static float    PLL_GetFrequency(const PLL_t *pll);
static float    PLL_GetPhase(const PLL_t *pll);
static void     PLL_Reset(PLL_t *pll);

/* ==================== 周期计数法频率测量实现 ==================== */

static void FreqMeas_Init(FreqMeas_t *fm)
{
    fm->capture_prev  = 0U;
    fm->capture_curr  = 0U;
    fm->period_ticks  = 0U;
    fm->frequency_hz  = 0.0f;
    fm->period_sec    = 0.0f;
    fm->first_capture = 1U;
    fm->valid         = 0U;
}

static void FreqMeas_Update(FreqMeas_t *fm, uint32_t capture_val)
{
    if (fm->first_capture) {
        fm->capture_prev  = capture_val;
        fm->first_capture = 0U;
        fm->valid         = 0U;
        return;
    }

    fm->capture_curr = capture_val;

    if (fm->capture_curr >= fm->capture_prev) {
        fm->period_ticks = fm->capture_curr - fm->capture_prev;
    } else {
        fm->period_ticks = (TIMER_ARR_REG - fm->capture_prev)
                         + fm->capture_curr + 1U;
    }

    fm->capture_prev = fm->capture_curr;

    if (fm->period_ticks < 2U) {
        fm->valid = 0U;
        return;
    }

    fm->period_sec   = (float)fm->period_ticks / (float)TIMER_TICK_HZ;
    fm->frequency_hz = (float)TIMER_TICK_HZ / (float)fm->period_ticks;
    fm->valid        = 1U;
}

/* ==================== 软件 PLL 实现 ==================== */

static void PLL_Init(PLL_t *pll, float ts, float fnom, float kp, float ki)
{
    pll->kp           = kp;
    pll->ki           = ki;
    pll->integrator   = 0.0f;
    pll->phase_error  = 0.0f;
    pll->freq_est     = fnom;
    pll->phase_est    = 0.0f;
    pll->omega_est    = 2.0f * (float)M_PI * fnom;
    pll->ts           = ts;
    pll->freq_nominal = fnom;
    pll->freq_min     = fnom * 0.5f;
    pll->freq_max     = fnom * 1.5f;
}

static void PLL_Reset(PLL_t *pll)
{
    pll->integrator  = 0.0f;
    pll->phase_error = 0.0f;
    pll->freq_est    = pll->freq_nominal;
    pll->phase_est   = 0.0f;
    pll->omega_est   = 2.0f * (float)M_PI * pll->freq_nominal;
}

static void PLL_SetFrequency(PLL_t *pll, float freq_hz)
{
    if (freq_hz < pll->freq_min) freq_hz = pll->freq_min;
    if (freq_hz > pll->freq_max) freq_hz = pll->freq_max;

    pll->freq_est  = freq_hz;
    pll->omega_est = 2.0f * (float)M_PI * freq_hz;
}

static float PLL_Update(PLL_t *pll, float phase_ref)
{
    float phase_err;
    float freq_correction;

    phase_err = phase_ref - pll->phase_est;
    while (phase_err >  (float)M_PI) phase_err -= 2.0f * (float)M_PI;
    while (phase_err < -(float)M_PI) phase_err += 2.0f * (float)M_PI;

    pll->phase_error = phase_err;

    pll->integrator += pll->ki * phase_err * pll->ts;

    if (pll->integrator >  pll->freq_max) pll->integrator =  pll->freq_max;
    if (pll->integrator <  pll->freq_min) pll->integrator =  pll->freq_min;

    freq_correction = pll->kp * phase_err + pll->integrator;

    pll->freq_est = pll->freq_nominal + freq_correction;

    if (pll->freq_est > pll->freq_max) pll->freq_est = pll->freq_max;
    if (pll->freq_est < pll->freq_min) pll->freq_est = pll->freq_min;

    pll->omega_est = 2.0f * (float)M_PI * pll->freq_est;

    pll->phase_est += pll->omega_est * pll->ts;
    while (pll->phase_est >  (float)M_PI) pll->phase_est -= 2.0f * (float)M_PI;
    while (pll->phase_est < -(float)M_PI) pll->phase_est += 2.0f * (float)M_PI;

    return pll->freq_est;
}

static float PLL_GetFrequency(const PLL_t *pll)
{
    return pll->freq_est;
}

static float PLL_GetPhase(const PLL_t *pll)
{
    return pll->phase_est;
}

/* ==================== 主函数 ==================== */

int main(void)
{
    const float    ts          = 1.0f / 10000.0f;
    const float    fnom        = 50.0f;
    const float    kp          = 2.0f;
    const float    ki          = 100.0f;
    const float    input_freq  = 50.5f;
    const uint32_t sim_steps   = 2000U;

    uint32_t i;
    float    t;
    float    phase_ref;
    float    freq_pll;
    float    freq_meas;
    uint32_t capture_val;
    uint8_t  zero_cross_detected;
    float    prev_phase = 0.0f;

    FreqMeas_Init(&g_freq_meas);
    PLL_Init(&g_pll, ts, fnom, kp, ki);

    TIMER_ARR_REG = 65535U;

    printf("=== PLL + Frequency Measurement (Period Counting) ===\n");
    printf("Nominal Freq: %.2f Hz, Input Freq: %.2f Hz\n", fnom, input_freq);
    printf("Timer Tick Freq: %u Hz\n", (unsigned)TIMER_TICK_HZ);
    printf("-----------------------------------------------------\n");
    printf("Step\tTime(s)\t\tPhaseRef\tPLL_Freq\tMeas_Freq\tPLL_Phase\n");

    zero_cross_detected = 0U;

    for (i = 0U; i < sim_steps; i++) {
        t         = (float)i * ts;
        phase_ref = 2.0f * (float)M_PI * input_freq * t;

        while (phase_ref >  (float)M_PI) phase_ref -= 2.0f * (float)M_PI;
        while (phase_ref < -(float)M_PI) phase_ref += 2.0f * (float)M_PI;

        if (prev_phase < 0.0f && phase_ref >= 0.0f) {
            zero_cross_detected = 1U;
        } else {
            zero_cross_detected = 0U;
        }
        prev_phase = phase_ref;

        if (zero_cross_detected) {
            capture_val = (uint32_t)(t * (float)TIMER_TICK_HZ) % TIMER_ARR_REG;
            FreqMeas_Update(&g_freq_meas, capture_val);
        }

        freq_pll = PLL_Update(&g_pll, phase_ref);

        if ((i % 200U) == 0U) {
            freq_meas = g_freq_meas.valid ? g_freq_meas.frequency_hz : 0.0f;
            printf("%u\t%.4f\t\t%+.4f\t\t%.4f\t\t%.4f\t\t%+.4f\n",
                   (unsigned)i, t, phase_ref, freq_pll, freq_meas,
                   PLL_GetPhase(&g_pll));
        }
    }

    printf("-----------------------------------------------------\n");
    printf("Final PLL Frequency:    %.4f Hz\n", PLL_GetFrequency(&g_pll));
    printf("Final Measured Frequency: %.4f Hz\n",
           g_freq_meas.valid ? g_freq_meas.frequency_hz : 0.0f);
    printf("Final Measured Period:  %.6f s\n", g_freq_meas.period_sec);
    printf("Final Period Ticks:     %u\n", (unsigned)g_freq_meas.period_ticks);
    printf("Final Phase Error:      %+.6f rad\n", g_pll.phase_error);

    PLL_SetFrequency(&g_pll, 49.8f);
