/* ===== Mock 寄存器与硬件抽象 ===== */
static volatile uint32_t g_pll_ctrl   = 0;
static volatile uint32_t g_pll_status = 0;
static volatile uint32_t g_pll_phase  = 0;
static volatile uint32_t g_pll_freq   = 0;
static volatile uint32_t g_pll_output = 0;

#define PLL_REG_CTRL        (g_pll_ctrl)
#define PLL_REG_STATUS      (g_pll_status)
#define PLL_REG_PHASE       (g_pll_phase)
#define PLL_REG_FREQ        (g_pll_freq)
#define PLL_REG_OUTPUT      (g_pll_output)

#define PLL_CTRL_ENABLE     (1U << 0)
#define PLL_CTRL_RESET      (1U << 1)
#define PLL_CTRL_WAVE_SEL   (1U << 2)   /* 0: 正弦波, 1: 方波 */
#define PLL_CTRL_AMP_SHIFT  4
#define PLL_CTRL_AMP_MASK   (0xFU << PLL_CTRL_AMP_SHIFT)

#define PLL_STATUS_LOCKED   (1U << 0)

/* ===== 输出波形类型 ===== */
typedef enum {
    WAVE_SINE = 0,
    WAVE_SQUARE = 1
} WaveType;

/* ===== PLL 输出整形配置结构体 ===== */
typedef struct {
    WaveType type;          /* 波形类型 */
    float    amplitude;     /* 幅度 0.0 ~ 1.0 */
    float    frequency;     /* 输出频率 Hz */
    float    phase;         /* 相位偏移 弧度 */
    float    duty_cycle;    /* 方波占空比 0.0 ~ 1.0 */
    uint32_t sample_rate;   /* 采样率 Hz */
} PLL_ShaperConfig;

/* ===== 全局状态 ===== */
static PLL_ShaperConfig g_cfg;
static float g_phase_acc;       /* 相位累加器 */
static float g_phase_step;      /* 每采样相位增量 */

/* ===== 初始化 PLL 输出整形模块 ===== */
static void PLL_Shaper_Init(PLL_ShaperConfig *cfg)
{
    if (cfg == NULL) {
        return;
    }

    g_cfg = *cfg;

    /* 参数合法性检查 */
    if (g_cfg.sample_rate == 0) {
        g_cfg.sample_rate = 10000; /* 默认 10kHz */
    }
    if (g_cfg.amplitude < 0.0f) g_cfg.amplitude = 0.0f;
    if (g_cfg.amplitude > 1.0f) g_cfg.amplitude = 1.0f;
    if (g_cfg.duty_cycle <= 0.0f || g_cfg.duty_cycle >= 1.0f) {
        g_cfg.duty_cycle = 0.5f;
    }

    /* 计算相位步进: 2*pi*f / fs */
    g_phase_step = (float)(2.0 * M_PI * g_cfg.frequency / (float)g_cfg.sample_rate);
    g_phase_acc  = g_cfg.phase;

    /* 归一化初始相位到 [0, 2*pi) */
    while (g_phase_acc >= (float)(2.0 * M_PI)) {
        g_phase_acc -= (float)(2.0 * M_PI);
    }
    while (g_phase_acc < 0.0f) {
        g_phase_acc += (float)(2.0 * M_PI);
    }

    /* 配置 mock 寄存器 */
    PLL_REG_CTRL = 0;
    PLL_REG_CTRL |= PLL_CTRL_ENABLE;
    if (g_cfg.type == WAVE_SQUARE) {
        PLL_REG_CTRL |= PLL_CTRL_WAVE_SEL;
    } else {
        PLL_REG_CTRL &= ~PLL_CTRL_WAVE_SEL;
    }

    /* 幅度量化到 4bit 写入寄存器 */
    uint32_t amp_code = (uint32_t)(g_cfg.amplitude * 15.0f + 0.5f);
    if (amp_code > 15) amp_code = 15;
    PLL_REG_CTRL &= ~PLL_CTRL_AMP_MASK;
    PLL_REG_CTRL |= (amp_code << PLL_CTRL_AMP_SHIFT);

    PLL_REG_FREQ = (uint32_t)g_cfg.frequency;
    PLL_REG_PHASE = (uint32_t)(g_cfg.phase * 1000.0f);

    printf("[PLL_Shaper_Init] type=%s amp=%.2f freq=%.1fHz fs=%uHz phase=%.3frad duty=%.2f\n",
           (g_cfg.type == WAVE_SQUARE) ? "SQUARE" : "SINE",
           g_cfg.amplitude, g_cfg.frequency, g_cfg.sample_rate,
           g_cfg.phase, g_cfg.duty_cycle);
}

/* ===== 生成正弦波样本 ===== */
static float PLL_Generate_Sine(float phase)
{
    return g_cfg.amplitude * sinf(phase);
}

/* ===== 生成方波样本 ===== */
static float PLL_Generate_Square(float phase)
{
    /* 将相位归一化到 [0, 1) 周期 */
    float norm = phase / (float)(2.0 * M_PI);
    norm = norm - floorf(norm);   /* 归一化到 [0,1) */

    float duty = g_cfg.duty_cycle;
    if (duty <= 0.0f) duty = 0.5f;
    if (duty >= 1.0f) duty = 0.5f;

    if (norm < duty) {
        return g_cfg.amplitude;   /* 高电平 */
    } else {
        return -g_cfg.amplitude;  /* 低电平 */
    }
}

/* ===== 单步输出整形 ===== */
static float PLL_Shaper_Step(void)
{
    float out;

    if (g_cfg.type == WAVE_SQUARE) {
        out = PLL_Generate_Square(g_phase_acc);
    } else {
        out = PLL_Generate_Sine(g_phase_acc);
    }

    /* 更新相位累加器 */
    g_phase_acc += g_phase_step;
    if (g_phase_acc >= (float)(2.0 * M_PI)) {
        g_phase_acc -= (float)(2.0 * M_PI);
    }

    /* 写入 mock 输出寄存器 (Q15 定点) */
    int32_t q15 = (int32_t)(out * 32767.0f);
    if (q15 > 32767)  q15 = 32767;
    if (q15 < -32768) q15 = -32768;
    PLL_REG_OUTPUT = (uint32_t)(q15 & 0xFFFF);

    return out;
}

/* ===== 批量生成并打印 ===== */
static void PLL_Shaper_Run(uint32_t n)
{
    printf("---- Output samples (%u) ----\n", n);
    for (uint32_t i = 0; i < n; i++) {
        float v = PLL_Shaper_Step();
        printf("sample[%3u] = %+8.4f  (reg=0x%04X)\n",
               i, v, (unsigned)(PLL_REG_OUTPUT & 0xFFFF));
    }
}

/* ===== 主函数 ===== */
int main(void)
{
    printf("===== PLL Output Shaper Test =====\n\n");

    /* 测试 1: 正弦波输出 */
    PLL_ShaperConfig cfg_sine;
    cfg_sine.type        = WAVE_SINE;
    cfg_sine.amplitude   = 1.0f;
    cfg_sine.frequency   = 50.0f;
    cfg_sine.phase       = 0.0f;
    cfg_sine.duty_cycle  = 0.5f;
    cfg_sine.sample_rate = 1000;

    PLL_Shaper_Init(&cfg_sine);
    PLL_Shaper_Run(12);

    printf("\n");

    /* 测试 2: 方波输出 */
    PLL_ShaperConfig cfg_square;
    cfg_square.type        = WAVE_SQUARE;
    cfg_square.amplitude   = 0.8f;
    cfg_square.frequency   = 50.0f;
    cfg_square.phase       = 0.0f;
    cfg_square.duty_cycle  = 0.5f;
    cfg_square.sample_rate = 1000;

    PLL_Shaper_Init(&cfg_square);
    PLL_Shaper_Run(12);

    printf("\n===== Test Done =====\n");
    return 0;
}
