#include <stdio.h>
#include <stdint.h>

/* ============================================================
 * 模拟寄存器与硬件抽象层（Mock）
 * 使用普通静态变量代替绝对地址访问，避免段错误
 * ============================================================ */
static volatile uint32_t g_pll_ctrl_reg   = 0;
static volatile uint32_t g_pll_status_reg = 0;
static volatile uint32_t g_pll_freq_reg   = 0;

#define PLL_CTRL_REG      (g_pll_ctrl_reg)
#define PLL_STATUS_REG    (g_pll_status_reg)
#define PLL_FREQ_REG      (g_pll_freq_reg)

#define PLL_LOCK_BIT      (1U << 0)
#define PLL_ERR_BIT       (1U << 1)

/* 模拟电网周期采样值（单位：微秒） */
static uint32_t mock_grid_period_us = 20000; /* 50Hz -> 20000us */

/* ============================================================
 * PLL 抗电磁干扰（软件防抖）参数
 * ============================================================ */
#define PLL_DEBOUNCE_WINDOW     5U      /* 防抖窗口大小（连续采样次数） */
#define PLL_MAX_DEVIATION_US    200U    /* 单次采样最大允许偏差（us） */
#define PLL_LOCK_THRESHOLD      3U      /* 连续稳定次数达到此值判定锁定 */
#define PLL_UNLOCK_THRESHOLD    5U      /* 连续异常次数达到此值判定失锁 */

/* ============================================================
 * PLL 状态结构体
 * ============================================================ */
typedef struct {
    uint32_t period_buffer[PLL_DEBOUNCE_WINDOW]; /* 周期采样环形缓冲区 */
    uint32_t buffer_index;                       /* 环形缓冲区写索引 */
    uint32_t buffer_count;                       /* 已填充样本数 */
    uint32_t stable_count;                       /* 连续稳定计数 */
    uint32_t unstable_count;                     /* 连续异常计数 */
    uint32_t filtered_period;                    /* 滤波后的周期值 */
    uint32_t lock_state;                         /* 0=失锁 1=锁定 */
    uint32_t glitch_count;                       /* 毛刺计数（统计用） */
} PLL_State_t;

/* ============================================================
 * 初始化 PLL 状态
 * ============================================================ */
static void PLL_Init(PLL_State_t *pll)
{
    uint32_t i;
    for (i = 0; i < PLL_DEBOUNCE_WINDOW; i++) {
        pll->period_buffer[i] = 0;
    }
    pll->buffer_index    = 0;
    pll->buffer_count    = 0;
    pll->stable_count    = 0;
    pll->unstable_count  = 0;
    pll->filtered_period = 0;
    pll->lock_state      = 0;
    pll->glitch_count    = 0;
}

/* ============================================================
 * 计算中位值（对缓冲区中有效样本排序后取中位）
 * 中位值滤波对脉冲干扰有很好的抑制效果
 * ============================================================ */
static uint32_t PLL_MedianFilter(const uint32_t *buf, uint32_t count)
{
    uint32_t tmp[PLL_DEBOUNCE_WINDOW];
    uint32_t i, j, temp;

    if (count == 0) return 0;
    if (count == 1) return buf[0];
    if (count > PLL_DEBOUNCE_WINDOW) count = PLL_DEBOUNCE_WINDOW;

    for (i = 0; i < count; i++) {
        tmp[i] = buf[i];
    }

    /* 简单冒泡排序 */
    for (i = 0; i < count - 1; i++) {
        for (j = 0; j < count - 1 - i; j++) {
            if (tmp[j] > tmp[j + 1]) {
                temp = tmp[j];
                tmp[j] = tmp[j + 1];
                tmp[j + 1] = temp;
            }
        }
    }

    return tmp[count / 2];
}

/* ============================================================
 * PLL 抗干扰核心处理函数
 * 输入：raw_period_us - 本次测量的电网周期（微秒）
 * 返回：滤波后的周期值
 * ============================================================ */
static uint32_t PLL_Process(PLL_State_t *pll, uint32_t raw_period_us)
{
    uint32_t median;
    uint32_t deviation;

    if (pll == NULL) return 0;

    /* ---- 第1步：单次采样偏差检查（快速毛刺剔除） ---- */
    if (pll->filtered_period != 0) {
        if (raw_period_us > pll->filtered_period) {
            deviation = raw_period_us - pll->filtered_period;
        } else {
            deviation = pll->filtered_period - raw_period_us;
        }

        if (deviation > PLL_MAX_DEVIATION_US) {
            /* 偏差过大，判定为电磁干扰毛刺，丢弃本次采样 */
            pll->glitch_count++;
            pll->unstable_count++;
            if (pll->unstable_count >= PLL_UNLOCK_THRESHOLD) {
                pll->lock_state = 0;
            }
            return pll->filtered_period; /* 保持上次有效值 */
        }
    }

    /* ---- 第2步：写入环形缓冲区 ---- */
    pll->period_buffer[pll->buffer_index] = raw_period_us;
    pll->buffer_index = (pll->buffer_index + 1) % PLL_DEBOUNCE_WINDOW;
    if (pll->buffer_count < PLL_DEBOUNCE_WINDOW) {
        pll->buffer_count++;
    }

    /* ---- 第3步：中位值滤波 ---- */
    median = PLL_MedianFilter(pll->period_buffer, pll->buffer_count);

    /* ---- 第4步：稳定性判定 ---- */
    if (pll->filtered_period != 0) {
        if (median > pll->filtered_period) {
            deviation = median - pll->filtered_period;
        } else {
            deviation = pll->filtered_period - median;
        }

        if (deviation <= PLL_MAX_DEVIATION_US) {
            pll->stable_count++;
            pll->unstable_count = 0;
            if (pll->stable_count >= PLL_LOCK_THRESHOLD) {
                pll->lock_state = 1;
            }
        } else {
            pll->unstable_count++;
            pll->stable_count = 0;
            if (pll->unstable_count >= PLL_UNLOCK_THRESHOLD) {
                pll->lock_state = 0;
            }
        }
    } else {
        pll->stable_count++;
        if (pll->stable_count >= PLL_LOCK_THRESHOLD) {
            pll->lock_state = 1;
        }
    }

    /* ---- 第5步：更新滤波输出 ---- */
    pll->filtered_period = median;

    /* ---- 第6步：更新模拟寄存器（Mock） ---- */
    PLL_FREQ_REG = pll->filtered_period;
    if (pll->lock_state) {
        PLL_STATUS_REG |= PLL_LOCK_BIT;
        PLL_STATUS_REG &= ~PLL_ERR_BIT;
    } else {
        PLL_STATUS_REG &= ~PLL_LOCK_BIT;
        PLL_STATUS_REG |= PLL_ERR_BIT;
    }

    return pll->filtered_period;
}

/* ============================================================
 * 模拟获取电网周期（含随机电磁干扰）
 * ============================================================ */
static uint32_t Mock_GetGridPeriod(void)
{
    static uint32_t call_count = 0;
    uint32_t period = mock_grid_period_us;

    call_count++;

    /* 模拟电磁干扰：在第 3、7、11 次采样时注入毛刺 */
    if (call_count == 3) {
        period = 15000; /* 严重干扰：周期突变 */
    } else if (call_count == 7) {
        period = 26000; /* 严重干扰：周期突变 */
    } else if (call_count == 11) {
        period = 18000; /* 中等干扰 */
    } else {
        /* 正常情况加入小幅随机抖动 */
        period = mock_grid_period_us + (call_count % 5) * 10 - 20;
    }

    return period;
}

/* ============================================================
 * 主函数：测试 PLL 抗电磁干扰算法
 * ============================================================ */
int main(void)
{
    PLL_State_t pll;
    uint32_t raw_period;
    uint32_t filtered_period;
    uint32_t i;

    printf("========================================\n");
    printf("  PLL 抗电磁干扰（软件防抖）测试\n");
    printf("========================================\n");
    printf("防抖窗口: %u, 最大偏差: %u us\n",
           (unsigned int)PLL_DEBOUNCE_WINDOW, (unsigned int)PLL_MAX_DEVIATION_US);
    printf("锁定阈值: %u, 失锁阈值: %u\n",
           (unsigned int)PLL_LOCK_THRESHOLD, (unsigned int)PLL_UNLOCK_THRESHOLD);
    printf("----------------------------------------\n");
    printf("%-6s %-12s %-12s %-8s %-8s\n",
           "次数", "原始周期(us)", "滤波周期(us)", "锁定", "毛刺");
    printf("----------------------------------------\n");

    PLL_Init(&pll);

    for (i = 0; i < 15; i++) {
        raw_period = Mock_GetGridPeriod();
        filtered_period = PLL_Process(&pll, raw_period);

        printf("%-6u %-12u %-12u %-8s %-8u\n",
               (unsigned int)(i + 1),
               (unsigned int)raw_period,
               (unsigned int)filtered_period,
               pll.lock_state ? "是" : "否",
               (unsigned int)pll.glitch_count);
    }

    printf("----------------------------------------\n");
    printf("最终状态: %s\n", pll.lock_state ? "锁定" : "失锁");
    printf("滤波输出周期: %u us\n", (unsigned int)pll.filtered_period);
    printf("毛刺剔除总数: %u\n", (unsigned int)pll.glitch_count);
    printf("PLL_STATUS_REG = 0x%08X\n", (unsigned int)PLL_STATUS_REG);
    printf("PLL_FREQ_REG   = 0x%08X (%u us)\n",
           (unsigned int)PLL_FREQ_REG, (unsigned int)PLL_FREQ_REG);
    printf("========================================\n");

    return 0;
}
