#include <stdio.h>
#include <math.h>
#include <stdint.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* ===== Mock 寄存器与硬件抽象 ===== */
static volatile uint32_t g_pll_ctrl    = 0;
static volatile uint32_t g_pll_status  = 0;
static volatile uint32_t g_pll_phase   = 0;
static volatile uint32_t g_pll_freq    = 0;
static volatile uint32_t g_pll_out_sel = 0;

#define PLL_REG_CTRL        (g_pll_ctrl)
#define PLL_REG_STATUS      (g_pll_status)
#define PLL_REG_PHASE       (g_pll_phase)
#define PLL_REG_FREQ        (g_pll_freq)
#define PLL_REG_OUT_SEL     (g_pll_out_sel)

#define PLL_CTRL_ENABLE     (1U << 0)
#define PLL_CTRL_RESET      (1U << 1)
#define PLL_STATUS_LOCKED   (1U << 0)

#define PLL_OUT_SINE        0U
#define PLL_OUT_SQUARE      1U

/* ===== 参数定义 ===== */
#define PLL_SAMPLE_RATE     10000.0f
#define PLL_TARGET_FREQ     50.0f
#define PLL_TWO_PI          (2.0f * (float)M_PI)

/* ===== 全局状态 ===== */
typedef struct {
    float   phase;
    float   freq;
    float   phase_step;
    float   amplitude;
    uint8_t output_mode;
    uint8_t locked;
} PLL_Handle_t;

static PLL_Handle_t g_pll;

/* ===== 硬件抽象层 ===== */
static void PLL_HwInit(void)
{
    PLL_REG_CTRL = 0;
    PLL_REG_CTRL |= PLL_CTRL_RESET;
    PLL_REG_CTRL &= ~PLL_CTRL_RESET;
    PLL_REG_CTRL |= PLL_CTRL_ENABLE;
    PLL_REG_OUT_SEL = PLL_OUT_SINE;
}

static uint8_t PLL_HwIsLocked(void)
{
    return (PLL_REG_STATUS & PLL_STATUS_LOCKED) ? 1U : 0U;
}

static void PLL_HwSetOutputMode(uint8_t mode)
{
    PLL_REG_OUT_SEL = mode;
}

/* ===== PLL 初始化 ===== */
void PLL_Init(PLL_Handle_t *pll, float target_freq, float sample_rate, float amplitude)
{
    if (pll == NULL || sample_rate <= 0.0f) {
        return;
    }

    pll->phase      = 0.0f;
    pll->freq       = target_freq;
    pll->phase_step = PLL_TWO_PI * target_freq / sample_rate;
    pll->amplitude  = amplitude;
    pll->output_mode = PLL_OUT_SINE;
    pll->locked     = 0;

    PLL_HwInit();
}

/* ===== 相位累加与频率更新 ===== */
void PLL_Update(PLL_Handle_t *pll)
{
    if (pll == NULL) {
        return;
    }

    pll->phase += pll->phase_step;
    if (pll->phase >= PLL_TWO_PI) {
        pll->phase -= PLL_TWO_PI;
    }
    if (pll->phase < 0.0f) {
        pll->phase += PLL_TWO_PI;
    }

    pll->locked = PLL_HwIsLocked();
}

/* ===== 输出信号整形 ===== */
float PLL_GetOutput(PLL_Handle_t *pll)
{
    float out = 0.0f;

    if (pll == NULL) {
        return 0.0f;
    }

    if (pll->output_mode == PLL_OUT_SINE) {
        out = pll->amplitude * sinf(pll->phase);
    } else {
        if (pll->phase < (float)M_PI) {
            out = pll->amplitude;
        } else {
            out = -pll->amplitude;
        }
    }

    return out;
}

/* ===== 设置输出模式 ===== */
void PLL_SetOutputMode(PLL_Handle_t *pll, uint8_t mode)
{
    if (pll == NULL) {
        return;
    }
    pll->output_mode = mode;
    PLL_HwSetOutputMode(mode);
}

/* ===== 设置频率 ===== */
void PLL_SetFrequency(PLL_Handle_t *pll, float freq, float sample_rate)
{
    if (pll == NULL || sample_rate <= 0.0f) {
        return;
    }
    pll->freq = freq;
    pll->phase_step = PLL_TWO_PI * freq / sample_rate;
}

/* ===== 主函数测试 ===== */
int main(void)
{
    int i;
    float sample;

    printf("===== PLL Output Shaping Test =====\n\n");

    PLL_Init(&g_pll, PLL_TARGET_FREQ, PLL_SAMPLE_RATE, 1.0f);

    PLL_REG_STATUS |= PLL_STATUS_LOCKED;

    printf("--- Sine Wave Output (50Hz, 10kHz sample rate) ---\n");
    PLL_SetOutputMode(&g_pll, PLL_OUT_SINE);

    for (i = 0; i < 20; i++) {
        PLL_Update(&g_pll);
        sample = PLL_GetOutput(&g_pll);
        printf("Sample[%2d]: phase=%.4f rad, output=%.6f, locked=%d\n",
               i, g_pll.phase, sample, g_pll.locked);
    }

    printf("\n");

    printf("--- Square Wave Output (50Hz, 10kHz sample rate) ---\n");
    PLL_SetOutputMode(&g_pll, PLL_OUT_SQUARE);

    g_pll.phase = 0.0f;

    for (i = 0; i < 20; i++) {
        PLL_Update(&g_pll);
        sample = PLL_GetOutput(&g_pll);
        printf("Sample[%2d]: phase=%.4f rad, output=%.6f, locked=%d\n",
               i, g_pll.phase, sample, g_pll.locked);
    }

    printf("\n");

    printf("--- Frequency Change to 100Hz (Square Wave) ---\n");
    PLL_SetFrequency(&g_pll, 100.0f, PLL_SAMPLE_RATE);
    g_pll.phase = 0.0f;

    for (i = 0; i < 10; i++) {
        PLL_Update(&g_pll);
        sample = PLL_GetOutput(&g_pll);
        printf("Sample[%2d]: phase=%.4f rad, output=%.6f\n",
               i, g_pll.phase, sample);
    }

    printf("\n===== Test Complete =====\n");

    return 0;
}
