static volatile unsigned int mock_pll_freq_reg = 0;
static volatile unsigned int mock_pll_phase_reg = 0;
static volatile unsigned int mock_protect_cmd_reg = 0;
static volatile unsigned int mock_protect_status_reg = 0;

#define PLL_CTRL_REG        (mock_pll_ctrl_reg)
#define PLL_STATUS_REG      (mock_pll_status_reg)
#define PLL_FREQ_REG        (mock_pll_freq_reg)
#define PLL_PHASE_REG       (mock_pll_phase_reg)
#define PROTECT_CMD_REG     (mock_protect_cmd_reg)
#define PROTECT_STATUS_REG  (mock_protect_status_reg)

#define PLL_ENABLE_BIT      (1U << 0)
#define PLL_LOCK_BIT        (1U << 0)
#define PLL_UNLOCK_BIT      (1U << 1)
#define PLL_FAULT_BIT       (1U << 2)

#define PROTECT_TRIP_BIT    (1U << 0)
#define PROTECT_CLEAR_BIT   (1U << 1)

#define PLL_LOCK_THRESHOLD  0.05f
#define PLL_UNLOCK_CNT_MAX  10
#define PLL_LOCK_CNT_MAX    5

/* ================= 数据结构定义 ================= */
typedef enum {
    PLL_STATE_UNLOCKED = 0,
    PLL_STATE_LOCKING,
    PLL_STATE_LOCKED,
    PLL_STATE_FAULT
} PLL_State_t;

typedef struct {
    float ref_freq;
    float ref_phase;
    float pll_freq;
    float pll_phase;
    float phase_error;
    float freq_error;
    unsigned int unlock_counter;
    unsigned int lock_counter;
    PLL_State_t state;
    bool trip_flag;
} PLL_Handle_t;

/* ================= 函数声明 ================= */
static void PLL_Init(PLL_Handle_t *pll, float ref_freq);
static void PLL_Update(PLL_Handle_t *pll, float ref_phase, float pll_phase, float pll_freq);
static void PLL_ProtectionLogic(PLL_Handle_t *pll);
static void PLL_TriggerTrip(PLL_Handle_t *pll);
static void PLL_ClearTrip(PLL_Handle_t *pll);
static const char* PLL_StateToString(PLL_State_t state);

/* ================= 函数实现 ================= */
static void PLL_Init(PLL_Handle_t *pll, float ref_freq)
{
    if (pll == NULL) {
        return;
    }

    pll->ref_freq = ref_freq;
    pll->ref_phase = 0.0f;
    pll->pll_freq = 0.0f;
    pll->pll_phase = 0.0f;
    pll->phase_error = 0.0f;
    pll->freq_error = 0.0f;
    pll->unlock_counter = 0;
    pll->lock_counter = 0;
    pll->state = PLL_STATE_UNLOCKED;
    pll->trip_flag = false;

    PLL_CTRL_REG |= PLL_ENABLE_BIT;
    PROTECT_CMD_REG &= ~PROTECT_TRIP_BIT;
    PROTECT_CMD_REG |= PROTECT_CLEAR_BIT;
}

static void PLL_Update(PLL_Handle_t *pll, float ref_phase, float pll_phase, float pll_freq)
{
    if (pll == NULL) {
        return;
    }

    pll->ref_phase = ref_phase;
    pll->pll_phase = pll_phase;
    pll->pll_freq = pll_freq;

    pll->phase_error = pll->ref_phase - pll->pll_phase;
    if (pll->phase_error > 180.0f) {
        pll->phase_error -= 360.0f;
    } else if (pll->phase_error < -180.0f) {
        pll->phase_error += 360.0f;
    }

    pll->freq_error = pll->ref_freq - pll->pll_freq;

    PLL_PHASE_REG = (unsigned int)(pll->pll_phase * 1000.0f);
    PLL_FREQ_REG = (unsigned int)(pll->pll_freq * 1000.0f);
}

static void PLL_ProtectionLogic(PLL_Handle_t *pll)
{
    float abs_phase_err;
    float abs_freq_err;

    if (pll == NULL) {
        return;
    }

    abs_phase_err = fabsf(pll->phase_error);
    abs_freq_err = fabsf(pll->freq_error);

    if (pll->trip_flag) {
        pll->state = PLL_STATE_FAULT;
        PLL_STATUS_REG |= PLL_FAULT_BIT;
        return;
    }

    if (abs_phase_err < PLL_LOCK_THRESHOLD && abs_freq_err < PLL_LOCK_THRESHOLD) {
        pll->lock_counter++;
        pll->unlock_counter = 0;
        if (pll->lock_counter >= PLL_LOCK_CNT_MAX) {
            pll->state = PLL_STATE_LOCKED;
            PLL_STATUS_REG |= PLL_LOCK_BIT;
            PLL_STATUS_REG &= ~PLL_UNLOCK_BIT;
        } else {
            pll->state = PLL_STATE_LOCKING;
        }
    } else {
        pll->unlock_counter++;
        pll->lock_counter = 0;
        if (pll->unlock_counter >= PLL_UNLOCK_CNT_MAX) {
            pll->state = PLL_STATE_UNLOCKED;
            PLL_STATUS_REG |= PLL_UNLOCK_BIT;
            PLL_STATUS_REG &= ~PLL_LOCK_BIT;
            PLL_TriggerTrip(pll);
        } else {
            pll->state = PLL_STATE_LOCKING;
        }
    }
}

static void PLL_TriggerTrip(PLL_Handle_t *pll)
{
    if (pll == NULL) {
        return;
    }

    pll->trip_flag = true;
    pll->state = PLL_STATE_FAULT;
    PROTECT_CMD_REG |= PROTECT_TRIP_BIT;
    PROTECT_STATUS_REG |= PROTECT_TRIP_BIT;
    PLL_CTRL_REG &= ~PLL_ENABLE_BIT;
    PLL_STATUS_REG |= PLL_FAULT_BIT;
    printf("[PROTECT] PLL失锁，触发停机保护！\n");
}

static void PLL_ClearTrip(PLL_Handle_t *pll)
{
    if (pll == NULL) {
        return;
    }

    pll->trip_flag = false;
    pll->unlock_counter = 0;
    pll->lock_counter = 0;
    pll->state = PLL_STATE_UNLOCKED;
    PROTECT_CMD_REG &= ~PROTECT_TRIP_BIT;
    PROTECT_CMD_REG |= PROTECT_CLEAR_BIT;
    PROTECT_STATUS_REG &= ~PROTECT_TRIP_BIT;
    PLL_STATUS_REG &= ~PLL_FAULT_BIT;
    PLL_CTRL_REG |= PLL_ENABLE_BIT;
    printf("[PROTECT] 保护已复位，PLL重新使能。\n");
}

static const char* PLL_StateToString(PLL_State_t state)
{
    switch (state) {
        case PLL_STATE_UNLOCKED: return "UNLOCKED";
        case PLL_STATE_LOCKING:  return "LOCKING";
        case PLL_STATE_LOCKED:   return "LOCKED";
        case PLL_STATE_FAULT:    return "FAULT";
        default:                 return "UNKNOWN";
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    PLL_Handle_t pll;
    int i;

    printf("===== PLL与保护逻辑联动（失锁停机）测试 =====\n\n");

    PLL_Init(&pll, 50.0f);
    printf("PLL初始化完成，参考频率: %.2f Hz\n", pll.ref_freq);
    printf("初始状态: %s\n\n", PLL_StateToString(pll.state));

    /* 模拟阶段1：PLL逐渐锁定 */
    printf("--- 阶段1：PLL逐渐锁定 ---\n");
    for (i = 0; i < 8; i++) {
        float ref_phase = 0.0f;
        float pll_phase = 0.0f + (float)i * 0.005f;
        float pll_freq = 50.0f - (float)(7 - i) * 0.005f;

        PLL_Update(&pll, ref_phase, pll_phase, pll_freq);
        PLL_ProtectionLogic(&pll);

        printf("Step %d: 相位误差=%.4f, 频率误差=%.4f, 状态=%s, 锁定计数=%u, 失锁计数=%u\n",
               i + 1, pll.phase_error, pll.freq_error,
               PLL_StateToString(pll.state),
               pll.lock_counter, pll.unlock_counter);
    }

    /* 模拟阶段2：PLL失锁 */
    printf("\n--- 阶段2：PLL失锁 ---\n");
    for (i = 0; i < 12; i++) {
        float ref_phase = 0.0f;
        float pll_phase = 0.0f + (float)(i + 1) * 0.5f;
        float pll_freq = 50.0f + (float)(i + 1) * 0.5f;

        PLL_Update(&pll, ref_phase, pll_phase, pll_freq);
        PLL_ProtectionLogic(&pll);

        printf("Step %d: 相位误差=%.4f, 频率误差=%.4f, 状态=%s, 锁定计数=%u, 失锁计数=%u, 跳闸=%s\n",
               i + 1, pll.phase_error, pll.freq_error,
               PLL_StateToString(pll.state),
               pll.lock_counter, pll.unlock_counter,
               pll.trip_flag ? "是" : "否");

        if (pll.trip_flag) {
            printf(">>> 保护动作：PLL失锁，系统已停机 <<<\n");
            break;
        }
    }

    /* 模拟阶段3：保护复位 */
    printf("\n--- 阶段3：保护复位 ---\n");
    PLL_ClearTrip(&pll);
    printf("复位后状态: %s, 跳闸标志: %s\n",
           PLL_StateToString(pll.state),
           pll.trip_flag ? "是" : "否");

    /* 模拟阶段4：重新锁定 */
    printf("\n--- 阶段4：重新锁定 ---\n");
    for (i = 0; i < 8; i++) {
        float ref_phase = 0.0f;
        float pll_phase = 0.0f + (float)i * 0.003f;
        float pll_freq = 50.0f - (float)(7 - i) * 0.003f;

        PLL_Update(&pll, ref_phase, pll_phase, pll_freq);
        PLL_ProtectionLogic(&pll);

        printf("Step %d: 相位误差=%.4f, 频率误差=%.4f, 状态=%s, 锁定计数=%u\n",
               i + 1, pll.phase_error, pll.freq_error,
               PLL_StateToString(pll.state),
               pll.lock_counter);
    }

    printf("\n===== 测试结束 =====\n");
    return 0;
}
