#include <stdio.h>
#include <math.h>
#include <stdint.h>
#include <string.h>

/* ========== 模拟寄存器与硬件抽象层 ========== */
#define MOCK_REG_ADC_CH0    0x40000000U
#define MOCK_REG_ADC_CH1    0x40000004U
#define MOCK_REG_ADC_CH2    0x40000008U
#define MOCK_REG_PWM_PERIOD 0x40000010U
#define MOCK_REG_PWM_DUTY   0x40000014U

typedef struct {
    volatile uint32_t *reg;
    uint32_t value;
} MockReg;

static MockReg mock_adc[3] = {
    { (volatile uint32_t *)MOCK_REG_ADC_CH0, 0 },
    { (volatile uint32_t *)MOCK_REG_ADC_CH1, 0 },
    { (volatile uint32_t *)MOCK_REG_ADC_CH2, 0 }
};

static MockReg mock_pwm_period = { (volatile uint32_t *)MOCK_REG_PWM_PERIOD, 10000 };
static MockReg mock_pwm_duty   = { (volatile uint32_t *)MOCK_REG_PWM_DUTY,   5000 };

/* ========== 数学常量 ========== */
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define TWO_PI (2.0f * (float)M_PI)

/* ========== PLL 参数 ========== */
#define PLL_KP          0.5f
#define PLL_KI          0.01f
#define PLL_TS          1.0e-4f          /* 采样周期 100us */
#define PLL_FREQ_NOM    50.0f            /* 额定频率 50Hz */
#define PLL_W_NOM       (TWO_PI * PLL_FREQ_NOM)
#define PLL_W_MIN       (TWO_PI * 45.0f)
#define PLL_W_MAX       (TWO_PI * 55.0f)
#define PLL_LPF_ALPHA   0.1f

/* ========== 多通道数量 ========== */
#define PLL_CHANNELS    3

/* ========== 单通道 PLL 结构体 ========== */
typedef struct {
    float theta;        /* 估计相位 */
    float omega;        /* 估计角频率 */
    float sin_theta;    /* sin(theta) */
    float cos_theta;    /* cos(theta) */
    float integrator;   /* 积分器状态 */
    float v_alpha;      /* 输入 alpha 分量 */
    float v_beta;       /* 输入 beta 分量 */
    float v_d;          /* d 轴分量 */
    float v_q;          /* q 轴分量 */
    float freq;         /* 估计频率 Hz */
    float lock;         /* 锁定标志 0~1 */
    float err_lpf;      /* 误差低通滤波 */
} PLL_Channel;

/* ========== 全局 PLL 实例 ========== */
static PLL_Channel pll[PLL_CHANNELS];

/* ========== 初始化 ========== */
static void PLL_Init(PLL_Channel *p, float init_theta)
{
    p->theta      = init_theta;
    p->omega      = PLL_W_NOM;
    p->sin_theta  = sinf(init_theta);
    p->cos_theta  = cosf(init_theta);
    p->integrator = 0.0f;
    p->v_alpha    = 0.0f;
    p->v_beta     = 0.0f;
    p->v_d        = 0.0f;
    p->v_q        = 0.0f;
    p->freq       = PLL_FREQ_NOM;
    p->lock       = 0.0f;
    p->err_lpf    = 0.0f;
}

/* ========== 单通道 PLL 更新 ========== */
static void PLL_Update(PLL_Channel *p, float v_alpha, float v_beta)
{
    float err, omega_corr;

    p->v_alpha = v_alpha;
    p->v_beta  = v_beta;

    /* Park 变换：将 alpha-beta 转到 d-q */
    p->v_d =  p->v_alpha * p->cos_theta + p->v_beta * p->sin_theta;
    p->v_q = -p->v_alpha * p->sin_theta + p->v_beta * p->cos_theta;

    /* 相位误差（q 轴分量） */
    err = p->v_q;

    /* 误差低通滤波，抑制谐波 */
    p->err_lpf = p->err_lpf + PLL_LPF_ALPHA * (err - p->err_lpf);

    /* PI 调节器 */
    p->integrator += PLL_KI * p->err_lpf * PLL_TS;
    omega_corr = PLL_KP * p->err_lpf + p->integrator;

    /* 角频率 = 额定 + 修正，并限幅 */
    p->omega = PLL_W_NOM + omega_corr;
    if (p->omega < PLL_W_MIN) p->omega = PLL_W_MIN;
    if (p->omega > PLL_W_MAX) p->omega = PLL_W_MAX;

    /* 相位积分 */
    p->theta += p->omega * PLL_TS;
    if (p->theta > TWO_PI) p->theta -= TWO_PI;
    if (p->theta < 0.0f)   p->theta += TWO_PI;

    /* 更新正余弦 */
    p->sin_theta = sinf(p->theta);
    p->cos_theta = cosf(p->theta);

    /* 频率估计 */
    p->freq = p->omega / TWO_PI;

    /* 锁定判断：频率接近额定且误差小 */
    if (fabsf(p->freq - PLL_FREQ_NOM) < 0.5f && fabsf(p->err_lpf) < 0.05f) {
        p->lock += 0.01f;
        if (p->lock > 1.0f) p->lock = 1.0f;
    } else {
        p->lock -= 0.02f;
        if (p->lock < 0.0f) p->lock = 0.0f;
    }
}

/* ========== 多通道同步更新 ========== */
static void PLL_MultiChannel_Update(float va[PLL_CHANNELS], float vb[PLL_CHANNELS])
{
    int i;
    for (i = 0; i < PLL_CHANNELS; i++) {
        PLL_Update(&pll[i], va[i], vb[i]);
    }
}

/* ========== 模拟 ADC 采样 ========== */
static void Mock_ADC_Read(float va[PLL_CHANNELS], float vb[PLL_CHANNELS], float t)
{
    int i;
    for (i = 0; i < PLL_CHANNELS; i++) {
        float phase = TWO_PI * PLL_FREQ_NOM * t + (float)i * (TWO_PI / 3.0f);
        float amp = 1.0f + 0.05f * (float)i;
        va[i] = amp * cosf(phase);
        vb[i] = amp * sinf(phase);
        mock_adc[i].value = (uint32_t)((va[i] + 1.0f) * 2048.0f);
    }
}

/* ========== 主函数 ========== */
int main(void)
{
    int i, step;
    float va[PLL_CHANNELS], vb[PLL_CHANNELS];
    float t = 0.0f;
    const int total_steps = 2000;

    printf("=== PLL Multi-Channel Synchronization Test ===\n");
    printf("Channels: %d, Nominal Freq: %.1f Hz, Ts: %.1e s\n\n",
           PLL_CHANNELS, PLL_FREQ_NOM, PLL_TS);

    /* 初始化各通道，初始相位略有差异以测试同步能力 */
    for (i = 0; i < PLL_CHANNELS; i++) {
        PLL_Init(&pll[i], (float)i * 0.3f);
    }

    /* 主循环 */
    for (step = 0; step < total_steps; step++) {
        /* 模拟 ADC 采样 */
        Mock_ADC_Read(va, vb, t);

        /* 多通道 PLL 同步更新 */
        PLL_MultiChannel_Update(va, vb);

        /* 每 200 步打印一次状态 */
        if (step % 200 == 0) {
            printf("Step %4d | t=%.4fs\n", step, t);
            for (i = 0; i < PLL_CHANNELS; i++) {
                printf("  CH%d: theta=%.4f rad, freq=%.3f Hz, lock=%.2f, "
                       "v_d=%.4f, v_q=%.4f\n",
                       i,
                       pll[i].theta,
                       pll[i].freq,
                       pll[i].lock,
                       pll[i].v_d,
                       pll[i].v_q);
            }
            printf("\n");
        }

        t += PLL_TS;
    }

    /* 最终同步状态检查 */
    printf("=== Final Synchronization Check ===\n");
    for (i = 0; i < PLL_CHANNELS; i++) {
        printf("CH%d: freq=%.4f Hz, lock=%.2f, theta=%.4f rad\n",
               i, pll[i].freq, pll[i].lock, pll[i].theta);
    }

    /* 检查通道间相位差是否接近 120 度 */
    printf("\nPhase differences (should be ~2.094 rad = 120 deg):\n");
    for (i = 0; i < PLL_CHANNELS; i++) {
        int j = (i + 1) % PLL_CHANNELS;
        float dtheta = pll[j].theta - pll[i].theta;
        if (dtheta < 0.0f) dtheta += TWO_PI;
        printf("  CH%d -> CH%d: %.4f rad (%.2f deg)\n",
               i, j, dtheta, dtheta * 180.0f / (float)M_PI);
    }

    printf("\nPLL Multi-Channel Test Complete.\n");
    return 0;
}
