#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器定义（使用普通变量，避免非法地址访问） ================= */
static volatile uint32_t g_pll_ctrl_reg   = 0;
static volatile uint32_t g_pll_status_reg = 0;
static volatile uint32_t g_pll_phase_reg  = 0;
static volatile uint32_t g_pll_freq_reg   = 0;
static volatile uint32_t g_pll_amp_reg    = 0;

#define PLL_CTRL_REG        (g_pll_ctrl_reg)
#define PLL_STATUS_REG      (g_pll_status_reg)
#define PLL_PHASE_REG       (g_pll_phase_reg)
#define PLL_FREQ_REG        (g_pll_freq_reg)
#define PLL_AMP_REG         (g_pll_amp_reg)

#define PLL_ENABLE_BIT      (1U << 0)
#define PLL_LOCK_BIT        (1U << 1)

/* ================= 常量定义 ================= */
#define PI                  3.14159265358979323846f
#define TWO_PI              (2.0f * PI)
#define SAMPLE_RATE         10000.0f
#define NOMINAL_FREQ        50.0f
#define NOMINAL_OMEGA       (TWO_PI * NOMINAL_FREQ)
#define KP_PLL              120.0f
#define KI_PLL              3200.0f
#define AMP_LPF_ALPHA       0.05f

/* ================= 数据结构 ================= */
typedef struct {
    float theta;
    float omega;
    float freq;
    float amp;
    float integrator;
    float sin_theta;
    float cos_theta;
    float alpha;
    float beta;
    float err;
    float lock_counter;
    uint8_t locked;
} PLL_State_t;

/* ================= 初始化 ================= */
static void PLL_Init(PLL_State_t *pll)
{
    pll->theta = 0.0f;
    pll->omega = NOMINAL_OMEGA;
    pll->freq = NOMINAL_FREQ;
    pll->amp = 0.0f;
    pll->integrator = 0.0f;
    pll->sin_theta = 0.0f;
    pll->cos_theta = 1.0f;
    pll->alpha = 0.0f;
    pll->beta = 0.0f;
    pll->err = 0.0f;
    pll->lock_counter = 0.0f;
    pll->locked = 0;

    PLL_CTRL_REG |= PLL_ENABLE_BIT;
}

/* ================= 单步 PLL 更新 ================= */
static void PLL_Update(PLL_State_t *pll, float alpha, float beta, float dt)
{
    float sin_t, cos_t, err, vq;
    float omega_err, omega_new;
    float amp_inst;

    pll->alpha = alpha;
    pll->beta = beta;

    sin_t = sinf(pll->theta);
    cos_t = cosf(pll->theta);
    pll->sin_theta = sin_t;
    pll->cos_theta = cos_t;

    vq = -alpha * sin_t + beta * cos_t;

    amp_inst = sqrtf(alpha * alpha + beta * beta);
    pll->amp += AMP_LPF_ALPHA * (amp_inst - pll->amp);

    if (pll->amp > 1e-6f) {
        err = vq / pll->amp;
    } else {
        err = 0.0f;
    }
    pll->err = err;

    pll->integrator += KI_PLL * err * dt;
    omega_err = KP_PLL * err + pll->integrator;

    omega_new = NOMINAL_OMEGA + omega_err;
    if (omega_new < TWO_PI * (NOMINAL_FREQ - 10.0f)) {
        omega_new = TWO_PI * (NOMINAL_FREQ - 10.0f);
    } else if (omega_new > TWO_PI * (NOMINAL_FREQ + 10.0f)) {
        omega_new = TWO_PI * (NOMINAL_FREQ + 10.0f);
    }
    pll->omega = omega_new;
    pll->freq = omega_new / TWO_PI;

    pll->theta += omega_new * dt;
    if (pll->theta >= TWO_PI) {
        pll->theta -= TWO_PI;
    } else if (pll->theta < 0.0f) {
        pll->theta += TWO_PI;
    }

    if (fabsf(err) < 0.02f) {
        pll->lock_counter += 1.0f;
        if (pll->lock_counter > 200.0f) {
            pll->locked = 1;
        }
    } else {
        pll->lock_counter = 0.0f;
        pll->locked = 0;
    }

    PLL_PHASE_REG = (uint32_t)(pll->theta * 1000000.0f);
    PLL_FREQ_REG  = (uint32_t)(pll->freq * 1000.0f);
    PLL_AMP_REG   = (uint32_t)(pll->amp * 1000.0f);
    if (pll->locked) {
        PLL_STATUS_REG |= PLL_LOCK_BIT;
    } else {
        PLL_STATUS_REG &= ~PLL_LOCK_BIT;
    }
}

/* ================= 实时监控打印 ================= */
static void PLL_PrintMonitor(const PLL_State_t *pll, uint32_t step)
{
    printf("[%6u] theta=%7.4f rad | freq=%8.4f Hz | amp=%7.4f | err=%+8.5f | lock=%s\n",
           step,
           pll->theta,
           pll->freq,
           pll->amp,
           pll->err,
           pll->locked ? "YES" : "NO ");
}

/* ================= 主函数 ================= */
int main(void)
{
    PLL_State_t pll;
    float dt = 1.0f / SAMPLE_RATE;
    float t;
    float alpha, beta;
    float input_freq;
    uint32_t step;
    uint32_t total_steps = 2000;

    printf("============================================================\n");
    printf("  PLL Real-Time Monitor (Phase / Frequency / Amplitude)\n");
    printf("  Sample Rate: %.0f Hz | Nominal Freq: %.1f Hz\n",
           SAMPLE_RATE, NOMINAL_FREQ);
    printf("============================================================\n");

    PLL_Init(&pll);

    for (step = 0; step < total_steps; step++) {
        t = (float)step * dt;

        if (step < 500) {
            input_freq = 50.0f;
        } else {
            input_freq = 52.0f;
        }

        alpha = 1.0f * cosf(TWO_PI * input_freq * t);
        beta  = 1.0f * sinf(TWO_PI * input_freq * t);

        PLL_Update(&pll, alpha, beta, dt);

        if ((step % 200) == 0 || step == total_steps - 1) {
            PLL_PrintMonitor(&pll, step);
        }
    }

    printf("============================================================\n");
    printf("  Final: theta=%.4f rad, freq=%.4f Hz, amp=%.4f, locked=%s\n",
           pll.theta, pll.freq, pll.amp, pll.locked ? "YES" : "NO");
    printf("============================================================\n");

    return 0;
}
