#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 模拟寄存器与宏定义 ==================== */
static volatile uint32_t g_pll_ctrl_reg = 0;
static volatile uint32_t g_pll_status_reg = 0;
static volatile float    g_pll_phase_reg = 0.0f;
static volatile float    g_pll_freq_reg = 0.0f;
static volatile float    g_pll_amp_reg = 0.0f;

#define PLL_CTRL_REG      (g_pll_ctrl_reg)
#define PLL_STATUS_REG    (g_pll_status_reg)
#define PLL_PHASE_REG     (g_pll_phase_reg)
#define PLL_FREQ_REG      (g_pll_freq_reg)
#define PLL_AMP_REG       (g_pll_amp_reg)

#define PLL_ENABLE_BIT    (1U << 0)
#define PLL_LOCK_BIT      (1U << 1)

/* ==================== 系统参数 ==================== */
#define PI                3.14159265358979323846f
#define TWO_PI            (2.0f * PI)
#define SAMPLE_RATE       10000.0f
#define NOMINAL_FREQ      50.0f
#define NOMINAL_OMEGA     (TWO_PI * NOMINAL_FREQ)
#define TS                (1.0f / SAMPLE_RATE)

/* SOGI-PLL 参数 */
#define SOGI_K            1.414f
#define PLL_KP            120.0f
#define PLL_KI            5000.0f

/* ==================== 数据结构 ==================== */
typedef struct {
    float alpha;
    float beta;
    float v_alpha;
    float v_beta;
    float theta;
    float omega;
    float freq;
    float amplitude;
    float integrator;
    float sin_theta;
    float cos_theta;
    float error;
    uint8_t locked;
} PLL_State;

/* ==================== 初始化 ==================== */
static void PLL_Init(PLL_State *pll)
{
    pll->alpha = 0.0f;
    pll->beta = 0.0f;
    pll->v_alpha = 0.0f;
    pll->v_beta = 0.0f;
    pll->theta = 0.0f;
    pll->omega = NOMINAL_OMEGA;
    pll->freq = NOMINAL_FREQ;
    pll->amplitude = 0.0f;
    pll->integrator = 0.0f;
    pll->sin_theta = 0.0f;
    pll->cos_theta = 1.0f;
    pll->error = 0.0f;
    pll->locked = 0;

    PLL_CTRL_REG |= PLL_ENABLE_BIT;
}

/* ==================== SOGI 正交信号生成 ==================== */
static void SOGI_Update(PLL_State *pll, float v_in)
{
    float alpha_dot, beta_dot;

    alpha_dot = pll->omega * (SOGI_K * (v_in - pll->alpha) - pll->beta);
    beta_dot  = pll->omega * pll->alpha;

    pll->alpha += alpha_dot * TS;
    pll->beta  += beta_dot  * TS;

    pll->v_alpha = pll->alpha;
    pll->v_beta  = pll->beta;
}

/* ==================== Park 变换 ==================== */
static void Park_Transform(PLL_State *pll, float *vd, float *vq)
{
    pll->sin_theta = sinf(pll->theta);
    pll->cos_theta = cosf(pll->theta);

    *vd =  pll->v_alpha * pll->cos_theta + pll->v_beta * pll->sin_theta;
    *vq = -pll->v_alpha * pll->sin_theta + pll->v_beta * pll->cos_theta;
}

/* ==================== PI 控制器 ==================== */
static float PI_Controller(PLL_State *pll, float error)
{
    float output;

    pll->integrator += PLL_KI * error * TS;

    if (pll->integrator > 200.0f)  pll->integrator = 200.0f;
    if (pll->integrator < -200.0f) pll->integrator = -200.0f;

    output = PLL_KP * error + pll->integrator;
    return output;
}

/* ==================== 幅值估计 ==================== */
static float Estimate_Amplitude(PLL_State *pll)
{
    return sqrtf(pll->v_alpha * pll->v_alpha +
                 pll->v_beta  * pll->v_beta);
}

/* ==================== PLL 主更新函数 ==================== */
static void PLL_Update(PLL_State *pll, float v_in)
{
    float vd, vq;
    float omega_delta;

    SOGI_Update(pll, v_in);

    Park_Transform(pll, &vd, &vq);

    pll->error = vq;

    omega_delta = PI_Controller(pll, pll->error);

    pll->omega = NOMINAL_OMEGA + omega_delta;
    if (pll->omega < 0.0f) pll->omega = 0.0f;
    pll->freq = pll->omega / TWO_PI;

    pll->theta += pll->omega * TS;

    while (pll->theta >= TWO_PI) pll->theta -= TWO_PI;
    while (pll->theta < 0.0f)    pll->theta += TWO_PI;

    pll->amplitude = Estimate_Amplitude(pll);

    if (fabsf(pll->error) < 0.05f &&
        fabsf(pll->freq - NOMINAL_FREQ) < 0.5f) {
        pll->locked = 1;
        PLL_STATUS_REG |= PLL_LOCK_BIT;
    } else {
        pll->locked = 0;
        PLL_STATUS_REG &= ~PLL_LOCK_BIT;
    }

    PLL_PHASE_REG = pll->theta;
    PLL_FREQ_REG  = pll->freq;
    PLL_AMP_REG   = pll->amplitude;
}

/* ==================== 实时监控打印 ==================== */
static void PLL_Monitor(const PLL_State *pll, uint32_t step)
{
    printf("[%6u] Phase: %7.4f rad (%6.2f deg) | "
           "Freq: %7.3f Hz | Amp: %7.4f V | "
           "Err: %+8.5f | Locked: %s\n",
           (unsigned)step,
           (double)pll->theta,
           (double)(pll->theta * 180.0f / PI),
           (double)pll->freq,
           (double)pll->amplitude,
           (double)pll->error,
           pll->locked ? "YES" : "NO ");
}

/* ==================== 主函数 ==================== */
int main(void)
{
    PLL_State pll;
    uint32_t step;
    float t;
    float v_in;
    const uint32_t total_steps = 2000;
    const uint32_t print_interval = 200;

    printf("============================================================\n");
    printf("        PLL Real-Time Monitor (Phase/Freq/Amplitude)        \n");
    printf("============================================================\n");
    printf("Sample Rate: %.0f Hz | Nominal Freq: %.1f Hz\n",
           (double)SAMPLE_RATE, (double)NOMINAL_FREQ);
    printf("------------------------------------------------------------\n");

    PLL_Init(&pll);

    for (step = 0; step < total_steps; step++) {
        t = (float)step * TS;

        v_in = 311.0f * sinf(TWO_PI * NOMINAL_FREQ * t);

        if (step > 1000) {
            v_in = 311.0f * sinf(TWO_PI * 55.0f * t);
        }

        PLL_Update(&pll, v_in);

        if (step % print_interval == 0) {
            PLL_Monitor(&pll, step);
        }
    }

    printf("------------------------------------------------------------\n");
    printf("Final State:\n");
    printf("  Phase     = %.4f rad (%.2f deg)\n",
           (double)pll.theta,
           (double)(pll.theta * 180.0f / PI));
    printf("  Frequency = %.3f Hz\n", (double)pll.freq);
    printf("  Amplitude = %.4f V\n", (double)pll.amplitude);
    printf("  Locked    = %s\n", pll.locked ? "YES" : "NO");
    printf("============================================================\n");

    return 0;
}
