#include <stdio.h>
#include <math.h>
#include <string.h>

/* ============================================================
 * 二阶 Chebyshev 低通滤波器（纹波抑制）
 * 采用双线性变换（Tustin）离散化
 * 传递函数（模拟域）：
 *   H(s) = K / (s^2 + (ω0/Q)s + ω0^2)
 * 其中 ω0 = 2π*fc，Q 由纹波系数决定
 * ============================================================ */

/* 滤波器结构体 */
typedef struct {
    /* 系数 */
    double b0, b1, b2;   /* 分子系数 */
    double a1, a2;       /* 分母系数（a0 归一化为 1） */
    /* 状态变量（直接 II 型转置） */
    double x1, x2;       /* 输入历史 */
    double y1, y2;       /* 输出历史 */
} Chebyshev2LPF;

/* 初始化二阶 Chebyshev 低通滤波器
 * fc     : 截止频率 (Hz)
 * fs     : 采样频率 (Hz)
 * ripple : 通带纹波 (dB)，例如 0.5 或 1.0
 */
void Chebyshev2LPF_Init(Chebyshev2LPF *f, double fc, double fs, double ripple)
{
    double wc = 2.0 * M_PI * fc;          /* 模拟角频率 */
    double T  = 1.0 / fs;                 /* 采样周期 */
    double K  = tan(wc * T / 2.0);        /* 预畸变 */

    /* 由纹波计算 Chebyshev 参数 */
    double eps = sqrt(pow(10.0, ripple / 10.0) - 1.0);
    double a   = asinh(1.0 / eps) / 2.0;  /* 极点实部参数 */
    double sinh_a = sinh(a);
    double cosh_a = cosh(a);

    /* 模拟域极点（归一化到 ω0 = 1）：
     * s1,2 = -sinh(a)*sin(π/4) ± j*cosh(a)*cos(π/4)
     * 对于二阶，角度为 π/4
     */
    double sigma = sinh_a * sin(M_PI / 4.0);
    double omega = cosh_a * cos(M_PI / 4.0);

    /* 模拟传递函数分母：s^2 + 2*sigma*s + (sigma^2 + omega^2) */
    double a0 = 1.0;
    double a1 = 2.0 * sigma;
    double a2 = sigma * sigma + omega * omega;

    /* 双线性变换：s = (2/T) * (1 - z^-1) / (1 + z^-1)
     * 代入并整理，得到数字域系数
     * 使用预畸变后的 K 进行频率缩放
     */
    double K2 = K * K;
    double denom = a0 + a1 * K + a2 * K2;

    /* 数字域分母系数（归一化前） */
    double d0 = denom;
    double d1 = 2.0 * (a2 * K2 - a0);
    double d2 = a0 - a1 * K + a2 * K2;

    /* 数字域分子系数（增益归一化到直流为 1） */
    double n0 = K2;
    double n1 = 2.0 * K2;
    double n2 = K2;

    /* 归一化使 a0 = 1 */
    f->b0 = n0 / d0;
    f->b1 = n1 / d0;
    f->b2 = n2 / d0;
    f->a1 = d1 / d0;
    f->a2 = d2 / d0;

    /* 清零状态 */
    f->x1 = f->x2 = 0.0;
    f->y1 = f->y2 = 0.0;
}

/* 滤波处理（直接 II 型转置结构） */
double Chebyshev2LPF_Process(Chebyshev2LPF *f, double x)
{
    double y = f->b0 * x + f->b1 * f->x1 + f->b2 * f->x2
               - f->a1 * f->y1 - f->a2 * f->y2;

    /* 更新历史 */
    f->x2 = f->x1;
    f->x1 = x;
    f->y2 = f->y1;
    f->y1 = y;

    return y;
}

/* 复位滤波器状态 */
void Chebyshev2LPF_Reset(Chebyshev2LPF *f)
{
    f->x1 = f->x2 = 0.0;
    f->y1 = f->y2 = 0.0;
}

/* ============================================================
 * 测试主函数
 * ============================================================ */
int main(void)
{
    Chebyshev2LPF lpf;
    double fs = 1000.0;    /* 采样率 1 kHz */
    double fc = 50.0;      /* 截止频率 50 Hz */
    double ripple = 0.5;   /* 通带纹波 0.5 dB */

    Chebyshev2LPF_Init(&lpf, fc, fs, ripple);

    printf("=== 二阶 Chebyshev 低通滤波器 (纹波抑制) ===\n");
    printf("采样率 fs = %.1f Hz\n", fs);
    printf("截止频率 fc = %.1f Hz\n", fc);
    printf("通带纹波 = %.2f dB\n", ripple);
    printf("系数: b0=%.10f, b1=%.10f, b2=%.10f\n", lpf.b0, lpf.b1, lpf.b2);
    printf("      a1=%.10f, a2=%.10f\n", lpf.a1, lpf.a2);
    printf("\n");

    /* 测试信号：直流 + 50Hz 正弦 + 200Hz 正弦 */
    printf("输入信号: 1.0 + 0.5*sin(2π*50*t) + 0.3*sin(2π*200*t)\n");
    printf("时间(ms)  输入        输出\n");
    printf("--------  ----------  ----------\n");

    int i;
    for (i = 0; i < 100; i++) {
        double t = (double)i / fs;
        double x = 1.0
                 + 0.5 * sin(2.0 * M_PI * 50.0 * t)
                 + 0.3 * sin(2.0 * M_PI * 200.0 * t);
        double y = Chebyshev2LPF_Process(&lpf, x);

        /* 每 10 个点打印一次 */
        if (i % 10 == 0) {
            printf("%8.2f  %10.6f  %10.6f\n", t * 1000.0, x, y);
        }
    }

    /* 阶跃响应测试 */
    printf("\n=== 阶跃响应测试 ===\n");
    Chebyshev2LPF_Reset(&lpf);
    printf("时间(ms)  输出\n");
    printf("--------  ----------\n");
    for (i = 0; i < 50; i++) {
        double y = Chebyshev2LPF_Process(&lpf, 1.0);
        if (i % 5 == 0) {
            printf("%8.2f  %10.6f\n", (double)i / fs * 1000.0, y);
        }
    }

    return 0;
}
