#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FIR_TAP_NUM 31
#define PI M_PI

static double fir_coeff[FIR_TAP_NUM];
static double fir_buffer[FIR_TAP_NUM];
static int fir_index = 0;

static void fir_lowpass_hanning_init(double cutoff_norm)
{
    int n;
    int m = FIR_TAP_NUM - 1;
    double sum = 0.0;

    for (n = 0; n < FIR_TAP_NUM; n++) {
        double sinc_val;
        double hanning;
        double x = (double)n - (double)m / 2.0;

        if (fabs(x) < 1e-12) {
            sinc_val = 2.0 * cutoff_norm;
        } else {
            sinc_val = sin(2.0 * PI * cutoff_norm * x) / (PI * x);
        }

        hanning = 0.5 - 0.5 * cos(2.0 * PI * (double)n / (double)m);

        fir_coeff[n] = sinc_val * hanning;
        sum += fir_coeff[n];
    }

    for (n = 0; n < FIR_TAP_NUM; n++) {
        fir_coeff[n] /= sum;
    }

    memset(fir_buffer, 0, sizeof(fir_buffer));
    fir_index = 0;
}

static double fir_filter(double input)
{
    int i;
    double output = 0.0;

    fir_buffer[fir_index] = input;

    for (i = 0; i < FIR_TAP_NUM; i++) {
        int idx = fir_index - i;
        if (idx < 0) {
            idx += FIR_TAP_NUM;
        }
        output += fir_coeff[i] * fir_buffer[idx];
    }

    fir_index++;
    if (fir_index >= FIR_TAP_NUM) {
        fir_index = 0;
    }

    return output;
}

int main(void)
{
    int i;
    double test_signal[64];
    double filtered[64];

    fir_lowpass_hanning_init(0.1);

    printf("FIR Lowpass Filter (Hanning Window)\n");
    printf("Tap number: %d\n", FIR_TAP_NUM);
    printf("Coefficients:\n");
    for (i = 0; i < FIR_TAP_NUM; i++) {
        printf("  h[%2d] = % .10f\n", i, fir_coeff[i]);
    }

    for (i = 0; i < 64; i++) {
        test_signal[i] = sin(2.0 * PI * 0.02 * i) + 0.5 * sin(2.0 * PI * 0.4 * i);
    }

    printf("\nInput and Output:\n");
    for (i = 0; i < 64; i++) {
        filtered[i] = fir_filter(test_signal[i]);
        printf("  n=%2d  in=% .6f  out=% .6f\n", i, test_signal[i], filtered[i]);
    }

    return 0;
