#include <stdio.h>
#include <math.h>
#include <string.h>

#define FIR_TAP_NUM 31
#define PI 3.14159265358979323846

/* 阻带衰减优化：采用 Kaiser 窗，beta 越大阻带衰减越高 */
static double bessel_i0(double x)
{
    double sum = 1.0;
    double term = 1.0;
    int k;
    for (k = 1; k < 25; k++) {
        term *= (x / (2.0 * k)) * (x / (2.0 * k));
        sum += term;
        if (term < 1e-12 * sum) break;
    }
    return sum;
}

static double kaiser_window(int n, int N, double beta)
{
    double alpha = (N - 1) / 2.0;
    double r = (n - alpha) / alpha;
    double arg = 1.0 - r * r;
    if (arg < 0.0) arg = 0.0;
    return bessel_i0(beta * sqrt(arg)) / bessel_i0(beta);
}

/* 设计 FIR 高通滤波器：理想高通 + Kaiser 窗 */
static void fir_highpass_design(double *h, int N, double fc, double beta)
{
    int n;
    double alpha = (N - 1) / 2.0;
    for (n = 0; n < N; n++) {
        double m = n - alpha;
        double ideal;
        if (fabs(m) < 1e-12) {
            ideal = 1.0 - 2.0 * fc;
        } else {
            ideal = -sin(2.0 * PI * fc * m) / (PI * m);
        }
        h[n] = ideal * kaiser_window(n, N, beta);
    }
    /* 归一化：使高频增益为 1（在 Nyquist 处） */
    double sum = 0.0;
    for (n = 0; n < N; n++) {
        sum += h[n] * ((n % 2 == 0) ? 1.0 : -1.0);
    }
    if (fabs(sum) > 1e-12) {
        for (n = 0; n < N; n++) h[n] /= sum;
    }
}

/* FIR 滤波：直接型，带历史状态 */
typedef struct {
    double h[FIR_TAP_NUM];
    double x[FIR_TAP_NUM];
    int idx;
} FIR_HP;

static void fir_hp_init(FIR_HP *f, const double *h)
{
    memcpy(f->h, h, sizeof(double) * FIR_TAP_NUM);
    memset(f->x, 0, sizeof(f->x));
    f->idx = 0;
}

static double fir_hp_process(FIR_HP *f, double in)
{
    int i, k;
    double y = 0.0;
    f->x[f->idx] = in;
    k = f->idx;
    for (i = 0; i < FIR_TAP_NUM; i++) {
        y += f->h[i] * f->x[k];
        k--;
        if (k < 0) k = FIR_TAP_NUM - 1;
    }
    f->idx++;
    if (f->idx >= FIR_TAP_NUM) f->idx = 0;
    return y;
}

int main(void)
{
    double h[FIR_TAP_NUM];
    FIR_HP filt;
    int i;
    double fs = 1000.0;
    double fc = 0.15;      /* 归一化截止频率 */
    double beta = 8.0;     /* Kaiser beta，阻带衰减约 80 dB */

    fir_highpass_design(h, FIR_TAP_NUM, fc, beta);

    printf("FIR Highpass Filter Coefficients (N=%d, fc=%.3f, beta=%.1f):\n",
           FIR_TAP_NUM, fc, beta);
    for (i = 0; i < FIR_TAP_NUM; i++) {
        printf("h[%2d] = % .10f\n", i, h[i]);
    }

    fir_hp_init(&filt, h);

    printf("\nTest: input = 0.5*sin(2*pi*50*t) + 0.5*sin(2*pi*300*t)\n");
    printf("idx\tinput\t\toutput\n");
    for (i = 0; i < 60; i++) {
        double t = (double)i / fs;
        double in = 0.5 * sin(2.0 * PI * 50.0 * t)
                  + 0.5 * sin(2.0 * PI * 300.0 * t);
        double out = fir_hp_process(&filt, in);
        if (i % 5 == 0) {
            printf("%3d\t% .6f\t% .6f\n", i, in, out);
        }
    }

    return 0;
}
