#include <stdio.h>
#include <math.h>
#include <string.h>

#define FIR_TAP_NUM 31
#define PI 3.14159265358979323846f

typedef struct {
    float coeff[FIR_TAP_NUM];
    float buffer[FIR_TAP_NUM];
    int index;
} FIR_Filter;

static void FIR_Init(FIR_Filter *fir, float cutoff_norm)
{
    int n;
    int m;
    int center = (FIR_TAP_NUM - 1) / 2;
    float sum = 0.0f;

    memset(fir, 0, sizeof(FIR_Filter));

    for (n = 0; n < FIR_TAP_NUM; n++) {
        if (n == center) {
            fir->coeff[n] = 2.0f * cutoff_norm;
        } else {
            float x = (float)(n - center);
            fir->coeff[n] = sinf(2.0f * PI * cutoff_norm * x) / (PI * x);
        }

        fir->coeff[n] *= 0.5f - 0.5f * cosf(2.0f * PI * (float)n / (float)(FIR_TAP_NUM - 1));
        sum += fir->coeff[n];
    }

    for (n = 0; n < FIR_TAP_NUM; n++) {
        fir->coeff[n] /= sum;
    }
}

static float FIR_Process(FIR_Filter *fir, float input)
{
    int i;
    float output = 0.0f;

    fir->buffer[fir->index] = input;

    for (i = 0; i < FIR_TAP_NUM; i++) {
        int idx = fir->index - i;
        if (idx < 0) {
            idx += FIR_TAP_NUM;
        }
        output += fir->coeff[i] * fir->buffer[idx];
    }

    fir->index++;
    if (fir->index >= FIR_TAP_NUM) {
        fir->index = 0;
    }

    return output;
}

int main(void)
{
    FIR_Filter fir;
    float input_signal[64];
    float output_signal[64];
    int i;

    FIR_Init(&fir, 0.1f);

    printf("FIR Low Pass Filter (Hanning Window)\n");
    printf("Tap Num: %d\n", FIR_TAP_NUM);
    printf("Coefficients:\n");
    for (i = 0; i < FIR_TAP_NUM; i++) {
        printf("h[%2d] = % .8f\n", i, fir.coeff[i]);
    }
    printf("\n");

    for (i = 0; i < 64; i++) {
        float t = (float)i;
        input_signal[i] = sinf(2.0f * PI * 0.05f * t) + 0.5f * sinf(2.0f * PI * 0.35f * t);
    }

    printf("Input -> Output:\n");
    for (i = 0; i < 64; i++) {
        output_signal[i] = FIR_Process(&fir, input_signal[i]);
