#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FIR_TAP_NUM 65
#define SAMPLE_RATE 1000.0f

typedef struct {
    float coeffs[FIR_TAP_NUM];
    float delay_line[FIR_TAP_NUM];
    int write_index;
    float center_freq;
    float bandwidth;
} FIRBandpass;

static void fir_bandpass_init(FIRBandpass *fir, float center_freq, float bandwidth)
{
    int n;
    int m;
    float sum;
    float fc_norm;
    float bw_norm;
    float wc;
    float wbw;

    memset(fir, 0, sizeof(FIRBandpass));
    fir->center_freq = center_freq;
    fir->bandwidth = bandwidth;
    fir->write_index = 0;

    fc_norm = center_freq / SAMPLE_RATE;
    bw_norm = bandwidth / SAMPLE_RATE;
    wc = 2.0f * (float)M_PI * fc_norm;
    wbw = 2.0f * (float)M_PI * bw_norm;

    sum = 0.0f;
    for (n = 0; n < FIR_TAP_NUM; n++) {
        m = n - (FIR_TAP_NUM - 1) / 2;
        if (m == 0) {
            fir->coeffs[n] = (2.0f * fc_norm);
        } else {
            fir->coeffs[n] = (sinf((float)m * wbw / 2.0f) / ((float)m * (float)M_PI)) *
                             cosf((float)m * wc);
        }
        sum += fir->coeffs[n];
    }

    if (fabsf(sum) > 1e-12f) {
        for (n = 0; n < FIR_TAP_NUM; n++) {
            fir->coeffs[n] /= sum;
        }
    }
}

static float fir_bandpass_process(FIRBandpass *fir, float input)
{
    int i;
    int idx;
    float acc;

    fir->delay_line[fir->write_index] = input;

    acc = 0.0f;
    idx = fir->write_index;
    for (i = 0; i < FIR_TAP_NUM; i++) {
        acc += fir->coeffs[i] * fir->delay_line[idx];
        idx--;
        if (idx < 0) {
            idx = FIR_TAP_NUM - 1;
        }
    }

    fir->write_index++;
    if (fir->write_index >= FIR_TAP_NUM) {
        fir->write_index = 0;
    }

    return acc;
}

static void fir_bandpass_set_center_freq(FIRBandpass *fir, float center_freq)
{
    fir_bandpass_init(fir, center_freq, fir->bandwidth);
}

