#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define FIR_TAP_NUM 64
#define PI 3.14159265358979323846

typedef struct {
    double coeff[FIR_TAP_NUM];
    double delay_line[FIR_TAP_NUM];
    int    write_idx;
} FIR_HP_Filter;

static void fir_hp_init(FIR_HP_Filter *f, double cutoff_norm, double stopband_atten_db)
{
    int i, n;
    int M = FIR_TAP_NUM - 1;
    double fc = cutoff_norm;
    double beta = 0.0;
    double sum = 0.0;

    if (stopband_atten_db >= 50.0) {
        beta = 0.1102 * (stopband_atten_db - 8.7);
    } else if (stopband_atten_db >= 21.0) {
        beta = 0.5842 * pow(stopband_atten_db - 21.0, 0.4)
             + 0.07886 * (stopband_atten_db - 21.0);
    } else {
        beta = 0.0;
    }

    for (n = 0; n <= M; n++) {
        double m = (double)n - (double)M / 2.0;
        double sinc_val;
        double window;
        double arg;

        if (fabs(m) < 1e-12) {
            sinc_val = 2.0 * fc;
        } else {
            sinc_val = sin(2.0 * PI * fc * m) / (PI * m);
        }

        arg = beta * sqrt(1.0 - pow((2.0 * n / M) - 1.0, 2.0));
        window = 0.0;
        {
            double x = arg;
            double term = 1.0;
            double bessel = 1.0;
            int k;
            for (k = 1; k < 25; k++) {
                term *= (x / (2.0 * k)) * (x / (2.0 * k));
                bessel += term;
                if (term < 1e-16) break;
            }
            window = bessel;
        }
        f->coeff[n] = sinc_val * window;
    }

    {
        double bessel0_beta = 1.0;
        double term = 1.0;
        int k;
        for (k = 1; k < 25; k++) {
            term *= (beta / (2.0 * k)) * (beta / (2.0 * k));
            bessel0_beta += term;
            if (term < 1e-16) break;
        }
        for (n = 0; n <= M; n++) {
            f->coeff[n] /= bessel0_beta;
        }
    }

    for (n = 0; n <= M; n++) {
        f->coeff[n] = -f->coeff[n];
    }
    f->coeff[M / 2] += 1.0;

    for (n = 0; n <= M; n++) {
        sum += f->coeff[n];
    }
    for (n = 0; n <= M; n++) {
        f->coeff[n] /= sum;
    }

    memset(f->delay_line, 0, sizeof(f->delay_line));
    f->write_idx = 0;
}

static double fir_hp_process(FIR_HP_Filter *f, double input)
{
    double output = 0.0;
    int i;
    int idx;

    f->delay_line[f->write_idx] = input;

    for (i = 0; i < FIR_TAP_NUM; i++) {
        idx = f->write_idx - i;
        if (idx < 0) idx += FIR_TAP_NUM;
        output += f->coeff[i] * f->delay_line[idx];
    }

    f->write_idx++;
    if (f->write_idx >= FIR_TAP_NUM) {
        f->write_idx = 0;
    }

    return output;
}

int main(void)
{
    FIR_HP_Filter hp;
    double fs = 1000.0;
    double fc = 100.0;
    double cutoff_norm = fc / fs;
    double stopband_atten = 60.0;
    int i;

    printf("=== FIR High-Pass Filter (Kaiser Window, Stopband Attenuation Optimized) ===\n");
    printf("Tap number      : %d\n", FIR_TAP_NUM);
    printf("Sampling rate   : %.1f Hz\n", fs);
    printf("Cutoff freq     : %.1f Hz\n", fc);
    printf("Stopband atten  : %.1f dB\n", stopband_atten);
    printf("Normalized fc   : %.4f\n\n", cutoff_norm);

    fir_hp_init(&hp, cutoff_norm, stopband_atten);

    printf("Filter coefficients (first 8):\n");
    for (i = 0; i < 8; i++) {
        printf("  h[%2d] = % .10f\n", i, hp.coeff[i]);
    }
    printf("  ...\n\n");

    printf("Impulse response test:\n");
    for (i = 0; i < 16; i++) {
        double in = (i == 0) ? 1.0 : 0.0;
        double out = fir_hp_process(&hp, in);
        printf("  n=%2d  in=% .4f  out=% .10f\n", i, in, out);
    }

    printf("\nStep response test:\n");
    fir_hp_init(&hp, cutoff_norm, stopband_atten);
    for (i = 0; i < 16; i++) {
        double in = 1.0;
        double out = fir_hp_process(&hp, in);
        printf("  n=%2d  in=% .4f  out=% .10f\n", i, in, out);
    }

    printf("\nSine wave test (10 Hz low freq, should be attenuated):\n");
    fir_hp_init(&hp, cutoff_norm, stopband_atten);
    for (i = 0; i < 16; i++) {
        double in = sin(2.0 * PI * 10.0 * i / fs);
        double out = fir_hp_process(&hp, in);
        printf("  n=%2d  in=% .6f  out=% .10f\n", i, in, out);
    }

    printf("\nSine wave test (300 Hz high freq, should pass):\n");
    fir_hp_init(&hp, cutoff_norm, stopband_atten);
    for (i = 0; i < 16; i++) {
        double in = sin(2.0 * PI * 300.0 * i / fs);
        double out = fir_hp_process(&hp, in);
        printf("  n=%2d  in=% .6f  out=% .10f\n", i, in, out);
    }

    return 0;
}
