#include <stdio.h>
#include <math.h>
#include <string.h>

#define FIR_TAP_NUM 101
#define PI 3.14159265358979323846f

/* 采样率与陷波频率 */
#define FS 1000.0f
#define F_NOTCH1 50.0f
#define F_NOTCH2 60.0f

/* 滤波器系数存储 */
static float fir_coeff[FIR_TAP_NUM];

/* 延迟线 */
static float delay_line[FIR_TAP_NUM];
static int delay_idx = 0;

/* 生成带阻 FIR 系数：两个陷波频率的带阻，使用窗函数法 */
static void fir_notch_design(void)
{
    int n;
    int M = FIR_TAP_NUM - 1;
    float fc1 = F_NOTCH1 / FS;
    float fc2 = F_NOTCH2 / FS;
    float bw = 0.02f; /* 过渡带宽度，归一化频率 */

    /* 设计两个带阻：先设计低通，再设计高通，然后组合 */
    /* 这里采用直接频率采样法构造带阻：理想带阻频率响应 */
    for (n = 0; n < FIR_TAP_NUM; n++)
    {
        int k = n - M / 2;
        float h;
        if (k == 0)
        {
            h = 1.0f - 2.0f * (fc2 - fc1);
        }
        else
        {
            float w1 = 2.0f * PI * fc1 * (float)k;
            float w2 = 2.0f * PI * fc2 * (float)k;
            h = (sinf(w1) - sinf(w2)) / (PI * (float)k);
        }
        /* 汉明窗 */
        float w = 0.54f - 0.46f * cosf(2.0f * PI * (float)n / (float)M);
        fir_coeff[n] = h * w;
    }

    /* 归一化直流增益为 1 */
    float sum = 0.0f;
    for (n = 0; n < FIR_TAP_NUM; n++)
    {
        sum += fir_coeff[n];
    }
    if (fabsf(sum) > 1e-12f)
    {
        for (n = 0; n < FIR_TAP_NUM; n++)
        {
            fir_coeff[n] /= sum;
        }
    }
}

/* FIR 滤波：每次输入一个样本，返回一个输出样本 */
static float fir_filter(float input)
{
    int i;
    float acc = 0.0f;

    delay_line[delay_idx] = input;

    for (i = 0; i < FIR_TAP_NUM; i++)
    {
        int idx = delay_idx - i;
        if (idx < 0)
        {
            idx += FIR_TAP_NUM;
        }
        acc += fir_coeff[i] * delay_line[idx];
    }

    delay_idx++;
    if (delay_idx >= FIR_TAP_NUM)
    {
        delay_idx = 0;
    }

    return acc;
}

/* 生成测试信号：50Hz + 60Hz + 200Hz 正弦叠加 */
static float test_signal(float t)
{
    float s = 0.0f;
    s += 1.0f * sinf(2.0f * PI * 50.0f * t);
    s += 1.0f * sinf(2.0f * PI * 60.0f * t);
    s += 0.5f * sinf(2.0f * PI * 200.0f * t);
    return s;
}

int main(void)
{
    int i;
    float t;
    float input;
    float output;

    memset(delay_line, 0, sizeof(delay_line));
    delay_idx = 0;

    fir_notch_design();

    printf("FIR notch filter (50Hz & 60Hz) coefficients:\n");
    for (i = 0; i < FIR_TAP_NUM; i++)
    {
        printf("h[%d] = %.8f\n", i, fir_coeff[i]);
    }
    printf("\n");

    printf("Time(s)   Input      Output\n");
    printf("------------------------------\n");

    for (i = 0; i < 200; i++)
    {
        t = (float)i / FS;
        input = test_signal(t);
        output = fir_filter(input);
        printf("%.4f   %8.4f   %8.4f\n", t, input, output);
    }

    return 0;
}
