```c
#include <stdio.h>
#include <math.h>
#include <string.h>

/* ============================================================
 * 扩展卡尔曼滤波 (EKF) 示例
 * 非线性系统模型:
 *   状态: x = [位置, 速度]^T
 *   状态方程: x_k = f(x_{k-1}) + w
 *   观测方程: z_k = h(x_k) + v
 *      观测: z = p^2 + 3*v   (非线性观测)
 * ============================================================ */

#define N 2   /* 状态维数 */
#define M 1   /* 观测维数 */

typedef struct { double m[N][N]; } MatNN;
typedef struct { double m[M][M]; } MatMM;
typedef struct { double m[N][M]; } MatNM;
typedef struct { double m[M][N]; } MatMN;
typedef struct { double m[N]; }    VecN;
typedef struct { double m[M]; }    VecM;

/* ---------- 矩阵/向量基本操作 ---------- */

static void matNN_zero(MatNN *A) { memset(A, 0, sizeof(*A)); }

static void matNN_eye(MatNN *A) {
    int i, j;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            A->m[i][j] = (i == j) ? 1.0 : 0.0;
}

static void matNN_add(MatNN *C, const MatNN *A, const MatNN *B) {
    int i, j;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            C->m[i][j] = A->m[i][j] + B->m[i][j];
}

static void matNN_sub(MatNN *C, const MatNN *A, const MatNN *B) {
    int i, j;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            C->m[i][j] = A->m[i][j] - B->m[i][j];
}

static void matNN_mul(MatNN *C, const MatNN *A, const MatNN *B) {
    int i, j, k;
    MatNN T;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++) {
            T.m[i][j] = 0.0;
            for (k = 0; k < N; k++)
                T.m[i][j] += A->m[i][k] * B->m[k][j];
        }
    *C = T;
}

static void matNN_mulT(MatNN *C, const MatNN *A, const MatNN *B) {
    /* C = A * B^T */
    int i, j, k;
    MatNN T;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++) {
            T.m[i][j] = 0.0;
            for (k = 0; k < N; k++)
                T.m[i][j] += A->m[i][k] * B->m[j][k];
        }
    *C = T;
}

static void matNN_transpose(MatNN *C, const MatNN *A) {
    int i, j;
    MatNN T;
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            T.m[i][j] = A->m[j][i];
    *C = T;
}

static int matNN_inv(MatNN *C, const MatNN *A) {
    double det = A->m[0][0] * A->m[1][1] - A->m[0][1] * A->m[1][0];
    if (fabs(det) < 1e-12)
        return -1;
    C->m[0][0] =  A->m[1][1] / det;
    C->m[0][1] = -A->m[0][1] / det;
    C->m[1][0] = -A->m[1][0] / det;
    C->m[1][1] =  A->m[0][0] / det;
    return 0;
}

static void matMM_mul(MatMM *C, const MatMN *A, const MatNM *B) {
    int i, j, k;
    MatMM T;
    for (i = 0; i < M; i++)
        for (j = 0; j < M; j++) {
            T.m[i][j] = 0.0;
            for (k = 0; k < N; k++)
                T.m[i][j] += A->m[i][k] * B->m[k][j];
        }
    *C = T;
}

static void matMM_add(MatMM *C, const MatMM *A, const MatMM *B) {
    int i, j;
    for (i = 0; i < M; i++)
        for (j = 0; j < M; j++)
            C->m[i][j] = A->m[i][j] + B->m[i][j];
}

static void matMM_inv(MatMM *C, const MatMM *A) {
    C->m[0][0] = 1.0 / A->m[0][0];
}

static void vecN_add(VecN *c, const VecN *a, const VecN *b) {
    int i;
    for (i = 0; i < N; i++)
        c->m[i] = a->m[i] + b->m[i];
}

static void vecM_sub(VecM *c, const VecM *a, const VecM *b) {
    int i;
    for (i = 0; i < M; i++)
        c->m[i] = a->m[i] - b->m[i];
}

static void matNM_vecN_mul(VecN *c, const MatNM *A, const VecM *b) {
    int i, j;
    VecN T;
    for (i = 0; i < N; i++) {
        T.m[i] = 0.0;
        for (j = 0; j < M; j++)
            T.m[i] += A->m[i][j] * b->m[j];
    }
    *c = T;
}

/* ---------- 非线性函数与雅可比 ---------- */

static double g_accel = 0.5;

static void f_func(VecN *x_out, const VecN *x_in, double dt) {
    double p = x_in->m[0];
    double v = x_in->m[1];
    x_out->m[0] = p + v * dt;
    x_out->m[1] = v + 0.5 * g_accel * dt * dt;
}

static void F_jacobian(MatNN *F, const VecN *x, double dt) {
    (void)x;
    F->m[0][0] = 1.0;
    F->m[0][1] = dt;
    F->m[1][0] = 0.0;
    F->m[1][1] = 1.0;
}

static void h_func(VecM *z_out, const VecN *x) {
    double p = x->m[0];
    double v = x->m[1];
    z_out->m[0] = p * p + 3.0 * v;
}

static void H_jacobian(MatMN *H, const VecN *x) {
    double p = x->m[0];
    H->m[0][0] = 2.0 * p;
    H->m[0][1] = 3.0;
}

/* ---------- EKF 主流程 ---------- */

int main(void) {
    VecN x_est;
    MatNN P_est;
    MatNN Q;
    MatMM R;

    x_est.m[0] = 0.0;
    x_est.m[1] = 1.0;

    matNN_eye(&P_est);
    P_est.m[0][0] = 1.0;
    P_est.m[1][1] = 1.0;

    matNN_zero(&Q);
    Q.m[0][0] = 0.01;
    Q.m[1][1] = 0.01;

    R.m[0][0] = 0.5;

    double dt = 0.1;

    VecN x_true;
    x_true.m[0] = 0.0;
    x_true.m[1] = 1.0;

    printf("=== Extended Kalman Filter (EKF) Demo ===\n");
    printf("Step | TruePos | TrueVel | EstPos  | EstVel  | MeasZ   | EstZ\n");
    printf("-----+---------+---------+---------+---------+---------+---------\n");

    int k;
    for (k = 0; k < 10; k++) {
        /* 1. 真实系统推进 */
        VecN x_true_next;
        f_func(&x_true_next, &x_true, dt);
        x_true = x_true_next;

        /* 2. 生成观测 */
        VecM z_meas;
        h_func(&z_meas, &x_true);
        z_meas.m[0] += 0.05 * sin((double)k);

        /* 3. EKF 预测 */
        VecN x_pred;
        f_func(&x_pred, &x_est, dt);

        MatNN F;
        F_jacobian(&F, &x_est, dt);

        MatNN P_pred, FP, FPFt;
        matNN_mul(&FP, &F, &P_est);
        matNN_mulT(&FPFt, &FP, &F);
        matNN_add(&P_pred, &FPFt, &Q);

        /* 4. EKF 更新 */
        MatMN H;
        H_jacobian(&H, &x_pred);

        VecM z_pred;
        h_func(&z_pred, &x_pred);

        VecM y;
        vecM_sub(&y, &z_meas, &z_pred);

        /* PHt = P_pred * H^T  (N x M) */
        MatNM PHt;
        {
            int i, j, kk;
            for (i = 0; i < N; i++)
                for (j = 0; j < M; j++) {
                    PHt.m[i][j] = 0.0;
                    for (kk = 0; kk < N; kk++)
                        PHt.m[i][j] += P_pred.m[i][kk] * H.m[j][kk];
                }
        }

        /* S = H * PHt + R */
        MatMM S, HPHt;
        matMM_mul(&HPHt, &H, &PHt);
        matMM_add(&S, &HPHt, &R);

        MatMM S_inv;
        matMM_inv(&S_inv, &S);

        /* K = PHt * S_inv  (N x M) */
        MatNM K;
        {
            int i, j, kk;
            for (i = 0; i < N; i++)
                for (j = 0; j < M; j++) {
                    K.m[i][j] = 0.0;
                    for (kk = 0; kk < M; kk++)
                        K.m[i][j] += PHt.m[i][kk] * S_inv.m[kk][j];
                }
        }

        /* x_est = x_pred + K * y */
        VecN Ky;
        matNM_vecN_mul(&Ky, &K, &y);
        vecN_add(&x_est, &x_pred, &Ky);

        /* P_est = (I - K*H) * P_pred */
        MatNN KH, I, IKH;
        matNN_zero(&KH);
        {
            int i, j, kk;
            for (i = 0; i < N; i++)
                for (j = 0; j < N; j++) {
                    KH.m[i][j] = 0.0;
                    for (kk = 0; kk < M; kk++)
                        KH.m[i][j] += K.m[i][kk] * H.m[kk][j];
                }
        }
        matNN_eye(&I);
        matNN_sub(&IKH, &I, &KH);
        matNN_mul(&P_est, &IKH, &P_pred);

        /* 5. 打印 */
        VecM z_est;
        h_func(&z_est, &x_est);

        printf("%4d | %7.4f | %7.4f | %7.4f | %7.4f | %7.4f | %7.4f\n",
               k,
               x_true.m[0], x_true.m[1],
               x_est.m[0],  x_est.m[1],
               z_meas.m[0], z_est.m[0]);
    }

    printf("\nEKF demo finished.\n");
    return 0;
}
