#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define N_PARTICLES 1000
#define STATE_DIM 2
#define MEAS_DIM 1

typedef struct {
    double x[STATE_DIM];
    double weight;
} Particle;

static double randn(void) {
    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;
    if (u1 < 1e-12) u1 = 1e-12;
    return sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
}

static void normalize_weights(Particle *p, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += p[i].weight;
    if (sum < 1e-300) sum = 1e-300;
    for (int i = 0; i < n; i++) p[i].weight /= sum;
}

static void systematic_resample(Particle *p, int n) {
    Particle *new_p = (Particle *)malloc(sizeof(Particle) * n);
    double *cdf = (double *)malloc(sizeof(double) * n);
    if (!new_p || !cdf) {
        free(new_p);
        free(cdf);
        return;
    }
    cdf[0] = p[0].weight;
    for (int i = 1; i < n; i++) cdf[i] = cdf[i - 1] + p[i].weight;
    double u = ((double)rand() / RAND_MAX) / n;
    int idx = 0;
    for (int i = 0; i < n; i++) {
        double target = u + (double)i / n;
        while (idx < n - 1 && target > cdf[idx]) idx++;
        new_p[i] = p[idx];
        new_p[i].weight = 1.0 / n;
    }
    for (int i = 0; i < n; i++) p[i] = new_p[i];
    free(new_p);
    free(cdf);
}

static void particle_filter_step(Particle *p, int n,
                                 double *meas,
                                 double process_noise,
                                 double meas_noise) {
    for (int i = 0; i < n; i++) {
        p[i].x[0] += p[i].x[1] + process_noise * randn();
        p[i].x[1] += process_noise * randn();
    }

    for (int i = 0; i < n; i++) {
        double predicted = p[i].x[0];
        double diff = meas[0] - predicted;
        double exponent = -(diff * diff) / (2.0 * meas_noise * meas_noise);
        p[i].weight *= exp(exponent);
    }

    normalize_weights(p, n);

    double neff = 0.0;
    for (int i = 0; i < n; i++) neff += p[i].weight * p[i].weight;
    neff = 1.0 / (neff + 1e-300);

    if (neff < n / 2.0) {
        systematic_resample(p, n);
    }
}

static void estimate_state(Particle *p, int n, double *est) {
    est[0] = 0.0;
    est[1] = 0.0;
    for (int i = 0; i < n; i++) {
        est[0] += p[i].weight * p[i].x[0];
        est[1] += p[i].weight * p[i].x[1];
    }
}

int main(void) {
    srand((unsigned)time(NULL));

    Particle particles[N_PARTICLES];
    for (int i = 0; i < N_PARTICLES; i++) {
        particles[i].x[0] = 0.0 + 1.0 * randn();
        particles[i].x[1] = 0.0 + 1.0 * randn();
        particles[i].weight = 1.0 / N_PARTICLES;
    }

    double true_pos = 0.0;
    double true_vel = 1.0;
    double process_noise = 0.5;
    double meas_noise = 2.0;

    printf("=== Particle Filter State Estimation (Strong Noise) ===\n");
    printf("Step | True Pos | Measured | Est Pos  | Est Vel\n");
    printf("-----+----------+----------+----------+----------\n");

    for (int t = 0; t < 20; t++) {
        true_pos += true_vel + process_noise * randn();
        true_vel += process_noise * randn();

        double meas[MEAS_DIM];
        meas[0] = true_pos + meas_noise * randn();

        particle_filter_step(particles, N_PARTICLES, meas,
                             process_noise, meas_noise);

        double est[STATE_DIM];
        estimate_state(particles, N_PARTICLES, est);

        printf("%4d | %8.3f | %8.3f | %8.3f | %8.3f\n",
               t + 1, true_pos, meas[0], est[0], est[1]);
    }

    printf("=== Done ===\n");
    return 0;
}
