#include <stdio.h>
#include <math.h>
#include <string.h>

/* ==================== 矩阵维度定义 ==================== */
#define NX  3   /* 状态维数 */
#define NZ  2   /* 观测维数 */
#define NU  1   /* 控制维数 */

/* ==================== 基础矩阵运算 ==================== */

/* 矩阵置零 */
static void mat_zero(double *A, int rows, int cols)
{
    memset(A, 0, sizeof(double) * rows * cols);
}

/* 矩阵拷贝 C = A */
static void mat_copy(const double *A, double *C, int rows, int cols)
{
    memcpy(C, A, sizeof(double) * rows * cols);
}

/* 矩阵加法 C = A + B */
static void mat_add(const double *A, const double *B, double *C, int rows, int cols)
{
    int i, n = rows * cols;
    for (i = 0; i < n; i++) C[i] = A[i] + B[i];
}

/* 矩阵减法 C = A - B */
static void mat_sub(const double *A, const double *B, double *C, int rows, int cols)
{
    int i, n = rows * cols;
    for (i = 0; i < n; i++) C[i] = A[i] - B[i];
}

/* 矩阵乘法 C = A * B, A: r x m, B: m x c */
static void mat_mul(const double *A, const double *B, double *C,
                    int r, int m, int c)
{
    int i, j, k;
    for (i = 0; i < r; i++) {
        for (j = 0; j < c; j++) {
            double sum = 0.0;
            for (k = 0; k < m; k++) {
                sum += A[i * m + k] * B[k * c + j];
            }
            C[i * c + j] = sum;
        }
    }
}

/* 矩阵转置 C = A^T, A: r x c -> C: c x r */
static void mat_trans(const double *A, double *C, int r, int c)
{
    int i, j;
    for (i = 0; i < r; i++)
        for (j = 0; j < c; j++)
            C[j * r + i] = A[i * c + j];
}

/* 单位矩阵 */
static void mat_eye(double *A, int n)
{
    int i;
    mat_zero(A, n, n);
    for (i = 0; i < n; i++) A[i * n + i] = 1.0;
}

/* 矩阵求逆（高斯-约旦法），A: n x n，成功返回0 */
static int mat_inv(const double *A, double *Ainv, int n)
{
    double aug[NX][2 * NX];
    int i, j, k;

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            aug[i][j] = A[i * n + j];
            aug[i][j + n] = (i == j) ? 1.0 : 0.0;
        }
    }

    for (i = 0; i < n; i++) {
        /* 选主元 */
        int pivot = i;
        double maxv = fabs(aug[i][i]);
        for (k = i + 1; k < n; k++) {
            if (fabs(aug[k][i]) > maxv) {
                maxv = fabs(aug[k][i]);
                pivot = k;
            }
        }
        if (maxv < 1e-12) return -1; /* 奇异 */

        if (pivot != i) {
            for (j = 0; j < 2 * n; j++) {
                double tmp = aug[i][j];
                aug[i][j] = aug[pivot][j];
                aug[pivot][j] = tmp;
            }
        }

        /* 归一化主元行 */
        double div = aug[i][i];
        for (j = 0; j < 2 * n; j++) aug[i][j] /= div;

        /* 消元 */
        for (k = 0; k < n; k++) {
            if (k == i) continue;
            double factor = aug[k][i];
            for (j = 0; j < 2 * n; j++) {
                aug[k][j] -= factor * aug[i][j];
            }
        }
    }

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            Ainv[i * n + j] = aug[i][j + n];

    return 0;
}

/* ==================== EKF 数据结构 ==================== */

typedef struct {
    double x[NX];          /* 状态估计 */
    double P[NX * NX];     /* 状态协方差 */
    double Q[NX * NX];     /* 过程噪声协方差 */
    double R[NZ * NZ];     /* 观测噪声协方差 */
} EKF_t;

/* ==================== 非线性系统模型 ==================== */

/*
 * 示例非线性系统：
 *   状态 x = [位置, 速度, 加速度]^T
 *   控制 u = 加加速度（jerk）
 *
 *   离散状态方程（采样周期 dt）：
 *     p(k+1) = p(k) + v(k)*dt + 0.5*a(k)*dt^2
 *     v(k+1) = v(k) + a(k)*dt
 *     a(k+1) = a(k) + u(k)*dt
 *
 *   观测方程（仅观测位置和速度）：
 *     z1 = p + 噪声
 *     z2 = v + 噪声
 */

#define DT 0.01

/* 状态转移函数 x_next = f(x, u) */
static void f_func(const double *x, const double *u, double *x_next)
{
    double p = x[0], v = x[1], a = x[2];
    double jerk = u[0];

    x_next[0] = p + v * DT + 0.5 * a * DT * DT;
    x_next[1] = v + a * DT;
    x_next[2] = a + jerk * DT;
}

/* 观测函数 z_pred = h(x) */
static void h_func(const double *x, double *z_pred)
{
    z_pred[0] = x[0]; /* 位置 */
    z_pred[1] = x[1]; /* 速度 */
}

/* 状态转移雅可比矩阵 F = df/dx */
static void jacobian_F(const double *x, const double *u, double *F)
{
    (void)x; (void)u;
    mat_zero(F, NX, NX);
    F[0 * NX + 0] = 1.0;
    F[0 * NX + 1] = DT;
    F[0 * NX + 2] = 0.5 * DT * DT;
    F[1 * NX + 1] = 1.0;
    F[1 * NX + 2] = DT;
    F[2 * NX + 2] = 1.0;
}

/* 观测雅可比矩阵 H = dh/dx */
static void jacobian_H(const double *x, double *H)
{
    (void)x;
    mat_zero(H, NZ, NX);
    H[0 * NX + 0] = 1.0; /* z1 对 p */
    H[1 * NX + 1] = 1.0; /* z2 对 v */
}

/* ==================== EKF 初始化 ==================== */

static void ekf_init(EKF_t *ekf)
{
    int i;

    /* 初始状态 */
    ekf->x[0] = 0.0;
    ekf->x[1] = 0.0;
    ekf->x[2] = 0.0;

    /* 初始协方差 */
    mat_zero(ekf->P, NX, NX);
    for (i = 0; i < NX; i++) ekf->P[i * NX + i] = 1.0;

    /* 过程噪声 */
    mat_zero(ekf->Q, NX, NX);
    for (i = 0; i < NX; i++) ekf->Q[i * NX + i] = 1e-4;

    /* 观测噪声 */
    mat_zero(ekf->R, NZ, NZ);
    for (i = 0; i < NZ; i++) ekf->R[i * NZ + i] = 1e-2;
}

/* ==================== EKF 预测步 ==================== */

static void ekf_predict(EKF_t *ekf, const double *u)
{
    double x_pred[NX];
    double F[NX * NX];
    double F_T[NX * NX];
    double FP[NX * NX];
    double FPF_T[NX * NX];
    double P_new[NX * NX];

    /* 1. 状态预测 x = f(x, u) */
    f_func(ekf->x, u, x_pred);
    memcpy(ekf->x, x_pred, sizeof(x_pred));

    /* 2. 计算雅可比 F */
    jacobian_F(ekf->x, u, F);

    /* 3. 协方差预测 P = F*P*F^T + Q */
    mat_trans(F, F_T, NX, NX);
    mat_mul(F, ekf->P, FP, NX, NX, NX);
    mat_mul(FP, F_T, FPF_T, NX, NX, NX);
    mat_add(FPF_T, ekf->Q, P_new, NX, NX);
    memcpy(ekf->P, P_new, sizeof(P_new));
}

/* ==================== EKF 更新步 ==================== */

static void ekf_update(EKF_t *ekf, const double *z)
{
    double H[NZ * NX];
    double H_T[NX * NZ];
    double HP[NZ * NX];
    double HPH_T[NZ * NZ];
    double S[NZ * NZ];
    double S_inv[NZ * NZ];
    double K[NX * NZ];
    double PH_T[NX * NZ];
    double z_pred[NZ];
    double y[NZ];           /* 新息 */
    double Ky[NX];
    double KH[NX * NX];
    double I[NX * NX];
    double I_KH[NX * NX];
    double P_new[NX * NX];
    int i;

    /* 1. 计算观测雅可比 H */
    jacobian_H(ekf->x, H);

    /* 2. 计算新息 y = z - h(x) */
    h_func(ekf->x, z_pred);
    for (i = 0; i < NZ; i++) y[i] = z[i] - z_pred[i];

    /* 3. S = H*P*H^T + R */
    mat_trans(H, H_T, NZ, NX);
    mat_mul(H, ekf->P, HP, NZ, NX, NX);
    mat_mul(HP, H_T, HPH_T, NZ, NX, NZ);
    mat_add(HPH_T, ekf->R, S, NZ, NZ);

    /* 4. 计算卡尔曼增益 K = P*H^T*S^-1 */
    if (mat_inv(S, S_inv, NZ) != 0) {
        printf("[EKF] Warning: S matrix singular, skip update.\n");
        return;
    }
    mat_mul(ekf->P, H_T, PH_T, NX, NX, NZ);
    mat_mul(PH_T, S_inv, K, NX, NZ, NZ);

    /* 5. 状态更新 x = x + K*y */
    mat_mul(K, y, Ky, NX, NZ, 1);
    for (i = 0; i < NX; i++) ekf->x[i] += Ky[i];

    /* 6. 协方差更新 P = (I - K*H)*P */
    mat_mul(K, H, KH, NX, NZ, NX);
    mat_eye(I, NX);
    mat_sub(I, KH, I_KH, NX, NX);
    mat_mul(I_KH, ekf->P, P_new, NX, NX, NX);
    memcpy(ekf->P, P_new, sizeof(P_new));
}

/* ==================== 打印辅助 ==================== */

static void print_state(const char *tag, const EKF_t *ekf)
{
    printf("%s: x = [%.6f, %.6f, %.6f]\n",
           tag, ekf->x[0], ekf->x[1], ekf->x[2]);
}

/* ==================== main 测试 ==================== */

int main(void)
{
    EKF_t ekf;
    double u[NU];
    double z[NZ];
    int k;

    printf("===== Extended Kalman Filter (EKF) Demo =====\n");
    printf("State: [position, velocity, acceleration]\n");
    printf("Observation: [position, velocity]\n\n");

    /* 初始化 EKF */
    ekf_init(&ekf);
    print_state("Init", &ekf);

    /* 模拟 20 步 */
    for (k = 0; k < 20; k++) {
        /* 控制输入：加加速度 */
        u[0] = 1.0;

        /* 预测 */
        ekf_predict(&ekf, u);

        /* 模拟真实观测（带噪声） */
        z[0] = ekf.x[0] + 0.01 * sin((double)k);  /* 位置观测 */
        z[1] = ekf.x[1] + 0.01 * cos((double)k);  /* 速度观测 */

        /* 更新 */
        ekf_update(&ekf, z);

        printf("Step %2d | u=%.2f | z=[%.4f, %.4f] | ",
               k, u[0], z[0], z[1]);
        print_state("est", &ekf);
    }

    printf("\n===== EKF Demo Finished =====\n");
    return 0;
}
