#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define WMA_WINDOW_SIZE 8

typedef struct {
    float buffer[WMA_WINDOW_SIZE];
    float weights[WMA_WINDOW_SIZE];
    uint32_t index;
    uint32_t count;
    float weight_sum;
} WeightedMovingAverage;

static void WMA_Init(WeightedMovingAverage *wma)
{
    uint32_t i;
    memset(wma->buffer, 0, sizeof(wma->buffer));
    wma->index = 0;
    wma->count = 0;
    wma->weight_sum = 0.0f;

    for (i = 0; i < WMA_WINDOW_SIZE; i++) {
        wma->weights[i] = (float)(i + 1);
        wma->weight_sum += wma->weights[i];
    }
}

static float WMA_Update(WeightedMovingAverage *wma, float new_sample)
{
    uint32_t i;
    uint32_t pos;
    float weighted_sum = 0.0f;

    wma->buffer[wma->index] = new_sample;
    wma->index = (wma->index + 1) % WMA_WINDOW_SIZE;
    if (wma->count < WMA_WINDOW_SIZE) {
        wma->count++;
    }

    for (i = 0; i < wma->count; i++) {
        pos = (wma->index + WMA_WINDOW_SIZE - wma->count + i) % WMA_WINDOW_SIZE;
        weighted_sum += wma->buffer[pos] * wma->weights[i];
    }

    if (wma->count < WMA_WINDOW_SIZE) {
        float partial_sum = 0.0f;
        for (i = 0; i < wma->count; i++) {
            partial_sum += wma->weights[i];
        }
        return weighted_sum / partial_sum;
    }

    return weighted_sum / wma->weight_sum;
}

int main(void)
{
    WeightedMovingAverage wma;
    float test_data[] = {10.0f, 12.0f, 14.0f, 16.0f, 18.0f, 20.0f, 22.0f, 24.0f, 26.0f, 28.0f};
    uint32_t i;
    float result;

    WMA_Init(&wma);

    printf("Weighted Moving Average Filter Test\n");
    printf("Window Size: %d\n", WMA_WINDOW_SIZE);
    printf("Weights: ");
    for (i = 0; i < WMA_WINDOW_SIZE; i++) {
        printf("%.1f ", wma.weights[i]);
    }
    printf("\n\n");

    printf("Sample\tInput\tOutput\n");
    printf("------\t-----\t------\n");

    for (i = 0; i < sizeof(test_data) / sizeof(test_data[0]); i++) {
        result = WMA_Update(&wma, test_data[i]);
        printf("%u\t%.1f\t%.4f\n", i + 1, test_data[i], result);
    }

    return 0;
}
