#include <stdio.h>
#include <math.h>
#include <complex.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FFT_SIZE 8

typedef struct {
    double real;
    double imag;
} Complex;

static void fft_radix2(Complex *x, int n) {
    int i, j, k, m;
    int len;
    Complex t;
    double angle;
    Complex w, wp;

    j = 0;
    for (i = 1; i < n; i++) {
        k = n >> 1;
        while (k <= j) {
            j -= k;
            k >>= 1;
        }
        j += k;
        if (i < j) {
            t = x[i];
            x[i] = x[j];
            x[j] = t;
        }
    }

    for (len = 2; len <= n; len <<= 1) {
        angle = -2.0 * M_PI / (double)len;
        w.real = cos(angle);
        w.imag = sin(angle);
        for (i = 0; i < n; i += len) {
            wp.real = 1.0;
            wp.imag = 0.0;
            for (k = 0; k < len / 2; k++) {
                Complex u = x[i + k];
                Complex v;
                v.real = x[i + k + len / 2].real * wp.real - x[i + k + len / 2].imag * wp.imag;
                v.imag = x[i + k + len / 2].real * wp.imag + x[i + k + len / 2].imag * wp.real;
                x[i + k].real = u.real + v.real;
                x[i + k].imag = u.imag + v.imag;
                x[i + k + len / 2].real = u.real - v.real;
                x[i + k + len / 2].imag = u.imag - v.imag;
                t.real = wp.real * w.real - wp.imag * w.imag;
                t.imag = wp.real * w.imag + wp.imag * w.real;
                wp = t;
            }
        }
    }
}

static void compute_magnitude(const Complex *x, double *mag, int n) {
    int i;
    for (i = 0; i < n; i++) {
        mag[i] = sqrt(x[i].real * x[i].real + x[i].imag * x[i].imag);
    }
}

int main(void) {
    Complex data[FFT_SIZE];
    double mag[FFT_SIZE];
    int i;

    for (i = 0; i < FFT_SIZE; i++) {
        data[i].real = 0.0;
        data[i].imag = 0.0;
    }

    for (i = 0; i < FFT_SIZE; i++) {
        data[i].real = sin(2.0 * M_PI * 1.0 * i / FFT_SIZE) +
                       0.5 * sin(2.0 * M_PI * 3.0 * i / FFT_SIZE);
    }

    printf("Input signal:\n");
    for (i = 0; i < FFT_SIZE; i++) {
        printf("x[%d] = %8.4f\n", i, data[i].real);
    }

    fft_radix2(data, FFT_SIZE);
    compute_magnitude(data, mag, FFT_SIZE);

    printf("\nFFT results (complex):\n");
    for (i = 0; i < FFT_SIZE; i++) {
        printf("X[%d] = %8.4f + j%8.4f\n", i, data[i].real, data[i].imag);
    }

    printf("\nMagnitude spectrum:\n");
    for (i = 0; i < FFT_SIZE; i++) {
