#define WMA_WINDOW_SIZE 8

typedef struct {
    double buffer[WMA_WINDOW_SIZE];
    double weights[WMA_WINDOW_SIZE];
    int index;
    int count;
    double weight_sum;
} WeightedMovingAverage;

void WMA_Init(WeightedMovingAverage *wma) {
    memset(wma->buffer, 0, sizeof(wma->buffer));
    wma->index = 0;
    wma->count = 0;
    wma->weight_sum = 0.0;

    for (int i = 0; i < WMA_WINDOW_SIZE; i++) {
        wma->weights[i] = (double)(i + 1);
        wma->weight_sum += wma->weights[i];
    }
}

double WMA_Update(WeightedMovingAverage *wma, double new_value) {
    wma->buffer[wma->index] = new_value;
    wma->index = (wma->index + 1) % WMA_WINDOW_SIZE;
    if (wma->count < WMA_WINDOW_SIZE) {
        wma->count++;
    }

    double weighted_sum = 0.0;
    double current_weight_sum = 0.0;

    for (int i = 0; i < wma->count; i++) {
        int buf_idx = (wma->index - 1 - i + WMA_WINDOW_SIZE) % WMA_WINDOW_SIZE;
        double weight = wma->weights[wma->count - 1 - i];
        weighted_sum += wma->buffer[buf_idx] * weight;
        current_weight_sum += weight;
    }

    if (current_weight_sum == 0.0) {
        return 0.0;
    }

    return weighted_sum / current_weight_sum;
}

double WMA_GetValue(WeightedMovingAverage *wma) {
    double weighted_sum = 0.0;
    double current_weight_sum = 0.0;

    for (int i = 0; i < wma->count; i++) {
        int buf_idx = (wma->index - 1 - i + WMA_WINDOW_SIZE) % WMA_WINDOW_SIZE;
        double weight = wma->weights[wma->count - 1 - i];
        weighted_sum += wma->buffer[buf_idx] * weight;
        current_weight_sum += weight;
    }

    if (current_weight_sum == 0.0) {
        return 0.0;
    }

    return weighted_sum / current_weight_sum;
}

int main(void) {
