typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum_sq;
} RMS_Calculator;

void RMS_Init(RMS_Calculator *rms) {
    int i;
    for (i = 0; i < WINDOW_SIZE; i++) {
        rms->buffer[i] = 0.0f;
    }
    rms->index = 0;
    rms->count = 0;
    rms->sum_sq = 0.0f;
}

float RMS_Update(RMS_Calculator *rms, float sample) {
    float abs_sample = fabsf(sample);
    float sq = abs_sample * abs_sample;

    if (rms->count < WINDOW_SIZE) {
        rms->buffer[rms->index] = sq;
        rms->sum_sq += sq;
        rms->count++;
    } else {
        rms->sum_sq -= rms->buffer[rms->index];
        rms->buffer[rms->index] = sq;
        rms->sum_sq += sq;
    }

    rms->index = (rms->index + 1) % WINDOW_SIZE;

    if (rms->count == 0) {
        return 0.0f;
    }

    return sqrtf(rms->sum_sq / (float)rms->count);
}

int main(void) {
    RMS_Calculator rms;
    RMS_Init(&rms);

    float dt = 1.0f / SAMPLE_RATE;
    float omega = 2.0f * PI * SIGNAL_FREQ;
    float peak = 1.0f;
    float dc_offset = 0.0f;

    int i;
    float rms_value = 0.0f;

    printf("=== True RMS Calculation (Full-Wave Rectify + Integrate) ===\n");
    printf("Sample Rate: %.0f Hz, Signal Freq: %.0f Hz, Window: %d samples\n\n",
           SAMPLE_RATE, SIGNAL_FREQ, WINDOW_SIZE);

    for (i = 0; i < TOTAL_SAMPLES; i++) {
        float t = (float)i * dt;
        float sample = peak * sinf(omega * t) + dc_offset;
        rms_value = RMS_Update(&rms, sample);

        if (i % 200 == 0 || i == TOTAL_SAMPLES - 1) {
            printf("Sample[%4d] t=%.4fs  input=%+.4f  RMS=%.6f\n",
                   i, t, sample, rms_value);
        }
    }

    float expected = peak / sqrtf(2.0f);
    printf("\nExpected RMS (sine, peak=%.1f): %.6f\n", peak, expected);
    printf("Calculated RMS: %.6f\n", rms_value);
    printf("Error: %.6f%%\n", fabsf(rms_value - expected) / expected * 100.0f);

    return 0;
}
