#include <stdio.h>
#include <math.h>
#include <complex.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define FFT_SIZE 8

typedef float fft_data_t;

static void fft_radix2(fft_data_t *real, fft_data_t *imag, int n)
{
    int i, j, k, m;
    int len;
    fft_data_t tr, ti;
    fft_data_t ur, ui, vr, vi;
    fft_data_t wr, wi;
    fft_data_t angle;

    j = 0;
    for (i = 0; i < n - 1; i++) {
        if (i < j) {
            tr = real[i];
            ti = imag[i];
            real[i] = real[j];
            imag[i] = imag[j];
            real[j] = tr;
            imag[j] = ti;
        }
        k = n >> 1;
        while (k <= j) {
            j -= k;
            k >>= 1;
        }
        j += k;
    }

    for (len = 2; len <= n; len <<= 1) {
        m = len >> 1;
        angle = -2.0f * (fft_data_t)M_PI / (fft_data_t)len;
        wr = cosf(angle);
        wi = sinf(angle);

        for (i = 0; i < n; i += len) {
            ur = 1.0f;
            ui = 0.0f;
            for (k = 0; k < m; k++) {
                int idx1 = i + k;
                int idx2 = i + k + m;

                vr = real[idx2] * ur - imag[idx2] * ui;
                vi = real[idx2] * ui + imag[idx2] * ur;

                real[idx2] = real[idx1] - vr;
                imag[idx2] = imag[idx1] - vi;
                real[idx1] += vr;
                imag[idx1] += vi;

                tr = ur * wr - ui * wi;
                ui = ur * wi + ui * wr;
                ur = tr;
            }
        }
    }
}

static void fft_magnitude(const fft_data_t *real, const fft_data_t *imag,
                          fft_data_t *mag, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        mag[i] = sqrtf(real[i] * real[i] + imag[i] * imag[i]);
    }
}

static void fft_harmonic_analysis(const fft_data_t *mag, int n,
                                  fft_data_t sample_rate,
                                  fft_data_t *freq, fft_data_t *amp)
{
    int i;
    fft_data_t bin_res = sample_rate / (fft_data_t)n;
    for (i = 0; i < n / 2; i++) {
        freq[i] = (fft_data_t)i * bin_res;
        amp[i] = mag[i] * 2.0f / (fft_data_t)n;
    }
}

int main(void)
{
    fft_data_t real[FFT_SIZE];
    fft_data_t imag[FFT_SIZE];
    fft_data_t mag[FFT_SIZE];
    fft_data_t freq[FFT_SIZE / 2];
    fft_data_t amp[FFT_SIZE / 2];
    fft_data_t sample_rate = 8000.0f;
    int i;

    for (i = 0; i < FFT_SIZE; i++) {
        real[i] = sinf(2.0f * (fft_data_t)M_PI * 1000.0f * (fft_data_t)i / sample_rate)
                + 0.5f * sinf(2.0f * (fft_data_t)M_PI * 2000.0f * (fft_data_t)i / sample_rate);
        imag[i] = 0.0f;
    }

    printf("Input signal (real part):\n");
    for (i = 0; i < FFT_SIZE; i++) {
        printf("  x[%d] = %8.4f\n", i, real[i]);
    }

    fft_radix2(real, imag, FFT_SIZE);

    printf("\nFFT output (complex):\n");
    for (i = 0; i < FFT_SIZE; i++) {
        printf("  X[%d] = %8.4f + j%8.4f\n", i, real[i], imag[i]);
    }

    fft_magnitude(real, imag, mag, FFT_SIZE);

    printf("\nMagnitude spectrum:\n");
    for (i = 0; i < FFT_SIZE; i++) {
        printf("  |X[%d]| = %8.4f\n", i, mag[i]);
    }

    fft_harmonic_analysis(mag, FFT_SIZE, sample_rate, freq, amp);

    printf("\nHarmonic analysis (sample rate = %.1f Hz):\n", sample_rate);
    printf("  %-10s %-12s\n", "Freq(Hz)", "Amp");
    for (i = 0; i < FFT_SIZE / 2; i++) {
        printf("  %-10.2f %-12.4f\n", freq[i], amp[i]);
    }

    return 0;
}
