#define PI 3.14159265358979323846f

/* 模拟采样参数 */
#define SAMPLE_RATE_HZ      10000.0f
#define SIGNAL_FREQ_HZ      50.0f
#define BUFFER_SIZE         256
#define DELAY_SAMPLES       12

/* 模拟寄存器（使用普通变量代替绝对地址，避免段错误） */
static volatile uint16_t mock_adc_data = 0;
static volatile uint16_t mock_dac_data = 0;
static volatile uint32_t mock_ctrl     = 0;

#define REG_ADC_DATA        (mock_adc_data)
#define REG_DAC_DATA        (mock_dac_data)
#define REG_CTRL            (mock_ctrl)

/* 环形缓冲区结构 */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   write_idx;
    int   read_idx;
    int   delay;
} DelayLine;

/* 初始化延迟线 */
void delay_line_init(DelayLine *dl, int delay_samples)
{
    int i;
    for (i = 0; i < BUFFER_SIZE; i++) {
        dl->buffer[i] = 0.0f;
    }
    dl->write_idx = 0;
    dl->read_idx  = 0;
    dl->delay     = delay_samples;
}

/* 写入新样本并返回延迟后的样本 */
float delay_line_process(DelayLine *dl, float input)
{
    float output;

    dl->buffer[dl->write_idx] = input;

    dl->read_idx = dl->write_idx - dl->delay;
    if (dl->read_idx < 0) {
        dl->read_idx += BUFFER_SIZE;
    }

    output = dl->buffer[dl->read_idx];

    dl->write_idx++;
    if (dl->write_idx >= BUFFER_SIZE) {
        dl->write_idx = 0;
    }

    return output;
}

/* 生成正弦波样本 */
float generate_sine(float freq_hz, float sample_rate_hz, int sample_index)
{
    float t = (float)sample_index / sample_rate_hz;
    return sinf(2.0f * PI * freq_hz * t);
}

/* 计算两个信号的相位差（度） */
float calculate_phase_diff(float *sig1, float *sig2, int len)
{
    float sum_xy = 0.0f;
    float sum_x2 = 0.0f;
    float sum_y2 = 0.0f;
    int i;

    for (i = 0; i < len; i++) {
        sum_xy += sig1[i] * sig2[i];
        sum_x2 += sig1[i] * sig1[i];
        sum_y2 += sig2[i] * sig2[i];
    }

    if (sum_x2 > 0.0f && sum_y2 > 0.0f) {
        float cos_theta = sum_xy / sqrtf(sum_x2 * sum_y2);
        if (cos_theta > 1.0f)  cos_theta = 1.0f;
        if (cos_theta < -1.0f) cos_theta = -1.0f;
        return acosf(cos_theta) * 180.0f / PI;
    }
    return 0.0f;
}

int main(void)
{
    DelayLine dl;
    float input_sig[BUFFER_SIZE];
    float output_sig[BUFFER_SIZE];
    float phase_diff;
    int i;

    printf("=== 信号相位校准（延迟补偿）测试 ===\n");
    printf("采样率: %.0f Hz, 信号频率: %.0f Hz\n", SAMPLE_RATE_HZ, SIGNAL_FREQ_HZ);
    printf("延迟样本数: %d (对应 %.3f ms)\n",
           DELAY_SAMPLES,
           (float)DELAY_SAMPLES / SAMPLE_RATE_HZ * 1000.0f);

    /* 初始化延迟线 */
    delay_line_init(&dl, DELAY_SAMPLES);

    /* 生成输入信号并处理 */
    for (i = 0; i < BUFFER_SIZE; i++) {
        input_sig[i] = generate_sine(SIGNAL_FREQ_HZ, SAMPLE_RATE_HZ, i);
        output_sig[i] = delay_line_process(&dl, input_sig[i]);
    }

    /* 计算延迟前后的相位差 */
    phase_diff = calculate_phase_diff(input_sig, output_sig, BUFFER_SIZE);

    printf("\n--- 处理结果 ---\n");
    printf("输入信号与延迟输出信号的相位差: %.2f 度\n", phase_diff);

    /* 打印部分样本对比 */
    printf("\n--- 样本对比 (前10个) ---\n");
    printf("索引\t输入\t\t延迟输出\n");
    for (i = 0; i < 10; i++) {
        printf("%d\t%.6f\t%.6f\n", i, input_sig[i], output_sig[i]);
    }

    /* 模拟寄存器读写（mock） */
    REG_CTRL = 0x01;
    REG_DAC_DATA = (uint16_t)(output_sig[BUFFER_SIZE - 1] * 2048.0f + 2048.0f);
    printf("\nDAC 输出寄存器值: %u\n", (unsigned int)REG_DAC_DATA);

    printf("\n=== 测试完成 ===\n");
    return 0;
}
