static volatile uint32_t mock_TIMx_CR1 = 0;
static volatile uint32_t mock_TIMx_SR  = 0;
static volatile uint32_t mock_TIMx_CNT = 0;
static volatile uint32_t mock_TIMx_PSC = 0;
static volatile uint32_t mock_TIMx_ARR = 0;
static volatile uint32_t mock_GPIO_INPUT_PIN = 0;

#define TIMx_CR1        (mock_TIMx_CR1)
#define TIMx_SR         (mock_TIMx_SR)
#define TIMx_CNT        (mock_TIMx_CNT)
#define TIMx_PSC        (mock_TIMx_PSC)
#define TIMx_ARR        (mock_TIMx_ARR)
#define GPIO_INPUT_PIN  (mock_GPIO_INPUT_PIN)

#define SYSTEM_CLOCK_HZ 72000000UL

#define TIM_CR1_CEN     (1U << 0)
#define TIM_SR_CC1IF    (1U << 1)

/* ================= 周期计数法频率测量 ================= */

typedef struct {
    uint32_t period_counts;
    uint32_t frequency_hz;
    uint32_t timer_clk_hz;
    bool     valid;
} FreqMeasureResult;

static void timer_init_for_period_measure(void)
{
    TIMx_CR1 &= ~TIM_CR1_CEN;
    TIMx_PSC = (SYSTEM_CLOCK_HZ / 1000000UL) - 1U;
    TIMx_ARR = 0xFFFFU;
    TIMx_CNT = 0;
    TIMx_SR &= ~TIM_SR_CC1IF;
    TIMx_CR1 |= TIM_CR1_CEN;
}

/* ================= 测试用模拟信号生成 ================= */
static uint32_t mock_signal_phase = 0;
static uint32_t mock_signal_period_counts = 1000;

static void mock_signal_update(void)
{
    mock_signal_phase++;
    if (mock_signal_phase >= mock_signal_period_counts) {
        mock_signal_phase = 0;
    }
    if (mock_signal_phase < (mock_signal_period_counts / 2U)) {
        GPIO_INPUT_PIN = 1U;
    } else {
        GPIO_INPUT_PIN = 0U;
    }
}

static void mock_timer_update(void)
{
    if (TIMx_CR1 & TIM_CR1_CEN) {
        TIMx_CNT++;
        if (TIMx_CNT > TIMx_ARR) {
            TIMx_CNT = 0;
        }
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    FreqMeasureResult result;
    uint32_t start_count = 0;
    uint32_t end_count = 0;
    uint32_t timer_clk = 0;
    int edge_count = 0;
    uint32_t i;

    result.period_counts = 0;
    result.frequency_hz = 0;
    result.timer_clk_hz = 0;
    result.valid = false;

    printf("========================================\n");
    printf("  信号频率测量（周期计数法）测试\n");
    printf("========================================\n");
    printf("系统时钟: %lu Hz\n", (unsigned long)SYSTEM_CLOCK_HZ);

    timer_init_for_period_measure();
    printf("定时器预分频: %lu\n", (unsigned long)TIMx_PSC);
    printf("定时器计数频率: %lu Hz\n",
           (unsigned long)(SYSTEM_CLOCK_HZ / (TIMx_PSC + 1U)));
    printf("自动重装载值: %lu\n", (unsigned long)TIMx_ARR);
    printf("----------------------------------------\n");

    /* 重置模拟信号 */
    mock_signal_phase = 0;
    GPIO_INPUT_PIN = 0U;
    TIMx_CNT = 0;

    timer_clk = SYSTEM_CLOCK_HZ / (TIMx_PSC + 1U);

    /* 模拟运行，捕获两个上升沿 */
    for (i = 0; i < 10000U; i++) {
        uint32_t prev_pin = GPIO_INPUT_PIN;

        mock_signal_update();
        mock_timer_update();

        if (prev_pin == 0U && GPIO_INPUT_PIN == 1U) {
            edge_count++;
            if (edge_count == 1) {
                start_count = TIMx_CNT;
            } else if (edge_count == 2) {
                end_count = TIMx_CNT;
                break;
            }
        }
    }

    if (end_count >= start_count) {
        result.period_counts = end_count - start_count;
    } else {
        result.period_counts = (TIMx_ARR - start_count) + end_count + 1U;
    }

    result.timer_clk_hz = timer_clk;
    if (result.period_counts > 0U) {
        result.frequency_hz = timer_clk / result.period_counts;
        result.valid = true;
    } else {
        result.frequency_hz = 0U;
        result.valid = false;
    }

    printf("测量结果:\n");
    printf("  周期计数值: %lu\n", (unsigned long)result.period_counts);
    printf("  定时器频率: %lu Hz\n", (unsigned long)result.timer_clk_hz);
    printf("  信号频率:   %lu Hz\n", (unsigned long)result.frequency_hz);
    printf("  测量有效:   %s\n", result.valid ? "是" : "否");
    printf("----------------------------------------\n");

    printf("预期信号频率: %lu Hz\n",
           (unsigned long)(result.timer_clk_hz / mock_signal_period_counts));

    if (result.valid && result.frequency_hz == 1000U) {
        printf("测试结果: 通过\n");
    } else {
        printf("测试结果: 失败\n");
    }

    printf("========================================\n");

    return 0;
}
