    if (rms->count < INTEGRAL_WINDOW) {
        rms->buffer[rms->index] = sq;
        rms->sum_sq += sq;
        rms->count++;
    } else {
        rms->sum_sq -= rms->buffer[rms->index];
        rms->buffer[rms->index] = sq;
        rms->sum_sq += sq;
    }

    rms->index = (rms->index + 1) % INTEGRAL_WINDOW;

    if (rms->count > 0) {
        rms->rms = sqrt(rms->sum_sq / (double)rms->count);
    }

