#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

#define SAMPLE_RATE       6400.0
#define FUNDAMENTAL_FREQ  50.0
#define NUM_SAMPLES       128
#define MAX_HARMONICS     10

typedef struct {
    double real;
    double imag;
} Complex;

static double input_signal[NUM_SAMPLES];

static void generate_test_signal(void)
{
    int n;
    for (n = 0; n < NUM_SAMPLES; n++) {
        double t = (double)n / SAMPLE_RATE;
        double val = 1.0 * sin(2.0 * M_PI * FUNDAMENTAL_FREQ * t);
        val += 0.30 * sin(2.0 * M_PI * 3.0 * FUNDAMENTAL_FREQ * t);
        val += 0.15 * sin(2.0 * M_PI * 5.0 * FUNDAMENTAL_FREQ * t);
        val += 0.08 * sin(2.0 * M_PI * 7.0 * FUNDAMENTAL_FREQ * t);
        val += 0.05 * sin(2.0 * M_PI * 9.0 * FUNDAMENTAL_FREQ * t);
        input_signal[n] = val;
    }
}

static Complex dft_bin(const double *sig, int n, int k)
{
    Complex result = {0.0, 0.0};
    int i;
    for (i = 0; i < n; i++) {
        double angle = 2.0 * M_PI * (double)k * (double)i / (double)n;
        result.real += sig[i] * cos(angle);
        result.imag -= sig[i] * sin(angle);
    }
    result.real /= (double)n;
    result.imag /= (double)n;
    return result;
}

static double magnitude(Complex c)
{
    return sqrt(c.real * c.real + c.imag * c.imag);
}

static double compute_thd(const double *sig, int n, int fundamental_bin, int max_harmonic)
{
    double fundamental_mag;
    double harmonic_sq_sum = 0.0;
    int h;

    Complex fund = dft_bin(sig, n, fundamental_bin);
    fundamental_mag = magnitude(fund);

    if (fundamental_mag < 1e-12) {
        return 0.0;
    }

    for (h = 2; h <= max_harmonic; h++) {
        int bin = fundamental_bin * h;
        if (bin >= n / 2) {
            break;
        }
        Complex hc = dft_bin(sig, n, bin);
        double hm = magnitude(hc);
        harmonic_sq_sum += hm * hm;
    }

    return sqrt(harmonic_sq_sum) / fundamental_mag * 100.0;
}

static void print_spectrum(const double *sig, int n, int max_bin)
{
    int k;
    printf("--- Harmonic Spectrum (bin : magnitude) ---\n");
    for (k = 1; k <= max_bin; k++) {
        Complex c = dft_bin(sig, n, k);
        double m = magnitude(c);
        if (m > 1e-6) {
            printf("  bin %2d (%.1f Hz) : %.6f\n",
                   k, (double)k * SAMPLE_RATE / (double)n, m);
        }
    }
}

int main(void)
{
    int fundamental_bin;
    double thd;

    printf("============================================\n");
    printf("  Signal Harmonic Analysis - THD Calculation\n");
    printf("============================================\n");
    printf("Sample rate      : %.1f Hz\n", SAMPLE_RATE);
    printf("Fundamental freq : %.1f Hz\n", FUNDAMENTAL_FREQ);
    printf("Samples per frame: %d\n", NUM_SAMPLES);
    printf("Frequency res.   : %.2f Hz\n", SAMPLE_RATE / (double)NUM_SAMPLES);
    printf("--------------------------------------------\n");

    generate_test_signal();

    fundamental_bin = (int)(FUNDAMENTAL_FREQ * (double)NUM_SAMPLES / SAMPLE_RATE + 0.5);
    if (fundamental_bin < 1) {
        fundamental_bin = 1;
    }

    printf("Fundamental bin  : %d\n", fundamental_bin);
    printf("--------------------------------------------\n");

    print_spectrum(input_signal, NUM_SAMPLES, NUM_SAMPLES / 2);

    thd = compute_thd(input_signal, NUM_SAMPLES, fundamental_bin, MAX_HARMONICS);

    printf("--------------------------------------------\n");
    printf("Total Harmonic Distortion (THD) = %.4f %%\n", thd);
    printf("============================================\n");

    return 0;
}
