#include <stdio.h>
#include <stdint.h>

/* ============================================================
 * 信号幅值校准（增益 + 零点补偿）控制算法
 * 公式：y = gain * (x - offset)
 * ============================================================ */

/* ---------- 校准参数结构体 ---------- */
typedef struct {
    float offset;   /* 零点补偿量 */
    float gain;     /* 增益系数   */
} CalibParam_t;

/* ---------- 校准上下文 ---------- */
typedef struct {
    CalibParam_t param;
    float        raw_min;
    float        raw_max;
    float        ref_min;
    float        ref_max;
    uint8_t      auto_mode;
} CalibContext_t;

/* ---------- 简单绝对值（避免依赖 math.h） ---------- */
static float my_fabsf(float x)
{
    return (x < 0.0f) ? -x : x;
}

/* ============================================================
 * 初始化校准上下文
 * ============================================================ */
static void Calib_Init(CalibContext_t *ctx,
                       float offset,
                       float gain,
                       float ref_min,
                       float ref_max)
{
    if (ctx == NULL) {
        return;
    }

    ctx->param.offset = offset;
    ctx->param.gain   = gain;
    ctx->raw_min      = 0.0f;
    ctx->raw_max      = 0.0f;
    ctx->ref_min      = ref_min;
    ctx->ref_max      = ref_max;
    ctx->auto_mode    = 0U;
}

/* ============================================================
 * 手动设置校准参数
 * ============================================================ */
static void Calib_SetParam(CalibContext_t *ctx, float offset, float gain)
{
    if (ctx == NULL) {
        return;
    }

    ctx->param.offset = offset;
    ctx->param.gain   = gain;
    ctx->auto_mode    = 0U;
}

/* ============================================================
 * 自动标定
 * ============================================================ */
static int Calib_AutoCalibrate(CalibContext_t *ctx)
{
    float raw_span;
    float ref_span;

    if (ctx == NULL) {
        return -1;
    }

    raw_span = ctx->raw_max - ctx->raw_min;
    ref_span = ctx->ref_max - ctx->ref_min;

    if (my_fabsf(raw_span) < 1e-6f) {
        return -1;
    }

    ctx->param.gain = ref_span / raw_span;

    if (my_fabsf(ctx->param.gain) < 1e-6f) {
        return -1;
    }

    ctx->param.offset = ctx->raw_min - (ctx->ref_min / ctx->param.gain);
    ctx->auto_mode    = 1U;

    return 0;
}

/* ============================================================
 * 核心校准函数
 * ============================================================ */
static float Calib_Apply(const CalibContext_t *ctx, float raw)
{
    if (ctx == NULL) {
        return raw;
    }

    return ctx->param.gain * (raw - ctx->param.offset);
}

/* ============================================================
 * 批量校准
 * ============================================================ */
static void Calib_ApplyBatch(const CalibContext_t *ctx,
                             const float *raw,
                             float *out,
                             uint32_t len)
{
    uint32_t i;

    if ((ctx == NULL) || (raw == NULL) || (out == NULL)) {
        return;
    }

    for (i = 0U; i < len; i++) {
        out[i] = Calib_Apply(ctx, raw[i]);
    }
}

/* ============================================================
 * 模拟读取 ADC 原始值（纯软件模拟，不访问任何硬件地址）
 * ============================================================ */
static float Mock_ReadAdcRaw(void)
{
    static uint32_t tick = 0U;
    float value;

    value = 100.0f + (float)(tick % 50U) * 2.0f;

    tick++;

    return value;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    CalibContext_t ctx;
    float raw_buf[8];
    float out_buf[8];
    uint32_t i;

    printf("============================================\n");
    printf("  信号幅值校准（增益 + 零点补偿）测试\n");
    printf("============================================\n\n");

    /* ---------- 1. 手动模式测试 ---------- */
    printf("[1] 手动模式测试\n");
    Calib_Init(&ctx, 100.0f, 2.0f, 0.0f, 100.0f);

    printf("    offset = %.3f, gain = %.3f\n", ctx.param.offset, ctx.param.gain);
    printf("    raw -> calibrated\n");

    for (i = 0U; i < 5U; i++) {
        float raw = 100.0f + (float)i * 10.0f;
        float out = Calib_Apply(&ctx, raw);
        printf("    %8.3f -> %8.3f\n", raw, out);
    }
    printf("\n");

    /* ---------- 2. 自动标定模式测试 ---------- */
    printf("[2] 自动标定模式测试\n");
    Calib_Init(&ctx, 0.0f, 1.0f, 0.0f, 100.0f);

    ctx.raw_min = 100.0f;
    ctx.raw_max = 200.0f;
    ctx.ref_min = 0.0f;
    ctx.ref_max = 100.0f;

    if (Calib_AutoCalibrate(&ctx) == 0) {
        printf("    自动标定成功\n");
        printf("    offset = %.6f, gain = %.6f\n",
               ctx.param.offset, ctx.param.gain);
    } else {
        printf("    自动标定失败\n");
    }

    printf("    raw -> calibrated\n");
    for (i = 0U; i < 5U; i++) {
        float raw = 100.0f + (float)i * 25.0f;
        float out = Calib_Apply(&ctx, raw);
        printf("    %8.3f -> %8.3f\n", raw, out);
    }
    printf("\n");

    /* ---------- 3. 批量校准测试 ---------- */
    printf("[3] 批量校准测试\n");
    for (i = 0U; i < 8U; i++) {
        raw_buf[i] = Mock_ReadAdcRaw();
    }

    Calib_ApplyBatch(&ctx, raw_buf, out_buf, 8U);

    printf("    idx   raw       calibrated\n");
    for (i = 0U; i < 8U; i++) {
        printf("    %2u  %8.3f  %8.3f\n", i, raw_buf[i], out_buf[i]);
    }
    printf("\n");

    /* ---------- 4. 边界测试 ---------- */
    printf("[4] 边界测试\n");
    Calib_SetParam(&ctx, 0.0f, 1.0f);
    printf("    offset = %.3f, gain = %.3f\n", ctx.param.offset, ctx.param.gain);
    printf("    raw = 0.0    -> %.3f\n", Calib_Apply(&ctx, 0.0f));
    printf("    raw = -50.0  -> %.3f\n", Calib_Apply(&ctx, -50.0f));
    printf("    raw = 1000.0 -> %.3f\n", Calib_Apply(&ctx, 1000.0f));
    printf("\n");

    printf("============================================\n");
    printf("  测试完成\n");
    printf("============================================\n");

    return 0;
}
