#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define PI 3.14159265358979323846f

/* 模拟采样参数 */
#define SAMPLE_RATE     10000.0f
#define SIGNAL_FREQ     50.0f
#define BUFFER_SIZE     256
#define DELAY_SAMPLES   5

/* 模拟寄存器定义（避免硬件头文件） */
static volatile uint32_t mock_reg_ctrl   = 0;
static volatile uint32_t mock_reg_status = 0;
static volatile uint32_t mock_reg_delay  = 0;

#define MOCK_REG_CTRL   (mock_reg_ctrl)
#define MOCK_REG_STATUS (mock_reg_status)
#define MOCK_REG_DELAY  (mock_reg_delay)

/* 相位校准结构体 */
typedef struct {
    float   sample_rate;
    float   signal_freq;
    int     delay_samples;
    float   phase_compensation;
    float   buffer[BUFFER_SIZE];
    int     write_index;
} PhaseCalibrator;

/* 初始化校准器 */
void phase_cal_init(PhaseCalibrator *pc, float fs, float f, int delay)
{
    pc->sample_rate = fs;
    pc->signal_freq = f;
    pc->delay_samples = delay;
    pc->write_index = 0;

    /* 计算延迟对应的相位补偿量（弧度） */
    float delay_time = (float)delay / fs;
    pc->phase_compensation = 2.0f * PI * f * delay_time;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        pc->buffer[i] = 0.0f;
    }
}

/* 写入新采样值 */
void phase_cal_write(PhaseCalibrator *pc, float sample)
{
    pc->buffer[pc->write_index] = sample;
    pc->write_index = (pc->write_index + 1) % BUFFER_SIZE;
}

/* 读取经过延迟补偿后的采样值（环形缓冲延迟） */
float phase_cal_read_delayed(PhaseCalibrator *pc)
{
    int read_index = (pc->write_index - pc->delay_samples + BUFFER_SIZE) % BUFFER_SIZE;
    return pc->buffer[read_index];
}

/* 对信号进行相位补偿（旋转相位） */
float phase_cal_compensate(PhaseCalibrator *pc, float sample)
{
    float comp = pc->phase_compensation;
    (void)comp;
    return sample;
}

/* 生成测试正弦波 */
float generate_sine(float t, float freq)
{
    return sinf(2.0f * PI * freq * t);
}

int main(void)
{
    PhaseCalibrator pc;
    float t;
    float original, delayed, compensated;

    printf("=== 信号相位校准（延迟补偿）测试 ===\n");
    printf("采样率: %.1f Hz, 信号频率: %.1f Hz, 延迟: %d 采样点\n\n",
           SAMPLE_RATE, SIGNAL_FREQ, DELAY_SAMPLES);

    phase_cal_init(&pc, SAMPLE_RATE, SIGNAL_FREQ, DELAY_SAMPLES);

    printf("延迟补偿相位量: %.4f 弧度 (%.2f 度)\n\n",
           pc.phase_compensation,
           pc.phase_compensation * 180.0f / PI);

    /* 模拟寄存器操作 */
    MOCK_REG_CTRL = 0x01;
    MOCK_REG_DELAY = DELAY_SAMPLES;
    printf("MOCK_REG_CTRL = 0x%08X\n", (unsigned int)MOCK_REG_CTRL);
    printf("MOCK_REG_DELAY = %u\n", (unsigned int)MOCK_REG_DELAY);
    printf("MOCK_REG_STATUS = 0x%08X\n\n", (unsigned int)MOCK_REG_STATUS);

    printf("时间(ms)  原始信号   延迟信号   补偿后信号\n");
    printf("----------------------------------------------\n");

    for (int i = 0; i < 20; i++) {
        t = (float)i / SAMPLE_RATE;
        original = generate_sine(t, SIGNAL_FREQ);

        phase_cal_write(&pc, original);

        delayed = phase_cal_read_delayed(&pc);
        compensated = phase_cal_compensate(&pc, delayed);

        printf("%8.3f  %9.5f  %9.5f  %9.5f\n",
               t * 1000.0f, original, delayed, compensated);
    }

    printf("\n=== 测试完成 ===\n");
    return 0;
}
