#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define N 1024
#define HARMONICS 10

/* 模拟信号采样值 */
static double signal[N];

/* 生成含谐波的测试信号 */
static void generate_signal(void)
{
    int i;
    for (i = 0; i < N; i++) {
        double t = (double)i / N;
        /* 基波 + 3次 + 5次 + 7次谐波 */
        signal[i] = 1.0 * sin(2.0 * PI * 1.0 * t)
                  + 0.3 * sin(2.0 * PI * 3.0 * t)
                  + 0.2 * sin(2.0 * PI * 5.0 * t)
                  + 0.1 * sin(2.0 * PI * 7.0 * t);
    }
}

/* 离散傅里叶变换提取指定次谐波幅值 */
static double dft_magnitude(const double *x, int n, int k)
{
    double real = 0.0, imag = 0.0;
    int i;
    for (i = 0; i < n; i++) {
        double angle = 2.0 * PI * k * i / n;
        real += x[i] * cos(angle);
        imag -= x[i] * sin(angle);
    }
    return sqrt(real * real + imag * imag) * 2.0 / n;
}

/* 计算总谐波畸变率 THD */
static double compute_thd(const double *x, int n, int max_harmonic)
{
    double fundamental;
    double harmonic_sum = 0.0;
    int h;

    fundamental = dft_magnitude(x, n, 1);
    if (fundamental < 1e-12) {
        return 0.0;
    }

    for (h = 2; h <= max_harmonic; h++) {
        double mag = dft_magnitude(x, n, h);
        harmonic_sum += mag * mag;
    }

    return sqrt(harmonic_sum) / fundamental * 100.0;
}

int main(void)
{
    double thd;
    int h;

    generate_signal();

    printf("=== Signal Harmonic Analysis (THD) ===\n");
    printf("Sample count: %d\n", N);

    printf("\nHarmonic magnitudes:\n");
    for (h = 1; h <= HARMONICS; h++) {
        double mag = dft_magnitude(signal, N, h);
        printf("  H%-2d : %.6f\n", h, mag);
    }

    thd = compute_thd(signal, N, HARMONICS);
    printf("\nTotal Harmonic Distortion (THD) = %.4f %%\n", thd);

    return 0;
}
