/* ================= 模拟硬件寄存器与宏定义 ================= */
#define MOCK_ADC_RESOLUTION     4095.0f
#define MOCK_VREF               3.3f
#define MOCK_PWM_MAX            1000

/* 模拟的 ADC 采样值寄存器 */
static volatile unsigned int g_adc_voltage_raw = 0;
static volatile unsigned int g_adc_current_raw = 0;

/* 模拟的 PWM 占空比寄存器 */
static volatile unsigned int g_pwm_duty = 500;

/* 模拟的 ADC 读取函数 */
static unsigned int mock_adc_read_voltage(void)
{
    return g_adc_voltage_raw;
}

static unsigned int mock_adc_read_current(void)
{
    return g_adc_current_raw;
}

/* 模拟的 PWM 设置函数 */
static void mock_pwm_set_duty(unsigned int duty)
{
    if (duty > MOCK_PWM_MAX) {
        duty = MOCK_PWM_MAX;
    }
    g_pwm_duty = duty;
}

/* ================= MPPT 电导增量法参数 ================= */
#define MPPT_DUTY_STEP          2       /* 占空比调整步长 */
#define MPPT_DUTY_MIN           50      /* 最小占空比 */
#define MPPT_DUTY_MAX           950     /* 最大占空比 */
#define MPPT_VOLTAGE_THRESHOLD  0.01f   /* 电压变化阈值，防止除零 */
#define MPPT_POWER_THRESHOLD    0.001f  /* 功率变化阈值，判断稳态 */

/* ================= MPPT 状态结构体 ================= */
typedef struct {
    float voltage;          /* 当前电压 */
    float current;          /* 当前电流 */
    float power;            /* 当前功率 */
    float voltage_prev;     /* 上一次电压 */
    float current_prev;     /* 上一次电流 */
    float power_prev;       /* 上一次功率 */
    float duty;             /* 当前占空比 */
    unsigned char first_run;/* 首次运行标志 */
} MPPT_IncCond_t;

/* ================= 初始化 MPPT 结构体 ================= */
static void mppt_inc_cond_init(MPPT_IncCond_t *mppt)
{
    mppt->voltage = 0.0f;
    mppt->current = 0.0f;
    mppt->power = 0.0f;
    mppt->voltage_prev = 0.0f;
    mppt->current_prev = 0.0f;
    mppt->power_prev = 0.0f;
    mppt->duty = (float)((MPPT_DUTY_MIN + MPPT_DUTY_MAX) / 2);
    mppt->first_run = 1;
}

/* ================= 读取电压电流并计算功率 ================= */
static void mppt_read_measurements(MPPT_IncCond_t *mppt)
{
    unsigned int v_raw = mock_adc_read_voltage();
    unsigned int i_raw = mock_adc_read_current();

    /* 将 ADC 原始值转换为实际物理量（模拟） */
    mppt->voltage = ((float)v_raw / MOCK_ADC_RESOLUTION) * MOCK_VREF * 10.0f;
    mppt->current = ((float)i_raw / MOCK_ADC_RESOLUTION) * MOCK_VREF * 2.0f;
    mppt->power = mppt->voltage * mppt->current;
}

/* ================= 电导增量法 MPPT 核心算法 =================
 * 原理：
 *   dP/dV = I + V * (dI/dV)
 *   当 dP/dV > 0 时，工作点在最大功率点左侧，应增大电压（减小占空比）
 *   当 dP/dV < 0 时，工作点在最大功率点右侧，应减小电压（增大占空比）
 *   当 dP/dV = 0 时，达到最大功率点，保持占空比不变
 *
 * 使用差分近似：
 *   dV = V(k) - V(k-1)
 *   dI = I(k) - I(k-1)
 *   dP = P(k) - P(k-1)
 *
 * 判断逻辑：
 *   若 |dV| < 阈值，则根据 dI 符号判断：
 *       dI > 0：电压不变电流增大，应增大电压（减小占空比）
 *       dI < 0：电压不变电流减小，应减小电压（增大占空比）
 *       dI = 0：已达到 MPP，保持
 *   否则：
 *       计算 dI/dV 与 -I/V 比较：
 *       dI/dV > -I/V：dP/dV > 0，增大电压（减小占空比）
 *       dI/dV < -I/V：dP/dV < 0，减小电压（增大占空比）
 *       dI/dV = -I/V：达到 MPP，保持
 *
 * 稳态无振荡处理：
 *   当功率变化量 |dP| 小于阈值时，认为已接近 MPP，
 *   不再调整占空比，避免稳态振荡。
 * ============================================================ */
static void mppt_inc_cond_update(MPPT_IncCond_t *mppt)
{
    float dV, dI, dP;
    float incremental_conductance;
    float instantaneous_conductance;
    float duty_new;

    /* 读取当前测量值 */
    mppt_read_measurements(mppt);

    /* 首次运行，仅记录数据，不调整 */
    if (mppt->first_run) {
        mppt->voltage_prev = mppt->voltage;
        mppt->current_prev = mppt->current;
        mppt->power_prev = mppt->power;
        mppt->first_run = 0;
        return;
    }

    /* 计算差分 */
    dV = mppt->voltage - mppt->voltage_prev;
    dI = mppt->current - mppt->current_prev;
    dP = mppt->power - mppt->power_prev;

    /* 稳态无振荡判断：功率变化极小，认为已达到 MPP，保持占空比 */
    if (fabsf(dP) < MPPT_POWER_THRESHOLD) {
        /* 更新历史数据，保持当前占空比 */
        mppt->voltage_prev = mppt->voltage;
        mppt->current_prev = mppt->current;
        mppt->power_prev = mppt->power;
        return;
    }

    duty_new = mppt->duty;

    /* 电导增量法判断 */
    if (fabsf(dV) < MPPT_VOLTAGE_THRESHOLD) {
        /* 电压基本不变，根据电流变化方向判断 */
        if (dI > 0.0f) {
            /* 电流增大，应增大电压 -> 减小占空比 */
            duty_new -= MPPT_DUTY_STEP;
        } else if (dI < 0.0f) {
            /* 电流减小，应减小电压 -> 增大占空比 */
            duty_new += MPPT_DUTY_STEP;
        }
        /* dI == 0 时保持 */
    } else {
        /* 计算电导 */
        incremental_conductance = dI / dV;
        instantaneous_conductance = -mppt->current / mppt->voltage;

        if (incremental_conductance > instantaneous_conductance) {
            /* dP/dV > 0，在 MPP 左侧，增大电压 -> 减小占空比 */
            duty_new -= MPPT_DUTY_STEP;
        } else if (incremental_conductance < instantaneous_conductance) {
            /* dP/dV < 0，在 MPP 右侧，减小电压 -> 增大占空比 */
            duty_new += MPPT_DUTY_STEP;
        }
        /* 相等时达到 MPP，保持 */
    }

    /* 占空比限幅 */
    if (duty_new < (float)MPPT_DUTY_MIN) {
        duty_new = (float)MPPT_DUTY_MIN;
    } else if (duty_new > (float)MPPT_DUTY_MAX) {
        duty_new = (float)MPPT_DUTY_MAX;
    }

    mppt->duty = duty_new;
    mock_pwm_set_duty((unsigned int)mppt->duty);

    /* 更新历史数据 */
    mppt->voltage_prev = mppt->voltage;
    mppt->current_prev = mppt->current;
    mppt->power_prev = mppt->power;
}

/* ================= 模拟光伏板特性 =================
 * 简单模拟：给定占空比，返回对应的电压和电流
 * 占空比越大，输出电压越低，电流越大（近似）
 * 最大功率点大约在占空比 500 附近
 * ================================================= */
static void mock_pv_panel_update(unsigned int duty)
{
    float duty_ratio = (float)duty / (float)MOCK_PWM_MAX;

    /* 模拟光伏板 I-V 特性 */
    float voc = 20.0f;      /* 开路电压 */
    float isc = 5.0f;       /* 短路电流 */

    /* 占空比影响工作点：占空比大 -> 电压低 -> 电流大 */
    float v = voc * (1.0f - duty_ratio * 0.9f);
    float i = isc * (1.0f - expf(-(voc - v) / 5.0f));

    if (v < 0.0f) v = 0.0f;
    if (i < 0.0f) i = 0.0f;

    /* 转换为 ADC 原始值 */
    g_adc_voltage_raw = (unsigned int)((v / (MOCK_VREF * 10.0f)) * MOCK_ADC_RESOLUTION);
    g_adc_current_raw = (unsigned int)((i / (MOCK_VREF * 2.0f)) * MOCK_ADC_RESOLUTION);

    if (g_adc_voltage_raw > (unsigned int)MOCK_ADC_RESOLUTION) {
        g_adc_voltage_raw = (unsigned int)MOCK_ADC_RESOLUTION;
    }
    if (g_adc_current_raw > (unsigned int)MOCK_ADC_RESOLUTION) {
        g_adc_current_raw = (unsigned int)MOCK_ADC_RESOLUTION;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    MPPT_IncCond_t mppt;
    int i;

    printf("===== MPPT 电导增量法 (Incremental Conductance) 测试 =====\n\n");

    /* 初始化 MPPT */
    mppt_inc_cond_init(&mppt);

    /* 初始占空比设置 */
    mock_pwm_set_duty((unsigned int)mppt.duty);

    printf("初始占空比: %u\n\n", g_pwm_duty);
    printf("%-6s %-10s %-10s %-10s %-10s %-10s\n",
           "迭代", "电压(V)", "电流(A)", "功率(W)", "占空比", "dP/dV");
    printf("--------------------------------------------------------------\n");

    /* 运行 MPPT 迭代 */
    for (i = 0; i < 50; i++) {
        float dP_dV;

        /* 模拟光伏板根据当前占空比更新输出 */
        mock_pv_panel_update(g_pwm_duty);

        /* 执行 MPPT 算法 */
        mppt_inc_cond_update(&mppt);

        /* 计算 dP/dV 用于显示 */
        if (fabsf(mppt.voltage - mppt.voltage_prev) > MPPT_VOLTAGE_THRESHOLD) {
            dP_dV = (mppt.power - mppt.power_prev) / (mppt.voltage - mppt.voltage_prev);
        } else {
            dP_dV = 0.0f;
        }

        printf("%-6d %-10.3f %-10.3f %-10.3f %-10u %-10.4f\n",
               i + 1,
               mppt.voltage,
               mppt.current,
               mppt.power,
               g_pwm_duty,
               dP_dV);
    }

    printf("\n===== 测试结束 =====\n");
    printf("最终占空比: %u\n", g_pwm_duty);
    printf("最终功率: %.3f W\n", mppt.power);

    return 0;
}
