#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ========== 模拟硬件寄存器与宏定义 ========== */
static volatile uint32_t g_mock_gpio_port = 0U;

#define ZERO_CROSS_GPIO_PORT   (g_mock_gpio_port)
#define ZERO_CROSS_PIN_MASK    (1U << 5)

/* 读取过零检测引脚电平：0 表示低电平，1 表示高电平 */
#define ZERO_CROSS_READ()      ((ZERO_CROSS_GPIO_PORT & ZERO_CROSS_PIN_MASK) ? 1U : 0U)

/* ========== 防抖参数 ========== */
#define DEBOUNCE_COUNT         3U      /* 连续相同电平次数达到该值才确认状态 */
#define ZERO_CROSS_ACTIVE_LOW  1U      /* 1: 低电平表示过零点；0: 高电平表示过零点 */

/* ========== 过零检测状态机 ========== */
typedef struct {
    uint8_t  stable_level;      /* 当前已确认的稳定电平 */
    uint8_t  last_raw_level;    /* 上一次采样的原始电平 */
    uint8_t  same_count;        /* 连续相同电平的计数 */
    uint32_t zero_cross_count;  /* 过零事件累计次数 */
    uint8_t  prev_stable_level; /* 上一次稳定电平，用于边沿判断 */
} ZeroCrossDetector;

/* 初始化检测器 */
static void zero_cross_init(ZeroCrossDetector *det)
{
    uint8_t raw = ZERO_CROSS_READ();
    det->stable_level      = raw;
    det->last_raw_level    = raw;
    det->same_count        = 0U;
    det->zero_cross_count  = 0U;
    det->prev_stable_level = raw;
}

/* 周期调用：采样一次引脚，执行防抖与过零计数
 * 返回 1 表示本次调用确认了一个过零事件，否则返回 0
 */
static uint8_t zero_cross_update(ZeroCrossDetector *det)
{
    uint8_t raw = ZERO_CROSS_READ();
    uint8_t event = 0U;

    if (raw == det->last_raw_level) {
        if (det->same_count < DEBOUNCE_COUNT) {
            det->same_count++;
        }
    } else {
        det->last_raw_level = raw;
        det->same_count = 1U;
    }

    /* 连续相同电平达到阈值，更新稳定电平 */
    if (det->same_count >= DEBOUNCE_COUNT) {
        if (det->stable_level != raw) {
            det->prev_stable_level = det->stable_level;
            det->stable_level = raw;

#if ZERO_CROSS_ACTIVE_LOW
            /* 低电平为有效过零点：稳定电平由高变低时计数 */
            if ((det->prev_stable_level == 1U) && (det->stable_level == 0U)) {
                det->zero_cross_count++;
                event = 1U;
            }
#else
            /* 高电平为有效过零点：稳定电平由低变高时计数 */
            if ((det->prev_stable_level == 0U) && (det->stable_level == 1U)) {
                det->zero_cross_count++;
                event = 1U;
            }
#endif
        }
    }

    return event;
}

/* ========== 测试辅助：模拟引脚电平变化 ========== */
static void mock_set_pin(uint8_t level)
{
    if (level) {
        ZERO_CROSS_GPIO_PORT |= ZERO_CROSS_PIN_MASK;
    } else {
        ZERO_CROSS_GPIO_PORT &= ~ZERO_CROSS_PIN_MASK;
    }
}

int main(void)
{
    ZeroCrossDetector det;
    uint32_t i;
    uint8_t  ev;

    /* 初始引脚为高电平 */
    mock_set_pin(1U);
    zero_cross_init(&det);

    printf("Zero-cross detection with debounce (count=%u)\n", DEBOUNCE_COUNT);
    printf("Initial stable level = %u, count = %u\n\n",
           det.stable_level, det.zero_cross_count);

    /* 模拟一段带抖动的过零信号：
     * 高 -> 抖动下降 -> 稳定低 -> 抖动上升 -> 稳定高 -> 稳定低 ...
     */
    const uint8_t seq[] = {
        1, 1, 1,          /* 稳定高 */
        0, 1, 0, 0, 0,    /* 抖动后稳定低，应产生 1 次过零 */
        0, 0, 0,          /* 保持低 */
        1, 0, 1, 1, 1,    /* 抖动后稳定高，不计数（高电平非有效） */
        1, 1, 1,          /* 保持高 */
        0, 0, 0,          /* 稳定低，应产生第 2 次过零 */
        0, 0, 0,          /* 保持低 */
        1, 1, 1,          /* 稳定高 */
        0, 0, 0           /* 稳定低，应产生第 3 次过零 */
    };

    for (i = 0U; i < sizeof(seq) / sizeof(seq[0]); i++) {
        mock_set_pin(seq[i]);
        ev = zero_cross_update(&det);
        printf("step %2u: raw=%u stable=%u same_cnt=%u event=%u total=%u\n",
               (unsigned)(i + 1U),
               (unsigned)seq[i],
               (unsigned)det.stable_level,
               (unsigned)det.same_count,
               (unsigned)ev,
               (unsigned)det.zero_cross_count);
    }

    printf("\nFinal zero-cross count = %u\n", det.zero_cross_count);
    return 0;
}
