#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ================= Mock 定义 ================= */
#define BATTERY_CAPACITY_AH      50.0f
#define COULOMBIC_EFFICIENCY     0.98f
#define OCV_RELAX_TIME_S         1800.0f
#define OCV_CORRECTION_GAIN      0.05f
#define SOC_MIN                  0.0f
#define SOC_MAX                  1.0f
#define OCV_TABLE_SIZE           11

/* OCV-SOC 查找表 (SOC 从 0 到 1，步长 0.1) */
static const float ocv_table_soc[OCV_TABLE_SIZE] = {
    0.0f, 0.1f, 0.2f, 0.3f, 0.4f, 0.5f, 0.6f, 0.7f, 0.8f, 0.9f, 1.0f
};
static const float ocv_table_volt[OCV_TABLE_SIZE] = {
    3.00f, 3.45f, 3.55f, 3.62f, 3.68f, 3.75f, 3.82f, 3.90f, 4.00f, 4.10f, 4.20f
};

/* ================= 数据结构 ================= */
typedef struct {
    float soc;                  /* 当前 SOC (0~1) */
    float current_a;            /* 电流 (A)，正为充电，负为放电 */
    float voltage_v;            /* 端电压 (V) */
    float temperature_c;        /* 温度 (C) */
    float coulomb_count_ah;     /* 累计安时量 (Ah) */
    float ocv_estimate;         /* 当前 OCV 估计值 */
    float last_ocv;             /* 上次 OCV 值 */
    float rest_time_s;          /* 静置时间 (s) */
    bool  is_resting;           /* 是否处于静置状态 */
    bool  ocv_valid;            /* OCV 修正是否有效 */
} BatteryState;

/* ================= 工具函数 ================= */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

/* 根据 SOC 查表获取 OCV */
static float soc_to_ocv(float soc)
{
    int i;
    float frac;
    soc = clampf(soc, 0.0f, 1.0f);
    for (i = 0; i < OCV_TABLE_SIZE - 1; i++) {
        if (soc <= ocv_table_soc[i + 1]) {
            frac = (soc - ocv_table_soc[i]) /
                   (ocv_table_soc[i + 1] - ocv_table_soc[i]);
            return ocv_table_volt[i] + frac * (ocv_table_volt[i + 1] - ocv_table_volt[i]);
        }
    }
    return ocv_table_volt[OCV_TABLE_SIZE - 1];
}

/* 根据 OCV 反查 SOC (线性插值) */
static float ocv_to_soc(float ocv)
{
    int i;
    float frac;
    if (ocv <= ocv_table_volt[0]) return 0.0f;
    if (ocv >= ocv_table_volt[OCV_TABLE_SIZE - 1]) return 1.0f;
    for (i = 0; i < OCV_TABLE_SIZE - 1; i++) {
        if (ocv <= ocv_table_volt[i + 1]) {
            frac = (ocv - ocv_table_volt[i]) /
                   (ocv_table_volt[i + 1] - ocv_table_volt[i]);
            return ocv_table_soc[i] + frac * (ocv_table_soc[i + 1] - ocv_table_soc[i]);
        }
    }
    return 1.0f;
}

/* ================= 初始化 ================= */
static void battery_init(BatteryState *bat, float init_soc)
{
    bat->soc = clampf(init_soc, SOC_MIN, SOC_MAX);
    bat->current_a = 0.0f;
    bat->voltage_v = soc_to_ocv(bat->soc);
    bat->temperature_c = 25.0f;
    bat->coulomb_count_ah = 0.0f;
    bat->ocv_estimate = bat->voltage_v;
    bat->last_ocv = bat->voltage_v;
    bat->rest_time_s = 0.0f;
    bat->is_resting = true;
    bat->ocv_valid = false;
}

/* ================= 安时积分 ================= */
static void coulomb_counting(BatteryState *bat, float dt_s)
{
    float delta_ah;
    float delta_soc;

    /* 安时积分: ΔAh = I * Δt / 3600 */
    delta_ah = bat->current_a * dt_s / 3600.0f;

    /* 考虑库仑效率 (充电时效率 < 1，放电时近似 1) */
    if (bat->current_a > 0.0f) {
        delta_ah *= COULOMBIC_EFFICIENCY;
    }

    bat->coulomb_count_ah += delta_ah;

    /* 转换为 SOC 变化量 */
    delta_soc = delta_ah / BATTERY_CAPACITY_AH;
    bat->soc = clampf(bat->soc + delta_soc, SOC_MIN, SOC_MAX);
}

/* ================= OCV 修正 ================= */
static void ocv_correction(BatteryState *bat, float dt_s)
{
    float ocv_from_soc;
    float soc_from_ocv;
    float error;

    /* 判断静置状态: 电流绝对值小于阈值 */
    if (fabsf(bat->current_a) < 0.05f) {
        bat->rest_time_s += dt_s;
        bat->is_resting = true;
    } else {
        bat->rest_time_s = 0.0f;
        bat->is_resting = false;
        bat->ocv_valid = false;
    }

    /* 静置足够长时间后，端电压近似等于 OCV */
    if (bat->is_resting && bat->rest_time_s >= OCV_RELAX_TIME_S) {
        bat->ocv_estimate = bat->voltage_v;
        bat->ocv_valid = true;
    }

    /* 如果 OCV 有效，进行 SOC 修正 */
    if (bat->ocv_valid) {
        ocv_from_soc = soc_to_ocv(bat->soc);
        soc_from_ocv = ocv_to_soc(bat->ocv_estimate);

        /* 计算误差 */
        error = soc_from_ocv - bat->soc;

        /* 用增益进行平滑修正，避免突变 */
        bat->soc = clampf(bat->soc + OCV_CORRECTION_GAIN * error, SOC_MIN, SOC_MAX);

        bat->last_ocv = bat->ocv_estimate;
    }
}

/* ================= 主更新函数 ================= */
static void battery_update(BatteryState *bat, float current_a,
                           float voltage_v, float temp_c, float dt_s)
{
    bat->current_a = current_a;
    bat->voltage_v = voltage_v;
    bat->temperature_c = temp_c;

    /* 步骤 1: 安时积分 */
    coulomb_counting(bat, dt_s);

    /* 步骤 2: OCV 修正 */
    ocv_correction(bat, dt_s);
}

/* ================= 打印状态 ================= */
static void print_state(const BatteryState *bat, int step)
{
    printf("Step %3d | SOC: %6.2f%% | I: %+6.2fA | V: %5.3fV | "
           "OCV: %5.3fV | Rest: %s | OCV_Valid: %s\n",
           step,
           bat->soc * 100.0f,
           bat->current_a,
           bat->voltage_v,
           bat->ocv_estimate,
           bat->is_resting ? "YES" : "NO ",
           bat->ocv_valid ? "YES" : "NO ");
}

/* ================= 主函数 ================= */
int main(void)
{
    BatteryState bat;
    float dt = 1.0f;  /* 时间步长 1 秒 */
    int step;

    printf("========================================\n");
    printf(" 锂电池 SOC 估算 (安时积分 + OCV 修正)\n");
    printf("========================================\n\n");

    /* 初始化: 初始 SOC 80% */
    battery_init(&bat, 0.80f);
    printf("初始状态:\n");
    print_state(&bat, 0);
    printf("\n");

    /* 阶段 1: 放电 (电流 -10A，持续 60 秒) */
    printf("--- 阶段 1: 放电 (I = -10A, 60s) ---\n");
    for (step = 1; step <= 60; step++) {
        float v = soc_to_ocv(bat.soc) - 0.05f * fabsf(-10.0f);
        battery_update(&bat, -10.0f, v, 25.0f, dt);
        if (step % 20 == 0) {
            print_state(&bat, step);
        }
    }
    printf("\n");

    /* 阶段 2: 静置 (电流 0A，持续 1800 秒) */
    printf("--- 阶段 2: 静置 (I = 0A, 1800s) ---\n");
    for (step = 1; step <= 1800; step++) {
        float v = soc_to_ocv(bat.soc);
        battery_update(&bat, 0.0f, v, 25.0f, dt);
        if (step % 600 == 0) {
            print_state(&bat, step);
        }
    }
    printf("\n");

    /* 阶段 3: 充电 (电流 +5A，持续 120 秒) */
    printf("--- 阶段 3: 充电 (I = +5A, 120s) ---\n");
    for (step = 1; step <= 120; step++) {
        float v = soc_to_ocv(bat.soc) + 0.05f * 5.0f;
        battery_update(&bat, 5.0f, v, 25.0f, dt);
        if (step % 40 == 0) {
            print_state(&bat, step);
        }
    }
    printf("\n");

    /* 阶段 4: 再次静置 (电流 0A，持续 1800 秒) */
    printf("--- 阶段 4: 静置 (I = 0A, 1800s) ---\n");
    for (step = 1; step <= 1800; step++) {
        float v = soc_to_ocv(bat.soc);
        battery_update(&bat, 0.0f, v, 25.0f, dt);
        if (step % 600 == 0) {
            print_state(&bat, step);
        }
    }
    printf("\n");

    printf("========================================\n");
    printf("最终 SOC: %.2f%%\n", bat.soc * 100.0f);
