#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ==================== Mock 硬件寄存器与宏定义 ==================== */
#define MOCK_ADC_RESOLUTION     4095.0f
#define MOCK_VREF               3.3f
#define MOCK_PWM_MAX            1000

/* 模拟 ADC 寄存器 */
static volatile unsigned int mock_adc_voltage_reg = 0;
static volatile unsigned int mock_adc_current_reg = 0;

/* 模拟 PWM 占空比寄存器 */
static volatile unsigned int mock_pwm_duty_reg = 0;

/* 模拟硬件读取函数 */
static float mock_read_voltage(void) {
    return (mock_adc_voltage_reg / MOCK_ADC_RESOLUTION) * MOCK_VREF * 10.0f;
}

static float mock_read_current(void) {
    return (mock_adc_current_reg / MOCK_ADC_RESOLUTION) * MOCK_VREF * 2.0f;
}

static void mock_set_pwm_duty(unsigned int duty) {
    if (duty > MOCK_PWM_MAX) duty = MOCK_PWM_MAX;
    mock_pwm_duty_reg = duty;
}

/* ==================== MPPT 扰动观察法参数 ==================== */
#define MPPT_DUTY_MIN           50
#define MPPT_DUTY_MAX           950
#define MPPT_DUTY_INIT          500
#define MPPT_STEP_MIN           1
#define MPPT_STEP_MAX           30
#define MPPT_STEP_INIT          10
#define MPPT_STEP_FACTOR        2
#define MPPT_POWER_THRESHOLD    0.001f
#define MPPT_VOLTAGE_THRESHOLD  0.5f
#define MPPT_IRRADIANCE_DROP    0.3f

/* ==================== MPPT 状态结构体 ==================== */
typedef struct {
    float voltage;
    float current;
    float power;
    float prev_voltage;
    float prev_current;
    float prev_power;
    int   duty;
    int   prev_duty;
    int   step;
    int   direction;
    int   perturb_count;
    bool  initialized;
} MPPT_State;

/* ==================== MPPT 初始化 ==================== */
static void mppt_init(MPPT_State *mppt) {
    mppt->voltage = 0.0f;
    mppt->current = 0.0f;
    mppt->power = 0.0f;
    mppt->prev_voltage = 0.0f;
    mppt->prev_current = 0.0f;
    mppt->prev_power = 0.0f;
    mppt->duty = MPPT_DUTY_INIT;
    mppt->prev_duty = MPPT_DUTY_INIT;
    mppt->step = MPPT_STEP_INIT;
    mppt->direction = 1;
    mppt->perturb_count = 0;
    mppt->initialized = false;
}

/* ==================== 光照突变检测 ==================== */
static bool mppt_detect_irradiance_change(MPPT_State *mppt) {
    if (!mppt->initialized) return false;

    float power_ratio = 0.0f;
    if (mppt->prev_power > MPPT_POWER_THRESHOLD) {
        power_ratio = mppt->power / mppt->prev_power;
    }

    if (power_ratio < MPPT_IRRADIANCE_DROP) {
        return true;
    }

    if (fabsf(mppt->voltage - mppt->prev_voltage) > MPPT_VOLTAGE_THRESHOLD * 3.0f) {
        return true;
    }

    return false;
}

/* ==================== 自适应步长调整 ==================== */
static void mppt_adapt_step(MPPT_State *mppt) {
    float power_delta = mppt->power - mppt->prev_power;
    float abs_delta = fabsf(power_delta);

    if (abs_delta > MPPT_POWER_THRESHOLD * 10.0f) {
        mppt->step = mppt->step * MPPT_STEP_FACTOR;
        if (mppt->step > MPPT_STEP_MAX) {
            mppt->step = MPPT_STEP_MAX;
        }
    } else if (abs_delta < MPPT_POWER_THRESHOLD) {
        mppt->step = mppt->step / MPPT_STEP_FACTOR;
        if (mppt->step < MPPT_STEP_MIN) {
            mppt->step = MPPT_STEP_MIN;
        }
    }
}

/* ==================== MPPT 扰动观察法主算法 ==================== */
static void mppt_perturb_and_observe(MPPT_State *mppt) {
    /* 1. 采样当前电压、电流、功率 */
    mppt->voltage = mock_read_voltage();
    mppt->current = mock_read_current();
    mppt->power = mppt->voltage * mppt->current;

    /* 2. 首次运行初始化 */
    if (!mppt->initialized) {
        mppt->prev_voltage = mppt->voltage;
        mppt->prev_current = mppt->current;
        mppt->prev_power = mppt->power;
        mppt->prev_duty = mppt->duty;
        mppt->initialized = true;
        mock_set_pwm_duty(mppt->duty);
        return;
    }

    /* 3. 光照突变检测 */
    if (mppt_detect_irradiance_change(mppt)) {
        printf("[MPPT] 检测到光照突变! 功率比: %.3f, 电压变化: %.3fV\n",
               (mppt->prev_power > MPPT_POWER_THRESHOLD) ?
               (mppt->power / mppt->prev_power) : 0.0f,
               mppt->voltage - mppt->prev_voltage);

        /* 光照突变时，重置步长并重新搜索 */
        mppt->step = MPPT_STEP_INIT;
        mppt->direction = 1;
        mppt->perturb_count = 0;

        /* 根据功率变化方向决定扰动方向 */
        if (mppt->power < mppt->prev_power) {
            mppt->direction = -mppt->direction;
        }

        mppt->prev_voltage = mppt->voltage;
        mppt->prev_current = mppt->current;
        mppt->prev_power = mppt->power;
        mppt->prev_duty = mppt->duty;

        /* 立即执行一次扰动 */
        mppt->duty += mppt->direction * mppt->step;
        if (mppt->duty < MPPT_DUTY_MIN) {
            mppt->duty = MPPT_DUTY_MIN;
            mppt->direction = 1;
        } else if (mppt->duty > MPPT_DUTY_MAX) {
            mppt->duty = MPPT_DUTY_MAX;
            mppt->direction = -1;
        }
        mock_set_pwm_duty(mppt->duty);
        return;
    }

    /* 4. 自适应步长调整 */
    mppt_adapt_step(mppt);

    /* 5. 扰动观察法核心逻辑 */
    float power_delta = mppt->power - mppt->prev_power;

    if (fabsf(power_delta) > MPPT_POWER_THRESHOLD) {
        if (power_delta > 0.0f) {
            /* 功率增加，保持当前扰动方向 */
            mppt->perturb_count = 0;
        } else {
            /* 功率减小，反向扰动 */
            mppt->direction = -mppt->direction;
            mppt->perturb_count++;
        }
    } else {
        /* 功率变化很小，可能接近最大功率点 */
        mppt->perturb_count++;

        /* 连续多次功率变化很小，减小步长 */
        if (mppt->perturb_count > 3) {
            mppt->step = mppt->step / MPPT_STEP_FACTOR;
            if (mppt->step < MPPT_STEP_MIN) {
                mppt->step = MPPT_STEP_MIN;
            }
            mppt->perturb_count = 0;
        }
    }

    /* 6. 更新占空比 */
    mppt->prev_duty = mppt->duty;
    mppt->duty += mppt->direction * mppt->step;

    /* 7. 占空比限幅 */
    if (mppt->duty < MPPT_DUTY_MIN) {
        mppt->duty = MPPT_DUTY_MIN;
        mppt->direction = 1;
    } else if (mppt->duty > MPPT_DUTY_MAX) {
        mppt->duty = MPPT_DUTY_MAX;
        mppt->direction = -1;
    }

    /* 8. 更新 PWM 输出 */
    mock_set_pwm_duty(mppt->duty);

    /* 9. 保存历史数据 */
    mppt->prev_voltage = mppt->voltage;
    mppt->prev_current = mppt->current;
    mppt->prev_power = mppt->power;
}

/* ==================== 模拟光伏板特性 ==================== */
static void mock_solar_panel(float irradiance, float temperature,
                             float duty, float *voltage, float *current) {
    /* 简化的光伏板模型 */
    float voc = 36.0f * (1.0f + 0.0005f * (temperature - 25.0f));
    float isc = 8.0f * irradiance * (1.0f + 0.0003f * (temperature - 25.0f));
    float vmp = voc * 0.8f;
    float imp = isc * 0.9f;

    /* 根据占空比计算工作点 */
    float v_out = vmp * (1.0f - (duty / (float)MOCK_PWM_MAX) * 0.5f);
    if (v_out < 0.0f) v_out = 0.0f;
    if (v_out > voc) v_out = voc;

    float i_out = isc * (1.0f - expf((v_out - voc) / (voc * 0.1f)));
    if (i_out < 0.0f) i_out = 0.0f;

    *voltage = v_out;
    *current = i_out;
}

/* ==================== 主函数 ==================== */
int main(void) {
    printf("========================================\n");
    printf("  MPPT 扰动观察法 (自适应步长 + 光照突变)\n");
    printf("========================================\n\n");

    MPPT_State mppt;
    mppt_init(&mppt);

    /* 模拟参数 */
    float irradiance = 1.0f;
    float temperature = 25.0f;
    int total_steps = 100;
    int irradiance_change_step = 50;

    printf("初始条件: 光照=%.1f, 温度=%.1f°C\n", irradiance, temperature);
    printf("光照突变将在第 %d 步发生\n\n", irradiance_change_step);

    printf("%-6s %-10s %-10s %-10s %-8s %-8s %-8s\n",
           "Step", "Voltage(V)", "Current(A)", "Power(W)",
           "Duty", "Step", "Dir");
    printf("--------------------------------------------------------------\n");

    for (int i = 0; i < total_steps; i++) {
        /* 在第 50 步模拟光照突变 */
        if (i == irradiance_change_step) {
            irradiance = 0.4f;
            printf("\n>>> 光照突变! 光照从 1.0 降至 0.4 <<<\n\n");
        }

        /* 模拟光伏板输出 */
        float v, c;
        mock_solar_panel(irradiance, temperature,
                         (float)mppt.duty / MOCK_PWM_MAX, &v, &c);

        /* 将模拟值写入 ADC 寄存器 */
        mock_adc_voltage_reg = (unsigned int)((v / 10.0f) / MOCK_VREF * MOCK_ADC_RESOLUTION);
        mock_adc_current_reg = (unsigned int)((c / 2.0f) / MOCK_VREF * MOCK_ADC_RESOLUTION);

        /* 执行 MPPT 算法 */
        mppt_perturb_and_observe(&mppt);

        /* 打印状态 */
        printf("%-6d %-10.3f %-10.3f %-10.3f %-8d %-8d %-8d\n",
               i + 1, mppt.voltage, mppt.current, mppt.power,
               mppt.duty, mppt.step, mppt.direction);
    }

    printf("\n========================================\n");
    printf("MPPT 测试完成\n");
    printf("最终工作点: V=%.3fV, I=%.3fA, P=%.3fW\n",
           mppt.voltage, mppt.current, mppt.power);
    printf("最终占空比: %d/%d\n", mppt.duty, MOCK_PWM_MAX);
    printf("========================================\n");

    return 0;
}
