#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== 模拟寄存器与硬件抽象 ==================== */
#define MOCK_REG_VOLTAGE_ADC    0x40000000U
#define MOCK_REG_CURRENT_ADC    0x40000004U
#define MOCK_REG_PWM_DUTY       0x40000008U
#define MOCK_REG_CHARGE_EN      0x4000000CU
#define MOCK_REG_DISCHARGE_EN   0x40000010U

/* 使用普通静态变量模拟寄存器，避免访问非法地址导致崩溃 */
static volatile uint32_t g_reg_voltage_adc = 0U;
static volatile uint32_t g_reg_current_adc = 0U;
static volatile uint32_t g_reg_pwm_duty = 0U;
static volatile uint32_t g_reg_charge_en = 0U;
static volatile uint32_t g_reg_discharge_en = 0U;

/* ==================== 电池参数定义 ==================== */
#define CELL_COUNT              1U
#define CELL_NOMINAL_VOLTAGE_MV 3700U
#define CELL_FULL_VOLTAGE_MV    4200U
#define CELL_EMPTY_VOLTAGE_MV   3000U
#define FLOAT_VOLTAGE_MV        4150U
#define CHARGE_CURRENT_MA       1000U
#define TRICKLE_CURRENT_MA      100U
#define FLOAT_CURRENT_MA        50U
#define CHARGE_TIMEOUT_MS       7200000U
#define FLOAT_TIMEOUT_MS        3600000U
#define CV_HOLD_TIME_MS         1800000U

/* ==================== 充电状态枚举 ==================== */
typedef enum {
    CHARGE_STATE_IDLE = 0,
    CHARGE_STATE_TRICKLE,
    CHARGE_STATE_CC,
    CHARGE_STATE_CV,
    CHARGE_STATE_FLOAT,
    CHARGE_STATE_DONE,
    CHARGE_STATE_FAULT
} charge_state_t;

/* ==================== 电池管理结构体 ==================== */
typedef struct {
    charge_state_t state;
    uint32_t voltage_mv;
    uint32_t current_ma;
    uint32_t target_voltage_mv;
    uint32_t target_current_ma;
    uint32_t state_timer_ms;
    uint32_t total_timer_ms;
    uint32_t pwm_duty;
    bool     charge_enable;
    bool     discharge_enable;
    bool     fault_flag;
} battery_charger_t;

/* ==================== 硬件读取模拟 ==================== */
static uint32_t hw_read_voltage_mv(void)
{
    static uint32_t v = 3800U;
    if (v < CELL_FULL_VOLTAGE_MV) {
        v += 10U;
    }
    return v;
}

static uint32_t hw_read_current_ma(void)
{
    static uint32_t i = 0U;
    if (i < CHARGE_CURRENT_MA) {
        i += 50U;
    }
    return i;
}

static void hw_set_pwm_duty(uint32_t duty)
{
    if (duty > 100U) {
        duty = 100U;
    }
    g_reg_pwm_duty = duty;
}

static void hw_set_charge_enable(bool en)
{
    g_reg_charge_en = en ? 1U : 0U;
}

static void hw_set_discharge_enable(bool en)
{
    g_reg_discharge_en = en ? 1U : 0U;
}

/* ==================== 充电器初始化 ==================== */
static void charger_init(battery_charger_t *chg)
{
    if (chg == NULL) {
        return;
    }
    chg->state = CHARGE_STATE_IDLE;
    chg->voltage_mv = 0U;
    chg->current_ma = 0U;
    chg->target_voltage_mv = CELL_FULL_VOLTAGE_MV;
    chg->target_current_ma = CHARGE_CURRENT_MA;
    chg->state_timer_ms = 0U;
    chg->total_timer_ms = 0U;
    chg->pwm_duty = 0U;
    chg->charge_enable = false;
    chg->discharge_enable = false;
    chg->fault_flag = false;

    hw_set_charge_enable(false);
    hw_set_discharge_enable(false);
    hw_set_pwm_duty(0U);
}

/* ==================== 状态机主循环 ==================== */
static void charger_update(battery_charger_t *chg, uint32_t dt_ms)
{
    if (chg == NULL) {
        return;
    }

    chg->voltage_mv = hw_read_voltage_mv();
    chg->current_ma = hw_read_current_ma();
    chg->state_timer_ms += dt_ms;
    chg->total_timer_ms += dt_ms;

    /* 故障检测 */
    if (chg->voltage_mv > (CELL_FULL_VOLTAGE_MV + 200U)) {
        chg->fault_flag = true;
        chg->state = CHARGE_STATE_FAULT;
    }
    if (chg->voltage_mv < CELL_EMPTY_VOLTAGE_MV) {
        chg->fault_flag = true;
        chg->state = CHARGE_STATE_FAULT;
    }

    switch (chg->state) {
    case CHARGE_STATE_IDLE:
        chg->charge_enable = false;
        chg->discharge_enable = false;
        chg->pwm_duty = 0U;
        if (chg->voltage_mv < CELL_FULL_VOLTAGE_MV) {
            chg->state = CHARGE_STATE_TRICKLE;
            chg->state_timer_ms = 0U;
        }
        break;

    case CHARGE_STATE_TRICKLE:
        chg->charge_enable = true;
        chg->discharge_enable = false;
        chg->target_current_ma = TRICKLE_CURRENT_MA;
        chg->pwm_duty = 10U;
        if (chg->voltage_mv >= (CELL_EMPTY_VOLTAGE_MV + 200U)) {
            chg->state = CHARGE_STATE_CC;
            chg->state_timer_ms = 0U;
        }
        if (chg->state_timer_ms > 600000U) {
            chg->state = CHARGE_STATE_FAULT;
            chg->fault_flag = true;
        }
        break;

    case CHARGE_STATE_CC:
        chg->charge_enable = true;
        chg->discharge_enable = false;
        chg->target_current_ma = CHARGE_CURRENT_MA;
        chg->pwm_duty = 80U;
        if (chg->voltage_mv >= CELL_FULL_VOLTAGE_MV) {
            chg->state = CHARGE_STATE_CV;
            chg->state_timer_ms = 0U;
        }
        if (chg->total_timer_ms > CHARGE_TIMEOUT_MS) {
            chg->state = CHARGE_STATE_FAULT;
            chg->fault_flag = true;
        }
        break;

    case CHARGE_STATE_CV:
        chg->charge_enable = true;
        chg->discharge_enable = false;
        chg->target_voltage_mv = CELL_FULL_VOLTAGE_MV;
        chg->target_current_ma = CHARGE_CURRENT_MA / 10U;
        chg->pwm_duty = 50U;
        if (chg->current_ma < (CHARGE_CURRENT_MA / 10U)) {
            chg->state = CHARGE_STATE_FLOAT;
            chg->state_timer_ms = 0U;
        }
        if (chg->state_timer_ms > CV_HOLD_TIME_MS) {
            chg->state = CHARGE_STATE_FLOAT;
            chg->state_timer_ms = 0U;
        }
        break;

    case CHARGE_STATE_FLOAT:
        chg->charge_enable = true;
        chg->discharge_enable = false;
        chg->target_voltage_mv = FLOAT_VOLTAGE_MV;
        chg->target_current_ma = FLOAT_CURRENT_MA;
        chg->pwm_duty = 20U;
        if (chg->state_timer_ms > FLOAT_TIMEOUT_MS) {
            chg->state = CHARGE_STATE_DONE;
            chg->state_timer_ms = 0U;
        }
        break;

    case CHARGE_STATE_DONE:
        chg->charge_enable = false;
        chg->discharge_enable = false;
        chg->pwm_duty = 0U;
        break;

    case CHARGE_STATE_FAULT:
        chg->charge_enable = false;
        chg->discharge_enable = false;
        chg->pwm_duty = 0U;
        chg->fault_flag = true;
        break;

    default:
        chg->state = CHARGE_STATE_IDLE;
        break;
    }

    hw_set_charge_enable(chg->charge_enable);
    hw_set_discharge_enable(chg->discharge_enable);
    hw_set_pwm_duty(chg->pwm_duty);
}

/* ==================== 状态名称打印辅助 ==================== */
static const char *state_name(charge_state_t s)
{
    switch (s) {
    case CHARGE_STATE_IDLE:    return "IDLE";
    case CHARGE_STATE_TRICKLE: return "TRICKLE";
    case CHARGE_STATE_CC:      return "CC";
    case CHARGE_STATE_CV:      return "CV";
    case CHARGE_STATE_FLOAT:   return "FLOAT";
    case CHARGE_STATE_DONE:    return "DONE";
    case CHARGE_STATE_FAULT:   return "FAULT";
    default:                   return "UNKNOWN";
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    battery_charger_t charger;
    uint32_t step;

    printf("===== Lithium Battery Charge Control Simulation =====\n");
    printf("Cell Full Voltage: %u mV\n", (unsigned)CELL_FULL_VOLTAGE_MV);
    printf("Charge Current:    %u mA\n", (unsigned)CHARGE_CURRENT_MA);
    printf("Float Voltage:     %u mV\n\n", (unsigned)FLOAT_VOLTAGE_MV);

    charger_init(&charger);

    for (step = 0U; step < 30U; step++) {
        charger_update(&charger, 1000U);

        printf("[Step %02u] State=%-8s V=%4u mV I=%4u mA PWM=%3u%% CHG=%u DSG=%u\n",
               (unsigned)step,
               state_name(charger.state),
               (unsigned)charger.voltage_mv,
               (unsigned)charger.current_ma,
               (unsigned)charger.pwm_duty,
               charger.charge_enable ? 1U : 0U,
               charger.discharge_enable ? 1U : 0U);

        if (charger.state == CHARGE_STATE_DONE) {
            printf("\n>>> Charging completed successfully.\n");
            break;
        }
        if (charger.state == CHARGE_STATE_FAULT) {
            printf("\n>>> Fault detected! Charging aborted.\n");
            break;
        }
    }

    printf("\n===== Simulation End =====\n");
    return 0;
}
