static BalanceController_t g_balancer;

/* ============================================================
 * 硬件抽象层（Mock）
 * ============================================================ */

static void HAL_ADC_Init(void)
{
    g_adc1_cr2 = 0x00000001U;
    g_adc1_cr2 |= 0x00000002U;
    printf("[HAL] ADC initialized for battery voltage sampling.\n");
}

static uint16_t HAL_ADC_ReadChannel(uint8_t channel)
{
    static const uint16_t mock_adc[CELL_COUNT] = {
        2482U,
        2451U,
        2513U,
        2476U
    };
    if (channel < CELL_COUNT) {
        return mock_adc[channel];
    }
    return 0U;
}

static void HAL_GPIO_Init(void)
{
    g_gpiob_odr = 0x00000000U;
    printf("[HAL] GPIO initialized for balance switches.\n");
}

static void HAL_GPIO_SetBalanceSwitch(uint8_t cell_index, uint8_t enable)
{
    if (cell_index >= CELL_COUNT) {
        return;
    }
    if (enable) {
        g_gpiob_bsrr = (1U << cell_index);
    } else {
        g_gpiob_bsrr = (1U << (cell_index + 16U));
    }
}

static void HAL_PWM_Init(void)
{
    g_tim1_arr = PWM_PERIOD - 1U;
    g_tim1_ccr1 = 0U;
    g_tim1_cr1 = 0x00000001U;
    printf("[HAL] PWM timer initialized for energy transfer.\n");
}

static void HAL_PWM_SetDuty(uint16_t duty)
{
    if (duty > PWM_PERIOD) {
        duty = PWM_PERIOD;
    }
    g_tim1_ccr1 = duty;
}

static uint32_t HAL_GetTick(void)
{
    static uint32_t tick = 0U;
    tick += 10U;
    return tick;
}

/* ============================================================
 * 均衡控制算法
 * ============================================================ */

static uint16_t Balance_AdcToVoltage(uint16_t adc_raw)
{
    float voltage;
    voltage = ((float)adc_raw * (float)ADC_VREF_MV) / (float)ADC_MAX_VALUE;
    voltage *= VOLTAGE_DIVIDER_RATIO;
    return (uint16_t)(voltage + 0.5f);
}

static void Balance_SampleVoltages(void)
{
    uint8_t i;
    for (i = 0U; i < CELL_COUNT; i++) {
        g_balancer.cells[i].adc_raw = HAL_ADC_ReadChannel(i);
        g_balancer.cells[i].voltage_mv = Balance_AdcToVoltage(g_balancer.cells[i].adc_raw);
    }
}

static void Balance_CalculateStatistics(void)
{
    uint8_t i;
    uint32_t sum = 0U;
    uint16_t vmax = 0U;
    uint16_t vmin = 0xFFFFU;
    uint8_t idx_max = 0U;
    uint8_t idx_min = 0U;

    for (i = 0U; i < CELL_COUNT; i++) {
        uint16_t v = g_balancer.cells[i].voltage_mv;
        sum += v;
        if (v > vmax) {
            vmax = v;
            idx_max = i;
        }
        if (v < vmin) {
            vmin = v;
            idx_min = i;
        }
    }

    g_balancer.max_voltage_mv = vmax;
    g_balancer.min_voltage_mv = vmin;
    g_balancer.avg_voltage_mv = (uint16_t)(sum / CELL_COUNT);
    g_balancer.voltage_diff_mv = (uint16_t)(vmax - vmin);
    g_balancer.max_cell_index = idx_max;
    g_balancer.min_cell_index = idx_min;
}

static uint16_t Balance_CalculateDuty(uint16_t diff_mv)
{
    uint32_t duty;
    uint32_t diff_range;

    if (diff_mv <= BALANCE_THRESHOLD_MV) {
        return 0U;
    }

    diff_range = diff_mv - BALANCE_THRESHOLD_MV;
    if (diff_range > 200U) {
        diff_range = 200U;
    }

    duty = BALANCE_DUTY_MIN +
           (diff_range * (BALANCE_DUTY_MAX - BALANCE_DUTY_MIN)) / 200U;

    if (duty > BALANCE_DUTY_MAX) {
        duty = BALANCE_DUTY_MAX;
    }

    return (uint16_t)duty;
}

static void Balance_Execute(void)
{
    uint8_t i;
    uint16_t diff = g_balancer.voltage_diff_mv;

    if (diff < BALANCE_THRESHOLD_MV) {
        if (g_balancer.state == BALANCE_ACTIVE) {
            if (diff < BALANCE_HYSTERESIS_MV) {
                g_balancer.state = BALANCE_IDLE;
                for (i = 0U; i < CELL_COUNT; i++) {
                    g_balancer.cells[i].balance_enable = 0U;
                    HAL_GPIO_SetBalanceSwitch(i, 0U);
                }
                HAL_PWM_SetDuty(0U);
                printf("[BALANCE] Idle: voltage diff %u mV < threshold %u mV\n",
                       diff, BALANCE_THRESHOLD_MV);
            }
        } else {
            g_balancer.state = BALANCE_IDLE;
        }
        return;
    }

    g_balancer.state = BALANCE_ACTIVE;

    g_balancer.balance_duty = Balance_CalculateDuty(diff);
    HAL_PWM_SetDuty(g_balancer.balance_duty);

    for (i = 0U; i < CELL_COUNT; i++) {
        g_balancer.cells[i].balance_enable = 0U;
        HAL_GPIO_SetBalanceSwitch(i, 0U);
    }

    g_balancer.cells[g_balancer.max_cell_index].balance_enable = 1U;
    HAL_GPIO_SetBalanceSwitch(g_balancer.max_cell_index, 1U);

    g_balancer.cells[g_balancer.min_cell_index].balance_enable = 1U;
    HAL_GPIO_SetBalanceSwitch(g_balancer.min_cell_index, 1U);

    printf("[BALANCE] Active: cell[%u] (%u mV) -> cell[%u] (%u mV), "
           "diff=%u mV, duty=%u/%u\n",
           g_balancer.max_cell_index,
           g_balancer.max_voltage_mv,
           g_balancer.min_cell_index,
           g_balancer.min_voltage_mv,
           diff,
           g_balancer.balance_duty,
           PWM_PERIOD);
}

static void Balance_Init(void)
{
    uint8_t i;

    for (i = 0U; i < CELL_COUNT; i++) {
        g_balancer.cells[i].voltage_mv = 0U;
        g_balancer.cells[i].adc_raw = 0U;
        g_balancer.cells[i].balance_enable = 0U;
        g_balancer.cells[i].fault_flag = 0U;
    }

    g_balancer.state = BALANCE_IDLE;
    g_balancer.max_voltage_mv = 0U;
    g_balancer.min_voltage_mv = 0U;
    g_balancer.avg_voltage_mv = 0U;
    g_balancer.voltage_diff_mv = 0U;
    g_balancer.max_cell_index = 0U;
    g_balancer.min_cell_index = 0U;
    g_balancer.balance_duty = 0U;
    g_balancer.balance_timer_ms = 0U;

    HAL_ADC_Init();
    HAL_GPIO_Init();
    HAL_PWM_Init();

    printf("[BALANCE] Controller initialized. Cells=%u, Threshold=%u mV\n",
           CELL_COUNT, BALANCE_THRESHOLD_MV);
}

static void Balance_Task(void)
{
    uint32_t now = HAL_GetTick();

    if ((now - g_balancer.balance_timer_ms) < 100U) {
        return;
    }
    g_balancer.balance_timer_ms = now;

    Balance_SampleVoltages();
    Balance_CalculateStatistics();
    Balance_Execute();
}

static void Balance_PrintStatus(void)
{
    uint8_t i;
    printf("\n========== Battery Pack Status ==========\n");
    for (i = 0U; i < CELL_COUNT; i++) {
        printf("  Cell[%u]: %4u mV (ADC: %4u)  Balance: %s\n",
               i,
               g_balancer.cells[i].voltage_mv,
               g_balancer.cells[i].adc_raw,
               g_balancer.cells[i].balance_enable ? "ON " : "OFF");
    }
    printf("  Max: %u mV (Cell %u)\n",
           g_balancer.max_voltage_mv, g_balancer.max_cell_index);
    printf("  Min: %u mV (Cell %u)\n",
           g_balancer.min_voltage_mv, g_balancer.min_cell_index);
    printf("  Avg: %u mV\n", g_balancer.avg_voltage_mv);
    printf("  Diff: %u mV\n", g_balancer.voltage_diff_mv);
    printf("  State: %s\n",
           (g_balancer.state == BALANCE_IDLE) ? "IDLE" :
           (g_balancer.state == BALANCE_ACTIVE) ? "ACTIVE" : "FAULT");
    printf("  PWM Duty: %u / %u\n", g_balancer.balance_duty, PWM_PERIOD);
    printf("==========================================\n\n");
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    uint8_t loop;

    printf("========================================\n");
    printf("  Lithium Battery Active Balance Control\n");
    printf("  (Energy Transfer Method)\n");
    printf("========================================\n\n");

    Balance_Init();

    for (loop = 0U; loop < 10U; loop++) {
        printf("--- Control Loop %u ---\n", loop + 1U);
        Balance_Task();
        Balance_PrintStatus();
    }

    printf("Balance control simulation finished.\n");
    return 0;
}
