/* 孤岛检测阈值配置 */
#define NOMINAL_VOLTAGE           220.0f
#define NOMINAL_FREQUENCY         50.0f
#define VOLTAGE_OVERVOLT_LIMIT    1.10f   /* 110% 额定电压 */
#define VOLTAGE_UNDERVOLT_LIMIT   0.88f   /* 88% 额定电压 */
#define FREQ_OVERFREQ_LIMIT       50.5f   /* 50.5 Hz */
#define FREQ_UNDERFREQ_LIMIT      49.5f   /* 49.5 Hz */
#define TRIP_CONFIRM_COUNT        5       /* 连续越限次数确认 */

/* 孤岛检测状态机 */
typedef enum {
    ISLAND_STATE_NORMAL = 0,
    ISLAND_STATE_SUSPECT,
    ISLAND_STATE_TRIPPED
} IslandState_t;

/* 孤岛检测上下文 */
typedef struct {
    IslandState_t state;
    int           overVoltCnt;
    int           underVoltCnt;
    int           overFreqCnt;
    int           underFreqCnt;
    float         lastVoltage;
    float         lastFrequency;
    bool          islandDetected;
} IslandDetector_t;

/* ============================================================
 * 初始化
 * ============================================================ */
static void IslandDetector_Init(IslandDetector_t *det)
{
    if (det == NULL) {
        return;
    }
    det->state           = ISLAND_STATE_NORMAL;
    det->overVoltCnt     = 0;
    det->underVoltCnt    = 0;
    det->overFreqCnt     = 0;
    det->underFreqCnt    = 0;
    det->lastVoltage     = NOMINAL_VOLTAGE;
    det->lastFrequency   = NOMINAL_FREQUENCY;
    det->islandDetected  = false;
}

/* ============================================================
 * 被动式孤岛检测核心算法
 * 原理：监测并网点电压幅值与频率，若超出允许范围并持续
 *       一定时间，则判定为孤岛状态，触发保护。
 * ============================================================ */
static void IslandDetector_Update(IslandDetector_t *det,
                                  float voltageRms,
                                  float frequency)
{
    if (det == NULL) {
        return;
    }

    det->lastVoltage   = voltageRms;
    det->lastFrequency = frequency;

    /* --- 电压幅值检测 --- */
    if (voltageRms > NOMINAL_VOLTAGE * VOLTAGE_OVERVOLT_LIMIT) {
        det->overVoltCnt++;
        det->underVoltCnt = 0;
    } else if (voltageRms < NOMINAL_VOLTAGE * VOLTAGE_UNDERVOLT_LIMIT) {
        det->underVoltCnt++;
        det->overVoltCnt = 0;
    } else {
        det->overVoltCnt  = 0;
        det->underVoltCnt = 0;
    }

    /* --- 频率检测 --- */
    if (frequency > FREQ_OVERFREQ_LIMIT) {
        det->overFreqCnt++;
        det->underFreqCnt = 0;
    } else if (frequency < FREQ_UNDERFREQ_LIMIT) {
        det->underFreqCnt++;
        det->overFreqCnt = 0;
    } else {
        det->overFreqCnt  = 0;
        det->underFreqCnt = 0;
    }

    /* --- 状态机迁移 --- */
    switch (det->state) {
    case ISLAND_STATE_NORMAL:
        if (det->overVoltCnt  >= TRIP_CONFIRM_COUNT ||
            det->underVoltCnt >= TRIP_CONFIRM_COUNT ||
            det->overFreqCnt  >= TRIP_CONFIRM_COUNT ||
            det->underFreqCnt >= TRIP_CONFIRM_COUNT) {
            det->state = ISLAND_STATE_SUSPECT;
        }
        break;

    case ISLAND_STATE_SUSPECT:
        /* 再次确认，若持续越限则判定孤岛 */
        if (det->overVoltCnt  >= TRIP_CONFIRM_COUNT ||
            det->underVoltCnt >= TRIP_CONFIRM_COUNT ||
            det->overFreqCnt  >= TRIP_CONFIRM_COUNT ||
            det->underFreqCnt >= TRIP_CONFIRM_COUNT) {
            det->state          = ISLAND_STATE_TRIPPED;
            det->islandDetected = true;
        } else {
            /* 恢复正常 */
            det->state = ISLAND_STATE_NORMAL;
        }
        break;

    case ISLAND_STATE_TRIPPED:
        /* 孤岛已确认，保持跳闸状态，等待人工复位 */
        det->islandDetected = true;
        break;

    default:
        det->state = ISLAND_STATE_NORMAL;
        break;
    }
}

/* ============================================================
 * 保护动作：断开并网继电器 / 关断逆变器
 * ============================================================ */
static void IslandDetector_TripAction(const IslandDetector_t *det)
{
    if (det == NULL) {
        return;
    }
    if (det->islandDetected) {
        printf("[保护动作] 检测到孤岛！断开并网继电器，关断逆变器输出。\n");
        printf("           最后电压 = %.2f V, 最后频率 = %.2f Hz\n",
               det->lastVoltage, det->lastFrequency);
