```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量代替指针解引用，避免非法地址访问 */
static volatile float g_mock_adc_grid_voltage = 0.0f;
static volatile float g_mock_adc_grid_current = 0.0f;
static volatile float g_mock_adc_inv_current  = 0.0f;
static volatile float g_mock_pwm_duty         = 0.0f;
static volatile float g_mock_sys_tick_sec     = 0.0f;
static volatile int   g_mock_trip_flag        = 0;

#define MOCK_ADC_GRID_VOLTAGE_REG   (g_mock_adc_grid_voltage)
#define MOCK_ADC_GRID_CURRENT_REG   (g_mock_adc_grid_current)
#define MOCK_ADC_INV_CURRENT_REG    (g_mock_adc_inv_current)
#define MOCK_PWM_DUTY_REG           (g_mock_pwm_duty)
#define MOCK_SYS_TICK_SEC           (g_mock_sys_tick_sec)
#define MOCK_TRIP_FLAG_REG          (g_mock_trip_flag)

/* ================= 系统参数定义 ================= */
#define GRID_NOMINAL_FREQ_HZ        50.0f
#define GRID_NOMINAL_VOLTAGE_RMS    220.0f
#define CONTROL_LOOP_FREQ_HZ        10000.0f
#define CONTROL_LOOP_TS             (1.0f / CONTROL_LOOP_FREQ_HZ)

/* 阻抗扰动法参数 */
#define IMPEDANCE_DISTURB_AMPLITUDE 0.02f
#define IMPEDANCE_DISTURB_FREQ_HZ   25.0f
#define IMPEDANCE_DISTURB_PHASE_STEP (2.0f * 3.14159265358979323846f * IMPEDANCE_DISTURB_FREQ_HZ * CONTROL_LOOP_TS)

/* 孤岛检测阈值 */
#define VOLTAGE_OVERVOLTAGE_TH      253.0f
#define VOLTAGE_UNDERVOLTAGE_TH     195.0f
#define FREQ_OVERFREQ_TH            50.5f
#define FREQ_UNDERFREQ_TH           49.5f
#define IMPEDANCE_CHANGE_TH         0.15f
#define ISLAND_CONFIRM_COUNT        50

/* ================= 数据结构 ================= */
typedef struct {
    float grid_voltage_rms;
    float grid_current_rms;
    float grid_freq_hz;
    float impedance_est;
    float impedance_est_prev;
    float disturb_phase;
    float disturb_current_ref;
    int   island_counter;
    bool  island_detected;
    bool  protection_trip;
    /* 频率估计内部状态 */
    float prev_v;
    float zero_cross_time;
    float last_zero_cross_time;
    int   half_cycle_count;
} IslandDetector_t;

/* ================= 全局变量 ================= */
static IslandDetector_t g_island_detector;

/* ================= 辅助函数 ================= */

static float calc_rms(float instantaneous, float prev_rms)
{
    const float alpha = 0.01f;
    return prev_rms + alpha * (fabsf(instantaneous) - prev_rms);
}

static float estimate_frequency(IslandDetector_t *det, float voltage)
{
    float freq = det->grid_freq_hz;

    if (det->prev_v < 0.0f && voltage >= 0.0f) {
        det->last_zero_cross_time = det->zero_cross_time;
        det->zero_cross_time = MOCK_SYS_TICK_SEC;
        det->half_cycle_count++;

        if (det->half_cycle_count >= 2) {
            float period = det->zero_cross_time - det->last_zero_cross_time;
            if (period > 0.001f) {
                freq = 1.0f / period;
            }
            det->half_cycle_count = 0;
        }
    }

    det->prev_v = voltage;

    const float alpha = 0.05f;
    return det->grid_freq_hz + alpha * (freq - det->grid_freq_hz);
}

static float estimate_impedance(float voltage_rms, float current_rms)
{
    if (current_rms < 0.01f) {
        return 999.0f;
    }
    return voltage_rms / current_rms;
}

static float generate_impedance_disturbance(float *phase)
{
    float disturb = IMPEDANCE_DISTURB_AMPLITUDE * sinf(*phase);
    *phase += IMPEDANCE_DISTURB_PHASE_STEP;
    if (*phase > 2.0f * 3.14159265358979323846f) {
        *phase -= 2.0f * 3.14159265358979323846f;
    }
    return disturb;
}

static void island_detection_process(IslandDetector_t *det)
{
    float v_grid = MOCK_ADC_GRID_VOLTAGE_REG;
    float i_grid = MOCK_ADC_GRID_CURRENT_REG;
    float i_inv  = MOCK_ADC_INV_CURRENT_REG;

    det->grid_voltage_rms = calc_rms(v_grid, det->grid_voltage_rms);
    det->grid_current_rms = calc_rms(i_grid, det->grid_current_rms);

    det->grid_freq_hz = estimate_frequency(det, v_grid);

    det->impedance_est_prev = det->impedance_est;
    det->impedance_est = estimate_impedance(det->grid_voltage_rms, det->grid_current_rms);

    det->disturb_current_ref = generate_impedance_disturbance(&det->disturb_phase);

    float current_ref = i_inv + det->disturb_current_ref * det->grid_current_rms;

    bool voltage_abnormal = (det->grid_voltage_rms > VOLTAGE_OVERVOLTAGE_TH) ||
                            (det->grid_voltage_rms < VOLTAGE_UNDERVOLTAGE_TH);
    bool freq_abnormal = (det->grid_freq_hz > FREQ_OVERFREQ_TH) ||
                         (det->grid_freq_hz < FREQ_UNDERFREQ_TH);

    float impedance_change = 0.0f;
    if (det->impedance_est_prev > 0.01f) {
        impedance_change = fabsf(det->impedance_est - det->impedance_est_prev) / det->impedance_est_prev;
    }
    bool impedance_abnormal = (impedance_change > IMPEDANCE_CHANGE_TH);

    if (voltage_abnormal || freq_abnormal || impedance_abnormal) {
        det->island_counter++;
        if (det->island_counter >= ISLAND_CONFIRM_COUNT) {
            det->island_detected = true;
            det->protection_trip = true;
        }
    } else {
        det->island_counter = 0;
        det->island_detected = false;
    }

    MOCK_PWM_DUTY_REG = current_ref;

    if (det->protection_trip) {
        MOCK_TRIP_FLAG_REG = 1;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    g_island_detector.grid_voltage_rms = GRID_NOMINAL_VOLTAGE_RMS;
    g_island_detector.grid_current_rms = 10.0f;
