#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 模拟寄存器与硬件抽象 ==================== */
static volatile uint32_t mock_wind_speed_reg = 0;
static volatile uint32_t mock_wind_valid_reg = 0;
static volatile uint32_t mock_pitch_cmd_reg = 0;
static volatile uint32_t mock_pitch_fb_reg = 0;
static volatile uint32_t mock_pitch_enable_reg = 0;
static volatile uint32_t mock_gen_speed_reg = 0;
static volatile uint32_t mock_gen_speed_valid_reg = 0;

#define WIND_SPEED_REG         (mock_wind_speed_reg)
#define WIND_VALID_REG         (mock_wind_valid_reg)
#define PITCH_CMD_REG          (mock_pitch_cmd_reg)
#define PITCH_FB_REG           (mock_pitch_fb_reg)
#define PITCH_ENABLE_REG       (mock_pitch_enable_reg)
#define GEN_SPEED_REG          (mock_gen_speed_reg)
#define GEN_SPEED_VALID_REG    (mock_gen_speed_valid_reg)

/* ==================== 控制参数与常量 ==================== */
#define PI                     3.14159265358979323846f
#define RAD_TO_DEG             (180.0f / PI)
#define DEG_TO_RAD             (PI / 180.0f)

#define RATED_GEN_SPEED_RPM    1500.0f
#define RATED_POWER_KW         2000.0f
#define CUT_IN_WIND_SPEED      3.0f
#define RATED_WIND_SPEED       12.0f
#define CUT_OUT_WIND_SPEED     25.0f

#define PITCH_MIN_DEG          0.0f
#define PITCH_MAX_DEG          90.0f
#define PITCH_RATE_LIMIT_DPS   5.0f

#define CONTROL_PERIOD_S       0.01f

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float integral_limit;
    float output_limit;
} PID_Controller;

typedef struct {
    float wind_speed;
    float Kp;
    float Ki;
    float Kd;
} WindAdaptiveGain;

typedef struct {
    float wind_speed;
    float gen_speed_rpm;
    float pitch_angle_deg;
    float pitch_rate_dps;
    float power_kw;
    float torque_ref;
    float pitch_ref;
    uint8_t system_enabled;
    uint8_t fault_flag;
} WindTurbineState;

static const WindAdaptiveGain adaptive_gain_table[] = {
    {  3.0f,  0.80f, 0.05f, 0.02f },
    {  6.0f,  1.00f, 0.08f, 0.03f },
    {  9.0f,  1.20f, 0.12f, 0.04f },
    { 12.0f,  1.50f, 0.15f, 0.05f },
    { 15.0f,  1.80f, 0.20f, 0.06f },
    { 18.0f,  2.10f, 0.25f, 0.07f },
    { 21.0f,  2.40f, 0.30f, 0.08f },
    { 25.0f,  2.80f, 0.35f, 0.10f }
};

#define GAIN_TABLE_SIZE (sizeof(adaptive_gain_table) / sizeof(adaptive_gain_table[0]))

static float clampf(float value, float min_val, float max_val)
{
    if (value < min_val) return min_val;
    if (value > max_val) return max_val;
    return value;
}

static float lerp(float a, float b, float t)
{
    return a + (b - a) * t;
}

static void get_adaptive_gains(float wind_speed, float *Kp, float *Ki, float *Kd)
{
    uint32_t i;
    float t;

    if (wind_speed <= adaptive_gain_table[0].wind_speed) {
        *Kp = adaptive_gain_table[0].Kp;
        *Ki = adaptive_gain_table[0].Ki;
        *Kd = adaptive_gain_table[0].Kd;
        return;
    }

    if (wind_speed >= adaptive_gain_table[GAIN_TABLE_SIZE - 1].wind_speed) {
        *Kp = adaptive_gain_table[GAIN_TABLE_SIZE - 1].Kp;
        *Ki = adaptive_gain_table[GAIN_TABLE_SIZE - 1].Ki;
        *Kd = adaptive_gain_table[GAIN_TABLE_SIZE - 1].Kd;
        return;
    }

    for (i = 0; i < GAIN_TABLE_SIZE - 1; i++) {
        if (wind_speed >= adaptive_gain_table[i].wind_speed &&
            wind_speed <= adaptive_gain_table[i + 1].wind_speed) {
            t = (wind_speed - adaptive_gain_table[i].wind_speed) /
                (adaptive_gain_table[i + 1].wind_speed - adaptive_gain_table[i].wind_speed);
            *Kp = lerp(adaptive_gain_table[i].Kp, adaptive_gain_table[i + 1].Kp, t);
            *Ki = lerp(adaptive_gain_table[i].Ki, adaptive_gain_table[i + 1].Ki, t);
            *Kd = lerp(adaptive_gain_table[i].Kd, adaptive_gain_table[i + 1].Kd, t);
            return;
        }
    }

    *Kp = adaptive_gain_table[0].Kp;
    *Ki = adaptive_gain_table[0].Ki;
    *Kd = adaptive_gain_table[0].Kd;
}

static void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd,
                     float integral_limit, float output_limit)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_limit = integral_limit;
    pid->output_limit = output_limit;
}

static void PID_UpdateGains(PID_Controller *pid, float Kp, float Ki, float Kd)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
}

static float PID_Compute(PID_Controller *pid, float setpoint, float feedback, float dt)
{
    float error;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = CONTROL_PERIOD_S;
    }

    error = setpoint - feedback;

    pid->integral += error * dt;
    pid->integral = clampf(pid->integral, -pid->integral_limit, pid->integral_limit);

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    output = clampf(output, -pid->output_limit, pid->output_limit);

    return output;
}

typedef struct {
    PID_Controller pid;
    float pitch_ref_deg;
    float pitch_rate_limit;
    float last_pitch_cmd;
    float wind_speed_filtered;
    float filter_alpha;
    uint32_t fault_counter;
} PitchController;

static void PitchController_Init(PitchController *ctrl)
{
    PID_Init(&ctrl->pid, 1.0f, 0.1f, 0.05f, 50.0f, 30.0f);
    ctrl->pitch_ref_deg = 0.0f;
    ctrl->pitch_rate_limit = PITCH_RATE_LIMIT_DPS;
    ctrl->last_pitch_cmd = 0.0f;
    ctrl->wind_speed_filtered = 0.0f;
    ctrl->filter_alpha = 0.1f;
    ctrl->fault_counter = 0;
}

static float PitchController_Compute(PitchController *ctrl,
                                     float wind_speed,
                                     float gen_speed_rpm,
                                     float dt)
{
    float Kp, Ki, Kd;
    float pitch_cmd;
    float pitch_delta;
    float max_delta;

    if (dt <= 0.0f) {
        dt = CONTROL_PERIOD_S;
    }

    ctrl->wind_speed_filtered = ctrl->filter_alpha * wind_speed +
                                (1.0f - ctrl->filter_alpha) * ctrl->wind_speed_filtered;

    get_adaptive_gains(ctrl->wind_speed_filtered, &Kp, &Ki, &Kd);
    PID_UpdateGains(&ctrl->pid, Kp, Ki, Kd);

    pitch_cmd = PID_Compute(&ctrl->pid, RATED_GEN_SPEED_RPM, gen_speed_rpm, dt);
    pitch_cmd = clampf(pitch_cmd, PITCH_MIN_DEG, PITCH_MAX_DEG);

    pitch_delta = pitch_cmd - ctrl->last_pitch_cmd;
    max_delta = ctrl->pitch_rate_limit * dt;
    if (pitch_delta > max_delta) {
        pitch_cmd = ctrl->last_pitch_cmd + max_delta;
    } else if (pitch_delta < -max_delta) {
        pitch_cmd = ctrl->last_pitch_cmd - max_delta;
    }

    ctrl->last_pitch_cmd = pitch_cmd;
    ctrl->pitch_ref_deg = pitch_cmd;

    return pitch_cmd;
}

static void ReadSensors(WindTurbineState *state)
{
    if (WIND_VALID_REG) {
        state->wind_speed = (float)WIND_SPEED_REG / 100.0f;
    } else {
        state->wind_speed = 0.0f;
    }

    if (GEN_SPEED_VALID_REG) {
        state->gen_speed_rpm = (float)GEN_SPEED_REG / 10.0f;
    } else {
        state->gen_speed_rpm = 0.0f;
    }

    state->pitch_angle_deg = (float)PITCH_FB_REG / 100.0f;
}

static void WriteActuators(const WindTurbineState *state)
{
    PITCH_CMD_REG = (uint32_t)(state->pitch_ref * 100.0f);
    PITCH_ENABLE_REG = state->system_enabled ? 1U : 0U;
}

static void UpdatePowerEstimate(WindTurbineState *state)
{
    float cp;
    float lambda;
    float pitch_rad;
    float wind_power;
    float denom;
    float lambda_i;

    pitch_rad = state->pitch_angle_deg * DEG_TO_RAD;

    denom = state->wind_speed + 0.001f;
    lambda = state->gen_speed_rpm / denom;
    if (lambda < 0.1f) lambda = 0.1f;

    {
        float pitch_cubed = pitch_rad * pitch_rad * pitch_rad;
        float denom2 = (1.0f / (lambda + 0.08f * pitch_rad)) - (0.035f / (pitch_cubed + 1.0f));
        if (fabsf(denom2) < 1e-6f) {
            denom2 = 1e-6f;
        }
        lambda_i = 1.0f / denom2;
        if (lambda_i < 0.1f) lambda_i = 0.1f;
        cp = 0.22f * (116.0f / lambda_i - 0.4f * pitch_rad - 5.0f) * expf(-12.5f / lambda_i);
    }
    cp = clampf(cp, 0.0f, 0.593f);

    wind_power = 0.5f * 1.225f * PI * 60.0f * 60.0f *
                 state->wind_speed * state->wind_speed * state->wind_speed;
    state->power_kw = wind_power * cp / 1000.0f;
}

static void ControlLoop(WindTurbineState *state, PitchController *pitch_ctrl, float dt)
{
    float pitch_cmd;

    ReadSensors(state);

    if (state->wind_speed > CUT_OUT_WIND_SPEED || state->wind_speed < CUT_IN_WIND_SPEED) {
        state->system_enabled = 0;
        state->pitch_ref = PITCH_MAX_DEG;
        WriteActuators(state);
        return;
    }

    state->system_enabled = 1;

    pitch_cmd = PitchController_Compute(pitch_ctrl,
                                        state->wind_speed,
                                        state->gen_speed_rpm,
                                        dt);

    state->pitch_ref = pitch_cmd;

    UpdatePowerEstimate(state);

    WriteActuators(state);
}

static void PrintState(const WindTurbineState *state, uint32_t step)
{
    printf("Step %4u | Wind: %6.2f m/s | GenSpd: %7.2f rpm | Pitch: %6.2f deg | Power: %8.2f kW | En: %u\n",
           step,
           state->wind_speed,
           state->gen_speed_rpm,
           state->pitch_angle_deg,
           state->power_kw,
           state->system_enabled);
}

int main(void)
{
    WindTurbineState state;
    PitchController pitch_ctrl;
    uint32_t step;
    float dt;
    float sim_wind;
    float sim_gen_speed;

    state.wind_speed = 0.0f;
    state.gen_speed_rpm = 0.0f;
    state.pitch_angle_deg = 0.0f;
    state.pitch_rate_dps = 0.0f;
    state.power_kw = 0.0f;
    state.torque_ref = 0.0f;
    state.pitch_ref = 0.0f;
    state.system_enabled = 0;
    state.fault_flag = 0;

    PitchController_Init(&pitch_ctrl);

    dt = CONTROL_PERIOD_S;

    printf("========================================\n");
    printf("  Wind Turbine Pitch Control Simulation\n");
    printf("  PID with Wind Speed Adaptive Gains\n");
    printf("========================================\n\n");

    for (step = 0; step < 200; step++) {
        sim_wind = 5.0f + 13.0f * (float)step / 200.0f;
        sim_wind += 0.5f * sinf((float)step * 0.1f);

        sim_gen_speed = RATED_GEN_SPEED_RPM * (sim_wind / RATED_WIND_SPEED);
        sim_gen_speed = clampf(sim_gen_speed, 0.0f, RATED_GEN_SPEED_RPM * 1.2f);

        WIND_SPEED_REG = (uint32_t)(sim_wind * 100.0f);
        WIND_VALID_REG = 1U;
        GEN_SPEED_REG = (uint32_t)(sim_gen_speed * 10.0f);
        GEN_SPEED_VALID_REG = 1U;

        ControlLoop(&state, &pitch_ctrl, dt);

        state.pitch_angle_deg += (state.pitch_ref - state.pitch_angle_deg) * 0.3f;
        PITCH_FB_REG = (uint32_t)(state.pitch_angle_deg * 100.0f);

        if (step % 10 == 0) {
            PrintState(&state, step);
        }
    }

    printf("\n========================================\n");
    printf("  Simulation Complete\n");
    printf("  Final Pitch Angle: %.2f deg\n", state.pitch_angle_deg);
    printf("  Final Power: %.2f kW\n", state.power_kw);
    printf("========================================\n");

    return 0;
}
