```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象层 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint16_t g_mock_adc_wind_speed_reg = 0;
static volatile uint16_t g_mock_adc_power_reg = 0;
static volatile uint16_t g_mock_pwm_duty_reg = 0;
static volatile uint32_t g_mock_sys_status_reg = 0;

#define MOCK_ADC_WIND_SPEED_REG     (g_mock_adc_wind_speed_reg)
#define MOCK_ADC_POWER_REG          (g_mock_adc_power_reg)
#define MOCK_PWM_DUTY_REG           (g_mock_pwm_duty_reg)
#define MOCK_SYS_STATUS_REG         (g_mock_sys_status_reg)

/* 状态位定义 */
#define SYS_STATUS_RUN              (1U << 0)
#define SYS_STATUS_FAULT            (1U << 1)

/* ================= 系统参数定义 ================= */
#define WIND_SPEED_MIN_MPS          3.0f
#define WIND_SPEED_MAX_MPS          25.0f
#define WIND_SPEED_RATED_MPS        12.0f
#define POWER_RATED_KW              1500.0f
#define POWER_MIN_KW                0.0f

#define ADC_VREF                    3.3f
#define ADC_RESOLUTION              4095.0f

#define WIND_SPEED_SCALE            (30.0f / ADC_VREF)
#define POWER_SCALE                 (2000.0f / ADC_VREF)

#define MPPT_STEP_DUTY              0.5f
#define MPPT_DUTY_MIN               10.0f
#define MPPT_DUTY_MAX               95.0f
#define MPPT_SAMPLE_TIME_MS         100

#define CURVE_A                     0.85f
#define CURVE_B                     -8.5f
#define CURVE_C                     45.0f
#define CURVE_D                     -30.0f

/* ================= 数据结构定义 ================= */
typedef struct {
    float wind_speed;
    float power_actual;
    float power_ref;
    float duty_cycle;
    float duty_prev;
    float power_prev;
    uint8_t mppt_dir;
    uint32_t tick_ms;
} MpptCtrl_t;

/* ================= 全局变量 ================= */
static MpptCtrl_t g_mppt;

/* ================= 函数声明 ================= */
static float adc_to_wind_speed(uint16_t adc_val);
static float adc_to_power(uint16_t adc_val);
static float wind_speed_to_power_ref(float wind_speed);
static void mppt_init(MpptCtrl_t *ctrl);
static void mppt_update(MpptCtrl_t *ctrl);
static void mppt_perturb_observe(MpptCtrl_t *ctrl);
static void mppt_output_duty(float duty);
static void system_delay_ms(uint32_t ms);

/* ================= 函数实现 ================= */

static float adc_to_wind_speed(uint16_t adc_val)
{
    float voltage = ((float)adc_val / ADC_RESOLUTION) * ADC_VREF;
    float wind_speed = voltage * WIND_SPEED_SCALE;
    if (wind_speed < 0.0f) {
        wind_speed = 0.0f;
    }
    return wind_speed;
}

static float adc_to_power(uint16_t adc_val)
{
    float voltage = ((float)adc_val / ADC_RESOLUTION) * ADC_VREF;
    float power = voltage * POWER_SCALE;
    if (power < 0.0f) {
        power = 0.0f;
    }
    return power;
}

static float wind_speed_to_power_ref(float wind_speed)
{
    float power_ref;

    if (wind_speed < WIND_SPEED_MIN_MPS) {
        return 0.0f;
    }
    if (wind_speed > WIND_SPEED_MAX_MPS) {
        return 0.0f;
    }
    if (wind_speed >= WIND_SPEED_RATED_MPS) {
        return POWER_RATED_KW;
    }

    power_ref = CURVE_A * wind_speed * wind_speed * wind_speed
              + CURVE_B * wind_speed * wind_speed
              + CURVE_C * wind_speed
              + CURVE_D;

    if (power_ref < POWER_MIN_KW) {
        power_ref = POWER_MIN_KW;
    }
    if (power_ref > POWER_RATED_KW) {
        power_ref = POWER_RATED_KW;
    }

    return power_ref;
}

static void mppt_init(MpptCtrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }
    ctrl->wind_speed = 0.0f;
    ctrl->power_actual = 0.0f;
    ctrl->power_ref = 0.0f;
    ctrl->duty_cycle = 50.0f;
    ctrl->duty_prev = 50.0f;
    ctrl->power_prev = 0.0f;
    ctrl->mppt_dir = 0;
    ctrl->tick_ms = 0;

    MOCK_SYS_STATUS_REG |= SYS_STATUS_RUN;
    MOCK_SYS_STATUS_REG &= ~SYS_STATUS_FAULT;
}

static void mppt_output_duty(float duty)
{
    uint16_t duty_reg;

    if (duty < MPPT_DUTY_MIN) {
        duty = MPPT_DUTY_MIN;
    }
    if (duty > MPPT_DUTY_MAX) {
        duty = MPPT_DUTY_MAX;
    }

    duty_reg = (uint16_t)(duty * 10.0f);
    MOCK_PWM_DUTY_REG = duty_reg;
}

static void mppt_perturb_observe(MpptCtrl_t *ctrl)
{
    float delta_power;
    float delta_duty;

    if (ctrl == NULL) {
        return;
    }

    delta_power = ctrl->power_actual - ctrl->power_prev;
    delta_duty = ctrl->duty_cycle - ctrl->duty_prev;

    if (fabsf(delta_power) < 0.01f) {
        /* 功率变化极小，保持当前方向 */
    } else if (delta_power > 0.0f) {
        if (delta_duty > 0.0f) {
            ctrl->mppt_dir = 0;
        } else {
            ctrl->mppt_dir = 1;
        }
    } else {
        if (delta_duty > 0.0f) {
            ctrl->mppt_dir = 1;
        } else {
            ctrl->mppt_dir = 0;
        }
    }

    ctrl->duty_prev = ctrl->duty_cycle;
    ctrl->power_prev = ctrl->power_actual;

    if (ctrl->mppt_dir == 0) {
        ctrl->duty_cycle += MPPT_STEP_DUTY;
    } else {
        ctrl->duty_cycle -= MPPT_STEP_DUTY;
    }

    if (ctrl->duty_cycle < MPPT_DUTY_MIN) {
        ctrl->duty_cycle = MPPT_DUTY_MIN;
        ctrl->mppt_dir = 0;
    }
    if (ctrl->duty_cycle > MPPT_DUTY_MAX) {
        ctrl->duty_cycle = MPPT_DUTY_MAX;
        ctrl->mppt_dir = 1;
    }
}

static void mppt_update(MpptCtrl_t *ctrl)
{
    uint16_t adc_wind;
    uint16_t adc_power;

    if (ctrl == NULL) {
        return;
    }

    adc_wind = MOCK_ADC_WIND_SPEED_REG;
    adc_power = MOCK_ADC_POWER_REG;

    ctrl->wind_speed = adc_to_wind_speed(adc_wind);
    ctrl->power_actual = adc_to_power(adc_power);

    ctrl->power_ref = wind_speed_to_power_ref(ctrl->wind_speed);

    if (ctrl->wind_speed < WIND_SPEED_MIN_MPS ||
        ctrl->wind_speed > WIND_SPEED_MAX_MPS) {
        ctrl->duty_cycle = MPPT_DUTY_MIN;
        ctrl->power_prev = 0.0f;
        ctrl->duty_prev = ctrl->duty_cycle;
        mppt_output_duty(ctrl->duty_cycle);
        return;
    }

    mppt_perturb_observe(ctrl);
    mppt_output_duty(ctrl->duty_cycle);

    ctrl->tick_ms += MPPT_SAMPLE_TIME_MS;
}

static void system_delay_ms(uint32_t ms)
{
    volatile uint32_t i;
    volatile uint32_t limit = ms * 1000U;
    for (i = 0; i < limit; i++) {
        /* 空循环模拟延时 */
    }
}

