/* ==================== 模拟硬件寄存器与宏定义 ==================== */
/* 使用静态变量模拟寄存器，避免非法地址访问 */
static volatile float mock_adc_p1;
static volatile float mock_adc_q1;
static volatile float mock_adc_p2;
static volatile float mock_adc_q2;
static volatile float mock_dac_f1;
static volatile float mock_dac_v1;
static volatile float mock_dac_f2;
static volatile float mock_dac_v2;

#define ADC_CH_P1       (&mock_adc_p1)
#define ADC_CH_Q1       (&mock_adc_q1)
#define ADC_CH_P2       (&mock_adc_p2)
#define ADC_CH_Q2       (&mock_adc_q2)

#define DAC_CH_F1       (&mock_dac_f1)
#define DAC_CH_V1       (&mock_dac_v1)
#define DAC_CH_F2       (&mock_dac_f2)
#define DAC_CH_V2       (&mock_dac_v2)

/* 系统参数 */
#define NOMINAL_FREQ    50.0f
#define NOMINAL_VOLT    311.0f
#define OMEGA_NOM       314.159f
#define PI_F            3.1415926f

/* 下垂系数 */
#define MP1             0.0001f
#define MQ1             0.0005f
#define MP2             0.0001f
#define MQ2             0.0005f

/* 低通滤波器截止频率 */
#define OMEGA_C         31.416f

/* 控制周期 */
#define TS              0.0001f

/* ==================== 数据结构 ==================== */
typedef struct {
    float P;
    float Q;
    float P_filt;
    float Q_filt;
    float freq;
    float volt;
    float omega;
    float theta;
    float mp;
    float mq;
} DroopCtrl_t;

/* ==================== 全局变量 ==================== */
static DroopCtrl_t inv1;
static DroopCtrl_t inv2;

/* ==================== 函数声明 ==================== */
static void Droop_Init(DroopCtrl_t *d, float mp, float mq);
static void Droop_Update(DroopCtrl_t *d, float P_meas, float Q_meas);
static void Droop_Output(DroopCtrl_t *d, volatile float *dac_f, volatile float *dac_v);

/* ==================== 初始化 ==================== */
static void Droop_Init(DroopCtrl_t *d, float mp, float mq)
{
    d->P = 0.0f;
    d->Q = 0.0f;
    d->P_filt = 0.0f;
    d->Q_filt = 0.0f;
    d->freq = NOMINAL_FREQ;
    d->volt = NOMINAL_VOLT;
    d->omega = OMEGA_NOM;
    d->theta = 0.0f;
    d->mp = mp;
    d->mq = mq;
}

/* ==================== 下垂控制核心更新 ==================== */
static void Droop_Update(DroopCtrl_t *d, float P_meas, float Q_meas)
{
    /* 1. 低通滤波，提取平均功率 */
    d->P_filt += OMEGA_C * TS * (P_meas - d->P_filt);
    d->Q_filt += OMEGA_C * TS * (Q_meas - d->Q_filt);

    /* 2. P-f 下垂控制 */
    d->freq = NOMINAL_FREQ - d->mp * d->P_filt;

    /* 3. Q-V 下垂控制 */
    d->volt = NOMINAL_VOLT - d->mq * d->Q_filt;

    /* 4. 频率限幅 */
    if (d->freq > 50.5f) d->freq = 50.5f;
    if (d->freq < 49.5f) d->freq = 49.5f;

    /* 5. 电压限幅 */
    if (d->volt > 330.0f) d->volt = 330.0f;
    if (d->volt < 290.0f) d->volt = 290.0f;

    /* 6. 角频率与相位积分 */
    d->omega = 2.0f * PI_F * d->freq;
    d->theta += d->omega * TS;

    /* 7. 相位卷绕 */
    if (d->theta > 2.0f * PI_F) {
        d->theta -= 2.0f * PI_F;
    }
}

/* ==================== 输出到执行机构 ==================== */
static void Droop_Output(DroopCtrl_t *d, volatile float *dac_f, volatile float *dac_v)
{
    *dac_f = d->freq;
    *dac_v = d->volt;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    int i;
    float P1_meas, Q1_meas, P2_meas, Q2_meas;

    printf("===== Microgrid Droop Control (P-f / Q-V) =====\n\n");

    /* 初始化两台逆变器 */
    Droop_Init(&inv1, MP1, MQ1);
    Droop_Init(&inv2, MP2, MQ2);

    /* 模拟 1000 个控制周期 */
    for (i = 0; i < 1000; i++) {
        /* 模拟采样 */
        P1_meas = 5000.0f;
        Q1_meas = 2000.0f;
        P2_meas = 5000.0f;
        Q2_meas = 2000.0f;

        /* 更新下垂控制 */
        Droop_Update(&inv1, P1_meas, Q1_meas);
        Droop_Update(&inv2, P2_meas, Q2_meas);

        /* 输出到 DAC */
        Droop_Output(&inv1, DAC_CH_F1, DAC_CH_V1);
        Droop_Output(&inv2, DAC_CH_F2, DAC_CH_V2);

        /* 每 200 个周期打印一次 */
        if ((i + 1) % 200 == 0) {
            printf("Cycle %4d:\n", i + 1);
            printf("  INV1: P_filt=%8.2f W  Q_filt=%8.2f Var  f=%7.4f Hz  V=%8.2f V  theta=%6.3f rad\n",
                   inv1.P_filt, inv1.Q_filt, inv1.freq, inv1.volt, inv1.theta);
            printf("  INV2: P_filt=%8.2f W  Q_filt=%8.2f Var  f=%7.4f Hz  V=%8.2f V  theta=%6.3f rad\n",
                   inv2.P_filt, inv2.Q_filt, inv2.freq, inv2.volt, inv2.theta);
            printf("  Power Sharing Ratio: P1/P2 = %.4f, Q1/Q2 = %.4f\n\n",
                   inv1.P_filt / inv2.P_filt, inv1.Q_filt / inv2.Q_filt);
        }
    }

    printf("===== Droop Control Simulation Complete =====\n");
    return 0;
}
