#define REG_ADC_VOLTAGE      (g_adc_voltage)
#define REG_PWM_DUTY         (g_pwm_duty)
#define REG_PWM_ENABLE       (g_pwm_enable)
#define REG_SYSTICK_MS       (g_systick_ms)

#define ADC_REF_VOLTAGE      3.3f
#define ADC_RESOLUTION       4095.0f
#define CURRENT_SENSOR_GAIN  0.05f
#define PWM_MAX_DUTY         10000U
#define PWM_MIN_DUTY         0U

/* ================= 控制参数 ================= */
#define TARGET_CURRENT_A     100.0f
#define KP_CURRENT           0.8f
#define KI_CURRENT           0.02f
#define RIPPLE_FILTER_ALPHA  0.15f
#define RIPPLE_COMP_GAIN     0.3f
#define CONTROL_PERIOD_MS    1U
#define MAX_INTEGRAL         500.0f
#define MIN_INTEGRAL         (-500.0f)

/* ================= 数据结构 ================= */
typedef struct {
    float target_current;
    float actual_current;
    float filtered_current;
    float ripple;
    float integral;
    float prev_error;
    float duty;
    float kp;
    float ki;
    float ripple_alpha;
    float ripple_comp_gain;
    bool  enabled;
} CurrentController;

/* ================= 函数声明 ================= */
static float read_current_sensor(void);
static void  set_pwm_duty(float duty_percent);
static void  enable_pwm(bool en);
static void  controller_init(CurrentController *ctrl);
static float controller_update(CurrentController *ctrl, float measured_current);
static void  delay_ms(uint32_t ms);

/* ================= 主函数 ================= */
int main(void)
{
    CurrentController ctrl;
    uint32_t tick = 0;
    uint32_t sim_steps = 200;

    printf("===== Hydrogen Electrolyzer Current Controller =====\n");
    printf("Target Current: %.2f A\n", TARGET_CURRENT_A);
    printf("KP: %.3f  KI: %.3f\n", KP_CURRENT, KI_CURRENT);
    printf("Ripple Filter Alpha: %.3f  Ripple Comp Gain: %.3f\n",
           RIPPLE_FILTER_ALPHA, RIPPLE_COMP_GAIN);
    printf("----------------------------------------------------\n");
    printf("Step | Measured(A) | Filtered(A) | Ripple(A) | Duty(%%)\n");
    printf("----------------------------------------------------\n");

    controller_init(&ctrl);
    enable_pwm(true);

    for (uint32_t i = 0; i < sim_steps; i++) {
        float measured = read_current_sensor();
        float duty = controller_update(&ctrl, measured);

        set_pwm_duty(duty);

        if (i % 20 == 0 || i == sim_steps - 1) {
            printf("%4lu | %10.3f | %10.3f | %8.3f | %7.2f\n",
                   (unsigned long)i,
                   measured,
                   ctrl.filtered_current,
                   ctrl.ripple,
                   ctrl.duty);
        }

        delay_ms(CONTROL_PERIOD_MS);
        tick += CONTROL_PERIOD_MS;
    }

    enable_pwm(false);
    printf("----------------------------------------------------\n");
    printf("Control loop finished. Total time: %lu ms\n",
           (unsigned long)tick);
    printf("Final Duty: %.2f%%  Final Current: %.3f A\n",
           ctrl.duty, ctrl.filtered_current);

    return 0;
}

/* ================= 控制器初始化 ================= */
static void controller_init(CurrentController *ctrl)
{
    ctrl->target_current   = TARGET_CURRENT_A;
    ctrl->actual_current   = 0.0f;
    ctrl->filtered_current = 0.0f;
    ctrl->ripple           = 0.0f;
    ctrl->integral         = 0.0f;
    ctrl->prev_error       = 0.0f;
    ctrl->duty             = 0.0f;
    ctrl->kp               = KP_CURRENT;
    ctrl->ki               = KI_CURRENT;
    ctrl->ripple_alpha     = RIPPLE_FILTER_ALPHA;
    ctrl->ripple_comp_gain = RIPPLE_COMP_GAIN;
    ctrl->enabled          = true;
}

/* ================= 控制器核心更新 ================= */
static float controller_update(CurrentController *ctrl, float measured_current)
{
    if (!ctrl->enabled) {
        return 0.0f;
    }

    ctrl->actual_current = measured_current;

    /* 一阶低通滤波，提取直流分量 */
    ctrl->filtered_current = ctrl->filtered_current +
        ctrl->ripple_alpha * (measured_current - ctrl->filtered_current);

    /* 纹波 = 原始信号 - 滤波后直流分量 */
    ctrl->ripple = measured_current - ctrl->filtered_current;

    /* PI 控制基于滤波后的直流分量 */
    float error = ctrl->target_current - ctrl->filtered_current;

    /* 积分项累加并限幅 */
    ctrl->integral += ctrl->ki * error;
    if (ctrl->integral > MAX_INTEGRAL) {
        ctrl->integral = MAX_INTEGRAL;
    } else if (ctrl->integral < MIN_INTEGRAL) {
        ctrl->integral = MIN_INTEGRAL;
    }

    /* PI 输出 */
    float pi_output = ctrl->kp * error + ctrl->integral;

    /* 纹波抑制：对纹波做反向补偿 */
    float ripple_compensation = -ctrl->ripple_comp_gain * ctrl->ripple;

    /* 总占空比 */
    float duty = pi_output + ripple_compensation;

    /* 占空比限幅 */
    if (duty > 100.0f) {
        duty = 100.0f;
    } else if (duty < 0.0f) {
        duty = 0.0f;
    }

    ctrl->prev_error = error;
    ctrl->duty = duty;

    return duty;
}

/* ================= 硬件抽象层（Mock） ================= */
static float read_current_sensor(void)
{
    static uint32_t sim_tick = 0;
    sim_tick++;

    /* 模拟电解槽电流：目标值 + 纹波 + 噪声 */
    float base = TARGET_CURRENT_A;
    float ripple = 2.5f * sinf((float)sim_tick * 0.3f);
    float noise  = 0.3f * sinf((float)sim_tick * 1.7f);
    float load   = 1.0f * sinf((float)sim_tick * 0.05f);

    float current = base + ripple + noise + load;

    /* 模拟 ADC 读取 */
    float voltage = current * CURRENT_SENSOR_GAIN;
    uint16_t adc_raw = (uint16_t)((voltage / ADC_REF_VOLTAGE) * ADC_RESOLUTION);
    if (adc_raw > 4095U) {
        adc_raw = 4095U;
    }

    REG_ADC_CURRENT = adc_raw;

    /* 反算回电流值 */
    float measured = ((float)adc_raw / ADC_RESOLUTION) * ADC_REF_VOLTAGE
                     / CURRENT_SENSOR_GAIN;

    return measured;
}

static void set_pwm_duty(float duty_percent)
{
    if (duty_percent < 0.0f) {
        duty_percent = 0.0f;
    } else if (duty_percent > 100.0f) {
        duty_percent = 100.0f;
    }

    uint16_t duty_raw = (uint16_t)((duty_percent / 100.0f) * PWM_MAX_DUTY);
    if (duty_raw > PWM_MAX_DUTY) {
        duty_raw = PWM_MAX_DUTY;
    }

    REG_PWM_DUTY = duty_raw;
}

static void enable_pwm(bool en)
{
    REG_PWM_ENABLE = en ? 1U : 0U;
}

static void delay_ms(uint32_t ms)
{
    /* 模拟延时，实际中由 SysTick 或定时器实现 */
    volatile uint32_t count = ms * 1000U;
    while (count--) {
        /* 空循环模拟 */
    }
}
