#define ADC_REF_VOLTAGE      3.3f
#define ADC_RESOLUTION       4095.0f
#define CURRENT_SENSOR_GAIN  0.05f
#define PWM_MAX_DUTY         1000

/* ================= 控制器参数 ================= */
#define CONTROL_FREQ_HZ      10000.0f
#define CONTROL_PERIOD_S     (1.0f / CONTROL_FREQ_HZ)

/* 恒流 PI 参数 */
#define PI_KP                0.85f
#define PI_KI                120.0f
#define PI_INTEGRAL_LIMIT    500.0f
#define PI_OUTPUT_LIMIT      1000.0f

/* 纹波抑制陷波器参数 (中心频率 100Hz, 采样 10kHz) */
#define NOTCH_FREQ_HZ        100.0f
#define NOTCH_BW_HZ          20.0f

/* 电流设定值 (A) */
#define CURRENT_SETPOINT_A   200.0f

#define PI_F               3.14159265358979323846f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float integral_limit;
    float output_limit;
    float prev_error;
} PI_Controller;

typedef struct {
    float b0;
    float b1;
    float b2;
    float a1;
    float a2;
    float x1;
    float x2;
    float y1;
    float y2;
} NotchFilter;

/* ================= 函数声明 ================= */
static void PI_Init(PI_Controller *pi, float kp, float ki, float ilim, float olim);
static float PI_Update(PI_Controller *pi, float setpoint, float feedback, float dt);
static void Notch_Init(NotchFilter *nf, float freq, float bw, float fs);
static float Notch_Update(NotchFilter *nf, float input);
static float Read_Current(void);
static float Read_Voltage(void);
static void Set_PWM_Duty(float duty);
static void Enable_PWM(uint8_t en);
static uint8_t Get_Fault(void);

/* ================= 函数实现 ================= */
static void PI_Init(PI_Controller *pi, float kp, float ki, float ilim, float olim)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->integral_limit = ilim;
    pi->output_limit = olim;
    pi->prev_error = 0.0f;
}

static float PI_Update(PI_Controller *pi, float setpoint, float feedback, float dt)
{
    float error = setpoint - feedback;
    float p_term = pi->kp * error;

    pi->integral += pi->ki * error * dt;
    if (pi->integral > pi->integral_limit) {
        pi->integral = pi->integral_limit;
    } else if (pi->integral < -pi->integral_limit) {
        pi->integral = -pi->integral_limit;
    }

    float output = p_term + pi->integral;
    if (output > pi->output_limit) {
        output = pi->output_limit;
    } else if (output < -pi->output_limit) {
        output = -pi->output_limit;
    }

    pi->prev_error = error;
    return output;
}

static void Notch_Init(NotchFilter *nf, float freq, float bw, float fs)
{
    float omega = 2.0f * PI_F * freq / fs;
    float sin_omega = sinf(omega);
    float cos_omega = cosf(omega);
    float alpha;

    if (sin_omega < 1e-6f) {
        sin_omega = 1e-6f;
    }

    alpha = sin_omega * sinhf(logf(2.0f) / 2.0f * bw / freq * omega / sin_omega);

    float a0 = 1.0f + alpha;
    if (a0 < 1e-6f) {
        a0 = 1e-6f;
    }

    nf->b0 = 1.0f / a0;
    nf->b1 = -2.0f * cos_omega / a0;
    nf->b2 = 1.0f / a0;
    nf->a1 = -2.0f * cos_omega / a0;
    nf->a2 = (1.0f - alpha) / a0;

    nf->x1 = 0.0f;
    nf->x2 = 0.0f;
    nf->y1 = 0.0f;
    nf->y2 = 0.0f;
}

static float Notch_Update(NotchFilter *nf, float input)
{
    float output = nf->b0 * input + nf->b1 * nf->x1 + nf->b2 * nf->x2
                   - nf->a1 * nf->y1 - nf->a2 * nf->y2;

    nf->x2 = nf->x1;
    nf->x1 = input;
    nf->y2 = nf->y1;
    nf->y1 = output;

    return output;
}

static float Read_Current(void)
{
    uint16_t adc = REG_ADC_CURRENT;
    float voltage = (float)adc / ADC_RESOLUTION * ADC_REF_VOLTAGE;
    return voltage / CURRENT_SENSOR_GAIN;
}

static float Read_Voltage(void)
{
    uint16_t adc = REG_ADC_VOLTAGE;
    return (float)adc / ADC_RESOLUTION * ADC_REF_VOLTAGE;
}

static void Set_PWM_Duty(float duty)
{
    if (duty < 0.0f) {
        duty = 0.0f;
    } else if (duty > (float)PWM_MAX_DUTY) {
        duty = (float)PWM_MAX_DUTY;
    }
    REG_PWM_DUTY = (uint16_t)duty;
}

static void Enable_PWM(uint8_t en)
{
    REG_PWM_ENABLE = en;
}

static uint8_t Get_Fault(void)
{
    return REG_FAULT_STATUS;
}

/* ================= 主函数 ================= */
int main(void)
{
    PI_Controller current_pi;
    NotchFilter ripple_notch;

    float current_fb;
    float current_fb_filtered;
    float duty;
    float voltage_fb;
    uint8_t fault;
    int step;

    PI_Init(&current_pi, PI_KP, PI_KI, PI_INTEGRAL_LIMIT, PI_OUTPUT_LIMIT);
    Notch_Init(&ripple_notch, NOTCH_FREQ_HZ, NOTCH_BW_HZ, CONTROL_FREQ_HZ);

    Enable_PWM(1);

    printf("=== Hydrogen Electrolyzer Current Control (CC + Ripple Suppression) ===\n");
    printf("Setpoint: %.1f A, Control Freq: %.0f Hz, Notch: %.0f Hz\n",
           CURRENT_SETPOINT_A, CONTROL_FREQ_HZ, NOTCH_FREQ_HZ);
    printf("Step | Current(A) | Filtered(A) | Voltage(V) | Duty | Fault\n");
    printf("-----+------------+-------------+------------+------+------\n");

    for (step = 0; step < 20; step++) {
        fault = Get_Fault();
        if (fault != 0) {
            Enable_PWM(0);
            printf("FAULT detected: 0x%02X, PWM disabled.\n", fault);
            break;
        }

        current_fb = Read_Current();
        voltage_fb = Read_Voltage();

        current_fb_filtered = Notch_Update(&ripple_notch, current_fb);

        duty = PI_Update(&current_pi, CURRENT_SETPOINT_A, current_fb_filtered, CONTROL_PERIOD_S);

        Set_PWM_Duty(duty);

        printf("%4d | %10.3f | %11.3f | %10.3f | %4.0f | 0x%02X\n",
               step, current_fb, current_fb_filtered, voltage_fb, duty, fault);
    }

    Enable_PWM(0);
    printf("Control loop finished. PWM disabled.\n");

    return 0;
}
