/* 计算从 start_time 到当前时刻经过的毫秒数（考虑计数器回绕） */
static unsigned int mock_get_elapsed_ms(unsigned int start_time)
{
    unsigned int now = mock_read_timer_count();
    unsigned int elapsed;

    if (now >= start_time) {
        elapsed = now - start_time;
    } else {
        /* 计数器回绕处理 */
        elapsed = (0xFFFFFFFFU - start_time) + now + 1U;
    }

    /* 将定时器计数转换为毫秒 */
    return (elapsed * 1000U) / MOCK_TIMER_FREQ_HZ;
}

