static unsigned int adc_to_current_ma(unsigned int adc_value)
{
    unsigned long long numerator;
    unsigned long long denominator;
    unsigned long long current_ma;

    numerator   = (unsigned long long)adc_value * MOCK_ADC_VREF_MV * 1000ULL;
    denominator = (unsigned long long)MOCK_ADC_RESOLUTION * MOCK_SHUNT_RESISTOR_MOHM * MOCK_CURRENT_GAIN;

    if (denominator == 0ULL) {
        return 0U;
    }

    current_ma = numerator / denominator;
    return (unsigned int)current_ma;
}

/* ==================== 保护器初始化 ==================== */
static void overcurrent_protector_init(overcurrent_protector_t *ocp)
{
    if (ocp == NULL) {
        return;
    }

    ocp->state      = PROTECT_STATE_IDLE;
    ocp->start_time = 0U;
    ocp->elapsed_ms = 0U;
    ocp->trip_flag  = false;

    MOCK_TRIP_OUTPUT_REG = TRIP_OUTPUT_INACTIVE;
}

