{
    if (ocp == NULL) {
        return;
    }

    ocp->state      = PROTECT_STATE_IDLE;
    ocp->start_time = 0U;
    ocp->elapsed_ms = 0U;
    ocp->trip_flag  = false;

    MOCK_TRIP_OUTPUT_REG = TRIP_OUTPUT_INACTIVE;
}

/* ==================== 过流保护核心更新函数 ==================== */
static void overcurrent_protector_update(overcurrent_protector_t *ocp, unsigned int current_ma)
{
    if (ocp == NULL) {
        return;
    }

    switch (ocp->state) {
    case PROTECT_STATE_IDLE:
        if (current_ma > OVERCURRENT_THRESHOLD_MA) {
            ocp->state      = PROTECT_STATE_TIMING;
            ocp->start_time = mock_read_timer_count();
            ocp->elapsed_ms = 0U;
            ocp->trip_flag  = false;
        }
        break;

    case PROTECT_STATE_TIMING:
        if (current_ma <= OVERCURRENT_THRESHOLD_MA) {
            ocp->state      = PROTECT_STATE_IDLE;
            ocp->start_time = 0U;
            ocp->elapsed_ms = 0U;
            ocp->trip_flag  = false;
            break;
        }

        ocp->elapsed_ms = mock_get_elapsed_ms(ocp->start_time);

        if (ocp->elapsed_ms >= OVERCURRENT_DELAY_MS) {
            ocp->state     = PROTECT_STATE_TRIPPED;
            ocp->trip_flag = true;
            MOCK_TRIP_OUTPUT_REG = TRIP_OUTPUT_ACTIVE;
        }
        break;

    case PROTECT_STATE_TRIPPED:
        MOCK_TRIP_OUTPUT_REG = TRIP_OUTPUT_ACTIVE;
        break;

    default:
        overcurrent_protector_reset(ocp);
        break;
    }
