#include <stdio.h>
#include <stdbool.h>

/* ========== Mock 寄存器与宏定义 ========== */
static unsigned int g_mock_adc_current = 0U;
static unsigned int g_mock_timer_count = 0U;
static unsigned int g_mock_protection_flag = 0U;

#define MOCK_REG_ADC_CURRENT      (g_mock_adc_current)
#define MOCK_REG_TIMER_COUNT      (g_mock_timer_count)
#define MOCK_REG_PROTECTION_FLAG  (g_mock_protection_flag)

#define CURRENT_THRESHOLD_MA      5000U
#define FIXED_DELAY_MS            100U
#define TIMER_TICK_MS             1U

/* ========== 过流保护状态机 ========== */
typedef enum {
    PROT_IDLE = 0,
    PROT_TIMING,
    PROT_TRIPPED
} ProtState_t;

typedef struct {
    ProtState_t state;
    unsigned int delay_counter;
    unsigned int trip_count;
    bool         output_trip;
} OverCurrentProt_t;

static OverCurrentProt_t g_prot = {
    PROT_IDLE,
    0U,
    0U,
    false
};

/* ========== 读取采样电流（mock） ========== */
static unsigned int ReadCurrent_mA(void)
{
    return MOCK_REG_ADC_CURRENT;
}

/* ========== 定时器节拍（mock） ========== */
static bool IsTimerTick(void)
{
    return (MOCK_REG_TIMER_COUNT != 0U);
}

/* ========== 过流保护（定时限，固定延时） ========== */
static void OverCurrentProtection_Update(void)
{
    unsigned int current = ReadCurrent_mA();

    switch (g_prot.state) {
        case PROT_IDLE:
            g_prot.delay_counter = 0;
            g_prot.output_trip = false;
            if (current > CURRENT_THRESHOLD_MA) {
                g_prot.state = PROT_TIMING;
                g_prot.delay_counter = 0;
            }
            break;

        case PROT_TIMING:
            if (current <= CURRENT_THRESHOLD_MA) {
                g_prot.state = PROT_IDLE;
                g_prot.delay_counter = 0;
                g_prot.output_trip = false;
            } else {
                if (IsTimerTick()) {
                    g_prot.delay_counter += TIMER_TICK_MS;
                }
                if (g_prot.delay_counter >= FIXED_DELAY_MS) {
                    g_prot.state = PROT_TRIPPED;
                    g_prot.output_trip = true;
                    g_prot.trip_count++;
                    MOCK_REG_PROTECTION_FLAG = 1U;
                }
            }
            break;

        case PROT_TRIPPED:
            g_prot.output_trip = true;
            if (current <= CURRENT_THRESHOLD_MA) {
                g_prot.state = PROT_IDLE;
                g_prot.delay_counter = 0;
                g_prot.output_trip = false;
                MOCK_REG_PROTECTION_FLAG = 0U;
            }
            break;

        default:
            g_prot.state = PROT_IDLE;
            break;
    }
}

/* ========== 测试辅助 ========== */
static void SetCurrent_mA(unsigned int mA)
{
    MOCK_REG_ADC_CURRENT = mA;
}

static void SetTimerTick(bool tick)
{
    MOCK_REG_TIMER_COUNT = tick ? 1U : 0U;
}

static const char *StateName(ProtState_t s)
{
    switch (s) {
        case PROT_IDLE:    return "IDLE";
        case PROT_TIMING:  return "TIMING";
        case PROT_TRIPPED: return "TRIPPED";
        default:           return "UNKNOWN";
    }
}

static void PrintStatus(const char *tag)
{
    printf("[%s] state=%-8s delay=%3u ms trip=%s count=%u\n",
           tag,
           StateName(g_prot.state),
           g_prot.delay_counter,
           g_prot.output_trip ? "ON" : "OFF",
           g_prot.trip_count);
}

/* ========== main ========== */
int main(void)
{
    int i;

    printf("===== Over-Current Protection (Definite Time) Test =====\n");
    printf("Threshold = %u mA, Fixed Delay = %u ms\n\n",
           CURRENT_THRESHOLD_MA, FIXED_DELAY_MS);

    /* 1. 正常电流，应保持 IDLE */
    SetCurrent_mA(1000U);
    SetTimerTick(true);
    OverCurrentProtection_Update();
    PrintStatus("Normal");

    /* 2. 过流出现，进入 TIMING */
    SetCurrent_mA(6000U);
    OverCurrentProtection_Update();
    PrintStatus("OverCurrent");

    /* 3. 延时未到，仍 TIMING */
    for (i = 0; i < 50; i++) {
        SetTimerTick(true);
        OverCurrentProtection_Update();
    }
    PrintStatus("Delay50ms");

    /* 4. 延时到达，跳闸 */
    for (i = 0; i < 60; i++) {
        SetTimerTick(true);
        OverCurrentProtection_Update();
    }
    PrintStatus("Trip");

    /* 5. 电流恢复，自动复位 */
    SetCurrent_mA(500U);
    OverCurrentProtection_Update();
    PrintStatus("Recover");

    /* 6. 再次过流，验证可重复触发 */
    SetCurrent_mA(7000U);
    OverCurrentProtection_Update();
    for (i = 0; i < 120; i++) {
        SetTimerTick(true);
        OverCurrentProtection_Update();
    }
    PrintStatus("Trip2");

    printf("\n===== Test Finished =====\n");
    return 0;
}
