#define MOCK_ADC_CR         (mock_adc_cr)
#define MOCK_ADC_SR         (mock_adc_sr)
#define MOCK_GPIO_ODR       (mock_gpio_odr)
#define MOCK_GPIO_IDR       (mock_gpio_idr)

/* 保护输出引脚位定义 */
#define OVP_OUTPUT_PIN      (1U << 5)

/* ADC 参考电压与分辨率 */
#define ADC_VREF_MV         3300U
#define ADC_FULL_SCALE      4095U

/* ---------- 过压保护参数配置 ---------- */
#define OVP_THRESHOLD_HIGH  2800U   /* 上限：超过此值触发保护 */
#define OVP_THRESHOLD_LOW   2600U   /* 下限：低于此值解除保护 */

/* 防误触发：连续采样确认次数 */
#define OVP_CONFIRM_COUNT   3U

/* ---------- 过压保护状态机 ---------- */
typedef enum {
    OVP_STATE_NORMAL = 0,
    OVP_STATE_WARNING,
    OVP_STATE_PROTECTED,
    OVP_STATE_RECOVERING
} ovp_state_t;

typedef struct {
    ovp_state_t state;
    uint32_t    confirm_cnt;
    uint32_t    voltage_mv;
    uint32_t    trip_count;
    uint32_t    recover_count;
} ovp_ctrl_t;

/* ---------- 函数声明 ---------- */
static void     ovp_init(ovp_ctrl_t *ovp);
static uint32_t adc_read_voltage_mv(void);
static void     ovp_set_output(bool enable);
static void     ovp_process(ovp_ctrl_t *ovp, uint32_t voltage_mv);
static const char *ovp_state_str(ovp_state_t state);

/* ============================================================
 * 初始化过压保护控制器
 * ============================================================ */
static void ovp_init(ovp_ctrl_t *ovp)
{
    ovp->state         = OVP_STATE_NORMAL;
    ovp->confirm_cnt   = 0U;
    ovp->voltage_mv    = 0U;
    ovp->trip_count    = 0U;
    ovp->recover_count = 0U;

    MOCK_ADC_CR = 0x00000001U;
    MOCK_ADC_SR = 0x00000000U;
    MOCK_GPIO_ODR &= ~OVP_OUTPUT_PIN;
}

/* ============================================================
 * 读取 ADC 电压值（模拟）
 * ============================================================ */
static uint32_t adc_read_voltage_mv(void)
{
    uint32_t raw;

    MOCK_ADC_SR |= 0x00000002U;
    raw = MOCK_ADC_DR & 0x00000FFFU;

    return (raw * ADC_VREF_MV) / ADC_FULL_SCALE;
}

/* ============================================================
 * 设置保护输出（模拟 GPIO 控制）
 * ============================================================ */
static void ovp_set_output(bool enable)
{
    if (enable) {
        MOCK_GPIO_ODR |= OVP_OUTPUT_PIN;
    } else {
        MOCK_GPIO_ODR &= ~OVP_OUTPUT_PIN;
    }
}

/* ============================================================
 * 过压保护核心处理（滞回比较 + 防误触发）
 * ============================================================ */
static void ovp_process(ovp_ctrl_t *ovp, uint32_t voltage_mv)
{
    ovp->voltage_mv = voltage_mv;

    switch (ovp->state) {
    case OVP_STATE_NORMAL:
        if (voltage_mv > OVP_THRESHOLD_HIGH) {
            ovp->confirm_cnt++;
            if (ovp->confirm_cnt >= OVP_CONFIRM_COUNT) {
                ovp->state       = OVP_STATE_PROTECTED;
                ovp->confirm_cnt = 0U;
                ovp->trip_count++;
                ovp_set_output(true);
                printf("[OVP] >>> 过压保护触发！电压=%u mV，累计触发=%u 次\n",
                       voltage_mv, ovp->trip_count);
            } else {
                ovp->state = OVP_STATE_WARNING;
            }
        } else {
            ovp->confirm_cnt = 0U;
        }
        break;

    case OVP_STATE_WARNING:
        if (voltage_mv > OVP_THRESHOLD_HIGH) {
            ovp->confirm_cnt++;
            if (ovp->confirm_cnt >= OVP_CONFIRM_COUNT) {
                ovp->state       = OVP_STATE_PROTECTED;
                ovp->confirm_cnt = 0U;
                ovp->trip_count++;
                ovp_set_output(true);
                printf("[OVP] >>> 过压保护触发！电压=%u mV，累计触发=%u 次\n",
                       voltage_mv, ovp->trip_count);
            }
        } else {
            ovp->confirm_cnt = 0U;
            ovp->state       = OVP_STATE_NORMAL;
        }
        break;

    case OVP_STATE_PROTECTED:
        if (voltage_mv < OVP_THRESHOLD_LOW) {
            ovp->confirm_cnt++;
            if (ovp->confirm_cnt >= OVP_CONFIRM_COUNT) {
                ovp->state       = OVP_STATE_NORMAL;
                ovp->confirm_cnt = 0U;
                ovp->recover_count++;
                ovp_set_output(false);
                printf("[OVP] <<< 过压保护解除。电压=%u mV，累计恢复=%u 次\n",
                       voltage_mv, ovp->recover_count);
            } else {
                ovp->state = OVP_STATE_RECOVERING;
            }
        } else {
            ovp->confirm_cnt = 0U;
        }
        break;

    case OVP_STATE_RECOVERING:
        if (voltage_mv < OVP_THRESHOLD_LOW) {
            ovp->confirm_cnt++;
            if (ovp->confirm_cnt >= OVP_CONFIRM_COUNT) {
                ovp->state       = OVP_STATE_NORMAL;
                ovp->confirm_cnt = 0U;
                ovp->recover_count++;
                ovp_set_output(false);
                printf("[OVP] <<< 过压保护解除。电压=%u mV，累计恢复=%u 次\n",
                       voltage_mv, ovp->recover_count);
            }
        } else {
            ovp->confirm_cnt = 0U;
            ovp->state       = OVP_STATE_PROTECTED;
        }
        break;

    default:
        ovp->state = OVP_STATE_NORMAL;
        break;
    }
}

/* ============================================================
 * 状态字符串（用于打印）
 * ============================================================ */
static const char *ovp_state_str(ovp_state_t state)
{
    switch (state) {
    case OVP_STATE_NORMAL:     return "NORMAL";
    case OVP_STATE_WARNING:    return "WARNING";
    case OVP_STATE_PROTECTED:  return "PROTECTED";
    case OVP_STATE_RECOVERING: return "RECOVERING";
    default:                   return "UNKNOWN";
    }
}

/* ============================================================
 * 主函数：模拟测试
 * ============================================================ */
int main(void)
{
    ovp_ctrl_t ovp;
    uint32_t   test_voltages[] = {
        2500U, 2650U, 2700U, 2750U, 2850U, 2900U, 2950U,
        2800U, 2750U, 2700U, 2650U, 2550U, 2500U, 2450U,
        2600U, 2700U, 2850U, 2900U, 2950U, 3000U,
        2700U, 2650U, 2600U, 2550U, 2500U, 2450U, 2400U
    };
    uint32_t   i;
    uint32_t   n;

    printf("========================================\n");
    printf("  过压保护（滞回比较，防误触发）测试\n");
    printf("  上限阈值: %u mV\n", OVP_THRESHOLD_HIGH);
    printf("  下限阈值: %u mV\n", OVP_THRESHOLD_LOW);
    printf("  确认次数: %u\n", OVP_CONFIRM_COUNT);
    printf("========================================\n\n");

    ovp_init(&ovp);

    n = (uint32_t)(sizeof(test_voltages) / sizeof(test_voltages[0]));

    for (i = 0U; i < n; i++) {
