        printf("  [%02u] 电压=%4u mV | 状态=%-10s | 输出=%s\n",
               i + 1U,
               v,
               ovp_state_str(ovp.state),
               (MOCK_GPIO_ODR & OVP_OUTPUT_PIN) ? "ON " : "OFF");
    }

    printf("\n========================================\n");
    printf("  测试结束\n");
    printf("  累计触发次数: %u\n", ovp.trip_count);
    printf("  累计恢复次数: %u\n", ovp.recover_count);
    printf("========================================\n");

    return 0;
}
