/* ================= Mock 硬件寄存器与宏定义 ================= */
/* 使用普通变量模拟寄存器，避免直接访问非法地址导致崩溃 */
static volatile uint16_t mock_adc_data = 0U;
static volatile uint8_t  mock_protect_out = 0U;

#define MOCK_ADC_DATA_REG       (mock_adc_data)
#define MOCK_PROTECT_OUT_REG    (mock_protect_out)

/* 过压保护阈值（滞回比较） */
#define OVP_THRESHOLD_HIGH      2500U   /* 过压触发阈值：ADC 值 >= 2500 时触发保护 */
#define OVP_THRESHOLD_LOW       2300U   /* 过压恢复阈值：ADC 值 <= 2300 时解除保护 */

/* 保护输出状态定义 */
#define PROTECT_ACTIVE          1U
#define PROTECT_INACTIVE        0U

/* ================= 过压保护状态机 ================= */
typedef enum {
    OVP_STATE_NORMAL = 0,       /* 正常状态，未触发保护 */
    OVP_STATE_PROTECTED         /* 保护状态，已触发过压保护 */
} OvpState_t;

typedef struct {
    OvpState_t state;           /* 当前保护状态 */
    uint16_t   adcValue;        /* 当前 ADC 采样值 */
    uint8_t    protectOutput;   /* 保护输出（0=不动作，1=动作） */
} OvpContext_t;

/* 初始化过压保护上下文 */
static void Ovp_Init(OvpContext_t *ctx)
{
    if (ctx == NULL) {
        return;
    }
    ctx->state = OVP_STATE_NORMAL;
    ctx->adcValue = 0U;
    ctx->protectOutput = PROTECT_INACTIVE;
    MOCK_PROTECT_OUT_REG = PROTECT_INACTIVE;
}

/* 读取 ADC 采样值（模拟硬件读取） */
static uint16_t Ovp_ReadAdc(void)
{
    return MOCK_ADC_DATA_REG;
}

/* 设置保护输出（模拟硬件写寄存器） */
static void Ovp_SetOutput(uint8_t output)
{
    MOCK_PROTECT_OUT_REG = output;
}

/* 过压保护核心算法：滞回比较，防误触发 */
static void Ovp_Process(OvpContext_t *ctx)
{
    if (ctx == NULL) {
        return;
    }

    /* 1. 读取当前 ADC 采样值 */
    ctx->adcValue = Ovp_ReadAdc();

    /* 2. 滞回比较状态机 */
    switch (ctx->state) {
        case OVP_STATE_NORMAL:
            /* 正常状态下，仅当 ADC 值 >= 高阈值时触发保护 */
            if (ctx->adcValue >= OVP_THRESHOLD_HIGH) {
                ctx->state = OVP_STATE_PROTECTED;
                ctx->protectOutput = PROTECT_ACTIVE;
                Ovp_SetOutput(PROTECT_ACTIVE);
            } else {
                ctx->protectOutput = PROTECT_INACTIVE;
                Ovp_SetOutput(PROTECT_INACTIVE);
            }
            break;

        case OVP_STATE_PROTECTED:
            /* 保护状态下，仅当 ADC 值 <= 低阈值时解除保护 */
            if (ctx->adcValue <= OVP_THRESHOLD_LOW) {
                ctx->state = OVP_STATE_NORMAL;
                ctx->protectOutput = PROTECT_INACTIVE;
                Ovp_SetOutput(PROTECT_INACTIVE);
            } else {
                ctx->protectOutput = PROTECT_ACTIVE;
                Ovp_SetOutput(PROTECT_ACTIVE);
            }
            break;

        default:
            /* 异常状态恢复为正常状态 */
            ctx->state = OVP_STATE_NORMAL;
            ctx->protectOutput = PROTECT_INACTIVE;
            Ovp_SetOutput(PROTECT_INACTIVE);
            break;
    }
}

/* ================= 测试辅助函数 ================= */
static void Ovp_PrintStatus(const OvpContext_t *ctx, const char *tag)
{
    if (ctx == NULL) {
        return;
    }
    printf("[%s] ADC=%4u, State=%s, Output=%s\n",
           tag,
           (unsigned int)ctx->adcValue,
           (ctx->state == OVP_STATE_NORMAL) ? "NORMAL" : "PROTECTED",
           (ctx->protectOutput == PROTECT_ACTIVE) ? "ACTIVE" : "INACTIVE");
}

/* ================= main 函数 ================= */
int main(void)
{
    OvpContext_t ovpCtx;

    printf("===== Over-Voltage Protection (Hysteresis) Test =====\n");
    printf("High Threshold = %u, Low Threshold = %u\n\n",
           (unsigned int)OVP_THRESHOLD_HIGH, (unsigned int)OVP_THRESHOLD_LOW);

    /* 初始化 */
    Ovp_Init(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Init");

    /* 测试 1：ADC 值低于高阈值，应保持正常 */
    MOCK_ADC_DATA_REG = 2000U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test1: ADC=2000 (< High)");

    /* 测试 2：ADC 值达到高阈值，应触发保护 */
    MOCK_ADC_DATA_REG = 2500U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test2: ADC=2500 (>= High)");

    /* 测试 3：ADC 值略低于高阈值但高于低阈值，应保持保护（滞回） */
    MOCK_ADC_DATA_REG = 2400U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test3: ADC=2400 (Hysteresis)");

    /* 测试 4：ADC 值继续下降但高于低阈值，应保持保护 */
    MOCK_ADC_DATA_REG = 2350U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test4: ADC=2350 (Hysteresis)");

    /* 测试 5：ADC 值降至低阈值，应解除保护 */
    MOCK_ADC_DATA_REG = 2300U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test5: ADC=2300 (<= Low)");

    /* 测试 6：ADC 值再次升高但未达高阈值，应保持正常（防误触发） */
    MOCK_ADC_DATA_REG = 2450U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test6: ADC=2450 (< High)");

    /* 测试 7：ADC 值再次达到高阈值，应重新触发保护 */
    MOCK_ADC_DATA_REG = 2600U;
    Ovp_Process(&ovpCtx);
    Ovp_PrintStatus(&ovpCtx, "Test7: ADC=2600 (>= High)");

    printf("\n===== Test Finished =====\n");
    return 0;
