#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== Mock 寄存器定义 ==================== */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static uint32_t mock_gpio_odr = 0U;
static uint32_t mock_gpio_idr = 0U;
static uint32_t mock_tim_cr1  = 0U;
static uint32_t mock_tim_sr   = 0U;
static uint32_t mock_tim_cnt  = 0U;
static uint32_t mock_adc_dr   = 0U;
static uint32_t mock_adc_sr   = 0U;
static uint32_t mock_exti_imr = 0U;
static uint32_t mock_exti_pr  = 0U;
static uint32_t mock_nvic_iser = 0U;

#define GPIO_ODR    (mock_gpio_odr)
#define GPIO_IDR    (mock_gpio_idr)
#define TIM_CR1     (mock_tim_cr1)
#define TIM_SR      (mock_tim_sr)
#define TIM_CNT     (mock_tim_cnt)
#define ADC_DR      (mock_adc_dr)
#define ADC_SR      (mock_adc_sr)
#define EXTI_IMR    (mock_exti_imr)
#define EXTI_PR     (mock_exti_pr)
#define NVIC_ISER   (mock_nvic_iser)

/* 模拟的位定义 */
#define GPIO_PIN_0      (1U << 0)
#define GPIO_PIN_1      (1U << 1)
#define GPIO_PIN_2      (1U << 2)
#define GPIO_PIN_3      (1U << 3)

#define TIM_SR_UIF      (1U << 0)
#define TIM_CR1_CEN     (1U << 0)

#define ADC_SR_EOC      (1U << 1)

#define EXTI_IMR_MR0    (1U << 0)
#define EXTI_PR_PR0     (1U << 0)

/* ==================== 系统参数 ==================== */
#define PWM_FREQ_HZ             20000U
#define PWM_PERIOD_TICKS        1000U
#define SHORT_CIRCUIT_THRESHOLD 800U
#define CONFIRM_COUNT           3U
#define CONFIRM_WINDOW_US       10U

/* ==================== 全局状态 ==================== */
typedef enum {
    STATE_NORMAL = 0,
    STATE_FAULT_DETECTED,
    STATE_SHUTDOWN,
    STATE_RECOVERY
} system_state_t;

typedef struct {
    system_state_t state;
    uint32_t fault_count;
    uint32_t confirm_counter;
    uint32_t last_fault_time;
    bool     pwm_enabled;
    bool     hardware_trip;
    uint32_t adc_value;
    uint32_t recovery_timer;
} protection_ctx_t;

static protection_ctx_t g_prot = {
    STATE_NORMAL, 0U, 0U, 0U, true, false, 0U, 0U
};

/* ==================== 硬件抽象层 (Mock) ==================== */

static void hw_pwm_enable(void)
{
    GPIO_ODR |= GPIO_PIN_0;
    g_prot.pwm_enabled = true;
    printf("[HW] PWM enabled\n");
}

static void hw_pwm_fast_disable(void)
{
    GPIO_ODR &= ~GPIO_PIN_0;
    g_prot.pwm_enabled = false;
    printf("[HW] PWM FAST DISABLED (hardware trip)\n");
}

static uint32_t hw_adc_read_current(void)
{
    static uint32_t mock_adc = 100U;
    mock_adc += 50U;
    if (mock_adc > 1200U) {
        mock_adc = 100U;
    }
    return mock_adc;
}

static void hw_clear_fault(void)
{
    EXTI_PR = EXTI_PR_PR0;
    g_prot.hardware_trip = false;
    printf("[HW] Fault flag cleared\n");
}

static uint32_t hw_get_time_us(void)
{
    static uint32_t mock_time = 0U;
    mock_time += 100U;
    return mock_time;
}

/* ==================== 中断服务程序 (ISR) ==================== */

void EXTI0_IRQHandler(void)
{
    if (EXTI_PR & EXTI_PR_PR0) {
        hw_pwm_fast_disable();
        g_prot.hardware_trip = true;
        g_prot.last_fault_time = hw_get_time_us();
        g_prot.state = STATE_FAULT_DETECTED;
        EXTI_PR = EXTI_PR_PR0;
        printf("[ISR] Hardware short circuit interrupt! PWM tripped.\n");
    }
}

/* ==================== 软件保护逻辑 ==================== */

static bool software_confirm_short_circuit(void)
{
    uint32_t confirm_count = 0U;
    uint32_t start_time = hw_get_time_us();
    uint32_t current_time;
    uint32_t loop_guard = 0U;

    printf("[SW] Starting software confirmation...\n");

    while (confirm_count < CONFIRM_COUNT) {
        current_time = hw_get_time_us();

        if ((current_time - start_time) > CONFIRM_WINDOW_US) {
            printf("[SW] Confirmation window timeout\n");
            break;
        }

        g_prot.adc_value = hw_adc_read_current();

        if (g_prot.adc_value > SHORT_CIRCUIT_THRESHOLD) {
            confirm_count++;
            printf("[SW] Over-current sample %lu: ADC=%lu\n",
                   (unsigned long)confirm_count,
                   (unsigned long)g_prot.adc_value);
        } else {
            confirm_count = 0U;
            printf("[SW] Sample below threshold: ADC=%lu\n",
                   (unsigned long)g_prot.adc_value);
        }

        /* 防止死循环 */
        loop_guard++;
        if (loop_guard > 1000U) {
            printf("[SW] Loop guard triggered, aborting confirmation\n");
            break;
        }
    }

    if (confirm_count >= CONFIRM_COUNT) {
        printf("[SW] Short circuit CONFIRMED!\n");
        return true;
    }

    printf("[SW] Short circuit NOT confirmed (false alarm)\n");
    return false;
}

static void execute_shutdown(void)
{
    printf("[PROT] Executing shutdown sequence...\n");

    if (g_prot.pwm_enabled) {
        hw_pwm_fast_disable();
    }

    g_prot.state = STATE_SHUTDOWN;
    g_prot.fault_count++;

    printf("[PROT] System SHUTDOWN. Total faults: %lu\n",
           (unsigned long)g_prot.fault_count);
}

static void handle_recovery(void)
{
    printf("[PROT] Attempting recovery...\n");

    hw_clear_fault();
    g_prot.confirm_counter = 0U;
    hw_pwm_enable();
    g_prot.state = STATE_NORMAL;

    printf("[PROT] Recovery complete. System back to NORMAL.\n");
}

/* ==================== 主控制循环 ==================== */

static void short_circuit_protection_task(void)
{
    switch (g_prot.state) {
        case STATE_NORMAL:
            g_prot.adc_value = hw_adc_read_current();

            if (g_prot.adc_value > SHORT_CIRCUIT_THRESHOLD) {
                g_prot.confirm_counter++;
                if (g_prot.confirm_counter >= CONFIRM_COUNT) {
                    printf("[PROT] Software over-current detected! ADC=%lu\n",
                           (unsigned long)g_prot.adc_value);
                    g_prot.state = STATE_FAULT_DETECTED;
                    g_prot.confirm_counter = 0U;
                }
            } else {
                g_prot.confirm_counter = 0U;
            }
            break;

        case STATE_FAULT_DETECTED:
            if (software_confirm_short_circuit()) {
                execute_shutdown();
            } else {
                printf("[PROT] False alarm, recovering...\n");
                handle_recovery();
            }
            break;

        case STATE_SHUTDOWN:
            g_prot.recovery_timer++;
            if (g_prot.recovery_timer > 5U) {
                g_prot.recovery_timer = 0U;
                handle_recovery();
            }
            break;

        case STATE_RECOVERY:
            g_prot.state = STATE_NORMAL;
            break;

        default:
            g_prot.state = STATE_NORMAL;
            break;
    }
}

/* ==================== 初始化 ==================== */

static void protection_init(void)
{
    printf("=== Short Circuit Protection System Init ===\n");

    EXTI_IMR |= EXTI_IMR_MR0;
    NVIC_ISER |= (1U << 6);

    hw_pwm_enable();

    g_prot.state = STATE_NORMAL;
    g_prot.fault_count = 0U;
    g_prot.confirm_counter = 0U;
    g_prot.hardware_trip = false;
    g_prot.recovery_timer = 0U;

    printf("=== Init Complete ===\n\n");
}

/* ==================== 主函数 ==================== */

int main(void)
{
    uint32_t loop_count = 0U;

    printf("Short Circuit Protection Demo\n");
    printf("==============================\n\n");

    protection_init();

    while (loop_count < 20U) {
        printf("--- Loop %lu ---\n", (unsigned long)loop_count);

        if (loop_count == 5U) {
            printf("[SIM] Simulating hardware short circuit trigger...\n");
            EXTI0_IRQHandler();
        }

        if (loop_count == 12U) {
            printf("[SIM] Simulating another hardware trigger...\n");
            EXTI0_IRQHandler();
        }

        short_circuit_protection_task();

        printf("[STATUS] State=%d, PWM=%s, ADC=%lu, Faults=%lu\n\n",
               (int)g_prot.state,
               g_prot.pwm_enabled ? "ON" : "OFF",
               (unsigned long)g_prot.adc_value,
               (unsigned long)g_prot.fault_count);

        loop_count++;
    }

    printf("==============================\n");
    printf("Demo Complete. Total faults: %lu\n",
           (unsigned long)g_prot.fault_count);

    return 0;
}
