#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * ============================================================ */

/* 使用普通变量模拟寄存器，避免非法地址访问导致崩溃 */
static volatile uint32_t g_gpio_moder = 0;
static volatile uint32_t g_gpio_odr   = 0;
static volatile uint32_t g_gpio_idr   = 0;

static volatile uint32_t g_tim1_cr1   = 0;
static volatile uint32_t g_tim1_sr    = 0;
static volatile uint32_t g_tim1_ccer  = 0;
static volatile uint32_t g_tim1_bdtr  = 0;

static volatile uint32_t g_exti_imr   = 0;
static volatile uint32_t g_exti_pr    = 0;

static volatile uint32_t g_nvic_iser0 = 0;
static volatile uint32_t g_nvic_icpr0 = 0;

static volatile uint32_t g_adc1_dr    = 0;
static volatile uint32_t g_adc1_cr2   = 0;

/* 寄存器访问宏 */
#define GPIOA_MODER         (g_gpio_moder)
#define GPIOA_ODR           (g_gpio_odr)
#define GPIOA_IDR           (g_gpio_idr)

#define TIM1_CR1            (g_tim1_cr1)
#define TIM1_SR             (g_tim1_sr)
#define TIM1_CCER           (g_tim1_ccer)
#define TIM1_BDTR           (g_tim1_bdtr)

#define EXTI_IMR            (g_exti_imr)
#define EXTI_PR             (g_exti_pr)

#define NVIC_ISER0          (g_nvic_iser0)
#define NVIC_ICPR0          (g_nvic_icpr0)

#define ADC1_DR             (g_adc1_dr)
#define ADC1_CR2            (g_adc1_cr2)

/* 位定义 */
#define TIM1_CR1_CEN        (1U << 0)
#define TIM1_BDTR_MOE       (1U << 15)
#define TIM1_CCER_CC1E      (1U << 0)
#define TIM1_CCER_CC1NE     (1U << 2)
#define TIM1_SR_UIF         (1U << 0)
#define EXTI_IMR_MR0        (1U << 0)
#define EXTI_PR_PR0         (1U << 0)
#define NVIC_ISER0_SETENA0  (1U << 0)
#define ADC1_CR2_ADON       (1U << 0)
#define ADC1_CR2_SWSTART    (1U << 30)

/* 短路保护相关宏 */
#define SHORT_CIRCUIT_THRESHOLD_ADC     3500U
#define SHORT_CIRCUIT_CONFIRM_COUNT     3U
#define SHORT_CIRCUIT_CONFIRM_WINDOW_MS 2U

/* 系统状态枚举 */
typedef enum {
    SYS_STATE_NORMAL = 0,
    SYS_STATE_FAULT_PENDING,
    SYS_STATE_SHORT_CIRCUIT,
    SYS_STATE_RECOVERY
} SystemState_t;

/* 短路保护上下文结构体 */
typedef struct {
    volatile SystemState_t state;
    volatile uint32_t      fault_counter;
    volatile uint32_t      fault_timestamp;
    volatile bool          hardware_trip_flag;
    volatile bool          software_confirm_flag;
    volatile uint32_t      trip_count;
    volatile uint32_t      recovery_delay_ms;
} ShortCircuitProtect_t;

static ShortCircuitProtect_t g_scp = {
    SYS_STATE_NORMAL,
    0,
    0,
    false,
    false,
    0,
    100
};

/* 模拟系统滴答计数器 */
static volatile uint32_t g_systick_ms = 0;

/* ============================================================
 * 硬件抽象层函数
 * ============================================================ */

static void HAL_GPIO_Init(void)
{
    GPIOA_MODER &= ~(3U << 0);
    GPIOA_MODER |=  (0U << 0);
    GPIOA_MODER &= ~(3U << 2);
    GPIOA_MODER |=  (1U << 2);
    GPIOA_ODR &= ~(1U << 1);
}

static void HAL_TIM1_Init(void)
{
    TIM1_CR1 = 0;
    TIM1_CCER = 0;
    TIM1_BDTR = 0;
}

static void HAL_TIM1_EnablePWM(void)
{
    TIM1_BDTR |= TIM1_BDTR_MOE;
    TIM1_CCER |= (TIM1_CCER_CC1E | TIM1_CCER_CC1NE);
    TIM1_CR1  |= TIM1_CR1_CEN;
    GPIOA_ODR |= (1U << 1);
}

static void HAL_TIM1_DisablePWM(void)
{
    TIM1_CR1  &= ~TIM1_CR1_CEN;
    TIM1_CCER &= ~(TIM1_CCER_CC1E | TIM1_CCER_CC1NE);
    TIM1_BDTR &= ~TIM1_BDTR_MOE;
    GPIOA_ODR &= ~(1U << 1);
}

static void HAL_EXTI0_Init(void)
{
    EXTI_IMR |= EXTI_IMR_MR0;
    NVIC_ISER0 |= NVIC_ISER0_SETENA0;
}

static void HAL_ADC_Init(void)
{
    ADC1_CR2 |= ADC1_CR2_ADON;
}

static uint32_t HAL_ADC_ReadCurrent(void)
{
    ADC1_CR2 |= ADC1_CR2_SWSTART;
    return ADC1_DR;
}

static uint32_t HAL_GetTick(void)
{
    return g_systick_ms;
}

static void HAL_SysTick_Inc(void)
{
    g_systick_ms++;
}

/* ============================================================
 * 短路保护核心逻辑
 * ============================================================ */

void EXTI0_IRQHandler(void)
{
    if (EXTI_PR & EXTI_PR_PR0) {
        HAL_TIM1_DisablePWM();
        g_scp.hardware_trip_flag = true;
        g_scp.fault_timestamp = HAL_GetTick();
        g_scp.state = SYS_STATE_FAULT_PENDING;
        EXTI_PR |= EXTI_PR_PR0;
    }
}

static bool SCP_SoftwareConfirm(void)
{
    uint32_t confirm_count = 0;
    uint32_t start_time = HAL_GetTick();

    while ((HAL_GetTick() - start_time) < SHORT_CIRCUIT_CONFIRM_WINDOW_MS) {
        uint32_t adc_val = HAL_ADC_ReadCurrent();
        if (adc_val >= SHORT_CIRCUIT_THRESHOLD_ADC) {
            confirm_count++;
            if (confirm_count >= SHORT_CIRCUIT_CONFIRM_COUNT) {
                return true;
            }
        } else {
            confirm_count = 0;
        }
        /* 推进时间，避免死循环 */
        HAL_SysTick_Inc();
    }
    return false;
}

static void SCP_Process(void)
{
    switch (g_scp.state) {
        case SYS_STATE_NORMAL:
            HAL_TIM1_EnablePWM();
            g_scp.hardware_trip_flag = false;
            g_scp.software_confirm_flag = false;
            g_scp.fault_counter = 0;
            break;

        case SYS_STATE_FAULT_PENDING:
            if (SCP_SoftwareConfirm()) {
                g_scp.software_confirm_flag = true;
                g_scp.state = SYS_STATE_SHORT_CIRCUIT;
                g_scp.trip_count++;
                printf("[SCP] Short circuit CONFIRMED! Trip count: %u\n",
                       (unsigned int)g_scp.trip_count);
            } else {
                printf("[SCP] False alarm, recovering...\n");
                g_scp.state = SYS_STATE_RECOVERY;
            }
            break;

        case SYS_STATE_SHORT_CIRCUIT:
            HAL_TIM1_DisablePWM();
            if ((HAL_GetTick() - g_scp.fault_timestamp) >= g_scp.recovery_delay_ms) {
                g_scp.state = SYS_STATE_RECOVERY;
                printf("[SCP] Recovery delay elapsed, attempting restart...\n");
            }
            break;

        case SYS_STATE_RECOVERY:
            HAL_TIM1_EnablePWM();
            g_scp.state = SYS_STATE_NORMAL;
            g_scp.hardware_trip_flag = false;
            g_scp.software_confirm_flag = false;
            printf("[SCP] System recovered to NORMAL state.\n");
            break;

        default:
            g_scp.state = SYS_STATE_NORMAL;
            break;
    }
}

/* ============================================================
 * 测试辅助函数
 * ============================================================ */

static void SimulateShortCircuit(void)
{
    printf("\n>>> Simulating short circuit event <<<\n");
    EXTI_PR |= EXTI_PR_PR0;
    EXTI0_IRQHandler();
}

static void SimulateADCValue(uint32_t value)
{
    ADC1_DR = value;
}

static void SimulateTickAdvance(uint32_t ms)
{
    uint32_t i;
    for (i = 0; i < ms; i++) {
        HAL_SysTick_Inc();
    }
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    int i;

    printf("========================================\n");
    printf("  Short Circuit Protection Demo\n");
    printf("  (Hardware Interrupt + Software Confirm)\n");
    printf("========================================\n\n");

    HAL_GPIO_Init();
    HAL_TIM1_Init();
    HAL_EXTI0_Init();
    HAL_ADC_Init();

    g_scp.state = SYS_STATE_NORMAL;
    SCP_Process();
    printf("[INIT] System initialized, PWM enabled.\n");
    printf("[INIT] State: NORMAL\n\n");

    /* ---- 测试场景 1：真实短路事件 ---- */
    printf("--- Test 1: Real short circuit ---\n");
    SimulateADCValue(SHORT_CIRCUIT_THRESHOLD_ADC + 500U);
    SimulateShortCircuit();
    printf("[TEST] Hardware trip flag: %s\n",
           g_scp.hardware_trip_flag ? "SET" : "CLEAR");
    printf("[TEST] State after HW trip: %d (FAULT_PENDING)\n", (int)g_scp.state);

    SimulateTickAdvance(SHORT_CIRCUIT_CONFIRM_WINDOW_MS + 1U);
    SCP_Process();
    printf("[TEST] State after SW confirm: %d (SHORT_CIRCUIT)\n", (int)g_scp.state);
    printf("[TEST] Software confirm flag: %s\n",
           g_scp.software_confirm_flag ? "SET" : "CLEAR");

    SimulateTickAdvance(g_scp.recovery_delay_ms + 1U);
    SCP_Process();
    printf("[TEST] State after recovery: %d (NORMAL)\n", (int)g_scp.state);
    printf("[TEST] Trip count: %u\n\n", (unsigned int)g_scp.trip_count);

    /* ---- 测试场景 2：干扰导致的误触发 ---- */
    printf("--- Test 2: False alarm (noise) ---\n");
    SimulateADCValue(1000U);
    SimulateShortCircuit();
    printf("[TEST] Hardware trip flag: %s\n",
           g_scp.hardware_trip_flag ? "SET" : "CLEAR");

    SimulateTickAdvance(SHORT_CIRCUIT_CONFIRM_WINDOW_MS + 1U);
    SCP_Process();
    printf("[TEST] State after SW confirm: %d (RECOVERY)\n", (int)g_scp.state);

    SimulateTickAdvance(1U);
    SCP_Process();
    printf("[TEST] State after recovery: %d (NORMAL)\n", (int)g_scp.state);
    printf("[TEST] Trip count: %u\n\n", (unsigned int)g_scp.trip_count);

    /* ---- 测试场景 3：连续多次短路 ---- */
    printf("--- Test 3: Multiple short circuits ---\n");
    for (i = 0; i < 3; i++) {
        printf("\n[TEST] Short circuit #%d\n", i + 1);
        SimulateADCValue(SHORT_CIRCUIT_THRESHOLD_ADC + 1000U);
        SimulateShortCircuit();
        SimulateTickAdvance(SHORT_CIRCUIT_CONFIRM_WINDOW_MS + 1U);
        SCP_Process();
        SimulateTickAdvance(g_scp.recovery_delay_ms + 1U);
        SCP_Process();
    }
    printf("\n[TEST] Total trip count: %u\n", (unsigned int)g_scp.trip_count);

    printf("\n========================================\n");
    printf("  Demo completed successfully.\n");
    printf("========================================\n");

    return 0;
}
