#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static volatile uint16_t g_igbt_temp_reg = 0;
static volatile uint16_t g_igbt_current_reg = 0;
static volatile uint16_t g_pwm_freq_reg = 0;
static volatile uint16_t g_pwm_duty_reg = 0;

#define IGBT_TEMP_REG       (g_igbt_temp_reg)
#define IGBT_CURRENT_REG    (g_igbt_current_reg)
#define PWM_FREQ_REG        (g_pwm_freq_reg)
#define PWM_DUTY_REG        (g_pwm_duty_reg)

#define IGBT_TEMP_ADC_TO_C(adc)     ((float)(adc) * 0.5f)
#define IGBT_CURRENT_ADC_TO_A(adc)  ((float)(adc) * 0.1f)

/* ================= 参数定义 ================= */
#define IGBT_TJ_WARNING_C       125.0f
#define IGBT_TJ_SHUTDOWN_C      150.0f
#define IGBT_TJ_RECOVER_C       110.0f

#define PWM_FREQ_NORMAL_HZ      10000U
#define PWM_FREQ_REDUCED_HZ     5000U
#define PWM_FREQ_MIN_HZ         2000U

#define THERMAL_R_THETA_JC      0.5f
#define THERMAL_R_THETA_CA      1.5f
#define THERMAL_TAU_S           0.5f
#define CONTROL_PERIOD_S        0.001f

/* ================= 状态定义 ================= */
typedef enum {
    IGBT_STATE_NORMAL = 0,
    IGBT_STATE_DERATING,
    IGBT_STATE_SHUTDOWN
} igbt_state_t;

typedef struct {
    float tj_est_c;
    float power_loss_w;
    float current_a;
    float ambient_c;
    igbt_state_t state;
    uint16_t pwm_freq_hz;
    uint16_t pwm_duty_permille;
    uint32_t fault_count;
} igbt_ctx_t;

/* ================= 结温估算 ================= */
static float igbt_estimate_junction_temp(float current_a, float ambient_c, float prev_tj)
{
    float conduction_loss;
    float switching_loss;
    float total_loss;
    float r_th_total;
    float tj_steady;
    float alpha;

    conduction_loss = current_a * current_a * 0.002f;
    switching_loss = current_a * 0.5f;
    total_loss = conduction_loss + switching_loss;

    r_th_total = THERMAL_R_THETA_JC + THERMAL_R_THETA_CA;
    tj_steady = ambient_c + total_loss * r_th_total;

    alpha = CONTROL_PERIOD_S / (THERMAL_TAU_S + CONTROL_PERIOD_S);
    return prev_tj + alpha * (tj_steady - prev_tj);
}

/* ================= 降频控制 ================= */
static void igbt_update_pwm_freq(igbt_ctx_t *ctx)
{
    switch (ctx->state) {
        case IGBT_STATE_NORMAL:
            ctx->pwm_freq_hz = PWM_FREQ_NORMAL_HZ;
            ctx->pwm_duty_permille = 1000U;
            break;

        case IGBT_STATE_DERATING: {
            float over = ctx->tj_est_c - IGBT_TJ_WARNING_C;
            float span = IGBT_TJ_SHUTDOWN_C - IGBT_TJ_WARNING_C;
            float ratio;
            uint16_t freq;
            uint16_t duty;

            if (span <= 0.0f) {
                ratio = 1.0f;
            } else {
                ratio = over / span;
            }

            if (ratio < 0.0f) ratio = 0.0f;
            if (ratio > 1.0f) ratio = 1.0f;

            freq = (uint16_t)((float)PWM_FREQ_NORMAL_HZ -
                   ratio * (float)(PWM_FREQ_NORMAL_HZ - PWM_FREQ_MIN_HZ));
            if (freq < PWM_FREQ_MIN_HZ) freq = PWM_FREQ_MIN_HZ;
            if (freq > PWM_FREQ_REDUCED_HZ) freq = PWM_FREQ_REDUCED_HZ;

            duty = (uint16_t)(1000.0f - ratio * 500.0f);
            if (duty > 1000U) duty = 1000U;

            ctx->pwm_freq_hz = freq;
            ctx->pwm_duty_permille = duty;
            break;
        }

        case IGBT_STATE_SHUTDOWN:
            ctx->pwm_freq_hz = 0U;
            ctx->pwm_duty_permille = 0U;
            break;

        default:
            ctx->pwm_freq_hz = PWM_FREQ_NORMAL_HZ;
            ctx->pwm_duty_permille = 1000U;
            break;
    }
}

/* ================= 状态机 ================= */
static void igbt_update_state(igbt_ctx_t *ctx)
{
    switch (ctx->state) {
        case IGBT_STATE_NORMAL:
            if (ctx->tj_est_c >= IGBT_TJ_SHUTDOWN_C) {
                ctx->state = IGBT_STATE_SHUTDOWN;
                ctx->fault_count++;
            } else if (ctx->tj_est_c >= IGBT_TJ_WARNING_C) {
                ctx->state = IGBT_STATE_DERATING;
            }
            break;

        case IGBT_STATE_DERATING:
            if (ctx->tj_est_c >= IGBT_TJ_SHUTDOWN_C) {
                ctx->state = IGBT_STATE_SHUTDOWN;
                ctx->fault_count++;
            } else if (ctx->tj_est_c <= IGBT_TJ_RECOVER_C) {
                ctx->state = IGBT_STATE_NORMAL;
            }
            break;

        case IGBT_STATE_SHUTDOWN:
            if (ctx->tj_est_c <= IGBT_TJ_RECOVER_C) {
                ctx->state = IGBT_STATE_NORMAL;
            }
            break;

        default:
            ctx->state = IGBT_STATE_NORMAL;
            break;
    }
}

/* ================= 主控制周期 ================= */
static void igbt_control_step(igbt_ctx_t *ctx)
{
    uint16_t temp_adc;
    uint16_t curr_adc;
    float ambient_c;

    temp_adc = IGBT_TEMP_REG;
    curr_adc = IGBT_CURRENT_REG;

    ambient_c = IGBT_TEMP_ADC_TO_C(temp_adc);
    ctx->ambient_c = ambient_c;
    ctx->current_a = IGBT_CURRENT_ADC_TO_A(curr_adc);

    ctx->tj_est_c = igbt_estimate_junction_temp(ctx->current_a,
                                                ctx->ambient_c,
                                                ctx->tj_est_c);

    igbt_update_state(ctx);
    igbt_update_pwm_freq(ctx);

    PWM_FREQ_REG = ctx->pwm_freq_hz;
    PWM_DUTY_REG = ctx->pwm_duty_permille;
}

/* ================= 测试打印 ================= */
static const char *state_to_str(igbt_state_t s)
{
    switch (s) {
        case IGBT_STATE_NORMAL:   return "NORMAL";
        case IGBT_STATE_DERATING: return "DERATING";
        case IGBT_STATE_SHUTDOWN: return "SHUTDOWN";
        default:                  return "UNKNOWN";
    }
}

static void print_ctx(const igbt_ctx_t *ctx, int step)
{
    printf("[%03d] Tj=%6.2f C  Ta=%6.2f C  I=%5.2f A  "
           "State=%-8s  Freq=%5u Hz  Duty=%4u/1000  Faults=%u\n",
           step,
           (double)ctx->tj_est_c,
           (double)ctx->ambient_c,
           (double)ctx->current_a,
           state_to_str(ctx->state),
           (unsigned)ctx->pwm_freq_hz,
           (unsigned)ctx->pwm_duty_permille,
           (unsigned)ctx->fault_count);
}

int main(void)
{
    igbt_ctx_t ctx;
    int i;

    ctx.tj_est_c = 25.0f;
    ctx.power_loss_w = 0.0f;
    ctx.current_a = 0.0f;
    ctx.ambient_c = 25.0f;
    ctx.state = IGBT_STATE_NORMAL;
    ctx.pwm_freq_hz = PWM_FREQ_NORMAL_HZ;
    ctx.pwm_duty_permille = 1000U;
    ctx.fault_count = 0U;

    printf("===== IGBT Over-Temperature Protection Test =====\n");

    for (i = 0; i < 30; i++) {
        if (i < 10) {
            IGBT_TEMP_REG = (uint16_t)(50.0f / 0.5f);
            IGBT_CURRENT_REG = (uint16_t)(10.0f / 0.1f);
        } else if (i < 20) {
            IGBT_TEMP_REG = (uint16_t)(80.0f / 0.5f);
            IGBT_CURRENT_REG = (uint16_t)(60.0f / 0.1f);
        } else {
            IGBT_TEMP_REG = (uint16_t)(40.0f / 0.5f);
            IGBT_CURRENT_REG = (uint16_t)(5.0f / 0.1f);
        }

        igbt_control_step(&ctx);
        print_ctx(&ctx, i);
    }

    printf("===== Test Finished =====\n");
    return 0;
}
