#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与宏定义 ================= */
/* 使用普通全局变量模拟寄存器，避免直接访问非法地址导致段错误 */
static uint32_t g_comm_status_reg = 0U;
static uint32_t g_control_output_reg = 0U;
static uint32_t g_local_mode_reg = 0U;
static uint32_t g_sys_tick_reg = 0U;

#define COMM_STATUS_REG     (g_comm_status_reg)
#define CONTROL_OUTPUT_REG  (g_control_output_reg)
#define LOCAL_MODE_REG      (g_local_mode_reg)
#define SYS_TICK_REG        (g_sys_tick_reg)

#define COMM_OK_BIT         (1U << 0)
#define COMM_LOST_BIT       (1U << 1)

#define OUTPUT_ENABLE       (1U << 0)
#define OUTPUT_DISABLE      (0U)

#define LOCAL_MODE_ON       (1U << 0)
#define LOCAL_MODE_OFF      (0U)

/* 通信超时阈值（毫秒） */
#define COMM_TIMEOUT_MS     500U

/* ================= 状态定义 ================= */
typedef enum {
    STATE_INIT = 0,
    STATE_COMM_NORMAL,
    STATE_COMM_TIMEOUT,
    STATE_LOCAL_MODE
} SystemState_t;

/* ================= 全局变量 ================= */
static SystemState_t g_state = STATE_INIT;
static uint32_t g_last_comm_tick = 0U;
static bool g_comm_lost = false;

/* ================= 辅助函数 ================= */
static uint32_t GetTickMs(void)
{
    return SYS_TICK_REG;
}

static bool IsCommOk(void)
{
    return (COMM_STATUS_REG & COMM_OK_BIT) != 0U;
}

static bool IsCommLost(void)
{
    return (COMM_STATUS_REG & COMM_LOST_BIT) != 0U;
}

static bool IsLocalMode(void)
{
    return (LOCAL_MODE_REG & LOCAL_MODE_ON) != 0U;
}

static void SetOutput(bool enable)
{
    if (enable) {
        CONTROL_OUTPUT_REG |= OUTPUT_ENABLE;
    } else {
        CONTROL_OUTPUT_REG &= ~OUTPUT_ENABLE;
    }
}

/* ================= 通信中断保护核心逻辑 ================= */
static void CommTimeoutProtection(void)
{
    uint32_t now = GetTickMs();

    /* 1. 检测本地模式：本地模式下强制停机 */
    if (IsLocalMode()) {
        g_state = STATE_LOCAL_MODE;
        SetOutput(false);
        g_comm_lost = false;
        printf("[PROTECT] Local mode active -> Output DISABLED\n");
        return;
    }

    /* 2. 检测通信状态 */
    if (IsCommOk()) {
        /* 通信正常，刷新时间戳 */
        g_last_comm_tick = now;
        g_comm_lost = false;
        g_state = STATE_COMM_NORMAL;
        SetOutput(true);
        printf("[PROTECT] Comm OK -> Output ENABLED\n");
        return;
    }

    /* 3. 通信异常或丢失，检查超时 */
    if (IsCommLost() || !IsCommOk()) {
        uint32_t elapsed = now - g_last_comm_tick;

        if (elapsed >= COMM_TIMEOUT_MS) {
            /* 超时停机 */
            g_state = STATE_COMM_TIMEOUT;
            g_comm_lost = true;
            SetOutput(false);
            printf("[PROTECT] Comm timeout (%u ms >= %u ms) -> Output DISABLED\n",
                   elapsed, COMM_TIMEOUT_MS);
        } else {
            /* 尚未超时，保持当前输出状态，但记录通信异常 */
            printf("[PROTECT] Comm abnormal, elapsed=%u ms, waiting...\n", elapsed);
        }
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    printf("===== Communication Interruption Protection Test =====\n");

    /* 初始化模拟寄存器 */
