#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * 使用普通静态变量代替绝对地址指针, 避免非法内存访问
 * ============================================================ */

static volatile uint16_t g_adc_data_reg = 0U;
static volatile uint32_t g_gpio_out_reg = 0U;
static volatile uint32_t g_tim_cnt_reg  = 0U;
static volatile uint32_t g_irq_flag_reg = 0U;

/* GPIO 位定义 */
#define IGBT_GATE_PIN           (1U << 0)   /* PWM 驱动输出引脚 */
#define FAULT_LED_PIN           (1U << 1)   /* 故障指示 LED */

/* 中断标志位 */
#define IRQ_FLAG_ADC_EOC        (1U << 0)   /* ADC 转换完成 */

/* ============================================================
 * 系统参数配置
 * ============================================================ */

#define VCC_NOMINAL_MV          15000U      /* 标称 VCC 电压 15V (单位: mV) */
#define VCC_UV_THRESHOLD_MV     12000U      /* 欠压阈值 12V (单位: mV) */
#define VCC_UV_HYSTERESIS_MV    500U        /* 欠压恢复迟滞 0.5V (单位: mV) */
#define VCC_OV_THRESHOLD_MV     20000U      /* 过压阈值 20V (单位: mV) */

#define ADC_VREF_MV             3300U       /* ADC 参考电压 3.3V */
#define ADC_RESOLUTION          4096U       /* 12 位 ADC */

#define VCC_DIVIDER_RATIO_NUM   11U         /* (R1+R2)/R2 = 11 */
#define VCC_DIVIDER_RATIO_DEN   1U

#define UV_DEBOUNCE_COUNT       3U

/* ============================================================
 * 状态机定义
 * ============================================================ */

typedef enum {
    IGBT_STATE_NORMAL = 0,
    IGBT_STATE_UV_WARNING,
    IGBT_STATE_UV_FAULT,
    IGBT_STATE_RECOVERY
} IGBT_State_t;

typedef struct {
    IGBT_State_t state;
    uint16_t     vcc_mv;
    uint16_t     uv_threshold_mv;
    uint8_t      uv_debounce_cnt;
    uint8_t      recovery_cnt;
    bool         gate_enabled;
    uint32_t     fault_count;
} IGBT_Driver_t;

/* ============================================================
 * 硬件抽象函数 (Mock)
 * ============================================================ */

static uint16_t HAL_ADC_ReadRaw(void)
{
    return (uint16_t)(g_adc_data_reg & 0x0FFFU);
}

static void HAL_Gate_Enable(void)
{
    g_gpio_out_reg |= IGBT_GATE_PIN;
}

static void HAL_Gate_Disable(void)
{
    g_gpio_out_reg &= ~IGBT_GATE_PIN;
}

static void HAL_FaultLED_On(void)
{
    g_gpio_out_reg |= FAULT_LED_PIN;
}

static void HAL_FaultLED_Off(void)
{
    g_gpio_out_reg &= ~FAULT_LED_PIN;
}

/* ============================================================
 * 核心算法: VCC 电压换算
 * ============================================================ */

static uint16_t VCC_ConvertToMv(uint16_t adc_raw)
{
    uint32_t adc_mv;
    uint32_t vcc_mv;

    adc_mv = ((uint32_t)adc_raw * ADC_VREF_MV) / ADC_RESOLUTION;
    vcc_mv = (adc_mv * VCC_DIVIDER_RATIO_NUM) / VCC_DIVIDER_RATIO_DEN;

    if (vcc_mv > 65535U) {
        vcc_mv = 65535U;
    }

    return (uint16_t)vcc_mv;
}

/* ============================================================
 * 核心算法: IGBT 驱动欠压保护状态机
 * ============================================================ */

static void IGBT_Driver_Init(IGBT_Driver_t *drv)
{
    if (drv == NULL) {
        return;
    }

    drv->state           = IGBT_STATE_NORMAL;
    drv->vcc_mv          = VCC_NOMINAL_MV;
    drv->uv_threshold_mv = VCC_UV_THRESHOLD_MV;
    drv->uv_debounce_cnt = 0U;
    drv->recovery_cnt    = 0U;
    drv->gate_enabled    = false;
    drv->fault_count     = 0U;

    HAL_Gate_Enable();
    drv->gate_enabled = true;
    HAL_FaultLED_Off();
}

static void IGBT_Driver_Process(IGBT_Driver_t *drv)
{
    uint16_t adc_raw;
    uint16_t vcc_mv;

    if (drv == NULL) {
        return;
    }

    /* --- 步骤 1: 采样 VCC 电压 --- */
    adc_raw = HAL_ADC_ReadRaw();
    vcc_mv  = VCC_ConvertToMv(adc_raw);
    drv->vcc_mv = vcc_mv;

    /* --- 步骤 2: 状态机处理 --- */
    switch (drv->state) {

    case IGBT_STATE_NORMAL:
        if (vcc_mv < drv->uv_threshold_mv) {
            drv->uv_debounce_cnt++;
            if (drv->uv_debounce_cnt >= UV_DEBOUNCE_COUNT) {
                drv->state = IGBT_STATE_UV_FAULT;
                drv->uv_debounce_cnt = 0U;
                drv->fault_count++;

                HAL_Gate_Disable();
                drv->gate_enabled = false;
                HAL_FaultLED_On();

                printf("[FAULT] IGBT UV detected! VCC=%u mV, threshold=%u mV\n",
                       (unsigned)vcc_mv, (unsigned)drv->uv_threshold_mv);
            } else {
                drv->state = IGBT_STATE_UV_WARNING;
                printf("[WARN]  IGBT UV warning! VCC=%u mV (debounce %u/%u)\n",
                       (unsigned)vcc_mv,
                       (unsigned)drv->uv_debounce_cnt,
                       (unsigned)UV_DEBOUNCE_COUNT);
            }
        } else {
            drv->uv_debounce_cnt = 0U;
        }
        break;

    case IGBT_STATE_UV_WARNING:
        if (vcc_mv < drv->uv_threshold_mv) {
            drv->uv_debounce_cnt++;
            if (drv->uv_debounce_cnt >= UV_DEBOUNCE_COUNT) {
                drv->state = IGBT_STATE_UV_FAULT;
                drv->uv_debounce_cnt = 0U;
                drv->fault_count++;

                HAL_Gate_Disable();
                drv->gate_enabled = false;
                HAL_FaultLED_On();

                printf("[FAULT] IGBT UV confirmed! VCC=%u mV, threshold=%u mV\n",
                       (unsigned)vcc_mv, (unsigned)drv->uv_threshold_mv);
            }
        } else {
            drv->state = IGBT_STATE_NORMAL;
            drv->uv_debounce_cnt = 0U;
            printf("[INFO]  IGBT UV warning cleared. VCC=%u mV\n", (unsigned)vcc_mv);
        }
        break;

    case IGBT_STATE_UV_FAULT:
        drv->uv_threshold_mv = VCC_UV_THRESHOLD_MV + VCC_UV_HYSTERESIS_MV;

        if (vcc_mv >= drv->uv_threshold_mv) {
            drv->recovery_cnt++;
            if (drv->recovery_cnt >= UV_DEBOUNCE_COUNT) {
                drv->state = IGBT_STATE_RECOVERY;
                drv->recovery_cnt = 0U;
                printf("[INFO]  IGBT UV recovery confirmed. VCC=%u mV\n", (unsigned)vcc_mv);
            }
        } else {
            drv->recovery_cnt = 0U;
        }
        break;

    case IGBT_STATE_RECOVERY:
        HAL_Gate_Enable();
        drv->gate_enabled = true;
        HAL_FaultLED_Off();

        drv->uv_threshold_mv = VCC_UV_THRESHOLD_MV;

        drv->state = IGBT_STATE_NORMAL;
        drv->uv_debounce_cnt = 0U;
        drv->recovery_cnt = 0U;

        printf("[INFO]  IGBT gate re-enabled. VCC=%u mV\n", (unsigned)vcc_mv);
        break;

    default:
        drv->state = IGBT_STATE_NORMAL;
        break;
    }

    /* --- 步骤 3: 过压保护 --- */
    if (vcc_mv > VCC_OV_THRESHOLD_MV) {
        HAL_Gate_Disable();
        drv->gate_enabled = false;
        HAL_FaultLED_On();
        printf("[FAULT] IGBT OV detected! VCC=%u mV, threshold=%u mV\n",
               (unsigned)vcc_mv, (unsigned)VCC_OV_THRESHOLD_MV);
    }
}

/* ============================================================
 * 测试辅助函数
 * ============================================================ */

static void Test_SetVCC(uint16_t vcc_mv)
{
    uint32_t adc_mv;
    uint32_t adc_raw;

    adc_mv = ((uint32_t)vcc_mv * VCC_DIVIDER_RATIO_DEN) / VCC_DIVIDER_RATIO_NUM;
    adc_raw = (adc_mv * ADC_RESOLUTION) / ADC_VREF_MV;

    if (adc_raw > 4095U) {
        adc_raw = 4095U;
    }

    g_adc_data_reg = (uint16_t)adc_raw;
}

static void Test_PrintStatus(const IGBT_Driver_t *drv)
{
    const char *state_str;

    if (drv == NULL) {
        return;
    }

    switch (drv->state) {
    case IGBT_STATE_NORMAL:     state_str = "NORMAL";     break;
    case IGBT_STATE_UV_WARNING: state_str = "UV_WARNING"; break;
    case IGBT_STATE_UV_FAULT:   state_str = "UV_FAULT";   break;
    case IGBT_STATE_RECOVERY:   state_str = "RECOVERY";   break;
    default:                    state_str = "UNKNOWN";    break;
    }

    printf("  State=%-10s VCC=%5u mV  Gate=%s  FaultCnt=%u\n",
           state_str,
           (unsigned)drv->vcc_mv,
           drv->gate_enabled ? "ON " : "OFF",
           (unsigned)drv->fault_count);
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    IGBT_Driver_t igbt_drv;
    uint32_t i;

    printf("========================================\n");
    printf("  IGBT Driver VCC Undervoltage Protection\n");
    printf("  Nominal VCC: %u mV\n", (unsigned)VCC_NOMINAL_MV);
    printf("  UV Threshold: %u mV\n", (unsigned)VCC_UV_THRESHOLD_MV);
