#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * 软件看门狗（程序跑飞，复位）控制算法骨架
 * 模拟硬件看门狗定时器，通过喂狗机制检测程序跑飞
 * 使用标准 GCC 编译，无单片机特定头文件
 * ============================================================ */

/* ---------- 模拟寄存器定义（mock） ---------- */
static volatile uint32_t g_wdt_cr  = 0;
static volatile uint32_t g_wdt_sr  = 0;
static volatile uint32_t g_wdt_cnt = 0;
static volatile uint32_t g_wdt_rld = 0;

#define WDT_CR   (g_wdt_cr)
#define WDT_SR   (g_wdt_sr)
#define WDT_CNT  (g_wdt_cnt)
#define WDT_RLD  (g_wdt_rld)

/* 看门狗控制寄存器位定义 */
#define WDT_CR_EN           (1U << 0)   /* 使能看门狗 */
#define WDT_CR_INT_EN       (1U << 1)   /* 中断使能 */
#define WDT_CR_RST_EN       (1U << 2)   /* 复位使能 */

/* 看门狗状态寄存器位定义 */
#define WDT_SR_TIMEOUT      (1U << 0)   /* 超时标志 */
#define WDT_SR_FEED_OK      (1U << 1)   /* 喂狗成功标志 */

/* 看门狗超时时间（模拟计数周期） */
#define WDT_TIMEOUT_VALUE   1000U

/* 软件看门狗任务状态 */
typedef enum {
    WDT_STATE_IDLE = 0,
    WDT_STATE_RUNNING,
    WDT_STATE_TIMEOUT,
    WDT_STATE_RESET
} wdt_state_t;

/* 软件看门狗控制块 */
typedef struct {
    wdt_state_t state;          /* 当前状态 */
    uint32_t    timeout_cnt;    /* 超时计数器 */
    uint32_t    feed_cnt;       /* 喂狗次数 */
    uint32_t    reset_cnt;      /* 复位次数 */
    bool        enabled;        /* 使能标志 */
} wdt_ctrl_t;

static wdt_ctrl_t g_wdt;

/* ---------- 模拟硬件看门狗寄存器操作 ---------- */
static void wdt_hw_init(void)
{
    WDT_CR = 0;
    WDT_SR = 0;
    WDT_CNT = 0;
    WDT_RLD = WDT_TIMEOUT_VALUE;
    WDT_CR = WDT_CR_EN | WDT_CR_RST_EN;
}

static void wdt_hw_feed(void)
{
    WDT_CNT = 0;
    WDT_SR |= WDT_SR_FEED_OK;
}

static bool wdt_hw_check_timeout(void)
{
    if (WDT_CNT >= WDT_RLD) {
        WDT_SR |= WDT_SR_TIMEOUT;
        return true;
    }
    return false;
}

static void wdt_hw_reset(void)
{
    /* 模拟系统复位：清零所有寄存器，重新初始化 */
    WDT_CR = 0;
    WDT_SR = 0;
    WDT_CNT = 0;
    WDT_RLD = WDT_TIMEOUT_VALUE;
    WDT_CR = WDT_CR_EN | WDT_CR_RST_EN;
}

/* ---------- 软件看门狗核心逻辑 ---------- */
static void wdt_init(void)
{
    g_wdt.state = WDT_STATE_IDLE;
    g_wdt.timeout_cnt = 0;
    g_wdt.feed_cnt = 0;
    g_wdt.reset_cnt = 0;
    g_wdt.enabled = false;
    wdt_hw_init();
}

static void wdt_start(void)
{
    g_wdt.enabled = true;
    g_wdt.state = WDT_STATE_RUNNING;
    g_wdt.timeout_cnt = 0;
    wdt_hw_feed();
    printf("[WDT] 软件看门狗已启动，超时阈值 = %u\n", (unsigned)WDT_TIMEOUT_VALUE);
}

static void wdt_feed(void)
{
    if (!g_wdt.enabled) {
        return;
    }
    g_wdt.feed_cnt++;
    g_wdt.timeout_cnt = 0;
    wdt_hw_feed();
    printf("[WDT] 喂狗成功 (第 %u 次)\n", (unsigned)g_wdt.feed_cnt);
}

static void wdt_tick(void)
{
    if (!g_wdt.enabled) {
        return;
    }

    g_wdt.timeout_cnt++;
    WDT_CNT++;

    if (wdt_hw_check_timeout()) {
        g_wdt.state = WDT_STATE_TIMEOUT;
        printf("[WDT] 警告：看门狗超时！程序可能跑飞！\n");
        printf("[WDT] 超时计数 = %u，喂狗次数 = %u\n",
               (unsigned)g_wdt.timeout_cnt, (unsigned)g_wdt.feed_cnt);

        /* 触发系统复位 */
        g_wdt.state = WDT_STATE_RESET;
        g_wdt.reset_cnt++;
        printf("[WDT] 触发系统复位 (第 %u 次)\n", (unsigned)g_wdt.reset_cnt);

        wdt_hw_reset();
        g_wdt.timeout_cnt = 0;
        g_wdt.feed_cnt = 0;
        g_wdt.state = WDT_STATE_RUNNING;
    }
}

static wdt_state_t wdt_get_state(void)
{
    return g_wdt.state;
}

/* ---------- 模拟应用任务 ---------- */
static void app_task_normal(void)
{
    /* 正常任务：周期性喂狗 */
    printf("[APP] 正常任务执行中...\n");
    wdt_feed();
}

static void app_task_stuck(void)
{
    /* 模拟程序跑飞：不喂狗，导致看门狗超时 */
    printf("[APP] 任务卡死（模拟程序跑飞），未喂狗...\n");
}

/* ---------- 主函数 ---------- */
int main(void)
{
    int i;
    int j;

    printf("========================================\n");
    printf("  软件看门狗（程序跑飞，复位）演示\n");
    printf("========================================\n\n");

    /* 初始化看门狗 */
    wdt_init();
    wdt_start();

    /* 阶段1：正常运行，周期性喂狗 */
    printf("\n--- 阶段1：正常运行，周期性喂狗 ---\n");
    for (i = 0; i < 5; i++) {
        app_task_normal();
        for (j = 0; j < 200; j++) {
            wdt_tick();
        }
    }

    printf("\n当前看门狗状态：%d (0=IDLE,1=RUNNING,2=TIMEOUT,3=RESET)\n",
           (int)wdt_get_state());

    /* 阶段2：模拟程序跑飞，不喂狗 */
    printf("\n--- 阶段2：程序跑飞，不喂狗 ---\n");
    app_task_stuck();
    for (i = 0; i < 1200; i++) {
        wdt_tick();
    }

    printf("\n当前看门狗状态：%d (0=IDLE,1=RUNNING,2=TIMEOUT,3=RESET)\n",
           (int)wdt_get_state());

    /* 阶段3：复位后恢复正常 */
    printf("\n--- 阶段3：复位后恢复正常 ---\n");
    for (i = 0; i < 3; i++) {
        app_task_normal();
        for (j = 0; j < 200; j++) {
            wdt_tick();
        }
    }

    printf("\n========================================\n");
    printf("  演示结束\n");
    printf("  总喂狗次数：%u\n", (unsigned)g_wdt.feed_cnt);
    printf("  总复位次数：%u\n", (unsigned)g_wdt.reset_cnt);
    printf("========================================\n");

    return 0;
}
