#include <stdint.h>

/* ==================== Mock 宏定义 ==================== */
#define GRID_NOMINAL_VOLTAGE      311.0f
#define GRID_NOMINAL_FREQ         50.0f
#define SAMPLE_FREQ               10000.0f
#define SAMPLE_PERIOD             (1.0f / SAMPLE_FREQ)
#define GRID_OMEGA                (2.0f * 3.14159265358979323846f * GRID_NOMINAL_FREQ)

#define LVRT_DIP_THRESHOLD        0.90f
#define LVRT_RECOVER_THRESHOLD    0.95f
#define LVRT_DIP_CONFIRM_CNT      5
#define LVRT_RECOVER_CONFIRM_CNT  20

#define PLL_KP                    50.0f
#define PLL_KI                    2000.0f
#define PLL_TS                    SAMPLE_PERIOD

#define PI                        3.14159265358979323846f
#define TWO_PI                    (2.0f * PI)

/* ==================== 数据类型定义 ==================== */
typedef struct {
    float alpha;
    float beta;
    float theta;
    float omega;
    float sin_theta;
    float cos_theta;
    float vd;
    float vq;
    float pll_integral;
    float amplitude;
    float amplitude_pu;
    float phase;
    float freq;
} GridVoltage_t;

typedef struct {
    uint8_t  dip_flag;
    uint8_t  dip_confirm_cnt;
    uint8_t  recover_confirm_cnt;
    float    dip_depth;
    float    dip_start_phase;
    uint32_t dip_duration_ms;
    uint32_t dip_start_time_ms;
} LVRT_Detector_t;

/* ==================== 全局变量 ==================== */
static GridVoltage_t    g_grid;
static LVRT_Detector_t  g_lvrt;

/* ==================== 工具函数 ==================== */
static float wrap_angle(float angle)
{
    int guard = 0;
    while (angle > PI && guard < 100) {
        angle -= TWO_PI;
        guard++;
    }
    guard = 0;
    while (angle < -PI && guard < 100) {
        angle += TWO_PI;
        guard++;
    }
    return angle;
}

static float fast_sin(float x)
{
    float x2 = x * x;
    return x * (1.0f - x2 / 6.0f + x2 * x2 / 120.0f);
}

static float fast_cos(float x)
{
    float x2 = x * x;
    return 1.0f - x2 / 2.0f + x2 * x2 / 24.0f;
}

/* ==================== 初始化 ==================== */
static void GridVoltage_Init(GridVoltage_t *g)
{
    g->alpha         = 0.0f;
    g->beta          = 0.0f;
    g->theta         = 0.0f;
    g->omega         = GRID_OMEGA;
    g->sin_theta     = 0.0f;
    g->cos_theta     = 1.0f;
    g->vd            = 0.0f;
    g->vq            = 0.0f;
    g->pll_integral  = 0.0f;
    g->amplitude     = 0.0f;
    g->amplitude_pu  = 0.0f;
    g->phase         = 0.0f;
    g->freq          = GRID_NOMINAL_FREQ;
}

static void LVRT_Detector_Init(LVRT_Detector_t *d)
{
    d->dip_flag            = 0;
    d->dip_confirm_cnt     = 0;
    d->recover_confirm_cnt = 0;
    d->dip_depth           = 0.0f;
    d->dip_start_phase     = 0.0f;
    d->dip_duration_ms     = 0;
    d->dip_start_time_ms   = 0;
}

/* ==================== 核心算法 ==================== */
static void Clarke_Transform(float va, float vb, float vc,
                             float *alpha, float *beta)
{
    *alpha = (2.0f / 3.0f) * (va - 0.5f * vb - 0.5f * vc);
    *beta  = (2.0f / 3.0f) * (0.86602540378f * (vb - vc));
}

static void PLL_Update(GridVoltage_t *g, float dt)
{
    g->sin_theta = fast_sin(g->theta);
    g->cos_theta = fast_cos(g->theta);

    g->vd =  g->alpha * g->cos_theta + g->beta * g->sin_theta;
    g->vq = -g->alpha * g->sin_theta + g->beta * g->cos_theta;

    float error = g->vq;
    g->pll_integral += PLL_KI * error * dt;
    float omega_correction = PLL_KP * error + g->pll_integral;

    if (g->pll_integral >  500.0f) g->pll_integral =  500.0f;
    if (g->pll_integral < -500.0f) g->pll_integral = -500.0f;

    g->omega = GRID_OMEGA + omega_correction;
    g->theta += g->omega * dt;
    g->theta  = wrap_angle(g->theta);

    g->freq = g->omega / TWO_PI;

    g->amplitude = sqrtf(g->vd * g->vd + g->vq * g->vq);
    g->amplitude_pu = g->amplitude / GRID_NOMINAL_VOLTAGE;
    g->phase = atan2f(g->vq, g->vd);
}

static void LVRT_Detect(LVRT_Detector_t *d, GridVoltage_t *g, float time_ms)
{
    float v_pu = g->amplitude_pu;

    if (d->dip_flag == 0) {
        if (v_pu < LVRT_DIP_THRESHOLD) {
            d->dip_confirm_cnt++;
            if (d->dip_confirm_cnt >= LVRT_DIP_CONFIRM_CNT) {
                d->dip_flag          = 1;
                d->dip_depth         = 1.0f - v_pu;
                d->dip_start_phase   = g->theta;
                d->dip_start_time_ms = (uint32_t)time_ms;
                d->dip_duration_ms   = 0;
                d->recover_confirm_cnt = 0;
                printf("[LVRT] *** 电压跌落检测! 深度=%.3f pu, 起始相位=%.2f deg ***\n",
                       d->dip_depth, d->dip_start_phase * 180.0f / PI);
            }
        } else {
            d->dip_confirm_cnt = 0;
        }
    } else {
        d->dip_duration_ms = (uint32_t)time_ms - d->dip_start_time_ms;

        if (v_pu > LVRT_RECOVER_THRESHOLD) {
            d->recover_confirm_cnt++;
            if (d->recover_confirm_cnt >= LVRT_RECOVER_CONFIRM_CNT) {
                d->dip_flag            = 0;
                d->dip_confirm_cnt     = 0;
                d->recover_confirm_cnt = 0;
                printf("[LVRT] *** 电压恢复! 跌落持续=%u ms ***\n",
                       d->dip_duration_ms);
            }
        } else {
            d->recover_confirm_cnt = 0;
        }
    }
}

static void Generate_Grid_Voltage(float t,
                                  int dip_enable,
                                  float dip_start,
                                  float dip_end,
                                  float dip_depth,
                                  float *va, float *vb, float *vc)
{
    float amp = GRID_NOMINAL_VOLTAGE;

    if (dip_enable && t >= dip_start && t <= dip_end) {
        amp = GRID_NOMINAL_VOLTAGE * (1.0f - dip_depth);
    }

    float wt = TWO_PI * GRID_NOMINAL_FREQ * t;

    *va = amp * fast_sin(wt);
    *vb = amp * fast_sin(wt - TWO_PI / 3.0f);
    *vc = amp * fast_sin(wt + TWO_PI / 3.0f);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("========================================\n");
    printf("  电网电压跌落检测 (LVRT) 算法演示\n");
    printf("  幅值检测 + 相位锁定 (SRF-PLL)\n");
    printf("========================================\n\n");

    GridVoltage_Init(&g_grid);
    LVRT_Detector_Init(&g_lvrt);

    const float sim_duration = 0.5f;
    const float dip_start    = 0.15f;
    const float dip_end      = 0.30f;
    const float dip_depth    = 0.60f;
    const int   dip_enable   = 1;

    float t = 0.0f;
    int   print_cnt = 0;
    int   total_steps = (int)(sim_duration / SAMPLE_PERIOD);

    printf("仿真参数:\n");
    printf("  额定电压峰值: %.1f V\n", GRID_NOMINAL_VOLTAGE);
    printf("  额定频率:     %.1f Hz\n", GRID_NOMINAL_FREQ);
    printf("  采样频率:     %.1f Hz\n", SAMPLE_FREQ);
    printf("  跌落时间:     %.0f ms ~ %.0f ms\n", dip_start * 1000.0f, dip_end * 1000.0f);
    printf("  跌落深度:     %.0f%%\n\n", dip_depth * 100.0f);

    printf("时间(ms) | Va(V)   | 幅值(V) | 幅值(pu) | 频率(Hz) | 相位(deg) | 状态\n");
    printf("---------|---------|---------|----------|----------|-----------|------\n");

    for (int step = 0; step < total_steps; step++) {
        float va, vb, vc;

        Generate_Grid_Voltage(t, dip_enable, dip_start, dip_end, dip_depth,
                              &va, &vb, &vc);

        Clarke_Transform(va, vb, vc, &g_grid.alpha, &g_grid.beta);
        PLL_Update(&g_grid, SAMPLE_PERIOD);
        LVRT_Detect(&g_lvrt, &g_grid, t * 1000.0f);

        if (print_cnt % 500 == 0) {
            printf("%7.1f  | %7.2f | %7.2f | %8.4f | %8.2f | %9.2f | %s\n",
                   t * 1000.0f,
                   va,
                   g_grid.amplitude,
                   g_grid.amplitude_pu,
                   g_grid.freq,
                   g_grid.theta * 180.0f / PI,
                   g_lvrt.dip_flag ? "跌落" : "正常");
        }

        t += SAMPLE_PERIOD;
        print_cnt++;
    }

    printf("\n========================================\n");
    printf("  仿真结束\n");
    printf("========================================\n");

    return 0;
}
