#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t WDT_CR;
static volatile uint32_t WDT_SR;
static volatile uint32_t WDT_CNT;
static volatile uint32_t WDT_RLD;

static volatile uint32_t PWR_SR;
static volatile uint32_t PWR_CR;

static volatile uint32_t RCC_CSR;

/* 看门狗控制寄存器位定义 */
#define WDT_CR_EN       (1U << 0)
#define WDT_CR_INTEN    (1U << 1)
#define WDT_CR_RSTEN    (1U << 2)
#define WDT_CR_KEY      (0x5A5A0000U)

/* 看门狗状态寄存器位定义 */
#define WDT_SR_TIMEOUT  (1U << 0)
#define WDT_SR_FEED_OK  (1U << 1)

#define PWR_SR_POR      (1U << 0)
#define PWR_SR_BOR      (1U << 1)
#define PWR_SR_PVD      (1U << 2)
#define PWR_SR_WDT_RST  (1U << 3)

#define PWR_CR_PVDEN    (1U << 0)
#define PWR_CR_PVDLVL   (1U << 1)

#define RCC_CSR_RMVF    (1U << 24)

#define WDT_FEED_KEY    0xAAAAU
#define WDT_FEED_KEY2   0x5555U

/* ================= 看门狗驱动层 ================= */

static void wdt_init(uint32_t timeout_ms)
{
    WDT_CR = WDT_CR_KEY | WDT_CR_EN | WDT_CR_RSTEN;
    WDT_RLD = timeout_ms;
    WDT_CNT = timeout_ms;
    printf("[WDT] 初始化完成，超时时间 = %u ms\n", timeout_ms);
}

static void wdt_feed(void)
{
    WDT_CNT = WDT_FEED_KEY;
    WDT_CNT = WDT_FEED_KEY2;
    WDT_SR |= WDT_SR_FEED_OK;
    printf("[WDT] 喂狗成功\n");
}

static bool wdt_is_timeout(void)
{
    return (WDT_SR & WDT_SR_TIMEOUT) != 0;
}

static void wdt_clear_timeout(void)
{
    WDT_SR &= ~WDT_SR_TIMEOUT;
}

/* ================= 电源监控层 ================= */

static void pwr_monitor_init(void)
{
    PWR_CR |= PWR_CR_PVDEN | PWR_CR_PVDLVL;
    printf("[PWR] 电源监控初始化完成\n");
}

static bool pwr_check_fault(void)
{
    uint32_t sr = PWR_SR;
    if (sr & PWR_SR_POR) {
        printf("[PWR] 检测到上电复位 (POR)\n");
        return true;
    }
    if (sr & PWR_SR_BOR) {
        printf("[PWR] 检测到欠压复位 (BOR)\n");
        return true;
    }
    if (sr & PWR_SR_PVD) {
        printf("[PWR] 检测到电源电压下降 (PVD)\n");
        return true;
    }
    if (sr & PWR_SR_WDT_RST) {
        printf("[PWR] 检测到看门狗复位 (WDT)\n");
        return true;
    }
    return false;
}

static void pwr_clear_fault(void)
{
    PWR_SR = 0;
    RCC_CSR |= RCC_CSR_RMVF;
    printf("[PWR] 电源故障标志已清除\n");
}

/* ================= 系统复位处理 ================= */

static void system_reset_analysis(void)
{
    printf("\n========== 系统复位原因分析 ==========\n");

    if (PWR_SR & PWR_SR_POR) {
        printf("复位原因: 上电复位 (Power-On Reset)\n");
    }
    if (PWR_SR & PWR_SR_BOR) {
        printf("复位原因: 欠压复位 (Brown-Out Reset)\n");
    }
    if (PWR_SR & PWR_SR_PVD) {
        printf("复位原因: 电源电压下降 (PVD)\n");
    }
    if (PWR_SR & PWR_SR_WDT_RST) {
        printf("复位原因: 看门狗复位 (Watchdog Reset)\n");
    }

    printf("======================================\n\n");
}

static void system_recovery(void)
{
    printf("[SYS] 执行系统安全恢复流程...\n");
    printf("[SYS] 1. 保存关键数据到非易失存储\n");
    printf("[SYS] 2. 关闭非必要外设\n");
    printf("[SYS] 3. 等待电源稳定\n");
    printf("[SYS] 4. 重新初始化系统\n");
    printf("[SYS] 系统恢复完成\n");
}

/* ================= 主应用程序任务 ================= */

static void main_task_process(void)
{
    static uint32_t task_counter = 0;
    task_counter++;
    printf("[APP] 主任务执行中... 计数 = %u\n", task_counter);
}

/* ================= 主函数 ================= */

int main(void)
{
    printf("========================================\n");
    printf("  硬件看门狗 + 电源故障监控 系统启动\n");
    printf("========================================\n\n");

    /* 步骤1: 分析复位原因 */
    system_reset_analysis();

    /* 步骤2: 检查电源故障 */
    if (pwr_check_fault()) {
        printf("[SYS] 检测到电源故障，执行恢复流程\n");
        system_recovery();
        pwr_clear_fault();
    }

    /* 步骤3: 初始化电源监控 */
    pwr_monitor_init();

    /* 步骤4: 初始化看门狗，超时时间 1000ms */
    wdt_init(1000);

    /* 步骤5: 主循环 */
    printf("\n[APP] 进入主循环...\n\n");

    for (int loop = 0; loop < 5; loop++) {
        main_task_process();

        if (loop == 2) {
            printf("[PWR] 模拟电源电压下降事件...\n");
            PWR_SR |= PWR_SR_PVD;
            if (pwr_check_fault()) {
                printf("[SYS] 电源故障！执行紧急恢复\n");
                system_recovery();
                pwr_clear_fault();
            }
        }

        if (loop == 3) {
            printf("[WDT] 模拟看门狗超时事件...\n");
            WDT_SR |= WDT_SR_TIMEOUT;
            if (wdt_is_timeout()) {
                printf("[WDT] 看门狗超时！系统即将复位\n");
                wdt_clear_timeout();
                printf("[SYS] 执行看门狗复位恢复流程\n");
                system_recovery();
            }
        }

        wdt_feed();

        printf("[APP] 任务间隔等待...\n\n");
    }

    printf("========================================\n");
    printf("  系统运行结束\n");
    printf("========================================\n");

    return 0;
}
