#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免直接访问非法地址导致段错误 */
static uint32_t g_mock_ctrl_reg = 0;
static uint32_t g_mock_status_reg = 0;
static uint32_t g_mock_err_reg = 0;
static uint32_t g_mock_mode_reg = 0;

#define MOCK_CTRL_REG   (g_mock_ctrl_reg)
#define MOCK_STATUS_REG (g_mock_status_reg)
#define MOCK_ERR_REG    (g_mock_err_reg)
#define MOCK_MODE_REG   (g_mock_mode_reg)

/* 控制寄存器位定义 */
#define CTRL_ENABLE             (1U << 0)
#define CTRL_RESET              (1U << 1)
#define CTRL_START              (1U << 2)

/* 状态寄存器位定义 */
#define STATUS_READY            (1U << 0)
#define STATUS_BUSY             (1U << 1)
#define STATUS_FAULT            (1U << 2)
#define STATUS_DONE             (1U << 3)

/* 错误寄存器位定义 */
#define ERR_TIMEOUT             (1U << 0)
#define ERR_CRC                 (1U << 1)
#define ERR_OVERRUN             (1U << 2)
#define ERR_HARDWARE            (1U << 3)

/* 模式寄存器值定义 */
#define MODE_NORMAL             0x00U
#define MODE_SAFE               0x01U
#define MODE_DEGRADED           0x02U
#define MODE_RECOVERY           0x03U

/* ================= 故障自恢复状态机定义 ================= */
typedef enum {
    STATE_IDLE = 0,
    STATE_RUNNING,
    STATE_FAULT_DETECTED,
    STATE_RETRY,
    STATE_RESET,
    STATE_SWITCH_MODE,
    STATE_RECOVERED,
    STATE_FATAL
} recovery_state_t;

typedef enum {
    RECOVERY_ACTION_NONE = 0,
    RECOVERY_ACTION_RETRY,
    RECOVERY_ACTION_RESET,
    RECOVERY_ACTION_SWITCH_MODE,
    RECOVERY_ACTION_FATAL
} recovery_action_t;

/* 故障自恢复配置 */
typedef struct {
    uint32_t max_retry_count;
    uint32_t max_reset_count;
    uint32_t max_mode_switch_count;
    uint32_t retry_delay_ms;
    uint32_t reset_delay_ms;
} recovery_config_t;

/* 故障自恢复上下文 */
typedef struct {
    recovery_state_t state;
    recovery_config_t config;
    uint32_t retry_count;
    uint32_t reset_count;
    uint32_t mode_switch_count;
    uint32_t last_error;
    uint32_t delay_counter;
    uint32_t total_faults;
    uint32_t total_recoveries;
} recovery_context_t;

/* ================= 模拟硬件操作函数 ================= */
static void mock_hw_init(void)
{
    MOCK_CTRL_REG = 0;
    MOCK_STATUS_REG = STATUS_READY;
    MOCK_ERR_REG = 0;
    MOCK_MODE_REG = MODE_NORMAL;
}

static void mock_hw_enable(void)
{
    MOCK_CTRL_REG |= CTRL_ENABLE;
}

static void mock_hw_start(void)
{
    MOCK_CTRL_REG |= CTRL_START;
    MOCK_STATUS_REG &= ~STATUS_READY;
    MOCK_STATUS_REG |= STATUS_BUSY;
    MOCK_STATUS_REG &= ~STATUS_FAULT;
    MOCK_STATUS_REG &= ~STATUS_DONE;
}

static void mock_hw_reset(void)
{
    MOCK_CTRL_REG |= CTRL_RESET;
    MOCK_STATUS_REG = STATUS_READY;
    MOCK_ERR_REG = 0;
    MOCK_CTRL_REG &= ~CTRL_RESET;
}

static void mock_hw_set_mode(uint32_t mode)
{
    MOCK_MODE_REG = mode;
}

static uint32_t mock_hw_get_status(void)
{
    return MOCK_STATUS_REG;
}

static uint32_t mock_hw_get_error(void)
{
    return MOCK_ERR_REG;
}

/* 模拟故障注入：根据运行次数产生不同故障 */
static uint32_t mock_fault_injection_counter = 0;

static void mock_hw_simulate_operation(void)
{
    mock_fault_injection_counter++;

    if (mock_fault_injection_counter == 1) {
        MOCK_STATUS_REG &= ~STATUS_BUSY;
        MOCK_STATUS_REG |= STATUS_FAULT;
        MOCK_ERR_REG = ERR_TIMEOUT;
    } else if (mock_fault_injection_counter == 2) {
        MOCK_STATUS_REG &= ~STATUS_BUSY;
        MOCK_STATUS_REG |= STATUS_FAULT;
        MOCK_ERR_REG = ERR_CRC;
    } else if (mock_fault_injection_counter == 3) {
        MOCK_STATUS_REG &= ~STATUS_BUSY;
        MOCK_STATUS_REG |= STATUS_FAULT;
        MOCK_ERR_REG = ERR_HARDWARE;
    } else {
        MOCK_STATUS_REG &= ~STATUS_BUSY;
        MOCK_STATUS_REG |= STATUS_DONE;
        MOCK_ERR_REG = 0;
    }
}

/* ================= 延时模拟 ================= */
static void mock_delay_ms(uint32_t ms)
{
    (void)ms;
}

/* ================= 故障自恢复核心算法 ================= */

static void recovery_init(recovery_context_t *ctx, const recovery_config_t *cfg)
{
    memset(ctx, 0, sizeof(recovery_context_t));
    ctx->state = STATE_IDLE;
    ctx->config = *cfg;
    ctx->last_error = 0;
    ctx->delay_counter = 0;
}

static const char *state_to_string(recovery_state_t state)
{
    switch (state) {
        case STATE_IDLE:            return "IDLE";
        case STATE_RUNNING:         return "RUNNING";
        case STATE_FAULT_DETECTED:  return "FAULT_DETECTED";
        case STATE_RETRY:           return "RETRY";
        case STATE_RESET:           return "RESET";
        case STATE_SWITCH_MODE:     return "SWITCH_MODE";
        case STATE_RECOVERED:       return "RECOVERED";
        case STATE_FATAL:           return "FATAL";
        default:                    return "UNKNOWN";
    }
}

static const char *error_to_string(uint32_t err)
{
    if (err & ERR_TIMEOUT)  return "TIMEOUT";
    if (err & ERR_CRC)      return "CRC";
    if (err & ERR_OVERRUN)  return "OVERRUN";
    if (err & ERR_HARDWARE) return "HARDWARE";
    return "NONE";
}

static bool is_recoverable_fault(uint32_t err)
{
    if (err & ERR_HARDWARE) {
        return false;
    }
    return true;
}

static recovery_action_t decide_recovery_action(recovery_context_t *ctx)
{
    if (ctx->retry_count < ctx->config.max_retry_count) {
        return RECOVERY_ACTION_RETRY;
    }
    if (ctx->reset_count < ctx->config.max_reset_count) {
        return RECOVERY_ACTION_RESET;
    }
    if (ctx->mode_switch_count < ctx->config.max_mode_switch_count) {
        return RECOVERY_ACTION_SWITCH_MODE;
    }
    return RECOVERY_ACTION_FATAL;
}

static void do_retry(recovery_context_t *ctx)
{
    ctx->retry_count++;
    printf("  [ACTION] Retry #%u (delay %u ms)\n",
           ctx->retry_count, ctx->config.retry_delay_ms);
    mock_delay_ms(ctx->config.retry_delay_ms);
    mock_hw_start();
}

static void do_reset(recovery_context_t *ctx)
{
    ctx->reset_count++;
    printf("  [ACTION] Reset #%u (delay %u ms)\n",
           ctx->reset_count, ctx->config.reset_delay_ms);
    mock_delay_ms(ctx->config.reset_delay_ms);
    mock_hw_reset();
    mock_hw_enable();
    mock_hw_start();
}

static void do_switch_mode(recovery_context_t *ctx)
{
    ctx->mode_switch_count++;
    printf("  [ACTION] Switch Mode #%u -> DEGRADED\n",
           ctx->mode_switch_count);
    mock_hw_set_mode(MODE_DEGRADED);
    mock_hw_start();
}

static void recovery_step(recovery_context_t *ctx)
{
    uint32_t status;
    uint32_t err;

    switch (ctx->state) {
        case STATE_IDLE:
            printf("[STATE] IDLE -> RUNNING\n");
            mock_hw_enable();
            mock_hw_start();
            ctx->state = STATE_RUNNING;
            break;

        case STATE_RUNNING:
            mock_hw_simulate_operation();
            status = mock_hw_get_status();
            err = mock_hw_get_error();

            if (status & STATUS_FAULT) {
                printf("[STATE] RUNNING -> FAULT_DETECTED (err=%s)\n",
                       error_to_string(err));
                ctx->last_error = err;
                ctx->total_faults++;
                ctx->state = STATE_FAULT_DETECTED;
            } else if (status & STATUS_DONE) {
                printf("[STATE] RUNNING -> RECOVERED (operation done)\n");
                ctx->state = STATE_RECOVERED;
            }
            break;

        case STATE_FAULT_DETECTED:
            if (!is_recoverable_fault(ctx->last_error)) {
                printf("[STATE] FAULT_DETECTED -> FATAL (unrecoverable: %s)\n",
                       error_to_string(ctx->last_error));
                ctx->state = STATE_FATAL;
                break;
            }

            {
                recovery_action_t action = decide_recovery_action(ctx);
                switch (action) {
                    case RECOVERY_ACTION_RETRY:
                        printf("[STATE] FAULT_DETECTED -> RETRY\n");
                        ctx->state = STATE_RETRY;
                        break;
                    case RECOVERY_ACTION_RESET:
                        printf("[STATE] FAULT_DETECTED -> RESET\n");
                        ctx->state = STATE_RESET;
                        break;
                    case RECOVERY_ACTION_SWITCH_MODE:
                        printf("[STATE] FAULT_DETECTED -> SWITCH_MODE\n");
                        ctx->state = STATE_SWITCH_MODE;
                        break;
                    case RECOVERY_ACTION_FATAL:
                    default:
                        printf("[STATE] FAULT_DETECTED -> FATAL (exhausted)\n");
                        ctx->state = STATE_FATAL;
                        break;
                }
            }
            break;

        case STATE_RETRY:
            do_retry(ctx);
            ctx->state = STATE_RUNNING;
            break;

        case STATE_RESET:
            do_reset(ctx);
            ctx->state = STATE_RUNNING;
            break;

        case STATE_SWITCH_MODE:
            do_switch_mode(ctx);
            ctx->state = STATE_RUNNING;
            break;

        case STATE_RECOVERED:
            ctx->total_recoveries++;
            printf("[STATE] RECOVERED (total_faults=%u, total_recoveries=%u)\n",
                   ctx->total_faults, ctx->total_recoveries);
            ctx->state = STATE_IDLE;
            break;

        case STATE_FATAL:
            printf("[STATE] FATAL - system halted\n");
            break;

        default:
            ctx->state = STATE_IDLE;
            break;
    }
}

/* ================= 测试主函数 ================= */
int main(void)
{
    recovery_config_t cfg = {
        2,   /* max_retry_count */
        1,   /* max_reset_count */
        1,   /* max_mode_switch_count */
        10,  /* retry_delay_ms */
        50   /* reset_delay_ms */
    };

    recovery_context_t ctx;
    uint32_t step;
    const uint32_t max_steps = 30;
    bool cycle_restarted = false;

    printf("========================================\n");
    printf("  Fault Self-Recovery Control Algorithm\n");
    printf("========================================\n");
    printf("Config: max_retry=%u, max_reset=%u, max_mode_switch=%u\n\n",
           cfg.max_retry_count, cfg.max_reset_count,
           cfg.max_mode_switch_count);

    mock_hw_init();
    recovery_init(&ctx, &cfg);

    for (step = 0; step < max_steps; step++) {
        printf("--- Step %u ---\n", step + 1);
        recovery_step(&ctx);

        if (ctx.state == STATE_FATAL) {
            printf("\nSystem entered FATAL state, stopping.\n");
            break;
        }

        /* 完成一次恢复循环后，重置故障注入计数器以进行下一轮测试 */
        if (ctx.state == STATE_IDLE && step > 0 && !cycle_restarted) {
            printf("\nRecovery cycle complete, restarting...\n\n");
            mock_fault_injection_counter = 0;
            cycle_restarted = true;
        }
    }

    printf("\n========================================\n");
    printf("  Final Report\n");
    printf("========================================\n");
    printf("Final State      : %s\n", state_to_string(ctx.state));
    printf("Total Faults     : %u\n", ctx.total_faults);
    printf("Total Recoveries : %u\n", ctx.total_recoveries);
    printf("Retry Count      : %u\n", ctx.retry_count);
    printf("Reset Count      : %u\n", ctx.reset_count);
    printf("Mode Switch Count: %u\n", ctx.mode_switch_count);
    printf("Last Error       : %s\n", error_to_string(ctx.last_error));
    printf("========================================\n");

    return 0;
}
