static volatile uint32_t g_wdt_cr  = 0;
static volatile uint32_t g_wdt_sr  = 0;
static volatile uint32_t g_wdt_cnt = 0;
static volatile uint32_t g_wdt_rlr = 0;
static volatile uint32_t g_rcc_csr = 0;

#define WDT_CR   (g_wdt_cr)
#define WDT_SR   (g_wdt_sr)
#define WDT_CNT  (g_wdt_cnt)
#define WDT_RLR  (g_wdt_rlr)
#define RCC_CSR  (g_rcc_csr)

/* 看门狗控制寄存器位定义 */
#define WDT_CR_EN           (1U << 0)
#define WDT_CR_INTEN        (1U << 1)
#define WDT_CR_RSTEN        (1U << 2)

/* 看门狗状态寄存器位定义 */
#define WDT_SR_TIMEOUT      (1U << 0)
#define WDT_SR_FEED_OK      (1U << 1)

/* 复位标志 */
#define RCC_CSR_WDTRSTF     (1U << 29)

/* 喂狗序列 */
#define WDT_FEED_SEQ1       0xAAAAU
#define WDT_FEED_SEQ2       0x5555U

/* 模拟系统复位函数 */
static void System_SoftwareReset(void)
{
    printf("[WDT] >>> 触发软件复位 (System Reset) <<<\n");
}

/* ============================================================
 * 软件看门狗数据结构
 * ============================================================ */

typedef struct {
    uint32_t timeout_ms;
    uint32_t counter;
    uint32_t reload;
    uint32_t feed_count;
    uint32_t timeout_count;
    bool     enabled;
    bool     reset_on_timeout;
} SoftWdt_t;

static SoftWdt_t g_soft_wdt;

/* ============================================================
 * 软件看门狗初始化
 * ============================================================ */
static void SoftWdt_Init(SoftWdt_t *wdt, uint32_t timeout_ms, bool reset_on_timeout)
{
    if (wdt == NULL) {
        return;
    }

    wdt->timeout_ms       = timeout_ms;
    wdt->reload           = timeout_ms;
    wdt->counter          = timeout_ms;
    wdt->feed_count       = 0;
    wdt->timeout_count    = 0;
    wdt->enabled          = true;
    wdt->reset_on_timeout = reset_on_timeout;

    WDT_RLR = timeout_ms;
    WDT_CNT = timeout_ms;
    WDT_CR  = WDT_CR_EN | WDT_CR_RSTEN;

    printf("[WDT] 软件看门狗初始化完成: 超时=%ums, 复位使能=%s\n",
           timeout_ms, reset_on_timeout ? "是" : "否");
}

/* ============================================================
 * 喂狗操作
 * ============================================================ */
static void SoftWdt_Feed(SoftWdt_t *wdt)
{
    if (wdt == NULL || !wdt->enabled) {
        return;
    }

    wdt->counter = wdt->reload;
    wdt->feed_count++;

    WDT_CNT = WDT_FEED_SEQ1;
    WDT_CNT = WDT_FEED_SEQ2;
    WDT_SR |= WDT_SR_FEED_OK;

    printf("[WDT] 喂狗成功 (第%u次), 计数器重载为%u\n",
           wdt->feed_count, wdt->reload);
}

/* ============================================================
 * 看门狗周期处理
 * ============================================================ */
static void SoftWdt_Process(SoftWdt_t *wdt, uint32_t elapsed_ms)
{
    if (wdt == NULL || !wdt->enabled) {
        return;
    }

    if (wdt->counter > elapsed_ms) {
        wdt->counter -= elapsed_ms;
    } else {
        wdt->counter = 0;
    }

    if (wdt->counter == 0) {
        wdt->timeout_count++;
        WDT_SR |= WDT_SR_TIMEOUT;

        printf("[WDT] !!! 看门狗超时 !!! (第%u次超时)\n", wdt->timeout_count);

        if (wdt->reset_on_timeout) {
            RCC_CSR |= RCC_CSR_WDTRSTF;
            System_SoftwareReset();

            /* 复位后重新初始化, 但保留统计信息 */
            uint32_t saved_feed    = wdt->feed_count;
            uint32_t saved_timeout = wdt->timeout_count;
            uint32_t saved_to      = wdt->timeout_ms;
            bool     saved_rst     = wdt->reset_on_timeout;

            SoftWdt_Init(wdt, saved_to, saved_rst);

            wdt->feed_count    = saved_feed;
            wdt->timeout_count = saved_timeout;
        } else {
            printf("[WDT] 超时警告: 程序可能跑飞, 但未使能复位\n");
            wdt->counter = wdt->reload;
        }
    }
}

/* ============================================================
 * 模拟程序跑飞场景
 * ============================================================ */
static void Simulate_ProgramHang(void)
{
    printf("[APP] 模拟程序跑飞: 进入死循环, 不再喂狗...\n");
}

/* ============================================================
 * 模拟正常任务
 * ============================================================ */
static void Simulate_NormalTask(void)
{
