}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    printf("========================================\n");
    printf("  软件看门狗 (程序跑飞复位) 演示程序\n");
    printf("========================================\n\n");

    SoftWdt_Init(&g_soft_wdt, 100, true);

    printf("\n--- 阶段1: 正常运行, 定期喂狗 ---\n");
    for (int i = 0; i < 5; i++) {
        Simulate_NormalTask();
        SoftWdt_Feed(&g_soft_wdt);
        SoftWdt_Process(&g_soft_wdt, 50);
        printf("[APP] 当前看门狗剩余计数: %u\n\n", g_soft_wdt.counter);
    }

    printf("--- 阶段2: 程序跑飞, 停止喂狗 ---\n");
