#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Mock 寄存器（使用普通变量，避免非法地址访问）
 * ============================================================ */

static volatile uint32_t g_wdt_cr  = 0U;
static volatile uint32_t g_wdt_sr  = 0U;
static volatile uint32_t g_wdt_cnt = 0U;
static volatile uint32_t g_wdt_rld = 0U;

static volatile uint32_t g_pwr_sr  = 0U;
static volatile uint32_t g_pwr_cr  = 0U;

static volatile uint32_t g_rst_sr  = 0U;

static volatile uint32_t g_sys_cr  = 0U;

#define WDT_CR          (g_wdt_cr)
#define WDT_SR          (g_wdt_sr)
#define WDT_CNT         (g_wdt_cnt)
#define WDT_RLD         (g_wdt_rld)

#define PWR_SR          (g_pwr_sr)
#define PWR_CR          (g_pwr_cr)

#define RST_SR          (g_rst_sr)

#define SYS_CR          (g_sys_cr)

/* 看门狗控制寄存器位定义 */
#define WDT_CR_EN       (1U << 0)
#define WDT_CR_INTEN    (1U << 1)
#define WDT_CR_RSTEN    (1U << 2)

/* 看门狗状态寄存器位定义 */
#define WDT_SR_TIMEOUT  (1U << 0)
#define WDT_SR_PWRFAIL  (1U << 1)

/* 电源监控寄存器位定义 */
#define PWR_SR_VDD_OK   (1U << 0)
#define PWR_SR_VDD_LOW  (1U << 1)
#define PWR_SR_BOR      (1U << 2)

/* 复位原因寄存器位定义 */
#define RST_SR_WDT      (1U << 0)
#define RST_SR_POR      (1U << 1)
#define RST_SR_BOR      (1U << 2)
#define RST_SR_SW       (1U << 3)

/* 系统控制寄存器位定义 */
#define SYS_CR_SWRST    (1U << 0)

/* ============================================================
 * 常量定义
 * ============================================================ */

#define WDT_RELOAD_VALUE        0x0000FFFFU
#define PWR_FAIL_THRESHOLD      3U

/* ============================================================
 * 数据结构
 * ============================================================ */

typedef enum {
    WDT_STATE_DISABLED = 0,
    WDT_STATE_ENABLED,
    WDT_STATE_TIMEOUT,
    WDT_STATE_PWR_FAIL
} wdt_state_t;

typedef enum {
    RST_CAUSE_UNKNOWN = 0,
    RST_CAUSE_POWER_ON,
    RST_CAUSE_WATCHDOG,
    RST_CAUSE_BROWNOUT,
    RST_CAUSE_SOFTWARE
} rst_cause_t;

typedef struct {
    wdt_state_t     state;
    uint32_t        feed_counter;
    uint32_t        timeout_counter;
    uint32_t        pwr_fail_counter;
    rst_cause_t     last_rst_cause;
    bool            pwr_fail_detected;
    bool            wdt_timeout_flag;
} wdt_context_t;

/* ============================================================
 * 全局上下文
 * ============================================================ */

static wdt_context_t g_wdt_ctx;

/* ============================================================
 * 硬件抽象层函数 (Mock)
 * ============================================================ */

static void hw_wdt_enable(void)
{
    WDT_CR |= WDT_CR_EN | WDT_CR_RSTEN;
    WDT_RLD = WDT_RELOAD_VALUE;
    WDT_CNT = WDT_RELOAD_VALUE;
}

static void hw_wdt_feed(void)
{
    WDT_CNT = WDT_RELOAD_VALUE;
}

static bool hw_wdt_is_timeout(void)
{
    return (WDT_SR & WDT_SR_TIMEOUT) != 0U;
}

static void hw_wdt_clear_timeout(void)
{
    WDT_SR &= ~WDT_SR_TIMEOUT;
}

static bool hw_pwr_is_vdd_ok(void)
{
    return (PWR_SR & PWR_SR_VDD_OK) != 0U;
}

static bool hw_pwr_is_vdd_low(void)
{
    return (PWR_SR & PWR_SR_VDD_LOW) != 0U;
}

static bool hw_pwr_is_bor(void)
{
    return (PWR_SR & PWR_SR_BOR) != 0U;
}

static void hw_pwr_clear_flags(void)
{
    PWR_SR &= ~(PWR_SR_VDD_LOW | PWR_SR_BOR);
}

static uint32_t hw_rst_get_cause(void)
{
    return RST_SR;
}

static void hw_rst_clear_cause(void)
{
    RST_SR = 0U;
}

static void hw_system_reset(void)
{
    SYS_CR |= SYS_CR_SWRST;
    WDT_CR = 0U;
    WDT_SR = 0U;
    WDT_CNT = 0U;
    PWR_SR = PWR_SR_VDD_OK;
    RST_SR = RST_SR_SW;
    SYS_CR = 0U;
}

/* ============================================================
 * 看门狗驱动层
 * ============================================================ */

static rst_cause_t wdt_parse_reset_cause(uint32_t rst_reg)
{
    if (rst_reg & RST_SR_WDT) {
        return RST_CAUSE_WATCHDOG;
    }
    if (rst_reg & RST_SR_BOR) {
        return RST_CAUSE_BROWNOUT;
    }
    if (rst_reg & RST_SR_POR) {
        return RST_CAUSE_POWER_ON;
    }
    if (rst_reg & RST_SR_SW) {
        return RST_CAUSE_SOFTWARE;
    }
    return RST_CAUSE_UNKNOWN;
}

static const char *wdt_rst_cause_str(rst_cause_t cause)
{
    switch (cause) {
    case RST_CAUSE_POWER_ON:   return "Power-On Reset";
    case RST_CAUSE_WATCHDOG:   return "Watchdog Reset";
    case RST_CAUSE_BROWNOUT:   return "Brown-Out Reset";
    case RST_CAUSE_SOFTWARE:   return "Software Reset";
    default:                   return "Unknown Reset";
    }
}

static void wdt_init(void)
{
    uint32_t rst_reg;

    /* 初始化电源状态为正常 */
    PWR_SR = PWR_SR_VDD_OK;

    rst_reg = hw_rst_get_cause();
    g_wdt_ctx.last_rst_cause = wdt_parse_reset_cause(rst_reg);
    hw_rst_clear_cause();

    g_wdt_ctx.state             = WDT_STATE_DISABLED;
    g_wdt_ctx.feed_counter      = 0U;
    g_wdt_ctx.timeout_counter   = 0U;
    g_wdt_ctx.pwr_fail_counter  = 0U;
    g_wdt_ctx.pwr_fail_detected = false;
    g_wdt_ctx.wdt_timeout_flag  = false;

    hw_pwr_clear_flags();

    hw_wdt_enable();
    g_wdt_ctx.state = WDT_STATE_ENABLED;

    printf("[WDT] Init done. Last reset cause: %s\n",
           wdt_rst_cause_str(g_wdt_ctx.last_rst_cause));
}

static void wdt_feed(void)
{
    if (g_wdt_ctx.state != WDT_STATE_ENABLED) {
        return;
    }

    hw_wdt_feed();
    g_wdt_ctx.feed_counter++;
    g_wdt_ctx.timeout_counter = 0U;

    printf("[WDT] Feed #%u\n", g_wdt_ctx.feed_counter);
}

static void wdt_check_power(void)
{
    if (hw_pwr_is_vdd_low() || hw_pwr_is_bor()) {
        g_wdt_ctx.pwr_fail_counter++;
        printf("[PWR] Power fault detected! Counter = %u\n",
               g_wdt_ctx.pwr_fail_counter);

        if (g_wdt_ctx.pwr_fail_counter >= PWR_FAIL_THRESHOLD) {
            g_wdt_ctx.pwr_fail_detected = true;
            g_wdt_ctx.state = WDT_STATE_PWR_FAIL;
            printf("[PWR] Power failure confirmed! Initiating safe shutdown...\n");
        }
    } else {
        g_wdt_ctx.pwr_fail_counter = 0U;
    }
}

static void wdt_check_timeout(void)
{
    if (hw_wdt_is_timeout()) {
        g_wdt_ctx.wdt_timeout_flag = true;
        g_wdt_ctx.state = WDT_STATE_TIMEOUT;
        hw_wdt_clear_timeout();
        printf("[WDT] Timeout detected! System will reset.\n");
    }
}

static void wdt_handle_power_failure(void)
{
    if (!g_wdt_ctx.pwr_fail_detected) {
        return;
    }

    printf("[PWR] Executing power-fail handler...\n");
    printf("[PWR] Saving critical data to NVM...\n");
    printf("[PWR] Shutting down non-critical peripherals...\n");

    if (hw_pwr_is_vdd_ok()) {
        printf("[PWR] Power restored. Recovering...\n");
        g_wdt_ctx.pwr_fail_detected = false;
        g_wdt_ctx.pwr_fail_counter = 0U;
        g_wdt_ctx.state = WDT_STATE_ENABLED;
        hw_pwr_clear_flags();
    } else {
        printf("[PWR] Power not restored. Triggering system reset.\n");
        hw_system_reset();
        g_wdt_ctx.pwr_fail_detected = false;
        g_wdt_ctx.pwr_fail_counter = 0U;
        g_wdt_ctx.state = WDT_STATE_ENABLED;
    }
}

static void wdt_process(void)
{
    wdt_check_power();
    wdt_check_timeout();
    wdt_handle_power_failure();

    if (g_wdt_ctx.state == WDT_STATE_TIMEOUT) {
        printf("[WDT] Executing watchdog reset...\n");
        hw_system_reset();
        g_wdt_ctx.state = WDT_STATE_ENABLED;
        g_wdt_ctx.wdt_timeout_flag = false;
    }
}

/* ============================================================
 * 应用层任务 (Mock)
 * ============================================================ */

static void app_task(void)
{
    printf("[APP] Running application task...\n");
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    uint32_t loop_count = 0U;

    printf("========================================\n");
    printf("  Hardware Watchdog & Power Monitor\n");
    printf("========================================\n");

    wdt_init();

    for (loop_count = 0U; loop_count < 10U; loop_count++) {
        printf("\n--- Loop %u ---\n", loop_count);

        app_task();
        wdt_feed();

        if (loop_count == 5U) {
            printf("[SIM] Simulating power voltage drop...\n");
            PWR_SR |= PWR_SR_VDD_LOW;
            PWR_SR &= ~PWR_SR_VDD_OK;
        }

        if (loop_count == 7U) {
            printf("[SIM] Simulating power voltage recovery...\n");
            PWR_SR |= PWR_SR_VDD_OK;
            PWR_SR &= ~PWR_SR_VDD_LOW;
        }

        if (loop_count == 9U) {
            printf("[SIM] Simulating watchdog timeout...\n");
            WDT_SR |= WDT_SR_TIMEOUT;
        }

        wdt_process();
    }

    printf("\n========================================\n");
    printf("  Test completed.\n");
    printf("  Total feeds: %u\n", g_wdt_ctx.feed_counter);
    printf("  Final state: %d\n", (int)g_wdt_ctx.state);
    printf("========================================\n");

    return 0;
}
