#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t g_mock_estop_input_reg = 0;
static volatile uint32_t g_mock_safety_loop_reg = 0;
static volatile uint32_t g_mock_main_contactor_reg = 0;
static volatile uint32_t g_mock_pwm_enable_reg = 0;
static volatile uint32_t g_mock_fault_latch_reg = 0;

#define MOCK_ESTOP_INPUT_REG    (g_mock_estop_input_reg)
#define MOCK_SAFETY_LOOP_REG    (g_mock_safety_loop_reg)
#define MOCK_MAIN_CONTACTOR_REG (g_mock_main_contactor_reg)
#define MOCK_PWM_ENABLE_REG     (g_mock_pwm_enable_reg)
#define MOCK_FAULT_LATCH_REG    (g_mock_fault_latch_reg)

/* 位定义 */
#define ESTOP_SIGNAL_BIT        (1U << 0)
#define SAFETY_LOOP_CLOSED_BIT  (1U << 0)
#define MAIN_CONTACTOR_BIT      (1U << 0)
#define PWM_ENABLE_BIT          (1U << 0)
#define FAULT_LATCH_BIT         (1U << 0)

/* ================= 系统状态定义 ================= */
typedef enum {
    SYS_STATE_INIT = 0,
    SYS_STATE_RUNNING,
    SYS_STATE_EMERGENCY_STOP,
    SYS_STATE_FAULT_LATCHED
} SystemState_t;

/* ================= 全局变量 ================= */
static SystemState_t g_sys_state = SYS_STATE_INIT;
static uint32_t g_estop_debounce_cnt = 0;
static uint32_t g_safety_loop_debounce_cnt = 0;

#define DEBOUNCE_THRESHOLD  3U

/* ================= 硬件抽象层函数 ================= */
static inline bool hal_read_estop_signal(void)
{
    return (MOCK_ESTOP_INPUT_REG & ESTOP_SIGNAL_BIT) != 0U;
}

static inline bool hal_read_safety_loop(void)
{
    return (MOCK_SAFETY_LOOP_REG & SAFETY_LOOP_CLOSED_BIT) != 0U;
}

static inline void hal_set_main_contactor(bool on)
{
    if (on) {
        MOCK_MAIN_CONTACTOR_REG |= MAIN_CONTACTOR_BIT;
    } else {
        MOCK_MAIN_CONTACTOR_REG &= ~MAIN_CONTACTOR_BIT;
    }
}

static inline void hal_set_pwm_enable(bool on)
{
    if (on) {
        MOCK_PWM_ENABLE_REG |= PWM_ENABLE_BIT;
    } else {
        MOCK_PWM_ENABLE_REG &= ~PWM_ENABLE_BIT;
    }
}

static inline void hal_set_fault_latch(bool on)
{
    if (on) {
        MOCK_FAULT_LATCH_REG |= FAULT_LATCH_BIT;
    } else {
        MOCK_FAULT_LATCH_REG &= ~FAULT_LATCH_BIT;
    }
}

/* ================= 紧急停机控制核心逻辑 ================= */
static void emergency_stop_control(void)
{
    bool estop_active = hal_read_estop_signal();
    bool safety_loop_closed = hal_read_safety_loop();

    /* 急停信号去抖 */
    if (estop_active) {
        if (g_estop_debounce_cnt < DEBOUNCE_THRESHOLD) {
            g_estop_debounce_cnt++;
        }
    } else {
        g_estop_debounce_cnt = 0;
    }

    /* 安全回路去抖 */
    if (!safety_loop_closed) {
        if (g_safety_loop_debounce_cnt < DEBOUNCE_THRESHOLD) {
            g_safety_loop_debounce_cnt++;
        }
    } else {
        g_safety_loop_debounce_cnt = 0;
    }

    bool estop_confirmed = (g_estop_debounce_cnt >= DEBOUNCE_THRESHOLD);
    bool safety_loop_open_confirmed = (g_safety_loop_debounce_cnt >= DEBOUNCE_THRESHOLD);

    /* 故障锁存状态：只有急停信号消失且安全回路恢复闭合后才能复位 */
    if (g_sys_state == SYS_STATE_FAULT_LATCHED) {
        if (!estop_active && safety_loop_closed) {
            hal_set_fault_latch(false);
            g_sys_state = SYS_STATE_INIT;
            printf("[ESTOP] Fault latch cleared, system re-initialized.\n");
        } else {
            /* 保持安全输出断开 */
            hal_set_main_contactor(false);
            hal_set_pwm_enable(false);
            return;
        }
    }

    /* 紧急停机触发条件：急停信号有效 或 安全回路断开 */
    if (estop_confirmed || safety_loop_open_confirmed) {
        /* 立即切断主接触器和 PWM 使能 */
        hal_set_main_contactor(false);
        hal_set_pwm_enable(false);
        hal_set_fault_latch(true);
        g_sys_state = SYS_STATE_FAULT_LATCHED;
        printf("[ESTOP] EMERGENCY STOP TRIGGERED! estop=%d safety_loop=%d\n",
               (int)estop_active, (int)safety_loop_closed);
        return;
    }

    /* 正常状态：允许输出 */
    if (g_sys_state == SYS_STATE_INIT || g_sys_state == SYS_STATE_RUNNING) {
        hal_set_main_contactor(true);
        hal_set_pwm_enable(true);
        g_sys_state = SYS_STATE_RUNNING;
    }
}

