/* ===== Mock 寄存器定义 ===== */
#define PERIPH_BASE        0x40000000UL
#define APB2PERIPH_BASE    (PERIPH_BASE + 0x10000UL)
#define TIM1_BASE          (APB2PERIPH_BASE + 0x2C00UL)

/* 定时器寄存器结构体 */
typedef struct {
    volatile uint32_t CR1;      /* 0x00 控制寄存器1 */
    volatile uint32_t CR2;      /* 0x04 控制寄存器2 */
    volatile uint32_t SMCR;     /* 0x08 从模式控制寄存器 */
    volatile uint32_t DIER;     /* 0x0C DMA/中断使能寄存器 */
    volatile uint32_t SR;       /* 0x10 状态寄存器 */
    volatile uint32_t EGR;      /* 0x14 事件产生寄存器 */
    volatile uint32_t CCMR1;    /* 0x18 捕获/比较模式寄存器1 */
    volatile uint32_t CCMR2;    /* 0x1C 捕获/比较模式寄存器2 */
    volatile uint32_t CCER;     /* 0x20 捕获/比较使能寄存器 */
    volatile uint32_t CNT;      /* 0x24 计数器 */
    volatile uint32_t PSC;      /* 0x28 预分频器 */
    volatile uint32_t ARR;      /* 0x2C 自动重装载寄存器 */
    volatile uint32_t RCR;      /* 0x30 重复计数器寄存器 */
    volatile uint32_t CCR1;     /* 0x34 捕获/比较寄存器1 */
    volatile uint32_t CCR2;     /* 0x38 捕获/比较寄存器2 */
    volatile uint32_t CCR3;     /* 0x3C 捕获/比较寄存器3 */
    volatile uint32_t CCR4;     /* 0x40 捕获/比较寄存器4 */
    volatile uint32_t BDTR;     /* 0x44 刹车和死区寄存器 */
    volatile uint32_t DCR;      /* 0x48 DMA控制寄存器 */
    volatile uint32_t DMAR;     /* 0x4C DMA连续模式地址寄存器 */
} TIM_TypeDef;

/* 使用静态实例代替硬编码地址, 避免访问非法内存 */
static TIM_TypeDef tim1_instance;
#define TIM1    (&tim1_instance)

/* ===== 位定义 ===== */
/* CR1 */
#define TIM_CR1_CEN         (1U << 0)
#define TIM_CR1_ARPE        (1U << 7)

/* CCMR1 */
#define TIM_CCMR1_OC1M_Pos  4
#define TIM_CCMR1_OC1M_Msk  (7U << TIM_CCMR1_OC1M_Pos)
#define TIM_CCMR1_OC1PE     (1U << 3)
#define TIM_CCMR1_OC2M_Pos  12
#define TIM_CCMR1_OC2M_Msk  (7U << TIM_CCMR1_OC2M_Pos)
#define TIM_CCMR1_OC2PE     (1U << 11)

/* CCER */
#define TIM_CCER_CC1E       (1U << 0)
#define TIM_CCER_CC1P       (1U << 1)
#define TIM_CCER_CC1NE      (1U << 2)
#define TIM_CCER_CC1NP      (1U << 3)
#define TIM_CCER_CC2E       (1U << 4)
#define TIM_CCER_CC2P       (1U << 5)
#define TIM_CCER_CC2NE      (1U << 6)
#define TIM_CCER_CC2NP      (1U << 7)

/* BDTR */
#define TIM_BDTR_MOE        (1U << 15)
#define TIM_BDTR_OSSR       (1U << 11)
#define TIM_BDTR_OSSI       (1U << 10)
#define TIM_BDTR_DTG_Pos    0
#define TIM_BDTR_DTG_Msk    (0xFFU << TIM_BDTR_DTG_Pos)

/* EGR */
#define TIM_EGR_UG          (1U << 0)

/* ===== 配置参数 ===== */
#define PWM_FREQ_HZ         20000U      /* PWM 频率 20kHz */
#define SYSTEM_CLOCK_HZ     72000000U   /* 系统时钟 72MHz */
#define PWM_DUTY_A          0.5f        /* 通道A占空比 50% */
#define PWM_DUTY_B          0.3f        /* 通道B占空比 30% */
#define DEAD_TIME_NS        500U        /* 死区时间 500ns */

/* ===== 辅助函数 ===== */
static uint32_t compute_prescaler(uint32_t sys_clk, uint32_t pwm_freq, uint32_t *arr)
{
    uint32_t psc;
    uint32_t denom;

    *arr = 999U;
    denom = pwm_freq * (*arr + 1U);
    if (denom == 0U) {
        return 0U;
    }
    psc = sys_clk / denom;
    if (psc > 0U) {
        psc -= 1U;
    }
    return psc;
}

static uint32_t compute_dead_time(uint32_t sys_clk, uint32_t dead_ns)
{
    uint32_t dtg;
    uint64_t ticks = ((uint64_t)sys_clk * (uint64_t)dead_ns) / 1000000000ULL;
    if (ticks > 255U) {
        ticks = 255U;
    }
    dtg = (uint32_t)ticks;
    return dtg & TIM_BDTR_DTG_Msk;
}

/* ===== 高级定时器 PWM 互补输出初始化 ===== */
static void TIM1_PWM_Complementary_Init(void)
{
    uint32_t arr = 0U;
    uint32_t psc;
    uint32_t ccr1;
    uint32_t ccr2;
    uint32_t dtg;

    /* 1. 计算分频与重装载值 */
    psc = compute_prescaler(SYSTEM_CLOCK_HZ, PWM_FREQ_HZ, &arr);
    ccr1 = (uint32_t)((float)(arr + 1U) * PWM_DUTY_A);
    ccr2 = (uint32_t)((float)(arr + 1U) * PWM_DUTY_B);
    dtg  = compute_dead_time(SYSTEM_CLOCK_HZ, DEAD_TIME_NS);

    /* 2. 配置时基: PSC, ARR, 自动重装载预装载 */
    TIM1->PSC = psc;
    TIM1->ARR = arr;
    TIM1->RCR = 0U;
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* 3. 配置通道1 PWM 模式1 (OC1M = 110), 使能预装载 */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos);
    TIM1->CCMR1 |= TIM_CCMR1_OC1PE;

    /* 4. 配置通道2 PWM 模式1 (OC2M = 110), 使能预装载 */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC2M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC2M_Pos);
    TIM1->CCMR1 |= TIM_CCMR1_OC2PE;

    /* 5. 设置比较值 */
    TIM1->CCR1 = ccr1;
    TIM1->CCR2 = ccr2;

    /* 6. 使能通道1 及其互补输出, 高电平有效 */
    TIM1->CCER |= TIM_CCER_CC1E;
    TIM1->CCER |= TIM_CCER_CC1NE;
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER &= ~TIM_CCER_CC1NP;

    /* 7. 使能通道2 及其互补输出, 高电平有效 */
    TIM1->CCER |= TIM_CCER_CC2E;
    TIM1->CCER |= TIM_CCER_CC2NE;
    TIM1->CCER &= ~TIM_CCER_CC2P;
    TIM1->CCER &= ~TIM_CCER_CC2NP;

    /* 8. 配置死区时间, 使能主输出 */
    TIM1->BDTR &= ~TIM_BDTR_DTG_Msk;
    TIM1->BDTR |= dtg;
    TIM1->BDTR |= TIM_BDTR_OSSR;
    TIM1->BDTR |= TIM_BDTR_OSSI;
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 9. 产生更新事件, 加载预装载寄存器 */
    TIM1->EGR |= TIM_EGR_UG;

    /* 10. 使能定时器 */
    TIM1->CR1 |= TIM_CR1_CEN;
}

/* ===== 打印寄存器状态 ===== */
static void print_tim1_registers(void)
{
