/* ============================================================
 * Mock 寄存器定义（替代 STM32 硬件头文件）
 * 使用静态变量模拟寄存器，避免非法地址访问
 * ============================================================ */

static uint32_t reg_TIM1_CR1   = 0;
static uint32_t reg_TIM1_CCMR1 = 0;
static uint32_t reg_TIM1_CCMR2 = 0;
static uint32_t reg_TIM1_CCER  = 0;
static uint32_t reg_TIM1_BDTR  = 0;
static uint32_t reg_TIM1_PSC   = 0;
static uint32_t reg_TIM1_ARR   = 0;
static uint32_t reg_TIM1_CCR1  = 0;
static uint32_t reg_TIM1_CCR2  = 0;
static uint32_t reg_TIM1_CCR3  = 0;
static uint32_t reg_TIM1_CCR4  = 0;

#define TIM1_CR1    (reg_TIM1_CR1)
#define TIM1_CCMR1  (reg_TIM1_CCMR1)
#define TIM1_CCMR2  (reg_TIM1_CCMR2)
#define TIM1_CCER   (reg_TIM1_CCER)
#define TIM1_BDTR   (reg_TIM1_BDTR)
#define TIM1_PSC    (reg_TIM1_PSC)
#define TIM1_ARR    (reg_TIM1_ARR)
#define TIM1_CCR1   (reg_TIM1_CCR1)
#define TIM1_CCR2   (reg_TIM1_CCR2)
#define TIM1_CCR3   (reg_TIM1_CCR3)
#define TIM1_CCR4   (reg_TIM1_CCR4)

/* CR1 位定义 */
#define TIM_CR1_CEN         (1U << 0)
#define TIM_CR1_ARPE        (1U << 7)

/* CCMR1 位定义 */
#define TIM_CCMR1_OC1M_PWM1 (0x6U << 4)
#define TIM_CCMR1_OC1PE     (1U << 3)
#define TIM_CCMR1_OC2M_PWM1 (0x6U << 12)
#define TIM_CCMR1_OC2PE     (1U << 11)

/* CCER 位定义 */
#define TIM_CCER_CC1E       (1U << 0)
#define TIM_CCER_CC1P       (1U << 1)
#define TIM_CCER_CC1NE      (1U << 2)
#define TIM_CCER_CC1NP      (1U << 3)
#define TIM_CCER_CC2E       (1U << 4)
#define TIM_CCER_CC2P       (1U << 5)
#define TIM_CCER_CC2NE      (1U << 6)
#define TIM_CCER_CC2NP      (1U << 7)

/* BDTR 位定义 */
#define TIM_BDTR_DTG_MASK   (0xFFU << 0)
#define TIM_BDTR_LOCK_MASK  (0x3U << 8)
#define TIM_BDTR_OSSI        (1U << 10)
#define TIM_BDTR_OSSR        (1U << 11)
#define TIM_BDTR_BKE         (1U << 12)
#define TIM_BDTR_BKP         (1U << 13)
#define TIM_BDTR_AOE         (1U << 14)
#define TIM_BDTR_MOE         (1U << 15)

/* ============================================================
 * 死区时间配置参数
 * ============================================================ */

#define TIM_CLK_HZ          72000000UL
#define DEADTIME_NS         1000U
#define PWM_FREQ_HZ         20000UL

/* ============================================================
 * 死区时间计算函数
 * ============================================================ */
static uint8_t calc_deadtime_dtg(uint32_t deadtime_ns)
{
    uint32_t t_dts_ns;
    uint32_t dt_ticks;
    uint8_t  dtg = 0;

    t_dts_ns = 1000000000UL / TIM_CLK_HZ;
    if (t_dts_ns == 0) {
        t_dts_ns = 1;
    }

    dt_ticks = (deadtime_ns + t_dts_ns - 1) / t_dts_ns;

    if (dt_ticks < 128U) {
        dtg = (uint8_t)dt_ticks;
    } else if (dt_ticks < 256U) {
        uint32_t val = (dt_ticks / 2U) - 64U;
        if (val > 63U) {
            val = 63U;
        }
        dtg = (uint8_t)(0x80U | val);
    } else if (dt_ticks < 512U) {
        uint32_t val = (dt_ticks / 8U) - 32U;
        if (val > 31U) {
            val = 31U;
        }
        dtg = (uint8_t)(0xC0U | val);
    } else {
        uint32_t val = (dt_ticks / 16U) - 32U;
        if (val > 31U) {
            val = 31U;
        }
        dtg = (uint8_t)(0xE0U | val);
    }

    return dtg;
}

/* ============================================================
 * 死区时间反算函数
 * ============================================================ */
static uint32_t calc_deadtime_ns(uint8_t dtg)
{
    uint32_t t_dts_ns = 1000000000UL / TIM_CLK_HZ;
    uint32_t dt_ns;

    if ((dtg & 0x80U) == 0x00U) {
        dt_ns = (uint32_t)(dtg & 0x7FU) * t_dts_ns;
    } else if ((dtg & 0xC0U) == 0x80U) {
        dt_ns = (64U + (uint32_t)(dtg & 0x3FU)) * 2U * t_dts_ns;
    } else if ((dtg & 0xE0U) == 0xC0U) {
        dt_ns = (32U + (uint32_t)(dtg & 0x1FU)) * 8U * t_dts_ns;
    } else {
        dt_ns = (32U + (uint32_t)(dtg & 0x1FU)) * 16U * t_dts_ns;
    }

    return dt_ns;
}

/* ============================================================
 * 定时器 PWM + 死区初始化
 * ============================================================ */
static void tim1_pwm_deadtime_init(uint32_t pwm_freq_hz, uint32_t deadtime_ns)
{
    uint32_t arr;
    uint32_t ccr;
    uint8_t  dtg;

    if (pwm_freq_hz == 0) {
        pwm_freq_hz = 1;
    }

    arr = (TIM_CLK_HZ / pwm_freq_hz) - 1U;
    ccr = (arr + 1U) / 2U;
    dtg = calc_deadtime_dtg(deadtime_ns);

    TIM1_PSC = 0;
    TIM1_ARR = arr;
    TIM1_CR1 = TIM_CR1_ARPE;

    TIM1_CCMR1 &= ~(0x7U << 4);
    TIM1_CCMR1 |= TIM_CCMR1_OC1M_PWM1 | TIM_CCMR1_OC1PE;

    TIM1_CCMR1 &= ~(0x7U << 12);
    TIM1_CCMR1 |= TIM_CCMR1_OC2M_PWM1 | TIM_CCMR1_OC2PE;

    TIM1_CCR1 = ccr;
    TIM1_CCR2 = ccr;

    TIM1_CCER |= TIM_CCER_CC1E | TIM_CCER_CC1NE;
    TIM1_CCER |= TIM_CCER_CC2E | TIM_CCER_CC2NE;

    TIM1_BDTR &= ~TIM_BDTR_DTG_MASK;
    TIM1_BDTR |= (uint32_t)dtg;

    TIM1_BDTR |= TIM_BDTR_AOE | TIM_BDTR_MOE;

    TIM1_CR1 |= TIM_CR1_CEN;
}

/* ============================================================
 * 动态调整死区时间
 * ============================================================ */
static void tim1_set_deadtime(uint32_t deadtime_ns)
{
    uint8_t dtg = calc_deadtime_dtg(deadtime_ns);

    TIM1_BDTR &= ~TIM_BDTR_DTG_MASK;
    TIM1_BDTR |= (uint32_t)dtg;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    uint32_t test_deadtimes[] = { 100, 500, 1000, 2000, 5000, 10000 };
    int i;
    int n;

    printf("========================================\n");
    printf(" STM32 TIM1 PWM Dead-Time Config Demo\n");
    printf("========================================\n");
    printf("TIM Clock   : %lu Hz\n", (unsigned long)TIM_CLK_HZ);
    printf("PWM Freq    : %lu Hz\n", (unsigned long)PWM_FREQ_HZ);
    printf("tDTS        : %lu ns\n", (unsigned long)(1000000000UL / TIM_CLK_HZ));
    printf("----------------------------------------\n");

    tim1_pwm_deadtime_init(PWM_FREQ_HZ, DEADTIME_NS);

    printf("Initial Config:\n");
    printf("  PSC   = %lu\n", (unsigned long)TIM1_PSC);
    printf("  ARR   = %lu\n", (unsigned long)TIM1_ARR);
