#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t g_reg_ctrl = 0;
static volatile uint32_t g_reg_status = 0;
static volatile uint32_t g_reg_data = 0;
static volatile uint32_t g_reg_err_code = 0;

#define MOCK_REG_CTRL           (g_reg_ctrl)
#define MOCK_REG_STATUS         (g_reg_status)
#define MOCK_REG_DATA           (g_reg_data)
#define MOCK_REG_ERR_CODE       (g_reg_err_code)

#define CTRL_ENABLE             (1U << 0)
#define CTRL_RESET              (1U << 1)
#define CTRL_MODE_A             (0U << 2)
#define CTRL_MODE_B             (1U << 2)
#define CTRL_MODE_C             (2U << 2)
#define CTRL_MODE_MASK          (3U << 2)

#define STATUS_READY            (1U << 0)
#define STATUS_BUSY             (1U << 1)
#define STATUS_FAULT            (1U << 2)
#define STATUS_TIMEOUT          (1U << 3)

#define ERR_NONE                0x00U
#define ERR_COMM                0x01U
#define ERR_TIMEOUT             0x02U
#define ERR_CRC                 0x03U
#define ERR_OVERRUN             0x04U
#define ERR_UNKNOWN             0xFFU

/* ================= 故障自恢复配置 ================= */
#define MAX_RETRY_COUNT         3U
#define MAX_RESET_COUNT         2U
#define MAX_MODE_SWITCH_COUNT   2U
#define RECOVERY_DELAY_MS       1U

typedef enum {
    MODE_A = 0,
    MODE_B = 1,
    MODE_C = 2,
    MODE_INVALID = 3
} work_mode_t;

typedef enum {
    RECOVERY_NONE = 0,
    RECOVERY_RETRY,
    RECOVERY_RESET,
    RECOVERY_SWITCH_MODE,
    RECOVERY_FAILED
} recovery_action_t;

typedef struct {
    work_mode_t current_mode;
    uint32_t retry_count;
    uint32_t reset_count;
    uint32_t mode_switch_count;
    uint32_t last_error;
    bool     in_recovery;
} recovery_ctx_t;

/* ================= 模拟硬件操作函数 ================= */
static void mock_hw_init(void)
{
    MOCK_REG_CTRL = 0;
    MOCK_REG_STATUS = STATUS_READY;
    MOCK_REG_DATA = 0;
    MOCK_REG_ERR_CODE = ERR_NONE;
}

static void mock_delay_ms(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 1000U; i++) {
        /* 空循环 */
    }
}

static bool mock_hw_is_ready(void)
{
    return (MOCK_REG_STATUS & STATUS_READY) != 0U;
}

static uint32_t mock_hw_get_error(void)
{
    return MOCK_REG_ERR_CODE;
}

static void mock_hw_clear_fault(void)
{
    MOCK_REG_STATUS &= ~(STATUS_FAULT | STATUS_TIMEOUT);
    MOCK_REG_ERR_CODE = ERR_NONE;
}

static void mock_hw_set_mode(work_mode_t mode)
{
    uint32_t ctrl = MOCK_REG_CTRL;
    ctrl &= ~CTRL_MODE_MASK;
    switch (mode) {
        case MODE_A: ctrl |= CTRL_MODE_A; break;
        case MODE_B: ctrl |= CTRL_MODE_B; break;
        case MODE_C: ctrl |= CTRL_MODE_C; break;
        default: break;
    }
    MOCK_REG_CTRL = ctrl;
}

static void mock_hw_reset(void)
{
    MOCK_REG_CTRL |= CTRL_RESET;
    mock_delay_ms(1);
    MOCK_REG_CTRL &= ~CTRL_RESET;
    mock_hw_clear_fault();
    MOCK_REG_STATUS = STATUS_READY;
}

/* 模拟一次数据操作，可能成功或失败 */
static bool mock_hw_operation(uint32_t *out_data)
{
    static uint32_t call_count = 0;
    call_count++;

    if (out_data == NULL) {
        return false;
    }

    /* 模拟前几次操作失败，用于测试恢复逻辑 */
    if (call_count <= 2U) {
        MOCK_REG_STATUS = STATUS_FAULT;
        MOCK_REG_ERR_CODE = ERR_COMM;
        return false;
    }
    if (call_count == 3U) {
        MOCK_REG_STATUS = STATUS_FAULT;
        MOCK_REG_ERR_CODE = ERR_TIMEOUT;
        return false;
    }
    if (call_count == 4U) {
        MOCK_REG_STATUS = STATUS_FAULT;
        MOCK_REG_ERR_CODE = ERR_CRC;
        return false;
    }

    MOCK_REG_STATUS = STATUS_READY;
    MOCK_REG_ERR_CODE = ERR_NONE;
    *out_data = 0x12345678U + call_count;
    return true;
}

/* ================= 故障自恢复核心逻辑 ================= */

static void recovery_init(recovery_ctx_t *ctx, work_mode_t init_mode)
{
    if (ctx == NULL) {
        return;
    }
    ctx->current_mode = init_mode;
    ctx->retry_count = 0;
    ctx->reset_count = 0;
    ctx->mode_switch_count = 0;
    ctx->last_error = ERR_NONE;
    ctx->in_recovery = false;
}

static void recovery_reset_counters(recovery_ctx_t *ctx)
{
    if (ctx == NULL) {
        return;
    }
    ctx->retry_count = 0;
    ctx->reset_count = 0;
    ctx->mode_switch_count = 0;
    ctx->last_error = ERR_NONE;
    ctx->in_recovery = false;
}

static recovery_action_t recovery_decide_action(recovery_ctx_t *ctx, uint32_t error)
{
    if (ctx == NULL) {
        return RECOVERY_FAILED;
    }

    ctx->last_error = error;

    if (error == ERR_COMM || error == ERR_CRC || error == ERR_OVERRUN) {
        if (ctx->retry_count < MAX_RETRY_COUNT) {
            ctx->retry_count++;
            return RECOVERY_RETRY;
        }
    }

    if (ctx->reset_count < MAX_RESET_COUNT) {
        ctx->reset_count++;
        return RECOVERY_RESET;
    }

    if (ctx->mode_switch_count < MAX_MODE_SWITCH_COUNT) {
        ctx->mode_switch_count++;
        return RECOVERY_SWITCH_MODE;
    }

    return RECOVERY_FAILED;
}

static bool recovery_execute_action(recovery_ctx_t *ctx, recovery_action_t action)
{
    if (ctx == NULL) {
        return false;
    }

    ctx->in_recovery = true;

    switch (action) {
        case RECOVERY_RETRY:
            printf("[RECOVERY] 执行重试 (第 %u/%u 次), 错误码=0x%02X\n",
                   ctx->retry_count, MAX_RETRY_COUNT, ctx->last_error);
            mock_delay_ms(RECOVERY_DELAY_MS);
            mock_hw_clear_fault();
            break;

        case RECOVERY_RESET:
            printf("[RECOVERY] 执行复位 (第 %u/%u 次), 错误码=0x%02X\n",
                   ctx->reset_count, MAX_RESET_COUNT, ctx->last_error);
            mock_hw_reset();
            mock_delay_ms(RECOVERY_DELAY_MS);
            break;

        case RECOVERY_SWITCH_MODE: {
            work_mode_t new_mode;
            printf("[RECOVERY] 执行模式切换 (第 %u/%u 次), 错误码=0x%02X\n",
                   ctx->mode_switch_count, MAX_MODE_SWITCH_COUNT, ctx->last_error);

            new_mode = (work_mode_t)((ctx->current_mode + 1U) % 3U);
            mock_hw_set_mode(new_mode);
            ctx->current_mode = new_mode;
            printf("[RECOVERY] 模式已切换至 MODE_%c\n", 'A' + (char)new_mode);

            mock_delay_ms(RECOVERY_DELAY_MS);
            mock_hw_clear_fault();
            break;
        }

        case RECOVERY_FAILED:
        default:
            printf("[RECOVERY] 所有恢复策略已耗尽，进入安全状态\n");
            ctx->in_recovery = false;
            return false;
    }

    ctx->in_recovery = false;
    return true;
}

/* 带故障自恢复的数据操作主流程 */
static bool safe_operation(recovery_ctx_t *ctx, uint32_t *out_data)
{
    uint32_t data = 0;
    bool success = false;
    uint32_t error;
    uint32_t loop_guard = 0;

    if (ctx == NULL || out_data == NULL) {
        return false;
    }

    if (!mock_hw_is_ready()) {
        recovery_action_t action;
        printf("[MAIN] 硬件未就绪，尝试恢复...\n");
        action = recovery_decide_action(ctx, ERR_UNKNOWN);
        if (!recovery_execute_action(ctx, action)) {
            return false;
        }
    }

    success = mock_hw_operation(&data);

    if (success) {
        *out_data = data;
        recovery_reset_counters(ctx);
        printf("[MAIN] 操作成功, 数据=0x%08X\n", data);
        return true;
    }

    error = mock_hw_get_error();
    printf("[MAIN] 操作失败, 错误码=0x%02X, 启动恢复流程...\n", error);

    while (loop_guard < 32U) {
        recovery_action_t action;
        loop_guard++;

        action = recovery_decide_action(ctx, error);

        if (action == RECOVERY_FAILED) {
            printf("[MAIN] 恢复失败，放弃操作\n");
            return false;
        }

        if (!recovery_execute_action(ctx, action)) {
            return false;
        }

        success = mock_hw_operation(&data);
        if (success) {
            *out_data = data;
            recovery_reset_counters(ctx);
            printf("[MAIN] 恢复后操作成功, 数据=0x%08X\n", data);
            return true;
        }

        error = mock_hw_get_error();
        printf("[MAIN] 恢复后仍失败, 错误码=0x%02X\n", error);
    }

    printf("[MAIN] 恢复循环达到上限，放弃操作\n");
    return false;
}

/* ================= 主函数 ================= */
int main(void)
{
    recovery_ctx_t ctx;
    uint32_t result = 0;
    int i;

    printf("========================================\n");
    printf("  故障自恢复(重试/复位/切换模式)演示\n");
    printf("========================================\n\n");

    mock_hw_init();
    recovery_init(&ctx, MODE_A);
    mock_hw_set_mode(MODE_A);

    printf("[INIT] 硬件初始化完成, 当前模式=MODE_%c\n\n", 'A' + (char)ctx.current_mode);

    for (i = 0; i < 6; i++) {
        printf("---------- 第 %d 次操作 ----------\n", i + 1);

        if (safe_operation(&ctx, &result)) {
            printf("[RESULT] 操作成功, 结果=0x%08X\n", result);
        } else {
            printf("[RESULT] 操作失败, 已进入安全状态\n");
        }

        printf("[STATE] 模式=%c, 重试=%u, 复位=%u, 切换=%u\n\n",
               'A' + (char)ctx.current_mode,
               ctx.retry_count,
               ctx.reset_count,
               ctx.mode_switch_count);
    }

    printf("========================================\n");
    printf("  演示结束\n");
    printf("========================================\n");

    return 0;
}
