/* ===== Mock STM32 寄存器定义（使用普通变量模拟，避免非法地址访问） ===== */
static volatile uint32_t mock_RCC_APB2ENR = 0;
static volatile uint32_t mock_GPIOA_CRL    = 0;
static volatile uint32_t mock_ADC1_CR1     = 0;
static volatile uint32_t mock_ADC1_CR2     = 0;
static volatile uint32_t mock_ADC1_SQR1    = 0;
static volatile uint32_t mock_ADC1_SQR3    = 0;
static volatile uint32_t mock_ADC1_SMPR2   = 0;
static volatile uint32_t mock_ADC1_DR      = 0;
static volatile uint32_t mock_ADC1_SR      = 0;

#define RCC_APB2ENR   (mock_RCC_APB2ENR)
#define GPIOA_CRL     (mock_GPIOA_CRL)
#define ADC1_CR1      (mock_ADC1_CR1)
#define ADC1_CR2      (mock_ADC1_CR2)
#define ADC1_SQR1     (mock_ADC1_SQR1)
#define ADC1_SQR3     (mock_ADC1_SQR3)
#define ADC1_SMPR2    (mock_ADC1_SMPR2)
#define ADC1_DR       (mock_ADC1_DR)
#define ADC1_SR       (mock_ADC1_SR)

#define RCC_APB2ENR_ADC1EN  (1U << 9)
#define RCC_APB2ENR_IOPAEN  (1U << 2)

#define GPIOA_CRL_MODE0  (0x3U << 0)
#define GPIOA_CRL_CNF0   (0x1U << 2)

#define ADC_CR1_EOCIE       (1U << 5)
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_CAL         (1U << 2)
#define ADC_CR2_RSTCAL      (1U << 3)
#define ADC_CR2_EXTTRIG     (1U << 20)
#define ADC_CR2_SWSTART     (1U << 22)
#define ADC_SR_EOC          (1U << 1)

#define ADC_SMPR2_SMP0_7    (0x7U << 0)

/* ===== 简单延时函数 ===== */
static void delay_loop(volatile uint32_t count)
{
    while (count--) {
        __asm__ volatile ("nop");
    }
}

/* ===== 模拟 ADC 转换：产生一个伪随机采样值 ===== */
static uint32_t mock_adc_convert(void)
{
    static uint32_t seed = 12345u;
    seed = seed * 1103515245u + 12345u;
    return (seed >> 16) & 0x0FFFu;   /* 12-bit 范围 0..4095 */
}

/* ===== ADC1 初始化：单通道(通道0/PA0)，软件触发，单次转换 ===== */
static void adc1_init(void)
{
    /* 使能 GPIOA 和 ADC1 时钟 */
    RCC_APB2ENR |= RCC_APB2ENR_IOPAEN;
    RCC_APB2ENR |= RCC_APB2ENR_ADC1EN;

    /* PA0 配置为模拟输入 */
    GPIOA_CRL &= ~(GPIOA_CRL_MODE0 | GPIOA_CRL_CNF0);

    /* ADC 校准（mock 中直接清除标志） */
    ADC1_CR2 |= ADC_CR2_ADON;
    delay_loop(1000);
    ADC1_CR2 |= ADC_CR2_RSTCAL;
    ADC1_CR2 &= ~ADC_CR2_RSTCAL;
    ADC1_CR2 |= ADC_CR2_CAL;
    ADC1_CR2 &= ~ADC_CR2_CAL;

    /* 单通道转换：规则序列长度 = 1 */
    ADC1_SQR1 &= ~(0xFU << 20);

    /* 规则序列第 1 个转换 = 通道 0 */
    ADC1_SQR3 &= ~(0x1FU << 0);

    /* 采样时间：通道 0 使用 55.5 周期 */
    ADC1_SMPR2 &= ~ADC_SMPR2_SMP0_7;
    ADC1_SMPR2 |= (0x5U << 0);

    /* 不使用外部触发，软件触发，单次转换 */
    ADC1_CR2 &= ~ADC_CR2_EXTTRIG;

    /* 使能 EOC 中断标志（可选，这里仅用于轮询） */
    ADC1_CR1 |= ADC_CR1_EOCIE;

    /* 再次使能 ADC */
    ADC1_CR2 |= ADC_CR2_ADON;
}

/* ===== 软件触发单次转换并读取结果 ===== */
static uint16_t adc1_read(void)
{
    /* 启动软件转换 */
    ADC1_CR2 |= ADC_CR2_SWSTART;

    /* mock：直接产生一个采样值并置 EOC */
    ADC1_DR = mock_adc_convert();
    ADC1_SR |= ADC_SR_EOC;

    /* 等待转换完成 */
    while (!(ADC1_SR & ADC_SR_EOC)) { }

    /* 读取结果（读 DR 自动清除 EOC） */
    uint16_t value = (uint16_t)(ADC1_DR & 0xFFFFU);
    ADC1_SR &= ~ADC_SR_EOC;
    return value;
}

/* ===== 主函数 ===== */
int main(void)
{
    uint16_t adc_value;
    float voltage;

    printf("STM32 ADC1 single-channel sampling (software trigger, single conversion)\n");

    adc1_init();

    for (int i = 0; i < 5; i++) {
        adc_value = adc1_read();
        voltage = (float)adc_value * 3.3f / 4095.0f;
        printf("Sample %d: ADC = %4u, Voltage = %.3f V\n", i + 1, adc_value, voltage);
        delay_loop(100000);
    }

    printf("ADC sampling finished.\n");
    return 0;
}
