    GPIOA_CRL |= 0x00000000U;
    printf("[GPIO] PA0~PA3 configured as analog input\n");
}

/* ==================== DMA 初始化 ==================== */
static void adc_dma_init(void)
{
    RCC_AHBENR |= RCC_AHBENR_DMA1EN;

    DMA1_IFCR |= (DMA_ISR_GIF1 | DMA_ISR_TCIF1 | DMA_ISR_HTIF1 | DMA_ISR_TEIF1);
    DMA1_CCR1 &= ~DMA_CCR1_EN;

    DMA1_CPAR1  = (uint32_t)(uintptr_t)(&ADC1_DR);
    DMA1_CMAR1  = (uint32_t)(uintptr_t)adc_dma_buffer;
    DMA1_CNDTR1 = ADC_BUFFER_SIZE;

    DMA1_CCR1 = DMA_CCR1_DIR
              | DMA_CCR1_CIRC
              | DMA_CCR1_MINC
              | DMA_CCR1_PSIZE_16BIT
              | DMA_CCR1_MSIZE_16BIT
              | DMA_CCR1_PL_HIGH
              | DMA_CCR1_TCIE
              | DMA_CCR1_HTIE;

    DMA1_CCR1 |= DMA_CCR1_EN;

    printf("[DMA] DMA1 Channel1 configured: %u transfers, circular mode\n",
           (unsigned)ADC_BUFFER_SIZE);
}

/* ==================== ADC 配置 ==================== */
static void adc_config(void)
{
    RCC_APB2ENR |= RCC_APB2ENR_ADC1EN;

    ADC1_CR2 |= ADC_CR2_RSTCAL;
    ADC1_CR2 &= ~ADC_CR2_RSTCAL;

    ADC1_CR2 |= ADC_CR2_ADON;
    mock_delay(1000);

    ADC1_CR2 |= ADC_CR2_CAL;
    ADC1_CR2 &= ~ADC_CR2_CAL;

    ADC1_SMPR2 &= ~(0x3FU);
    ADC1_SMPR2 |= (0x05U << 0)
               |  (0x05U << 3)
               |  (0x05U << 6)
               |  (0x05U << 9);

    ADC1_SQR1 &= ~(0xFU << 20);
    ADC1_SQR1 |= (3U << 20);

    ADC1_SQR3 &= ~(0x1FU << 0);
    ADC1_SQR3 |= (0U << 0);

    ADC1_SQR3 &= ~(0x1FU << 5);
    ADC1_SQR3 |= (1U << 5);

    ADC1_SQR3 &= ~(0x1FU << 10);
    ADC1_SQR3 |= (2U << 10);

    ADC1_SQR3 &= ~(0x1FU << 15);
    ADC1_SQR3 |= (3U << 15);

    ADC1_CR1 |= ADC_CR1_SCAN;
    ADC1_CR2 |= ADC_CR2_CONT;
    ADC1_CR2 |= ADC_CR2_DMA;

    printf("[ADC] ADC1 configured: 4 channels (CH0~CH3), scan + continuous + DMA\n");
}

/* ==================== 启动 ADC 转换 ==================== */
static void adc_start_conversion(void)
{
    ADC1_CR2 |= ADC_CR2_EXTTRIG;
    ADC1_CR2 &= ~(0x7U << 17);
    ADC1_CR2 |= ADC_CR2_EXTSEL_SWSTART;
    ADC1_CR2 |= ADC_CR2_SWSTART;

    printf("[ADC] Conversion started (software trigger)\n");
}

/* ==================== 处理 DMA 数据 ==================== */
static void adc_dma_process_data(void)
{
    uint32_t i;
    uint32_t ch;
    uint32_t sum;
    uint16_t avg;

    printf("\n========== ADC DMA Data Processing ==========\n");

    for (ch = 0; ch < ADC_CHANNEL_COUNT; ch++) {
        sum = 0;
        for (i = 0; i < ADC_SAMPLE_COUNT; i++) {
            sum += adc_dma_buffer[ch * ADC_SAMPLE_COUNT + i];
        }
        avg = (uint16_t)(sum / ADC_SAMPLE_COUNT);

        printf("Channel %u: avg = %5u (0x%04X), voltage = %u.%03u V\n",
               (unsigned)ch,
               (unsigned)avg,
               (unsigned)avg,
               (unsigned)((avg * 3300U) / 4095U / 1000U),
               (unsigned)((avg * 3300U) / 4095U % 1000U));
    }

    printf("=============================================\n\n");
}

/* ==================== 打印 DMA 缓冲区 ==================== */
static void adc_dma_print_buffer(void)
{
    uint32_t i;
    uint32_t ch;

    printf("\n---------- Raw DMA Buffer ----------\n");
    for (ch = 0; ch < ADC_CHANNEL_COUNT; ch++) {
        printf("CH%u: ", (unsigned)ch);
        for (i = 0; i < ADC_SAMPLE_COUNT; i++) {
            printf("%4u ", (unsigned)adc_dma_buffer[ch * ADC_SAMPLE_COUNT + i]);
            if ((i + 1) % 8 == 0) {
                printf("\n     ");
            }
        }
        printf("\n");
    }
    printf("------------------------------------\n\n");
}

/* ==================== 模拟 DMA 中断处理 ==================== */
static void adc_dma_irq_handler(void)
{
    uint32_t isr = DMA1_ISR;

    if (isr & DMA_ISR_TCIF1) {
        DMA1_IFCR |= DMA_ISR_TCIF1;
        adc_dma_full_count++;
        adc_dma_complete_flag = 1;
        printf("[IRQ] DMA transfer complete (count=%u)\n",
               (unsigned)adc_dma_full_count);
    }

    if (isr & DMA_ISR_HTIF1) {
        DMA1_IFCR |= DMA_ISR_HTIF1;
        adc_dma_half_count++;
        printf("[IRQ] DMA half transfer complete (count=%u)\n",
               (unsigned)adc_dma_half_count);
    }

    if (isr & DMA_ISR_TEIF1) {
        DMA1_IFCR |= DMA_ISR_TEIF1;
        printf("[IRQ] DMA transfer error!\n");
    }
}

/* ==================== 模拟 ADC 数据填充 ==================== */
static void mock_adc_fill_buffer(void)
{
    uint32_t i;
    uint32_t ch;

    for (ch = 0; ch < ADC_CHANNEL_COUNT; ch++) {
        for (i = 0; i < ADC_SAMPLE_COUNT; i++) {
            uint16_t base = (uint16_t)(ch * 800U + 200U);
            uint16_t noise = (uint16_t)((i * 37U + ch * 13U) % 100U);
            adc_dma_buffer[ch * ADC_SAMPLE_COUNT + i] = base + noise;
        }
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    printf("========================================\n");
    printf("  STM32 ADC Multi-Channel DMA Sample\n");
    printf("  Continuous Conversion + Circular DMA\n");
    printf("========================================\n\n");

    adc_gpio_init();
    adc_dma_init();
    adc_config();
    adc_start_conversion();

    printf("\n[Main] Simulating DMA transfer...\n");
    mock_adc_fill_buffer();

    DMA1_ISR |= DMA_ISR_HTIF1;
    adc_dma_irq_handler();

    DMA1_ISR |= DMA_ISR_TCIF1;
    adc_dma_irq_handler();

    adc_dma_print_buffer();

    if (adc_dma_complete_flag) {
        adc_dma_process_data();
        adc_dma_complete_flag = 0;
    }

    printf("[Main] Simulating second DMA cycle...\n");
    mock_adc_fill_buffer();

    DMA1_ISR |= DMA_ISR_HTIF1;
    adc_dma_irq_handler();

    DMA1_ISR |= DMA_ISR_TCIF1;
    adc_dma_irq_handler();

    if (adc_dma_complete_flag) {
        adc_dma_process_data();
        adc_dma_complete_flag = 0;
    }

    printf("========== Statistics ==========\n");
    printf("Half transfer count: %u\n", (unsigned)adc_dma_half_count);
    printf("Full transfer count: %u\n", (unsigned)adc_dma_full_count);
    printf("Buffer size: %u (channels: %u, samples/ch: %u)\n",
           (unsigned)ADC_BUFFER_SIZE,
           (unsigned)ADC_CHANNEL_COUNT,
           (unsigned)ADC_SAMPLE_COUNT);
    printf("================================\n");

    printf("\n[Main] Done.\n");
    return 0;
}
