/**
 * @brief  初始化TIM1高级定时器互补PWM输出
 */
void TIM1_PWM_Init(void)
{
    uint32_t psc;
    uint32_t arr;
    uint32_t dead_time;
    uint32_t i;

    /* 清零所有寄存器 */
    for (i = 0; i < TIM1_REG_COUNT; i++) {
        tim1_regs[i] = 0;
    }

    /* 计算预分频和自动重装载值 */
    psc = 0;
    arr = (SYSTEM_CLOCK_HZ / PWM_FREQ_HZ) - 1;

    /* 1. 配置时基单元 */
    TIM1_PSC = psc;
    TIM1_ARR = arr;
    TIM1_RCR = 0;

    /* 2. 配置通道1为PWM模式1 */
    TIM1_CCMR1 &= ~(0x7U << 4);
    TIM1_CCMR1 |= TIM_CCMR1_OC1M_PWM1 | TIM_CCMR1_OC1PE;

    /* 3. 设置初始占空比 */
    TIM1_CCR1 = (arr + 1) * PWM_DUTY_PERCENT / 100U;

    /* 4. 配置死区时间 */
    dead_time = (DEAD_TIME_NS * (SYSTEM_CLOCK_HZ / 1000000U)) / 1000U;
    if (dead_time > 255U) {
        dead_time = 255U;
    }
    TIM1_BDTR = (dead_time & 0xFFU) | TIM_BDTR_MOE;

    /* 5. 使能通道1输出和互补输出 */
    TIM1_CCER |= TIM_CCER_CC1E | TIM_CCER_CC1NE;

    /* 6. 使能自动重装载预装载 */
    TIM1_CR1 |= TIM_CR1_ARPE;

    /* 7. 产生更新事件 */
    TIM1_EGR |= TIM_EGR_UG;

    printf("[TIM1_PWM_Init] PSC=%lu, ARR=%lu, CCR1=%lu, DeadTime=%lu\r\n",
           (unsigned long)psc, (unsigned long)arr,
           (unsigned long)TIM1_CCR1, (unsigned long)dead_time);
}

/**
 * @brief  设置PWM占空比
 */
void TIM1_PWM_SetDuty(uint8_t duty_percent)
{
    uint32_t arr;
    uint32_t ccr;

    if (duty_percent > 100U) {
        duty_percent = 100U;
    }

    arr = TIM1_ARR;
    ccr = (arr + 1) * duty_percent / 100U;
    TIM1_CCR1 = ccr;

    printf("[TIM1_PWM_SetDuty] Duty=%u%%, CCR1=%lu\r\n",
           (unsigned int)duty_percent, (unsigned long)ccr);
}

/**
 * @brief  启动PWM输出
 */
void TIM1_PWM_Start(void)
{
    TIM1_CR1 |= TIM_CR1_CEN;
    printf("[TIM1_PWM_Start] Timer started, CR1=0x%08lX\r\n",
           (unsigned long)TIM1_CR1);
}

/**
 * @brief  停止PWM输出
 */
void TIM1_PWM_Stop(void)
{
    TIM1_CR1 &= ~TIM_CR1_CEN;
    printf("[TIM1_PWM_Stop] Timer stopped, CR1=0x%08lX\r\n",
           (unsigned long)TIM1_CR1);
}

