#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器定义 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问 */
static uint32_t mock_TIM1_CR1   = 0;
static uint32_t mock_TIM1_CCMR1 = 0;
static uint32_t mock_TIM1_CCMR2 = 0;
static uint32_t mock_TIM1_CCER  = 0;
static uint32_t mock_TIM1_PSC   = 0;
static uint32_t mock_TIM1_ARR   = 0;
static uint32_t mock_TIM1_CCR1  = 0;
static uint32_t mock_TIM1_CCR2  = 0;
static uint32_t mock_TIM1_BDTR  = 0;

#define TIM1_CR1    (mock_TIM1_CR1)
#define TIM1_CCMR1  (mock_TIM1_CCMR1)
#define TIM1_CCMR2  (mock_TIM1_CCMR2)
#define TIM1_CCER   (mock_TIM1_CCER)
#define TIM1_PSC    (mock_TIM1_PSC)
#define TIM1_ARR    (mock_TIM1_ARR)
#define TIM1_CCR1   (mock_TIM1_CCR1)
#define TIM1_CCR2   (mock_TIM1_CCR2)
#define TIM1_BDTR   (mock_TIM1_BDTR)

/* 位定义 */
#define TIM_CR1_CEN         (1U << 0)
#define TIM_CR1_ARPE        (1U << 7)

#define TIM_CCMR1_OC1M_PWM1 (6U << 4)
#define TIM_CCMR1_OC1PE     (1U << 3)
#define TIM_CCMR1_OC2M_PWM1 (6U << 12)
#define TIM_CCMR1_OC2PE     (1U << 11)

#define TIM_CCER_CC1E       (1U << 0)
#define TIM_CCER_CC1P       (1U << 1)
#define TIM_CCER_CC1NE      (1U << 2)
#define TIM_CCER_CC1NP      (1U << 3)
#define TIM_CCER_CC2E       (1U << 4)
#define TIM_CCER_CC2P       (1U << 5)
#define TIM_CCER_CC2NE      (1U << 6)
#define TIM_CCER_CC2NP      (1U << 7)

#define TIM_BDTR_DTG_MASK   (0xFFU << 0)
#define TIM_BDTR_LOCK_MASK  (0x3U << 8)
#define TIM_BDTR_OSSI        (1U << 10)
#define TIM_BDTR_OSSR        (1U << 11)
#define TIM_BDTR_BKE         (1U << 12)
#define TIM_BDTR_BKP         (1U << 13)
#define TIM_BDTR_AOE         (1U << 14)
#define TIM_BDTR_MOE         (1U << 15)

/* ================= 死区时间配置 ================= */

/* 根据死区时间(单位: tDTS 的倍数)计算 DTG[7:0] 值 */
static uint8_t calc_dtg_value(uint32_t dt_in_tdts)
{
    uint8_t dtg = 0;

    if (dt_in_tdts <= 127U) {
        dtg = (uint8_t)(dt_in_tdts & 0x7FU);
    } else if (dt_in_tdts <= 254U) {
        uint32_t val = (dt_in_tdts / 2U) - 64U;
        if (val > 63U) val = 63U;
        dtg = (uint8_t)(0x80U | (val & 0x3FU));
    } else if (dt_in_tdts <= 504U) {
        uint32_t val = (dt_in_tdts / 8U) - 32U;
        if (val > 31U) val = 31U;
        dtg = (uint8_t)(0xC0U | (val & 0x1FU));
    } else {
        uint32_t val = (dt_in_tdts / 16U) - 32U;
        if (val > 31U) val = 31U;
        dtg = (uint8_t)(0xE0U | (val & 0x1FU));
    }

    return dtg;
}

/* 根据 DTG 值反算死区时间(单位: tDTS 的倍数) */
static uint32_t calc_dt_from_dtg(uint8_t dtg)
{
    uint32_t dt = 0;
    uint8_t range = (dtg >> 5) & 0x07U;

    if (range < 4U) {
        dt = (uint32_t)(dtg & 0x7FU);
    } else if (range < 6U) {
        dt = (uint32_t)(64U + (dtg & 0x3FU)) * 2U;
    } else if (range == 6U) {
        dt = (uint32_t)(32U + (dtg & 0x1FU)) * 8U;
    } else {
        dt = (uint32_t)(32U + (dtg & 0x1FU)) * 16U;
    }

    return dt;
}

/* ================= 定时器 PWM 死区配置 ================= */

typedef struct {
    uint32_t psc;
    uint32_t arr;
    uint32_t ccr1;
    uint32_t ccr2;
    uint32_t dead_time_tdts;
    uint8_t  complementary;
    uint8_t  polarity;
} PWM_DeadTimeConfig_t;

static void TIM1_PWM_DeadTime_Init(const PWM_DeadTimeConfig_t *cfg)
{
    uint8_t dtg;
    uint32_t bdtr;

    if (cfg == NULL) {
        return;
    }

    TIM1_PSC = cfg->psc;
    TIM1_ARR = cfg->arr;

    TIM1_CCMR1 = 0;
    TIM1_CCMR1 |= TIM_CCMR1_OC1M_PWM1 | TIM_CCMR1_OC1PE;
    TIM1_CCMR1 |= TIM_CCMR1_OC2M_PWM1 | TIM_CCMR1_OC2PE;

    TIM1_CCR1 = cfg->ccr1;
    TIM1_CCR2 = cfg->ccr2;

    TIM1_CCER = 0;
    if (cfg->polarity == 0) {
        TIM1_CCER |= TIM_CCER_CC1E | TIM_CCER_CC2E;
        if (cfg->complementary) {
            TIM1_CCER |= TIM_CCER_CC1NE | TIM_CCER_CC2NE;
        }
    } else {
        TIM1_CCER |= TIM_CCER_CC1E | TIM_CCER_CC1P;
        TIM1_CCER |= TIM_CCER_CC2E | TIM_CCER_CC2P;
        if (cfg->complementary) {
            TIM1_CCER |= TIM_CCER_CC1NE | TIM_CCER_CC1NP;
            TIM1_CCER |= TIM_CCER_CC2NE | TIM_CCER_CC2NP;
        }
    }

    dtg = calc_dtg_value(cfg->dead_time_tdts);

    bdtr = TIM1_BDTR;
    bdtr &= ~TIM_BDTR_DTG_MASK;
    bdtr |= (uint32_t)dtg;
    bdtr |= TIM_BDTR_AOE;
    bdtr |= TIM_BDTR_MOE;
    bdtr |= TIM_BDTR_OSSR | TIM_BDTR_OSSI;

    TIM1_BDTR = bdtr;

    TIM1_CR1 |= TIM_CR1_ARPE;
    TIM1_CR1 |= TIM_CR1_CEN;
}

static void TIM1_UpdateDeadTime(uint32_t dead_time_tdts)
{
    uint8_t dtg = calc_dtg_value(dead_time_tdts);
    uint32_t bdtr = TIM1_BDTR;

    bdtr &= ~TIM_BDTR_DTG_MASK;
    bdtr |= (uint32_t)dtg;
    TIM1_BDTR = bdtr;
}

/* ================= 测试打印 ================= */

static void print_bdtr_info(void)
{
    uint32_t bdtr = TIM1_BDTR;
    uint8_t dtg = (uint8_t)(bdtr & 0xFFU);
    uint32_t dt = calc_dt_from_dtg(dtg);

    printf("  BDTR = 0x%08X\n", (unsigned int)bdtr);
    printf("  DTG[7:0] = 0x%02X\n", dtg);
    printf("  Dead Time = %u * tDTS\n", (unsigned int)dt);
    printf("  MOE = %u, AOE = %u, OSSR = %u, OSSI = %u\n",
           (unsigned int)((bdtr >> 15) & 1U),
           (unsigned int)((bdtr >> 14) & 1U),
           (unsigned int)((bdtr >> 11) & 1U),
           (unsigned int)((bdtr >> 10) & 1U));
}

int main(void)
{
    PWM_DeadTimeConfig_t cfg;

    printf("========================================\n");
