#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层
 * 使用普通静态变量模拟寄存器，避免直接访问非法地址
 * ============================================================ */
static volatile uint32_t g_adc_cr2 = 0;
static volatile uint32_t g_adc_sr  = 0;
static volatile uint32_t g_adc_dr  = 0;
static volatile uint32_t g_adc_sqr3 = 0;

#define ADC1_CR2            (g_adc_cr2)
#define ADC1_SR             (g_adc_sr)
#define ADC1_DR             (g_adc_dr)
#define ADC1_SQR3           (g_adc_sqr3)

#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_CAL         (1U << 2)
#define ADC_CR2_RSTCAL      (1U << 3)
#define ADC_CR2_SWSTART     (1U << 22)
#define ADC_SR_EOC          (1U << 1)

/* 模拟 ADC 原始值寄存器（用于测试） */
static volatile uint16_t g_mock_adc_raw = 0;

/* ============================================================
 * 校准数据结构
 * ============================================================ */
#define CAL_POINT_MAX       8U

typedef struct {
    float   raw;            /* ADC 原始码值 */
    float   ref;            /* 参考物理量（如电压/电流） */
} CalPoint_t;

typedef struct {
    CalPoint_t  points[CAL_POINT_MAX];
    uint8_t     count;          /* 已录入的校准点数量 */
    float       zero_offset;    /* 零点偏移（原始码值） */
    float       gain;           /* 增益系数 */
    float       gain_inv;       /* 增益倒数，用于反向计算 */
    uint8_t     calibrated;     /* 校准完成标志 */
} AdcCal_t;

/* ============================================================
 * 硬件抽象层（Mock）
 * ============================================================ */
static void ADC_HwInit(void)
{
    ADC1_CR2 |= ADC_CR2_ADON;
    ADC1_CR2 |= ADC_CR2_RSTCAL;
    ADC1_CR2 &= ~ADC_CR2_RSTCAL;    /* mock: 立即完成复位 */
    ADC1_CR2 |= ADC_CR2_CAL;
    ADC1_CR2 &= ~ADC_CR2_CAL;       /* mock: 立即完成校准 */
}

static uint16_t ADC_HwReadRaw(void)
{
    ADC1_CR2 |= ADC_CR2_SWSTART;
    ADC1_SR |= ADC_SR_EOC;          /* mock: 立即置位 EOC */
    ADC1_SR &= ~ADC_SR_EOC;
    return g_mock_adc_raw;
}

/* ============================================================
 * 校准算法核心
 * ============================================================ */

static void AdcCal_Init(AdcCal_t *cal)
{
    if (cal == NULL) {
        return;
    }
    memset(cal, 0, sizeof(AdcCal_t));
    cal->gain       = 1.0f;
    cal->gain_inv   = 1.0f;
    cal->calibrated = 0U;
}

static int AdcCal_AddPoint(AdcCal_t *cal, float raw, float ref)
{
    if (cal == NULL) {
        return -1;
    }
    if (cal->count >= CAL_POINT_MAX) {
        return -1;
    }
    cal->points[cal->count].raw = raw;
    cal->points[cal->count].ref = ref;
    cal->count++;
    return 0;
}

static int AdcCal_Compute(AdcCal_t *cal)
{
    uint8_t n;
    double sum_x  = 0.0;
    double sum_y  = 0.0;
    double sum_xx = 0.0;
    double sum_xy = 0.0;
    double denom;
    double gain;
    double offset;
    uint8_t i;

    if (cal == NULL) {
        return -1;
    }

    n = cal->count;
    if (n < 2U) {
        return -1;
    }

    for (i = 0U; i < n; i++) {
        double x = (double)cal->points[i].raw;
        double y = (double)cal->points[i].ref;
        sum_x  += x;
        sum_y  += y;
        sum_xx += x * x;
        sum_xy += x * y;
    }

    denom = (double)n * sum_xx - sum_x * sum_x;
    if (fabs(denom) < 1e-12) {
        return -1;
    }

    gain   = ((double)n * sum_xy - sum_x * sum_y) / denom;
    offset = (sum_y - gain * sum_x) / (double)n;

    if (fabs(gain) < 1e-12) {
        return -1;
    }

    cal->gain        = (float)gain;
    cal->zero_offset = (float)offset;
    cal->gain_inv    = (float)(1.0 / gain);
    cal->calibrated  = 1U;
    return 0;
}

static float AdcCal_Apply(const AdcCal_t *cal, uint16_t raw)
{
    if (cal == NULL) {
        return (float)raw;
    }
    if (!cal->calibrated) {
        return (float)raw;
    }
    return cal->gain * (float)raw + cal->zero_offset;
}

static float AdcCal_Inverse(const AdcCal_t *cal, float value)
{
    if (cal == NULL) {
        return value;
    }
    if (!cal->calibrated) {
        return value;
    }
    return (value - cal->zero_offset) * cal->gain_inv;
}

/* ============================================================
 * 测试辅助
 * ============================================================ */
static void PrintCalInfo(const AdcCal_t *cal)
{
    uint8_t i;
    if (cal == NULL) {
        return;
    }
    printf("---- Calibration Info ----\n");
    printf("Points : %u\n", (unsigned)cal->count);
    for (i = 0U; i < cal->count; i++) {
        printf("  [%u] raw=%.1f  ref=%.4f\n",
               (unsigned)i,
               cal->points[i].raw,
               cal->points[i].ref);
    }
    printf("Gain       = %.8f\n", cal->gain);
    printf("ZeroOffset = %.8f\n", cal->zero_offset);
    printf("GainInv    = %.8f\n", cal->gain_inv);
    printf("Calibrated = %s\n", cal->calibrated ? "YES" : "NO");
    printf("--------------------------\n");
}

/* ============================================================
 * main
 * ============================================================ */
int main(void)
{
    AdcCal_t cal;
    uint16_t test_raw[7] = {0U, 100U, 500U, 1000U, 2048U, 3000U, 4095U};
    float    test_val[5] = {0.0f, 0.5f, 1.0f, 2.0f, 4.0f};
    uint16_t raw_live;
    float    val_live;
    uint8_t  i;

    printf("===== STM32 ADC Multi-Point Calibration Demo =====\n\n");

    /* 1. 硬件初始化 */
    ADC_HwInit();

    /* 2. 校准结构体初始化 */
    AdcCal_Init(&cal);

    /* 3. 录入多点校准数据 */
    AdcCal_AddPoint(&cal, 100.0f,  0.150f);
    AdcCal_AddPoint(&cal, 500.0f,  0.550f);
    AdcCal_AddPoint(&cal, 1000.0f, 1.050f);
    AdcCal_AddPoint(&cal, 2000.0f, 2.050f);
    AdcCal_AddPoint(&cal, 3000.0f, 3.050f);
    AdcCal_AddPoint(&cal, 4095.0f, 4.145f);

    /* 4. 计算校准系数 */
    if (AdcCal_Compute(&cal) != 0) {
        printf("Calibration FAILED!\n");
        return 0;
    }

    PrintCalInfo(&cal);

    /* 5. 使用校准结果进行转换测试 */
    printf("\n---- Apply Calibration ----\n");
    for (i = 0U; i < 7U; i++) {
        float val = AdcCal_Apply(&cal, test_raw[i]);
        printf("raw=%4u  ->  value=%.6f\n", (unsigned)test_raw[i], val);
    }

    /* 6. 反向计算测试 */
    printf("\n---- Inverse Calibration ----\n");
    for (i = 0U; i < 5U; i++) {
        float raw = AdcCal_Inverse(&cal, test_val[i]);
        printf("value=%.4f  ->  raw=%.2f\n", test_val[i], raw);
    }

    /* 7. 模拟一次实际采样并转换 */
    printf("\n---- Live Sample Simulation ----\n");
    g_mock_adc_raw = 2048U;
    raw_live = ADC_HwReadRaw();
    val_live = AdcCal_Apply(&cal, raw_live);
    printf("Live raw=%u  ->  value=%.6f\n", (unsigned)raw_live, val_live);

    printf("\n===== Demo Finished =====\n");
    return 0;
}
