static void sine_table_init(void)
{
    int i;
    for (i = 0; i < SINE_TABLE_SIZE; i++) {
        double angle = 2.0 * PI * (double)i / (double)SINE_TABLE_SIZE;
        double val = (sin(angle) + 1.0) * 0.5 * (double)DAC_MAX_VALUE;
        sine_table[i] = (uint16_t)(val + 0.5);
    }
}

