    DAC_CR = 0;
    DAC_CR |= DAC_CR_EN1;
    DAC_CR |= DAC_CR_TEN1;
    DAC_CR |= DAC_CR_TSEL1;
    DAC_CR |= DAC_CR_DMAEN1;

