    DMA1_CMAR  = (uint32_t)(uintptr_t)sine_table;
    DMA1_CNDTR = SINE_TABLE_SIZE;
    DMA1_CCR   = 0;
    DMA1_CCR  |= DMA_CCR_EN;
    DMA1_CCR  |= DMA_CCR_CIRC;
    DMA1_CCR  |= DMA_CCR_DIR;
    DMA1_CCR  |= DMA_CCR_MINC;
    DMA1_CCR  |= DMA_CCR_PSIZE_16;
    DMA1_CCR  |= DMA_CCR_MSIZE_16;

