    TIM2_PSC = 0;
    TIM2_ARR = 279;
    TIM2_EGR |= TIM_EGR_UG;
    TIM2_SR   = 0;
    TIM2_DIER |= TIM_DIER_UDE;
    TIM2_CR1  |= TIM_CR1_CEN;
