#define ADC1_SQR3       (mock_adc_sqr3)
#define ADC1_SR         (mock_adc_sr)
#define ADC1_DR         (mock_adc_dr)

#define RCC_APB2ENR_ADC1EN  (1U << 9)

#define ADC_CR2_ADON    (1U << 0)
#define ADC_CR2_CAL     (1U << 2)
#define ADC_CR2_RSTCAL  (1U << 3)
#define ADC_CR2_EXTTRIG (1U << 20)
#define ADC_CR2_SWSTART (1U << 22)

#define ADC_SR_EOC      (1U << 1)

/* ===== 简单延时 ===== */
static void delay_loop(volatile uint32_t n)
{
    while (n--) {
        __asm__ volatile ("nop");
    }
}

/* ===== ADC1 初始化：单通道、软件触发、单次转换 ===== */
static void adc1_init(void)
{
    /* 使能 ADC1 时钟 */
    RCC_APB2ENR |= RCC_APB2ENR_ADC1EN;

    /* 复位校准：置位后立即清除，模拟硬件自动完成 */
    ADC1_CR2 |= ADC_CR2_RSTCAL;
    ADC1_CR2 &= ~ADC_CR2_RSTCAL;

    /* 开启 ADC */
    ADC1_CR2 |= ADC_CR2_ADON;
    delay_loop(100);

    /* 启动校准：置位后立即清除，模拟硬件自动完成 */
    ADC1_CR2 |= ADC_CR2_CAL;
    ADC1_CR2 &= ~ADC_CR2_CAL;

    /* 规则通道序列：第 1 个转换通道 = 通道 0 */
    ADC1_SQR3 = 0U;

    /* 软件触发，单次转换模式 */
    ADC1_CR2 |= ADC_CR2_EXTTRIG;
    ADC1_CR2 &= ~ADC_CR2_SWSTART;
}

/* ===== 启动一次软件触发转换并读取结果 ===== */
static uint16_t adc1_read(void)
{
    /* 软件启动转换 */
    ADC1_CR2 |= ADC_CR2_SWSTART;

    /* 模拟转换完成：写入一个示例数据并置位 EOC */
    ADC1_DR = 2048U;
    ADC1_SR |= ADC_SR_EOC;

    /* 等待转换结束 */
    while ((ADC1_SR & ADC_SR_EOC) == 0U) {
        /* 等待 EOC */
    }

    /* 读取数据寄存器，同时清除 EOC */
    ADC1_SR &= ~ADC_SR_EOC;
    return (uint16_t)(ADC1_DR & 0xFFFFU);
}

/* ===== 主函数 ===== */
int main(void)
{
    uint16_t adc_value;
    float voltage;

    printf("STM32 ADC single-channel sample (software trigger, single conversion)\n");

    adc1_init();

    adc_value = adc1_read();
    voltage = (float)adc_value * 3.3f / 4095.0f;

    printf("ADC raw value: %u\n", (unsigned int)adc_value);
    printf("Voltage: %.3f V\n", voltage);

    return 0;
}
