/* ================= DMA 目标缓冲区 ================= */
static volatile uint16_t adc_dma_buffer[ADC_CHANNEL_COUNT];

/* ================= 模拟 ADC 数据源 ================= */
static uint16_t mock_adc_values[ADC_CHANNEL_COUNT] = {1000, 2000, 3000, 4000};

/* ================= 模拟 DMA 传输 ================= */
static void mock_dma_transfer(void)
{
    uint8_t i;
    for (i = 0; i < ADC_CHANNEL_COUNT; i++) {
        adc_dma_buffer[i] = mock_adc_values[i];
    }
}

/* ================= ADC 初始化 ================= */
static void adc_dma_init(void)
{
    /* 使能时钟 */
    RCC_APB2ENR |= RCC_APB2ENR_ADC1EN;
    RCC_APB2ENR |= RCC_APB2ENR_IOPAEN;
    RCC_AHBENR  |= RCC_AHBENR_DMA1EN;

    /* 配置 PA0~PA3 为模拟输入 */
    GPIOA_CRL &= ~(0xFFFFU);
    GPIOA_CRL |= 0x0000BBBBU;

    /* ADC 校准 */
    ADC1_CR2 |= ADC_CR2_ADON;
    ADC1_CR2 |= ADC_CR2_CAL;
    /* 模拟校准完成：清除 CAL 位 */
    ADC1_CR2 &= ~ADC_CR2_CAL;

    /* 扫描模式 + 连续转换 + DMA */
    ADC1_CR1 |= ADC_CR1_SCAN;
    ADC1_CR2 |= ADC_CR2_CONT;
    ADC1_CR2 |= ADC_CR2_DMA;

    /* 采样时间配置 */
    ADC1_SMPR2 &= ~(0xFFFFFFFFU);
    ADC1_SMPR2 |= (ADC_SAMPLING_TIME << 0)  |
                  (ADC_SAMPLING_TIME << 3)  |
                  (ADC_SAMPLING_TIME << 6)  |
                  (ADC_SAMPLING_TIME << 9);

    /* 规则序列长度 = 4 */
    ADC1_SQR1 &= ~(0xFU << 20);
    ADC1_SQR1 |= ((ADC_CHANNEL_COUNT - 1U) << 20);

    /* 规则序列通道: 0,1,2,3 */
    ADC1_SQR3 &= ~(0x1FU << 0);
    ADC1_SQR3 |= (0U << 0);
    ADC1_SQR3 &= ~(0x1FU << 5);
    ADC1_SQR3 |= (1U << 5);
    ADC1_SQR3 &= ~(0x1FU << 10);
    ADC1_SQR3 |= (2U << 10);
    ADC1_SQR3 &= ~(0x1FU << 15);
    ADC1_SQR3 |= (3U << 15);

    /* DMA 配置: 循环模式, 外设到存储器, 16 位 */
    DMA1_CCR1 = 0;
    DMA1_CCR1 |= DMA_CCR1_MINC;
    DMA1_CCR1 |= DMA_CCR1_PSIZE_16;
    DMA1_CCR1 |= DMA_CCR1_MSIZE_16;
    DMA1_CCR1 |= DMA_CCR1_CIRC;
    DMA1_CCR1 |= DMA_CCR1_TCIE;

    DMA1_CPAR1  = (uint32_t)(uintptr_t)(&ADC1_DR);
    DMA1_CMAR1  = (uint32_t)(uintptr_t)adc_dma_buffer;
    DMA1_CNDTR1 = ADC_CHANNEL_COUNT;

    DMA1_CCR1 |= DMA_CCR1_EN;

    /* 启动 ADC */
    ADC1_CR2 |= ADC_CR2_ADON;
    ADC1_CR2 |= ADC_CR2_SWSTART;
}

/* ================= 打印缓冲区 ================= */
static void print_adc_buffer(void)
{
    uint8_t i;
    printf("ADC DMA Buffer: ");
    for (i = 0; i < ADC_CHANNEL_COUNT; i++) {
        printf("[CH%d]=%4u ", i, (unsigned int)adc_dma_buffer[i]);
    }
    printf("\n");
}

/* ================= main ================= */
int main(void)
{
    uint8_t loop;

    printf("=== STM32 ADC Multi-Channel DMA (Continuous, Circular) ===\n");

    adc_dma_init();

    for (loop = 0; loop < 5; loop++) {
        /* 模拟 DMA 完成一次循环传输 */
        mock_dma_transfer();

        printf("Loop %u -> ", (unsigned int)loop);
        print_adc_buffer();
    }

    printf("=== Done ===\n");
    return 0;
}
