#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
#define ADC1_BASE           0x40012400UL
#define ADC1_DR             (*(volatile uint32_t *)(ADC1_BASE + 0x4C))
#define ADC1_CR2            (*(volatile uint32_t *)(ADC1_BASE + 0x08))
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_CAL         (1U << 2)
#define ADC_CR2_RSTCAL      (1U << 3)
#define ADC_CR2_SWSTART     (1U << 22)

#define VREF_MV             3300.0f
#define ADC_FULL_SCALE      4095.0f

/* ================= 多点校准数据结构 ================= */
#define CAL_POINT_MAX       5

typedef struct {
    float raw;
    float ref;
} CalPoint;

typedef struct {
    CalPoint pts[CAL_POINT_MAX];
    int      count;
    float    gain;
    float    offset;
    int      valid;
} AdcCalib;

/* ================= 硬件 Mock 层 ================= */
static void adc_hw_init(void)
{
    /* 使用本地静态变量模拟寄存器，避免访问非法地址 */
    static volatile uint32_t mock_cr2 = 0;
    mock_cr2 |= ADC_CR2_ADON;
    mock_cr2 |= ADC_CR2_RSTCAL;
    mock_cr2 &= ~ADC_CR2_RSTCAL;
    mock_cr2 |= ADC_CR2_CAL;
    mock_cr2 &= ~ADC_CR2_CAL;
    (void)mock_cr2;
}

static uint32_t adc_hw_read_raw(void)
{
    /* 返回一个模拟的原始 ADC 码值 */
    static uint32_t counter = 0;
    static const uint32_t samples[5] = { 100, 1024, 2048, 3072, 4000 };
    uint32_t v = samples[counter % 5];
    counter++;
    return v;
}

/* ================= 校准算法 ================= */

/* 最小二乘线性拟合：ref = gain * raw + offset */
static int calib_fit(AdcCalib *cal)
{
    int n;
    double sx = 0.0, sy = 0.0, sxx = 0.0, sxy = 0.0;
    int i;
    double denom;

    if (cal == NULL) {
        return -1;
    }

    n = cal->count;
    if (n < 2) {
        cal->valid = 0;
        return -1;
    }

    for (i = 0; i < n; i++) {
        double x = (double)cal->pts[i].raw;
        double y = (double)cal->pts[i].ref;
        sx  += x;
        sy  += y;
        sxx += x * x;
        sxy += x * y;
    }

    denom = (double)n * sxx - sx * sx;
    if (fabs(denom) < 1e-12) {
        cal->valid = 0;
        return -1;
    }

    cal->gain   = (float)(((double)n * sxy - sx * sy) / denom);
    cal->offset = (float)((sy - cal->gain * sx) / (double)n);
    cal->valid  = 1;
    return 0;
}

/* 添加一个校准点 */
static int calib_add_point(AdcCalib *cal, float raw, float ref)
{
    if (cal == NULL) {
        return -1;
    }
    if (cal->count >= CAL_POINT_MAX) {
        return -1;
    }
    cal->pts[cal->count].raw = raw;
    cal->pts[cal->count].ref = ref;
    cal->count++;
    return 0;
}

/* 应用校准：输入原始 ADC 码值，输出校准后电压(mV) */
static float calib_apply(const AdcCalib *cal, float raw)
{
    if (cal == NULL || !cal->valid) {
        return raw * (VREF_MV / ADC_FULL_SCALE);
    }
    return cal->gain * raw + cal->offset;
}

/* 将原始码值转换为电压(mV) */
static float raw_to_mv(uint32_t raw)
{
    return (float)raw * (VREF_MV / ADC_FULL_SCALE);
}

/* ================= 测试主函数 ================= */
int main(void)
{
    AdcCalib cal;
    int i;
    uint32_t raw_samples[5] = { 100, 1024, 2048, 3072, 4000 };
    float    ref_values[5]  = { 80.0f, 820.0f, 1640.0f, 2460.0f, 3200.0f };

    /* 初始化 */
    cal.count  = 0;
    cal.gain   = 1.0f;
    cal.offset = 0.0f;
    cal.valid  = 0;

    adc_hw_init();

    printf("===== STM32 ADC 多点校准测试 =====\n");
    printf("VREF = %.1f mV, FullScale = %.0f\n\n", VREF_MV, ADC_FULL_SCALE);

    /* 采集校准点 */
    printf("--- 采集校准点 ---\n");
    for (i = 0; i < 5; i++) {
        uint32_t raw = adc_hw_read_raw();
        (void)raw;
        raw = raw_samples[i];
        calib_add_point(&cal, (float)raw, ref_values[i]);
        printf("Point[%d]: raw=%4u (%.1f mV), ref=%.1f mV\n",
               i, (unsigned)raw, raw_to_mv(raw), ref_values[i]);
    }

    /* 拟合 */
    printf("\n--- 最小二乘拟合 ---\n");
    if (calib_fit(&cal) == 0) {
        printf("Gain   = %.6f\n", cal.gain);
        printf("Offset = %.3f mV\n", cal.offset);
    } else {
        printf("拟合失败！\n");
    }

    /* 验证 */
    printf("\n--- 校准验证 ---\n");
    for (i = 0; i < 5; i++) {
        float raw_mv = raw_to_mv(raw_samples[i]);
        float cal_mv = calib_apply(&cal, (float)raw_samples[i]);
        float err    = cal_mv - ref_values[i];
        printf("raw=%4u | 未校准=%7.1f mV | 校准后=%7.1f mV | 参考=%7.1f mV | 误差=%+6.2f mV\n",
               (unsigned)raw_samples[i], raw_mv, cal_mv, ref_values[i], err);
    }

    /* 零点与增益单独展示 */
    printf("\n--- 零点与增益 ---\n");
    printf("零点(offset) = %.3f mV\n", cal.offset);
    printf("增益(gain)   = %.6f\n", cal.gain);
    printf("零点校准后 raw=0 输出 = %.3f mV\n", calib_apply(&cal, 0.0f));
    printf("满量程校准后 raw=4095 输出 = %.3f mV\n", calib_apply(&cal, 4095.0f));

    return 0;
}
