static uint32_t mock_dac_dhr12r1  = 0;
static uint32_t mock_dac_swtrigr  = 0;
static uint32_t mock_dac_dor1     = 0;

#define RCC_APB1ENR     (mock_rcc_apb1enr)
#define RCC_APB1ENR_DACEN   (1U << 29)

#define DAC_CR          (mock_dac_cr)
#define DAC_CR_EN       (1U << 0)
#define DAC_CR_TEN1     (1U << 1)
#define DAC_CR_TSEL1    (7U << 3)
#define DAC_CR_WAVE1    (3U << 6)
#define DAC_CR_WAVE1_NOISE  (1U << 6)
#define DAC_CR_WAVE1_TRI    (2U << 6)
#define DAC_CR_MAMP1    (0xFU << 8)

#define DAC_DHR12R1     (mock_dac_dhr12r1)
#define DAC_DHR12L1     (mock_dac_dhr12r1)
#define DAC_DHR8R1      (mock_dac_dhr12r1)

#define DAC_SWTRIGR     (mock_dac_swtrigr)
#define DAC_SWTRIGR_SWTRIG1 (1U << 0)

#define DAC_DOR1        (mock_dac_dor1)

/* ==================== 三角波参数 ==================== */
#define TRI_WAVE_STEP       64U
#define TRI_WAVE_MAX        4095U
#define TRI_WAVE_MIN        0U

/* ==================== 软件三角波生成器 ==================== */
typedef struct {
    uint16_t value;
    int8_t   direction;   /* +1 上升, -1 下降 */
    uint16_t step;
    uint16_t max;
    uint16_t min;
} TriWaveGen_t;

static TriWaveGen_t g_tri = {
    0, 1, TRI_WAVE_STEP, TRI_WAVE_MAX, TRI_WAVE_MIN
};

static void TriWave_Init(TriWaveGen_t *gen, uint16_t step, uint16_t max, uint16_t min)
{
    gen->value     = min;
    gen->direction = 1;
    gen->step      = step;
    gen->max       = max;
    gen->min       = min;
}

static uint16_t TriWave_Next(TriWaveGen_t *gen)
{
    if (gen->direction > 0) {
        if ((uint32_t)gen->value + gen->step >= gen->max) {
            gen->value     = gen->max;
            gen->direction = -1;
        } else {
            gen->value = (uint16_t)(gen->value + gen->step);
        }
    } else {
        if (gen->value <= (uint16_t)(gen->min + gen->step)) {
            gen->value     = gen->min;
            gen->direction = 1;
        } else {
            gen->value = (uint16_t)(gen->value - gen->step);
        }
    }
    return gen->value;
}

/* ==================== DAC Mock 驱动 ==================== */
static void DAC_Init(void)
{
    RCC_APB1ENR |= RCC_APB1ENR_DACEN;
    DAC_CR &= ~(DAC_CR_TEN1 | DAC_CR_TSEL1 | DAC_CR_WAVE1 | DAC_CR_MAMP1);
    DAC_CR |= DAC_CR_EN;
}

static void DAC_SetChannel1Data(uint16_t data)
{
    DAC_DHR12R1 = (uint32_t)(data & 0x0FFFU);
    /* 模拟硬件行为：DHR 写入后 DOR 更新 */
    DAC_DOR1 = DAC_DHR12R1;
}

static uint16_t DAC_GetChannel1Output(void)
{
    return (uint16_t)(DAC_DOR1 & 0x0FFFU);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t i;
    uint16_t sample;
    uint16_t dac_out;

    printf("===== STM32 DAC Triangle Wave (Software Generated) =====\n");

    DAC_Init();
    TriWave_Init(&g_tri, TRI_WAVE_STEP, TRI_WAVE_MAX, TRI_WAVE_MIN);

    printf("Triangle Wave Params: step=%u, max=%u, min=%u\n",
           (unsigned)TRI_WAVE_STEP,
           (unsigned)TRI_WAVE_MAX,
           (unsigned)TRI_WAVE_MIN);
    printf("--------------------------------------------------------\n");

    for (i = 0; i < 128U; i++) {
        sample = TriWave_Next(&g_tri);
        DAC_SetChannel1Data(sample);
        dac_out = DAC_GetChannel1Output();

        printf("Sample[%3lu] : value=%4u, DAC_DOR1=%4u, dir=%+d\n",
               (unsigned long)i,
               (unsigned)sample,
               (unsigned)dac_out,
               (int)g_tri.direction);
    }

    printf("--------------------------------------------------------\n");
    printf("Triangle wave generation completed.\n");

    return 0;
}
