    DMA1_CNDTR1 = SINE_TABLE_SIZE;
    DMA1_CCR1 = DMA_CCR_MINC | DMA_CCR_PSIZE_16 | DMA_CCR_MSIZE_16 |
                DMA_CCR_DIR | DMA_CCR_CIRC | DMA_CCR_EN;
