#define ADS1256_CMD_SELFOCAL    0xF1
#define ADS1256_CMD_SELFGCAL    0xF2
#define ADS1256_CMD_SYSOCAL     0xF3
#define ADS1256_CMD_SYSGCAL     0xF4
#define ADS1256_CMD_SYNC        0xFC
#define ADS1256_CMD_STANDBY     0xFD
#define ADS1256_CMD_WAKEUP      0xFE
#define ADS1256_CMD_RESET       0xFF

/* ADS1256 寄存器地址 */
#define ADS1256_REG_STATUS      0x00
#define ADS1256_REG_MUX         0x01
#define ADS1256_REG_ADCON       0x02
#define ADS1256_REG_DRATE       0x03
#define ADS1256_REG_IO          0x04
#define ADS1256_REG_OFC0        0x05
#define ADS1256_REG_OFC1        0x06
#define ADS1256_REG_OFC2        0x07
#define ADS1256_REG_FSC0        0x08
#define ADS1256_REG_FSC1        0x09
#define ADS1256_REG_FSC2        0x0A

/* ADS1256 数据速率设置 (高速采样) */
#define ADS1256_DRATE_30KSPS    0xF0
#define ADS1256_DRATE_15KSPS    0xE0
#define ADS1256_DRATE_7_5KSPS   0xD0
#define ADS1256_DRATE_3_75KSPS  0xC0

/* ADS1256 增益设置 */
#define ADS1256_GAIN_1          0x00
#define ADS1256_GAIN_2          0x01
#define ADS1256_GAIN_4          0x02
#define ADS1256_GAIN_8          0x03
#define ADS1256_GAIN_16         0x04
#define ADS1256_GAIN_32         0x05
#define ADS1256_GAIN_64         0x06

/* ==================== 模拟 ADS1256 寄存器存储 ==================== */
static uint8_t ads1256_regs[11] = {0};

/* ==================== 延时函数 (Mock) ==================== */
static void delay_us(uint32_t us)
{
    volatile uint32_t i;
    for (i = 0; i < us * 10; i++) {
        /* 空循环模拟延时 */
    }
}

/* ==================== SPI 底层驱动 ==================== */
static void spi_init(void)
{
    SPI_CR1 = SPI_CR1_MSTR | SPI_CR1_SSM | SPI_CR1_SSI |
              SPI_CR1_CPHA | SPI_CR1_BR_0;
    SPI_CR1 |= SPI_CR1_SPE;
    /* 模拟 SPI 状态：TXE 和 RXNE 均置位，避免死循环 */
    SPI_SR = SPI_SR_TXE | SPI_SR_RXNE;
}

static uint8_t spi_transfer(uint8_t tx_data)
{
    /* 模拟 SPI 传输：直接返回数据，避免依赖硬件状态位 */
    SPI_DR = tx_data;
    SPI_SR = SPI_SR_TXE | SPI_SR_RXNE;
    return (uint8_t)(SPI_DR & 0xFF);
}

/* ==================== ADS1256 片选控制 ==================== */
static void ads1256_cs_low(void)
{
    GPIOA_ODR &= ~ADS1256_CS_PIN;
}

static void ads1256_cs_high(void)
{
    GPIOA_ODR |= ADS1256_CS_PIN;
}

/* ==================== ADS1256 数据就绪检测 ==================== */
static uint8_t ads1256_drdy_is_low(void)
{
    /* 模拟 DRDY 始终为低，避免死循环 */
    return 1;
}

static void ads1256_wait_drdy(void)
{
    /* 模拟等待，直接返回 */
    (void)ads1256_drdy_is_low();
}

/* ==================== ADS1256 寄存器操作 ==================== */
static void ads1256_write_reg(uint8_t reg, uint8_t value)
{
    if (reg < sizeof(ads1256_regs)) {
        ads1256_regs[reg] = value;
    }
    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_WREG | reg);
    spi_transfer(0x00);
    spi_transfer(value);
    ads1256_cs_high();
    delay_us(10);
}

static uint8_t ads1256_read_reg(uint8_t reg)
{
    uint8_t value;

    if (reg < sizeof(ads1256_regs)) {
        value = ads1256_regs[reg];
    } else {
        value = 0;
    }

    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_RREG | reg);
    spi_transfer(0x00);
    delay_us(10);
    spi_transfer(0xFF);
    ads1256_cs_high();
    delay_us(10);

    return value;
}

/* ==================== ADS1256 初始化 ==================== */
static void ads1256_init(void)
{
    memset(ads1256_regs, 0, sizeof(ads1256_regs));

    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_RESET);
    ads1256_cs_high();
    delay_us(1000);

    ads1256_wait_drdy();

    ads1256_write_reg(ADS1256_REG_STATUS, 0x00);
    ads1256_write_reg(ADS1256_REG_MUX, 0x08);
    ads1256_write_reg(ADS1256_REG_ADCON, ADS1256_GAIN_1);
    ads1256_write_reg(ADS1256_REG_DRATE, ADS1256_DRATE_30KSPS);
    ads1256_write_reg(ADS1256_REG_IO, 0x00);

    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_SELFCAL);
    ads1256_cs_high();
    ads1256_wait_drdy();
}

/* ==================== ADS1256 读取单次转换数据 ==================== */
static int32_t ads1256_read_data(void)
{
    int32_t value = 0;
    uint8_t buf[3];

    ads1256_wait_drdy();

    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_RDATA);
    delay_us(10);

    buf[0] = spi_transfer(0xFF);
    buf[1] = spi_transfer(0xFF);
    buf[2] = spi_transfer(0xFF);

    ads1256_cs_high();

    value = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2];

    if (value & 0x00800000) {
        value |= 0xFF000000;
    }

    return value;
}

/* ==================== ADS1256 连续读取模式 ==================== */
static void ads1256_start_continuous(void)
{
    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_RDATAC);
    ads1256_cs_high();
}

static void ads1256_stop_continuous(void)
{
    ads1256_cs_low();
    spi_transfer(ADS1256_CMD_SDATAC);
    ads1256_cs_high();
}

static int32_t ads1256_read_continuous(void)
{
    int32_t value = 0;
    uint8_t buf[3];

    ads1256_wait_drdy();

    ads1256_cs_low();
    buf[0] = spi_transfer(0xFF);
    buf[1] = spi_transfer(0xFF);
    buf[2] = spi_transfer(0xFF);
    ads1256_cs_high();

    value = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2];

    if (value & 0x00800000) {
        value |= 0xFF000000;
    }

    return value;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    int32_t adc_value;
    int i;

    printf("========================================\n");
    printf("  ADS1256 SPI Driver Test (High Speed)  \n");
    printf("========================================\n\n");

    printf("[1] Initializing SPI...\n");
    spi_init();
    printf("    SPI initialized: MSTR=1, CPOL=0, CPHA=1\n\n");

    printf("[2] Initializing ADS1256...\n");
    ads1256_init();
    printf("    ADS1256 initialized: Gain=1, DRATE=30kSPS\n\n");

    printf("[3] Register verification:\n");
    printf("    STATUS = 0x%02X\n", ads1256_read_reg(ADS1256_REG_STATUS));
    printf("    MUX    = 0x%02X\n", ads1256_read_reg(ADS1256_REG_MUX));
    printf("    ADCON  = 0x%02X\n", ads1256_read_reg(ADS1256_REG_ADCON));
    printf("    DRATE  = 0x%02X\n\n", ads1256_read_reg(ADS1256_REG_DRATE));

    printf("[4] Single conversion test:\n");
    for (i = 0; i < 5; i++) {
        adc_value = ads1256_read_data();
