/* ===== Mock 寄存器定义（使用普通变量模拟，避免非法地址访问） ===== */
static volatile uint32_t mock_DAC_CR      = 0;
static volatile uint32_t mock_DAC_SWTRIGR = 0;
static volatile uint32_t mock_DAC_DHR12R1 = 0;
static volatile uint32_t mock_DAC_DOR1    = 0;
static volatile uint32_t mock_RCC_APB1ENR = 0;

#define DAC_CR              (mock_DAC_CR)
#define DAC_SWTRIGR         (mock_DAC_SWTRIGR)
#define DAC_DHR12R1         (mock_DAC_DHR12R1)
#define DAC_DOR1            (mock_DAC_DOR1)
#define RCC_APB1ENR         (mock_RCC_APB1ENR)

#define RCC_APB1ENR_DACEN   (1U << 29)

#define DAC_CR_EN1          (1U << 0)
#define DAC_CR_TEN1         (1U << 1)
#define DAC_CR_TSEL1_SHIFT  3
#define DAC_CR_TSEL1_SW     (7U << DAC_CR_TSEL1_SHIFT)

#define DAC_SWTRIGR_SWTRIG1 (1U << 0)

/* ===== 三角波参数 ===== */
#define TRI_WAVE_STEPS      64U
#define TRI_WAVE_MAX        4095U
#define TRI_WAVE_MIN        0U
#define TRI_WAVE_STEP       ((TRI_WAVE_MAX - TRI_WAVE_MIN) / (TRI_WAVE_STEPS / 2U))

/* ===== 软件延时（mock） ===== */
static void delay_cycles(volatile uint32_t count)
{
    while (count--) {
        __asm__ volatile ("nop");
    }
}

/* ===== DAC 初始化 ===== */
static void dac_init(void)
{
    RCC_APB1ENR |= RCC_APB1ENR_DACEN;

    DAC_CR = 0;
    DAC_CR |= DAC_CR_TEN1;
    DAC_CR |= DAC_CR_TSEL1_SW;
    DAC_CR |= DAC_CR_EN1;
}

/* ===== 软件触发 DAC 输出 ===== */
static void dac_software_trigger(void)
{
    DAC_SWTRIGR |= DAC_SWTRIGR_SWTRIG1;
    /* 模拟硬件行为：触发后数据寄存器内容被锁存到输出寄存器 */
    DAC_DOR1 = DAC_DHR12R1 & 0x0FFFU;
}

/* ===== 设置 DAC 12 位右对齐数据 ===== */
static void dac_set_value(uint16_t value)
{
    DAC_DHR12R1 = (uint32_t)(value & 0x0FFFU);
}

/* ===== 生成三角波一个周期 ===== */
static void dac_triangle_wave_once(void)
{
    uint16_t i;
    uint16_t value;

    for (i = 0; i < TRI_WAVE_STEPS; i++) {
        if (i < (TRI_WAVE_STEPS / 2U)) {
            value = (uint16_t)(TRI_WAVE_MIN + i * TRI_WAVE_STEP);
        } else {
            value = (uint16_t)(TRI_WAVE_MAX - (i - TRI_WAVE_STEPS / 2U) * TRI_WAVE_STEP);
        }

        dac_set_value(value);
        dac_software_trigger();

        printf("DAC step %2u: value = %4u, DOR1 = %4u\n",
               (unsigned)i,
               (unsigned)value,
               (unsigned)(DAC_DOR1 & 0x0FFFU));

        delay_cycles(1000);
    }
}

/* ===== main ===== */
int main(void)
{
    printf("STM32 DAC Triangle Wave (Software Generated) Test\n");
    printf("------------------------------------------------\n");

    dac_init();

    printf("DAC initialized. CR = 0x%08X\n", (unsigned)DAC_CR);
    printf("Generating one triangle wave period...\n\n");

    dac_triangle_wave_once();

    printf("\nTriangle wave generation complete.\n");

    return 0;
}
