#define SPI_CR1_BR_1        (1U << 4)
#define SPI_CR1_BR_2        (1U << 5)
#define SPI_CR1_SPE         (1U << 6)
#define SPI_CR1_LSBFIRST    (1U << 7)
#define SPI_CR1_SSI         (1U << 8)
#define SPI_CR1_SSM         (1U << 9)
#define SPI_CR1_RXONLY      (1U << 10)
#define SPI_CR1_DFF         (1U << 11)
#define SPI_CR1_CRCNEXT     (1U << 12)
#define SPI_CR1_CRCEN       (1U << 13)
#define SPI_CR1_BIDIOE      (1U << 14)
#define SPI_CR1_BIDIMODE    (1U << 15)

#define SPI_SR_RXNE         (1U << 0)
#define SPI_SR_TXE          (1U << 1)
#define SPI_SR_BSY          (1U << 7)

#define GPIO_PIN_4          (1U << 4)
#define GPIO_PIN_5          (1U << 5)
#define GPIO_PIN_7          (1U << 7)

#define DAC8552_CMD_WRITE_AND_UPDATE_A  0x00
#define DAC8552_CMD_WRITE_AND_UPDATE_B  0x01
#define DAC8552_CMD_WRITE_AND_UPDATE_AB 0x02
#define DAC8552_CMD_POWER_DOWN          0x03
#define DAC8552_CMD_RESET               0x04
#define DAC8552_CMD_LDAC                0x05

#define DAC8552_CHANNEL_A               0
#define DAC8552_CHANNEL_B               1

#define DAC8552_RESOLUTION              16
#define DAC8552_MAX_VALUE               0xFFFF

#define SPI_TIMEOUT_COUNT               100000

/* ==================== 函数声明 ==================== */

static void SPI_GPIO_Init(void);
static void SPI_Init(void);
static uint8_t SPI_TransferByte(uint8_t tx_data);
static void SPI_CS_Low(void);
static void SPI_CS_High(void);
static void DAC8552_Write(uint8_t channel, uint16_t value);
static void DAC8552_WriteAndUpdate(uint8_t channel, uint16_t value);
static void DAC8552_Reset(void);
