static void Delay_ms(uint32_t ms);

/* ==================== 函数实现 ==================== */

static void SPI_GPIO_Init(void)
{
    GPIOA_MODER &= ~((3U << (4 * 2)) | (3U << (5 * 2)) | (3U << (7 * 2)));
    GPIOA_MODER |= ((2U << (4 * 2)) | (2U << (5 * 2)) | (2U << (7 * 2)));
    GPIOA_OTYPER &= ~(GPIO_PIN_4 | GPIO_PIN_5 | GPIO_PIN_7);
    GPIOA_OSPEEDR |= ((3U << (4 * 2)) | (3U << (5 * 2)) | (3U << (7 * 2)));
    GPIOA_PUPDR &= ~((3U << (4 * 2)) | (3U << (5 * 2)) | (3U << (7 * 2)));
    GPIOA_BSRR = GPIO_PIN_4;
}

static void SPI_Init(void)
{
    SPI_CR1 &= ~SPI_CR1_SPE;
    SPI_CR1 = SPI_CR1_MSTR | SPI_CR1_SSM | SPI_CR1_SSI;
    SPI_CR1 &= ~(SPI_CR1_BR_0 | SPI_CR1_BR_1 | SPI_CR1_BR_2);
    SPI_CR1 |= (SPI_CR1_BR_2 | SPI_CR1_BR_0);
    SPI_CR1 &= ~SPI_CR1_DFF;
    SPI_CR1 &= ~SPI_CR1_LSBFIRST;
    SPI_CR1 |= SPI_CR1_SPE;
}

static uint8_t SPI_TransferByte(uint8_t tx_data)
{
    uint32_t timeout = SPI_TIMEOUT_COUNT;

    /* 模拟发送缓冲区为空 */
    SPI_SR |= SPI_SR_TXE;

    while (!(SPI_SR & SPI_SR_TXE)) {
        if (--timeout == 0) {
            printf("[ERROR] SPI TX timeout\r\n");
            return 0;
        }
    }

    SPI_DR = tx_data;

    /* 模拟接收缓冲区非空 */
    SPI_SR |= SPI_SR_RXNE;

    timeout = SPI_TIMEOUT_COUNT;

    while (!(SPI_SR & SPI_SR_RXNE)) {
        if (--timeout == 0) {
            printf("[ERROR] SPI RX timeout\r\n");
            return 0;
        }
    }

    return (uint8_t)(SPI_DR & 0xFF);
}

static void SPI_CS_Low(void)
{
    GPIOA_BSRR = (GPIO_PIN_4 << 16);
}

static void SPI_CS_High(void)
{
    GPIOA_BSRR = GPIO_PIN_4;
}

static void DAC8552_Write(uint8_t channel, uint16_t value)
{
    uint8_t cmd;
    uint8_t data_high;
    uint8_t data_low;

    if (channel == DAC8552_CHANNEL_A) {
        cmd = (DAC8552_CMD_WRITE_AND_UPDATE_A << 4) & 0xF0;
    } else {
        cmd = (DAC8552_CMD_WRITE_AND_UPDATE_B << 4) & 0xF0;
    }

    data_high = (uint8_t)((value >> 8) & 0xFF);
    data_low = (uint8_t)(value & 0xFF);

    SPI_CS_Low();
    SPI_TransferByte(cmd);
    SPI_TransferByte(data_high);
    SPI_TransferByte(data_low);
    SPI_CS_High();
}

static void DAC8552_WriteAndUpdate(uint8_t channel, uint16_t value)
{
    uint8_t cmd;
    uint8_t data_high;
    uint8_t data_low;

    if (channel == DAC8552_CHANNEL_A) {
        cmd = (DAC8552_CMD_WRITE_AND_UPDATE_A << 4) & 0xF0;
    } else {
        cmd = (DAC8552_CMD_WRITE_AND_UPDATE_B << 4) & 0xF0;
    }

    data_high = (uint8_t)((value >> 8) & 0xFF);
    data_low = (uint8_t)(value & 0xFF);

    SPI_CS_Low();
    SPI_TransferByte(cmd);
    SPI_TransferByte(data_high);
    SPI_TransferByte(data_low);
    SPI_CS_High();
}

static void DAC8552_Reset(void)
{
    uint8_t cmd = (DAC8552_CMD_RESET << 4) & 0xF0;

    SPI_CS_Low();
    SPI_TransferByte(cmd);
    SPI_TransferByte(0x00);
    SPI_TransferByte(0x00);
    SPI_CS_High();
}

static void DAC8552_PowerDown(uint8_t channel, uint8_t mode)
{
    uint8_t cmd;
    uint8_t data_high;

    if (channel == DAC8552_CHANNEL_A) {
        cmd = (DAC8552_CMD_POWER_DOWN << 4) & 0xF0;
    } else {
        cmd = (DAC8552_CMD_POWER_DOWN << 4) & 0xF0;
    }

    data_high = (uint8_t)((mode & 0x03) << 6);

    SPI_CS_Low();
    SPI_TransferByte(cmd);
    SPI_TransferByte(data_high);
    SPI_TransferByte(0x00);
    SPI_CS_High();
}

static void DAC8552_WriteVoltage(uint8_t channel, float voltage, float vref)
{
    uint32_t dac_code;
    float ratio;

    if (vref <= 0.0f) {
        printf("[ERROR] Invalid VREF: %.3f V\r\n", vref);
        return;
    }

    if (voltage < 0.0f) {
        voltage = 0.0f;
    } else if (voltage > vref) {
        voltage = vref;
    }

    ratio = voltage / vref;
    dac_code = (uint32_t)(ratio * (float)DAC8552_MAX_VALUE + 0.5f);

    if (dac_code > DAC8552_MAX_VALUE) {
        dac_code = DAC8552_MAX_VALUE;
    }

    printf("[DAC8552] CH%c: Vout=%.4f V, Vref=%.4f V, Code=%u (0x%04X)\r\n",
           (channel == DAC8552_CHANNEL_A) ? 'A' : 'B',
           voltage, vref, (unsigned int)dac_code, (unsigned int)dac_code);

    DAC8552_WriteAndUpdate(channel, (uint16_t)dac_code);
}

