static volatile uint32_t mock_spi_cr1 = 0;
static volatile uint32_t mock_gpioa_odr = 0;
static volatile uint32_t mock_gpioa_idr = 0;

#define SPI_DR      (mock_spi_dr)
#define SPI_SR      (mock_spi_sr)
#define SPI_CR1     (mock_spi_cr1)

#define SPI_SR_TXE  (1U << 1)
#define SPI_SR_RXNE (1U << 0)
#define SPI_SR_BSY  (1U << 7)

#define SPI_CR1_SPE (1U << 6)
#define SPI_CR1_MSTR (1U << 2)

#define GPIOA_ODR   (mock_gpioa_odr)
#define GPIOA_IDR   (mock_gpioa_idr)

#define ADS1256_CS_PIN   0
#define ADS1256_DRDY_PIN 1
#define ADS1256_RST_PIN  2

#define ADS1256_CS_LOW()   (GPIOA_ODR &= ~(1U << ADS1256_CS_PIN))
#define ADS1256_CS_HIGH()  (GPIOA_ODR |=  (1U << ADS1256_CS_PIN))
#define ADS1256_RST_LOW()  (GPIOA_ODR &= ~(1U << ADS1256_RST_PIN))
#define ADS1256_RST_HIGH() (GPIOA_ODR |=  (1U << ADS1256_RST_PIN))
#define ADS1256_DRDY_READ() ((GPIOA_IDR >> ADS1256_DRDY_PIN) & 0x01U)

/* ADS1256 命令 */
#define ADS1256_CMD_RREG   0x10
#define ADS1256_CMD_WREG   0x50
#define ADS1256_CMD_SELFCAL 0xF0
#define ADS1256_CMD_SYNC   0xFC
#define ADS1256_CMD_WAKEUP 0x00
#define ADS1256_CMD_RDATA  0x01
#define ADS1256_CMD_RESET  0xFE

/* ADS1256 寄存器地址 */
#define ADS1256_REG_STATUS 0x00
#define ADS1256_REG_MUX    0x01
#define ADS1256_REG_ADCON  0x02
#define ADS1256_REG_DRATE  0x03
#define ADS1256_REG_IO     0x04
#define ADS1256_REG_OFC0   0x05
#define ADS1256_REG_OFC1   0x06
#define ADS1256_REG_OFC2   0x07
#define ADS1256_REG_FSC0   0x08
#define ADS1256_REG_FSC1   0x09
#define ADS1256_REG_FSC2   0x0A

/* 采样率设置 (DRATE 寄存器值) */
#define ADS1256_DRATE_30KSPS   0xF0
#define ADS1256_DRATE_15KSPS   0xE0
#define ADS1256_DRATE_7_5KSPS  0xD0
#define ADS1256_DRATE_3_75KSPS 0xC0

/* 增益设置 (ADCON 寄存器值) */
#define ADS1256_GAIN_1  0x00
#define ADS1256_GAIN_2  0x01
#define ADS1256_GAIN_4  0x02
#define ADS1256_GAIN_8  0x03
#define ADS1256_GAIN_16 0x04
#define ADS1256_GAIN_32 0x05
#define ADS1256_GAIN_64 0x06

/* ==================== 软件延时 ==================== */
static void delay_us(uint32_t us)
{
    volatile uint32_t i;
    for (i = 0; i < us * 10; i++) {
        __asm__ volatile ("nop");
    }
}

static void delay_ms(uint32_t ms)
{
    while (ms--) {
        delay_us(1000);
    }
}

/* ==================== SPI 底层驱动 (Mock) ==================== */
static void spi_init(void)
{
    SPI_CR1 = SPI_CR1_MSTR | SPI_CR1_SPE;
}

static uint8_t spi_transfer(uint8_t tx_data)
{
    uint32_t timeout = 100000;

    while (!(SPI_SR & SPI_SR_TXE) && timeout--) {
        ;
    }
    SPI_DR = tx_data;

    /* 模拟接收: 直接返回发送的数据, 保证 RXNE 置位 */
    SPI_SR |= SPI_SR_RXNE;

    timeout = 100000;
    while (!(SPI_SR & SPI_SR_RXNE) && timeout--) {
        ;
    }
    return (uint8_t)(SPI_DR & 0xFF);
}

/* ==================== ADS1256 驱动 ==================== */
static void ads1256_write_reg(uint8_t reg, uint8_t value)
{
    ADS1256_CS_LOW();
    spi_transfer(ADS1256_CMD_WREG | reg);
    spi_transfer(0x00);
    spi_transfer(value);
    ADS1256_CS_HIGH();
}

static uint8_t ads1256_read_reg(uint8_t reg)
{
    uint8_t value;
    ADS1256_CS_LOW();
    spi_transfer(ADS1256_CMD_RREG | reg);
    spi_transfer(0x00);
    value = spi_transfer(0xFF);
    ADS1256_CS_HIGH();
    return value;
}

static void ads1256_send_cmd(uint8_t cmd)
{
    ADS1256_CS_LOW();
    spi_transfer(cmd);
    ADS1256_CS_HIGH();
}

static void ads1256_reset(void)
{
    ADS1256_RST_LOW();
    delay_us(10);
    ADS1256_RST_HIGH();
    delay_ms(10);
    ads1256_send_cmd(ADS1256_CMD_RESET);
    delay_ms(10);
}

static void ads1256_init(void)
{
    ads1256_reset();

    ads1256_write_reg(ADS1256_REG_STATUS, 0x04);
    ads1256_write_reg(ADS1256_REG_MUX, 0x01);
    ads1256_write_reg(ADS1256_REG_ADCON, ADS1256_GAIN_1);
    ads1256_write_reg(ADS1256_REG_DRATE, ADS1256_DRATE_30KSPS);
    ads1256_write_reg(ADS1256_REG_IO, 0x00);

    ads1256_send_cmd(ADS1256_CMD_SELFCAL);
    delay_ms(50);
}

static int32_t ads1256_read_data(void)
{
    int32_t value = 0;
    uint8_t buf[3];
    uint32_t timeout = 100000;

    /* 等待 DRDY 变低 (数据就绪) */
    while (ADS1256_DRDY_READ() && timeout--) {
        ;
    }
    if (timeout == 0) {
        return -1;
    }

    ADS1256_CS_LOW();
    spi_transfer(ADS1256_CMD_RDATA);
    delay_us(2);
    buf[0] = spi_transfer(0xFF);
    buf[1] = spi_transfer(0xFF);
    buf[2] = spi_transfer(0xFF);
    ADS1256_CS_HIGH();

    value = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2];

    /* 24 位有符号数扩展 */
    if (value & 0x00800000) {
        value |= 0xFF000000;
    }

    return value;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    int32_t adc_value;
    int i;

    printf("ADS1256 SPI Driver Test\n");
    printf("=======================\n");

    spi_init();
    printf("SPI initialized.\n");

    ads1256_init();
    printf("ADS1256 initialized.\n");

    printf("STATUS = 0x%02X\n", ads1256_read_reg(ADS1256_REG_STATUS));
    printf("MUX    = 0x%02X\n", ads1256_read_reg(ADS1256_REG_MUX));
    printf("ADCON  = 0x%02X\n", ads1256_read_reg(ADS1256_REG_ADCON));
    printf("DRATE  = 0x%02X\n", ads1256_read_reg(ADS1256_REG_DRATE));

    printf("\nSampling 10 times:\n");
    for (i = 0; i < 10; i++) {
        adc_value = ads1256_read_data();
        if (adc_value < 0) {
            printf("Sample %2d: timeout\n", i);
        } else {
            printf("Sample %2d: raw = %8ld, voltage = %.6f V\n",
                   i, (long)adc_value,
                   (double)adc_value * 5.0 / 8388608.0);
        }
    }

    printf("\nTest complete.\n");
    return 0;
}
