/* ==================== Mock I2C 寄存器与宏定义 ==================== */
#define I2C_OK              0
#define I2C_ERR             1

/* INA219 寄存器地址 */
#define INA219_REG_CONFIG       0x00
#define INA219_REG_SHUNT_VOLT   0x01
#define INA219_REG_BUS_VOLT     0x02
#define INA219_REG_POWER        0x03
#define INA219_REG_CURRENT      0x04
#define INA219_REG_CALIBRATION  0x05

/* INA219 配置值: 32V, 320mV shunt, 12bit ADC, 连续模式 */
#define INA219_CONFIG_VALUE     0x399F

/* 校准值: 针对 0.1 ohm 分流电阻, 最大预期电流 3.2A */
#define INA219_CALIBRATION_VALUE 4096

/* 分流电阻值 (欧姆) */
#define SHUNT_RESISTOR_OHM      0.1f

/* 电流 LSB = 1 / 4096 A = 0.2441 mA */
#define CURRENT_LSB             0.0002441f

/* 总线电压 LSB = 4 mV */
#define BUS_VOLTAGE_LSB         0.004f

/* 分流电压 LSB = 10 uV */
#define SHUNT_VOLTAGE_LSB       0.00001f

/* 功率 LSB = 20 * CURRENT_LSB */
#define POWER_LSB               (20.0f * CURRENT_LSB)

/* ==================== Mock I2C 底层接口 ==================== */
typedef struct {
    uint8_t  dev_addr;
    uint8_t  reg_addr;
    uint16_t reg_data;
} MockI2CDevice;

static MockI2CDevice g_ina219 = { 0x40, 0, 0 };

/* 模拟 I2C 写寄存器 */
static int mock_i2c_write(uint8_t dev_addr, uint8_t reg, uint16_t data)
{
    g_ina219.dev_addr = dev_addr;
    g_ina219.reg_addr = reg;
    g_ina219.reg_data = data;
    return I2C_OK;
}

/* 模拟 I2C 读寄存器 */
static int mock_i2c_read(uint8_t dev_addr, uint8_t reg, uint16_t *data)
{
    (void)dev_addr;
    (void)reg;
    /* 模拟返回数据: 总线电压约 12V, 分流电压约 10mV, 电流约 100mA */
    switch (reg) {
        case INA219_REG_BUS_VOLT:
            *data = (uint16_t)(12.0f / BUS_VOLTAGE_LSB) & 0xFFF8;
            break;
        case INA219_REG_SHUNT_VOLT:
            *data = (uint16_t)(0.01f / SHUNT_VOLTAGE_LSB);
            break;
        case INA219_REG_CURRENT:
            *data = (uint16_t)(0.1f / CURRENT_LSB);
            break;
        case INA219_REG_POWER:
            *data = (uint16_t)(1.2f / POWER_LSB);
            break;
        default:
            *data = 0;
            break;
    }
    return I2C_OK;
}

/* ==================== INA219 驱动接口 ==================== */
static int ina219_init(uint8_t dev_addr)
{
    int ret;

    /* 写配置寄存器 */
    ret = mock_i2c_write(dev_addr, INA219_REG_CONFIG, INA219_CONFIG_VALUE);
    if (ret != I2C_OK) {
        printf("INA219: config write failed\n");
        return ret;
    }

    /* 写校准寄存器 */
    ret = mock_i2c_write(dev_addr, INA219_REG_CALIBRATION, INA219_CALIBRATION_VALUE);
    if (ret != I2C_OK) {
        printf("INA219: calibration write failed\n");
        return ret;
    }

    printf("INA219: init done (addr=0x%02X)\n", dev_addr);
    return I2C_OK;
}

static int ina219_read_bus_voltage(uint8_t dev_addr, float *voltage)
{
    uint16_t raw;
    int ret = mock_i2c_read(dev_addr, INA219_REG_BUS_VOLT, &raw);
    if (ret != I2C_OK) {
        return ret;
    }
    /* 总线电压: bit3~bit15, 右移 3 位, LSB = 4mV */
    *voltage = (float)(raw >> 3) * BUS_VOLTAGE_LSB;
    return I2C_OK;
}

static int ina219_read_shunt_voltage(uint8_t dev_addr, float *voltage)
{
    uint16_t raw;
    int ret = mock_i2c_read(dev_addr, INA219_REG_SHUNT_VOLT, &raw);
    if (ret != I2C_OK) {
        return ret;
    }
    /* 分流电压为有符号 16 位, LSB = 10uV */
    *voltage = (float)(int16_t)raw * SHUNT_VOLTAGE_LSB;
    return I2C_OK;
}

static int ina219_read_current(uint8_t dev_addr, float *current)
{
    uint16_t raw;
    int ret = mock_i2c_read(dev_addr, INA219_REG_CURRENT, &raw);
    if (ret != I2C_OK) {
        return ret;
    }
    /* 电流为有符号 16 位, LSB = CURRENT_LSB */
    *current = (float)(int16_t)raw * CURRENT_LSB;
    return I2C_OK;
}

static int ina219_read_power(uint8_t dev_addr, float *power)
{
    uint16_t raw;
    int ret = mock_i2c_read(dev_addr, INA219_REG_POWER, &raw);
    if (ret != I2C_OK) {
        return ret;
    }
    /* 功率为无符号 16 位, LSB = 20 * CURRENT_LSB */
    *power = (float)raw * POWER_LSB;
    return I2C_OK;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint8_t dev_addr = 0x40;
    float bus_voltage = 0.0f;
    float shunt_voltage = 0.0f;
    float current = 0.0f;
    float power = 0.0f;
    int ret;

    printf("===== INA219 Voltage/Current Monitor =====\n");

    ret = ina219_init(dev_addr);
    if (ret != I2C_OK) {
        printf("INA219 init failed, ret=%d\n", ret);
        return -1;
    }

    ret = ina219_read_bus_voltage(dev_addr, &bus_voltage);
    if (ret == I2C_OK) {
        printf("Bus Voltage   : %.3f V\n", bus_voltage);
    } else {
        printf("Read bus voltage failed\n");
    }

    ret = ina219_read_shunt_voltage(dev_addr, &shunt_voltage);
    if (ret == I2C_OK) {
        printf("Shunt Voltage : %.3f mV\n", shunt_voltage * 1000.0f);
    } else {
        printf("Read shunt voltage failed\n");
    }

    ret = ina219_read_current(dev_addr, &current);
    if (ret == I2C_OK) {
        printf("Current       : %.3f mA\n", current * 1000.0f);
    } else {
        printf("Read current failed\n");
    }

    ret = ina219_read_power(dev_addr, &power);
    if (ret == I2C_OK) {
        printf("Power         : %.3f W\n", power);
    } else {
        printf("Read power failed\n");
    }

    printf("===== Monitor Done =====\n");
    return 0;
}
