```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* ==================== 寄存器与硬件抽象层 mock ==================== */

/* 使用普通变量模拟寄存器，避免访问非法地址导致段错误 */
static uint32_t mock_spi_cr1 = 0;
static uint32_t mock_spi_cr2 = 0;
static uint32_t mock_spi_sr  = 0;
static uint32_t mock_spi_dr  = 0;

static uint32_t mock_gpioa_moder = 0;
static uint32_t mock_gpioa_odr   = 0;
static uint32_t mock_gpioa_bsrr  = 0;

/* SPI 控制寄存器位定义 */
#define SPI_CR1_SPE         (1UL << 6)
#define SPI_CR1_MSTR        (1UL << 2)
#define SPI_CR1_BR_SHIFT    3
#define SPI_CR1_BR_MASK     (7UL << SPI_CR1_BR_SHIFT)
#define SPI_CR1_CPOL        (1UL << 1)
#define SPI_CR1_CPHA        (1UL << 0)
#define SPI_CR1_SSM         (1UL << 9)
#define SPI_CR1_SSI         (1UL << 8)
#define SPI_CR1_DFF         (1UL << 11)
#define SPI_CR1_LSBFIRST    (1UL << 7)

/* SPI 状态寄存器位定义 */
#define SPI_SR_TXE          (1UL << 1)
#define SPI_SR_RXNE         (1UL << 0)
#define SPI_SR_BSY          (1UL << 7)

/* GPIO 模式定义 */
#define GPIO_MODE_OUTPUT    0x01UL
#define GPIO_MODE_AF        0x02UL

/* DAC8552 命令定义 */
#define DAC8552_CMD_WRITE   0x00
#define DAC8552_CMD_UPDATE  0x08
#define DAC8552_CMD_POWER   0x10
#define DAC8552_CMD_RESET   0x18

/* DAC8552 通道选择 */
#define DAC8552_CH_A        0x00
#define DAC8552_CH_B        0x01

/* DAC8552 参考电压（伏特） */
#define DAC8552_VREF        2.500f

/* 寄存器访问宏（映射到 mock 变量） */
#define SPI_CR1             (mock_spi_cr1)
#define SPI_CR2             (mock_spi_cr2)
#define SPI_SR              (mock_spi_sr)
#define SPI_DR              (mock_spi_dr)

#define GPIOA_MODER         (mock_gpioa_moder)
#define GPIOA_ODR           (mock_gpioa_odr)
#define GPIOA_BSRR          (mock_gpioa_bsrr)

/* 片选引脚定义（PA4） */
#define DAC_CS_PIN          4
#define DAC_CS_LOW()        (GPIOA_BSRR = (1UL << (DAC_CS_PIN + 16)))
#define DAC_CS_HIGH()       (GPIOA_BSRR = (1UL << DAC_CS_PIN))

/* 延时函数（模拟） */
static void delay_us(uint32_t us)
{
    volatile uint32_t i;
    for (i = 0; i < us * 10; i++) {
        __asm__ volatile ("nop");
    }
}

/* ==================== SPI 驱动层 ==================== */

/**
 * @brief 初始化 SPI 外设（主机模式，模式1，8位数据，软件NSS）
 */
static void spi_init(void)
{
    /* 配置 PA4 为通用推挽输出（片选） */
    GPIOA_MODER &= ~(3UL << (DAC_CS_PIN * 2));
    GPIOA_MODER |=  (GPIO_MODE_OUTPUT << (DAC_CS_PIN * 2));
    DAC_CS_HIGH();

    /* 配置 PA5(SCK), PA6(MISO), PA7(MOSI) 为复用功能 */
    GPIOA_MODER &= ~((3UL << (5 * 2)) | (3UL << (6 * 2)) | (3UL << (7 * 2)));
    GPIOA_MODER |=  ((GPIO_MODE_AF << (5 * 2)) |
                     (GPIO_MODE_AF << (6 * 2)) |
                     (GPIO_MODE_AF << (7 * 2)));

    /* 配置 SPI 控制寄存器 */
    SPI_CR1 = 0;
    SPI_CR1 |= SPI_CR1_MSTR;
    SPI_CR1 |= SPI_CR1_SSM | SPI_CR1_SSI;
    SPI_CR1 |= SPI_CR1_CPOL;
    SPI_CR1 |= SPI_CR1_CPHA;
    SPI_CR1 &= ~SPI_CR1_DFF;
    SPI_CR1 &= ~SPI_CR1_LSBFIRST;
    SPI_CR1 &= ~SPI_CR1_BR_MASK;
    SPI_CR1 |= (2UL << SPI_CR1_BR_SHIFT);
    SPI_CR1 |= SPI_CR1_SPE;

    /* 初始化状态寄存器：TXE 置位表示发送缓冲区空 */
    SPI_SR |= SPI_SR_TXE;
}

/**
 * @brief SPI 发送并接收一个字节
 * @param tx_data 待发送数据
 * @return 接收到的数据
 */
static uint8_t spi_transfer_byte(uint8_t tx_data)
{
    uint32_t timeout = 100000;

    /* 等待发送缓冲区空 */
    while (!(SPI_SR & SPI_SR_TXE)) {
        if (--timeout == 0) return 0;
    }

    /* 写入数据寄存器 */
    SPI_DR = tx_data;

    /* 模拟：发送完成后 TXE 置位，RXNE 置位 */
    SPI_SR |= SPI_SR_TXE;
    SPI_SR |= SPI_SR_RXNE;

    /* 等待接收缓冲区非空 */
    timeout = 100000;
    while (!(SPI_SR & SPI_SR_RXNE)) {
        if (--timeout == 0) return 0;
    }

    /* 清除 RXNE */
    SPI_SR &= ~SPI_SR_RXNE;

    return (uint8_t)(SPI_DR & 0xFF);
}

/**
 * @brief SPI 发送一个字节（不关心接收）
 */
static void spi_send_byte(uint8_t data)
{
    (void)spi_transfer_byte(data);
}

/* ==================== DAC8552 驱动层 ==================== */

/**
 * @brief 向 DAC8552 写入 24 位数据
 * @param channel 通道选择（DAC8552_CH_A 或 DAC8552_CH_B）
 * @param command 命令字
 * @param data 16 位数据
 */
static void dac8552_write(uint8_t channel, uint8_t command, uint16_t data)
{
    uint8_t frame[3];

    /* 构造 24 位帧 */
    frame[0] = (uint8_t)((command << 3) | ((channel & 0x03) << 1) | ((data >> 15) & 0x01));
    frame[1] = (uint8_t)((data >> 7) & 0xFF);
    frame[2] = (uint8_t)((data << 1) & 0xFE);

    /* 拉低片选 */
    DAC_CS_LOW();

    /* 发送 3 字节 */
    spi_send_byte(frame[0]);
    spi_send_byte(frame[1]);
    spi_send_byte(frame[2]);

    /* 拉高片选 */
    DAC_CS_HIGH();

    /* 等待转换完成 */
    delay_us(10);
}

/**
 * @brief 初始化 DAC8552
 */
static void dac8552_init(void)
{
    /* 复位 DAC */
    dac8552_write(DAC8552_CH_A, DAC8552_CMD_RESET, 0x0000);
    delay_us(100);

    /* 上电通道 A 和 B */
    dac8552_write(DAC8552_CH_A, DAC8552_CMD_POWER, 0x0000);
    delay_us(100);
}

/**
 * @brief 设置 DAC8552 指定通道的输出电压
 * @param channel 通道选择
 * @param voltage 目标电压（伏特），范围 0 ~ VREF
 */
static void dac8552_set_voltage(uint8_t channel, float voltage)
{
    uint16_t dac_code;
    float vref = DAC8552_VREF;

    /* 限幅 */
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > vref) voltage = vref;

    /* 计算 DAC 码值：code = (Vout / Vref) * 65535 */
    dac_code = (uint16_t)((voltage / vref) * 65535.0f + 0.5f);

    /* 写入并更新 DAC 寄存器 */
    dac8552_write(channel, DAC8552_CMD_WRITE, dac_code);
}

/**
 * @brief 设置 DAC8552 指定通道的原始码值
 * @param channel 通道选择
 * @param code 16 位码值
 */
static void dac8552_set_code(uint8_t channel, uint16_t code)
{
    dac8552_write(channel, DAC8552_CMD_WRITE, code);
}

/* ==================== 主函数 ==================== */

int main(void)
{
    printf("========================================\n");
    printf("  DAC8552 SPI Driver Test (Mock)\n");
    printf("========================================\n\n");

    /* 初始化 SPI */
    printf("[INIT] Initializing SPI...\n");
    spi_init();
    printf("[INIT] SPI initialized (Master, Mode 1, 8-bit, fPCLK/8)\n");

    /* 初始化 DAC8552 */
    printf("[INIT] Initializing DAC8552...\n");
    dac8552_init();
    printf("[INIT] DAC8552 initialized\n\n");

    /* 测试 1：设置通道 A 输出电压 */
    printf("[TEST 1] Set Channel A voltage:\n");
    {
        float voltages[] = {0.0f, 0.5f, 1.0f, 1.25f, 2.0f, 2.5f};
        int i;
        for (i = 0; i < 6; i++) {
            uint16_t code = (uint16_t)((voltages[i] / DAC8552_VREF) * 65535.0f + 0.5f);
            dac8552_set_voltage(DAC8552_CH_A, voltages[i]);
            printf("  CH-A: %.3f V -> code = 0x%04X (%u)\n",
                   voltages[i], code, code);
        }
    }
    printf("\n");

    /* 测试 2：设置通道 B 输出电压 */
    printf("[TEST 2] Set Channel B voltage:\n");
    {
        float voltages[] = {0.0f, 0.625f, 1.25f, 1.875f, 2.5f};
        int i;
        for (i = 0; i < 5; i++) {
            uint16_t code = (uint16_t)((voltages[i] / DAC8552_VREF) * 65535.0f + 0.5f);
            dac8552_set_voltage(DAC8552_CH_B, voltages[i]);
            printf("  CH-B: %.3f V -> code = 0x%04X (%u)\n",
                   voltages[i], code, code);
        }
    }
    printf("\n");

    /* 测试 3：直接设置原始码值 */
    printf("[TEST 3] Set raw codes:\n");
    {
        uint16_t codes[] = {0x0000, 0x4000, 0x8000, 0xC000, 0xFFFF};
        int i;
        for (i = 0; i < 5; i++) {
            dac8552_set_code(DAC8552_CH_A, codes[i]);
            printf("  CH-A: code = 0x%04X -> %.4f V\n",
                   codes[i], (codes[i] / 65535.0f) * DAC8552_VREF);
        }
    }
    printf("\n");

    /* 测试 4：边界条件 */
    printf("[TEST 4] Boundary conditions:\n");
    {
        dac8552_set_voltage(DAC8552_CH_A, -1.0f);
        printf("  CH-A: -1.0 V (clamped) -> 0.000 V\n");

        dac8552_set_voltage(DAC8552_CH_A, 3.3f);
        printf("  CH-A: 3.3 V (clamped) -> %.3f V\n", DAC8552_VREF);

        dac8552_set_voltage(DAC8552_CH_A, 1.25f);
        printf("  CH-A: 1.25 V -> code = 0x%04X\n",
               (uint16_t)((1.25f / DAC8552_VREF) * 65535.0f + 0.5f));
    }
    printf("\n");

    printf("========================================\n");
    printf("  All tests completed successfully.\n");
    printf("========================================\n");

    return 0;
}
