#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

static uint32_t g_can_mcr = 0U;
static uint32_t g_can_msr = 0U;
static uint32_t g_can_tsr = 0U;
static uint32_t g_can_ier = 0U;
static uint32_t g_can_esr = 0U;
static uint32_t g_can_btr = 0U;

#define CAN_MCR      g_can_mcr
#define CAN_MSR      g_can_msr
#define CAN_TSR      g_can_tsr
#define CAN_IER      g_can_ier
#define CAN_ESR      g_can_esr
#define CAN_BTR      g_can_btr

#define CAN_MCR_INRQ        (1U << 0)
#define CAN_MCR_SLEEP       (1U << 1)
#define CAN_MCR_TXFP        (1U << 2)
#define CAN_MCR_RFLM        (1U << 3)
#define CAN_MCR_NART        (1U << 4)
#define CAN_MCR_AWUM        (1U << 5)
#define CAN_MCR_ABOM        (1U << 6)
#define CAN_MCR_TTCM        (1U << 7)
#define CAN_MCR_RESET       (1U << 15)
#define CAN_MCR_DBF         (1U << 16)

#define CAN_MSR_INAK        (1U << 0)
#define CAN_MSR_SLAK        (1U << 1)
#define CAN_MSR_ERRI        (1U << 2)
#define CAN_MSR_WKUI        (1U << 3)
#define CAN_MSR_SLAKI       (1U << 4)
#define CAN_MSR_TXM         (1U << 8)
#define CAN_MSR_RXM         (1U << 9)
#define CAN_MSR_SAMP        (1U << 10)
#define CAN_MSR_RX          (1U << 11)

#define CAN_TSR_RQCP0       (1U << 0)
#define CAN_TSR_TXOK0       (1U << 1)
#define CAN_TSR_ALST0       (1U << 2)
#define CAN_TSR_TERR0       (1U << 3)
#define CAN_TSR_ABRQ0       (1U << 7)

#define CAN_ESR_EWGF        (1U << 0)
#define CAN_ESR_EPVF        (1U << 1)
#define CAN_ESR_BOFF        (1U << 2)
#define CAN_ESR_LEC_SHIFT   4
#define CAN_ESR_LEC_MASK    (0x7U << CAN_ESR_LEC_SHIFT)
#define CAN_ESR_TEC_SHIFT   16
#define CAN_ESR_TEC_MASK    (0xFFU << CAN_ESR_TEC_SHIFT)
#define CAN_ESR_REC_SHIFT   24
#define CAN_ESR_REC_MASK    (0xFFU << CAN_ESR_REC_SHIFT)

#define CAN_IER_TMEIE       (1U << 0)
#define CAN_IER_FMPIE0      (1U << 1)
#define CAN_IER_FFIE0       (1U << 2)
#define CAN_IER_FOVIE0      (1U << 3)
#define CAN_IER_FMPIE1      (1U << 4)
#define CAN_IER_FFIE1       (1U << 5)
#define CAN_IER_FOVIE1      (1U << 6)
#define CAN_IER_EWGIE       (1U << 8)
#define CAN_IER_EPVIE       (1U << 9)
#define CAN_IER_BOFIE       (1U << 10)
#define CAN_IER_LECIE       (1U << 11)
#define CAN_IER_ERRIE       (1U << 15)
#define CAN_IER_WKUIE       (1U << 16)
#define CAN_IER_SLKIE       (1U << 17)

#define CAN_BTR_BRP_SHIFT   0
#define CAN_BTR_BRP_MASK    (0x3FFU << CAN_BTR_BRP_SHIFT)
#define CAN_BTR_TS1_SHIFT   16
#define CAN_BTR_TS1_MASK    (0xFU << CAN_BTR_TS1_SHIFT)
#define CAN_BTR_TS2_SHIFT   20
#define CAN_BTR_TS2_MASK    (0x7U << CAN_BTR_TS2_SHIFT)
#define CAN_BTR_SJW_SHIFT   24
#define CAN_BTR_SJW_MASK    (0x3U << CAN_BTR_SJW_SHIFT)
#define CAN_BTR_LBKM        (1U << 30)
#define CAN_BTR_SILM        (1U << 31)

typedef enum {
    CAN_STATE_NORMAL = 0,
    CAN_STATE_ERROR_WARNING,
    CAN_STATE_ERROR_PASSIVE,
    CAN_STATE_BUS_OFF,
    CAN_STATE_RECOVERING,
    CAN_STATE_INIT
} CanState_t;

typedef struct {
    CanState_t state;
    uint32_t   recoveryDelayMs;
    uint32_t   recoveryTimerMs;
    uint32_t   recoveryAttempts;
    uint32_t   maxRecoveryAttempts;
    uint32_t   busOffCount;
    uint32_t   lastErrorCode;
    uint32_t   tec;
    uint32_t   rec;
    bool       autoRecoveryEnabled;
} CanFaultHandler_t;

static uint32_t g_mockTimeMs = 0;

static uint32_t Mock_GetTickMs(void)
{
    return g_mockTimeMs;
}

static void Mock_DelayMs(uint32_t ms)
{
    g_mockTimeMs += ms;
}

static void Mock_CanWriteReg(volatile uint32_t *reg, uint32_t value)
{
    *reg = value;
}

static uint32_t Mock_CanReadReg(volatile uint32_t *reg)
{
    return *reg;
}

static void Can_EnterInitMode(void)
{
    uint32_t mcr = Mock_CanReadReg(&CAN_MCR);
    mcr |= CAN_MCR_INRQ;
    Mock_CanWriteReg(&CAN_MCR, mcr);

    uint32_t msr = Mock_CanReadReg(&CAN_MSR);
    msr |= CAN_MSR_INAK;
    Mock_CanWriteReg(&CAN_MSR, msr);
}

static void Can_ExitInitMode(void)
{
    uint32_t mcr = Mock_CanReadReg(&CAN_MCR);
    mcr &= ~CAN_MCR_INRQ;
    Mock_CanWriteReg(&CAN_MCR, mcr);

    uint32_t msr = Mock_CanReadReg(&CAN_MSR);
    msr &= ~CAN_MSR_INAK;
    Mock_CanWriteReg(&CAN_MSR, msr);
}

static void Can_ConfigureBitTiming(void)
{
    uint32_t btr = 0U;
    btr |= (3U << CAN_BTR_BRP_SHIFT);
    btr |= (12U << CAN_BTR_TS1_SHIFT);
    btr |= (2U << CAN_BTR_TS2_SHIFT);
    btr |= (1U << CAN_BTR_SJW_SHIFT);
    Mock_CanWriteReg(&CAN_BTR, btr);
}

static void Can_EnableInterrupts(void)
{
    uint32_t ier = 0U;
    ier |= CAN_IER_TMEIE;
    ier |= CAN_IER_ERRIE;
    ier |= CAN_IER_BOFIE;
    ier |= CAN_IER_EPVIE;
    ier |= CAN_IER_EWGIE;
    ier |= CAN_IER_LECIE;
    Mock_CanWriteReg(&CAN_IER, ier);
}

static void Can_DisableInterrupts(void)
{
    Mock_CanWriteReg(&CAN_IER, 0U);
}

static void Can_ClearErrorFlags(void)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    esr &= ~CAN_ESR_LEC_MASK;
    Mock_CanWriteReg(&CAN_ESR, esr);
}

static void Can_AbortAllTxMailboxes(void)
{
    uint32_t tsr = Mock_CanReadReg(&CAN_TSR);
    tsr |= CAN_TSR_ABRQ0;
    Mock_CanWriteReg(&CAN_TSR, tsr);
}

static void Can_ResetPeripheral(void)
{
    uint32_t mcr = Mock_CanReadReg(&CAN_MCR);
    mcr &= ~CAN_MCR_RESET;
    Mock_CanWriteReg(&CAN_MCR, mcr);
}

static void Can_Init(void)
{
    Can_ResetPeripheral();
    Can_EnterInitMode();

    uint32_t mcr = Mock_CanReadReg(&CAN_MCR);
    mcr &= ~CAN_MCR_SLEEP;
    mcr |= CAN_MCR_ABOM;
    mcr |= CAN_MCR_NART;
    mcr &= ~CAN_MCR_TXFP;
    mcr &= ~CAN_MCR_RFLM;
    mcr &= ~CAN_MCR_DBF;
    Mock_CanWriteReg(&CAN_MCR, mcr);

    Can_ConfigureBitTiming();
    Can_ExitInitMode();
    Can_EnableInterrupts();
}

static void CanFault_Init(CanFaultHandler_t *handler)
{
    handler->state = CAN_STATE_INIT;
    handler->recoveryDelayMs = 100U;
    handler->recoveryTimerMs = 0U;
    handler->recoveryAttempts = 0U;
    handler->maxRecoveryAttempts = 5U;
    handler->busOffCount = 0U;
    handler->lastErrorCode = 0U;
    handler->tec = 0U;
    handler->rec = 0U;
    handler->autoRecoveryEnabled = true;
}

static void CanFault_UpdateErrorCounters(CanFaultHandler_t *handler)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    handler->tec = (esr & CAN_ESR_TEC_MASK) >> CAN_ESR_TEC_SHIFT;
    handler->rec = (esr & CAN_ESR_REC_MASK) >> CAN_ESR_REC_SHIFT;
    handler->lastErrorCode = (esr & CAN_ESR_LEC_MASK) >> CAN_ESR_LEC_SHIFT;
}

static void CanFault_UpdateState(CanFaultHandler_t *handler)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);

    if ((esr & CAN_ESR_BOFF) != 0U) {
        handler->state = CAN_STATE_BUS_OFF;
        handler->busOffCount++;
        return;
    }

    if ((esr & CAN_ESR_EPVF) != 0U) {
        handler->state = CAN_STATE_ERROR_PASSIVE;
        return;
    }

    if ((esr & CAN_ESR_EWGF) != 0U) {
        handler->state = CAN_STATE_ERROR_WARNING;
        return;
    }

    handler->state = CAN_STATE_NORMAL;
}

static void CanFault_StartRecovery(CanFaultHandler_t *handler)
{
    printf("[FAULT] Bus-Off detected! TEC=%u REC=%u, starting recovery...\n",
           handler->tec, handler->rec);

    Can_DisableInterrupts();
    Can_AbortAllTxMailboxes();
    Can_ClearErrorFlags();

    handler->state = CAN_STATE_RECOVERING;
    handler->recoveryTimerMs = Mock_GetTickMs();
    handler->recoveryAttempts++;
}

static bool CanFault_ProcessRecovery(CanFaultHandler_t *handler)
{
    uint32_t elapsed = Mock_GetTickMs() - handler->recoveryTimerMs;

    if (elapsed < handler->recoveryDelayMs) {
        return false;
    }

    printf("[RECOVERY] Attempt %u/%u, re-initializing CAN...\n",
           handler->recoveryAttempts, handler->maxRecoveryAttempts);

    Can_Init();

    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    if ((esr & CAN_ESR_BOFF) == 0U) {
        printf("[RECOVERY] Success! CAN back to normal.\n");
        handler->state = CAN_STATE_NORMAL;
        handler->recoveryAttempts = 0U;
        return true;
    }

    printf("[RECOVERY] Failed, will retry...\n");
    handler->recoveryTimerMs = Mock_GetTickMs();
    return false;
}

static void CanFault_Handle(CanFaultHandler_t *handler)
{
    CanFault_UpdateErrorCounters(handler);
    CanFault_UpdateState(handler);

    switch (handler->state) {
    case CAN_STATE_NORMAL:
        break;

    case CAN_STATE_ERROR_WARNING:
        printf("[WARN] Error warning: TEC=%u REC=%u\n",
               handler->tec, handler->rec);
        break;

    case CAN_STATE_ERROR_PASSIVE:
        printf("[WARN] Error passive: TEC=%u REC=%u\n",
               handler->tec, handler->rec);
        break;

    case CAN_STATE_BUS_OFF:
        if (handler->autoRecoveryEnabled) {
            CanFault_StartRecovery(handler);
        } else {
            printf("[FAULT] Bus-Off, auto recovery disabled.\n");
        }
        break;

    case CAN_STATE_RECOVERING:
        if (handler->recoveryAttempts >= handler->maxRecoveryAttempts) {
            printf("[FAULT] Max recovery attempts reached, giving up.\n");
            handler->state = CAN_STATE_BUS_OFF;
            break;
        }
        (void)CanFault_ProcessRecovery(handler);
        break;

    case CAN_STATE_INIT:
        Can_Init();
        handler->state = CAN_STATE_NORMAL;
        break;

    default:
        break;
    }
}

static void Mock_SetBusOff(void)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    esr |= CAN_ESR_BOFF;
    esr |= (250U << CAN_ESR_TEC_SHIFT);
    esr |= (128U << CAN_ESR_REC_SHIFT);
    Mock_CanWriteReg(&CAN_ESR, esr);
}

static void Mock_ClearBusOff(void)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    esr &= ~CAN_ESR_BOFF;
    esr &= ~CAN_ESR_TEC_MASK;
    esr &= ~CAN_ESR_REC_MASK;
    Mock_CanWriteReg(&CAN_ESR, esr);
}

static void Mock_SetErrorWarning(void)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    esr |= CAN_ESR_EWGF;
    esr |= (100U << CAN_ESR_TEC_SHIFT);
    esr |= (100U << CAN_ESR_REC_SHIFT);
    Mock_CanWriteReg(&CAN_ESR, esr);
}

static void Mock_SetErrorPassive(void)
{
    uint32_t esr = Mock_CanReadReg(&CAN_ESR);
    esr |= CAN_ESR_EPVF;
    esr |= (200U << CAN_ESR_TEC_SHIFT);
    esr |= (150U << CAN_ESR_REC_SHIFT);
    Mock_CanWriteReg(&CAN_ESR, esr);
}

int main(void)
{
    CanFaultHandler_t handler;

    printf("===== CAN Bus-Off Fault Handler Test =====\n\n");

    CanFault_Init(&handler);
    Can_Init();
    handler.state = CAN_STATE_NORMAL;

    printf("--- Test 1: Normal state ---\n");
    Mock_ClearBusOff();
    CanFault_Handle(&handler);
    printf("State: %d (expected 0)\n\n", handler.state);

    printf("--- Test 2: Error Warning ---\n");
    Mock_SetErrorWarning();
    CanFault_Handle(&handler);
    printf("State: %d (expected 1)\n\n", handler.state);

    printf("--- Test 3: Error Passive ---\n");
    Mock_SetErrorPassive();
    CanFault_Handle(&handler);
    printf("State: %d (expected 2)\n\n", handler.state);

    printf("--- Test 4: Bus-Off with auto recovery ---\n");
    Mock_SetBusOff();
    CanFault_Handle(&handler);
    printf("State after bus-off: %d (expected 4)\n", handler.state);
    printf("BusOff count: %u\n\n", handler.busOffCount);

    printf("--- Test 5: Recovery in progress ---\n");
    Mock_DelayMs(50);
    CanFault_Handle(&handler);
    printf("State: %d (expected 4, still recovering)\n\n", handler.state);

    printf("--- Test 6: Recovery complete ---\n");
    Mock_ClearBusOff();
    Mock_DelayMs(100);
    CanFault_Handle(&handler);
    printf("State: %d (expected 0)\n", handler.state);
    printf("Recovery attempts: %u\n\n", handler.recoveryAttempts);

    printf("===== All tests done =====\n");
    return 0;
}
