#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* ================= Modbus RTU 协议定义 ================= */
#define MODBUS_FUNC_READ_HOLDING_REG    0x03
#define MODBUS_FUNC_WRITE_SINGLE_REG    0x06
#define MODBUS_FUNC_WRITE_MULTI_REG     0x10

#define MODBUS_EXC_ILLEGAL_FUNCTION     0x01
#define MODBUS_EXC_ILLEGAL_DATA_ADDR    0x02
#define MODBUS_EXC_ILLEGAL_DATA_VALUE   0x03

#define MODBUS_RTU_SLAVE_ADDR           0x01
#define HOLDING_REG_COUNT               16

static uint16_t g_holding_regs[HOLDING_REG_COUNT];

/* ================= CRC16 (Modbus) ================= */
static uint16_t modbus_crc16(const uint8_t *data, uint16_t len)
{
    uint16_t crc = 0xFFFF;
    uint16_t i;
    uint8_t j;
    for (i = 0; i < len; i++) {
        crc ^= (uint16_t)data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc = (crc >> 1) ^ 0xA001;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

/* ================= Modbus RTU 从机处理 ================= */
static uint16_t modbus_build_exception(uint8_t *resp, uint8_t slave_addr,
                                       uint8_t func, uint8_t exc_code)
{
    uint16_t crc;
    resp[0] = slave_addr;
    resp[1] = func | 0x80;
    resp[2] = exc_code;
    crc = modbus_crc16(resp, 3);
    resp[3] = (uint8_t)(crc & 0xFF);
    resp[4] = (uint8_t)(crc >> 8);
    return 5;
}

static uint16_t modbus_slave_process(const uint8_t *req, uint16_t req_len,
                                     uint8_t *resp)
{
    uint8_t slave_addr;
    uint8_t func;
    uint16_t crc_calc;
    uint16_t crc_recv;

    if (req_len < 4) {
        return 0;
    }

    slave_addr = req[0];
    func       = req[1];

    if (slave_addr != MODBUS_RTU_SLAVE_ADDR && slave_addr != 0x00) {
        return 0;
    }

    crc_calc = modbus_crc16(req, req_len - 2);
    crc_recv = (uint16_t)req[req_len - 2] |
               ((uint16_t)req[req_len - 1] << 8);
    if (crc_calc != crc_recv) {
        return 0;
    }

    if (func == MODBUS_FUNC_READ_HOLDING_REG) {
        uint16_t start_addr;
        uint16_t reg_count;
        uint16_t resp_len;
        uint16_t crc;
        uint16_t i;

        if (req_len != 8) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_VALUE);
        }
        start_addr = ((uint16_t)req[2] << 8) | req[3];
        reg_count  = ((uint16_t)req[4] << 8) | req[5];

        if (reg_count == 0 || reg_count > 125) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_VALUE);
        }
        if ((uint32_t)start_addr + reg_count > HOLDING_REG_COUNT) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_ADDR);
        }

        resp[0] = slave_addr;
        resp[1] = func;
        resp[2] = (uint8_t)(reg_count * 2);
        for (i = 0; i < reg_count; i++) {
            uint16_t val = g_holding_regs[start_addr + i];
            resp[3 + i * 2]     = (uint8_t)(val >> 8);
            resp[3 + i * 2 + 1] = (uint8_t)(val & 0xFF);
        }
        resp_len = 3 + reg_count * 2;
        crc = modbus_crc16(resp, resp_len);
        resp[resp_len]     = (uint8_t)(crc & 0xFF);
        resp[resp_len + 1] = (uint8_t)(crc >> 8);
        return resp_len + 2;
    }
    else if (func == MODBUS_FUNC_WRITE_SINGLE_REG) {
        uint16_t reg_addr;
        uint16_t reg_val;
        uint16_t crc;

        if (req_len != 8) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_VALUE);
        }
        reg_addr = ((uint16_t)req[2] << 8) | req[3];
        reg_val  = ((uint16_t)req[4] << 8) | req[5];

        if (reg_addr >= HOLDING_REG_COUNT) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_ADDR);
        }
        g_holding_regs[reg_addr] = reg_val;

        memcpy(resp, req, 6);
        crc = modbus_crc16(resp, 6);
        resp[6] = (uint8_t)(crc & 0xFF);
        resp[7] = (uint8_t)(crc >> 8);
        return 8;
    }
    else if (func == MODBUS_FUNC_WRITE_MULTI_REG) {
        uint16_t start_addr;
        uint16_t reg_count;
        uint8_t  byte_count;
        uint16_t crc;
        uint16_t i;

        if (req_len < 11) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_VALUE);
        }
        start_addr = ((uint16_t)req[2] << 8) | req[3];
        reg_count  = ((uint16_t)req[4] << 8) | req[5];
        byte_count = req[6];

        if (reg_count == 0 || reg_count > 123 ||
            byte_count != reg_count * 2 ||
            req_len != (uint16_t)(9 + byte_count)) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_VALUE);
        }
        if ((uint32_t)start_addr + reg_count > HOLDING_REG_COUNT) {
            return modbus_build_exception(resp, slave_addr, func,
                                          MODBUS_EXC_ILLEGAL_DATA_ADDR);
        }

        for (i = 0; i < reg_count; i++) {
            g_holding_regs[start_addr + i] =
                ((uint16_t)req[7 + i * 2] << 8) | req[8 + i * 2];
        }

        resp[0] = slave_addr;
        resp[1] = func;
        resp[2] = (uint8_t)(start_addr >> 8);
        resp[3] = (uint8_t)(start_addr & 0xFF);
        resp[4] = (uint8_t)(reg_count >> 8);
        resp[5] = (uint8_t)(reg_count & 0xFF);
        crc = modbus_crc16(resp, 6);
        resp[6] = (uint8_t)(crc & 0xFF);
        resp[7] = (uint8_t)(crc >> 8);
        return 8;
    }
    else {
        return modbus_build_exception(resp, slave_addr, func,
                                      MODBUS_EXC_ILLEGAL_FUNCTION);
    }
}

/* ================= Modbus RTU 主机请求构建 ================= */
static uint16_t modbus_master_build_read_req(uint8_t slave_addr,
                                             uint16_t start_addr,
                                             uint16_t reg_count,
                                             uint8_t *req)
{
    uint16_t crc;
    req[0] = slave_addr;
    req[1] = MODBUS_FUNC_READ_HOLDING_REG;
    req[2] = (uint8_t)(start_addr >> 8);
    req[3] = (uint8_t)(start_addr & 0xFF);
    req[4] = (uint8_t)(reg_count >> 8);
    req[5] = (uint8_t)(reg_count & 0xFF);
    crc = modbus_crc16(req, 6);
    req[6] = (uint8_t)(crc & 0xFF);
    req[7] = (uint8_t)(crc >> 8);
    return 8;
}

static uint16_t modbus_master_build_write_req(uint8_t slave_addr,
                                              uint16_t reg_addr,
                                              uint16_t reg_val,
                                              uint8_t *req)
{
    uint16_t crc;
    req[0] = slave_addr;
    req[1] = MODBUS_FUNC_WRITE_SINGLE_REG;
    req[2] = (uint8_t)(reg_addr >> 8);
    req[3] = (uint8_t)(reg_addr & 0xFF);
    req[4] = (uint8_t)(reg_val >> 8);
    req[5] = (uint8_t)(reg_val & 0xFF);
    crc = modbus_crc16(req, 6);
    req[6] = (uint8_t)(crc & 0xFF);
    req[7] = (uint8_t)(crc >> 8);
    return 8;
}

/* ================= 测试打印 ================= */
static void print_hex(const char *tag, const uint8_t *data, uint16_t len)
{
