#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 模拟 RS485 收发器方向控制引脚寄存器 */
static volatile uint32_t g_rs485_dir_reg = 0U;
static volatile uint32_t g_uart_data_reg = 0U;
static volatile uint32_t g_uart_status_reg = 0U;
static volatile uint32_t g_rs485_bus_idle_reg = 0U;

#define RS485_DIR_REG       (g_rs485_dir_reg)
#define RS485_DIR_TX        (1U << 0)   /* 1: 发送模式 */
#define RS485_DIR_RX        (0U << 0)   /* 0: 接收模式 */

#define UART_DATA_REG       (g_uart_data_reg)
#define UART_STATUS_REG     (g_uart_status_reg)
#define UART_STATUS_TXE     (1U << 0)   /* 发送寄存器空 */
#define UART_STATUS_RXNE    (1U << 1)   /* 接收寄存器非空 */

#define RS485_BUS_IDLE_REG  (g_rs485_bus_idle_reg)
#define RS485_BUS_IDLE      (1U << 0)

/* ================= 协议常量定义 ================= */
#define RS485_ADDR_BROADCAST    0xFFU
#define RS485_FRAME_HEAD        0xAAU
#define RS485_FRAME_TAIL        0x55U
#define RS485_MAX_PAYLOAD       32U
#define RS485_TIMEOUT_MS        100U

/* 本机地址 */
static uint8_t g_local_addr = 0x01U;

/* ================= 帧结构定义 ================= */
typedef struct {
    uint8_t  head;
    uint8_t  addr;
    uint8_t  cmd;
    uint8_t  len;
    uint8_t  data[RS485_MAX_PAYLOAD];
    uint16_t crc;
    uint8_t  tail;
} RS485_Frame_t;

/* ================= CRC16 校验（Modbus 风格） ================= */
static uint16_t rs485_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFFU;
    uint16_t i;
    uint8_t  j;

    for (i = 0U; i < len; i++) {
        crc ^= (uint16_t)buf[i];
        for (j = 0U; j < 8U; j++) {
            if ((crc & 0x0001U) != 0U) {
                crc = (uint16_t)((crc >> 1) ^ 0xA001U);
            } else {
                crc = (uint16_t)(crc >> 1);
            }
        }
    }
    return crc;
}

/* ================= 硬件抽象层（HAL） ================= */
static void rs485_set_tx_mode(void)
{
    RS485_DIR_REG |= RS485_DIR_TX;
}

static void rs485_set_rx_mode(void)
{
    RS485_DIR_REG &= ~RS485_DIR_TX;
}

static bool rs485_bus_is_idle(void)
{
    return (RS485_BUS_IDLE_REG & RS485_BUS_IDLE) != 0U;
}

static bool uart_tx_ready(void)
{
    return (UART_STATUS_REG & UART_STATUS_TXE) != 0U;
}

static bool uart_rx_ready(void)
{
    return (UART_STATUS_REG & UART_STATUS_RXNE) != 0U;
}

static void uart_write_byte(uint8_t byte)
{
    uint32_t timeout = RS485_TIMEOUT_MS * 1000U;
    while ((!uart_tx_ready()) && (timeout > 0U)) {
        timeout--;
    }
    UART_DATA_REG = (uint32_t)byte;
}

static uint8_t uart_read_byte(void)
{
    return (uint8_t)(UART_DATA_REG & 0xFFU);
}

/* ================= RS485 发送帧 ================= */
static bool rs485_send_frame(const RS485_Frame_t *frame)
{
    uint8_t  raw[RS485_MAX_PAYLOAD + 6U];
    uint16_t idx = 0U;
    uint16_t i;
    uint16_t crc;

    if (frame == NULL) {
        return false;
    }
    if (frame->len > RS485_MAX_PAYLOAD) {
        return false;
    }

    raw[idx++] = frame->head;
    raw[idx++] = frame->addr;
    raw[idx++] = frame->cmd;
    raw[idx++] = frame->len;
    for (i = 0U; i < frame->len; i++) {
        raw[idx++] = frame->data[i];
    }

    crc = rs485_crc16(raw, idx);
    raw[idx++] = (uint8_t)(crc & 0xFFU);
    raw[idx++] = (uint8_t)((crc >> 8) & 0xFFU);
    raw[idx++] = RS485_FRAME_TAIL;

    /* 等待总线空闲 */
    {
        uint32_t wait = RS485_TIMEOUT_MS * 1000U;
        while ((!rs485_bus_is_idle()) && (wait > 0U)) {
            wait--;
        }
        if (wait == 0U) {
            return false;
        }
    }

    rs485_set_tx_mode();

    for (i = 0U; i < idx; i++) {
        uart_write_byte(raw[i]);
    }

    {
        uint32_t wait = RS485_TIMEOUT_MS * 1000U;
        while ((!uart_tx_ready()) && (wait > 0U)) {
            wait--;
        }
    }

    rs485_set_rx_mode();

    return true;
}

/* ================= RS485 接收帧（非阻塞轮询） ================= */
static bool rs485_receive_frame(RS485_Frame_t *frame)
{
    static uint8_t  rx_buf[RS485_MAX_PAYLOAD + 6U];
    static uint16_t rx_idx = 0U;
    static bool     in_frame = false;
    uint8_t         byte;
    uint16_t        crc_calc;
    uint16_t        crc_recv;

    if (frame == NULL) {
        return false;
    }

    while (uart_rx_ready()) {
        byte = uart_read_byte();

        if (!in_frame) {
            if (byte == RS485_FRAME_HEAD) {
                in_frame = true;
                rx_idx = 0U;
                rx_buf[rx_idx++] = byte;
            }
            continue;
        }

        if (rx_idx < (uint16_t)(RS485_MAX_PAYLOAD + 6U)) {
            rx_buf[rx_idx++] = byte;
        } else {
            in_frame = false;
            rx_idx = 0U;
            continue;
        }

        if (byte == RS485_FRAME_TAIL) {
            in_frame = false;

            if (rx_idx < 7U) {
                rx_idx = 0U;
                continue;
            }

            crc_recv = (uint16_t)rx_buf[rx_idx - 3U] |
                       ((uint16_t)rx_buf[rx_idx - 2U] << 8);
            crc_calc = rs485_crc16(rx_buf, (uint16_t)(rx_idx - 3U));

            if (crc_calc != crc_recv) {
                rx_idx = 0U;
                continue;
            }

            frame->head = rx_buf[0];
            frame->addr = rx_buf[1];
            frame->cmd  = rx_buf[2];
            frame->len  = rx_buf[3];

            if (frame->len > RS485_MAX_PAYLOAD) {
                rx_idx = 0U;
                continue;
            }

            if ((uint16_t)(frame->len + 6U) != rx_idx) {
                rx_idx = 0U;
                continue;
            }

            {
                uint16_t i;
                for (i = 0U; i < frame->len; i++) {
                    frame->data[i] = rx_buf[4U + i];
                }
            }
            frame->crc  = crc_recv;
            frame->tail = RS485_FRAME_TAIL;

            rx_idx = 0U;
            return true;
        }
    }

    return false;
}

/* ================= 地址匹配 ================= */
static bool rs485_addr_match(uint8_t frame_addr)
{
    if (frame_addr == RS485_ADDR_BROADCAST) {
        return true;
    }
    return (frame_addr == g_local_addr);
}

/* ================= 应用层处理 ================= */
static void rs485_process_frame(const RS485_Frame_t *frame)
{
    if (frame == NULL) {
        return;
    }

    printf("[RS485] 收到帧: addr=0x%02X cmd=0x%02X len=%u\n",
           frame->addr, frame->cmd, frame->len);

    if (!rs485_addr_match(frame->addr)) {
        printf("[RS485] 地址不匹配 (本机=0x%02X)，忽略\n", g_local_addr);
        return;
    }

    printf("[RS485] 地址匹配成功，处理命令 0x%02X\n", frame->cmd);

    switch (frame->cmd) {
        case 0x01U: {
            RS485_Frame_t resp;
            uint8_t i;
            resp.head = RS485_FRAME_HEAD;
            resp.addr = frame->addr;
            resp.cmd  = 0x81U;
            resp.len  = frame->len;
            for (i = 0U; i < frame->len; i++) {
                resp.data[i] = frame->data[i];
            }
            resp.crc  = 0U;
            resp.tail = RS485_FRAME_TAIL;
            (void)rs485_send_frame(&resp);
            printf("[RS485] 已发送回显响应\n");
            break;
        }
        case 0x02U:
            printf("[RS485] 执行命令 0x02\n");
            break;
        default:
            printf("[RS485] 未知命令 0x%02X\n", frame->cmd);
            break;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    RS485_Frame_t tx_frame;
    RS485_Frame_t rx_frame;
    uint8_t i;

    printf("===== RS485 通信控制算法骨架 =====\n");
    printf("本机地址: 0x%02X\n", g_local_addr);

    /* 初始化：默认接收模式，总线空闲 */
    rs485_set_rx_mode();
    RS485_BUS_IDLE_REG |= RS485_BUS_IDLE;
    UART_STATUS_REG |= UART_STATUS_TXE;
    printf("[初始化] RS485 收发器设置为接收模式\n");

    /* 构造测试发送帧 */
    tx_frame.head = RS485_FRAME_HEAD;
    tx_frame.addr = 0x02U;
    tx_frame.cmd  = 0x01U;
    tx_frame.len  = 4U;
    tx_frame.data[0] = 0x11U;
    tx_frame.data[1] = 0x22U;
    tx_frame.data[2] = 0x33U;
    tx_frame.data[3] = 0x44U;
    tx_frame.crc  = 0U;
    tx_frame.tail = RS485_FRAME_TAIL;

    printf("\n[发送] 构造帧: addr=0x%02X cmd=0x%02X len=%u data=",
           tx_frame.addr, tx_frame.cmd, tx_frame.len);
    for (i = 0U; i < tx_frame.len; i++) {
        printf("%02X ", tx_frame.data[i]);
    }
    printf("\n");

    if (rs485_send_frame(&tx_frame)) {
        printf("[发送] 成功\n");
    } else {
        printf("[发送] 失败（总线忙或超时）\n");
    }

    /* 模拟接收处理（轮询） */
    printf("\n[接收] 开始轮询...\n");
    {
        uint32_t poll_count = 0U;
        while (poll_count < 1000U) {
            if (rs485_receive_frame(&rx_frame)) {
                rs485_process_frame(&rx_frame);
                break;
            }
            poll_count++;
        }
        if (poll_count >= 1000U) {
            printf("[接收] 轮询超时，未收到有效帧\n");
        }
    }

    /* 地址匹配测试 */
    printf("\n[测试] 地址匹配验证:\n");
    printf("  帧地址 0x01 -> %s\n",
           rs485_addr_match(0x01U) ? "匹配" : "不匹配");
    printf("  帧地址 0x02 -> %s\n",
           rs485_addr_match(0x02U) ? "匹配" : "不匹配");
    printf("  帧地址 0xFF -> %s\n",
           rs485_addr_match(0xFFU) ? "匹配(广播)" : "不匹配");

    /* CRC 测试 */
    printf("\n[测试] CRC16 计算:\n");
    {
        uint8_t test_data[] = {0xAAU, 0x01U, 0x01U, 0x04U,
                               0x11U, 0x22U, 0x33U, 0x44U};
        uint16_t crc = rs485_crc16(test_data, sizeof(test_data));
        printf("  CRC16 = 0x%04X\n", crc);
    }

    printf("\n===== 程序结束 =====\n");
    return 0;
}
