#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ========== 硬件寄存器模拟（mock） ========== */
static volatile uint32_t mock_gpioa_idr = 0xFFFFFFFFU;
#define GPIOA_IDR       (mock_gpioa_idr)

/* 光耦输入引脚定义（假设接在 PA0） */
#define OPTO_IN_PIN     0x00000001U
#define OPTO_IN_ACTIVE  0U          /* 光耦导通时引脚为低电平 */

/* 消抖时间配置（单位：ms） */
#define DEBOUNCE_TIME_MS    20U
#define SAMPLE_PERIOD_MS    1U

/* ========== 光耦输入信号处理结构体 ========== */
typedef struct {
    uint8_t  stable_state;      /* 消抖后的稳定状态：0-无效/断开，1-有效/导通 */
    uint8_t  last_raw_state;    /* 上一次采样的原始状态 */
    uint16_t debounce_counter;  /* 消抖计数器 */
    uint16_t debounce_time;     /* 消抖时间（采样次数） */
} OptoInput_t;

/* ========== 初始化光耦输入处理 ========== */
void OptoInput_Init(OptoInput_t *input, uint16_t debounce_ms)
{
    input->stable_state     = 0;
    input->last_raw_state   = 0;
    input->debounce_counter = 0;
    input->debounce_time    = debounce_ms / SAMPLE_PERIOD_MS;
    if (input->debounce_time == 0) {
        input->debounce_time = 1;
    }
}

/* ========== 读取光耦原始电平（带硬件抽象） ========== */
static uint8_t OptoInput_ReadRaw(void)
{
    if ((GPIOA_IDR & OPTO_IN_PIN) == OPTO_IN_ACTIVE) {
        return 1;   /* 光耦导通，信号有效 */
    } else {
        return 0;   /* 光耦截止，信号无效 */
    }
}

/* ========== 光耦输入消抖处理（周期调用，建议 1ms 一次） ========== */
uint8_t OptoInput_Process(OptoInput_t *input)
{
    uint8_t raw_state = OptoInput_ReadRaw();

    if (raw_state != input->last_raw_state) {
        input->last_raw_state   = raw_state;
        input->debounce_counter = 0;
    } else {
        if (input->debounce_counter < input->debounce_time) {
            input->debounce_counter++;
        }
    }

    if (input->debounce_counter >= input->debounce_time) {
        input->stable_state = raw_state;
    }

    return input->stable_state;
}

/* ========== 获取消抖后的稳定状态 ========== */
uint8_t OptoInput_GetStableState(const OptoInput_t *input)
{
    return input->stable_state;
}

/* ========== 测试用：模拟 GPIO 输入变化 ========== */
static void Mock_SetOptoInput(uint8_t active)
{
    if (active) {
        mock_gpioa_idr &= ~OPTO_IN_PIN;  /* 光耦导通，引脚拉低 */
    } else {
        mock_gpioa_idr |= OPTO_IN_PIN;   /* 光耦截止，引脚拉高 */
    }
}

/* ========== 主函数测试 ========== */
int main(void)
{
    OptoInput_t opto_input;
    uint32_t    tick;
    uint8_t     prev_stable = 0;

    printf("===== 光耦隔离输入信号处理（消抖）测试 =====\n");
    printf("消抖时间: %u ms, 采样周期: %u ms\n\n",
           (unsigned)DEBOUNCE_TIME_MS, (unsigned)SAMPLE_PERIOD_MS);

    /* 初始化：默认光耦截止 */
    mock_gpioa_idr = OPTO_IN_PIN;
    OptoInput_Init(&opto_input, DEBOUNCE_TIME_MS);

    printf("--- 场景1: 光耦导通 5ms（小于消抖时间，应被滤除）---\n");
    for (tick = 0; tick < 50; tick++) {
        if (tick == 10) {
            Mock_SetOptoInput(1);
        }
        if (tick == 15) {
            Mock_SetOptoInput(0);
        }

        OptoInput_Process(&opto_input);

        if (opto_input.stable_state != prev_stable) {
            printf("  [t=%2ums] 稳定状态变化: %u -> %u\n",
                   (unsigned)tick, (unsigned)prev_stable,
                   (unsigned)opto_input.stable_state);
            prev_stable = opto_input.stable_state;
        }
    }
    printf("  场景1结束，最终稳定状态: %u\n\n",
           (unsigned)opto_input.stable_state);

