#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 硬件寄存器定义 ================= */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint8_t  g_opto_input_reg = 0x0F;   /* 默认所有通道高电平 */
static volatile uint32_t g_systick_ms_reg = 0;

#define OPTO_INPUT_REG      (g_opto_input_reg)
#define SYSTICK_MS_REG      (g_systick_ms_reg)

/* ================= 消抖参数配置 ================= */
#define DEBOUNCE_TIME_MS    20U     /* 消抖时间：20ms */
#define SAMPLE_PERIOD_MS    1U      /* 采样周期：1ms */

/* ================= 光耦输入通道定义 ================= */
typedef enum {
    OPTO_CH0 = 0,
    OPTO_CH1,
    OPTO_CH2,
    OPTO_CH3,
    OPTO_CH_NUM
} OptoChannel_t;

/* ================= 消抖状态机 ================= */
typedef enum {
    DEBOUNCE_STATE_IDLE = 0,
    DEBOUNCE_STATE_COUNTING,
    DEBOUNCE_STATE_STABLE
} DebounceState_t;

/* ================= 光耦输入通道数据结构 ================= */
typedef struct {
    DebounceState_t state;
    uint8_t         raw_level;
    uint8_t         stable_level;
    uint16_t        counter;
    uint8_t         prev_raw;
} OptoInput_t;

/* ================= 全局变量 ================= */
static OptoInput_t g_opto_inputs[OPTO_CH_NUM];

/* ================= 函数声明 ================= */
static void OptoInput_Init(void);
static void OptoInput_Process(void);
static uint8_t OptoInput_ReadRaw(OptoChannel_t ch);
static uint8_t OptoInput_GetStable(OptoChannel_t ch);
static void OptoInput_PrintStatus(void);

/* ================= 初始化 ================= */
static void OptoInput_Init(void)
{
    uint8_t i;
    for (i = 0; i < OPTO_CH_NUM; i++) {
        g_opto_inputs[i].state        = DEBOUNCE_STATE_IDLE;
        g_opto_inputs[i].raw_level    = 1;
        g_opto_inputs[i].stable_level = 1;
        g_opto_inputs[i].counter      = 0;
        g_opto_inputs[i].prev_raw     = 1;
    }
}

/* ================= 读取原始电平 ================= */
static uint8_t OptoInput_ReadRaw(OptoChannel_t ch)
{
    uint8_t reg_val = OPTO_INPUT_REG;
    return (uint8_t)((reg_val >> ch) & 0x01U);
}

/* ================= 获取消抖后的稳定电平 ================= */
static uint8_t OptoInput_GetStable(OptoChannel_t ch)
{
    if (ch >= OPTO_CH_NUM) {
        return 1;
    }
    return g_opto_inputs[ch].stable_level;
}

/* ================= 消抖处理核心 ================= */
static void OptoInput_Process(void)
{
    uint8_t i;
    for (i = 0; i < OPTO_CH_NUM; i++) {
        OptoInput_t *p = &g_opto_inputs[i];
        uint8_t raw = OptoInput_ReadRaw((OptoChannel_t)i);

        switch (p->state) {
        case DEBOUNCE_STATE_IDLE:
            if (raw != p->stable_level) {
                p->raw_level = raw;
                p->counter   = 1;
                p->state     = DEBOUNCE_STATE_COUNTING;
            }
            break;

        case DEBOUNCE_STATE_COUNTING:
            if (raw == p->raw_level) {
                p->counter++;
                if (p->counter >= DEBOUNCE_TIME_MS) {
                    p->stable_level = p->raw_level;
                    p->counter      = 0;
                    p->state        = DEBOUNCE_STATE_STABLE;
                }
            } else {
                p->raw_level = raw;
                p->counter   = 1;
            }
            break;

        case DEBOUNCE_STATE_STABLE:
            if (raw != p->stable_level) {
                p->raw_level = raw;
                p->counter   = 1;
                p->state     = DEBOUNCE_STATE_COUNTING;
            }
            break;

        default:
            p->state = DEBOUNCE_STATE_IDLE;
            break;
        }

        p->prev_raw = raw;
    }
}

/* ================= 打印状态 ================= */
static void OptoInput_PrintStatus(void)
{
    uint8_t i;
    printf("OPTO: ");
    for (i = 0; i < OPTO_CH_NUM; i++) {
        printf("CH%d[raw=%d,stable=%d,state=%d,cnt=%d] ",
               i,
               g_opto_inputs[i].raw_level,
               g_opto_inputs[i].stable_level,
               (int)g_opto_inputs[i].state,
               g_opto_inputs[i].counter);
    }
    printf("\n");
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t tick;
    uint32_t last_tick = 0;
    uint8_t i;

    printf("=== Opto Isolated Input Debounce Demo ===\n");
    printf("Debounce time: %u ms, Sample period: %u ms\n\n",
           (unsigned)DEBOUNCE_TIME_MS, (unsigned)SAMPLE_PERIOD_MS);

    OptoInput_Init();

    for (tick = 0; tick < 100; tick++) {
        SYSTICK_MS_REG = tick;

        if (tick == 10) {
            OPTO_INPUT_REG = 0x00;
            printf("[t=%3u ms] Hardware: all channels -> LOW\n", (unsigned)tick);
        }
        if (tick == 40) {
            OPTO_INPUT_REG = 0x01;
            printf("[t=%3u ms] Hardware: CH0 -> HIGH, others LOW\n", (unsigned)tick);
        }
        if (tick == 70) {
            OPTO_INPUT_REG = 0x0F;
            printf("[t=%3u ms] Hardware: all channels -> HIGH\n", (unsigned)tick);
        }

        if ((tick - last_tick) >= SAMPLE_PERIOD_MS) {
            last_tick = tick;
            OptoInput_Process();
        }

        if ((tick % 10) == 0) {
            printf("[t=%3u ms] ", (unsigned)tick);
            OptoInput_PrintStatus();
        }
    }

    printf("\n=== Final stable levels ===\n");
    for (i = 0; i < OPTO_CH_NUM; i++) {
        printf("CH%d stable = %d\n", i, OptoInput_GetStable((OptoChannel_t)i));
    }

    return 0;
}
