/* ==================== 模拟寄存器与硬件抽象层 ==================== */
#define ADC1_BASE           0x40012400U
#define ADC1_DR             (*(volatile uint32_t *)(ADC1_BASE + 0x4CU))
#define ADC1_CR2            (*(volatile uint32_t *)(ADC1_BASE + 0x08U))
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_SWSTART     (1U << 22)

#define TEMP_SENSOR_BASE    0x40013000U
#define TEMP_SENSOR_DR      (*(volatile uint32_t *)(TEMP_SENSOR_BASE + 0x00U))
#define TEMP_SENSOR_CR      (*(volatile uint32_t *)(TEMP_SENSOR_BASE + 0x04U))
#define TEMP_CR_START       (1U << 0)

/* ==================== 数据类型定义 ==================== */
typedef struct {
    float zero_offset;
    float gain;
    float temp_coeff_zero;
    float temp_coeff_gain;
    float ref_temp;
    uint32_t magic;
} CalibrationData_t;

#define CAL_MAGIC           0x5A5A1234U

/* ==================== 全局变量 ==================== */
static CalibrationData_t g_cal;
static CalibrationData_t g_nvm_storage;   /* 模拟非易失存储，使用普通内存 */
static float g_current_amps = 0.0f;

/* ==================== 硬件模拟函数 ==================== */
static uint32_t mock_adc_read(void)
{
    static uint32_t mock_val = 2048U;
    mock_val = (mock_val + 7U) % 4096U;
    return mock_val;
}

static float mock_temp_read(void)
{
    static float mock_temp = 25.0f;
    mock_temp += 0.1f;
    if (mock_temp > 45.0f) mock_temp = 15.0f;
    return mock_temp;
}

static void mock_nvm_write(const CalibrationData_t *data)
{
    g_nvm_storage = *data;
}

static int mock_nvm_read(CalibrationData_t *data)
{
    if (g_nvm_storage.magic != CAL_MAGIC) {
        return -1;
    }
    *data = g_nvm_storage;
    return 0;
}

/* ==================== 校准算法核心 ==================== */

static void cal_init_default(CalibrationData_t *cal)
{
    cal->zero_offset     = 2048.0f;
    cal->gain            = 0.0122f;
    cal->temp_coeff_zero = 0.5f;
    cal->temp_coeff_gain = -0.0001f;
    cal->ref_temp        = 25.0f;
    cal->magic           = CAL_MAGIC;
}

static void cal_load(CalibrationData_t *cal)
{
    if (mock_nvm_read(cal) != 0) {
        printf("[CAL] NVM 无有效校准数据，使用默认参数\n");
        cal_init_default(cal);
    } else {
        printf("[CAL] 从 NVM 加载校准参数成功\n");
    }
}

static void cal_save(const CalibrationData_t *cal)
{
    mock_nvm_write(cal);
    printf("[CAL] 校准参数已保存到 NVM\n");
}

static void cal_zero(CalibrationData_t *cal, uint32_t samples)
{
    uint64_t sum = 0;
    uint32_t i;

    if (samples == 0) samples = 1;

    printf("[CAL] 开始零点校准，采样 %u 次...\n", samples);
    for (i = 0; i < samples; i++) {
        sum += mock_adc_read();
    }
    cal->zero_offset = (float)sum / (float)samples;
    printf("[CAL] 零点校准完成，零点偏移 = %.2f ADC码\n", cal->zero_offset);
}

static void cal_gain(CalibrationData_t *cal, float known_current, uint32_t samples)
{
    uint64_t sum = 0;
    uint32_t i;
    float adc_avg;
    float delta;

    if (samples == 0) samples = 1;
    if (fabsf(known_current) < 1e-6f) {
        printf("[CAL] 增益校准失败：标准电流不能为零\n");
        return;
    }

    printf("[CAL] 开始增益校准，标准电流 = %.3f A，采样 %u 次...\n",
           known_current, samples);
    for (i = 0; i < samples; i++) {
        sum += mock_adc_read();
    }
    adc_avg = (float)sum / (float)samples;
    delta = adc_avg - cal->zero_offset;

    if (fabsf(delta) < 1e-6f) {
        printf("[CAL] 增益校准失败：ADC 变化量过小\n");
        return;
    }

    cal->gain = known_current / delta;
    printf("[CAL] 增益校准完成，增益 = %.6f A/ADC码\n", cal->gain);
}

static void cal_temp_compensation(CalibrationData_t *cal,
                                  float temp_low, float temp_high)
{
    float zero_low, zero_high;
    float gain_low, gain_high;
    float temp_span;

    printf("[CAL] 开始温度补偿校准，低温 = %.1f℃，高温 = %.1f℃\n",
           temp_low, temp_high);

    zero_low  = cal->zero_offset + cal->temp_coeff_zero * (temp_low - cal->ref_temp);
    zero_high = cal->zero_offset + cal->temp_coeff_zero * (temp_high - cal->ref_temp);

    gain_low  = cal->gain * (1.0f + cal->temp_coeff_gain * (temp_low - cal->ref_temp));
    gain_high = cal->gain * (1.0f + cal->temp_coeff_gain * (temp_high - cal->ref_temp));

    temp_span = temp_high - temp_low;
    if (fabsf(temp_span) < 1e-6f) {
        printf("[CAL] 温度补偿校准失败：温度跨度为零\n");
        return;
    }

    cal->temp_coeff_zero = (zero_high - zero_low) / temp_span;
    if (fabsf(gain_low) > 1e-6f) {
        cal->temp_coeff_gain = (gain_high - gain_low) / (gain_low * temp_span);
    }

    printf("[CAL] 温度补偿校准完成\n");
    printf("[CAL]   零点温度系数 = %.6f ADC码/℃\n", cal->temp_coeff_zero);
    printf("[CAL]   增益温度系数 = %.6f 1/℃\n", cal->temp_coeff_gain);
}

static float cal_compute_current(const CalibrationData_t *cal,
                                 uint32_t adc_raw, float temperature)
{
    float delta_temp;
    float zero_comp;
    float gain_comp;
    float current;

    delta_temp = temperature - cal->ref_temp;
    zero_comp  = cal->zero_offset + cal->temp_coeff_zero * delta_temp;
    gain_comp  = cal->gain * (1.0f + cal->temp_coeff_gain * delta_temp);
    current    = ((float)adc_raw - zero_comp) * gain_comp;

    return current;
}

static void cal_print(const CalibrationData_t *cal)
{
    printf("========== 校准参数 ==========\n");
    printf("  零点偏移       : %.2f ADC码\n", cal->zero_offset);
    printf("  增益           : %.6f A/ADC码\n", cal->gain);
    printf("  零点温度系数   : %.6f ADC码/℃\n", cal->temp_coeff_zero);
    printf("  增益温度系数   : %.6f 1/℃\n", cal->temp_coeff_gain);
    printf("  参考温度       : %.1f ℃\n", cal->ref_temp);
    printf("  有效性标志     : 0x%08X\n", cal->magic);
    printf("==============================\n");
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t adc_val;
    float temp;
    int i;

    printf("========================================\n");
    printf("  霍尔电流传感器校准算法（零点+增益+温度补偿）\n");
    printf("========================================\n\n");

    /* 初始化 NVM 存储为无效状态 */
    g_nvm_storage.magic = 0;

    /* 1. 加载校准参数 */
    cal_load(&g_cal);
    cal_print(&g_cal);

    /* 2. 零点校准 */
    printf("\n--- 步骤 1：零点校准 ---\n");
    cal_zero(&g_cal, 16);
    cal_print(&g_cal);

    /* 3. 增益校准 */
    printf("\n--- 步骤 2：增益校准 ---\n");
    cal_gain(&g_cal, 10.0f, 16);
    cal_print(&g_cal);

    /* 4. 温度补偿校准 */
    printf("\n--- 步骤 3：温度补偿校准 ---\n");
    cal_temp_compensation(&g_cal, 0.0f, 50.0f);
    cal_print(&g_cal);

    /* 5. 保存校准参数 */
    printf("\n--- 步骤 4：保存校准参数 ---\n");
    cal_save(&g_cal);

    /* 6. 模拟电流测量 */
    printf("\n--- 步骤 5：模拟电流测量（含温度补偿）---\n");
    for (i = 0; i < 5; i++) {
