               i + 1, adc_val, temp, g_current_amps);
    }

    /* 7. 验证 NVM 读取 */
    printf("\n--- 步骤 6：验证 NVM 读取 ---\n");
    {
        CalibrationData_t verify;
        if (mock_nvm_read(&verify) == 0) {
