#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ========== 模拟硬件寄存器与宏定义 ========== */
#define MOCK_ADC_RESOLUTION     4096.0f
#define MOCK_ADC_VREF           3.3f
#define MOCK_SENSOR_SENSITIVITY 0.025f
#define MOCK_SENSOR_OFFSET      1.65f

/* 模拟寄存器 */
typedef struct {
    volatile uint16_t adc_raw;
    volatile float    temperature;
} MockRegs_t;

static MockRegs_t mock_regs = { 0 };

/* ========== 非线性补偿参数 ========== */
#define CAL_POINTS  7

typedef struct {
    float raw_voltage;
    float true_voltage;
} CalPoint_t;

/* 校准表：原始电压 -> 真实电压（非线性补偿） */
static const CalPoint_t cal_table[CAL_POINTS] = {
    { 0.00f,  0.00f },
    { 0.50f,  0.48f },
    { 1.00f,  0.97f },
    { 1.65f,  1.65f },
    { 2.30f,  2.34f },
    { 2.80f,  2.86f },
    { 3.30f,  3.38f }
};

/* ========== 线性插值函数 ========== */
static float linear_interpolate(float x, float x0, float y0, float x1, float y1)
{
    if (x1 == x0) return y0;
    return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
}

/* ========== 非线性补偿函数 ========== */
static float nonlinear_compensate(float raw_voltage)
{
    int i;

    if (raw_voltage <= cal_table[0].raw_voltage)
        return cal_table[0].true_voltage;

    if (raw_voltage >= cal_table[CAL_POINTS - 1].raw_voltage)
        return cal_table[CAL_POINTS - 1].true_voltage;

    for (i = 0; i < CAL_POINTS - 1; i++) {
        if (raw_voltage >= cal_table[i].raw_voltage &&
            raw_voltage <= cal_table[i + 1].raw_voltage) {
            return linear_interpolate(
                raw_voltage,
                cal_table[i].raw_voltage,
                cal_table[i].true_voltage,
                cal_table[i + 1].raw_voltage,
                cal_table[i + 1].true_voltage
            );
        }
    }

    return raw_voltage;
}

/* ========== 温度漂移补偿 ========== */
static float temperature_compensate(float voltage, float temperature)
{
    const float ref_temp = 25.0f;
    const float temp_coeff = -0.0002f; /* 每摄氏度漂移系数 */
    float delta = temperature - ref_temp;
    return voltage * (1.0f + temp_coeff * delta);
}

/* ========== 读取 ADC 原始电压 ========== */
static float read_adc_voltage(void)
{
    /* 模拟读取寄存器 */
    uint16_t raw = mock_regs.adc_raw;
    return ((float)raw / MOCK_ADC_RESOLUTION) * MOCK_ADC_VREF;
}

/* ========== 霍尔电压传感器校准主流程 ========== */
static float hall_voltage_calibrate(void)
{
    float raw_voltage;
    float compensated;
    float final_voltage;

    /* 1. 读取 ADC 原始电压 */
    raw_voltage = read_adc_voltage();

    /* 2. 非线性补偿 */
    compensated = nonlinear_compensate(raw_voltage);

    /* 3. 温度漂移补偿 */
    final_voltage = temperature_compensate(compensated, mock_regs.temperature);

    /* 4. 转换为实际被测电压（去除传感器偏移与灵敏度） */
    final_voltage = (final_voltage - MOCK_SENSOR_OFFSET) / MOCK_SENSOR_SENSITIVITY;

    return final_voltage;
}

/* ========== 测试打印 ========== */
static void test_print(float adc_raw, float temp, float result)
{
    printf("ADC raw = %4.0f | Temp = %5.1f C | Calibrated Voltage = %8.4f V\n",
           adc_raw, temp, result);
}

/* ========== 主函数 ========== */
int main(void)
{
    float test_adc[] = { 0, 512, 1024, 2048, 3072, 3584, 4095 };
    float test_temp[] = { 25.0f, 25.0f, 25.0f, 25.0f, 25.0f, 25.0f, 25.0f };
    int i;

    printf("===== Hall Voltage Sensor Calibration Test =====\n");

    for (i = 0; i < (int)(sizeof(test_adc) / sizeof(test_adc[0])); i++) {
        mock_regs.adc_raw = (uint16_t)test_adc[i];
        mock_regs.temperature = test_temp[i];

        float result = hall_voltage_calibrate();
        test_print(test_adc[i], test_temp[i], result);
    }

    printf("===== Temperature Drift Test =====\n");
    mock_regs.adc_raw = 2048;
    for (i = 0; i < 5; i++) {
        float temp = 0.0f + i * 15.0f;
        mock_regs.temperature = temp;
        float result = hall_voltage_calibrate();
        test_print(2048, temp, result);
    }

    return 0;
}
