#define MOCK_ADC_RAW_REG        (g_mock_adc_raw)
#define MOCK_TEMP_RAW_REG       (g_mock_temp_raw)
#define MOCK_CALIB_MEM_BASE     (g_mock_calib_mem)

/* 模拟 ADC 参考电压（mV） */
#define ADC_VREF_MV             3300.0f
/* ADC 满量程（12 位） */
#define ADC_FULL_SCALE          4095.0f
/* 温度传感器零点电压（mV），对应 0°C */
#define TEMP_SENSOR_V0_MV       500.0f
/* 温度传感器灵敏度（mV/°C） */
#define TEMP_SENSOR_SENS_MV_C   10.0f
/* 霍尔传感器标称灵敏度（mV/A） */
#define HALL_NOMINAL_SENS_MV_A  40.0f
/* 霍尔传感器零点标称电压（mV） */
#define HALL_NOMINAL_ZERO_MV    2500.0f
/* 温度补偿系数（%/°C），典型霍尔传感器灵敏度温漂 */
#define HALL_TEMPCO_SENS_PCT_C  (-0.03f)
/* 温度补偿系数（mV/°C），典型霍尔传感器零点温漂 */
#define HALL_TEMPCO_ZERO_MV_C   (0.05f)

/* ================= 校准参数结构体 ================= */
typedef struct {
    float zero_offset_mv;       /* 零点偏移（mV），实际零点与标称零点的差值 */
    float gain_correction;      /* 增益校正系数，实际灵敏度 / 标称灵敏度 */
    float tempco_zero_mv_c;     /* 零点温度系数（mV/°C） */
    float tempco_gain_pct_c;    /* 灵敏度温度系数（%/°C） */
    float calib_temp_c;         /* 校准时温度（°C） */
    uint16_t magic;             /* 有效性标志 */
} HallCalibParams_t;

#define CALIB_MAGIC             0x5A5A

/* ================= 全局校准参数 ================= */
static HallCalibParams_t g_calib = {
    0.0f,
    1.0f,
    HALL_TEMPCO_ZERO_MV_C,
    HALL_TEMPCO_SENS_PCT_C,
    25.0f,
    CALIB_MAGIC
};

/* ================= 工具函数 ================= */

/* 将 ADC 原始值转换为电压（mV） */
static float adc_raw_to_mv(uint16_t raw)
{
    return ((float)raw / ADC_FULL_SCALE) * ADC_VREF_MV;
}

/* 读取温度（°C） */
static float read_temperature_c(void)
{
    uint16_t raw = MOCK_TEMP_RAW_REG;
    float v_mv = adc_raw_to_mv(raw);
    return (v_mv - TEMP_SENSOR_V0_MV) / TEMP_SENSOR_SENS_MV_C;
}

/* 读取霍尔传感器输出电压（mV） */
static float read_hall_voltage_mv(void)
{
    uint16_t raw = MOCK_ADC_RAW_REG;
    return adc_raw_to_mv(raw);
}

/* 保存校准参数到模拟 EEPROM */
static void calib_save(const HallCalibParams_t *p)
{
    volatile uint16_t *mem = MOCK_CALIB_MEM_BASE;
    union { float f; uint16_t u[2]; } conv;
    mem[0] = p->magic;
    conv.f = p->zero_offset_mv;     mem[1] = conv.u[0]; mem[2] = conv.u[1];
    conv.f = p->gain_correction;    mem[3] = conv.u[0]; mem[4] = conv.u[1];
    conv.f = p->tempco_zero_mv_c;   mem[5] = conv.u[0]; mem[6] = conv.u[1];
    conv.f = p->tempco_gain_pct_c;  mem[7] = conv.u[0]; mem[8] = conv.u[1];
    conv.f = p->calib_temp_c;       mem[9] = conv.u[0]; mem[10] = conv.u[1];
}

/* 从模拟 EEPROM 加载校准参数 */
static int calib_load(HallCalibParams_t *p)
{
    volatile uint16_t *mem = MOCK_CALIB_MEM_BASE;
    union { float f; uint16_t u[2]; } conv;
    if (mem[0] != CALIB_MAGIC) {
        return -1;
    }
    p->magic = mem[0];
    conv.u[0] = mem[1]; conv.u[1] = mem[2]; p->zero_offset_mv = conv.f;
    conv.u[0] = mem[3]; conv.u[1] = mem[4]; p->gain_correction = conv.f;
    conv.u[0] = mem[5]; conv.u[1] = mem[6]; p->tempco_zero_mv_c = conv.f;
    conv.u[0] = mem[7]; conv.u[1] = mem[8]; p->tempco_gain_pct_c = conv.f;
    conv.u[0] = mem[9]; conv.u[1] = mem[10]; p->calib_temp_c = conv.f;
    return 0;
}

/* ================= 校准算法 ================= */

/*
 * 零点校准：在无电流条件下测量传感器输出电压，
 * 计算实际零点与标称零点的差值。
 */
static void hall_calibrate_zero(HallCalibParams_t *p, float measured_zero_mv, float temp_c)
{
    p->zero_offset_mv = measured_zero_mv - HALL_NOMINAL_ZERO_MV;
    p->calib_temp_c = temp_c;
}

/*
 * 增益校准：在已知标准电流条件下测量传感器输出，
 * 计算实际灵敏度与标称灵敏度的比值。
 */
static void hall_calibrate_gain(HallCalibParams_t *p,
                                float measured_mv,
                                float ref_current_a,
                                float temp_c)
{
    float v_zero_actual = HALL_NOMINAL_ZERO_MV + p->zero_offset_mv;
    float delta_v = measured_mv - v_zero_actual;
    float expected_delta_v = ref_current_a * HALL_NOMINAL_SENS_MV_A;
    if (fabsf(expected_delta_v) > 1e-6f) {
        p->gain_correction = delta_v / expected_delta_v;
    } else {
        p->gain_correction = 1.0f;
    }
    p->calib_temp_c = temp_c;
}

/*
 * 温度补偿后的电流计算
 */
static float hall_get_current_a(const HallCalibParams_t *p,
                                float measured_mv,
                                float current_temp_c)
{
    float delta_temp = current_temp_c - p->calib_temp_c;
    float zero_offset_comp = p->zero_offset_mv + p->tempco_zero_mv_c * delta_temp;
    float sens_comp = HALL_NOMINAL_SENS_MV_A *
                      (1.0f + p->tempco_gain_pct_c * 0.01f * delta_temp) *
                      p->gain_correction;
    float v_zero = HALL_NOMINAL_ZERO_MV + zero_offset_comp;
    if (fabsf(sens_comp) < 1e-6f) {
        return 0.0f;
    }
    return (measured_mv - v_zero) / sens_comp;
}

/* ================= 测试主函数 ================= */
int main(void)
{
    printf("===== Hall Current Sensor Calibration (Zero + Gain + Temp Comp) =====\n\n");

    /* 模拟环境：设置温度 ADC 原始值，25°C -> 750mV -> raw ≈ 931 */
    MOCK_TEMP_RAW_REG = (uint16_t)(750.0f / ADC_VREF_MV * ADC_FULL_SCALE);

    /* --- 步骤 1：零点校准 --- */
    printf("[Step 1] Zero Calibration\n");
    {
        float zero_measured_mv = 2520.0f;
        float temp_now;
        float v_zero_read;
        MOCK_ADC_RAW_REG = (uint16_t)(zero_measured_mv / ADC_VREF_MV * ADC_FULL_SCALE);
        temp_now = read_temperature_c();
        v_zero_read = read_hall_voltage_mv();
        printf("  Temperature: %.2f C\n", temp_now);
        printf("  Measured zero voltage: %.2f mV\n", v_zero_read);
        hall_calibrate_zero(&g_calib, v_zero_read, temp_now);
        printf("  Zero offset: %.2f mV\n\n", g_calib.zero_offset_mv);
    }

    /* --- 步骤 2：增益校准 --- */
    printf("[Step 2] Gain Calibration\n");
    {
        float ref_current = 10.0f;
        float gain_measured_mv = 2940.0f;
        float v_gain_read;
        float temp_now = read_temperature_c();
        MOCK_ADC_RAW_REG = (uint16_t)(gain_measured_mv / ADC_VREF_MV * ADC_FULL_SCALE);
        v_gain_read = read_hall_voltage_mv();
        printf("  Reference current: %.2f A\n", ref_current);
        printf("  Measured voltage: %.2f mV\n", v_gain_read);
        hall_calibrate_gain(&g_calib, v_gain_read, ref_current, temp_now);
        printf("  Gain correction: %.4f\n\n", g_calib.gain_correction);
    }

    /* --- 步骤 3：保存校准参数 --- */
    printf("[Step 3] Save Calibration\n");
    calib_save(&g_calib);
    printf("  Calibration saved to mock EEPROM.\n\n");

    /* --- 步骤 4：加载并验证 --- */
    printf("[Step 4] Load & Verify\n");
    {
        HallCalibParams_t loaded;
        if (calib_load(&loaded) == 0) {
            printf("  Loaded zero offset: %.2f mV\n", loaded.zero_offset_mv);
            printf("  Loaded gain correction: %.4f\n", loaded.gain_correction);
            printf("  Loaded calib temp: %.2f C\n\n", loaded.calib_temp_c);

            /* --- 步骤 5：温度补偿电流测量 --- */
            printf("[Step 5] Temperature-Compensated Current Measurement\n");
            {
                float test_temp_c = 60.0f;
                float test_measured_mv = 3000.0f;
                float current = hall_get_current_a(&loaded, test_measured_mv, test_temp_c);
                float dt = test_temp_c - loaded.calib_temp_c;
                float zero_comp = loaded.zero_offset_mv + loaded.tempco_zero_mv_c * dt;
                float sens_comp = HALL_NOMINAL_SENS_MV_A *
                                  (1.0f + loaded.tempco_gain_pct_c * 0.01f * dt) *
                                  loaded.gain_correction;
                float v_zero = HALL_NOMINAL_ZERO_MV + zero_comp;

                printf("  Test temperature: %.2f C\n", test_temp_c);
                printf("  Measured voltage: %.2f mV\n", test_measured_mv);
                printf("  Calculated current: %.4f A\n", current);
                printf("  [Verify] Delta temp: %.2f C\n", dt);
                printf("  [Verify] Compensated zero offset: %.2f mV\n", zero_comp);
                printf("  [Verify] Compensated sensitivity: %.4f mV/A\n", sens_comp);
                printf("  [Verify] Actual zero voltage: %.2f mV\n", v_zero);
                printf("  [Verify] Current = (%.2f - %.2f) / %.4f = %.4f A\n",
                       test_measured_mv, v_zero, sens_comp,
                       (test_measured_mv - v_zero) / sens_comp);
            }
        } else {
            printf("  Load failed!\n\n");
        }
    }

    printf("\n===== Done =====\n");
    return 0;
}
