#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ============================================================
 * Mock 寄存器与硬件抽象层（不依赖任何单片机头文件）
 * 使用普通变量模拟寄存器，避免非法地址访问导致段错误
 * ============================================================ */

static volatile uint32_t mock_ADC_DR   = 0;
static volatile uint32_t mock_ADC_CR2  = 0;
static volatile uint32_t mock_ADC_SR   = 0;
static volatile uint32_t mock_GPIOA_ODR = 0;
static volatile uint32_t mock_TIM2_CR1 = 0;
static volatile uint32_t mock_TIM2_SR  = 0;

#define ADC_DR      (mock_ADC_DR)
#define ADC_CR2     (mock_ADC_CR2)
#define ADC_SR      (mock_ADC_SR)
#define GPIOA_ODR   (mock_GPIOA_ODR)
#define TIM2_CR1    (mock_TIM2_CR1)
#define TIM2_SR     (mock_TIM2_SR)

/* 位定义 */
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_SWSTART     (1U << 30)
#define ADC_SR_EOC          (1U << 1)
#define TIM2_CR1_CEN        (1U << 0)
#define TIM2_SR_UIF         (1U << 0)

/* ============================================================
 * PT 信号调理参数
 * ============================================================ */

#define PT_SECONDARY_RATED_VRMS     100.0f
#define ADC_VREF                    3.3f
#define ADC_FULL_SCALE              4095.0f

#define PT_GAIN_LOW                 1.0f
#define PT_GAIN_MID                 2.5f
#define PT_GAIN_HIGH                6.0f

#define RANGE_SWITCH_UP_TH          0.85f
#define RANGE_SWITCH_DOWN_TH        0.15f

#define OVERSAMPLE_COUNT            16
#define IIR_ALPHA                   0.15f

typedef enum {
    PT_RANGE_LOW = 0,
    PT_RANGE_MID = 1,
    PT_RANGE_HIGH = 2
} PT_Range_t;

typedef struct {
    PT_Range_t range;
    float      gain;
    float      adc_offset;
    float      filtered_peak;
    float      rms_voltage;
    uint32_t   sample_count;
} PT_Context_t;

/* ============================================================
 * 硬件抽象层（HAL）Mock 函数
 * ============================================================ */

static void HAL_ADC_Init(void)
{
    ADC_CR2 |= ADC_CR2_ADON;
}

static uint16_t HAL_ADC_ReadRaw(void)
{
    static uint32_t tick = 0;
    float phase = (float)(tick % 200) / 200.0f * 6.2831853f;
    float signal = 0.5f + 0.45f * sinf(phase);
    tick++;
    if (signal < 0.0f) signal = 0.0f;
    if (signal > 1.0f) signal = 1.0f;
    return (uint16_t)(signal * ADC_FULL_SCALE);
}

static void HAL_SetRangeGain(PT_Range_t range)
{
    uint32_t odr = GPIOA_ODR;
    odr &= ~(0x3U << 4);
    odr |= ((uint32_t)range << 4);
    GPIOA_ODR = odr;
}

static void HAL_DelayMs(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 1000U; i++) {
        __asm__ volatile ("nop");
    }
}

/* ============================================================
 * PT 信号调理核心算法
 * ============================================================ */

static float PT_GetGainByRange(PT_Range_t range)
{
    switch (range) {
        case PT_RANGE_LOW:  return PT_GAIN_LOW;
        case PT_RANGE_MID:  return PT_GAIN_MID;
        case PT_RANGE_HIGH: return PT_GAIN_HIGH;
        default:            return PT_GAIN_LOW;
    }
}

static void PT_Init(PT_Context_t *ctx)
{
    if (ctx == NULL) return;

    ctx->range         = PT_RANGE_LOW;
    ctx->gain          = PT_GetGainByRange(PT_RANGE_LOW);
    ctx->adc_offset    = 0.5f;
    ctx->filtered_peak = 0.0f;
    ctx->rms_voltage   = 0.0f;
    ctx->sample_count  = 0;

    HAL_ADC_Init();
    HAL_SetRangeGain(ctx->range);
}

static void PT_AutoRange(PT_Context_t *ctx, float normalized_peak)
{
    PT_Range_t new_range = ctx->range;

    if (normalized_peak > RANGE_SWITCH_UP_TH) {
        if (ctx->range > PT_RANGE_LOW) {
            new_range = (PT_Range_t)(ctx->range - 1);
        }
    } else if (normalized_peak < RANGE_SWITCH_DOWN_TH) {
        if (ctx->range < PT_RANGE_HIGH) {
            new_range = (PT_Range_t)(ctx->range + 1);
        }
    }

    if (new_range != ctx->range) {
        ctx->range = new_range;
        ctx->gain  = PT_GetGainByRange(new_range);
        HAL_SetRangeGain(new_range);
        ctx->filtered_peak = normalized_peak;
    }
}

static float PT_ProcessSample(PT_Context_t *ctx)
{
    uint16_t raw = HAL_ADC_ReadRaw();
    float normalized = (float)raw / ADC_FULL_SCALE;

    float ac = normalized - ctx->adc_offset;
    float abs_ac = (ac >= 0.0f) ? ac : -ac;

    ctx->filtered_peak = IIR_ALPHA * abs_ac +
                         (1.0f - IIR_ALPHA) * ctx->filtered_peak;

    PT_AutoRange(ctx, ctx->filtered_peak);

    ctx->sample_count++;
    return ctx->filtered_peak;
}

static float PT_ComputeRms(PT_Context_t *ctx)
{
    float input_peak;
    float rms;

    if (ctx->gain <= 0.0f) {
        ctx->rms_voltage = 0.0f;
        return 0.0f;
    }

    input_peak = ctx->filtered_peak * ADC_VREF / ctx->gain;
    rms = input_peak / 1.41421356f;

    ctx->rms_voltage = rms;
    return rms;
}

static float PT_OversampleAverage(PT_Context_t *ctx)
{
    float sum = 0.0f;
    uint32_t i;

    for (i = 0; i < OVERSAMPLE_COUNT; i++) {
        sum += PT_ProcessSample(ctx);
        HAL_DelayMs(1);
    }

    return sum / (float)OVERSAMPLE_COUNT;
}

/* ============================================================
 * 主函数：测试打印
 * ============================================================ */

int main(void)
{
    PT_Context_t pt_ctx;
    uint32_t loop;

    printf("===== PT Signal Conditioning (Range Adaptation) =====\n");
    printf("PT Secondary Rated: %.1f Vrms\n", PT_SECONDARY_RATED_VRMS);
    printf("ADC Vref: %.2f V, Full Scale: %.0f\n", ADC_VREF, ADC_FULL_SCALE);
    printf("Gain Low/Mid/High: %.1f / %.1f / %.1f\n",
           PT_GAIN_LOW, PT_GAIN_MID, PT_GAIN_HIGH);
    printf("----------------------------------------------------\n");

    PT_Init(&pt_ctx);

    for (loop = 0; loop < 10; loop++) {
        float avg_peak = PT_OversampleAverage(&pt_ctx);
        float rms = PT_ComputeRms(&pt_ctx);

        printf("[Loop %2lu] Range=%d Gain=%.1f Peak=%.4f RMS=%.4f V\n",
               (unsigned long)loop,
               (int)pt_ctx.range,
               pt_ctx.gain,
               avg_peak,
               rms);

        HAL_DelayMs(50);
    }

    printf("----------------------------------------------------\n");
    printf("Final: Range=%d, Gain=%.1f, RMS=%.4f V, Samples=%lu\n",
           (int)pt_ctx.range,
           pt_ctx.gain,
           pt_ctx.rms_voltage,
           (unsigned long)pt_ctx.sample_count);

    return 0;
}
