#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 模拟寄存器与硬件抽象层 ==================== */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t g_adc_dr = 0;
static volatile uint32_t g_adc_cr = 0;
static volatile uint32_t g_adc_sr = 0;
static volatile uint32_t g_dac_dhr12r1 = 0;
static volatile uint32_t g_dac_cr = 0;
static volatile uint32_t g_gpio_odr = 0;

#define MOCK_ADC_DR         (g_adc_dr)
#define MOCK_ADC_CR         (g_adc_cr)
#define MOCK_ADC_SR         (g_adc_sr)
#define MOCK_DAC_DHR12R1    (g_dac_dhr12r1)
#define MOCK_DAC_CR         (g_dac_cr)
#define MOCK_GPIO_ODR       (g_gpio_odr)

/* 模拟 ADC 启动转换 */
static void mock_adc_start(void)
{
    MOCK_ADC_CR |= (1U << 0);   /* ADON = 1 */
    MOCK_ADC_CR |= (1U << 2);   /* 启动规则转换 */
}

/* 模拟 ADC 读取转换结果 */
static uint16_t mock_adc_read(void)
{
    MOCK_ADC_SR |= (1U << 1);   /* EOC = 1 */
    return (uint16_t)(MOCK_ADC_DR & 0x0FFFU);
}

/* 模拟 DAC 输出 */
static void mock_dac_output(uint16_t value)
{
    MOCK_DAC_DHR12R1 = value & 0x0FFFU;
}

/* ==================== 霍尔电压传感器校准参数 ==================== */
#define ADC_RESOLUTION      4096.0f     /* 12 位 ADC */
#define ADC_VREF            3.3f        /* 参考电压 3.3V */
#define SENSOR_SENSITIVITY  0.025f      /* 霍尔传感器灵敏度 25mV/A */
#define SENSOR_OFFSET       1.65f       /* 零电流时输出电压 1.65V */
#define CAL_POINTS          7           /* 校准点数量 */

/* 校准点结构体：原始 ADC 值 -> 实际电压值 */
typedef struct {
    float adc_voltage;      /* 传感器原始输出电压 (V) */
    float actual_voltage;   /* 实际被测电压 (V) */
} CalPoint_t;

/* 校准表：通过实验测量得到的非线性校准数据 */
static const CalPoint_t g_cal_table[CAL_POINTS] = {
    {0.00f,   0.00f},
    {0.50f,   0.48f},
    {1.00f,   0.97f},
    {1.65f,   1.65f},
    {2.00f,   2.02f},
    {2.50f,   2.55f},
    {3.00f,   3.08f}
};

/* ==================== 非线性补偿算法 ==================== */

/**
 * @brief 线性插值校准
 * @param raw_voltage 传感器原始输出电压 (V)
 * @return 校准后的实际电压 (V)
 */
static float calibrate_linear_interp(float raw_voltage)
{
    int i;
    float ratio;

    /* 边界处理 */
    if (raw_voltage <= g_cal_table[0].adc_voltage) {
        return g_cal_table[0].actual_voltage;
    }
    if (raw_voltage >= g_cal_table[CAL_POINTS - 1].adc_voltage) {
        return g_cal_table[CAL_POINTS - 1].actual_voltage;
    }

    /* 查找所在区间并线性插值 */
    for (i = 0; i < CAL_POINTS - 1; i++) {
        if (raw_voltage >= g_cal_table[i].adc_voltage &&
            raw_voltage <= g_cal_table[i + 1].adc_voltage) {
            float denom = g_cal_table[i + 1].adc_voltage - g_cal_table[i].adc_voltage;
            if (denom == 0.0f) {
                return g_cal_table[i].actual_voltage;
            }
            ratio = (raw_voltage - g_cal_table[i].adc_voltage) / denom;
            return g_cal_table[i].actual_voltage +
                   ratio * (g_cal_table[i + 1].actual_voltage -
                            g_cal_table[i].actual_voltage);
        }
    }

    return raw_voltage; /* 理论上不会执行到这里 */
}

/**
 * @brief 多项式拟合校准（二次多项式）
 * @param raw_voltage 传感器原始输出电压 (V)
 * @return 校准后的实际电压 (V)
 */
static float calibrate_poly2(float raw_voltage)
{
    /* 二次多项式系数：V_actual = a2*V_raw^2 + a1*V_raw + a0 */
    const float a2 = 0.0125f;
    const float a1 = 0.9850f;
    const float a0 = 0.0020f;

    return a2 * raw_voltage * raw_voltage + a1 * raw_voltage + a0;
}

/**
 * @brief 分段线性 + 多项式混合校准
 * @param raw_voltage 传感器原始输出电压 (V)
 * @return 校准后的实际电压 (V)
 */
static float calibrate_hybrid(float raw_voltage)
{
    /* 在中心区域使用多项式，边缘区域使用线性插值 */
    if (raw_voltage > 0.8f && raw_voltage < 2.5f) {
        return calibrate_poly2(raw_voltage);
    } else {
        return calibrate_linear_interp(raw_voltage);
    }
}

/* ==================== 传感器数据采集与处理 ==================== */

/**
 * @brief 读取霍尔传感器原始电压
 * @return 传感器输出电压 (V)
 */
static float read_sensor_voltage(void)
{
    uint16_t adc_raw;
    float voltage;

    mock_adc_start();
    adc_raw = mock_adc_read();
    voltage = ((float)adc_raw / ADC_RESOLUTION) * ADC_VREF;

    return voltage;
}

/**
 * @brief 计算被测电压（基于霍尔传感器原理）
 * @param sensor_voltage 传感器输出电压 (V)
 * @return 被测电压 (V)
 */
static float calculate_measured_voltage(float sensor_voltage)
{
    /* 霍尔电压传感器：V_out = V_offset + Sensitivity * V_measured */
    if (SENSOR_SENSITIVITY == 0.0f) {
        return 0.0f;
    }
    return (sensor_voltage - SENSOR_OFFSET) / SENSOR_SENSITIVITY;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    float raw_voltage;
    float calibrated_voltage;
    float measured_voltage;
    float linear_result;
    float poly_result;
    float hybrid_result;
    uint16_t dac_value;
    int i;

    /* 模拟一组 ADC 采样值进行测试 */
    uint16_t test_adc_values[] = {
        0, 512, 1024, 1365, 2048, 2560, 3072, 3584, 4095
    };
    int test_count = (int)(sizeof(test_adc_values) / sizeof(test_adc_values[0]));

    printf("========================================\n");
    printf("  霍尔电压传感器校准（非线性补偿）测试\n");
    printf("========================================\n\n");

    printf("%-10s %-12s %-12s %-12s %-12s %-12s\n",
           "ADC值", "原始电压(V)", "线性插值(V)", "多项式(V)", "混合校准(V)", "被测电压(V)");
    printf("--------------------------------------------------------------------------\n");

    for (i = 0; i < test_count; i++) {
        /* 将 ADC 值转换为电压 */
        raw_voltage = ((float)test_adc_values[i] / ADC_RESOLUTION) * ADC_VREF;

        /* 三种校准方法 */
        linear_result = calibrate_linear_interp(raw_voltage);
        poly_result = calibrate_poly2(raw_voltage);
        hybrid_result = calibrate_hybrid(raw_voltage);

        /* 使用混合校准结果计算被测电压 */
        calibrated_voltage = hybrid_result;
        measured_voltage = calculate_measured_voltage(calibrated_voltage);

        printf("%-10u %-12.4f %-12.4f %-12.4f %-12.4f %-12.4f\n",
               (unsigned int)test_adc_values[i], raw_voltage, linear_result,
               poly_result, hybrid_result, measured_voltage);
    }

    printf("\n");

    /* 模拟实际采集流程 */
    printf("--- 模拟实际采集流程 ---\n");
    for (i = 0; i < 5; i++) {
        int idx = i * 2;
        if (idx >= test_count) {
            idx = test_count - 1;
        }
        /* 模拟 ADC 数据寄存器写入 */
        MOCK_ADC_DR = (uint32_t)(test_adc_values[idx] & 0x0FFFU);

        raw_voltage = read_sensor_voltage();
        calibrated_voltage = calibrate_hybrid(raw_voltage);
        measured_voltage = calculate_measured_voltage(calibrated_voltage);

        /* 输出到 DAC（用于监控） */
        dac_value = (uint16_t)((calibrated_voltage / ADC_VREF) * ADC_RESOLUTION);
        if (dac_value > 4095) dac_value = 4095;
        mock_dac_output(dac_value);

        printf("采样 %d: ADC原始=%.4fV, 校准后=%.4fV, 被测电压=%.4fV, DAC输出=%u\n",
               i + 1, raw_voltage, calibrated_voltage, measured_voltage,
               (unsigned int)dac_value);
    }

    /* 状态指示 */
    MOCK_GPIO_ODR |= (1U << 5);  /* 点亮 LED 表示校准完成 */

    printf("\n校准完成，状态指示已置位。\n");

    return 0;
}
