#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <stdbool.h>

/* ================= Mock 硬件寄存器与宏定义 ================= */
static volatile uint32_t g_adc_dr = 0U;
static volatile uint32_t g_adc_sr = 0U;
static volatile uint32_t g_adc_cr = 0U;

#define CT_ADC_DR           (g_adc_dr)
#define CT_ADC_SR           (g_adc_sr)
#define CT_ADC_CR           (g_adc_cr)

#define CT_ADC_SR_EOC       (1U << 0)
#define CT_ADC_CR_ADEN      (1U << 0)
#define CT_ADC_CR_ADSTART   (1U << 1)

#define CT_ADC_VREF         3.3f
#define CT_ADC_RESOLUTION   4096.0f
#define CT_ADC_OFFSET       2048.0f

/* CT 信号调理参数 */
#define CT_SAMPLE_RATE_HZ   4000.0f
#define CT_NOMINAL_RMS      (5.0f * 0.7071f)
#define CT_SATURATION_THRESHOLD  0.85f
#define CT_SATURATION_COUNT_MAX  8U
#define CT_RECOVERY_COUNT_MAX    16U
#define CT_DI_DT_THRESHOLD       0.35f
#define CT_DC_OFFSET_ALPHA       0.001f
#define CT_FILTER_ALPHA          0.15f

/* ================= 数据结构定义 ================= */
typedef enum {
    CT_STATE_NORMAL = 0,
    CT_STATE_SATURATION,
    CT_STATE_RECOVERY
} CT_State_t;

typedef struct {
    float    sample_raw;
    float    sample_filtered;
    float    sample_prev;
    float    di_dt;
    float    dc_offset;
    float    amplitude_est;
    float    rms_est;
    uint32_t saturation_counter;
    uint32_t recovery_counter;
    CT_State_t state;
    bool     saturation_flag;
} CT_Handle_t;

/* ================= 函数声明 ================= */
static void     CT_Init(CT_Handle_t *hct);
static uint32_t CT_ReadADC(void);
static float    CT_ConvertToCurrent(uint32_t adc_val);
static void     CT_Update(CT_Handle_t *hct, float current_sample);
static bool     CT_DetectSaturation(CT_Handle_t *hct);

/* ================= 函数实现 ================= */

static void CT_Init(CT_Handle_t *hct)
{
    if (hct == NULL) return;

    hct->sample_raw         = 0.0f;
    hct->sample_filtered    = 0.0f;
    hct->sample_prev        = 0.0f;
    hct->di_dt              = 0.0f;
    hct->dc_offset          = 0.0f;
    hct->amplitude_est      = 0.0f;
    hct->rms_est            = 0.0f;
    hct->saturation_counter = 0U;
    hct->recovery_counter   = 0U;
    hct->state              = CT_STATE_NORMAL;
    hct->saturation_flag    = false;

    /* 初始化 Mock ADC 寄存器 */
    CT_ADC_CR = CT_ADC_CR_ADEN;
}

static uint32_t CT_ReadADC(void)
{
    /* Mock: 模拟 ADC 转换完成并返回数据 */
    CT_ADC_SR |= CT_ADC_SR_EOC;
    if (CT_ADC_SR & CT_ADC_SR_EOC) {
        CT_ADC_SR &= ~CT_ADC_SR_EOC;
        return CT_ADC_DR;
    }
    return 0U;
}

static float CT_ConvertToCurrent(uint32_t adc_val)
{
    float voltage = ((float)adc_val / CT_ADC_RESOLUTION) * CT_ADC_VREF;
    float current = (voltage - (CT_ADC_VREF * 0.5f)) * 10.0f;
    return current;
}

static bool CT_DetectSaturation(CT_Handle_t *hct)
{
    bool saturated = false;
    float abs_sample;
    float abs_di_dt;

    if (hct == NULL) return false;

    abs_sample = fabsf(hct->sample_filtered);
    abs_di_dt  = fabsf(hct->di_dt);

    /* 条件1: 瞬时幅值超过额定峰值的阈值 */
    if (abs_sample > (CT_NOMINAL_RMS * 1.414f * CT_SATURATION_THRESHOLD)) {
        saturated = true;
    }

    /* 条件2: 电流变化率异常增大 */
    if (abs_di_dt > CT_DI_DT_THRESHOLD) {
        saturated = true;
    }

    /* 条件3: 直流偏移量异常 */
    if (fabsf(hct->dc_offset) > (CT_NOMINAL_RMS * 0.5f)) {
        saturated = true;
    }

    return saturated;
}

static void CT_Update(CT_Handle_t *hct, float current_sample)
{
    if (hct == NULL) return;

    hct->sample_raw = current_sample;

    /* 一阶低通滤波 */
    hct->sample_filtered = hct->sample_filtered +
                           CT_FILTER_ALPHA * (current_sample - hct->sample_filtered);

    /* 计算电流变化率 di/dt */
    hct->di_dt = (hct->sample_filtered - hct->sample_prev) * CT_SAMPLE_RATE_HZ;
    hct->sample_prev = hct->sample_filtered;

    /* 直流偏移估计 */
    hct->dc_offset = hct->dc_offset +
                     CT_DC_OFFSET_ALPHA * (hct->sample_filtered - hct->dc_offset);

    /* 幅值估计（滑动峰值） */
    if (fabsf(hct->sample_filtered) > hct->amplitude_est) {
        hct->amplitude_est = fabsf(hct->sample_filtered);
    } else {
        hct->amplitude_est *= 0.999f;
    }

    /* RMS 估计 */
    hct->rms_est = hct->amplitude_est * 0.7071f;

    /* 状态机 */
    switch (hct->state) {
        case CT_STATE_NORMAL:
            if (CT_DetectSaturation(hct)) {
                hct->saturation_counter++;
                if (hct->saturation_counter >= CT_SATURATION_COUNT_MAX) {
                    hct->state = CT_STATE_SATURATION;
                    hct->saturation_flag = true;
                    hct->recovery_counter = 0U;
                }
            } else {
                if (hct->saturation_counter > 0U) {
                    hct->saturation_counter--;
                }
            }
            break;

        case CT_STATE_SATURATION:
            if (!CT_DetectSaturation(hct)) {
                hct->recovery_counter++;
                if (hct->recovery_counter >= CT_RECOVERY_COUNT_MAX) {
                    hct->state = CT_STATE_RECOVERY;
                    hct->saturation_flag = false;
                }
            } else {
                hct->recovery_counter = 0U;
            }
            break;

        case CT_STATE_RECOVERY:
            if (CT_DetectSaturation(hct)) {
                hct->state = CT_STATE_SATURATION;
                hct->saturation_flag = true;
                hct->recovery_counter = 0U;
            } else {
                hct->recovery_counter++;
                if (hct->recovery_counter >= (CT_RECOVERY_COUNT_MAX * 2U)) {
                    hct->state = CT_STATE_NORMAL;
                    hct->saturation_counter = 0U;
                    hct->recovery_counter = 0U;
                }
            }
            break;

        default:
            hct->state = CT_STATE_NORMAL;
            break;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    CT_Handle_t hct;
    uint32_t adc_val;
    float current;
    uint32_t i;

    printf("========================================\n");
    printf("  CT Signal Conditioning - Saturation Detection\n");
    printf("========================================\n\n");

    CT_Init(&hct);

    /* 模拟正常正弦波信号 */
    printf("[Phase 1] Normal sinusoidal signal:\n");
    for (i = 0U; i < 20U; i++) {
        float angle = (float)i * 0.314f;
        float sim_current = 5.0f * sinf(angle);

        adc_val = (uint32_t)((sim_current / 10.0f + 0.5f) * CT_ADC_RESOLUTION);
        if (adc_val > 4095U) adc_val = 4095U;
        CT_ADC_DR = adc_val;

        adc_val = CT_ReadADC();
        current = CT_ConvertToCurrent(adc_val);
        CT_Update(&hct, current);

        printf("  Sample[%2u]: ADC=%4u, I=%7.3f A, di/dt=%8.3f, State=%d, Sat=%d\n",
               i, adc_val, hct.sample_filtered, hct.di_dt,
               (int)hct.state, (int)hct.saturation_flag);
    }

    /* 模拟饱和信号（大电流 + 高 di/dt） */
    printf("\n[Phase 2] Saturation event (high current + high di/dt):\n");
    for (i = 0U; i < 30U; i++) {
        float sim_current;
        if (i < 10U) {
            sim_current = 5.0f + (float)i * 8.0f;
        } else if (i < 20U) {
            sim_current = 85.0f - (float)(i - 10U) * 8.0f;
        } else {
            sim_current = 5.0f * sinf((float)i * 0.314f);
        }

        adc_val = (uint32_t)((sim_current / 10.0f + 0.5f) * CT_ADC_RESOLUTION);
        if (adc_val > 4095U) adc_val = 4095U;
        CT_ADC_DR = adc_val;

        adc_val = CT_ReadADC();
        current = CT_ConvertToCurrent(adc_val);
        CT_Update(&hct, current);

        printf("  Sample[%2u]: ADC=%4u, I=%7.3f A, di/dt=%8.3f, State=%d, Sat=%d\n",
               i, adc_val, hct.sample_filtered, hct.di_dt,
               (int)hct.state, (int)hct.saturation_flag);
    }

    /* 模拟恢复过程 */
    printf("\n[Phase 3] Recovery:\n");
    for (i = 0U; i < 25U; i++) {
        float angle = (float)i * 0.314f;
        float sim_current = 5.0f * sinf(angle);

        adc_val = (uint32_t)((sim_current / 10.0f + 0.5f) * CT_ADC_RESOLUTION);
        if (adc_val > 4095U) adc_val = 4095U;
        CT_ADC_DR = adc_val;

        adc_val = CT_ReadADC();
        current = CT_ConvertToCurrent(adc_val);
        CT_Update(&hct, current);

        printf("  Sample[%2u]: ADC=%4u, I=%7.3f A, di/dt=%8.3f, State=%d, Sat=%d\n",
               i, adc_val, hct.sample_filtered, hct.di_dt,
               (int)hct.state, (int)hct.saturation_flag);
    }

    printf("\n========================================\n");
    printf("  Final State: %d\n", (int)hct.state);
    printf("  Saturation Flag: %d\n", (int)hct.saturation_flag);
    printf("  RMS Estimate: %.3f A\n", hct.rms_est);
    printf("  DC Offset: %.3f A\n", hct.dc_offset);
    printf("========================================\n");

    return 0;
}
