/* ==================== 量程档位定义 ==================== */
typedef enum {
    PT_RANGE_10V = 0,
    PT_RANGE_100V,
    PT_RANGE_300V,
    PT_RANGE_1000V,
    PT_RANGE_MAX
} PT_Range_t;

/* 各档位对应的硬件增益系数（模拟前端分压/放大比） */
static const float PT_RangeGain[PT_RANGE_MAX] = {
    100.0f,   /* 10V 档 */
    10.0f,    /* 100V 档 */
    3.333f,   /* 300V 档 */
    1.0f      /* 1000V 档 */
};

#define PT_ADC_VREF           3.3f
#define PT_ADC_FULL_SCALE     4095.0f

/* ==================== 全局状态 ==================== */
static PT_Range_t g_currentRange = PT_RANGE_1000V;
static float      g_lastVoltage  = 0.0f;
static uint16_t   g_mockAdcCode  = 0;

/* ==================== 硬件抽象层（纯软件模拟） ==================== */
static void PT_Hardware_Init(void)
{
    g_currentRange = PT_RANGE_1000V;
    g_lastVoltage  = 0.0f;
    g_mockAdcCode  = 0;
}

static uint16_t PT_ADC_ReadRaw(void)
{
    return g_mockAdcCode;
}

static void PT_SetRange(PT_Range_t range)
{
    if (range >= PT_RANGE_MAX) {
        return;
    }
    g_currentRange = range;
}

/* ==================== 信号调理核心算法 ==================== */
static float PT_ConvertToVoltage(uint16_t rawCode)
{
    float adcVoltage;
    float primaryVoltage;

    adcVoltage = ((float)rawCode / PT_ADC_FULL_SCALE) * PT_ADC_VREF;
    primaryVoltage = adcVoltage * PT_RangeGain[g_currentRange];

    return primaryVoltage;
}

static PT_Range_t PT_AutoRangeSelect(float measuredVoltage)
{
    PT_Range_t bestRange = g_currentRange;
    float bestScore = -1.0f;
    int r;

    for (r = 0; r < (int)PT_RANGE_MAX; r++) {
        float fullScaleVoltage = PT_ADC_VREF * PT_RangeGain[r];
        float ratio;
        float score;

        if (fullScaleVoltage <= 0.0f) {
            continue;
        }

        ratio = measuredVoltage / fullScaleVoltage;

        if (ratio < 0.2f || ratio > 0.9f) {
            continue;
        }

        score = 1.0f - fabsf(ratio - 0.5f) * 2.0f;
        if (score > bestScore) {
            bestScore = score;
            bestRange = (PT_Range_t)r;
        }
    }

    if (bestScore < 0.0f) {
        for (r = 0; r < (int)PT_RANGE_MAX; r++) {
            float fullScaleVoltage = PT_ADC_VREF * PT_RangeGain[r];
            if (fullScaleVoltage <= 0.0f) {
                continue;
            }
            if (measuredVoltage <= fullScaleVoltage * 0.95f) {
                bestRange = (PT_Range_t)r;
                break;
            }
        }
    }

    return bestRange;
}

static float PT_MeasureWithAutoRange(void)
{
    uint16_t rawCode;
    float voltage;
    PT_Range_t newRange;

    rawCode = PT_ADC_ReadRaw();
    voltage = PT_ConvertToVoltage(rawCode);

    newRange = PT_AutoRangeSelect(voltage);

    if (newRange != g_currentRange) {
        PT_SetRange(newRange);
        rawCode = PT_ADC_ReadRaw();
        voltage = PT_ConvertToVoltage(rawCode);
    }

    g_lastVoltage = voltage;
    return voltage;
}

/* ==================== 测试辅助函数 ==================== */
static const char *PT_RangeName(PT_Range_t range)
{
    switch (range) {
        case PT_RANGE_10V:   return "10V";
        case PT_RANGE_100V:  return "100V";
        case PT_RANGE_300V:  return "300V";
        case PT_RANGE_1000V: return "1000V";
        default:             return "UNKNOWN";
    }
}

static void PT_PrintStatus(void)
{
    printf("  [状态] 当前档位: %-6s | 上次电压: %.3f V\n",
           PT_RangeName(g_currentRange), g_lastVoltage);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    uint16_t testCodes[] = { 100, 500, 1000, 2000, 3000, 4000 };
    int i;
    int n;

    printf("========================================\n");
    printf("  电压互感器(PT)信号调理 - 量程适配测试\n");
    printf("========================================\n\n");

    PT_Hardware_Init();
    printf("硬件初始化完成，默认档位: %s\n\n", PT_RangeName(g_currentRange));

    n = (int)(sizeof(testCodes) / sizeof(testCodes[0]));

    for (i = 0; i < n; i++) {
        uint16_t code = testCodes[i];
        float voltage;
        PT_Range_t suggested;

        g_mockAdcCode = code;

        printf("--- 测试 %d: ADC 原始码值 = %u ---\n", i + 1, (unsigned)code);

        voltage = PT_ConvertToVoltage(code);
        printf("  直接转换电压: %.3f V (档位: %s)\n",
               voltage, PT_RangeName(g_currentRange));

        suggested = PT_AutoRangeSelect(voltage);
        printf("  建议档位: %s\n", PT_RangeName(suggested));

        voltage = PT_MeasureWithAutoRange();
        printf("  自动量程测量结果: %.3f V\n", voltage);
        PT_PrintStatus();
        printf("\n");
    }

    printf("--- 边界测试: ADC 码值 = 0 ---\n");
    g_mockAdcCode = 0;
    PT_SetRange(PT_RANGE_1000V);
    printf("  电压: %.3f V\n", PT_ConvertToVoltage(0));
