#include <stdio.h>
#include <math.h>
#include <stdbool.h>

/* ============================================================
 * 电流互感器（CT）信号调理 —— 饱和检测算法
 * 纯软件仿真骨架，可在标准 GCC 下编译运行
 * ============================================================ */

/* ---------- 模拟寄存器与硬件抽象层（mock） ---------- */
#define ADC_BASE_ADDR       0x40012000U
#define ADC_DR              (*(volatile unsigned int *)(ADC_BASE_ADDR + 0x40U))
#define ADC_SR              (*(volatile unsigned int *)(ADC_BASE_ADDR + 0x00U))
#define ADC_CR2             (*(volatile unsigned int *)(ADC_BASE_ADDR + 0x08U))

#define ADC_SR_EOC          (1U << 1)
#define ADC_CR2_ADON        (1U << 0)
#define ADC_CR2_SWSTART     (1U << 30)

/* ---------- 系统参数 ---------- */
#define ADC_FULL_SCALE      4095.0f     /* 12 位 ADC 满量程 */
#define ADC_VREF            3.3f        /* 参考电压 V */
#define CT_RATIO            1000.0f     /* 电流互感器变比 1000:1 */
#define BURDEN_RES          100.0f      /* 二次侧负载电阻 Ω */
#define SAMPLE_RATE_HZ      4000.0f     /* 采样率 4 kHz */
#define NOMINAL_FREQ_HZ     50.0f       /* 工频 50 Hz */
#define SAT_THRESHOLD_RATIO 0.85f       /* 饱和阈值：幅值达到满量程 85% */
#define SAT_HOLD_SAMPLES    20U         /* 饱和标志保持的采样点数 */

/* ---------- 饱和检测状态机 ---------- */
typedef enum {
    CT_STATE_NORMAL = 0,
    CT_STATE_SATURATED,
    CT_STATE_RECOVERING
} ct_state_t;

typedef struct {
    /* 配置 */
    float   adc_full_scale;
    float   adc_vref;
    float   ct_ratio;
    float   burden_res;
    float   sample_rate;
    float   nominal_freq;
    float   sat_threshold_ratio;
    unsigned int sat_hold_samples;

    /* 运行时状态 */
    ct_state_t   state;
    float        peak_abs;          /* 当前窗口内绝对值峰值 */
    float        rms_accum;         /* 平方累加 */
    unsigned int rms_count;
    float        rms_value;         /* 计算出的 RMS */
    unsigned int sat_counter;       /* 饱和保持计数器 */
    unsigned int sample_index;
    float        last_primary_current;
    bool         saturation_flag;
} ct_ctx_t;

/* ---------- 初始化 ---------- */
static void ct_init(ct_ctx_t *ctx)
{
    ctx->adc_full_scale      = ADC_FULL_SCALE;
    ctx->adc_vref            = ADC_VREF;
    ctx->ct_ratio            = CT_RATIO;
    ctx->burden_res          = BURDEN_RES;
    ctx->sample_rate         = SAMPLE_RATE_HZ;
    ctx->nominal_freq        = NOMINAL_FREQ_HZ;
    ctx->sat_threshold_ratio = SAT_THRESHOLD_RATIO;
    ctx->sat_hold_samples    = SAT_HOLD_SAMPLES;

    ctx->state               = CT_STATE_NORMAL;
    ctx->peak_abs            = 0.0f;
    ctx->rms_accum           = 0.0f;
    ctx->rms_count           = 0U;
    ctx->rms_value           = 0.0f;
    ctx->sat_counter         = 0U;
    ctx->sample_index        = 0U;
    ctx->last_primary_current = 0.0f;
    ctx->saturation_flag     = false;
}

/* ---------- ADC 原始值 → 二次侧电压 ---------- */
static float ct_adc_to_secondary_voltage(const ct_ctx_t *ctx, unsigned int adc_raw)
{
    return ((float)adc_raw / ctx->adc_full_scale) * ctx->adc_vref;
}

/* ---------- 二次侧电压 → 一次侧电流（安培） ---------- */
static float ct_secondary_voltage_to_primary_current(const ct_ctx_t *ctx, float v_sec)
{
    /* I_sec = V_sec / R_burden ; I_pri = I_sec * CT_ratio */
    float i_sec = v_sec / ctx->burden_res;
    return i_sec * ctx->ct_ratio;
}

/* ---------- 饱和检测核心 ---------- */
static void ct_process_sample(ct_ctx_t *ctx, unsigned int adc_raw)
{
    float v_sec;
    float i_pri;
    float abs_i;
    float threshold;
    float rms_window_samples;

    /* 1. 信号调理：ADC → 电压 → 一次电流 */
    v_sec = ct_adc_to_secondary_voltage(ctx, adc_raw);
    i_pri = ct_secondary_voltage_to_primary_current(ctx, v_sec);
    ctx->last_primary_current = i_pri;

    /* 2. 绝对值峰值跟踪 */
    abs_i = fabsf(i_pri);
    if (abs_i > ctx->peak_abs) {
        ctx->peak_abs = abs_i;
    }

    /* 3. RMS 累加（一个工频周期窗口） */
    rms_window_samples = ctx->sample_rate / ctx->nominal_freq;
    ctx->rms_accum += i_pri * i_pri;
    ctx->rms_count++;
    if ((float)ctx->rms_count >= rms_window_samples) {
        ctx->rms_value = sqrtf(ctx->rms_accum / (float)ctx->rms_count);
        ctx->rms_accum = 0.0f;
        ctx->rms_count = 0U;
    }

    /* 4. 饱和判定：峰值超过满量程对应电流的阈值比例 */
    threshold = (ctx->adc_vref / ctx->burden_res) * ctx->ct_ratio
                * ctx->sat_threshold_ratio;

    if (ctx->peak_abs >= threshold) {
        ctx->state = CT_STATE_SATURATED;
        ctx->sat_counter = ctx->sat_hold_samples;
        ctx->saturation_flag = true;
    } else {
        if (ctx->sat_counter > 0U) {
            ctx->sat_counter--;
            ctx->state = CT_STATE_RECOVERING;
            ctx->saturation_flag = true;
        } else {
            ctx->state = CT_STATE_NORMAL;
            ctx->saturation_flag = false;
            /* 峰值缓慢衰减，避免长期保持 */
            ctx->peak_abs *= 0.95f;
        }
    }

    ctx->sample_index++;
}

/* ---------- 状态字符串 ---------- */
static const char *ct_state_str(ct_state_t s)
{
    switch (s) {
        case CT_STATE_NORMAL:     return "NORMAL";
        case CT_STATE_SATURATED:  return "SATURATED";
        case CT_STATE_RECOVERING: return "RECOVERING";
        default:                  return "UNKNOWN";
    }
}

/* ---------- 模拟 ADC 读取（mock） ---------- */
static unsigned int mock_adc_read(unsigned int index)
{
    /* 生成一个含饱和段的合成波形：
     * 前 40 个点正常正弦，中间 20 个点饱和削顶，后面恢复 */
    float t = (float)index / SAMPLE_RATE_HZ;
    float amp = 1.0f;
    float val;

    if (index >= 40U && index < 60U) {
        amp = 1.6f;   /* 饱和段：幅值增大，ADC 削顶 */
    }

    val = amp * sinf(2.0f * 3.14159265f * NOMINAL_FREQ_HZ * t);
    /* 映射到 0 ~ ADC_FULL_SCALE 的中间偏置 */
    float adc_f = (val * 0.5f + 0.5f) * ADC_FULL_SCALE;
    if (adc_f < 0.0f) adc_f = 0.0f;
    if (adc_f > ADC_FULL_SCALE) adc_f = ADC_FULL_SCALE;
    return (unsigned int)(adc_f + 0.5f);
}

/* ---------- main ---------- */
int main(void)
{
    ct_ctx_t ctx;
    unsigned int i;
    unsigned int total_samples = 100U;

    printf("========================================\n");
    printf(" CT Signal Conditioning - Saturation Detector\n");
    printf("========================================\n");
    printf(" ADC Full Scale : %.0f\n", ADC_FULL_SCALE);
    printf(" VREF           : %.2f V\n", ADC_VREF);
    printf(" CT Ratio       : %.0f:1\n", CT_RATIO);
    printf(" Burden Res     : %.1f ohm\n", BURDEN_RES);
    printf(" Sample Rate    : %.0f Hz\n", SAMPLE_RATE_HZ);
    printf(" Nominal Freq   : %.0f Hz\n", NOMINAL_FREQ_HZ);
    printf(" Sat Threshold  : %.0f%%\n", SAT_THRESHOLD_RATIO * 100.0f);
    printf("----------------------------------------\n");
    printf(" idx |  ADC  |  I_pri(A) |  RMS(A)  |  State\n");
    printf("----------------------------------------\n");

    ct_init(&ctx);

    for (i = 0U; i < total_samples; i++) {
        unsigned int raw = mock_adc_read(i);
        ct_process_sample(&ctx, raw);

        if ((i % 5U) == 0U || ctx.saturation_flag) {
            printf(" %3u | %5u | %9.2f | %8.2f | %s\n",
                   i,
                   raw,
                   ctx.last_primary_current,
                   ctx.rms_value,
                   ct_state_str(ctx.state));
        }
    }

    printf("----------------------------------------\n");
    printf(" Final State    : %s\n", ct_state_str(ctx.state));
    printf(" Saturation Flag: %s\n", ctx.saturation_flag ? "TRUE" : "FALSE");
    printf(" Peak Abs I_pri : %.2f A\n", ctx.peak_abs);
    printf(" Final RMS      : %.2f A\n", ctx.rms_value);
    printf("========================================\n");

    return 0;
}
