#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器定义 ================= */
static volatile uint32_t g_pwm_cr1  = 0U;
static volatile uint32_t g_pwm_cr2  = 0U;
static volatile uint32_t g_pwm_arr  = 0U;
static volatile uint32_t g_pwm_ccr1 = 0U;
static volatile uint32_t g_pwm_ccr2 = 0U;
static volatile uint32_t g_pwm_bdtr = 0U;
static volatile uint32_t g_pwm_sr   = 0U;

#define PWM_CR1   (g_pwm_cr1)
#define PWM_CR2   (g_pwm_cr2)
#define PWM_ARR   (g_pwm_arr)
#define PWM_CCR1  (g_pwm_ccr1)
#define PWM_CCR2  (g_pwm_ccr2)
#define PWM_BDTR  (g_pwm_bdtr)
#define PWM_SR    (g_pwm_sr)

/* 位定义 */
#define PWM_CR1_CEN     (1U << 0)
#define PWM_CR1_ARPE    (1U << 7)
#define PWM_BDTR_MOE    (1U << 15)
#define PWM_BDTR_DTG_SHIFT 0U
#define PWM_BDTR_DTG_MASK  (0xFFU << PWM_BDTR_DTG_SHIFT)

/* 死区时间参数 */
#define DEAD_TIME_NS        500U
#define PWM_CLK_FREQ_HZ     72000000U
#define PWM_PERIOD_TICKS    1000U

/* 米勒平台相关参数 */
#define MILLER_PLATEAU_NS   200U
#define GATE_RESISTOR_OHM   10U
#define GATE_CAP_NF         10U

/* ================= 死区时间计算 ================= */
static uint8_t calc_dead_time_ticks(uint32_t dead_ns, uint32_t clk_hz)
{
    uint64_t ticks;
    uint8_t dtg;

    if (clk_hz == 0U) {
        return 0U;
    }

    ticks = ((uint64_t)dead_ns * (uint64_t)clk_hz) / 1000000000ULL;
    if (ticks > 255U) {
        ticks = 255U;
    }
    dtg = (uint8_t)ticks;
    return dtg;
}

/* ================= 米勒平台时间估算 ================= */
static uint32_t calc_miller_plateau_ns(uint32_t rg_ohm, uint32_t cg_nf)
{
    /* 简化模型: t = Rg * Cg * ln(10) 近似 */
    uint64_t t_ns;
    t_ns = (uint64_t)rg_ohm * (uint64_t)cg_nf * 2300ULL;
    return (uint32_t)t_ns;
}

/* ================= PWM 初始化 ================= */
static void pwm_init(uint32_t period_ticks, uint32_t duty1_ticks, uint32_t duty2_ticks)
{
    PWM_CR1 = 0U;
    PWM_CR2 = 0U;
    PWM_ARR = period_ticks;
    PWM_CCR1 = duty1_ticks;
    PWM_CCR2 = duty2_ticks;
    PWM_BDTR = 0U;
    PWM_SR = 0U;
}

/* ================= 配置死区时间 ================= */
static void pwm_set_dead_time(uint8_t dtg)
{
    uint32_t reg;
    reg = PWM_BDTR;
    reg &= ~PWM_BDTR_DTG_MASK;
    reg |= ((uint32_t)dtg << PWM_BDTR_DTG_SHIFT) & PWM_BDTR_DTG_MASK;
    PWM_BDTR = reg;
}

/* ================= 使能 PWM 输出 ================= */
static void pwm_enable(void)
{
    PWM_BDTR |= PWM_BDTR_MOE;
    PWM_CR1 |= PWM_CR1_CEN | PWM_CR1_ARPE;
}

/* ================= 关闭 PWM 输出 ================= */
static void pwm_disable(void)
{
    PWM_CR1 &= ~PWM_CR1_CEN;
    PWM_BDTR &= ~PWM_BDTR_MOE;
}

/* ================= 更新占空比 ================= */
static void pwm_set_duty(uint32_t duty1_ticks, uint32_t duty2_ticks)
{
    PWM_CCR1 = duty1_ticks;
    PWM_CCR2 = duty2_ticks;
}

/* ================= 读取当前死区配置 ================= */
static uint8_t pwm_get_dead_time(void)
{
    return (uint8_t)((PWM_BDTR & PWM_BDTR_DTG_MASK) >> PWM_BDTR_DTG_SHIFT);
}

/* ================= 主函数 ================= */
int main(void)
{
    uint8_t dtg;
    uint32_t miller_ns;
    uint32_t dead_ns;
    uint32_t i;

    printf("===== MOSFET Driver Control (Dead Time & Miller Plateau) =====\n");

    /* 计算死区时间 */
    dtg = calc_dead_time_ticks(DEAD_TIME_NS, PWM_CLK_FREQ_HZ);
    dead_ns = (uint32_t)(((uint64_t)dtg * 1000000000ULL) / (uint64_t)PWM_CLK_FREQ_HZ);
    printf("[DeadTime] Requested: %u ns, DTG ticks: %u, Actual: %u ns\n",
           (unsigned int)DEAD_TIME_NS, (unsigned int)dtg, (unsigned int)dead_ns);

    /* 计算米勒平台时间 */
    miller_ns = calc_miller_plateau_ns(GATE_RESISTOR_OHM, GATE_CAP_NF);
    printf("[Miller] Rg=%u ohm, Cg=%u nF, Plateau time approx: %u ns\n",
           (unsigned int)GATE_RESISTOR_OHM, (unsigned int)GATE_CAP_NF, (unsigned int)miller_ns);

    /* 初始化 PWM */
    pwm_init(PWM_PERIOD_TICKS, 300U, 300U);
    printf("[PWM] Init: ARR=%u, CCR1=%u, CCR2=%u\n",
           (unsigned int)PWM_ARR, (unsigned int)PWM_CCR1, (unsigned int)PWM_CCR2);

    /* 设置死区时间 */
    pwm_set_dead_time(dtg);
    printf("[PWM] Dead time register DTG = %u\n", (unsigned int)pwm_get_dead_time());

    /* 使能 PWM */
    pwm_enable();
    printf("[PWM] Enabled: CR1=0x%08X, BDTR=0x%08X\n",
           (unsigned int)PWM_CR1, (unsigned int)PWM_BDTR);

    /* 模拟占空比扫描 */
    printf("[PWM] Duty sweep:\n");
    for (i = 0U; i <= 5U; i++) {
        uint32_t d = 100U + i * 100U;
        pwm_set_duty(d, PWM_PERIOD_TICKS - d);
        printf("  Step %u: CCR1=%u, CCR2=%u\n",
               (unsigned int)i, (unsigned int)PWM_CCR1, (unsigned int)PWM_CCR2);
    }

    /* 检查米勒平台是否在死区时间内 */
    if (miller_ns > dead_ns) {
        printf("[WARN] Miller plateau (%u ns) > dead time (%u ns), "
               "shoot-through risk!\n",
               (unsigned int)miller_ns, (unsigned int)dead_ns);
    } else {
        printf("[OK] Miller plateau (%u ns) <= dead time (%u ns)\n",
               (unsigned int)miller_ns, (unsigned int)dead_ns);
    }

    /* 关闭 PWM */
    pwm_disable();
    printf("[PWM] Disabled: CR1=0x%08X, BDTR=0x%08X\n",
           (unsigned int)PWM_CR1, (unsigned int)PWM_BDTR);

    printf("===== Done =====\n");
    return 0;
}
