#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t mock_gpioa_odr = 0;
static volatile uint16_t mock_adc_dr = 0;
static volatile uint32_t mock_tim2_cnt = 0;

#define GPIOA_ODR       (mock_gpioa_odr)
#define ADC1_DR         (mock_adc_dr)
#define TIM2_CNT        (mock_tim2_cnt)

/* 引脚定义 */
#define MAIN_CONTACTOR_PIN   (1U << 0)   /* PA0: 主接触器 */
#define PRE_CHARGE_PIN       (1U << 1)   /* PA1: 预充电接触器 */

/* 预充电参数 */
#define PRE_CHARGE_TIME_MS   500U        /* 预充电持续时间 500ms */
#define VOLTAGE_THRESHOLD    400U        /* 母线电压阈值 (ADC 值) */
#define ADC_MAX_VALUE        4095U       /* 12 位 ADC 满量程 */

/* 状态机枚举 */
typedef enum {
    STATE_IDLE = 0,
    STATE_PRECHARGE,
    STATE_MAIN_ON,
    STATE_FAULT
} ContactorState_t;

/* 控制上下文结构体 */
typedef struct {
    ContactorState_t state;
    uint32_t precharge_start_time;
    uint32_t precharge_elapsed;
    uint16_t bus_voltage;
    bool precharge_done;
    bool main_done;
} ContactorCtrl_t;

/* ================= 模拟硬件操作函数 ================= */
static void GPIO_SetPin(uint32_t pin)
{
    GPIOA_ODR |= pin;
}

static void GPIO_ResetPin(uint32_t pin)
{
    GPIOA_ODR &= ~pin;
}

static uint16_t ADC_ReadBusVoltage(void)
{
    /* 模拟母线电压逐渐上升 */
    static uint16_t mock_voltage = 0;
    if (mock_voltage < ADC_MAX_VALUE) {
        mock_voltage += 200;
        if (mock_voltage > ADC_MAX_VALUE) {
            mock_voltage = ADC_MAX_VALUE;
        }
    }
    return mock_voltage;
}

static uint32_t GetTickMs(void)
{
    /* 模拟系统滴答，每次调用递增 50ms */
    static uint32_t tick = 0;
    tick += 50;
    return tick;
}

/* ================= 接触器控制核心逻辑 ================= */
static void Contactor_Init(ContactorCtrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }

    ctrl->state = STATE_IDLE;
    ctrl->precharge_start_time = 0;
    ctrl->precharge_elapsed = 0;
    ctrl->bus_voltage = 0;
    ctrl->precharge_done = false;
    ctrl->main_done = false;

    /* 初始状态：断开所有接触器 */
    GPIO_ResetPin(MAIN_CONTACTOR_PIN);
    GPIO_ResetPin(PRE_CHARGE_PIN);
}

static void Contactor_StartPrecharge(ContactorCtrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }

    if (ctrl->state == STATE_IDLE) {
        ctrl->state = STATE_PRECHARGE;
        ctrl->precharge_start_time = GetTickMs();
        ctrl->precharge_done = false;
        ctrl->main_done = false;

        /* 闭合预充电接触器，主接触器保持断开 */
        GPIO_ResetPin(MAIN_CONTACTOR_PIN);
        GPIO_SetPin(PRE_CHARGE_PIN);

        printf("[PRECHARGE] 预充电接触器闭合，开始预充电...\n");
    }
}

static void Contactor_Update(ContactorCtrl_t *ctrl)
{
    uint32_t now;

    if (ctrl == NULL) {
        return;
    }

    now = GetTickMs();

    switch (ctrl->state) {
    case STATE_IDLE:
        /* 空闲状态，等待启动命令 */
        break;

    case STATE_PRECHARGE:
        /* 读取母线电压 */
        ctrl->bus_voltage = ADC_ReadBusVoltage();
        ctrl->precharge_elapsed = now - ctrl->precharge_start_time;

        printf("[PRECHARGE] 已充电 %u ms, 母线电压 ADC = %u\n",
               ctrl->precharge_elapsed, ctrl->bus_voltage);

        /* 判断预充电是否完成：时间到 或 电压达到阈值 */
        if (ctrl->precharge_elapsed >= PRE_CHARGE_TIME_MS ||
            ctrl->bus_voltage >= VOLTAGE_THRESHOLD) {

            ctrl->precharge_done = true;
            ctrl->state = STATE_MAIN_ON;

            /* 闭合主接触器，断开预充电接触器 */
            GPIO_SetPin(MAIN_CONTACTOR_PIN);
            GPIO_ResetPin(PRE_CHARGE_PIN);

            printf("[MAIN] 预充电完成，主接触器闭合，预充电接触器断开\n");
        }
        break;

    case STATE_MAIN_ON:
        /* 主接触器已闭合，正常运行 */
        ctrl->main_done = true;
        ctrl->bus_voltage = ADC_ReadBusVoltage();
        printf("[MAIN] 主接触器运行中，母线电压 ADC = %u\n",
               ctrl->bus_voltage);
        break;

    case STATE_FAULT:
        /* 故障状态：断开所有接触器 */
        GPIO_ResetPin(MAIN_CONTACTOR_PIN);
        GPIO_ResetPin(PRE_CHARGE_PIN);
        printf("[FAULT] 故障状态，所有接触器断开\n");
        break;

    default:
        break;
    }
}

static void Contactor_Stop(ContactorCtrl_t *ctrl)
{
    if (ctrl == NULL) {
        return;
    }

    GPIO_ResetPin(MAIN_CONTACTOR_PIN);
    GPIO_ResetPin(PRE_CHARGE_PIN);
    ctrl->state = STATE_IDLE;
    ctrl->precharge_done = false;
    ctrl->main_done = false;
    printf("[STOP] 所有接触器断开，系统回到空闲状态\n");
}

/* ================= 主函数 ================= */
int main(void)
{
    ContactorCtrl_t ctrl;
    int i;

    printf("===== 接触器驱动控制（预充电，防冲击）测试 =====\n\n");

    /* 初始化 */
    Contactor_Init(&ctrl);
    printf("系统初始化完成，状态: IDLE\n\n");

    /* 启动预充电 */
    Contactor_StartPrecharge(&ctrl);
    printf("\n");

    /* 模拟控制循环，直到主接触器闭合 */
    for (i = 0; i < 20; i++) {
        Contactor_Update(&ctrl);

        if (ctrl.state == STATE_MAIN_ON) {
            printf("\n>>> 主接触器已成功闭合，预充电流程结束 <<<\n\n");
            break;
        }
    }

    /* 模拟运行一段时间 */
    printf("--- 主接触器运行阶段 ---\n");
    for (i = 0; i < 3; i++) {
        Contactor_Update(&ctrl);
    }

    /* 停止系统 */
    printf("\n");
    Contactor_Stop(&ctrl);

    printf("\n===== 测试结束 =====\n");
    return 0;
}
