#define PMIC_VOLT_MAX_MV        1500

/* 状态寄存器位定义 */
#define PMIC_STATUS_PGOOD       (1 << 0)
#define PMIC_STATUS_OCP         (1 << 1)
#define PMIC_STATUS_OTP         (1 << 2)

/* ================= PMIC 驱动结构体 ================= */
typedef struct {
    uint8_t  dev_addr;
    uint8_t  chip_id;
    uint8_t  ctrl_shadow;   /* CTRL 寄存器影子 */
    uint8_t  int_mask;
    uint8_t  initialized;
} pmic_dev_t;

/* ================= 电压转换辅助函数 ================= */
static int pmic_mv_to_code(uint16_t mv, uint8_t *code)
{
    if (mv < PMIC_VOLT_BASE_MV || mv > PMIC_VOLT_MAX_MV) {
        return -1;
    }
    if ((mv - PMIC_VOLT_BASE_MV) % PMIC_VOLT_STEP_MV != 0) {
        return -1;
    }
    *code = (uint8_t)((mv - PMIC_VOLT_BASE_MV) / PMIC_VOLT_STEP_MV);
    return 0;
}

static uint16_t pmic_code_to_mv(uint8_t code)
{
    return (uint16_t)(PMIC_VOLT_BASE_MV + code * PMIC_VOLT_STEP_MV);
}

/* ================= PMIC 驱动 API ================= */

/* 初始化 PMIC */
static int pmic_init(pmic_dev_t *dev, uint8_t dev_addr)
{
    uint8_t id = 0;
    int ret;

    if (dev == NULL) {
        return -1;
    }

    memset(dev, 0, sizeof(pmic_dev_t));
    dev->dev_addr = dev_addr;

    /* 读取 Chip ID */
    ret = mock_i2c_read_reg(dev->dev_addr, PMIC_REG_CHIP_ID, &id);
    if (ret != I2C_OK) {
        printf("[PMIC] Read Chip ID failed: %d\n", ret);
        return ret;
    }
    dev->chip_id = id;
    printf("[PMIC] Chip ID = 0x%02X\n", id);

    /* 关闭所有电源轨 */
    dev->ctrl_shadow = 0x00;
    ret = mock_i2c_write_reg(dev->dev_addr, PMIC_REG_CTRL, dev->ctrl_shadow);
    if (ret != I2C_OK) {
        printf("[PMIC] Disable all rails failed: %d\n", ret);
        return ret;
    }

    /* 屏蔽所有中断 */
    dev->int_mask = 0xFF;
    ret = mock_i2c_write_reg(dev->dev_addr, PMIC_REG_INT_MASK, dev->int_mask);
    if (ret != I2C_OK) {
        printf("[PMIC] Set INT mask failed: %d\n", ret);
        return ret;
    }

    dev->initialized = 1;
    printf("[PMIC] Init done.\n");
    return 0;
}

/* 设置指定电源轨电压 */
static int pmic_set_voltage(pmic_dev_t *dev, uint8_t reg, uint16_t mv)
{
    uint8_t code = 0;
    int ret;

    if (dev == NULL || !dev->initialized) {
        return -1;
    }
    if (pmic_mv_to_code(mv, &code) != 0) {
        printf("[PMIC] Voltage %u mV out of range\n", mv);
        return -1;
    }

    ret = mock_i2c_write_reg(dev->dev_addr, reg, code);
    if (ret != I2C_OK) {
        printf("[PMIC] Set voltage reg=0x%02X failed: %d\n", reg, ret);
        return ret;
    }
    printf("[PMIC] Set reg=0x%02X -> %u mV (code=0x%02X)\n", reg, mv, code);
    return 0;
}

/* 使能/禁用指定电源轨 */
static int pmic_enable_rail(pmic_dev_t *dev, uint8_t rail_bit, uint8_t enable)
{
    uint8_t new_ctrl;
    int ret;

    if (dev == NULL || !dev->initialized) {
        return -1;
    }

    if (enable) {
        new_ctrl = dev->ctrl_shadow | rail_bit;
    } else {
        new_ctrl = dev->ctrl_shadow & (uint8_t)(~rail_bit);
    }

    if (new_ctrl == dev->ctrl_shadow) {
        return 0; /* 无变化 */
    }

    ret = mock_i2c_write_reg(dev->dev_addr, PMIC_REG_CTRL, new_ctrl);
    if (ret != I2C_OK) {
        printf("[PMIC] CTRL write failed: %d\n", ret);
        return ret;
    }
    dev->ctrl_shadow = new_ctrl;
    printf("[PMIC] CTRL updated: 0x%02X\n", new_ctrl);
    return 0;
}

/* 读取状态寄存器 */
static int pmic_read_status(pmic_dev_t *dev, uint8_t *status)
{
    int ret;

    if (dev == NULL || !dev->initialized || status == NULL) {
        return -1;
    }

    ret = mock_i2c_read_reg(dev->dev_addr, PMIC_REG_STATUS, status);
    if (ret != I2C_OK) {
        printf("[PMIC] Read STATUS failed: %d\n", ret);
        return ret;
    }
    return 0;
}

/* 打印状态信息 */
static void pmic_dump_status(uint8_t status)
{
    printf("[PMIC] STATUS = 0x%02X : PGOOD=%d OCP=%d OTP=%d\n",
           status,
           (status & PMIC_STATUS_PGOOD) ? 1 : 0,
           (status & PMIC_STATUS_OCP)   ? 1 : 0,
           (status & PMIC_STATUS_OTP)   ? 1 : 0);
}

/* ================= 主函数 ================= */
int main(void)
{
    pmic_dev_t pmic;
    uint8_t status = 0;
    int ret;

    printf("===== PMIC I2C Driver Test =====\n");

    /* 1. 初始化 PMIC */
    ret = pmic_init(&pmic, PMIC_I2C_ADDR);
    if (ret != 0) {
        printf("PMIC init failed!\n");
        return -1;
    }

    /* 2. 配置各路电压 */
    pmic_set_voltage(&pmic, PMIC_REG_BUCK1_VOLT, 1200); /* 1.2V */
    pmic_set_voltage(&pmic, PMIC_REG_BUCK2_VOLT, 1000); /* 1.0V */
    pmic_set_voltage(&pmic, PMIC_REG_LDO1_VOLT,   900); /* 0.9V */
    pmic_set_voltage(&pmic, PMIC_REG_LDO2_VOLT,  1800); /* 1.8V */

    /* 3. 使能所有电源轨 */
    pmic_enable_rail(&pmic, PMIC_CTRL_EN_BUCK1, 1);
    pmic_enable_rail(&pmic, PMIC_CTRL_EN_BUCK2, 1);
    pmic_enable_rail(&pmic, PMIC_CTRL_EN_LDO1,  1);
    pmic_enable_rail(&pmic, PMIC_CTRL_EN_LDO2,  1);

    /* 4. 读取状态 */
    if (pmic_read_status(&pmic, &status) == 0) {
        pmic_dump_status(status);
    }

    /* 5. 关闭 LDO2 */
    pmic_enable_rail(&pmic, PMIC_CTRL_EN_LDO2, 0);

    /* 6. 再次读取状态 */
    if (pmic_read_status(&pmic, &status) == 0) {
        pmic_dump_status(status);
    }

    /* 7. 电压编码转换测试 */
    {
        uint8_t code = 0;
        uint16_t mv;
        if (pmic_mv_to_code(1350, &code) == 0) {
            mv = pmic_code_to_mv(code);
            printf("[PMIC] 1350 mV -> code=0x%02X -> %u mV\n", code, mv);
        }
    }

    printf("===== Test Done =====\n");
    return 0;
}
