} RTC_TypeDef;

/* 使用静态实例代替硬编码地址，避免访问非法内存 */
static RTC_TypeDef g_rtc_regs;
#define RTC                 (&g_rtc_regs)

/* RTC 控制位 */
#define RTC_CRH_SECIE       (1U << 0)
#define RTC_CRH_ALRIE       (1U << 1)
#define RTC_CRH_OWIE        (1U << 2)
#define RTC_CRL_SECF        (1U << 0)
#define RTC_CRL_ALRF        (1U << 1)
#define RTC_CRL_OWF         (1U << 2)
#define RTC_CRL_RSF         (1U << 3)
#define RTC_CRL_CNF         (1U << 4)
#define RTC_CRL_RTOFF       (1U << 5)

/* 备份寄存器 (BKP) Mock */
typedef struct {
    volatile uint32_t DR1;
    volatile uint32_t DR2;
    volatile uint32_t DR3;
    volatile uint32_t DR4;
    volatile uint32_t DR5;
    volatile uint32_t DR6;
    volatile uint32_t DR7;
    volatile uint32_t DR8;
    volatile uint32_t DR9;
    volatile uint32_t DR10;
} BKP_TypeDef;

static BKP_TypeDef g_bkp_regs;
#define BKP                 (&g_bkp_regs)

/* 电源控制 (PWR) Mock */
typedef struct {
    volatile uint32_t CR;
    volatile uint32_t CSR;
} PWR_TypeDef;

static PWR_TypeDef g_pwr_regs;
#define PWR                 (&g_pwr_regs)
#define PWR_CR_DBP          (1U << 8)
#define PWR_CSR_EWUP        (1U << 8)

/* RCC Mock */
typedef struct {
    volatile uint32_t CR;
    volatile uint32_t CFGR;
    volatile uint32_t CIR;
    volatile uint32_t APB1RSTR;
    volatile uint32_t APB1ENR;
    volatile uint32_t APB2ENR;
    volatile uint32_t BDCR;
} RCC_TypeDef;

static RCC_TypeDef g_rcc_regs;
#define RCC                 (&g_rcc_regs)
#define RCC_BDCR_LSEON      (1U << 0)
#define RCC_BDCR_LSERDY     (1U << 1)
#define RCC_BDCR_RTCSEL_LSE (1U << 8)
#define RCC_BDCR_RTCEN      (1U << 15)
#define RCC_APB1ENR_PWREN   (1U << 28)
#define RCC_APB1ENR_BKPEN   (1U << 27)

/* ==================== 时间结构体 ==================== */
typedef struct {
    uint8_t  hours;
    uint8_t  minutes;
    uint8_t  seconds;
    uint8_t  day;
    uint8_t  month;
    uint16_t year;
} RTC_Time_t;

/* ==================== 内部辅助函数 ==================== */
static uint32_t rtc_read_counter(void)
{
    uint32_t high1, low, high2;
    do {
        high1 = RTC->CNTH;
        low   = RTC->CNTL;
        high2 = RTC->CNTH;
    } while (high1 != high2);
    return (high1 << 16) | low;
}

static void rtc_write_counter(uint32_t value)
{
    RTC->CRL |= RTC_CRL_CNF;
    RTC->CNTH = (value >> 16) & 0xFFFF;
    RTC->CNTL = value & 0xFFFF;
    RTC->CRL &= ~RTC_CRL_CNF;
    RTC->CRL |= RTC_CRL_RTOFF;
}

static void rtc_wait_sync(void)
{
    RTC->CRL |= RTC_CRL_RSF;
}

static void rtc_wait_rtc_off(void)
{
    RTC->CRL |= RTC_CRL_RTOFF;
}

/* ==================== 时间转换 ==================== */
static uint32_t rtc_time_to_counter(const RTC_Time_t *t)
{
    struct tm tm_time;
    time_t epoch;

    memset(&tm_time, 0, sizeof(tm_time));
    tm_time.tm_year = (int)t->year - 1900;
    tm_time.tm_mon  = (int)t->month - 1;
    tm_time.tm_mday = (int)t->day;
    tm_time.tm_hour = (int)t->hours;
    tm_time.tm_min  = (int)t->minutes;
    tm_time.tm_sec  = (int)t->seconds;

    epoch = mktime(&tm_time);
    if (epoch < 0) {
        return 0;
    }
    return (uint32_t)epoch;
}

static void rtc_counter_to_time(uint32_t counter, RTC_Time_t *t)
{
    time_t epoch = (time_t)counter;
    struct tm *tm_time = gmtime(&epoch);

    if (tm_time == NULL) {
        memset(t, 0, sizeof(RTC_Time_t));
        return;
    }

    t->year    = (uint16_t)(tm_time->tm_year + 1900);
    t->month   = (uint8_t)(tm_time->tm_mon + 1);
    t->day     = (uint8_t)tm_time->tm_mday;
    t->hours   = (uint8_t)tm_time->tm_hour;
    t->minutes = (uint8_t)tm_time->tm_min;
    t->seconds = (uint8_t)tm_time->tm_sec;
}

/* ==================== RTC 初始化 ==================== */
static int rtc_init(void)
{
    RCC->APB1ENR |= RCC_APB1ENR_PWREN | RCC_APB1ENR_BKPEN;
    PWR->CR |= PWR_CR_DBP;

    RCC->BDCR |= RCC_BDCR_LSEON;
    {
        uint32_t timeout = 0xFFFFF;
        while (!(RCC->BDCR & RCC_BDCR_LSERDY) && timeout > 0) {
            timeout--;
        }
        if (timeout == 0) {
            printf("[RTC] LSE 启动超时\r\n");
            return -1;
        }
    }

    RCC->BDCR &= ~(3U << 8);
    RCC->BDCR |= RCC_BDCR_RTCSEL_LSE;
    RCC->BDCR |= RCC_BDCR_RTCEN;

    rtc_wait_sync();
    rtc_wait_rtc_off();

    RTC->CRL |= RTC_CRL_CNF;
    RTC->PRLH = 0x0000;
    RTC->PRLL = 0x7FFF;
    RTC->CRL &= ~RTC_CRL_CNF;

    rtc_wait_rtc_off();

    printf("[RTC] 初始化完成，时钟源 LSE，预分频 32767\r\n");
    return 0;
}

/* ==================== 时间同步 ==================== */
static void rtc_set_time(const RTC_Time_t *t)
{
    uint32_t counter = rtc_time_to_counter(t);

    rtc_wait_rtc_off();
    rtc_write_counter(counter);

    printf("[RTC] 时间已同步: %04u-%02u-%02u %02u:%02u:%02u (counter=%lu)\r\n",
           t->year, t->month, t->day,
           t->hours, t->minutes, t->seconds,
           (unsigned long)counter);
}

static void rtc_get_time(RTC_Time_t *t)
{
    uint32_t counter = rtc_read_counter();
    rtc_counter_to_time(counter, t);
}

/* ==================== 掉电走时检测 ==================== */
static int rtc_check_power_loss(void)
{
    if (BKP->DR1 != 0xA5A5) {
        printf("[RTC] 检测到掉电，RTC 时间可能丢失\r\n");
        BKP->DR1 = 0xA5A5;
        return 1;
    }
    printf("[RTC] 掉电走时正常，RTC 时间保持\r\n");
    return 0;
}

