#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

/* ================= Mock 寄存器与宏定义 ================= */
#define FLASH_BASE_ADDR         0x08000000U
#define FLASH_TOTAL_SIZE        (1024U * 1024U)   /* 1MB */
#define FLASH_BLOCK_SIZE        (64U * 1024U)     /* 64KB 块 */
#define FLASH_PAGE_SIZE         256U
#define FLASH_BLOCK_COUNT       (FLASH_TOTAL_SIZE / FLASH_BLOCK_SIZE)

/* 模拟 Flash 控制寄存器 - 使用静态变量而非固定地址，避免访问非法内存 */
typedef struct {
    volatile uint32_t CR;
    volatile uint32_t SR;
    volatile uint32_t AR;
    volatile uint32_t DR;
} FLASH_TypeDef;

static FLASH_TypeDef g_flash_regs;
#define FLASH                   (&g_flash_regs)

/* CR 位定义 */
#define FLASH_CR_PG             (1U << 0)
#define FLASH_CR_PER            (1U << 1)
#define FLASH_CR_MER            (1U << 2)
#define FLASH_CR_STRT           (1U << 6)
#define FLASH_CR_LOCK           (1U << 7)

/* SR 位定义 */
#define FLASH_SR_BSY            (1U << 0)
#define FLASH_SR_PGERR          (1U << 2)
#define FLASH_SR_WRPRTERR       (1U << 4)
#define FLASH_SR_EOP            (1U << 5)

/* 模拟 Flash 存储空间 */
static uint8_t g_flash_mem[FLASH_TOTAL_SIZE];

/* ================= 底层驱动接口 ================= */

static void flash_unlock(void)
{
    FLASH->CR &= ~FLASH_CR_LOCK;
}

static void flash_lock(void)
{
    FLASH->CR |= FLASH_CR_LOCK;
}

static int flash_wait_ready(uint32_t timeout)
{
    while ((FLASH->SR & FLASH_SR_BSY) && timeout--) {
        /* 等待 */
    }
    if (FLASH->SR & FLASH_SR_BSY) {
        return -1;
    }
    if (FLASH->SR & (FLASH_SR_PGERR | FLASH_SR_WRPRTERR)) {
        return -2;
    }
    return 0;
}

static int flash_erase_block(uint32_t block_index)
{
    uint32_t addr;

    if (block_index >= FLASH_BLOCK_COUNT) {
        return -1;
    }

    addr = FLASH_BASE_ADDR + block_index * FLASH_BLOCK_SIZE;

    flash_unlock();
    FLASH->CR |= FLASH_CR_MER;
    FLASH->AR = addr;
    FLASH->CR |= FLASH_CR_STRT;

    if (flash_wait_ready(1000000) != 0) {
        FLASH->CR &= ~FLASH_CR_MER;
        flash_lock();
        return -2;
    }

    FLASH->CR &= ~FLASH_CR_MER;
    FLASH->SR |= FLASH_SR_EOP;
    flash_lock();

    memset(&g_flash_mem[block_index * FLASH_BLOCK_SIZE], 0xFF, FLASH_BLOCK_SIZE);
    return 0;
}

static int flash_write(uint32_t addr, const uint8_t *data, uint32_t len)
{
    uint32_t offset;
    uint32_t i;

    if (addr < FLASH_BASE_ADDR || (addr + len) > (FLASH_BASE_ADDR + FLASH_TOTAL_SIZE)) {
        return -1;
    }

    offset = addr - FLASH_BASE_ADDR;

    flash_unlock();
    for (i = 0; i < len; i++) {
        FLASH->CR |= FLASH_CR_PG;
        FLASH->AR = addr + i;
        FLASH->DR = data[i];
        FLASH->CR |= FLASH_CR_STRT;

        if (flash_wait_ready(100000) != 0) {
            FLASH->CR &= ~FLASH_CR_PG;
            flash_lock();
            return -2;
        }
        FLASH->CR &= ~FLASH_CR_PG;
        FLASH->SR |= FLASH_SR_EOP;

        g_flash_mem[offset + i] = data[i];
    }
    flash_lock();
    return 0;
}

static int flash_read(uint32_t addr, uint8_t *data, uint32_t len)
{
    uint32_t offset;

    if (addr < FLASH_BASE_ADDR || (addr + len) > (FLASH_BASE_ADDR + FLASH_TOTAL_SIZE)) {
        return -1;
    }

    offset = addr - FLASH_BASE_ADDR;
    memcpy(data, &g_flash_mem[offset], len);
    return 0;
}

/* ================= 大容量块操作管理层 ================= */

#define DATA_MAGIC              0xA5A5A5A5U
#define DATA_HEADER_SIZE        16U
#define DATA_MAX_PAYLOAD        (FLASH_BLOCK_SIZE - DATA_HEADER_SIZE)

typedef struct {
    uint32_t magic;
    uint32_t block_index;
    uint32_t data_len;
    uint32_t crc;
} DataHeader_t;

static uint32_t simple_crc32(const uint8_t *data, uint32_t len)
{
    uint32_t crc = 0xFFFFFFFFU;
    uint32_t i;
    int j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 1U) {
                crc = (crc >> 1) ^ 0xEDB88320U;
            } else {
                crc >>= 1;
            }
        }
    }
    return ~crc;
}

/* 使用静态缓冲区避免栈溢出 */
static uint8_t g_block_buffer[FLASH_BLOCK_SIZE];

static int flash_block_write(uint32_t block_index, const uint8_t *data, uint32_t len)
{
    DataHeader_t header;
    uint32_t addr;

    if (block_index >= FLASH_BLOCK_COUNT) {
        return -1;
    }
    if (len > DATA_MAX_PAYLOAD) {
        return -2;
    }

    header.magic = DATA_MAGIC;
    header.block_index = block_index;
    header.data_len = len;
    header.crc = simple_crc32(data, len);

    if (flash_erase_block(block_index) != 0) {
        return -3;
    }

    memset(g_block_buffer, 0xFF, sizeof(g_block_buffer));
    memcpy(g_block_buffer, &header, sizeof(header));
    if (len > 0) {
        memcpy(g_block_buffer + DATA_HEADER_SIZE, data, len);
    }

    addr = FLASH_BASE_ADDR + block_index * FLASH_BLOCK_SIZE;
    if (flash_write(addr, g_block_buffer, DATA_HEADER_SIZE + len) != 0) {
        return -4;
    }

    return 0;
}

static int flash_block_read(uint32_t block_index, uint8_t *data, uint32_t *len)
{
    DataHeader_t header;
    uint32_t addr;
    uint32_t crc;

    if (block_index >= FLASH_BLOCK_COUNT) {
        return -1;
    }

    addr = FLASH_BASE_ADDR + block_index * FLASH_BLOCK_SIZE;
    if (flash_read(addr, g_block_buffer, sizeof(g_block_buffer)) != 0) {
        return -2;
    }

    memcpy(&header, g_block_buffer, sizeof(header));

    if (header.magic != DATA_MAGIC) {
        return -3;
    }
    if (header.block_index != block_index) {
        return -4;
    }
    if (header.data_len > DATA_MAX_PAYLOAD) {
        return -5;
    }

    crc = simple_crc32(g_block_buffer + DATA_HEADER_SIZE, header.data_len);
    if (crc != header.crc) {
        return -6;
    }

    if (data != NULL && len != NULL) {
        memcpy(data, g_block_buffer + DATA_HEADER_SIZE, header.data_len);
        *len = header.data_len;
    }

    return 0;
}

/* ================= 测试主函数 ================= */

int main(void)
{
    static uint8_t write_buf[1024];
    static uint8_t read_buf[1024];
