#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* ==================== 模拟寄存器与宏定义 ==================== */
#define RTC_BASE            0x40002800U
#define RTC_TR              (*(volatile uint32_t *)(RTC_BASE + 0x00U))
#define RTC_DR              (*(volatile uint32_t *)(RTC_BASE + 0x04U))
#define RTC_CR              (*(volatile uint32_t *)(RTC_BASE + 0x08U))
#define RTC_ISR             (*(volatile uint32_t *)(RTC_BASE + 0x0CU))
#define RTC_PRER            (*(volatile uint32_t *)(RTC_BASE + 0x10U))
#define RTC_WPR             (*(volatile uint32_t *)(RTC_BASE + 0x24U))
#define RTC_BKP0R           (*(volatile uint32_t *)(RTC_BASE + 0x50U))

/* RTC_CR 位定义 */
#define RTC_CR_FMT          (1U << 6)
#define RTC_CR_BYPSHAD      (1U << 5)

/* RTC_ISR 位定义 */
#define RTC_ISR_INITF       (1U << 6)
#define RTC_ISR_INIT        (1U << 7)
#define RTC_ISR_RSF         (1U << 5)

/* RTC_WPR 密钥 */
#define RTC_WPR_KEY1        0xCAU
#define RTC_WPR_KEY2        0x53U

/* 时间结构体 */
typedef struct {
    uint8_t hours;
    uint8_t minutes;
    uint8_t seconds;
    uint8_t day;
    uint8_t month;
    uint16_t year;
    uint8_t weekday;
} RTC_Time_t;

/* ==================== 模拟硬件寄存器存储 ==================== */
static uint32_t mock_rtc_tr = 0;
static uint32_t mock_rtc_dr = 0;
static uint32_t mock_rtc_cr = 0;
static uint32_t mock_rtc_isr = 0;
static uint32_t mock_rtc_prer = 0;
static uint32_t mock_rtc_wpr = 0;
static uint32_t mock_rtc_bkp0r = 0;

/* 重定向寄存器访问到模拟变量 */
#define RTC_TR_REG          mock_rtc_tr
#define RTC_DR_REG          mock_rtc_dr
#define RTC_CR_REG          mock_rtc_cr
#define RTC_ISR_REG         mock_rtc_isr
#define RTC_PRER_REG        mock_rtc_prer
#define RTC_WPR_REG         mock_rtc_wpr
#define RTC_BKP0R_REG       mock_rtc_bkp0r

/* ==================== 辅助函数 ==================== */
static uint8_t dec2bcd(uint8_t val)
{
    return (uint8_t)(((val / 10U) << 4U) | (val % 10U));
}

static uint8_t bcd2dec(uint8_t val)
{
    return (uint8_t)(((val >> 4U) * 10U) + (val & 0x0FU));
}

static uint8_t is_leap_year(uint16_t year)
{
    return ((year % 4U == 0U) && (year % 100U != 0U)) || (year % 400U == 0U);
}

static uint8_t days_in_month(uint8_t month, uint16_t year)
{
    static const uint8_t days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2U && is_leap_year(year)) {
        return 29U;
    }
    if (month >= 1U && month <= 12U) {
        return days[month - 1U];
    }
    return 30U;
}

/* ==================== RTC 底层操作 (无死循环) ==================== */
static void rtc_unlock(void)
{
    RTC_WPR_REG = RTC_WPR_KEY1;
    RTC_WPR_REG = RTC_WPR_KEY2;
}

static void rtc_lock(void)
{
    RTC_WPR_REG = 0xFFU;
}

static void rtc_enter_init_mode(void)
{
    RTC_ISR_REG |= RTC_ISR_INIT;
    /* 模拟硬件: 直接置位 INITF, 避免死循环 */
    RTC_ISR_REG |= RTC_ISR_INITF;
}

static void rtc_exit_init_mode(void)
{
    RTC_ISR_REG &= ~RTC_ISR_INIT;
}

static void rtc_wait_sync(void)
{
    /* 模拟硬件: 直接置位 RSF, 避免死循环 */
    RTC_ISR_REG |= RTC_ISR_RSF;
}

/* ==================== RTC 初始化 ==================== */
void RTC_Init(void)
{
    rtc_unlock();

    rtc_enter_init_mode();
    RTC_PRER_REG = (127U << 16U) | 255U;
    RTC_CR_REG &= ~(RTC_CR_FMT | RTC_CR_BYPSHAD);

    rtc_exit_init_mode();
    rtc_wait_sync();
    rtc_lock();
}

/* ==================== 设置时间 ==================== */
void RTC_SetTime(const RTC_Time_t *time)
{
    uint32_t tr_val;
    uint32_t dr_val;

    if (time == NULL) {
        return;
    }

    rtc_unlock();
    rtc_enter_init_mode();

    tr_val = ((uint32_t)dec2bcd(time->hours) << 16U) |
             ((uint32_t)dec2bcd(time->minutes) << 8U) |
             ((uint32_t)dec2bcd(time->seconds));

    dr_val = ((uint32_t)dec2bcd((uint8_t)(time->year % 100U)) << 16U) |
             ((uint32_t)dec2bcd(time->month) << 8U) |
             ((uint32_t)dec2bcd(time->day)) |
             ((uint32_t)(time->weekday & 0x07U) << 13U);

    RTC_TR_REG = tr_val;
    RTC_DR_REG = dr_val;

    rtc_exit_init_mode();
    rtc_wait_sync();
    rtc_lock();
}

/* ==================== 读取时间 ==================== */
void RTC_GetTime(RTC_Time_t *time)
{
    uint32_t tr_val;
    uint32_t dr_val;

    if (time == NULL) {
        return;
    }

    rtc_wait_sync();

    tr_val = RTC_TR_REG;
    dr_val = RTC_DR_REG;

    time->hours   = bcd2dec((uint8_t)((tr_val >> 16U) & 0x3FU));
    time->minutes = bcd2dec((uint8_t)((tr_val >> 8U) & 0x7FU));
    time->seconds = bcd2dec((uint8_t)(tr_val & 0x7FU));

    time->year    = (uint16_t)(2000U + bcd2dec((uint8_t)((dr_val >> 16U) & 0xFFU)));
    time->month   = bcd2dec((uint8_t)((dr_val >> 8U) & 0x1FU));
    time->day     = bcd2dec((uint8_t)(dr_val & 0x3FU));
    time->weekday = (uint8_t)((dr_val >> 13U) & 0x07U);
}

/* ==================== 时间同步 (从备份寄存器恢复) ==================== */
void RTC_SyncFromBackup(void)
{
    uint32_t backup = RTC_BKP0R_REG;
    RTC_Time_t time;

    if (backup == 0U) {
        printf("[RTC] 备份寄存器为空, 使用默认时间\n");
        time.hours = 0U;
        time.minutes = 0U;
        time.seconds = 0U;
        time.day = 1U;
        time.month = 1U;
        time.year = 2024U;
        time.weekday = 1U;
        RTC_SetTime(&time);
        return;
    }

    time.hours   = (uint8_t)((backup >> 24U) & 0xFFU);
    time.minutes = (uint8_t)((backup >> 16U) & 0xFFU);
    time.seconds = (uint8_t)((backup >> 8U) & 0xFFU);
    time.day     = (uint8_t)(backup & 0xFFU);
    time.month   = 1U;
    time.year    = 2024U;
    time.weekday = 1U;

    printf("[RTC] 从备份恢复时间: %02u:%02u:%02u\n",
           time.hours, time.minutes, time.seconds);
    RTC_SetTime(&time);
}

/* ==================== 保存时间到备份寄存器 ==================== */
void RTC_SaveToBackup(const RTC_Time_t *time)
{
    uint32_t backup;

    if (time == NULL) {
        return;
    }

    backup = ((uint32_t)time->hours << 24U) |
             ((uint32_t)time->minutes << 16U) |
             ((uint32_t)time->seconds << 8U) |
             ((uint32_t)time->day);
    RTC_BKP0R_REG = backup;
    printf("[RTC] 时间已保存到备份寄存器\n");
}

/* ==================== 时间递增 (模拟走时) ==================== */
void RTC_Tick(RTC_Time_t *time)
{
    if (time == NULL) {
        return;
    }

    time->seconds++;
    if (time->seconds >= 60U) {
        time->seconds = 0U;
        time->minutes++;
        if (time->minutes >= 60U) {
            time->minutes = 0U;
            time->hours++;
            if (time->hours >= 24U) {
                time->hours = 0U;
                time->day++;
                time->weekday++;
                if (time->weekday > 7U) {
                    time->weekday = 1U;
                }
                if (time->day > days_in_month(time->month, time->year)) {
                    time->day = 1U;
                    time->month++;
                    if (time->month > 12U) {
                        time->month = 1U;
                        time->year++;
                    }
                }
            }
        }
    }
}

/* ==================== 打印时间 ==================== */
void RTC_PrintTime(const RTC_Time_t *time)
{
    if (time == NULL) {
        return;
    }
    printf("RTC: %04u-%02u-%02u 星期%u  %02u:%02u:%02u\n",
           time->year, time->month, time->day, time->weekday,
           time->hours, time->minutes, time->seconds);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    RTC_Time_t time;
    int i;

    printf("===== RTC 实时时钟配置测试 =====\n\n");

    /* 1. 初始化 RTC */
    printf("[1] 初始化 RTC...\n");
    RTC_Init();
    printf("    RTC 初始化完成\n\n");

    /* 2. 设置初始时间 */
    printf("[2] 设置初始时间...\n");
    time.hours = 12U;
    time.minutes = 30U;
    time.seconds = 0U;
    time.day = 15U;
    time.month = 6U;
    time.year = 2024U;
    time.weekday = 6U;
    RTC_SetTime(&time);
    RTC_PrintTime(&time);
    printf("\n");

    /* 3. 读取时间验证 */
    printf("[3] 读取 RTC 时间...\n");
    RTC_GetTime(&time);
    RTC_PrintTime(&time);
    printf("\n");

    /* 4. 模拟走时 */
    printf("[4] 模拟走时 (每秒递增)...\n");
    for (i = 0; i < 5; i++) {
        RTC_Tick(&time);
        RTC_PrintTime(&time);
    }
    printf("\n");

    /* 5. 保存到备份寄存器 (掉电走时) */
    printf("[5] 保存时间到备份寄存器...\n");
    RTC_SaveToBackup(&time);
    printf("\n");

    /* 6. 模拟掉电重启后从备份恢复 */
    printf("[6] 模拟掉电重启, 从备份恢复...\n");
    RTC_SyncFromBackup();
    RTC_GetTime(&time);
    RTC_PrintTime(&time);
    printf("\n");

    /* 7. 边界测试: 跨天 */
    printf("[7] 边界测试: 23:59:59 -> 00:00:00\n");
    time.hours = 23U;
    time.minutes = 59U;
    time.seconds = 59U;
    time.day = 31U;
    time.month = 12U;
    time.year = 2024U;
    time.weekday = 2U;
    RTC_SetTime(&time);
    RTC_PrintTime(&time);
    RTC_Tick(&time);
    RTC_PrintTime(&time);
    printf("\n");

    /* 8. 闰年测试 */
    printf("[8] 闰年测试: 2024-02-28 -> 2024-02-29\n");
    time.hours = 23U;
    time.minutes = 59U;
    time.seconds = 59U;
    time.day = 28U;
    time.month = 2U;
    time.year = 2024U;
    time.weekday = 3U;
    RTC_SetTime(&time);
    RTC_PrintTime(&time);
    RTC_Tick(&time);
    RTC_PrintTime(&time);
    printf("\n");

    printf("===== 测试完成 =====\n");
    return 0;
}
