#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * 模拟寄存器定义 (Mock Registers)
 * 使用普通变量模拟寄存器，避免直接访问非法内存地址
 * ============================================================ */

/* 独立看门狗 (IWDG) 寄存器 */
static volatile uint32_t iwdg_kr  = 0U;
static volatile uint32_t iwdg_pr  = 0U;
static volatile uint32_t iwdg_rlr = 0U;
static volatile uint32_t iwdg_sr  = 0U;

#define IWDG_KR   (iwdg_kr)
#define IWDG_PR   (iwdg_pr)
#define IWDG_RLR  (iwdg_rlr)
#define IWDG_SR   (iwdg_sr)

/* 窗口看门狗 (WWDG) 寄存器 */
static volatile uint32_t wwdg_cr  = 0U;
static volatile uint32_t wwdg_cfr = 0U;
static volatile uint32_t wwdg_sr  = 0U;

#define WWDG_CR   (wwdg_cr)
#define WWDG_CFR  (wwdg_cfr)
#define WWDG_SR   (wwdg_sr)

/* 独立看门狗 键值 */
#define IWDG_KEY_RELOAD     0x0000AAAAU
#define IWDG_KEY_ENABLE     0x0000CCCCU
#define IWDG_KEY_WRITE      0x00005555U

/* 独立看门狗 预分频值 */
#define IWDG_PRESCALER_4    0x00U
#define IWDG_PRESCALER_8    0x01U
#define IWDG_PRESCALER_16   0x02U
#define IWDG_PRESCALER_32   0x03U
#define IWDG_PRESCALER_64   0x04U
#define IWDG_PRESCALER_128  0x05U
#define IWDG_PRESCALER_256  0x06U

/* 窗口看门狗 控制位 */
#define WWDG_CR_WDGA        (1U << 7)
#define WWDG_CR_T_MASK      0x7FU
#define WWDG_CFR_W_MASK     0x7FU
#define WWDG_CFR_WDGTB_Pos  7U
#define WWDG_CFR_WDGTB_MASK (3U << WWDG_CFR_WDGTB_Pos)
#define WWDG_CFR_EWI        (1U << 9)

/* 窗口看门狗 预分频值 */
#define WWDG_PRESCALER_1    0U
#define WWDG_PRESCALER_2    1U
#define WWDG_PRESCALER_4    2U
#define WWDG_PRESCALER_8    3U

/* 状态寄存器标志 */
#define IWDG_SR_PVU         (1U << 0)
#define IWDG_SR_RVU         (1U << 1)
#define WWDG_SR_EWIF        (1U << 0)

/* ============================================================
 * 独立看门狗 (IWDG) 配置与喂狗
 * ============================================================ */

/**
 * @brief  初始化独立看门狗
 * @param  prescaler: 预分频值 (IWDG_PRESCALER_x)
 * @param  reload:    重装载值 (0x0000 ~ 0x0FFF)
 */
void IWDG_Init(uint8_t prescaler, uint16_t reload)
{
    /* 1. 使能写访问 */
    IWDG_KR = IWDG_KEY_WRITE;

    /* 2. 设置预分频器 */
    IWDG_PR = (uint32_t)(prescaler & 0x07U);

    /* 3. 设置重装载值 */
    IWDG_RLR = (uint32_t)(reload & 0x0FFFU);

    /* 4. 模拟寄存器更新完成 (mock 中直接清零) */
    IWDG_SR = 0U;

    /* 5. 重装载计数器 (喂狗) */
    IWDG_KR = IWDG_KEY_RELOAD;

    /* 6. 启动独立看门狗 */
    IWDG_KR = IWDG_KEY_ENABLE;

    printf("[IWDG] Initialized: prescaler=%u, reload=%u\n",
           (unsigned)prescaler, (unsigned)reload);
}

/**
 * @brief  独立看门狗喂狗
 */
void IWDG_Feed(void)
{
    IWDG_KR = IWDG_KEY_RELOAD;
    printf("[IWDG] Fed the watchdog.\n");
}

/* ============================================================
 * 窗口看门狗 (WWDG) 配置与喂狗
 * ============================================================ */

/**
 * @brief  初始化窗口看门狗
 * @param  prescaler: 预分频值 (WWDG_PRESCALER_x)
 * @param  window:    窗口值 (0x40 ~ 0x7F)
 * @param  counter:   初始计数值 (0x40 ~ 0x7F)
 */
void WWDG_Init(uint8_t prescaler, uint8_t window, uint8_t counter)
{
    /* 参数合法性检查 */
    if (window < 0x40U || window > 0x7FU) {
        printf("[WWDG] Error: window value out of range (0x40~0x7F)\n");
        return;
    }
    if (counter < 0x40U || counter > 0x7FU) {
        printf("[WWDG] Error: counter value out of range (0x40~0x7F)\n");
        return;
    }

    /* 1. 设置预分频器和窗口值 */
    WWDG_CFR = ((uint32_t)(prescaler & 0x03U) << WWDG_CFR_WDGTB_Pos)
             | ((uint32_t)window & WWDG_CFR_W_MASK);

    /* 2. 设置计数器并启用看门狗 */
    WWDG_CR = WWDG_CR_WDGA | ((uint32_t)counter & WWDG_CR_T_MASK);

    printf("[WWDG] Initialized: prescaler=%u, window=0x%02X, counter=0x%02X\n",
           (unsigned)prescaler, (unsigned)window, (unsigned)counter);
}

/**
 * @brief  窗口看门狗喂狗
 * @param  counter: 新的计数值 (0x40 ~ 0x7F)
 */
void WWDG_Feed(uint8_t counter)
{
    if (counter < 0x40U || counter > 0x7FU) {
        printf("[WWDG] Error: feed counter out of range (0x40~0x7F)\n");
        return;
    }
    WWDG_CR = WWDG_CR_WDGA | ((uint32_t)counter & WWDG_CR_T_MASK);
    printf("[WWDG] Fed the watchdog with counter=0x%02X\n", (unsigned)counter);
}

/**
 * @brief  检查窗口看门狗早期唤醒中断标志
 * @return true 表示发生了早期唤醒中断
 */
bool WWDG_CheckEWI(void)
{
    if (WWDG_SR & WWDG_SR_EWIF) {
        WWDG_SR &= ~WWDG_SR_EWIF;  /* 清除标志 */
        return true;
    }
    return false;
}

/* ============================================================
 * 主函数
 * ============================================================ */

int main(void)
{
    printf("========================================\n");
    printf("  Watchdog Timer Configuration Demo\n");
    printf("========================================\n\n");

    /* ---------- 独立看门狗测试 ---------- */
    printf("--- Independent Watchdog (IWDG) Test ---\n");

    /* 预分频 64, 重装载 4095 => 超时约 26.2 秒 (LSI=40kHz) */
    IWDG_Init(IWDG_PRESCALER_64, 4095);

    /* 模拟正常喂狗 */
    for (int i = 0; i < 3; i++) {
        IWDG_Feed();
    }

    printf("\n");

    /* ---------- 窗口看门狗测试 ---------- */
    printf("--- Window Watchdog (WWDG) Test ---\n");

    /* 预分频 8, 窗口 0x50, 初始计数 0x7F */
    WWDG_Init(WWDG_PRESCALER_8, 0x50, 0x7F);

    /* 模拟在窗口内喂狗 (counter 递减到 0x50 以下时喂狗) */
    WWDG_Feed(0x60);  /* 合法: 0x60 < 0x7F 且 > 0x50 */
    WWDG_Feed(0x55);  /* 合法: 0x55 > 0x50 */
    WWDG_Feed(0x50);  /* 合法: 等于窗口值 */

    /* 检查早期唤醒中断 */
    if (WWDG_CheckEWI()) {
        printf("[WWDG] Early wakeup interrupt detected!\n");
    } else {
        printf("[WWDG] No early wakeup interrupt.\n");
    }

