 * @param prescaler 预分频值 (0~7)，对应 4~256
 * @param reload    重装载值 (0~0xFFF)
 */
void IWDG_Init(uint8_t prescaler, uint16_t reload)
{
    /* 1. 使能写访问 */
    IWDG_KR = IWDG_KEY_WRITE;

    /* 2. 设置预分频 */
    IWDG_PR = (uint32_t)(prescaler & 0x07U);

    /* 3. 设置重装载值 */
    IWDG_RLR = (uint32_t)(reload & 0x0FFFU);

    /* 4. 模拟寄存器更新完成（清 PVU/RVU 标志） */
    IWDG_SR &= ~(IWDG_SR_PVU | IWDG_SR_RVU);

    /* 5. 重装载计数器并启动看门狗 */
    IWDG_KR = IWDG_KEY_RELOAD;
    IWDG_KR = IWDG_KEY_ENABLE;

    printf("[IWDG] Init done: prescaler=%u, reload=%u\n",
           (unsigned)prescaler, (unsigned)reload);
}

/**
 * @brief 喂狗（重装载独立看门狗计数器）
 */
void IWDG_Feed(void)
{
    IWDG_KR = IWDG_KEY_RELOAD;
    printf("[IWDG] Feed watchdog\n");
}

/* ============================================================
 * 窗口看门狗 (WWDG) 配置与喂狗
 * ============================================================ */

/**
 * @brief 初始化窗口看门狗
 * @param counter   初始计数值 (0x40 ~ 0x7F)
 * @param window    窗口值 (0x40 ~ 0x7F)
 * @param prescaler 预分频 (0~3)
 * @param early_wakeup 是否使能提前唤醒中断
 */
void WWDG_Init(uint8_t counter, uint8_t window,
               uint8_t prescaler, bool early_wakeup)
{
    /* 1. 设置配置寄存器：窗口值 + 预分频 + 可选 EWI */
    uint32_t cfr = ((uint32_t)(window & WWDG_CFR_W_MASK))
                 | (((uint32_t)(prescaler & 0x03U)) << WWDG_CFR_WDGTB_Pos);
    if (early_wakeup) {
        cfr |= WWDG_CFR_EWI;
    }
    WWDG_CFR = cfr;

    /* 2. 设置计数器并启动看门狗 */
    WWDG_CR = (uint32_t)((counter & WWDG_CR_T_MASK) | WWDG_CR_WDGA);

    printf("[WWDG] Init done: counter=0x%02X, window=0x%02X, "
           "prescaler=%u, ewi=%s\n",
           (unsigned)counter, (unsigned)window,
           (unsigned)prescaler, early_wakeup ? "on" : "off");
}

/**
 * @brief 喂狗（重装载窗口看门狗计数器）
 * @param counter 新的计数值 (0x40 ~ 0x7F)
 * @return true 表示喂狗成功，false 表示喂狗过早（在窗口外）
 */
bool WWDG_Feed(uint8_t counter)
{
    uint8_t window = (uint8_t)(WWDG_CFR & WWDG_CFR_W_MASK);

    /* 检查是否在窗口内：计数值必须小于等于窗口值 */
    if (counter > window) {
        printf("[WWDG] Feed FAILED: counter=0x%02X > window=0x%02X "
               "(too early)\n",
               (unsigned)counter, (unsigned)window);
        return false;
    }

    /* 检查计数值是否在有效范围内 */
    if (counter < 0x40U) {
        printf("[WWDG] Feed FAILED: counter=0x%02X < 0x40 (invalid)\n",
               (unsigned)counter);
        return false;
    }

    WWDG_CR = (uint32_t)(counter & WWDG_CR_T_MASK);
    printf("[WWDG] Feed OK: counter=0x%02X\n", (unsigned)counter);
    return true;
}

/**
 * @brief 检查窗口看门狗提前唤醒中断标志
 * @return true 表示发生了提前唤醒中断
 */
bool WWDG_CheckEarlyWakeup(void)
{
    if (WWDG_SR & WWDG_SR_EWIF) {
        WWDG_SR &= ~WWDG_SR_EWIF;  /* 清除标志 */
        printf("[WWDG] Early wakeup interrupt detected!\n");
        return true;
    }
    return false;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    printf("===== Watchdog Configuration Demo =====\n\n");

    /* ---------- 独立看门狗测试 ---------- */
    printf("--- Independent Watchdog (IWDG) ---\n");
    IWDG_Init(4, 0x0FFF);   /* 预分频 4，重装载 4095 */
    IWDG_Feed();
    IWDG_Feed();
    printf("\n");

    /* ---------- 窗口看门狗测试 ---------- */
    printf("--- Window Watchdog (WWDG) ---\n");
    WWDG_Init(0x7F, 0x5F, 1, true);  /* 计数器 0x7F，窗口 0x5F */

    /* 正常喂狗：计数值在窗口内 */
    WWDG_Feed(0x7F);
    WWDG_Feed(0x60);
    WWDG_Feed(0x5F);

    /* 过早喂狗：计数值大于窗口值，应失败 */
    WWDG_Feed(0x70);

    /* 检查提前唤醒中断 */
    WWDG_CheckEarlyWakeup();

    printf("\n===== Demo Finished =====\n");
    return 0;
}
