/* ================= Mock 寄存器与宏定义 ================= */
/* 使用静态变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t mock_gpio_moder = 0;
static volatile uint32_t mock_gpio_pupdr = 0;
static volatile uint32_t mock_gpio_idr   = 0;

static volatile uint32_t mock_exti_imr  = 0;
static volatile uint32_t mock_exti_rtsr = 0;
static volatile uint32_t mock_exti_ftsr = 0;
static volatile uint32_t mock_exti_pr   = 0;

static volatile uint32_t mock_nvic_iser0 = 0;

#define GPIOA_MODER     (mock_gpio_moder)
#define GPIOA_PUPDR     (mock_gpio_pupdr)
#define GPIOA_IDR       (mock_gpio_idr)

#define EXTI_IMR        (mock_exti_imr)
#define EXTI_RTSR       (mock_exti_rtsr)
#define EXTI_FTSR       (mock_exti_ftsr)
#define EXTI_PR         (mock_exti_pr)

#define NVIC_ISER0      (mock_nvic_iser0)

#define GPIO_PIN_0      (1U << 0)
#define EXTI_LINE_0     (1U << 0)
#define IRQ_EXTI0       6U

/* 防抖时间阈值（单位：毫秒，模拟计数） */
#define DEBOUNCE_MS     20U

/* ================= 全局变量 ================= */
static volatile uint32_t g_tick_ms = 0;
static volatile uint32_t g_last_edge_time = 0;
static volatile uint32_t g_edge_count = 0;
static volatile bool     g_last_level = false;

/* ================= 模拟系统滴答 ================= */
static void SysTick_Handler_Mock(void)
{
    g_tick_ms++;
}

/* ================= GPIO 初始化 ================= */
static void GPIO_Init(void)
{
    /* PA0 配置为输入模式 (MODER = 00) */
    GPIOA_MODER &= ~(3U << (0U * 2U));
    /* PA0 下拉 (PUPDR = 10) */
    GPIOA_PUPDR &= ~(3U << (0U * 2U));
    GPIOA_PUPDR |=  (2U << (0U * 2U));
}

/* ================= EXTI 初始化 ================= */
static void EXTI_Init(void)
{
    /* 使能 EXTI0 中断屏蔽 */
    EXTI_IMR |= EXTI_LINE_0;
    /* 使能上升沿触发 */
    EXTI_RTSR |= EXTI_LINE_0;
    /* 使能下降沿触发 */
    EXTI_FTSR |= EXTI_LINE_0;
    /* 清除挂起位 */
    EXTI_PR = EXTI_LINE_0;
    /* 使能 NVIC EXTI0 中断 */
    NVIC_ISER0 |= (1U << IRQ_EXTI0);
}

/* ================= 防抖处理 ================= */
static bool Debounce_Check(uint32_t now_ms)
{
    if ((now_ms - g_last_edge_time) >= DEBOUNCE_MS) {
        g_last_edge_time = now_ms;
        return true;
    }
    return false;
}

/* ================= EXTI0 中断服务函数 ================= */
void EXTI0_IRQHandler(void)
{
    /* 检查挂起位 */
    if (EXTI_PR & EXTI_LINE_0) {
        /* 清除挂起位 */
        EXTI_PR = EXTI_LINE_0;

        uint32_t now = g_tick_ms;
        bool current_level = (GPIOA_IDR & GPIO_PIN_0) ? true : false;

        /* 防抖判断 */
        if (Debounce_Check(now)) {
            if (current_level != g_last_level) {
                g_last_level = current_level;
                g_edge_count++;
                if (current_level) {
                    printf("[EXTI0] Rising edge detected at %u ms, count=%u\n",
                           (unsigned)now, (unsigned)g_edge_count);
                } else {
                    printf("[EXTI0] Falling edge detected at %u ms, count=%u\n",
                           (unsigned)now, (unsigned)g_edge_count);
                }
            }
        } else {
            printf("[EXTI0] Debounced (ignored) at %u ms\n", (unsigned)now);
        }
    }
}

/* ================= 模拟外部信号触发 ================= */
static void Simulate_Edge(bool level, uint32_t delay_ms)
{
    /* 模拟时间推进 */
    for (uint32_t i = 0; i < delay_ms; i++) {
        SysTick_Handler_Mock();
    }

    /* 设置 GPIO 输入电平 */
    if (level) {
        GPIOA_IDR |= GPIO_PIN_0;
    } else {
        GPIOA_IDR &= ~GPIO_PIN_0;
    }

    /* 设置 EXTI 挂起位，模拟硬件触发 */
    EXTI_PR = EXTI_LINE_0;

    /* 调用中断服务函数 */
    EXTI0_IRQHandler();
}

/* ================= main 函数 ================= */
int main(void)
{
    printf("===== GPIO Interrupt (Rising/Falling Edge + Debounce) Demo =====\n");

    /* 初始化 */
    GPIO_Init();
    EXTI_Init();

    printf("Initial state: level=%d, count=%u\n",
           (int)g_last_level, (unsigned)g_edge_count);

    /* 模拟一系列边沿事件 */
    printf("\n--- Simulating edges ---\n");

    /* 上升沿，间隔 50ms（有效） */
    Simulate_Edge(true, 50);

    /* 下降沿，间隔 5ms（防抖忽略） */
    Simulate_Edge(false, 5);

    /* 下降沿，间隔 30ms（有效） */
    Simulate_Edge(false, 30);

    /* 上升沿，间隔 10ms（防抖忽略） */
    Simulate_Edge(true, 10);

    /* 上升沿，间隔 40ms（有效） */
    Simulate_Edge(true, 40);

    /* 下降沿，间隔 100ms（有效） */
    Simulate_Edge(false, 100);

    printf("\n--- Final result ---\n");
    printf("Total valid edges: %u\n", (unsigned)g_edge_count);
    printf("Last level: %d\n", (int)g_last_level);

    return 0;
}
