#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器与宏定义 ==================== */
#define MOTOR_POLE_PAIRS            2U
#define PWM_FREQ_HZ                 10000U
#define PWM_PERIOD_TICKS            1000U
#define VF_RATED_FREQ_HZ            50.0f
#define VF_RATED_VOLTAGE_V          380.0f
#define VF_MIN_FREQ_HZ              0.5f
#define VF_BOOST_VOLTAGE_V          20.0f
#define VF_BOOST_FREQ_HZ            5.0f
#define VF_MAX_FREQ_HZ              100.0f
#define VF_VOLTAGE_LIMIT_V          400.0f
#define VF_SLIP_COMPENSATION_HZ     1.0f
#define VF_ACCEL_RATE_HZ_PER_S      10.0f
#define VF_DECEL_RATE_HZ_PER_S      15.0f
#define VF_CTRL_PERIOD_S            0.001f

typedef struct {
    float freq_ref_hz;
    float freq_actual_hz;
    float voltage_ref_v;
    float boost_voltage_v;
    float boost_freq_hz;
    float rated_freq_hz;
    float rated_voltage_v;
    float min_freq_hz;
    float max_freq_hz;
    float accel_rate;
    float decel_rate;
    float slip_comp_hz;
    float duty_a;
    float duty_b;
    float duty_c;
    float theta_elec;
    float theta_step;
    uint8_t enable;
    uint8_t direction;
} vf_ctrl_t;

static vf_ctrl_t g_vf;

/* ==================== 初始化 ==================== */
static void vf_init(vf_ctrl_t *vf)
{
    vf->freq_ref_hz      = 0.0f;
    vf->freq_actual_hz   = 0.0f;
    vf->voltage_ref_v    = 0.0f;
    vf->boost_voltage_v  = VF_BOOST_VOLTAGE_V;
    vf->boost_freq_hz    = VF_BOOST_FREQ_HZ;
    vf->rated_freq_hz    = VF_RATED_FREQ_HZ;
    vf->rated_voltage_v  = VF_RATED_VOLTAGE_V;
    vf->min_freq_hz      = VF_MIN_FREQ_HZ;
    vf->max_freq_hz      = VF_MAX_FREQ_HZ;
    vf->accel_rate       = VF_ACCEL_RATE_HZ_PER_S;
    vf->decel_rate       = VF_DECEL_RATE_HZ_PER_S;
    vf->slip_comp_hz     = VF_SLIP_COMPENSATION_HZ;
    vf->duty_a           = 0.5f;
    vf->duty_b           = 0.5f;
    vf->duty_c           = 0.5f;
    vf->theta_elec       = 0.0f;
    vf->theta_step       = 0.0f;
    vf->enable           = 0U;
    vf->direction        = 1U;
}

/* ==================== 电压计算（含转矩提升） ==================== */
static float vf_calc_voltage(const vf_ctrl_t *vf, float freq_hz)
{
    float v;
    float f = freq_hz;

    if (f < 0.0f) {
        f = -f;
    }

    if (f < vf->min_freq_hz) {
        f = vf->min_freq_hz;
    }

    if (f <= vf->boost_freq_hz) {
        /* 低频段：线性提升，从 0 到 boost_voltage */
        v = vf->boost_voltage_v * (f / vf->boost_freq_hz);
    } else if (f <= vf->rated_freq_hz) {
        /* 恒压频比段：在 boost 电压基础上按 V/F 线性增加 */
        float v_base = vf->boost_voltage_v;
        float v_rated = vf->rated_voltage_v;
        float f_span = vf->rated_freq_hz - vf->boost_freq_hz;
        float v_span = v_rated - v_base;
        v = v_base + v_span * ((f - vf->boost_freq_hz) / f_span);
    } else {
        /* 弱磁段：电压保持额定值 */
        v = vf->rated_voltage_v;
    }

    if (v > VF_VOLTAGE_LIMIT_V) {
        v = VF_VOLTAGE_LIMIT_V;
    }

    return v;
}

/* ==================== 频率斜坡 ==================== */
static float vf_ramp_freq(vf_ctrl_t *vf, float target_hz, float dt)
{
    float diff = target_hz - vf->freq_actual_hz;
    float step;

    if (diff > 0.0f) {
        step = vf->accel_rate * dt;
        if (step > diff) {
            step = diff;
        }
    } else {
        step = -vf->decel_rate * dt;
        if (step < diff) {
            step = diff;
        }
    }

    vf->freq_actual_hz += step;

    if (vf->freq_actual_hz > vf->max_freq_hz) {
        vf->freq_actual_hz = vf->max_freq_hz;
    }
    if (vf->freq_actual_hz < -vf->max_freq_hz) {
        vf->freq_actual_hz = -vf->max_freq_hz;
    }

    return vf->freq_actual_hz;
}

/* ==================== SVPWM 占空比计算（简化） ==================== */
static void vf_calc_duty(vf_ctrl_t *vf, float freq_hz, float voltage_v)
{
    float vdc = 540.0f;
    float mod_index;
    float theta;
    float u_alpha;
    float u_beta;
    float ua;
    float ub;
    float uc;
    float u_max;
    float u_min;
    float u_mid;
    float u_offset;

    if (vf->enable == 0U) {
        vf->duty_a = 0.5f;
        vf->duty_b = 0.5f;
        vf->duty_c = 0.5f;
        return;
    }

    mod_index = voltage_v / vdc;
    if (mod_index > 0.95f) {
        mod_index = 0.95f;
    }

    /* 电角度积分 */
    vf->theta_step = 2.0f * 3.14159265f * freq_hz * VF_CTRL_PERIOD_S;
    vf->theta_elec += vf->theta_step;

    while (vf->theta_elec > 2.0f * 3.14159265f) {
        vf->theta_elec -= 2.0f * 3.14159265f;
    }
    while (vf->theta_elec < 0.0f) {
        vf->theta_elec += 2.0f * 3.14159265f;
    }

    theta = vf->theta_elec;

    /* 三相正弦参考 */
    ua = mod_index * cosf(theta);
    ub = mod_index * cosf(theta - 2.0f * 3.14159265f / 3.0f);
    uc = mod_index * cosf(theta + 2.0f * 3.14159265f / 3.0f);

    /* 零序注入（SVPWM 等效） */
    u_max = ua;
    if (ub > u_max) u_max = ub;
    if (uc > u_max) u_max = uc;

    u_min = ua;
    if (ub < u_min) u_min = ub;
    if (uc < u_min) u_min = uc;

    u_mid = (u_max + u_min) * 0.5f;
    u_offset = -u_mid;

    ua += u_offset;
    ub += u_offset;
    uc += u_offset;

    /* 归一化到占空比 0~1 */
    vf->duty_a = 0.5f + 0.5f * ua;
    vf->duty_b = 0.5f + 0.5f * ub;
    vf->duty_c = 0.5f + 0.5f * uc;

    if (vf->duty_a < 0.0f) vf->duty_a = 0.0f;
    if (vf->duty_a > 1.0f) vf->duty_a = 1.0f;
    if (vf->duty_b < 0.0f) vf->duty_b = 0.0f;
    if (vf->duty_b > 1.0f) vf->duty_b = 1.0f;
    if (vf->duty_c < 0.0f) vf->duty_c = 0.0f;
    if (vf->duty_c > 1.0f) vf->duty_c = 1.0f;
}

/* ==================== 主控制步 ==================== */
static void vf_step(vf_ctrl_t *vf, float target_freq_hz, float dt)
{
    float f_actual;
    float v_ref;

    if (vf->enable == 0U) {
        vf->freq_actual_hz = 0.0f;
        vf->voltage_ref_v = 0.0f;
        vf->duty_a = 0.5f;
        vf->duty_b = 0.5f;
        vf->duty_c = 0.5f;
        return;
    }

    if (target_freq_hz > vf->max_freq_hz) {
        target_freq_hz = vf->max_freq_hz;
    }
    if (target_freq_hz < -vf->max_freq_hz) {
        target_freq_hz = -vf->max_freq_hz;
    }

    f_actual = vf_ramp_freq(vf, target_freq_hz, dt);

    /* 滑差补偿：根据负载增加频率 */
    if (f_actual > 0.0f) {
        f_actual += vf->slip_comp_hz;
    } else if (f_actual < 0.0f) {
        f_actual -= vf->slip_comp_hz;
    }

    v_ref = vf_calc_voltage(vf, f_actual);
    vf->voltage_ref_v = v_ref;

    vf_calc_duty(vf, f_actual, v_ref);
}

/* ==================== 打印状态 ==================== */
static void vf_print(const vf_ctrl_t *vf)
{
    printf("Freq: %7.3f Hz | Volt: %7.3f V | Duty: A=%.4f B=%.4f C=%.4f | Theta: %.4f rad\n",
           vf->freq_actual_hz,
           vf->voltage_ref_v,
           vf->duty_a,
           vf->duty_b,
           vf->duty_c,
           vf->theta_elec);
}

/* ==================== main ==================== */
int main(void)
{
    float t;
    float dt = VF_CTRL_PERIOD_S;
    int i;

    printf("===== V/F Control with Torque Boost =====\n");
    printf("Rated: %.1f Hz / %.1f V, Boost: %.1f V @ %.1f Hz\n\n",
           VF_RATED_FREQ_HZ, VF_RATED_VOLTAGE_V,
           VF_BOOST_VOLTAGE_V, VF_BOOST_FREQ_HZ);

    vf_init(&g_vf);
    g_vf.enable = 1U;

    /* 阶段1：加速到 50Hz */
    printf("--- Phase 1: Accelerate to 50 Hz ---\n");
    for (i = 0; i < 6000; i++) {
        t = (float)i * dt;
        vf_step(&g_vf, 50.0f, dt);
        if (i % 1000 == 0) {
            printf("t=%6.3fs ", t);
            vf_print(&g_vf);
        }
    }

    /* 阶段2：稳定运行 */
    printf("\n--- Phase 2: Steady at 50 Hz ---\n");
    for (i = 0; i < 2000; i++) {
        t = 6.0f + (float)i * dt;
        vf_step(&g_vf, 50.0f, dt);
        if (i % 500 == 0) {
            printf("t=%6.3fs ", t);
            vf_print(&g_vf);
        }
    }

    /* 阶段3：降速到 10Hz */
    printf("\n--- Phase 3: Decelerate to 10 Hz ---\n");
    for (i = 0; i < 5000; i++) {
        t = 8.0f + (float)i * dt;
        vf_step(&g_vf, 10.0f, dt);
        if (i % 1000 == 0) {
            printf("t=%6.3fs ", t);
            vf_print(&g_vf);
        }
    }

    /* 阶段4：低频运行（转矩提升生效） */
    printf("\n--- Phase 4: Low freq 3 Hz (Boost active) ---\n");
    for (i = 0; i < 3000; i++) {
        t = 13.0f + (float)i * dt;
        vf_step(&g_vf, 3.0f, dt);
        if (i % 1000 == 0) {
            printf("t=%6.3fs ", t);
            vf_print(&g_vf);
        }
    }

    /* 阶段5：停机 */
    printf("\n--- Phase 5: Stop ---\n");
    g_vf.enable = 0U;
    vf_step(&g_vf, 0.0f, dt);
    printf("t=16.000s ");
    vf_print(&g_vf);

    printf("\n===== Done =====\n");
    return 0;
}
