#include <stdio.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* ================= 模拟寄存器与硬件抽象 ================= */
/* 模拟 ADC 采样结果寄存器 */
#define MOCK_ADC_U  ((float)0.0f)
#define MOCK_ADC_V  ((float)0.0f)
#define MOCK_ADC_W  ((float)0.0f)

/* 模拟 PWM 占空比输出寄存器 */
static float mock_pwm_u = 0.0f;
static float mock_pwm_v = 0.0f;
static float mock_pwm_w = 0.0f;

/* 模拟编码器/霍尔角度获取 */
static float mock_encoder_angle = 0.0f;

/* ================= 电机参数 ================= */
#define MOTOR_POLE_PAIRS     4
#define MOTOR_RS             0.5f
#define MOTOR_LD             0.001f
#define MOTOR_LQ             0.0015f
#define MOTOR_FLUX           0.05f

/* ================= 控制参数 ================= */
#define TS                   0.0001f
#define SPEED_REF            1000.0f
#define IQ_REF               2.0f
#define ID_REF               0.0f

/* ================= 数学工具 ================= */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

/* ================= Clarke 变换 ================= */
/* 三相电流 -> alpha-beta 静止坐标系 */
static void clarke_transform(float ia, float ib, float ic,
                             float *ialpha, float *ibeta)
{
    *ialpha = ia;
    *ibeta  = (ia + 2.0f * ib) / sqrtf(3.0f);
    (void)ic;
}

/* ================= Park 变换 ================= */
/* alpha-beta 静止坐标系 -> d-q 旋转坐标系 */
static void park_transform(float ialpha, float ibeta, float theta,
                           float *id, float *iq)
{
    float sin_t = sinf(theta);
    float cos_t = cosf(theta);

    *id =  ialpha * cos_t + ibeta * sin_t;
    *iq = -ialpha * sin_t + ibeta * cos_t;
}

/* ================= 反 Park 变换 ================= */
/* d-q 旋转坐标系 -> alpha-beta 静止坐标系 */
static void inv_park_transform(float ud, float uq, float theta,
                               float *ualpha, float *ubeta)
{
    float sin_t = sinf(theta);
    float cos_t = cosf(theta);

    *ualpha = ud * cos_t - uq * sin_t;
    *ubeta  = ud * sin_t + uq * cos_t;
}

/* ================= 反 Clarke 变换 ================= */
/* alpha-beta 静止坐标系 -> 三相电压 */
static void inv_clarke_transform(float ualpha, float ubeta,
                                 float *ua, float *ub, float *uc)
{
    *ua = ualpha;
    *ub = -0.5f * ualpha + (sqrtf(3.0f) / 2.0f) * ubeta;
    *uc = -0.5f * ualpha - (sqrtf(3.0f) / 2.0f) * ubeta;
}

/* ================= SVPWM 简化实现 ================= */
/* 将三相电压归一化后转换为占空比 */
static void svpwm_generate(float ua, float ub, float uc, float vdc,
                           float *duty_a, float *duty_b, float *duty_c)
{
    float half_vdc = 0.5f * vdc;
    *duty_a = clampf(0.5f + ua / vdc, 0.0f, 1.0f);
    *duty_b = clampf(0.5f + ub / vdc, 0.0f, 1.0f);
    *duty_c = clampf(0.5f + uc / vdc, 0.0f, 1.0f);
    (void)half_vdc;
}

/* ================= PI 控制器 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_min;
    float out_max;
} pi_ctrl_t;

static void pi_init(pi_ctrl_t *pi, float kp, float ki, float out_min, float out_max)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_min = out_min;
    pi->out_max = out_max;
}

static float pi_update(pi_ctrl_t *pi, float error, float ts)
{
    float p_term = pi->kp * error;
    pi->integral += pi->ki * error * ts;
    pi->integral = clampf(pi->integral, pi->out_min, pi->out_max);
    float out = p_term + pi->integral;
    return clampf(out, pi->out_min, pi->out_max);
}

/* ================= d-q 轴解耦控制 ================= */
/* 前馈解耦项：交叉耦合电压 + 反电动势 */
static void decoupling_compensation(float id, float iq, float omega_e,
                                    float *ud_ff, float *uq_ff)
{
    /* d 轴耦合项： -omega_e * Lq * iq */
    *ud_ff = -omega_e * MOTOR_LQ * iq;
    /* q 轴耦合项： omega_e * Ld * id + omega_e * flux */
    *uq_ff =  omega_e * MOTOR_LD * id + omega_e * MOTOR_FLUX;
}

/* ================= FOC 主控制循环 ================= */
typedef struct {
    float theta_e;
    float omega_e;
    float id;
    float iq;
    float ud;
    float uq;
    float ialpha;
    float ibeta;
    float ualpha;
    float ubeta;
    float duty_a;
    float duty_b;
    float duty_c;
} foc_state_t;

static void foc_init(foc_state_t *foc)
{
    foc->theta_e = 0.0f;
    foc->omega_e = 0.0f;
    foc->id = 0.0f;
    foc->iq = 0.0f;
    foc->ud = 0.0f;
    foc->uq = 0.0f;
    foc->ialpha = 0.0f;
    foc->ibeta = 0.0f;
    foc->ualpha = 0.0f;
    foc->ubeta = 0.0f;
    foc->duty_a = 0.5f;
    foc->duty_b = 0.5f;
    foc->duty_c = 0.5f;
}

static void foc_run(foc_state_t *foc,
                    float ia, float ib, float ic,
                    float theta_mech,
                    float vdc,
                    pi_ctrl_t *pi_d,
                    pi_ctrl_t *pi_q)
{
    float id_ref = ID_REF;
    float iq_ref = IQ_REF;
    float ud_ff, uq_ff;
    float ud_pi, uq_pi;

    /* 1. 电角度计算 */
    foc->theta_e = theta_mech * MOTOR_POLE_PAIRS;
    /* 归一化到 [0, 2*pi) */
    while (foc->theta_e >= 2.0f * M_PI) foc->theta_e -= 2.0f * M_PI;
    while (foc->theta_e < 0.0f) foc->theta_e += 2.0f * M_PI;

    /* 2. Clarke 变换 */
    clarke_transform(ia, ib, ic, &foc->ialpha, &foc->ibeta);

    /* 3. Park 变换 */
    park_transform(foc->ialpha, foc->ibeta, foc->theta_e, &foc->id, &foc->iq);

    /* 4. d-q 轴电流 PI 控制 */
    ud_pi = pi_update(pi_d, id_ref - foc->id, TS);
    uq_pi = pi_update(pi_q, iq_ref - foc->iq, TS);

    /* 5. d-q 轴解耦补偿 */
    decoupling_compensation(foc->id, foc->iq, foc->omega_e, &ud_ff, &uq_ff);

    foc->ud = ud_pi + ud_ff;
    foc->uq = uq_pi + uq_ff;

    /* 6. 反 Park 变换 */
    inv_park_transform(foc->ud, foc->uq, foc->theta_e,
                       &foc->ualpha, &foc->ubeta);

    /* 7. 反 Clarke 变换 */
    inv_clarke_transform(foc->ualpha, foc->ubeta,
                         &foc->duty_a, &foc->duty_b, &foc->duty_c);

    /* 8. SVPWM 生成占空比 */
    svpwm_generate(foc->duty_a, foc->duty_b, foc->duty_c, vdc,
                   &foc->duty_a, &foc->duty_b, &foc->duty_c);

    /* 9. 输出到模拟 PWM 寄存器 */
    mock_pwm_u = foc->duty_a;
    mock_pwm_v = foc->duty_b;
    mock_pwm_w = foc->duty_c;
}

/* ================= 主函数 ================= */
int main(void)
{
    foc_state_t foc;
    pi_ctrl_t pi_d, pi_q;
    float ia, ib, ic;
    float theta_mech;
    float vdc = 24.0f;
    int step;

    foc_init(&foc);
    pi_init(&pi_d, 0.5f, 10.0f, -12.0f, 12.0f);
    pi_init(&pi_q, 0.5f, 10.0f, -12.0f, 12.0f);

    printf("===== PMSM FOC Control (Park + dq Decoupling) =====\n");
    printf("Step | Theta_e | Id     | Iq     | Ud     | Uq     | DutyA  | DutyB  | DutyC\n");
    printf("-----+---------+--------+--------+--------+--------+--------+--------+-------\n");

    for (step = 0; step < 10; step++) {
        /* 模拟三相电流采样（此处用简单正弦模拟） */
        theta_mech = (float)step * 0.1f;
        ia = 1.5f * sinf(theta_mech);
        ib = 1.5f * sinf(theta_mech - 2.0f * M_PI / 3.0f);
        ic = 1.5f * sinf(theta_mech + 2.0f * M_PI / 3.0f);

        /* 模拟电角速度 */
        foc.omega_e = 100.0f;

        /* 执行 FOC 控制 */
        foc_run(&foc, ia, ib, ic, theta_mech, vdc, &pi_d, &pi_q);

        printf("%4d | %7.4f | %6.4f | %6.4f | %6.4f | %6.4f | %6.4f | %6.4f | %6.4f\n",
               step,
               foc.theta_e,
               foc.id,
               foc.iq,
               foc.ud,
               foc.uq,
               mock_pwm_u,
               mock_pwm_v,
               mock_pwm_w);
    }

    printf("\n===== FOC Control Loop Finished =====\n");
    return 0;
}
