#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== Mock 寄存器（使用普通变量，避免非法地址访问） ==================== */
static volatile uint32_t g_adc_ch0 = 0;
static volatile uint32_t g_adc_ch1 = 0;
static volatile uint32_t g_adc_ch2 = 0;
static volatile uint32_t g_pwm_u   = 0;
static volatile uint32_t g_pwm_v   = 0;
static volatile uint32_t g_pwm_w   = 0;
static volatile uint32_t g_encoder = 0;

#define ADC_RESULT_CH0       (g_adc_ch0)
#define ADC_RESULT_CH1       (g_adc_ch1)
#define ADC_RESULT_CH2       (g_adc_ch2)
#define PWM_DUTY_U           (g_pwm_u)
#define PWM_DUTY_V           (g_pwm_v)
#define PWM_DUTY_W           (g_pwm_w)
#define ENCODER_SPEED        (g_encoder)

/* ==================== 电机与系统参数 ==================== */
#define PI                   3.14159265358979323846f
#define TWO_PI               (2.0f * PI)

#define RS                   1.2f
#define RR                   1.0f
#define LS                   0.15f
#define LR                   0.15f
#define LM                   0.14f
#define POLE_PAIRS           2
#define J_MOMENT             0.01f
#define FLUX_REF             0.8f

#define TS                   0.0001f

#define SIGMA_L              (LS - (LM * LM) / LR)
#define TR                   (LR / RR)

/* ==================== 数据结构 ==================== */
typedef struct {
    float u_alpha;
    float u_beta;
    float i_alpha;
    float i_beta;
    float i_d;
    float i_q;
    float u_d;
    float u_q;
    float flux_r;
    float theta_e;
    float omega_r;
    float omega_e;
    float omega_slip;
    float speed_ref;
    float speed_fdb;
    float iq_ref;
    float id_ref;
    float id_fdb;
    float iq_fdb;
    float ud_out;
    float uq_out;
    float integral_d;
    float integral_q;
    float integral_speed;
} MotorCtrl_t;

/* ==================== 全局变量 ==================== */
static MotorCtrl_t g_motor;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static float pi_ctrl(float ref, float fdb, float kp, float ki,
                     float *integral, float out_min, float out_max)
{
    float err = ref - fdb;
    float out;

    *integral += ki * err * TS;
    *integral = clampf(*integral, out_min, out_max);

    out = kp * err + *integral;
    out = clampf(out, out_min, out_max);

    return out;
}

/* ==================== Clarke 变换 ==================== */
static void clarke_transform(float ia, float ib, float ic,
                             float *i_alpha, float *i_beta)
{
    *i_alpha = ia;
    *i_beta  = (ia + 2.0f * ib) / sqrtf(3.0f);
    (void)ic;
}

/* ==================== Park 变换 ==================== */
static void park_transform(float i_alpha, float i_beta, float theta,
                           float *i_d, float *i_q)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *i_d =  i_alpha * ct + i_beta * st;
    *i_q = -i_alpha * st + i_beta * ct;
}

/* ==================== 反 Park 变换 ==================== */
static void inv_park_transform(float u_d, float u_q, float theta,
                               float *u_alpha, float *u_beta)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *u_alpha = u_d * ct - u_q * st;
    *u_beta  = u_d * st + u_q * ct;
}

/* ==================== 反 Clarke 变换 ==================== */
static void inv_clarke_transform(float u_alpha, float u_beta,
                                 float *ua, float *ub, float *uc)
{
    *ua = u_alpha;
    *ub = -0.5f * u_alpha + (sqrtf(3.0f) / 2.0f) * u_beta;
    *uc = -0.5f * u_alpha - (sqrtf(3.0f) / 2.0f) * u_beta;
}

/* ==================== 磁链观测器 ==================== */
static void flux_observer(MotorCtrl_t *m)
{
    static float psi_r_alpha = 0.0f;
    static float psi_r_beta  = 0.0f;

    float dpsi_alpha, dpsi_beta;

    dpsi_alpha = (LM / TR) * m->i_alpha - (1.0f / TR) * psi_r_alpha
                 - m->omega_e * psi_r_beta;
    dpsi_beta  = (LM / TR) * m->i_beta  - (1.0f / TR) * psi_r_beta
                 + m->omega_e * psi_r_alpha;

    psi_r_alpha += dpsi_alpha * TS;
    psi_r_beta  += dpsi_beta  * TS;

    m->flux_r = sqrtf(psi_r_alpha * psi_r_alpha + psi_r_beta * psi_r_beta);
    if (m->flux_r < 1e-6f) {
        m->flux_r = 1e-6f;
    }

    m->theta_e = atan2f(psi_r_beta, psi_r_alpha);

    if (m->theta_e < 0.0f) {
        m->theta_e += TWO_PI;
    }
}

/* ==================== 速度环 ==================== */
static void speed_loop(MotorCtrl_t *m)
{
    const float KP_SPEED = 2.0f;
    const float KI_SPEED = 10.0f;
    const float IQ_MAX   = 10.0f;

    m->iq_ref = pi_ctrl(m->speed_ref, m->speed_fdb,
                        KP_SPEED, KI_SPEED,
                        &m->integral_speed,
                        -IQ_MAX, IQ_MAX);

    m->id_ref = 0.0f;
}

/* ==================== 电流环 ==================== */
static void current_loop(MotorCtrl_t *m)
{
    const float KP_CURR = 5.0f;
    const float KI_CURR = 100.0f;
    const float UD_MAX  = 200.0f;
    const float UQ_MAX  = 200.0f;

    m->ud_out = pi_ctrl(m->id_ref, m->id_fdb,
                        KP_CURR, KI_CURR,
                        &m->integral_d,
                        -UD_MAX, UD_MAX);

    m->uq_out = pi_ctrl(m->iq_ref, m->iq_fdb,
                        KP_CURR, KI_CURR,
                        &m->integral_q,
                        -UQ_MAX, UQ_MAX);

    m->ud_out -= m->omega_e * SIGMA_L * m->iq_fdb;
    m->uq_out += m->omega_e * SIGMA_L * m->id_fdb;
    m->uq_out += m->omega_e * (LM / LR) * m->flux_r;
}

/* ==================== SVPWM 生成 ==================== */
static void svpwm_generate(float ua, float ub, float uc, float udc)
{
    float duty_u, duty_v, duty_w;

    if (udc < 1e-6f) {
        udc = 1e-6f;
    }

    duty_u = 0.5f + ua / udc;
    duty_v = 0.5f + ub / udc;
    duty_w = 0.5f + uc / udc;

    duty_u = clampf(duty_u, 0.0f, 1.0f);
    duty_v = clampf(duty_v, 0.0f, 1.0f);
    duty_w = clampf(duty_w, 0.0f, 1.0f);

    PWM_DUTY_U = (uint32_t)(duty_u * 10000.0f);
    PWM_DUTY_V = (uint32_t)(duty_v * 10000.0f);
    PWM_DUTY_W = (uint32_t)(duty_w * 10000.0f);
}

/* ==================== 主控制循环 ==================== */
static void motor_control_step(MotorCtrl_t *m)
{
    float ia, ib, ic;
    float ua, ub, uc;
    float udc = 300.0f;

    ia = (float)(int32_t)ADC_RESULT_CH0 * 0.001f;
    ib = (float)(int32_t)ADC_RESULT_CH1 * 0.001f;
    ic = -ia - ib;

    m->speed_fdb = (float)(int32_t)ENCODER_SPEED * 0.01f;
    m->omega_r   = m->speed_fdb;
    m->omega_e   = m->omega_r * (float)POLE_PAIRS;

    clarke_transform(ia, ib, ic, &m->i_alpha, &m->i_beta);

    flux_observer(m);

    park_transform(m->i_alpha, m->i_beta, m->theta_e,
                   &m->i_d, &m->i_q);
    m->id_fdb = m->i_d;
    m->iq_fdb = m->i_q;

    speed_loop(m);

    current_loop(m);

    inv_park_transform(m->ud_out, m->uq_out, m->theta_e,
                       &m->u_alpha, &m->u_beta);

    inv_clarke_transform(m->u_alpha, m->u_beta, &ua, &ub, &uc);

    svpwm_generate(ua, ub, uc, udc);

    if (m->flux_r > 1e-6f) {
        m->omega_slip = (LM * m->iq_fdb) / (TR * m->flux_r);
    } else {
        m->omega_slip = 0.0f;
    }
}

/* ==================== 初始化 ==================== */
static void motor_init(MotorCtrl_t *m)
{
    m->u_alpha = 0.0f;
    m->u_beta  = 0.0f;
    m->i_alpha = 0.0f;
    m->i_beta  = 0.0f;
    m->i_d     = 0.0f;
    m->i_q     = 0.0f;
    m->u_d     = 0.0f;
    m->u_q     = 0.0f;
    m->flux_r  = 0.0f;
    m->theta_e = 0.0f;
    m->omega_r = 0.0f;
    m->omega_e = 0.0f;
    m->omega_slip = 0.0f;
