```c
#include <stdio.h>
#include <math.h>

/* ==================== 电机与系统参数 ==================== */
#define RS              1.2f        /* 定子电阻 (Ohm) */
#define RR              1.0f        /* 转子电阻 (Ohm) */
#define LS              0.15f       /* 定子电感 (H) */
#define LR              0.15f       /* 转子电感 (H) */
#define LM              0.14f       /* 互感 (H) */
#define SIGMA_LS        (LS - LM * LM / LR)  /* 定子瞬态电感 */
#define POLE_PAIRS      2           /* 极对数 */
#define TS              0.0001f     /* 控制周期 100us */
#define PSI_REF         0.8f        /* 定子磁链参考值 (Wb) */
#define TORQUE_REF      5.0f        /* 转矩参考值 (Nm) */
#define PI              3.14159265358979f

/* ==================== 电压矢量表 (两电平逆变器) ==================== */
/* 6个有效矢量 + 2个零矢量, 用开关状态表示 */
typedef struct {
    int sa;
    int sb;
    int sc;
} VoltageVector;

static const VoltageVector VV[8] = {
    {0, 0, 0},  /* V0: 零矢量 */
    {1, 0, 0},  /* V1: 100 */
    {1, 1, 0},  /* V2: 110 */
    {0, 1, 0},  /* V3: 010 */
    {0, 1, 1},  /* V4: 011 */
    {0, 0, 1},  /* V5: 001 */
    {1, 0, 1},  /* V6: 101 */
    {1, 1, 1}   /* V7: 零矢量 */
};

/* ==================== 电机状态结构体 ==================== */
typedef struct {
    /* 定子磁链 (alpha-beta 坐标系) */
    float psi_s_alpha;
    float psi_s_beta;
    /* 定子电流 */
    float i_s_alpha;
    float i_s_beta;
    /* 转子磁链 */
    float psi_r_alpha;
    float psi_r_beta;
    /* 电磁转矩 */
    float torque;
    /* 磁链幅值与角度 */
    float psi_s_mag;
    float psi_s_angle;
    /* 扇区 */
    int sector;
    /* 转速 */
    float omega_r;
    /* 直流母线电压 */
    float vdc;
} MotorState;

/* ==================== 初始化 ==================== */
static void Motor_Init(MotorState *m)
{
    m->psi_s_alpha = 0.0f;
    m->psi_s_beta  = 0.0f;
    m->i_s_alpha   = 0.0f;
    m->i_s_beta    = 0.0f;
    m->psi_r_alpha = 0.0f;
    m->psi_r_beta  = 0.0f;
    m->torque      = 0.0f;
    m->psi_s_mag   = 0.0f;
    m->psi_s_angle = 0.0f;
    m->sector      = 1;
    m->omega_r     = 0.0f;
    m->vdc         = 300.0f;
}

/* ==================== 电压矢量到 alpha-beta 变换 ==================== */
static void Voltage_To_AlphaBeta(const VoltageVector *vv, float vdc,
                                 float *v_alpha, float *v_beta)
{
    /* 相电压: Van = Vdc/3 * (2*sa - sb - sc) 等 */
    float va = vdc / 3.0f * (2.0f * vv->sa - vv->sb - vv->sc);
    float vb = vdc / 3.0f * (2.0f * vv->sb - vv->sa - vv->sc);
    float vc = vdc / 3.0f * (2.0f * vv->sc - vv->sa - vv->sb);

    /* Clarke 变换 (等幅值) */
    *v_alpha = (2.0f / 3.0f) * (va - 0.5f * vb - 0.5f * vc);
    *v_beta  = (2.0f / 3.0f) * (0.8660254f * vb - 0.8660254f * vc);
}

/* ==================== 磁链观测器 (电压模型 + 电流模型混合) ==================== */
static void Flux_Observer(MotorState *m, float v_alpha, float v_beta)
{
    /* --- 电压模型: 积分 (psi_s = ∫(v_s - Rs*i_s)dt) --- */
    float emf_alpha = v_alpha - RS * m->i_s_alpha;
    float emf_beta  = v_beta  - RS * m->i_s_beta;

    /* 纯积分 (实际中需加低通滤波或漂移补偿) */
    m->psi_s_alpha += emf_alpha * TS;
    m->psi_s_beta  += emf_beta  * TS;

    /* --- 电流模型: 转子磁链 --- */
    float tr = LR / RR;  /* 转子时间常数 */
    float sigma = 1.0f - (LM * LM) / (LS * LR);

    /* 转子磁链微分方程:
       dpsi_r/dt = (Lm/Tr)*i_s - (1/Tr + j*omega_r)*psi_r */
    float dpsi_r_alpha = (LM / tr) * m->i_s_alpha
                         - (1.0f / tr) * m->psi_r_alpha
                         + m->omega_r * m->psi_r_beta;
    float dpsi_r_beta  = (LM / tr) * m->i_s_beta
                         - (1.0f / tr) * m->psi_r_beta
                         - m->omega_r * m->psi_r_alpha;

    m->psi_r_alpha += dpsi_r_alpha * TS;
    m->psi_r_beta  += dpsi_r_beta  * TS;

    /* 定子磁链 = 转子磁链 + sigma*Ls*定子电流 */
    float psi_s_alpha_curr = m->psi_r_alpha + SIGMA_LS * m->i_s_alpha;
    float psi_s_beta_curr  = m->psi_r_beta  + SIGMA_LS * m->i_s_beta;

    /* 混合: 低速用电流模型, 高速用电压模型 (简单加权) */
    float speed_abs = fabsf(m->omega_r);
    float w = speed_abs / (speed_abs + 10.0f);  /* 0~1 权重 */
    m->psi_s_alpha = w * m->psi_s_alpha + (1.0f - w) * psi_s_alpha_curr;
    m->psi_s_beta  = w * m->psi_s_beta  + (1.0f - w) * psi_s_beta_curr;

    /* 磁链幅值与角度 */
    m->psi_s_mag   = sqrtf(m->psi_s_alpha * m->psi_s_alpha +
                           m->psi_s_beta  * m->psi_s_beta);
    m->psi_s_angle = atan2f(m->psi_s_beta, m->psi_s_alpha);
    if (m->psi_s_angle < 0.0f)
        m->psi_s_angle += 2.0f * PI;
}

/* ==================== 转矩计算 ==================== */
static void Torque_Calc(MotorState *m)
{
    /* Te = 1.5 * P * (psi_s_alpha * i_s_beta - psi_s_beta * i_s_alpha) */
    m->torque = 1.5f * POLE_PAIRS *
                (m->psi_s_alpha * m->i_s_beta - m->psi_s_beta * m->i_s_alpha);
}

/* ==================== 扇区判断 ==================== */
static int Sector_Detect(float angle)
{
    /* 将 0~2pi 分为 6 个扇区, 每个 60 度 */
    int sec = (int)(angle / (PI / 3.0f)) + 1;
    if (sec > 6) sec = 6;
    if (sec < 1) sec = 1;
    return sec;
}

/* ==================== 磁链与转矩滞环比较 ==================== */
static int Hysteresis_Flux(float psi_mag, float psi_ref)
{
    /* 磁链滞环: 返回 1 表示需要增大, 0 表示需要减小 */
    float err = psi_ref - psi_mag;
    if (err > 0.01f)       return 1;  /* 需要增大磁链 */
    else if (err < -0.01f) return 0;  /* 需要减小磁链 */
    else                   return -1; /* 保持 */
}

static int Hysteresis_Torque(float torque, float torque_ref)
{
    /* 转矩滞环: 返回 1 表示需要增大, 0 表示需要减小 */
    float err = torque_ref - torque;
    if (err > 0.1f)        return 1;  /* 需要增大转矩 */
    else if (err < -0.1f)  return 0;  /* 需要减小转矩 */
    else                   return -1; /* 保持 */
}

/* ==================== 电压矢量选择表 ==================== */
/* 根据扇区、磁链滞环输出、转矩滞环输出选择电压矢量 */
/* 表: [sector][flux_hyst][torque_hyst] -> 电压矢量索引 */
static const int VV_Table[6][2][2] = {
    /* sector 1 */
    {{2, 3}, {6, 1}},
    /* sector 2 */
    {{3, 4}, {1, 2}},
    /* sector 3 */
    {{4, 5}, {2, 3}},
    /* sector 4 */
    {{5, 6}, {3, 4}},
    /* sector 5 */
    {{6, 1}, {4, 5}},
    /* sector 6 */
    {{1, 2}, {5, 6}}
};

/* ==================== DTC 控制器 ==================== */
static int DTC_Controller(MotorState *m)
{
    /* 1. 扇区判断 */
    m->sector = Sector_Detect(m->psi_s_angle);

    /* 2. 滞环比较 */
    int flux_hyst   = Hysteresis_Flux(m->psi_s_mag, PSI_REF);
    int torque_hyst = Hysteresis_Torque(m->torque, TORQUE_REF);

    /* 3. 选择电压矢量 */
    int vv_idx;
    if (flux_hyst < 0 || torque_hyst < 0) {
        /* 保持: 使用零矢量 */
        vv_idx = 0;
    } else {
        int sec_idx = m->sector - 1;
        if (sec_idx < 0) sec_idx = 0;
        if (sec_idx > 5) sec_idx = 5;
        vv_idx = VV_Table[sec_idx][flux_hyst][torque_hyst];
    }

    return vv_idx;
}

/* ==================== 电流更新 (简化电机模型) ==================== */
static void Current_Update(MotorState *m, float v_alpha, float v_beta)
{
    /* 简化: 用瞬态电感近似
       d(i_s)/dt = (v_s - Rs*i_s - d(psi_s)/dt) / sigma_Ls
       这里用简化模型: 仅用于测试骨架 */
    float di_alpha = (v_alpha - RS * m->i_s_alpha) / SIGMA_LS;
    float di_beta  = (v_beta  - RS * m->i_s_beta)  / SIGMA_LS;

    m->i_s_alpha += di_alpha * TS;
    m->i_s_beta  += di_beta  * TS;

    /* 限制电流幅值 (模拟实际限幅) */
    float i_mag = sqrtf(m->i_s_alpha * m->i_s_alpha +
                        m->i_s_beta  * m->i_s_beta);
    if (i_mag > 20.0f) {
        m->i_s_alpha *= 20.0f / i_mag;
        m->i_s_beta  *= 20.0f / i_mag;
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    MotorState motor;
    Motor_Init(&motor);

    /* 模拟运行 1000 个控制周期 */
    int step;
    for (step = 0; step < 1000; step++) {
        /* 1. 选择电压矢量 */
        int vv_idx = DTC_Controller(&motor);

        /* 2. 计算 alpha-beta 电压 */
        float v_alpha, v_beta;
        Voltage_To_AlphaBeta(&VV[vv_idx], motor.vdc, &v_alpha, &v_beta);

        /* 3. 更新电流 (简化电机模型) */
        Current_Update(&motor, v_alpha, v_beta);

        /* 4. 磁链观测 */
        Flux_Observer(&motor, v_alpha, v_beta);

        /* 5. 转矩计算 */
        Torque_Calc(&motor);

        /* 6. 模拟转速变化 (简单加速) */
        motor.omega_r += 0.001f * motor.torque;
        if (motor.omega_r > 100.0f) motor.omega_r = 100.0f;

        /* 每 200 步打印一次状态 */
        if (step % 200 == 0) {
            printf("Step %4d | VV=%d | Sector=%d | Psi=%.4f Wb | "
                   "Te=%.4f Nm | wr=%.2f rad/s | "
                   "i_alpha=%.4f i_beta=%.4f\n",
                   step, vv_idx, motor.sector,
                   motor.psi_s_mag, motor.torque, motor.omega_r,
                   motor.i_s_alpha, motor.i_s_beta);
        }
    }

    printf("\n=== DTC Simulation Complete ===\n");
    printf("Final: Psi=%.4f Wb, Te=%.4f Nm, Sector=%d\n",
           motor.psi_s_mag, motor.torque, motor.sector);

    return 0;
}
