#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static uint32_t g_adc_ia = 0;
static uint32_t g_adc_ib = 0;
static uint32_t g_adc_ic = 0;
static uint32_t g_adc_udc = 0;
static uint32_t g_pwm_ta = 0;
static uint32_t g_pwm_tb = 0;
static uint32_t g_pwm_tc = 0;
static uint32_t g_enc_speed = 0;

#define ADC_IA_REG      (g_adc_ia)
#define ADC_IB_REG      (g_adc_ib)
#define ADC_IC_REG      (g_adc_ic)
#define ADC_UDC_REG     (g_adc_udc)

#define PWM_TA_REG      (g_pwm_ta)
#define PWM_TB_REG      (g_pwm_tb)
#define PWM_TC_REG      (g_pwm_tc)

#define ENC_SPEED_REG   (g_enc_speed)

/* ================= 电机参数 ================= */
#define MOTOR_RS        1.2f
#define MOTOR_RR        1.0f
#define MOTOR_LS        0.15f
#define MOTOR_LR        0.15f
#define MOTOR_LM        0.14f
#define MOTOR_PN        2
#define MOTOR_J         0.01f

#define MOTOR_SIGMA_LS  (MOTOR_LS - MOTOR_LM * MOTOR_LM / MOTOR_LR)
#define MOTOR_TR        (MOTOR_LR / MOTOR_RR)

/* ================= 控制参数 ================= */
#define TS              0.0001f
#define PI_F            3.14159265358979f
#define SQRT3           1.73205080756888f
#define TWO_PI          6.28318530717958f

#define KP_SPEED        0.5f
#define KI_SPEED        5.0f
#define KP_IQ           10.0f
#define KI_IQ           200.0f
#define KP_ID           10.0f
#define KI_ID           200.0f

#define IQ_MAX          10.0f
#define ID_MAX          10.0f
#define UQ_MAX          200.0f
#define UD_MAX          200.0f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_max;
    float out_min;
} PI_Controller;

typedef struct {
    float theta_e;
    float omega_r;
    float omega_m;
    float psi_r;

    float ia, ib, ic;
    float ialpha, ibeta;
    float id, iq;

    float ud, uq;
    float ualpha, ubeta;
    float ua, ub, uc;

    float speed_ref;
    float speed_fdb;
    float id_ref;
    float iq_ref;

    float psi_ralpha;
    float psi_rbeta;

    PI_Controller pi_speed;
    PI_Controller pi_id;
    PI_Controller pi_iq;

    float ts;
} MotorCtrl;

/* ================= PI 调节器 ================= */
static void PI_Init(PI_Controller *pi, float kp, float ki, float out_max, float out_min)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_max = out_max;
    pi->out_min = out_min;
}

static float PI_Calc(PI_Controller *pi, float error)
{
    float p_term = pi->kp * error;
    pi->integral += pi->ki * error * TS;

    if (pi->integral > pi->out_max) pi->integral = pi->out_max;
    if (pi->integral < pi->out_min) pi->integral = pi->out_min;

    float out = p_term + pi->integral;

    if (out > pi->out_max) out = pi->out_max;
    if (out < pi->out_min) out = pi->out_min;

    return out;
}

/* ================= Clarke 变换 ================= */
static void Clarke_Transform(float ia, float ib, float ic, float *ialpha, float *ibeta)
{
    *ialpha = ia;
    *ibeta = (ia + 2.0f * ib) / SQRT3;
    (void)ic;
}

/* ================= Park 变换 ================= */
static void Park_Transform(float ialpha, float ibeta, float theta, float *id, float *iq)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *id =  ialpha * ct + ibeta * st;
    *iq = -ialpha * st + ibeta * ct;
}

/* ================= 反 Park 变换 ================= */
static void Inv_Park_Transform(float ud, float uq, float theta, float *ualpha, float *ubeta)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *ualpha = ud * ct - uq * st;
    *ubeta  = ud * st + uq * ct;
}

/* ================= 反 Clarke 变换 ================= */
static void Inv_Clarke_Transform(float ualpha, float ubeta, float *ua, float *ub, float *uc)
{
    *ua = ualpha;
    *ub = -0.5f * ualpha + (SQRT3 / 2.0f) * ubeta;
    *uc = -0.5f * ualpha - (SQRT3 / 2.0f) * ubeta;
}

/* ================= SVPWM 占空比计算 ================= */
static void SVPWM_Calc(float ualpha, float ubeta, float udc, float *ta, float *tb, float *tc)
{
    float half_udc = udc * 0.5f;
    if (half_udc < 1.0f) half_udc = 1.0f;

    float ma = 0.9f;
    float theta = atan2f(ubeta, ualpha);
    float va = ma * cosf(theta);
    float vb = ma * cosf(theta - TWO_PI / 3.0f);
    float vc = ma * cosf(theta + TWO_PI / 3.0f);

    float t1 = (va + 1.0f) * 0.5f;
    float t2 = (vb + 1.0f) * 0.5f;
    float t0 = (vc + 1.0f) * 0.5f;

    if (t1 > 1.0f) t1 = 1.0f;
    if (t1 < 0.0f) t1 = 0.0f;
    if (t2 > 1.0f) t2 = 1.0f;
    if (t2 < 0.0f) t2 = 0.0f;
    if (t0 > 1.0f) t0 = 1.0f;
    if (t0 < 0.0f) t0 = 0.0f;

    *ta = t1;
    *tb = t2;
    *tc = t0;

    (void)ualpha;
    (void)ubeta;
    (void)half_udc;
}

/* ================= 转子磁链观测器 ================= */
static void Flux_Observer(MotorCtrl *m)
{
    float dpsi = (MOTOR_LM / MOTOR_TR) * m->id - (1.0f / MOTOR_TR) * m->psi_r;
    m->psi_r += dpsi * TS;

    if (m->psi_r < 0.001f) m->psi_r = 0.001f;

    float omega_slip = (MOTOR_LM * m->iq) / (MOTOR_TR * m->psi_r + 1e-6f);

    m->omega_r = m->omega_m * MOTOR_PN;

    float omega_e = m->omega_r + omega_slip;

    m->theta_e += omega_e * TS;

    while (m->theta_e >= TWO_PI) m->theta_e -= TWO_PI;
    while (m->theta_e < 0.0f)    m->theta_e += TWO_PI;

    m->psi_ralpha = m->psi_r * cosf(m->theta_e);
    m->psi_rbeta  = m->psi_r * sinf(m->theta_e);
}

/* ================= 电流采样 ================= */
static void Current_Sample(MotorCtrl *m)
{
    m->ia = (float)(int32_t)ADC_IA_REG * 0.001f;
    m->ib = (float)(int32_t)ADC_IB_REG * 0.001f;
    m->ic = (float)(int32_t)ADC_IC_REG * 0.001f;
}

/* ================= 速度采样 ================= */
static void Speed_Sample(MotorCtrl *m)
{
    m->omega_m = (float)(int32_t)ENC_SPEED_REG * 0.001f;
    m->speed_fdb = m->omega_m * MOTOR_PN;
}

/* ================= 矢量控制主算法 ================= */
static void FOC_Control(MotorCtrl *m)
{
    Current_Sample(m);
    Speed_Sample(m);

    Clarke_Transform(m->ia, m->ib, m->ic, &m->ialpha, &m->ibeta);

    Park_Transform(m->ialpha, m->ibeta, m->theta_e, &m->id, &m->iq);

    float speed_error = m->speed_ref - m->speed_fdb;
    m->iq_ref = PI_Calc(&m->pi_speed, speed_error);

    m->id_ref = 0.0f;

    float id_error = m->id_ref - m->id;
    float iq_error = m->iq_ref - m->iq;

    m->ud = PI_Calc(&m->pi_id, id_error);
    m->uq = PI_Calc(&m->pi_iq, iq_error);

    float omega_e = m->omega_r + (MOTOR_LM * m->iq) / (MOTOR_TR * m->psi_r + 1e-6f);
    float decouple_d = -omega_e * MOTOR_SIGMA_LS * m->iq;
    float decouple_q =  omega_e * MOTOR_SIGMA_LS * m->id
                      + omega_e * MOTOR_LM * m->psi_r / MOTOR_LR;

    m->ud += decouple_d;
    m->uq += decouple_q;

    Inv_Park_Transform(m->ud, m->uq, m->theta_e, &m->ualpha, &m->ubeta);

    float udc = (float)(int32_t)ADC_UDC_REG * 0.01f;
    if (udc < 1.0f) udc = 300.0f;

    SVPWM_Calc(m->ualpha, m->ubeta, udc, &m->ua, &m->ub, &m->uc);

    PWM_TA_REG = (uint32_t)(m->ua * 10000.0f);
    PWM_TB_REG = (uint32_t)(m->ub * 10000.0f);
    PWM_TC_REG = (uint32_t)(m->uc * 10000.0f);

    Flux_Observer(m);
}

/* ================= 初始化 ================= */
static void MotorCtrl_Init(MotorCtrl *m)
{
    m->theta_e = 0.0f;
    m->omega_r = 0.0f;
    m->omega_m = 0.0f;
    m->psi_r = 0.5f;

    m->ia = 0.0f; m->ib = 0.0f; m->ic = 0.0f;
