#define MICROSTEP       16U
#define FULL_STEP_ANGLE 1.8f
#define MICROSTEP_ANGLE (FULL_STEP_ANGLE / MICROSTEP)

/* 相电流幅值 (单位: mA) */
#define PHASE_CURRENT_MAX   1000U
#define PHASE_CURRENT_MIN   0U

/* 正弦表: 16 细分, 每步 22.5 度 */
static const float sin_table[MICROSTEP] = {
    0.0000f,  0.3827f,  0.7071f,  0.9239f,
    1.0000f,  0.9239f,  0.7071f,  0.3827f,
    0.0000f, -0.3827f, -0.7071f, -0.9239f,
   -1.0000f, -0.9239f, -0.7071f, -0.3827f
};

/* 余弦表: 与正弦表相差 90 度 */
static const float cos_table[MICROSTEP] = {
    1.0000f,  0.9239f,  0.7071f,  0.3827f,
    0.0000f, -0.3827f, -0.7071f, -0.9239f,
   -1.0000f, -0.9239f, -0.7071f, -0.3827f,
    0.0000f,  0.3827f,  0.7071f,  0.9239f
};

/* 步进电机状态 */
typedef struct {
    uint8_t  step_index;      /* 当前细分步索引 0~15 */
    int32_t  position;        /* 累计位置 (微步) */
    uint16_t current_a;       /* A 相目标电流 (mA) */
    uint16_t current_b;       /* B 相目标电流 (mA) */
    uint16_t current_a_meas;  /* A 相实测电流 (mA) */
    uint16_t current_b_meas;  /* B 相实测电流 (mA) */
    uint8_t  enabled;         /* 使能标志 */
} StepperMotor_t;

static StepperMotor_t motor = {
    0, 0, 0, 0, 0, 0, 0
};

/* ========== 硬件抽象层 (Mock) ========== */

/* 初始化定时器用于 PWM 输出 */
static void HAL_TIM_PWM_Init(void)
{
    /* 设置 PWM 周期: 假设系统时钟 72MHz, 20kHz PWM */
    TIM_ARR = 3600 - 1;
    /* 使能自动重装载预装载 */
    TIM_CR1 |= (1U << 7);
    /* 使能计数器 */
    TIM_CR1 |= (1U << 0);
    printf("[HAL] TIM PWM initialized, ARR=%u\n", (unsigned)TIM_ARR);
}

/* 设置 A 相 PWM 占空比 (0~1000 对应 0~100%) */
static void HAL_SetPWM_A(uint16_t duty)
{
    if (duty > 1000) duty = 1000;
    TIM_CCR1 = (uint32_t)((uint64_t)TIM_ARR * duty / 1000);
}

/* 设置 B 相 PWM 占空比 (0~1000 对应 0~100%) */
static void HAL_SetPWM_B(uint16_t duty)
{
    if (duty > 1000) duty = 1000;
    TIM_CCR2 = (uint32_t)((uint64_t)TIM_ARR * duty / 1000);
}

/* 读取 A 相电流采样值 (mA) */
static uint16_t HAL_ReadCurrent_A(void)
{
    return motor.current_a_meas;
}

/* 读取 B 相电流采样值 (mA) */
static uint16_t HAL_ReadCurrent_B(void)
{
    return motor.current_b_meas;
}

/* 使能/禁用电机驱动 */
static void HAL_EnableDriver(uint8_t en)
{
    if (en) {
        GPIOA_ODR |= (1U << 0);
        printf("[HAL] Driver ENABLED\n");
    } else {
        GPIOA_ODR &= ~(1U << 0);
        printf("[HAL] Driver DISABLED\n");
    }
}

/* ========== 细分驱动核心算法 ========== */

/*
 * 根据细分步索引计算两相目标电流
 * 采用正弦/余弦电流波形实现 16 细分
 * I_A = I_max * sin(theta)
 * I_B = I_max * cos(theta)
 * theta = step_index * 22.5 度
 */
static void Stepper_CalcPhaseCurrent(uint8_t step_index,
                                      uint16_t *ia, uint16_t *ib)
{
    float sin_val, cos_val;
    int32_t ia_signed, ib_signed;

    if (ia == NULL || ib == NULL) {
        return;
    }

    step_index %= MICROSTEP;

    sin_val = sin_table[step_index];
    cos_val = cos_table[step_index];

    /* 计算带符号电流值 */
    ia_signed = (int32_t)(sin_val * (float)PHASE_CURRENT_MAX);
    ib_signed = (int32_t)(cos_val * (float)PHASE_CURRENT_MAX);

    /* 转换为无符号 (H 桥双向驱动, 用符号表示方向) */
    *ia = (uint16_t)(ia_signed >= 0 ? ia_signed : -ia_signed);
    *ib = (uint16_t)(ib_signed >= 0 ? ib_signed : -ib_signed);
}

/*
 * 电流闭环控制 (PI 控制器)
 * 根据目标电流和实测电流调整 PWM 占空比
 */
static uint16_t Stepper_CurrentControl(uint16_t target, uint16_t measured)
{
    int32_t error;
    int32_t output;
    const int32_t Kp = 2;      /* 比例增益 */
    const int32_t out_max = 1000;

    error = (int32_t)target - (int32_t)measured;

    /* 简化 PI: 仅比例控制用于演示 */
    output = Kp * error;

    /* 限幅 */
    if (output > out_max) output = out_max;
    if (output < 0) output = 0;

    return (uint16_t)output;
}

/*
 * 执行一个微步
 * direction: 1=正转, -1=反转
 */
static void Stepper_Step(int8_t direction)
{
    uint16_t ia, ib;
    uint16_t duty_a, duty_b;

    if (!motor.enabled) {
        printf("[STEP] Motor not enabled, skip\n");
        return;
    }

    /* 更新步索引 */
    if (direction > 0) {
        motor.step_index = (uint8_t)((motor.step_index + 1) % MICROSTEP);
        motor.position++;
    } else {
        motor.step_index = (uint8_t)((motor.step_index + MICROSTEP - 1) % MICROSTEP);
        motor.position--;
    }

    /* 计算目标相电流 */
    Stepper_CalcPhaseCurrent(motor.step_index, &ia, &ib);
    motor.current_a = ia;
    motor.current_b = ib;

    /* 读取实测电流 (Mock) */
    motor.current_a_meas = HAL_ReadCurrent_A();
    motor.current_b_meas = HAL_ReadCurrent_B();

    /* 电流闭环控制 */
    duty_a = Stepper_CurrentControl(motor.current_a, motor.current_a_meas);
    duty_b = Stepper_CurrentControl(motor.current_b, motor.current_b_meas);

    /* 输出 PWM */
    HAL_SetPWM_A(duty_a);
    HAL_SetPWM_B(duty_b);

    printf("[STEP] idx=%2u pos=%4d | "
           "Ia_tgt=%4u Ia_meas=%4u dutyA=%4u | "
           "Ib_tgt=%4u Ib_meas=%4u dutyB=%4u\n",
           (unsigned)motor.step_index, (int)motor.position,
           (unsigned)motor.current_a, (unsigned)motor.current_a_meas, (unsigned)duty_a,
           (unsigned)motor.current_b, (unsigned)motor.current_b_meas, (unsigned)duty_b);
}

/* 初始化步进电机 */
static void Stepper_Init(void)
{
    motor.step_index = 0;
    motor.position = 0;
    motor.current_a = 0;
    motor.current_b = 0;
    motor.current_a_meas = 0;
    motor.current_b_meas = 0;
    motor.enabled = 0;

