    printf("[INIT] Stepper motor initialized, microstep=%u, "
           "step_angle=%.2f deg\n",
           (unsigned)MICROSTEP, (double)MICROSTEP_ANGLE);
}

/* 使能步进电机 */
static void Stepper_Enable(void)
{
    motor.enabled = 1;
    HAL_EnableDriver(1);
}

/* 禁用步进电机 */
static void Stepper_Disable(void)
{
    motor.enabled = 0;
    HAL_SetPWM_A(0);
    HAL_SetPWM_B(0);
    HAL_EnableDriver(0);
}

/* ========== 主函数 ========== */
int main(void)
{
    int i;

    printf("========================================\n");
    printf("  Stepper Motor Microstep Driver (16x)\n");
    printf("  Current Control Algorithm Demo\n");
    printf("========================================\n\n");

    /* 初始化 */
    Stepper_Init();

    /* 使能电机 */
    Stepper_Enable();
    printf("\n");

    /* 正转 16 个微步 (一个完整电气周期) */
    printf("--- Forward 16 microsteps ---\n");
