#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ========== 模拟硬件寄存器与宏定义 ========== */
#define MOCK_REG32(addr) (*(volatile uint32_t *)(addr))

/* 模拟编码器位置寄存器 */
#define ENCODER_POS_REG     MOCK_REG32(0x40000000)
/* 模拟PWM输出寄存器 */
#define PWM_OUTPUT_REG      MOCK_REG32(0x40000004)
/* 模拟定时器计数寄存器 */
#define TIMER_COUNT_REG     MOCK_REG32(0x40000008)

/* 编码器分辨率 (脉冲/圈) */
#define ENCODER_RESOLUTION  4096.0f
/* PWM 最大占空比计数值 */
#define PWM_MAX_VALUE       10000
/* 控制周期 (秒) */
#define CONTROL_PERIOD      0.001f

/* ========== PID + 前馈 控制器结构体 ========== */
typedef struct {
    /* PID 参数 */
    float Kp;               /* 比例增益 */
    float Ki;               /* 积分增益 */
    float Kd;               /* 微分增益 */

    /* 前馈参数 */
    float Kff_vel;          /* 速度前馈增益 */
    float Kff_acc;          /* 加速度前馈增益 */

    /* 内部状态 */
    float integral;         /* 积分累加项 */
    float prev_error;       /* 上一次误差 */
    float prev_prev_error;  /* 上上次误差 (用于微分滤波) */
    float prev_velocity;    /* 上一次速度 (用于加速度前馈) */
    float prev_target;      /* 上一次目标位置 (用于计算目标速度) */

    /* 输出限幅 */
    float out_max;
    float out_min;

    /* 微分低通滤波系数 (0~1, 越小滤波越强) */
    float d_filter_alpha;
    float d_filtered;       /* 滤波后的微分项 */
} ServoController;

/* ========== 控制器初始化 ========== */
void ServoController_Init(ServoController *ctrl)
{
    ctrl->Kp = 12.0f;
    ctrl->Ki = 0.5f;
    ctrl->Kd = 0.8f;

    ctrl->Kff_vel = 0.02f;
    ctrl->Kff_acc = 0.001f;

    ctrl->integral = 0.0f;
    ctrl->prev_error = 0.0f;
    ctrl->prev_prev_error = 0.0f;
    ctrl->prev_velocity = 0.0f;
    ctrl->prev_target = 0.0f;

    ctrl->out_max = (float)PWM_MAX_VALUE;
    ctrl->out_min = -(float)PWM_MAX_VALUE;

    ctrl->d_filter_alpha = 0.3f;
    ctrl->d_filtered = 0.0f;
}

/* ========== 限幅辅助函数 ========== */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

/* ========== 位置闭环控制核心算法 ==========
 * 输入:
 *   ctrl          - 控制器实例
 *   target_pos    - 目标位置 (编码器脉冲数)
 *   actual_pos    - 实际位置 (编码器脉冲数)
 *   dt            - 控制周期 (秒)
 * 输出:
 *   PWM 占空比计数值 (带符号, 正负代表方向)
 */
float ServoController_Update(ServoController *ctrl,
                             float target_pos,
                             float actual_pos,
                             float dt)
{
    float error;
    float p_term, i_term, d_term;
    float ff_term;
    float target_velocity, target_acceleration;
    float output;

    /* 1. 计算位置误差 */
    error = target_pos - actual_pos;

    /* 2. 比例项 */
    p_term = ctrl->Kp * error;

    /* 3. 积分项 (带抗饱和) */
    ctrl->integral += error * dt;
    /* 积分限幅, 防止积分饱和 */
    ctrl->integral = clampf(ctrl->integral,
                            ctrl->out_min / (ctrl->Ki + 1e-6f),
                            ctrl->out_max / (ctrl->Ki + 1e-6f));
    i_term = ctrl->Ki * ctrl->integral;

    /* 4. 微分项 (对误差微分, 带低通滤波) */
    {
        float d_raw = (error - ctrl->prev_error) / dt;
        ctrl->d_filtered = ctrl->d_filter_alpha * d_raw
                         + (1.0f - ctrl->d_filter_alpha) * ctrl->d_filtered;
        d_term = ctrl->Kd * ctrl->d_filtered;
    }

    /* 5. 前馈项 */
    /* 目标速度 = (当前目标 - 上次目标) / dt */
    target_velocity = (target_pos - ctrl->prev_target) / dt;
    /* 目标加速度 = (当前目标速度 - 上次目标速度) / dt */
    target_acceleration = (target_velocity - ctrl->prev_velocity) / dt;

    ff_term = ctrl->Kff_vel * target_velocity
            + ctrl->Kff_acc * target_acceleration;

    /* 6. 总输出 = PID + 前馈 */
    output = p_term + i_term + d_term + ff_term;

    /* 7. 输出限幅 */
    output = clampf(output, ctrl->out_min, ctrl->out_max);

    /* 8. 更新历史状态 */
    ctrl->prev_prev_error = ctrl->prev_error;
    ctrl->prev_error = error;
    ctrl->prev_velocity = target_velocity;
    ctrl->prev_target = target_pos;

    return output;
}

/* ========== 模拟电机与编码器 ========== */
typedef struct {
    float position;         /* 当前实际位置 (脉冲) */
    float velocity;         /* 当前速度 (脉冲/秒) */
    float inertia;          /* 转动惯量 (简化模型) */
    float damping;          /* 阻尼系数 */
} MockMotor;

void MockMotor_Init(MockMotor *motor)
{
    motor->position = 0.0f;
    motor->velocity = 0.0f;
    motor->inertia = 0.01f;
    motor->damping = 0.5f;
}

/* 用 PWM 输出驱动模拟电机 */
void MockMotor_Step(MockMotor *motor, float pwm_output, float dt)
{
    /* 将 PWM 输出转换为力矩 (简化线性模型) */
    float torque = pwm_output / (float)PWM_MAX_VALUE * 10.0f;
    /* 力矩 = 惯量 * 角加速度 + 阻尼 * 角速度 */
    float acceleration = (torque - motor->damping * motor->velocity) / motor->inertia;
    motor->velocity += acceleration * dt;
    motor->position += motor->velocity * dt;
}

/* ========== 主函数 ========== */
int main(void)
{
    ServoController ctrl;
    MockMotor motor;

    float target_pos;
    float actual_pos;
    float pwm_output;
    int i;

    printf("===== Servo Motor Position Closed-Loop Control (PID + Feedforward) =====\n\n");

    /* 初始化 */
    ServoController_Init(&ctrl);
    MockMotor_Init(&motor);

    /* 打印控制器参数 */
    printf("Controller Parameters:\n");
    printf("  Kp = %.3f, Ki = %.3f, Kd = %.3f\n", ctrl.Kp, ctrl.Ki, ctrl.Kd);
    printf("  Kff_vel = %.4f, Kff_acc = %.5f\n", ctrl.Kff_vel, ctrl.Kff_acc);
    printf("  Output Limit: [%.0f, %.0f]\n", ctrl.out_min, ctrl.out_max);
    printf("  Control Period: %.1f ms\n\n", CONTROL_PERIOD * 1000.0f);

