/* ==================== 模拟硬件寄存器（使用普通变量，避免非法地址访问） ==================== */
static int32_t  mock_encoder_pos    = 0;
static int32_t  mock_pwm_output     = 0;
static uint32_t mock_control_enable = 0;

#define MOCK_REG_ENCODER_POS    (mock_encoder_pos)
#define MOCK_REG_PWM_OUTPUT     (mock_pwm_output)
#define MOCK_REG_CONTROL_ENABLE (mock_control_enable)

/* ==================== 伺服控制参数结构体 ==================== */
typedef struct {
    /* PID 参数 */
    float kp;
    float ki;
    float kd;

    /* 前馈参数 */
    float kvff;
    float kaff;

    /* 限幅 */
    float out_max;
    float out_min;
    float integral_max;

    /* 状态变量 */
    float integral;
    float prev_error;
    float prev_prev_error;
    float prev_velocity;
} ServoController;

/* ==================== 控制器初始化 ==================== */
void servo_init(ServoController *ctrl)
{
    if (ctrl == NULL) return;

    ctrl->kp = 12.0f;
    ctrl->ki = 0.5f;
    ctrl->kd = 0.8f;

    ctrl->kvff = 0.9f;
    ctrl->kaff = 0.05f;

    ctrl->out_max = 1000.0f;
    ctrl->out_min = -1000.0f;
    ctrl->integral_max = 500.0f;

    ctrl->integral = 0.0f;
    ctrl->prev_error = 0.0f;
    ctrl->prev_prev_error = 0.0f;
    ctrl->prev_velocity = 0.0f;
}

/* ==================== 限幅辅助函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

/* ==================== 位置闭环控制核心算法 ==================== */
float servo_position_control(ServoController *ctrl,
                             float target_pos,
                             float actual_pos,
                             float target_vel,
                             float target_acc,
                             float dt)
{
    float error;
    float derivative;
    float feedforward;
    float output;

    if (ctrl == NULL) return 0.0f;

    /* 1. 计算位置误差 */
    error = target_pos - actual_pos;

    /* 2. 积分项（带限幅） */
    ctrl->integral += error * dt;
    ctrl->integral = clampf(ctrl->integral, -ctrl->integral_max, ctrl->integral_max);

    /* 3. 微分项（对误差微分，使用后向差分） */
    if (dt > 1e-9f) {
        derivative = (error - ctrl->prev_error) / dt;
    } else {
        derivative = 0.0f;
    }

    /* 4. 前馈项：速度前馈 + 加速度前馈 */
    feedforward = ctrl->kvff * target_vel + ctrl->kaff * target_acc;

    /* 5. PID + 前馈 合成输出 */
    output = ctrl->kp * error
           + ctrl->ki * ctrl->integral
           + ctrl->kd * derivative
           + feedforward;

    /* 6. 输出限幅 */
    output = clampf(output, ctrl->out_min, ctrl->out_max);

    /* 7. 更新历史状态 */
    ctrl->prev_prev_error = ctrl->prev_error;
    ctrl->prev_error = error;
    ctrl->prev_velocity = target_vel;

    return output;
}

/* ==================== 模拟编码器读取 ==================== */
static int32_t mock_read_encoder(void)
{
    return MOCK_REG_ENCODER_POS;
}

/* ==================== 模拟 PWM 输出 ==================== */
static void mock_write_pwm(float duty)
{
    MOCK_REG_PWM_OUTPUT = (int32_t)duty;
}

/* ==================== 主函数 ==================== */
int main(void)
{
    ServoController ctrl;
    float target_pos;
    float target_vel;
    float target_acc;
    float actual_pos;
    float pwm_out;
    float dt = 0.001f;   /* 1ms 控制周期 */
    int i;

    printf("===== Servo Position Loop Control (PID + Feedforward) =====\n\n");

    /* 初始化控制器 */
    servo_init(&ctrl);

    /* 使能控制 */
    MOCK_REG_CONTROL_ENABLE = 1;

    /* 设定目标轨迹 */
    target_pos = 0.0f;
    target_vel = 0.0f;
    target_acc = 0.0f;

    printf("Step | TargetPos | ActualPos | Error | PWM_Out\n");
    printf("-----+-----------+-----------+-------+---------\n");

    for (i = 0; i < 20; i++) {
        /* 模拟目标轨迹：前 10 步加速，后 10 步匀速 */
        if (i < 10) {
            target_vel = 100.0f;
            target_acc = 10.0f;
        } else {
            target_vel = 100.0f;
            target_acc = 0.0f;
        }
        target_pos += target_vel * dt;

        /* 读取编码器反馈 */
        actual_pos = (float)mock_read_encoder();

        /* 执行位置闭环控制 */
        pwm_out = servo_position_control(&ctrl,
                                         target_pos,
                                         actual_pos,
                                         target_vel,
                                         target_acc,
                                         dt);

        /* 输出 PWM */
        mock_write_pwm(pwm_out);

        /* 模拟电机响应：简单一阶惯性 + 积分 */
        MOCK_REG_ENCODER_POS += (int32_t)(pwm_out * 0.01f);

        /* 打印调试信息 */
        printf("%4d | %9.2f | %9.2f | %5.2f | %7.2f\n",
               i,
               target_pos,
               actual_pos,
               target_pos - actual_pos,
               pwm_out);
    }

    printf("\n===== Control Loop Finished =====\n");
    return 0;
}
