#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile uint32_t mock_timer_cr;
static volatile uint32_t mock_timer_sr;
static volatile uint32_t mock_timer_cnt;
static volatile uint32_t mock_timer_arr;

