static volatile uint32_t mock_pwm_ccr;
static volatile uint32_t mock_pwm_arr;

static volatile uint32_t mock_gpio_odr;
static volatile uint32_t mock_gpio_idr;

#define TIMER_CR        (mock_timer_cr)
#define TIMER_SR        (mock_timer_sr)
#define TIMER_CNT       (mock_timer_cnt)
#define TIMER_ARR       (mock_timer_arr)

#define ADC_CR          (mock_adc_cr)
#define ADC_DR          (mock_adc_dr)
#define ADC_SR          (mock_adc_sr)

#define PWM_CR          (mock_pwm_cr)
#define PWM_CCR         (mock_pwm_ccr)
#define PWM_ARR         (mock_pwm_arr)

#define GPIO_ODR        (mock_gpio_odr)
#define GPIO_IDR        (mock_gpio_idr)

/* 位定义 */
#define TIMER_CR_EN     (1U << 0)
#define TIMER_SR_UIF    (1U << 0)
#define ADC_CR_ADON     (1U << 0)
#define ADC_CR_SWSTART  (1U << 1)
#define ADC_SR_EOC      (1U << 0)
#define PWM_CR_EN       (1U << 0)
#define GPIO_PIN_0      (1U << 0)

/* ================= 系统参数 ================= */
#define PWM_FREQ_HZ          20000U
#define PWM_PERIOD_TICKS     1000U
#define ADC_REF_VOLTAGE      3.3f
#define ADC_RESOLUTION       4096.0f
#define BUS_VOLTAGE_MAX      450.0f
#define BUS_VOLTAGE_MIN      200.0f
#define BATTERY_VOLTAGE      48.0f
#define INDUCTOR_CURRENT_MAX 30.0f
#define VOLTAGE_LOOP_KP      0.5f
#define VOLTAGE_LOOP_KI      0.01f
#define CURRENT_LOOP_KP      0.3f
#define CURRENT_LOOP_KI      0.005f
#define DEAD_TIME_NS         500U

/* ================= 数据结构 ================= */
typedef struct {
    float bus_voltage;
    float battery_voltage;
    float inductor_current;
    float duty_cycle;
    float voltage_ref;
    float voltage_error;
    float voltage_integral;
    float current_ref;
    float current_error;
    float current_integral;
    uint8_t direction;
    uint8_t fault;
} EnergyFeedback_t;

/* ================= 全局变量 ================= */
static EnergyFeedback_t g_ef;
static uint32_t g_pwm_duty = 0;

/* ================= 函数声明 ================= */
static void System_Init(void);
static void ADC_ReadValues(void);
static float ADC_ToVoltage(uint32_t adc_val);
static float ADC_ToCurrent(uint32_t adc_val);
static void Voltage_Loop(void);
static void Current_Loop(void);
static void PWM_Update(float duty);
static void Protection_Check(void);
static void Delay_ms(uint32_t ms);

/* ================= 系统初始化 ================= */
static void System_Init(void)
{
    TIMER_ARR = PWM_PERIOD_TICKS - 1U;
    TIMER_CR |= TIMER_CR_EN;

    ADC_CR |= ADC_CR_ADON;

    PWM_ARR = PWM_PERIOD_TICKS - 1U;
    PWM_CCR = 0U;
    PWM_CR |= PWM_CR_EN;

    g_ef.bus_voltage = 0.0f;
    g_ef.battery_voltage = BATTERY_VOLTAGE;
    g_ef.inductor_current = 0.0f;
    g_ef.duty_cycle = 0.0f;
    g_ef.voltage_ref = 380.0f;
    g_ef.voltage_error = 0.0f;
    g_ef.voltage_integral = 0.0f;
    g_ef.current_ref = 0.0f;
    g_ef.current_error = 0.0f;
    g_ef.current_integral = 0.0f;
    g_ef.direction = 0U;
    g_ef.fault = 0U;

    printf("[INIT] System initialized. PWM Freq=%uHz, Period=%u ticks\n",
           PWM_FREQ_HZ, PWM_PERIOD_TICKS);
}

/* ================= ADC 采样 ================= */
static void ADC_ReadValues(void)
{
    uint32_t adc_bus, adc_curr;

    /* 模拟母线电压采样: 380V -> ADC 值约 471 (380/100/3.3*4096) */
    adc_bus = 471U;
    g_ef.bus_voltage = ADC_ToVoltage(adc_bus);

    /* 模拟电感电流采样: 5A -> ADC 值约 3300 */
    adc_curr = 3300U;
    g_ef.inductor_current = ADC_ToCurrent(adc_curr);

    /* 更新 ADC 寄存器 mock 值 */
    ADC_DR = adc_bus;
    ADC_SR |= ADC_SR_EOC;
}

static float ADC_ToVoltage(uint32_t adc_val)
{
    float adc_voltage = ((float)adc_val / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    return adc_voltage * 100.0f;
}

static float ADC_ToCurrent(uint32_t adc_val)
{
    float adc_voltage = ((float)adc_val / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    return (adc_voltage - 2.5f) / 0.04f;
}

/* ================= 电压外环 ================= */
static void Voltage_Loop(void)
{
    float output;

    g_ef.voltage_error = g_ef.voltage_ref - g_ef.bus_voltage;

    g_ef.voltage_integral += g_ef.voltage_error * VOLTAGE_LOOP_KI;

    if (g_ef.voltage_integral > INDUCTOR_CURRENT_MAX) {
        g_ef.voltage_integral = INDUCTOR_CURRENT_MAX;
    } else if (g_ef.voltage_integral < -INDUCTOR_CURRENT_MAX) {
        g_ef.voltage_integral = -INDUCTOR_CURRENT_MAX;
    }

    output = (g_ef.voltage_error * VOLTAGE_LOOP_KP) + g_ef.voltage_integral;

    if (output > INDUCTOR_CURRENT_MAX) {
        output = INDUCTOR_CURRENT_MAX;
    } else if (output < -INDUCTOR_CURRENT_MAX) {
        output = -INDUCTOR_CURRENT_MAX;
    }

    g_ef.current_ref = output;

    if (g_ef.current_ref >= 0.0f) {
        g_ef.direction = 1U;
    } else {
        g_ef.direction = 0U;
    }
}

/* ================= 电流内环 ================= */
static void Current_Loop(void)
{
    float output;

    g_ef.current_error = g_ef.current_ref - g_ef.inductor_current;

    g_ef.current_integral += g_ef.current_error * CURRENT_LOOP_KI;

    if (g_ef.current_integral > 1.0f) {
        g_ef.current_integral = 1.0f;
    } else if (g_ef.current_integral < 0.0f) {
        g_ef.current_integral = 0.0f;
    }

    output = (g_ef.current_error * CURRENT_LOOP_KP) + g_ef.current_integral;

    if (output > 0.95f) {
        output = 0.95f;
    } else if (output < 0.05f) {
        output = 0.05f;
    }

    g_ef.duty_cycle = output;
}

/* ================= PWM 更新 ================= */
static void PWM_Update(float duty)
{
    uint32_t ccr;

    if (duty > 1.0f) {
        duty = 1.0f;
    } else if (duty < 0.0f) {
        duty = 0.0f;
    }

    ccr = (uint32_t)(duty * (float)PWM_PERIOD_TICKS);
    if (ccr >= PWM_PERIOD_TICKS) {
        ccr = PWM_PERIOD_TICKS - 1U;
    }

    g_pwm_duty = ccr;
    PWM_CCR = ccr;
}

/* ================= 保护检测 ================= */
static void Protection_Check(void)
{
    if (g_ef.bus_voltage > BUS_VOLTAGE_MAX) {
        g_ef.fault |= 0x01U;
        PWM_CCR = 0U;
        printf("[FAULT] Bus over-voltage: %.1fV\n", g_ef.bus_voltage);
    }

    if (g_ef.bus_voltage < BUS_VOLTAGE_MIN && g_ef.bus_voltage > 1.0f) {
        g_ef.fault |= 0x02U;
        PWM_CCR = 0U;
        printf("[FAULT] Bus under-voltage: %.1fV\n", g_ef.bus_voltage);
    }

    if (fabsf(g_ef.inductor_current) > INDUCTOR_CURRENT_MAX) {
        g_ef.fault |= 0x04U;
        PWM_CCR = 0U;
        printf("[FAULT] Over-current: %.1fA\n", g_ef.inductor_current);
    }

    if (g_ef.fault != 0U) {
        if (g_ef.bus_voltage < BUS_VOLTAGE_MAX &&
            g_ef.bus_voltage > BUS_VOLTAGE_MIN &&
            fabsf(g_ef.inductor_current) < INDUCTOR_CURRENT_MAX) {
            g_ef.fault = 0U;
            printf("[INFO] Fault cleared, resuming operation\n");
        }
    }
}

/* ================= 延时函数 (mock) ================= */
static void Delay_ms(uint32_t ms)
{
    volatile uint32_t i, j;
    for (i = 0U; i < ms; i++) {
        for (j = 0U; j < 1000U; j++) {
            /* 空循环模拟延时 */
        }
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    uint32_t loop_count = 0U;

    printf("========================================\n");
    printf("  Elevator Energy Feedback DC/DC Control\n");
    printf("========================================\n");

    System_Init();

    for (loop_count = 0U; loop_count < 10U; loop_count++) {
        ADC_ReadValues();

        Protection_Check();

        if (g_ef.fault == 0U) {
            Voltage_Loop();
            Current_Loop();
            PWM_Update(g_ef.duty_cycle);
        }

        printf("[LOOP %02u] Vbus=%.1fV Iind=%.2fA Duty=%.3f Dir=%s Fault=0x%02X\n",
               loop_count,
               g_ef.bus_voltage,
               g_ef.inductor_current,
               g_ef.duty_cycle,
               (g_ef.direction == 1U) ? "FEEDBACK" : "CHARGE",
               g_ef.fault);

        Delay_ms(1U);
    }

    printf("========================================\n");
    printf("  Control loop finished.\n");
    printf("========================================\n");

    return 0;
}
