```c
#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致崩溃 */
static volatile uint16_t g_adc_data_reg      = 0;
static volatile uint16_t g_pwm_duty_reg      = 0;
static volatile uint8_t  g_pwm_enable_reg    = 0;
static volatile uint16_t g_bus_voltage_reg   = 0;
static volatile uint16_t g_bat_voltage_reg   = 0;
static volatile int16_t  g_current_reg       = 0;

#define ADC_DATA_REG        (g_adc_data_reg)
#define PWM_DUTY_REG        (g_pwm_duty_reg)
#define PWM_ENABLE_REG      (g_pwm_enable_reg)
#define BUS_VOLTAGE_REG     (g_bus_voltage_reg)
#define BAT_VOLTAGE_REG     (g_bat_voltage_reg)
#define CURRENT_REG         (g_current_reg)

/* ==================== 系统参数定义 ==================== */
#define PWM_PERIOD          1000U
#define PWM_MAX_DUTY        950U
#define PWM_MIN_DUTY        50U
#define ADC_REF_VOLTAGE     3.3f
#define ADC_RESOLUTION      4095.0f
#define VOLTAGE_DIVIDER     11.0f
#define CURRENT_SENSOR      0.01f
#define BUS_VOLTAGE_TARGET  400.0f
#define BAT_VOLTAGE_MIN     200.0f
#define BAT_VOLTAGE_MAX     420.0f
#define CURRENT_LIMIT       10.0f

/* ==================== 控制状态枚举 ==================== */
typedef enum {
    STATE_IDLE = 0,
    STATE_CHARGE,
    STATE_DISCHARGE,
    STATE_FAULT
} SystemState_t;

/* ==================== 控制器结构体 ==================== */
typedef struct {
    float bus_voltage;
    float bat_voltage;
    float current;
    float duty;
    float duty_step;
    float voltage_error;
    float voltage_error_prev;
    float integral;
    float kp;
    float ki;
    float kd;
    SystemState_t state;
    uint32_t fault_count;
} Controller_t;

/* ==================== 全局控制器实例 ==================== */
static Controller_t g_ctrl;

/* ==================== 函数声明 ==================== */
static void System_Init(void);
static void Read_Sensors(Controller_t *ctrl);
static void Control_Loop(Controller_t *ctrl);
static void Update_PWM(float duty);
static void Fault_Handler(Controller_t *ctrl);
static float Clamp(float value, float min, float max);

/* ==================== 系统初始化 ==================== */
static void System_Init(void)
{
    g_ctrl.bus_voltage = 0.0f;
    g_ctrl.bat_voltage = 0.0f;
    g_ctrl.current = 0.0f;
    g_ctrl.duty = 0.5f;
    g_ctrl.duty_step = 0.001f;
    g_ctrl.voltage_error = 0.0f;
    g_ctrl.voltage_error_prev = 0.0f;
    g_ctrl.integral = 0.0f;
    g_ctrl.kp = 0.02f;
    g_ctrl.ki = 0.005f;
    g_ctrl.kd = 0.001f;
    g_ctrl.state = STATE_IDLE;
    g_ctrl.fault_count = 0;

    PWM_ENABLE_REG = 0;
    PWM_DUTY_REG = (uint16_t)(g_ctrl.duty * PWM_PERIOD);

    printf("[INIT] Elevator Energy Feedback DC/DC Controller Initialized.\n");
    printf("[INIT] Target Bus Voltage: %.1f V, Current Limit: %.1f A\n",
           BUS_VOLTAGE_TARGET, CURRENT_LIMIT);
}

/* ==================== 读取传感器数据 ==================== */
static void Read_Sensors(Controller_t *ctrl)
{
    uint16_t adc_bus = BUS_VOLTAGE_REG;
    uint16_t adc_bat = BAT_VOLTAGE_REG;
    int16_t adc_cur = CURRENT_REG;

    ctrl->bus_voltage = ((float)adc_bus / ADC_RESOLUTION) * ADC_REF_VOLTAGE * VOLTAGE_DIVIDER;
    ctrl->bat_voltage = ((float)adc_bat / ADC_RESOLUTION) * ADC_REF_VOLTAGE * VOLTAGE_DIVIDER;
    ctrl->current = ((float)adc_cur / ADC_RESOLUTION) * ADC_REF_VOLTAGE / CURRENT_SENSOR;
}

/* ==================== 限幅函数 ==================== */
static float Clamp(float value, float min, float max)
{
    if (value > max) return max;
    if (value < min) return min;
    return value;
}

/* ==================== 更新 PWM 输出 ==================== */
static void Update_PWM(float duty)
{
    uint16_t pwm_val;

    duty = Clamp(duty, 0.0f, 1.0f);
    pwm_val = (uint16_t)(duty * PWM_PERIOD);

    if (pwm_val > PWM_MAX_DUTY) pwm_val = PWM_MAX_DUTY;
    if (pwm_val < PWM_MIN_DUTY) pwm_val = PWM_MIN_DUTY;

    PWM_DUTY_REG = pwm_val;
    PWM_ENABLE_REG = 1;
}

/* ==================== 故障处理 ==================== */
static void Fault_Handler(Controller_t *ctrl)
{
    ctrl->fault_count++;
    ctrl->state = STATE_FAULT;
    PWM_ENABLE_REG = 0;
    PWM_DUTY_REG = 0;

    printf("[FAULT] Fault detected! Count: %lu\n", (unsigned long)ctrl->fault_count);
    printf("[FAULT] Bus: %.1f V, Bat: %.1f V, Cur: %.2f A\n",
           ctrl->bus_voltage, ctrl->bat_voltage, ctrl->current);
}

/* ==================== 核心控制循环 ==================== */
static void Control_Loop(Controller_t *ctrl)
{
    float p_term, i_term, d_term, output;

    /* 安全检查 */
    if (ctrl->bus_voltage > 500.0f || ctrl->bat_voltage > 500.0f ||
        fabsf(ctrl->current) > CURRENT_LIMIT * 1.5f) {
        Fault_Handler(ctrl);
        return;
    }

    switch (ctrl->state) {
        case STATE_IDLE:
            if (ctrl->bat_voltage > BAT_VOLTAGE_MIN &&
                ctrl->bus_voltage < BUS_VOLTAGE_TARGET) {
                ctrl->state = STATE_CHARGE;
                printf("[STATE] -> CHARGE (Bat: %.1f V, Bus: %.1f V)\n",
                       ctrl->bat_voltage, ctrl->bus_voltage);
            } else if (ctrl->bat_voltage < BAT_VOLTAGE_MAX &&
                       ctrl->bus_voltage > BUS_VOLTAGE_TARGET) {
                ctrl->state = STATE_DISCHARGE;
                printf("[STATE] -> DISCHARGE (Bat: %.1f V, Bus: %.1f V)\n",
                       ctrl->bat_voltage, ctrl->bus_voltage);
            }
            break;

        case STATE_CHARGE:
            ctrl->voltage_error = BUS_VOLTAGE_TARGET - ctrl->bus_voltage;

            p_term = ctrl->kp * ctrl->voltage_error;
            ctrl->integral += ctrl->ki * ctrl->voltage_error;
            ctrl->integral = Clamp(ctrl->integral, -0.5f, 0.5f);
            i_term = ctrl->integral;
            d_term = ctrl->kd * (ctrl->voltage_error - ctrl->voltage_error_prev);

            output = p_term + i_term + d_term;
            ctrl->duty = Clamp(ctrl->duty + output * ctrl->duty_step, 0.05f, 0.95f);

            ctrl->voltage_error_prev = ctrl->voltage_error;

            if (fabsf(ctrl->current) > CURRENT_LIMIT) {
                ctrl->duty = Clamp(ctrl->duty - 0.01f, 0.05f, 0.95f);
            }

            Update_PWM(ctrl->duty);

            printf("[CHARGE] Bus: %.1f V, Bat: %.1f V, Cur: %.2f A, Duty: %.3f\n",
                   ctrl->bus_voltage, ctrl->bat_voltage, ctrl->current, ctrl->duty);

            if (ctrl->bus_voltage >= BUS_VOLTAGE_TARGET * 1.05f ||
                ctrl->bat_voltage < BAT_VOLTAGE_MIN) {
                ctrl->state = STATE_IDLE;
                ctrl->integral = 0.0f;
                PWM_ENABLE_REG = 0;
                printf("[STATE] -> IDLE (Charge complete)\n");
            }
            break;

        case STATE_DISCHARGE:
            ctrl->voltage_error = ctrl->bus_voltage - BUS_VOLTAGE_TARGET;

            p_term = ctrl->kp * ctrl->voltage_error;
            ctrl->integral += ctrl->ki * ctrl->voltage_error;
            ctrl->integral = Clamp(ctrl->integral, -0.5f, 0.5f);
            i_term = ctrl->integral;
            d_term = ctrl->kd * (ctrl->voltage_error - ctrl->voltage_error_prev);

            output = p_term + i_term + d_term;
            ctrl->duty = Clamp(ctrl->duty + output * ctrl->duty_step, 0.05f, 0.95f);

            ctrl->voltage_error_prev = ctrl->voltage_error;

            if (fabsf(ctrl->current) > CURRENT_LIMIT) {
                ctrl->duty = Clamp(ctrl->duty - 0.01f, 0.05f, 0.95f);
            }

            Update_PWM(ctrl->duty);

            printf("[DISCHARGE] Bus: %.1f V, Bat: %.1f V, Cur: %.2f A, Duty: %.3f\n",
                   ctrl->bus_voltage, ctrl->bat_voltage, ctrl->current, ctrl->duty);

            if (ctrl->bus_voltage <= BUS_VOLTAGE_TARGET * 0.95f ||
                ctrl->bat_voltage > BAT_VOLTAGE_MAX) {
                ctrl->state = STATE_IDLE;
                ctrl->integral = 0.0f;
                PWM_ENABLE_REG = 0;
                printf("[STATE] -> IDLE (Discharge complete)\n");
            }
            break;

        case STATE_FAULT:
            PWM_ENABLE_REG = 0;
            PWM_DUTY_REG = 0;
            printf("[FAULT] System in fault state, waiting for reset...\n");
            break;

        default:
            ctrl->state = STATE_IDLE;
            break;
    }
}

