/* 系统状态位定义 */
#define STATUS_INV_READY         (1U << 0)
#define STATUS_BYPASS_READY      (1U << 1)
#define STATUS_FAULT             (1U << 2)
#define STATUS_SYNC_DONE         (1U << 3)

/* 旁路切换状态机 */
typedef enum {
    BYPASS_STATE_IDLE = 0,
    BYPASS_STATE_SYNC_PHASE,
    BYPASS_STATE_ZERO_CROSS_WAIT,
    BYPASS_STATE_SWITCH_OVER,
    BYPASS_STATE_INV_MODE,
    BYPASS_STATE_BYPASS_MODE,
    BYPASS_STATE_FAULT
} BypassState_t;

/* 控制参数 */
#define ADC_VREF_MV              3300U
#define ADC_FULL_SCALE           4095U
#define ZERO_CROSS_THRESHOLD_MV  50U
#define SYNC_PHASE_TOLERANCE_DEG 5.0f
#define SWITCH_DELAY_US          100U
#define INV_NOMINAL_FREQ_HZ      50.0f
#define PI                       3.14159265358979323846f

/* 全局变量 */
static BypassState_t g_bypass_state = BYPASS_STATE_IDLE;
static float g_inv_voltage_mv = 0.0f;
static float g_bypass_voltage_mv = 0.0f;
static float g_load_current_ma = 0.0f;
static float g_phase_diff_deg = 0.0f;
static uint32_t g_zero_cross_counter = 0;
static bool g_inv_ready = false;
static bool g_bypass_ready = false;
static bool g_sync_done = false;

/* ================= 工具函数 ================= */
static float adc_to_mv(uint16_t adc_val)
{
    return ((float)adc_val * (float)ADC_VREF_MV) / (float)ADC_FULL_SCALE;
}

static float adc_to_current_ma(uint16_t adc_val)
{
    return adc_to_mv(adc_val);
}

static float calc_phase_diff_deg(float v_inv, float v_bypass)
{
    float ratio;
    if (fabsf(v_inv) < 1.0f || fabsf(v_bypass) < 1.0f) {
        return 0.0f;
    }
    ratio = v_inv / v_bypass;
    if (ratio > 1.0f) ratio = 1.0f;
    if (ratio < -1.0f) ratio = -1.0f;
    return acosf(ratio) * 180.0f / PI;
}

static bool is_zero_crossing(float voltage_mv)
{
    return (fabsf(voltage_mv) < (float)ZERO_CROSS_THRESHOLD_MV);
}

static void delay_us(uint32_t us)
{
