    g_bypass_voltage_mv = adc_to_mv(REG_ADC_BYPASS_VOLTAGE);
    g_load_current_ma = adc_to_current_ma(REG_ADC_LOAD_CURRENT);
}

static void hw_update_status(void)
{
    uint16_t status = 0;
    if (g_inv_ready) status |= STATUS_INV_READY;
    if (g_bypass_ready) status |= STATUS_BYPASS_READY;
    if (g_sync_done) status |= STATUS_SYNC_DONE;
    REG_SYSTEM_STATUS = status;
}

/* ================= 旁路切换控制核心 ================= */
static void bypass_switch_init(void)
{
    g_bypass_state = BYPASS_STATE_IDLE;
    g_inv_ready = false;
    g_bypass_ready = false;
    g_sync_done = false;
    g_zero_cross_counter = 0;
    hw_set_inv_pwm(false, 0);
    hw_set_bypass_pwm(false);
    hw_set_relay(false);
    hw_update_status();
    printf("[INIT] Bypass switch controller initialized.\n");
}

static void bypass_switch_step(void)
{
    hw_read_adc();

    switch (g_bypass_state) {
    case BYPASS_STATE_IDLE:
        printf("[IDLE] Checking readiness...\n");
        if (g_inv_ready && g_bypass_ready) {
            g_bypass_state = BYPASS_STATE_SYNC_PHASE;
            printf("[IDLE] Both sources ready, entering sync phase.\n");
        }
        break;

    case BYPASS_STATE_SYNC_PHASE:
        g_phase_diff_deg = calc_phase_diff_deg(g_inv_voltage_mv, g_bypass_voltage_mv);
        printf("[SYNC] Inv=%.1fmV Bypass=%.1fmV PhaseDiff=%.2fdeg\n",
               g_inv_voltage_mv, g_bypass_voltage_mv, g_phase_diff_deg);
        if (g_phase_diff_deg < SYNC_PHASE_TOLERANCE_DEG) {
            g_sync_done = true;
            g_bypass_state = BYPASS_STATE_ZERO_CROSS_WAIT;
            printf("[SYNC] Phase locked, waiting zero crossing.\n");
        }
        break;

    case BYPASS_STATE_ZERO_CROSS_WAIT:
        if (is_zero_crossing(g_inv_voltage_mv) && is_zero_crossing(g_bypass_voltage_mv)) {
            g_zero_cross_counter++;
            printf("[ZC] Zero crossing detected (%lu), Inv=%.1fmV Bypass=%.1fmV\n",
                   (unsigned long)g_zero_cross_counter, g_inv_voltage_mv, g_bypass_voltage_mv);
            if (g_zero_cross_counter >= 2U) {
                g_bypass_state = BYPASS_STATE_SWITCH_OVER;
                printf("[ZC] Stable zero crossing, starting switch over.\n");
            }
        } else {
            g_zero_cross_counter = 0;
        }
        break;

    case BYPASS_STATE_SWITCH_OVER:
        printf("[SWITCH] Zero-voltage switching: enabling bypass path.\n");
        hw_set_inv_pwm(false, 0);
        delay_us(SWITCH_DELAY_US);
        hw_set_bypass_pwm(true);
        hw_set_relay(true);
        delay_us(SWITCH_DELAY_US);
        g_bypass_state = BYPASS_STATE_BYPASS_MODE;
        printf("[SWITCH] Switch over complete, now in bypass mode.\n");
        break;

    case BYPASS_STATE_INV_MODE:
        printf("[INV] Running on inverter. Inv=%.1fmV Load=%.1fmA\n",
               g_inv_voltage_mv, g_load_current_ma);
        if (!g_inv_ready) {
            g_bypass_state = BYPASS_STATE_FAULT;
            printf("[INV] Inverter fault, switching to bypass.\n");
        }
        break;

    case BYPASS_STATE_BYPASS_MODE:
        printf("[BYPASS] Running on bypass. Bypass=%.1fmV Load=%.1fmA\n",
               g_bypass_voltage_mv, g_load_current_ma);
        if (!g_bypass_ready) {
            g_bypass_state = BYPASS_STATE_FAULT;
            printf("[BYPASS] Bypass fault detected.\n");
        }
        break;

    case BYPASS_STATE_FAULT:
        printf("[FAULT] System fault, disabling all outputs.\n");
        hw_set_inv_pwm(false, 0);
        hw_set_bypass_pwm(false);
        hw_set_relay(false);
        break;

    default:
        g_bypass_state = BYPASS_STATE_FAULT;
        break;
    }

    hw_update_status();
}

