static volatile uint32_t g_reg_inv_pwm_duty      = 0U;
static volatile uint32_t g_reg_bypass_ctrl       = 0U;
static volatile uint32_t g_reg_adc_inv_volt      = 0U;
static volatile uint32_t g_reg_adc_byp_volt      = 0U;
static volatile uint32_t g_reg_adc_load_volt     = 0U;
static volatile uint32_t g_reg_zero_cross_status = 0U;
static volatile uint32_t g_reg_sys_status        = 0U;

#define INV_PWM_DUTY_REG      (g_reg_inv_pwm_duty)
#define BYPASS_CTRL_REG       (g_reg_bypass_ctrl)
#define ADC_INV_VOLT_REG      (g_reg_adc_inv_volt)
#define ADC_BYP_VOLT_REG      (g_reg_adc_byp_volt)
#define ADC_LOAD_VOLT_REG     (g_reg_adc_load_volt)
#define ZERO_CROSS_STATUS_REG (g_reg_zero_cross_status)
#define SYS_STATUS_REG        (g_reg_sys_status)

/* 寄存器位定义 */
#define BYPASS_CTRL_ENABLE    (1U << 0)
#define ZERO_CROSS_DETECTED   (1U << 0)
#define SYS_STATUS_INV_READY  (1U << 0)
#define SYS_STATUS_BYP_READY  (1U << 1)

/* ============================================================
 * 系统参数定义
 * ============================================================ */
#define ADC_VOLT_FULL_SCALE   4095.0f
#define ADC_VOLT_REF          3.3f
#define VOLT_SENSOR_RATIO     100.0f
#define ZERO_CROSS_THRESHOLD  5.0f
#define PHASE_MATCH_TOLERANCE 3.0f
#define SWITCH_DELAY_US       50U

/* ============================================================
 * 状态机枚举
 * ============================================================ */
typedef enum {
    STATE_IDLE = 0,
    STATE_INV_TO_BYPASS_WAIT_ZERO,
    STATE_INV_TO_BYPASS_SWITCH,
    STATE_BYPASS_TO_INV_WAIT_ZERO,
    STATE_BYPASS_TO_INV_SWITCH,
    STATE_FAULT
} ups_state_t;

/* ============================================================
 * 全局变量
 * ============================================================ */
static ups_state_t g_ups_state = STATE_IDLE;
static uint32_t    g_switch_timer = 0;
static bool        g_bypass_active = false;

/* ============================================================
 * 工具函数：将 ADC 原始值转换为实际电压（伏特）
 * ============================================================ */
static float adc_to_voltage(uint32_t adc_raw)
{
    float v_adc = ((float)adc_raw / ADC_VOLT_FULL_SCALE) * ADC_VOLT_REF;
    return v_adc * VOLT_SENSOR_RATIO;
}

static float read_inverter_voltage(void)
{
    return adc_to_voltage(ADC_INV_VOLT_REG);
}

static float read_bypass_voltage(void)
{
    return adc_to_voltage(ADC_BYP_VOLT_REG);
}

static float read_load_voltage(void)
{
    return adc_to_voltage(ADC_LOAD_VOLT_REG);
}

static bool is_zero_cross_detected(void)
{
    return (ZERO_CROSS_STATUS_REG & ZERO_CROSS_DETECTED) != 0U;
}

static bool is_phase_matched(void)
{
    float v_inv = read_inverter_voltage();
    float v_byp = read_bypass_voltage();
    float diff = fabsf(v_inv - v_byp);
    return (diff < PHASE_MATCH_TOLERANCE);
}

static void bypass_enable(void)
{
    BYPASS_CTRL_REG |= BYPASS_CTRL_ENABLE;
    g_bypass_active = true;
    printf("[HW] Bypass ENABLED\n");
}

static void bypass_disable(void)
{
    BYPASS_CTRL_REG &= ~BYPASS_CTRL_ENABLE;
    g_bypass_active = false;
    printf("[HW] Bypass DISABLED\n");
}

static void set_inverter_duty(float duty_percent)
{
    if (duty_percent < 0.0f)   duty_percent = 0.0f;
    if (duty_percent > 100.0f) duty_percent = 100.0f;
    INV_PWM_DUTY_REG = (uint32_t)(duty_percent * 100.0f);
    printf("[HW] Inverter PWM duty = %.1f%%\n", duty_percent);
}

static void delay_us(uint32_t us)
{
    volatile uint32_t i;
    for (i = 0; i < us * 10U; i++) {
        /* 空循环模拟延时 */
    }
}

/* ============================================================
 * 状态机：UPS 旁路切换控制核心
 * ============================================================ */
static void ups_bypass_switch_task(void)
{
    float v_inv, v_byp, v_load;

    switch (g_ups_state) {

    case STATE_IDLE:
        printf("[STATE] IDLE\n");
        if ((SYS_STATUS_REG & SYS_STATUS_INV_READY) &&
            (SYS_STATUS_REG & SYS_STATUS_BYP_READY)) {
            g_ups_state = STATE_INV_TO_BYPASS_WAIT_ZERO;
            printf("[STATE] -> INV_TO_BYPASS_WAIT_ZERO\n");
        }
        break;

    case STATE_INV_TO_BYPASS_WAIT_ZERO:
        v_inv = read_inverter_voltage();
        v_byp = read_bypass_voltage();
        printf("[STATE] INV_TO_BYPASS_WAIT_ZERO  V_inv=%.2fV  V_byp=%.2fV\n",
               v_inv, v_byp);

        if (is_zero_cross_detected() && is_phase_matched()) {
            printf("[EVENT] Zero-cross detected & phase matched!\n");
            g_ups_state = STATE_INV_TO_BYPASS_SWITCH;
            g_switch_timer = SWITCH_DELAY_US;
        }
        break;

    case STATE_INV_TO_BYPASS_SWITCH:
        printf("[STATE] INV_TO_BYPASS_SWITCH  timer=%u us\n", g_switch_timer);

        if (g_switch_timer > 0U) {
            delay_us(1U);
            g_switch_timer--;
        } else {
            bypass_enable();
            delay_us(SWITCH_DELAY_US);
            set_inverter_duty(0.0f);

            v_load = read_load_voltage();
            printf("[CHECK] Load voltage after switch = %.2fV\n", v_load);

            if (v_load > ZERO_CROSS_THRESHOLD) {
                printf("[OK] Bypass switch successful, load powered.\n");
                g_ups_state = STATE_IDLE;
            } else {
                printf("[ERROR] Load voltage lost! Enter FAULT.\n");
                g_ups_state = STATE_FAULT;
            }
        }
        break;

    case STATE_BYPASS_TO_INV_WAIT_ZERO:
        v_inv = read_inverter_voltage();
        v_byp = read_bypass_voltage();
        printf("[STATE] BYPASS_TO_INV_WAIT_ZERO  V_inv=%.2fV  V_byp=%.2fV\n",
               v_inv, v_byp);

        if (is_zero_cross_detected() && is_phase_matched()) {
            printf("[EVENT] Zero-cross detected & phase matched!\n");
            g_ups_state = STATE_BYPASS_TO_INV_SWITCH;
            g_switch_timer = SWITCH_DELAY_US;
        }
        break;

    case STATE_BYPASS_TO_INV_SWITCH:
        printf("[STATE] BYPASS_TO_INV_SWITCH  timer=%u us\n", g_switch_timer);

        if (g_switch_timer > 0U) {
            delay_us(1U);
            g_switch_timer--;
        } else {
            set_inverter_duty(50.0f);
            delay_us(SWITCH_DELAY_US);
            bypass_disable();

            v_load = read_load_voltage();
            printf("[CHECK] Load voltage after switch = %.2fV\n", v_load);

            if (v_load > ZERO_CROSS_THRESHOLD) {
                printf("[OK] Inverter switch successful, load powered.\n");
                g_ups_state = STATE_IDLE;
            } else {
                printf("[ERROR] Load voltage lost! Enter FAULT.\n");
                g_ups_state = STATE_FAULT;
            }
        }
        break;

    case STATE_FAULT:
        printf("[STATE] FAULT - shutting down outputs\n");
        set_inverter_duty(0.0f);
        bypass_disable();
        break;

    default:
        g_ups_state = STATE_FAULT;
        break;
    }
}

/* ============================================================
 * 模拟硬件状态更新（用于测试）
 * ============================================================ */
static void mock_hardware_update(uint32_t tick)
{
    float phase = (float)(tick % 100U) / 100.0f * 2.0f * 3.1415926f;
    float v_inv = 220.0f * sinf(phase);
    float v_byp = 220.0f * sinf(phase);

    ADC_INV_VOLT_REG = (uint32_t)((v_inv / VOLT_SENSOR_RATIO / ADC_VOLT_REF)
                                  * ADC_VOLT_FULL_SCALE);
    ADC_BYP_VOLT_REG = (uint32_t)((v_byp / VOLT_SENSOR_RATIO / ADC_VOLT_REF)
                                  * ADC_VOLT_FULL_SCALE);
    ADC_LOAD_VOLT_REG = g_bypass_active ?
                        ADC_BYP_VOLT_REG : ADC_INV_VOLT_REG;

    if (fabsf(v_inv) < ZERO_CROSS_THRESHOLD) {
        ZERO_CROSS_STATUS_REG |= ZERO_CROSS_DETECTED;
    } else {
        ZERO_CROSS_STATUS_REG &= ~ZERO_CROSS_DETECTED;
    }

    SYS_STATUS_REG = SYS_STATUS_INV_READY | SYS_STATUS_BYP_READY;
}

/* ============================================================
 * main 函数
 * ============================================================ */
int main(void)
{
    uint32_t tick;

    printf("========================================\n");
    printf("  UPS Inverter Bypass Zero-Volt Switch\n");
    printf("========================================\n\n");

    INV_PWM_DUTY_REG      = 0U;
    BYPASS_CTRL_REG       = 0U;
    ADC_INV_VOLT_REG      = 0U;
    ADC_BYP_VOLT_REG      = 0U;
    ADC_LOAD_VOLT_REG     = 0U;
    ZERO_CROSS_STATUS_REG = 0U;
    SYS_STATUS_REG        = 0U;

    set_inverter_duty(50.0f);
    bypass_disable();
    g_ups_state = STATE_IDLE;

    printf("\n--- Phase 1: Inverter -> Bypass ---\n");
    for (tick = 0U; tick < 200U; tick++) {
        mock_hardware_update(tick);
        ups_bypass_switch_task();
        if (g_ups_state == STATE_IDLE && g_bypass_active) {
            printf("[MAIN] Bypass active, switching to Phase 2.\n\n");
            break;
        }
    }

    printf("\n--- Phase 2: Bypass -> Inverter ---\n");
    g_ups_state = STATE_BYPASS_TO_INV_WAIT_ZERO;
    for (tick = 0U; tick < 200U; tick++) {
        mock_hardware_update(tick);
        ups_bypass_switch_task();
        if (g_ups_state == STATE_IDLE && !g_bypass_active) {
            printf("[MAIN] Inverter active, test complete.\n");
            break;
        }
    }

    printf("\n========================================\n");
    printf("  Test Finished. Final State: %d\n", (int)g_ups_state);
    printf("  Bypass Active: %s\n", g_bypass_active ? "YES" : "NO");
    printf("========================================\n");

    return 0;
}
