/* ================= Mock 寄存器与硬件抽象 ================= */
static uint32_t g_relay_main_port = 0;
static uint32_t g_relay_pre_port  = 0;
static uint32_t g_adc_vbus_reg    = 0;
static uint32_t g_adc_ibus_reg    = 0;
static uint32_t g_timer_tick_reg  = 0;

#define RELAY_MAIN_PORT        (g_relay_main_port)
#define RELAY_PRE_PORT         (g_relay_pre_port)
#define ADC_VBUS_REG           (g_adc_vbus_reg)
#define ADC_IBUS_REG           (g_adc_ibus_reg)
#define TIMER_TICK_REG         (g_timer_tick_reg)

#define RELAY_MAIN_BIT         (1U << 0)
#define RELAY_PRE_BIT          (1U << 1)

#define ADC_VREF_MV            3300U
#define ADC_FULL_SCALE         4095U

#define VBUS_DIVIDER_NUM       11U
#define VBUS_DIVIDER_DEN       1U

#define IBUS_ADC_TO_MA(adc)    (((adc) * ADC_VREF_MV / ADC_FULL_SCALE) * 10U)

#define PRE_CHARGE_TARGET_MV   400000U
#define PRE_CHARGE_DELTA_MV    20000U
#define PRE_CHARGE_TIMEOUT_MS  5000U
#define PRE_CHARGE_MAX_MA      2000U

typedef enum {
    STATE_IDLE = 0,
    STATE_PRECHARGE,
    STATE_PRECHARGE_DONE,
    STATE_FAULT
} precharge_state_t;

typedef struct {
    precharge_state_t state;
    uint32_t start_tick;
    uint32_t vbus_mv;
    uint32_t ibus_ma;
    uint32_t fault_code;
} precharge_ctx_t;

/* ================= 硬件抽象层 ================= */

static uint32_t get_tick_ms(void)
{
    return TIMER_TICK_REG;
}

static uint32_t read_vbus_mv(void)
{
    uint32_t adc = ADC_VBUS_REG & 0x0FFFU;
    uint32_t v_adc_mv = adc * ADC_VREF_MV / ADC_FULL_SCALE;
    return v_adc_mv * VBUS_DIVIDER_NUM / VBUS_DIVIDER_DEN;
}

static uint32_t read_ibus_ma(void)
{
    uint32_t adc = ADC_IBUS_REG & 0x0FFFU;
    return IBUS_ADC_TO_MA(adc);
}

static void relay_main_set(bool on)
{
    if (on) {
        RELAY_MAIN_PORT |= RELAY_MAIN_BIT;
    } else {
        RELAY_MAIN_PORT &= ~RELAY_MAIN_BIT;
    }
}

static void relay_pre_set(bool on)
{
    if (on) {
        RELAY_PRE_PORT |= RELAY_PRE_BIT;
    } else {
        RELAY_PRE_PORT &= ~RELAY_PRE_BIT;
    }
}

/* ================= 预充电控制逻辑 ================= */

static void precharge_init(precharge_ctx_t *ctx)
{
    ctx->state = STATE_IDLE;
    ctx->start_tick = 0;
    ctx->vbus_mv = 0;
    ctx->ibus_ma = 0;
    ctx->fault_code = 0;

    relay_main_set(false);
    relay_pre_set(false);
}

static void precharge_start(precharge_ctx_t *ctx)
{
    if (ctx->state == STATE_IDLE || ctx->state == STATE_FAULT) {
        ctx->state = STATE_PRECHARGE;
        ctx->start_tick = get_tick_ms();
        ctx->fault_code = 0;
        relay_main_set(false);
        relay_pre_set(true);
        printf("[PRECHARGE] Start precharge, target=%u mV, timeout=%u ms\n",
               PRE_CHARGE_TARGET_MV, PRE_CHARGE_TIMEOUT_MS);
    }
}

static void precharge_fault(precharge_ctx_t *ctx, uint32_t code)
{
    relay_pre_set(false);
    relay_main_set(false);
    ctx->state = STATE_FAULT;
    ctx->fault_code = code;
    printf("[PRECHARGE] FAULT code=%u, relays off\n", code);
}

static void precharge_step(precharge_ctx_t *ctx)
{
    uint32_t now;
    uint32_t elapsed;

    ctx->vbus_mv = read_vbus_mv();
    ctx->ibus_ma = read_ibus_ma();

    switch (ctx->state) {
    case STATE_IDLE:
        break;

    case STATE_PRECHARGE:
        now = get_tick_ms();
        elapsed = now - ctx->start_tick;

        if (ctx->ibus_ma > PRE_CHARGE_MAX_MA) {
            precharge_fault(ctx, 1);
            break;
        }

        if (elapsed > PRE_CHARGE_TIMEOUT_MS) {
            precharge_fault(ctx, 2);
            break;
        }

        if (ctx->vbus_mv + PRE_CHARGE_DELTA_MV >= PRE_CHARGE_TARGET_MV) {
            relay_main_set(true);
            relay_pre_set(false);
            ctx->state = STATE_PRECHARGE_DONE;
            printf("[PRECHARGE] Done at %u ms, vbus=%u mV, ibus=%u mA\n",
                   elapsed, ctx->vbus_mv, ctx->ibus_ma);
        }
        break;

    case STATE_PRECHARGE_DONE:
        if (ctx->ibus_ma > PRE_CHARGE_MAX_MA) {
            precharge_fault(ctx, 3);
        }
        break;

    case STATE_FAULT:
        break;

    default:
        break;
    }
}

/* ================= 测试用 Mock 数据注入 ================= */

static void mock_set_vbus_mv(uint32_t mv)
{
    uint32_t v_adc_mv = mv * VBUS_DIVIDER_DEN / VBUS_DIVIDER_NUM;
    uint32_t adc = v_adc_mv * ADC_FULL_SCALE / ADC_VREF_MV;
    if (adc > ADC_FULL_SCALE) {
