        adc = ADC_FULL_SCALE;
    }
    ADC_IBUS_REG = adc;
}

static void mock_set_tick(uint32_t ms)
{
    TIMER_TICK_REG = ms;
}

/* ================= main ================= */

int main(void)
{
    precharge_ctx_t ctx;
    uint32_t t;

    printf("===== Charging Pile Precharge Control Test =====\n");

    precharge_init(&ctx);
    mock_set_tick(0);
    mock_set_vbus_mv(0);
