#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ============================================================
 *  Mock 寄存器与硬件抽象层
 *  使用普通静态变量模拟寄存器，避免非法地址访问
 * ============================================================ */

static volatile uint32_t mock_timer_cr   = 0;
static volatile uint32_t mock_timer_sr   = 0;
static volatile uint32_t mock_timer_cnt  = 0;
static volatile uint32_t mock_timer_arr  = 0;
static volatile uint32_t mock_timer_ccr1 = 0;
static volatile uint32_t mock_timer_ccr2 = 0;
static volatile uint32_t mock_timer_ccr3 = 0;
static volatile uint32_t mock_timer_ccr4 = 0;

static volatile uint32_t mock_adc_cr = 0;
static volatile uint32_t mock_adc_sr = 0;
static volatile uint32_t mock_adc_dr = 0;

static volatile uint32_t mock_gpio_odr  = 0;
static volatile uint32_t mock_gpio_bsrr = 0;

#define TIMER_CR    (mock_timer_cr)
#define TIMER_SR    (mock_timer_sr)
#define TIMER_CNT   (mock_timer_cnt)
#define TIMER_ARR   (mock_timer_arr)
#define TIMER_CCR1  (mock_timer_ccr1)
#define TIMER_CCR2  (mock_timer_ccr2)
#define TIMER_CCR3  (mock_timer_ccr3)
#define TIMER_CCR4  (mock_timer_ccr4)

#define ADC_CR      (mock_adc_cr)
#define ADC_SR      (mock_adc_sr)
#define ADC_DR      (mock_adc_dr)

#define GPIO_ODR    (mock_gpio_odr)
#define GPIO_BSRR   (mock_gpio_bsrr)

#define TIMER_CR_CEN        (1U << 0)
#define TIMER_CR_ARPE       (1U << 7)
#define TIMER_SR_UIF        (1U << 0)

#define ADC_CR_ADON         (1U << 0)
#define ADC_CR_SWSTART      (1U << 1)
#define ADC_SR_EOC          (1U << 0)

#define GPIO_PIN_0          (1U << 0)
#define GPIO_PIN_1          (1U << 1)

#define SYSTEM_CORE_CLOCK   72000000UL

/* ============================================================
 *  弧焊逆变器软开关控制参数
 * ============================================================ */

#define INV_FREQ_MIN_HZ     20000UL
#define INV_FREQ_MAX_HZ     100000UL

#define DEADTIME_MIN_NS     200UL
#define DEADTIME_MAX_NS     1000UL

#define PHASE_SHIFT_MIN     0.05f
#define PHASE_SHIFT_MAX     0.45f

#define RESONANT_L_H        (2.0e-6f)
#define RESONANT_C_F        (10.0e-9f)

#define VBUS_MIN_V          200.0f
#define VBUS_MAX_V          400.0f

#define IOUT_MIN_A          10.0f
#define IOUT_MAX_A          400.0f

/* ============================================================
 *  数据结构定义
 * ============================================================ */

typedef enum {
    ZVS_STATE_IDLE = 0,
    ZVS_STATE_DEADTIME,
    ZVS_STATE_ACTIVE,
    ZVS_STATE_FAULT
} zvs_state_t;

typedef struct {
    float    target_current_a;
    float    target_freq_hz;
    float    phase_shift;

    float    actual_current_a;
    float    actual_vbus_v;
    float    actual_freq_hz;

    uint32_t deadtime_ns;
    float    resonant_period_ns;
    bool     zvs_achieved;

    zvs_state_t state;
    uint32_t    pwm_period_ticks;
    uint32_t    deadtime_ticks;
    uint32_t    phase_shift_ticks;

    float    overcurrent_threshold;
    float    overvoltage_threshold;
    bool     fault_flag;
} arc_welder_ctrl_t;

/* ============================================================
 *  函数声明
 * ============================================================ */

static void     system_clock_init(void);
static void     timer_pwm_init(uint32_t freq_hz, uint32_t deadtime_ns);
static void     adc_init(void);
static void     gpio_init(void);

static uint32_t freq_to_period_ticks(uint32_t freq_hz);
static uint32_t ns_to_ticks(uint32_t ns);
static float    calc_resonant_period_ns(float l_h, float c_f);
static bool     check_zvs_condition(float vbus, float iout, float l_h, float c_f);
static void     update_phase_shift(arc_welder_ctrl_t *ctrl);
static void     update_deadtime(arc_welder_ctrl_t *ctrl);
static void     apply_pwm_outputs(arc_welder_ctrl_t *ctrl);
static void     read_feedback(arc_welder_ctrl_t *ctrl);
static void     protection_check(arc_welder_ctrl_t *ctrl);
static void     soft_start(arc_welder_ctrl_t *ctrl);
static void     arc_welder_control_loop(arc_welder_ctrl_t *ctrl);

/* ============================================================
 *  系统初始化
 * ============================================================ */

static void system_clock_init(void)
{
    printf("[INIT] System clock configured to %lu Hz\n",
           (unsigned long)SYSTEM_CORE_CLOCK);
}

static void gpio_init(void)
{
    GPIO_ODR = 0;
    printf("[INIT] GPIO initialized for PWM outputs\n");
}

static void adc_init(void)
{
    ADC_CR |= ADC_CR_ADON;
    printf("[INIT] ADC initialized\n");
}

static void timer_pwm_init(uint32_t freq_hz, uint32_t deadtime_ns)
{
    uint32_t period_ticks;
    uint32_t dt_ticks;

    period_ticks = freq_to_period_ticks(freq_hz);
    dt_ticks = ns_to_ticks(deadtime_ns);

    TIMER_ARR = period_ticks - 1;
    TIMER_CR |= TIMER_CR_ARPE;

    TIMER_CCR1 = dt_ticks;
    TIMER_CCR2 = dt_ticks;
    TIMER_CCR3 = period_ticks / 2;
    TIMER_CCR4 = period_ticks / 2 + dt_ticks;

    TIMER_CR |= TIMER_CR_CEN;

    printf("[INIT] PWM Timer: freq=%lu Hz, period=%lu ticks, deadtime=%lu ticks\n",
           (unsigned long)freq_hz,
           (unsigned long)period_ticks,
           (unsigned long)dt_ticks);
}

/* ============================================================
 *  工具函数
 * ============================================================ */

static uint32_t freq_to_period_ticks(uint32_t freq_hz)
{
    if (freq_hz < INV_FREQ_MIN_HZ) freq_hz = INV_FREQ_MIN_HZ;
    if (freq_hz > INV_FREQ_MAX_HZ) freq_hz = INV_FREQ_MAX_HZ;
    return SYSTEM_CORE_CLOCK / freq_hz;
}

static uint32_t ns_to_ticks(uint32_t ns)
{
    uint32_t ticks = (uint32_t)((uint64_t)ns * SYSTEM_CORE_CLOCK / 1000000000ULL);
    if (ticks == 0) ticks = 1;
    return ticks;
}

static float calc_resonant_period_ns(float l_h, float c_f)
{
    float period_s = 2.0f * 3.14159265f * sqrtf(l_h * c_f);
    return period_s * 1.0e9f;
}

static bool check_zvs_condition(float vbus, float iout, float l_h, float c_f)
{
    float resonant_period_ns = calc_resonant_period_ns(l_h, c_f);
    float half_period_ns = resonant_period_ns * 0.5f;

    if (half_period_ns > (float)DEADTIME_MAX_NS) {
        return false;
    }

    float z0 = sqrtf(l_h / c_f);
    float i_resonant_peak = vbus / z0;

    if (i_resonant_peak < iout * 0.1f) {
        return false;
    }

    return true;
}

/* ============================================================
 *  控制算法
 * ============================================================ */

static void update_phase_shift(arc_welder_ctrl_t *ctrl)
{
    float error = ctrl->target_current_a - ctrl->actual_current_a;
    float kp = 0.0005f;

    ctrl->phase_shift += kp * error;

    if (ctrl->phase_shift < PHASE_SHIFT_MIN) {
        ctrl->phase_shift = PHASE_SHIFT_MIN;
    }
    if (ctrl->phase_shift > PHASE_SHIFT_MAX) {
        ctrl->phase_shift = PHASE_SHIFT_MAX;
    }

    ctrl->phase_shift_ticks = (uint32_t)(ctrl->phase_shift * (float)ctrl->pwm_period_ticks);
}

static void update_deadtime(arc_welder_ctrl_t *ctrl)
{
    float vbus_ratio = (ctrl->actual_vbus_v - VBUS_MIN_V) / (VBUS_MAX_V - VBUS_MIN_V);
    if (vbus_ratio < 0.0f) vbus_ratio = 0.0f;
    if (vbus_ratio > 1.0f) vbus_ratio = 1.0f;

    uint32_t dt_ns = DEADTIME_MIN_NS +
                     (uint32_t)(vbus_ratio * (float)(DEADTIME_MAX_NS - DEADTIME_MIN_NS));

    ctrl->deadtime_ns = dt_ns;
    ctrl->deadtime_ticks = ns_to_ticks(dt_ns);

    TIMER_CCR1 = ctrl->deadtime_ticks;
    TIMER_CCR2 = ctrl->deadtime_ticks;
}

static void apply_pwm_outputs(arc_welder_ctrl_t *ctrl)
{
    uint32_t period = ctrl->pwm_period_ticks;
    uint32_t dt = ctrl->deadtime_ticks;
    uint32_t ps = ctrl->phase_shift_ticks;

    TIMER_CCR1 = dt;
    TIMER_CCR2 = period / 2;

    TIMER_CCR3 = period / 2 + ps;
    TIMER_CCR4 = period - dt;

    GPIO_BSRR = GPIO_PIN_0 | GPIO_PIN_1;
}

static void read_feedback(arc_welder_ctrl_t *ctrl)
{
    static uint32_t sim_counter = 0;
    sim_counter++;

    float noise = (float)((sim_counter % 100) - 50) * 0.1f;
    ctrl->actual_current_a = ctrl->target_current_a + noise;

    ctrl->actual_vbus_v = 300.0f + (float)((sim_counter % 50) - 25) * 0.5f;

    ctrl->actual_freq_hz = ctrl->target_freq_hz;

    if (ctrl->actual_current_a < 0.0f) ctrl->actual_current_a = 0.0f;
    if (ctrl->actual_vbus_v < 0.0f) ctrl->actual_vbus_v = 0.0f;
}

static void protection_check(arc_welder_ctrl_t *ctrl)
{
    if (ctrl->actual_current_a > ctrl->overcurrent_threshold) {
        ctrl->fault_flag = true;
        ctrl->state = ZVS_STATE_FAULT;
        printf("[FAULT] Overcurrent: %.1f A > %.1f A\n",
               ctrl->actual_current_a, ctrl->overcurrent_threshold);
        return;
    }

    if (ctrl->actual_vbus_v > ctrl->overvoltage_threshold) {
        ctrl->fault_flag = true;
        ctrl->state = ZVS_STATE_FAULT;
        printf("[FAULT] Overvoltage: %.1f V > %.1f V\n",
               ctrl->actual_vbus_v, ctrl->overvoltage_threshold);
        return;
    }

    if (ctrl->actual_vbus_v < VBUS_MIN_V * 0.8f) {
        ctrl->fault_flag = true;
        ctrl->state = ZVS_STATE_FAULT;
        printf("[FAULT] Undervoltage: %.1f V\n", ctrl->actual_vbus_v);
        return;
    }

    ctrl->fault_flag = false;
}

static void soft_start(arc_welder_ctrl_t *ctrl)
{
    static uint32_t start_counter = 0;
    const uint32_t soft_start_steps = 100;

    if (start_counter < soft_start_steps) {
        start_counter++;
        float ratio = (float)start_counter / (float)soft_start_steps;
        ctrl->target_current_a = IOUT_MIN_A + ratio * (IOUT_MAX_A - IOUT_MIN_A) * 0.5f;
    }
}

static void arc_welder_control_loop(arc_welder_ctrl_t *ctrl)
{
    read_feedback(ctrl);

    protection_check(ctrl);
    if (ctrl->fault_flag) {
        GPIO_ODR = 0;
        return;
    }

    soft_start(ctrl);

    ctrl->zvs_achieved = check_zvs_condition(
        ctrl->actual_vbus_v,
        ctrl->actual_current_a,
        RESONANT_L_H,
        RESONANT_C_F
    );

    update_deadtime(ctrl);
    update_phase_shift(ctrl);
    apply_pwm_outputs(ctrl);

    if (ctrl->zvs_achieved) {
        ctrl->state = ZVS_STATE_ACTIVE;
    } else {
        ctrl->state = ZVS_STATE_DEADTIME;
    }
}

/* ============================================================
 *  主函数
 * ============================================================ */

int main(void)
{
    arc_welder_ctrl_t ctrl;
    int i;

    printf("========================================\n");
    printf("  Arc Welding Inverter Soft-Switching\n");
    printf("  Control Algorithm Demo\n");
    printf("========================================\n\n");

    /* 初始化控制结构体 */
    ctrl.target_current_a      = 150.0f;
    ctrl.target_freq_hz        = 50000.0f;
    ctrl.phase_shift           = 0.2f;
    ctrl.actual_current_a      = 0.0f;
    ctrl.actual_vbus_v         = 300.0f;
    ctrl.actual_freq_hz        = 0.0f;
    ctrl.deadtime_ns           = DEADTIME_MIN_NS;
    ctrl.resonant_period_ns    = calc_resonant_period_ns(RESONANT_L_H, RESONANT_C_F);
    ctrl.zvs_achieved          = false;
    ctrl.state                 = ZVS_STATE_IDLE;
    ctrl.pwm_period_ticks      = freq_to_period_ticks((uint32_t)ctrl.target_freq_hz);
    ctrl.deadtime_ticks        = ns_to_ticks(ctrl.deadtime_ns);
    ctrl.phase_shift_ticks     = 0;
    ctrl.overcurrent_threshold = IOUT_MAX_A * 1.1f;
    ctrl.overvoltage_threshold = VBUS_MAX_V * 1.1f;
    ctrl.fault_flag            = false;

