#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
static uint16_t mock_adc_u = 2048;
static uint16_t mock_adc_v = 2048;
static uint16_t mock_adc_w = 2048;
static uint16_t mock_adc_il = 2048;
static uint16_t mock_pwm_u = 0;
static uint16_t mock_pwm_v = 0;
static uint16_t mock_pwm_w = 0;

#define MOCK_REG_ADC_U  (mock_adc_u)
#define MOCK_REG_ADC_V  (mock_adc_v)
#define MOCK_REG_ADC_W  (mock_adc_w)
#define MOCK_REG_ADC_IL (mock_adc_il)
#define MOCK_REG_PWM_U  (mock_pwm_u)
#define MOCK_REG_PWM_V  (mock_pwm_v)
#define MOCK_REG_PWM_W  (mock_pwm_w)

/* ================= 系统参数 ================= */
#define PI              3.14159265358979323846f
#define TS              0.0001f
#define GRID_FREQ       50.0f
#define OMEGA           2.0f * PI * GRID_FREQ
#define VDC_NOMINAL     700.0f
#define ADC_VREF        3.3f
#define ADC_FULL_SCALE  4095.0f
#define VOLT_SENSOR_GAIN 0.01f
#define CURR_SENSOR_GAIN 0.005f
#define PWM_PERIOD      4200.0f

/* ================= 控制器参数 ================= */
#define KP_IQ           0.5f
#define KI_IQ           50.0f
#define KP_ID           0.5f
#define KI_ID           50.0f
#define KP_VDC          0.1f
#define KI_VDC          5.0f

/* ================= 数据结构 ================= */
typedef struct {
    float alpha;
    float beta;
} AlphaBeta;

typedef struct {
    float d;
    float q;
} DQ;

typedef struct {
    float kp;
    float ki;
    float integral;
    float out_max;
    float out_min;
} PI_Controller;

typedef struct {
    float id_ref;
    float iq_ref;
    float vdc_ref;
    float vdc_fdb;
    float id_fdb;
    float iq_fdb;
    float vd_fdb;
    float vq_fdb;
    float vd_out;
    float vq_out;
    float theta;
    float sin_theta;
    float cos_theta;
    PI_Controller pi_id;
    PI_Controller pi_iq;
    PI_Controller pi_vdc;
} SVG_Controller;

/* ================= 工具函数 ================= */
static float clampf(float val, float min, float max)
{
    if (val > max) return max;
    if (val < min) return min;
    return val;
}

static void PI_Init(PI_Controller *pi, float kp, float ki, float out_max, float out_min)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_max = out_max;
    pi->out_min = out_min;
}

static float PI_Calc(PI_Controller *pi, float error, float ts)
{
    float p_term = pi->kp * error;
    pi->integral += pi->ki * error * ts;
    pi->integral = clampf(pi->integral, pi->out_min, pi->out_max);
    float out = p_term + pi->integral;
    out = clampf(out, pi->out_min, pi->out_max);
    return out;
}

/* ================= Clarke 变换 ================= */
static AlphaBeta Clarke_Transform(float u, float v, float w)
{
    AlphaBeta ab;
    ab.alpha = (2.0f * u - v - w) / 3.0f;
    ab.beta  = (v - w) / 1.7320508075688772f;
    return ab;
}

/* ================= Park 变换 ================= */
static DQ Park_Transform(AlphaBeta ab, float sin_theta, float cos_theta)
{
    DQ dq;
    dq.d =  ab.alpha * cos_theta + ab.beta * sin_theta;
    dq.q = -ab.alpha * sin_theta + ab.beta * cos_theta;
    return dq;
}

/* ================= 反 Park 变换 ================= */
static AlphaBeta Inv_Park_Transform(DQ dq, float sin_theta, float cos_theta)
{
    AlphaBeta ab;
    ab.alpha = dq.d * cos_theta - dq.q * sin_theta;
    ab.beta  = dq.d * sin_theta + dq.q * cos_theta;
    return ab;
}

/* ================= 反 Clarke 变换 ================= */
static void Inv_Clarke_Transform(AlphaBeta ab, float *u, float *v, float *w)
{
    *u = ab.alpha;
    *v = -0.5f * ab.alpha + 0.8660254037844386f * ab.beta;
    *w = -0.5f * ab.alpha - 0.8660254037844386f * ab.beta;
}

/* ================= 锁相环 ================= */
static void PLL_Update(SVG_Controller *svg, float v_alpha, float v_beta, float ts)
{
    float vq = -v_alpha * svg->sin_theta + v_beta * svg->cos_theta;
    float omega_est = OMEGA + 100.0f * vq;
    svg->theta += omega_est * ts;
    if (svg->theta > 2.0f * PI) svg->theta -= 2.0f * PI;
    if (svg->theta < 0.0f) svg->theta += 2.0f * PI;
    svg->sin_theta = sinf(svg->theta);
    svg->cos_theta = cosf(svg->theta);
}

/* ================= ADC 转换 ================= */
static float ADC_To_Voltage(uint16_t adc_val)
{
    return ((float)adc_val / ADC_FULL_SCALE) * ADC_VREF / VOLT_SENSOR_GAIN;
}

static float ADC_To_Current(uint16_t adc_val)
{
    return ((float)adc_val / ADC_FULL_SCALE) * ADC_VREF / CURR_SENSOR_GAIN;
}

/* ================= SVG 初始化 ================= */
static void SVG_Init(SVG_Controller *svg)
{
    svg->id_ref = 0.0f;
    svg->iq_ref = 0.0f;
    svg->vdc_ref = VDC_NOMINAL;
    svg->vdc_fdb = 0.0f;
    svg->id_fdb = 0.0f;
    svg->iq_fdb = 0.0f;
    svg->vd_fdb = 0.0f;
    svg->vq_fdb = 0.0f;
    svg->vd_out = 0.0f;
    svg->vq_out = 0.0f;
    svg->theta = 0.0f;
    svg->sin_theta = 0.0f;
    svg->cos_theta = 1.0f;

    PI_Init(&svg->pi_id, KP_ID, KI_ID, 400.0f, -400.0f);
    PI_Init(&svg->pi_iq, KP_IQ, KI_IQ, 400.0f, -400.0f);
    PI_Init(&svg->pi_vdc, KP_VDC, KI_VDC, 50.0f, -50.0f);
}

/* ================= SVG 控制主循环 ================= */
static void SVG_ControlStep(SVG_Controller *svg, float ts)
{
    uint16_t adc_u = MOCK_REG_ADC_U;
    uint16_t adc_v = MOCK_REG_ADC_V;
    uint16_t adc_w = MOCK_REG_ADC_W;
    uint16_t adc_il = MOCK_REG_ADC_IL;

    float vu = ADC_To_Voltage(adc_u);
    float vv = ADC_To_Voltage(adc_v);
    float vw = ADC_To_Voltage(adc_w);
    float il = ADC_To_Current(adc_il);

    AlphaBeta v_ab = Clarke_Transform(vu, vv, vw);

    PLL_Update(svg, v_ab.alpha, v_ab.beta, ts);

    DQ v_dq = Park_Transform(v_ab, svg->sin_theta, svg->cos_theta);
    svg->vd_fdb = v_dq.d;
    svg->vq_fdb = v_dq.q;

    svg->vdc_fdb = VDC_NOMINAL + il * 0.1f;
    float vdc_err = svg->vdc_ref - svg->vdc_fdb;
    float id_ref_from_vdc = PI_Calc(&svg->pi_vdc, vdc_err, ts);

    svg->id_ref = id_ref_from_vdc;
    svg->iq_ref = 0.0f;

    svg->id_fdb = il * svg->cos_theta;
    svg->iq_fdb = il * svg->sin_theta;

    float id_err = svg->id_ref - svg->id_fdb;
    float iq_err = svg->iq_ref - svg->iq_fdb;

    float vd_pi = PI_Calc(&svg->pi_id, id_err, ts);
    float vq_pi = PI_Calc(&svg->pi_iq, iq_err, ts);

    float vd_decouple = svg->vd_fdb - OMEGA * 0.001f * svg->iq_fdb;
    float vq_decouple = svg->vq_fdb + OMEGA * 0.001f * svg->id_fdb;

    svg->vd_out = vd_pi + vd_decouple;
    svg->vq_out = vq_pi + vq_decouple;

    DQ v_out_dq;
    v_out_dq.d = svg->vd_out;
    v_out_dq.q = svg->vq_out;
    AlphaBeta v_out_ab = Inv_Park_Transform(v_out_dq, svg->sin_theta, svg->cos_theta);

    float mu, mv, mw;
    Inv_Clarke_Transform(v_out_ab, &mu, &mv, &mw);

    float vdc_half = VDC_NOMINAL * 0.5f;
    mu = clampf(mu / vdc_half, -1.0f, 1.0f);
    mv = clampf(mv / vdc_half, -1.0f, 1.0f);
    mw = clampf(mw / vdc_half, -1.0f, 1.0f);

    MOCK_REG_PWM_U = (uint16_t)((mu * 0.5f + 0.5f) * PWM_PERIOD);
    MOCK_REG_PWM_V = (uint16_t)((mv * 0.5f + 0.5f) * PWM_PERIOD);
    MOCK_REG_PWM_W = (uint16_t)((mw * 0.5f + 0.5f) * PWM_PERIOD);
}

/* ================= 主函数 ================= */
int main(void)
{
    SVG_Controller svg;
    SVG_Init(&svg);

    MOCK_REG_ADC_U = 2048;
    MOCK_REG_ADC_V = 2048;
    MOCK_REG_ADC_W = 2048;
    MOCK_REG_ADC_IL = 2048;

    printf("===== SVG Control Algorithm Simulation =====\n");
    printf("Parameters: Ts=%.4f s, GridFreq=%.1f Hz, Vdc=%.1f V\n",
           TS, GRID_FREQ, VDC_NOMINAL);
    printf("PI: Kp_id=%.2f Ki_id=%.2f Kp_iq=%.2f Ki_iq=%.2f\n",
           KP_ID, KI_ID, KP_IQ, KI_IQ);
    printf("---------------------------------------------\n");

    int step;
    for (step = 0; step < 10; step++) {
        float angle = 2.0f * PI * GRID_FREQ * step * TS;
        MOCK_REG_ADC_U = (uint16_t)(2048 + 1000 * sinf(angle));
        MOCK_REG_ADC_V = (uint16_t)(2048 + 1000 * sinf(angle - 2.094f));
        MOCK_REG_ADC_W = (uint16_t)(2048 + 1000 * sinf(angle + 2.094f));
        MOCK_REG_ADC_IL = (uint16_t)(2048 + 500 * sinf(angle + 0.5f));

        SVG_ControlStep(&svg, TS);

        printf("Step %2d: theta=%.4f rad | Vd=%.2f Vq=%.2f | "
               "Id=%.3f Iq=%.3f | Id_ref=%.3f Iq_ref=%.3f | "
               "Vd_out=%.2f Vq_out=%.2f | PWM=(%u,%u,%u)\n",
               step,
               svg.theta,
               svg.vd_fdb, svg.vq_fdb,
               svg.id_fdb, svg.iq_fdb,
               svg.id_ref, svg.iq_ref,
               svg.vd_out, svg.vq_out,
               (unsigned)MOCK_REG_PWM_U,
               (unsigned)MOCK_REG_PWM_V,
               (unsigned)MOCK_REG_PWM_W);
    }

    printf("---------------------------------------------\n");
    printf("SVG simulation completed successfully.\n");
    return 0;
}
