static volatile uint32_t mock_tim_arr = 0;
static volatile uint32_t mock_gpio_odr = 0;

#define ADC_DR      (mock_adc_dr)
#define ADC_CR2     (mock_adc_cr2)
#define ADC_SR      (mock_adc_sr)
#define TIM_CR1     (mock_tim_cr1)
#define TIM_CCR1    (mock_tim_ccr1)
#define TIM_ARR     (mock_tim_arr)
#define GPIO_ODR    (mock_gpio_odr)

/* 模拟 ADC 读取函数 */
static uint32_t mock_adc_read(void)
{
    static uint32_t fake_val = 2048;
    fake_val += 1;
    if (fake_val > 4095) fake_val = 0;
    return fake_val;
}

/* ==================== 温度换算与系统参数 ==================== */
#define ADC_REF_VOLTAGE     3.3f
#define ADC_RESOLUTION      4096.0f
#define TEMP_SENSOR_GAIN    0.01f
#define TEMP_SENSOR_OFFSET  0.5f

#define PID_KP              8.0f
#define PID_KI              0.5f
#define PID_KD              2.0f

#define TEMP_SETPOINT       150.0f
#define TEMP_OVERTEMP       180.0f
#define TEMP_HYSTERESIS     5.0f

#define PWM_MAX             1000U
#define PWM_MIN             0U

#define SAMPLE_PERIOD_S     0.1f

/* ==================== PID 控制器结构体 ==================== */
typedef struct {
    float kp;
    float ki;
    float kd;
    float setpoint;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
    float integral_min;
    float integral_max;
} PID_Controller;

/* ==================== 过温保护状态机 ==================== */
typedef enum {
    OT_STATE_NORMAL = 0,
    OT_STATE_TRIPPED
} OverTempState;

typedef struct {
    OverTempState state;
    float trip_threshold;
    float reset_threshold;
} OverTempProtection;

/* ==================== 全局变量 ==================== */
static PID_Controller g_pid;
static OverTempProtection g_otp;
static float g_current_temp = 0.0f;
static uint32_t g_pwm_duty = 0;

/* ==================== 函数声明 ==================== */
static void pid_init(PID_Controller *pid, float kp, float ki, float kd,
                     float setpoint, float out_min, float out_max);
static float pid_compute(PID_Controller *pid, float measured, float dt);
static void otp_init(OverTempProtection *otp, float trip, float reset);
static bool otp_update(OverTempProtection *otp, float temperature);
static float adc_to_temperature(uint32_t adc_value);
static void pwm_set_duty(uint32_t duty);
static void heater_enable(bool enable);
static void system_clock_init(void);

/* ==================== 主函数 ==================== */
int main(void)
{
    uint32_t adc_raw;
    float pid_output;
    bool heater_on;
    int loop_count;

    printf("========================================\n");
    printf("  工业加热电源温控系统 (PID + 过温保护)\n");
    printf("========================================\n");
    printf("设定温度: %.1f C\n", TEMP_SETPOINT);
    printf("过温保护阈值: %.1f C\n", TEMP_OVERTEMP);
    printf("过温恢复迟滞: %.1f C\n", TEMP_HYSTERESIS);
    printf("PID 参数: Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
           PID_KP, PID_KI, PID_KD);
    printf("----------------------------------------\n");

    system_clock_init();
    pid_init(&g_pid, PID_KP, PID_KI, PID_KD,
             TEMP_SETPOINT, (float)PWM_MIN, (float)PWM_MAX);
    otp_init(&g_otp, TEMP_OVERTEMP, TEMP_OVERTEMP - TEMP_HYSTERESIS);

    for (loop_count = 0; loop_count < 100; loop_count++) {
        adc_raw = mock_adc_read();
        g_current_temp = adc_to_temperature(adc_raw);

        heater_on = otp_update(&g_otp, g_current_temp);

        if (heater_on) {
            pid_output = pid_compute(&g_pid, g_current_temp, SAMPLE_PERIOD_S);
            g_pwm_duty = (uint32_t)pid_output;
        } else {
            g_pwm_duty = PWM_MIN;
            g_pid.integral = 0.0f;
            g_pid.prev_error = 0.0f;
            pid_output = 0.0f;
        }

        pwm_set_duty(g_pwm_duty);
        heater_enable(heater_on);

        printf("[%03d] ADC=%4lu  Temp=%6.2f C  PID_Out=%6.2f  PWM=%4lu  Heater=%s  OT_State=%s\n",
               loop_count,
               (unsigned long)adc_raw,
               g_current_temp,
               pid_output,
               (unsigned long)g_pwm_duty,
               heater_on ? "ON " : "OFF",
               (g_otp.state == OT_STATE_NORMAL) ? "NORMAL" : "TRIPPED");
    }

    printf("----------------------------------------\n");
    printf("测试结束。\n");
    return 0;
}

/* ==================== 系统时钟初始化（模拟） ==================== */
static void system_clock_init(void)
{
    ADC_CR2 = 0x00000001U;
    TIM_CR1 = 0x00000001U;
    TIM_ARR = PWM_MAX;
    GPIO_ODR = 0x00000000U;
}

/* ==================== ADC 值转温度 ==================== */
static float adc_to_temperature(uint32_t adc_value)
{
    float voltage;
    float temperature;

    voltage = ((float)adc_value / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    temperature = (voltage - TEMP_SENSOR_OFFSET) / TEMP_SENSOR_GAIN;

    return temperature;
}

/* ==================== PID 初始化 ==================== */
static void pid_init(PID_Controller *pid, float kp, float ki, float kd,
                     float setpoint, float out_min, float out_max)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->integral_min = out_min;
    pid->integral_max = out_max;
}

/* ==================== PID 计算 ==================== */
static float pid_compute(PID_Controller *pid, float measured, float dt)
{
    float error;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = SAMPLE_PERIOD_S;
    }

    error = pid->setpoint - measured;

    pid->integral += error * dt;
    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = (pid->kp * error)
           + (pid->ki * pid->integral)
           + (pid->kd * derivative);

    if (output > pid->output_max) {
        output = pid->output_max;
    } else if (output < pid->output_min) {
        output = pid->output_min;
    }

    return output;
}

/* ==================== 过温保护初始化 ==================== */
static void otp_init(OverTempProtection *otp, float trip, float reset)
{
    otp->state = OT_STATE_NORMAL;
    otp->trip_threshold = trip;
    otp->reset_threshold = reset;
}

/* ==================== 过温保护更新 ==================== */
static bool otp_update(OverTempProtection *otp, float temperature)
{
    bool heater_allowed = true;

    switch (otp->state) {
    case OT_STATE_NORMAL:
        if (temperature >= otp->trip_threshold) {
            otp->state = OT_STATE_TRIPPED;
            heater_allowed = false;
        }
        break;

    case OT_STATE_TRIPPED:
        if (temperature <= otp->reset_threshold) {
            otp->state = OT_STATE_NORMAL;
            heater_allowed = true;
        } else {
            heater_allowed = false;
        }
        break;

    default:
        otp->state = OT_STATE_NORMAL;
        heater_allowed = true;
        break;
    }

    return heater_allowed;
}

/* ==================== PWM 占空比设置 ==================== */
static void pwm_set_duty(uint32_t duty)
{
    if (duty > PWM_MAX) {
        duty = PWM_MAX;
    }
    TIM_CCR1 = duty;
}

/* ==================== 加热器使能控制 ==================== */
static void heater_enable(bool enable)
{
    if (enable) {
        GPIO_ODR |= 0x00000001U;
    } else {
        GPIO_ODR &= ~0x00000001U;
    }
}
