    float target_power;
    float duty_cycle;
    uint32_t pwm_duty_ticks;
} PowerControl;

/* ===== 函数声明 ===== */
static void PID_Init(PID_Controller *pid);
static float PID_Compute(PID_Controller *pid, float setpoint, float measured);
static void PWM_Init(void);
static void PWM_SetDuty(float duty);
static float ADC_ReadVoltage(void);
static float ADC_ReadCurrent(void);
static void PowerControl_Init(PowerControl *pc);
static void PowerControl_Update(PowerControl *pc, PID_Controller *pid);
static void Delay_ms(uint32_t ms);

/* ===== PID 初始化 ===== */
static void PID_Init(PID_Controller *pid)
{
    pid->kp = PID_KP;
    pid->ki = PID_KI;
    pid->kd = PID_KD;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->out_min = PID_OUT_MIN;
    pid->out_max = PID_OUT_MAX;
    pid->integral_limit = PID_INTEGRAL_LIMIT;
}

/* ===== PID 计算 ===== */
static float PID_Compute(PID_Controller *pid, float setpoint, float measured)
{
    float error = setpoint - measured;
    float p_term = pid->kp * error;

    pid->integral += pid->ki * error;
    if (pid->integral > pid->integral_limit) {
        pid->integral = pid->integral_limit;
    } else if (pid->integral < -pid->integral_limit) {
        pid->integral = -pid->integral_limit;
    }

    float d_term = pid->kd * (error - pid->prev_error);
    pid->prev_error = error;

    float output = p_term + pid->integral + d_term;

    if (output > pid->out_max) {
        output = pid->out_max;
    } else if (output < pid->out_min) {
        output = pid->out_min;
    }

    return output;
}

/* ===== PWM 初始化 ===== */
static void PWM_Init(void)
{
    PWM_PERIOD_REG = PWM_PERIOD_TICKS;
    PWM_DUTY_REG = 0;
    TIMER_CTRL_REG |= TIMER_ENABLE;
}

/* ===== 设置 PWM 占空比 ===== */
static void PWM_SetDuty(float duty)
{
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;

    uint32_t ticks = (uint32_t)(duty * (float)PWM_PERIOD_TICKS);
    PWM_DUTY_REG = ticks;
}

/* ===== 读取电压（mock：模拟 ADC 返回固定值） ===== */
static float ADC_ReadVoltage(void)
{
    /* 模拟 ADC 转换：直接设置 EOC 标志，返回一个模拟值 */
    ADC_CTRL_REG |= ADC_START;
    ADC_CTRL_REG |= ADC_EOC;   /* 模拟转换完成 */
    ADC_DATA_REG = 2000U;      /* 模拟 ADC 原始值 */
    uint32_t raw = ADC_DATA_REG & 0x0FFF;
    float voltage = ((float)raw / (float)ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
    return voltage * VOLTAGE_DIVIDER;
}

/* ===== 读取电流（mock：模拟 ADC 返回固定值） ===== */
static float ADC_ReadCurrent(void)
{
    ADC_CTRL_REG |= ADC_START;
    ADC_CTRL_REG |= ADC_EOC;
    ADC_DATA_REG = 1000U;      /* 模拟 ADC 原始值 */
    uint32_t raw = ADC_DATA_REG & 0x0FFF;
    float voltage = ((float)raw / (float)ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
    return voltage / (CURRENT_SENSE_R * CURRENT_AMP_GAIN);
}

/* ===== 功率控制初始化 ===== */
static void PowerControl_Init(PowerControl *pc)
{
    pc->voltage = 0.0f;
    pc->current = 0.0f;
    pc->power = 0.0f;
    pc->target_power = TARGET_POWER_W;
    pc->duty_cycle = 0.0f;
    pc->pwm_duty_ticks = 0;
}

/* ===== 功率控制更新 ===== */
static void PowerControl_Update(PowerControl *pc, PID_Controller *pid)
{
    pc->voltage = ADC_ReadVoltage();
    pc->current = ADC_ReadCurrent();
    pc->power = pc->voltage * pc->current;

    float duty = PID_Compute(pid, pc->target_power, pc->power);

    if (pc->power > MAX_POWER_W) {
        duty = 0.0f;
        pid->integral = 0.0f;
    }

    pc->duty_cycle = duty;
    pc->pwm_duty_ticks = (uint32_t)(duty * (float)PWM_PERIOD_TICKS);
    PWM_SetDuty(duty);
}

/* ===== 简单延时 ===== */
static void Delay_ms(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 1000U; i++) {
        /* 空循环 */
    }
}

/* ===== 主函数 ===== */
int main(void)
{
    PID_Controller pid;
    PowerControl pc;

    printf("===== Microwave Power Control (PWM + Feedback) =====\n");
    printf("PWM Frequency: %u Hz\n", (unsigned)PWM_FREQ_HZ);
    printf("PWM Period Ticks: %u\n", (unsigned)PWM_PERIOD_TICKS);
    printf("Target Power: %.1f W\n", (double)TARGET_POWER_W);
    printf("Max Power: %.1f W\n", (double)MAX_POWER_W);
    printf("PID Params: Kp=%.2f Ki=%.2f Kd=%.2f\n",
           (double)PID_KP, (double)PID_KI, (double)PID_KD);
    printf("----------------------------------------------------\n");

    PID_Init(&pid);
    PowerControl_Init(&pc);
    PWM_Init();

    printf("Initial Duty: %.2f%%\n", (double)(pc.duty_cycle * 100.0f));
    printf("----------------------------------------------------\n");

    for (int step = 0; step < 10; step++) {
        PowerControl_Update(&pc, &pid);

        printf("Step %2d | V=%.2f V | I=%.3f A | P=%.2f W | Duty=%.2f%% | Ticks=%u\n",
               step + 1,
               (double)pc.voltage,
               (double)pc.current,
               (double)pc.power,
               (double)(pc.duty_cycle * 100.0f),
               (unsigned)pc.pwm_duty_ticks);

        Delay_ms(1);
    }

    printf("----------------------------------------------------\n");
    printf("Final Duty: %.2f%%\n", (double)(pc.duty_cycle * 100.0f));
    printf("Final Power: %.2f W\n", (double)pc.power);
    printf("===== Control Loop Finished =====\n");

    return 0;
}
