#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* ============================================================
 * 系统参数
 * ============================================================ */
#define FILTER_WINDOW_SIZE      8U
#define MEDIAN_WINDOW_SIZE      5U
#define IIR_ALPHA_Q15           9830
#define SPIKE_THRESHOLD         200U
#define NOMINAL_VOLTAGE_MV      12000U
#define OVP_THRESHOLD_MV        16000U
#define UVP_THRESHOLD_MV        8000U

/* ============================================================
 * 数据结构
 * ============================================================ */
typedef struct {
    uint16_t buf[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t  idx;
    uint8_t  count;
} MovingAvg_t;

typedef struct {
    uint16_t buf[MEDIAN_WINDOW_SIZE];
    uint8_t  idx;
    uint8_t  count;
} MedianFilter_t;

typedef struct {
    int32_t  prev;
    uint16_t alpha_q15;
} IirFilter_t;

typedef struct {
    MovingAvg_t    ma;
    MedianFilter_t med;
    IirFilter_t    iir;
    uint16_t       last_valid;
    uint32_t       spike_count;
    uint32_t       sample_count;
    uint16_t       filtered_mv;
    uint8_t        ovp_flag;
    uint8_t        uvp_flag;
} EmcFilter_t;

/* ============================================================
 * 滤波器初始化
 * ============================================================ */
static void moving_avg_init(MovingAvg_t *f)
{
    memset(f->buf, 0, sizeof(f->buf));
    f->sum   = 0;
    f->idx   = 0;
    f->count = 0;
}

static void median_init(MedianFilter_t *f)
{
    memset(f->buf, 0, sizeof(f->buf));
    f->idx   = 0;
    f->count = 0;
}

static void iir_init(IirFilter_t *f, uint16_t alpha_q15)
{
    f->prev      = 0;
    f->alpha_q15 = alpha_q15;
}

static void emc_filter_init(EmcFilter_t *f)
{
    moving_avg_init(&f->ma);
    median_init(&f->med);
    iir_init(&f->iir, IIR_ALPHA_Q15);
    f->last_valid   = NOMINAL_VOLTAGE_MV;
    f->spike_count  = 0;
    f->sample_count = 0;
    f->filtered_mv  = NOMINAL_VOLTAGE_MV;
    f->ovp_flag     = 0;
    f->uvp_flag     = 0;
}

/* ============================================================
 * 滑动平均滤波
 * ============================================================ */
static uint16_t moving_avg_update(MovingAvg_t *f, uint16_t sample)
{
    if (f->count < FILTER_WINDOW_SIZE) {
        f->buf[f->idx] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buf[f->idx];
        f->buf[f->idx] = sample;
        f->sum += sample;
    }
    f->idx = (uint8_t)((f->idx + 1U) % FILTER_WINDOW_SIZE);
    if (f->count == 0U) {
        return sample;
    }
    return (uint16_t)(f->sum / f->count);
}

/* ============================================================
 * 中值滤波（插入排序）
 * ============================================================ */
static uint16_t median_update(MedianFilter_t *f, uint16_t sample)
{
    uint16_t tmp[MEDIAN_WINDOW_SIZE];
    uint8_t  i, j, n;

    f->buf[f->idx] = sample;
    f->idx = (uint8_t)((f->idx + 1U) % MEDIAN_WINDOW_SIZE);
    if (f->count < MEDIAN_WINDOW_SIZE) {
        f->count++;
    }

    n = f->count;
    if (n == 0U) {
        return sample;
    }
    memcpy(tmp, f->buf, (size_t)n * sizeof(uint16_t));

    for (i = 1; i < n; i++) {
        uint16_t key = tmp[i];
        j = i;
        while (j > 0 && tmp[j - 1] > key) {
            tmp[j] = tmp[j - 1];
            j--;
        }
        tmp[j] = key;
    }
    return tmp[n / 2U];
}

/* ============================================================
 * 一阶 IIR 低通滤波（Q15 定点）
 * ============================================================ */
static uint16_t iir_update(IirFilter_t *f, uint16_t sample)
{
    int32_t y = f->prev + ((((int32_t)sample - f->prev) * (int32_t)f->alpha_q15) >> 15);
    if (y < 0) {
        y = 0;
    }
    if (y > 65535) {
        y = 65535;
    }
    f->prev = y;
    return (uint16_t)y;
}

/* ============================================================
 * 尖峰检测
 * ============================================================ */
static uint8_t spike_detect(EmcFilter_t *f, uint16_t sample)
{
    int32_t diff = (int32_t)sample - (int32_t)f->last_valid;
    if (diff < 0) {
        diff = -diff;
    }
    if (diff > (int32_t)SPIKE_THRESHOLD) {
        f->spike_count++;
        return 1U;
    }
    return 0U;
}

/* ============================================================
 * EMC 综合滤波主流程
 * ============================================================ */
static uint16_t emc_filter_process(EmcFilter_t *f, uint16_t raw_mv)
{
    uint16_t med_out, ma_out, iir_out;

    f->sample_count++;

    if (spike_detect(f, raw_mv)) {
        raw_mv = f->last_valid;
    } else {
        f->last_valid = raw_mv;
    }

    med_out = median_update(&f->med, raw_mv);
    ma_out  = moving_avg_update(&f->ma, med_out);
    iir_out = iir_update(&f->iir, ma_out);

    f->filtered_mv = iir_out;

    f->ovp_flag = (iir_out > OVP_THRESHOLD_MV) ? 1U : 0U;
    f->uvp_flag = (iir_out < UVP_THRESHOLD_MV) ? 1U : 0U;

    return iir_out;
}

/* ============================================================
 * Mock ADC 读取（纯整数运算，无 math.h）
 * ============================================================ */
static uint16_t mock_adc_read(uint32_t tick)
{
    int32_t base   = 12000;
    int32_t ripple;
    int32_t noise;
    int32_t spike  = 0;
    int32_t v;
    uint32_t phase;

    phase = tick % 64U;
    if (phase < 32U) {
        ripple = (int32_t)phase * 300 / 32;
    } else {
        ripple = (int32_t)(64U - phase) * 300 / 32;
    }
    ripple -= 150;

    noise = (int32_t)((tick * 7919U) % 201U) - 100;

    if ((tick % 37U) == 0U) {
        spike = 2500;
    }
    if ((tick % 53U) == 0U) {
        spike = -2500;
    }

    v = base + ripple + noise + spike;
    if (v < 0) {
        v = 0;
    }
    if (v > 65535) {
        v = 65535;
    }
    return (uint16_t)v;
}

/* ============================================================
 * 主函数
 * ============================================================ */
int main(void)
{
    EmcFilter_t filter;
    uint32_t tick;
    uint16_t raw, filtered;
    uint16_t duty;

    printf("========================================\n");
    printf(" 车载电源抗干扰控制 (EMC 软件滤波)\n");
    printf("========================================\n");
    printf("滑动平均窗口: %u, 中值窗口: %u\n",
           (unsigned)FILTER_WINDOW_SIZE, (unsigned)MEDIAN_WINDOW_SIZE);
    printf("IIR alpha(Q15): %u, 尖峰阈值: %u mV\n",
           (unsigned)IIR_ALPHA_Q15, (unsigned)SPIKE_THRESHOLD);
    printf("----------------------------------------\n");
    printf(" Tick |   Raw(mV) | Filtered(mV) | OVP | UVP\n");
    printf("----------------------------------------\n");

    emc_filter_init(&filter);

    for (tick = 0; tick < 100U; tick++) {
        raw = mock_adc_read(tick);
        filtered = emc_filter_process(&filter, raw);

        if (filtered > NOMINAL_VOLTAGE_MV) {
            duty = (uint16_t)((filtered - NOMINAL_VOLTAGE_MV) / 10U);
        } else {
            duty = 0;
        }
        if (duty > 1000U) {
            duty = 1000U;
        }

        if ((tick % 10U) == 0U) {
            printf(" %4u | %9u | %12u |  %u  |  %u\n",
                   (unsigned)tick, (unsigned)raw, (unsigned)filtered,
                   (unsigned)filter.ovp_flag, (unsigned)filter.uvp_flag);
        }
    }

    printf("----------------------------------------\n");
    printf("统计结果:\n");
    printf("  总采样次数    : %u\n", (unsigned)filter.sample_count);
    printf("  尖峰抑制次数  : %u\n", (unsigned)filter.spike_count);
    printf("  最终滤波值    : %u mV\n", (unsigned)filter.filtered_mv);
    printf("  过压标志      : %u\n", (unsigned)filter.ovp_flag);
    printf("  欠压标志      : %u\n", (unsigned)filter.uvp_flag);
    printf("========================================\n");

    return 0;
}
