#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ==================== 模拟寄存器与硬件抽象层 ==================== */
/* 使用普通变量模拟寄存器，避免非法地址访问导致段错误 */
static volatile float g_temp_sensor_reg = 0.0f;
static volatile float g_setpoint_reg = 0.0f;
static volatile uint8_t g_fan_speed_reg = 0;
static volatile uint8_t g_valve_reg = 0;
static volatile uint8_t g_sys_enable_reg = 0;

#define TEMP_SENSOR_REG     (g_temp_sensor_reg)
#define SETPOINT_REG        (g_setpoint_reg)
#define FAN_SPEED_REG       (g_fan_speed_reg)
#define VALVE_REG           (g_valve_reg)
#define SYS_ENABLE_REG      (g_sys_enable_reg)

/* ==================== PID 参数与结构体 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float setpoint;
    float integral;
    float prev_error;
    float output;
    float out_min;
    float out_max;
} PID_Controller;

/* ==================== 风机盘管控制结构体 ==================== */
typedef struct {
    PID_Controller pid;
    float current_temp;
    float target_temp;
    uint8_t fan_speed;
    uint8_t valve_opening;
    uint8_t system_on;
} FanCoilController;

/* ==================== PID 初始化 ==================== */
void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd,
              float setpoint, float out_min, float out_max)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output = 0.0f;
    pid->out_min = out_min;
    pid->out_max = out_max;
}

/* ==================== PID 计算 ==================== */
float PID_Compute(PID_Controller *pid, float measured, float dt)
{
    float error;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = 1.0f;
    }

    error = pid->setpoint - measured;

    pid->integral += error * dt;

    derivative = (error - pid->prev_error) / dt;

    output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output > pid->out_max) {
        output = pid->out_max;
        pid->integral -= error * dt;
    } else if (output < pid->out_min) {
        output = pid->out_min;
        pid->integral -= error * dt;
    }

    pid->prev_error = error;
    pid->output = output;
    return output;
}

/* ==================== 风速调节逻辑 ==================== */
uint8_t FanSpeed_Adjust(float pid_output, float error)
{
    float abs_error = fabsf(error);

    if (pid_output <= 5.0f && abs_error < 1.0f) {
        return 0;
    } else if (pid_output <= 30.0f && abs_error < 3.0f) {
        return 1;
    } else if (pid_output <= 70.0f && abs_error < 6.0f) {
        return 2;
    } else {
        return 3;
    }
}

/* ==================== 水阀开度计算 ==================== */
uint8_t Valve_Opening_Calc(float pid_output)
{
    if (pid_output <= 0.0f) {
        return 0;
    } else if (pid_output >= 100.0f) {
        return 100;
    } else {
        return (uint8_t)pid_output;
    }
}

/* ==================== 控制器初始化 ==================== */
void FanCoil_Init(FanCoilController *fc)
{
    PID_Init(&fc->pid, 2.5f, 0.8f, 0.5f, 24.0f, 0.0f, 100.0f);
    fc->current_temp = 0.0f;
    fc->target_temp = 24.0f;
    fc->fan_speed = 0;
    fc->valve_opening = 0;
    fc->system_on = 0;
}

/* ==================== 控制器主循环 ==================== */
void FanCoil_Control_Loop(FanCoilController *fc, float dt)
{
    float pid_out;
    float error;

    fc->current_temp = TEMP_SENSOR_REG;
    fc->target_temp = SETPOINT_REG;
    fc->system_on = SYS_ENABLE_REG;

    if (!fc->system_on) {
        fc->fan_speed = 0;
        fc->valve_opening = 0;
        FAN_SPEED_REG = 0;
        VALVE_REG = 0;
        return;
    }

    fc->pid.setpoint = fc->target_temp;

    pid_out = PID_Compute(&fc->pid, fc->current_temp, dt);

    error = fc->target_temp - fc->current_temp;

    fc->fan_speed = FanSpeed_Adjust(pid_out, error);

    fc->valve_opening = Valve_Opening_Calc(pid_out);

    FAN_SPEED_REG = fc->fan_speed;
    VALVE_REG = fc->valve_opening;
}

/* ==================== 测试打印 ==================== */
void Print_Status(FanCoilController *fc, int step)
{
    const char *fan_str[4] = {"OFF", "LOW", "MID", "HIGH"};
    uint8_t idx = fc->fan_speed;
    if (idx > 3) {
        idx = 3;
    }
    printf("Step %2d | Temp: %5.2f C | Target: %5.2f C | PID: %6.2f | Fan: %-4s | Valve: %3d%%\n",
           step,
           fc->current_temp,
           fc->target_temp,
           fc->pid.output,
           fan_str[idx],
           fc->valve_opening);
}

/* ==================== 主函数 ==================== */
int main(void)
{
    FanCoilController fc;
    float dt = 1.0f;
    int i;

    printf("===== Fan Coil Unit Thermostat Control (PID + Fan Speed) =====\n\n");

    FanCoil_Init(&fc);

    SYS_ENABLE_REG = 1;
    SETPOINT_REG = 24.0f;
    TEMP_SENSOR_REG = 30.0f;

    printf("--- Cooling Mode: Target 24.0 C, Start Temp 30.0 C ---\n");

    for (i = 0; i < 20; i++) {
        float temp = TEMP_SENSOR_REG;
        float target = SETPOINT_REG;
        float diff = temp - target;

        if (diff > 0.0f) {
            float cooling = (float)fc.valve_opening / 100.0f * (float)(fc.fan_speed + 1) * 0.15f;
            temp -= cooling;
            if (temp < target) temp = target;
        } else if (diff < 0.0f) {
            float heating = (float)fc.valve_opening / 100.0f * (float)(fc.fan_speed + 1) * 0.15f;
            temp += heating;
            if (temp > target) temp = target;
        }

        TEMP_SENSOR_REG = temp;

        FanCoil_Control_Loop(&fc, dt);
        Print_Status(&fc, i + 1);
    }

    printf("\n--- Heating Mode: Target 26.0 C, Start Temp 20.0 C ---\n");

    FanCoil_Init(&fc);
    SYS_ENABLE_REG = 1;
    SETPOINT_REG = 26.0f;
    TEMP_SENSOR_REG = 20.0f;

    for (i = 0; i < 20; i++) {
        float temp = TEMP_SENSOR_REG;
        float target = SETPOINT_REG;
        float diff = temp - target;

        if (diff > 0.0f) {
            float cooling = (float)fc.valve_opening / 100.0f * (float)(fc.fan_speed + 1) * 0.15f;
            temp -= cooling;
            if (temp < target) temp = target;
        } else if (diff < 0.0f) {
            float heating = (float)fc.valve_opening / 100.0f * (float)(fc.fan_speed + 1) * 0.15f;
            temp += heating;
            if (temp > target) temp = target;
        }

        TEMP_SENSOR_REG = temp;

        FanCoil_Control_Loop(&fc, dt);
        Print_Status(&fc, i + 1);
    }

    printf("\n===== Test Complete =====\n");
    return 0;
}
