    float integral;
    float prev_error;
    float integral_limit;
    float output_min;
    float output_max;
    float deadband;
} PID_Controller;

/* ===== 系统状态结构体 ===== */
typedef struct {
    float target_pressure;
    float actual_pressure;
    float flow_rate;
    uint32_t pwm_duty;
    uint32_t tick_ms;
    uint32_t last_tick_ms;
    uint8_t pump_enabled;
} WaterSupplySystem;

/* ===== 函数声明 ===== */
static void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
                     float setpoint, float out_min, float out_max);
static float PID_Compute(PID_Controller *pid, float feedback, float dt);
static float ADC_To_Pressure(uint32_t adc_value);
static float ADC_To_Flow(uint32_t adc_value);
static void Pump_SetDuty(uint32_t duty);
static void System_Init(WaterSupplySystem *sys);
static void System_Update(WaterSupplySystem *sys, PID_Controller *pid);
static void System_PrintStatus(const WaterSupplySystem *sys, const PID_Controller *pid);

/* ===== PID 初始化 ===== */
static void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
                     float setpoint, float out_min, float out_max)
{
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_limit = 500.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->deadband = 0.005f;
}

/* ===== PID 计算 ===== */
static float PID_Compute(PID_Controller *pid, float feedback, float dt)
{
    float error;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = 0.001f;
    }

    error = pid->setpoint - feedback;

    if (fabsf(error) < pid->deadband) {
        error = 0.0f;
    }

    pid->integral += error * dt;
    if (pid->integral > pid->integral_limit) {
        pid->integral = pid->integral_limit;
    } else if (pid->integral < -pid->integral_limit) {
        pid->integral = -pid->integral_limit;
    }

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output > pid->output_max) {
        output = pid->output_max;
    } else if (output < pid->output_min) {
        output = pid->output_min;
    }

    return output;
}

/* ===== ADC 转换 ===== */
static float ADC_To_Pressure(uint32_t adc_value)
{
    float ratio;
    if (adc_value > ADC_MAX_VALUE) {
        adc_value = ADC_MAX_VALUE;
    }
    ratio = (float)adc_value / (float)ADC_MAX_VALUE;
    return PRESSURE_MIN_MPA + ratio * (PRESSURE_MAX_MPA - PRESSURE_MIN_MPA);
}

static float ADC_To_Flow(uint32_t adc_value)
{
    float ratio;
    if (adc_value > ADC_MAX_VALUE) {
        adc_value = ADC_MAX_VALUE;
    }
    ratio = (float)adc_value / (float)ADC_MAX_VALUE;
    return ratio * 50.0f;
}

/* ===== 水泵 PWM 输出 ===== */
static void Pump_SetDuty(uint32_t duty)
{
    if (duty > PWM_MAX_DUTY) {
        duty = PWM_MAX_DUTY;
    }
    REG_PWM_DUTY = duty;
}

/* ===== 系统初始化 ===== */
static void System_Init(WaterSupplySystem *sys)
{
    sys->target_pressure = 0.5f;
    sys->actual_pressure = 0.0f;
    sys->flow_rate = 0.0f;
    sys->pwm_duty = 0;
    sys->tick_ms = 0;
    sys->last_tick_ms = 0;
    sys->pump_enabled = 1;

    Pump_SetDuty(0);
}

/* ===== 系统周期更新 ===== */
static void System_Update(WaterSupplySystem *sys, PID_Controller *pid)
{
    uint32_t adc_pressure;
    uint32_t adc_flow;
    float dt;
    float pid_output;

    sys->tick_ms = REG_SYS_TICK_MS;
    dt = (float)(sys->tick_ms - sys->last_tick_ms) / 1000.0f;
    sys->last_tick_ms = sys->tick_ms;

    if (dt <= 0.0f) {
        dt = 0.001f;
    }

    adc_pressure = REG_ADC_PRESSURE;
    adc_flow = REG_ADC_FLOW;

    sys->actual_pressure = ADC_To_Pressure(adc_pressure);
    sys->flow_rate = ADC_To_Flow(adc_flow);

    pid->setpoint = sys->target_pressure;

    if (sys->pump_enabled) {
        pid_output = PID_Compute(pid, sys->actual_pressure, dt);
        if (pid_output < 0.0f) {
            pid_output = 0.0f;
        }
        if (pid_output > (float)PWM_MAX_DUTY) {
            pid_output = (float)PWM_MAX_DUTY;
        }
        sys->pwm_duty = (uint32_t)pid_output;
        Pump_SetDuty(sys->pwm_duty);
    } else {
        sys->pwm_duty = 0;
        Pump_SetDuty(0);
    }
}

/* ===== 状态打印 ===== */
static void System_PrintStatus(const WaterSupplySystem *sys, const PID_Controller *pid)
{
    printf("Tick=%u ms | Target=%.3f MPa | Actual=%.3f MPa | Flow=%.2f L/min | "
           "PWM=%u/1000 | Err=%.4f | Int=%.4f\n",
           (unsigned int)sys->tick_ms,
           sys->target_pressure,
           sys->actual_pressure,
           sys->flow_rate,
           (unsigned int)sys->pwm_duty,
           pid->setpoint - sys->actual_pressure,
           pid->integral);
}

/* ===== 模拟硬件行为（用于测试） ===== */
static void Mock_Hardware_Update(uint32_t tick_ms, uint32_t pwm_duty)
{
    static float simulated_pressure = 0.0f;
    float target_pressure;
    float pressure_step;
    uint32_t adc_val;

    target_pressure = ((float)pwm_duty / (float)PWM_MAX_DUTY) * PRESSURE_MAX_MPA;

    pressure_step = (target_pressure - simulated_pressure) * 0.05f;
    simulated_pressure += pressure_step;

    if (simulated_pressure < 0.0f) {
        simulated_pressure = 0.0f;
    }
    if (simulated_pressure > PRESSURE_MAX_MPA) {
        simulated_pressure = PRESSURE_MAX_MPA;
    }

    adc_val = (uint32_t)((simulated_pressure / PRESSURE_MAX_MPA) * (float)ADC_MAX_VALUE);
    if (adc_val > ADC_MAX_VALUE) {
        adc_val = ADC_MAX_VALUE;
    }

    REG_ADC_PRESSURE = adc_val;
    REG_ADC_FLOW = (uint32_t)((float)pwm_duty * 0.04f);
    REG_SYS_TICK_MS = tick_ms;
}

/* ===== 主函数 ===== */
int main(void)
{
    WaterSupplySystem sys;
    PID_Controller pid;
    uint32_t tick;
    const uint32_t total_ticks = 200;
    const uint32_t tick_step_ms = 10;

    printf("===== Water Pump Variable Frequency Constant Pressure Control =====\n");
    printf("PID Parameters: Kp=2.0, Ki=0.5, Kd=0.1\n");
    printf("Target Pressure: 0.5 MPa\n\n");

    System_Init(&sys);
    PID_Init(&pid, 2.0f, 0.5f, 0.1f, sys.target_pressure, 0.0f, (float)PWM_MAX_DUTY);

    for (tick = 0; tick <= total_ticks; tick++) {
        uint32_t current_ms = tick * tick_step_ms;

        Mock_Hardware_Update(current_ms, sys.pwm_duty);
        System_Update(&sys, &pid);

        if ((tick % 10) == 0) {
            System_PrintStatus(&sys, &pid);
        }
    }

    printf("\n===== Simulation Complete =====\n");
    printf("Final Pressure: %.3f MPa (Target: %.3f MPa)\n",
           sys.actual_pressure, sys.target_pressure);
    printf("Final PWM Duty: %u / %u\n",
           (unsigned int)sys.pwm_duty, (unsigned int)PWM_MAX_DUTY);

    if (fabsf(sys.actual_pressure - sys.target_pressure) < 0.02f) {
        printf("Result: PID control converged successfully.\n");
    } else {
        printf("Result: PID control did not fully converge.\n");
    }

    return 0;
}
