    PID_Init(&g_pid, 2.0f, 0.5f, 0.1f, 150.0f, 0.0f, 100.0f);

    /* 初始化过温保护: 阈值 180.0C, 回差 5.0C, 连续 3 次触发才锁定 */
    OTP_Init(&g_otp, 180.0f, 5.0f, 3);

