            Set_Heater_PWM(0.0f);
            Set_Alarm(true);
            printf("[%02d] Temp=%.1fC  OTP TRIPPED! Heater OFF, Alarm ON\n",
                   i, temperature);
            continue;
        }

        /* 过温保护未触发，执行 PID 控制 */
        pid_output = PID_Compute(&g_pid, temperature, dt);

        /* 输出限幅 */
        if (pid_output < g_pid.output_min) {
