/* ==================== PID 初始化 ==================== */
static void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
                     float setpoint, float out_min, float out_max)
{
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_limit = 50.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->deadband = 0.5f;
}

/* ==================== PID 计算 ==================== */
static float PID_Compute(PID_Controller *pid, float measured, float dt)
{
    float error;
    float derivative;
    float output;

    error = pid->setpoint - measured;

    /* 死区处理：误差在死区内不调节 */
    if (fabsf(error) < pid->deadband) {
        error = 0.0f;
    }

    /* 积分项 */
    pid->integral += error * dt;
    if (pid->integral > pid->integral_limit) {
        pid->integral = pid->integral_limit;
    } else if (pid->integral < -pid->integral_limit) {
        pid->integral = -pid->integral_limit;
    }

    /* 微分项 */
    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    /* PID 输出 */
    output = pid->Kp * error
           + pid->Ki * pid->integral
           + pid->Kd * derivative;

    return output;
}

/* ==================== 过温保护初始化 ==================== */
static void OTP_Init(OverTempProtection *otp, float threshold, float hyst,
                     uint32_t trip_max)
{
    otp->over_temp_threshold = threshold;
    otp->hysteresis = hyst;
    otp->trip_count = 0;
    otp->trip_count_max = trip_max;
    otp->latched = false;
}

/* ==================== 过温保护检查 ==================== */
static bool OTP_Check(OverTempProtection *otp, float temperature)
{
    /* 已锁定则直接返回 true */
    if (otp->latched) {
        return true;
    }

    /* 超过阈值，累加计数 */
    if (temperature >= otp->over_temp_threshold) {
        otp->trip_count++;
        if (otp->trip_count >= otp->trip_count_max) {
            otp->latched = true;
            return true;
        }
    } else {
        /* 低于阈值 - 回差，清零计数 */
        if (temperature < (otp->over_temp_threshold - otp->hysteresis)) {
            otp->trip_count = 0;
        }
    }

    return false;
}

/* ==================== 设置加热器 PWM ==================== */
static void Set_Heater_PWM(float duty_percent)
{
    uint32_t duty;

    if (duty_percent < 0.0f) {
        duty_percent = 0.0f;
    }
    if (duty_percent > 100.0f) {
        duty_percent = 100.0f;
    }

    duty = (uint32_t)(duty_percent * (float)PWM_MAX_DUTY / 100.0f);
    REG_PWM_DUTY = duty;
