#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ==================== Mock 寄存器与硬件抽象 ==================== */
/* 使用普通全局变量模拟寄存器，避免访问非法地址导致段错误 */
static uint32_t g_vfd_cmd_reg = 0;
static uint32_t g_vfd_freq_set_reg = 0;
static uint32_t g_vfd_freq_act_reg = 0;
static uint32_t g_vfd_current_reg = 0;
