#define INJ_FLOW_REG        (g_inj_flow_reg)
#define INJ_PHASE_REG       (g_inj_phase_reg)

/* 变频器命令位 */
#define VFD_CMD_RUN         (1U << 0)
#define VFD_CMD_STOP        (1U << 1)
#define VFD_CMD_FAULT_RESET (1U << 2)

/* 伺服控制位 */
#define SERVO_CTRL_ENABLE   (1U << 0)
#define SERVO_CTRL_MODE_POS (0U << 1)
#define SERVO_CTRL_MODE_SPD (1U << 1)
#define SERVO_CTRL_MODE_TRQ (2U << 1)

/* 注塑机工艺阶段 */
typedef enum {
    PHASE_IDLE = 0,
    PHASE_CLAMP,
    PHASE_INJECTION,
    PHASE_HOLD,
    PHASE_COOLING,
    PHASE_PLASTICIZE,
    PHASE_EJECTION,
    PHASE_FAULT
} InjectionPhase_t;

/* 节能控制参数结构体 */
typedef struct {
    float base_freq;
    float energy_save_ratio;
    float pressure_feedback;
    float flow_feedback;
    float target_pressure;
    float target_flow;
    float vfd_freq_output;
    float servo_torque_output;
    float servo_speed_output;
    float kp;
    float ki;
    float integral;
    float integral_limit;
} EnergySaveCtrl_t;

/* ==================== 全局变量 ==================== */
static EnergySaveCtrl_t g_ctrl;
static InjectionPhase_t g_phase = PHASE_IDLE;

/* ==================== 工具函数 ==================== */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static float read_pressure(void)
{
    uint32_t raw = INJ_PRESSURE_REG;
    return (float)(raw & 0xFFFFU) / 100.0f;
