/* ==================== 变频器控制 ==================== */
static void vfd_set_frequency(float freq_hz)
{
    freq_hz = clampf(freq_hz, 0.0f, 50.0f);
    VFD_FREQ_SET_REG = (uint32_t)(freq_hz * 100.0f);
