    SERVO_SPEED_SET = (uint32_t)((speed_rpm + 3000.0f) * 10.0f);
}

/* ==================== 节能控制核心算法 ==================== */
static void energy_save_init(void)
{
    g_ctrl.base_freq = 50.0f;
    g_ctrl.energy_save_ratio = 0.0f;
    g_ctrl.pressure_feedback = 0.0f;
    g_ctrl.flow_feedback = 0.0f;
    g_ctrl.target_pressure = 0.0f;
    g_ctrl.target_flow = 0.0f;
    g_ctrl.vfd_freq_output = 0.0f;
    g_ctrl.servo_torque_output = 0.0f;
    g_ctrl.servo_speed_output = 0.0f;
    g_ctrl.kp = 0.8f;
    g_ctrl.ki = 0.05f;
    g_ctrl.integral = 0.0f;
    g_ctrl.integral_limit = 20.0f;
}

static float pi_control(float target, float feedback, float kp, float ki,
                        float *integral, float integral_limit)
{
    float error = target - feedback;
    *integral += error;
    *integral = clampf(*integral, -integral_limit, integral_limit);
    return kp * error + ki * (*integral);
}

static float calc_vfd_freq(InjectionPhase_t phase, float pressure_err)
{
    float freq = 0.0f;
    float save_factor = 1.0f - g_ctrl.energy_save_ratio;

    switch (phase) {
    case PHASE_CLAMP:
        freq = 45.0f * save_factor;
        break;
    case PHASE_INJECTION:
        freq = 50.0f * save_factor;
        break;
    case PHASE_HOLD:
        freq = 25.0f * save_factor + pressure_err * 0.5f;
        break;
    case PHASE_COOLING:
        freq = 10.0f * save_factor;
        break;
    case PHASE_PLASTICIZE:
        freq = 40.0f * save_factor;
        break;
    case PHASE_EJECTION:
        freq = 35.0f * save_factor;
        break;
    default:
        freq = 0.0f;
        break;
    }
    return clampf(freq, 0.0f, 50.0f);
}

static void calc_servo_output(InjectionPhase_t phase, float pressure_err,
                              float flow_err, float *torque, float *speed)
{
    float save_factor = 1.0f - g_ctrl.energy_save_ratio;

    switch (phase) {
    case PHASE_CLAMP:
        *torque = 60.0f * save_factor;
        *speed = 1500.0f * save_factor;
        break;
    case PHASE_INJECTION:
        *torque = 80.0f * save_factor + pressure_err * 2.0f;
        *speed = 2000.0f * save_factor;
        break;
    case PHASE_HOLD:
        *torque = 50.0f * save_factor + pressure_err * 3.0f;
        *speed = 500.0f * save_factor;
        break;
    case PHASE_COOLING:
        *torque = 10.0f * save_factor;
        *speed = 200.0f * save_factor;
        break;
    case PHASE_PLASTICIZE:
        *torque = 40.0f * save_factor + flow_err * 1.5f;
        *speed = 1200.0f * save_factor;
        break;
    case PHASE_EJECTION:
        *torque = 55.0f * save_factor;
        *speed = 1000.0f * save_factor;
        break;
    default:
        *torque = 0.0f;
        *speed = 0.0f;
        break;
    }
    *torque = clampf(*torque, -100.0f, 100.0f);
    *speed = clampf(*speed, -3000.0f, 3000.0f);
}

static void energy_save_control_loop(void)
{
    float pressure_err, flow_err;
    float vfd_freq, servo_torque, servo_speed;
    float pi_out;

    g_ctrl.pressure_feedback = read_pressure();
    g_ctrl.flow_feedback = read_flow();

    pressure_err = g_ctrl.target_pressure - g_ctrl.pressure_feedback;
    flow_err = g_ctrl.target_flow - g_ctrl.flow_feedback;

    pi_out = pi_control(g_ctrl.target_pressure,
                        g_ctrl.pressure_feedback,
                        g_ctrl.kp, g_ctrl.ki,
                        &g_ctrl.integral,
                        g_ctrl.integral_limit);

    vfd_freq = calc_vfd_freq(g_phase, pressure_err);
    vfd_freq += pi_out * 0.1f;
    vfd_freq = clampf(vfd_freq, 0.0f, 50.0f);
    g_ctrl.vfd_freq_output = vfd_freq;

    calc_servo_output(g_phase, pressure_err, flow_err,
                      &servo_torque, &servo_speed);
    g_ctrl.servo_torque_output = servo_torque;
    g_ctrl.servo_speed_output = servo_speed;

    if (g_phase != PHASE_IDLE && g_phase != PHASE_FAULT) {
        vfd_set_frequency(vfd_freq);
        vfd_run();
        servo_enable();
        servo_set_torque(servo_torque);
        servo_set_speed(servo_speed);
    } else {
        vfd_stop();
        servo_disable();
    }

    if (vfd_is_fault()) {
        g_phase = PHASE_FAULT;
        vfd_stop();
        servo_disable();
    }
}

static void set_phase(InjectionPhase_t phase)
{
    g_phase = phase;
    g_ctrl.integral = 0.0f;
}

static void set_targets(float pressure, float flow)
