}

/* ==================== main 函数 ==================== */
int main(void)
{
    InjectionPhase_t cycle[7];
    float targets[7][2];
    int num_phases;
    int i, step;

    printf("========================================\n");
    printf(" 注塑机节能控制 (变频+伺服) 测试\n");
    printf("========================================\n\n");

    energy_save_init();
    set_energy_save_ratio(0.3f);

    cycle[0] = PHASE_CLAMP;
    cycle[1] = PHASE_INJECTION;
    cycle[2] = PHASE_HOLD;
    cycle[3] = PHASE_COOLING;
    cycle[4] = PHASE_PLASTICIZE;
    cycle[5] = PHASE_EJECTION;
    cycle[6] = PHASE_IDLE;

    targets[0][0] = 120.0f; targets[0][1] = 200.0f;
    targets[1][0] = 150.0f; targets[1][1] = 250.0f;
    targets[2][0] = 100.0f; targets[2][1] =  50.0f;
    targets[3][0] =  20.0f; targets[3][1] =  10.0f;
    targets[4][0] =  60.0f; targets[4][1] = 180.0f;
