#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= 超声波电源参数 ================= */
#define PWM_FREQ_MIN        20000UL
#define PWM_FREQ_MAX        40000UL
#define PWM_FREQ_START      28000UL
#define PWM_FREQ_STEP       10UL
#define PWM_DUTY            0.5f

#define PHASE_TARGET        0.0f
#define PHASE_TOLERANCE     2.0f
#define LOCK_COUNT_MAX      50
#define UNLOCK_COUNT_MAX    20

/* ================= 全局变量 ================= */
typedef struct {
    uint32_t current_freq;
    uint32_t target_freq;
    float    phase_diff;
    float    last_phase_diff;
    int      lock_counter;
    int      unlock_counter;
    int      is_locked;
    int      direction;
} FreqTracker_t;

static FreqTracker_t tracker;

/* 简单伪随机数生成器 */
static uint32_t g_rand_seed = 12345U;

static uint32_t simple_rand(void)
{
    g_rand_seed = g_rand_seed * 1103515245U + 12345U;
    return (g_rand_seed >> 16) & 0x7FFFU;
}

/* ================= 硬件抽象层函数 ================= */

static void PWM_SetFrequency(uint32_t freq_hz)
{
    if (freq_hz < PWM_FREQ_MIN) freq_hz = PWM_FREQ_MIN;
    if (freq_hz > PWM_FREQ_MAX) freq_hz = PWM_FREQ_MAX;

    tracker.current_freq = freq_hz;
}

static float MeasurePhaseDifference(void)
{
    float freq_norm;
    float resonance;
    float diff;
    float phase;

    freq_norm = (float)(tracker.current_freq - PWM_FREQ_MIN) /
                (float)(PWM_FREQ_MAX - PWM_FREQ_MIN);
    resonance = 0.5f;
    diff = freq_norm - resonance;

    phase = diff * 180.0f;

    phase += ((float)(simple_rand() % 100) - 50.0f) * 0.02f;

    return phase;
}

static void DelayMs(uint32_t ms)
{
    volatile uint32_t i;
    for (i = 0; i < ms * 1000; i++) {
        /* 空循环 */
    }
}

/* ================= 频率跟踪算法 ================= */

static void FreqTracker_Init(void)
{
    tracker.current_freq    = PWM_FREQ_START;
    tracker.target_freq     = PWM_FREQ_START;
    tracker.phase_diff      = 0.0f;
    tracker.last_phase_diff = 0.0f;
    tracker.lock_counter    = 0;
    tracker.unlock_counter  = 0;
    tracker.is_locked       = 0;
    tracker.direction       = 1;

    PWM_SetFrequency(tracker.current_freq);
}

static void FreqTracker_Update(void)
{
    float phase;
    float phase_error;
    uint32_t new_freq;

    phase = MeasurePhaseDifference();
    tracker.phase_diff = phase;

    phase_error = PHASE_TARGET - phase;

    if (fabsf(phase_error) <= PHASE_TOLERANCE) {
        tracker.lock_counter++;
        tracker.unlock_counter = 0;

        if (tracker.lock_counter >= LOCK_COUNT_MAX) {
            tracker.is_locked = 1;
        }
    } else {
        tracker.unlock_counter++;
        tracker.lock_counter = 0;

        if (tracker.unlock_counter >= UNLOCK_COUNT_MAX) {
            tracker.is_locked = 0;
        }
    }

    if (tracker.is_locked) {
        return;
    }

    if (phase_error > 0.0f) {
        tracker.direction = 1;
    } else if (phase_error < 0.0f) {
        tracker.direction = -1;
    }

    if (tracker.direction > 0) {
        new_freq = tracker.current_freq + PWM_FREQ_STEP;
    } else {
        new_freq = tracker.current_freq - PWM_FREQ_STEP;
    }

    if (new_freq < PWM_FREQ_MIN) {
        new_freq = PWM_FREQ_MIN;
        tracker.direction = 1;
    } else if (new_freq > PWM_FREQ_MAX) {
        new_freq = PWM_FREQ_MAX;
        tracker.direction = -1;
    }

    tracker.target_freq = new_freq;
    PWM_SetFrequency(new_freq);

    tracker.last_phase_diff = phase;
}

static void FreqTracker_PrintStatus(void)
{
    printf("Freq: %5lu Hz | Phase: %+7.2f deg | Locked: %s | LockCnt: %2d | UnlockCnt: %2d\n",
           (unsigned long)tracker.current_freq,
           tracker.phase_diff,
           tracker.is_locked ? "YES" : "NO ",
           tracker.lock_counter,
           tracker.unlock_counter);
}

/* ================= 主函数 ================= */
int main(void)
{
    int i;

    printf("========================================\n");
    printf("  Ultrasonic Power Frequency Tracking\n");
    printf("  Resonance Point Locking Algorithm\n");
    printf("========================================\n\n");

    FreqTracker_Init();

    printf("Initial Frequency: %lu Hz\n", (unsigned long)tracker.current_freq);
    printf("Target Phase: %.1f deg, Tolerance: +/-%.1f deg\n\n",
           PHASE_TARGET, PHASE_TOLERANCE);

    for (i = 0; i < 200; i++) {
        FreqTracker_Update();

        if (i % 10 == 0) {
            printf("[%3d] ", i);
            FreqTracker_PrintStatus();
        }

        DelayMs(1);
    }

    printf("\n========================================\n");
    printf("  Final Status:\n");
    printf("  Frequency: %lu Hz\n", (unsigned long)tracker.current_freq);
    printf("  Phase Diff: %.2f deg\n", tracker.phase_diff);
    printf("  Locked: %s\n", tracker.is_locked ? "YES" : "NO");
    printf("========================================\n");

    return 0;
}
