#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 硬件寄存器定义 ================= */
static volatile int32_t mock_enc_pos = 0;
static volatile int32_t mock_enc_vel = 0;
static volatile int32_t mock_pwm_duty = 0;
static volatile uint32_t mock_ctrl_enable = 0;
static volatile uint32_t mock_ctrl_mode = 0;

#define MOCK_REG_ENC_POS       (mock_enc_pos)
#define MOCK_REG_ENC_VEL       (mock_enc_vel)
#define MOCK_REG_PWM_DUTY      (mock_pwm_duty)
#define MOCK_REG_CTRL_ENABLE   (mock_ctrl_enable)
#define MOCK_REG_CTRL_MODE     (mock_ctrl_mode)

/* ================= 系统参数 ================= */
#define ENC_CPR                4096.0f
#define GEAR_RATIO             50.0f
#define PWM_PERIOD             10000
#define PWM_MAX                (PWM_PERIOD - 1)
#define PWM_MIN                (-PWM_PERIOD + 1)
#define CTRL_FREQ_HZ           1000.0f
#define CTRL_DT                (1.0f / CTRL_FREQ_HZ)

/* ================= 位置闭环控制器参数 ================= */
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float integral_limit;
    float output_limit;
} PosPID_t;

/* ================= 关节状态 ================= */
typedef struct {
    float target_pos_deg;
    float actual_pos_deg;
    float actual_vel_dps;
    float pos_error_deg;
    int32_t pwm_output;
    uint8_t enabled;
} Joint_t;

static Joint_t g_joint;
static PosPID_t g_pos_pid;

/* ================= 工具函数 ================= */
static float clampf(float v, float lo, float hi)
{
    if (v > hi) return hi;
    if (v < lo) return lo;
    return v;
}

static float encoder_to_deg(int32_t counts)
{
    return ((float)counts / ENC_CPR) * 360.0f / GEAR_RATIO;
}

static float encoder_to_dps(int32_t counts_per_sec)
{
    return ((float)counts_per_sec / ENC_CPR) * 360.0f / GEAR_RATIO;
}

/* ================= PID 初始化 ================= */
static void pos_pid_init(PosPID_t *pid, float kp, float ki, float kd,
                         float ilim, float olim)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_limit = ilim;
    pid->output_limit = olim;
}

/* ================= 位置闭环 PID 计算 ================= */
static float pos_pid_calc(PosPID_t *pid, float error, float dt)
{
    float p_term, i_term, d_term, output;

    p_term = pid->kp * error;

    pid->integral += pid->ki * error * dt;
    pid->integral = clampf(pid->integral, -pid->integral_limit, pid->integral_limit);
    i_term = pid->integral;

    d_term = pid->kd * (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = p_term + i_term + d_term;
    output = clampf(output, -pid->output_limit, pid->output_limit);

    return output;
}

/* ================= 关节初始化 ================= */
static void joint_init(Joint_t *j)
{
    j->target_pos_deg = 0.0f;
    j->actual_pos_deg = 0.0f;
    j->actual_vel_dps = 0.0f;
    j->pos_error_deg = 0.0f;
    j->pwm_output = 0;
    j->enabled = 0;

    pos_pid_init(&g_pos_pid, 25.0f, 0.5f, 1.2f, 5000.0f, (float)PWM_MAX);
}

/* ================= 读取传感器 ================= */
static void joint_read_sensors(Joint_t *j)
{
    int32_t raw_pos = MOCK_REG_ENC_POS;
    int32_t raw_vel = MOCK_REG_ENC_VEL;

    j->actual_pos_deg = encoder_to_deg(raw_pos);
    j->actual_vel_dps = encoder_to_dps(raw_vel);
}

/* ================= 位置闭环控制步 ================= */
static void joint_control_step(Joint_t *j)
{
    float pid_out;

    if (!j->enabled) {
        MOCK_REG_PWM_DUTY = 0;
        j->pwm_output = 0;
        return;
    }

    j->pos_error_deg = j->target_pos_deg - j->actual_pos_deg;

    pid_out = pos_pid_calc(&g_pos_pid, j->pos_error_deg, CTRL_DT);

    if (pid_out > (float)PWM_MAX) pid_out = (float)PWM_MAX;
    if (pid_out < (float)PWM_MIN) pid_out = (float)PWM_MIN;

    j->pwm_output = (int32_t)pid_out;
    MOCK_REG_PWM_DUTY = j->pwm_output;
}

/* ================= 使能/失能 ================= */
static void joint_enable(Joint_t *j, uint8_t en)
{
    j->enabled = en;
    MOCK_REG_CTRL_ENABLE = en ? 1u : 0u;
    if (!en) {
        g_pos_pid.integral = 0.0f;
        g_pos_pid.prev_error = 0.0f;
        MOCK_REG_PWM_DUTY = 0;
        j->pwm_output = 0;
    }
}

/* ================= 模拟传感器更新（仅用于测试） ================= */
static void mock_sensor_update(Joint_t *j, float dt)
{
    static float sim_pos = 0.0f;
    static float sim_vel = 0.0f;
    float torque_cmd;

    torque_cmd = (float)j->pwm_output / (float)PWM_PERIOD;

    sim_vel += torque_cmd * 200.0f * dt;
    sim_vel *= 0.98f;
    sim_pos += sim_vel * dt;

    MOCK_REG_ENC_POS = (int32_t)(sim_pos * ENC_CPR * GEAR_RATIO / 360.0f);
    MOCK_REG_ENC_VEL = (int32_t)(sim_vel * ENC_CPR * GEAR_RATIO / 360.0f);
}

/* ================= 主函数 ================= */
int main(void)
{
    int step;
    const int total_steps = 2000;

    printf("=== Robot Joint Servo Position Loop Test ===\n");
    printf("Encoder CPR: %.0f, Gear Ratio: %.0f\n", ENC_CPR, GEAR_RATIO);
    printf("Control Freq: %.0f Hz, DT: %.6f s\n", CTRL_FREQ_HZ, CTRL_DT);

    joint_init(&g_joint);

    printf("PID: Kp=%.2f Ki=%.2f Kd=%.2f\n\n",
           g_pos_pid.kp, g_pos_pid.ki, g_pos_pid.kd);

    MOCK_REG_CTRL_MODE = 1;
    joint_enable(&g_joint, 1);

    g_joint.target_pos_deg = 90.0f;
    printf("Target position set to: %.2f deg\n\n", g_joint.target_pos_deg);

    printf("%-8s %-12s %-12s %-12s %-10s\n",
           "Step", "Target(deg)", "Actual(deg)", "Error(deg)", "PWM");
    printf("----------------------------------------------------------\n");

    for (step = 0; step < total_steps; step++) {
        joint_read_sensors(&g_joint);
        joint_control_step(&g_joint);
        mock_sensor_update(&g_joint, CTRL_DT);

        if (step % 200 == 0 || step == total_steps - 1) {
            printf("%-8d %-12.3f %-12.3f %-12.3f %-10d\n",
                   step,
                   g_joint.target_pos_deg,
                   g_joint.actual_pos_deg,
                   g_joint.pos_error_deg,
                   g_joint.pwm_output);
        }
    }

    printf("\n=== Final State ===\n");
    printf("Target:  %.3f deg\n", g_joint.target_pos_deg);
    printf("Actual:  %.3f deg\n", g_joint.actual_pos_deg);
    printf("Error:   %.3f deg\n", g_joint.pos_error_deg);
    printf("PWM:     %d\n", g_joint.pwm_output);
    printf("Enabled: %u\n", (unsigned)g_joint.enabled);

    joint_enable(&g_joint, 0);
    printf("\nJoint disabled. Test complete.\n");

    return 0;
}
