#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
static volatile uint32_t g_reg_pwm_cr   = 0U;
static volatile uint32_t g_reg_pwm_arr  = 0U;
static volatile uint32_t g_reg_pwm_ccr  = 0U;
static volatile uint32_t g_reg_adc_dr   = 0U;
static volatile uint32_t g_reg_adc_cr   = 0U;
static volatile uint32_t g_reg_gpio_led = 0U;

#define REG_PWM_CR      (g_reg_pwm_cr)
#define REG_PWM_ARR     (g_reg_pwm_arr)
#define REG_PWM_CCR     (g_reg_pwm_ccr)
#define REG_ADC_DR      (g_reg_adc_dr)
#define REG_ADC_CR      (g_reg_adc_cr)
#define REG_GPIO_LED    (g_reg_gpio_led)

#define PWM_CR_EN       (1U << 0)
#define PWM_CR_ARPE     (1U << 1)
#define ADC_CR_START    (1U << 0)
#define ADC_CR_EOC      (1U << 1)

/* ==================== 系统参数 ==================== */
#define PWM_FREQ_HZ         20000U
#define PWM_TIMER_CLK_HZ    72000000U
#define PWM_MAX_DUTY        1000U
#define ADC_FULL_SCALE      4095U
#define ADC_REF_MV          3300U

#define TARGET_CURRENT_MA   350U
#define SENSE_RESISTOR_MOHM 100U
#define AMP_GAIN            10U

#define KP_NUM              3
#define KP_DEN              10
#define KI_NUM              1
#define KI_DEN              100

#define DIMMING_MIN_PERCENT  0
#define DIMMING_MAX_PERCENT  100

/* ==================== 数据结构 ==================== */
typedef struct {
    uint32_t pwm_arr;
    uint32_t pwm_ccr;
    uint32_t duty_percent;
    int32_t  integral;
    int32_t  prev_error;
    uint32_t target_adc;
    uint32_t current_adc;
    uint32_t current_ma;
    bool     output_enabled;
} LED_Driver_t;

static LED_Driver_t g_led;

/* ==================== 硬件抽象层 ==================== */
static void HW_PWM_Init(uint32_t freq_hz)
{
    uint32_t arr;
    if (freq_hz == 0U) {
        freq_hz = 1U;
    }
    arr = (PWM_TIMER_CLK_HZ / freq_hz) - 1U;
    REG_PWM_ARR = arr;
    REG_PWM_CCR = 0U;
    REG_PWM_CR |= PWM_CR_ARPE;
    REG_PWM_CR |= PWM_CR_EN;
    g_led.pwm_arr = arr;
}

static void HW_PWM_SetDuty(uint32_t duty)
{
    uint32_t ccr;
    if (duty > PWM_MAX_DUTY) {
        duty = PWM_MAX_DUTY;
    }
    ccr = (uint32_t)(((uint64_t)duty * ((uint64_t)g_led.pwm_arr + 1U)) / PWM_MAX_DUTY);
    REG_PWM_CCR = ccr;
    g_led.pwm_ccr = ccr;
}

static uint32_t HW_ADC_ReadCurrent(void)
{
    uint32_t timeout = 100000U;
    REG_ADC_CR |= ADC_CR_START;
    while (!(REG_ADC_CR & ADC_CR_EOC) && timeout > 0U) {
        timeout--;
    }
    REG_ADC_CR &= ~ADC_CR_EOC;
    return REG_ADC_DR & 0x0FFFU;
}

static void HW_GPIO_SetLED(bool on)
{
    if (on) {
        REG_GPIO_LED |= 0x01U;
    } else {
        REG_GPIO_LED &= ~0x01U;
    }
}

/* ==================== 电流采样与换算 ==================== */
static uint32_t ADC_ToCurrent_mA(uint32_t adc_val)
{
    uint32_t mv;
    uint32_t amp_out_mv;
    uint32_t sense_mv;
    uint32_t current_ma;
    if (adc_val > ADC_FULL_SCALE) {
        adc_val = ADC_FULL_SCALE;
    }
    mv = (uint32_t)(((uint64_t)adc_val * ADC_REF_MV) / ADC_FULL_SCALE);
    amp_out_mv = mv;
    sense_mv = amp_out_mv / AMP_GAIN;
    current_ma = (uint32_t)(((uint64_t)sense_mv * 1000U) / SENSE_RESISTOR_MOHM);
    return current_ma;
}

static uint32_t Current_mA_ToADC(uint32_t current_ma)
{
    uint32_t sense_mv;
    uint32_t amp_out_mv;
    uint32_t adc_val;
    sense_mv = (uint32_t)(((uint64_t)current_ma * SENSE_RESISTOR_MOHM) / 1000U);
    amp_out_mv = sense_mv * AMP_GAIN;
    adc_val = (uint32_t)(((uint64_t)amp_out_mv * ADC_FULL_SCALE) / ADC_REF_MV);
    if (adc_val > ADC_FULL_SCALE) {
        adc_val = ADC_FULL_SCALE;
    }
    return adc_val;
}

/* ==================== 恒流控制算法 ==================== */
static void LED_CurrentControl_Init(void)
{
    g_led.pwm_arr = 0U;
    g_led.pwm_ccr = 0U;
    g_led.duty_percent = 0U;
    g_led.integral = 0;
    g_led.prev_error = 0;
    g_led.target_adc = Current_mA_ToADC(TARGET_CURRENT_MA);
    g_led.current_adc = 0U;
    g_led.current_ma = 0U;
    g_led.output_enabled = false;

    HW_PWM_Init(PWM_FREQ_HZ);
    HW_PWM_SetDuty(0U);
    HW_GPIO_SetLED(false);
}

static void LED_CurrentControl_Enable(bool en)
{
    g_led.output_enabled = en;
    if (!en) {
        HW_PWM_SetDuty(0U);
        HW_GPIO_SetLED(false);
        g_led.integral = 0;
        g_led.prev_error = 0;
    } else {
        HW_GPIO_SetLED(true);
    }
}

static void LED_CurrentControl_Update(void)
{
    int32_t error;
    int32_t p_term;
    int32_t i_term;
    int32_t output;
    int32_t duty;

    if (!g_led.output_enabled) {
        return;
    }

    g_led.current_adc = HW_ADC_ReadCurrent();
    g_led.current_ma = ADC_ToCurrent_mA(g_led.current_adc);

    error = (int32_t)g_led.target_adc - (int32_t)g_led.current_adc;

    g_led.integral += error;
    if (g_led.integral > 100000) {
        g_led.integral = 100000;
    } else if (g_led.integral < -100000) {
        g_led.integral = -100000;
    }

    p_term = (KP_NUM * error) / KP_DEN;
    i_term = (KI_NUM * g_led.integral) / KI_DEN;
    output = p_term + i_term;

    duty = (int32_t)g_led.duty_percent + output;
    if (duty < 0) {
        duty = 0;
    } else if (duty > (int32_t)PWM_MAX_DUTY) {
        duty = (int32_t)PWM_MAX_DUTY;
    }

    g_led.duty_percent = (uint32_t)duty;
    g_led.prev_error = error;

    HW_PWM_SetDuty(g_led.duty_percent);
}

/* ==================== PWM 调光接口 ==================== */
static void LED_SetBrightness(uint32_t percent)
{
    uint32_t duty;
    if (percent > DIMMING_MAX_PERCENT) {
        percent = DIMMING_MAX_PERCENT;
    }
    if (percent < DIMMING_MIN_PERCENT) {
        percent = DIMMING_MIN_PERCENT;
    }

    if (percent == 0U) {
        HW_PWM_SetDuty(0U);
        HW_GPIO_SetLED(false);
        g_led.duty_percent = 0U;
    } else {
        duty = (percent * PWM_MAX_DUTY) / 100U;
        HW_PWM_SetDuty(duty);
        HW_GPIO_SetLED(true);
        g_led.duty_percent = duty;
    }
}

/* ==================== 测试主函数 ==================== */
int main(void)
{
    int i;
    uint32_t dim_levels[5];
    uint32_t simulated_adc;

    printf("===== LED Driver Constant Current Control (PWM Dimming) =====\n\n");

    LED_CurrentControl_Init();
    printf("[Init] PWM Freq = %u Hz, ARR = %u\n", PWM_FREQ_HZ, g_led.pwm_arr);
    printf("[Init] Target Current = %u mA, Target ADC = %u\n",
           TARGET_CURRENT_MA, g_led.target_adc);
    printf("[Init] Output Enabled = %s\n\n", g_led.output_enabled ? "YES" : "NO");

    LED_CurrentControl_Enable(true);
    printf("[Enable] Output Enabled = %s\n\n", g_led.output_enabled ? "YES" : "NO");

    printf("--- Constant Current Loop Simulation ---\n");
    for (i = 0; i < 10; i++) {
        simulated_adc = (uint32_t)((g_led.target_adc * 8U) / 10U) + (uint32_t)(i * 20);
        if (simulated_adc > ADC_FULL_SCALE) {
            simulated_adc = ADC_FULL_SCALE;
        }
        REG_ADC_DR = simulated_adc;

        LED_CurrentControl_Update();

        printf("Step %2d: ADC=%4u, Current=%4u mA, Duty=%4u (%3u%%), CCR=%4u\n",
               i + 1,
               g_led.current_adc,
               g_led.current_ma,
               g_led.duty_percent,
               (g_led.duty_percent * 100U) / PWM_MAX_DUTY,
               g_led.pwm_ccr);
    }

    printf("\n--- PWM Dimming Test ---\n");
    dim_levels[0] = 0U;
    dim_levels[1] = 25U;
    dim_levels[2] = 50U;
    dim_levels[3] = 75U;
    dim_levels[4] = 100U;
    for (i = 0; i < 5; i++) {
        LED_SetBrightness(dim_levels[i]);
        printf("Brightness = %3u%% -> Duty = %4u, CCR = %4u, LED = %s\n",
               dim_levels[i],
               g_led.duty_percent,
               g_led.pwm_ccr,
               (REG_GPIO_LED & 0x01U) ? "ON" : "OFF");
    }

    printf("\n--- Disable Output ---\n");
    LED_CurrentControl_Enable(false);
    printf("Output Enabled = %s, Duty = %u, LED = %s\n",
           g_led.output_enabled ? "YES" : "NO",
           g_led.duty_percent,
           (REG_GPIO_LED & 0x01U) ? "ON" : "OFF");

    printf("\n===== Test Complete =====\n");
    return 0;
}
