```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ===================== 硬件寄存器 Mock 定义 ===================== */
static uint32_t g_adc_solar_volt;
static uint32_t g_adc_solar_curr;
static uint32_t g_adc_bat_volt;
static uint32_t g_adc_bat_curr;
static uint32_t g_adc_load_volt;
static uint32_t g_adc_load_curr;
static uint32_t g_pwm_charge_duty;
static uint32_t g_pwm_load_enable;
static uint32_t g_gpio_led_status;

#define ADC_SOLAR_VOLT_REG      (g_adc_solar_volt)
#define ADC_SOLAR_CURR_REG      (g_adc_solar_curr)
#define ADC_BAT_VOLT_REG        (g_adc_bat_volt)
#define ADC_BAT_CURR_REG        (g_adc_bat_curr)
#define ADC_LOAD_VOLT_REG       (g_adc_load_volt)
#define ADC_LOAD_CURR_REG       (g_adc_load_curr)

#define PWM_CHARGE_DUTY_REG     (g_pwm_charge_duty)
#define PWM_LOAD_ENABLE_REG     (g_pwm_load_enable)

#define GPIO_LED_STATUS_REG     (g_gpio_led_status)

/* ===================== 系统参数定义 ===================== */
#define ADC_REF_VOLT            3.3f
#define ADC_RESOLUTION          4095.0f

#define SOLAR_VOLT_DIV_RATIO    11.0f
#define BAT_VOLT_DIV_RATIO      11.0f
#define LOAD_VOLT_DIV_RATIO     11.0f

#define SOLAR_CURR_GAIN         0.05f
#define BAT_CURR_GAIN           0.05f
#define LOAD_CURR_GAIN          0.05f

#define PWM_MAX_DUTY            1000U
#define PWM_MIN_DUTY            0U

#define MPPT_STEP               5U
#define MPPT_POWER_THRESHOLD    0.5f

#define BAT_VOLT_FULL           14.4f
#define BAT_VOLT_OVERVOLT       15.0f
#define BAT_VOLT_LOW            11.0f
#define BAT_VOLT_UNDERVOLT      10.5f
#define BAT_VOLT_RECOVER        12.0f

#define LOAD_ON_VOLT            11.5f
#define LOAD_OFF_VOLT           10.8f

#define TEMP_COMP_COEFF         (-0.005f)
#define TEMP_REF                25.0f

/* ===================== 状态机定义 ===================== */
typedef enum {
    STATE_INIT = 0,
    STATE_MPPT,
    STATE_CHARGE_CV,
    STATE_CHARGE_FLOAT,
    STATE_BAT_LOW,
    STATE_BAT_UNDERVOLT,
    STATE_FAULT
} SystemState_t;

typedef enum {
    LOAD_OFF = 0,
    LOAD_ON
} LoadState_t;

/* ===================== 系统数据结构 ===================== */
typedef struct {
    float solar_volt;
    float solar_curr;
    float solar_power;
    float bat_volt;
    float bat_curr;
    float load_volt;
    float load_curr;
    float temperature;
} SensorData_t;

typedef struct {
    uint32_t charge_duty;
    uint32_t prev_duty;
    float prev_power;
    int8_t mppt_dir;
    SystemState_t state;
    LoadState_t load_state;
    uint32_t fault_code;
} Controller_t;

/* ===================== 全局变量 ===================== */
static SensorData_t g_sensor;
static Controller_t g_ctrl;

/* ===================== 辅助函数 ===================== */
static float adc_to_voltage(uint32_t adc_val)
{
    return ((float)adc_val / ADC_RESOLUTION) * ADC_REF_VOLT;
}

static float read_solar_voltage(void)
{
    return adc_to_voltage(ADC_SOLAR_VOLT_REG) * SOLAR_VOLT_DIV_RATIO;
}

static float read_solar_current(void)
{
    return adc_to_voltage(ADC_SOLAR_CURR_REG) / SOLAR_CURR_GAIN;
}

static float read_battery_voltage(void)
{
    return adc_to_voltage(ADC_BAT_VOLT_REG) * BAT_VOLT_DIV_RATIO;
}

static float read_battery_current(void)
{
    return adc_to_voltage(ADC_BAT_CURR_REG) / BAT_CURR_GAIN;
}

static float read_load_voltage(void)
{
    return adc_to_voltage(ADC_LOAD_VOLT_REG) * LOAD_VOLT_DIV_RATIO;
}

static float read_load_current(void)
{
    return adc_to_voltage(ADC_LOAD_CURR_REG) / LOAD_CURR_GAIN;
}

static float read_temperature(void)
{
    return 25.0f;
}

static void sensors_update(void)
{
    g_sensor.solar_volt = read_solar_voltage();
    g_sensor.solar_curr = read_solar_current();
    g_sensor.solar_power = g_sensor.solar_volt * g_sensor.solar_curr;
    g_sensor.bat_volt = read_battery_voltage();
    g_sensor.bat_curr = read_battery_current();
    g_sensor.load_volt = read_load_voltage();
    g_sensor.load_curr = read_load_current();
    g_sensor.temperature = read_temperature();
}

static void set_charge_duty(uint32_t duty)
{
    if (duty > PWM_MAX_DUTY) {
        duty = PWM_MAX_DUTY;
    }
    if (duty < PWM_MIN_DUTY) {
        duty = PWM_MIN_DUTY;
    }
    g_ctrl.charge_duty = duty;
    PWM_CHARGE_DUTY_REG = duty;
}

static void set_load_state(LoadState_t state)
{
    g_ctrl.load_state = state;
    PWM_LOAD_ENABLE_REG = (state == LOAD_ON) ? 1U : 0U;
}

static void set_led_status(uint32_t status)
{
    GPIO_LED_STATUS_REG = status;
}

static float get_temp_compensated_full_volt(void)
{
    return BAT_VOLT_FULL + TEMP_COMP_COEFF * (g_sensor.temperature - TEMP_REF);
}

static void mppt_perturb_observe(void)
{
    float current_power = g_sensor.solar_power;
    float power_diff = current_power - g_ctrl.prev_power;
    uint32_t new_duty = g_ctrl.charge_duty;

    if (fabsf(power_diff) > MPPT_POWER_THRESHOLD) {
        if (power_diff > 0.0f) {
            if (g_ctrl.mppt_dir > 0) {
                new_duty = new_duty + MPPT_STEP;
            } else {
                new_duty = new_duty - MPPT_STEP;
            }
        } else {
            g_ctrl.mppt_dir = -g_ctrl.mppt_dir;
            if (g_ctrl.mppt_dir > 0) {
                new_duty = new_duty + MPPT_STEP;
            } else {
                new_duty = new_duty - MPPT_STEP;
            }
        }
    }

    if (new_duty > PWM_MAX_DUTY) {
        new_duty = PWM_MAX_DUTY;
        g_ctrl.mppt_dir = -1;
    }
    if (new_duty < PWM_MIN_DUTY) {
        new_duty = PWM_MIN_DUTY;
        g_ctrl.mppt_dir = 1;
    }

    g_ctrl.prev_power = current_power;
    set_charge_duty(new_duty);
}

static void charge_control(void)
{
    float full_volt = get_temp_compensated_full_volt();

    if (g_sensor.bat_volt >= BAT_VOLT_OVERVOLT) {
        g_ctrl.state = STATE_FAULT;
        g_ctrl.fault_code = 0x01;
        set_charge_duty(0);
        return;
    }

    if (g_sensor.bat_volt >= full_volt) {
        g_ctrl.state = STATE_CHARGE_FLOAT;
        set_charge_duty(0);
        return;
    }

    if (g_sensor.bat_volt >= (full_volt - 0.3f)) {
        g_ctrl.state = STATE_CHARGE_CV;
        if (g_sensor.bat_volt > full_volt) {
            if (g_ctrl.charge_duty > 0) {
                set_charge_duty(g_ctrl.charge_duty - 1);
            }
        } else {
            if (g_ctrl.charge_duty < PWM_MAX_DUTY) {
                set_charge_duty(g_ctrl.charge_duty + 1);
            }
        }
        return;
    }

    if (g_sensor.solar_volt > g_sensor.bat_volt + 1.0f) {
        g_ctrl.state = STATE_MPPT;
        mppt_perturb_observe();
    } else {
        g_ctrl.state = STATE_BAT_LOW;
        set_charge_duty(0);
    }
}

static void load_control(void)
{
    if (g_sensor.bat_volt < BAT_VOLT_UNDERVOLT) {
        set_load_state(LOAD_OFF);
        g_ctrl.state = STATE_BAT_UNDERVOLT;
        return;
    }

    if (g_sensor.bat_volt < LOAD_OFF_VOLT) {
        set_load_state(LOAD_OFF);
        return;
    }

    if (g_sensor.bat_volt > LOAD_ON_VOLT) {
        set_load_state(LOAD_ON);
    }

    if (g_sensor.load_curr > 10.0f) {
        set_load_state(LOAD_OFF);
        g_ctrl.fault_code = 0x02;
    }
}

