#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ========== 模拟寄存器与硬件抽象层 ========== */
/* 使用普通变量模拟寄存器，避免直接访问非法地址导致段错误 */
static uint32_t g_vfd_ctrl_reg        = 0U;
static uint32_t g_vfd_freq_set_reg    = 0U;
static uint32_t g_vfd_freq_act_reg    = 0U;
static uint32_t g_vfd_current_reg     = 0U;
static uint32_t g_vfd_voltage_reg     = 0U;
static uint32_t g_vfd_torque_reg      = 0U;
static uint32_t g_vfd_status_reg      = 0U;

static uint32_t g_adc_load_torque_reg = 0U;
static uint32_t g_adc_motor_speed_reg = 0U;
static uint32_t g_adc_oil_flow_reg    = 0U;

#define VFD_CTRL_REG            (g_vfd_ctrl_reg)
#define VFD_FREQ_SET_REG        (g_vfd_freq_set_reg)
#define VFD_FREQ_ACT_REG        (g_vfd_freq_act_reg)
#define VFD_CURRENT_REG         (g_vfd_current_reg)
#define VFD_VOLTAGE_REG         (g_vfd_voltage_reg)
#define VFD_TORQUE_REG          (g_vfd_torque_reg)
#define VFD_STATUS_REG          (g_vfd_status_reg)

#define ADC_LOAD_TORQUE_REG     (g_adc_load_torque_reg)
#define ADC_MOTOR_SPEED_REG     (g_adc_motor_speed_reg)
#define ADC_OIL_FLOW_REG        (g_adc_oil_flow_reg)

/* 控制位定义 */
#define VFD_CTRL_RUN            (1U << 0)
#define VFD_CTRL_STOP           (1U << 1)
#define VFD_CTRL_RESET          (1U << 2)
#define VFD_CTRL_ENERGY_SAVE    (1U << 3)

/* 状态位定义 */
#define VFD_STATUS_READY        (1U << 0)
#define VFD_STATUS_RUNNING      (1U << 1)
#define VFD_STATUS_FAULT        (1U << 2)
#define VFD_STATUS_OVERLOAD     (1U << 3)

/* ========== 系统参数 ========== */
#define POLE_PAIRS              4U
#define RATED_FREQ              50.0f
#define MIN_FREQ                15.0f
#define MAX_FREQ                50.0f
#define RATED_SPEED             1450.0f
#define RATED_TORQUE            100.0f
#define SAMPLE_PERIOD_MS        100U

/* 节能控制参数 */
#define TORQUE_LIGHT_THRESHOLD  30.0f
#define TORQUE_HEAVY_THRESHOLD  70.0f
#define FREQ_STEP_LIGHT         0.5f
#define FREQ_STEP_HEAVY         1.0f
#define FREQ_STEP_NORMAL        0.2f
#define FILTER_ALPHA            0.3f

/* ========== 数据结构 ========== */
typedef struct {
    float target_freq;
    float actual_freq;
    float motor_speed;
    float load_torque;
    float oil_flow;
    float filtered_torque;
    float energy_save_ratio;
    uint32_t run_time;
    uint8_t  state;
} PumpController_t;

/* ========== 全局变量 ========== */
static PumpController_t g_pump;

/* ========== 函数声明 ========== */
static void VFD_Init(void);
static void VFD_SetFrequency(float freq);
static float VFD_GetActualFrequency(void);
static float VFD_GetCurrent(void);
static float VFD_GetVoltage(void);
static float VFD_GetTorque(void);
static uint32_t VFD_GetStatus(void);
static void VFD_Start(void);
static void VFD_Stop(void);
static void VFD_EnableEnergySave(void);

static float ADC_ReadLoadTorque(void);
static float ADC_ReadMotorSpeed(void);
static float ADC_ReadOilFlow(void);

static float LowPassFilter(float input, float prev_output, float alpha);
static float CalculateEnergySaveRatio(float torque, float freq);
static void PumpControl_Init(PumpController_t *ctrl);
static void PumpControl_Update(PumpController_t *ctrl);
static void PumpControl_PrintStatus(const PumpController_t *ctrl);

/* ========== 变频器驱动层 (mock) ========== */
static void VFD_Init(void)
{
    VFD_CTRL_REG = 0U;
    VFD_FREQ_SET_REG = 0U;
    VFD_STATUS_REG = VFD_STATUS_READY;
}

static void VFD_SetFrequency(float freq)
{
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;
    VFD_FREQ_SET_REG = (uint32_t)(freq * 100.0f);
}

static float VFD_GetActualFrequency(void)
{
    return (float)VFD_FREQ_ACT_REG / 100.0f;
}

static float VFD_GetCurrent(void)
{
    return (float)VFD_CURRENT_REG / 10.0f;
}

static float VFD_GetVoltage(void)
{
    return (float)VFD_VOLTAGE_REG / 10.0f;
}

static float VFD_GetTorque(void)
{
    return (float)VFD_TORQUE_REG / 10.0f;
}

static uint32_t VFD_GetStatus(void)
{
    return VFD_STATUS_REG;
}

static void VFD_Start(void)
{
    VFD_CTRL_REG |= VFD_CTRL_RUN;
    VFD_CTRL_REG &= ~VFD_CTRL_STOP;
    VFD_STATUS_REG |= VFD_STATUS_RUNNING;
}

static void VFD_Stop(void)
{
    VFD_CTRL_REG |= VFD_CTRL_STOP;
    VFD_CTRL_REG &= ~VFD_CTRL_RUN;
    VFD_STATUS_REG &= ~VFD_STATUS_RUNNING;
}

static void VFD_EnableEnergySave(void)
{
    VFD_CTRL_REG |= VFD_CTRL_ENERGY_SAVE;
}

/* ========== ADC 采样层 (mock) ========== */
static float ADC_ReadLoadTorque(void)
{
    return (float)ADC_LOAD_TORQUE_REG / 10.0f;
}

static float ADC_ReadMotorSpeed(void)
{
    return (float)ADC_MOTOR_SPEED_REG;
}

static float ADC_ReadOilFlow(void)
{
    return (float)ADC_OIL_FLOW_REG / 100.0f;
}

/* ========== 算法层 ========== */
static float LowPassFilter(float input, float prev_output, float alpha)
{
    return alpha * input + (1.0f - alpha) * prev_output;
}

static float CalculateEnergySaveRatio(float torque, float freq)
{
    float torque_ratio = torque / RATED_TORQUE;
    float freq_ratio = freq / RATED_FREQ;
    float power_ratio = torque_ratio * freq_ratio * freq_ratio * freq_ratio;
    if (power_ratio > 1.0f) power_ratio = 1.0f;
    if (power_ratio < 0.0f) power_ratio = 0.0f;
    return (1.0f - power_ratio) * 100.0f;
}

static void PumpControl_Init(PumpController_t *ctrl)
{
    if (ctrl == NULL) return;

    ctrl->target_freq = RATED_FREQ;
    ctrl->actual_freq = 0.0f;
    ctrl->motor_speed = 0.0f;
    ctrl->load_torque = 0.0f;
    ctrl->oil_flow = 0.0f;
    ctrl->filtered_torque = 0.0f;
    ctrl->energy_save_ratio = 0.0f;
    ctrl->run_time = 0U;
    ctrl->state = 0U;

    VFD_Init();
    VFD_EnableEnergySave();
    VFD_SetFrequency(ctrl->target_freq);
    VFD_Start();
    ctrl->state = 1U;
}

static void PumpControl_Update(PumpController_t *ctrl)
{
    float torque_raw;
    float freq_delta = 0.0f;
    uint32_t status;

    if (ctrl == NULL) return;

    /* 1. 读取传感器数据 */
    torque_raw = ADC_ReadLoadTorque();
    ctrl->motor_speed = ADC_ReadMotorSpeed();
    ctrl->oil_flow = ADC_ReadOilFlow();
    ctrl->actual_freq = VFD_GetActualFrequency();

    /* 2. 转矩滤波 */
    ctrl->filtered_torque = LowPassFilter(torque_raw, ctrl->filtered_torque, FILTER_ALPHA);
    ctrl->load_torque = ctrl->filtered_torque;

    /* 3. 故障检测 */
    status = VFD_GetStatus();
    if (status & VFD_STATUS_FAULT) {
        VFD_Stop();
        ctrl->state = 0U;
        printf("[ALARM] VFD fault detected! Stopping.\n");
        return;
    }
    if (status & VFD_STATUS_OVERLOAD) {
        ctrl->target_freq -= FREQ_STEP_HEAVY;
        if (ctrl->target_freq < MIN_FREQ) ctrl->target_freq = MIN_FREQ;
        VFD_SetFrequency(ctrl->target_freq);
        printf("[WARN] Overload! Reducing frequency to %.2f Hz\n", ctrl->target_freq);
        return;
    }

    /* 4. 节能控制策略: 根据负载转矩动态调整频率 */
    if (ctrl->load_torque < TORQUE_LIGHT_THRESHOLD) {
        freq_delta = -FREQ_STEP_LIGHT;
    } else if (ctrl->load_torque > TORQUE_HEAVY_THRESHOLD) {
        freq_delta = FREQ_STEP_HEAVY;
    } else {
        if (ctrl->load_torque < 50.0f) {
            freq_delta = -FREQ_STEP_NORMAL;
        } else {
            freq_delta = FREQ_STEP_NORMAL;
        }
    }

    /* 5. 频率限幅与更新 */
    ctrl->target_freq += freq_delta;
    if (ctrl->target_freq < MIN_FREQ) ctrl->target_freq = MIN_FREQ;
    if (ctrl->target_freq > MAX_FREQ) ctrl->target_freq = MAX_FREQ;
    VFD_SetFrequency(ctrl->target_freq);

    /* 6. 计算节能率 */
    ctrl->energy_save_ratio = CalculateEnergySaveRatio(ctrl->load_torque, ctrl->actual_freq);

    /* 7. 运行时间累加 */
    ctrl->run_time++;
}

static void PumpControl_PrintStatus(const PumpController_t *ctrl)
{
    if (ctrl == NULL) return;

    printf("========================================\n");
    printf("  Oil Pump Energy-Saving Control Status\n");
    printf("========================================\n");
    printf("  State          : %s\n", ctrl->state ? "RUNNING" : "STOPPED");
    printf("  Target Freq    : %.2f Hz\n", ctrl->target_freq);
    printf("  Actual Freq    : %.2f Hz\n", ctrl->actual_freq);
    printf("  Motor Speed    : %.0f rpm\n", ctrl->motor_speed);
    printf("  Load Torque    : %.1f %%\n", ctrl->load_torque);
    printf("  Oil Flow       : %.2f (mock)\n", ctrl->oil_flow);
    printf("  Energy Save    : %.1f %%\n", ctrl->energy_save_ratio);
    printf("  Run Time       : %u cycles\n", ctrl->run_time);
    printf("  VFD Current    : %.1f A\n", VFD_GetCurrent());
    printf("  VFD Voltage    : %.1f V\n", VFD_GetVoltage());
    printf("  VFD Torque     : %.1f %%\n", VFD_GetTorque());
    printf("========================================\n\n");
}

/* ========== 主函数 ========== */
int main(void)
{
    uint32_t cycle;

    printf("Oil Pump Energy-Saving Control (VFD) - Simulation Start\n\n");

    PumpControl_Init(&g_pump);

    for (cycle = 0U; cycle < 20U; cycle++) {
        if (cycle < 5U) {
            ADC_LOAD_TORQUE_REG = (uint32_t)(20.0f * 10.0f);
            ADC_MOTOR_SPEED_REG = (uint32_t)(1400.0f);
            ADC_OIL_FLOW_REG = (uint32_t)(80.0f * 100.0f);
        } else if (cycle < 12U) {
            ADC_LOAD_TORQUE_REG = (uint32_t)(50.0f * 10.0f);
            ADC_MOTOR_SPEED_REG = (uint32_t)(1450.0f);
            ADC_OIL_FLOW_REG = (uint32_t)(100.0f * 100.0f);
        } else {
            ADC_LOAD_TORQUE_REG = (uint32_t)(85.0f * 10.0f);
            ADC_MOTOR_SPEED_REG = (uint32_t)(1480.0f);
            ADC_OIL_FLOW_REG = (uint32_t)(120.0f * 100.0f);
        }

        VFD_FREQ_ACT_REG = (uint32_t)(g_pump.target_freq * 100.0f);
        VFD_CURRENT_REG = (uint32_t)((g_pump.load_torque * 0.5f + 10.0f) * 10.0f);
        VFD_VOLTAGE_REG = (uint32_t)((g_pump.actual_freq * 7.6f) * 10.0f);
        VFD_TORQUE_REG = (uint32_t)(g_pump.load_torque * 10.0f);

        PumpControl_Update(&g_pump);

        printf("--- Cycle %u ---\n", cycle + 1U);
        PumpControl_PrintStatus(&g_pump);
    }

