#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ========== 模拟寄存器与硬件抽象层 ========== */
static uint16_t mock_temp_input = 0;
static uint8_t  mock_fan_speed_out = 0;
static uint8_t  mock_valve_out = 0;

#define MOCK_REG_TEMP_INPUT      (mock_temp_input)
#define MOCK_REG_FAN_SPEED_OUT   (mock_fan_speed_out)
#define MOCK_REG_VALVE_OUT       (mock_valve_out)

/* 风机盘管风速档位 */
typedef enum {
    FAN_SPEED_OFF = 0,
    FAN_SPEED_LOW,
    FAN_SPEED_MED,
    FAN_SPEED_HIGH
} FanSpeed_t;

/* 阀门开度 0~100 */
typedef uint8_t ValvePos_t;

/* PID 控制器结构体 */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float setpoint;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
    float deadband;
    float integral_limit;
} PID_Controller;

/* 温控器整体状态 */
typedef struct {
    PID_Controller pid;
    float current_temp;
    float target_temp;
    FanSpeed_t fan_speed;
    ValvePos_t valve_pos;
    float hysteresis;
} Thermostat_t;

/* ========== 工具函数 ========== */
static float clampf(float v, float lo, float hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float read_temperature(void)
{
    uint16_t raw = MOCK_REG_TEMP_INPUT;
    return (float)raw * 50.0f / 4095.0f;
}

static void set_valve_position(ValvePos_t pos)
{
    MOCK_REG_VALVE_OUT = pos;
}

static void set_fan_speed(FanSpeed_t speed)
{
    MOCK_REG_FAN_SPEED_OUT = (uint8_t)speed;
}

/* ========== PID 初始化与计算 ========== */
static void pid_init(PID_Controller *pid,
                     float Kp, float Ki, float Kd,
                     float setpoint,
                     float out_min, float out_max,
                     float deadband, float integral_limit)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->setpoint = setpoint;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = out_min;
    pid->output_max = out_max;
    pid->deadband = deadband;
    pid->integral_limit = integral_limit;
}

static float pid_compute(PID_Controller *pid, float measured, float dt)
{
    float error = pid->setpoint - measured;

    if (fabsf(error) < pid->deadband) {
        error = 0.0f;
    }

    pid->integral += error * dt;
    pid->integral = clampf(pid->integral, -pid->integral_limit, pid->integral_limit);

    float derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    float output = pid->Kp * error
                 + pid->Ki * pid->integral
                 + pid->Kd * derivative;

    output = clampf(output, pid->output_min, pid->output_max);
    return output;
}

/* ========== 风速调节逻辑 ========== */
static FanSpeed_t determine_fan_speed(float error, float hysteresis, FanSpeed_t current)
{
    float abs_err = fabsf(error);
    (void)current;

    if (abs_err < 0.5f + hysteresis) {
        return FAN_SPEED_OFF;
    } else if (abs_err < 1.5f + hysteresis) {
        return FAN_SPEED_LOW;
    } else if (abs_err < 3.0f + hysteresis) {
        return FAN_SPEED_MED;
    } else {
        return FAN_SPEED_HIGH;
    }
}

/* ========== 温控器初始化 ========== */
static void thermostat_init(Thermostat_t *th, float target)
{
    pid_init(&th->pid,
             2.5f,
             0.8f,
             0.1f,
             target,
             0.0f,
             100.0f,
             0.3f,
             50.0f);

    th->current_temp = 0.0f;
    th->target_temp = target;
    th->fan_speed = FAN_SPEED_OFF;
    th->valve_pos = 0;
    th->hysteresis = 0.2f;
}

/* ========== 温控器主控制循环 ========== */
static void thermostat_update(Thermostat_t *th, float dt)
{
    th->current_temp = read_temperature();
    th->pid.setpoint = th->target_temp;

    float pid_out = pid_compute(&th->pid, th->current_temp, dt);

    th->valve_pos = (ValvePos_t)clampf(pid_out, 0.0f, 100.0f);
    set_valve_position(th->valve_pos);

    float error = th->target_temp - th->current_temp;
    th->fan_speed = determine_fan_speed(error, th->hysteresis, th->fan_speed);
    set_fan_speed(th->fan_speed);

    printf("[Thermostat] Temp=%.2f C | Target=%.2f C | Error=%.2f | "
           "Valve=%3u%% | Fan=%d | PID_out=%.2f\n",
           th->current_temp, th->target_temp, error,
           (unsigned)th->valve_pos, (int)th->fan_speed, pid_out);
}

/* ========== 主函数 ========== */
int main(void)
{
    Thermostat_t thermostat;
    float dt = 1.0f;
    int i;

    printf("===== Fan Coil Thermostat Control (PID + Fan Speed) =====\n\n");

    thermostat_init(&thermostat, 24.0f);

    for (i = 0; i < 20; i++) {
        float simulated_temp = 20.0f + (float)i * 0.25f;
        if (simulated_temp > 25.0f) simulated_temp = 25.0f;

        MOCK_REG_TEMP_INPUT = (uint16_t)(simulated_temp * 4095.0f / 50.0f);

        printf("--- Cycle %2d ---\n", i + 1);
        thermostat_update(&thermostat, dt);
    }

    printf("\n===== Control Loop Finished =====\n");
    return 0;
}
