    float id_ref;
    float iq_ref;
    float vd_ref;
    float vq_ref;
} FOC_State_t;

typedef struct {
    float kp;
    float ki;
    float integral;
    float out_min;
    float out_max;
} PI_Controller_t;

/* ================= 数学工具 ================= */
static float clampf(float v, float lo, float hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float wrap_angle(float angle)
{
    while (angle >= TWO_PI) angle -= TWO_PI;
    while (angle < 0.0f) angle += TWO_PI;
    return angle;
}

/* ================= PI 控制器 ================= */
static void PI_Init(PI_Controller_t *pi, float kp, float ki, float out_min, float out_max)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_min = out_min;
    pi->out_max = out_max;
}

static float PI_Update(PI_Controller_t *pi, float error, float ts)
{
    float p = pi->kp * error;
    pi->integral += pi->ki * error * ts;
    pi->integral = clampf(pi->integral, pi->out_min, pi->out_max);
    float out = p + pi->integral;
    return clampf(out, pi->out_min, pi->out_max);
}

/* ================= Clarke 变换 ================= */
static void Clarke_Transform(float ia, float ib, float ic, float *ialpha, float *ibeta)
{
    *ialpha = ia;
    *ibeta = (ia + 2.0f * ib) * ONE_BY_SQRT3;
    (void)ic;
}

/* ================= Park 变换 ================= */
static void Park_Transform(float ialpha, float ibeta, float theta, float *id, float *iq)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *id =  ialpha * ct + ibeta * st;
    *iq = -ialpha * st + ibeta * ct;
}

/* ================= 反 Park 变换 ================= */
static void InvPark_Transform(float vd, float vq, float theta, float *valpha, float *vbeta)
{
    float ct = cosf(theta);
    float st = sinf(theta);
    *valpha = vd * ct - vq * st;
    *vbeta  = vd * st + vq * ct;
}

/* ================= SVPWM 占空比计算 ================= */
static void SVPWM_Calc(float valpha, float vbeta, float vbus, float *ta, float *tb, float *tc)
{
    float vmax = vbus * ONE_BY_SQRT3;
    float vmin = -vmax;

    float u1 = valpha;
    float u2 = -0.5f * valpha + SQRT3_2 * vbeta;
    float u3 = -0.5f * valpha - SQRT3_2 * vbeta;

    float umax = u1;
    if (u2 > umax) umax = u2;
    if (u3 > umax) umax = u3;

    float umin = u1;
    if (u2 < umin) umin = u2;
    if (u3 < umin) umin = u3;

    float uoffset = -0.5f * (umax + umin);

    float ua = u1 + uoffset;
    float ub = u2 + uoffset;
    float uc = u3 + uoffset;

    ua = clampf(ua, vmin, vmax);
    ub = clampf(ub, vmin, vmax);
    uc = clampf(uc, vmin, vmax);

    *ta = (ua - vmin) / (vmax - vmin);
    *tb = (ub - vmin) / (vmax - vmin);
    *tc = (uc - vmin) / (vmax - vmin);

    *ta = clampf(*ta, 0.0f, 1.0f);
    *tb = clampf(*tb, 0.0f, 1.0f);
    *tc = clampf(*tc, 0.0f, 1.0f);
}

/* ================= 电流采样与重构 ================= */
static void Current_Sample(FOC_State_t *s)
{
    float ia = (float)(int32_t)ADC_IU_RESULT * 0.001f;
    float ib = (float)(int32_t)ADC_IV_RESULT * 0.001f;
    float ic = (float)(int32_t)ADC_IW_RESULT * 0.001f;

    float sum = ia + ib + ic;
    ia -= sum / 3.0f;
    ib -= sum / 3.0f;
    ic -= sum / 3.0f;

    Clarke_Transform(ia, ib, ic, &s->i_alpha, &s->i_beta);
}

/* ================= 母线电压采样 ================= */
static void Vbus_Sample(FOC_State_t *s)
{
    float raw = (float)(int32_t)ADC_VBUS_RESULT;
    s->vbus = raw * 0.1f;
    s->vbus = clampf(s->vbus, VBUS_MIN, VBUS_MAX);
}

/* ================= 编码器采样 ================= */
static void Encoder_Sample(FOC_State_t *s)
{
    uint32_t raw = (uint32_t)ADC_ENC_RESULT;
    float mech_angle = (float)(raw & 0xFFFFU) / 65536.0f * TWO_PI;
    s->theta_m = wrap_angle(mech_angle);
    s->theta_e = wrap_angle(s->theta_m * (float)MOTOR_POLE_PAIRS);
}

/* ================= 速度计算 ================= */
static float g_prev_theta_m = 0.0f;
static void Speed_Calc(FOC_State_t *s)
{
    float delta = s->theta_m - g_prev_theta_m;
    if (delta > PI) delta -= TWO_PI;
    if (delta < -PI) delta += TWO_PI;
    s->omega_m = delta / TS;
    s->omega_e = s->omega_m * (float)MOTOR_POLE_PAIRS;
    g_prev_theta_m = s->theta_m;
}

/* ================= 电流环控制 ================= */
static PI_Controller_t g_pi_d;
static PI_Controller_t g_pi_q;

static void Current_Loop(FOC_State_t *s)
{
    float id_err = s->id_ref - s->i_d;
    float iq_err = s->iq_ref - s->i_q;

    float vd = PI_Update(&g_pi_d, id_err, TS);
    float vq = PI_Update(&g_pi_q, iq_err, TS);

    float omega_e = s->omega_e;
    float ld = MOTOR_LD;
    float lq = MOTOR_LQ;
    float flux = MOTOR_FLUX;

    float vd_ff = -omega_e * lq * s->i_q;
    float vq_ff =  omega_e * (ld * s->i_d + flux);

    vd += vd_ff;
    vq += vq_ff;

    float v_mag = sqrtf(vd * vd + vq * vq);
    float v_max = s->vbus * ONE_BY_SQRT3 * 0.95f;
    if (v_mag > v_max && v_mag > 1e-6f) {
        float scale = v_max / v_mag;
        vd *= scale;
        vq *= scale;
    }

    s->v_d = vd;
    s->v_q = vq;
    s->vd_ref = vd;
    s->vq_ref = vq;
}

/* ================= 弱磁控制 ================= */
static void Field_Weakening(FOC_State_t *s)
{
    float v_mag = sqrtf(s->v_d * s->v_d + s->v_q * s->v_q);
    float v_max = s->vbus * ONE_BY_SQRT3 * 0.95f;

    if (v_mag > v_max * 0.95f) {
        float excess = v_mag - v_max * 0.95f;
        s->id_ref -= excess * 0.01f;
        s->id_ref = clampf(s->id_ref, -CURRENT_LIMIT, 0.0f);
    } else {
        s->id_ref += (0.0f - s->id_ref) * 0.001f;
    }
}

/* ================= 电流限幅 ================= */
static void Current_Limit(FOC_State_t *s)
{
    float i_mag = sqrtf(s->id_ref * s->id_ref + s->iq_ref * s->iq_ref);
    if (i_mag > CURRENT_LIMIT && i_mag > 1e-6f) {
        float scale = CURRENT_LIMIT / i_mag;
        s->id_ref *= scale;
        s->iq_ref *= scale;
    }
}

/* ================= PWM 输出 ================= */
static void PWM_Output(float ta, float tb, float tc)
{
    uint32_t cmp_a = (uint32_t)(ta * (float)PWM_PERIOD);
    uint32_t cmp_b = (uint32_t)(tb * (float)PWM_PERIOD);
    uint32_t cmp_c = (uint32_t)(tc * (float)PWM_PERIOD);

    if (cmp_a > PWM_PERIOD) cmp_a = PWM_PERIOD;
    if (cmp_b > PWM_PERIOD) cmp_b = PWM_PERIOD;
    if (cmp_c > PWM_PERIOD) cmp_c = PWM_PERIOD;

    PWM_TA_REG = cmp_a;
    PWM_TB_REG = cmp_b;
    PWM_TC_REG = cmp_c;
}

/* ================= FOC 主控制步骤 ================= */
static void FOC_Step(FOC_State_t *s)
{
    Vbus_Sample(s);
    Encoder_Sample(s);
    Speed_Calc(s);
    Current_Sample(s);

    Park_Transform(s->i_alpha, s->i_beta, s->theta_e, &s->i_d, &s->i_q);

    Field_Weakening(s);
    Current_Limit(s);
    Current_Loop(s);

    InvPark_Transform(s->v_d, s->v_q, s->theta_e, &s->v_alpha, &s->v_beta);

    float ta, tb, tc;
    SVPWM_Calc(s->v_alpha, s->v_beta, s->vbus, &ta, &tb, &tc);

    PWM_Output(ta, tb, tc);
}

/* ================= 初始化 ================= */
static void FOC_Init(FOC_State_t *s)
{
    s->i_alpha = 0.0f;
    s->i_beta = 0.0f;
    s->i_d = 0.0f;
    s->i_q = 0.0f;
    s->v_alpha = 0.0f;
    s->v_beta = 0.0f;
    s->v_d = 0.0f;
    s->v_q = 0.0f;
    s->theta_e = 0.0f;
    s->theta_m = 0.0f;
    s->omega_e = 0.0f;
    s->omega_m = 0.0f;
    s->vbus = VBUS_NOMINAL;
    s->id_ref = 0.0f;
    s->iq_ref = 0.0f;
    s->vd_ref = 0.0f;
    s->vq_ref = 0.0f;

    PI_Init(&g_pi_d, 0.5f, 100.0f, -VBUS_NOMINAL, VBUS_NOMINAL);
    PI_Init(&g_pi_q, 0.5f, 100.0f, -VBUS_NOMINAL, VBUS_NOMINAL);

    g_prev_theta_m = 0.0f;
}

/* ================= 测试打印 ================= */
static void Print_State(const FOC_State_t *s, int step)
{
    printf("Step %3d | Vbus=%6.1fV | Theta_e=%6.3frad | Id=%7.3fA | Iq=%7.3fA | "
           "Vd=%7.3fV | Vq=%7.3fV | Ta=%.3f Tb=%.3f Tc=%.3f\n",
           step,
           s->vbus,
           s->theta_e,
           s->i_d,
           s->i_q,
           s->v_d,
           s->v_q,
           (float)PWM_TA_REG / (float)PWM_PERIOD,
           (float)PWM_TB_REG / (float)PWM_PERIOD,
           (float)PWM_TC_REG / (float)PWM_PERIOD);
}

/* ================= 主函数 ================= */
int main(void)
{
    FOC_State_t state;
    FOC_Init(&state);

    printf("=== EV Motor Controller FOC (High Voltage) ===\n");
    printf("PWM Freq: %u Hz, Period: %u counts\n", PWM_FREQ_HZ, PWM_PERIOD);
    printf("Pole Pairs: %u, Rs: %.4f ohm, Ld: %.6f H, Lq: %.6f H\n",
           MOTOR_POLE_PAIRS, MOTOR_RS, MOTOR_LD, MOTOR_LQ);
    printf("Current Limit: %.1f A, Vbus Nominal: %.1f V\n\n",
           CURRENT_LIMIT, VBUS_NOMINAL);

    /* 模拟运行 20 个控制周期 */
    for (int i = 0; i < 20; i++) {
        /* 模拟 ADC 输入数据 */
        ADC_IU_RESULT   = (uint32_t)(int32_t)(50.0f * sinf((float)i * 0.3f) * 1000.0f);
        ADC_IV_RESULT   = (uint32_t)(int32_t)(50.0f * sinf((float)i * 0.3f - 2.094f) * 1000.0f);
        ADC_IW_RESULT   = (uint32_t)(int32_t)(50.0f * sinf((float)i * 0.3f + 2.094f) * 1000.0f);
        ADC_VBUS_RESULT = (uint32_t)(int32_t)(VBUS_NOMINAL * 10.0f);
        ADC_ENC_RESULT  = (uint32_t)(int32_t)((float)i * 1000.0f);

        /* 设置转矩指令 */
        state.iq_ref = 100.0f;
        state.id_ref = 0.0f;

        FOC_Step(&state);

        if (i % 2 == 0) {
            Print_State(&state, i);
        }
    }

    printf("\n=== FOC Test Complete ===\n");
    return 0;
}
