#include <stdio.h>
#include <stdint.h>

/* ==================== 模拟寄存器与硬件抽象 ==================== */
static volatile uint16_t mock_pressure_adc = 0;
static volatile uint16_t mock_pump_pwm = 0;
static volatile uint32_t mock_system_tick = 0;

#define MOCK_REG_PRESSURE_ADC    (mock_pressure_adc)
#define MOCK_REG_PUMP_PWM        (mock_pump_pwm)
#define MOCK_REG_SYSTEM_TICK     (mock_system_tick)

/* 压力传感器量程与ADC分辨率 */
#define PRESSURE_ADC_MAX         4095.0f
#define PRESSURE_RANGE_MPA       1.6f

/* PWM输出范围 */
#define PWM_MIN                  0
#define PWM_MAX                  1000

/* PID参数 */
#define PID_KP                   120.0f
#define PID_KI                   8.0f
#define PID_KD                   2.0f

/* 采样与控制周期（毫秒） */
#define CONTROL_PERIOD_MS        100

/* 积分限幅 */
#define PID_INTEGRAL_MAX         500.0f
#define PID_INTEGRAL_MIN         (-500.0f)

/* 输出限幅 */
#define PID_OUTPUT_MAX           ((float)PWM_MAX)
#define PID_OUTPUT_MIN           ((float)PWM_MIN)

/* ==================== PID 控制器结构体 ==================== */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float setpoint;
    float integral;
    float prev_error;
    float output;
    float integral_max;
    float integral_min;
    float output_max;
    float output_min;
} PID_Controller;

/* ==================== 函数声明 ==================== */
static void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
                     float sp, float out_min, float out_max,
                     float int_min, float int_max);
static float PID_Compute(PID_Controller *pid, float measured, float dt);
static float ADC_To_Pressure(uint16_t adc_value);
static void Pump_SetPWM(uint16_t duty);
static uint32_t Get_SystemTick(void);
static void Delay_ms(uint32_t ms);

/* ==================== PID 初始化 ==================== */
static void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
                     float sp, float out_min, float out_max,
                     float int_min, float int_max)
{
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->setpoint = sp;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output = 0.0f;
    pid->integral_max = int_max;
    pid->integral_min = int_min;
    pid->output_max = out_max;
    pid->output_min = out_min;
}

/* ==================== PID 计算 ==================== */
static float PID_Compute(PID_Controller *pid, float measured, float dt)
{
    float error;
    float derivative;
    float output;

    if (dt <= 0.0f) {
        return pid->output;
    }

    error = pid->setpoint - measured;

    pid->integral += error * dt;

    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }

    derivative = (error - pid->prev_error) / dt;

    output = pid->Kp * error
           + pid->Ki * pid->integral
           + pid->Kd * derivative;

    if (output > pid->output_max) {
        output = pid->output_max;
    } else if (output < pid->output_min) {
        output = pid->output_min;
    }

    pid->prev_error = error;
    pid->output = output;

    return output;
}

/* ==================== 硬件抽象层 ==================== */
static float ADC_To_Pressure(uint16_t adc_value)
{
    float pressure;
    if (adc_value > (uint16_t)PRESSURE_ADC_MAX) {
        adc_value = (uint16_t)PRESSURE_ADC_MAX;
    }
    pressure = ((float)adc_value / PRESSURE_ADC_MAX) * PRESSURE_RANGE_MPA;
    return pressure;
}

static void Pump_SetPWM(uint16_t duty)
{
    if (duty > PWM_MAX) {
        duty = PWM_MAX;
    }
    MOCK_REG_PUMP_PWM = duty;
}

static uint32_t Get_SystemTick(void)
{
    return MOCK_REG_SYSTEM_TICK;
}

static void Delay_ms(uint32_t ms)
{
    uint32_t start = Get_SystemTick();
    while ((Get_SystemTick() - start) < ms) {
        MOCK_REG_SYSTEM_TICK++;
    }
}

/* ==================== 主函数 ==================== */
int main(void)
{
    PID_Controller pid;
    float target_pressure = 0.60f;
    float measured_pressure = 0.0f;
    float pid_output = 0.0f;
    uint16_t adc_raw = 0;
    uint16_t pwm_duty = 0;
    uint32_t last_tick;
    uint32_t now_tick;
    float dt;
    float sim_pressure = 0.0f;
    int i;

    printf("========================================\n");
    printf("  水泵变频调速恒压供水 PID 控制仿真\n");
    printf("========================================\n");
    printf("目标压力: %.2f MPa\n", target_pressure);
    printf("PID参数: Kp=%.1f, Ki=%.1f, Kd=%.1f\n",
           (float)PID_KP, (float)PID_KI, (float)PID_KD);
    printf("控制周期: %d ms\n", CONTROL_PERIOD_MS);
    printf("----------------------------------------\n");

    PID_Init(&pid, PID_KP, PID_KI, PID_KD,
             target_pressure,
             PID_OUTPUT_MIN, PID_OUTPUT_MAX,
             PID_INTEGRAL_MIN, PID_INTEGRAL_MAX);

    Pump_SetPWM(0);
    last_tick = Get_SystemTick();

    for (i = 0; i < 30; i++) {
        float pump_effect;
        float target_sim;

        pump_effect = (float)MOCK_REG_PUMP_PWM / (float)PWM_MAX;
        target_sim = pump_effect * PRESSURE_RANGE_MPA;
        sim_pressure += (target_sim - sim_pressure) * 0.15f;
        if (sim_pressure < 0.0f) sim_pressure = 0.0f;
        if (sim_pressure > PRESSURE_RANGE_MPA) sim_pressure = PRESSURE_RANGE_MPA;

        adc_raw = (uint16_t)((sim_pressure / PRESSURE_RANGE_MPA) * PRESSURE_ADC_MAX);
        MOCK_REG_PRESSURE_ADC = adc_raw;

        measured_pressure = ADC_To_Pressure(MOCK_REG_PRESSURE_ADC);

        now_tick = Get_SystemTick();
        dt = (float)(now_tick - last_tick) / 1000.0f;
        if (dt <= 0.0f) {
            dt = (float)CONTROL_PERIOD_MS / 1000.0f;
        }
        last_tick = now_tick;

        pid_output = PID_Compute(&pid, measured_pressure, dt);

        pwm_duty = (uint16_t)pid_output;
        Pump_SetPWM(pwm_duty);

        printf("周期[%2d] 压力=%.3f MPa 目标=%.3f MPa 误差=%+.3f "
               "PID输出=%.1f PWM=%4u\n",
               i + 1,
               measured_pressure,
               target_pressure,
               target_pressure - measured_pressure,
               pid_output,
               pwm_duty);

        Delay_ms(CONTROL_PERIOD_MS);
    }

    printf("----------------------------------------\n");
    printf("控制结束，最终压力: %.3f MPa\n", measured_pressure);
    printf("最终PWM输出: %u\n", pwm_duty);
    printf("========================================\n");

    return 0;
}
