#include <stdio.h>
#include <stdint.h>

/* ==================== 硬件寄存器 Mock 定义 ==================== */
static volatile uint32_t g_reg_pwm_freq = 0;
static volatile uint16_t g_reg_adc_airflow = 0;
static volatile uint16_t g_reg_adc_current = 0;
static volatile uint32_t g_reg_gpio_led = 0;

#define REG_PWM_FREQ        (g_reg_pwm_freq)
#define REG_ADC_AIRFLOW     (g_reg_adc_airflow)
#define REG_ADC_CURRENT     (g_reg_adc_current)
#define REG_GPIO_LED        (g_reg_gpio_led)

/* ==================== 系统参数定义 ==================== */
#define PWM_FREQ_MIN        1000U
#define PWM_FREQ_MAX        20000U
#define PWM_FREQ_BASE       10000U

#define ADC_REF_VOLTAGE     3.3f
#define ADC_RESOLUTION      4095.0f

#define AIRFLOW_SETPOINT    500.0f
#define AIRFLOW_MIN         0.0f
#define AIRFLOW_MAX         1000.0f

/* PID 参数 */
#define PID_KP              2.5f
#define PID_KI              0.8f
#define PID_KD              0.1f

#define PID_OUT_MIN         ((float)PWM_FREQ_MIN)
#define PID_OUT_MAX         ((float)PWM_FREQ_MAX)

#define SAMPLE_PERIOD_S     0.01f

/* ==================== 数据结构定义 ==================== */
typedef struct {
    float setpoint;
    float feedback;
    float error;
    float error_prev;
    float error_prev2;
    float integral;
    float kp;
    float ki;
    float kd;
    float output;
    float out_min;
    float out_max;
} PID_Controller;

/* ==================== 全局变量 ==================== */
static PID_Controller g_pid;
static uint32_t g_pwm_freq = PWM_FREQ_BASE;
static uint32_t g_sample_count = 0;

/* ==================== PID 初始化 ==================== */
void PID_Init(PID_Controller *pid, float kp, float ki, float kd,
              float out_min, float out_max)
{
    pid->setpoint = 0.0f;
    pid->feedback = 0.0f;
    pid->error = 0.0f;
    pid->error_prev = 0.0f;
    pid->error_prev2 = 0.0f;
    pid->integral = 0.0f;
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->output = 0.0f;
    pid->out_min = out_min;
    pid->out_max = out_max;
}

/* ==================== PID 计算 ==================== */
float PID_Compute(PID_Controller *pid, float setpoint, float feedback, float dt)
{
    float p_term, i_term, d_term;
    float output;

    pid->setpoint = setpoint;
    pid->feedback = feedback;
    pid->error = setpoint - feedback;

    p_term = pid->kp * pid->error;

    pid->integral += pid->error * dt;
    i_term = pid->ki * pid->integral;

    d_term = pid->kd * (pid->error - pid->error_prev) / dt;

    output = p_term + i_term + d_term;

    if (output > pid->out_max) {
        output = pid->out_max;
        pid->integral -= pid->error * dt;
    } else if (output < pid->out_min) {
        output = pid->out_min;
        pid->integral -= pid->error * dt;
    }

    pid->error_prev2 = pid->error_prev;
    pid->error_prev = pid->error;
    pid->output = output;

    return output;
}

/* ==================== 读取风量传感器 ==================== */
float Read_Airflow(void)
{
    uint16_t adc_val = REG_ADC_AIRFLOW;
    float voltage = (float)adc_val / ADC_RESOLUTION * ADC_REF_VOLTAGE;
    float airflow = voltage / ADC_REF_VOLTAGE * AIRFLOW_MAX;
    if (airflow < AIRFLOW_MIN) airflow = AIRFLOW_MIN;
    if (airflow > AIRFLOW_MAX) airflow = AIRFLOW_MAX;
    return airflow;
}

/* ==================== 设置 PWM 频率 ==================== */
void Set_PWM_Frequency(uint32_t freq)
{
    if (freq < PWM_FREQ_MIN) freq = PWM_FREQ_MIN;
    if (freq > PWM_FREQ_MAX) freq = PWM_FREQ_MAX;
    g_pwm_freq = freq;
    REG_PWM_FREQ = freq;
}

/* ==================== 系统初始化 ==================== */
void System_Init(void)
{
    PID_Init(&g_pid, PID_KP, PID_KI, PID_KD, PID_OUT_MIN, PID_OUT_MAX);
    g_pid.setpoint = AIRFLOW_SETPOINT;
    Set_PWM_Frequency(PWM_FREQ_BASE);
    g_sample_count = 0;
    printf("[INIT] PID: Kp=%.2f Ki=%.2f Kd=%.2f\n", PID_KP, PID_KI, PID_KD);
    printf("[INIT] Setpoint=%.1f, PWM base=%u Hz\n", AIRFLOW_SETPOINT, PWM_FREQ_BASE);
}

/* ==================== 控制主循环（单步） ==================== */
void Control_Loop(void)
{
    float airflow;
    float pid_out;
    uint32_t new_freq;

    airflow = Read_Airflow();

    pid_out = PID_Compute(&g_pid, AIRFLOW_SETPOINT, airflow, SAMPLE_PERIOD_S);

    new_freq = (uint32_t)pid_out;
    Set_PWM_Frequency(new_freq);

    REG_GPIO_LED = (airflow > AIRFLOW_SETPOINT * 0.95f &&
                    airflow < AIRFLOW_SETPOINT * 1.05f) ? 1U : 0U;

    g_sample_count++;
    printf("[%04u] SP=%.1f FB=%.1f Err=%.2f P=%.2f I=%.2f D=%.2f Out=%.1f Freq=%uHz LED=%u\n",
           g_sample_count,
           g_pid.setpoint,
           airflow,
           g_pid.error,
           g_pid.kp * g_pid.error,
           g_pid.ki * g_pid.integral,
           g_pid.kd * (g_pid.error - g_pid.error_prev) / SAMPLE_PERIOD_S,
           pid_out,
           g_pwm_freq,
           (unsigned)REG_GPIO_LED);
}

/* ==================== 模拟风量传感器 ==================== */
void Mock_Sensor_Update(uint32_t pwm_freq)
{
    float ratio;
    float airflow;
    float noise;
    float voltage;
    uint16_t adc_val;

    ratio = (float)pwm_freq / (float)PWM_FREQ_MAX;
    airflow = ratio * AIRFLOW_MAX;
    noise = ((float)(g_sample_count % 7) - 3.0f) * 0.01f * airflow;
    airflow += noise;
    if (airflow < 0.0f) airflow = 0.0f;
    if (airflow > AIRFLOW_MAX) airflow = AIRFLOW_MAX;

    voltage = airflow / AIRFLOW_MAX * ADC_REF_VOLTAGE;
    adc_val = (uint16_t)(voltage / ADC_REF_VOLTAGE * ADC_RESOLUTION);
    REG_ADC_AIRFLOW = adc_val;
}

/* ==================== main 函数 ==================== */
int main(void)
{
    uint32_t i;

    printf("========================================\n");
    printf("  Fan Variable Frequency Control (PID)\n");
    printf("  Constant Airflow Mode\n");
    printf("========================================\n\n");

    System_Init();

    for (i = 0; i < 50; i++) {
        Mock_Sensor_Update(g_pwm_freq);
        Control_Loop();
    }

    printf("\n[END] Final PWM Frequency = %u Hz\n", g_pwm_freq);
    printf("[END] Final Airflow = %.1f (Target = %.1f)\n",
           g_pid.feedback, AIRFLOW_SETPOINT);

    return 0;
}
