#include <stdio.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免非法地址访问导致崩溃 */
static uint32_t mock_adc_pfc_vin   = 0;
static uint32_t mock_adc_pfc_iin   = 0;
static uint32_t mock_adc_pfc_vout  = 0;
static uint32_t mock_adc_llc_vout  = 0;
static uint32_t mock_adc_llc_iout  = 0;

static uint32_t mock_pwm_pfc_duty  = 0;
static uint32_t mock_pwm_llc_freq  = 0;
static uint32_t mock_pwm_llc_phase = 0;

static uint32_t mock_gpio_led      = 0;
static uint32_t mock_systick_ms    = 0;

#define ADC_PFC_VIN        (mock_adc_pfc_vin)
#define ADC_PFC_IIN        (mock_adc_pfc_iin)
#define ADC_PFC_VOUT       (mock_adc_pfc_vout)
#define ADC_LLC_VOUT       (mock_adc_llc_vout)
#define ADC_LLC_IOUT       (mock_adc_llc_iout)

#define PWM_PFC_DUTY       (mock_pwm_pfc_duty)
#define PWM_LLC_FREQ       (mock_pwm_llc_freq)
#define PWM_LLC_PHASE      (mock_pwm_llc_phase)

#define GPIO_LED           (mock_gpio_led)
#define SYSTICK_MS         (mock_systick_ms)

/* ================= 系统参数定义 ================= */
#define VIN_NOMINAL        220.0f
#define VIN_MIN            85.0f
#define VIN_MAX            265.0f
#define PFC_VOUT_REF       400.0f
#define LLC_VOUT_REF       400.0f
#define LLC_VOUT_MIN       250.0f
#define LLC_VOUT_MAX       450.0f
#define LLC_IOUT_MAX       10.0f
#define PWM_PERIOD         10000.0f
#define LLC_FREQ_MIN       80000.0f
#define LLC_FREQ_MAX       200000.0f
#define LLC_FREQ_NOM       120000.0f
#define PI_KP_PFC          0.5f
#define PI_KI_PFC          0.01f
#define PI_KP_LLC          0.3f
#define PI_KI_LLC          0.005f
#define ADC_VREF           3.3f
#define ADC_RES            4095.0f
#define VIN_DIVIDER        0.01f
#define VOUT_DIVIDER       0.005f
#define IIN_GAIN           0.1f
#define IOUT_GAIN          0.05f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float integral;
    float out_min;
    float out_max;
    float prev_error;
} PI_Controller;

typedef struct {
    float vin;
    float iin;
    float pfc_vout;
    float llc_vout;
    float llc_iout;
    float pfc_duty;
    float llc_freq;
    float llc_phase;
} OBC_State;

typedef enum {
    OBC_STATE_INIT = 0,
    OBC_STATE_STANDBY,
    OBC_STATE_PFC_SOFTSTART,
    OBC_STATE_LLC_SOFTSTART,
    OBC_STATE_RUN,
    OBC_STATE_FAULT
} OBC_StateEnum;

/* ================= 全局变量 ================= */
static OBC_State g_obc;
static OBC_StateEnum g_state = OBC_STATE_INIT;
static PI_Controller g_pi_pfc_vout;
static PI_Controller g_pi_llc_vout;
static uint32_t g_fault_code = 0;

/* ================= PI 控制器 ================= */
static void PI_Init(PI_Controller *pi, float kp, float ki, float out_min, float out_max)
{
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0f;
    pi->out_min = out_min;
    pi->out_max = out_max;
    pi->prev_error = 0.0f;
}

static float PI_Update(PI_Controller *pi, float ref, float fb, float dt)
{
    float error = ref - fb;
    float p_term = pi->kp * error;
    float i_term;
    float out;

    pi->integral += pi->ki * error * dt;
    i_term = pi->integral;

    if (i_term > pi->out_max) {
        i_term = pi->out_max;
        pi->integral = pi->out_max;
    } else if (i_term < pi->out_min) {
        i_term = pi->out_min;
        pi->integral = pi->out_min;
    }

    pi->prev_error = error;

    out = p_term + i_term;
    if (out > pi->out_max) out = pi->out_max;
    if (out < pi->out_min) out = pi->out_min;

    return out;
}

/* ================= 采样与标定 ================= */
static float ADC_ToVoltage(uint32_t raw)
{
    return ((float)raw / ADC_RES) * ADC_VREF;
}

static void OBC_SampleInputs(void)
{
    g_obc.vin      = ADC_ToVoltage(ADC_PFC_VIN) / VIN_DIVIDER;
    g_obc.iin      = ADC_ToVoltage(ADC_PFC_IIN) / IIN_GAIN;
    g_obc.pfc_vout = ADC_ToVoltage(ADC_PFC_VOUT) / VOUT_DIVIDER;
    g_obc.llc_vout = ADC_ToVoltage(ADC_LLC_VOUT) / VOUT_DIVIDER;
    g_obc.llc_iout = ADC_ToVoltage(ADC_LLC_IOUT) / IOUT_GAIN;
}

/* ================= 保护逻辑 ================= */
static void OBC_ProtectionCheck(void)
{
    if (g_obc.vin > VIN_MAX || g_obc.vin < VIN_MIN) {
        g_fault_code |= 0x01;
    }
    if (g_obc.pfc_vout > 450.0f) {
        g_fault_code |= 0x02;
    }
    if (g_obc.llc_vout > LLC_VOUT_MAX || g_obc.llc_vout < LLC_VOUT_MIN) {
        g_fault_code |= 0x04;
    }
    if (g_obc.llc_iout > LLC_IOUT_MAX) {
        g_fault_code |= 0x08;
    }
}

/* ================= PFC 控制 ================= */
static void PFC_Control(float dt)
{
    float duty;

    duty = PI_Update(&g_pi_pfc_vout, PFC_VOUT_REF, g_obc.pfc_vout, dt);

    if (duty > 0.95f) duty = 0.95f;
    if (duty < 0.05f) duty = 0.05f;

    g_obc.pfc_duty = duty;
    PWM_PFC_DUTY = (uint32_t)(duty * PWM_PERIOD);
}

/* ================= LLC 控制 ================= */
static void LLC_Control(float dt)
{
    float freq;

    freq = PI_Update(&g_pi_llc_vout, LLC_VOUT_REF, g_obc.llc_vout, dt);

    if (freq > LLC_FREQ_MAX) freq = LLC_FREQ_MAX;
    if (freq < LLC_FREQ_MIN) freq = LLC_FREQ_MIN;

    g_obc.llc_freq = freq;
    PWM_LLC_FREQ = (uint32_t)freq;

    g_obc.llc_phase = 0.5f;
    PWM_LLC_PHASE = (uint32_t)(g_obc.llc_phase * PWM_PERIOD);
}

/* ================= 状态机 ================= */
static void OBC_StateMachine(float dt)
{
    switch (g_state) {
    case OBC_STATE_INIT:
        PI_Init(&g_pi_pfc_vout, PI_KP_PFC, PI_KI_PFC, 0.05f, 0.95f);
        PI_Init(&g_pi_llc_vout, PI_KP_LLC, PI_KI_LLC, LLC_FREQ_MIN, LLC_FREQ_MAX);
        g_fault_code = 0;
        g_state = OBC_STATE_STANDBY;
        printf("[OBC] INIT -> STANDBY\n");
        break;

    case OBC_STATE_STANDBY:
        if (g_obc.vin > VIN_MIN && g_obc.vin < VIN_MAX) {
            g_state = OBC_STATE_PFC_SOFTSTART;
            printf("[OBC] STANDBY -> PFC_SOFTSTART\n");
        }
        break;

    case OBC_STATE_PFC_SOFTSTART:
        PFC_Control(dt);
        if (g_obc.pfc_vout > PFC_VOUT_REF * 0.9f) {
            g_state = OBC_STATE_LLC_SOFTSTART;
            printf("[OBC] PFC_SOFTSTART -> LLC_SOFTSTART\n");
        }
        break;

    case OBC_STATE_LLC_SOFTSTART:
        PFC_Control(dt);
        LLC_Control(dt);
        if (g_obc.llc_vout > LLC_VOUT_REF * 0.9f) {
            g_state = OBC_STATE_RUN;
            printf("[OBC] LLC_SOFTSTART -> RUN\n");
        }
        break;

    case OBC_STATE_RUN:
        PFC_Control(dt);
        LLC_Control(dt);
        OBC_ProtectionCheck();
        if (g_fault_code != 0) {
            g_state = OBC_STATE_FAULT;
            printf("[OBC] RUN -> FAULT, code=0x%02X\n", g_fault_code);
        }
        break;

    case OBC_STATE_FAULT:
        PWM_PFC_DUTY = 0;
        PWM_LLC_FREQ = (uint32_t)LLC_FREQ_MAX;
        PWM_LLC_PHASE = 0;
        GPIO_LED = 1;
        printf("[OBC] FAULT state, waiting for reset\n");
        break;

    default:
        g_state = OBC_STATE_INIT;
        break;
    }
}

/* ================= 主函数 ================= */
int main(void)
{
    float dt = 0.0001f;
    int cycle;

    printf("========================================\n");
    printf("  OBC Control Algorithm (PFC + LLC)\n");
    printf("========================================\n");

    /* 模拟 ADC 初始值 */
    ADC_PFC_VIN  = 2000;
    ADC_PFC_IIN  = 500;
    ADC_PFC_VOUT = 1500;
    ADC_LLC_VOUT = 1200;
    ADC_LLC_IOUT = 300;

    for (cycle = 0; cycle < 20; cycle++) {
        OBC_SampleInputs();

        /* 模拟闭环反馈：逐渐逼近目标 */
        if (g_state == OBC_STATE_PFC_SOFTSTART || g_state == OBC_STATE_RUN) {
            ADC_PFC_VOUT = (uint32_t)(ADC_PFC_VOUT + 50);
            if (ADC_PFC_VOUT > 2400) ADC_PFC_VOUT = 2400;
        }
        if (g_state == OBC_STATE_LLC_SOFTSTART || g_state == OBC_STATE_RUN) {
            ADC_LLC_VOUT = (uint32_t)(ADC_LLC_VOUT + 40);
            if (ADC_LLC_VOUT > 2400) ADC_LLC_VOUT = 2400;
        }

        OBC_StateMachine(dt);

        printf("Cycle %2d | State=%d | Vin=%6.1fV | PFC_Vout=%6.1fV | LLC_Vout=%6.1fV | Duty=%.3f | Freq=%.0fHz\n",
               cycle, (int)g_state, g_obc.vin, g_obc.pfc_vout, g_obc.llc_vout,
               g_obc.pfc_duty, g_obc.llc_freq);

        SYSTICK_MS += 1;
    }

    printf("========================================\n");
    printf("  OBC Control Test Complete\n");
    printf("========================================\n");

    return 0;
}
