```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ========== Mock 寄存器与硬件抽象 ========== */
#define UPS_NUM                 4
#define ADC_REF_VOLTAGE         3.3f
#define ADC_RESOLUTION          4096.0f
#define CURRENT_SENSOR_RATIO    100.0f
#define PWM_MAX_DUTY            1000
#define PWM_MIN_DUTY            0
#define CONTROL_PERIOD_MS       10
#define CURRENT_LOOP_KI         0.05f
#define CURRENT_LOOP_KP         0.8f
#define MAX_CURRENT_DEVIATION   0.05f
#define BUS_VOLTAGE_NOMINAL     400.0f
#define BUS_VOLTAGE_MIN         360.0f
#define BUS_VOLTAGE_MAX         440.0f

/* Mock 寄存器地址 */
#define REG_ADC_BASE            0x40012000UL
#define REG_PWM_BASE            0x40013000UL
#define REG_GPIO_BASE           0x40020000UL

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t SR;
    volatile uint32_t DR;
} Mock_ADC_TypeDef;

typedef struct {
    volatile uint32_t CR;
    volatile uint32_t SR;
    volatile uint32_t CCR[UPS_NUM];
} Mock_PWM_TypeDef;

typedef struct {
    volatile uint32_t MODER;
    volatile uint32_t ODR;
} Mock_GPIO_TypeDef;

/* 使用静态存储代替直接指针访问，避免非法地址访问 */
static Mock_ADC_TypeDef g_mock_adc;
static Mock_PWM_TypeDef g_mock_pwm;
static Mock_GPIO_TypeDef g_mock_gpio;

#define MOCK_ADC                (&g_mock_adc)
#define MOCK_PWM                (&g_mock_pwm)
#define MOCK_GPIO               (&g_mock_gpio)

/* Mock 硬件读写函数 */
static uint32_t mock_adc_read(uint8_t channel)
{
    static const uint32_t mock_values[UPS_NUM] = {2048, 2100, 1980, 2060};
    if (channel < UPS_NUM) {
        return mock_values[channel];
    }
    return 0;
}

static void mock_pwm_set_duty(uint8_t channel, uint32_t duty)
{
    if (channel < UPS_NUM) {
        MOCK_PWM->CCR[channel] = duty;
    }
}

static float mock_read_bus_voltage(void)
{
    return 400.0f;
}

/* ========== UPS 集群数据结构 ========== */
typedef struct {
    float current;
    float current_ref;
    float current_error;
    float integral;
    uint32_t pwm_duty;
    bool online;
    bool fault;
} UPS_Unit;

typedef struct {
    UPS_Unit units[UPS_NUM];
    float total_current;
    float avg_current;
    float bus_voltage;
    float current_share_error;
    uint32_t active_count;
    uint32_t tick;
} UPS_Cluster;

/* ========== 函数声明 ========== */
static void ups_cluster_init(UPS_Cluster *cluster);
static void ups_read_feedback(UPS_Cluster *cluster);
static void ups_calc_average(UPS_Cluster *cluster);
static void ups_current_share_control(UPS_Cluster *cluster);
static void ups_apply_pwm(UPS_Cluster *cluster);
static void ups_fault_check(UPS_Cluster *cluster);
static void ups_print_status(const UPS_Cluster *cluster);
static float adc_to_current(uint32_t adc_value);
static uint32_t current_to_pwm(float current_ref);

/* ========== 初始化 ========== */
static void ups_cluster_init(UPS_Cluster *cluster)
{
    uint32_t i;
    cluster->total_current = 0.0f;
    cluster->avg_current = 0.0f;
    cluster->bus_voltage = 0.0f;
    cluster->current_share_error = 0.0f;
    cluster->active_count = 0;
    cluster->tick = 0;

    for (i = 0; i < UPS_NUM; i++) {
        cluster->units[i].current = 0.0f;
        cluster->units[i].current_ref = 0.0f;
        cluster->units[i].current_error = 0.0f;
        cluster->units[i].integral = 0.0f;
        cluster->units[i].pwm_duty = 0;
        cluster->units[i].online = true;
        cluster->units[i].fault = false;
    }

    MOCK_PWM->CR = 1;
    MOCK_PWM->SR = 0;
    for (i = 0; i < UPS_NUM; i++) {
        MOCK_PWM->CCR[i] = 0;
    }

    MOCK_ADC->CR = 1;
    MOCK_ADC->SR = 0;

    printf("[INIT] UPS Cluster initialized, %d units online\n", UPS_NUM);
}

/* ========== ADC 值转电流 ========== */
static float adc_to_current(uint32_t adc_value)
{
    float voltage = ((float)adc_value / ADC_RESOLUTION) * ADC_REF_VOLTAGE;
    return voltage * CURRENT_SENSOR_RATIO;
}

/* ========== 电流参考值转 PWM 占空比 ========== */
static uint32_t current_to_pwm(float current_ref)
{
    float duty_f = (current_ref / 100.0f) * (float)PWM_MAX_DUTY;
    if (duty_f > (float)PWM_MAX_DUTY) {
        duty_f = (float)PWM_MAX_DUTY;
    }
    if (duty_f < (float)PWM_MIN_DUTY) {
        duty_f = (float)PWM_MIN_DUTY;
    }
    return (uint32_t)duty_f;
}

/* ========== 读取反馈 ========== */
static void ups_read_feedback(UPS_Cluster *cluster)
{
    uint32_t i;
    for (i = 0; i < UPS_NUM; i++) {
        if (cluster->units[i].online && !cluster->units[i].fault) {
            uint32_t adc_val = mock_adc_read((uint8_t)i);
            cluster->units[i].current = adc_to_current(adc_val);
        } else {
            cluster->units[i].current = 0.0f;
        }
    }
    cluster->bus_voltage = mock_read_bus_voltage();
}

/* ========== 计算平均电流 ========== */
static void ups_calc_average(UPS_Cluster *cluster)
{
    uint32_t i;
    float sum = 0.0f;
    uint32_t count = 0;

    for (i = 0; i < UPS_NUM; i++) {
        if (cluster->units[i].online && !cluster->units[i].fault) {
            sum += cluster->units[i].current;
            count++;
        }
    }

    cluster->active_count = count;
    cluster->total_current = sum;

    if (count > 0) {
        cluster->avg_current = sum / (float)count;
    } else {
        cluster->avg_current = 0.0f;
    }
}

/* ========== 均流控制核心算法 ========== */
static void ups_current_share_control(UPS_Cluster *cluster)
{
    uint32_t i;
    float max_deviation = 0.0f;

    if (cluster->active_count == 0) {
        return;
    }

    for (i = 0; i < UPS_NUM; i++) {
        UPS_Unit *unit = &cluster->units[i];

        if (!unit->online || unit->fault) {
            unit->pwm_duty = 0;
            continue;
        }

        unit->current_error = unit->current - cluster->avg_current;

        float abs_err = fabsf(unit->current_error);
        if (abs_err > max_deviation) {
            max_deviation = abs_err;
        }

        unit->integral += unit->current_error * CURRENT_LOOP_KI;
        unit->current_ref = cluster->avg_current
                          - (CURRENT_LOOP_KP * unit->current_error)
                          - unit->integral;

        if (unit->current_ref < 0.0f) {
            unit->current_ref = 0.0f;
        }
        if (unit->current_ref > 100.0f) {
            unit->current_ref = 100.0f;
        }

        unit->pwm_duty = current_to_pwm(unit->current_ref);
    }

    if (cluster->avg_current > 0.001f) {
        cluster->current_share_error = (max_deviation / cluster->avg_current) * 100.0f;
    } else {
        cluster->current_share_error = 0.0f;
    }
}

/* ========== 应用 PWM 输出 ========== */
static void ups_apply_pwm(UPS_Cluster *cluster)
{
    uint32_t i;
    for (i = 0; i < UPS_NUM; i++) {
        if (cluster->units[i].online && !cluster->units[i].fault) {
            mock_pwm_set_duty((uint8_t)i, cluster->units[i].pwm_duty);
        } else {
            mock_pwm_set_duty((uint8_t)i, 0);
        }
    }
}

/* ========== 故障检测 ========== */
static void ups_fault_check(UPS_Cluster *cluster)
{
    uint32_t i;

    if (cluster->bus_voltage < BUS_VOLTAGE_MIN ||
        cluster->bus_voltage > BUS_VOLTAGE_MAX) {
        printf("[FAULT] Bus voltage out of range: %.2fV\n", cluster->bus_voltage);
    }

    if (cluster->current_share_error > (MAX_CURRENT_DEVIATION * 100.0f)) {
        printf("[WARN] Current sharing error too high: %.2f%%\n",
               cluster->current_share_error);
    }

    for (i = 0; i < UPS_NUM; i++) {
        UPS_Unit *unit = &cluster->units[i];
        if (!unit->online) {
            continue;
        }
        if (unit->current > 120.0f || unit->current < -5.0f) {
            unit->fault = true;
            printf("[FAULT] UPS[%u] current abnormal: %.2fA\n", i, unit->current);
        }
    }
}

/* ========== 打印状态 ========== */
static void ups_print_status(const UPS_Cluster *cluster)
{
    uint32_t i;
    printf("---- Tick %u | Bus: %.1fV | Avg: %.2fA | Total: %.2fA | ShareErr: %.2f%% ----\n",
           cluster->tick,
           cluster->bus_voltage,
           cluster->avg_current,
           cluster->total_current,
           cluster->current_share_error);

    for (i = 0; i < UPS_NUM; i++) {
        const UPS_Unit *u = &cluster->units[i];
        printf("  UPS[%u] %s | I: %6.2fA | Ref: %6.2fA | Err: %+6.2fA | PWM: %4u\n",
               i,
               u->fault ? "FAULT" : (u->online ? "ONLINE" : "OFFLINE"),
               u->current,
               u->current_ref,
               u->current_error,
               u->pwm_duty);
    }
}

/* ========== 主函数 ========== */
int main(void)
{
    UPS_Cluster cluster;
    uint32_t cycle;

    printf("========================================\n");
    printf("  Data Center UPS Cluster Current Share\n");
    printf("  Control Algorithm Simulation\n");
    printf("========================================\n\n");

    ups_cluster_init(&cluster);

    for (cycle = 0; cycle < 5; cycle++) {
        cluster.tick = cycle;

        ups_read_feedback(&cluster);
        ups_calc_average(&cluster);
        ups_current_share_control(&cluster);
        ups_apply_pwm(&cluster);
        ups_fault_check(&cluster);
        ups_print_status(&cluster);

        printf("\n");
    }

    printf("========================================\n");
    printf("  Simulation complete.\n");
    printf("========================================\n");

    return 0;
}
