#include <stdio.h>
#include <math.h>
#include <stdint.h>

/* ================= Mock 寄存器与硬件抽象 ================= */
/* 使用普通全局变量模拟寄存器，避免直接访问非法地址导致段错误 */
static volatile uint32_t g_encoder_cnt = 0;
static volatile uint32_t g_pwm_duty = 0;
static volatile uint32_t g_motor_dir = 0;
static volatile uint32_t g_motor_en = 0;

#define ENCODER_CNT_REG     (g_encoder_cnt)
#define PWM_DUTY_REG        (g_pwm_duty)
#define MOTOR_DIR_REG       (g_motor_dir)
#define MOTOR_EN_REG        (g_motor_en)

/* ================= 系统参数 ================= */
#define ENCODER_PPR         4096.0f
#define GEAR_RATIO          50.0f
#define CTRL_PERIOD_S       0.001f
#define PWM_MAX             1000.0f
#define PWM_MIN             0.0f

#define KP                  8.0f
#define KI                  0.5f
#define KD                  0.02f

#define POS_MIN_RAD         (-3.1415926f)
#define POS_MAX_RAD         ( 3.1415926f)
#define INTEGRAL_MAX        500.0f

/* ================= 数据结构 ================= */
typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float prev_error;
    float output;
} PID_Controller;

typedef struct {
    float target_pos_rad;
    float current_pos_rad;
    float current_vel_rad_s;
    float prev_pos_rad;
    PID_Controller pid;
} JointController;

/* ================= 工具函数 ================= */
static float clampf(float val, float min, float max)
{
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

static float encoder_to_rad(int32_t pulse)
{
    float rev = (float)pulse / ENCODER_PPR;
    float joint_rev = rev / GEAR_RATIO;
    return joint_rev * 2.0f * 3.1415926f;
}

static int32_t read_encoder(void)
{
    return (int32_t)ENCODER_CNT_REG;
}

static void set_pwm_output(float duty)
{
    duty = clampf(duty, PWM_MIN, PWM_MAX);
    if (duty >= 0.0f) {
        MOTOR_DIR_REG = 0;
        PWM_DUTY_REG = (uint32_t)duty;
    } else {
        MOTOR_DIR_REG = 1;
        PWM_DUTY_REG = (uint32_t)(-duty);
    }
}

/* ================= PID 初始化 ================= */
static void pid_init(PID_Controller *pid, float kp, float ki, float kd)
{
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output = 0.0f;
}

/* ================= PID 计算 ================= */
static float pid_compute(PID_Controller *pid, float error, float dt)
{
    float derivative;
    float output;

    if (dt <= 0.0f) {
        dt = CTRL_PERIOD_S;
    }

    pid->integral += error * dt;
    pid->integral = clampf(pid->integral, -INTEGRAL_MAX, INTEGRAL_MAX);

    derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    output = pid->kp * error
           + pid->ki * pid->integral
           + pid->kd * derivative;

    pid->output = output;
    return output;
}

/* ================= 关节控制器初始化 ================= */
static void joint_init(JointController *jc)
{
    jc->target_pos_rad = 0.0f;
    jc->current_pos_rad = 0.0f;
    jc->current_vel_rad_s = 0.0f;
    jc->prev_pos_rad = 0.0f;
    pid_init(&jc->pid, KP, KI, KD);
}

/* ================= 关节控制周期任务 ================= */
static void joint_control_step(JointController *jc, float dt)
{
    float error;
    float pid_out;

    if (dt <= 0.0f) {
        dt = CTRL_PERIOD_S;
    }

    jc->current_pos_rad = encoder_to_rad(read_encoder());

    jc->current_vel_rad_s = (jc->current_pos_rad - jc->prev_pos_rad) / dt;
    jc->prev_pos_rad = jc->current_pos_rad;

    error = jc->target_pos_rad - jc->current_pos_rad;

    pid_out = pid_compute(&jc->pid, error, dt);

    set_pwm_output(pid_out);
}

/* ================= 主函数 ================= */
int main(void)
{
    JointController joint;
    int i;
    int32_t mock_encoder_pulse = 0;

    printf("===== Robot Joint Servo Position Loop Test =====\n");

    joint_init(&joint);
    joint.target_pos_rad = 1.0f;

    MOTOR_EN_REG = 1;

    printf("Target position: %.4f rad\n", joint.target_pos_rad);
    printf("-----------------------------------------------\n");
    printf("Step | Encoder | Pos(rad) | Error(rad) | PWM\n");
    printf("-----------------------------------------------\n");

    for (i = 0; i < 200; i++) {
        float target_pulse = joint.target_pos_rad
                           / (2.0f * 3.1415926f)
                           * GEAR_RATIO * ENCODER_PPR;
        float diff = target_pulse - (float)mock_encoder_pulse;
        mock_encoder_pulse += (int32_t)(diff * 0.05f);
        ENCODER_CNT_REG = (uint32_t)mock_encoder_pulse;

        joint_control_step(&joint, CTRL_PERIOD_S);

        if (i % 20 == 0) {
            float err = joint.target_pos_rad - joint.current_pos_rad;
            printf("%4d | %7d | %8.4f | %10.4f | %4u\n",
                   i,
                   (int)mock_encoder_pulse,
                   joint.current_pos_rad,
                   err,
                   (unsigned)PWM_DUTY_REG);
        }
    }

    printf("-----------------------------------------------\n");
    printf("Final position: %.4f rad\n", joint.current_pos_rad);
    printf("Final error   : %.4f rad\n",
           joint.target_pos_rad - joint.current_pos_rad);
    printf("Final PWM     : %u\n", (unsigned)PWM_DUTY_REG);

    MOTOR_EN_REG = 0;

    return 0;
}
